import { useId, type ReactNode } from 'react';
import { defaultAdminTheme } from '@jini-ai/ui/theme';
import { InfoTip } from '@jini-ai/ui/admin-widgets';
import type { ConsentAppearanceView, ConsentFieldProblem, ConsentSettingsView } from './ConsentSettingsPanel.js';
import { pixelInputValue, problemsFor, useConsentSettingsPanel, usePolicyVersionInput } from './settings-panel.hooks.js';

/**
 * @file The consent settings split into the three sections a host can place on its own tabs:
 * Banner (copy and links), Look (placement and appearance) and Rules (on/off, region, version).
 * `ConsentSettingsPanel` stacks all three for hosts that want one screen. Every section is
 * controlled: it renders `value`, reports edits as patches and shows the host's `problems` next to
 * the field each one names. Hosts style the plain `jini-` classes.
 */

type TextKey = 'title' | 'message' | 'acceptLabel' | 'rejectLabel' | 'preferencesLabel' | 'privacyPolicyUrl' | 'secondaryLinkLabel' | 'secondaryLinkUrl';

export interface ConsentFieldsProps {
  value: ConsentSettingsView;
  onChange(required: { patch: Partial<ConsentSettingsView> }, optional?: Record<string, never>): void;
  disabled?: boolean | undefined;
  /** Server/engine problems; each one with a matching `field` renders under that control. */
  problems?: readonly ConsentFieldProblem[] | undefined;
  /** Host translations keyed by the exact fallback copy; unspecified entries use English. */
  dictionary?: Readonly<Record<string, string>> | undefined;
  /** Host max lengths per text field; the defaults are the engine's loosest bounds. */
  limits?: Readonly<Partial<Record<TextKey | 'policyVersion', number>>> | undefined;
}

const BANNER_FIELDS: readonly { key: TextKey; label: string; multiline?: boolean }[] = [
  { key: 'title', label: 'Banner title' }, { key: 'message', label: 'Banner message', multiline: true },
  { key: 'acceptLabel', label: 'Accept button text' }, { key: 'rejectLabel', label: 'Reject button text' },
  { key: 'preferencesLabel', label: 'Preferences label' }, { key: 'privacyPolicyUrl', label: 'Privacy policy page URL' },
  { key: 'secondaryLinkLabel', label: 'Second link text' }, { key: 'secondaryLinkUrl', label: 'Second link URL' },
];
const BANNER_MODE_LABELS = { jini: 'Jini banner', headless: 'My own', off: 'None' } as const;
const REGION_LABELS: Readonly<Record<ConsentSettingsView['regionMode'], string>> = {
  auto: 'Automatic (unknown region: opt-in)', 'opt-in': 'Opt-in everywhere (EU / UK)', 'opt-out': 'Opt-out everywhere (California)',
};
const PLACEMENT_LABELS: Readonly<Record<string, string>> = { 'bottom-bar': 'Bottom bar', 'bottom-left': 'Bottom left', 'bottom-right': 'Bottom right', 'top-bar': 'Top bar' };
// Native color inputs need concrete colors rather than CSS variable expressions.
const COLOR_TOKENS: readonly { key: keyof ConsentAppearanceView; label: string; fallback: string }[] = [
  { key: 'backgroundColor', label: 'Background', fallback: defaultAdminTheme.light.bg }, { key: 'textColor', label: 'Text', fallback: defaultAdminTheme.light.text }, { key: 'borderColor', label: 'Border', fallback: defaultAdminTheme.light.border },
];
/** The engine's own pixel bounds (`compileConsentCss`); out-of-range values come back as problems. */
const PIXEL_TOKENS: readonly { key: keyof ConsentAppearanceView; label: string; min: number; max: number }[] = [
  { key: 'borderRadius', label: 'Corner radius (px)', min: 0, max: 32 }, { key: 'padding', label: 'Padding (px)', min: 8, max: 32 },
  { key: 'fontSize', label: 'Text size (px)', min: 16, max: 24 }, { key: 'maxWidth', label: 'Max width (px)', min: 256, max: 960 },
];

function translator(dictionary: Readonly<Record<string, string>> = {}) {
  return (text: string) => dictionary[text] ?? text;
}

/** One field's problems, linked to its control through `aria-describedby`. */
function FieldProblems({ id, problems }: { id: string; problems: readonly ConsentFieldProblem[] }) {
  if (!problems.length) return null;
  return <span id={id} className="jini-consent-field-problems">{problems.map(problem => <span key={`${problem.code ?? ''}${problem.message}`} className="jini-hint jini-hint-error">{problem.message}</span>)}</span>;
}

type ControlAttributes = { id: string; 'aria-invalid'?: true; 'aria-describedby'?: string };

/** Label + control + problems. Problems sit outside the label so they never join the control's
 * name; they are its description and mark it invalid instead. */
function Field({ label, field, problems, children }: { label: string; field: string; problems?: readonly ConsentFieldProblem[] | undefined; children: (attributes: ControlAttributes) => ReactNode }) {
  const id = useId();
  const own = problemsFor({ problems, field });
  const attributes = own.length ? { id, 'aria-invalid': true as const, 'aria-describedby': `${id}-problems` } : { id };
  return <div className="jini-consent-settings-field"><label htmlFor={id} className="jini-field-label">{label}</label>{children(attributes)}<FieldProblems id={`${id}-problems`} problems={own} /></div>;
}

/** Host-supplied banner modes. Native radios provide keyboard selection; the hint keeps its space
 * while hidden, and the parent fieldset supplies the disabled state. */
function BannerModeFields({ value, onChange, dictionary, modes }: Pick<ConsentFieldsProps, 'value' | 'onChange' | 'dictionary'> & { modes: readonly NonNullable<ConsentSettingsView['bannerMode']>[] }) {
  const id = useId();
  const t = translator(dictionary);
  const handlers = useConsentSettingsPanel({ value, onChange });
  return <fieldset className="jini-consent-banner-modes" aria-describedby={value.bannerMode === 'headless' ? `${id}-mode-hint` : undefined}>
      <legend>{t('Banner mode')}</legend>
      <div className="jini-consent-banner-options">{modes.map(mode => <label key={mode}>
        <input type="radio" name={`${id}-banner-mode`} value={mode} checked={(value.bannerMode ?? 'jini') === mode} onChange={handlers.bannerMode({ mode })} />
        <span>{t(BANNER_MODE_LABELS[mode])}</span>
      </label>)}</div>
      <p id={`${id}-mode-hint`} className="jini-hint jini-consent-banner-mode-hint" style={{ visibility: value.bannerMode === 'headless' ? 'visible' : 'hidden' }}>
        {t('Your banner calls window.jiniConsent.set(...)')}
      </p>
    </fieldset>;
}

/** Banner copy and its links. Optional host modes report only a mode patch; the host's independent
 * enabled switch stays authoritative. Text is always plain text.
 * @example <ConsentBannerFields value={value} onChange={onChange} bannerModes={['jini', 'headless', 'off']} /> */
export function ConsentBannerFields({ value, onChange, disabled = false, problems, dictionary, limits = {}, bannerModes }: ConsentFieldsProps & { bannerModes?: readonly NonNullable<ConsentSettingsView['bannerMode']>[] | undefined }) {
  const t = translator(dictionary);
  const handlers = useConsentSettingsPanel({ value, onChange });
  return <fieldset disabled={disabled} className="jini-consent-settings-fields"><legend>{t('Banner text')}</legend>
    {bannerModes && <BannerModeFields value={value} onChange={onChange} dictionary={dictionary} modes={bannerModes} />}
    {BANNER_FIELDS.map(({ key, label, multiline }) => <Field key={key} label={t(label)} field={key} problems={problems}>{aria => multiline
      ? <textarea className="jini-input" value={value[key] ?? ''} maxLength={limits[key] ?? 2000} rows={3} onChange={handlers.text(key)} {...aria} />
      : <input className="jini-input" type="text" value={value[key] ?? ''} maxLength={limits[key] ?? 2000} onChange={handlers.text(key)} {...aria} />}</Field>)}
    <p className="jini-hint">{t('Link a published privacy page, such as /privacy. The second link is optional.')}</p>
  </fieldset>;
}

/** On/off, script policy, region behavior and the version that re-asks visitors when it changes. */
export function ConsentRulesFields({ value, onChange, disabled = false, problems, dictionary, limits = {}, regionModes = ['auto', 'opt-in', 'opt-out'] }: ConsentFieldsProps & { regionModes?: readonly ConsentSettingsView['regionMode'][] }) {
  const id = useId();
  const t = translator(dictionary);
  const handlers = useConsentSettingsPanel({ value, onChange });
  const modes = regionModes.includes(value.regionMode) ? regionModes : [value.regionMode, ...regionModes];
  return <fieldset disabled={disabled} className="jini-consent-settings-fields"><legend>{t('Rules')}</legend>
    <button type="button" className={value.enabled ? 'jini-toggle-row on' : 'jini-toggle-row'} role="switch" aria-checked={value.enabled} aria-labelledby={`${id}-enabled`} aria-describedby={`${id}-hint`} onClick={handlers.toggle}>
      <span className="jini-toggle-row-text"><span id={`${id}-enabled`} className="jini-toggle-row-label">{t('Enable cookie consent on this site')}</span><span id={`${id}-hint`} className="jini-toggle-row-hint">{t('Applies to published site pages.')}</span></span><span className="jini-toggle-row-switch" aria-hidden="true" />
    </button>
    {value.enabled && <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
      <button type="button" className={value.allowUnsafeEval === true ? 'jini-toggle-row on' : 'jini-toggle-row'} role="switch" aria-checked={value.allowUnsafeEval === true} aria-labelledby={`${id}-eval`} aria-describedby={`${id}-eval-hint`} onClick={handlers.toggleUnsafeEval}>
        <span className="jini-toggle-row-text"><span id={`${id}-eval`} className="jini-toggle-row-label">{t('Allow dynamic code (unsafe-eval)')}</span></span><span className="jini-toggle-row-switch" aria-hidden="true" />
      </button>
      {/* Keep the independently focusable help trigger outside the switch. */}
      <InfoTip triggerLabel={t('About dynamic code')} descriptionId={`${id}-eval-hint`} label={t("Some themes need this. It weakens the site's script protection. Optional scripts still wait for consent.")} />
    </div>}
    <Field label={t('Region mode')} field="regionMode" problems={problems}>{aria => <select className="jini-input" value={value.regionMode} onChange={handlers.region} {...aria}>
      {modes.map(mode => <option key={mode} value={mode}>{t(REGION_LABELS[mode])}</option>)}
    </select>}</Field>
    <p className="jini-hint">{t('California permits optional categories until opt-out. Global Privacy Control always disables analytics and marketing.')}</p>
    <Field label={t('Policy version')} field="policyVersion" problems={problems}>{aria => <PolicyVersionInput value={value.policyVersion} onChange={onChange} maxLength={limits.policyVersion ?? 128} aria={aria} />}</Field>
    <p className="jini-hint">{t('Change the policy version to ask visitors to choose again.')}</p>
  </fieldset>;
}

/** Placement, bounded appearance tokens and allowlisted custom CSS. The engine checks contrast and
 * CSS safety; its problems arrive on the `appearance` field and show under the custom CSS. */
export function ConsentLookFields({ value, onChange, disabled = false, problems, dictionary, placements = Object.keys(PLACEMENT_LABELS) }: ConsentFieldsProps & { placements?: readonly string[] }) {
  const t = translator(dictionary);
  const handlers = useConsentSettingsPanel({ value, onChange });
  const appearance = value.appearance ?? {};
  return <fieldset disabled={disabled} className="jini-consent-settings-fields"><legend>{t('Look & position')}</legend>
    <Field label={t('Position')} field="placement" problems={problems}>{aria => <select className="jini-input" value={value.placement ?? placements[0]} onChange={handlers.placement} {...aria}>
      {placements.map(placement => <option key={placement} value={placement}>{t(PLACEMENT_LABELS[placement] ?? placement)}</option>)}
    </select>}</Field>
    <div className="jini-consent-token-grid">
      {COLOR_TOKENS.map(token => <ColorToken key={token.key} label={t(token.label)} value={appearance[token.key]} fallback={token.fallback} resetLabel={t('Default')} onChange={handlers.token(token.key)} />)}
      {PIXEL_TOKENS.map(token => <Field key={token.key} label={t(token.label)} field={token.key}>{attributes =>
        <input className="jini-input" type="number" inputMode="numeric" min={token.min} max={token.max} step={1} placeholder={t('Default')} value={pixelInputValue({ value: appearance[token.key] })} onChange={event => handlers.token(token.key)(event.target.value === '' ? '' : `${event.target.value}px`)} {...attributes} />}</Field>)}
    </div>
    <Field label={t('Custom CSS')} field="appearance" problems={problems}>{aria => <textarea className="jini-input jini-consent-css" value={value.customCss ?? ''} rows={6} spellCheck={false} onChange={handlers.text('customCss')} {...aria} />}</Field>
    <p className="jini-hint">{t('Only banner selectors and safe properties are allowed. Text needs 4.5:1 contrast.')}</p>
  </fieldset>;
}

/** A native color picker; unset shows the shared theme default and offers no reset. */
function ColorToken({ label, value, fallback, resetLabel, onChange }: { label: string; value: string | undefined; fallback: string; resetLabel: string; onChange(next: string): void }) {
  const id = useId();
  return <div className="jini-consent-settings-field"><label htmlFor={id} className="jini-field-label">{label}</label>
    <span className="jini-consent-color-row">
      <input id={id} className="jini-consent-color" type="color" value={value ?? fallback} onChange={event => onChange(event.target.value)} />
      <code className="jini-hint">{value ?? resetLabel}</code>
      {value !== undefined && <button type="button" className="jini-btn-link" aria-label={`${resetLabel}: ${label}`} onClick={() => onChange('')}>{resetLabel}</button>}
    </span>
  </div>;
}

/** Keep transient empty edits local; only a valid policy version reaches autosave.
 * Native validity gives keyboard users an actionable error. @complexity O(version length), <=128. */
function PolicyVersionInput({ value, onChange, maxLength, aria }: Pick<ConsentFieldsProps, 'onChange'> & { value: string; maxLength: number; aria: object }) {
  const { draft, change, blur } = usePolicyVersionInput({ value, onChange });
  return <input className="jini-input" type="text" value={draft} required pattern={String.raw`.*\S.*`} maxLength={maxLength}
    onChange={change} onBlur={blur} {...aria} />;
}

import { createElement } from 'react';
import type { FormEvent } from 'react';
import type { TabBarTab } from '@jini-ai/ui/tab-strip';
import { SeoDefaultsIcon, SeoSitemapIcon, SeoEntriesIcon } from '../components/SeoIcons.js';
import { buildSeoSettingsPatch, resolveSeoTabId, sortIssuesBySeverity, scoreTone } from '../../rules.js';
import type { SeoTranslator, SeoSettingsPatch, SeoSettings, SeoEntryAnalysis } from '../../models.js';
import { useSeoOptions } from './SeoPorts.hooks.js';
export { buildSeoSettingsPatch, resolveSeoTabId } from '../../rules.js';
export type { SeoTabId } from '../../rules.js';
export function resolveSeoTabs(_required: Record<string, never> = {}, { t = key => key }: { t?: SeoTranslator | undefined } = {}): TabBarTab[] {
  return [
    { id: 'defaults', label: t('Site defaults'), icon: createElement(SeoDefaultsIcon), handle: 'seo-tab-defaults', handleLabel: 'Switch to the Site defaults tab — title template, meta description, social image and card handle, and the default robots directives' },
    { id: 'sitemap', label: t('Sitemap'), icon: createElement(SeoSitemapIcon), handle: 'seo-tab-sitemap', handleLabel: 'Switch to the Sitemap tab — rebuild the cached sitemap, or view the URLs it contains' },
    { id: 'entries', label: t('Pages & posts'), icon: createElement(SeoEntriesIcon), handle: 'seo-tab-entries', handleLabel: 'Switch to the Pages & posts tab — override and analyze the SEO metadata of one page or post' },
  ];
}
export function sitemapStateLabel({ sitemapEnabled }: { sitemapEnabled: boolean }, { t = key => key }: { t?: SeoTranslator | undefined } = {}): string {
  return t(sitemapEnabled ? 'This site publishes a sitemap.' : 'This site does not publish a sitemap. Turn it on under Site defaults.');
}
/** Module onTabChange owns the ?tab= URL. The host uses replace:true to avoid back-stack growth. */
export function useSeoPageActions(
  { onTabChange }: { onTabChange?: ((required: { tab: string }, optional?: Record<string, never>) => void) | undefined }, _optional: Record<string, never> = {},
) { return { changeTab: (tab: string) => onTabChange?.({ tab }) }; }
export function useSeoTabs({ tabId }: { tabId?: string | null | undefined }, _optional: Record<string, never> = {}) {
  const { t } = useSeoOptions();
  return { activeTabId: resolveSeoTabId({ tabId }), tabs: resolveSeoTabs({}, { t }) };
}
export function useAnalyzePanel({ analysis }: { analysis: SeoEntryAnalysis }, _optional: Record<string, never> = {}) {
  return { sortedIssues: sortIssuesBySeverity({ issues: analysis.issues }), tone: scoreTone({ score: analysis.score }) };
}
/** All seven defaults remain in one FormData submission; tabs never split this form. */
export function useSeoDefaults({ save }: { save: (patch: SeoSettingsPatch) => Promise<void> }, _optional: Record<string, never> = {}) {
  return { submit: (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); void save(buildSeoSettingsPatch({ form: new FormData(event.currentTarget) })); } };
}

export interface SeoTabController {
  locale: string;
  settings: SeoSettings;
  saving: boolean;
  save: (patch: SeoSettingsPatch) => Promise<void>;
  defaultOgImage: string;
  setDefaultOgImage: (value: string) => void;
  regenerateSitemap: () => void;
  openSitemapModal: () => void;
}

import { useAnalyzePanel, useSeoDefaults, useSeoTabs } from "../hooks/SeoPage.hooks.js";
import type { ReactNode } from "react";
import type { SeoTabController, SeoTabId } from "../hooks/SeoPage.hooks.js";

import { agentHandle } from "@jini-ai/agentic";

import { TabBar } from "@jini-ai/ui/tab-strip";
import { InfoTip, Select } from "@jini-ai/ui/admin-widgets";
import { useSeoCopy, useSeoOptions } from "../hooks/SeoPorts.hooks.js";
import { actionLabel, orEmpty, xIsCustomized, xResolvedValue } from "../../rules.js";
import { useWiredEntryPicker } from "../hooks/use-entry-picker.hooks.js";
import { useWiredSeoEntryPanel } from "../hooks/use-seo-entry-panel.hooks.js";
import { useSeoEntrySection } from "../hooks/use-seo-entry-section.hooks.js";
import { useWiredSeo } from "../hooks/use-seo.hooks.js";
import {
  useSeoPageActions,
  sitemapStateLabel,
} from "../hooks/SeoPage.hooks.js";
import { MediaRefField } from "../components/MediaRefField.js";
import { SitemapModal } from "../components/SitemapModal.js";

import type { SeoEntryAnalysis, SeoEntryPanelController } from "../../models.js";

/**
 * `SeoSettingsScreen` (SPEC-008 ui.spec.md §2.4) — the site-wide `seo.*` settings form +
 * `SitemapRegenerateButton` (§2.6). Coordinator-authored 2026-07-13, post-session-limit resume.
 * Markup only.
 *
 * State and API calls live in one hook per component: `hooks/use-seo.hooks.ts` (top-level
 * defaults form + sitemap button), `hooks/use-entry-picker.hooks.ts`, `hooks/use-seo-entry-panel
 * .hooks.ts`, `hooks/use-seo-entry-section.hooks.ts`. The issue-severity sort lives in `rules.ts`.
 *
 * SPEC-037 REQ-06/07/08: `SeoEntryPanel` closes the deferred per-entry gap this file's own header
 * used to disclose — a standalone entry picker (dropdown over `listPosts`/`listPages`, cheaper
 * than threading a new panel through `PostEditor.tsx`, per REQ-06's own "implementer's choice")
 * plus a partial-override edit form and a read-only analyze view. `RobotsRuleEditor` (§2.5) is
 * still a minimal textarea-per-rule form (unchanged from the original disclosed scope note).
 *
 * Copy comes from the module's injected t function. Legacy locale props remain render-contract
 * metadata only; the host retains its dictionaries and passes the bound translator through the module.
 * Host publish behavior is injected as headerActions, and media selection uses its existing slot
 * or the shared mediaPickerToken service. The original rationale is archived in SOURCE-RATIONALE.
 *
 * ## Tabs (2026-09-06)
 *
 * The three sections above are now three `?tab=` tabs — Site defaults, Sitemap, Pages & posts —
 * built on the shared `@jini-ai/ui/tab-strip` that `Deployment.tsx`, `Sites.tsx`, `Themes.tsx`,
 * `Security.tsx`, `SourceControl.tsx` and `Database.tsx` already use. Nothing new was written for
 * the tab mechanism: the shell was ALREADY extracted (`@jini-ai/ui/tab-strip` for the strip,
 * `lib/resolve-active-tab-id.ts` for the `?tab=` guard), so this screen reuses it rather than
 * becoming a third implementation. The reasoning for the grouping, the tab NAMES, and the one
 * cut that was considered and rejected all live in `react/hooks/SeoPage.hooks.ts`'s header.
 *
 * Everything below the shell is unchanged markup, only relocated: `SeoDefaultsTab` holds the form
 * verbatim (with two field-group headings added, which it never had), `SeoSitemapTab` holds the
 * sitemap actions plus a new state line, and the Pages & posts panel IS the existing
 * `SeoEntrySection`, rendered directly rather than wrapped in a new component that would add
 * nothing.
 * No component was split or merged, so `SeoEntryPanel` — the one function in this file carrying a
 * recorded complexity exemption (`development/scripts/admin-complexity-debt.json`, keyed by
 * `{rule, file, reason}`) — stays in THIS file at its recorded measurement. Moving it to a tab
 * file of its own, the way `Deployment.tsx` gives each tab a file, would have made its debt entry
 * name a path that no longer exists and required adding a NEW entry for the new file, growing a
 * baseline that JSON's own instructions say must only shrink. One file, top-level components: the
 * ESLint gate scores functions independently of which file they sit in, so the ceiling is
 * satisfied either way — only the organizational preference differs, and the debt key decides it.
 *
 * ## Out of the cards (2026-09-06, same day)
 *
 * Owner, on the screen the section above describes: "for seo can you take the stuff out of the
 * cards?" Every panel here was a `.card` (Site defaults, Sitemap) or a `.notice` (the two
 * per-entry panels) and is now content laid directly on the page, held together by `SeoSection`'s
 * heading rail and one hairline per seam. `styles/seo.css`'s header carries the measurements and
 * the full reasoning, including why the card was never what grouped the three field groups.
 *
 * Two claims in the paragraph above are now stale and are corrected here rather than rewritten in
 * place, since the tab conversion's own reasoning is still the reason the tabs exist: the defaults
 * form has THREE field-group headings, not two ("Social sharing" was split out in the same
 * commit), and those groups are `SeoSection`s rather than `.field-group` divs. What has NOT
 * changed is the constraint that matters — all seven fields still live in one `<form>`, submitted
 * as one `FormData`, with nothing about them conditional.
 */

export interface SeoSectionProps {
  title: string;
  /** Optional ⓘ explanation beside the title (explanations are tips, never loose paragraphs). */
  tip?: string;
  children: ReactNode;
}

/**
 * One titled group on this screen — title in the left rail, controls in the right column. Markup
 * only; every visual decision and the reasoning for the rail lives in `styles/seo.css`'s header.
 *
 * This is the 1:1 replacement for the `<div className="field-group"><h2 className="card-title">`
 * pair `56e87ae0` introduced, and the swap is deliberately structure-preserving: the section body
 * carries `.field-group`'s exact `flex-column` + `--space-4` gap, so the fields inside are laid
 * out identically and NOTHING becomes conditional. That matters more here than anywhere else in
 * this file — `SeoDefaultsTab` submits via `new FormData(e.currentTarget)`, so a field that stops
 * being mounted is simply absent from the payload and silently saves as blank. A wrapper element
 * cannot unmount anything, and `Seo.unit.test.tsx`'s "keeps every defaults field inside ONE form"
 * pins all seven names, in order, against exactly that.
 *
 * Fixed `<h2>` rather than a `level` prop: both callers are top-level groups under the page `H1`,
 * and the one heading on this screen that is genuinely subordinate — `SeoEntryPanel`'s "Per-entry
 * overrides", which sits INSIDE the "Per-entry SEO" section — keeps its own `<h3>` and is not
 * routed through here.
 */
function SeoSection({ title, tip, children }: SeoSectionProps) {
  return (
    <section className="jini-seo-section">
      <div className="jini-seo-section-head">
        <h2 className="jini-seo-section-title">
          {title}
          {tip ? <InfoTip label={tip} /> : null}
        </h2>
      </div>
      <div className="jini-seo-section-body">{children}</div>
    </section>
  );
}

export interface EntryPickerProps {
  locale: string;
  entryId: string;
  onChange: (entryId: string) => void;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. */
  useEntryPickerHook?: typeof useWiredEntryPicker;
}

/** Searchable picker over every page + post, sourced from the already-existing `listPosts`/`listPages`
 * routes (REQ-06). It was a native `<select>`; with a few dozen entries that opened as one tall OS
 * list with "(published)" after every row (owner, 2026-10-15: "we have a searchable dropdown
 * right?"). The shared admin-widgets `Select` already types-to-filter and handles the keyboard, so
 * rows are just grouped Pages/Posts with a pill only for the non-published exceptions
 * (`entryPickerOptions` in `rules.ts`). */
function EntryPicker({ locale, entryId, onChange, useEntryPickerHook = useWiredEntryPicker }: EntryPickerProps) {
  const t = useSeoCopy();
  const { entries, options, error } = useEntryPickerHook();

  if (error) return <div className="jini-notice jini-notice-error">{error}</div>;
  if (!entries) return <div className="jini-notice">{t({ locale: locale, key: "Loading entries…" })}</div>;

  /* The "Entry" caption is no longer painted (owner, 2026-09-06: "you can actually just get rid of
     'Entry'") — the placeholder already says "Choose an entry…", so the visible word was saying it
     twice. It stays the control's accessible name (now `aria-label` on the combobox trigger) rather
     than leaving a placeholder-only control with no name at all. The i18n key is unchanged. */
  return (
    <div className="jini-seo-entry-picker">
      <Select
        value={entryId}
        onChange={onChange}
        options={options ?? []}
        placeholder={t({ locale: locale, key: "Choose an entry…" })}
        aria-label={t({ locale: locale, key: "Entry" })}
        agentHandle="seo-entry-picker"
        translate={(key) => t({ locale, key })}
      />
    </div>
  );
}

/** Status-chip modifier for an issue: errors read as failures, warnings as warnings, anything else as success. */
function issueStatusClass(severity: string): string {
  if (severity === "error") return "failure";
  return severity === "warning" ? "warning" : "success";
}

/** Read-only score + issues view (REQ-07) — exact field names read off `SeoAnalysis`/`SeoIssue`
 * (`src/seo/types.ts`), not guessed. No state of its own — only the severity sort, which lives in
 * `rules.ts` as `sortIssuesBySeverity`. */
function AnalyzePanel(props: { locale: string; analysis: SeoEntryAnalysis }) {
  const t = useSeoCopy();
  const { locale } = props;
  const { sortedIssues, tone } = useAnalyzePanel({ analysis: props.analysis });

  /* Heading + score pill on one line, issues as a compact list (owner, 2026-10-15: the bare
     "Score: 100 / No issues." read as unstyled text). The pill reuses the issue pills' status
     tones, so the score and the issues under it speak one colour language. */
  return (
    <section className="jini-seo-analyze-panel" aria-labelledby="seo-analysis-heading">
      <div className="jini-seo-analyze-head">
        <h3 id="seo-analysis-heading">{t({ locale: locale, key: "Analysis" })}</h3>
        <span className={`jini-status jini-status-${tone} jini-seo-score`}>
          {t({ locale: locale, key: "Score:" })} <strong>{props.analysis.score}</strong>
        </span>
      </div>
      {sortedIssues.length === 0 ? (
        <p className="jini-seo-analyze-empty">{t({ locale: locale, key: "No issues." })}</p>
      ) : (
        <ul className="jini-seo-issues">
          {sortedIssues.map((issue, i) => (
            <li key={`${issue.code}-${i}`} className="jini-seo-issue">
              <span className={`jini-status jini-status-${issueStatusClass(issue.severity)}`}>
                {issue.severity}
              </span>
              <span className="jini-seo-issue-text">
                {issue.message}
                {issue.field ? <span className="jini-muted-cell"> ({issue.field})</span> : null}
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export interface SeoEntryPanelProps {
