import { listInstalledPackageRoots } from "./installed-package-roots.js";
import { createUninstallModule } from "./uninstall.js";
import { AgentPluginInstallError } from "./install-errors.js";
import { createInstalledPackageIndex } from "./installed-package-index.js";
import { readPluginIdentity, assertPluginIdentityAvailable } from "@jini-ai/core/plugin-directory";
/**
 * @file `installAgentPlugin()` — content-addressed, adversarially-hardened extraction of one Agent
 * Plugin (agent-plugins.org) archive into one workspace's own `AgentPluginWorkspaceLayout.packages`.
 *
 * This is the highest-risk unit in the whole feature. Extraction is where containment actually
 * breaks — everything downstream (capability projection, a future MCP admission gate) trusts that a
 * "package root" is exactly the bytes the archive declared, laid out exactly where the archive said,
 * with nothing outside it touched. Two independently-cited attack classes drive the checks here:
 *
 * - **Zip-slip / archive-extraction path traversal** (Snyk's zip-slip research; JFrog's
 *   `mholt/archiver` writeup; the `node-tar` GHSA-8qq5-rm4j-mr97 advisory) has two vectors: a
 *   crafted entry NAME containing `../` (caught by {@link normalizePackageEntryPath}'s lexical
 *   check), and a crafted SYMLINK entry whose target a later, innocent-looking entry name walks
 *   through. The convergent ecosystem fix for the second vector — and the one this module takes — is
 *   to refuse symlink entries outright rather than attempt to validate where they point: a plugin
 *   has no legitimate reason to ship a symlink inside its own package, and the Agent Plugins spec's
 *   own path-safety clause only ever promises symlinks MAY resolve inside the root, never that a
 *   client must accept one.
 * - **Decompression bombs**, in both the classic "one file lies about its size" shape (caught by
 *   bounding bytes actually observed leaving `openReadStream()`, not the archive's own declared
 *   size) and the "many small files" shape (caught by a running total across the whole archive).
 *
 * Why this is a SEPARATE format from the host runtime-plugin format's loader (`plugin-runtime/loader.ts`), not a
 * shared one: verified against that file directly. `loadPlugin()`'s BR-01 pipeline requires
 * `manifest.integrity` (a per-file SHA-256 map), `manifest.sdkRange` checked against a runtime
 * the host plugin SDK version, and a `server/index.mjs` ESM entry point it `import()`s. An Agent Plugin has
 * none of those — no integrity map, no SDK range, no single entry point, and (per this feature's own
 * FINAL decision) no code the host ever imports or executes at all in v1: Skills are markdown read for
 * context injection, and MCP servers are preview-only (`capability-projection.ts`). Adapting Agent
 * Plugins into `loadPlugin()`'s pipeline would mean inventing values for fields the open standard
 * does not define, which is precisely the "package format vs. execution/trust model" conflation this
 * feature's own owner-locked decisions (see `CTX-AGENTPLUGINS-2026-08-12.md` F2) rule out.
 *
 * Why the archive itself is a `ArchiveReaderPort`, not a concrete zip/tar library call: this
 * codebase's own port+adapter discipline (`mcp-federation/ports.ts`'s `McpSessionPort`/
 * `McpStdioChannel` split is the direct precedent) — and, concretely, no zip/tar dependency exists
 * in this repo's `package.json` today. Choosing and vetting one (license, maintenance, streaming
 * support) is a real decision outside a Programmer's scope to make silently; this module declares
 * the seam and is exercised end-to-end by a scripted double, so a real adapter is a pure addition
 * with zero change to the hardening logic here. See the handoff's REMAINING section.
 *
 * Content-addressing (`ws/<workspaceId>/packages/sha256/<archiveDigest>/`): the digest is verified
 * BEFORE extraction ever touches the archive reader, so an install with a mismatched digest never
 * even attempts to unpack — the digest is the trust boundary between "bytes a marketplace claimed"
 * and "bytes this process is willing to run a parser over". A second install of byte-identical
 * content BY THE SAME WORKSPACE is recognized from the digest alone and short-circuits without a
 * second extraction. Deliberately NOT shared across workspaces — see `layout.ts`'s header (owner
 * decision, tenant-grade isolation, 2026-08-12): this function resolves the workspace-scoped layout
 * itself, exactly once, from an instance-level `AgentPluginLayout` plus one `workspaceId` (see the
 * SECURITY note on {@link InstallAgentPluginRequired} below) — the caller is what makes two
 * different workspaces' installs land in disjoint trees, simply by supplying a different
 * `workspaceId` for each; this function's own internal `forWorkspace()` call is what turns that into
 * disjoint, internally-consistent paths.
 *
 * Architectural role:
 * The one place this feature performs filesystem writes for installed package bytes. No network I/O
 * (archive bytes and their expected digest are caller-supplied — see the module header above for why
 * "how does the archive get here" is out of this slice) and no execution of anything extracted.
 */
import { createPersistentStateModule } from "./persistent-state.js";
import { createAgentPluginUpdateStore, settleAgentPluginUpdateJournal } from "./update-store.js";
/** Extracted from the host plugin lifecycle. Effects are supplied per host context. */
import { createHash } from "node:crypto";
import { constants } from "node:fs";
import path from "node:path";
import type { AgentPluginLayout } from "./layout.js";
import { PackagePathViolation } from "./package-paths.js";
import { createPackagePathsModule } from "./package-paths.js";
import type { AgentPluginLifecyclePorts } from "./ports.js";
import type { InstalledAgentPlugin } from "./types.js";
export type { InstalledAgentPlugin, InstalledAgentPluginSkill } from "./types.js";

export { AgentPluginInstallError } from "./install-errors.js";
export type { AgentPluginInstallErrorCode } from "./install-errors.js";
/** One archive entry. A symlink is modeled as its OWN kind rather than folded into "file" — the
 * zip-slip research this module's header cites is explicit that the symlink-entry vector is
 * distinct from the lexical-traversal one, and the two need independent tests and independent
 * handling (see the "symlink entries are rejected outright" rule below). */
export type AgentPluginArchiveEntry =
  | {
      readonly kind: "file";
      readonly entryPath: string;

      /** The archive format's own claimed size. Never trusted alone — see `DECOMPRESSION_BOMB`. */
  readonly declaredSize?: (number) | undefined;
      readonly executable?: (boolean) | undefined;
      readonly openReadStream: (required: Record<string, never>) => AsyncIterable<Uint8Array>;
    }
  | { readonly kind: "directory"; readonly entryPath: string }
  | { readonly kind: "symlink" | "hardlink" | "device" | "fifo"; readonly entryPath: string; readonly linkTarget?: string | undefined };

/**
 * `entries` must be a pure function of the archive bytes: an install iterates it twice, once to
 * check entry-count limits from metadata alone and once to extract.
 */
/** `entries` is a pure function of archive bytes: metadata preflight and extraction iterate it twice. */
export interface AgentPluginArchiveReaderPort {
  entries(required: { readonly archive: Uint8Array }): AsyncIterable<AgentPluginArchiveEntry>;
}

export interface InstallAgentPluginRequired {
  readonly archive: Uint8Array;

  /** Lowercase hex SHA-256 the caller expects `archive` to hash to — a real marketplace flow would
   * supply this from the server's own metadata; verified here, never trusted from the archive
   * itself. */
  readonly expectedSha256: string;
  readonly archiveReader: AgentPluginArchiveReaderPort;

  /**
   * SECURITY (2026-08-13, security pass Finding 2 — tenant isolation, `ADS-memory/reports/security/
   * 2026-08-13-post-session-security-pass.md`): this field used to be an already-resolved
   * `AgentPluginWorkspaceLayout` (`{ root, packages, staging, pluginDataDir }`) — a plain interface
   * of four independently-typed string/function fields with no tag identifying which workspace it
   * came from. Nothing stopped a caller from hand-assembling one from two DIFFERENT real
   * `forWorkspace()` results (wrong variable capture, a stale cached layout, a future code path that
   * builds one by hand instead of calling `forWorkspace`) — such a value type-checked identically to
   * a correctly-resolved one, and `installAgentPlugin` published into whatever `packages`/`staging`
   * it was handed with no consistency check. Proven at the unit level in `install.unit.test.ts`
   * (a layout stitching workspace A's `root`/`pluginDataDir` onto workspace B's real `packages`/
   * `staging` published into workspace B's real, on-disk store with no error).
   *
   * The fix: `installAgentPlugin` no longer accepts a pre-resolved workspace layout as input AT ALL.
   * It takes the RAW MATERIALS instead — the INSTANCE-level layout (`resolveAgentPluginLayout()`,
   * carries no workspace-scoped path of its own) plus one `workspaceId` — and calls
   * `layout.forWorkspace(workspaceId)` itself, exactly once, internally. There is no longer any
   * `AgentPluginWorkspaceLayout`-shaped parameter here for a caller to stitch fields into: the one
   * and only path from these two inputs to `packages`/`staging`/`pluginDataDir` is the real
   * `forWorkspace()` closure, called atomically, so the four resulting paths can never disagree with
   * each other about which workspace they belong to. Passing a hand-built `{ packages, staging, ... }`
   * literal where this field is expected is now a compile-time type error, not a runtime hazard.
   *
   * `workspaceId` must still come from the authenticated principal's own request context, never
   * derived from `layout` itself (a hand-built or malicious `AgentPluginLayout` could fake a
   * `forWorkspace` implementation identically) — that half of the guarantee is a caller obligation
   * this type cannot enforce, the same way `archiveReader` above is a fully caller-trusted port. What
   * IS closed is the specific, demonstrated bug class: stitching or hand-assembling an
   * already-resolved workspace layout from parts.
   */
  readonly layout: AgentPluginLayout;

  /** The workspace this install is for. Combined with {@link layout} via `layout.forWorkspace(workspaceId)`
   * — see the SECURITY note on {@link layout} above. */
  readonly workspaceId: string;
}

export interface InstallAgentPluginOptional {
  /** Full bounded extraction/validation in staging, with no package or memory publication. */
  readonly previewOnly?: boolean;
  /** Host policy transaction inside the per-plugin lock after validation. Call publish exactly
   * once to install; returning an existing package without calling it is a deduplicated no-op. */
  /** Host policy transaction, called inside the existing per-plugin lock after validation.
   * It must invoke publish exactly once to install. Shared lifecycle counterpart is in chat-tools.jini.patch. */
  readonly publishGuard?: (required: { readonly plugin: InstalledAgentPlugin; readonly publish: () => Promise<InstalledAgentPlugin> }, optional: Record<string, never>) => Promise<InstalledAgentPlugin>;
}

function buildModule(ports: AgentPluginLifecyclePorts) {
  const persistentState = createPersistentStateModule(ports);
  const chmod = ports.filesystem.chmod.bind(ports.filesystem);
  const mkdir = ports.filesystem.mkdir.bind(ports.filesystem);
  const mkdtemp = ports.filesystem.mkdtemp.bind(ports.filesystem);
  const open = ports.filesystem.open.bind(ports.filesystem);
  const readdir = ports.filesystem.readdir.bind(ports.filesystem);
  const readFile = ports.filesystem.readFile.bind(ports.filesystem);
  const rename = ports.filesystem.rename.bind(ports.filesystem);
  const rm = ports.filesystem.rm.bind(ports.filesystem);
  const stat = ports.filesystem.stat.bind(ports.filesystem);
  const index = createInstalledPackageIndex({ ports });
  const indexInstalledRoot = (packageRoot: string, archiveDigest: string) => index.indexInstalledRoot({ packageRoot, archiveDigest });
  const { assertContainedOnDisk, normalizePackageEntryPath } = createPackagePathsModule(ports);
  const LIMITS = {
    maxArchiveBytes: 32 * 1024 * 1024,
    maxEntries: 4096,
    maxFileBytes: 16 * 1024 * 1024,
    maxTotalExtractedBytes: 64 * 1024 * 1024,
  } as const;

  /** Publisher ids are metadata, never filesystem segments. The workspace identity lock
   * serializes installs under different local names competing for one qualified id.
   * @complexity O(d) manifest reads for d installed revisions; no executable imports. */
  async function assertIdentityAvailable(workspaceRoot: string, candidate: InstalledAgentPlugin): Promise<void> {
    // Installed roots are canonical paths; compare against the same root even when the host
    // supplied an OS alias (macOS /var -> /private/var). Containment still rejects escaped links.
    workspaceRoot = await ports.filesystem.realpath(workspaceRoot);
    for (const root of await listInstalledPackageRoots({ ports, workspaceRoot })) {
      const manifestPath = path.join(root.packageRoot, 'plugin.json');
      await persistentState.assertOwnedPath({ workspaceRoot, entryPath: path.relative(workspaceRoot, manifestPath) });
      let raw: Record<string, unknown>;
      let identity: ReturnType<typeof readPluginIdentity>;
      try {
        raw = JSON.parse(await readFile(manifestPath, 'utf8'));
        identity = readPluginIdentity({ manifest: raw, name: root.localId, namespace: ports.extensionNamespace });
      } catch {
        // A damaged unrelated install must not block fresh installs or bundled seeding.
        ports.onEvent?.({ event: 'agent-plugin-identity-warning', message: `Plugin '${root.localId}': installed identity manifest is unreadable or invalid; omitted from identity admission.` });
        continue;
      }
      try {
        assertPluginIdentityAvailable({ candidate: { id: candidate.id!, localId: candidate.pluginId, family: 'agent-plugin' },
          installed: [{ ...identity, localId: root.localId, family: 'agent-plugin', version: typeof raw.version === 'string' ? raw.version : null, enabled: false }] });
      } catch { throw new AgentPluginInstallError({ code: 'PLUGIN_ID_CONFLICT', message: 'The publisher-qualified plugin id conflicts with an installed package.' }); }
    }
  }

  /** Retires only this plugin's superseded revisions after accepted publication, under the same
   * identity/plugin locks. Persistent data, learned facts and notes never enter this operation.
   * Reuse uninstall's frozen-tree staging so an interrupted removal is no longer a live digest.
   * There is no previous-revision rollback slot in this lifecycle; failed publication keeps all
   * prior bytes. Cleanup faults warn without turning an accepted install into a failed install.
   * @complexity O(d + f), d workspace revisions, f files in this plugin's superseded packages.
   */
  async function pruneSupersededRevisions(
    { workspaceRoot, installed }: { workspaceRoot: string; installed: InstalledAgentPlugin },
    _optional: Record<string, never> = {},
  ): Promise<void> {
    try {
      const removal = createUninstallModule(ports);
      for (const root of await listInstalledPackageRoots({ ports, workspaceRoot })) {
        if (root.localId !== installed.pluginId || root.archiveDigest === installed.archiveDigest) continue;
        try {
          const staged = await removal.stageForRemoval(path.dirname(root.packageRoot), root.packageRoot);
          await removal.removeFrozenPackageTree(staged.quarantined);
        } catch {
          ports.onEvent?.({ event: 'agent-plugin-revision-prune-warning', message: `Plugin '${installed.pluginId}': a superseded revision could not be pruned.` });
        }
      }
    } catch {
      ports.onEvent?.({ event: 'agent-plugin-revision-prune-warning', message: `Plugin '${installed.pluginId}': superseded revisions could not be scanned for pruning.` });
    }
  }

  /** Exposes `LIMITS.maxArchiveBytes` for a caller outside this module — concretely, a test asserting
 * `@jini-ai/agent-plugins/lifecycle`'s fetch cap constant stays pinned to this one. The local fetch-archive.ts fork was deleted; see the package's fetch module
 * for why it duplicates the number instead of importing it (no runtime dependency on `install.ts`);
 * this accessor is what lets a test assert the pairing without either module importing the other. */
  function maxAgentPluginInstallArchiveBytes(): number {
    return LIMITS.maxArchiveBytes;
  }

  const SHA256_HEX_PATTERN = /^[a-f0-9]{64}$/;

  /**
 * Verifies, extracts, and publishes one Agent Plugin archive.
 *
 * @throws {AgentPluginInstallError} For every expected failure — a hostile or malformed archive, a
 * digest mismatch, an invalid manifest. Never partially publishes: any failure after extraction has
 * begun removes the whole staging directory before rethrowing.
 * @complexity O(e) in archive entry count, O(b) in total extracted bytes — both explicitly bounded
 * by {@link LIMITS}, so this function's cost cannot be driven unbounded by a hostile archive.
 */
// The ONE call that turns (instance layout, workspaceId) into real, internally-consistent
// packages/staging/pluginDataDir paths — see the SECURITY note on `InstallAgentPluginRequired.layout`
// above for why this replaces accepting an already-resolved `AgentPluginWorkspaceLayout` directly.
// `forWorkspace` itself still throws for a syntactically invalid `workspaceId`, unchanged.
// Whether this install succeeded (bytes now live at `finalRoot`) or failed, the staging
// transaction directory itself must never be left behind — on success `rename` already moved
// `extractionRoot` out of it, so this only ever removes the (now-empty, or failure-abandoned)
// temp directory, never the published package.
  async function installAgentPlugin(
    required: InstallAgentPluginRequired,
    optional: InstallAgentPluginOptional = {}
  ): Promise<InstalledAgentPlugin> {
    const { archive, expectedSha256, archiveReader, layout, workspaceId } = required;

    const workspaceLayout = layout.forWorkspace({ workspaceId });

    if (archive.byteLength > LIMITS.maxArchiveBytes) {
      throw new AgentPluginInstallError({ code: "ARCHIVE_TOO_LARGE", message: `archive is ${archive.byteLength} bytes, over the ${LIMITS.maxArchiveBytes}-byte cap` });
    }

    const digest = sha256(archive);
    if (!SHA256_HEX_PATTERN.test(expectedSha256) || digest !== expectedSha256.toLowerCase()) {
      throw new AgentPluginInstallError({ code: "DIGEST_MISMATCH", message: `archive SHA-256 '${digest}' does not match the expected '${expectedSha256}' — refusing to extract unverified bytes` });
    }

    await mkdir(workspaceLayout.root, { recursive: true, mode: 0o700 });
    await persistentState.assertOwnedPath({ workspaceRoot: workspaceLayout.root, entryPath: "staging" });
    await mkdir(workspaceLayout.staging, { recursive: true, mode: 0o700 });
    await assertEntryCountWithinCap(archiveReader.entries({ archive }));
    const transactionRoot = await mkdtemp(path.join(workspaceLayout.staging, "install-"));
    const extractionRoot = path.join(transactionRoot, "root");
    await mkdir(extractionRoot, { mode: 0o700 });

    try {
      const executablePaths = await extractEntries(archiveReader.entries({ archive }), extractionRoot);
      const indexed = await indexInstalledRoot(extractionRoot, digest);
      if (optional.previewOnly) return indexed;

      return await persistentState.withIdentityLock({ workspaceRoot: workspaceLayout.root, run: async () => {
        await assertIdentityAvailable(workspaceLayout.root, indexed);
        const publishWithinPluginLock = () => persistentState.withPluginLock({ workspaceRoot: workspaceLayout.root, pluginId: indexed.pluginId, run: async () => {
          // Every install and replacement, not only an update, is a mutation of this plugin: an
          // unfinished update journal refuses it here, under the same plugin lock, because boot
          // recovery removes only the journal's own candidate digest and would otherwise restore the
          // old revision beside whatever this install published.
          // The journal lives under the layout this install was given, the one it publishes into.
          await settleAgentPluginUpdateJournal({ store: createAgentPluginUpdateStore({ ports: { ...ports, layout }, workspaceId, pluginId: indexed.pluginId }) });
          // Layout B needs the manifest id before choosing the package destination. Dedup still
          // skips publication and freezing, after one bounded staging extraction.
          // Owner decision 2026-10-04: learned facts begin empty for each site; author guidance stays
          // in package docs. Package extension files never seed learned memory or the user's notes.
          // Content-addressed dedup, scoped to THIS workspace's own tree (`workspaceLayout` was just
          // resolved above, atomically, from this same `workspaceId`): identical bytes were already
          // extracted, verified, and frozen by a prior install of this same workspace's — never
          // re-extracted for a different workspace, by construction, since a different workspace's
          // `workspaceLayout.packages` is a different path entirely. one bounded staging extraction precedes this check.
          // Publish BEFORE freezing permissions, not after: `rename()` moves `extractionRoot` as a single
          // directory-entry operation, and on this filesystem renaming an already-read-only (0o555)
          // directory itself fails EACCES (observed, not merely theoretical — see the regression test this
          // ordering fixed). Freezing after publish also closes a smaller race for free: nothing outside
          // this function can observe the package at its live path while it is still writable, because the
          // live path does not exist until `publish` returns.
          let publishedPlugin: InstalledAgentPlugin | undefined;
          const publishPackage = async (): Promise<InstalledAgentPlugin> => {
            // The manifest identifies the plugin only after bounded staging extraction (Layout B).
            const pluginId = indexed.pluginId;
            const packagesDir = workspaceLayout.pluginPackagesDir({ pluginId });
            await persistentState.assertOwnedPath({ workspaceRoot: workspaceLayout.root, entryPath: path.relative(workspaceLayout.root, packagesDir) });
            await mkdir(packagesDir, { recursive: true, mode: 0o700 });
            const finalRoot = await assertContainedOnDisk(packagesDir, digest);
            for (const directory of [workspaceLayout.pluginDataDir({ pluginId }),
              workspaceLayout.pluginMemoryDir({ pluginId, kind: 'learned' }),
              workspaceLayout.pluginMemoryDir({ pluginId, kind: 'notes' })]) {
              await persistentState.assertOwnedPath({ workspaceRoot: workspaceLayout.root, entryPath: path.relative(workspaceLayout.root, directory) });
              await mkdir(directory, { recursive: true, mode: 0o700 });
            }
            if (await isRealDirectory(finalRoot)) {
              publishedPlugin = await indexInstalledRoot(finalRoot, digest);
              return publishedPlugin;
            }
            await publish(extractionRoot, finalRoot);
            await freezeTree(finalRoot, executablePaths);
            /** Absolute, read-only (frozen) path to the extracted package root. */
            publishedPlugin = { ...indexed, packageRoot: finalRoot };
            return publishedPlugin;
          };
          const installed = await (optional.publishGuard ? optional.publishGuard({ plugin: indexed, publish: publishPackage }, {}) : publishPackage());
          if (publishedPlugin) await pruneSupersededRevisions({ workspaceRoot: workspaceLayout.root, installed: publishedPlugin });
          return installed;
        } });
        if (ports.identityAdmission) return ports.identityAdmission({ id: indexed.id!, localId: indexed.pluginId, run: publishWithinPluginLock }, {});
        return publishWithinPluginLock();
      } });
    } finally {

      await rm(transactionRoot, { recursive: true, force: true });
    }
  }

  /** The `(target '...')` suffix on the symlink-rejection message, or nothing when the entry carries
 * no `linkTarget` at all — split out purely to keep that `&&`/ternary pair out of
 * {@link extractOneEntry}'s own branch count. */
  function symlinkRejectionMessage(entry: AgentPluginArchiveEntry): string {
    const targetSuffix = "linkTarget" in entry && entry.linkTarget ? ` (target '${entry.linkTarget}')` : "";
    return `archive entry '${entry.entryPath}' has kind '${entry.kind}', which Agent Plugin packages are not permitted to contain${targetSuffix}`;
  }

  /** `normalizePackageEntryPath()`, with its thrown error re-shaped into the module's own
 * `AgentPluginInstallError` vocabulary. */
  function normalizeEntryPathOrThrow(entryPath: string): string {
    try {
      return normalizePackageEntryPath(entryPath);
    } catch (error) {
      throw new AgentPluginInstallError({ code: "UNSAFE_ENTRY_PATH", message: `archive entry path is unsafe: '${entryPath}'` }, { cause: error });
    }
  }

  /** `assertContainedOnDisk()`, with its thrown error re-shaped the same way. */
  async function resolveContainedDestinationOrThrow(extractionRoot: string, normalized: string): Promise<string> {
    try {
      return await assertContainedOnDisk(extractionRoot, normalized);
    } catch (error) {
      throw new AgentPluginInstallError({ code: "UNSAFE_ENTRY_PATH", message: `archive entry resolves outside the package root: '${normalized}'` }, {
        cause: error instanceof PackagePathViolation ? error : undefined,
      });
    }
  }

  /**
 * Applies every hardening rule in this module's header to one archive entry: symlink rejection,
 * path normalization, duplicate detection, containment, the per-file size cap, and (for a file
 * entry) the actual write. Returns the running total-extracted-bytes count, since that is the one
 * piece of `extractEntries`'s loop state a single entry's processing can change.
 */
// Refused BEFORE path normalization: a symlink entry is never acceptable regardless of how
// "safe" its own name looks, matching the ecosystem fix this module's header cites — validating
// where a permitted symlink might point is more attack surface than refusing the entry kind.
  async function extractOneEntry(args: {
    entry: AgentPluginArchiveEntry;
    extractionRoot: string;
    seen: Set<string>;
    executablePaths: Set<string>;
    totalBytesSoFar: number;
  }): Promise<number> {
    const { entry, extractionRoot, seen, executablePaths, totalBytesSoFar } = args;

    if (entry.kind !== "file" && entry.kind !== "directory") {
      throw new AgentPluginInstallError({ code: "SYMLINK_ENTRY_REJECTED", message: symlinkRejectionMessage(entry) });
    }

    const normalized = normalizeEntryPathOrThrow(entry.entryPath);

    if (seen.has(normalized)) {
      throw new AgentPluginInstallError({ code: "DUPLICATE_ENTRY", message: `duplicate archive entry '${normalized}' — refusing a second write over an already-vetted first one` });
    }
    seen.add(normalized);

    const destination = await resolveContainedDestinationOrThrow(extractionRoot, normalized);

    if (entry.kind === "directory") {
      await mkdir(destination, { recursive: true, mode: 0o700 });
      return totalBytesSoFar;
    }

    if ((entry.declaredSize ?? 0) > LIMITS.maxFileBytes) {
      throw new AgentPluginInstallError({ code: "FILE_TOO_LARGE", message: `archive file '${normalized}' declares ${entry.declaredSize} bytes, over the ${LIMITS.maxFileBytes}-byte cap` });
    }

    await mkdir(path.dirname(destination), { recursive: true, mode: 0o700 });
    const totalBytes = await writeContainedFile({
      destination,
      normalized,
      stream: entry.openReadStream({}),
      totalBytesSoFar,
    });

    if (entry.executable) executablePaths.add(normalized);
    return totalBytes;
  }

  /**
   * Refuses a "million small files" archive from entry metadata alone, before a staging
   * transaction exists. Checking only inside the extraction loop meant an over-cap archive first
   * had the cap's worth of files contained, written and then deleted again. Every reader derives
   * its entries from the archive bytes, so a second iteration costs one central-directory walk
   * and opens no content stream.
   */
  /** Ported from Jini 78d4b60b: reject from metadata before a staging transaction exists.
 * A second central-directory walk opens no content streams and avoids over-cap disk churn. */
  async function assertEntryCountWithinCap(entries: AsyncIterable<AgentPluginArchiveEntry>): Promise<void> {
    // Only the count matters, so the entries are stepped through without being bound to a name.
    // Leaving early closes the walk the way for-await would, without letting a failing close
    // replace the cap error.
    const iterator = entries[Symbol.asyncIterator]();
    let entryCount = 0;
    for (let next = await iterator.next(); !next.done; next = await iterator.next()) {
      entryCount += 1;
      if (entryCount > LIMITS.maxEntries) {
        await Promise.resolve(iterator.return?.()).catch(() => undefined);
        throw tooManyEntriesError();
      }
    }
  }

  function tooManyEntriesError(): AgentPluginInstallError {
    return new AgentPluginInstallError({ code: "TOO_MANY_ENTRIES", message: `archive exceeds the ${LIMITS.maxEntries}-entry cap` });
  }

  /** Extracts every entry into `extractionRoot`, enforcing every hardening rule in this module's
 * header. Returns the set of archive-relative paths the archive marked executable, for
 * {@link freezeTree} to preserve the `+x` bit on. */
  async function extractEntries(
    entries: AsyncIterable<AgentPluginArchiveEntry>,
    extractionRoot: string,
  ): Promise<ReadonlySet<string>> {
    const seen = new Set<string>();
    const executablePaths = new Set<string>();
    let entryCount = 0;
    let totalBytes = 0;

    for await (const entry of entries) {
      entryCount += 1;
      // Still enforced here: the pre-pass trusts the reader to yield the same entries twice.
      if (entryCount > LIMITS.maxEntries) throw tooManyEntriesError();

      totalBytes = await extractOneEntry({ entry, extractionRoot, seen, executablePaths, totalBytesSoFar: totalBytes });
    }

    return executablePaths;
  }

  /** Streams one file entry to disk, bounding both its own size and the running archive total against
 * bytes ACTUALLY observed — never the archive format's declared size, which a decompression bomb
 * lies about by construction. `O_EXCL` refuses to write over anything already at `destination`
 * (there cannot legitimately be one — `extractEntries`'s duplicate check already refused a second
 * entry for the same path); `O_NOFOLLOW` refuses to follow a final-component symlink if the
 * filesystem somehow already had one (defense in depth — this module never creates one itself). */
  async function writeContainedFile(params: {
    destination: string;
    normalized: string;
    stream: AsyncIterable<Uint8Array>;
    totalBytesSoFar: number;
  }): Promise<number> {
    let flags = constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL;
    if (ports.process.platform !== "win32") flags |= constants.O_NOFOLLOW;

    const handle = await open(params.destination, flags, 0o600);
    let fileBytes = 0;
    let totalBytes = params.totalBytesSoFar;

    try {
      for await (const chunk of params.stream) {
        fileBytes += chunk.byteLength;
        totalBytes += chunk.byteLength;

        if (fileBytes > LIMITS.maxFileBytes) {
          throw new AgentPluginInstallError({ code: "DECOMPRESSION_BOMB", message: `archive file '${params.normalized}' exceeded the ${LIMITS.maxFileBytes}-byte cap while decompressing — its declared size was a lie` });
        }
        if (totalBytes > LIMITS.maxTotalExtractedBytes) {
          throw new AgentPluginInstallError({ code: "TOTAL_SIZE_EXCEEDED", message: `archive exceeds the ${LIMITS.maxTotalExtractedBytes}-byte total extracted-size cap` });
        }

        await handle.write(chunk instanceof Buffer ? chunk : Buffer.from(chunk));
      }
    } finally {
      await handle.close();
    }

    return totalBytes;
  }

  /** Makes every file/directory under `root` read-only (executables keep `+x`, per the Agent Plugins
 * spec's own MCP `command` needing to launch a `./`-relative script — not exercised by anything in
 * this slice, since MCP execution is out of scope for v1, but the bit is preserved now rather than
 * silently dropped for whenever it is).
 *
 * Stated plainly rather than implied (`mcp-federation/trust.ts`'s own "what this tier deliberately
 * does NOT claim" discipline): this is best-effort defense against an ACCIDENTAL same-process write
 * into what is supposed to be a read-only `PLUGIN_ROOT`, not a security boundary against a
 * determined attacker already running code as this same OS user — that user can `chmod` again. */
  async function freezeTree(root: string, executables: ReadonlySet<string>, prefix = ""): Promise<void> {
    for (const entry of await readdir(root, { withFileTypes: true })) {
      const relative = prefix ? `${prefix}/${entry.name}` : entry.name;
      const absolute = path.join(root, entry.name);

      if (entry.isDirectory()) {
        await freezeTree(absolute, executables, relative);
        await chmod(absolute, 0o555);
      } else {
        await chmod(absolute, executables.has(relative) ? 0o555 : 0o444);
      }
    }
    await chmod(root, 0o555);
  }

  /** Publishes `extractionRoot` to `finalRoot` by rename — atomic on the same filesystem, so a reader
   * can never observe a partially-extracted package at the live path. Tolerates losing a race against
   * a concurrent install of the byte-identical digest (the same content, published a moment earlier by
   * another process) rather than treating that as a failure. */
  // macOS reports EACCES, rather than ENOTEMPTY, when the winning install has already
  // frozen its destination directory. Still require a real directory below: a permission
  // failure with no published winner must remain PUBLISH_FAILED.
  async function publish(extractionRoot: string, finalRoot: string): Promise<void> {
    try {
      await rename(extractionRoot, finalRoot);
    } catch (error) {

      if (!isErrnoException(error) || (error.code !== "EEXIST" && error.code !== "ENOTEMPTY" && error.code !== "EACCES")) {
        throw new AgentPluginInstallError({ code: "PUBLISH_FAILED", message: `failed to publish the extracted package to '${finalRoot}'` }, { cause: error });
      }
      if (!(await isRealDirectory(finalRoot))) {
        throw new AgentPluginInstallError({ code: "PUBLISH_FAILED", message: `'${finalRoot}' exists but is not a real, published package directory` }, { cause: error });
      }
      // Lost the race to a concurrent install of identical bytes — the bytes at `finalRoot` are the
      // ones this install itself would have written, so this is not a failure.
    }
  }

  async function isRealDirectory(target: string): Promise<boolean> {
    try {
      const info = await stat(target);
      return info.isDirectory();
    } catch (error) {
      if (isErrnoException(error) && error.code === "ENOENT") return false;
      throw error;
    }
  }

  function sha256(value: Uint8Array): string {
    return createHash("sha256").update(value).digest("hex");
  }

  function isErrnoException(error: unknown): error is NodeJS.ErrnoException {
    return typeof error === "object" && error !== null && "code" in error;
  }

  return { maxAgentPluginInstallArchiveBytes, installAgentPlugin, indexInstalledRoot };
}

const instances = new WeakMap<AgentPluginLifecyclePorts, ReturnType<typeof buildModule>>();
/** Internal composition; one state/queue instance per injected host context. */
export function createInstallModule(ports: AgentPluginLifecyclePorts) {
  let instance = instances.get(ports);
  if (!instance) { instance = buildModule(ports); instances.set(ports, instance); }
  return instance;
}

/**
 * @file `parseAgentPluginManifest()` / `parseAgentPluginMcpConfig()` — the Agent Plugins 1.0.0/1.1.0
 * `plugin.json` / `mcp.json` grammar (agent-plugins.org/specification), verified against the live
 * spec rather than inferred from an example manifest.
 *
 * Deliberately a SEPARATE, smaller validator from `src/features/plugin-runtime/manifest.ts`'s
 * `validateManifest()`. That file validates `.host-plugin`'s own tarball format — `integrity`
 * (per-file SHA-256), `sdkRange`, `tier`, an exactly-three-token capability vocabulary, a single
 * `content.entry.beforeSave` hook. This file validates the OPEN standard's `plugin.json`, which
 * shares none of those fields and defines no execution/trust/capability model at all — see this
 * feature's own header comment in `install.ts` for why the two formats cannot be unified.
 *
 * Pinned 1.0.0/1.1.0 rules from agent-plugins.org/specification:
 * - `plugin.json`'s `name`: 1-64 chars, lowercase alphanumeric/hyphen/period only, must start and
 *   end alphanumeric, no `--` or `..` consecutive delimiters (§5.5). Valid: `my-plugin`,
 *   `acme.tools`, `lint3r`, `a`. Invalid: `My-Plugin`, `-start`, `has--double`.
 * - `plugin.json`'s `$schema` MUST be a recognized canonical identifier
 *   (`https://agent-plugins.org/schemas/<version>/plugin.schema.json`); `mcp.json`'s likewise
 *   (`.../<version>/mcp.schema.json`), and when both are present their versions MUST match (§10).
 *   1.0.0 and 1.1.0 are recognized; an unknown 1.x is read with the newest known grammar plus one
 *   warning; any other major is refused — see `KNOWN_SPEC_VERSIONS`.
 * - Unknown top-level `plugin.json` fields produce warnings but do not block loading — this module
 *   returns them as `warnings`, never as a rejection reason.
 * - `mcp.json`'s top-level shape is `{ "$schema": ..., "mcpServers": { "<server-id>": {...} } }` —
 *   `mcpServers` MUST be an object whose member names identify servers.
 * - Each server entry MUST carry a `type` discriminator matching one of three CLOSED variants.
 *   Launching requires the actual transport config, not just a server id:
 *     - `stdio`: requires `command` (non-empty string); optional `args` (string[]), `env`
 *       (string-valued object — MUST NOT set `PLUGIN_ROOT`/`PLUGIN_DATA`, which the spec reserves),
 *       `cwd` (plugin-relative path).
 *     - `streamable-http` / `sse`: requires `url` (non-empty string); optional `headers`
 *       (string-valued object).
 * - **The spec defines NO auth-related field on a server entry at all.** Verbatim from
 *   `/specification`: "Agent Plugins v1 defines no OAuth configuration or portable
 *   credential-reference fields. Authorization discovery, user interaction, and credential storage
 *   are client-managed." A plugin therefore cannot declare "this server needs OAuth" using any
 *   spec-defined field — the host is the client the spec defers that decision to. This module accepts
 *   the host-specific metadata in `plugin.json`'s `extensions.<host-namespace>.mcpServers[serverId]`, keeping
 *   `mcp.json` transport entries closed per §7.2.1. Hosts may translate legacy auth and sign-in defaults in MCP
 *   entries through readServerMetadata for existing packages, but those cannot supply operator read trust.
 *   `authMode: "oauth" | "none"` selects client auth; absent defaults to "none".
 *   `defaultTools: { allow?, write?, read? }` names sign-in grants and reviewed read tools.
 *   `write` requires `allow` and must be its subset; `read` must be a subset when `allow` is
 *   present. A read-only declaration without `allow` leaves sign-in grants unchanged.
 *   Remote hints may veto a read declaration but never supply it. A third,
 *   `tokenAuth: { helpUrl, probeUrl }`, offers a pasted access token as the sign-in fallback
 *   (`access-token-tool.ts`). A fourth, `renamedTools: { oldName: newName }`, carries saved tool
 *   selections across a vendor's tool rename (`apply-tool-renames.ts`). A malformed per-server entry
 *   (wrong/missing `type`, missing required field) does not fail the whole file — see
 *   `ParseAgentPluginMcpConfigResult`'s own doc for the fail-open contract this preserves.
 *
 * Architectural role:
 * Pure, no-I/O parsing over an already-`JSON.parse`d value — mirrors `plugin-runtime/manifest.ts`'s
 * own "receives a JS value, never a file path or raw bytes" contract. `install.ts` is the only
 * caller that reads the file and hands the parsed value here.
 */
import { readAgentPluginCompatibilityMetadata } from "./compatibility-metadata.js";
import { parseAgentPluginExports, type AgentPluginExportMetadata } from './exports.js';
export * from './exports.js';
import { readPluginIdentity, validatePluginIdentity } from "@jini-ai/core/plugin-directory";
export { validatePluginManifest, validateMcpManifest } from '../manifest.js';
export type { PluginManifest, McpManifest, McpServerEntry } from '../manifest.js';
import type { PluginManifestAuthor } from '../manifest.js';
export type { PluginManifestAuthor } from '../manifest.js';
/** Agent Plugins 1.0.0/1.1.0 parsing, with application metadata confined to an explicit namespace. */
export type AgentPluginServerMetadataReader = (required: { readonly serverId: string; readonly value: Readonly<Record<string, unknown>>; readonly server: Readonly<Record<string, unknown>> }) => Readonly<Record<string, unknown>>;

/**
 * The Agent Plugins versions whose schemas have been diffed against this file's grammar. 1.1.0's
 * spec text and both schemas differ from 1.0.0 only in the version identifiers, so both map to the
 * one grammar below — §5.1 allows mapping explicitly recognized compatible versions to one
 * implementation. Add a version here only after diffing its schemas against this grammar.
 */
const KNOWN_SPEC_VERSIONS = ["1.0.0", "1.1.0"] as const;
const SUPPORTED_MAJOR = "1";

/**
 * Owner decision (2026-10-12): any other 1.x is accepted with the newest known grammar and one
 * warning, so a minor spec release does not lock out packages that target it. This goes beyond
 * §5.1, which says a client MUST reject a version it does not explicitly recognize. Unknown fields
 * stay tolerated only where the known grammar already allows them (unknown top-level fields warn,
 * `extensions` is opaque). A different major is refused, since majors may break the grammar.
 */
const SCHEMA_URL_PATTERN = /^https:\/\/agent-plugins\.org\/schemas\/((\d+)\.\d+\.\d+)\/(plugin|mcp)\.schema\.json$/;

/** The canonical `$schema` identifier for one spec version's `plugin.json` or `mcp.json`. */
function schemaUrl(version: string, file: "plugin" | "mcp"): string {
  return `https://agent-plugins.org/schemas/${version}/${file}.schema.json`;
}

type SpecVersion =
  | { readonly version: string; readonly warning?: string; readonly error?: undefined }
  | { readonly version?: undefined; readonly warning?: undefined; readonly error: string };

/**
 * Reads the spec version `value` names as `file`'s canonical schema identifier: a known version,
 * an unknown 1.x (with its warning), or the error for a different major or a non-canonical value.
 */
function readSpecVersion(value: unknown, file: "plugin" | "mcp"): SpecVersion {
  const match = typeof value === "string" ? SCHEMA_URL_PATTERN.exec(value) : null;
  if (!match || match[3] !== file) {
    const accepted = KNOWN_SPEC_VERSIONS.map((version) => `'${schemaUrl(version, file)}'`).join(" or ");
    return { error: `${file}.json '$schema' must be ${accepted} (Agent Plugins ${KNOWN_SPEC_VERSIONS.join(", ")}, or another ${SUPPORTED_MAJOR}.x), got '${String(value)}'` };
  }
  const version = match[1]!;
  if (match[2] !== SUPPORTED_MAJOR) {
    return { error: `${file}.json targets Agent Plugins ${version}, an unsupported major version (supported: ${SUPPORTED_MAJOR}.x)` };
  }
  if ((KNOWN_SPEC_VERSIONS as readonly string[]).includes(version)) return { version };
  const newest = KNOWN_SPEC_VERSIONS[KNOWN_SPEC_VERSIONS.length - 1];
  return { version, warning: `${file}.json targets Agent Plugins ${version}, newer than this loader knows; validated with the ${newest} grammar` };
}

/**
 * §5.5's grammar as one regex: alnum runs separated by single `-`/`.` delimiters. This shape alone
 * guarantees start/end are alphanumeric (the regex can only start and end on `[a-z0-9]+`) AND that
 * no two delimiters are ever adjacent (a delimiter is always followed by at least one alnum char
 * before the next one can appear) — so "no leading/trailing hyphen" and "no consecutive delimiters"
 * fall out of one pattern rather than needing separate checks that could disagree.
 */
const NAME_PATTERN = /^[a-z0-9]+(?:[-.][a-z0-9]+)*$/;
const MAX_NAME_LENGTH = 64;

/**
 * True when `value` is a valid Agent Plugin id: `plugin.json`'s `name` grammar (§5.5, see
 * `NAME_PATTERN`), 1-64 characters. The one owner of that grammar: a host checks an id taken from a
 * URL or a tool input here before it names anything on disk, instead of restating the pattern.
 * @complexity O(n) in the value's length.
 */
export function isAgentPluginName({ value }: { readonly value: unknown }, _optional: Record<string, never> = {}): boolean {
  return typeof value === "string" && value.length <= MAX_NAME_LENGTH && NAME_PATTERN.test(value);
}

export interface AgentPluginManifest extends AgentPluginExportMetadata {
  readonly name: string;
  readonly version?: (string) | undefined;
  readonly description?: (string) | undefined;
  readonly author?: string | PluginManifestAuthor | undefined;
  readonly license?: (string) | undefined;
  readonly keywords?: (readonly string[]) | undefined;
  readonly extensions?: (Readonly<Record<string, unknown>>) | undefined;
  /** Normalized publisher identity, independent of name/storage key and version. */
  readonly id?: string | undefined;
  readonly provides?: readonly string[] | undefined;
  /** `extensions.<ns>.requires`: advisory capability ids other active plugins should provide. */
  readonly requires?: readonly string[] | undefined;
  /** `extensions.<ns>.hostRange`: semver range over AGENT_PLUGIN_CONTRACT_VERSION; a malformed value is stored as `<invalid>`. */
  readonly hostRange?: string | undefined;
}

export type ParseAgentPluginManifestResult =
  | { readonly ok: true; readonly manifest: AgentPluginManifest; readonly warnings: readonly string[] }
  | { readonly ok: false; readonly errors: readonly string[] };

const KNOWN_MANIFEST_KEYS = new Set(["$schema", "name", "version", "description", "author", "license", "keywords", "extensions"]);

/**
 * True for a non-null, non-array plain object — the "is this actually a JSON object" gate both
 * `parseAgentPluginManifest` and `parseAgentPluginMcpConfig` need before touching any field.
 */
function isJsonObject(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * `undefined` for an absent optional field, otherwise whatever `parse` makes of it — `null` meaning
 * present but malformed, which every caller folds into rejecting the whole entry.
 */
function parseOptional<T>({ value, parse }: { readonly value: unknown; readonly parse: (value: unknown) => T | null }): T | undefined | null {
  return value === undefined ? undefined : parse(value);
}

/** Drops `undefined` members, so an absent optional field stays absent rather than present-as-undefined. */
function definedFields<T extends Record<string, unknown>>(fields: T): { [K in keyof T]?: Exclude<T[K], undefined> } {
  return Object.fromEntries(Object.entries(fields).filter(([, value]) => value !== undefined)) as { [K in keyof T]?: Exclude<T[K], undefined> };
}

/**
 * `value` narrowed to a `string`, or `undefined` — every optional string field below coerces
 * through this one check instead of repeating its own `typeof ... === "string" ? ... : undefined`
 * ternary.
 */
function coerceOptionalString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function parseManifestAuthor(value: unknown): string | PluginManifestAuthor | undefined {
  if (typeof value === 'string') return value; // Existing installed manifests may carry a string.
  if (!isJsonObject(value)) return undefined;
  return definedFields({ name: coerceOptionalString(value.name), email: coerceOptionalString(value.email), url: coerceOptionalString(value.url) });
}

/**
 * Validates `plugin.json`'s `name` field per §5.5's grammar (see `NAME_PATTERN`'s own header for
 * what the one regex encodes). Returns the valid name, or the one error message to report — never
 * both, so the caller needs exactly one branch to consume this instead of the original's
 * required-then-format else-if chain.
 */
function resolveManifestName(raw: Readonly<Record<string, unknown>>): { name: string; error?: undefined } | { name?: undefined; error: string } {
  const name = coerceOptionalString(raw.name);
  if (name === undefined) return { error: "plugin.json 'name' is required and must be a string" };
  if (!isAgentPluginName({ value: name })) {
    return {
      error: `plugin.json 'name' ('${name}') must be 1-${MAX_NAME_LENGTH} lowercase alphanumeric/hyphen/period characters, start and end alphanumeric, with no consecutive delimiters`,
    };
  }
  return { name };
}

/** Every `plugin.json` error and warning, in report order: spec version, extensions, name, unknown keys, identity. */
function collectManifestProblems(
  { raw, identityNamespace }: { readonly raw: Readonly<Record<string, unknown>>; readonly identityNamespace: string },
  { nameError }: { readonly nameError?: string | undefined } = {},
): { errors: string[]; warnings: string[] } {
  const errors: string[] = [];
  const warnings: string[] = [];

  const specVersion = readSpecVersion(raw.$schema, "plugin");
  if (specVersion.error) errors.push(specVersion.error);
  // A version error already explains the schema; its warning would only repeat it.
  if (!specVersion.error && specVersion.warning) warnings.push(specVersion.warning);

  if (raw.extensions !== undefined && !isJsonObject(raw.extensions)) errors.push("plugin.json extensions must be an object");
  if (nameError) errors.push(nameError);

  for (const key of Object.keys(raw)) {
    if (!KNOWN_MANIFEST_KEYS.has(key)) warnings.push(`unrecognized plugin.json field '${key}' (ignored per spec)`);
  }

  errors.push(...validatePluginIdentity({ manifest: raw, namespace: identityNamespace }).errors);
  return { errors, warnings };
}

/**
 * Validates an already-`JSON.parse`d `plugin.json` value against the 1.0.0/1.1.0 grammar.
 * Hosts inject identityNamespace; the default retains the existing plugin extension format.
 *
 * @throws Nothing — every failure is reported via the returned `errors`, matching this codebase's
 * own convention for expected validation outcomes (`plugin-runtime/manifest.ts`,
 * `plugin-runtime/discovery.ts`).
 * @complexity O(k + n) time and space in the input keys and keyword entries.
 */
export function parseAgentPluginManifest({ value }: { readonly value: unknown }, { identityNamespace = "tovu" }: { readonly identityNamespace?: string } = {}): ParseAgentPluginManifestResult {
  if (!isJsonObject(value)) return { ok: false, errors: ["plugin.json must be a JSON object"] };

  const raw = value;
  const nameResult = resolveManifestName(raw);
  const { errors, warnings } = collectManifestProblems({ raw, identityNamespace }, { nameError: nameResult.error });
  if (errors.length > 0) return { ok: false, errors };
  const identity = readPluginIdentity({ manifest: raw, namespace: identityNamespace });
  warnings.push(...identity.warnings);
  const extension = isJsonObject(raw.extensions) && isJsonObject(raw.extensions[identityNamespace]) ? raw.extensions[identityNamespace] : {};
  const { warnings: compatibilityWarnings, ...compatibility } = readAgentPluginCompatibilityMetadata({ extension });
  warnings.push(...compatibilityWarnings);
  const exportsResult = parseAgentPluginExports({ extension, provides: identity.provides });
  if (!exportsResult.ok) return { ok: false, errors: exportsResult.errors };
  warnings.push(...exportsResult.warnings);

  const manifest: AgentPluginManifest = {
    ...compatibility,
    ...exportsResult.metadata,
    name: nameResult.name as string,
    id: identity.id,
    provides: identity.provides,
    version: coerceOptionalString(raw.version),
    description: coerceOptionalString(raw.description),
    author: parseManifestAuthor(raw.author),
    license: coerceOptionalString(raw.license),
    keywords: raw.keywords === undefined ? undefined : identity.keywords,
    ...(isJsonObject(raw.extensions) ? { extensions: raw.extensions } : {}),
  };
  return { ok: true, manifest, warnings };
}

/**
 * The three closed transport variants `mcp.schema.json` 1.0.0/1.1.0 defines. See this file's header for
 * the verified field shape of each.
 */
export const MCP_SERVER_TRANSPORTS = ["stdio", "streamable-http", "sse"] as const;
export type McpServerTransport = (typeof MCP_SERVER_TRANSPORTS)[number];

/**
 * Reserved by the spec — a `stdio` server's `env` MUST NOT set either, since the client (the host)
 * owns them. Checked defensively; nothing upstream of this parser fills them in yet, so this is a
 * spec-conformance check today rather than one guarding a real collision.
 */
const RESERVED_STDIO_ENV_KEYS = ["PLUGIN_ROOT", "PLUGIN_DATA"];

export interface StdioMcpServerConfig {
  readonly type: "stdio";
  readonly command: string;
  readonly args?: (readonly string[]) | undefined;
  readonly env?: (Readonly<Record<string, string>>) | undefined;
  readonly cwd?: (string) | undefined;
}

export interface AgentPluginServerMetadata {
  readonly authMode?: ('oauth' | 'none') | undefined;
  readonly defaultTools?: (AgentPluginDefaultTools) | undefined;
  readonly tokenAuth?: (AgentPluginTokenAuth) | undefined;
  readonly renamedTools?: (Readonly<Record<string, string>>) | undefined;
}
/**
 * `streamable-http` and `sse` share an identical field shape (`url` + optional `headers`); only
 * their `type` differs, and both are handled by the one remote branch below.
 */
export interface RemoteMcpServerConfig extends AgentPluginServerMetadata {
  readonly type: 'streamable-http' | 'sse';
  readonly url: string;
  readonly headers?: (Readonly<Record<string, string>>) | undefined;
}

/**
 * the host-specific extension, not part of the spec — see this file's header for why it exists and
 * what a strictly spec-conformant client does with it (ignores it).
 *
 * the host-specific extension, not part of the spec: the tools this server's row is granted on the
 *  operator's FIRST successful sign-in (`apply-connect-defaults.ts`), so connecting is the only step.
 *  `write` is a subset of `allow`, the same rule the external-MCP store enforces on a save.
 *
 * the host-specific extension, not part of the spec: this server also takes a pasted access token, sent
 *  as `Authorization: Bearer` — the fallback when its sign-in cannot start (`access-token-tool.ts`).
 *
 * the host-specific extension, not part of the spec: `{ oldName: newName }` for tools the vendor
 *  renamed. A row this plugin provisioned has each old name in its saved lists replaced by the new
 *  one at boot (`apply-tool-renames.ts`), so a rename never strands an operator's selection.
 *
 * Where a human makes the token (`helpUrl`, linked from the form) and the URL a pasted token is
 *  checked against before it is saved (`probeUrl`: one GET, 401/403 means the token was rejected).
 *  Both https.
 *
 *  `importFromEnv` names an env var whose token is copied onto this server's row at boot when the row
 *  has no credential yet (`import-access-token.ts`); `retiredEnv` names old env vars that are no
 *  longer read, so boot can say so once. Both let a plugin take over an old env-configured
 *  integration without core naming the vendor.
 */
export interface AgentPluginTokenAuth {
  readonly helpUrl: string;
  readonly probeUrl: string;
  readonly importFromEnv?: (string) | undefined;
  readonly retiredEnv?: (readonly string[]) | undefined;
}

export interface AgentPluginDefaultTools {

  readonly allow?: (readonly string[]) | undefined;
  readonly write: readonly string[];

  readonly read?: (readonly string[]) | undefined;
}

/**
 * Absent means no first-sign-in defaults, rather than an empty grant.
 *
 * Operator-reviewed remote names; absent on older programmatic configs means no read grants.
 */
export type McpServerConfig = StdioMcpServerConfig | RemoteMcpServerConfig;

export interface AgentPluginMcpConfig {

  readonly serverIds: readonly string[];

  readonly servers: Readonly<Record<string, McpServerConfig>>;
}

/**
 * `mcpServers`' own member names, in declaration order — the identity a future admission record
 * pins to (`serverId` in the debate's own admission shape). Includes every declared key
 * regardless of whether that entry's transport shape validated — see {@link servers} for the
 * validated subset — so a discovery caller that only ever needed ids (`search_agent_plugin_local`)
 * sees no behavior change from before this module parsed transports at all.
 *
 * Only the entries whose transport shape validated against one of the three closed variants.
 * A `serverId` present in {@link serverIds} but absent here declared an unrecognized `type` or was
 * missing a required field for the `type` it declared — fail-open per this file's header, not an
 * error for the whole `mcp.json`.
 */
export type ParseAgentPluginMcpConfigResult =
  | { readonly ok: true; readonly config: AgentPluginMcpConfig }
  | { readonly ok: false; readonly errors: readonly string[] };

/**
 * `value` narrowed to an object whose own values are all strings, or `undefined` for anything
 *  else — the shared shape `env`/`headers` both need.
 */
function isStringRecord(value: unknown): value is Readonly<Record<string, string>> {
  return isJsonObject(value) && Object.values(value).every((entry) => typeof entry === "string");
}

/**
 * Validates one `type: "stdio"` server entry.
 *
 * @returns The parsed config, or `null` for any shape violation (missing/empty `command`, a
 * malformed `args`/`env`/`cwd`, or an `env` setting a reserved key) — the caller folds `null` into
 * "this one server is excluded from `servers`", never into a whole-file rejection.
 * @complexity O(k) in the entry's own field count.
 */
function parseStdioServerConfig(raw: Readonly<Record<string, unknown>>): StdioMcpServerConfig | null {
  if (typeof raw.command !== "string" || raw.command.length === 0) return null;

  const args = parseOptional({ value: raw.args, parse: (value) => Array.isArray(value) && value.every((entry): entry is string => typeof entry === "string") ? value : null });
  const env = parseOptional({ value: raw.env, parse: (value) => isStringRecord(value) && !RESERVED_STDIO_ENV_KEYS.some((key) => Object.hasOwn(value, key)) ? value : null });
  const cwd = parseOptional({ value: raw.cwd, parse: (value) => typeof value === "string" ? value : null });
  if (args === null || env === null || cwd === null) return null;

  return { type: "stdio", command: raw.command, ...definedFields({ args, env, cwd }) };
}

/**
 * Same bound and grammar as `external-mcp-store.ts`'s `MAX_ALLOWED_TOOLS`/`REMOTE_TOOL_NAME_PATTERN`,
 *  so a declared default can never be one the store would refuse on save.
 */
const MAX_DEFAULT_TOOLS = 64;
const DEFAULT_TOOL_NAME_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,63}$/;

/**
 * A bounded array of valid tool names, or `null`.
 */
function parseDefaultToolNames(value: unknown): readonly string[] | null {
  if (!Array.isArray(value) || value.length > MAX_DEFAULT_TOOLS) return null;
  return value.every((name): name is string => typeof name === "string" && DEFAULT_TOOL_NAME_PATTERN.test(name)) ? value : null;
}

/** `read` and `write` default to `[]` when absent. */
function parseGrantList(value: unknown): readonly string[] | null {
  return value === undefined ? [] : parseDefaultToolNames(value);
}

/**
 * Validates bounded sign-in and read lists. `read` and `write` default to `[]`.
 * A provided `allow` bounds both lists; without it only a read declaration is meaningful,
 * and sign-in defaults stay absent. Any malformed list excludes the entire server.
 *
 * @returns Parsed defaults, or `null` for a malformed declaration.
 * @complexity O(n) time and space in the lists' total length (each capped at 64).
 */
function parseDefaultTools(value: unknown): AgentPluginDefaultTools | null {
  if (!isJsonObject(value)) return null;
  const allow = parseOptional({ value: value.allow, parse: parseDefaultToolNames });
  const write = parseGrantList(value.write);
  const read = parseGrantList(value.read);
  if (allow === null || write === null || read === null) return null;
  if (allow === undefined) return value.read !== undefined && write.length === 0 ? { write, read } : null;
  const allowed = new Set(allow);
  return [...write, ...read].every((name) => allowed.has(name)) ? { allow, write, read } : null;
}

const MAX_TOKEN_AUTH_URL_LENGTH = 2048;

function isHttpsUrl(value: unknown): value is string {
  if (typeof value !== "string" || value.length > MAX_TOKEN_AUTH_URL_LENGTH) return false;
  try {
    return new URL(value).protocol === "https:";
  } catch {
    return false;
  }
}

/**
 * An env var name a manifest may point at: upper-case, digits and `_`.
 */
const ENV_VAR_NAME_PATTERN = /^[A-Z][A-Z0-9_]{0,127}$/;
const MAX_RETIRED_ENV = 32;

function isEnvVarName(value: unknown): value is string {
  return typeof value === "string" && ENV_VAR_NAME_PATTERN.test(value);
}

function parseRetiredEnv(value: unknown): readonly string[] | null {
  return Array.isArray(value) && value.length <= MAX_RETIRED_ENV && value.every(isEnvVarName) ? value : null;
}

/**
 * Validates a remote entry's `renamedTools` extension: at most {@link MAX_DEFAULT_TOOLS} entries,
 * every key and value a valid tool name, no name renamed to itself, and no new name that is itself
 * renamed again (so one pass is the whole rewrite).
 *
 * @returns The parsed map, or `null` for any shape violation — the caller excludes the whole server.
 * @complexity O(n) in the entry count.
 */
function parseRenamedTools(value: unknown): Readonly<Record<string, string>> | null {
  if (!isStringRecord(value)) return null;
  const entries = Object.entries(value);
  if (entries.length > MAX_DEFAULT_TOOLS) return null;
  const valid = entries.every(
    ([from, to]) => DEFAULT_TOOL_NAME_PATTERN.test(from) && DEFAULT_TOOL_NAME_PATTERN.test(to) && from !== to && !Object.hasOwn(value, to),
  );
  return valid ? value : null;
}

/**
 * Validates a remote entry's `tokenAuth` extension, or `null` for any shape violation — the
 *  caller excludes the whole server, same as a malformed `defaultTools`.
 */
function parseTokenAuth(value: unknown): AgentPluginTokenAuth | null {
  if (!isJsonObject(value) || !isHttpsUrl(value.helpUrl) || !isHttpsUrl(value.probeUrl)) return null;
  const importFromEnv = parseOptional({ value: value.importFromEnv, parse: (name) => isEnvVarName(name) ? name : null });
  const retiredEnv = parseOptional({ value: value.retiredEnv, parse: parseRetiredEnv });
  if (importFromEnv === null || retiredEnv === null) return null;
  return { helpUrl: value.helpUrl, probeUrl: value.probeUrl, ...definedFields({ importFromEnv, retiredEnv }) };
}

/**
 * Validates one `type: "streamable-http"` or `type: "sse"` server entry — the two remote transports
 * share this one implementation because they share every field (see {@link RemoteMcpServerConfig}).
 *
 * @returns The parsed config, or `null` for any shape violation. Same fold-into-exclusion contract
 * as {@link parseStdioServerConfig}.
 * @complexity O(k) in the entry's own field count.
 *
 * Read trust is accepted only from the plugin extension. Keep legacy sign-in grants.
 */
function parseRemoteServerConfig(type: "streamable-http" | "sse", raw: Readonly<Record<string, unknown>>, extension?: Readonly<Record<string, unknown>>): RemoteMcpServerConfig | null {
  if (typeof raw.url !== "string" || raw.url.length === 0) return null;

  const headers = parseOptional({ value: raw.headers, parse: (value) => isStringRecord(value) ? value : null });
  const metadata = parseServerMetadata(extension ?? {});
  if (headers === null || metadata === null) return null;

  return { type, url: raw.url, ...definedFields({ headers }), ...metadata };
}

/** A remote entry's extension metadata, or `null` when any declared member is malformed. */
function parseServerMetadata(extension: Readonly<Record<string, unknown>>): AgentPluginServerMetadata | null {
  const authMode = parseOptional<"oauth" | "none">({ value: extension.authMode, parse: (mode) => mode === "oauth" || mode === "none" ? mode : null });
  const defaultTools = parseOptional({ value: extension.defaultTools, parse: parseDefaultTools });
  const tokenAuth = parseOptional({ value: extension.tokenAuth, parse: parseTokenAuth });
  const renamedTools = parseOptional({ value: extension.renamedTools, parse: parseRenamedTools });
  if (authMode === null || defaultTools === null || tokenAuth === null || renamedTools === null) return null;
  return definedFields({ authMode, defaultTools, tokenAuth, renamedTools });
}

/**
 * Dispatches one `mcpServers` object entry to its transport's validator by `type`, or `null` for a
 *  `type` outside {@link MCP_SERVER_TRANSPORTS}.
 */
function parseMcpServerConfig(value: Readonly<Record<string, unknown>>, extension?: Readonly<Record<string, unknown>>): McpServerConfig | null {
  if (value.type === "stdio") return parseStdioServerConfig(value);
  if (value.type === "streamable-http" || value.type === "sse") return parseRemoteServerConfig(value.type, value, extension);
  return null;
}

/** One declared server, or `null` for a non-object entry, a malformed extension, or an invalid transport shape. */
function parseDeclaredServer(
  { serverId, rawServer, extension }: { readonly serverId: string; readonly rawServer: unknown; readonly extension: unknown },
  { readServerMetadata }: { readonly readServerMetadata?: AgentPluginServerMetadataReader | undefined } = {},
): McpServerConfig | null {
  // A malformed declared extension excludes the server before the translator can hide it.
  if (!isJsonObject(rawServer) || (extension !== undefined && !isJsonObject(extension))) return null;
  const metadata = readServerMetadata?.({ serverId, value: extension ?? {}, server: rawServer }) ?? extension;
  return parseMcpServerConfig(rawServer, metadata);
}

/** `mcp.json`'s top-level errors: its own `$schema`, a version mismatch with `plugin.json` (§10), and `mcpServers`' shape. */
function collectMcpConfigErrors({ raw }: { readonly raw: Readonly<Record<string, unknown>> }, { pluginManifest }: { readonly pluginManifest?: unknown } = {}): string[] {
  const errors: string[] = [];

  // plugin.json already reports an unknown-1.x warning; mcp.json adds none of its own.
  const mcpSpec = readSpecVersion(raw.$schema, "mcp");
  const mcpVersion = mcpSpec.version;
  const pluginVersion = isJsonObject(pluginManifest) ? readSpecVersion(pluginManifest.$schema, "plugin").version : undefined;
  if (mcpSpec.error) errors.push(mcpSpec.error);
  if (!mcpSpec.error && pluginVersion !== undefined && pluginVersion !== mcpVersion) {
    errors.push(`mcp.json targets Agent Plugins ${mcpVersion} but plugin.json targets ${pluginVersion}; the versions must match`);
  }

  if (!isJsonObject(raw.mcpServers)) errors.push("mcp.json 'mcpServers' is required and must be an object");
  return errors;
}

/** The per-server metadata `plugin.json` declares under `extensionNamespace`, or `{}` when it declares none. */
function readExtensionServers({ pluginManifest, extensionNamespace }: { readonly pluginManifest: unknown; readonly extensionNamespace: string }): Readonly<Record<string, unknown>> {
  const manifest = parseAgentPluginManifest({ value: pluginManifest });
  if (!manifest.ok) return {};
  return readAgentPluginExtension({ manifest: manifest.manifest, namespace: extensionNamespace, read: ({ value }) => isJsonObject(value.mcpServers) ? value.mcpServers : {} }) ?? {};
}

/**
 * Validates an already-`JSON.parse`d `mcp.json` value against the 1.0.0/1.1.0 top-level shape:
 * `{ "$schema": ..., "mcpServers": { "<server-id>": {...} } }`, then validates each declared
 * server's own transport shape (see this file's header for the three variants). When
 * `pluginManifest` declares a supported version, `mcp.json` must declare the same one (§10).
 *
 * @throws Nothing — see {@link parseAgentPluginManifest}.
 * @complexity O(s) in the number of declared servers.
 */
export function parseAgentPluginMcpConfig({ value, extensionNamespace }: { readonly value: unknown; readonly extensionNamespace: string }, optional: { readonly pluginManifest?: unknown; readonly readServerMetadata?: AgentPluginServerMetadataReader | undefined } = {}): ParseAgentPluginMcpConfigResult {
  if (!extensionNamespace.trim()) throw new Error("An extension namespace is required");
  if (!isJsonObject(value)) return { ok: false, errors: ["mcp.json must be a JSON object"] };

  const errors = collectMcpConfigErrors({ raw: value }, { pluginManifest: optional.pluginManifest });
  if (errors.length > 0) return { ok: false, errors };

  const extensionServers = readExtensionServers({ pluginManifest: optional.pluginManifest, extensionNamespace });
  const entries = Object.entries(value.mcpServers as Record<string, unknown>);
  const servers: Record<string, McpServerConfig> = Object.create(null);
  for (const [serverId, rawServer] of entries) {
    const extension = Object.hasOwn(extensionServers, serverId) ? extensionServers[serverId] : undefined;
    const parsed = parseDeclaredServer({ serverId, rawServer, extension }, { readServerMetadata: optional.readServerMetadata });
    if (parsed) servers[serverId] = parsed;
  }

  return { ok: true, config: { serverIds: entries.map(([serverId]) => serverId), servers } };
}

/** Typed extension reader: unknown namespaces have no semantics until a host supplies a reader. */
export function readAgentPluginExtension<T>(required: {
  readonly manifest: Pick<AgentPluginManifest, 'extensions'>;
  readonly namespace: string;
  readonly read: (required: { readonly value: Readonly<Record<string, unknown>> }) => T;
}): T | undefined {
  if (!required.namespace.trim()) throw new Error('An extension namespace is required');
  const extensions = required.manifest.extensions;
  if (!extensions || !Object.hasOwn(extensions, required.namespace)) return undefined;
  const value = extensions[required.namespace];
  return isJsonObject(value) ? required.read({ value }) : undefined;
}

import path from 'node:path';
import { createInstallModule, type InstallAgentPluginOptional, type InstallAgentPluginRequired } from './install.js';
import { createUninstallModule } from './uninstall.js';
import { createActivationModule, type AgentPluginActivations } from './activation.js';
import { createResolveAgentPluginRefsModule } from './resolve-agent-plugin-refs.js';
import { createPersistentStateModule } from './persistent-state.js';
import { createInstalledPackageIndex } from './installed-package-index.js';
import { provisionAgentPluginMcp } from './mcp-provisioning.js';
import { planAgentPluginUpdate, type AgentPluginUpdatePlan } from './update-plan.js';
import { AgentPluginHostIncompatibleError, describeAgentPluginCompatibility, agentPluginDependentWarnings } from './compatibility.js';
import { AgentPluginUpdateError, createAgentPluginUpdateStore, isMissing, settleAgentPluginUpdateJournal, type AgentPluginUpdateJournal } from './update-store.js';
import type { AgentPluginLifecyclePorts } from './ports.js';
import type { InstalledAgentPlugin } from './types.js';

export interface UpdateAgentPluginRequired extends InstallAgentPluginRequired {
  readonly pluginId: string;
  /** The digest the operator previewed; any other live revision refuses with PLUGIN_CHANGED. */
  readonly expectedOldDigest: string;
  /** The authenticated principal, recorded in the update audit. */
  readonly actor: string;
  /** Host owns settings schemas; archives never supply executable migrations or snapshot code.
   * Return a NON-SECRET summary only: it is persisted (0600) in the journal and update history. */
  readonly snapshotSettings: (required: { workspaceId: string; pluginId: string }, optional: Record<string, never>) => Promise<unknown>;
}
export interface UpdateAgentPluginResult {
  readonly plugin: InstalledAgentPlugin;
  readonly enabled: boolean;
  readonly alreadyInstalled: boolean;
  readonly warnings: readonly string[];
}
type InstallAgentPluginPort = (required: InstallAgentPluginRequired, optional: InstallAgentPluginOptional) => Promise<InstalledAgentPlugin>;

interface UpdateTarget {
  readonly previous: InstalledAgentPlugin;
  readonly installed: readonly InstalledAgentPlugin[];
  readonly activations: AgentPluginActivations;
  readonly enabled: boolean;
}
interface UpdateTransaction {
  readonly required: UpdateAgentPluginRequired;
  readonly store: ReturnType<typeof createAgentPluginUpdateStore>;
  readonly target: UpdateTarget;
  readonly candidate: InstalledAgentPlugin;
  readonly publish: () => Promise<InstalledAgentPlugin>;
}

const PLAN_REFUSALS: Partial<Record<AgentPluginUpdatePlan['action'], { code: string; message: string }>> = {
  'downgrade-refused': { code: 'PLUGIN_DOWNGRADE_REFUSED', message: 'Plugin downgrades are refused.' },
  'id-mismatch': { code: 'PLUGIN_ID_MISMATCH', message: 'Choose a candidate for this plugin.' },
};

/** Update transaction owner for operator-installed plugins (bundled ones stay seed-managed).
 *
 * Runs inside the installer's identity lock and per-plugin file lock (the publish guard), so it is
 * serialized against enable/disable/uninstall, which take the same plugin lock. Nothing called in
 * the guard re-takes that lock: activation writes use their own activations.json lock.
 *
 * Invariant: never two live digests. The old revision moves to a frozen rollback area outside
 * `package/sha256` before the candidate is published; a per-plugin journal (pending -> published ->
 * committed) lets boot reconciliation restore it if the process dies before commit.
 *
 * Documented behavior:
 * - In-flight MCP calls against the old revision may fail once the roster is re-provisioned.
 * - Running chats keep the skill text they already captured; new runs resolve the new revision.
 * - Rollback bytes are retained after commit (a run may still read them) and collected by the next
 *   boot's reconciliation, when no run can hold those paths.
 * - Plugin data and memory directories carry over untouched. A rollback restores package bytes and
 *   activation only; it does NOT revert data, memory or settings written while the candidate ran.
 *   The settings snapshot is an audit record, not a restore source.
 * - Caches: this package keeps no cache of skill prompt indexes or search ranking keyed by plugin
 *   (search ranking is computed per call from the installed list; per-run automatic-use state is
 *   per run; module imports are keyed by the digest path), so a switch has nothing to invalidate.
 */
export function createUpdateModule(ports: AgentPluginLifecyclePorts, optional: { installAgentPlugin?: InstallAgentPluginPort } = {}) {
  const installAgentPlugin = optional.installAgentPlugin ?? createInstallModule(ports).installAgentPlugin;
  const activation = createActivationModule(ports);
  const removal = createUninstallModule(ports);
  const refs = createResolveAgentPluginRefsModule(ports);
  const persistent = createPersistentStateModule(ports);
  const index = createInstalledPackageIndex({ ports });

  /** Verifies and stages the candidate through the installer, then runs the transaction in its
   * publish guard. @throws AgentPluginUpdateError, AgentPluginHostIncompatibleError, install errors. */
  async function updateAgentPlugin(required: UpdateAgentPluginRequired, _optional: Record<string, never> = {}): Promise<UpdateAgentPluginResult> {
    const input = { ...required, layout: ports.layout };
    const outcomes: UpdateAgentPluginResult[] = [];
    await installAgentPlugin(input, { publishGuard: async ({ plugin, publish }) => {
      const outcome = await updateLocked({ required: input, candidate: plugin, publish });
      outcomes.push(outcome);
      return outcome.plugin;
    } });
    const [outcome] = outcomes;
    if (!outcome) throw new AgentPluginUpdateError({ code: 'PLUGIN_UPDATE_NOT_RUN', message: 'The installer did not run the update transaction.' });
    return outcome;
  }

  /** All validation precedes the first live-state mutation. @complexity O(p) installed plugins. */
  async function updateLocked({ required, candidate, publish }: {
    required: UpdateAgentPluginRequired; candidate: InstalledAgentPlugin; publish: () => Promise<InstalledAgentPlugin>;
  }, _optional = {}): Promise<UpdateAgentPluginResult> {
    // The installer locked the candidate's id; refuse before reading another plugin's state.
    if (candidate.pluginId !== required.pluginId) throw new AgentPluginUpdateError(PLAN_REFUSALS['id-mismatch']!);
    const store = createAgentPluginUpdateStore({ ports, workspaceId: required.workspaceId, pluginId: required.pluginId });
    await settleAgentPluginUpdateJournal({ store });
    const target = await readTarget({ required });
    const plan = planAgentPluginUpdate({ installed: { ...target.previous, enabled: target.enabled }, candidate });
    if (plan.action === 'none') return { plugin: target.previous, enabled: target.enabled, alreadyInstalled: true, warnings: [] };
    const refusal = PLAN_REFUSALS[plan.action];
    if (refusal) throw new AgentPluginUpdateError(refusal);
    const warnings = admissionWarnings({ target, candidate, planWarnings: plan.warnings });
    const plugin = await performUpdate({ required, store, target, candidate, publish });
    return { plugin, enabled: target.enabled, alreadyInstalled: false, warnings };
  }

  /** Exactly one live revision at the previewed digest, operator-installed, with a readable decision. */
  async function readTarget({ required }: { required: UpdateAgentPluginRequired }, _optional = {}): Promise<UpdateTarget> {
    const workspaceRoot = ports.layout.forWorkspace({ workspaceId: required.workspaceId }).root;
    const installed = await refs.listInstalledPlugins(workspaceRoot);
    const matches = installed.filter(plugin => plugin.pluginId === required.pluginId);
    if (matches.length !== 1 || matches[0]!.archiveDigest !== required.expectedOldDigest) {
      throw new AgentPluginUpdateError({ code: 'PLUGIN_CHANGED', message: 'The installed plugin changed; preview it again.' });
    }
    const previous = matches[0]!;
    if (await activation.isAgentPluginRecordedAsBundled(workspaceRoot, previous.pluginId)) {
      throw new AgentPluginUpdateError({ code: 'PLUGIN_BUNDLED', message: 'Bundled plugins are managed by the host.' });
    }
    const verdict = await activation.resolveAgentPluginActivation(workspaceRoot, previous.pluginId);
    if (verdict.verdict === 'undetermined') throw new AgentPluginUpdateError({ code: 'PLUGIN_ACTIVATION_UNKNOWN', message: 'Repair this plugin activation record before updating.' });
    const activations = await activation.readAgentPluginActivations(workspaceRoot);
    return { previous, installed, activations, enabled: verdict.verdict === 'active' };
  }

  /** An enabled plugin must stay host-compatible; requirement and dependent losses only warn. */
  function admissionWarnings({ target, candidate, planWarnings }: {
    target: UpdateTarget; candidate: InstalledAgentPlugin; planWarnings: readonly string[];
  }, _optional = {}): string[] {
    const { previous, installed, activations } = target;
    const compatibility = describeAgentPluginCompatibility({ plugin: candidate, installed, activations });
    if (target.enabled && !compatibility.hostOk) throw new AgentPluginHostIncompatibleError({ pluginId: candidate.pluginId });
    return [...planWarnings, ...compatibility.missingRequires.map(id => `Needs ${id}`),
      ...agentPluginDependentWarnings({ plugin: previous, installed, activations, nextProvides: candidate.provides ?? [] })];
  }

  /** Records intent, switches revisions, then files the audit. A failed audit filing after commit
   * does not undo the update: the committed journal stays and the next update or boot files it. */
  async function performUpdate(transaction: UpdateTransaction, _optional = {}): Promise<InstalledAgentPlugin> {
    const journal = await beginJournal(transaction);
    const installed = await switchRevision({ ...transaction, journal });
    try { await transaction.store.finish({ journal: { ...journal, state: 'committed', result: 'updated' } }); }
    catch {
      ports.onEvent?.({ event: 'agent-plugin-update-audit-deferred', message: `Plugin '${journal.pluginId}': the committed update will be filed in its history at the next boot.` });
    }
    return installed;
  }

  async function beginJournal({ required, store, target, candidate }: UpdateTransaction, _optional = {}): Promise<AgentPluginUpdateJournal> {
    const { previous, enabled } = target;
    const settingsSnapshot = await required.snapshotSettings({ workspaceId: required.workspaceId, pluginId: previous.pluginId }, {});
    const journal: AgentPluginUpdateJournal = { schemaVersion: 1, state: 'pending', transactionId: ports.ids.newId(),
      pluginId: previous.pluginId, actor: required.actor, enabled, fromDigest: previous.archiveDigest,
      toDigest: candidate.archiveDigest, fromVersion: previous.version, toVersion: candidate.version,
      settingsSnapshot, startedAt: new Date(ports.clock.nowMs()).toISOString() };
    await store.prepare({});
    // A copy of this same digest retained by an earlier committed update (kept for in-flight runs
    // until boot) holds identical bytes and would make the rollback rename fail, so it is removed,
    // and only when present: the rename cannot replace a non-empty directory. A run still reading
    // that retained copy loses it here (the same bytes stay live at package/sha256/<digest> until
    // the switch below). Done before recording intent, so recovery never sees both a stale copy
    // and a live old revision.
    const staleCopy = store.rollbackRoot({ digest: journal.fromDigest });
    if (await store.realDirectoryExists({ root: staleCopy })) await removal.removeFrozenPackageTree(staleCopy);
    await store.write({ journal });
    return journal;
  }

  /** The live-state switch. Any failure restores the old revision; a failed restore keeps the
   * journal for boot and reports PLUGIN_ROLLBACK_INCOMPLETE carrying both errors. The candidate is
   * re-enabled only after its MCP roster is provisioned, so an MCP failure leaves it off even when
   * the rollback that follows cannot finish. */
  async function switchRevision({ required, store, target, publish, journal }: UpdateTransaction & { journal: AgentPluginUpdateJournal }, _optional = {}): Promise<InstalledAgentPlugin> {
    const { workspaceId } = required;
    await disableBeforeSwitch({ workspaceId, store, journal });
    let current = journal;
    try {
      await freezeRollback({ store, previous: target.previous });
      const installed = await publish();
      // `current` follows the durable record: recovery re-provisions MCP only once `published` is on disk.
      const published: AgentPluginUpdateJournal = { ...journal, state: 'published' };
      await store.write({ journal: published });
      current = published;
      await provisionAgentPluginMcp({ mcpProvisioning: ports.mcpProvisioning, workspaceId, installed });
      await setActivation({ workspaceId, journal, enabled: journal.enabled });
      await store.write({ journal: { ...journal, state: 'committed', result: 'updated' } });
      return installed;
    } catch (cause) {
      throw await rollBackAfterFailure({ workspaceId, journal: current, cause });
    }
  }

  /** If the first switch-off fails no byte has moved and activation is unchanged, so there is
   * nothing to recover: the intent is dropped instead of being left pending for boot. */
  async function disableBeforeSwitch({ workspaceId, store, journal }: { workspaceId: string; store: UpdateTransaction['store']; journal: AgentPluginUpdateJournal }, _optional = {}): Promise<void> {
    try { await setActivation({ workspaceId, journal, enabled: false }); }
    catch (cause) { await store.clear({}); throw cause; }
  }

  /** Moves the old revision out of `package/sha256` (reusing uninstall's staging move) and refreezes it. */
  async function freezeRollback({ store, previous }: { store: UpdateTransaction['store']; previous: InstalledAgentPlugin }, _optional = {}): Promise<void> {
    const rollbackRoot = store.rollbackRoot({ digest: previous.archiveDigest });
    await removal.stageForRemoval(path.dirname(previous.packageRoot), previous.packageRoot, { quarantined: rollbackRoot });
    await ports.filesystem.chmod(rollbackRoot, 0o555);
  }

  async function rollBackAfterFailure({ workspaceId, journal, cause }: { workspaceId: string; journal: AgentPluginUpdateJournal; cause: unknown }, _optional = {}): Promise<unknown> {
    try {
      await restoreUpdate({ workspaceId, journal });
      return cause;
    } catch (rollbackError) {
      return new AgentPluginUpdateError({ code: 'PLUGIN_ROLLBACK_INCOMPLETE', message: 'The update failed and its rollback did not finish; restart the host to recover.' },
        { cause: new AggregateError([cause, rollbackError], 'update failure, then rollback failure') });
    }
  }

  async function setActivation({ workspaceId, journal, enabled }: { workspaceId: string; journal: AgentPluginUpdateJournal; enabled: boolean }, _optional = {}) {
    return activation.setAgentPluginActivation({ workspaceRoot: ports.layout.forWorkspace({ workspaceId }).root,
      pluginId: journal.pluginId, enabled, actor: journal.actor }, { origin: 'operator-installed' });
  }

  /** Idempotent recovery (automatic rollback restore, exempt from downgrade planning): remove the
   * candidate, put the old revision back live and frozen, re-provision its MCP roster when the
   * candidate may have been provisioned (journal reached `published`), and only then restore its
   * activation decision. Any failure restoring bytes keeps the journal for the next boot, including
   * failure after the restore rename.
   *
   * MCP re-provisioning is attempted at boot too, not skipped: provisioning writes host-owned roster
   * records naming the candidate's servers, and nothing guarantees the host rebuilds them from the
   * installed bytes at start. A host whose boot binding has no MCP port (it throws) therefore gets the
   * degraded outcome below rather than a journal that fails every boot.
   */
  async function restoreUpdate({ workspaceId, journal }: { workspaceId: string; journal: AgentPluginUpdateJournal }, _optional = {}): Promise<void> {
    const store = createAgentPluginUpdateStore({ ports, workspaceId, pluginId: journal.pluginId });
    const oldRoot = store.liveRoot({ digest: journal.fromDigest });
    await setActivation({ workspaceId, journal, enabled: false });
    await restoreOldBytes({ store, journal, oldRoot });
    if (journal.state === 'published' && !await reprovisionOld({ workspaceId, journal, oldRoot })) {
      ports.onEvent?.({ event: 'agent-plugin-update-recovered-disabled', message: `Plugin '${journal.pluginId}': the previous revision is back but its MCP servers could not be re-provisioned; it stays off until an operator enables it.` });
    } else {
      await setActivation({ workspaceId, journal, enabled: journal.enabled });
    }
    await store.finish({ journal: { ...journal, result: 'rolled-back' } });
  }

  /** Removes the candidate and puts the old revision back live. Refreezing runs whichever branch
   * ran, so a crash between an earlier reinstate rename and its refreeze is repaired here.
   * @throws AgentPluginUpdateError PLUGIN_ROLLBACK_MISSING, PLUGIN_UPDATE_PATH_UNSAFE. */
  async function restoreOldBytes({ store, journal, oldRoot }: { store: UpdateTransaction['store']; journal: AgentPluginUpdateJournal; oldRoot: string }, _optional = {}): Promise<void> {
    const rollbackRoot = store.rollbackRoot({ digest: journal.fromDigest });
    const oldLive = await store.realDirectoryExists({ root: oldRoot });
    if (!oldLive && !await store.realDirectoryExists({ root: rollbackRoot })) {
      throw new AgentPluginUpdateError({ code: 'PLUGIN_ROLLBACK_MISSING', message: 'Previous plugin bytes are missing; recovery is required.' });
    }
    const candidateRoot = store.liveRoot({ digest: journal.toDigest });
    if (await store.realDirectoryExists({ root: candidateRoot })) await removal.removeFrozenPackageTree(candidateRoot);
    // A read-only directory cannot be renamed, so unfreeze the rollback root before moving it back.
    if (!oldLive) {
      await ports.filesystem.chmod(rollbackRoot, 0o700);
      await ports.filesystem.rename(rollbackRoot, oldRoot);
    }
    await ports.filesystem.chmod(oldRoot, 0o555);
  }

  /** @returns false when the old revision's MCP roster could not be re-provisioned; the bytes are
   * already back, so the caller degrades to "restored but off" instead of wedging the journal. */
  async function reprovisionOld({ workspaceId, journal, oldRoot }: { workspaceId: string; journal: AgentPluginUpdateJournal; oldRoot: string }, _optional = {}): Promise<boolean> {
    try {
      const installed = await index.indexInstalledRoot({ packageRoot: oldRoot, archiveDigest: journal.fromDigest });
      await provisionAgentPluginMcp({ mcpProvisioning: ports.mcpProvisioning, workspaceId, installed });
      return true;
    } catch { return false; }
  }

  /** Boot only, before serving runs: recover incomplete switches, file committed audits, then
   * collect retained rollback bytes. One plugin's failure does not stop the others; the first
   * failure is rethrown afterwards. Bundled plugins have no update journal and get no decisions.
   * @complexity O(p + f) workspace entries and retained rollback files.
   */
  async function reconcileAgentPluginUpdates({ workspaceId }: { workspaceId: string }, _optional: Record<string, never> = {}): Promise<void> {
    const workspaceRoot = ports.layout.forWorkspace({ workspaceId }).root;
    const failures: unknown[] = [];
    for (const pluginId of await listPluginStateIds({ workspaceId })) {
      try {
        await persistent.withPluginLock({ workspaceRoot, pluginId, run: () => reconcilePlugin({ workspaceId, pluginId }) });
      } catch (error) {
        failures.push(error);
        ports.onEvent?.({ event: 'agent-plugin-update-recovery-failed', message: `Plugin '${pluginId}': an interrupted update could not be recovered (${errorCode({ error })}); it is kept off until a later boot recovers it.` });
      }
    }
    if (failures.length) throw failures[0];
  }

  /** Workspace entries that can be plugin state roots. Reserved names (staging, packages, memory,
   * data) and invalid ids are rejected by the layout itself and are skipped, never locked. */
  async function listPluginStateIds({ workspaceId }: { workspaceId: string }, _optional = {}): Promise<string[]> {
    const workspace = ports.layout.forWorkspace({ workspaceId });
    let entries;
    try { entries = await ports.filesystem.readdir(workspace.root, { withFileTypes: true }); }
    catch (error) {
      if (!isMissing({ error })) throw error;
      return [];
    }
    return entries.filter(entry => entry.isDirectory() && isPluginStateRoot({ workspace, pluginId: entry.name })).map(entry => entry.name);
  }

  function isPluginStateRoot({ workspace, pluginId }: { workspace: ReturnType<AgentPluginLifecyclePorts['layout']['forWorkspace']>; pluginId: string }): boolean {
    try { workspace.pluginRootDir({ pluginId }); return true; }
    catch { return false; }
  }

  async function reconcilePlugin({ workspaceId, pluginId }: { workspaceId: string; pluginId: string }, _optional = {}): Promise<void> {
    const store = createAgentPluginUpdateStore({ ports, workspaceId, pluginId });
    const switchOff = (error: unknown) => switchOffUnrecovered({ workspaceId, pluginId, error });
    const journal = await store.read({}).catch(switchOff);
    // A committed update only needs finishing; any other journal is rolled back.
    const committed = journal?.state === 'committed';
    if (journal && committed) await store.finish({ journal });
    if (journal && !committed) await restoreUpdate({ workspaceId, journal }).catch(switchOff);
    for (const rollbackRoot of await store.listRollbackRoots({})) await removal.removeFrozenPackageTree(rollbackRoot);
  }

  /** Unrecovered = off: an unreadable journal or a failed restore switches the plugin off (best
   * effort; the journal stays, so the next boot retries) and rethrows. A failure only filing a
   * committed audit or collecting rollback bytes never reaches here. Bundled plugins never get a
   * journal from this module and are never touched. */
  async function switchOffUnrecovered({ workspaceId, pluginId, error }: { workspaceId: string; pluginId: string; error: unknown }, _optional = {}): Promise<never> {
    const workspaceRoot = ports.layout.forWorkspace({ workspaceId }).root;
    try {
      if (!await activation.isAgentPluginRecordedAsBundled(workspaceRoot, pluginId)) {
        await activation.setAgentPluginActivation({ workspaceRoot, pluginId, enabled: false, actor: 'system:update-recovery' }, { origin: 'operator-installed' });
      }
    } catch { /* best effort: the retained journal keeps refusing mutations until a boot recovers it */ }
    throw error;
  }

  function errorCode({ error }: { error: unknown }, _optional = {}): string {
    return typeof error === 'object' && error !== null && 'code' in error ? String(error.code) : 'unknown error';
  }
  return { updateAgentPlugin, reconcileAgentPluginUpdates };
}

import { validatePluginIdentity } from "@jini-ai/core/plugin-directory";
/**
 * Types for the Agent Plugins 1.0.0 open standard (published by a Technical Steering Committee
 * with maintainers from Amazon, Cursor, Google, Microsoft, OpenAI, and Vercel). A plugin is a
 * directory: a `plugin.json` manifest, an optional `skills/<name>/` tree following the Agent
 * Skills spec, an optional `mcp.json` for MCP server declarations, and optional
 * reverse-domain-namespaced directories (e.g. `com.example.client/`) for client-specific
 * extensions that unrecognizing clients ignore.
 *
 * Field lists below are read from the published schemas (`AGENT_PLUGINS_SCHEMA_URL`,
 * `AGENT_PLUGINS_MCP_SCHEMA_URL`), not inferred — both still carry an index signature since
 * neither type asserts it has captured every future schema addition.
 */

export const AGENT_PLUGINS_SCHEMA_URL = 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json';
export const AGENT_PLUGINS_MCP_SCHEMA_URL = 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json';

export const PLUGIN_MANIFEST_FILENAME = 'plugin.json';
export const PLUGIN_SKILLS_DIRNAME = 'skills';
export const PLUGIN_MCP_MANIFEST_FILENAME = 'mcp.json';

export interface PluginManifestAuthor {
  readonly name?: string;
  readonly email?: string;
  readonly url?: string;
}

export type { PluginIdentityExtension } from "@jini-ai/core/plugin-directory";

export interface PluginManifest {
  readonly $schema?: string;
  /** 1-64 chars, lowercase alphanumeric/dots/hyphens, no leading/trailing/doubled separators. */
  readonly name: string;
  readonly version?: string;
  readonly description?: string;
  readonly author?: PluginManifestAuthor;
  readonly homepage?: string;
  readonly repository?: string;
  readonly license?: string;
  readonly keywords?: readonly string[];
  /** Reverse-domain-namespaced client extensions (e.g. `com.example.client`) — the schema assigns
   *  no semantics to what's inside each namespace's object. */
  readonly extensions?: Readonly<Record<string, unknown>>;
  readonly [key: string]: unknown;
}

export function isPluginManifest(value: unknown): value is PluginManifest {
  if (typeof value !== 'object' || value === null) return false;
  const name = (value as Record<string, unknown>).name;
  return typeof name === 'string' && name.trim().length > 0;
}

export type McpServerEntry =
  | {
      readonly type: 'stdio';
      readonly command: string;
      readonly args?: readonly string[];
      readonly env?: Readonly<Record<string, string>>;
      readonly cwd?: string;
    }
  | {
      readonly type: 'streamable-http';
      readonly url: string;
      readonly headers?: Readonly<Record<string, string>>;
    }
  | {
      readonly type: 'sse';
      readonly url: string;
      readonly headers?: Readonly<Record<string, string>>;
    };

export interface McpManifest {
  readonly $schema?: string;
  readonly mcpServers: Readonly<Record<string, McpServerEntry>>;
}

export function isMcpManifest(value: unknown): value is McpManifest {
  if (typeof value !== 'object' || value === null) return false;
  const servers = (value as Record<string, unknown>).mcpServers;
  return typeof servers === 'object' && servers !== null && !Array.isArray(servers);
}

/** Object-argument facade for the legacy structural validator.
 * Hosts inject identityNamespace; the default retains the existing plugin extension format. */
export function validatePluginManifest(required: { readonly value: unknown }, optional: { readonly identityNamespace?: string } = {}): boolean {
  return isPluginManifest(required.value) && validatePluginIdentity({ manifest: required.value, namespace: optional.identityNamespace ?? "tovu" }).errors.length === 0;
}

/** Object-argument facade for the legacy structural validator. */
export function validateMcpManifest(required: { readonly value: unknown }): boolean {
  return isMcpManifest(required.value);
}

import type { GuideCaller, GuideContribution, GuideFact, GuideResult, GuideTopic, GuideTopicView, SiteGuide, SiteGuidePorts } from './types.js';

const MINIMAL_TOPICS: readonly GuideTopic[] = [{
  id: 'site', title: 'How this site works', summary: 'Learn the available building blocks before planning or building.',
  explanation: 'Read the live facts, then consult the host topics and their tools. Missing or forbidden facts are unknown, not disabled capabilities.',
  permissions: [], pointers: [], workflows: [],
}];

export class SiteGuideInputError extends Error {
  constructor({ message }: { readonly message: string }, _options: Record<string, never> = {}) { super(message); this.name = 'SiteGuideInputError'; }
}

/** Bound an injected read so an unavailable extension cannot hang learning. Always clear timers.
 * @complexity O(1) beyond the supplied read; rejection text is kept internal to the shell.
 */
async function boundedRead<T>(read: () => Promise<T>, timeoutMs: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([Promise.resolve().then(read), new Promise<never>((_resolve, reject) => {
      timer = setTimeout(() => reject(new Error('site guide read timed out')), timeoutMs);
    })]);
  } finally { if (timer !== undefined) clearTimeout(timer); }
}

/** Compose by topic id. Core cards keep their owner; plugins add distinct, permission-gated topics.
 * @complexity O(t) in bounded built-in and contributed topic counts, O(t) lookup space.
 */
function combineTopics(builtIns: readonly GuideTopic[], contributions: readonly GuideContribution[]) {
  const topics = new Map(builtIns.map(topic => [topic.id, { topic, source: 'core' }]));
  const byId = new Map<string, { topic: GuideTopic; pluginId: string }[]>();
  for (const contribution of contributions) {
    for (const topic of contribution.topics) {
      const candidates = byId.get(topic.id) ?? [];
      candidates.push({ topic, pluginId: contribution.pluginId });
      byId.set(topic.id, candidates);
    }
  }
  let conflicts = false;
  for (const [id, candidates] of byId) {
    // A contribution cannot replace a host's prose, pointers, workflows or security gates.
    if (topics.has(id) || candidates.length !== 1) { conflicts = true; continue; }
    const candidate = candidates[0]!;
    topics.set(id, { topic: candidate.topic, source: candidate.pluginId });
  }
  return { topics: [...topics.values()], conflicts };
}

/** Build a neutral read-only guide over host ports. No product state or plugin loader is ambient.
 * Authorization and contributions are read fresh for each request. Errors from enrichment/facts
 * yield explicit unavailable status without copying arbitrary error messages into model context.
 * @param ports - Facts, authorization, optional enrichment, and host minimal capability cards.
 * @returns One overview/explain service. Invalid input and hidden topics throw SiteGuideInputError.
 * @complexity O(t + p) per request, topics plus distinct permissions; one bulk facts read.
 * @example createSiteGuide({ facts, authorize, builtInTopics: cards }).run({ caller, operation: 'overview' });
 */
export function createSiteGuide(ports: SiteGuidePorts, options: { readonly readTimeoutMs?: number } = {}): SiteGuide {
  const timeoutMs = options.readTimeoutMs ?? 5_000;
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) throw new SiteGuideInputError({ message: 'readTimeoutMs must be a positive finite number' });
  const builtIns = ports.builtInTopics ?? MINIMAL_TOPICS;
  if (builtIns.length > 256 || new Set(builtIns.map(topic => topic.id)).size !== builtIns.length) throw new SiteGuideInputError({ message: 'Built-in topics must have unique ids and contain at most 256 cards' });
  return { async run(input, _options = {}): Promise<GuideResult> {
    assertGuideInput(input);
    const loaded = await loadContributions({ ports, caller: input.caller, timeoutMs });
    const combined = combineTopics(builtIns, loaded.contributions);
    const enrichment = combined.conflicts ? 'partial' : loaded.enrichment;
    const gate = createPermissionGate({ ports, caller: input.caller, timeoutMs });
    const views = await buildViews({ topics: combined.topics, input, permitted: gate.permitted });
    if (input.operation === 'explain' && views.length === 0) throw new SiteGuideInputError({ message: 'Topic unavailable. Call site_guide with operation overview for topics you may read.' });
    // Overview is discovery only; read fresh domain facts when a visible topic is explained.
    const facts = input.operation === 'explain' ? await readFacts({ ports, caller: input.caller, topicIds: views.map(view => view.id), timeoutMs }) : {};
    return { operation: input.operation, topics: views, facts, enrichment };
  } };
}

type GuideInput = Parameters<SiteGuide['run']>[0];
type Permitted = (permissions: readonly string[]) => Promise<boolean>;

/** Refuses unknown operations, a topic on overview, and explain without a well-formed topic id. */
function assertGuideInput(input: GuideInput): void {
  if (input.operation !== 'overview' && input.operation !== 'explain') throw new SiteGuideInputError({ message: 'operation must be overview or explain' });
  if (input.operation === 'overview' && input.topic !== undefined) throw new SiteGuideInputError({ message: 'topic is only accepted with operation explain' });
  if (input.operation === 'explain' && (typeof input.topic !== 'string' || !/^[a-z][a-z0-9-]{0,63}$/.test(input.topic))) {
    throw new SiteGuideInputError({ message: 'explain requires a topic id from overview' });
  }
}

/** Reads plugin contributions within the deadline; any failure or over-limit result degrades to none. */
async function loadContributions({ ports, caller, timeoutMs }: { ports: SiteGuidePorts; caller: GuideCaller; timeoutMs: number }): Promise<{ contributions: readonly GuideContribution[]; enrichment: GuideResult['enrichment'] }> {
  if (!ports.loadContributions) return { contributions: [], enrichment: 'ok' };
  try {
    const loaded = await boundedRead(() => ports.loadContributions!({ caller }), timeoutMs);
    if (loaded.items.reduce((count, item) => count + item.topics.length, 0) > 256) throw new SiteGuideInputError({ message: 'Too many contributed topics' });
    return { contributions: loaded.items, enrichment: loaded.refusals.length ? 'partial' : 'ok' };
  } catch { return { contributions: [], enrichment: 'unavailable' }; }
}

/** Per-request authorization cache: each permission is asked at most once, in first-use order. */
function createPermissionGate({ ports, caller, timeoutMs }: { ports: SiteGuidePorts; caller: GuideCaller; timeoutMs: number }, _options = {}): { permitted: Permitted } {
  // Granted permissions consulted for this result, rather than an inventory of the caller's roles.
  // Keep these decisions internal so partial checks cannot be mistaken for a complete grant list.
  const decisions = new Map<string, Promise<boolean>>();
  const allowed = (permission: string): Promise<boolean> => {
    let decision = decisions.get(permission);
    if (!decision) {
      // Failed authorization is denial, never an excuse to expose a card or run its read.
      decision = boundedRead(() => ports.authorize({ caller, permission }), timeoutMs).catch(() => false);
      decisions.set(permission, decision);
    }
    return decision;
  };
  return {
    permitted: async permissions => (await Promise.all(permissions.map(allowed))).every(Boolean),
  };
}

/** Visible cards in topic order; explain narrows to the requested id and adds its permitted details. */
async function buildViews({ topics, input, permitted }: { topics: readonly { topic: GuideTopic; source: string }[]; input: GuideInput; permitted: Permitted }): Promise<GuideTopicView[]> {
  const views: GuideTopicView[] = [];
  for (const entry of topics) {
    const requested = input.operation !== 'explain' || entry.topic.id === input.topic;
    if (!requested || !await permitted(entry.topic.permissions)) continue;
    const view: GuideTopicView = { id: entry.topic.id, title: entry.topic.title, summary: entry.topic.summary, source: entry.source };
    views.push(input.operation === 'explain' ? await explainView({ view, topic: entry.topic, permitted }) : view);
  }
  return views;
}

async function explainView({ view, topic, permitted }: { view: GuideTopicView; topic: GuideTopic; permitted: Permitted }): Promise<GuideTopicView> {
  const pointers = await withoutForbidden({ items: topic.pointers, permitted });
  const workflows = await withoutForbidden({ items: topic.workflows, permitted });
  return { ...view, explanation: topic.explanation, pointers, workflows };
}

/** Keeps items whose permissions are all granted, asked one item at a time, minus their gates. */
async function withoutForbidden<T extends { readonly permissions: readonly string[] }>({ items, permitted }: { items: readonly T[]; permitted: Permitted }): Promise<Omit<T, 'permissions'>[]> {
  const kept: Omit<T, 'permissions'>[] = [];
  for (const { permissions, ...item } of items) if (await permitted(permissions)) kept.push(item);
  return kept;
}

/** One bulk facts read for the visible topics; failure marks each of them unavailable. */
async function readFacts({ ports, caller, topicIds, timeoutMs }: { ports: SiteGuidePorts; caller: GuideCaller; topicIds: readonly string[]; timeoutMs: number }): Promise<Readonly<Record<string, GuideFact>>> {
  try {
    const read = await boundedRead(() => ports.facts.read({ caller, topics: topicIds }), timeoutMs);
    // A facts adapter returning an unrelated section cannot disclose it through this tool.
    return Object.fromEntries(topicIds.map(id => [id, read[id] ?? { status: 'unavailable' }]));
  } catch { return Object.fromEntries(topicIds.map(id => [id, { status: 'unavailable' }])); }
}

/** Accepted composer input has one identity across optimistic display, replay and recall. */
import { questionAnswerFromResult, questionAnswerLabel } from './question-answer.js';
import type { AgentEvent } from './events.js';
import type { ChatAttachment, ChatMessage } from './messages.js';
import { MID_RUN_USER_MESSAGE_EVENT_NAME } from './turn-usage.js';

export interface AcceptedChatInput {
  id: string;
  text: string;
  /** Standalone questions have no owning tool id; a receipt answers the preceding document at its URI. */
  surfaceUri?: string;
  /** The card's answer without its title; text retains the complete user bubble. */
  answerText?: string;
  /** Absent for legacy/ordinary inputs; consumed only after a CLI UUID receipt. */
  deliveryState?: 'queued' | 'consumed';
  attachments?: ChatAttachment[];
  secretRedaction?: ChatMessage['secretRedaction'];
  /** Wire ids replaced by this receipt remain seen by recall. */
  aliases?: readonly string[];
}

/** Display queue constituents using their accepted identities; storage and delivery retain one turn.
 * MOVE: Receipts travel in events_json, so separate bubbles survive a history reload without another store.
 * @complexity O(m + e + i) time/space for m messages, e receipt events and i accepted queue inputs.
 */
export function projectAcceptedInputMessages({ messages }: { messages: readonly ChatMessage[] }, _options = {}): ChatMessage[] {
  return messages.flatMap(message => {
    if (message.role !== 'user') return [message];
    const inputs = (message.events ?? []).flatMap(event => {
      const input = acceptedInputEvent({ event });
      return input ? [input.data] : [];
    });
    if (inputs.length === 0) return [message];
    const { attachments: _attachments, secretRedaction: _redaction, ...turn } = message;
    // MOVE: Older receipts have no per-input files; retain those legacy files on the final bubble.
    return inputs.map((input, index) => ({ ...turn, id: input.id, content: input.text,
      attachments: input.attachments ?? (index === inputs.length - 1 ? message.attachments ?? [] : []), ...(input.secretRedaction ? { secretRedaction: input.secretRedaction } : {}) }));
  });
}

type UserMessageEvent = Extract<AgentEvent, { kind: 'ext' }> & {
  data: AcceptedChatInput & { optimistic?: boolean; toolUseId?: string; afterInputId?: string; inputs?: AcceptedChatInput[] };
};

/** Hosts can recover standalone form labels without adding a DOM dependency to core. */
export interface AcceptedInputProjectionOptions {
  answerContexts?: ReadonlyMap<string, { input: unknown; includeTitle?: boolean }>;
}

/** Reads the existing event-backed user bubble without depending on a host renderer. */
export function acceptedInputEvent({ event }: { event: AgentEvent }, _options = {}): UserMessageEvent | null {
  if (event.kind !== 'ext' || event.name !== MID_RUN_USER_MESSAGE_EVENT_NAME) return null;
  const data = event.data as Partial<UserMessageEvent['data']> | null;
  return data && typeof data.id === 'string' && typeof data.text === 'string' ? event as UserMessageEvent : null;
}

/** Read resource identity without importing the browser/UI parser into core. */
function surfaceUriOf({ event }: { event: AgentEvent }, _options = {}): string | undefined {
  if (event.kind !== 'ext' || event.name !== 'mcp-ui') return undefined;
  const data = event.data as { resource?: { uri?: unknown } } | null;
  return typeof data?.resource?.uri === 'string' ? data.resource.uri : undefined;
}

/** Bind each unique receipt to the preceding document, never a later outcome or retry at its URI.
 * Both transcript closure and activity use this projection; resource identity alone is not an answer.
 * @returns Answer labels keyed by the original ext-event data; no caller mutation or I/O.
 * @complexity O(e) time/space for events, including replay deduplication by accepted-input id.
 */
export function recordedSurfaceAnswers({ events }: { events: readonly AgentEvent[] }, _options = {}): ReadonlyMap<unknown, string> {
  const latest = new Map<string, unknown>();
  const answers = new Map<unknown, string>();
  const seen = new Set<string>();
  for (const event of events) {
    const uri = surfaceUriOf({ event });
    if (uri !== undefined && event.kind === 'ext') latest.set(uri, event.data);
    const receipt = acceptedInputEvent({ event })?.data;
    if (typeof receipt?.surfaceUri !== 'string' || seen.has(receipt.id)) continue;
    seen.add(receipt.id);
    const document = latest.get(receipt.surfaceUri);
    if (document !== undefined) answers.set(document, surfaceAnswerText({ receipt }));
  }
  return answers;
}

function surfaceAnswerText({ receipt }: { receipt: AcceptedChatInput }, _options = {}): string {
  return typeof receipt.answerText === 'string' ? receipt.answerText : receipt.text;
}

/** Project a persisted answer through the same receipt owner as composer input. */
function questionAnswerEvent({ event, input }: { event: AgentEvent; input: unknown }, { includeTitle = false }: { includeTitle?: boolean } = {}): UserMessageEvent | null {
  if (event.kind !== 'tool_result') return null;
  const text = questionAnswerFromResult({ result: event, input });
  if (text === undefined) return null;
  // A standalone form's bubble reads like its closed card: "<title>: <answer>".
  return { kind: 'ext', name: MID_RUN_USER_MESSAGE_EVENT_NAME,
    data: { id: `answer:${event.toolUseId}`, text: includeTitle ? questionAnswerLabel({ input, text }) : text, toolUseId: event.toolUseId } };
}

/** Builds the same bubble for delivered answers and steering; queues use the existing pending row. */
export function acceptedInputUserEvent(
  { input, inputs, toolUseId, afterInputId }: { input: AcceptedChatInput; inputs?: AcceptedChatInput[]; toolUseId?: string; afterInputId?: string },
  { receipt = 'optimistic' }: { receipt?: 'optimistic' | 'accepted' } = {},
): AgentEvent {
  return { kind: 'ext', name: MID_RUN_USER_MESSAGE_EVENT_NAME,
    data: { ...input, ...(receipt === 'optimistic' ? { optimistic: true } : {}), ...(inputs === undefined ? {} : { inputs }), ...(afterInputId === undefined ? {} : { afterInputId }), ...(toolUseId === undefined ? {} : { toolUseId }) } };
}

type OptimisticTextQueue = { events: UserMessageEvent[]; index: number };
type OptimisticInputs = { byText: Map<string, OptimisticTextQueue>; byQuestion: Map<string, UserMessageEvent> };
type InputReconciliation = { replacements: Map<AgentEvent, AgentEvent>; replaced: Set<AgentEvent>; seen: Set<string> };

function expandQuestionAnswers({ events }: { events: readonly AgentEvent[] }, { answerContexts }: AcceptedInputProjectionOptions = {}): AgentEvent[] {
  const savedAnswers = new Set(events.flatMap(event => {
    const input = acceptedInputEvent({ event });
    return input && !input.data.optimistic && input.data.toolUseId ? [input.data.toolUseId] : [];
  }));
  // MOVE: Persisted picks carry values; the original tool input retains their human-readable labels.
  const questions = new Map(events.flatMap(event => event.kind === 'tool_use' ? [[event.id, event.input] as const] : []));
  const answers = new Map(events.flatMap(event => {
    const context = event.kind === 'tool_result' ? answerContexts?.get(event.toolUseId) : undefined;
    const input = context ? context.input : event.kind === 'tool_result' ? questions.get(event.toolUseId) : undefined;
    const answer = questionAnswerEvent({ event, input }, { includeTitle: context?.includeTitle === true });
    return answer ? [[answer.data.toolUseId!, answer] as const] : [];
  }));
  return events.flatMap(event => {
    const receipt = acceptedInputEvent({ event });
    const recorded = receipt?.data.toolUseId ? answers.get(receipt.data.toolUseId) : undefined;
    if (receipt && recorded) return [{ ...receipt, data: { ...receipt.data, text: recorded.data.text } }];
    const answer = event.kind === 'tool_result' ? answers.get(event.toolUseId) : undefined;
    return answer && !savedAnswers.has(answer.data.toolUseId!) ? [event, answer] : [event];
  });
}

function collectOptimisticInputs({ events }: { events: readonly AgentEvent[] }, _options = {}): OptimisticInputs {
  const optimisticByText = new Map<string, { events: UserMessageEvent[]; index: number }>();
  const optimisticByQuestion = new Map<string, UserMessageEvent>();
  for (const event of events) {
    const input = acceptedInputEvent({ event });
    if (!input?.data.optimistic) continue;
    if (input.data.toolUseId) optimisticByQuestion.set(input.data.toolUseId, input);
    else {
      const list = optimisticByText.get(input.data.text) ?? { events: [], index: 0 };
      list.events.push(input);
      optimisticByText.set(input.data.text, list);
    }
  }
  return { byText: optimisticByText, byQuestion: optimisticByQuestion };
}

function matchOptimisticInput(
  { input, optimistic, seen }: { input: UserMessageEvent; optimistic: OptimisticInputs; seen: Set<string> }, _options = {},
): UserMessageEvent | undefined {
  const candidates = optimistic.byText.get(input.data.text);
  const next = candidates?.events[candidates.index];
  const follows = next?.data.afterInputId === undefined || seen.has(next.data.afterInputId);
  // Keep predecessor testing before the caller adds this receipt's ids to seen.
  return input.data.toolUseId ? optimistic.byQuestion.get(input.data.toolUseId) : follows ? next : undefined;
}

/** Apply authoritative receipt data while retaining local identity and queued constituents. */
function mergeAcceptedReceipt(
  { input, pending }: { input: UserMessageEvent; pending: UserMessageEvent }, _options = {},
): UserMessageEvent {
  // Replayed queue acceptance cannot undo confirmed consumption.
  const deliveryState = pending.data.deliveryState === 'consumed' ? 'consumed' : input.data.deliveryState ?? pending.data.deliveryState;
  const { optimistic: _optimistic, afterInputId: _afterInputId, ...pendingData } = pending.data;
  const aliases = [...new Set([...(input.data.aliases ?? []), input.data.id, ...(pending.data.aliases ?? [])])].filter(id => id !== pending.data.id);
  return { ...input, data: { ...pendingData, ...input.data, id: pending.data.id,
    // Legacy acceptance receipts omit state; HTTP acceptance still means queued until consumption.
    ...(deliveryState === undefined ? {} : { deliveryState }),
    ...(pending.data.inputs ? { inputs: pending.data.inputs.map(item => ({ ...item, ...(deliveryState ? { deliveryState } : {}) })) } : {}),
    ...(aliases.length > 0 ? { aliases } : {}) } };
}

function acceptedInputIds({ input }: { input: UserMessageEvent }, _options = {}): string[] {
  return [input.data.id, ...(input.data.toolUseId ? [`answer:${input.data.toolUseId}`] : []), ...(input.data.aliases ?? [])];
}

function reconcileAcceptedInput(
  { event, optimistic, state }: { event: AgentEvent; optimistic: OptimisticInputs; state: InputReconciliation }, _options = {},
): void {
  const input = acceptedInputEvent({ event });
  if (!input || input.data.optimistic) return;
  const { replacements, replaced, seen } = state;
  const ids = acceptedInputIds({ input });
  if (ids.some(id => seen.has(id))) { replaced.add(event); return; }
  const pending = matchOptimisticInput({ input, optimistic, seen });
  for (const id of ids) seen.add(id);
  if (!pending) return;
  advanceOptimisticInput({ input, optimistic });
  for (const id of [pending.data.id, ...(pending.data.aliases ?? [])]) seen.add(id);
  optimistic.byQuestion.delete(input.data.toolUseId ?? '');
  // Acceptance can arrive after the reply it triggered. Keep the position where the person sent it.
  replaced.add(event);
  replacements.set(pending, mergeAcceptedReceipt({ input, pending }));
}

function advanceOptimisticInput(
  { input, optimistic }: { input: UserMessageEvent; optimistic: OptimisticInputs }, _options = {},
): void {
  const candidates = optimistic.byText.get(input.data.text);
  if (candidates && !input.data.toolUseId) candidates.index += 1;
}

/** Fold state updates into the original bubble, preserving its position, local id and aliases.
 * O(e + a + i) time/space for events, receipt aliases and expanded input constituents; equal text never establishes identity. */
function collapseDeliveryReceipts({ events }: { events: readonly AgentEvent[] }, _options = {}): AgentEvent[] {
  const result: AgentEvent[] = [];
  const positions = new Map<string, number>();
  for (const event of events) {
    const input = acceptedInputEvent({ event });
    const position = input ? positions.get(input.data.id) : undefined;
    if (input && position !== undefined && !input.data.optimistic) {
      const original = acceptedInputEvent({ event: result[position]! })!;
      result[position] = mergeAcceptedReceipt({ input, pending: original });
      continue;
    }
    if (input) recordInputPosition({ input, positions, position: result.length });
    result.push(event);
  }
  return result;
}

function recordInputPosition({ input, positions, position }: { input: UserMessageEvent; positions: Map<string, number>; position: number }, _options = {}): void {
  for (const id of acceptedInputIds({ input })) positions.set(id, position);
}

/** Projects saved answers and reconciles optimistic bubbles with wire events, occurrence for
 * occurrence. Legacy steering receipts have no client id: only unmatched optimistic input may
 * match by text; two real events with equal text always remain distinct.
 * @complexity O(e + u + a) time, O(e + u) space for e events, u user inputs and total answer-label lookup cost a.
 */
export function projectAcceptedInputEvents(
  { events }: { events: readonly AgentEvent[] }, options?: AcceptedInputProjectionOptions,
): AgentEvent[] {
  if (options !== undefined) return projectEvents({ events }, options);
  // Event arrays are replaced, never mutated, so a transcript update re-projects only changed messages.
  let projected = defaultProjections.get(events);
  if (!projected) defaultProjections.set(events, projected = projectEvents({ events }, {}));
  return projected;
}

const defaultProjections = new WeakMap<readonly AgentEvent[], AgentEvent[]>();

function projectEvents(
  { events }: { events: readonly AgentEvent[] }, options: AcceptedInputProjectionOptions,
): AgentEvent[] {
  const expanded = expandQuestionAnswers({ events: collapseDeliveryReceipts({ events }) }, options);
  const optimistic = collectOptimisticInputs({ events: expanded });
  const state: InputReconciliation = { replacements: new Map(), replaced: new Set(), seen: new Set() };
  for (const event of expanded) reconcileAcceptedInput({ event, optimistic, state });
  const { replacements, replaced } = state;
  const projected: AgentEvent[] = [];
  const emitted = new Set<string>();
  for (const event of expanded) {
    if (replaced.has(event)) continue;
    const next = replacements.get(event) ?? event;
    const input = acceptedInputEvent({ event: next });
    if (input && emitted.has(input.data.id)) continue;
    if (input) emitted.add(input.data.id);
    projected.push(next);
  }
  return projected;
}

/** The sole transcript-to-recall projection. A merged queued turn retains its original inputs. */
export function acceptedInputsFromMessages(
  { messages }: { messages: readonly ChatMessage[] }, _options = {},
): AcceptedChatInput[] {
  return messages.flatMap(message => {
    if (message.role === 'user') {
      if (message.inputPending) return [];
      // Queue constituents travel in events_json, already preserved by the existing chat store.
      const receipts = (message.events ?? []).flatMap(event => {
        const input = acceptedInputEvent({ event });
        return input ? [input.data] : [];
      });
      return receipts.length > 0 ? receipts : [{ id: message.id, text: message.content }];
    }
    return projectAcceptedInputEvents({ events: message.events ?? [] }).flatMap(event => {
      const input = acceptedInputEvent({ event });
      if (!input) return [];
      return input.data.inputs?.map((receipt, index) => index === 0 ? { ...receipt, aliases: input.data.aliases ?? [] } : receipt) ?? [input.data];
    });
  });
}

/** Pure chat-event to AG-UI projection; lifecycle state belongs to one run.
 * This legacy wire reducer is independent of saved-chat reduction: partial tool input remains
 * a CUSTOM extension, while media stays in run-event vocabulary and is absent from TOOL_CALL_RESULT.
 * Strict interruption ordering closes a message before a tool starts. IDs and custom event names
 * are injected, with official AG-UI types authoritative; auth, routes and encoder stay with the host.
 * The host emits RUN_STARTED and terminal RUN_FINISHED/RUN_ERROR outside this pure projection. */
import { EventType, type AGUIEvent } from '@ag-ui/core';
import type { AgentEvent } from '../events.js';

export interface EventIdGenerator {
  next(args: { prefix: string; ordinal: number }): string;
}
export interface CustomEventNames {
  readonly usage: string;
  readonly status: string;
  readonly extensionPrefix: string;
}

export interface RunAgentWirePayload {
  readonly type: string;
  readonly [key: string]: unknown;
}

function asString(v: unknown): string {
  return typeof v === "string" ? v : v == null ? "" : JSON.stringify(v);
}

function reduceUsagePayload(payload: RunAgentWirePayload): AgentEvent {
  const usage = (payload.usage ?? {}) as Record<string, unknown>;
  return {
    kind: "usage",
    ...(typeof usage.input_tokens === "number" ? { inputTokens: usage.input_tokens } : {}),
    ...(typeof usage.output_tokens === "number" ? { outputTokens: usage.output_tokens } : {}),
    ...(typeof payload.costUsd === "number" ? { costUsd: payload.costUsd } : {}),
    ...(typeof payload.cumulativeCostUsd === "number" ? { cumulativeCostUsd: payload.cumulativeCostUsd } : {}),
    ...(typeof payload.costSessionId === "string" ? { costSessionId: payload.costSessionId } : {}),
    ...(typeof payload.durationMs === "number" ? { durationMs: payload.durationMs } : {}),
  };
}

const WIRE_PAYLOAD_REDUCERS: Record<string, (payload: RunAgentWirePayload) => AgentEvent | null> = {
  status: (payload) => ({ kind: "status", label: asString(payload.label), ...(payload.detail ? { detail: asString(payload.detail) } : {}) }),
  text_delta: (payload) => ({ kind: "text", text: asString(payload.delta) }),
  thinking_delta: (payload) => ({ kind: "thinking", text: asString(payload.delta) }),
  tool_use: (payload) => ({ kind: "tool_use", id: asString(payload.id), name: asString(payload.name), input: payload.input }),
  tool_result: (payload) => ({
    kind: "tool_result",
    toolUseId: asString(payload.toolUseId),
    content: asString(payload.content),
    isError: Boolean(payload.isError),
  }),
  usage: reduceUsagePayload,
  raw: (payload) => ({ kind: "raw", line: asString(payload.line) }),
  "mcp-ui": (payload) => ({ kind: "ext", name: "mcp-ui", data: payload.resource }),
  a2ui: (payload) => ({ kind: "ext", name: "a2ui", data: payload.message }),
  thinking_start: () => null,
};

/** Preserve the legacy AG-UI wire reduction, including partial input as extension events.
 * Unlike the saved-chat reducer, this projection carries partial tool-input extensions. */
export function reduceAgentWirePayload({ payload }: { payload: RunAgentWirePayload }): AgentEvent | null {
  const reducer = Object.hasOwn(WIRE_PAYLOAD_REDUCERS, payload.type) ? WIRE_PAYLOAD_REDUCERS[payload.type] : undefined;
  return reducer ? reducer(payload) : { kind: "ext", name: payload.type, data: payload };
}

export type AgUiEvent = Extract<
  AGUIEvent,
  {
    type:
      | EventType.RUN_STARTED
      | EventType.RUN_FINISHED
      | EventType.RUN_ERROR
      | EventType.TEXT_MESSAGE_START
      | EventType.TEXT_MESSAGE_CONTENT
      | EventType.TEXT_MESSAGE_END
      | EventType.REASONING_START
      | EventType.REASONING_MESSAGE_START
      | EventType.REASONING_MESSAGE_CONTENT
      | EventType.REASONING_MESSAGE_END
      | EventType.REASONING_END
      | EventType.TOOL_CALL_START
      | EventType.TOOL_CALL_ARGS
      | EventType.TOOL_CALL_END
      | EventType.TOOL_CALL_RESULT
      | EventType.RAW
      | EventType.CUSTOM;
  }
>;

export interface AgUiTranslationState {
  openTextMessageId: string | null;
  openReasoningMessageId: string | null;

  nextId: number;
  readonly ids: EventIdGenerator;
  readonly customEventNames: CustomEventNames;
}

/** Create isolated per-run translation state with explicit IDs and custom-event wire names. */
export function createAgUiTranslationState({ ids, customEventNames }: { ids: EventIdGenerator; customEventNames: CustomEventNames }): AgUiTranslationState {
  return { openTextMessageId: null, openReasoningMessageId: null, nextId: 0, ids, customEventNames: { ...customEventNames } };
}

function mintId(state: AgUiTranslationState, prefix: string): string {
  state.nextId += 1;
  return state.ids.next({ prefix, ordinal: state.nextId });
}

function closeOpenMessages(state: AgUiTranslationState): AgUiEvent[] {
  const events: AgUiEvent[] = [];
  if (state.openTextMessageId) {
    events.push({ type: EventType.TEXT_MESSAGE_END, messageId: state.openTextMessageId });
    state.openTextMessageId = null;
  }
  if (state.openReasoningMessageId) {
    const messageId = state.openReasoningMessageId;
    events.push({ type: EventType.REASONING_MESSAGE_END, messageId });
    events.push({ type: EventType.REASONING_END, messageId });
    state.openReasoningMessageId = null;
  }
  return events;
}

function handleTextAgentEvent(event: Extract<AgentEvent, { kind: "text" }>, state: AgUiTranslationState): AgUiEvent[] {
  const events: AgUiEvent[] = [];
  if (state.openReasoningMessageId) events.push(...closeOpenMessages(state));
  if (!state.openTextMessageId) {
    state.openTextMessageId = mintId(state, "msg");
    events.push({ type: EventType.TEXT_MESSAGE_START, messageId: state.openTextMessageId, role: "assistant" });
  }
  events.push({ type: EventType.TEXT_MESSAGE_CONTENT, messageId: state.openTextMessageId, delta: event.text });
  return events;
}

function handleThinkingAgentEvent(event: Extract<AgentEvent, { kind: "thinking" }>, state: AgUiTranslationState): AgUiEvent[] {
  const events: AgUiEvent[] = [];
  if (state.openTextMessageId) events.push(...closeOpenMessages(state));
  if (!state.openReasoningMessageId) {
    state.openReasoningMessageId = mintId(state, "reasoning");
    events.push({ type: EventType.REASONING_START, messageId: state.openReasoningMessageId });
    events.push({ type: EventType.REASONING_MESSAGE_START, messageId: state.openReasoningMessageId, role: "reasoning" });
  }
  events.push({ type: EventType.REASONING_MESSAGE_CONTENT, messageId: state.openReasoningMessageId, delta: event.text });
  return events;
}

function handleToolUseAgentEvent(event: Extract<AgentEvent, { kind: "tool_use" }>, state: AgUiTranslationState): AgUiEvent[] {
  const events: AgUiEvent[] = [];
  if (state.openTextMessageId || state.openReasoningMessageId) events.push(...closeOpenMessages(state));
  events.push({ type: EventType.TOOL_CALL_START, toolCallId: event.id, toolCallName: event.name });
  events.push({ type: EventType.TOOL_CALL_ARGS, toolCallId: event.id, delta: JSON.stringify(event.input ?? {}) });
  events.push({ type: EventType.TOOL_CALL_END, toolCallId: event.id });
  return events;
}

/** Emit ordered message/tool lifecycles; a tool call closes the preceding message first. */
export function translateAgentEventToAgUi({ event, state }: { event: AgentEvent; state: AgUiTranslationState }): AgUiEvent[] {
  switch (event.kind) {
    case "text":
      return handleTextAgentEvent(event, state);

    case "thinking":
      return handleThinkingAgentEvent(event, state);

    case "tool_use":
      return handleToolUseAgentEvent(event, state);

    case "tool_result":
      return [
        {
          type: EventType.TOOL_CALL_RESULT,
          messageId: mintId(state, "tool_result_msg"),
          toolCallId: event.toolUseId,
          content: event.content,
          role: "tool",
        },
      ];

    case "usage":
      return [{ type: EventType.CUSTOM, name: state.customEventNames.usage, value: event }];

    case "status":
      return [{ type: EventType.CUSTOM, name: state.customEventNames.status, value: event }];

    case "raw":
      return [{ type: EventType.RAW, event: event.line }];

    case "ext":
      return [{ type: EventType.CUSTOM, name: `${state.customEventNames.extensionPrefix}${event.name}`, value: event.data }];

    default: {
      const neverEvent: never = event;
      throw new Error(`translateAgentEventToAgUi: unhandled AgentEvent.kind ${JSON.stringify(neverEvent)}`);
    }
  }
}

/** Close open text/reasoning before the host emits RUN_FINISHED or RUN_ERROR. */
export function closeAgUiRun({ state }: { state: AgUiTranslationState }): AgUiEvent[] {
  return closeOpenMessages(state);
}


/**
 * Accumulates `TOOL_CALL_ARGS` deltas by `toolCallId` between a call's `TOOL_CALL_START` and
 * `TOOL_CALL_END` — the inverse of `assistant-ag-ui.ts`'s server-side translator, which emits all
 * three tool-call events back-to-back for one chat `tool_use` event today, but this side is written
 * to accumulate real streamed deltas too (a future daemon driver that streams `tool_input_delta`
 * incrementally needs no transport-layer change to render correctly). One instance per run, NOT a
 * module-level singleton — the same reasoning `assistant-ag-ui.ts`'s `AgUiTranslationState` gives.
 */
export interface AgUiToAgentTranslationState {
  toolCalls: Map<string, { name: string; argsJson: string }>;
  readonly customEventNames: CustomEventNames;
}

export function createAgUiToAgentTranslationState({ customEventNames }: { customEventNames: CustomEventNames }, _options: Record<string, never> = {}): AgUiToAgentTranslationState {
  return { toolCalls: new Map(), customEventNames: { ...customEventNames } };
}

/** The `TOOL_CALL_ARGS` case of {@link translateAgUiEventToAgentEvent} — accumulates one delta onto
 *  the in-flight call's buffer, a silent no-op for an id with no matching `TOOL_CALL_START`. Split
 *  out so this `if` is scored in its own complexity budget rather than the switch's. */
function accumulateToolCallArgs(toolCallId: string, delta: string, state: AgUiToAgentTranslationState): void {
  const call = state.toolCalls.get(toolCallId);
  if (call) call.argsJson += delta;
}

/** `TEXT_MESSAGE_START` keeps an explicit step boundary so two assistant messages cannot fuse into
 *  one word; every other unmapped event translates to nothing. Split out so this `if` is scored in
 *  its own complexity budget rather than the switch's. */
function translateAgUiStepStart({ event }: { event: AgUiEvent }, _options = {}): AgentEvent[] {
  if (event.type !== EventType.TEXT_MESSAGE_START) return [];
  return [{ kind: 'status', code: 'step_start', label: '', data: { messageId: event.messageId } }];
}

/** The `TOOL_CALL_END` case of {@link translateAgUiEventToAgentEvent} — parses the accumulated
 *  args buffer (already removed from `state` by the caller) into one `tool_use` event, or `[]` for
 *  an id with no matching `TOOL_CALL_START`. */
function finalizeToolCallAgentEvent(toolCallId: string, call: { name: string; argsJson: string } | undefined): AgentEvent[] {
  if (!call) return [];
  let input: unknown = {};
  try {
    input = call.argsJson.length > 0 ? JSON.parse(call.argsJson) : {};
  } catch {
    // A malformed/partial args buffer must not throw and drop the whole tool call — the raw
    // string is still more useful to a human than nothing.
    input = call.argsJson;
  }
  return [{ kind: "tool_use", id: toolCallId, name: call.name, input }];
}

/** The `CUSTOM` case of {@link translateAgUiEventToAgentEvent}. */
function translateAgUiCustomEvent(event: Extract<AgUiEvent, { type: EventType.CUSTOM }>, names: CustomEventNames): AgentEvent[] {
  // Host-supplied usage/status names: the server's own translator put the ORIGINAL `AgentEvent`
  // straight into `.value` (see `assistant-ag-ui.ts`'s `translateAgentEventToAgUi`), so this is
  // an exact round trip, not a re-derivation.
  if (event.name === names.usage || event.name === names.status) return [event.value as AgentEvent];
  if (event.name.startsWith(names.extensionPrefix)) return [{ kind: "ext", name: event.name.slice(names.extensionPrefix.length), data: event.value }];
  return [{ kind: "ext", name: event.name, data: event.value }];
}

/**
 * Translates one AG-UI event into zero or more chat-core `AgentEvent`s, threading `state` across
 * calls within a single run for tool-call argument accumulation.
 *
 * `TEXT_MESSAGE_START` preserves an explicit step boundary so two assistant messages cannot fuse
 * into one word. End/reasoning markers carry no text. The two cases
 * with real internal branching (`TOOL_CALL_END`, `CUSTOM`) and the one with a guard (`TOOL_CALL_ARGS`)
 * are pulled into their own named functions above so this switch's own cost is just its case count.
 */
export function translateAgUiEventToAgentEvent({ event, state }: { event: AgUiEvent; state: AgUiToAgentTranslationState }, _options: Record<string, never> = {}): AgentEvent[] {
  switch (event.type) {
    case EventType.TEXT_MESSAGE_CONTENT:
      return [{ kind: "text", text: event.delta }];

    case EventType.REASONING_MESSAGE_CONTENT:
      return [{ kind: "thinking", text: event.delta }];

    case EventType.TOOL_CALL_START:
      state.toolCalls.set(event.toolCallId, { name: event.toolCallName, argsJson: "" });
      return [];

    case EventType.TOOL_CALL_ARGS:
      accumulateToolCallArgs(event.toolCallId, event.delta, state);
      return [];

    case EventType.TOOL_CALL_END: {
      const call = state.toolCalls.get(event.toolCallId);
      state.toolCalls.delete(event.toolCallId);
      return finalizeToolCallAgentEvent(event.toolCallId, call);
    }

    case EventType.TOOL_CALL_RESULT:
      // AG-UI's `ToolCallResultEvent` carries no `isError` field (verified against the real schema)
      // — a genuine protocol-level fidelity gap, not a translator bug: chat's `isError` flag cannot
      // survive the round trip through AG-UI's wire shape, so it always reconstructs as `false`.
      return [{ kind: "tool_result", toolUseId: event.toolCallId, content: event.content, isError: false }];

    case EventType.RAW:
      return [{ kind: "raw", line: asString(event.event) }];

    case EventType.CUSTOM:
      return translateAgUiCustomEvent(event, state.customEventNames);

    default:
      return translateAgUiStepStart({ event });
  }
}

/** Browser-local per-chat decisions; the person's mode remains in the host's settings ledger. */
export interface AgentPluginChatState { decision: { selected: readonly string[]; asked?: boolean } | null; excluded: readonly string[] }
export interface AgentPluginUsage { conversationId: string; state: AgentPluginChatState; plugins: readonly { id: string; name: string }[] }
export interface ChatPluginStorage { getItem(key: string): string | null; setItem(key: string, value: string): void }
export const AGENT_PLUGIN_STATE_CHANGED = 'jini:agent-plugin-state';
const key = (conversationId: string) => `jini:chat-agent-plugins:${conversationId}`;
function browserStorage(): ChatPluginStorage | undefined {
  try { return typeof window === 'undefined' ? undefined : window.localStorage; } catch { return undefined; }
}
function isStringList({ value }: { value: unknown }): boolean {
  return Array.isArray(value) && value.every(id => typeof id === 'string');
}
/** A stored row is usable only when its exclusions and (null or listed) decision are all string ids. */
function usableChatState({ value }: { value: AgentPluginChatState | null }): AgentPluginChatState | null {
  return value && isStringList({ value: value.excluded }) && (value.decision === null || isStringList({ value: value.decision?.selected })) ? value : null;
}
/** Corrupt/blocked storage permits a fresh question, as clearing localStorage does. */
export function readAgentPluginChatState(
  { conversationId }: { conversationId: string }, { storage = browserStorage() }: { storage?: ChatPluginStorage | undefined } = {},
): AgentPluginChatState {
  try {
    const state = usableChatState({ value: JSON.parse(storage?.getItem(key(conversationId)) ?? 'null') as AgentPluginChatState | null });
    if (state) return state;
  } catch { /* Private browsing/corrupt rows behave as a new chat decision. */ }
  return { decision: null, excluded: [] };
}
/** Persist only decision/exclusions. Existing exclusions win over an in-flight server response. */
export function writeAgentPluginChatState(
  { conversationId, state }: { conversationId: string; state: AgentPluginChatState }, { storage = browserStorage() }: { storage?: ChatPluginStorage | undefined } = {},
): void {
  const current = readAgentPluginChatState({ conversationId }, { storage });
  const next = { decision: state.decision, excluded: [...new Set([...current.excluded, ...state.excluded])] };
  try { storage?.setItem(key(conversationId), JSON.stringify(next)); } catch { /* Session can continue without persistence. */ }
  if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent(AGENT_PLUGIN_STATE_CHANGED, { detail: { conversationId, state: next } }));
}
/** Called only for the protocol's structured plugin event, before delivering it to the transcript. */
export function captureAgentPluginUsage({ event }: { event: { kind: string; name?: string; data?: unknown } }, _options = {}): void {
  if (event.kind !== 'ext' || event.name !== 'agent_plugins') return;
  const usage = event.data as AgentPluginUsage;
  if (typeof usage?.conversationId !== 'string' || !usage.state || !Array.isArray(usage.state.excluded)) return;
  writeAgentPluginChatState({ conversationId: usage.conversationId, state: usage.state });
}

import type { ChatAttachment } from "../messages.js";

/**
 * @file Restore cached attachment references only after the host confirms their bytes still exist.
 * Drafts persist references separately from text; staged bytes have a host-defined TTL. Dropping
 * an unconfirmed live reference costs a re-drag, while restoring a dead one causes a failed turn.
 * Ref shape, endpoint and probe cap enter through host ports: malformed/excess refs, refusals,
 * network failures and timeouts are discarded, without losing the draft's words.
 * HEAD avoids downloading every attachment to answer a liveness question. The host endpoint must
 * support it (Express routes HEAD through a GET handler when no HEAD handler exists and omits the
 * body); get-chat-attachment-route.test.ts covers the original composed route.
 */







/** In-flight probes. Matches `createDaemonAttachmentUploader`'s own upload concurrency — enough to
 *  hide localhost latency, few enough to leave the page's connection budget alone. */
const DEFAULT_CONCURRENCY = 2;

/** Abort deadline per probe. A restore runs at mount behind the composer, so a wedged request must
 *  not keep a worker (and the operator's attachment chips) pending indefinitely. */
const DEFAULT_TIMEOUT_MS = 10_000;

export interface ChatAttachmentValidatorOptions {
  /** Injected `fetch` for tests; defaults to the page's own. */
  readonly fetchImpl?: typeof fetch;
  /** In-flight probe cap. Defaults to {@link DEFAULT_CONCURRENCY}. */
  readonly concurrency?: number;
  /** Per-probe abort deadline in ms. Defaults to {@link DEFAULT_TIMEOUT_MS}. */
  readonly timeoutMs?: number;
}

/**
 * Whether the server still serves this one reference.
 *
 * @param ref opaque `attachment:<uuid>` capability id (`ChatAttachment.path`).
 * @returns `true` only on a 2xx. Every refusal and every fault answers `false` — the caller cannot
 *   act differently on them, and a probe that could not reach the server has not confirmed anything.
 * @complexity O(1); one request, abandoned after `timeoutMs`.
 */
async function isAttachmentStillServed(ref: string, options: { fetchImpl: typeof fetch; timeoutMs: number; endpoint: (required: { ref: string }, optional: Record<string, never>) => string }): Promise<boolean> {
  try {
    const response = await options.fetchImpl(options.endpoint({ ref }, {}), {
      method: "HEAD",
      credentials: "same-origin",
      signal: AbortSignal.timeout(options.timeoutMs),
    });
    return response.ok;
  } catch {
    // A network fault, an abort, or a same-origin policy refusal. Indistinguishable from here, and
    // all mean the same thing: nothing was confirmed, so the reference does not come back.
    return false;
  }
}

/**
 * Runs `probe` over `refs` with at most `concurrency` in flight, answering positionally.
 *
 * Shared-iterator workers rather than a chunked `Promise.all` loop, for the same reason
 * `createDaemonAttachmentUploader` uses them: a chunked loop stalls the whole batch on its slowest
 * member, and this one runs while the operator is looking at a half-restored composer.
 *
 * @complexity O(n) requests, at most `concurrency` concurrent; O(n) space for the verdicts.
 */
async function probeAll(refs: readonly string[], concurrency: number, probe: (ref: string) => Promise<boolean>): Promise<boolean[]> {
  const verdicts = new Array<boolean>(refs.length).fill(false);
  const entries = refs.entries();
  async function worker(): Promise<void> {
    for (const [index, ref] of entries) {
      verdicts[index] = await probe(ref);
    }
  }
  await Promise.all(Array.from({ length: Math.max(1, Math.min(concurrency, refs.length)) }, worker));
  return verdicts;
}

/**
 * Builds the `validateAttachments` callback `<ChatPane>` calls when it restores a persisted draft.
 *
 * @param input.fetch injected request implementation; the host supplies it explicitly.
 * @param input.endpoint resolves a reference to the host's HEAD-capable read endpoint.
 * @param input.isSupportedRef validates the host's staged-reference grammar before a request.
 * @param input.maxProbedAttachments bounds request fan-out from malformed or hand-edited drafts.
 * @param options.concurrency in-flight probe cap; defaults to {@link DEFAULT_CONCURRENCY}.
 * @param options.timeoutMs per-probe abort deadline; defaults to {@link DEFAULT_TIMEOUT_MS}.
 * @returns a validator taking the cached references and resolving to the subset still served, in
 *   the order they were given. Never rejects: a caller's only sane response to a rejection is to
 *   restore nothing, which is what an empty subset already means.
 * @complexity O(n) requests bounded by input.maxProbedAttachments, at most concurrency at once.
 * @example
 * <ChatPane validateAttachments={createChatAttachmentValidator({ fetch, endpoint, isSupportedRef, maxProbedAttachments })} />
 */
export function createChatAttachmentValidator(
  { fetch, endpoint, isSupportedRef, maxProbedAttachments }: ChatAttachmentValidatorInput,
  options: Omit<ChatAttachmentValidatorOptions, "fetchImpl"> = {},
): (attachments: readonly ChatAttachment[]) => Promise<readonly ChatAttachment[]> {
  const probeOptions = {
    fetchImpl: fetch,
    endpoint,
    timeoutMs: options.timeoutMs ?? DEFAULT_TIMEOUT_MS,
  };
  const concurrency = options.concurrency ?? DEFAULT_CONCURRENCY;

  return async (attachments) => {
    const candidates = attachments
      .slice(0, maxProbedAttachments)
      .filter((candidate) => isSupportedRef({ ref: candidate.path }, {}));
    if (candidates.length === 0) return [];

    const verdicts = await probeAll(
      candidates.map((candidate) => candidate.path),
      concurrency,
      (ref) => isAttachmentStillServed(ref, probeOptions),
    );
    return candidates.filter((_, index) => verdicts[index]);
  };
}

export interface ChatAttachmentValidatorInput {
 readonly fetch: typeof fetch;
 readonly endpoint: (required: { ref: string }, optional: Record<string, never>) => string;
 readonly isSupportedRef: (required: { ref: string }, optional: Record<string, never>) => boolean;
 readonly maxProbedAttachments: number;
}

import type { ChatMessage } from "../messages.js";
import type { RunHandlers } from "../transport.js";
import { translateRunFrame } from "../run-events/entry.js";
import type { RunNotices } from "../run-events/entry.js";

export interface DurableRunBinding { readonly messageId: string; readonly conversationId: string }


export interface DurableSubscriptionPorts {
  /** Absent recover intent preserves legacy recovery; false requests only the saved checkpoint. */
  readonly read: (required: { runId: string; messageId?: string }, optional: { recover?: boolean }) => Promise<ChatMessage | null | "gone">;
  readonly stream: (required: { runId: string; cursor: string; frame: (kind: string, data: string, cursor: string) => void; dropped: (reason?: string) => void }, optional: {}) => () => void;
  readonly schedule: (required: { work: () => void; delayMs: number }, optional: {}) => () => void;
}

type CheckpointHandlers = RunHandlers & { onCheckpoint?: (message: ChatMessage) => void };

/** SSE is a view of one attempt. The saved message owns terminal state and can point at a new
 * attempt after recovery; neither a browser 404 nor a closed stream may fail the logical run.
 * An explicit "gone" result ends observation and releases the caller's streaming state. */
export function followDurableRun(
  { runId: initialRunId, handlers, signal, binding, ports, notices, bindings }: { runId: string; handlers: CheckpointHandlers; signal?: AbortSignal; binding?: DurableRunBinding; ports: DurableSubscriptionPorts; notices: RunNotices; bindings: Map<string, DurableRunBinding> }, { logger = console }: { logger?: Pick<Console, "info"> } = {},
): () => void {
  let streamEpoch = 0;
  let runId = initialRunId;
  let cursor = "";
  let stopped = false;
  let reading = false;
  let recoveryPending = true;
  let dropped = false;
  let reconnectDelayMs = 0;
  let stopStream: (() => void) | undefined;
  let stopTimer: (() => void) | undefined;
  let messageId = binding?.messageId;

  function stop() {
    stopped = true;
    streamEpoch += 1;
    stopStream?.();
    stopTimer?.();
    signal?.removeEventListener("abort", stop);
  }

  function finish(message: ChatMessage) {
    stop();
    handlers.onCheckpoint?.(message);
    if (message.runStatus === "failed" && !handlers.onCheckpoint) handlers.onError(new Error("The assistant could not finish this answer. Saved work is above."));
    handlers.onDone(message.events ?? []);
  }

  function open() {
    const epoch = ++streamEpoch;
    dropped = false;
    stopStream?.();
    stopStream = ports.stream({ runId, cursor,
      frame: (...args) => { if (epoch === streamEpoch) frame(...args); },
      dropped: reason => { if (epoch === streamEpoch) disconnected(reason); },
    }, {});
  }

  /** One timer owns reconnects, including faults during a checkpoint read. No cursor reset. */
  function disconnected(reason = "stream-error") {
    if (stopped || dropped) return;
    dropped = true;
    streamEpoch += 1;
    recoveryPending = true;
    reconnectDelayMs = Math.min(30_000, Math.max(1_000, reconnectDelayMs * 2));
    // Metadata only: neither frame contents nor saved user messages belong in transport logs.
    logger.info("[durable-subscription] " + JSON.stringify({ runId, reason, cursor, retryDelayMs: reconnectDelayMs }));
    stopStream?.();
    if (!reading) scheduleRead();
  }

  function scheduleRead() {
    stopTimer?.();
    stopTimer = ports.schedule({ work: () => void read().catch(() => undefined), delayMs: dropped ? reconnectDelayMs : 1_000 }, {});
  }

  function frame(kind: string, data: string, nextCursor: string) {
    if (stopped) return;
    if (nextCursor) {
      if (nextCursor !== cursor) reconnectDelayMs = 0;
      cursor = nextCursor;
    }
    const outcome = translateRunFrame({ kind, raw: data, notices }, {});
    // An attempt's error/end may be followed by a continuation. Only the row can finalize it.
    if (outcome.terminal || outcome.error) { recoveryPending = true; void read().catch(() => undefined); return; }
    // With the checkpoint-capable hook, render only durable projections. Replaying a daemon
    // prefix into a seeded bubble would duplicate its text; the server folds those deltas once.
    if (handlers.onCheckpoint) return;
    for (const event of outcome.events) handlers.onEvent(event);
  }

  async function read() {
    if (stopped || reading) return;
    reading = true;
    stopTimer?.();
    stopTimer = undefined;
    const recover = recoveryPending;
    // Consume only when a read starts: faults during its await latch one follow-up recovery.
    recoveryPending = false;
    try {
      const message = await ports.read({ runId, ...(messageId ? { messageId } : {}) }, { recover });
      if (stopped || !message) return;
      if (message === "gone") { stop(); handlers.onDone([]); return; }
      applySavedMessage(message);
    } finally {
      reading = false;
      if (!stopped) {
        // Always schedule: an error arriving during read must not create a tight recovery loop.
        scheduleRead();
      }
    }
  }

  function applySavedMessage(message: ChatMessage) {
    messageId = message.id;
    if (["succeeded", "failed", "canceled"].includes(message.runStatus ?? "")) { finish(message); return; }
    handlers.onCheckpoint?.(message);
    if (message.runId && message.runId !== runId) {
      runId = message.runId;
      cursor = "";
      reconnectDelayMs = 0;
      if (binding) bindings.set(runId, binding);
      dropped = true;
    }
    if (dropped) open();
  }

  if (signal?.aborted) return stop;
  signal?.addEventListener("abort", stop);
  open();
  // Polling also covers an attempt that dies before a first frame/connection error arrives.
  stopTimer = ports.schedule({ work: () => void read().catch(() => undefined), delayMs: 1_000 }, {});
  return stop;
}

import { readAgentPluginChatState, captureAgentPluginUsage, type AgentPluginUsage } from '../agent-plugin-chat-state.js';
import { buildTranscript, latestUserPromptFromHistory } from "../transcript.js";
import type { AgentEvent } from "../events.js";
import type { ChatMessage } from "../messages.js";
import type { ChatTransport, ReattachRunOptions, RunHandlers, StartRunInput } from "../transport.js";
import * as runEvents from "../run-events/entry.js";
import type { RunAgentPayload, RunNotices } from "../run-events/entry.js";
import type { AgUiRunClient } from "./ag-ui-transport.js";
import type { DurableRunBinding } from "./durable-run-subscription.js";

/** Per-turn dispatch input; hosts may return their fuller saved settings without UI dependencies. */
export interface AssistantExecutionConfig {
  mode: 'local-cli' | 'byok';
  byok: {
    protocol: 'anthropic' | 'openai' | 'azure' | 'google';
    apiKey: string;
    baseUrl: string;
    model: string;
    maxTokens?: number | undefined;
  };
}

export interface AssistantTransportOptions {
  /**
   * Read fresh on every `startRun` call, never captured once — matching `AssistantDock.tsx`'s own
   * `runContext` convention (see that file's doc on why `frontendBindToken` is read the same way):
   * the operator can flip the runtime picker's mode mid-session, and a captured value would keep
   * routing every later turn through whichever mode was selected when the transport was first
   * built (`AssistantDock.tsx` memoizes the transport once, for the reason its own comment gives —
   * rebuilding it would drop in-flight runs).
   */
  getExecutionConfig?: (required: Record<string, never>, optional: Record<string, never>) => AssistantExecutionConfig;
  /**
   * ADR-059's AG-UI canary toggle — deliberately separate from {@link AssistantExecutionConfig}'s
   * closed `'local-cli' | 'byok'` union so enabling the canary does not extend the host's saved
   * execution modes. Read fresh on every `startRun` call, same "never captured" convention
   * {@link getExecutionConfig} already establishes, for the same reason: an operator can flip this
   * mid-session without rebuilding the memoized transport.
   */
  getAgUiEnabled?: (required: Record<string, never>, optional: Record<string, never>) => boolean;
  /**
   * Agent ids whose own CLI/ACP session already carries multi-turn conversation memory across
   * spawns — `@jini-ai/agent-runtime`'s `resumesSessionViaCli`/`resumesSessionViaAcpLoad`, projected
   * client-safe as `AssistantAgentSummary.carriesOwnMemory` (`assistant/agents.ts` in the host server).
   * {@link runPrompt}'s own doc has the full "used to send only the newest message" background; this
   * option is the inverse regression it introduced for exactly these agents — see `startRun`'s Local
   * CLI branch below, which resends the doc's own contract instead of the full transcript ONLY for an
   * agentId this set contains: "the caller trusts this adapter's CLI to carry its own multi-turn
   * conversation memory... and should skip resending the rendered transcript on follow-up turns"
   * (`types.ts`). Resending it anyway would duplicate everything the daemon's own `--resume`/
   * `session/load` already restores (`agent-session-resume.ts`).
   *
   * Read fresh on every `startRun` call, same "never captured" convention {@link getExecutionConfig}/
   * {@link getAgUiEnabled} already establish: the admin's own `/api/agents` probe resolves
   * asynchronously and can still be in flight when this transport is first built, and an operator can
   * switch the Local CLI agent pick mid-session.
   *
   * Omitted, or an agentId absent from the returned set, keeps today's behavior — the full transcript
   * is sent. That is the SAFE default for a def this option's source has not resolved as resume-capable
   * yet: sending redundant history to a resume-capable def costs extra tokens, but withholding history
   * from a stateless def would silently erase its memory — the two failure directions are not
   * symmetric, so "unknown" must resolve to "send everything," not to "send only the latest message."
   */
  getResumeCapableAgentIds?: (required: Record<string, never>, optional: Record<string, never>) => ReadonlySet<string>;
  /**
   * This pane's conversation id, adopting one if none is active yet —
   * `useAssistantChats.ensureConversationId` (`hooks/use-assistant-chats.hooks.ts`), wired through
   * `AssistantDock`'s `useAssistantTransport`. Awaited by `startRun` ONLY when `input.context` names
   * no conversation, which in practice means the first turn of a chat.
   *
   * Why the transport has to be the one to ask: the admin adopts a conversation lazily, from the
   * first message delta — and `@jini-ai/chat`'s `useChatPane.sendPrompt` freezes `runContext(...)`
   * into `input.context` BEFORE calling `conversation.sendMessage(...)`, the very call that produces
   * that delta. So on turn 1 there is no id to capture yet, and `runContext` (synchronous by
   * contract) has no way to wait for one. `startRun` is the last point in the chain that can still
   * `await`, which makes it the only place the run can acquire the identity its agent-CLI session id
   * gets filed under. Without it, `agent-daemon-server.ts`'s `onStarted` skipped its entire
   * session-capture subscription for turn 1, and turn 2 — sent only the bare latest user message,
   * trusting a resume that had nothing stored — answered with none of the conversation.
   *
   * Contract: resolves `null` rather than rejecting when creation fails. `startRun` treats that as
   * "send the turn anyway, with no conversationId" — one run with no resumable session is a far
   * smaller loss than a run that never happens.
   */
  ensureConversationId?: (required: Record<string, never>, optional: Record<string, never>) => Promise<string | null>;
  /**
   * Writes one user message to durable storage — `useAssistantChats.persistUserTurn`
   * (`hooks/use-assistant-chats.hooks.ts`), wired through `AssistantDock`'s `useAssistantTransport`.
   * Awaited by `startRun` on the Local CLI path before `POST /api/runs`, including a delta's pending
   * PUT. Acceptance persists the same message with its stub if the browser write fails. See
   * {@link persistUserTurnBeforeDispatch} for the defect and the idempotency contract.
   *
   * Optional for transports without the dock's persistence hook; acceptance still receives the
   * exact user message, and the delta-driven `flush` can write the same ID afterward.
   * Its rejection is swallowed at the call site rather than failing the turn.
   */
  persistUserTurn?: (required: { conversationId: string; message: ChatMessage }, optional: Record<string, never>) => Promise<void>;
}

export interface AssistantTransportPorts {
 readonly runsUrl: string; readonly byokTurnUrl: string; readonly byokRunIdPrefix: string; readonly notices: RunNotices;
 readonly fetch: typeof fetch;
 readonly mintId: (required: Record<string, never>, optional: Record<string, never>) => string;
 readonly projectPrompt: (required: { prompt: string; context: StartRunInput["context"] }, optional: Record<string, never>) => string;
 readonly projectInput: (required: { input: StartRunInput }, optional: Record<string, never>) => StartRunInput;
 readonly bindRun: (required: { runId: string; binding: DurableRunBinding }, optional: Record<string, never>) => void;
 readonly runBinding: (required: { runId: string }, optional: Record<string, never>) => DurableRunBinding | undefined;
 readonly followRun: (required: { runId: string; handlers: RunHandlers; signal?: AbortSignal }, optional: Record<string, never>) => void;
 readonly acceptRun: (required: { body: unknown; signal?: AbortSignal; requestSignal?: AbortSignal; messageId: unknown; conversationId?: string }, optional: Record<string, never>) => Promise<Response>;
 readonly agUi: AgUiRunClient;
}

export interface ByokFrameContext { collected: AgentEvent[]; handlers: RunHandlers; finish: () => void }
export interface ByokStreamContext extends ByokFrameContext { runId: string; controller: AbortController }
export interface AssistantTransportClient {
  createAssistantTransport(required: { options?: AssistantTransportOptions }, optional?: Record<string, never>): ChatTransport;
  historyForTranscript(required: { history: readonly ChatMessage[] }, optional?: Record<string, never>): ChatMessage[];
  undeliveredUserPrompt(required: { history: readonly ChatMessage[] }, optional?: Record<string, never>): string;
  buildLocalCliContextRef(required: { input: StartRunInput; prompt: string; resolvedConversationId?: string }, optional?: Record<string, never>): Record<string, unknown>;
  handleByokFrame(required: { frame: { event: string; data: string }; ctx: ByokFrameContext }, optional?: Record<string, never>): void;
  consumeByokStream(required: { body: ReadableStream<Uint8Array>; ctx: ByokStreamContext }, optional?: Record<string, never>): Promise<void>;
}
/** Bind transport effects once; in-flight controllers belong to this client, never the package.
 * Positional run methods implement the existing ChatTransport contract. */
export function createAssistantTransportClient({ ports }: { ports: AssistantTransportPorts }, _options: Record<string, never> = {}): AssistantTransportClient {
  const asString = (value: unknown) => runEvents.asString({ value }, {});
  const readSseFrames = (body: ReadableStream<Uint8Array>) => runEvents.readSseFrames({ body }, {});
  const readTerminalReason = (raw: string | undefined, wrapped: boolean) => runEvents.readTerminalReason({ raw, wrapped }, {});
  const terminalReasonNotice = (reason: string) => runEvents.terminalReasonNotice({ reason, notice: ports.notices.toolStepLimit }, {});
  const translateRunAgentPayload = (payload: RunAgentPayload) => runEvents.translateRunAgentPayload({ payload }, {});

  /**
   * Shared HTTP implementation of `@jini-ai/chat/react`'s `ChatTransport` port (originally ADR-049).
   *
   * TWO run paths live here, selected per-turn by `getExecutionConfig()` (see
   * `createAssistantTransport`'s own doc):
   *
   * 1. **Local CLI** (the original, unchanged path): binds to the real `@jini-ai/http` run surface
   *    `src/server/modules/assistant.ts` mounts — `POST /api/runs` to start, `GET
   *    /api/runs/:runId/events` (native `EventSource`) to stream, `GET /api/runs/:runId` for status,
   *    `POST /api/runs/:runId/cancel` to stop. Every SSE frame's `data` is a full `@jini-ai/protocol`
   *    `RunProtocolEvent` (`{kind, payload, ...}`), not chat-core's own `AgentEvent` — chat-core's own
   *    module doc is explicit that this reduction is a transport concern ("a host's transport adapter
   *    is responsible for reducing wire deltas... into the persisted/renderable AgentEvent items"), so
   *    `translateRunAgentPayload` below does that translation.
   * 2. **API · BYOK** (2026-08-04, ADR-049's picker): binds to `src/server/modules/assistant-byok.ts`'s
   *    `POST /api/admin/v1/assistant/byok-turn` — one request/response holding the WHOLE turn open,
   *    no separate `EventSource`/reattach/cancel-by-runId (see that route's own header for why, and
   *    what it costs). Its SSE frames carry the SAME `payload.type` vocabulary
   *    (`status`/`text_delta`/`tool_use`/`tool_result`/`usage`/`error`) `translateRunAgentPayload`
   *    already parses for path 1 — deliberately, so this path reuses that exact function rather than
   *    duplicating the translation switch.
   *
   * `text_delta`/`thinking_delta` are forwarded as their own small `AgentEvent` per delta (not
   * accumulated here) — chat-core's own `ChatMessage.events` array is what concatenates them into one
   * growing message, so accumulating twice would double the text.
   */

  /** Distinguishes a BYOK-run id (client-minted, no server-side run record) from a daemon-run id
   *  (server-minted, reattachable) wherever a bare `runId` string is all a `ChatTransport` method
   *  receives — see `stopRun`/`fetchRunStatus`/`reattachRun` below for why the distinction matters. */
  const BYOK_RUN_ID_PREFIX = ports.byokRunIdPrefix;

  /**
   * How many trailing messages of a conversation go to the agent.
   *
   * A cap rather than none: each turn cold-boots a fresh subprocess and pays for its whole input, so
   * an uncapped transcript makes every message in a long chat more expensive than the last. 40 is
   * roughly 20 exchanges — beyond what a working session usually needs to stay coherent, and far
   * short of where input cost starts to dominate. `buildTranscript` separately truncates any single
   * oversized message, so this bounds the number of turns, not their size.
   */
  const MAX_TRANSCRIPT_TURNS = 40;

  // The daemon-stream translation (`translateRunAgentPayload`, the terminal notices, `translateRunFrame`)
  // lives in `@jini-ai/chat/core/run-events`, extracted from the host's 2026-09-27 contract, so the API's
  // run finalizer saves exactly what this transport would have. Re-exported here so existing importers
  // and tests keep their paths.

  /**
   * The prompt for one run: the whole conversation so far, not just the newest message.
   *
   * This used to send only the latest user turn, which is why the assistant appeared to have no
   * memory — ask it something, then ask a follow-up, and the second run had never seen the first.
   * That looked like a missing capability and was not: `ChatPane` hands the full history to every
   * `startRun`, and it was being discarded here, in the browser, before the request was even built.
   * Nothing server-side had to change.
   *
   * `buildTranscript` rather than a hand-rolled join, because flattening a transcript has more edges
   * than it first appears: it truncates any single oversized message, escapes `## user`/`## assistant`
   * inside message bodies so a user cannot forge a turn boundary by pasting one, summarizes persisted
   * artifacts instead of replaying them, and prepends a warning when prior-run telemetry shows the
   * context was already large. Every admin turn cold-boots a fresh CLI subprocess, so the transcript
   * IS the memory — and the same property makes an unbounded one expensive.
   *
   * Bounded deliberately: each run is billed, and an unbounded transcript grows the input cost of
   * every subsequent turn in a conversation that has no natural end. {@link MAX_TRANSCRIPT_TURNS}
   * keeps a long-running chat from silently becoming the most expensive thing in the product.
   * Failed turns are labeled outcomes so another agent can explain and recover from them.
   */
  function runPrompt(history: StartRunInput["history"]): string {
    const recent = history.slice(-MAX_TRANSCRIPT_TURNS).map(message => {
      if (message.role !== 'assistant' || isAnsweredAssistantTurn(message)) return message;
      const detail = message.events?.filter(event => event.kind === 'status')
        .map(event => [event.label, event.detail].filter(Boolean).join(': ')).join('\n').slice(-4000);
      // Reserve space for the failure reason even when partial output fills the transcript cap.
      const outcome = [message.content.slice(0, 6000), detail].filter(Boolean).join('\n\n');
      return { ...message, content: `[${message.agentName ?? message.agentId ?? 'Assistant'} run ${message.runStatus}; not a completed answer]\n${outcome || 'No assistant reply was produced.'}` };
    });
    return buildTranscript({ history: recent });
  }

  /**
   * Whether an assistant message represents a turn the agent actually answered — the single
   * definition both {@link historyForTranscript} and {@link undeliveredUserPrompt} key off.
   *
   * `undefined` counts as answered: rows written before `ai_chat_messages.run_status` existed carry
   * no status at all, and treating those as unanswered would re-send the whole history of every
   * legacy conversation on its next turn. Every non-`succeeded` status counts as unanswered —
   * `failed` and `canceled` obviously, and `queued`/`running` because a run killed mid-flight (a
   * daemon respawn, see `daemon-supervisor.ts`) never reaches a terminal status at all and leaves
   * exactly such a row behind.
   *
   * Do not "simplify" this away by deleting the failed rows at the source instead. That was the first
   * shape proposed for this fix and it is the wrong trade: `run_status='failed'` was ALREADY the
   * explicit failed state, and the only thing missing was somewhere that skips it. The row's
   * `events_json` is the sole durable record of why a run died (exit code, signal, the CLI's own
   * stderr) once the daemon's in-memory event log is gone, and the pane renders it on reload — so
   * dropping the row trades a history bug for a forensics hole. The skip belongs here, on the read
   * side. The transcript's hidden-tool mode likewise filters only recovered tool failures and keeps
   * unrecovered failures behind a compact disclosure; it never deletes this durable evidence.
   * See {@link historyForTranscript} and `assistant-chats.ts`'s `persistableMessages`.
   */
  function isAnsweredAssistantTurn(message: ChatMessage): boolean {
    return message.runStatus === undefined || message.runStatus === "succeeded";
  }

  /**
   * The history a transcript may be built from: every user turn, and only those assistant turns the
   * agent actually answered.
   *
   * Defect 3 of the 2026-09-11 chat-lifecycle repair. `ai_chat_messages` in
   * the investigated host's `chat.db` holds assistant rows with `run_status='failed'` and
   * `length(content)=0` — the durable trace of a run that died before writing a token. Replayed
   * through `buildTranscript` they become a `## assistant` block with nothing under it: the next run
   * is told the agent replied when what actually happened is that it died, and a failure the user can
   * see in the pane is laundered into an empty answer in the model's context.
   *
   * The rows themselves are deliberately NOT deleted, and this is the fix instead: their
   * `events_json` carries the only surviving record of why the run failed (exit code, signal, the
   * CLI's own stderr), the daemon's event log is in-memory and gone, and the pane renders that notice
   * on reload. Partial output from a failed run stays stored as partial output for the same reason —
   * it is visible to the user, and it is not the agent's answer, so it does not go back into a prompt.
   *
   * @param history - The pane's transcript, oldest first.
   * @returns A new array; the input is never mutated.
   * @complexity O(n) in history length, one pass, no allocation per message.
   */
  function historyForTranscript(history: readonly ChatMessage[]): ChatMessage[] {
    return history.filter((message) => message.role !== "assistant" || isAnsweredAssistantTurn(message));
  }

  /**
   * Prepended when more than one user turn is being sent at once, so the agent is not told the user
   * typed all of it just now. Deliberately absent from the single-turn case — a note on every
   * ordinary message would be a standing lie in the prompt of every turn in every conversation.
   */
  const UNDELIVERED_TURNS_NOTE =
    "[Some of the messages below never reached you: the run that should have answered them failed before it could. Treat them as the user's own words, in order, and answer all of them.]";

  /**
   * The user text a run must carry when the agent carries its own conversation memory: every user
   * turn since the last one the agent actually answered, not only the newest.
   *
   * Defect 2 of the 2026-09-11 chat-lifecycle repair, and the half of it that was actually lossy. In
   * the investigated host's `chat.db` conversation `9289701c-…`, position 5's user text is present in
   * `ai_chat_messages` and absent from every agent-session transcript: the run meant to answer it
   * failed 140 ms after start, so no CLI ever read it — and because
   * {@link resolveLocalCliPrompt} sends only the NEWEST user turn to a resume-capable agent, no later
   * turn ever carried it either. The message was durable the whole time and still lost, permanently,
   * with nothing anywhere saying so.
   *
   * Re-delivering costs a duplicate whenever the CLI did read the prompt before dying, which the
   * agent can reconcile from its own session. Not re-delivering costs the user a message with no
   * trace. The two are not symmetric, so this errs toward the duplicate.
   *
   * @param history - The pane's transcript, oldest first.
   * @returns The prompt text — the bare newest turn in the ordinary case (the previous turn was
   *   answered), or the unanswered turns joined oldest-first behind {@link UNDELIVERED_TURNS_NOTE}.
   *   Falls back to the newest user turn when the history ends in an answered assistant turn and
   *   there is therefore nothing pending.
   * @complexity O(n) in history length — one forward scan for the boundary plus one slice/filter over
   *   the tail. A backwards scan with an early exit would be O(1) in practice but needs `break`, and
   *   `n` here is bounded by one conversation's transcript; this is not a hot path (once per turn).
   *   The result is capped at {@link MAX_TRANSCRIPT_TURNS} for the pathological case of a
   *   conversation whose every run has failed.
   */
  function undeliveredUserPrompt(history: readonly ChatMessage[]): string {
    // `Array.prototype.findLastIndex` would say this in one call, but it is ES2023 and the
    // supported target is ES2022, so the index is accumulated instead.
    let lastAnsweredIndex = -1;
    history.forEach((message, position) => {
      if (message.role === "assistant" && isAnsweredAssistantTurn(message)) lastAnsweredIndex = position;
    });

    const pending = history
      .slice(lastAnsweredIndex + 1)
      .filter((message) => message.role === "user")
      .slice(-MAX_TRANSCRIPT_TURNS);

    if (pending.length === 0) return latestUserPromptFromHistory({ history: history as ChatMessage[] });
    const newest = pending[pending.length - 1] as ChatMessage;
    const newestText = newest.content.trim();
    const newestAttachmentRefs = JSON.stringify((newest.attachments ?? []).map((attachment) => attachment.path));
    // Collapse resends of the newest text with matching attachment refs: a retry is one request.
    const distinct = pending.filter((message, index) => index === pending.length - 1
      || message.content.trim() !== newestText
      || JSON.stringify((message.attachments ?? []).map((attachment) => attachment.path)) !== newestAttachmentRefs)
      .map((message) => message.content);
    if (distinct.length === 1) return distinct[0] as string;
    return `${UNDELIVERED_TURNS_NOTE}\n\n${distinct.join("\n\n")}`;
  }

  /** `@jini-ai/protocol`'s `RunState` -> chat-core's flat `RunStatus` union (different spelling: `cancelled` vs `canceled`, `pending` vs `queued`). */
  function toChatCoreRunStatus(state: string): "queued" | "running" | "succeeded" | "failed" | "canceled" | undefined {
    switch (state) {
      case "pending":
        return "queued";
      case "running":
        return "running";
      case "succeeded":
        return "succeeded";
      case "failed":
        return "failed";
      case "cancelled":
        return "canceled";
      default:
        return undefined;
    }
  }

  /** The durable message owns recovery and terminal state; this subscription follows replacement
   * attempts without writing a browser-inferred failure into history. */
  function subscribeToRun(runId: string, handlers: RunHandlers, signal?: AbortSignal): void {
    ports.followRun({ runId, handlers: capturePluginUsage(handlers), ...(signal === undefined ? {} : { signal }) }, {});
  }

  /** The well-formed plugin usage an `agent_plugins` extension event carries, or `undefined` for any
   * other event — the one validity rule both live events and checkpoint replays are captured by. */
  function pluginUsageOf({ event }: { event: AgentEvent }, _optional: Record<string, never>): AgentPluginUsage | undefined {
    if (event.kind !== 'ext' || event.name !== 'agent_plugins') return undefined;
    const usage = event.data as AgentPluginUsage | undefined;
    return typeof usage?.conversationId === 'string' && usage.state && Array.isArray(usage.state.excluded) ? usage : undefined;
  }

  /** Capture before notifying the UI so answers received after reload persist for the next turn.
   * Checkpoint panes skip live deltas to avoid duplicate text, so capture their saved events here
   * too. Keep this wrapper as the single capture owner for both delivery contracts.
   * @complexity O(e + s) per checkpoint; O(s) per live event, in saved events and plugin-state size.
   */
  function capturePluginUsage(handlers: RunHandlers): RunHandlers {
    const captured = new Map<string, string>();
    const capture = (event: AgentEvent) => {
      const usage = pluginUsageOf({ event }, {});
      if (!usage) return;
      const state = JSON.stringify(usage.state);
      if (captured.get(usage.conversationId) === state) return;
      captured.set(usage.conversationId, state);
      captureAgentPluginUsage({ event });
    };
    return {
      ...handlers,
      onEvent: event => { capture(event); handlers.onEvent(event); },
      ...(handlers.onCheckpoint ? { onCheckpoint: (message: ChatMessage) => {
        // Historical answers must not roll the current state backwards on every poll.
        const latest = new Map<string, AgentEvent>();
        for (const event of message.events ?? []) {
          const usage = pluginUsageOf({ event }, {});
          if (usage) latest.set(usage.conversationId, event);
        }
        for (const event of latest.values()) capture(event);
        handlers.onCheckpoint!(message);
      } } : {}),
    };
  }

  /** Client-minted, not server-minted — see module doc's path-2 section: a BYOK run has no server-side
   *  run record to name it. Prefixed so `stopRun`/`fetchRunStatus`/`reattachRun` below can tell a
   *  BYOK-run id apart from a daemon-run id without any other context. */
  function mintByokRunId(): string { return `${BYOK_RUN_ID_PREFIX}${ports.mintId({}, {})}`; }

  /** In-flight BYOK turns' abort controllers, keyed by the client-minted runId — the ONLY way
   *  `stopRun` can cancel a BYOK turn: unlike the daemon path, there is no server-side run record to
   *  `POST .../cancel` against, so cancellation has to reach back into THIS tab's own in-flight
   *  `fetch`. Entries are removed as soon as a turn settles (normally, on error, or on abort) so a
   *  stale id can never resurrect a finished controller. */
  const byokAbortControllers = new Map<string, AbortController>();

  /**
   * Dispatches one parsed BYOK SSE frame to the right `RunHandlers` call — the `"agent"`/`"error"`/
   * `"end"` handling pulled out of `startByokRun`'s stream-consumer IIFE (2026-08-06, complexity
   * pass), where it sat four levels of nesting deep (async IIFE > `try` > `for await` > `if`/
   * `else if`, with a further nested `if` inside the `"agent"` and `"end"` cases). At module scope it
   * is a single, independently testable function: a plain `{event, data}` frame in, a fake
   * `RunHandlers` to assert against, no `ReadableStream`/`fetch`/timers required.
   *
   * @param ctx.collected - This turn's running event log — the same array `startByokRun` hands to
   *   `handlers.onDone` once the stream ends.
   * @param ctx.finish - `startByokRun`'s own idempotent finish (closes out the turn, deletes its abort
   *   controller, calls `onDone`). Called on `"end"`, exactly as the inline version did.
   */
  function handleByokFrame(
    frame: { event: string; data: string },
    ctx: ByokFrameContext,
  ): void {
    if (frame.event === "agent") {
      const payload = JSON.parse(frame.data) as RunAgentPayload;
      const translated = translateRunAgentPayload(payload);
      if (translated) {
        ctx.collected.push(translated);
        ctx.handlers.onEvent(translated);
      }
    } else if (frame.event === "error") {
      const payload = JSON.parse(frame.data) as { message?: unknown };
      ctx.handlers.onError(new Error(asString(payload.message) || "BYOK turn failed"));
    } else if (frame.event === "end") {
      const notice = terminalReasonNotice(readTerminalReason(frame.data, false));
      if (notice) {
        ctx.collected.push(notice);
        ctx.handlers.onEvent(notice);
      }
      ctx.finish();
    }
  }

  /**
   * Drains a BYOK turn's SSE body to completion, dispatching each frame via {@link handleByokFrame}
   * and settling the turn through `ctx.finish` — the async IIFE `startByokRun` used to hold its
   * stream-consumer loop in, pulled out to a top-level function (2026-08-06, complexity pass, second
   * pass). `startByokRun`'s own per-function score is already under the per-function ceiling; this
   * split is for the OTHER metric this repo's complexity ceiling tracks — a tool that rolls a nested
   * closure's branches into its enclosing function's total still counted this IIFE as part of
   * `startByokRun` as long as it stayed physically inside the body. Moving it to a sibling top-level
   * function removes it from that rollup instead of just moving it to a different nested scope (a
   * `const` inside `startByokRun` would not have changed the rollup at all).
   *
   * @param ctx.runId - Only used to clear {@link byokAbortControllers} on a genuine (non-abort)
   *   failure — the abort path itself already deletes its own entry in `startByokRun` before this
   *   runs, so `ctx.runId` here is scoped to the error branch alone.
   * @param ctx.controller - Read only for `.signal.aborted`, to tell a deliberate `stopRun`/composer
   *   abort apart from a real stream failure — same distinction the inline version drew.
   */
  async function consumeByokStream(
    body: ReadableStream<Uint8Array>,
    ctx: ByokStreamContext,
  ): Promise<void> {
    try {
      for await (const frame of readSseFrames(body)) {
        handleByokFrame(frame, { collected: ctx.collected, handlers: ctx.handlers, finish: ctx.finish });
      }
      ctx.finish();
    } catch (error) {
      byokAbortControllers.delete(ctx.runId);
      if (ctx.controller.signal.aborted) {
        // Cancelled via `stopRun` or the composer's own signal — an expected exit, not a reportable
        // failure. `subscribeToRun`'s `EventSource` has no equivalent branch because `.close()`
        // doesn't reject a promise the way an aborted `fetch`'s body reader does; this mirrors what a
        // cancelled daemon run already looks like to the rest of the pane: silence, not an error toast.
        ctx.finish();
        return;
      }
      // Error THEN finish, same order and same reason as `subscribeToRun`'s `end` listener: reporting
      // alone left the turn unsettled (no `onDone`, so the events collected before the failure were
      // never persisted), and finishing first would record the dead run as succeeded.
      ctx.handlers.onError(error instanceof Error ? error : new Error(String(error)));
      ctx.finish();
    }
  }

  /**
   * The provider-bound history of one BYOK turn: only turns the agent actually answered, never an
   * empty one, each carrying its redaction signal.
   */
  function byokMessages({ history }: { history: readonly ChatMessage[] }, _optional: Record<string, never>): Array<Record<string, unknown>> {
    // `historyForTranscript` first (Defect 3, 2026-09-11): the empty-content filter below already
    // hides a failed run that produced nothing, but NOT one that emitted a few tokens before dying —
    // that partial output would be sent to the provider as if it were the assistant's answer. This is
    // the same defect as on the Local CLI path, reachable by a second route.
    return historyForTranscript(history)
      .filter((message) => message.content.trim().length > 0)
      .map((message) => ({ role: message.role, content: message.content,
        ...(message.secretRedaction?.secretRedacted ? { secretRedacted: true } : {}),
      }));
  }

  /** The credential block of a BYOK turn; an empty base URL and an unset token cap are omitted. */
  function byokCredentials({ byok }: { byok: AssistantExecutionConfig["byok"] }, _optional: Record<string, never>): Record<string, unknown> {
    return {
      protocol: byok.protocol,
      apiKey: byok.apiKey,
      ...(byok.baseUrl ? { baseUrl: byok.baseUrl } : {}),
      model: byok.model,
      ...(byok.maxTokens !== undefined ? { maxTokens: byok.maxTokens } : {}),
    };
  }

  /** The JSON body `POST byokTurnUrl` carries for one turn. */
  function byokTurnBody(
    { input, byok }: { input: StartRunInput; byok: AssistantExecutionConfig["byok"] },
    _optional: Record<string, never>,
  ): Record<string, unknown> {
    return {
      messages: byokMessages({ history: input.history }, {}),
      ...attachmentIdsField(input),
      ...conversationIdField(input),
      agentPluginState: input.context?.["agentPluginState"],
      userPrompt: input.context?.["userPrompt"],
      ...pluginRefIdsField(input),
      // The admin screen, as on the Local CLI path (`buildLocalCliContextRef`): the server puts it
      // in front of the newest message so a BYOK turn knows the open page and where drawings go.
      ...pageContextField(input),
      byok: byokCredentials({ byok }, {}),
    };
  }

  /**
   * The error for a refused request: `<action> (<status>)`, plus up to 300 characters of the
   * response body when it has one — shared by the BYOK start, Local CLI start and cancel refusals.
   */
  async function refusalError({ action, response }: { action: string; response: Response }, _optional: Record<string, never>): Promise<Error> {
    // A response whose body stream errors out (e.g. a dropped connection) must not turn "the server
    // rejected the request" into "the client crashed reading the rejection".
    const detail = await response.text().catch(() => "");
    return new Error(`${action} (${response.status})${detail ? `: ${detail.slice(0, 300)}` : ""}`);
  }

  /**
   * The BYOK run path (2026-08-04) — one held-open `POST` to `assistant-byok.ts`, no separate
   * `EventSource`/reattach. See module doc's path-2 section for why this shape differs from
   * `subscribeToRun`'s daemon-path pattern, and what it costs (no reattach after a reload; `stopRun`
   * works via the abort-controller map above instead of a server-side cancel endpoint).
   *
   * @complexity Dominated by the network/stream cost of the turn itself; per-frame parsing is O(1).
   * @overallScore 100
   */
  async function startByokRun(
    input: StartRunInput,
    handlers: RunHandlers,
    byok: AssistantExecutionConfig["byok"],
  ): Promise<{ runId: string }> {
    const runId = mintByokRunId();
    const controller = new AbortController();
    byokAbortControllers.set(runId, controller);
    // Conversation adoption may have yielded while the subscription was torn down.
    if (input.signal?.aborted) controller.abort();
    else input.signal?.addEventListener("abort", () => controller.abort());

    let response: Response;
    try {
      response = await ports.fetch(ports.byokTurnUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify(byokTurnBody({ input, byok }, {})),
        signal: controller.signal,
      });
    } catch (error) {
      byokAbortControllers.delete(runId);
      throw error instanceof Error ? error : new Error(String(error));
    }

    if (!response.ok || !response.body) {
      byokAbortControllers.delete(runId);
      throw await refusalError({ action: "BYOK turn failed to start", response }, {});
    }

    const collected: AgentEvent[] = [];
    let settled = false;
    const finish = () => {
      if (settled) return;
      settled = true;
      byokAbortControllers.delete(runId);
      handlers.onDone(collected);
    };

    // Deliberately not awaited: `startRun`'s contract (matching the daemon path immediately above)
    // is to resolve `{runId}` once the turn has STARTED, not once it has finished — the response
    // headers (hence this function reaching this point at all) arrive as soon as
    // `assistant-byok.ts` calls `beginStream`, well before generation completes.
    void consumeByokStream(response.body, { runId, collected, handlers, finish, controller });

    return { runId };
  }

  /**
   * Which browser tab a Local CLI run should be allowed to drive, from `ChatPane`'s `runContext` prop
   * (`AssistantDock.tsx` supplies it from the live `FrontendSessionBridge`).
   *
   * Read by name rather than spreading the whole `input.context` blob: `contextRef` is a shared
   * envelope that the host's proxy also writes `principalId` into (`src/server/modules/assistant.ts`),
   * and a spread would let any future `runContext` key silently shadow it — an identity field being
   * overwritten by a UI prop is not a failure mode worth leaving open to save one line.
   *
   * Returns `{}` (omitting the field entirely) when absent, which is a normal state, not an error:
   * the daemon treats a run with no bind token as one with no screen to drive
   * (`agent-daemon-server.ts`).
   */
  function frontendBindTokenField(input: StartRunInput): Record<string, unknown> {
    const frontendBindToken = input.context?.["frontendBindToken"];
    return typeof frontendBindToken === "string" && frontendBindToken.length > 0 ? { frontendBindToken } : {};
  }

  /**
   * The Local CLI picker's live model selection, from `ChatPane`'s `runContext` prop
   * (`AssistantDock.tsx`'s `resolveRunContext`). Same "read by name, not spread" reasoning as
   * {@link frontendBindTokenField} above, and the same "omit when absent" convention. Forwarded as an
   * opaque string — `agent-daemon-server.ts` forwards it the same way, and `AgentExecutor.run()`'s
   * def-level `buildArgs` is what decides what an absent or `'default'` value means for a given CLI
   * (`@jini-ai/agent-runtime`'s `models.ts`/`resolveModelForAgent`).
   */
  function modelField(input: StartRunInput): Record<string, unknown> {
    const model = input.context?.["model"];
    return typeof model === "string" && model.length > 0 ? { model } : {};
  }

  /**
   * The Execution tab's "Reasoning effort" pick, from the same `runContext` seam as {@link modelField}
   * above and forwarded with the identical "opaque string, omit when absent" convention. What turns it
   * into real argv is the def's own `buildArgs` on the daemon side (`claude --effort <level>`, codex's
   * `-c model_reasoning_effort=...`) — nothing here interprets it, and a runtime whose effort is
   * encoded in the model id (antigravity) never sends it at all, because its level is already inside
   * `model`.
   */
  function reasoningField(input: StartRunInput): Record<string, unknown> {
    const reasoning = input.context?.["reasoning"];
    return typeof reasoning === "string" && reasoning.length > 0 ? { reasoning } : {};
  }

  /**
   * Opaque `attachment:<uuid>` capability ids (`ChatAttachment.path` — never a real filesystem path
   * this early; see `@jini-ai/http-kit`'s `attachments.ts` trust-model doc), not the attachments
   * themselves — `contextRef` is the one channel `prompt`/`frontendBindToken` already ride on to reach
   * `agent-daemon-server.ts`'s `onStarted`, which is where these ids get exchanged for real,
   * re-validated paths via `AttachmentStore.claim()`. Nothing on this side of the wire is trusted; the
   * id is inert until the daemon claims it.
   *
   * Returns `{}`, same convention as {@link frontendBindTokenField} above — a run with no attachments
   * is the overwhelmingly common case and should not carry a key for it.
   */
  function attachmentIdsField(input: StartRunInput): Record<string, unknown> {
    return input.attachments && input.attachments.length > 0
      ? { attachmentIds: input.attachments.map((attachment) => attachment.path) }
      : {};
  }

  /**
   * Opaque Agent Plugin ids (`plugin.json`'s own `name`, e.g. `"ui-ux-design"`) the operator has
   * pinned as composer chips — `AssistantDock.tsx`'s `useSelectedAgentPlugins`, threaded here via
   * `ChatPane`'s `runContext` prop the same way {@link frontendBindTokenField}/{@link modelField}
   * above already are. Same "read by name, not spread" and "omit when absent" conventions as those
   * two fields: this is not the plugin's CONTENT, only a reference to it —
   * `agent-daemon-server.ts`'s `onStarted` is where a ref gets resolved against the real installed
   * package on disk and its own text prepended to the prompt (see that function's own doc for the
   * resolution/failure rules). Filtered to non-empty strings for the same reason `attachmentIds` is
   * filtered on the decode side (`run-start-context.ts`'s `parseRunStartContextRef`) — this is the
   * encode side of the same wire value, and a malformed entry here should not silently become a
   * malformed one there.
   */
  function pluginRefIdsField(input: StartRunInput): Record<string, unknown> {
    const pluginRefIds = input.context?.["pluginRefIds"];
    if (!Array.isArray(pluginRefIds)) return {};
    const filtered = pluginRefIds.filter((id): id is string => typeof id === "string" && id.length > 0);
    return filtered.length > 0 ? { pluginRefIds: filtered } : {};
  }

  /**
   * The active conversation id, from `ChatPane`'s `runContext` prop (`AssistantDock.tsx`'s
   * `chats.activeId`, the same `useRunContext` seam {@link frontendBindTokenField}/{@link modelField}/
   * {@link pluginRefIdsField} above already ride). Lets `agent-daemon-server.ts`'s `onStarted` resume
   * this conversation's agent-CLI session across turns instead of spawning cold every time
   * (`server/inbound/assistant/agent-session-resume.ts`) — see that file's own doc. Returns `{}`, same
   * convention as every other optional field here: a run started before any conversation exists yet
   * (or from a future daemon client that never sends one) just gets no session-resume behavior, not
   * an error.
   */
  function conversationIdField(input: StartRunInput, resolvedConversationId?: string): Record<string, unknown> {
    const conversationId = resolvedConversationId ?? input.context?.["conversationId"];
    return typeof conversationId === "string" && conversationId.length > 0 ? { conversationId } : {};
  }

  /**
   * The admin screen this message was sent from (`lib/agent-screen-context.ts`, read by
   * `AssistantDock.hooks.tsx`'s `useRunContext` at send time), so the agent knows what "this page"
   * means. Forwarded as-is when it is a plain object — the daemon's `run-page-context.ts` owns
   * validating and capping its fields, the same split `attachmentIds` has — and omitted otherwise.
   */
  function pageContextField(input: StartRunInput): Record<string, unknown> {
    const pageContext = input.context?.["pageContext"];
    return typeof pageContext === "object" && pageContext !== null && !Array.isArray(pageContext) ? { pageContext } : {};
  }

  /**
   * Assembles the Local CLI path's `contextRef` — everything `startRun`'s daemon branch sends besides
   * `agentId` itself. Pulled out of `startRun` (2026-08-06, complexity pass, second pass) as its own
   * pure function, then split again (2026-09-04, complexity pass) into one pure field-helper per
   * optional field, each above: six independent, unrelated fields, none sharing state or order
   * dependence, each read from `input` by name and included only when present (see each helper's own
   * doc for why). Kept as six separate functions rather than grouped, on purpose — the fields have no
   * conceptual relationship to group them by (identity, execution config, and content all mixed
   * together), and inventing a grouping would obscure the very independence each field's own doc
   * argues for. A plain object in, a plain object out — directly testable with a `StartRunInput`
   * fixture, no `fetch`/`EventSource` involved.
   *
   * @param prompt - The already-built transcript string ({@link runPrompt}'s result) — this function
   *   only decides which of the six OPTIONAL fields ride alongside it, not how the prompt itself is
   *   built.
   * @param resolvedConversationId - {@link resolveRunConversationId}'s answer, when `startRun` had to
   *   adopt a conversation because `input.context` named none (the first turn of a chat). Omitted by
   *   every caller that already has an id on `input.context`, and by this function's own unit tests —
   *   in which case the `context` field is read exactly as before.
   * The bounded `coldStartContext` is the complete prompt, including the current request. The
   * daemon selects it instead of the resume tail when native resume is unavailable.
   */
  function buildLocalCliContextRef(
    input: StartRunInput,
    prompt: string,
    resolvedConversationId?: string,
  ): Record<string, unknown> {
    return {
      prompt: ports.projectPrompt({ prompt, context: input.context }, {}),
      // Select one complete transcript after binding; concatenating it with the tail repeats turns.
      coldStartContext: ports.projectPrompt({ prompt: runPrompt(input.history), context: input.context }, {}),
      // The transcript is already sanitized; retain its signal across the daemon JSON boundary.
      ...(input.history.some(message => message.role === "user" && message.secretRedaction?.secretRedacted) ? { secretRedacted: true } : {}),
      assistantMessageId: (input as StartRunInput & { assistantMessageId?: string }).assistantMessageId,
      ...frontendBindTokenField(input),
      ...modelField(input),
      ...reasoningField(input),
      ...attachmentIdsField(input),
      ...pluginRefIdsField(input),
      agentPluginState: input.context?.["agentPluginState"],
      userPrompt: input.context?.["userPrompt"],
      ...conversationIdField(input, resolvedConversationId),
      ...pageContextField(input),
    };
  }

  /**
   * The conversation id this run must carry, adopting one if the caller had none.
   *
   * @param input - `startRun`'s own input; `input.context.conversationId` wins whenever it is a
   *   non-empty string, so turn 2 onward never touches {@link ensureConversationId} and never issues a
   *   redundant `POST /conversations`.
   * @param ensureConversationId - `AssistantTransportOptions.ensureConversationId`, or
   *   `undefined` for a transport built without it (every test and any non-dock consumer).
   * @returns The id to put on the wire, or `undefined` to omit the key entirely — including when
   *   adoption failed. The `.catch` is load-bearing: `ensureConversationId`'s own contract promises
   *   `null` over a rejection, and this makes that promise safe to depend on even if a future
   *   implementation breaks it, rather than failing the user's turn over a lost session id.
   * @complexity O(1) plus at most one conversation-creation round trip, on the first turn only.
   */
  async function resolveRunConversationId(
    input: StartRunInput,
    ensureConversationId: ((required: Record<string, never>, optional: Record<string, never>) => Promise<string | null>) | undefined,
  ): Promise<string | undefined> {
    const fromContext = input.context?.["conversationId"];
    if (typeof fromContext === "string" && fromContext.length > 0) return fromContext;
    if (!ensureConversationId) return undefined;
    const adopted = await ensureConversationId({}, {}).catch(() => null);
    return typeof adopted === "string" && adopted.length > 0 ? adopted : undefined;
  }

  /** Send a resumed agent only its unseen conversation tail, retaining other agents' outcomes.
   * Legacy rows without agent identity retain the existing unanswered-user delivery contract.
   * @complexity O(n) to find the last answered turn; transcript rendering is capped at 40 turns.
   */
  function resolveLocalCliPrompt(
    input: StartRunInput,
    resumeCapableAgentIds: ReadonlySet<string> | undefined,
  ): string {
    const carriesOwnMemory = input.agentId !== undefined && resumeCapableAgentIds?.has(input.agentId) === true;
    if (!carriesOwnMemory) return runPrompt(input.history);
    let lastOwnAnswer = -1;
    input.history.forEach((message, index) => {
      if (message.role === 'assistant' && (!message.agentId || message.agentId === input.agentId) && isAnsweredAssistantTurn(message)) lastOwnAnswer = index;
    });
    const unseen = input.history.slice(lastOwnAnswer + 1);
    const crossedAgents = unseen.some(message => message.role === 'assistant' && message.agentId && message.agentId !== input.agentId);
    // BEHAVIOR CHANGE (2026-09-11, Defect 2): the resume-capable branch was `latestUserPrompt` — the
    // single newest user turn, on the assumption that everything before it is already inside the
    // CLI's own session. That assumption holds only for turns the agent actually answered; a turn
    // whose run died before the CLI read its prompt is in neither place, and nothing ever sent it
    // again. `undeliveredUserPrompt` returns the identical single string in the ordinary case and
    // differs only when there is genuinely something unanswered to catch up on.
    return crossedAgents ? runPrompt(unseen) : undeliveredUserPrompt(input.history);
  }

  /**
   * Writes the newest user turn to durable storage before its run is dispatched, and never fails the
   * turn over it.
   *
   * Defect 2 of the 2026-09-11 chat-lifecycle repair. Message persistence is a client-side
   * `Promise.all` driven by `onMessagesChange` deltas (`use-assistant-chats.hooks.ts`'s `flush`) and
   * run dispatch is a separate `POST /api/runs` here — nothing orders them and nothing makes them
   * atomic, so a browser or daemon death in the window between them could leave a dispatched run whose
   * prompt existed nowhere durable. Await the same PUT when a delta has already scheduled it;
   * acceptance also carries the exact user message and commits it with the assistant stub when
   * browser persistence fails, so sending does not depend on a successful separate PUT.
   *
   * The idempotency key is the message's own id — `assistant-chats.ts`'s `saveMessage` PUTs to
   * `/messages/<id>`, so this write and the `flush` that will race it converge on one row rather than
   * two, and a retry of the same content is free. `useAssistantChats`'s own `persistUserTurn` also
   * marks the id written, so in practice `flush` skips it entirely.
   *
   * @param message - The newest `role: "user"` message in `startRun`'s history — what gets written.
   *   `startRun` has already refused a history without one, so it is always present here.
   * @param conversationId - The already-resolved conversation (see `resolveRunConversationId`), or
   *   `undefined` when adoption failed — there is no row to write into in that case.
   * @param persistUserTurn - `AssistantTransportOptions.persistUserTurn`, or `undefined`
   *   for a transport built without it (every test and any non-dock consumer).
   * @returns Nothing, always. The `.catch` keeps a failed browser PUT from refusing the user's turn;
   *   durable acceptance is now responsible for committing its copy before dispatch.
   * @complexity O(1) plus one PUT.
   */
  async function persistUserTurnBeforeDispatch(
    { message, conversationId }: { message: ChatMessage; conversationId: string | undefined },
    { persistUserTurn }: { persistUserTurn?: AssistantTransportOptions["persistUserTurn"] },
  ): Promise<void> {
    // Pending composer input is persisted by atomic run acceptance. An earlier PUT could save a
    // rejected (409) draft as a user turn; confirmed/legacy callers retain their existing ordering.
    if (message.inputPending || conversationId === undefined || persistUserTurn === undefined) return;
    await persistUserTurn({ conversationId, message }, {}).catch(() => undefined);
  }

  /** The newest `role: "user"` message in a history, or `undefined` when it has none.
   * @complexity O(n) in history length. */
  function newestUserMessage({ history }: { history: readonly ChatMessage[] }, _optional: Record<string, never>): ChatMessage | undefined {
    return [...history].reverse().find((message) => message.role === "user");
  }

  /**
   * Turns `startRun`'s Local CLI `POST /api/runs` response into either a thrown, detailed error or a
   * subscribed run — the two outcomes once the request lands. Pulled out of `startRun` (2026-09-04,
   * complexity pass) as its own step: `response.ok` in, `{runId}` or a thrown `Error` out. The
   * `.text().catch(() => "")` is load-bearing, not decorative — see {@link refusalError}'s inline comment.
   */
  async function finishLocalCliRun(
    response: Response,
    handlers: RunHandlers,
    signal: AbortSignal | undefined,
  ): Promise<{ runId: string }> {
    if (!response.ok) throw await refusalError({ action: "agent run failed to start", response }, {});

    const { run, messageId, conversationId } = (await response.json()) as { run: { id: string }; messageId?: string; conversationId?: string };
    if (messageId && conversationId) ports.bindRun({ runId: run.id, binding: { messageId, conversationId } }, {});
    subscribeToRun(run.id, handlers, signal);
    return { runId: run.id };
  }

  /**
   * The Local CLI path of `startRun`: durable user turn, then acceptance, then the followed run.
   *
   * @param input - `startRun`'s input with its conversation identity already merged into `context`.
   * @param userMessage - The newest user message; acceptance carries it verbatim.
   * @param conversationId - The resolved conversation, or `undefined` when adoption failed.
   */
  async function startLocalCliRun(
    { input, handlers, userMessage, conversationId }: { input: StartRunInput; handlers: RunHandlers; userMessage: ChatMessage; conversationId: string | undefined },
    { options }: { options: AssistantTransportOptions },
  ): Promise<{ runId: string }> {
    // Local CLI path below. `resolveLocalCliPrompt`'s own doc has the full contract for why an
    // unresolved/absent agentId fails open to the full transcript rather than the bare message.
    const prompt = resolveLocalCliPrompt(input, options.getResumeCapableAgentIds?.({}, {}));
    // Also before the POST, and for the same reason it is awaited rather than fired off: the
    // user's turn must be durable before a run that can fail to deliver it exists at all
    // (Defect 2, 2026-09-11). Ordered after conversation adoption because it needs the id that
    // adoption produces. BYOK and AG-UI share the identity above; neither writes a durable
    // user turn ahead of dispatch; those transports retain their own persistence behavior.
    await persistUserTurnBeforeDispatch({ message: userMessage, conversationId }, { persistUserTurn: options.persistUserTurn });
    // Acceptance commits the question and stub together even if the separate browser PUT fails
    // or the tab disappears. Carry the exact message ID/payload, never the rendered prompt.
    const base = buildLocalCliContextRef(input, prompt, conversationId);
    const contextRef = { ...base, userMessage };

    const response = await ports.acceptRun({
      ...(input.cancelSignal === undefined ? {} : { signal: input.cancelSignal }),
      requestSignal: input.cancelSignal ?? input.signal,
      body: { contextRef: JSON.stringify(contextRef), agentId: input.agentId, idempotencyKey: base.assistantMessageId },
      messageId: base.assistantMessageId,
      ...(conversationId === undefined ? {} : { conversationId }),
    }, {});

    return finishLocalCliRun(response, handlers, input.signal);
  }

  function createAssistantTransport(options: AssistantTransportOptions = {}): ChatTransport {
    return {
      async startRun(input: StartRunInput, handlers: RunHandlers): Promise<{ runId: string }> {
        // Guard on the newest USER turn, not on the assembled transcript: a history containing only
        // assistant messages would still produce a non-empty transcript, and sending that as a
        // prompt asks the agent to reply to itself. Shared by both paths below, and reused (rather than
        // recomputed) by the Local CLI branch's own resume-capable check further down.
        const latestUserPrompt = latestUserPromptFromHistory({ history: input.history as ChatMessage[] });
        const userMessage = newestUserMessage({ history: input.history }, {});
        if (!latestUserPrompt || userMessage === undefined) {
          throw new Error("no user message to send");
        }

        // Adopt identity before either runtime branch so first-turn decisions survive a reload.
        const conversationId = await resolveRunConversationId(input, options.ensureConversationId);
        input = { ...input, context: { ...input.context, ...(conversationId ? { conversationId, agentPluginState: readAgentPluginChatState({ conversationId }) } : {}), userPrompt: latestUserPrompt } };
        const executionConfig = options.getExecutionConfig?.({}, {});
        // Dispatches on MODE alone, not on whether a key is typed in this browser right now
        // (2026-08-05). `executionConfig.byok.apiKey` is write-only server-side — it is empty on
        // every fresh load even when a credential IS stored — so gating on it here would make BYOK
        // mode permanently unable to dispatch for exactly the case the server-side store exists to
        // support. `assistant-byok.ts`'s route already resolves the credential correctly either way
        // (a locally-typed key wins when present; an empty/omitted one falls back to this admin's own
        // stored row), so an empty `byok.apiKey` is a legitimate turn, not a reason to fall through to
        // the Local CLI path. A turn with genuinely no usable credential anywhere still fails, just one
        // level down — the route's own 400 `"no usable BYOK credential..."` — which is a real,
        // actionable answer instead of the mode picker silently refusing to try.
        if (executionConfig?.mode === "byok") {
          return startByokRun(ports.projectInput({ input }, {}), capturePluginUsage(handlers), executionConfig.byok);
        }

        // AG-UI canary path (ADR-059) — a host-supplied toggle, independent of `executionConfig.mode`
        // (Jini's own closed union, never extended for this). Checked AFTER the byok branch above:
        // BYOK's single-request shape never touches the daemon at all, so there is nothing for this
        // path (which wraps the daemon specifically) to intercept there — the toggle only ever
        // diverts the Local CLI branch below.
        if (options.getAgUiEnabled?.({}, {})) {
          // `historyForTranscript` here rather than inside `startAgUiRun`: that module importing this
          // one would be a cycle, and this is its only caller. Same rule as the BYOK and Local CLI paths.
          return ports.agUi.startAgUiRun({ input: ports.projectInput({ input: { ...input, history: historyForTranscript(input.history as ChatMessage[]) } }, {}), handlers: capturePluginUsage(handlers) }, {});
        }

        return startLocalCliRun({ input, handlers, userMessage, conversationId }, { options });
      },

      async reattachRun(runId: string, handlers: RunHandlers, options?: ReattachRunOptions): Promise<void> {
        // A BYOK run has no server-side record to reattach to (module doc's path-2 section) — the
        // stream lived entirely on the original `fetch()`'s response body, which a reload has already
        // discarded. Reporting the run as simply over (an empty `onDone`) is the honest answer: there
        // is no way to resume it, and pretending otherwise would hang the pane waiting for events that
        // can never arrive.
        if (runId.startsWith(BYOK_RUN_ID_PREFIX)) {
          handlers.onDone([]);
          return;
        }
        // Same "no server-side record to resume" reasoning as the BYOK branch above — see
        // `assistant-transport-ag-ui.ts`'s own doc for why this path has no reattach story yet.
        if (ports.agUi.isAgUiRunId({ runId }, {})) {
          return ports.agUi.reattachAgUiRun({ handlers }, {});
        }
        subscribeToRun(runId, handlers, options?.signal);
      },

      async fetchRunStatus(runId: string) {
        // Same reasoning as `reattachRun` above — no server-side run record exists for a BYOK run id,
        // so there is no status to fetch. `null` is this port's existing "unknown/not trackable"
        // value (see the daemon branch below's own `!response.ok` case), not a new state.
        if (runId.startsWith(BYOK_RUN_ID_PREFIX)) return null;
        if (ports.agUi.isAgUiRunId({ runId }, {})) return ports.agUi.fetchAgUiRunStatus({}, {});
        const response = await ports.fetch(`${ports.runsUrl}/${encodeURIComponent(runId)}`, { credentials: "same-origin" });
        if (!response.ok) return null;
        const { run } = (await response.json()) as { run: { state: string } };
        return toChatCoreRunStatus(run.state) ?? null;
      },

      async stopRun(runId: string): Promise<void> {
        // A BYOK run's only cancellation handle is the abort controller `startByokRun` registered for
        // this exact id — there is no server-side run to `POST .../cancel` against.
        if (runId.startsWith(BYOK_RUN_ID_PREFIX)) {
          byokAbortControllers.get(runId)?.abort();
          return;
        }
        if (ports.agUi.isAgUiRunId({ runId }, {})) {
          return ports.agUi.stopAgUiRun({ runId }, {});
        }
        const response = await ports.fetch(`${ports.runsUrl}/${encodeURIComponent(runId)}/cancel`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "same-origin",
          body: JSON.stringify({ runId, messageId: ports.runBinding({ runId }, {})?.messageId }),
        });
        // 404: the daemon no longer knows this run (it restarted), so nothing is left running to stop.
        if (response.status === 404) return;
        // `fetch` resolves on any status: without this a refused cancel (401/403/500) resolved exactly
        // like a successful one while the run kept executing. `useRunStream` logs a rejection here.
        if (!response.ok) throw await refusalError({ action: "cancelling agent run failed", response }, {});
      },
    };
  }

  return {
   createAssistantTransport: ({ options = {} }: { options?: AssistantTransportOptions }, _optional: Record<string, never> = {}) => createAssistantTransport(options),
   historyForTranscript: ({ history }: { history: readonly ChatMessage[] }, _optional: Record<string, never> = {}) => historyForTranscript(history),
   undeliveredUserPrompt: ({ history }: { history: readonly ChatMessage[] }, _optional: Record<string, never> = {}) => undeliveredUserPrompt(history),
   buildLocalCliContextRef: ({ input, prompt, resolvedConversationId }: { input: StartRunInput; prompt: string; resolvedConversationId?: string }, _optional: Record<string, never> = {}) => buildLocalCliContextRef(input, prompt, resolvedConversationId),
   handleByokFrame: ({ frame, ctx }: { frame: Parameters<typeof handleByokFrame>[0]; ctx: Parameters<typeof handleByokFrame>[1] }, _optional: Record<string, never> = {}) => handleByokFrame(frame, ctx),
   consumeByokStream: ({ body, ctx }: { body: ReadableStream<Uint8Array>; ctx: Parameters<typeof consumeByokStream>[1] }, _optional: Record<string, never> = {}) => consumeByokStream(body, ctx),
  };
}

/**
 * @module assistant-content
 *
 * The ONE rule for turning a turn's events into its saved text `content`.
 *
 * Why it exists: `content` used to be every `text` event glued together (`out += ev.text`). A model
 * that writes a short note, calls a tool, then answers produced `"Need project id. Find
 * list_projects.`test_table` now exists…"` — the working note fused onto the answer mid-sentence,
 * in the saved row, the copy button, and any transcript rebuilt from it. The live pane already
 * shows those as separate steps (text, tool card, text); the saved string now keeps them apart too,
 * with a blank line (a Markdown paragraph break) wherever a tool call or card sat between them.
 *
 * Every producer of `content` must use this: the browser (`useConversation`) and any host that
 * saves a finished turn server-side. `interleaveMessageBlocks` accepts both this shape and the old
 * glued one, so rows saved before this change still render in order.
 */
import type { AgentEvent } from './events.js';
import { dedupeToolUsesById } from './tool-events.js';

/** What separates two text runs that a tool call or card sat between. */
export const ASSISTANT_STEP_SEPARATOR = '\n\n';

function separatorBefore({ out, text }: { out: string; text: string }, _options = {}): string {
  if (out.length === 0 || out.endsWith(ASSISTANT_STEP_SEPARATOR) || text.startsWith('\n')) return '';
  return out.endsWith('\n') ? '\n' : ASSISTANT_STEP_SEPARATOR;
}

/** Only explicit step transitions separate text. Thinking-token heartbeats and raw diagnostics
 * may occur inside a streamed step and must never split its deltas.
 * @complexity O(1); no mutation or I/O.
 */
export function isAssistantStepBoundary({ event }: { event: AgentEvent }, _options = {}): boolean {
  if (event.kind === 'tool_use' || event.kind === 'ext' || event.kind === 'usage') return true;
  if (event.kind !== 'status') return false;
  if (event.code !== undefined) return event.code === 'step_start';
  return event.label === 'thinking' || event.label === 'running';
}

/**
 * A turn's text, with a paragraph break between runs separated by a tool call or card.
 * A replay of an already-seen tool ID is not a new step, matching the saved-event projection.
 *
 * @param events - The turn's events, in arrival order.
 * @complexity O(n + total text length) time and O(n) space for n events.
 */
export function assistantContentFromEvents({ events }: { events: readonly AgentEvent[] | undefined }, _options = {}): string {
  let out = '';
  let stepBoundary = false;
  for (const ev of dedupeToolUsesById({ events: events ? [...events] : undefined })) {
    if (isAssistantStepBoundary({ event: ev })) {
      stepBoundary = true;
    } else if (ev.kind === 'text' && ev.text.length > 0) {
      out += (stepBoundary ? separatorBefore({ out, text: ev.text }) : '') + ev.text;
      stepBoundary = false;
    }
  }
  return out;
}

/** The pre-2026-09-27 rule (plain concatenation), kept only so older saved rows still match. */
export function legacyAssistantContentFromEvents({ events }: { events: readonly AgentEvent[] | undefined }): string {
  let out = '';
  for (const ev of events ?? []) {
    if (ev.kind === 'text') out += ev.text;
  }
  return out;
}

/** Text-only prompt recall. Browsing owns a snapshot so incoming turns cannot move its cursor. */
export interface ComposerHistoryState {
  entries: readonly string[];
  index: number | null;
  draft: string | null;
}

export interface ComposerHistoryStoragePort {
  read: (required: { scope: string }, optional: { cap?: number }) => Promise<readonly string[]>;
  write: (required: { scope: string; entries: readonly string[] }, optional: { cap?: number }) => Promise<void>;
}

export interface ComposerHistoryKeyInput {
  key: string;
  text: string;
  selectionStart: number;
  selectionEnd: number;
  shiftKey?: boolean;
  ctrlKey?: boolean;
  altKey?: boolean;
  metaKey?: boolean;
  isComposing?: boolean;
  popupOpen?: boolean;
  /** A DOM host can refine logical newline boundaries with measured soft-wrap boundaries. */
  firstLine?: boolean;
  lastLine?: boolean;
}

export function normalizeComposerHistory(
  { entries }: { entries: readonly string[] },
  { cap = 100 }: { cap?: number } = {},
): string[] {
  const result: string[] = [];
  for (const text of entries) {
    // Blank/attachment-only turns are not useful prompts; meaningful whitespace stays exact.
    if (text.trim() && text !== result[result.length - 1]) result.push(text);
  }
  return result.slice(-Math.max(1, Math.floor(cap)));
}

export function mergeComposerHistory(
  { recent, current }: { recent: readonly string[]; current: readonly string[] },
  { cap = 100 }: { cap?: number } = {},
): string[] {
  const left = normalizeComposerHistory({ entries: recent }, { cap });
  const right = normalizeComposerHistory({ entries: current }, { cap });
  // A mounted conversation is usually already the recent list's suffix. Do not append its
  // entire transcript again on every streamed render; preserve nonconsecutive repetitions.
  let overlap = Math.min(left.length, right.length);
  while (overlap > 0 && !right.slice(0, overlap).every((text, i) => text === left[left.length - overlap + i])) overlap -= 1;
  return normalizeComposerHistory({ entries: [...left, ...right.slice(overlap)] }, { cap });
}

export function createComposerHistoryState(
  _required: {},
  _optional: {} = {},
): ComposerHistoryState {
  return { entries: [], index: null, draft: null };
}

type ComposerHistoryKeyAction = 'previous' | 'next' | 'restore';
type ComposerHistoryTransition = { state: ComposerHistoryState; text: string; handled: boolean };

function hasModifierOrPopup({ input }: { input: ComposerHistoryKeyInput }, _optional: {} = {}): boolean {
  return Boolean(input.shiftKey || input.ctrlKey || input.altKey || input.metaKey || input.isComposing || input.popupOpen);
}

/**
 * Whether the selection sits on the first/last line. A selection spanning a newline is on
 * neither, because text[0, end) and text[start, ∞) both contain the selected newline.
 */
function caretBoundaries(
  { input }: { input: ComposerHistoryKeyInput },
  _optional: {} = {},
): { firstLine: boolean; lastLine: boolean } {
  const start = Math.min(input.selectionStart, input.selectionEnd);
  const end = Math.max(input.selectionStart, input.selectionEnd);
  return {
    firstLine: !input.text.slice(0, end).includes('\n') && input.firstLine !== false,
    lastLine: !input.text.slice(start).includes('\n') && input.lastLine !== false,
  };
}

export function composerHistoryKeyAction(
  input: ComposerHistoryKeyInput,
  _optional: {} = {},
): ComposerHistoryKeyAction | null {
  if (hasModifierOrPopup({ input })) return null;
  if (input.key === 'Escape') return 'restore';
  const lines = caretBoundaries({ input });
  if (input.key === 'ArrowUp' && lines.firstLine) return 'previous';
  if (input.key === 'ArrowDown' && lines.lastLine) return 'next';
  return null;
}

function startBrowsing(
  { state, action, text, entries }: { state: ComposerHistoryState; action: string; text: string; entries: readonly string[] },
  _optional: {} = {},
): ComposerHistoryTransition {
  if (action !== 'previous' || entries.length === 0) return { state, text, handled: false };
  const snapshot = [...entries];
  const index = snapshot.length - 1;
  return { state: { entries: snapshot, index, draft: text }, text: snapshot[index]!, handled: true };
}

export function transitionComposerHistory(
  { state, action, text, entries }: {
    state: ComposerHistoryState;
    action: ComposerHistoryKeyAction | 'edit' | 'reset';
    text: string;
    entries: readonly string[];
  },
  _optional: {} = {},
): ComposerHistoryTransition {
  if (action === 'edit' || action === 'reset') {
    return { state: createComposerHistoryState({}), text, handled: false };
  }
  if (state.index === null) return startBrowsing({ state, action, text, entries });
  if (action === 'restore' || (action === 'next' && state.index === state.entries.length - 1)) {
    return { state: createComposerHistoryState({}), text: state.draft ?? '', handled: true };
  }
  const index = action === 'previous' ? Math.max(0, state.index - 1) : state.index + 1;
  return { state: { ...state, index }, text: state.entries[index]!, handled: true };
}

import type { AgentEvent } from './events.js';
import type { ChatMessage } from './messages.js';

function identity(event: AgentEvent, usageOccurrences: Map<string, number>): string {
  const wire = event as AgentEvent & { cursor?: string | number; eventId?: string };
  if (wire.eventId !== undefined) return `event:${wire.eventId}`;
  if (wire.cursor !== undefined) return `cursor:${wire.cursor}`;
  if (event.kind === 'tool_use') return `use:${event.id}`;
  if (event.kind === 'tool_result') return `result:${event.toolUseId}`;
  const snapshot = JSON.stringify(event);
  if (event.kind === 'usage') {
    // Two segments can have identical counters. Match occurrence-for-occurrence during replay,
    // rather than treating equal charges as the same event and silently dropping one segment.
    const occurrence = (usageOccurrences.get(snapshot) ?? 0) + 1;
    usageOccurrences.set(snapshot, occurrence);
    return `usage:${snapshot}:${occurrence}`;
  }
  return snapshot;
}

function textOf(events: readonly AgentEvent[]): string {
  return events.filter((event) => event.kind === 'text').map((event) => event.text).join('');
}

/** Records `key` and reports whether it was new, so each identifiable event is merged once. */
function claimNewKey({ key, keys }: { key: string; keys: Set<string> }): boolean {
  if (keys.has(key)) return false;
  keys.add(key);
  return true;
}

const NO_ROLLOUT = /no rollout found for thread id/;

/** The missing native resume diagnostic, in either the status or the raw-line form a runtime emits. */
function isNoRolloutDiagnostic({ event }: { event: AgentEvent }): boolean {
  if (event.kind === 'status') return NO_ROLLOUT.test(`${event.label}\n${event.detail ?? ''}`);
  return event.kind === 'raw' && NO_ROLLOUT.test(event.line);
}

/** Saved checkpoints can coalesce deltas and a completion may replay only a prefix. Keep the
 * saved projection, merge identifiable events, and append only text beyond its saved prefix. */
export function mergeRunEvents({ saved, incoming }: { saved?: readonly AgentEvent[] | undefined; incoming: readonly AgentEvent[] }, _optional = {}): AgentEvent[] {
  const previous = saved ?? [];
  const result = [...previous];
  const savedUsage = new Map<string, number>();
  const incomingUsage = new Map<string, number>();
  const keys = new Set(previous.map(event => identity(event, savedUsage)));
  const before = textOf(previous);
  const after = textOf(incoming);
  let skip = after.startsWith(before) ? before.length : after.length;
  for (const event of incoming) {
    if (event.kind === 'text') {
      const text = event.text.slice(skip);
      skip = Math.max(0, skip - event.text.length);
      if (text) result.push({ ...event, text });
    } else if (claimNewKey({ key: identity(event, incomingUsage), keys })) {
      result.push(event);
    }
  }
  return result;
}

/** A recovered attempt stays visibly in progress until new text or tool work supersedes its marker. */
export function continuingRunNotice({ events, active }: { events: readonly AgentEvent[] | undefined; active: boolean }, _optional = {}): string | null {
  if (!active) return null;
  const list = events ?? [];
  const marker = list.findLastIndex((event) => event.kind === 'status' && event.code === 'run_recovering');
  if (marker < 0) return null;
  const markerEvent = list[marker];
  if (markerEvent?.kind === 'status' && markerEvent.label === '') return null;
  const progressed = list.slice(marker + 1).some((event) => event.kind === 'text' || event.kind === 'tool_use' || event.kind === 'tool_result');
  return progressed ? null : 'Continuing…';
}

export function preserveAssistantContent({ saved, incoming }: { saved: string; incoming: string }, _optional = {}): string {
  return incoming.length >= saved.length ? incoming : saved;
}

/** Terminal failure belongs to the message. Legacy resend instructions are display-only;
 * changing this copy must never execute or reopen an old terminal run. */
export function terminalMessageNotice({ message }: { message: ChatMessage }, _optional = {}): string | null {
  if (message.runStatus !== 'failed' && message.runStatus !== 'canceled') return null;
  const notice = message.events?.filter((event) => event.kind === 'status' &&
    (event.code === 'run_terminal' || /failed|stopped|restarted|could not|not logged in|cancell?ed/i.test(event.label))).at(-1);
  if (notice?.kind === 'status') return [notice.label, notice.detail].filter(Boolean).join(' ').replace(/Send your message again to retry\.?/gi, '').trim();
  return message.runStatus === 'failed' ? 'This turn failed.' : 'Stopped.';
}

/** The first answer has no earlier segment to divide, even if startup was retried. Only saved
 * visible text can justify a Continued divider; the recovery marker still records the attempt. */
export function recoveredRunEvents({ saved }: { saved: readonly AgentEvent[] }, { notice = 'visible' }: { notice?: 'visible' | 'silent' } = {}): AgentEvent[] {
  if (notice === 'silent') {
    // A missing rollout is an expected reconstruction fallback, not a failed user turn. Keep an
    // invisible attempt marker for fencing/diagnostic offsets, and preserve all unrelated work.
    const attemptStart = saved.findLastIndex(event => event.kind === 'status' && event.code === 'run_recovering') + 1;
    const diagnostic = saved.findIndex((event, index) => index >= attemptStart && isNoRolloutDiagnostic({ event }));
    const events = saved.filter((event, index) => {
      if (diagnostic < 0 || index < attemptStart) return true;
      if (event.kind === 'status' && event.label === 'Run failed — the agent process exited without answering') return false;
      return !isNoRolloutDiagnostic({ event });
    });
    return [...events, { kind: 'status', code: 'run_recovering', label: '' }];
  }
  const hasAnswer = saved.some(event => event.kind === 'text' && event.text.trim().length > 0);
  return [...saved, ...(hasAnswer ? [{ kind: 'text' as const, text: '\n\n---\n\nContinued\n\n' }] : []),
    { kind: 'status', code: 'run_recovering', label: 'Continuing…' }];
}

import type { AgentEvent } from "../index.js";
import type { AcceptedRunRequest, DurableRun } from "./ports.js";
import type { AgentPluginUsage } from "../agent-plugin-chat-state.js";

export const CONTINUATION_DIVIDER = "\n\n---\n\nContinued\n\n";
export const UNKNOWN_MUTATION_ERROR = "This operation may already be done. Its earlier outcome is unknown; verify the current state before repeating it.";

/** Object-key order and a new tool-use id must not turn the same mutation into a new operation. */
export function canonicalToolInput({ value }: { value: unknown }, _optional = {}): string {
  if (Array.isArray(value)) return `[${value.map((item) => canonicalToolInput({ value: item }, {})).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const object = value as Record<string, unknown>;
    return `{${Object.keys(object).sort().map((key) => `${JSON.stringify(key)}:${canonicalToolInput({ value: object[key] }, {})}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

function delegatedCall(event: Extract<AgentEvent, { kind: "tool_use" }>): { toolId: string; input: unknown } {
  const input = event.input as { toolId?: unknown; input?: unknown } | null;
  if (input && typeof input.toolId === "string" && /execute.*delegated_tool/.test(event.name)) return { toolId: input.toolId, input: input.input };
  return { toolId: event.name, input: event.input };
}

/** Results that settle their call. An outcome-unknown result does not: the call may have run. */
function settledResults({ events }: { events: readonly AgentEvent[] }, _optional = {}): Map<string, AgentEvent> {
  return new Map(events.flatMap((event) => event.kind === "tool_result" && event.outcome !== "unknown" ? [[event.toolUseId, event] as const] : []));
}

export function hasUnknownToolCall(
  { events, toolId, input }: { events: readonly AgentEvent[]; toolId: string; input: unknown }, _optional = {},
): boolean {
  const completed = settledResults({ events }, {});
  const canonical = canonicalToolInput({ value: input }, {});
  return events.some((event) => {
    if (event.kind !== "tool_use" || completed.has(event.id)) return false;
    // The read-only gateway either reads or refuses before execution; neither can leave a mutation.
    if (/execute_readonly_delegated_tool$/.test(event.name)) return false;
    const call = delegatedCall(event);
    return call.toolId === toolId && canonicalToolInput({ value: call.input }, {}) === canonical;
  });
}

function toolHistory(events: readonly AgentEvent[]): string {
  const results = settledResults({ events }, {});
  return events.filter((event) => event.kind === "tool_use").map((event) => {
    const result = results.get(event.id);
    return JSON.stringify({ call: delegatedCall(event), result: result ?? "OUTCOME UNKNOWN: verify state before repeating" });
  }).join("\n");
}

/** The accepted browser state predates this turn's Ask answer. A replacement attempt must
 * carry the latest saved decision, including Skip, instead of asking from that frozen state.
 * Scan backwards so recovery markers and unrelated extensions cannot hide the last answer.
 */
function latestAgentPluginState(
  { events, conversationId, accepted }: { events: readonly AgentEvent[]; conversationId: string; accepted: unknown }, _optional = {},
): unknown {
  for (let index = events.length - 1; index >= 0; index--) {
    const event = events[index]!;
    if (event.kind !== "ext" || event.name !== "agent_plugins") continue;
    const usage = event.data as AgentPluginUsage | undefined;
    if (usage?.conversationId === conversationId && usage.state) return usage.state;
  }
  return accepted;
}

function continuationPrompt(
  { run, native, acceptedPrompt, events }: { run: DurableRun; native: boolean; acceptedPrompt: unknown; events: readonly AgentEvent[] }, _optional = {},
): string {
  // Native sessions may have disappeared on deploy. Reconstruction includes the saved answer
  // and tool results for every runtime; completed side effects must never be silently repeated.
  const transcript = run.transcript.map((message) => `${message.role}: ${message.content}`).join("\n\n");
  return [
    "Continue the interrupted answer from the saved work below. Preserve completed work. Do not repeat completed mutations.",
    "Omission markers in the saved work are system housekeeping, not user content; do not mention them to the user or infer a user disclosure from them.",
    "Calls without a result have an unknown outcome: inspect current state before any retry. Expired plans or approvals must be re-planned and re-approved; never reuse them.",
    "Never re-ask a pending question in this turn. The interrupted segment remains visible; append the continuation.",
    `Accepted task:\n${String(acceptedPrompt ?? "")}`,
    native ? "Native session is confirmed; continue its saved task." : `Saved conversation:\n${transcript}`,
    `Saved partial answer:\n${run.message.content}`,
    `Saved tool calls and results:\n${toolHistory(events)}`,
  ].join("\n\n");
}

/** Reconstruct one attempt from the accepted task and its saved work, including plugin consent.
 * Returns a new request without changing the accepted input or transcript; invalid context JSON throws.
 * @complexity O(e + t) time/space in saved events and transcript text; no external effects.
 */
export function continuationRequest(
  { run, native }: { run: DurableRun; native: boolean }, _optional = {},
): AcceptedRunRequest {
  const original = JSON.parse(run.request.contextRef) as Record<string, unknown>;
  const events = run.message.events ?? [];
  const agentPluginState = latestAgentPluginState({ events, conversationId: run.conversationId, accepted: original.agentPluginState }, {});
  const prompt = continuationPrompt({ run, native, acceptedPrompt: original.prompt, events }, {});
  return {
    ...run.request,
    contextRef: JSON.stringify({ ...original, prompt, conversationId: run.conversationId,
      ...(agentPluginState === undefined ? {} : { agentPluginState }),
      assistantMessageId: run.messageId, principalId: run.principalId,
      recoveryMode: native ? "native" : "reconstruction", recoverySessionId: native ? run.sessionId : undefined,
      // Old attachment claims have been consumed. Saved transcript/tool results carry their
      // observations; attempting to claim the same ids again would fail before execution.
      attachmentIds: [],
    }),
  };
}

import type { AgentEvent, ChatMessage, ChatRunStatus } from "../index.js";
import type { DurableRunStore } from "./ports.js";

import type { RunRef, RunProgress, RunSettlement } from "./run-contracts.js";
export type { RunRef, RunProgress, RunSettlement } from "./run-contracts.js";

/** {@link ChatRunLedger.unlessSettled}'s result: the write's value, or that the run had settled. */
export type UnlessSettled<T> = { readonly written: true; readonly value: T } | { readonly written: false };

/** Internal boot recovery, never an HTTP history read. The owner comes from storage, not a client. */
export interface InterruptedChatTurn {
  readonly principalId: string | null;
  readonly conversationId: string;
  readonly message: ChatMessage;
}

export interface ChatRunRecoveryOptions {
  /** True retains the row: a daemon run was adopted with bounded resolution of uncertainty.
   * Called outside storage transactions so a daemon request cannot hold the database lock. */
  readonly recover?: (input: InterruptedChatTurn) => Promise<boolean>;
}

export interface ChatRunLedger {
  readonly durable?: DurableRunStore;
  /**
   * Runs `write` only while `run`'s row holds no terminal status (an unknown row, another run id, or
   * a row still `queued`/`running` all count as unsettled), with no settle able to land in between.
   * `write` must reach the chat database through this ledger's kernel (the same connection, on
   * SQLite) so it joins the transaction.
   */
  unlessSettled<T>(required: { run: RunRef; write: () => Promise<T> }, optional?: {}): Promise<UnlessSettled<T>>;
  /**
   * Writes the run's final content, events and status — only if the row still belongs to that run
   * and is not yet terminal. Resolves `true` when this call was the one that settled it.
   */
  settle(settlement: RunSettlement, optional?: {}): Promise<boolean>;
  /**
   * Saves what a still-running run has produced so far (content and events; the status stays), so
   * a process that dies mid-run leaves its partial answer for {@link reconcileInterrupted} to keep.
   * A no-op once the row is terminal or belongs to another run. Resolves `true` when it wrote, or
   * when the row already held exactly this checkpoint (accepted without rewriting the row).
   */
  checkpoint(progress: RunProgress, optional?: {}): Promise<boolean>;
  /** Serving-only discovery of unfinished rows. The injected recovery coordinator owns adopted
   * runs; rows it cannot adopt are canceled, preserving saved work. Returns handled rows.
   * Export apps must not invoke discovery while a serving daemon is still alive. */
  reconcileInterrupted(required?: { now?: number }, optional?: ChatRunRecoveryOptions): Promise<number>;
}

/**
 * @module partial-json
 *
 * Truncation-tolerant JSON parsing for streamed LLM output. A streaming
 * `<question-form>` (or any other structured artifact) needs to render a
 * JSON *prefix* that grows one token at a time, so callers rely on this
 * repair pass instead of waiting for the closing brace.
 *
 * Deliberately handles only the shapes a streaming model emits — balanced
 * structure that simply hasn't finished — not arbitrary corruption. Callers
 * should still keep their last good parsed result as a fallback.
 */

// Bound repair and JSON.parse work for untrusted model-generated structured output.
const MAX_STRUCTURED_INPUT_CHARS = 64 * 1024;
// A valid streamed prefix settles in two cleanup passes (cut value, then its key/comma). Input
// needing more is not JSON (`[t,t,t,…`), and each extra pass would rescan the whole buffer.
const MAX_TAIL_CLEANUP_PASSES = 8;

/** Linear form of `/[,\s]+$/`, which V8 retries from every separator in a long run (quadratic). */
function trimTrailingSeparators({ text }: { text: string }, _optional: {} = {}): string {
  let end = text.length;
  while (end > 0 && /[,\s]/.test(text[end - 1]!)) end -= 1;
  return text.slice(0, end);
}

/** Consume one quoted character; an escaped quote does not end the string. */
function advanceJsonString({ c, esc }: { c: string; esc: boolean }, _optional: {} = {}): { inStr: boolean; esc: boolean } {
  if (esc) return { inStr: true, esc: false };
  return { inStr: c !== '"', esc: c === '\\' };
}

/** Track strings/escapes and owed container closers in one pass over a bounded JSON prefix. */
function scanJsonPrefix({ buf }: { buf: string }, _optional: {} = {}): { stack: string[]; inStr: boolean } {
  const stack: string[] = []; // closers owed, e.g. ['}', ']']
  let inStr = false;
  let esc = false;
  for (const c of buf) {
    if (inStr) {
      ({ inStr, esc } = advanceJsonString({ c, esc }));
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === '{') stack.push('}');
    else if (c === '[') stack.push(']');
    else if (c === '}' || c === ']') stack.pop();
  }
  return { stack, inStr };
}

/** Close a string cut off mid-value (or mid-key). First neutralize a
 * dangling escape at the cut point, otherwise the closing quote would be
 * swallowed (`...x\` + `"` → escaped quote) or a partial `\uXXXX` would
 * be an invalid escape — either makes JSON.parse fail and collapses the
 * live preview. Common in prompts that mention Windows paths, regexes,
 * or escaped quotes.
 */
function closeJsonString({ out }: { out: string }, _optional: {} = {}): string {
  out = out.replace(/\\u[0-9a-fA-F]{0,3}$/, ''); // incomplete \uXXXX
  if (/(?:^|[^\\])(?:\\\\)*\\$/.test(out)) out = out.slice(0, -1); // lone trailing backslash
  return out + '"';
}

/** Returns null when the tail never settles within the pass bound. */
function trimIncompleteTail({ out }: { out: string }, _optional: {} = {}): string | null {
  // 2. Trim trailing structural noise that can't be completed into a value:
  //    a dangling comma, a `"key":` with no value yet, and an unfinished
  //    *scalar* value cut mid-token (a partial `true`/`false`/`null`, or a
  //    number ending on `.`/`e`/sign). Leaving those makes `{… :f}` etc.
  //    unparseable, collapsing the live preview whenever a literal splits
  //    across deltas. Each trim leaves a `"key":` / `,` / `[` boundary that
  //    the next loop iteration cleans up. Complete literals (`true`, `12`,
  //    `1.5`, `1e3`) are not prefixes of these patterns, so they survive.
  const valueStart = '([:[,]\\s*)';
  let prev: string;
  let passes = 0;
  do {
    if (++passes > MAX_TAIL_CLEANUP_PASSES) return null;
    prev = out;
    out = trimTrailingSeparators({ text: out });
    out = out.replace(/"(?:[^"\\]|\\.)*"\s*:\s*$/, ''); // key + colon, no value
    out = out.replace(new RegExp(`${valueStart}(?:tru|tr|t|fals|fal|fa|f|nul|nu|n)$`), '$1'); // partial bool/null
    out = out.replace(new RegExp(`${valueStart}-?(?:\\d+(?:\\.\\d*)?|\\.\\d+)?[eE][+-]?$`), '$1'); // dangling exponent
    out = out.replace(new RegExp(`${valueStart}-?\\d*\\.$`), '$1'); // number ending in '.'
    out = out.replace(new RegExp(`${valueStart}-$`), '$1'); // lone minus
    out = out.replace(/"(?:[^"\\]|\\.)*"\s*:\s*$/, ''); // key + colon exposed by the trims above
    out = trimTrailingSeparators({ text: out });
  } while (out !== prev);
  return out;
}

/**
 * Repair a truncated JSON prefix into the largest valid JSON text that can be
 * parsed, by walking the buffer once to track string/escape state and the
 * open-container stack, then closing whatever is still open.
 *
 * @param buf - A possibly-incomplete JSON text (a streamed prefix).
 * @returns Empty text above 64 Ki characters or for non-JSON tails that never settle; otherwise
 *   best-effort closed JSON. Not guaranteed to parse (e.g. an empty buffer round-trips unchanged) — callers should still
 *   wrap consumption in `JSON.parse`/try-catch (see {@link parsePartialJson}).
 * @complexity O(n) time / O(d) space in the input length `n` and max nesting
 *   depth `d` — one linear scan plus at most 8 linear cleanup passes over the tail.
 */
export function repairJsonPrefix({ buf }: { buf: string }, _optional: {} = {}): string {
  if (buf.length > MAX_STRUCTURED_INPUT_CHARS) return '';
  const { stack, inStr } = scanJsonPrefix({ buf });
  const settled = trimIncompleteTail({ out: inStr ? closeJsonString({ out: buf }) : buf });
  if (settled === null) return '';
  let out = dropPendingKey({ out: settled, stack });
  // 3. Close every still-open container, innermost first.
  for (let i = stack.length - 1; i >= 0; i--) out += stack[i];
  return out;
}

// A bare trailing key (string with no following colon) only happens when
// the *innermost* open container is an object. Drop it so we don't emit
// `{"hea"}` which is invalid (key without value).
function dropPendingKey({ out, stack }: { out: string; stack: readonly string[] }, _optional: {} = {}): string {
  if (stack[stack.length - 1] === '}' && /"(?:[^"\\]|\\.)*"\s*$/.test(out)) {
    const trimmed = out.replace(/"(?:[^"\\]|\\.)*"\s*$/, '');
    // Only drop it if what precedes is a container/comma boundary (i.e. the
    // string really is a pending key, not a completed value like `:"x"`).
    if (/[{,]\s*$/.test(trimmed)) {
      out = trimTrailingSeparators({ text: trimmed });
    }
  }
  return out;
}

/**
 * Best-effort parse of a (possibly truncated) JSON prefix.
 *
 * @param buf - A possibly-incomplete JSON text.
 * @returns The parsed value, or `null` on input above 64 Ki characters, empty input or an unrecoverable
 *   parse failure — callers should fall back to their last good value.
 * @complexity O(n) — dominated by {@link repairJsonPrefix}.
 */
export function parsePartialJson({ buf }: { buf: string }, _optional: {} = {}): unknown {
  if (buf.length > MAX_STRUCTURED_INPUT_CHARS) return null;
  const trimmed = buf.trim();
  if (!trimmed) return null;
  try {
    return JSON.parse(repairJsonPrefix({ buf: trimmed }));
  } catch {
    return null;
  }
}

/**
 * @module persistence/title
 *
 * Derives a conversation's working title from its first user message, synchronously and with no
 * model call.
 *
 * The point of doing this locally is latency and cost: a conversation needs a name the instant
 * it appears in a list, and for an anonymous-visitor surface a per-conversation LLM call to name
 * a chat is a real cost against a session that may be one message long. A host that wants a
 * better title asks its agent for one later and calls `rename(id, title, 'generated')`; the
 * store refuses to overwrite a `manual` title, so a user's own rename always wins.
 *
 * Ported from Open Design's `summarizeProjectNameFromPrompt` (`apps/web/src/utils/projectName.ts`).
 * The Latin path has since diverged: it keeps the prompt's words, names and dotted domains (the
 * original's stop-word removal and title casing turned "port example.com to jini" into "Port
 * Example Com Jini"), and `LEADING_LATIN_FILLER` fixes the original's article bug, documented at
 * its declaration. The CJK path keeps the original's filler and punctuation rules, which is not
 * decoration: they differ enough from the Latin ones that a shared path produced worse titles in both.
 */

const MAX_CJK_LENGTH = 18;
/**
 * Hard character ceiling, because a word cap is not a length cap.
 *
 * A word boundary says nothing about token size: a pasted base64 blob or minified bundle is a single
 * enormous token, so it must not survive intact and become the title verbatim. That title is
 * then stored, listed, and re-rendered on every conversation-list read — megabytes of it. Applied to
 * the finished title so both the Latin and CJK paths are covered.
 */
const MAX_TITLE_CHARS = 80;

const CJK_PATTERN = /[㐀-鿿]/;

/**
 * Leading politeness/imperative filler — "can you build a dashboard" is a dashboard.
 *
 * The trailing article group requires `\s+` *inside* it rather than the original's
 * `(an|a|the|…)?\s*`. That form is subtly wrong: with the whitespace outside the optional group,
 * the bare `a` alternative happily matches the first letter of the following word, so
 * "update app.tsx" became "Pp Tsx" and "build analytics" became "Nalytics". Any word starting
 * with `a` after a verb silently lost its first character. Requiring the separator as part of the
 * article makes an article an article rather than a prefix.
 */
const LEADING_LATIN_FILLER =
  /^(please\s+)?(can\s+you\s+|could\s+you\s+|help\s+me\s+|i\s+want\s+to\s+|i\s+need\s+to\s+)?(create|build|make|design|implement|add|fix|update|improve|optimize|generate|write|search|find|show|list|turn)\s+((this|that)\s+into\s+)?((an|a|the|this|that|my|me)\s+)?/i;

const LEADING_CJK_FILLER = [
  /^先?(帮我|帮忙|麻烦|请|可以|能不能|能否|给我|我想要|我要)/,
  /^(先)?(实现|做|做一下|创建|生成|设计|开发|新增|添加|优化|修复|改|更改|调整)(一下|一个|一版|下)?/,
  /^(一个|一份|这个|那个)/,
];

/**
 * Strips the parts of a prompt that are never a good title: fenced code, URLs, and
 * `@handle`/`#tag` tokens. Each of these is high-entropy and low-meaning in a short summary.
 * Inline code keeps its label with delimiters removed, so a filename can still name the task.
 */
function cleanPrompt(prompt: string): string {
  return stripConversationTitleMarkdown({ text: prompt })
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/[@#][\w.-]+/g, ' ')
    .replace(/[“”"']/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Remove presentation markup from title text while preserving link labels and inline code.
 * Shared by prompt derivation, stored-title display and product naming adapters; no DOM or I/O.
 * Fenced programs and reference definitions are not titles. Only paired emphasis is stripped:
 * glob stars and identifier underscores are meaningful text. Older saved titles may already have
 * been cut through a markdown span; cut links keep their partial label, unpaired emphasis stays.
 * @param input.text - A prompt or a previously saved title.
 * @returns Plain text with whitespace collapsed; identifiers keep their internal underscores.
 * @complexity O(n²) worst-case regex time for unmatched spans; O(n) space in title/prompt length.
 */
export function stripConversationTitleMarkdown({ text }: { text: string }, _options = {}): string {
  return text
    .replace(/```[\s\S]*?(?:```|$)/g, ' ')
    .replace(/^\s{0,3}\[[^\]\n]+\]:[^\n]*(?:\n|$)/gm, ' ')
    .replace(/!?\[([^\[\]\n]+)\]\((?:[^()[\]\n]|\([^()[\]\n]*\))*(?:\)|$)/g, '$1')
    .replace(/\[([^\[\]\n]+)\]\[[^\[\]\n]*(?:\]|$)/g, '$1')
    .replace(/^\s{0,3}#{1,6}\s+|[ \t]+#+[ \t]*$/gm, '')
    .replace(/(?<![\w\\*])(\*\*|\*)(?=[^\s*])([^*\n]*?[^\s*\\])\1(?![\w*])/g, '$2')
    .replace(/(?<![\w\\_])(__|_)(?=[^\s_])([^\n]*?[^\s\\])\1(?![\w_])/g, '$2')
    .replace(/`|~~/g, '')
    .replace(/!?\[([^\]\n]*)(?=\n|$)/g, '$1')
    // Unescape after markup removal so an escaped literal marker cannot become emphasis.
    .replace(/\\([\\`*_[\]~])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Keep complete words at the display ceiling. A single oversized token still gets a bounded
 * prefix: pasted blobs must never become megabyte-sized stored/listed titles. The old six-word cap
 * stranded auxiliaries and pronouns mid-clause; the character ceiling leaves short questions whole.
 * @complexity O(n) time/space, bounded by the title ceiling after the initial length check.
 */
function truncateTitle(title: string): string {
  if (title.length <= MAX_TITLE_CHARS) return title;
  const prefix = title.slice(0, MAX_TITLE_CHARS);
  if (/\s/.test(title.charAt(MAX_TITLE_CHARS))) return prefix.trimEnd();
  const lastSpace = prefix.lastIndexOf(' ');
  return (lastSpace > 0 ? prefix.slice(0, lastSpace) : prefix).trimEnd();
}

function trimLatinTitle(input: string): string {
  const words = input.replace(LEADING_LATIN_FILLER, '').match(/[\p{L}\p{N}]+(?:[._-][\p{L}\p{N}]+)*/gu) ?? [];
  const title = words.join(' ');
  // Domain and filename tokens retain their original case, even at the start of a sentence.
  return words[0]?.includes('.') ? title : title.charAt(0).toUpperCase() + title.slice(1);
}

function trimCjkTitle(input: string): string {
  let title = input.trim();
  for (const pattern of LEADING_CJK_FILLER) title = title.replace(pattern, '').trim();
  // Cut at the first sentence-ending punctuation, then drop spacing — CJK titles do not use it.
  title = title.replace(/[，。！？；：,.!?;:].*$/, '').replace(/\s+/g, '');
  return title.slice(0, MAX_CJK_LENGTH);
}

/**
 * Returns a short display title for a conversation, or `''` when the prompt yields nothing
 * usable (a bare URL, a lone code fence, pure punctuation). Callers should treat `''` as "leave
 * the conversation untitled" rather than substituting the raw prompt — a list row showing 400
 * characters of pasted code is worse than one showing "Untitled".
 *
 * @complexity O(n) in prompt length; no allocation beyond the intermediate strings.
 */
export function deriveConversationTitle({ prompt }: { prompt: string }, _optional: Record<string, never> = {}): string {
  const cleaned = cleanPrompt(prompt);
  if (!cleaned) return '';
  // `split` always yields a first element, even for a string that starts with a separator.
  const firstClause = cleaned.split(/[\n\r。！？!?]/)[0]!.trim();
  if (!firstClause) return '';
  const title = CJK_PATTERN.test(firstClause) ? trimCjkTitle(firstClause) : trimLatinTitle(firstClause);
  // Truncated without an ellipsis: this is a working title, not prose, and a `…` would end up stored
  // and shown as if the author wrote it.
  return truncateTitle(title);
}

/** A known heuristic title is already display-ready: derivation keeps the prompt's own wording.
 * Manual names, model-authored names and unloaded transcripts keep their saved wording, with
 * presentation markup removed and the display ceiling applied; no writes.
 * @complexity O(n) time/space in the first prompt's length, using the existing bounded heuristic.
 */
export function conversationTitleForDisplay({ title, titleSource, firstPrompt }: {
  title: string | null; titleSource: 'fallback' | 'generated' | 'manual'; firstPrompt?: string | undefined;
}, _options = {}): string | null {
  if (!title) return title;
  if (titleSource === 'generated' && firstPrompt && title === deriveConversationTitle({ prompt: firstPrompt })) {
    return title;
  }
  return truncateTitle(stripConversationTitleMarkdown({ text: title })) || null;
}

/**
 * @module question-form/normalize
 *
 * Normalization of a raw (already-JSON-parsed) question object into this
 * package's stable `FormQuestion`/`DirectionCard` shape — tolerant of the
 * looser vocabulary a model tends to emit (`"multi"` for `checkbox`,
 * `"default"` for `defaultValue`, etc). Split out of the original
 * single-file `question-form.ts`; see `../question-form.ts` for the public
 * facade and `./scan.ts` for the caller that turns raw JSON into these
 * question objects.
 */
import type { DirectionCard, FormOption, FormQuestion, QuestionType } from './types.js';
import { formOptionValueForLabel } from './format.js';

/** `raw` viewed as a record of fields, or `null` when it isn't an object at all. */
export function asRecord(raw: unknown): Record<string, unknown> | null {
  return raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : null;
}

/** `raw` when it is a string, else `undefined`. */
export function stringOrUndefined(raw: unknown): string | undefined {
  return typeof raw === 'string' ? raw : undefined;
}

/** `raw` when it is a non-empty string, else `undefined`. */
export function nonEmptyString(raw: unknown): string | undefined {
  return stringOrUndefined(raw) || undefined;
}

/** `raw` trimmed when it is a string with visible content, else `undefined`. */
function trimmedNonBlank(raw: unknown): string | undefined {
  return nonEmptyString(stringOrUndefined(raw)?.trim());
}

/** The string entries of `raw` when it is an array, else an empty list. */
function stringsOnly(raw: unknown): string[] {
  return Array.isArray(raw) ? raw.filter((entry): entry is string => typeof entry === 'string') : [];
}

type OmitUndefined<T> = { [K in keyof T as undefined extends T[K] ? never : K]: T[K] } & {
  [K in keyof T as undefined extends T[K] ? K : never]?: Exclude<T[K], undefined>;
};

/**
 * `obj` without its `undefined`-valued keys, in the original key order — so
 * an optional field is absent rather than present-but-undefined, which
 * `exactOptionalPropertyTypes` (and a consumer's `'key' in obj`) can tell apart.
 */
export function omitUndefined<T extends Record<string, unknown>>(obj: T): OmitUndefined<T> {
  return Object.fromEntries(Object.entries(obj).filter(([, value]) => value !== undefined)) as OmitUndefined<T>;
}

export function mapRawQuestion({ q, index }: { q: unknown; index: number }): FormQuestion | null {
  const qo = asRecord(q);
  if (!qo) return null;
  const id = trimmedNonBlank(qo.id) ?? `q${index + 1}`;
  const type = normalizeType(qo.type);
  const options = parseOptions(qo.options);
  const isFile = type === 'file';
  return omitUndefined({
    id,
    name: stringOrUndefined(qo.name),
    label: stringOrUndefined(qo.label) ?? id,
    type,
    options,
    placeholder: nonEmptyString(qo.placeholder),
    help: nonEmptyString(qo.help),
    required: qo.required === true || undefined,
    defaultValue: parseDefaultValue(qo, options),
    maxSelections: type === 'checkbox' ? positiveInteger(qo.maxSelections) : undefined,
    allowCustom: parseAllowCustom(qo),
    customLabel: nonEmptyString(qo.customLabel),
    customPlaceholder: nonEmptyString(qo.customPlaceholder),
    min: parseNumberAttr(qo.min),
    max: parseNumberAttr(qo.max),
    step: parseNumberAttr(qo.step),
    multiple: (isFile && qo.multiple === true) || undefined,
    accept: isFile ? nonEmptyString(qo.accept) : undefined,
    cards: parseDirectionCards(qo.cards),
  });
}

function positiveInteger(raw: unknown): number | undefined {
  return typeof raw === 'number' && Number.isInteger(raw) && raw > 0 ? raw : undefined;
}

// An explicit `allowCustom: false` wins over the legacy `custom: true` key.
function parseAllowCustom(question: Record<string, unknown>): boolean | undefined {
  if (question.allowCustom === false) return false;
  return question.allowCustom === true || question.custom === true || undefined;
}

const TYPE_ALIASES: ReadonlyMap<string, QuestionType> = new Map<string, QuestionType>(
  (
    [
      ['radio', ['radio', 'single', 'choice']],
      ['checkbox', ['checkbox', 'multi', 'multiple']],
      ['select', ['select', 'dropdown']],
      ['textarea', ['textarea', 'long', 'paragraph']],
      ['number', ['number', 'numeric']],
      ['range', ['range', 'slider']],
      ['date', ['date']],
      ['time', ['time']],
      ['datetime-local', ['datetime-local', 'datetime', 'date-time', 'datetime_local']],
      ['color', ['color', 'colour', 'color-picker']],
      ['url', ['url', 'link']],
      ['email', ['email']],
      ['tel', ['tel', 'phone']],
      ['file', ['file', 'upload', 'attachment']],
      ['switch', ['switch', 'toggle', 'boolean']],
      ['direction-cards', ['direction-cards', 'directions', 'cards', 'direction']],
    ] satisfies [QuestionType, string[]][]
  ).flatMap(([type, aliases]) => aliases.map((alias): [string, QuestionType] => [alias, type])),
);

function normalizeType(raw: unknown): QuestionType {
  if (typeof raw !== 'string') return 'text';
  return TYPE_ALIASES.get(raw.toLowerCase().trim()) ?? 'text';
}

function parseNumberAttr(raw: unknown): number | undefined {
  if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
  if (typeof raw !== 'string') return undefined;
  const n = Number(raw);
  return Number.isFinite(n) ? n : undefined;
}

function parseOptions(raw: unknown): FormOption[] | undefined {
  if (!Array.isArray(raw)) return undefined;
  const options = raw.map(parseOption).filter((option): option is FormOption => option !== null);
  return options.length > 0 ? options : undefined;
}

function parseOption(raw: unknown): FormOption | null {
  if (typeof raw === 'string') {
    const label = trimmedNonBlank(raw);
    return label ? { label, value: label } : null;
  }
  const obj = asRecord(raw) ?? {};
  const label = trimmedNonBlank(obj.label);
  if (!label) return null;
  return omitUndefined({ label, value: trimmedNonBlank(obj.value) ?? label, description: trimmedNonBlank(obj.description) });
}

// Only `defaultValue` may hold a list; the legacy `default` key is read as a scalar only.
function parseDefaultValue(
  question: Record<string, unknown>,
  options: FormOption[] | undefined,
): string | string[] | undefined {
  const resolve = (labelOrValue: string) => formOptionValueForLabel({ question: { options }, labelOrValue });
  if (Array.isArray(question.defaultValue)) return stringsOnly(question.defaultValue).map(resolve);
  const raw = scalarString(question.defaultValue) ?? scalarString(question.default);
  return raw === undefined ? undefined : resolve(raw);
}

function scalarString(raw: unknown): string | undefined {
  if (typeof raw === 'number' || typeof raw === 'boolean') return String(raw);
  return stringOrUndefined(raw);
}

/** `#rgb`, `#rgba`, `#rrggbb`, `#rrggbbaa`. */
const HEX_COLOR = /^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
/** A bare CSS colour keyword. Letters only — with no parenthesis it cannot become a function call. */
const COLOR_KEYWORD = /^[a-z]+$/i;
/**
 * A colour function. The argument charset deliberately excludes `(`, so no nested function —
 * `var()`, `url()`, `image-set()`, `attr()` — can appear inside one of these either.
 */
const COLOR_FUNCTION = /^(?:rgb|rgba|hsl|hsla|hwb|lab|lch|oklab|oklch|color)\(\s*[0-9a-z%.,/\s+-]*\)$/i;

/**
 * Whether a model-supplied palette entry may be written into a CSS value.
 *
 * `palette` reaches `QuestionForm`'s swatch as `style={{ background: c }}`, and `background` is a
 * SHORTHAND — it accepts far more than a colour. An agent (or anything that can influence one)
 * emitting `url(https://attacker.example/pixel)` therefore got the browser to issue a request the
 * moment the card rendered: a tracking beacon inside the chat transcript, needing no click. Neither
 * React nor the CSSOM filters this; React passes style values through, and the CSSOM happily
 * accepts a valid shorthand.
 *
 * Enforced HERE rather than at the swatch, because this is the normalization boundary and the
 * component is not the only thing that could ever read `palette`. An entry that fails is DROPPED
 * rather than substituted: a silently recoloured swatch would misrepresent the agent's proposal,
 * and a card with fewer swatches is honest about what survived validation.
 */
export function isRenderableColor({ value }: { value: string }): boolean {
  const candidate = value.trim();
  // Bounded before any regex runs: these come from model output, and the function pattern's `\s*`
  // plus a character class is the shape that makes a pathological input worth not accepting at all.
  if (candidate.length === 0 || candidate.length > 64) return false;
  return HEX_COLOR.test(candidate) || COLOR_KEYWORD.test(candidate) || COLOR_FUNCTION.test(candidate);
}

function parseDirectionCards(raw: unknown): DirectionCard[] | undefined {
  if (!Array.isArray(raw)) return undefined;
  const out = raw.flatMap((entry: unknown) => parseDirectionCard(asRecord(entry) ?? {}) ?? []);
  return out.length > 0 ? out : undefined;
}

function parseDirectionCard(e: Record<string, unknown>): DirectionCard | null {
  const id = trimmedNonBlank(e.id);
  const label = stringOrUndefined(e.label);
  if (id === undefined || label === undefined) return null;
  return {
    id,
    label,
    mood: stringOrUndefined(e.mood) ?? '',
    references: stringsOnly(e.references).slice(0, 6),
    palette: stringsOnly(e.palette).filter((value) => isRenderableColor({ value })).slice(0, 8),
    displayFont: stringOrUndefined(e.displayFont) ?? 'Georgia, serif',
    bodyFont: stringOrUndefined(e.bodyFont) ?? '-apple-system, system-ui, sans-serif',
  };
}

/**
 * @module question-form/scan
 *
 * Markup segmentation for `<question-form>` / `<ask-question>` blocks:
 * locating open/close tags, splitting prose from form JSON, and the
 * tolerant streaming-recovery path that renders a partial form before its
 * JSON body has finished arriving. Split out of the original single-file
 * `question-form.ts`; see `../question-form.ts` for the public facade, the
 * block format, and the tag-name-alias rule.
 */
import { parsePartialJson } from '../partial-json.js';
import { parseQuotedAttrs } from '../util/markup-attributes.js';
import { asRecord, mapRawQuestion, nonEmptyString, omitUndefined, stringOrUndefined } from './normalize.js';
import type { FormQuestion, FormSegment, QuestionForm } from './types.js';

// `question-form` is the canonical tag; `ask-question` is an alias the model
// occasionally drifts to. The close tag must match the open tag name, so each
// match captures the name and computes its own close-tag string. Matching is
// case-insensitive so `<Question-Form>` / `<ASK-QUESTION>` still parse.
const OPEN_RE = /<(question-form|ask-question)\b([^>]*)>/i;

interface Block {
  start: number;
  bodyStart: number;
  /** Where the close tag starts, or `input.length` while it hasn't streamed in. */
  bodyEnd: number;
  /** Past the close tag, or `input.length` while it hasn't streamed in. */
  end: number;
  closed: boolean;
  rawAttrs: string;
}

/** The first question-form block opening at or after `from`, or `null` when there is none. */
function locateBlock({ input, from }: { input: string; from: number }): Block | null {
  const m = OPEN_RE.exec(input.slice(from));
  if (!m) return null;
  // Group 1 is a mandatory (non-optional) alternation and group 2 is an
  // unconditional `*`-quantified capture, so both always participate whenever
  // `m` itself is non-null — `noUncheckedIndexedAccess` just can't see that
  // from the regex alone.
  const closeTag = `</${m[1]!.toLowerCase()}>`;
  const start = from + m.index;
  const bodyStart = start + m[0].length;
  const closeIdx = findCloseTag(input, bodyStart, closeTag);
  const closed = closeIdx !== -1;
  return {
    start,
    bodyStart,
    bodyEnd: closed ? closeIdx : input.length,
    end: closed ? closeIdx + closeTag.length : input.length,
    closed,
    rawAttrs: m[2]!,
  };
}

/**
 * Split `input` into ordered prose/form segments. Scans repeatedly for
 * `question-form`/`ask-question` opens; for each, locates the matching close
 * tag and tries to parse the JSON body. A block that doesn't parse cleanly,
 * or has no close tag yet, is left in the prose stream verbatim.
 *
 * @complexity O(n) amortized in `input.length` — each iteration advances the
 *   cursor past the segment it just emitted.
 */
export function splitOnQuestionForms({ input }: { input: string }): FormSegment[] {
  const out: FormSegment[] = [];
  let cursor = 0;
  while (cursor < input.length) {
    const block = locateBlock({ input, from: cursor });
    if (!block?.closed) {
      // No block, or an unterminated one — leave the rest as prose so we don't swallow it.
      out.push({ kind: 'text', text: input.slice(cursor) });
      break;
    }
    if (block.start > cursor) {
      out.push({ kind: 'text', text: input.slice(cursor, block.start) });
    }
    const raw = input.slice(block.start, block.end);
    const form = tryParseForm(input.slice(block.bodyStart, block.bodyEnd), parseQuotedAttrs({ raw: block.rawAttrs }));
    // Malformed — keep raw text so the user can still see it.
    out.push(form ? { kind: 'form', form, raw } : { kind: 'text', text: raw });
    cursor = block.end;
  }
  return out;
}

/** The first complete, parseable `<question-form>` in `input`, or `null`. */
export function findFirstQuestionForm({ input }: { input: string }): { form: QuestionForm; raw: string } | null {
  for (const seg of splitOnQuestionForms({ input: input })) {
    if (seg.kind === 'form') return { form: seg.form, raw: seg.raw };
  }
  return null;
}

/**
 * Convenience wrapper over {@link findFirstQuestionForm} matching the
 * `parseQuestionForm()` name from the target API — returns just the form
 * (dropping the matched raw text), or `null` when `input` has no complete
 * question-form block. For a still-streaming block use
 * {@link parsePartialQuestionForm} instead.
 */
export function parseQuestionForm({ input }: { input: string }): QuestionForm | null {
  return findFirstQuestionForm({ input: input })?.form ?? null;
}

/**
 * Drop a trailing, not-yet-closed question-form block from streaming text so
 * a chat surface doesn't flash raw `<question-form>{…` markup before the
 * JSON finishes. Returns the visible text plus whether such an open block
 * existed (meaning a form is mid-generation).
 */
export function stripTrailingOpenQuestionForm({ input }: { input: string }): { text: string; hadOpenForm: boolean } {
  let cursor = 0;
  while (cursor < input.length) {
    const block = locateBlock({ input, from: cursor });
    if (!block) break;
    if (!block.closed) return { text: input.slice(0, block.start), hadOpenForm: true };
    cursor = block.end;
  }
  return { text: input, hadOpenForm: false };
}

/** `true` when a question-form open tag is present but its close tag hasn't streamed in yet. */
export function hasUnterminatedQuestionForm({ input }: { input: string }): boolean {
  return stripTrailingOpenQuestionForm({ input: input }).hadOpenForm;
}

function findCloseTag(input: string, from: number, closeTag: string): number {
  const closeLower = closeTag.toLowerCase();
  const tagLen = closeTag.length;
  const maxStart = input.length - tagLen;
  for (let i = from; i <= maxStart; i++) {
    if (input.slice(i, i + tagLen).toLowerCase() === closeLower) {
      return i;
    }
  }
  return -1;
}

function tryParseForm(body: string, attrs: Record<string, string>): QuestionForm | null {
  // Allow the JSON to be wrapped in a fenced ```json block — common when the
  // model echoes its own indented body.
  const stripped = body
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
  let data: unknown;
  try {
    data = JSON.parse(stripped);
  } catch {
    return null;
  }
  const obj = asRecord(data);
  if (!obj || !Array.isArray(obj.questions)) return null;
  const questions = obj.questions.flatMap((q: unknown, index) => mapRawQuestion({ q, index }) ?? []);
  if (questions.length === 0) return null;
  return assembleForm({ attrs, top: obj, bodyId: stringOrUndefined(obj.id), bodyTitle: stringOrUndefined(obj.title), questions });
}

// Form-level fields shared by the complete and streaming parsers: the open
// tag's attrs win over the body's own id/title, which win over the defaults.
function assembleForm({ attrs, top, bodyId, bodyTitle, questions }: {
  attrs: Record<string, string>;
  top: Record<string, unknown>;
  bodyId: string | undefined;
  bodyTitle: string | undefined;
  questions: FormQuestion[];
}): QuestionForm {
  return omitUndefined({
    id: attrs.id ?? bodyId ?? 'discovery',
    title: attrs.title ?? bodyTitle ?? 'A few quick questions',
    questions,
    description: nonEmptyString(top.description),
    submitLabel: nonEmptyString(top.submitLabel),
  });
}

/**
 * Tolerant parser for a still-streaming `<question-form>` block. Unlike
 * {@link tryParseForm} it does not require valid, complete JSON: it reads the
 * title/id from the open tag's attrs (available the instant the tag streams
 * in) and extracts however many *complete* question objects have arrived so
 * far, so a Questions panel can render a frame immediately and fill
 * questions in progressively. Returns `null` only when no open tag is
 * present at all.
 *
 * @complexity O(n) in `input.length` (one regex scan plus a linear
 *   string-aware brace walk via {@link parsePartialJson}).
 */
export function parsePartialQuestionForm({ input }: { input: string }): QuestionForm | null {
  const block = locateBlock({ input, from: 0 });
  if (!block) return null;
  const rawBody = input.slice(block.bodyStart, block.bodyEnd);
  // Strip the fenced ```json wrapper some models emit. The opening fence is
  // removed always; the trailing fence is removed too once it streams in
  // (possibly only a partial ``` so far) — otherwise leftover backticks make
  // the JSON unparseable in the gap between "fence closed" and
  // "</question-form> arrived", dropping the live preview back to empty.
  const body = stripTrailingFence(rawBody.replace(/^\s*```(?:json)?\s*/i, ''));
  // Derive form-level metadata from the *parsed top-level object*, not a
  // whole-body regex scan: a nested question/option `id`/`title`/`description`
  // must not masquerade as the form's own.
  const top = asRecord(parsePartialJson({ buf: body })) ?? {};
  const title = stringOrUndefined(top.title);
  // `id` keys a still-editable panel, so it must be stable for the whole
  // stream — don't adopt it until its string literal is fully terminated,
  // otherwise it would churn character-by-character and remount the panel.
  return assembleForm({
    attrs: parseQuotedAttrs({ raw: block.rawAttrs }),
    top,
    bodyId: completeTopLevelString(body, 'id'),
    bodyTitle: title?.trim() ? title : undefined,
    questions: shapeStreamingQuestions(top.questions, countClosedQuestionObjects(body)),
  });
}

// Strip a trailing ``` fence (possibly only partially streamed) from a form
// body — but only when those backticks are the closing wrapper, not content
// of a JSON string value still being typed.
function stripTrailingFence(body: string): string {
  const m = /\s*`{1,3}\s*$/.exec(body);
  if (!m) return body;
  const before = body.slice(0, m.index);
  if (endsInsideJsonString(before)) return body;
  return before;
}

function endsInsideJsonString(s: string): boolean {
  for (let i = s.indexOf('"'); i !== -1; i = s.indexOf('"', i)) {
    i = jsonStringEnd({ s, start: i });
    if (i === -1) return true;
  }
  return false;
}

// Index just past the closing quote of the JSON string literal whose opening
// quote is at `start`, or -1 when that literal hasn't finished streaming.
function jsonStringEnd({ s, start }: { s: string; start: number }): number {
  for (let i = start + 1; i < s.length; i++) {
    if (s[i] === '\\') i++;
    else if (s[i] === '"') return i + 1;
  }
  return -1;
}

const DEPTH_DELTA: Record<string, number> = { '{': 1, '[': 1, '}': -1, ']': -1 };

// Return a top-level (depth-1) string field's value ONLY if its string
// literal is fully terminated in the (possibly partial) body. Depth-aware so
// a nested question `id` can't be mistaken for the form's own.
function completeTopLevelString(body: string, field: string): string | undefined {
  const marker = `"${field}"`;
  let depth = 0;
  for (let i = 0; i < body.length; i++) {
    const c = body[i] as string;
    if (c !== '"') {
      depth += DEPTH_DELTA[c] ?? 0;
      continue;
    }
    const valueStart = depth === 1 ? keyValueStart({ body, at: i, marker }) : -1;
    if (valueStart !== -1) return readStringLiteral({ body, start: valueStart });
    // A string that isn't our key (any other key, or a value) — skip it.
    const end = jsonStringEnd({ s: body, start: i });
    if (end === -1) return undefined;
    i = end - 1;
  }
  return undefined;
}

const KEY_COLON_RE = /\s*:\s*/y;

// Where the value starts when the string literal at `at` is the `marker` key,
// or -1 when it isn't — including a value string that merely spells the key,
// which no `:` follows.
function keyValueStart({ body, at, marker }: { body: string; at: number; marker: string }): number {
  if (!body.startsWith(marker, at)) return -1;
  KEY_COLON_RE.lastIndex = at + marker.length;
  return KEY_COLON_RE.test(body) ? KEY_COLON_RE.lastIndex : -1;
}

// The decoded string literal at `start`, or `undefined` when the value isn't
// a (started) string or its closing quote hasn't streamed yet.
function readStringLiteral({ body, start }: { body: string; start: number }): string | undefined {
  if (body[start] !== '"') return undefined; // value not a (started) string
  const end = jsonStringEnd({ s: body, start });
  if (end === -1) return undefined; // closing quote hasn't streamed yet
  const value = body.slice(start + 1, end - 1);
  try {
    return JSON.parse(`"${value}"`) as string;
  } catch {
    return value;
  }
}

function shapeStreamingQuestions(rawQuestions: unknown, closedCount: number): FormQuestion[] {
  if (!Array.isArray(rawQuestions)) return [];
  const out: FormQuestion[] = [];
  rawQuestions.forEach((raw, index) => {
    const q = asRecord(raw);
    if (!q) return;
    const label = q.label;
    if (typeof label !== 'string' || label.trim().length === 0) return;
    // Surface a question only once its canonical id is determinable, so the
    // preview id matches what the final parse assigns: a closed object's id
    // is final; an in-flight object needs an explicit id already present.
    const isClosed = index < closedCount;
    const hasId = typeof q.id === 'string' && q.id.trim().length > 0;
    if (!isClosed && !hasId) return;
    const mapped = mapRawQuestion({ q: raw, index: index });
    if (mapped) out.push(mapped);
  });
  return out;
}

// Count how many question objects in a partial `"questions": [ … ]` body
// have their closing brace already streamed (string-aware).
function countClosedQuestionObjects(body: string): number {
  const keyMatch = /"questions"\s*:\s*\[/.exec(body);
  if (!keyMatch) return 0;
  let i = keyMatch.index + keyMatch[0].length;
  let count = 0;
  for (;;) {
    while (i < body.length && /[\s,]/.test(body[i] as string)) i++;
    // Past the end, at `]`, or at a non-object element: nothing more to count.
    if (body[i] !== '{') return count;
    i = balancedObjectEnd({ s: body, start: i });
    if (i === -1) return count; // trailing object hasn't closed yet
    count++;
  }
}

// Index just past the balanced `{...}` object starting at `start`, or -1 if
// it never closes (string-aware so braces inside strings don't count).
function balancedObjectEnd({ s, start }: { s: string; start: number }): number {
  let depth = 0;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (c === '"') {
      const end = jsonStringEnd({ s, start: i });
      if (end === -1) return -1;
      i = end - 1;
    } else if (c === '{') {
      depth++;
    } else if (c === '}' && --depth === 0) {
      return i + 1;
    }
  }
  return -1;
}

/** Chat question forms are model-visible text, never secure credential storage. */
import { redactUserText, type UserTextRedactionOptions, type UserTextRedaction } from '../user-text-redaction.js';
import type { FormQuestion, QuestionForm } from './types.js';

export function isSecretQuestion({ question }: { readonly question: Pick<FormQuestion, 'id' | 'label' | 'type' | 'name'> }): boolean {
  if (question.type !== 'text' && question.type !== 'textarea') return false;
  const names = [question.id, question.label, question.name ?? ''].join(' ').replace(/([a-z])([A-Z])/g, '$1 $2');
  return /(?:^|[^a-z0-9])(?:key|token|password|passwd|secret)(?:$|[^a-z0-9])/i.test(names);
}

/** The map as well as its formatted transcript must be safe: hosts often persist both. */
export function redactQuestionAnswers(
  { form, answers }: { readonly form: QuestionForm; readonly answers: Readonly<Record<string, string | string[]>> },
  options: UserTextRedactionOptions = {},
): { readonly answers: Record<string, string | string[]>; readonly secretRedacted: boolean; readonly count: number } {
  let count = 0;
  const cleaned: Record<string, string | string[]> = {};
  const redact = options.redactUserText ?? redactUserText;
  for (const question of form.questions) {
    const value = answers[question.id];
    if (value === undefined) continue;
    const guard = (text: string): string => {
      const result: UserTextRedaction = redact({ text }, { secretField: isSecretQuestion({ question }) });
      count += result.count;
      return result.text;
    };
    cleaned[question.id] = Array.isArray(value) ? value.map(guard) : guard(value);
  }
  if (count > 0) options.onSecretRedacted?.({ secretRedacted: true, count });
  return { answers: cleaned, secretRedacted: count > 0, count };
}

/** Never populate a credential text question from model-supplied defaults. */
export function withoutSecretQuestionDefaults({ form }: { readonly form: QuestionForm }): QuestionForm {
  return { ...form, questions: form.questions.map(question => {
    if (!isSecretQuestion({ question })) return question;
    const { defaultValue: _defaultValue, ...safe } = question;
    return safe;
  }) };
}

/** Attributes are presentation policy, shared by any host renderer. */
export function questionTextInputProps({ question }: { readonly question: FormQuestion }): { type: 'password' | 'text'; autoComplete?: string; spellCheck?: boolean } {
  return isSecretQuestion({ question }) ? { type: 'password', autoComplete: 'new-password', spellCheck: false } : { type: 'text' };
}

export function questionTextareaProps({ question }: { readonly question: FormQuestion }): { autoComplete?: string; spellCheck?: boolean; style?: { WebkitTextSecurity: string; whiteSpace: 'pre-wrap' } } {
  return isSecretQuestion({ question }) ? { autoComplete: 'off', spellCheck: false, style: { WebkitTextSecurity: 'disc', whiteSpace: 'pre-wrap' } } : {};
}

/**
 * @module run-activity
 *
 * What a running turn is doing right now, as one short line ("Running Page Fill… 1 m 20 s").
 *
 * Why: once a turn's first tool row appeared, nothing on screen showed the run was still alive —
 * the old "Thinking…" placeholder only showed while the message was completely empty. Model think
 * time, long tool calls, held cards and API overload retries all looked identical: dead.
 *
 * Shape: {@link deriveRunActivity} reads the events the pane already has and returns the latest
 * signal; {@link RUN_ACTIVITY_LABELS} is the ONE table that turns a signal into words. The clock
 * (seconds since the signal began) is the caller's: the React hook ticks it once a second. Nothing
 * here special-cases a particular tool.
 *
 * Status events this reads (a host translates its runtime's heartbeats into them):
 * - `code: 'api_retry'`, `data: { attempt, maxAttempts, service? }` — the model API is overloaded.
 * - `code: 'tool_progress'`, `data: { elapsedSeconds }` — a tool call is still running.
 * - `code: 'thinking'` — the model is reasoning (keeps the idle timer honest).
 */
import { a2uiSurfaceIdOf, displayOnlySurfaceIdOf } from '@jini-ai/agentic/a2ui';
import type { AgentEvent } from './events.js';
import { isDelegatedWrapperToolName } from './tool-events.js';
import { MID_RUN_USER_MESSAGE_EVENT_NAME } from './turn-usage.js';
import { SURFACE_QUESTION_META_KEY } from './question-answer.js';
import { recordedSurfaceAnswers } from './accepted-input.js';

/** The latest thing a running turn is doing. */
export type RunActivity =
  | { readonly kind: 'thinking' }
  | { readonly kind: 'writing' }
  | { readonly kind: 'finding-tool' }
  | { readonly kind: 'running-tool'; readonly tool: string; readonly reportedSeconds?: number }
  | { readonly kind: 'awaiting-answer' }
  | { readonly kind: 'retrying'; readonly attempt?: number; readonly maxAttempts?: number; readonly service?: string };

/** {@link deriveRunActivity}'s result: the signal, plus a key that changes whenever the signal restarts. */
export interface RunActivityState {
  readonly activity: RunActivity;
  /** Changes when a new signal begins, so the caller restarts its clock (e.g. `tool:<id>`). */
  readonly key: string;
  /** Count of events the person can see (text, tool rows, cards). A change means "something new". */
  readonly visibleCount: number;
}

/** Tool names whose only job is finding the right tool (MCP tool search / schema lookup). */
const DISCOVERY_TOOL_NAMES = new Set([
  'ToolSearch',
  'search_tools',
  'describe_tool',
  'mcp__jini__search_tools',
  'mcp__jini__describe_tool',
]);

/** Ext events that are a card for the person (a form, a confirm, a sign-in). */
const CARD_EXT_NAMES = new Set(['mcp-ui', 'a2ui']);

/** The A2UI ext name: its surfaces may declare themselves display-only (`@jini-ai/agentic/a2ui`). */
const A2UI_EXT_NAME = 'a2ui';

/** After this long with nothing new on screen, a thinking/writing line says "Still working…". */
export const RUN_ACTIVITY_IDLE_MS = 20_000;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function numberField(data: unknown, key: string): number | undefined {
  const value = isRecord(data) ? data[key] : undefined;
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function stringField(data: unknown, key: string): string | undefined {
  const value = isRecord(data) ? data[key] : undefined;
  return typeof value === 'string' && value ? value : undefined;
}

/** `"page.fill"` → `"Page Fill"`, `"mcp__supabase__list_projects"` → `"List Projects"`. Display only. */
export function humanizeToolName({ name }: { name: string }, { input }: { input?: (unknown) | undefined } = {}): string {
  // A transport wrapper's real tool id is in `input.toolId`.
  const real = isDelegatedWrapperToolName({ name: name }) ? (stringField(input, 'toolId') ?? name) : name;
  const bare = real.startsWith('mcp__') ? real.split('__').slice(2).join('__') || real : real;
  return bare
    .split(/[._\s]+/)
    .filter(Boolean)
    .map((word) => word[0]!.toUpperCase() + word.slice(1))
    .join(' ');
}

interface OpenTool {
  readonly id: string;
  readonly name: string;
  readonly input: unknown;
  readonly index: number;
}

interface Scan {
  open: OpenTool[];
  lastVisible: { index: number; kind: AgentEvent['kind'] } | null;
  lastCardIndex: number;
  standaloneCardIndex: number;
  pendingQuestionIndex: number;
  lastWorkIndex: number;
  retry: { index: number; data: unknown } | null;
  progress: { index: number; seconds: number } | null;
  visibleCount: number;
  /** A2UI surfaces whose `createSurface` declared display-only: a chart, not a question. */
  displayOnlySurfaces: Set<string>;
  /** See {@link RunActivityOptions.isAnsweredCard}. */
  isAnsweredCard: IsAnsweredCard | undefined;
  answeredSurfaces: ReadonlyMap<unknown, string>;
}

/** Whether the person already answered a card, before its tool call returned. */
export type IsAnsweredCard = (card: { name: string; data: unknown }) => boolean;

export interface RunActivityOptions {
  /**
   * A card the person answered no longer waits on them, even though its tool call stays open while
   * the confirmed work runs (a publish can take minutes). Without this the line kept saying
   * "Waiting for your answer above" under a card that already read "Done." (owner, 2026-10-11).
   */
  isAnsweredCard?: IsAnsweredCard | undefined;
}

function isVisible(event: AgentEvent): boolean {
  return event.kind === 'text' ? event.text.length > 0 : event.kind === 'tool_use' || event.kind === 'tool_result' || event.kind === 'ext';
}

/**
 * Whether an ext event is a card the person must answer. A display-only A2UI surface shows
 * something and asks nothing, so a tool holding its call open after drawing one (assistant_render_ui
 * waits a few seconds to hear a browser refusal) must not read as "Waiting for your answer above"
 * (demo V3, 2026-10-05).
 */
function isAnswerCard(scan: Scan, name: string, data: unknown): boolean {
  if (!CARD_EXT_NAMES.has(name)) return false;
  if (name === 'mcp-ui' && scan.answeredSurfaces.has(data)) return false;
  if (scan.isAnsweredCard?.({ name, data }) === true) return false;
  if (name !== A2UI_EXT_NAME) return true;
  const displayOnlyId = displayOnlySurfaceIdOf({ message: data });
  if (displayOnlyId !== undefined) scan.displayOnlySurfaces.add(displayOnlyId);
  const surfaceId = a2uiSurfaceIdOf({ message: data });
  return surfaceId === undefined || !scan.displayOnlySurfaces.has(surfaceId);
}

function scanStatus(
  { scan, event, index }: { scan: Scan; event: Extract<AgentEvent, { kind: 'status' }>; index: number },
  _optional: {} = {},
): void {
  if (event.code === 'api_retry') {
    scan.retry = { index, data: event.data };
  } else if (event.code === 'tool_progress') {
    const seconds = numberField(event.data, 'elapsedSeconds');
    if (seconds !== undefined) scan.progress = { index, seconds };
  }
}

function scanEvent(scan: Scan, event: AgentEvent, index: number): void {
  // Queue acceptance/consumption is user input, not new agent activity. Neither restarts its clock.
  if (event.kind === 'ext' && event.name === MID_RUN_USER_MESSAGE_EVENT_NAME) return;
  if (WORK_EVENT_KINDS.has(event.kind)) scan.lastWorkIndex = index;
  if (isVisible(event)) {
    scan.lastVisible = { index, kind: event.kind };
    scan.visibleCount += 1;
  }
  // Starting tool work after an explicit question proves the run moved past it (expired, skipped or aborted
  // without a receipt); otherwise its waiting line would outlive the question for the whole run.
  if (event.kind === 'tool_use') {
    scan.pendingQuestionIndex = -1;
    scan.open = scan.open.filter((tool) => tool.id !== event.id);
    scan.open.push({ id: event.id, name: event.name, input: event.input, index });
  } else if (event.kind === 'tool_result') {
    // Completion may be unrelated background work or the ask tool returning before human input.
    scan.open = scan.open.filter((tool) => tool.id !== event.toolUseId);
  } else if (event.kind === 'ext') {
    scanCard({ scan, event, index });
  } else if (event.kind === 'status') {
    scanStatus({ scan, event, index });
  }
}

/** Work after a standalone form proves the run has moved past that form. */
const WORK_EVENT_KINDS: ReadonlySet<AgentEvent['kind']> = new Set<AgentEvent['kind']>(['text', 'tool_use', 'tool_result']);

/** Standalone approval forms have no open tool call. Require interactive markup so outcome
 * documents do not acquire a waiting status. Inspect text only; this never executes a document. */
function scanCard({ scan, event, index }: {
  scan: Scan; event: Extract<AgentEvent, { kind: 'ext' }>; index: number;
}, _options = {}): void {
  if (!isAnswerCard(scan, event.name, event.data)) return;
  scan.lastCardIndex = index;
  const resource = isRecord(event.data) ? event.data.resource : undefined;
  const html = isRecord(resource) ? resource.text : undefined;
  const meta = isRecord(resource) ? resource._meta : undefined;
  // A producer can retain its question before flattening it into a document (including custom forms).
  const question = isRecord(meta) ? meta[SURFACE_QUESTION_META_KEY] : undefined;
  if (isRecord(question)) scan.pendingQuestionIndex = index;
  if (typeof html === 'string' && /<form\b|data-mcpui-action\s*=/i.test(html)) scan.standaloneCardIndex = index;
}

/** `{ a: 1, b: undefined }` → `{ a: 1 }`, so optional activity fields are absent rather than undefined. */
function definedFields<T extends Record<string, unknown>>(
  { fields }: { fields: T },
  _optional: {} = {},
): { [K in keyof T]?: Exclude<T[K], undefined> } {
  return Object.fromEntries(Object.entries(fields).filter(([, value]) => value !== undefined)) as { [K in keyof T]?: Exclude<T[K], undefined> };
}

function retryingActivity({ data }: { data: unknown }, _optional: {} = {}): RunActivity {
  return {
    kind: 'retrying',
    ...definedFields({
      fields: {
        attempt: numberField(data, 'attempt'),
        maxAttempts: numberField(data, 'maxAttempts'),
        service: stringField(data, 'service'),
      },
    }),
  };
}

/** The signal while a tool call is open: a card waiting on the person, tool discovery, or the tool itself. */
function openToolSignal(
  { scan, newestOpen }: { scan: Scan; newestOpen: OpenTool },
  _optional: {} = {},
): Pick<RunActivityState, 'activity' | 'key'> {
  if (scan.lastCardIndex > newestOpen.index) {
    return { activity: { kind: 'awaiting-answer' }, key: `card:${scan.lastCardIndex}` };
  }
  const key = `tool:${newestOpen.id}`;
  if (DISCOVERY_TOOL_NAMES.has(newestOpen.name)) return { activity: { kind: 'finding-tool' }, key };
  const reported = scan.progress && scan.progress.index > newestOpen.index ? scan.progress.seconds : undefined;
  return {
    activity: {
      kind: 'running-tool',
      tool: humanizeToolName({ name: newestOpen.name }, { input: newestOpen.input }),
      ...definedFields({ fields: { reportedSeconds: reported } }),
    },
    key,
  };
}

function latestSignal({ scan }: { scan: Scan }, _optional: {} = {}): Pick<RunActivityState, 'activity' | 'key'> {
  // Explicit standalone questions wait for their receipt; unrelated startup/model activity cannot
  // establish that a person answered. Markup-only legacy cards retain their existing work heuristic.
  if (scan.pendingQuestionIndex >= 0) {
    return { activity: { kind: 'awaiting-answer' }, key: `card:${scan.pendingQuestionIndex}` };
  }
  const lastVisibleIndex = scan.lastVisible?.index ?? -1;
  if (scan.retry && scan.retry.index > lastVisibleIndex) {
    return { activity: retryingActivity({ data: scan.retry.data }), key: `retry:${lastVisibleIndex}` };
  }
  const newestOpen = scan.open[scan.open.length - 1];
  if (newestOpen) return openToolSignal({ scan, newestOpen });
  return idleSignal({ scan });
}

/** The no-open-tool fallback; legacy markup alone stops waiting when work follows it. O(1). */
function idleSignal({ scan }: { scan: Scan }, _options = {}): Pick<RunActivityState, 'activity' | 'key'> {
  const lastVisibleIndex = scan.lastVisible?.index ?? -1;
  if (scan.standaloneCardIndex > scan.lastWorkIndex) {
    return { activity: { kind: 'awaiting-answer' }, key: `card:${scan.standaloneCardIndex}` };
  }
  if (scan.lastVisible?.kind === 'text') {
    return { activity: { kind: 'writing' }, key: `writing:${lastVisibleIndex}` };
  }
  return { activity: { kind: 'thinking' }, key: `thinking:${lastVisibleIndex}` };
}

/**
 * The latest signal in a running turn's events.
 *
 * Precedence, newest wins: an API retry with nothing visible after it; a card that arrived while a
 * tool call is still open (the tool is waiting on the person; a display-only A2UI surface is not a
 * card); the newest open tool call; else
 * writing (last visible event is text) or thinking.
 *
 * @complexity O(n) time in events, O(open tool calls + answered surfaces) extra space.
 */
export function deriveRunActivity(
  { events }: { events: readonly AgentEvent[] | undefined },
  { isAnsweredCard }: RunActivityOptions = {},
): RunActivityState {
  // A replayed standalone receipt closes only the document it followed, not every use of its URI.
  const answeredSurfaces = recordedSurfaceAnswers({ events: events ?? [] });
  const scan: Scan = { open: [], lastVisible: null, lastCardIndex: -1, standaloneCardIndex: -1, pendingQuestionIndex: -1, lastWorkIndex: -1, retry: null, progress: null, visibleCount: 0, displayOnlySurfaces: new Set(), isAnsweredCard, answeredSurfaces };
  (events ?? []).forEach((event, index) => scanEvent(scan, event, index));
  return { ...latestSignal({ scan }), visibleCount: scan.visibleCount };
}

/**
 * Whether the run is waiting on the person: a card (form, confirm, sign-in) arrived while its tool
 * call is still open. Hosts use it to hide "still working" notices, which read as a hung run while
 * the run is really waiting for an answer.
 *
 * @complexity O(n) in events.
 */
export function isAwaitingAnswer({ events }: { events: readonly AgentEvent[] | undefined }, options: RunActivityOptions = {}): boolean {
  return deriveRunActivity({ events }, options).activity.kind === 'awaiting-answer';
}

/** `4` → `"4 s"`, `80` → `"1 m 20 s"`, `120` → `"2 m 0 s"`. */
export function formatActivityClock({ totalSeconds }: { totalSeconds: number }): string {
  const seconds = Math.max(0, Math.floor(totalSeconds));
  const minutes = Math.floor(seconds / 60);
  return minutes > 0 ? `${minutes} m ${seconds % 60} s` : `${seconds} s`;
}

/** A translator: the chat package's `t(key, vars)`. */
export type RunActivityTranslate = (key: string, vars?: Record<string, string | number>) => string;

/** The clock values a label may use. */
export interface RunActivityClock {
  /** Seconds since this signal began (already corrected by any `tool_progress` report). */
  readonly seconds: number;
  /** Milliseconds since anything new appeared on screen. */
  readonly idleMs: number;
}

/**
 * THE event → words table. One entry per {@link RunActivity} kind; nothing else in the package
 * decides what the activity line says. Keys are English source strings for the host's `t()`.
 */
export const RUN_ACTIVITY_LABELS: {
  readonly [K in RunActivity['kind']]: (
    activity: Extract<RunActivity, { kind: K }>,
    clock: RunActivityClock,
    t: RunActivityTranslate,
  ) => string;
} = {
  thinking: (_a, clock, t) =>
    clock.idleMs >= RUN_ACTIVITY_IDLE_MS
      ? t('Still working… {time}', { time: formatActivityClock({ totalSeconds: clock.seconds }) })
      : t('Thinking… {time}', { time: formatActivityClock({ totalSeconds: clock.seconds }) }),
  writing: (_a, clock, t) =>
    clock.idleMs >= RUN_ACTIVITY_IDLE_MS
      ? t('Still working… {time}', { time: formatActivityClock({ totalSeconds: clock.seconds }) })
      : t('Writing…'),
  'finding-tool': (_a, clock, t) => t('Finding the right tool… {time}', { time: formatActivityClock({ totalSeconds: clock.seconds }) }),
  'running-tool': (a, clock, t) => t('Running {tool}… {time}', { tool: a.tool, time: formatActivityClock({ totalSeconds: clock.seconds }) }),
  // No clock: the run is waiting on the person, not working, and a ticking timer under an open
  // form read as a hung run (demo dry-run, 2026-10-05).
  'awaiting-answer': (_a, _clock, t) => t('Waiting for your answer above'),
  retrying: (a, _clock, t) => {
    const who = a.service ? t("{service}'s servers are busy", { service: a.service }) : t('The AI service is busy');
    return a.attempt !== undefined && a.maxAttempts !== undefined
      ? t('{who} — retrying ({attempt} of {max})…', { who, attempt: a.attempt, max: a.maxAttempts })
      : t('{who} — retrying…', { who });
  },
};

/**
 * The activity line's text for a signal and clock.
 *
 * @complexity O(1).
 */
export function describeRunActivity({ activity, clock, t }: { activity: RunActivity; clock: RunActivityClock; t: RunActivityTranslate }): string {
  const label = RUN_ACTIVITY_LABELS[activity.kind] as (a: RunActivity, c: RunActivityClock, tr: RunActivityTranslate) => string;
