  readonly terminal?: Extract<ChatRunStatus, "succeeded" | "failed" | "canceled">;
}

function parseWire(raw: string | undefined): RunProtocolEventWire | null {
  if (!raw) return null;
  try {
    const parsed: unknown = JSON.parse(raw);
    return isRecord(parsed) ? parsed as unknown as RunProtocolEventWire : null;
  } catch {
    return null;
  }
}

/** A wire frame's `payload` when it is a plain object; `null` for an absent, malformed or bare body. */
function parseWirePayload(raw: string | undefined): Record<string, unknown> | null {
  const payload: unknown = parseWire(raw)?.payload;
  return isRecord(payload) ? payload : null;
}

function parseJsonLine(line: string): Record<string, unknown> | null {
  if (!line.startsWith("{")) return null;
  try {
    // A line starting with `{` either parses to a plain object or throws; it cannot parse to an
    // array, a scalar or `null`, so no shape check is needed after the parse.
    return JSON.parse(line) as Record<string, unknown>;
  } catch {
    return null;
  }
}

function numberOf(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}
/** `{attempt, maxAttempts}` from an `api_retry` line, keeping only the fields it actually carries. */
// `api_retry` is Claude Code's own line shape, so the service it names is Claude.


function retryData(line: Record<string, unknown>): Record<string, string | number> {
  const attempt = numberOf(line.attempt);
  const maxAttempts = numberOf(line.max_retries);
  return { ...(attempt !== undefined ? { attempt } : {}), ...(maxAttempts !== undefined ? { maxAttempts } : {}), service: "Claude" };
}
/**
 * Claude Code's stdout heartbeats → typed `status` events for the live activity line
 * (`@jini-ai/chat`'s `run-activity.ts` reads `code`/`data`). `null` for any other line.
 */


function heartbeatStatus(line: Record<string, unknown>): AgentEvent | null {
  if (line.type === "tool_progress") {
    const elapsedSeconds = numberOf(line.elapsed_time_seconds);
    return { kind: "status", code: "tool_progress", label: "tool_progress", ...(elapsedSeconds !== undefined ? { data: { elapsedSeconds } } : {}) };
  }
  if (line.type !== "system") return null;
  if (line.subtype === "api_retry") {
    const detail = [numberOf(line.error_status), typeof line.error === "string" ? line.error : undefined].filter((p) => p !== undefined).join(" ");
    return { kind: "status", code: "api_retry", label: "api_retry", ...(detail ? { detail } : {}), data: retryData(line) };
  }
  if (line.subtype === "thinking_tokens") return { kind: "status", code: "thinking", label: "thinking" };
  return null;
}
/**
 * Lines the daemon has already parsed into typed events, so keeping them as `raw` only stores them
 * twice: `stream_event` (the token-by-token echo `--include-partial-messages` adds → `text`), and the
 * whole `assistant`/`user` messages (→ `text`/`thinking`/`tool_use`/`tool_result`). The `user` echo
 * repeats every tool result: one "summarize my posts" turn saved 129 KB of them. Matched on the
 * line's start, not a parse, because a long line arrives split over several stdout chunks and its
 * first piece is not valid JSON on its own. Claude Code writes `type` first on every line.
 */


const ECHO_LINE = /^\{"type":"(?:stream_event|assistant|user)"/;
/**
 * Per-connection memory for {@link translateRunFrame}: which channels are mid-way through an echo
 * line. Only a line's first chunk carries the {@link ECHO_LINE} prefix, so without it the rest of a
 * split `user` echo stays as `raw` — tool-result prose that durable recovery then reads as executor
 * diagnostics. Pass one fresh `{}` per daemon connection (each connection replays from event 0).
 */
export interface RunFrameCarry {
  openEchoChannels?: Set<string>;
}
/**
 * One CLI stdout/stderr chunk → events. Every JSON line that is a heartbeat also yields a typed
 * `status` event; echo lines ({@link ECHO_LINE}) are dropped — with a `carry`, including the later
 * chunks of a split one; everything else stays in ONE `raw` event, verbatim. A chunk with no JSON
 * lines at all (a plain-format CLI) is one `raw` event, as before.
 */


function chunkEvent(raw: string | undefined, channel: string, carry?: RunFrameCarry): AgentEvent[] {
  const frame = parseWire(raw);
  if (!frame) return [];
  const chunk = wireString((frame.payload as { chunk?: unknown } | null)?.chunk);
  const open = carry ? (carry.openEchoChannels ??= new Set()) : undefined;
  const { kept, statuses, droppedAny } = splitChunk({ chunk, channel }, { open });
  const line = droppedAny ? kept : chunk;
  return line.length > 0 ? [{ kind: "raw", line }, ...statuses] : statuses;
}

/** A chunk's non-echo text and heartbeat statuses, and whether any echo piece was dropped. */
function splitChunk(
  { chunk, channel }: { chunk: string; channel: string },
  { open }: { open?: Set<string> | undefined } = {},
): { kept: string; statuses: AgentEvent[]; droppedAny: boolean } {
  const statuses: AgentEvent[] = [];
  let kept = "";
  let droppedAny = false;
  chunk.split(/(?<=\n)/).forEach((piece, index) => {
    if (isEchoPiece({ piece, channel, first: index === 0 }, { open })) {
      droppedAny = true;
      return;
    }
    const status = pieceStatus(piece);
    if (status) statuses.push(status);
    kept += piece;
  });
  return { kept, statuses, droppedAny };
}

/** Whether a piece belongs to an echo line, updating which channels are mid-way through one. */
function isEchoPiece(
  { piece, channel, first }: { piece: string; channel: string; first: boolean },
  { open }: { open?: Set<string> | undefined } = {},
): boolean {
  // Only a chunk's first piece can continue the previous chunk's line; splitting on "\n" starts
  // every later piece on a fresh line. Channels are tracked apart: stderr can interleave mid-line.
  const echo = (first && open?.has(channel) === true) || ECHO_LINE.test(piece.trimStart());
  if (echo && !piece.endsWith("\n")) open?.add(channel);
  else open?.delete(channel);
  return echo;
}

function pieceStatus(piece: string): AgentEvent | null {
  const line = parseJsonLine(piece.trim());
  return line ? heartbeatStatus(line) : null;
}
// Order matters and matches the browser's `end` listener: the `max_tool_turns` notice first, then
// the failed/canceled notice, then the failure itself.


function endOutcome(raw: string | undefined, notices: RunNotices): RunFrameOutcome {
  const events: AgentEvent[] = [];
  const reasonNotice = terminalReasonNotice({ reason: readTerminalReason({ raw, wrapped: true }), notice: notices.toolStepLimit });
  if (reasonNotice) events.push(reasonNotice);
  const outcomeNotice = terminalOutcomeNotice({ raw, notices });
  if (outcomeNotice) events.push(outcomeNotice);
  const error = terminalFailureError({ raw });
  const outcome = readTerminalOutcome({ raw });
  const terminal = outcome?.status ?? "succeeded";
  return error ? { events, error, terminal } : { events, terminal };
}
/**
 * Translates one named daemon SSE frame (`event:` name plus raw `data:` text) into its effect on the
 * turn. The browser's `subscribeToRun` dispatches the result to `RunHandlers`; the server finalizer
 * folds it into the row it saves. Never throws: a malformed frame yields no events rather than
 * stranding either reader mid-turn.
 *
 * An `error` frame with no data is a connection error, not a run error — the browser's
 * `EventSource` reports those on the same event name, so it must check for data before calling this.
 *
 * @complexity O(size of the frame).
 */
/** Fold one named daemon frame into events, a failure and an optional terminal status. */
export function translateRunFrame({ kind, raw, notices }: { kind: string; raw: string | undefined; notices: RunNotices }, { carry }: { carry?: RunFrameCarry } = {}): RunFrameOutcome {
  switch (kind) {
    case "agent":
      return { events: agentFrameEvents(raw) };
    // The agent CLI's own output. `stderr` is where a dying CLI says WHY it is dying.
    case "stdout":
    case "stderr":
      return { events: chunkEvent(raw, kind, carry) };
    case "error":
      return errorFrameOutcome(raw);
    case "end":
      return endOutcome(raw, notices);
    default:
      return { events: [] };
  }
}

function agentFrameEvents(raw: string | undefined): AgentEvent[] {
  const payload = parseWirePayload(raw);
  const translated = typeof payload?.type === "string" ? translateRunAgentPayload({ payload: payload as RunAgentPayload }) : null;
  return translated ? [translated] : [];
}

// Shown AND saved as a status line, not only reported: the error is live-only state, so without
// the event the saved turn (and a reload) showed a bare "failed" with the reason lost. This is
// where the daemon's plain pre-spawn reason ("The assistant could not start: ...") and the
// host's start refusals reach the user.
function errorFrameOutcome(raw: string | undefined): RunFrameOutcome {
  const frame = parseWire(raw);
  const payload = frame?.payload as { message?: unknown; error?: { code?: unknown } } | null;
  const message = wireString(payload?.message) || "agent run failed";
  return { events: [{ kind: "status", label: message, ...(typeof payload?.error?.code === "string" ? { code: payload.error.code } : {}) }], error: new Error(message) };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * @module todos
 *
 * Pure TodoWrite-style plan-tool snapshot parsing/derivation. Reads the
 * structured plan a `TodoWrite`/`update_plan`-shaped tool call carries and
 * derives the "latest plan state" a pinned progress card renders — no I/O,
 * no framework.
 */
import type { AgentEvent } from './events.js';
import { isTerminalRunStatus, type ChatRunStatus } from './messages.js';

export type TodoStatus = 'pending' | 'in_progress' | 'completed' | 'stopped';

export interface TodoItem {
  content: string;
  status: TodoStatus;
  activeForm?: string | undefined;
}

const TODO_WRITE_TOOL_NAMES: ReadonlySet<string> = new Set([
  'TodoWrite',
  'todowrite',
  'todo_write',
  'update_plan',
]);

/** `true` when `name` is one of the accepted plan/TodoWrite tool-name spellings. */
export function isTodoWriteToolName({ name }: { name: string }): boolean {
  return TODO_WRITE_TOOL_NAMES.has(name);
}

function normalizeTodoStatus(status: unknown): TodoStatus {
  if (status === 'completed' || status === 'in_progress' || status === 'stopped') {
    return status;
  }
  if (status === 'cancelled' || status === 'canceled' || status === 'failed') {
    return 'stopped';
  }
  return 'pending';
}

/**
 * Parse a plan-tool call's raw `input` into a normalized `TodoItem[]`,
 * tolerating the several shapes different agent runtimes emit (`todos` vs
 * `plan` array; `content`/`step`/`description`/`label`/`text` for the item
 * body; `activeForm`/`active_form`).
 *
 * @param input - The `tool_use` event's `input`, of unknown shape.
 * @returns Normalized items; entries with no recognizable body text are dropped.
 * @complexity O(n) in the number of raw plan entries.
 */
export function parseTodoWriteInput({ input }: { input: unknown }): TodoItem[] {
  const list = todoListOf({ input });
  return list ? list.items.map((todo) => parseTodoItem({ todo })).filter((todo): todo is TodoItem => todo !== null) : [];
}

/** The plan array a tool input carries (`todos` wins over `plan`), with the key it sits under. */
function todoListOf({ input }: { input: unknown }, _optional: {} = {}): { key: 'todos' | 'plan'; items: unknown[] } | null {
  if (!input || typeof input !== 'object') return null;
  const obj = input as { plan?: unknown; todos?: unknown };
  if (Array.isArray(obj.todos)) return { key: 'todos', items: obj.todos };
  if (Array.isArray(obj.plan)) return { key: 'plan', items: obj.plan };
  return null;
}

/** The first of `keys` whose value is a string (even an empty one), else undefined. */
function firstStringField({ record, keys }: { record: Record<string, unknown>; keys: readonly string[] }, _optional: {} = {}): string | undefined {
  for (const key of keys) {
    const value = record[key];
    if (typeof value === 'string') return value;
  }
  return undefined;
}

const TODO_BODY_KEYS = ['content', 'step', 'description', 'label', 'text'] as const;
const TODO_ACTIVE_FORM_KEYS = ['activeForm', 'active_form'] as const;

function parseTodoItem({ todo }: { todo: unknown }, _optional: {} = {}): TodoItem | null {
  if (!todo || typeof todo !== 'object') return null;
  const record = todo as Record<string, unknown>;
  const content = firstStringField({ record, keys: TODO_BODY_KEYS });
  if (!content) return null;
  return {
    content,
    status: normalizeTodoStatus(record.status),
    activeForm: firstStringField({ record, keys: TODO_ACTIVE_FORM_KEYS }),
  };
}

/**
 * Find the most recent plan-tool `tool_use` in a single turn's events and
 * return its parsed items, or `[]` if this turn never wrote a plan.
 * @complexity O(n), scanning from the end.
 */
export function latestTodosFromEvents({ events }: { events: AgentEvent[] | undefined }): TodoItem[] {
  const event = latestTodoWriteEvent({ events });
  return event ? parseTodoWriteInput({ input: event.input }) : [];
}

type ToolUseEvent = Extract<AgentEvent, { kind: 'tool_use' }>;

/** The newest plan-tool `tool_use` in one turn's events, scanning from the end. */
function latestTodoWriteEvent({ events }: { events: readonly AgentEvent[] | undefined }, _optional: {} = {}): ToolUseEvent | undefined {
  return events?.findLast((event): event is ToolUseEvent => event.kind === 'tool_use' && isTodoWriteToolName({ name: event.name }));
}

/** The newest message holding a plan-tool call, with that call; messages are scanned newest first. */
function latestTodoWriteInMessages<T extends { events?: AgentEvent[] | undefined }>(
  { messages }: { messages: ReadonlyArray<T> | undefined },
  _optional: {} = {},
): { message: T; event: ToolUseEvent } | null {
  for (let mi = (messages?.length ?? 0) - 1; mi >= 0; mi -= 1) {
    const message = messages![mi]!;
    const event = latestTodoWriteEvent({ events: message.events });
    if (event) return { message, event };
  }
  return null;
}

/** The subset of {@link latestTodosFromEvents} not yet marked `completed`. */
export function unfinishedTodosFromEvents({ events }: { events: AgentEvent[] | undefined }): TodoItem[] {
  return latestTodosFromEvents({ events: events }).filter((todo) => todo.status !== 'completed');
}

/**
 * Walk a conversation in reverse to find the most recent plan-tool
 * `tool_use` across every message and return its raw (un-parsed) `input`, so
 * a caller can hand it straight to a plan/todo card without re-implementing
 * the discovery walk.
 *
 * @param messages - Conversation turns, oldest first (only `events` is read).
 * @returns The raw tool input, or `null` if no plan tool has run yet.
 * @complexity O(n*m) worst case (n messages, m events each), but returns on
 *   the first hit scanning backwards, so the common case (a recent plan
 *   update) is far cheaper.
 */
export function latestTodoWriteInputFromMessages({ messages }: { messages: ReadonlyArray<{ events?: AgentEvent[] | undefined }> | undefined }
): unknown | null {
  return latestTodoWriteInMessages({ messages })?.event.input ?? null;
}

/** Convenience alias for {@link latestTodoWriteInputFromMessages} matching the `latestTodoWriteInput()` name in the target API. */
export const latestTodoWriteInput = latestTodoWriteInputFromMessages;

function hasTerminalRunEnded(runStatus: ChatRunStatus | undefined, endedAt: number | undefined): boolean {
  return isTerminalRunStatus({ status: runStatus }) || (runStatus === undefined && endedAt !== undefined);
}

function stoppedTodoWriteInput(input: unknown): unknown {
  const list = todoListOf({ input });
  if (!list) return input;
  return {
    ...(input as Record<string, unknown>),
    [list.key]: list.items.map((todo) => {
      if (!todo || typeof todo !== 'object') return todo;
      const record = todo as Record<string, unknown>;
      if (record.status !== 'in_progress') return todo;
      return { ...record, status: 'stopped' };
    }),
  };
}

/**
 * Variant of {@link latestTodoWriteInputFromMessages} for a "pinned progress
 * card" that must stay honest once its owning run has ended: while the run
 * is still active the raw input is returned as-is, but once the run is
 * terminal any item still marked `in_progress` is flipped to `stopped` (the
 * agent process exited before marking it done or failed).
 *
 * @complexity Same as {@link latestTodoWriteInputFromMessages}, plus an O(m)
 *   remap of the winning turn's items when the run has ended.
 */
export function latestTodoWriteInputForPinnedCard<
  T extends {
    events?: AgentEvent[] | undefined;
    runStatus?: ChatRunStatus | undefined;
    endedAt?: number | undefined;
  },
>({ messages }: { messages: ReadonlyArray<T> | undefined }): unknown | null {
  const found = latestTodoWriteInMessages({ messages });
  if (!found) return null;
  const { message, event } = found;
  return hasTerminalRunEnded(message.runStatus, message.endedAt) ? stoppedTodoWriteInput(event.input) : event.input;
}

/**
 * @module transcript
 *
 * Pure transcript-assembly helpers: turning a `ChatMessage[]` history into
 * the flattened text a host sends to an agent as prior-turn context.
 *
 * Adapted from OD's `providers/daemon.ts` transcript section (see
 * archived provenance ledger). The OD original also owned SSE/fetch transport
 * (`streamViaDaemon`, `DaemonStreamHandlers`) — none of that is ported here;
 * only the pure string-assembly helpers. It also hard-coded OD's BYOK/
 * OpenCode agent-family policy and an `agent-browser`-tool-specific
 * context-warning heuristic; both are OD product policy, not generic
 * transcript assembly, so they are generalized into caller-supplied hooks
 * (or dropped) below — see archived provenance ledger for the full accounting.
 */
import { redactUserMessage, type UserTextRedactionOptions } from './user-text-redaction.js';
import type { ChatMessage } from './messages.js';
import type { PersistedArtifactFileRef } from './util/strip.js';
import { summarizeArtifactsForTranscript } from './util/strip.js';

const DEFAULT_MAX_TRANSCRIPT_MESSAGE_CHARS = 12_000;
const DEFAULT_LARGE_TOOL_RESULT_CHARS = 8_000;
const DEFAULT_HIGH_INPUT_TOKEN_WARNING_THRESHOLD = 200_000;

/** The most recent `user`-authored message's content, or `''` if there isn't one. */
export function latestUserPromptFromHistory({ history }: { history: ChatMessage[] }, options: UserTextRedactionOptions = {}): string {
  for (let i = history.length - 1; i >= 0; i -= 1) {
    const message = history[i];
    if (message?.role === 'user') return redactUserMessage({ message }, options).message.content;
  }
  return '';
}

function truncateForTranscript(content: string, maxChars: number): string {
  if (content.length <= maxChars) return content;
  const omitted = content.length - maxChars;
  return `${content.slice(0, maxChars)}\n\n[truncated ${omitted} chars from this prior message before sending it to the agent. Full content remains in persisted history.]`;
}

function escapeTranscriptRoleDelimiters(content: string): string {
  return content.replace(/^(## (?:user|assistant)[ \t]*)(\r?)$/gm, '\\$1$2');
}

/**
 * Build a short warning block when prior-run telemetry embedded in
 * `history`'s events suggests the next turn should keep its own output
 * compact (a previous run reported a very high input-token count, or
 * carries large persisted tool results that a fresh turn shouldn't replay
 * verbatim).
 * @complexity O(n) across all messages' events.
 */
function buildPriorRunContextWarning(history: ChatMessage[], largeToolResultChars: number, highInputTokenWarningThreshold: number): string | null {
  const { highestInputTokens, largeToolResults } = scanPriorRunTelemetry({ history, largeToolResultChars });
  const notes: string[] = [];
  if (highestInputTokens >= highInputTokenWarningThreshold) {
    notes.push(`a previous run reported ${highestInputTokens} input tokens`);
  }
  if (largeToolResults > 0) {
    notes.push(`${largeToolResults} large prior tool result${largeToolResults === 1 ? '' : 's'} exist only in persisted event history`);
  }
  if (notes.length === 0) return null;

  return ['## context warning', `Detected ${notes.join(', ')}.`, 'Keep this turn compact: summarize prior tool output, read large references from temp files, and quote only task-relevant lines.'].join('\n');
}

/** The highest reported input-token count and the number of oversized tool results across all events. */
function scanPriorRunTelemetry(
  { history, largeToolResultChars }: { history: ChatMessage[]; largeToolResultChars: number },
  _optional: {} = {},
): { highestInputTokens: number; largeToolResults: number } {
  let highestInputTokens = 0;
  let largeToolResults = 0;
  for (const event of history.flatMap((message) => message.events ?? [])) {
    if (event.kind === 'usage' && typeof event.inputTokens === 'number') {
      highestInputTokens = Math.max(highestInputTokens, event.inputTokens);
    }
    if (event.kind === 'tool_result' && event.content.length > largeToolResultChars) {
      largeToolResults += 1;
    }
  }
  return { highestInputTokens, largeToolResults };
}

function scopeHistoryToAgent(history: ChatMessage[], targetAgentId: string | undefined, isSameAgentFamily: (agentId: string, targetAgentId: string) => boolean): ChatMessage[] {
  if (!targetAgentId) return history;
  for (let i = history.length - 1; i >= 0; i -= 1) {
    const message = history[i];
    if (message?.role === 'assistant' && message.agentId && !isSameAgentFamily(message.agentId, targetAgentId)) {
      return history.slice(i + 1);
    }
  }
  return history;
}

type QuestionFormTag = { name: string; start: number; end: number; closing: boolean };

/** Scan tag boundaries once, including malformed openers, without retrying an unterminated tag. */
function questionFormTags({ content }: { content: string }): QuestionFormTag[] {
  const matcher = /<(question-form|ask-question)\b|<\/(question-form|ask-question)>/g;
  const tags: QuestionFormTag[] = [];
  let match: RegExpExecArray | null;
  while ((match = matcher.exec(content))) {
    const closing = match[2] !== undefined;
    const end = closing ? matcher.lastIndex : content.indexOf('>', matcher.lastIndex) + 1;
    if (!end) break;
    tags.push({ name: (match[1] ?? match[2])!, start: match.index, end, closing });
    matcher.lastIndex = end;
  }
  return tags;
}

/** Find matched form ranges in reverse source order without retrying unmatched openers.
 * Keep the first following close of the same name, matching the former non-greedy replacement.
 * Matching by name (formerly a `\1` backreference) means a `<question-form>…</ask-question>`
 * mismatch is never spliced.
 * @complexity O(n) time and space in content length; each tag and source character is scanned once.
 */
function questionFormRanges({ content }: { content: string }): Array<{ start: number; end: number }> {
  const tags = questionFormTags({ content });
  const nextClose = new Map<string, number>();
  const ranges: Array<{ start: number; end: number }> = [];
  for (let i = tags.length - 1; i >= 0; i--) {
    const tag = tags[i]!;
    if (tag.closing) nextClose.set(tag.name, tag.end);
    else {
      const end = nextClose.get(tag.name);
      if (end !== undefined) ranges.push({ start: tag.start, end });
    }
  }
  return ranges;
}

/**
 * Strip transcript-echo hazards from a prior assistant turn before it goes
 * back to the agent as history: an already-answered `<question-form>` /
 * `<ask-question>` block (and a fenced JSON schema echo of the same shape),
 * plus any `<artifact>` body CONFIRMED persisted to `persistedArtifactFiles`
 * (replaced with a one-line pointer to the on-disk file — see
 * {@link summarizeArtifactsForTranscript}).
 *
 * Leaving an answered form literal in the transcript causes a weak/plain
 * model to pattern-match it as a template and re-emit an identical form on
 * the user's next turn, looking like the clarification loop never breaks.
 *
 * User-authored content is never sanitized by this function — a user
 * legitimately quoting `<question-form>` markup must not be mangled; only
 * assistant turns should be passed in.
 *
 * @complexity O(n) in `content.length` (a small fixed number of regex
 *   passes) plus {@link summarizeArtifactsForTranscript}'s cost.
 */
export function sanitizePriorAssistantTurn({ content }: { content: string }, { persistedArtifactFiles = [] }: { persistedArtifactFiles?: (ReadonlyArray<PersistedArtifactFileRef>) | undefined } = {}): string {
  const chunks: string[] = [];
  let copiedTo = 0;
  for (const range of questionFormRanges({ content }).reverse()) {
    if (range.start < copiedTo) continue;
    chunks.push(content.slice(copiedTo, range.start), '[question-form was emitted here on a prior turn; the user already answered, see their reply below.]');
    copiedTo = range.end;
  }
  chunks.push(content.slice(copiedTo));
  let sanitized = chunks.join('');
  // Strip ```json (or plain ```) fenced blocks whose body matches the form
  // schema shape — `"questions": [` is the strongest tell. A generic JSON
  // snippet without that key is left intact.
  sanitized = sanitized.replace(/```(?:json)?\s*\n([\s\S]*?)\n```/g, (match, body: string) => {
    if (/"questions"\s*:\s*\[/.test(body)) {
      return '[form schema was echoed here on a prior turn; stripped to avoid a loop.]';
    }
    return match;
  });
  // Replace prior-turn `<artifact>` HTML with a one-line summary for
  // artifacts CONFIRMED persisted (see summarizeArtifactsForTranscript's own
  // doc for why an unconfirmed save is left verbatim).
  sanitized = summarizeArtifactsForTranscript({ content: sanitized, persistedFiles: persistedArtifactFiles });
  return sanitized;
}

export interface BuildTranscriptOptions extends UserTextRedactionOptions {
  /**
   * Scope the transcript to messages from this agent's family onward,
   * dropping any older history from a different agent. Omit to include the
   * full history (no scoping).
   */
  targetAgentId?: string;
  /**
   * How to decide two agent ids belong to the "same family" for the
   * purposes of `targetAgentId` scoping (e.g. a host may route several
   * model ids through one shared agent identity). Defaults to exact-id
   * equality when omitted.
   */
  isSameAgentFamily?: (agentId: string, targetAgentId: string) => boolean;
  /**
   * Resolve the files a given message's artifacts were confirmed persisted
   * to, so their bodies can be summarized instead of replayed verbatim. A
   * host derives this from its own file-write bookkeeping — chat-core's
   * `ChatMessage` intentionally carries no `producedFiles`-shaped field.
   * Defaults to "nothing persisted" (no summarization).
   */
  resolvePersistedArtifactFiles?: (message: ChatMessage) => ReadonlyArray<PersistedArtifactFileRef>;
  /** Per-message character cap before truncation. @default 12000 */
  maxMessageChars?: number;
  /** `tool_result.content` length above which a result counts as "large" for the context warning. @default 8000 */
  largeToolResultChars?: number;
  /** `usage.inputTokens` above which the context warning fires. @default 200000 */
  highInputTokenWarningThreshold?: number;
}

/**
 * Flatten a conversation history into the `## role\n<content>` transcript
 * text sent to an agent as prior-turn context: scopes to the target agent
 * family (if requested), sanitizes each assistant turn, truncates
 * over-length messages, and prepends a compact-turn warning when prior-run
 * telemetry suggests one is warranted.
 *
 * @complexity O(n) in the total transcript character count — one pass to
 *   scope, one to sanitize/truncate/join each message, one to scan events
 *   for the warning.
 */
export function buildTranscript({ history }: { history: ChatMessage[] }, options: BuildTranscriptOptions = {}): string {
  const maxMessageChars = options.maxMessageChars ?? DEFAULT_MAX_TRANSCRIPT_MESSAGE_CHARS;
  const largeToolResultChars = options.largeToolResultChars ?? DEFAULT_LARGE_TOOL_RESULT_CHARS;
  const highInputTokenWarningThreshold = options.highInputTokenWarningThreshold ?? DEFAULT_HIGH_INPUT_TOKEN_WARNING_THRESHOLD;
  const isSameAgentFamily = options.isSameAgentFamily ?? ((agentId: string, targetAgentId: string) => agentId === targetAgentId);
  const resolvePersistedArtifactFiles = options.resolvePersistedArtifactFiles ?? (() => [] as ReadonlyArray<PersistedArtifactFileRef>);

  const scopedHistory = scopeHistoryToAgent(history, options.targetAgentId, isSameAgentFamily);
  const transcript = scopedHistory
    .map((m) => {
      const trimmed = redactUserMessage({ message: m }, options).message.content.trim();
      const sanitized = m.role === 'assistant' ? sanitizePriorAssistantTurn({ content: trimmed }, { persistedArtifactFiles: resolvePersistedArtifactFiles(m) }) : trimmed;
      return `## ${m.role}\n${escapeTranscriptRoleDelimiters(truncateForTranscript(sanitized, maxMessageChars))}`;
    })
    .join('\n\n');
  const warning = buildPriorRunContextWarning(scopedHistory, largeToolResultChars, highInputTokenWarningThreshold);
  return warning ? `${warning}\n\n${transcript}` : transcript;
}

import type { AgentEvent } from './events.js';
import type { ChatMessage } from './messages.js';
type UsageEvent = Extract<AgentEvent, { kind: 'usage' }>;
/** A turn's reported usage plus the conversation's prefix total. `segments` is present only when the
 * message holds more than one reply (a mid-run message started a new one): one entry per reply, in
 * order, each with its own prefix total, so every reply can show its own "Done" line. */
export type ChatUsageSummary = UsageEvent & { totalCostUsd?: number; segments?: readonly (ChatUsageSummary | undefined)[] };
type SessionCost = { sessionId: string; chargedUsd: number };

/** The ext event a message sent mid-run arrives as (the daemon's `user_message` run event). The agent
 * answers it as a new reply inside the same run, so it ends the reply before it. */
export const MID_RUN_USER_MESSAGE_EVENT_NAME = 'user_message';

/** Whether this event is a mid-run user message, i.e. the boundary between two replies of one run. */
export function isReplyBoundary({ event }: { event: AgentEvent }, _optional = {}): boolean {
  return event.kind === 'ext' && event.name === MID_RUN_USER_MESSAGE_EVENT_NAME;
}

/** Queued/consumed receipts update one input, so usage must split that reply only once. */
function newReplyBoundary({ event, seen }: { event: AgentEvent; seen: Set<string> }, _options = {}): boolean {
  if (!isReplyBoundary({ event })) return false;
  const id = (event as Extract<AgentEvent, { kind: 'ext' }>).data as { id?: unknown } | null;
  if (typeof id?.id !== 'string') return true;
  if (seen.has(id.id)) return false;
  seen.add(id.id);
  return true;
}

/** Split one assistant message's events into replies at each mid-run user message. A usage event
 * that lands after a boundary but before the next reply produced anything is the interrupted
 * reply's own result (the daemon notes it can arrive after the interrupt ack), so it stays with
 * the reply before. Event order is otherwise preserved. O(n) for n events.
 * @example replySegments({ events }).length // 1 + number of mid-run user messages */
export function replySegments({ events }: { events: readonly AgentEvent[] | undefined }, _optional = {}): AgentEvent[][] {
  const segments: AgentEvent[][] = [[]];
  let started = false;
  const seen = new Set<string>();
  for (const event of events ?? []) {
    if (newReplyBoundary({ event, seen })) {
      segments.push([]);
      started = false;
      continue;
    }
    const lateResult = event.kind === 'usage' && !started && segments.length > 1;
    started ||= producesReplyOutput({ event });
    segments[segments.length - (lateResult ? 2 : 1)]!.push(event);
  }
  return segments;
}

/** Usage, status and raw lines are bookkeeping; anything else means the reply has produced output. */
function producesReplyOutput({ event }: { event: AgentEvent }, _optional = {}): boolean {
  return !['usage', 'status', 'raw'].includes(event.kind) && !isReplyBoundary({ event });
}

/** Resolve one charge against this agent/session's last snapshot. State is local to an
 * ordered transcript projection; revisiting a session keeps its baseline. A lower snapshot
 * starts a new counter epoch (some CLIs reset their counter on resume). O(1) map access. */
function usageCost({ event, agentId, sessions }: { event: UsageEvent; agentId: string; sessions: Map<string, SessionCost> }, _optional = {}): number | undefined {
  const sessionId = event.costSessionId;
  if (!sessionId) return validCost(event.costUsd);
  const key = JSON.stringify([agentId, sessionId]);
  const chargedUsd = sessions.get(key)?.chargedUsd ?? 0;
  const cumulative = validCost(event.cumulativeCostUsd);
  const cost = cumulative === undefined ? validCost(event.costUsd)
    : cumulative < chargedUsd ? cumulative : cumulative - chargedUsd;
  // Interim interrupted-segment charges are already paid; later snapshots subtract them.
  // After a counter reset the new snapshot, rather than the old epoch's total, is the baseline.
  sessions.set(key, { sessionId, chargedUsd: cumulative ?? chargedUsd + (cost ?? 0) });
  return cost;
}

/** Missing or malformed costs stay unknown; never infer charges from tokens. */
function validCost(value: number | undefined): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : undefined;
}

/** Sum reported segment usage for a turn, including aborted segments and recovered attempts.
 * Optional projection state is updated to reconcile session snapshots across turns.
 * Missing fields stay absent; money is never inferred. O(n) time for n events.
 * @example turnUsage({ events: message.events }) */
export function turnUsage({ events }: { events: readonly AgentEvent[] | undefined }, { sessions = new Map<string, SessionCost>(), agentId = '' }: { sessions?: Map<string, SessionCost>; agentId?: string } = {}): UsageEvent | undefined {
  let total: UsageEvent | undefined;
  for (const event of events ?? []) {
    if (event.kind !== 'usage') continue;
    total ??= { kind: 'usage' };
    addReportedCounts({ total, event });
    if (event.stopReason !== undefined) total.stopReason = event.stopReason;
    const cost = usageCost({ event, agentId, sessions });
    addReportedCost({ total, cost });
  }
  return total;
}

function addReportedCost({ total, cost }: { total: UsageEvent; cost: number | undefined }, _options = {}): void {
  if (cost !== undefined) total.costUsd = (total.costUsd ?? 0) + cost;
}

/** Add an event's well-formed token and duration counts into `total`, in place. */
function addReportedCounts({ total, event }: { total: UsageEvent; event: UsageEvent }, _optional = {}): void {
  for (const field of ['inputTokens', 'outputTokens', 'durationMs'] as const) {
    const value = event[field];
    if (typeof value === 'number' && Number.isFinite(value) && value >= 0) total[field] = (total[field] ?? 0) + value;
  }
}

/** Add one reply's usage into a message total; fields absent from both stay absent. O(1). */
function addUsage({ total, usage }: { total: UsageEvent | undefined; usage: UsageEvent | undefined }, _optional = {}): UsageEvent | undefined {
  if (!usage) return total;
  const next: UsageEvent = { ...(total ?? { kind: 'usage' }) };
  if (usage.stopReason !== undefined) next.stopReason = usage.stopReason;
  for (const field of ['inputTokens', 'outputTokens', 'durationMs', 'costUsd'] as const) {
    const value = usage[field];
    if (value !== undefined) next[field] = (next[field] ?? 0) + value;
  }
  return next;
}

/** Derive per-turn charges and prefix totals from persisted events_json, for live and reloaded
 * chats alike. Single replies without reported duration use the message's elapsed run time.
 * A message with mid-run replies also gets per-reply `segments`. O(e + m) for e events
 * and m messages; no per-row transcript scans or I/O.
 * @example conversationUsage({ messages: savedMessages }).get('assistant-2') */
export function conversationUsage({ messages }: { messages: readonly ChatMessage[] }, _optional = {}): Map<string, ChatUsageSummary> {
  const sessions = new Map<string, SessionCost>();
  const summaries = new Map<string, ChatUsageSummary>();
  let totalCostUsd: number | undefined;
  for (const message of messages) {
    if (message.role !== 'assistant') continue;
    const result = messageUsage({ message, sessions, totalCostUsd });
    totalCostUsd = result.totalCostUsd;
    if (result.usage) summaries.set(message.id, messageSummary({ ...result, usage: result.usage, message }));
  }
  return summaries;
}

/** A message's summary: its usage, the prefix total, and per-reply segments when it holds several replies. */
function messageSummary(
  { usage, segments, totalCostUsd, message }: {
    usage: UsageEvent;
    segments: (ChatUsageSummary | undefined)[];
    totalCostUsd: number | undefined;
    message: ChatMessage;
  },
  _optional = {},
): ChatUsageSummary {
  // Tokens-only runtimes still have run timestamps; those cannot time individual mid-run replies.
  if (segments.length === 1) fillRunDuration({ usage, message });
  return {
    ...usage,
    ...(totalCostUsd === undefined ? {} : { totalCostUsd }),
    ...(segments.length > 1 ? { segments } : {}),
  };
}

/** One assistant message's summed usage and per-reply summaries, advancing the conversation's prefix total. */
function messageUsage(
  { message, sessions, totalCostUsd }: { message: ChatMessage; sessions: Map<string, SessionCost>; totalCostUsd: number | undefined },
  _optional = {},
): { usage: UsageEvent | undefined; segments: (ChatUsageSummary | undefined)[]; totalCostUsd: number | undefined } {
  // Replies run in event order through one session map, so their sum equals the whole-message charge.
  const segments: (ChatUsageSummary | undefined)[] = [];
  let usage: UsageEvent | undefined;
  let prefixTotal = totalCostUsd;
  for (const events of replySegments({ events: message.events })) {
    const segment = turnUsage({ events }, { sessions, agentId: message.agentId ?? '' });
    usage = addUsage({ total: usage, usage: segment });
    if (segment?.costUsd !== undefined) prefixTotal = (prefixTotal ?? 0) + segment.costUsd;
    segments.push(segment && { ...segment, ...(prefixTotal === undefined ? {} : { totalCostUsd: prefixTotal }) });
  }
  return { usage, segments, totalCostUsd: prefixTotal };
}

/** Use the message's elapsed run time when no reply reported a duration; invalid timestamps stay unknown. */
function fillRunDuration({ usage, message }: { usage: UsageEvent; message: ChatMessage }, _optional = {}): void {
  if (usage.durationMs !== undefined || message.startedAt === undefined || message.endedAt === undefined) return;
  const durationMs = message.endedAt - message.startedAt;
  if (Number.isFinite(durationMs) && durationMs >= 0) usage.durationMs = durationMs;
}

/** One credential policy for chat text; secure card values must bypass this text-only boundary. */
import { redactSecretShapes, type RedactionRule } from '@jini-ai/diagnostics/redaction/secrets-only';
import type { ChatMessage, SecretRedactionSignal } from './messages.js';
export type { SecretRedactionSignal } from './messages.js';

export interface UserTextRedaction {
  readonly text: string;
  readonly secretRedacted: boolean;
  readonly count: number;
}
export type RedactUserText = (required: { readonly text: string }, optional?: { readonly secretField?: boolean }) => UserTextRedaction;
export interface UserTextRedactionOptions {
  /** Default on; hosts may supply a stricter credential policy without changing chat storage. */
  readonly redactUserText?: RedactUserText;
  /** Contains no user text or credential fragments. A host can offer its secure credential card. */
  readonly onSecretRedacted?: (signal: SecretRedactionSignal) => void;
}
export const SECRET_REDACTED_NOTICE = 'I removed what looked like a key from your message. If it was real, rotate it. Use the secure form to save it.';
export const CREDENTIAL_CARD_GUIDANCE = 'Use the secure form to save keys, tokens, passwords, and secrets. Chat answers are sent to the assistant.';
const REMOVED = '[token removed]';
const INTERNAL_REMOVED = '[REDACTED:chat_secret]';
const REDACTION_MARKER = /\[REDACTED:[^\]\r\n]+\]/g;
const CHAT_RULES: readonly RedactionRule[] = [
  { kind: 'chat_key', pattern: /(?<![A-Za-z0-9_-])sk-[A-Za-z0-9_-]{16,}/g, replacement: () => INTERNAL_REMOVED },
  // Kept on top of the shared Slack rule: that rule refuses a token preceded by `-` (e.g. a URL path
  // segment `/-xoxb-…`) and the entropy fallback below exempts URLs, so without this rule such a token
  // would reach storage and model history. Only drop it once the shared rule covers that case.
  { kind: 'chat_key', pattern: /(?<![A-Za-z0-9_])xox[baprs]-[A-Za-z0-9-]{16,}/g, replacement: () => INTERNAL_REMOVED },
  // Explicit authorization syntax catches even short values. Exempt scheme descriptions in prose.
  { kind: 'chat_bearer', pattern: /\bBearer[ \t]+(?!\[REDACTED)(?!(?:token|tokens|authentication|authorization|auth|scheme|credentials?)\b)[A-Za-z0-9._~+\/=-]+/gi, replacement: () => 'Bearer ' + INTERNAL_REMOVED },
];

function entropy(text: string): number {
  const counts = new Map<string, number>();
  for (const char of text) counts.set(char, (counts.get(char) ?? 0) + 1);
  let bits = 0;
  for (const count of counts.values()) {
    const probability = count / text.length;
    bits -= probability * Math.log2(probability);
  }
  return bits;
}

/** Stricter than error redaction: also detects unlabelled long tokens, while retaining ordinary URLs,
 * hexadecimal hashes, identifiers and prose. Strong credential syntax inside a URL is still caught. */
export function redactUserText({ text }: { readonly text: string }, { secretField = false }: { readonly secretField?: boolean } = {}): UserTextRedaction {
  // Existing removal markers must survive a second pass through assignment rules (api_key=…).
  const literalMarkers = new Map<string, string>();
  let literalPrefix = 'chat_literal_';
  while (text.includes(literalPrefix)) literalPrefix += '_';
  const protectedText = text.replace(REDACTION_MARKER, marker => {
    const key = '[REDACTED:' + literalPrefix + literalMarkers.size + ']';
    literalMarkers.set(key, marker);
    return key;
  }).replaceAll(REMOVED, INTERNAL_REMOVED);
  const base = redactSecretShapes({ text: protectedText, policy: { additionalRules: CHAT_RULES } });
  let count = base.redactions;
  const urls = [...base.text.matchAll(/\b[a-z][a-z0-9+.-]*:\/\/[^\s<>"']+/gi)]
    .map(match => ({ start: match.index!, end: match.index! + match[0].length }));
  let cleaned = base.text.replace(/(?<![A-Za-z0-9_+\/=-])[A-Za-z0-9_+\/=-]{40,}(?![A-Za-z0-9_+\/=-])/g, (candidate: string, offset: number) => {
    if (urls.some(url => offset >= url.start && offset < url.end)) return candidate;
    if (/^[a-f0-9]+$/i.test(candidate) || !/[A-Za-z]/.test(candidate)) return candidate;
    const bits = entropy(candidate);
    const mixedAlphabet = /[A-Z]/.test(candidate) && /[a-z]/.test(candidate);
    if (bits < 4 || (!/[0-9]/.test(candidate) && (!mixedAlphabet || bits < 4.5))) return candidate;
    count += 1;
    return INTERNAL_REMOVED;
  });
  // A labelled credential answer can be a short password with no recognisable shape at all.
  if (secretField && cleaned.trim() !== '' && cleaned !== INTERNAL_REMOVED) {
    cleaned = INTERNAL_REMOVED;
    count = Math.max(1, count);
  }
  return { text: cleaned.replace(REDACTION_MARKER, marker => literalMarkers.get(marker) ?? REMOVED), secretRedacted: count > 0, count };
}

/** Prepare before storage OR model dispatch. Return only sanitized content and non-secret metadata. */
export function redactUserMessage<T extends { readonly role: string; readonly content: string }>(
  { message }: { readonly message: T }, options: UserTextRedactionOptions = {},
): { readonly message: T; readonly secretRedacted: boolean; readonly count: number } {
  if (message.role !== 'user') return { message, secretRedacted: false, count: 0 };
  const result = (options.redactUserText ?? redactUserText)({ text: message.content });
  const signal = result.secretRedacted ? { secretRedacted: true as const, count: result.count } : undefined;
  if (signal) options.onSecretRedacted?.(signal);
  return {
    message: { ...message, content: result.text, ...(signal ? { secretRedaction: signal } : {}) },
    secretRedacted: result.secretRedacted, count: result.count,
  };
}

/** Also protects replay of historical text accepted before the guard was installed. */
export function redactUserHistory({ history }: { readonly history: readonly ChatMessage[] }, options: UserTextRedactionOptions = {}): ChatMessage[] {
  return history.map(message => redactUserMessage({ message }, options).message);
}

/** Redact model input and append the host's non-secret card guidance once, using the redaction
 * signal rather than display text. `secretRedacted` carries an earlier ingress/composer signal;
 * persistence must continue to use redactUserText/redactUserMessage without the model note. */
export function guardUserText(
  { text }: { readonly text: string },
  options: { readonly modelNote?: string; readonly secretRedacted?: boolean; readonly redactUserText?: RedactUserText } = {},
): string {
  const safe = (options.redactUserText ?? redactUserText)({ text }, {});
  if (!safe.secretRedacted && options.secretRedacted !== true) return safe.text;
  if (!options.modelNote || safe.text.includes(options.modelNote)) return safe.text;
  return `${safe.text}\n\n${options.modelNote}`;
}

/**
 * @module manifest
 *
 * Create, serialize, parse, and infer the sidecar `ArtifactManifest` a
 * generated file carries. See `./types.js` for the manifest shape itself.
 */
import type { ArtifactExportKind, ArtifactKind, ArtifactManifest, ArtifactRendererId, ArtifactStatus } from './types.js';

const MANIFEST_VERSION = 1;
const ALLOWED_KINDS: ReadonlySet<ArtifactKind> = new Set([
  'html',
  'deck',
  'react-component',
  'markdown-document',
  'svg',
  'diagram',
  'code-snippet',
  'mini-app',
  'design-system',
]);
const ALLOWED_RENDERERS: ReadonlySet<ArtifactRendererId> = new Set([
  'html',
  'deck-html',
  'react-component',
  'markdown',
  'svg',
  'diagram',
  'code',
  'mini-app',
  'design-system',
]);
const ALLOWED_EXPORTS: ReadonlySet<ArtifactExportKind> = new Set(['html', 'pdf', 'zip', 'jsx', 'md', 'svg', 'txt']);
const ALLOWED_STATUS: ReadonlySet<ArtifactStatus> = new Set(['streaming', 'complete', 'error']);

function normalizeExt(name: string): string {
  const i = name.lastIndexOf('.');
  return i >= 0 ? name.slice(i).toLowerCase() : '';
}

// The exact finite subset of `ArtifactKind` this function can actually
// return — narrower than `ArtifactKind` itself (which also has `deck`,
// `diagram`, `mini-app`, `design-system`, none reachable from a bare file
// extension) so callers get a statically provable exhaustiveness check
// instead of having to defend against kinds this function never produces.
type LegacyInferredKind = 'html' | 'svg' | 'markdown-document' | 'react-component' | 'code-snippet';

const LEGACY_KIND_BY_EXT: ReadonlyMap<string, LegacyInferredKind> = new Map([
  ['.html', 'html'],
  ['.htm', 'html'],
  ['.svg', 'svg'],
  ['.md', 'markdown-document'],
  ['.jsx', 'react-component'],
  ['.tsx', 'react-component'],
  ['.js', 'code-snippet'],
  ['.ts', 'code-snippet'],
  ['.json', 'code-snippet'],
  ['.css', 'code-snippet'],
]);

/** Renderer and export set for every kind `inferLegacyManifest` can resolve to (the inferred kinds plus the deck-name heuristic's `deck`). */
const LEGACY_KIND_INFO: Readonly<Record<LegacyInferredKind | 'deck', { renderer: ArtifactRendererId; exports: readonly ArtifactExportKind[] }>> = {
  html: { renderer: 'html', exports: ['html', 'pdf', 'zip'] },
  deck: { renderer: 'deck-html', exports: ['html', 'pdf', 'zip'] },
  'markdown-document': { renderer: 'markdown', exports: ['md', 'html', 'pdf', 'zip'] },
  'react-component': { renderer: 'react-component', exports: ['jsx', 'html', 'zip'] },
  'code-snippet': { renderer: 'code', exports: ['txt', 'zip'] },
  svg: { renderer: 'svg', exports: ['svg', 'zip'] }, // 'svg' is a valid ArtifactRendererId as-is
};

/** The manifest sidecar file name convention for a given artifact entry file name. */
export function artifactManifestNameFor({ entry }: { entry: string }): string {
  return `${entry}.artifact.json`;
}

/** Build a fresh, complete manifest for a newly-persisted HTML artifact. */
export function createHtmlArtifactManifest(input: {
  entry: string;
  title: string;
  metadata?: Record<string, unknown>;
  sourceSkillId?: string;
  designSystemId?: string | null;
}): ArtifactManifest {
  const now = new Date().toISOString();
  return {
    version: MANIFEST_VERSION,
    kind: 'html',
    title: input.title,
    entry: input.entry,
    renderer: 'html',
    status: 'complete',
    exports: ['html', 'pdf', 'zip'],
    primary: true,
    createdAt: now,
    updatedAt: now,
    sourceSkillId: input.sourceSkillId,
    designSystemId: input.designSystemId,
    metadata: input.metadata,
  };
}

export function serializeArtifactManifest({ manifest }: { manifest: ArtifactManifest }): string {
  return JSON.stringify(manifest, null, 2);
}

/**
 * Parse and validate a manifest JSON string, rejecting anything that isn't a
 * well-formed, currently-supported manifest (wrong version, missing
 * required fields, or a `kind`/`renderer`/`status`/`exports` value outside
 * the known sets).
 *
 * @returns The validated manifest, or `null` on any parse/shape failure.
 * @complexity O(k) in the manifest's own field/array count — no I/O.
 */
export function parseArtifactManifest({ raw }: { raw: string }): ArtifactManifest | null {
  let parsed: Partial<ArtifactManifest> | null;
  try {
    parsed = JSON.parse(raw) as Partial<ArtifactManifest> | null;
  } catch {
    return null;
  }
  if (!hasRequiredManifestFields(parsed) || !hasKnownManifestValues(parsed)) return null;
  return {
    version: MANIFEST_VERSION,
    kind: parsed.kind,
    title: parsed.title,
    entry: parsed.entry,
    renderer: parsed.renderer,
    status: parsed.status ?? 'complete',
    exports: parsed.exports,
    ...optionalManifestFields(parsed),
  };
}

/** The optional manifest fields, each kept only when it has its documented type (anything else is dropped, not rejected). */
function optionalManifestFields(parsed: Partial<ArtifactManifest>): Partial<ArtifactManifest> {
  return {
    primary: parsed.primary === true || typeof parsed.primary === 'string' ? parsed.primary : undefined,
    supportingFiles: Array.isArray(parsed.supportingFiles) ? parsed.supportingFiles.filter(isString) : undefined,
    createdAt: stringOrUndefined(parsed.createdAt),
    updatedAt: stringOrUndefined(parsed.updatedAt),
    sourceSkillId: stringOrUndefined(parsed.sourceSkillId),
    designSystemId: parsed.designSystemId === null ? null : stringOrUndefined(parsed.designSystemId),
    metadata: parsed.metadata && typeof parsed.metadata === 'object' && !Array.isArray(parsed.metadata) ? parsed.metadata : undefined,
  };
}

type RequiredManifestFields = Partial<ArtifactManifest> & { entry: string; title: string; kind: string; renderer: string; exports: unknown[] };

function hasRequiredManifestFields(parsed: Partial<ArtifactManifest> | null): parsed is RequiredManifestFields {
  if (parsed?.version !== MANIFEST_VERSION) return false;
  if (!isNonEmptyString(parsed.entry) || !isNonEmptyString(parsed.title)) return false;
  return Array.isArray(parsed.exports) && isString(parsed.kind) && isString(parsed.renderer);
}

function hasKnownManifestValues(
  parsed: RequiredManifestFields,
): parsed is RequiredManifestFields & { kind: ArtifactKind; renderer: ArtifactRendererId; status?: ArtifactStatus; exports: ArtifactExportKind[] } {
  if (!ALLOWED_KINDS.has(parsed.kind as ArtifactKind)) return false;
  if (!ALLOWED_RENDERERS.has(parsed.renderer as ArtifactRendererId)) return false;
  if (parsed.status !== undefined && !ALLOWED_STATUS.has(parsed.status)) return false;
  return parsed.exports.length > 0 && parsed.exports.every((value) => ALLOWED_EXPORTS.has(value as ArtifactExportKind));
}

function isString(value: unknown): value is string {
  return typeof value === 'string';
}

function isNonEmptyString(value: unknown): value is string {
  return isString(value) && value !== '';
}

function stringOrUndefined(value: unknown): string | undefined {
  return isString(value) ? value : undefined;
}

/**
 * Infer a manifest for a legacy artifact file that predates manifest
 * sidecars, from its entry file name alone (extension → kind → renderer).
 * @returns `null` when the extension isn't a recognized artifact kind.
 */
export function inferLegacyManifest(input: { entry: string; title?: string; metadata?: Record<string, unknown> }): ArtifactManifest | null {
  const kind = LEGACY_KIND_BY_EXT.get(normalizeExt(input.entry));
  if (!kind) return null;
  const isDeck = kind === 'html' && /deck|slides|pitch/.test(input.entry.toLowerCase());
  const resolvedKind = isDeck ? 'deck' : kind;
  const info = LEGACY_KIND_INFO[resolvedKind];
  return {
    version: MANIFEST_VERSION,
    kind: resolvedKind,
    title: input.title || input.entry,
    entry: input.entry,
    renderer: info.renderer,
    status: 'complete',
    exports: [...info.exports],
    primary: resolvedKind === 'html' || resolvedKind === 'deck' ? true : undefined,
    metadata: input.metadata,
  };
}

/**
 * @module markdown-context
 * @internal
 *
 * Shared Markdown-context helpers used by both the streaming artifact parser
 * ({@link ./parser.js}) and the post-stream `<artifact>` stripper
 * ({@link ./strip.js}). The single source of truth for what counts as a
 * fenced code block or an inline code span, so the parser/stripper's view of
 * a buffer matches what a Markdown-rendering chat surface will actually
 * render — anything that "looks like" an artifact tag inside one of these
 * regions is literal Markdown and must not be treated as a real protocol tag.
 *
 * Not part of the package's public surface (no `index.ts` re-export): it is
 * an implementation detail shared by two sibling modules, not a name a
 * consumer should depend on directly.
 */

// Line-anchored fence delimiters. Deliberately asymmetric: an opening fence
// may carry an info string (e.g. ```html), a closing fence must be a bare
// triple-backtick line. Neither permits leading indentation — an indented
// "   ```" line renders as a paragraph, not a fence.
export const FENCE_OPEN_RE = /^```(\w[\w+-]*)?\s*$/;
export const FENCE_CLOSE_RE = /^```\s*$/;

// Inline code span (single-backtick pair).
export const INLINE_CODE_RE = /`[^`]+`/g;

// Paragraph-break recognizers — mirror a typical Markdown paragraph-block
// walker's block-starter set (heading / list item / blank line). A block
// boundary caps how far inline-code backtick pairing can reach: backticks
// never pair across it in the rendered output.
const HEADING_RE = /^#{1,4}\s+/;
const UL_ITEM_RE = /^\s*[-*+]\s+/;
const OL_ITEM_RE = /^\s*\d+\.\s+/;

/**
 * `<artifact` followed by whitespace is a real protocol open tag; any other
 * continuation (e.g. `<artifactual`) is a prefix-shared literal that must
 * not be treated as a tag.
 */
export function isRealArtifactOpenAt({ content, idx }: { content: string; idx: number }): boolean {
  const next = content.charAt(idx + '<artifact'.length);
  return next !== '' && /\s/.test(next);
}

export type Range = readonly [number, number];

/**
 * Compute the half-open `[start, end)` ranges of `buffer` that a Markdown
 * renderer would treat as fenced code blocks or inline code spans. The
 * `unclosedFenceStart` is the index of an opening fence with no matching
 * close in the buffer (or `null` if every fence is closed) — the streaming
 * parser uses it to hold back rendering; the stripper ignores it.
 *
 * Lines without a terminating `\n` (a trailing partial line during
 * streaming) are not classified as fence delimiters here; callers that care
 * about partial-tail behavior inspect the tail themselves.
 *
 * @complexity O(n) in `buffer.length` — one line-by-line scan plus one
 *   backtick scan per accumulated paragraph block.
 */
export function computeSkipRanges({ buffer }: { buffer: string }): {
  ranges: Range[];
  unclosedFenceStart: number | null;
} {
  const scan: LineScan = { ranges: [], blockRegions: [], fenceStart: -1, blockStart: -1 };
  for (const line of linesOf(buffer)) {
    if (scan.fenceStart === -1) visitLineOutsideFence(scan, line);
    else visitLineInsideFence(scan, line);
  }
  const unclosedFenceStart = scan.fenceStart === -1 ? null : scan.fenceStart;
  if (unclosedFenceStart === null) closeBlockBefore(scan, buffer.length); // flush an open paragraph region at end-of-buffer

  for (const [s, e] of scan.blockRegions) {
    for (const m of buffer.slice(s, e).matchAll(INLINE_CODE_RE)) {
      scan.ranges.push([s + m.index, s + m.index + m[0].length]);
    }
  }
  return { ranges: scan.ranges, unclosedFenceStart };
}

interface LineScan {
  ranges: Range[];
  // Paragraph-block regions are contiguous spans of paragraph lines outside
  // any fenced code block; inline-code scanning is restricted to one block at
  // a time so backticks never pair across a block boundary.
  blockRegions: Range[];
  /** Start of the currently open fence, or -1 when outside a fence. */
  fenceStart: number;
  /** Start of the currently open paragraph block, or -1 when none is open. */
  blockStart: number;
}

interface Line {
  start: number;
  end: number;
  text: string;
  hasNewline: boolean;
}

function* linesOf(buffer: string): Generator<Line> {
  let pos = 0;
  while (pos < buffer.length) {
    const eol = buffer.indexOf('\n', pos);
    if (eol === -1) {
      // trailing partial line — classified like any other, but never as a fence delimiter
      yield { start: pos, end: buffer.length, text: buffer.slice(pos), hasNewline: false };
      return;
    }
    yield { start: pos, end: eol, text: buffer.slice(pos, eol), hasNewline: true };
    pos = eol + 1;
  }
}

function closeBlockBefore(scan: LineScan, idx: number): void {
  if (scan.blockStart !== -1 && idx > scan.blockStart) scan.blockRegions.push([scan.blockStart, idx]);
  scan.blockStart = -1;
}

function visitLineInsideFence(scan: LineScan, line: Line): void {
  if (!line.hasNewline || !FENCE_CLOSE_RE.test(line.text)) return;
  scan.ranges.push([scan.fenceStart, line.end + 1]);
  scan.fenceStart = -1;
}

function visitLineOutsideFence(scan: LineScan, line: Line): void {
  if (line.hasNewline && FENCE_OPEN_RE.test(line.text)) {
    closeBlockBefore(scan, line.start);
    scan.fenceStart = line.start;
  } else if (line.text.trim() === '') {
    closeBlockBefore(scan, line.start);
  } else if (HEADING_RE.test(line.text) || UL_ITEM_RE.test(line.text) || OL_ITEM_RE.test(line.text)) {
    // Each heading/list-item line is its own inline-scan region rather
    // than joining adjacent paragraphs.
    closeBlockBefore(scan, line.start);
    scan.blockRegions.push([line.start, line.end]);
  } else if (scan.blockStart === -1) {
    scan.blockStart = line.start;
  }
}

/** `true` when position `p` falls inside one of `ranges` (half-open intervals). */
export function rangeContains({ ranges, p }: { ranges: ReadonlyArray<Range>; p: number }): boolean {
  for (const [s, e] of ranges) {
    if (p >= s && p < e) return true;
  }
  return false;
}

/**
 * @module markup-attributes
 *
 * Shared quoted-attribute parser for this package's inline protocol tags —
 * `<artifact …>` (`./parser.ts`, `./strip.ts`) and `<question-form …>` /
 * `<ask-question …>` (`../question-form/scan.ts`). All three interpret
 * model-produced markup with the exact same tolerant grammar; centralizing
 * it means a future correction to escaping, accepted attribute names, or
 * malformed-quote handling can't drift between streaming, post-stream, and
 * question-form parsing.
 *
 * Internal only — deliberately not part of this package's public surface;
 * see `./index.ts`'s barrel comment.
 */

/**
 * Parse `name="value"` / `name='value'` pairs out of a tag's raw attribute
 * string (the content between the tag name and the closing `>`).
 */
export function parseQuotedAttrs({ raw }: { raw: string }): Record<string, string> {
  const re = /(\w+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
  const out: Record<string, string> = {};
  let m: RegExpExecArray | null = re.exec(raw);
  while (m !== null) {
    // The pattern's quote alternation means exactly one of group 2 (double-
    // quoted) / group 3 (single-quoted) participates in any successful match
    // — never both, never neither — so `m[2] ?? m[3]` is always defined; the
    // cast just satisfies `noUncheckedIndexedAccess`.
    out[m[1] as string] = (m[2] ?? m[3]) as string;
    m = re.exec(raw);
  }
  return out;
}

/**
 * @module parser
 *
 * Streaming parser for `<artifact identifier="..." type="..." title="...">
 * ...</artifact>` tags. Handles one artifact at a time (no nesting). Feed
 * deltas in, iterate events — every event type has a stable meaning so
 * consumers don't need to rewrite their reducer if this parser is later
 * swapped for a fuller one.
 */
import { computeSkipRanges, FENCE_OPEN_RE, isRealArtifactOpenAt, rangeContains, type Range } from './markdown-context.js';
import { parseQuotedAttrs } from './markup-attributes.js';

export type ArtifactEvent =
  | { type: 'text'; delta: string }
  | { type: 'artifact:start'; identifier: string; artifactType: string; title: string }
  | { type: 'artifact:chunk'; identifier: string; delta: string }
  | { type: 'artifact:end'; identifier: string; fullContent: string };

const OPEN_PREFIX = '<artifact';
const CLOSE_TAG = '</artifact>';

interface ParserState {
  inside: boolean;
  buffer: string;
  identifier: string;
  artifactType: string;
  title: string;
  content: string;
}

type OpenTagMatch = { kind: 'complete'; start: number; end: number; attrs: string } | { kind: 'partial'; start: number } | { kind: 'none' };

const NO_OPEN: OpenTagMatch = { kind: 'none' };
const SKIP = { kind: 'skip' } as const;

interface SkipContext {
  buffer: string;
  ranges: ReadonlyArray<Range>;
}

// Scan the buffer for `<artifact …>` while skipping any positions that a
// Markdown renderer would render as a fenced code block or inline code span
// — see markdown-context.ts for the shared classification used by both this
// streaming parser and the post-stream `<artifact>` stripper.
//
// Streaming caveats handled here on top of the shared ranges:
//   * Open fence with no close yet → hold back from its opening line.
//   * Unterminated tail line that could still resolve into a fence delimiter
//     (e.g. "```", "```ht") → hold back from the line start.
//   * Unmatched opening backtick after the last \n → hold back from it; a
//     future chunk may turn it into an inline code span.
function findOpenTag(buffer: string): OpenTagMatch {
  const { ranges, unclosedFenceStart } = computeSkipRanges({ buffer: buffer });
  const ctx: SkipContext = { buffer, ranges };

  // Pass 1: scan for the earliest *complete* real `<artifact …>` open outside
  // any skip range, before any hold-back decision — otherwise a stray
  // backtick or fence-opener prefix on a tail line would suppress an
  // already self-contained artifact earlier in the buffer.
  const open = scanForOpen(ctx, { unclosedFenceStart });
  if (open.kind === 'complete') return open;

  // Pass 2: no complete open found. Decide whether to hold back, and if so,
  // from which position. Earliest hold-back wins so the text-flush boundary
  // never crosses something that might still resolve into a tag/fence/span.
  const holdbacks = [
    open.kind === 'partial' ? open.start : -1,
    unclosedFenceStart ?? -1,
    tailFenceHoldback(ctx),
    unmatchedBacktickHoldback(ctx),
    tailPrefixHoldback(ctx),
  ].filter((pos) => pos !== -1);
  if (holdbacks.length === 0) return NO_OPEN;
  return { kind: 'partial', start: Math.min(...holdbacks) };
}

function scanForOpen(ctx: SkipContext, { unclosedFenceStart }: { unclosedFenceStart: number | null }): OpenTagMatch {
  let idx = ctx.buffer.indexOf(OPEN_PREFIX);
  while (idx !== -1) {
    const found = classifyOpenAt(ctx, { idx, unclosedFenceStart });
    if (found.kind !== 'skip') return found;
    idx = ctx.buffer.indexOf(OPEN_PREFIX, idx + OPEN_PREFIX.length);
  }
  return NO_OPEN;
}

function classifyOpenAt(
  { buffer, ranges }: SkipContext,
  { idx, unclosedFenceStart }: { idx: number; unclosedFenceStart: number | null },
): OpenTagMatch | typeof SKIP {
  if (rangeContains({ ranges: ranges, p: idx })) return SKIP;
  // Anything past an unclosed fence opener is inside a code block that
  // will close in a later chunk; treat as skip range, not a real tag.
  if (unclosedFenceStart !== null && idx >= unclosedFenceStart) return NO_OPEN;
  const after = idx + OPEN_PREFIX.length;
  // `<artifact` at very end of buffer — could become real with the next
  // chunk. Remember the earliest one and keep looking for a complete tag.
  if (after === buffer.length) return { kind: 'partial', start: idx };
  if (!isRealArtifactOpenAt({ content: buffer, idx: idx })) return SKIP; // e.g. "<artifactual" — not a real open, keep scanning
  const close = findTagEnd({ buffer, from: after });
  // Ran out of buffer before the closing `>` arrived — an open tag mid-stream.
  if (close === -1) return { kind: 'partial', start: idx };
  return { kind: 'complete', start: idx, end: close + 1, attrs: buffer.slice(after, close) };
}

/** Index of the open tag's closing `>`, ignoring any `>` inside a quoted attribute value; -1 if not yet arrived. */
function findTagEnd({ buffer, from }: { buffer: string; from: number }): number {
  let quote: string | null = null;
  for (let j = from; j < buffer.length; j++) {
    const c = buffer.charAt(j);
    if (quote !== null) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === '>') {
      return j;
    }
  }
  return -1;
}

/** Start of an unterminated tail line that could still resolve into a fence delimiter; -1 otherwise. */
function tailFenceHoldback({ buffer }: SkipContext): number {
  const tailLineStart = buffer.lastIndexOf('\n') + 1;
  const tail = buffer.slice(tailLineStart);
  return FENCE_OPEN_RE.test(tail) || /^`{1,2}$/.test(tail) ? tailLineStart : -1;
}

/** Position of an unmatched opening backtick after the last `\n` (outside skip ranges); -1 otherwise. */
function unmatchedBacktickHoldback({ buffer, ranges }: SkipContext): number {
  let firstUnmatched = -1;
  for (let k = buffer.lastIndexOf('\n') + 1; k < buffer.length; k++) {
    if (buffer.charAt(k) !== '`' || rangeContains({ ranges: ranges, p: k })) continue;
    firstUnmatched = firstUnmatched === -1 ? k : -1;
  }
  return firstUnmatched;
}

// Strict prefix at the tail (e.g. "<art") — hold back.
function tailPrefixHoldback({ buffer, ranges }: SkipContext): number {
  const tailLt = buffer.lastIndexOf('<');
  if (tailLt === -1 || rangeContains({ ranges: ranges, p: tailLt })) return -1;
  const slice = buffer.slice(tailLt);
  return OPEN_PREFIX.startsWith(slice) && slice.length < OPEN_PREFIX.length ? tailLt : -1;
}

/**
 * Create a fresh streaming artifact parser. Call `feed({ delta })` for each
 * chunk as it arrives (iterate its generator to drain queued events), and
 * `flush()` once at end-of-stream to emit whatever is still buffered.
 *
 * @complexity Each `feed` call is O(buffer.length) — `findOpenTag` rescans
 *   the buffered tail (bounded by how far behind the caller is at draining
 *   the generator), which is the standard tradeoff for streaming tag
 *   detection over an ever-growing buffer.
 */
export function createArtifactParser(_requiredArgs: Record<string, never>): {
  feed: (args: { delta: string }) => Generator<ArtifactEvent>;
  flush: (args: Record<string, never>) => Generator<ArtifactEvent>;
} {
  const state: ParserState = {
    inside: false,
    buffer: '',
    identifier: '',
    artifactType: '',
    title: '',
    content: '',
  };

  function* feed({ delta }: { delta: string }): Generator<ArtifactEvent> {
    state.buffer += delta;
    let progressed = true;
    while (progressed && state.buffer.length > 0) {
      progressed = state.inside ? yield* drainInside() : yield* drainOutside();
    }
  }

  /** Emit text up to the next open tag; `true` when an artifact was opened and draining should continue. */
  function* drainOutside(): Generator<ArtifactEvent, boolean> {
    const open = findOpenTag(state.buffer);
    const textEnd = open.kind === 'none' ? state.buffer.length : open.start;
    if (textEnd > 0) {
      yield { type: 'text', delta: state.buffer.slice(0, textEnd) };
      state.buffer = state.buffer.slice(textEnd);
    }
    if (open.kind !== 'complete') return false;
    const attrs = parseQuotedAttrs({ raw: open.attrs });
    Object.assign(state, {
      inside: true,
      identifier: attrs['identifier'] ?? '',
      artifactType: attrs['type'] ?? '',
      title: attrs['title'] ?? '',
      content: '',
      buffer: state.buffer.slice(open.end - open.start),
    });
    yield {
      type: 'artifact:start',
      identifier: state.identifier,
      artifactType: state.artifactType,
      title: state.title,
    };
    return true;
  }

  /** Emit body up to the close tag; `true` when the artifact closed and draining should continue. */
  function* drainInside(): Generator<ArtifactEvent, boolean> {
    const closeIdx = state.buffer.indexOf(CLOSE_TAG);
    // Hold back enough bytes to detect a partial close tag at the tail.
    const chunkEnd = closeIdx === -1 ? state.buffer.length - (CLOSE_TAG.length - 1) : closeIdx;
    if (chunkEnd > 0) {
      const chunk = state.buffer.slice(0, chunkEnd);
      state.content += chunk;
      state.buffer = state.buffer.slice(chunkEnd);
      yield { type: 'artifact:chunk', identifier: state.identifier, delta: chunk };
    }
    if (closeIdx === -1) return false;
    yield { type: 'artifact:end', identifier: state.identifier, fullContent: state.content };
    Object.assign(state, {
      inside: false,
      identifier: '',
      artifactType: '',
      title: '',
      content: '',
      buffer: state.buffer.slice(CLOSE_TAG.length),
    });
    return true;
  }

  function* flush(_requiredArgs: Record<string, never>): Generator<ArtifactEvent> {
    if (state.inside) {
      if (state.buffer.length > 0) {
        state.content += state.buffer;
        yield { type: 'artifact:chunk', identifier: state.identifier, delta: state.buffer };
        state.buffer = '';
      }
      yield { type: 'artifact:end', identifier: state.identifier, fullContent: state.content };
    } else if (state.buffer.length > 0) {
      yield { type: 'text', delta: state.buffer };
    }
    state.buffer = '';
    state.inside = false;
  }

  return { feed, flush };
}

/**
 * Convenience wrapper over {@link createArtifactParser} for the common
 * non-streaming case: parse a complete string in one call. Matches the
 * `parseArtifacts()` name from the target API — feeds the whole content
 * through a fresh parser instance and flushes it, collecting every event.
 *
 * @param content - A complete (already fully-arrived) message body.
 * @complexity O(n) in `content.length` (one `feed` + one `flush` over the whole string).
 */
export function parseArtifacts({ content }: { content: string }): ArtifactEvent[] {
  const parser = createArtifactParser({});
  return [...parser.feed({ delta: content }), ...parser.flush({})];
}

/**
 * @module pointer
 *
 * Detects an assistant reply that is *only* a pointer to an existing file
 * ("see design.html") rather than new content, so a host can resolve it to
 * that file instead of treating the short reply as a fresh artifact.
 */
interface HtmlPointerArtifactTargetInput {
  content: string;
  candidateFileName: string;
  projectFiles: Array<{ name: string; path?: string }>;
}

const MAX_POINTER_TEXT_BYTES = 100;
const POINTER_TARGET_RE = /^(?:见|see)(?:\s*[:：]\s*|\s+)[`"'“”‘’]?(.+?\.html?)[`"'“”‘’]?[.。]?$/iu;
const SCRIPT_OR_STYLE_RE = /<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi;
const HTML_TAG_RE = /<[^>]+>/g;

/**
 * Resolve a short "see foo.html"-style reply to the referenced file name, if
 * `content` is (after stripping tags) nothing but such a pointer and the
 * target unambiguously resolves against `projectFiles`.
 *
 * @returns The resolved target file path/name, or `null` when `content`
 *   isn't a bare pointer, the target is unsafe, or it doesn't resolve to
 *   exactly one known file.
 * @complexity O(n + m) in `content.length` plus `projectFiles.length`.
 */
export function resolveHtmlPointerArtifactTarget(input: HtmlPointerArtifactTargetInput): string | null {
  const target = extractPointerTarget(input.content);
  if (target === null || target === input.candidateFileName || !isSafeHtmlTarget(target)) return null;
  return resolveAgainstProjectFiles({ target, candidateFileName: input.candidateFileName, projectFiles: input.projectFiles });
}

/** The normalized file name a bare short pointer reply names, or `null` when `content` isn't one. */
function extractPointerTarget(content: string): string | null {
  const pointerText = visiblePointerText(content);
  if (!pointerText || utf8ByteLength(pointerText) > MAX_POINTER_TEXT_BYTES) return null;
  const match = POINTER_TARGET_RE.exec(pointerText);
  // The target group is a mandatory (non-optional) part of the pattern, not
  // inside an alternation, so it's always defined when `match` is non-null;
  // the assertion just satisfies `noUncheckedIndexedAccess`.
  return match ? normalizeTarget(match[1]!) : null;
}

/** A full-path match wins; otherwise exactly one basename match that isn't the candidate itself. */
function resolveAgainstProjectFiles({ target, candidateFileName, projectFiles }: Omit<HtmlPointerArtifactTargetInput, 'content'> & { target: string }): string | null {
  const projectFileNames = projectFiles.map((file) => file.path || file.name).filter((name) => /\.html?$/i.test(name));
  if (projectFileNames.includes(target)) return target;
  const [only, ...others] = projectFileNames.filter((name) => basename(name) === target);
  return only !== undefined && others.length === 0 && only !== candidateFileName ? only : null;
}

function visiblePointerText(content: string): string {
  const stripped = content
    .replace(/^﻿/, '')
    .replace(SCRIPT_OR_STYLE_RE, ' ')
    .replace(HTML_TAG_RE, ' ');
  return decodeBasicHtmlEntities(stripped).replace(/\s+/g, ' ').trim();
}

function normalizeTarget(value: string): string {
  return value.trim().replace(/^[`"'“”‘’]+|[`"'“”‘’]+$/g, '');
}

function isSafeHtmlTarget(value: string): boolean {
  if (!/\.(?:html?|HTML?)$/.test(value)) return false;
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) return false;
  if (value.startsWith('/') || value.includes('\\') || value.includes('\0')) return false;
  return value.split('/').every((segment) => segment && segment !== '.' && segment !== '..');
}

function basename(value: string): string {
  const i = value.lastIndexOf('/');
  return i >= 0 ? value.slice(i + 1) : value;
}

function utf8ByteLength(value: string): number {
  return new TextEncoder().encode(value).length;
}

function decodeBasicHtmlEntities(value: string): string {
  return value
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

/**
 * @module recover
 *
 * Recovery helpers for HTML artifacts a model emitted outside the
 * `<artifact>` protocol — as prose next to a complete `<html>` document, as
 * a standalone document reply, or as a single fenced ```html block.
 */
import { validateHtmlArtifact } from './validate.js';

type RecoverHtmlArtifactInput = {
  artifactHtml: string;
  identifier?: string | undefined;
  sourceText?: string | undefined;
};

const HTML_OPEN_RE = /<html\b/gi;
const HTML_CLOSE_RE = /<\/html\s*>/gi;
const ADJACENT_DOCTYPE_RE = /<!doctype\s+html\b[^>]*>\s*$/i;
const HTML_FENCE_RE = /```(?:html|HTML)\s*\n([\s\S]*?)\n```/g;

function findLastArtifactOpen(sourceText: string, identifier?: string): number {
  if (!identifier) return sourceText.lastIndexOf('<artifact');

  const escapedIdentifier = identifier.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const taggedOpenRe = new RegExp(`<artifact\\b(?=[^>]*\\bidentifier\\s*=\\s*(?:"${escapedIdentifier}"|'${escapedIdentifier}'))[^>]*>`, 'gi');
  let last = -1;
  let match: RegExpExecArray | null;
  while ((match = taggedOpenRe.exec(sourceText)) !== null) {
    last = match.index;
  }
  return last !== -1 ? last : sourceText.lastIndexOf('<artifact');
}

function lastIndexOfRegex(re: RegExp, text: string): number {
  re.lastIndex = 0;
  let last = -1;
  let match: RegExpExecArray | null;
  while ((match = re.exec(text)) !== null) {
    last = match.index;
  }
  return last;
}

/**
 * When an `<artifact>` body fails {@link validateHtmlArtifact} (looks like
 * prose, not a document) but a complete `<html>…</html>` document
 * immediately precedes the artifact tag in the same turn's `sourceText`,
 * recover that preceding document as the real artifact content.
 *
 * @returns The recovered HTML, or `null` when the artifact body already
 *   validates, or no adjacent recoverable document is found.
 * @complexity O(n) in `sourceText.length`.
 */
export function recoverHtmlArtifactFromPrecedingDocument({ artifactHtml, identifier, sourceText }: RecoverHtmlArtifactInput): string | null {
  if (!sourceText) return null;
  if (validateHtmlArtifact({ content: artifactHtml }).ok) return null;

  const artifactOpen = findLastArtifactOpen(sourceText, identifier);
  if (artifactOpen === -1) return null;

  const beforeArtifact = sourceText.slice(0, artifactOpen);
  if (!/<\/html\s*>\s*$/i.test(beforeArtifact)) return null;

  const htmlOpenStart = lastIndexOfRegex(HTML_OPEN_RE, beforeArtifact);
  if (htmlOpenStart === -1) return null;

  // The guard above (`beforeArtifact` ends with `</html\s*>` plus only
  // trailing whitespace) already pins HTML_CLOSE_RE's last match to that exact
  // trailing tag: `htmlClose` can't be -1, can't fall before `htmlOpenStart`
  // (no room for another `<html` open after it), and the slice from `htmlClose`
  // always re-matches `/^<\/html\s*>/i` — the assertion just satisfies
  // `String.prototype.match`'s generically-nullable return type.
  const htmlClose = lastIndexOfRegex(HTML_CLOSE_RE, beforeArtifact);
  const closeMatch = beforeArtifact.slice(htmlClose).match(/^<\/html\s*>/i)!;

  const beforeHtmlOpen = beforeArtifact.slice(0, htmlOpenStart);
  const adjacentDoctype = beforeHtmlOpen.match(ADJACENT_DOCTYPE_RE);
  const htmlStart = adjacentDoctype ? htmlOpenStart - adjacentDoctype[0].length : htmlOpenStart;

  const candidate = beforeArtifact.slice(htmlStart, htmlClose + closeMatch[0].length).trim();
  return validateHtmlArtifact({ content: candidate }).ok ? candidate : null;
}

/**
 * Resolve the HTML that should actually be persisted for an artifact. When
 * a model emits a prose-only `<artifact>` next to a complete `<html>`
 * document in the same turn, recover the real document from the preceding
 * text; otherwise keep the artifact body as-is.
 *
 * A same-turn duplicate-content lookup and the actual persist path MUST
 * resolve this identically — feeding a dedup check the raw prose summary
 * while persisting the recovered document would make an exact-match dedup
 * miss the same-turn write, causing the recovered document to persist twice.
 */
export function resolvePersistedArtifactHtml(input: RecoverHtmlArtifactInput): string {
  return recoverHtmlArtifactFromPrecedingDocument(input) ?? input.artifactHtml;
}

/** Recover a complete `<html>…</html>` document that IS the entire (trimmed) `sourceText`, or `null` otherwise. */
export function recoverStandaloneHtmlDocument({ sourceText }: { sourceText: string | null | undefined }): string | null {
  const candidate = String(sourceText || '').replace(/^﻿/, '').trim();
  if (!/<\/html\s*>$/i.test(candidate)) return null;
  return validateHtmlArtifact({ content: candidate }).ok ? candidate : null;
}

/**
 * Recover a complete HTML document from a *single* ```html fenced block in
 * `sourceText`. Returns `null` when there is no such fence, more than one
 * candidate, or the recovered text doesn't validate as a document — multiple
 * candidates are ambiguous about which one is "the" artifact, so none is
 * chosen automatically.
 */
export function recoverHtmlDocumentFromMarkdownFence({ sourceText }: { sourceText: string | null | undefined }): string | null {
  const text = String(sourceText || '');
  HTML_FENCE_RE.lastIndex = 0;
  let recovered: string | null = null;
  let count = 0;
  let match: RegExpExecArray | null;
  while ((match = HTML_FENCE_RE.exec(text)) !== null) {
    const candidate = (match[1] || '').replace(/^﻿/, '').trim();
    if (!/<\/html\s*>$/i.test(candidate)) continue;
    if (!validateHtmlArtifact({ content: candidate }).ok) continue;
    recovered = candidate;
    count += 1;
  }
  return count === 1 ? recovered : null;
}

/**
 * @module strip
 *
 * Post-stream `<artifact>` removal/summarization and the streaming-display
 * counterpart that surfaces an in-flight (not-yet-closed) artifact block.
 */
import { computeSkipRanges, isRealArtifactOpenAt, rangeContains, type Range } from './markdown-context.js';
import { parseQuotedAttrs } from './markup-attributes.js';
import {
  recoverHtmlArtifactFromPrecedingDocument,
  recoverHtmlDocumentFromMarkdownFence,
  recoverStandaloneHtmlDocument,
} from './recover.js';

const OPEN = '<artifact';
const CLOSE = '</artifact>';
const HTML_FENCE_RE = /```(?:html|HTML)\s*\n([\s\S]*?)\n```/g;

type MarkdownFenceRange = { start: number; end: number; html: string };

function findUnskipped(content: string, needle: string, fromIndex: number, ranges: ReadonlyArray<Range>): number {
  let from = fromIndex;
  // `needle` (always `CLOSE`, non-empty) makes `content.indexOf` itself
  // return -1 once `from` runs past `content.length` — the loop always exits
  // through the `idx === -1` check below, so no bounded `while` or trailing
  // fallback return is needed for this to provably terminate.
  for (;;) {
    const idx = content.indexOf(needle, from);
    if (idx === -1) return -1;
    if (!rangeContains({ ranges: ranges, p: idx })) return idx;
    from = idx + needle.length;
  }
}

// Like `findUnskipped(OPEN, …)` but also rejects prefix-shared literals like
// `<artifactual` — only `<artifact` followed by whitespace counts as a real
// protocol open. Matches the streaming parser's `findOpenTag` real-open guard
// so the two paths agree on what a renderer will treat as a tag.
function findRealOpen(content: string, fromIndex: number, ranges: ReadonlyArray<Range>): number {
  let from = fromIndex;
  // Same reasoning as findUnskipped: `OPEN` is a fixed non-empty literal, so
  // `content.indexOf` alone provides the bound safety once `from` runs past
  // `content.length` — no separate bounded `while` is needed.
  for (;;) {
    const idx = content.indexOf(OPEN, from);
    if (idx === -1) return -1;
    if (rangeContains({ ranges: ranges, p: idx }) || !isRealArtifactOpenAt({ content: content, idx: idx })) {
      from = idx + OPEN.length;
      continue;
    }
    return idx;
  }
}

// For complete (non-streaming) content, an unclosed fence renders as a code
// block extending to end of input — the stripper mirrors that, otherwise a
// literal `<artifact …>` tucked into a trailing code example (no trailing
// newline) gets treated as a real protocol tag and eaten.
function completeContentSkipRanges({ content }: { content: string }): Range[] {
  const { ranges, unclosedFenceStart } = computeSkipRanges({ buffer: content });
  return unclosedFenceStart !== null ? [...ranges, [unclosedFenceStart, content.length]] : ranges;
}

/** Positions of a complete real block: its `<artifact`, the open tag's `>`, and its `</artifact>`. */
type ArtifactBlock = { open: number; openEnd: number; close: number };

/**
 * The first complete real `<artifact …>…</artifact>` block at or after
 * `fromIndex`, or `null` when there is no real open, the open tag never
 * terminates with `>`, or no real close follows it.
 */
function findCompleteArtifactBlock(
  { content, ranges }: { content: string; ranges: ReadonlyArray<Range> },
  { fromIndex = 0 }: { fromIndex?: number } = {},
): ArtifactBlock | null {
  const open = findRealOpen(content, fromIndex, ranges);
  if (open === -1) return null;
  const openEnd = content.indexOf('>', open);
  if (openEnd === -1) return null;
  const close = findUnskipped(content, CLOSE, openEnd, ranges);
  return close === -1 ? null : { open, openEnd, close };
}

/**
 * Remove the first real `<artifact …>…</artifact>` block from `content`.
 *
 * "Real" excludes any `<artifact` substring that a Markdown-rendering chat
 * surface would render as inline code or part of a fenced code block —
 * those are literal recitations of the protocol and must survive intact,
 * otherwise a rendered reply gets silently truncated mid-explanation.
 *
 * If no real open tag exists, `content` is returned unchanged. If a real
 * open exists but no matching real close is found, `content` is also
 * returned unchanged (refusing to strip is safer than truncating to
 * end-of-string when a tag is malformed or still streaming).
 *
 * @complexity O(n) in `content.length` — one skip-range computation plus a
 *   pair of linear scans for the open/close tags.
 */
export function stripArtifact({ content }: { content: string }): string {
  const block = findCompleteArtifactBlock({ content, ranges: completeContentSkipRanges({ content }) });
  if (!block) return content;
  return (content.slice(0, block.open) + content.slice(block.close + CLOSE.length)).trim();
}

function findSingleRecoverableHtmlFence(content: string): MarkdownFenceRange | null {
  HTML_FENCE_RE.lastIndex = 0;
  let recovered: MarkdownFenceRange | null = null;
  let count = 0;
  let match: RegExpExecArray | null = HTML_FENCE_RE.exec(content);
  while (match !== null) {
    const html = (match[1] || '').replace(/^﻿/, '').trim();
    if (recoverHtmlDocumentFromMarkdownFence({ sourceText: match[0] }) === html) {
      recovered = { start: match.index, end: match.index + match[0].length, html };
      count += 1;
    }
    match = HTML_FENCE_RE.exec(content);
  }
  return count === 1 ? recovered : null;
}

function findRecoverablePrecedingHtmlArtifact(sourceText: string): string | null {
  const ranges = completeContentSkipRanges({ content: sourceText });

  let from = 0;
  // `findRealOpen` already returns -1 once `from` runs past `sourceText.length`
  // (it inherits the same `indexOf`-based bound safety), so this loop also
  // always exits through an inner return — no trailing fallback needed.
  for (;;) {
    const block = findCompleteArtifactBlock({ content: sourceText, ranges }, { fromIndex: from });
    if (!block) return null;

    const attrs = parseQuotedAttrs({ raw: sourceText.slice(block.open, block.openEnd) });
    const recovered = recoverHtmlArtifactFromPrecedingDocument({
      artifactHtml: sourceText.slice(block.openEnd + 1, block.close),
      identifier: attrs['identifier'],
      sourceText,
    });
    if (recovered) return recovered;

    from = block.close + CLOSE.length;
  }
}

function stripRecoverablePrecedingHtml(content: string, sourceText: string): string | null {
  const recovered = findRecoverablePrecedingHtmlArtifact(sourceText);
  if (!recovered) return null;

  const start = content.lastIndexOf(recovered);
  if (start === -1) return null;

  return `${content.slice(0, start)}${content.slice(start + recovered.length)}`.trim();
}

/**
 * Display-only cleanup for a fallback shape some models emit: a complete
 * HTML document as a standalone reply, or as a single ```html fenced block,
 * instead of using the `<artifact>` protocol. A host that persists that
 * recovered document as a real file (see `resolvePersistedArtifactHtml` in
 * `./recover.js`) uses this helper to remove the now-duplicate raw document
 * from the rendered chat bubble.
 *
 * Must never be used to rewrite the canonical stored message content — only
 * the *display* copy — because that content is the transcript future agent
 * turns and forked conversations read from.
 *
 * @complexity O(n) in `content.length` (plus one bounded regex scan over `sourceText` for the fence-recovery path).
 */
export function stripRecoveredHtmlFallbackForDisplay({ content }: { content: string }, { sourceText = content }: { sourceText?: (string) | undefined } = {}): string {
  const withoutPrecedingDocument = stripRecoverablePrecedingHtml(content, sourceText);
  if (withoutPrecedingDocument !== null) return withoutPrecedingDocument;

  if (recoverStandaloneHtmlDocument({ sourceText: content })) return '';

  const fence = findSingleRecoverableHtmlFence(content);
  if (!fence) return content;
  return `${content.slice(0, fence.start)}${content.slice(fence.end)}`.trim();
}

/**
 * A persisted file a host confirms an artifact save wrote to storage.
 * `identifier` is the artifact manifest's `metadata.identifier` when present
 * — the strongest link, since it survives a collision-suffix rename that
 * would break a name-only match.
 */
export interface PersistedArtifactFileRef {
  name: string;
  identifier?: string;
}

type ArtifactFileExt = '.html' | '.jsx' | '.tsx' | '.css' | '.svg' | '.md';

// Checked in order; the first rule whose identifier suffix, exact type, or type substring matches wins.
const EXTENSION_RULES: ReadonlyArray<{ ext: ArtifactFileExt; typeIncludes: readonly string[]; typeEquals?: string }> = [
  { ext: '.tsx', typeIncludes: ['tsx'] },
  { ext: '.jsx', typeIncludes: ['jsx', 'react'] },
  { ext: '.css', typeIncludes: ['css'] },
  { ext: '.svg', typeIncludes: ['svg'] },
  { ext: '.md', typeIncludes: ['markdown'], typeEquals: 'md' },
];

// The on-disk extension a persist path would pick from the artifact's type/identifier.
function artifactExtensionForAttrs(attrs: Record<string, string>): ArtifactFileExt {
  const type = (attrs['type'] || '').toLowerCase();
  const identifier = (attrs['identifier'] || '').toLowerCase();
  const rule = EXTENSION_RULES.find(
    (r) => identifier.endsWith(r.ext) || r.typeEquals === type || r.typeIncludes.some((hint) => type.includes(hint)),
  );
  return rule?.ext ?? '.html';
}

// The slug a persist path would derive the file name from.
function artifactBaseNameForAttrs(attrs: Record<string, string>): string {
  return (
    (attrs['identifier'] || attrs['title'] || 'artifact')
      .toLowerCase()
      .replace(/[^a-z0-9_-]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 60) || 'artifact'
  );
}

/**
 * Find the persisted file this artifact block was saved to, or `null` when
 * persistence cannot be confirmed. Match order: manifest identifier first
 * (strongest — survives collision-suffix renames), then the derived
 * `<slug><ext>` / `<slug>-<n><ext>` file name.
 *
 * @complexity O(m) in `persistedFiles.length` (linear `find`s).
 */
export function matchPersistedArtifactFile({ attrs, persistedFiles }: { attrs: Record<string, string>; persistedFiles: ReadonlyArray<PersistedArtifactFileRef> }
): PersistedArtifactFileRef | null {
  const identifier = attrs['identifier'] ?? '';
  if (identifier) {
    const byManifest = persistedFiles.find((f) => f.identifier === identifier);
    if (byManifest) return byManifest;
  }
  const ext = artifactExtensionForAttrs(attrs);
  const base = artifactBaseNameForAttrs(attrs);
  const namePattern = new RegExp(`^${base.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?:-\\d+)?${ext.replace('.', '\\.')}$`);
  return persistedFiles.find((f) => namePattern.test(f.name)) ?? null;
}

/**
 * Replace every real `<artifact …>…</artifact>` block whose body is
 * CONFIRMED persisted to a file with a one-line summary, for use in a
 * multi-turn transcript sent back to the agent.
 *
 * Once an artifact lives on disk, an agent reads/edits it from there, never
 * from a transcript copy, so re-sending the whole body every turn is pure
 * waste — a large artifact balloons every subsequent turn's input. The
 * summary keeps the metadata the agent needs (`identifier`/`title`/`type`
 * plus the saved file name) and points it at the on-disk file.
 *
 * Persistence is confirmed against `persistedFiles` — evidence a host
 * derives from its own per-turn file-write bookkeeping (see
 * {@link import('../transcript.js').buildTranscript}'s
 * `resolvePersistedArtifactFiles` option). A save can fail validation or a
 * write, in which case the transcript copy is the ONLY surviving artifact
 * body — an unmatched block is left verbatim so a follow-up turn can still
 * inspect or repair it.
 *
 * Uses the same skip-range / real-open detection as {@link stripArtifact},
 * so a literal `<artifact …>` recited inside a code fence is left intact —
 * only genuine protocol blocks are summarized. Malformed / still-streaming
 * blocks (real open, no real close) are left untouched.
 *
 * @complexity O(n) in `content.length` across the whole scan (each iteration
 *   consumes at least one full artifact block or the remaining tail), times
 *   O(m) for the `persistedFiles` lookup per block.
 */
export function summarizeArtifactsForTranscript({ content, persistedFiles }: { content: string; persistedFiles: ReadonlyArray<PersistedArtifactFileRef> }): string {
  if (persistedFiles.length === 0) return content;
  let result = '';
  let cursor = 0;
  // Recompute skip ranges per iteration against the remaining tail so indices
  // stay valid as we consume the string left to right. Each iteration either
  // returns or consumes at least one whole block, so the loop terminates.
  for (;;) {
    const tail = content.slice(cursor);
    const block = findCompleteArtifactBlock({ content: tail, ranges: completeContentSkipRanges({ content: tail }) });
    // No real open, an open tag that never terminates, or a real open but no
    // real close — refuse to summarize (safer than eating to end-of-string on
    // a malformed/streaming tag). Keep the rest as-is.
    if (!block) return result + tail;
    const afterBlock = block.close + CLOSE.length;
    const attrs = parseQuotedAttrs({ raw: tail.slice(block.open, block.openEnd) });
    const persisted = matchPersistedArtifactFile({ attrs: attrs, persistedFiles: persistedFiles });
    result += persisted
      ? tail.slice(0, block.open) + artifactTranscriptSummary(attrs, persisted)
      : // Unconfirmed save — the transcript copy may be the only surviving
        // body. Keep the block verbatim and keep scanning past it.
        tail.slice(0, afterBlock);
    cursor += afterBlock;
  }
}

function artifactTranscriptSummary(attrs: Record<string, string>, persisted: PersistedArtifactFileRef): string {
  const id = attrs['identifier'] ?? '';
  const title = attrs['title'] ?? '';
  const type = attrs['type'] ?? 'text/html';
  const meta = [id ? `identifier="${id}"` : '', title ? `title="${title}"` : '', `type="${type}"`].filter(Boolean).join(', ');
  return `[artifact emitted on a prior turn — ${meta}. Its full content was saved to the file "${persisted.name}" and is NOT repeated here. Read or modify that file on disk (list/grep the workspace directory if it was since renamed); do not rely on this transcript for its contents.]`;
}

export interface StreamingArtifact {
  artifactType: string;
  title: string;
  identifier: string;
  /** The artifact body received so far — raw, possibly mid-token. */
  content: string;
}

/**
 * Split `content` around the first real `<artifact …>` whose closing
 * `</artifact>` has NOT yet arrived — i.e. an artifact whose body is still
 * streaming in. Returns the text *before* the open tag as `head` (safe to
 * render as Markdown) and the in-flight artifact as `live`.
 *
 * This is the streaming-display counterpart to {@link stripArtifact}: the
 * stripper removes a *completed* block once `</artifact>` lands, whereas
 * this surfaces the *incomplete* one so a chat surface can show a live
 * preview instead of leaking the raw `<artifact …>` tag plus half-written
 * body as text.
 *
 * Returns `{ head: content, live: null }` when there is no open artifact,
 * when the open tag already has a matching close (defer to the stripper),
 * or when the artifact `type` is a non-text/HTML kind (media artifacts must
 * not render as a code panel). "Real" open detection reuses the same
 * skip-range logic as the stripper.
 *
 * @complexity O(n) in `content.length`.
 */
export function splitStreamingArtifact({ content }: { content: string }): { head: string; live: StreamingArtifact | null } {
  const ranges = completeContentSkipRanges({ content });
  const open = findRealOpen(content, 0, ranges);
  if (open === -1) return { head: content, live: null };
  const gt = content.indexOf('>', open);
  if (gt === -1) {
    // The open tag's attributes are still streaming — the type/title aren't
    // known yet, but an artifact is starting, so show the box (empty body)
    // and hide the partial `<artifact …` tail from Markdown.
    return {
      head: content.slice(0, open).replace(/\s+$/, ''),
      live: { artifactType: '', title: '', identifier: '', content: '' },
    };
  }
  // A matching close means the block is complete; defer to stripArtifact.
  if (findUnskipped(content, CLOSE, gt, ranges) !== -1) return { head: content, live: null };
  const attrs = parseQuotedAttrs({ raw: content.slice(open, gt) });
  const artifactType = attrs['type'] ?? '';
  // Only HTML/text artifacts read as code. An unknown type (attrs not fully
  // parsed, or omitted) is treated as code-eligible since the dominant case
  // is text/html; media/binary types fall through and render as raw text.
  if (artifactType && !/html|text\//i.test(artifactType)) return { head: content, live: null };
  return {
    head: content.slice(0, open).replace(/\s+$/, ''),
    live: {
      artifactType,
      title: attrs['title'] ?? '',
      identifier: attrs['identifier'] ?? '',
      content: content.slice(gt + 1),
    },
  };
}

/**
 * @module validate
 *
 * Pre-write structural sniff for AI-emitted HTML artifacts.
 *
 * Defends an HTML-artifact persistence path against the failure mode where a
 * model emits an `<artifact type="text/html">…</artifact>` block whose body
 * is a prose summary instead of a complete document. Without this gate, such
 * content can land on disk as a real `.html` file and pollute a file panel
 * as a phantom artifact tab.
 *
 * Policy (intentionally narrow — false positives here block real saves):
 * - non-empty after trimming BOM and leading whitespace
 * - meets a minimum length threshold
 * - the *first* non-whitespace token is `<!doctype html>` or `<html`
 *   (anchored at the start; mid-string mentions of these tags do NOT count —
 *   prose like "Updated the <html lang> attribute…" must be rejected)
 * - URL-bearing attributes or CSS `url(...)` / `@import` values do not point
 *   at a reserved internal workspace-storage path
 *
 * What this gate is NOT:
 * - It is **not** an HTML linter or validator. Malformed but
 *   recognizably document-shaped HTML passes; only content that obviously
 *   isn't a document fails. The guarantee is "blocks obvious prose-as-HTML",
 *   not "validates well-formed HTML."
 * - It does **not** cover `.jsx`/`.tsx` or any other artifact kind — a caller
 *   should only invoke this for an HTML-typed artifact.
 * - It does **not** apply to user-driven file saves through some other path;
 *   those may legitimately persist partial drafts.
 *
 * Threshold note: 64 chars rejects minimal empty-body documents like
 * `<!doctype html><html><body></body></html>` (49 chars) — AI-emitted
 * artifacts are expected to be non-trivial deliverables, not test fixtures,
 * so the lower bound favors fewer phantom files over preserving
 * fixture-grade empties.
 */

const MIN_HTML_LENGTH = 64;
const STARTS_WITH_DOCUMENT_RE = /^(?:<!doctype\s+html\b|<html\b)/i;
/** Path segments reserved for internal workspace/artifact storage that a saved document must never reference. */
const RESERVED_WORKSPACE_PATH_RE = /(?:^|\/|\.\/)(?:\.live-artifacts|\.workspace|\.tmp)(?=$|[/?#"'`\s>)])/i;
const URL_SCHEME_RE = /^[a-z][a-z0-9+.-]*:/i;
const URL_ATTRIBUTE_RE = /\b(href|src|srcset|poster|action|formaction|data|xlink:href)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))/gi;
const STYLE_ATTRIBUTE_RE = /\bstyle\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))/gi;
const HTML_TAG_RE = /<[a-z][^>]*>/gi;
const STYLE_BLOCK_RE = /<style\b[^>]*>([\s\S]*?)<\/style>/gi;
const CSS_URL_RE = /\burl\(\s*(?:"([^"]*)"|'([^']*)'|([^)]*?))\s*\)/gi;
const CSS_IMPORT_RE = /@import\s+(?:url\(\s*(?:"([^"]*)"|'([^']*)'|([^)]*?))\s*\)|"([^"]*)"|'([^']*)')/gi;

export type HtmlArtifactValidationResult = { ok: true } | { ok: false; reason: string };

/**
 * Sniff-test whether `content` looks like a complete HTML document rather
 * than prose that happens to mention HTML.
 *
 * @complexity O(n) in `content.length` — a handful of linear regex scans.
 */
export function validateHtmlArtifact({ content }: { content: string }): HtmlArtifactValidationResult {
  const trimmed = content.replace(/^﻿/, '').trim();
  if (trimmed.length === 0) {
    return { ok: false, reason: 'empty content' };
  }
  if (trimmed.length < MIN_HTML_LENGTH) {
    return { ok: false, reason: `content too short to be HTML (got ${trimmed.length} chars, need ≥${MIN_HTML_LENGTH})` };
  }
  if (!STARTS_WITH_DOCUMENT_RE.test(trimmed)) {
    return { ok: false, reason: 'content does not start with <!doctype html> or <html — looks like prose, not a complete HTML document' };
  }
  if (referencesReservedWorkspacePath(trimmed)) {
    return { ok: false, reason: 'content references a reserved internal workspace-storage path' };
  }
  return { ok: true };
}

function referencesReservedWorkspacePath(content: string): boolean {
  return hasReservedWorkspacePathInTags(content) || hasReservedWorkspacePathInStyleBlocks(content);
}

function hasReservedWorkspacePathInTags(content: string): boolean {
  HTML_TAG_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = HTML_TAG_RE.exec(content)) !== null) {
    // A successful regex-exec result's whole-match slot (`match[0]`) is never
    // undefined; the assertion just satisfies `noUncheckedIndexedAccess`.
    const tag = match[0]!;
    if (hasReservedWorkspacePathAttribute(tag) || hasReservedWorkspacePathInStyleAttributes(tag)) {
      return true;
    }
  }
  return false;
}

function hasReservedWorkspacePathAttribute(tag: string): boolean {
  URL_ATTRIBUTE_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = URL_ATTRIBUTE_RE.exec(tag)) !== null) {
    const attributeName = match[1]?.toLowerCase();
    // Exactly one of the three quote-form alternatives (groups 2/3/4)
    // participates in any successful match, so this is always defined; the
    // cast just satisfies `noUncheckedIndexedAccess`.
    const candidate = (match[2] ?? match[3] ?? match[4]) as string;
    if (candidateReferencesReservedWorkspacePath(candidate, attributeName === 'srcset')) {
      return true;
    }
  }
  return false;
}

function hasReservedWorkspacePathInStyleAttributes(tag: string): boolean {
  STYLE_ATTRIBUTE_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = STYLE_ATTRIBUTE_RE.exec(tag)) !== null) {
    // Exactly one of the three quote-form alternatives (groups 1/2/3)
    // participates in any successful match, so this is always defined; the
    // cast just satisfies `noUncheckedIndexedAccess`.
    const cssText = (match[1] ?? match[2] ?? match[3]) as string;
    if (cssTextReferencesReservedWorkspacePath(cssText)) {
      return true;
    }
  }
  return false;
}

function hasReservedWorkspacePathInStyleBlocks(content: string): boolean {
  STYLE_BLOCK_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = STYLE_BLOCK_RE.exec(content)) !== null) {
    // The style-block body group uses a lazy `*?` quantifier (matches even an
    // empty body), so it always participates in a successful match; the
    // assertion just satisfies `noUncheckedIndexedAccess`.
    const cssText = match[1]!;
    if (cssTextReferencesReservedWorkspacePath(cssText)) {
      return true;
    }
  }
  return false;
}

function cssTextReferencesReservedWorkspacePath(cssText: string): boolean {
  for (const pattern of [CSS_URL_RE, CSS_IMPORT_RE]) {
    pattern.lastIndex = 0;
    let match: RegExpExecArray | null;
    while ((match = pattern.exec(cssText)) !== null) {
      // Both CSS_URL_RE and CSS_IMPORT_RE are single top-level alternations
      // across all their capture groups, so exactly one group is ever defined
      // on a successful match — `.find` always finds it; the assertion just
      // satisfies `noUncheckedIndexedAccess`.
      const candidate = match.slice(1).find((value) => value !== undefined)!;
      if (candidateReferencesReservedWorkspacePath(candidate, false)) {
        return true;
      }
    }
  }
  return false;
}

function candidateReferencesReservedWorkspacePath(candidate: string, splitCandidates: boolean): boolean {
  const paths = splitCandidates ? srcsetCandidateUrls(candidate) : [firstUrlToken(candidate)];
  return paths.some((path) => {
    if (!isLocalPathLike(path)) {
      return false;
    }
    return RESERVED_WORKSPACE_PATH_RE.test(pathnameOnly(path));
  });
}

function pathnameOnly(path: string): string {
  const separator = path.search(/[?#]/);
  if (separator === -1) {
    return path;
  }
  return path.slice(0, separator);
}

function srcsetCandidateUrls(srcset: string): string[] {
  const candidates: string[] = [];
  let start = 0;
  let candidate: SrcsetCandidateState | null = null;

  for (let index = 0; index < srcset.length; index += 1) {
    const char = srcset[index]!;
    const isSpace = /\s/.test(char);
    if (candidate === null && (char === ',' || isSpace)) {
      start = index + 1;
      continue;
    }
    candidate ??= { isDataUrl: /^data:/i.test(srcset.slice(index)), sawWhitespaceAfterUrl: false };
    if (isSpace) {
      candidate.sawWhitespaceAfterUrl = true;
    } else if (endsSrcsetCandidate(candidate, char)) {
      candidates.push(srcset.slice(start, index));
      start = index + 1;
      candidate = null;
    }
  }

  candidates.push(srcset.slice(start));
  return candidates.map(firstUrlToken).filter(Boolean);
}

interface SrcsetCandidateState {
  isDataUrl: boolean;
  sawWhitespaceAfterUrl: boolean;
}

// A data: URL may itself contain commas, so for one a comma only ends the
// candidate once whitespace has separated the URL from its descriptor.
function endsSrcsetCandidate(candidate: SrcsetCandidateState, char: string): boolean {
  return char === ',' && (!candidate.isDataUrl || candidate.sawWhitespaceAfterUrl);
}

function firstUrlToken(value: string): string {
  // `String.split()` on a regex separator always returns at least one
  // element (even `''.split(/\s+/)` is `['']`), so `[0]` is never
  // `undefined` here — the assertion only satisfies `noUncheckedIndexedAccess`.
  return value.trim().split(/\s+/)[0]!;
}

function isLocalPathLike(path: string): boolean {
  return path.length > 0 && !path.startsWith('#') && !path.startsWith('//') && !URL_SCHEME_RE.test(path);
}

export { CHAT_BUBBLE_STYLE } from '../../contracts/chat-bubble-style.js';

export interface LazyChatLoaderArgs {
  readonly button: HTMLButtonElement;
  readonly load: (args: Record<string, never>) => Promise<void>;
  readonly open: (args: { focus?: boolean }) => void;
  readonly resume: boolean;
  readonly deepLink: boolean;
  readonly preload?: boolean;
  readonly loadingLabel: string;
  readonly retryLabel: string;
}

/**
 * Activates a host-rendered button without importing chat, React, icons or storage.
 * One in-flight load serves repeated activation; failures remain retryable. Native button
 * keyboard activation also emits click; preventDefault avoids a second toggle after keydown.
 */
export function installLazyChatLoader(args: LazyChatLoaderArgs, _options = {}) {
  let pending: Promise<void> | null = null;
  let ready = false;
  let disposed = false;
  let shouldOpen = false;
  let shouldFocus = false;
  const initialContent = args.button.innerHTML;
  const label = args.button.getAttribute('aria-label') ?? '';
  const activate = async ({ open = true, focus = open }: { open?: boolean; focus?: boolean } = {}, _options = {}): Promise<void> => {
    if (disposed) return;
    if (!pending) { shouldOpen = false; shouldFocus = false; }
    shouldOpen ||= open;
    shouldFocus ||= focus;
    if (pending) return pending;
    args.button.setAttribute('aria-busy', 'true');
    args.button.setAttribute('aria-label', args.loadingLabel);
    args.button.textContent = args.loadingLabel;
    delete args.button.dataset.loadFailed;
    // Defer through a promise so a synchronous host load failure follows the same retry path.
    pending = Promise.resolve().then(() => { if (!ready) return args.load({}); }).then(() => {
      if (disposed) return;
      // Asset readiness survives an open failure; retry must never evaluate the script twice.
      ready = true;
      if (shouldOpen) args.open({ focus: shouldFocus });
      args.button.setAttribute('aria-label', label);
      args.button.innerHTML = initialContent;
      args.button.hidden = true;
    }).catch(() => {
      if (!disposed) {
        args.button.hidden = false;
        args.button.dataset.loadFailed = 'true';
        args.button.setAttribute('aria-label', args.retryLabel);
        args.button.textContent = args.retryLabel;
      }
    }).finally(() => {
      pending = null;
      args.button.removeAttribute('aria-busy');
    });
    return pending;
  };
  const click = () => { void activate({}); };
  const keydown = (event: KeyboardEvent) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault();
    void activate({});
  };
  args.button.addEventListener('click', click);
  args.button.addEventListener('keydown', keydown);
  args.button.dataset.loaderReady = 'true';
  if (args.resume || args.deepLink) void activate({ focus: args.deepLink });
  else if (args.preload) void activate({ open: false });
  return {
    activate,
    dispose(_input: Record<string, never> = {}, _options = {}) {
      disposed = true;
      args.button.removeEventListener('click', click);
      args.button.removeEventListener('keydown', keydown);
      args.button.setAttribute('aria-label', label);
      args.button.innerHTML = initialContent;
      args.button.removeAttribute('aria-busy');
      delete args.button.dataset.loadFailed;
      delete args.button.dataset.loaderReady;
    },
  };
}

/** Loads CSS before a self-mounting classic script; failed elements are removed for retry. */
export async function loadChatAssets({ document, scriptUrl, styleUrl, mount }: {
  document: Document; scriptUrl: string; styleUrl: string; mount?: HTMLElement;
}, _options = {}): Promise<void> {
  const stylesheet = document.createElement('link');
  stylesheet.rel = 'stylesheet';
  stylesheet.href = styleUrl;
  const script = document.createElement('script');
  script.src = scriptUrl;
  const loaded = (element: HTMLLinkElement | HTMLScriptElement) => new Promise<void>((resolve, reject) => {
    element.onload = () => resolve();
    element.onerror = () => reject(new Error('Chat assets could not be loaded'));
    document.head.appendChild(element);
  });
  try {
    await loaded(stylesheet);
    await loaded(script);
    // A classic script's load event proves evaluation, not React commit or a successful mount.
    // Optional for legacy hosts; lazy visitor hosts supply their root as the readiness boundary.
    if (mount && mount.dataset.chatMounted !== 'true') {
      await new Promise<void>((resolve, reject) => {
        const ready = () => { cleanup(); resolve(); };
        const timeout = setTimeout(() => { cleanup(); reject(new Error('Chat widget did not mount')); }, 10_000);
        const cleanup = () => { clearTimeout(timeout); mount.removeEventListener('jini-chat-mounted', ready); };
        mount.addEventListener('jini-chat-mounted', ready);
      });
    }
  }
  catch (error) { stylesheet.remove(); script.remove(); throw error; }
}

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type RefObject } from 'react';
import { useFocusTrap } from '@jini-ai/ui/panel-kit';

/**
 * Shares the panel-kit trap across embeds. Escape respects a child popup's preventDefault;
 * Closing restores the mounted launcher, including after a lazy-loader handoff.
 * A changed resetKey focuses the replacement composer after the host remounts the pane.
 * @complexity O(focusable controls) per Tab; O(1) listeners and retained state.
 */
export function useEmbedChatDialog({ open, onClose, panelRef, launcherRef }: {
  open: boolean; onClose: () => void;
  panelRef: RefObject<HTMLElement | null>; launcherRef: RefObject<HTMLElement | null>;
}, { resetKey }: { resetKey?: number | undefined } = {}): void {
  const wasOpen = useRef(open);
  const previousResetKey = useRef(resetKey);
  useFocusTrap({ containerRef: panelRef }, { active: open });
  useLayoutEffect(() => {
    if (open && previousResetKey.current !== resetKey) {
      panelRef.current?.querySelector<HTMLTextAreaElement>('textarea:not(:disabled)')?.focus();
    }
    previousResetKey.current = resetKey;
  }, [open, resetKey, panelRef]);
  useEffect(() => {
    if (wasOpen.current && !open) {
      const launcher = launcherRef.current;
      (launcher?.querySelector<HTMLElement>('button') ?? launcher)?.focus();
    }
    wasOpen.current = open;
  }, [open, launcherRef]);
  useEffect(() => {
    if (!open) return;
    const panel = panelRef.current;
    const view = panel?.ownerDocument.defaultView;
    if (!panel || !view) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !event.defaultPrevented) {
        event.preventDefault();
        onClose();
      }
    };
    view.addEventListener('keydown', onKeyDown);
    return () => view.removeEventListener('keydown', onKeyDown);
  }, [open, onClose, panelRef]);
}

/** Reusable state/ref wiring for the packaged embed. O(1) besides the shared trap's Tab scan. */
export function useEmbedChatSurface({ initialOpen }: { initialOpen: boolean }, { resetKey }: { resetKey?: number | undefined } = {}) {
  const [open, setOpen] = useState(initialOpen);
  const panelRef = useRef<HTMLDivElement>(null);
  const launcherRef = useRef<HTMLDivElement>(null);
  const panelId = useId();
  const close = useCallback(() => setOpen(false), []);
  const toggle = useCallback(() => setOpen(current => !current), []);
  useEmbedChatDialog({ open, onClose: close, panelRef, launcherRef }, { resetKey });
  return { open, toggle, panelRef, launcherRef, panelId };
}

