/** Confirm discarding messages or a live draft; Cancel/Escape restore the reset button.
 * @complexity O(pane controls + draft length) per request; O(1) retained state.
 */
export function useEmbedChatHeader({ hasMessages, onReset, keyboard }: Pick<EmbedChatHeaderArgs,
  'hasMessages' | 'onReset' | 'keyboard'>, _options = {}) {
  const [confirming, setConfirming] = useState(false);
  const headerRef = useRef<HTMLDivElement>(null);
  const resetButtonRef = useRef<HTMLButtonElement>(null);
  const wasConfirming = useRef(false);
  const cancel = () => setConfirming(false);
  useLayoutEffect(() => {
    if (wasConfirming.current && !confirming) resetButtonRef.current?.focus();
    wasConfirming.current = confirming;
  }, [confirming]);
  useEffect(() => {
    if (!confirming) return;
    return keyboard.subscribe({ onEscape: () => setConfirming(false) });
  }, [confirming, keyboard]);
  return { confirming, cancel, headerRef, resetButtonRef,
    requestReset: () => {
      // The pane owns the draft; inspect its live composer rather than keeping a second copy.
      const composer = headerRef.current?.closest('.jini-chat-pane')?.querySelector<HTMLTextAreaElement>('.jini-composer-input');
      if (hasMessages || composer?.value) setConfirming(true);
      else onReset();
    },
    confirmReset: () => { setConfirming(false); onReset(); },
  };
}

import type { AgentEvent } from '../../core/events.js';
import type { ChatMessage } from '../../core/messages.js';
import type { ChatTransport, RunHandlers, StartRunInput } from '../../core/transport.js';

export interface DecodedSseFrame { readonly event: string | null; readonly data: string }
/** Structurally satisfied by the existing agent-runtime decodeSseStream; host binds it. */
export type SseDecoderPort = (args: { source: AsyncIterable<Uint8Array | string> }) => AsyncIterable<DecodedSseFrame>;
export interface HistoryTurn { readonly role: ChatMessage['role']; readonly content: string }
export interface FetchSseRequest {
  readonly endpoint: string;
  readonly agentId: string;
  readonly message: string;
  readonly history: readonly HistoryTurn[];
  readonly input: StartRunInput;
}
export type FetchSseFrameResult = { readonly event?: AgentEvent; readonly error?: Error; readonly done?: boolean };
export interface FetchSseTransportArgs {
  readonly endpoint: string;
  readonly agentId: string;
  readonly fetch: (url: string, init: RequestInit) => Promise<Response>;
  readonly ids: (args: Record<string, never>) => string;
  readonly decode: SseDecoderPort;
  readonly requestBuilder: (args: FetchSseRequest) => RequestInit;
  readonly frameMapper: (args: { frame: DecodedSseFrame }) => FetchSseFrameResult;
  readonly maxHistoryMessages: number;
  readonly maxHistoryMessageChars: number;
  readonly copy: {
    readonly noUserMessage: string;
    readonly missingBody: string;
    readonly requestFailed: (args: { status: number }) => string;
  };
}
export interface FetchSseTransportOptions {
  readonly createAbortController?: (args: Record<string, never>) => AbortController;
  readonly onLifecycle?: (args: { runId: string; phase: 'started' | 'settled' | 'error' | 'aborted' }) => void;
}
/** Default JSON wire request is an explicit host choice, never a hidden endpoint default. O(history). */
export function buildJsonChatRequest({ message, history }: FetchSseRequest): RequestInit {
  return { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message, history }) };
}
/** Maps the text/error/end/directive JSON protocol with required directive vocabulary and copy. O(data). */
export function mapJsonChatSseFrame({ frame, directiveEventName, streamError }: {
  frame: DecodedSseFrame; directiveEventName: string; streamError: string;
}): FetchSseFrameResult {
  if (!frame.data) return {};
  const data: unknown = JSON.parse(frame.data);
  const obj = typeof data === 'object' && data !== null ? data as Record<string, unknown> : {};
  switch (frame.event) {
    case 'text':
      if (typeof obj.delta !== 'string') throw new Error('Invalid text frame');
      return { event: { kind: 'text', text: obj.delta } };
    case 'error': return { error: new Error(nonEmptyString(obj.message) ?? streamError) };
    case 'end': return { done: true };
    default: return frame.event === directiveEventName ? { event: { kind: 'ext', name: directiveEventName, data } } : {};
  }
}
const nonEmptyString = (value: unknown): string | undefined => (typeof value === 'string' && value ? value : undefined);
async function* responseChunks(body: ReadableStream<Uint8Array>, signal: AbortSignal): AsyncGenerator<Uint8Array> {
  const reader = body.getReader();
  const cancel = () => { void reader.cancel().catch(() => {}); };
  signal.addEventListener('abort', cancel, { once: true });
  if (signal.aborted) cancel();
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return;
      yield value;
    }
  } finally {
    signal.removeEventListener('abort', cancel);
    try { await reader.cancel(); } catch { /* Already closed or aborted. */ }
    reader.releaseLock();
  }
}
/**
 * Creates a cancellable, one-POST-per-run transport with no reattachable server state.
 * Uses the host-bound SSE decoder rather than implementing another parser. Every run
 * owns its controller, listeners and event log; cancellation and end settle once and
 * prevent late events. Input and cancelSignal aborts release readers/listeners, and frames after
 * end cannot mutate the settled reply. A later settlement clears an earlier pending directive.
 * Default request bytes retain the {message, history} wire shape; a host requestBuilder may carry
 * required agent identity differently. No browser module imports a Node-backed runtime barrel.
 * The returned positional methods implement the existing ChatTransport.
 * @complexity O(history + streamed bytes + emitted events); O(emitted events + decoder buffer) space.
 */
export function createFetchSseTransport(args: FetchSseTransportArgs, options: FetchSseTransportOptions = {}): ChatTransport {
  for (const limit of [args.maxHistoryMessages, args.maxHistoryMessageChars]) {
    if (!Number.isSafeInteger(limit) || limit < 0) throw new Error('Invalid history limit');
  }
  if (!args.endpoint || !args.agentId) throw new Error('Endpoint and agent identity are required');
  const activeRuns = new Map<string, AbortController>();
  const observe = (runId: string, phase: RunPhase) => {
    try { options.onLifecycle?.({ runId, phase }); } catch { /* Telemetry cannot break a run. */ }
  };
  return {
    async startRun(input, handlers) {
      const latestIndex = latestUserIndex(input.history);
      const message = input.history[latestIndex]?.content;
      if (!message) throw new Error(args.copy.noUserMessage);
      const history = priorHistory({ history: input.history, latestIndex, maxMessages: args.maxHistoryMessages, maxChars: args.maxHistoryMessageChars });
      // Build before registering a run, so a synchronous host-builder failure leaks no state.
      const request = args.requestBuilder({ endpoint: args.endpoint, agentId: args.agentId, message, history, input });
      const runId = args.ids({});
      if (!runId || activeRuns.has(runId)) throw new Error('Run ID must be unique and nonempty');
      const controller = options.createAbortController?.({}) ?? new AbortController();
      activeRuns.set(runId, controller);
      const run = openRun({ controller, input, handlers },
        { observe: phase => observe(runId, phase), release: () => activeRuns.delete(runId) });
      void pumpRun({ run, args, request });
      return { runId };
    },
    async reattachRun(_runId, handlers) { handlers.onDone([]); },
    async fetchRunStatus() { return null; },
    async stopRun(runId) { activeRuns.get(runId)?.abort(); },
  };
}

type RunPhase = 'started' | 'settled' | 'error' | 'aborted';
/** One run's settle-once state: its controller, listeners and collected event log. */
interface ActiveRun {
  readonly controller: AbortController;
  readonly handlers: RunHandlers;
  readonly collected: AgentEvent[];
  isSettled(): boolean;
  finish(): void;
  report(error: Error): void;
}

function latestUserIndex(history: readonly ChatMessage[]): number {
  let index = history.length - 1;
  while (index >= 0 && history[index]?.role !== 'user') index -= 1;
  return index;
}

/** Prior turns only (the latest user turn travels as `message`), non-empty, count- and char-bounded. */
function priorHistory({ history, latestIndex, maxMessages, maxChars }: {
  history: readonly ChatMessage[]; latestIndex: number; maxMessages: number; maxChars: number;
}): HistoryTurn[] {
  return (maxMessages === 0 ? [] : history.slice(Math.max(0, latestIndex - maxMessages), latestIndex))
    .filter(m => m.content.trim().length > 0)
    .map(m => ({ role: m.role, content: m.content.slice(0, maxChars) }));
}

/** Wires abort listeners and returns the settle-once handle; an already-aborted signal aborts at once. */
function openRun({ controller, input, handlers }: { controller: AbortController; input: StartRunInput; handlers: RunHandlers },
  { observe, release }: { observe: (phase: RunPhase) => void; release: () => void }): ActiveRun {
  const collected: AgentEvent[] = [];
  let settled = false;
  const signals = [input.signal, ...(input.cancelSignal ? [input.cancelSignal] : [])];
  const finish = () => {
    if (settled) return;
    settled = true;
    release();
    for (const signal of signals) signal.removeEventListener('abort', abort);
    controller.signal.removeEventListener('abort', onAborted);
    observe('settled');
    handlers.onDone([...collected]);
  };
  const onAborted = () => { observe('aborted'); finish(); };
  const abort = () => controller.abort();
  controller.signal.addEventListener('abort', onAborted, { once: true });
  for (const signal of signals) signal.addEventListener('abort', abort, { once: true });
  observe('started');
  if (signals.some(signal => signal.aborted)) abort();
  const report = (error: Error) => { observe('error'); handlers.onError(error); };
  return { controller, handlers, collected, isSettled: () => settled, finish, report };
}

/** Performs the POST and streams frames; always settles the run exactly once when it returns. */
async function pumpRun({ run, args, request }: { run: ActiveRun; args: FetchSseTransportArgs; request: RequestInit }): Promise<void> {
  try {
    if (run.isSettled()) return;
    const response = await args.fetch(args.endpoint, { ...request, signal: run.controller.signal });
    await deliverResponse({ run, args, response });
  } catch (error) {
    if (!run.isSettled() && !run.controller.signal.aborted) run.report(error instanceof Error ? error : new Error(String(error)));
  } finally { run.finish(); }
}

async function deliverResponse({ run, args, response }: { run: ActiveRun; args: FetchSseTransportArgs; response: Response }): Promise<void> {
  if (run.isSettled()) { try { await response.body?.cancel(); } catch { /* closed body */ } return; }
  if (!response.ok) return reportHttpFailure({ run, response, requestFailed: args.copy.requestFailed });
  if (!response.body) throw new Error(args.copy.missingBody);
  for await (const frame of args.decode({ source: responseChunks(response.body, run.controller.signal) })) {
    if (run.isSettled() || !dispatchFrame({ run, result: args.frameMapper({ frame }) })) break;
  }
}

async function reportHttpFailure({ run, response, requestFailed }: {
  run: ActiveRun; response: Response; requestFailed: FetchSseTransportArgs['copy']['requestFailed'];
}): Promise<void> {
  const body: unknown = await response.json().catch(() => null);
  if (run.isSettled()) return;
  const serverError = typeof body === 'object' && body !== null && 'error' in body ? nonEmptyString(body.error) : undefined;
  run.report(new Error(serverError ?? requestFailed({ status: response.status })));
}

/** Delivers one mapped frame; returns false once the run is settled (by a handler or an end frame). */
function dispatchFrame({ run, result }: { run: ActiveRun; result: FetchSseFrameResult }): boolean {
  if (result.event) { run.collected.push(result.event); run.handlers.onEvent(result.event); }
  if (run.isSettled()) return false;
  if (result.error) run.report(result.error);
  if (run.isSettled() || result.done) { run.finish(); return false; }
  return true;
}

import { CHAT_BUBBLE_STYLE } from '../../contracts/chat-bubble-style.js';
import { createVanillaChatController } from './state.js';
import type { VanillaChatControllerArgs, VanillaChatState } from './state.js';
import { isQueuedPageAction } from '../../core/browser/page-actions.js';
export { createVanillaChatController } from './state.js';
export type { VanillaChatControllerArgs, VanillaChatState } from './state.js';

export interface VanillaChatCopy {
  readonly title: string;
  readonly fabLabel: string;
  readonly placeholder: string;
  readonly send: string;
  readonly stop: string;
  readonly close: string;
  readonly reset: string;
  readonly resetQuestion: string;
  readonly confirm: string;
  readonly confirmDraft?: string;
  readonly keep: string;
  readonly proposalGo: string;
  readonly proposalLabel: (args: { title: string }) => string;
  readonly thinking: string;
  readonly greeting?: string;
  readonly suggestionsLabel?: string;
}
export interface MountVanillaChatArgs extends Omit<VanillaChatControllerArgs, 'onChange'> {
  readonly element: HTMLElement;
  readonly document: Document;
  readonly copy: VanillaChatCopy;
  readonly suggestions?: readonly string[];
  /** Host renderer must escape raw HTML and reject unsafe link protocols. */
  readonly renderMarkdown: (args: { content: string; element: HTMLElement }) => void;
  readonly scheduleFrame: (args: { callback: () => void }) => () => void;
}

function svgIcon({ document, path }: { document: Document; path: string }): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  const shape = document.createElementNS(svg.namespaceURI, 'path');
  shape.setAttribute('d', path);
  shape.setAttribute('fill', 'none');
  shape.setAttribute('stroke', 'currentColor');
  shape.setAttribute('stroke-width', '2');
  svg.append(shape);
  return svg;
}

/**
 * Mounts a DOM-only chat panel. Native buttons/forms supply keyboard semantics;
 * explicitly opened dialogs trap focus, restore the bubble on close and announce settled replies.
 * Restored panels leave page focus alone. Streaming markdown is rendered at most once per frame.
 * All listeners, scheduled page effects and runs belong to this mount and are disposed.
 * Markdown is an injected host capability; no framework or icon font enters this graph.
 */
export function mountVanillaChat(args: MountVanillaChatArgs, options: { initialOpen?: boolean } = {}) {
  const { document, element, copy } = args;
  const node = <T extends keyof HTMLElementTagNameMap>(tag: T, className: string, text = '') => {
    const result = document.createElement(tag);
    result.className = className;
    result.textContent = text;
    return result;
  };
  const button = (label: string) => {
    const result = node('button', 'jini-chat-vanilla__button', label);
    result.type = 'button';
    return result;
  };
  const shell = node('div', 'jini-chat-vanilla');
  const fab = button('');
  fab.className = 'jini-chat-bubble';
  fab.setAttribute('aria-label', copy.fabLabel);
  fab.setAttribute('aria-haspopup', 'dialog');
  fab.append(svgIcon({ document, path: 'M4 4h16v12H9l-5 4V4z' }));
  const panel = node('section', 'jini-chat-vanilla__panel');
  panel.id = `jini-chat-${args.ids({})}`;
  fab.setAttribute('aria-controls', panel.id);
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', 'false');
  panel.setAttribute('aria-label', copy.title);
  const header = node('header', 'jini-chat-vanilla__header');
  const title = node('strong', 'jini-chat-vanilla__title', copy.title);
  const reset = button(copy.reset);
  const close = button('');
  close.setAttribute('aria-label', copy.close);
  close.append(svgIcon({ document, path: 'M6 6l12 12M18 6L6 18' }));
  header.append(title, reset, close);
  const confirmation = node('div', 'jini-chat-vanilla__confirmation');
  const confirm = button(copy.confirm);
  confirm.classList.add('jini-chat-vanilla__discard');
  const keep = button(copy.keep);
  confirmation.append(node('span', '', copy.resetQuestion), confirm, keep);
  confirmation.hidden = true;
  const log = node('div', 'jini-chat-vanilla__messages');
  log.setAttribute('role', 'log');
  log.setAttribute('aria-live', 'off');
  log.setAttribute('aria-relevant', 'additions text');
  log.setAttribute('aria-label', copy.title);
  log.tabIndex = 0;
  const status = node('div', 'jini-chat-vanilla__status');
  status.setAttribute('role', 'status');
  const announcements = node('div', 'jini-chat-vanilla__announcements');
  announcements.setAttribute('role', 'log');
  announcements.setAttribute('aria-live', 'polite');
  announcements.setAttribute('aria-relevant', 'additions');
  announcements.setAttribute('aria-atomic', 'false');
  const error = node('div', 'jini-chat-vanilla__error');
  error.setAttribute('role', 'alert');
  const proposal = node('div', 'jini-chat-vanilla__proposal');
  const proposalText = node('span', '');
  const go = button(copy.proposalGo);
  proposal.append(proposalText, go);
  const form = node('form', 'jini-chat-vanilla__composer');
  const input = node('textarea', 'jini-chat-vanilla__input');
  input.placeholder = copy.placeholder;
  input.setAttribute('aria-label', copy.placeholder);
  input.maxLength = 8000;
  input.rows = 2;
  const send = button(copy.send);
  send.type = 'submit';
  send.classList.add('jini-chat-vanilla__send');
  send.setAttribute('aria-label', copy.send);
  send.replaceChildren(svgIcon({ document, path: 'M5 4l15 8-15 8v-6l9-2-9-2V4z' }));
  const stop = button(copy.stop);
  form.append(input, send, stop);
  const greeting = node('p', 'jini-chat-vanilla__greeting', copy.greeting);
  const suggestions = node('div', 'jini-chat-vanilla__suggestions');
  if (copy.suggestionsLabel) suggestions.setAttribute('aria-label', copy.suggestionsLabel);
  const suggestionEntries = (args.suggestions ?? []).map(text => ({ text, button: button(text) }));
  const suggestionButtons = suggestionEntries.map(entry => entry.button);
  suggestions.append(...suggestionButtons);
  log.append(greeting, suggestions);
  panel.append(header, confirmation, log, status, announcements, error, proposal, form);
  const bubbleStyle = node('style', '', CHAT_BUBBLE_STYLE);
  shell.append(bubbleStyle, fab, panel);
  element.replaceChildren(shell);
  const rows = new Map<string, { element: HTMLElement; content: string }>();
  let wasOpen = false;
  let initialized = false;
  const liveReplies = new Set<string>();
  const renderChrome = ({ state }: { state: VanillaChatState }) => {
    panel.hidden = !state.open;
    panel.setAttribute('aria-modal', String(state.open));
    fab.setAttribute('aria-expanded', String(state.open));
    fab.querySelector('path')?.setAttribute('d', state.open ? 'M6 6l12 12M18 6L6 18' : 'M4 4h16v12H9l-5 4V4z');
    greeting.hidden = !copy.greeting || state.messages.length > 0;
    suggestions.hidden = suggestionButtons.length === 0 || state.messages.length > 0;
    suggestionButtons.forEach(button => { button.disabled = state.busy; });
    error.textContent = state.error ?? '';
    error.hidden = !state.error;
    status.textContent = state.busy ? copy.thinking : '';
    send.disabled = state.busy || !input.value.trim();
    input.disabled = state.busy;
    stop.hidden = !state.busy;
    proposal.hidden = state.proposal === null;
    proposalText.textContent = state.proposal ? copy.proposalLabel({ title: state.proposal.navigate.target.title }) : '';
  };
  const createRow = ({ message }: { message: VanillaChatState['messages'][number] }) => {
    const row = { element: node('div', `jini-chat-vanilla__message jini-chat-vanilla__message--${message.role}`), content: '\0' };
    rows.set(message.id, row);
    log.append(row.element);
    return row;
  };
  const renderRow = ({ message }: { message: VanillaChatState['messages'][number] }) => {
    const row = rows.get(message.id) ?? createRow({ message });
    if (row.content === message.content) return;
    if (message.role === 'user') row.element.textContent = message.content;
    else args.renderMarkdown({ content: message.content, element: row.element });
    row.content = message.content;
  };
  const announce = ({ text }: { text: string | undefined }) => {
    if (!text) return;
    announcements.append(node('span', '', text));
    // Bound the additions-only live region without replaying earlier replies.
    while (announcements.childElementCount > 2) announcements.firstElementChild!.remove();
  };
  const announceSettledReplies = ({ messages }: { messages: VanillaChatState['messages'] }) => {
    // A dedicated additions-only region announces each LIVE settled reply once. Markdown rows
    // may be rebuilt while streaming, but restored transcripts and old text stay silent.
    for (const message of messages) {
      if (message.role !== 'assistant' || message.runStatus === 'running' || !liveReplies.delete(message.id)) continue;
      announce({ text: rows.get(message.id)?.element.textContent });
    }
  };
  const renderRows = ({ state }: { state: VanillaChatState }) => {
    const pinned = log.scrollHeight - log.scrollTop - log.clientHeight < 80;
    const ids = new Set(state.messages.map(message => message.id));
    for (const [id, row] of rows) if (!ids.has(id)) { row.element.remove(); rows.delete(id); }
    for (const message of state.messages) renderRow({ message });
    announceSettledReplies({ messages: state.messages });
    if (state.messages.length === 0) announcements.replaceChildren();
    if (pinned) log.scrollTop = log.scrollHeight;
  };
  const focusEntry = ({ busy }: { busy: boolean }) => { if (busy) close.focus(); else input.focus(); };
  const moveFocus = ({ state, composerHadFocus, stopHadFocus }: {
    state: VanillaChatState; composerHadFocus: boolean; stopHadFocus: boolean;
  }) => {
    if (!state.open) return;
    if (!wasOpen && initialized) focusEntry({ busy: state.busy });
    else if (state.busy && composerHadFocus) stop.focus();
    else if (!state.busy && stopHadFocus) input.focus();
  };
  const renderFocus = ({ state, composerHadFocus, stopHadFocus, panelHadFocus }: {
    state: VanillaChatState; composerHadFocus: boolean; stopHadFocus: boolean; panelHadFocus: boolean;
  }) => {
    moveFocus({ state, composerHadFocus, stopHadFocus });
    // renderChrome (which always runs first) already ended modal semantics for a closed panel.
    if (!state.open && wasOpen) {
      confirmation.hidden = true;
      if (panelHadFocus) fab.focus();
    }
    wasOpen = state.open;
  };
  let latestState: VanillaChatState;
  let framePending = false;
  let cancelRenderFrame = () => {};
  const render = ({ state }: { state: VanillaChatState }) => {
    latestState = state;
    const panelHadFocus = panel.contains(document.activeElement);
    const composerHadFocus = document.activeElement === input;
    const stopHadFocus = document.activeElement === stop;
    renderChrome({ state });
    renderFocus({ state, composerHadFocus, stopHadFocus, panelHadFocus });
    if (initialized && state.busy) {
      for (const message of state.messages) if (message.role === 'assistant' && message.runStatus === 'running') liveReplies.add(message.id);
      if (framePending) return;
      framePending = true;
      cancelRenderFrame = args.scheduleFrame({ callback: () => {
        framePending = false;
        renderRows({ state: latestState });
      } });
      return;
    }
    cancelRenderFrame();
    framePending = false;
    renderRows({ state });
  };
  const controller = createVanillaChatController({ ...args, onChange: render });
  const listeners: (() => void)[] = [];
  const listen = (target: EventTarget, type: string, handler: EventListener) => {
    target.addEventListener(type, handler);
    listeners.push(() => target.removeEventListener(type, handler));
  };
  suggestionEntries.forEach(({ text, button }) => listen(button, 'click', () => {
    input.value = text;
    renderChrome({ state: controller.getState({}) });
    input.focus();
  }));
  listen(input, 'input', () => renderChrome({ state: controller.getState({}) }));
  listen(fab, 'click', () => controller.setOpen({ open: !controller.getState({}).open }));
  listen(close, 'click', () => controller.setOpen({ open: false }));
  listen(reset, 'click', () => {
    if (controller.getState({}).messages.length === 0 && input.value.length === 0) {
      controller.reset({}); input.focus(); return;
    }
    confirm.textContent = controller.getState({}).messages.length === 0 ? copy.confirmDraft ?? copy.confirm : copy.confirm;
    confirmation.hidden = false; keep.focus();
  });
  const dismissConfirmation = () => { confirmation.hidden = true; reset.focus(); };
  listen(keep, 'click', dismissConfirmation);
  listen(confirm, 'click', () => { confirmation.hidden = true; input.value = ''; controller.reset({}); input.focus(); });
  listen(go, 'click', () => controller.acceptProposal({}));
  listen(stop, 'click', () => controller.cancel({}));
  listen(form, 'submit', event => {
    event.preventDefault();
    const text = input.value;
    if (!text.trim() || controller.getState({}).busy) return;
    input.value = '';
    void controller.send({ text }).then(() => {
      const state = controller.getState({});
      if (state.open && !state.busy && panel.contains(document.activeElement)) input.focus();
    });
  });
  listen(input, 'keydown', event => {
    const key = event as KeyboardEvent;
    if (key.key === 'Enter' && !key.shiftKey && !key.isComposing) { key.preventDefault(); form.requestSubmit(); }
  });
  const onEscape = ({ key }: { key: KeyboardEvent }) => {
    key.preventDefault();
    if (!confirmation.hidden) dismissConfirmation();
    else controller.setOpen({ open: false });
  };
  // Only reached while focus is inside the panel (see the document keydown guard), so wrapping
  // happens exactly at the first/last visible enabled control.
  const trapTab = ({ key }: { key: KeyboardEvent }) => {
    const focusable = Array.from(panel.querySelectorAll<HTMLElement>('button:not(:disabled), textarea:not(:disabled), a[href], [tabindex="0"]'))
      .filter(candidate => !candidate.closest('[hidden]'));
    const first = focusable[0];
    const last = focusable.at(-1);
    if (document.activeElement !== (key.shiftKey ? first : last)) return;
    key.preventDefault();
    (key.shiftKey ? last : first)?.focus();
  };
  listen(document, 'keydown', event => {
    if (!controller.getState({}).open || !panel.contains(document.activeElement)) return;
    const key = event as KeyboardEvent;
    if (key.key === 'Escape') onEscape({ key });
    else if (key.key === 'Tab') trapTab({ key });
  });
  listen(element, 'jini-chat-open', () => {
    controller.setOpen({ open: true });
    focusEntry({ busy: controller.getState({}).busy });
  });
  const queued = { value: args.session.drain({}) };
  let cancelFrame = () => {};
  if (isQueuedPageAction(queued) && queued.value.type !== 'navigate') {
    const action = queued.value;
    cancelFrame = args.scheduleFrame({ callback: () => { args.pageActions.execute({ action }); } });
  }
  controller.setOpen({ open: options.initialOpen ?? controller.getState({}).open });
  initialized = true;
  element.dataset.chatMounted = 'true';
  element.dispatchEvent(new (document.defaultView?.Event ?? Event)('jini-chat-mounted'));
  return {
    controller,
    unmount(_input: Record<string, never> = {}, _opts = {}) {
      listeners.forEach(dispose => dispose());
      cancelFrame();
      cancelRenderFrame();
      delete element.dataset.chatMounted;
      controller.dispose({});
      args.pageActions.clearHighlight({});
      shell.remove();
    },
  };
}

import type { AgentEvent } from '../../core/events.js';
import type { ChatMessage } from '../../core/messages.js';
import { assistantContentFromEvents } from '../../core/assistant-content.js';
import type { ChatTransport } from '../../core/transport.js';
import type { BrowserSessionStore } from '../browser/session-store.js';
import { extractPageActions, splitPageActions } from '../../core/browser/page-actions.js';
import type { PageActionPort, NavigateAction, NonNavigateAction } from '../../core/browser/page-actions.js';

export interface VanillaChatState {
  readonly open: boolean;
  readonly messages: ChatMessage[];
  readonly busy: boolean;
  readonly error: string | null;
  readonly proposal: { navigate: NavigateAction; bundled: NonNavigateAction | null } | null;
}
export interface VanillaChatControllerArgs {
  readonly transport: ChatTransport;
  readonly session: BrowserSessionStore;
  readonly pageActions: PageActionPort;
  readonly directiveEventName: string;
  readonly agentId: string;
  readonly ids: (args: Record<string, never>) => string;
  readonly createAbortController: (args: Record<string, never>) => AbortController;
  readonly onChange: (args: { state: VanillaChatState }) => void;
}

/**
 * Framework-free visitor state over the existing transport/session/page-action owners.
 * Restored messages never replay directives. Only a successful live settlement can act;
 * persistence and queued effects finish synchronously before navigation tears down the page.
 * Reset invalidates callbacks before aborting, preventing late chunks from reviving a thread.
 * @complexity O(retained transcript + reply events + reply characters) per update; storage writes
 * occur only on settle/open/reset/navigation, never per streamed chunk. Session bounds persisted bytes.
 */
export function createVanillaChatController(args: VanillaChatControllerArgs, _options = {}) {
  const initial = args.session.load({});
  let state: VanillaChatState = { ...initial, busy: false, error: null, proposal: null };
  let generation = 0;
  let active: AbortController | null = null;
  const publish = ({ persist = true }: { persist?: boolean } = {}) => {
    if (persist) args.session.save({ state: { open: state.open, messages: state.messages } });
    args.onChange({ state });
  };
  const go = (proposal: NonNullable<VanillaChatState['proposal']>) => {
    if (!args.pageActions.allows({ action: proposal.navigate })) return;
    if (proposal.bundled && args.pageActions.allows({ action: proposal.bundled })) args.session.enqueue({ action: proposal.bundled });
    state = { ...state, proposal: null };
    publish();
    args.pageActions.navigate({ action: proposal.navigate });
  };
  const settleActions = (events: AgentEvent[]) => {
    const actions = extractPageActions({ events, directiveEventName: args.directiveEventName })
      .filter(action => args.pageActions.allows({ action }));
    const { navigate, other } = splitPageActions({ actions });
    if (!navigate) { if (other) args.pageActions.execute({ action: other }); return; }
    const proposal = { navigate, bundled: other };
    if (navigate.auto) go(proposal);
    else { state = { ...state, proposal }; publish(); }
  };
  return {
    getState(_input: Record<string, never> = {}, _opts = {}) { return state; },
    setOpen({ open }: { open: boolean }, _opts = {}) { state = { ...state, open }; publish(); },
    async send({ text }: { text: string }, _opts = {}) {
      const content = text.trim();
      if (!content || state.busy) return false;
      const token = ++generation;
      const abort = args.createAbortController({});
      active = abort;
      const history = [...state.messages, { id: args.ids({}), role: 'user' as const, content }];
      const reply: ChatMessage = { id: args.ids({}), role: 'assistant', content: '', events: [], runStatus: 'running' };
      state = { ...state, messages: [...history, reply], busy: true, error: null, proposal: null };
      publish({ persist: false });
      let events: AgentEvent[] = [];
      let failed = false;
      let settled = false;
      const current = () => token === generation && !settled;
      const updateReply = (next: ChatMessage, { persist = false }: { persist?: boolean } = {}) => {
        state = { ...state, messages: state.messages.map(message => message.id === reply.id ? next : message) };
        publish({ persist });
      };
      const fail = (error: Error) => {
        if (!current()) return;
        failed = true;
        state = { ...state, error: error.message };
        updateReply({ ...reply, content: assistantContentFromEvents({ events }), events: [...events], runStatus: 'failed' });
      };
      const done = (final: AgentEvent[]) => {
        if (!current()) return;
        settled = true;
        active = null;
        events = final;
        state = { ...state, busy: false };
        updateReply({ ...reply, content: assistantContentFromEvents({ events }), events: [...events],
          runStatus: failed ? 'failed' : abort.signal.aborted ? 'canceled' : 'succeeded' }, { persist: true });
        if (!failed && !abort.signal.aborted) settleActions(events);
      };
      try {
        await args.transport.startRun({ history, agentId: args.agentId, assistantMessageId: reply.id, signal: abort.signal }, {
          onEvent(event) {
            if (!current()) return;
            events = [...events, event];
            updateReply({ ...reply, content: assistantContentFromEvents({ events }), events: [...events], runStatus: failed ? 'failed' : 'running' });
          },
          onError: fail,
          onDone: done,
        });
      } catch (error) { fail(error instanceof Error ? error : new Error(String(error))); done(events); }
      return true;
    },
    acceptProposal(_input: Record<string, never> = {}, _opts = {}) { if (state.proposal) go(state.proposal); },
    cancel(_input: Record<string, never> = {}, _opts = {}) { active?.abort(); },
    reset(_input: Record<string, never> = {}, _opts = {}) {
      generation += 1;
      active?.abort();
      active = null;
      args.session.clear({});
      state = { open: state.open, messages: [], busy: false, error: null, proposal: null };
      publish();
    },
    dispose(_input: Record<string, never> = {}, _opts = {}) { generation += 1; active?.abort(); active = null; },
  };
}

/**
 * @module artifact-types
 *
 * Chat's public streaming artifact contracts, used by useArtifactStream and
 * ProjectContextValue. The renderer implementation is available in @jini-ai/ui,
 * but direct delegation would change this compatibility surface: chat registers
 * mutably, resolves newest-first, returns unregister handles, accepts files
 * without manifests and returns the matched file. UI's registry is immutable,
 * replaces registrations by ID, requires a manifest and returns that manifest;
 * its predicate and resolve signatures also pass hints as a separate option.
 *
 * TODO(renderer-delegation): Coordinator must resolve these contracts before
 * delegating to UI. A wildcard re-export is not a behavior-preserving migration.
 */
import type { ArtifactManifest } from '../core/index.js';

/** Generic artifact-file shape a host's project/workspace file maps onto. */
export interface ArtifactFile {
  name: string;
  kind: string;
  content?: string;
  url?: string;
  manifest?: ArtifactManifest;
}

export interface ArtifactRenderContext {
  file: ArtifactFile;
  hints?: Record<string, unknown>;
}

export interface ArtifactRenderer {
  id: string;
  supportsStreaming: boolean;
  renderPartial?: (content: string) => string;
  canRender: (ctx: ArtifactRenderContext) => boolean;
}

export interface ArtifactRenderMatch {
  renderer: ArtifactRenderer;
  file: ArtifactFile;
}

/**
 * A minimal ordered registry of `ArtifactRenderer`s: newest-registered,
 * first-matched (later registrations override earlier matches by registering
 * before resolution, mirroring the tool-renderer registry's "last writer
 * wins on the same id" convention is intentionally NOT used here — artifact
 * renderers are matched by predicate, not by name, so ordering is the
 * override mechanism instead).
 */
export class RendererRegistry {
  private readonly renderers: ArtifactRenderer[] = [];

  /** Registers `renderer`, returning an unregister handle. */
  register(renderer: ArtifactRenderer): () => void {
    this.renderers.unshift(renderer);
    return () => {
      const idx = this.renderers.indexOf(renderer);
      if (idx !== -1) this.renderers.splice(idx, 1);
    };
  }

  /** The newest registered renderer whose `canRender` accepts `ctx`, or `null`. */
  resolve(ctx: ArtifactRenderContext): ArtifactRenderMatch | null {
    for (const renderer of this.renderers) {
      if (renderer.canRender(ctx)) return { renderer, file: ctx.file };
    }
    return null;
  }

  /** Visible mainly for tests. */
  list(): readonly ArtifactRenderer[] {
    return this.renderers;
  }
}

/**
 * @file `AttachmentPreviewModal`'s open/close, focus-management, and content-derivation state,
 * split out of the component per this package's own hooks-file convention (mirrors
 * `packages/admin/src/react/components/ConfirmDialog/ConfirmDialog.hooks.tsx` and
 * `usePreviewModalShell.ts`).
 *
 * **Dialog lifecycle.** Native `<dialog>` + `showModal()`, the same primitive already used one file
 * over in `Markdown.tsx`'s `TableBlock` for its wide-table pop-out (`openTableDialog`/
 * `closeTableDialog`) — reused here rather than a third hand-rolled overlay. That gives Tab-cycling
 * focus containment for free from the browser; this hook only adds the two things `TableBlock`
 * does not need: an explicit focus-restore-to-opener (native `close()` does return focus in a real
 * browser, but jsdom's `showModal`/`close` are both unimplemented — see the guard below — so a test
 * asserting the restore has nothing to observe without doing it by hand, the same reason
 * `ConfirmDialog.hooks.tsx` does it explicitly rather than trusting the platform), and the
 * image/text/unsupported content derivation an attachment preview needs that a table pop-out does
 * not.
 *
 * **Why content can be missing entirely.** `attachment-preview-cache.ts` only ever holds bytes this
 * browser itself staged for upload, in this page session (see that module's doc for why the server
 * cannot hand them back). A cache miss - a reload, a different session, the eviction cap - degrades
 * to the honest "unsupported" status rather than a broken image or an empty text pane.
 *
 * **Why image-ness is not decided by `attachment.kind` alone.** `@jini-ai/http-kit`'s
 * `detectAttachmentKind` (`attachments.ts`) now sniffs PNG/JPEG/GIF/WEBP/AVIF signatures - AVIF was
 * added specifically for the bug that motivated this task, brand-checked against the same ISO-BMFF
 * `ftyp` box `@jini-ai/cms`'s media sniffer uses, so a real `.avif` upload now carries `kind:
 * 'image'` from the server. This module's extension fallback stays anyway, for two reasons that are
 * still true even with AVIF fixed: BMP/ICO/SVG are in `IMAGE_PREVIEW_EXTENSIONS` but are not sniffed
 * server-side at all (no `hasBmpSignature`/etc. exists), so `kind` alone would still misclassify
 * those as `'file'`; and gating on `kind` would make ANY future sniffer gap fail the same way this
 * one did, whereas the extension guess plus the `<img>`'s own `onError` (wired by the component) is
 * self-correcting - if the browser cannot actually decode what got attempted, `imageFailed` flips
 * this back to a text/unsupported status rather than showing a broken-image icon or trusting a wrong
 * guess. The two checks cannot disagree in a way that matters: `looksLikeImageAttachment` is an OR,
 * so a server `kind: 'image'` is decisive on its own, and the extension guess is only ever a
 * fallback that `onError` can retract - never a second, competing source of truth for a format the
 * server already classified.
 */
import { useEffect, useState, type KeyboardEvent, type MouseEvent, type RefCallback, type SyntheticEvent } from 'react';
import type { ChatAttachment } from '../../core/index.js';
import { getAttachmentPreviewSource } from '../hooks/attachment-preview-cache.js';
import { formatAttachmentSize } from './attachment-size.js';
import type { AttachmentPreviewNavigation } from './AttachmentGallery.hooks.js';

export type AttachmentPreviewStatus = 'image' | 'text' | 'unsupported';

/** Extensions attempted as an `<img>` even when `attachment.kind` says otherwise — see module doc. */
const IMAGE_PREVIEW_EXTENSIONS = new Set(['png', 'jpg', 'jpeg', 'gif', 'webp', 'avif', 'bmp', 'ico', 'svg']);

/** Extensions shown in a scrollable monospace pane. Deliberately narrow — see task scope: "txt, md, json, csv, and similar", not every source-code language. */
const TEXT_PREVIEW_EXTENSIONS = new Set(['txt', 'md', 'markdown', 'json', 'csv', 'tsv', 'log', 'yaml', 'yml', 'xml']);

/** Hard cap on rendered text-preview characters, so a large attached log/CSV cannot hang the tab painting one giant `<pre>`. */
export const MAX_TEXT_PREVIEW_CHARS = 200_000;

function extensionOf(name: string): string {
  const dot = name.lastIndexOf('.');
  return dot === -1 ? '' : name.slice(dot + 1).toLowerCase();
}

/** Exported for the component's own render branch, which needs the same answer without re-deriving it from `status`. */
export function looksLikeImageAttachment({ attachment }: { attachment: Pick<ChatAttachment, 'kind' | 'name'> }): boolean {
  return attachment.kind === 'image' || IMAGE_PREVIEW_EXTENSIONS.has(extensionOf(attachment.name));
}

/** The image step an arrow key asks for in the preview (`-1`/`1`), or `0` for any other key. */
export function galleryStepForKey({ key }: { key: string }): number {
  if (key === 'ArrowLeft') return -1;
  if (key === 'ArrowRight') return 1;
  return 0;
}

function looksLikeTextAttachment(name: string): boolean {
  return TEXT_PREVIEW_EXTENSIONS.has(extensionOf(name));
}

/**
 * Reads `file` as text via `FileReader`, not the newer `Blob.prototype.text()` promise API: both
 * are supported in every real evergreen browser, but jsdom (this package's test environment,
 * verified directly - `File`/`Blob` here has no `.text`/`.arrayBuffer` at all) implements
 * `FileReader.readAsText` while leaving `.text()` unimplemented. Choosing the form the test
 * environment can actually exercise avoids a test-only monkeypatch of a browser primitive whose
 * production behavior isn't in question - only its jsdom coverage was.
 */
export function readFileAsText(
  { file }: { file: File },
  { createReader = () => new FileReader() }: { createReader?: () => FileReader } = {},
): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = createReader();
    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
    reader.onerror = () => reject(reader.error ?? new Error('Failed to read attachment as text'));
    reader.readAsText(file);
  });
}

/**
 * `false` in an environment with no Blob-URL support — real browsers have shipped this for well
 * over a decade, but jsdom (this package's own test environment) never implemented it, and this
 * package cannot assume every embedding host is a browser tab. Feature-detected the same way this
 * file already feature-detects `<dialog>`'s `showModal`/`close`, rather than assumed.
 */
export function canCreateObjectUrl(): boolean {
  return typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function';
}

/**
 * Opens `dialog` as a modal and returns the matching close, which also restores focus to whatever
 * was focused when it opened — see this module's doc on why the restore is explicit rather than left
 * to the browser's own (jsdom-absent) default.
 */
function openModalDialog(dialog: HTMLDialogElement): () => void {
  const trigger = document.activeElement;
  if (typeof dialog.showModal === 'function') {
    if (!dialog.open) dialog.showModal();
  } else {
    dialog.setAttribute('open', '');
  }
  return () => {
    if (typeof dialog.close === 'function') {
      if (dialog.open) dialog.close();
    } else {
      dialog.removeAttribute('open');
    }
    if (trigger instanceof HTMLElement) trigger.focus();
  };
}

/**
 * The `<dialog>`'s callback ref: open on attach, close + restore focus on detach. A callback ref
 * rather than an effect reading a ref object, so the element is always in hand — there is no
 * "not attached" case to guard. React 18 and 19 both call it with the element on mount and `null`
 * on unmount, and attach always precedes detach, so `close` is set by the time it is called.
 */
function createDialogRef(): (dialog: HTMLDialogElement | null) => void {
  let close: () => void;
  return (dialog) => {
    if (dialog) close = openModalDialog(dialog);
    else close();
  };
}

export interface AttachmentTextPreview {
  content: string;
  truncated: boolean;
}

export interface AttachmentPreviewController {
  dialogRef: RefCallback<HTMLDialogElement>;
  status: AttachmentPreviewStatus;
  imageUrl: string | undefined;
  onImageError: () => void;
  textLoading: boolean;
  text: AttachmentTextPreview | undefined;
  sizeLabel: string | null;
  handleNativeCancel: (event: SyntheticEvent<HTMLDialogElement>) => void;
  handleBackdropClick: (event: MouseEvent<HTMLDialogElement>) => void;
  /** ←/→ step through `navigation`'s images; a no-op without it. */
  handleKeyDown: (event: KeyboardEvent<HTMLDialogElement>) => void;
}

/**
 * Drives one `AttachmentPreviewModal` instance for `attachment`. The caller conditionally mounts
 * this (one open attachment at a time per `MessageRow`), so mount = open and unmount = close; there
 * is no `open` boolean to track separately.
 * @complexity Time/space: O(1) plus O(n) in the cached file's byte length for the one-time text
 * read on mount (bounded in practice by the upload route's own 20 MB per-attachment cap, and by
 * {@link MAX_TEXT_PREVIEW_CHARS} for what actually renders).
 */
export function useAttachmentPreviewModal(
  { attachment, onClose, navigation }: { attachment: ChatAttachment; onClose: () => void; navigation?: AttachmentPreviewNavigation | undefined },
  { readText = readFileAsText }: { readText?: (required: { file: File }) => Promise<string> } = {},
): AttachmentPreviewController {
  // Lazy state, not `useCallback`: a new ref identity would make React detach and re-attach it,
  // closing and reopening the dialog. The caller mounts a fresh instance per opened attachment (never
  // reuses one instance across two different open attachments), so there is no "attachment changed
  // while still open" transition for the ref to react to. Previous/next is the one exception: it swaps
  // `attachment` under the same open dialog, keeping focus on the button pressed, so the failure flag
  // below is keyed by path rather than a boolean that would carry over to the next image.
  const [dialogRef] = useState(createDialogRef);
  const [failedImagePath, setFailedImagePath] = useState<string | null>(null);
  const imageFailed = failedImagePath === attachment.path;
  const [imageUrl, setImageUrl] = useState<string | undefined>(undefined);
  const [text, setText] = useState<AttachmentTextPreview | undefined>(undefined);
  const [textLoading, setTextLoading] = useState(false);

  const cachedFile = getAttachmentPreviewSource({ path: attachment.path });
  const attemptImage =
    !imageFailed && cachedFile !== undefined && looksLikeImageAttachment({ attachment: attachment }) && canCreateObjectUrl();
  const attemptText = !attemptImage && cachedFile !== undefined && looksLikeTextAttachment(attachment.name);
  const status: AttachmentPreviewStatus = attemptImage ? 'image' : attemptText ? 'text' : 'unsupported';

  // Object URL: created/revoked in an effect (not `useMemo`) so a React 18 Strict Mode double-render
  // can never create two URLs and revoke only one — the cleanup below always pairs with the create
  // that produced the URL currently in state.
  useEffect(() => {
    if (!attemptImage || !cachedFile) {
      setImageUrl(undefined);
      return undefined;
    }
    const url = URL.createObjectURL(cachedFile);
    setImageUrl(url);
    return () => URL.revokeObjectURL(url);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attemptImage, cachedFile]);

  useEffect(() => {
    if (!attemptText || !cachedFile) {
      setText(undefined);
      return undefined;
    }
    let canceled = false;
    setTextLoading(true);
    readText({ file: cachedFile })
      .then((full) => {
        if (canceled) return;
        const truncated = full.length > MAX_TEXT_PREVIEW_CHARS;
        setText({ content: truncated ? full.slice(0, MAX_TEXT_PREVIEW_CHARS) : full, truncated });
      })
      .catch(() => {
        // A file this extension-list called "text-ish" that fails to decode as text falls back to
        // the honest unsupported view via `text` staying `undefined`, rather than showing garbage.
        if (!canceled) setText(undefined);
      })
      .finally(() => {
        if (!canceled) setTextLoading(false);
      });
    return () => {
      canceled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attemptText, cachedFile]);

  function handleNativeCancel(event: SyntheticEvent<HTMLDialogElement>): void {
    // Always prevented, same reasoning as `ConfirmDialog.hooks.tsx`: the effect above is the single
    // source of truth for open/closed, so Escape still closes — it just does so through `onClose`
    // (which unmounts this controller) rather than letting the browser desync from React state.
    event.preventDefault();
    onClose();
  }

  function handleBackdropClick(event: MouseEvent<HTMLDialogElement>): void {
    // A `<dialog>` element's own box is sized to its content; a click landing on the `<dialog>`
    // element itself (rather than a descendant) is a click on the backdrop area outside that box.
    // The handler is bound on the `<dialog>`, so `currentTarget` is that element.
    if (event.target === event.currentTarget) onClose();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDialogElement>): void {
    const step = navigation ? galleryStepForKey({ key: event.key }) : 0;
    if (step === 0 || !navigation) return;
    event.preventDefault();
    if (step < 0) navigation.onPrevious();
    else navigation.onNext();
  }

  return {
    dialogRef,
    status,
    imageUrl,
    onImageError: () => setFailedImagePath(attachment.path),
    textLoading,
    text,
    sizeLabel: formatAttachmentSize({ size: attachment.size }),
    handleNativeCancel,
    handleBackdropClick,
    handleKeyDown,
  };
}

import { useEffect, useId, useLayoutEffect, useRef } from 'react';
import { TabBar } from '@jini-ai/ui/tab-strip';
import { InfoTip } from '@jini-ai/ui/admin-widgets';
import { useChatSettingsView, type ChatPermissionsPort, type ChatSettingsSection } from './ChatSettingsDialog.hooks.js';
import { ChatSettingsSegmented } from './ChatSettingsSegmented.js';

/** One switch row, with optional inline description and help beside the control and label.
 * The help trigger stays outside the label so tapping it never toggles the switch.
 * Earlier (owner) ⓘ tips floated away from their icon, so this row showed visible text only; on 2026-10-18 the owner approved per-option ⓘ help, which InfoTip now anchors to the icon.
 * Later that day radio groups moved to one ⓘ beside their legend; a switch keeps its own, which now
 * sits right after its label like the legend's (owner, 2026-10-21) instead of at the row's far edge. */
function SettingSwitch(required: {
  label: string; checked: boolean; disabled?: boolean | undefined; onChange: (checked: boolean) => void;
  description?: string | undefined; descriptionId: string; className?: string | undefined;
  tooltip?: string | undefined;
}, _optional: Record<string, never> = {}) {
  const inputId = useId();
  return <div className={['jini-chat-settings-row', required.className].filter(Boolean).join(' ')}>
    <input id={inputId} type="checkbox" role="switch" className="jini-checkbox jini-chat-settings-switch"
      checked={required.checked} disabled={required.disabled}
      aria-describedby={[required.description ? required.descriptionId : '', required.tooltip ? `${required.descriptionId}-tooltip` : ''].filter(Boolean).join(' ') || undefined}
      onChange={event => required.onChange(event.currentTarget.checked)} />
    <div className="jini-chat-settings-text">
      <span className="jini-chat-settings-label-row">
        <label htmlFor={inputId} className="jini-chat-settings-label">{required.label}</label>
        {required.tooltip && <InfoTip label={required.tooltip} descriptionId={`${required.descriptionId}-tooltip`} />}
      </span>
      {required.description && <p id={required.descriptionId} className="jini-chat-settings-description">{required.description}</p>}
    </div>
  </div>;
}

/** Advanced chat settings; the host supplies display actions, capabilities and persistence.
 * Native dialog semantics own modal focus containment; closing restores the opener.
 * Header and tabs stay fixed while only the active panel scrolls.
 */
export function ChatSettingsDialog(required: {
  open: boolean; onClose: () => void; displaySections: readonly ChatSettingsSection[];
  permissions: ChatPermissionsPort; t?: (key: string) => string;
}, _optional: Record<string, never> = {}) {
  const vm = useChatSettingsView(required);
  const dialogRef = useRef<HTMLDialogElement>(null), closeRef = useRef<HTMLButtonElement>(null), titleId = useId();
  const openerRef = useRef<Element | null>(null);
  useLayoutEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog || !required.open) return;
    openerRef.current = document.activeElement;
    if (typeof dialog.showModal === 'function') { if (!dialog.open) dialog.showModal(); }
    else dialog.setAttribute('open', '');
    closeRef.current?.focus({ preventScroll: true });
    dialog.scrollTop = 0;
    return () => {
      if (typeof dialog.close === 'function') { if (dialog.open) dialog.close(); }
      else dialog.removeAttribute('open');
    };
  }, [required.open]);
  // Return focus to the opener from a passive cleanup: React's commit-time focus restore runs after
  // layout cleanups and would pull focus straight back to the closing dialog's × button.
  useEffect(() => {
    if (!required.open) return;
    return () => {
      const opener = openerRef.current;
      if (opener instanceof HTMLElement && opener.isConnected) opener.focus({ preventScroll: true });
    };
  }, [required.open]);
  // Its own tip bounds: hosts mount this inside a narrow dock marked `data-jini-tip-bounds`, which
  // pushed the ⓘ bubbles of options outside the dock across the dialog, away from their icon.
  return <dialog ref={dialogRef} aria-labelledby={titleId} aria-modal="true" tabIndex={-1} data-jini-tip-bounds=""
    className="jini-dialog jini-chat-settings-dialog"
    onCancel={event => { event.preventDefault(); required.onClose(); }}
    onClick={event => {
      if (event.target !== event.currentTarget) return;
      const { clientX: x, clientY: y } = event, box = event.currentTarget.getBoundingClientRect();
      if ((x === 0 && y === 0) || x < box.left || x > box.right || y < box.top || y > box.bottom) required.onClose();
    }}>
    <header className="jini-chat-settings-header">
      <h2 id={titleId} className="jini-dialog-title">{vm.t('Chat settings')}</h2>
      <button ref={closeRef} type="button" className="jini-dialog-close jini-chat-settings-close"
        aria-label={vm.t('Close')} onClick={required.onClose}><span aria-hidden="true">×</span></button>
    </header>
    <TabBar tabs={vm.tabs} activeId={vm.tab} onChange={vm.setTab} ariaLabel={vm.t('Chat settings')} />
    <div className="jini-chat-settings-body" role="tabpanel"
      aria-label={vm.tab === 'display' ? vm.t('Display') : vm.t('Agent permissions')}>
      {vm.tab === 'display' ? vm.display.map(section => section.radio
        // One ⓘ for the whole choice, beside the legend (owner, 2026-10-18), not one per option. The
        // fieldset is named by the label span alone, so the tip's text never joins the group's name.
        ? <fieldset key={section.key} className="jini-chat-settings-group" aria-labelledby={section.label ? section.labelId : undefined}
          aria-describedby={[section.hint ? section.hintId : '', section.tooltip ? section.tooltipId : ''].filter(Boolean).join(' ') || undefined}>
          {section.label && <legend className="jini-chat-settings-legend">
            <span id={section.labelId}>{section.label}</span>
            {section.tooltip && <InfoTip label={section.tooltip} descriptionId={section.tooltipId} />}
          </legend>}
          {section.hint && <p id={section.hintId} className="jini-chat-settings-description jini-chat-settings-description--group">{section.hint}</p>}
          <ChatSettingsSegmented name={section.name} items={section.items} />
        </fieldset>
        : <fieldset key={section.key} className="jini-chat-settings-group">
          {section.label && <legend className="jini-chat-settings-legend">{section.label}</legend>}
          {section.items.map(item => <SettingSwitch key={item.key} label={item.label} checked={!!item.checked}
            disabled={item.disabled} onChange={item.change} description={item.hint} descriptionId={item.hintId} tooltip={item.tooltip} />)}
        </fieldset>)
      : <>
        <p className="jini-chat-settings-note">{vm.t('Permission changes apply to the next run.')}</p>
        {vm.permissions.unavailableReason && <p className="jini-chat-settings-note">{vm.t(vm.permissions.unavailableReason)}</p>}
        <SettingSwitch className="jini-chat-settings-row--master" label={vm.master.label} checked={vm.master.checked}
          disabled={vm.master.disabled} onChange={checked => vm.master.onCheckedChange({ checked })}
          description={vm.master.description} descriptionId={vm.master.descriptionId} />
        <div className="jini-chat-settings-capabilities">
          {vm.capabilities.map(item => <SettingSwitch key={item.key} label={item.control.label} checked={item.control.checked}
            disabled={item.control.disabled} onChange={checked => item.control.onCheckedChange({ checked })}
            description={item.description} descriptionId={item.descriptionId} />)}
        </div>
        {vm.permissions.busy && <p role="status" className="jini-chat-settings-note">{vm.t('Saving…')}</p>}
        {vm.permissions.error && <p role="alert" className="jini-chat-settings-error">{vm.permissions.error}</p>}
      </>}
    </div>
  </dialog>;
}

/**
 * @module Composer
 *
 * The dumb, presentational half of the composer: takes a `useComposer()`
 * controller (headless state) plus a few UI-only props and renders the
 * textarea/attachment-tray/send-button chrome. Slot extraction points
 * (`ComposerPlusItem[]`, `leadingAccessories`, `footerAccessories`, the mention popover) are
 * generalized from OD's `ChatComposer.tsx` decomposition
 * (`ComposerPlusMenu`/`LibraryPicker`/`SessionModeToggle`-equivalent) per
 * `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §2/§3 — this component renders
 * the slots a host supplies; it does not itself know what a "library
 * picker" or "session mode" is.
 */
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
  type CSSProperties,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from 'react';
import { RemixIcon } from '@jini-ai/ui';
import { useT } from '../hooks/context.js';
import { useComposerHistoryKeys } from '../hooks/useComposerHistoryKeys.hooks.js';
import { AttachmentTray } from './AttachmentTray.js';
import type { UseComposerResult } from '../hooks/useComposer.js';
import type { ComposerDiscoveryGroup, ComposerDiscoveryItem, ComposerDiscoveryOutcome, ComposerPlusItem, ComposerSlots } from '../slots.js';
import { ComposerDiscoveryMenu, ComposerSlashMenu } from './ComposerDiscovery.js';
import {
  appendComposerDiscovery,
  composerDiscoveryMenuPosition,
  composerSlashMenuPosition,
  filterComposerDiscovery,
  parseComposerSlashQuery,
  replaceComposerSlashTrigger,
  resolveComposerSlashInvocation,
  resolveComposerSlashKeyAction,
} from './composer-discovery.js';

export interface ComposerProps {
  composer: UseComposerResult;
  onSend: () => void;
  disabled?: boolean;
  /** Disables submission without disabling draft editing or attachment controls. */
  sendDisabled?: boolean;
  /** Human-readable submission blocker, exposed on the Send button. */
  sendDisabledReason?: string;
  /** ID of the rendered blocker hint used as the Send button's description. */
  sendDisabledReasonId?: string;
  placeholder?: string;
  slots?: ComposerSlots;
  attachmentPicker?: {
    onFiles: (files: File[]) => void | Promise<void>;
    accept?: string;
    uploading?: boolean;
  };
  /**
   * A run is currently streaming. Swaps the trailing send button for a stop button in the same
   * position — same control an operator already has their attention on, rather than a second,
   * separately placed cancel affordance elsewhere in the pane. Always clickable when true,
   * regardless of `disabled`/`sendDisabled`/`composer.canSubmit`: those all gate *submitting a new
   * draft*, which has nothing to do with whether a caller may cancel the run already in flight.
   * Once the draft is submittable (and neither gate refuses it), Send comes back beside Stop, so a
   * message can go out mid-run without stopping anything.
   */
  running?: boolean;
  /** Cancels the in-flight run. Required when `running` is true; ignored otherwise. */
  onCancel?: () => void;
  /**
   * Cmd/Ctrl+Enter: end the run in flight and send this draft next. Optional — without it the
   * modifier falls through to the ordinary Enter path, so a host that has not opted in keeps
   * exactly its previous behavior.
   */
  onInterrupt?: () => void;
  /**
   * Current working directory, or null/undefined when none is set yet. Paired with
   * `onChangeWorkingDirectory` — see that prop's own doc for why the trigger's presence is gated
   * on the handler rather than on this value.
   */
  workingDirectory?: string | null;
  /**
   * Confirms a directory typed into the working-directory popover. Its presence (not
   * `workingDirectory`'s) is what renders the folder-icon trigger in "popover" mode, next to the
   * attach/discovery button — for a host with no native picker to offer instead. A host that has
   * `ChatPaneWorkingDirectoryAccess` and wants the SAME trigger wired to the native dialog instead
   * passes `onPickWorkingDirectory` (below) in place of this prop, never both. A host relying on
   * `ChatPane`'s richer below-composer `WorkingDirPicker` passes neither, so it gets no second,
   * competing control here. This is the same working-directory value
   * `ChatPane`/`useChatPaneWorkingDirectory` already own — threaded one level deeper into this
   * presentational component, not a parallel concept.
   */
  onChangeWorkingDirectory?: (workingDirectory: string) => void;
  /**
   * Triggers the host's native OS directory dialog directly. Supplied instead of
   * `onChangeWorkingDirectory` (never alongside it) when the host has a
   * `ChatPaneWorkingDirectoryAccess` implementation and asked `ChatPane` to place the
   * working-directory control in the composer rather than below it
   * (`workingDirectoryControlPlacement="composer"`). Renders the exact same folder-icon trigger as
   * the popover mode — byte-identical `jini-composer-attach` styling, hit area, hover, and focus —
   * but clicking it calls this directly instead of opening the in-page text-input popover: there is
   * nothing to type, the native dialog IS the picker.
   */
  onPickWorkingDirectory?: () => void;
}

function reportComposerHostEffectFailure(effectName: string, error: unknown) {
  console.error(`[@jini-ai/chat] Composer ${effectName} host effect failed:`, error);
}

/**
 * Invokes host code synchronously, then observes either its synchronous result or async failure.
 *
 * @param onResolved - Optional, called with the host's resolved (non-thrown/non-rejected) return
 * value — never called after a synchronous throw or an async rejection. Added for
 * `onDiscoverySelect`, whose {@link ComposerDiscoveryOutcome} return value the caller applies to
 * the draft; the two other host effects this function backs (`plusMenuItems.onSelect`,
 * `attachmentPicker.onFiles`) simply omit it, which reproduces their exact prior behavior.
 */
function runComposerHostEffect(
  effectName: string,
  effect: () => unknown,
  onSettled?: () => void,
  onResolved?: (result: unknown) => void,
) {
  let result: unknown;
  try {
    result = effect();
  } catch (error) {
    reportComposerHostEffectFailure(effectName, error);
    onSettled?.();
    return;
  }

  const asynchronous = result !== undefined;
  if (!asynchronous) {
    onResolved?.(result);
    onSettled?.();
  }
  void Promise.resolve(result)
    .then((resolved) => {
      if (asynchronous) onResolved?.(resolved);
    })
    .catch((error: unknown) => {
      reportComposerHostEffectFailure(effectName, error);
    })
    .finally(() => {
      if (asynchronous) onSettled?.();
    });
}

/**
 * Renders the controlled message composer and optional attachment picker.
 *
 * @complexity Time/space: O(n) in rendered attachments and supplied menu items.
 * @overallScore 100/100
 */
export function Composer({
  composer,
  onSend,
  disabled = false,
  sendDisabled = false,
  sendDisabledReason,
  sendDisabledReasonId,
  placeholder,
  slots,
  attachmentPicker,
  running = false,
  onCancel,
  onInterrupt,
  workingDirectory,
  onChangeWorkingDirectory,
  onPickWorkingDirectory,
}: ComposerProps) {
  const t = useT();
  const attachmentInputRef = useRef<HTMLInputElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const discoveryEffectInFlightRef = useRef(false);
  /**
   * Mirrors `composer.draft` for the ONE place it must be read outside a render: inside
   * `notifyDiscovery`'s `onResolved` callback, which can fire after arbitrarily many re-renders
   * (nothing here disables the textarea while a host effect is in flight, so the user is free to
   * keep typing). Reassigned every render rather than via an effect — an effect would lag one
   * render behind the value it needs to be compared against at the exact moment the outcome
   * settles.
   */
  const draftRef = useRef(composer.draft);
  draftRef.current = composer.draft;
  const [discoveryMenuOpen, setDiscoveryMenuOpen] = useState(false);
  const [slashActiveIndex, setSlashActiveIndex] = useState(0);
  const [dismissedSlashDraft, setDismissedSlashDraft] = useState<string | null>(null);
  const [discoveryMenuPosition, setDiscoveryMenuPosition] = useState<CSSProperties>();
  const [slashMenuPosition, setSlashMenuPosition] = useState<CSSProperties>();
  const [workdirOpen, setWorkdirOpen] = useState(false);
  const [workdirDraft, setWorkdirDraft] = useState('');
  const [workdirPosition, setWorkdirPosition] = useState<CSSProperties>();
  const { discoveryGroups = [], leadingAccessories, footerLeadingAccessory, footerAccessories, plusMenuItems } = slots ?? {};
  const hasDiscoveryItems = discoveryGroups.some((group) => group.items.length > 0);
  const slash = slashPalette({ draft: composer.draft, groups: discoveryGroups, dismissedSlashDraft });
  const slashOpen = slash.open;
  const slashActiveOption = Math.min(slashActiveIndex, slash.matches.length - 1);
  const popovers: OpenPopovers = { discoveryMenuOpen, slashOpen, workdirOpen };

  const handleHistoryKey = useComposerHistoryKeys({ composer, textareaRef }, {
    popupOpen: anyPopoverOpen(popovers) || composer.mention.open,
  });

  function restoreComposerFocus() {
    textareaRef.current?.focus();
  }

  /**
   * Neither popover had any way to dismiss on an outside click — Escape worked (each already wires
   * its own keydown), but clicking away left them open with no affordance to close (bug report:
   * "no click-outside, owner is stuck once it opens"). `mousedown`, not `click`, so this settles
   * before the "+" trigger button's own `onToggle` fires on the SAME click — that click's target is
   * inside `.jini-composer-discovery` (the trigger lives there too), so it's correctly treated as
   * "inside" and left for `onToggle` to handle, not fought over by two competing handlers.
   *
   * Scoped by DOM lookup (`closest`/`querySelector`) off `textareaRef`, not new refs threaded
   * through `ComposerDiscovery.tsx`'s props — both popovers already carry stable classes/ids this
   * component doesn't otherwise need direct handles to.
   */
  useEffect(() => {
    if (!anyPopoverOpen(popovers)) return;
    const textarea = textareaRef.current;
    const composerRoot = textarea?.closest('.jini-composer');
    if (!composerRoot) return;

    function handleOutsideMouseDown(event: MouseEvent) {
      const target = event.target as Node | null;
      if (!target) return;
      if (discoveryMenuOpen && isOutside(composerRoot!, '.jini-composer-discovery', target)) setDiscoveryMenuOpen(false);
      if (slashOpen && !textarea!.contains(target) && isOutside(composerRoot!, '#jini-composer-slash-menu', target)) setDismissedSlashDraft(composer.draft);
      if (workdirOpen && isOutside(composerRoot!, '.jini-composer-workdir', target)) setWorkdirOpen(false);
    }

    document.addEventListener('mousedown', handleOutsideMouseDown);
    return () => document.removeEventListener('mousedown', handleOutsideMouseDown);
  }, [discoveryMenuOpen, slashOpen, workdirOpen, composer.draft]);

  /**
   * Anchors the "+" menu and slash palette to `.jini-composer`'s live on-screen rect via
   * `position: fixed` (see `composerDiscoveryMenuPosition`/`composerSlashMenuPosition`'s own doc
   * in `composer-discovery.ts` for the ancestor-clipping bug this fixes). `useLayoutEffect`, not
   * `useEffect`, so the measured position lands before the browser paints the just-opened popover
   * — otherwise the very first frame would flash at the CSS default (`position: absolute`)
   * position before snapping to the fixed one. Recomputed on scroll/resize while either popover is
   * open, matching `useAgentRuntimePicker.hooks.ts`'s identical popover-tracking idiom: the
   * composer's on-screen position can change under an open popover without it ever unmounting.
   */
  useLayoutEffect(() => {
    if (!anyPopoverOpen(popovers)) return undefined;
    const composerRoot = textareaRef.current?.closest('.jini-composer');
    if (!composerRoot) return undefined;

    function update() {
      const rect = composerRoot!.getBoundingClientRect();
      if (discoveryMenuOpen) setDiscoveryMenuPosition(composerDiscoveryMenuPosition({ composerRect: rect }));
      if (slashOpen) setSlashMenuPosition(composerSlashMenuPosition({ composerRect: rect }));
      // Shares the discovery menu's own anchor math (same left inset off `.jini-composer`) rather
      // than measuring the working-dir button's own rect — one less measurement to keep in sync,
      // and the two popovers already never open at once (each is gated on its own trigger).
      if (workdirOpen) setWorkdirPosition(composerDiscoveryMenuPosition({ composerRect: rect }));
    }

    update();
    window.addEventListener('scroll', update, true);
    window.addEventListener('resize', update);
    return () => {
      window.removeEventListener('scroll', update, true);
      window.removeEventListener('resize', update);
    };
  }, [discoveryMenuOpen, slashOpen, workdirOpen]);

  /**
   * `expectedDraft` is the draft as the user last saw it at the moment of selection — what the
   * host's effect was computed against. `argument` is passed only for a resolved `'invoke'` on a
   * `command`-bearing item (see `resolveComposerSlashInvocation`); omitted entirely for a plain
   * macro item, matching `ComposerDiscoverySelection.argument`'s own "absent means no command
   * grammar" contract.
   *
   * A `ComposerDiscoveryOutcome` the host returns replaces the draft — this is how a command whose
   * effect is computed asynchronously (e.g. composing agent-directed instruction text) gets to
   * write its result back, since nothing here can guess it in advance the way a plain item's own
   * `insertText` can. But nothing disables the textarea while that effect is in flight, so the
   * live draft (`draftRef.current`) may have moved on by the time it resolves. The outcome is
   * applied only if the live draft still matches `expectedDraft` exactly; otherwise it is
   * DISCARDED — silently overwriting keystrokes the user typed in the meantime would be worse than
   * dropping a result they can reselect.
   */
  function notifyDiscovery(
    item: ComposerDiscoveryItem,
    source: 'plus' | 'slash',
    expectedDraft: string,
    argument?: string | null,
  ) {
    const onDiscoverySelect = slots?.onDiscoverySelect;
    if (!onDiscoverySelect || discoveryEffectInFlightRef.current) return;
    discoveryEffectInFlightRef.current = true;
    runComposerHostEffect(
      'onDiscoverySelect',
      () => onDiscoverySelect({ item, source, ...(argument !== undefined ? { argument } : {}) }),
      () => {
        discoveryEffectInFlightRef.current = false;
      },
      (outcome) => {
        if (!outcome || typeof outcome !== 'object') return;
        const draft = (outcome as ComposerDiscoveryOutcome).draft;
        if (draft === undefined) return;
        if (draftRef.current !== expectedDraft) return;
        composer.setDraft(draft);
      },
    );
  }

  function selectSlashItem(item: ComposerDiscoveryItem) {
    const resolution = resolveComposerSlashInvocation({ draft: composer.draft, item });
    if (!resolution) return;

    if (resolution.type === 'complete') {
      // The command word is ambiguous or its argument is still missing — finish the trigger and
      // keep the palette open for further typing. No host effect fires: nothing was invoked yet.
      composer.setDraft(resolution.draft);
      setDismissedSlashDraft(null);
      restoreComposerFocus();
      return;
    }

    let expectedDraft = composer.draft;
    if (!item.command) {
      expectedDraft = replaceComposerSlashTrigger({ draft: composer.draft, insertText: item.insertText ?? item.label });
      composer.setDraft(expectedDraft);
    }
    setDismissedSlashDraft(null);
    notifyDiscovery(item, 'slash', expectedDraft, resolution.argument);
    restoreComposerFocus();
  }

  function selectPlusItem(item: ComposerDiscoveryItem) {
    const expectedDraft = item.insertText ? appendComposerDiscovery({ draft: composer.draft, insertText: item.insertText }) : composer.draft;
    if (item.insertText) composer.setDraft(expectedDraft);
    setDiscoveryMenuOpen(false);
    notifyDiscovery(item, 'plus', expectedDraft);
    restoreComposerFocus();
  }

  /** Opens the working-directory popover, seeding its draft from the live value so a reopen never
   *  shows a stale edit from a previously-dismissed attempt. */
  function toggleWorkdir() {
    if (!workdirOpen) setWorkdirDraft(workingDirectory ?? '');
    setWorkdirOpen((open) => !open);
  }

  /** Confirms the popover's draft. Blank input is treated as "no change" (closes without calling
   *  the host) rather than clearing the directory — this lightweight control has no clear
   *  affordance of its own; `onChangeWorkingDirectory`'s own doc points to the native picker
   *  (`ChatPaneWorkingDirectoryAccess`) that does support clearing. */
  function confirmWorkdir() {
    const trimmed = workdirDraft.trim();
    if (trimmed) onChangeWorkingDirectory?.(trimmed);
    setWorkdirOpen(false);
  }

  /** Palette navigation wins over history and Enter while the slash palette is open; true when it consumed the key. */
  function handleSlashKey(event: KeyboardEvent<HTMLTextAreaElement>): boolean {
    if (!slashOpen) return false;
    const action = resolveComposerSlashKeyAction({ key: event.key, shiftKey: event.shiftKey });
    if (action.type === 'none') return false;
    event.preventDefault();
    if (action.type === 'move') {
      setSlashActiveIndex((current) => (current + action.offset + slash.matches.length) % slash.matches.length);
    } else if (action.type === 'select') {
      selectSlashItem(slash.matches[slashActiveOption]!.item);
    } else {
      setDismissedSlashDraft(composer.draft);
    }
    return true;
  }

  function submitFromEnter(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (disabled || !composer.canSubmit) return;
    // Cmd/Ctrl+Enter ends the current run and sends this next; plain Enter queues behind it.
    // `sendDisabled` is deliberately NOT consulted on the interrupt path — while a run streams it
    // is set precisely BECAUSE of that run, which is the one case this modifier exists to act on.
    if ((event.metaKey || event.ctrlKey) && onInterrupt) {
      onInterrupt();
      return;
    }
    if (!sendDisabled) onSend();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.nativeEvent.isComposing) return;
    if (handleSlashKey(event)) return;
    if (handleHistoryKey(event)) return;
    if (event.key !== 'Enter' || event.shiftKey) return;
    event.preventDefault();
    submitFromEnter(event);
  }

  function handleAttachmentChange(event: ChangeEvent<HTMLInputElement>) {
    const files = Array.from(event.target.files ?? []);
    event.target.value = '';
    if (files.length > 0 && attachmentPicker) {
      runComposerHostEffect('attachmentPicker.onFiles', () => attachmentPicker.onFiles(files));
    }
  }

  /**
   * A screenshot or a Finder-copied video pasted into the textarea previously vanished with no
   * feedback: the browser's default paste has nothing to do with a `File` on the clipboard (it only
   * inserts `text/plain`, which a file-only clipboard entry never carries), so the keystroke was a
   * silent no-op — no chip, no `/api/attachments` call, nothing. This is the paste-side counterpart
   * to `handleAttachmentChange` (the file-input path) and `useChatPaneFileDrop` (the drag-and-drop
   * path); all three now reach `attachmentPicker.onFiles` the same way.
   *
   * `preventDefault` only when `files.length > 0` — an ordinary text paste (the overwhelmingly
   * common case) is left to the browser's own default handling untouched.
   */
  function handleAttachmentPaste(event: ClipboardEvent<HTMLTextAreaElement>) {
    if (!attachmentPicker) return;
    const files = Array.from(event.clipboardData?.files ?? []);
    if (files.length === 0) return;
    event.preventDefault();
    runComposerHostEffect('attachmentPicker.onFiles', () => attachmentPicker.onFiles(files));
  }

  return (
    <div className="jini-composer">
      <AccessorySlot className="jini-composer-leading">{leadingAccessories}</AccessorySlot>
      <AttachmentTray attachments={composer.attachments} onRemove={composer.removeAttachment} />
      <textarea
        ref={textareaRef}
        className="jini-composer-input"
        value={composer.draft}
        placeholder={placeholder ?? t('Send a message…')}
        disabled={disabled}
        onChange={(e) => {
          composer.setDraft(e.target.value);
          setSlashActiveIndex(0);
          setDismissedSlashDraft(null);
        }}
        onKeyDown={handleKeyDown}
        // Draft persistence is debounced (see `DRAFT_PERSIST_DEBOUNCE_MS`); leaving the field is a
        // natural point to make it durable now.
        onBlur={() => composer.flushDraft?.()}
        onPaste={handleAttachmentPaste}
        {...slashTextareaAria(slashOpen, slashActiveOption)}
        rows={3}
      />
      {slashOpen ? (
        <ComposerSlashMenu
          matches={slash.matches}
          activeIndex={slashActiveOption}
          onSelect={selectSlashItem}
          showFilterHint={slash.showFilterHint}
          style={slashMenuPosition}
          t={t}
        />
      ) : null}
      <div className="jini-composer-footer">
        <ComposerAttachButton attachmentPicker={attachmentPicker} hidden={hasDiscoveryItems} disabled={disabled} inputRef={attachmentInputRef} onChange={handleAttachmentChange} t={t} />
        <ComposerDiscoveryMenu
          groups={discoveryGroups}
          open={discoveryMenuOpen}
          disabled={disabled}
          {...(attachmentPicker ? { attachmentPicker } : {})}
          attachmentInputRef={attachmentInputRef}
          onToggle={() => setDiscoveryMenuOpen((open) => !open)}
          onClose={() => setDiscoveryMenuOpen(false)}
          onSelect={selectPlusItem}
          onAttachmentChange={handleAttachmentChange}
          style={discoveryMenuPosition}
          t={t}
        />
        <AccessorySlot className="jini-composer-footer-leading">{footerLeadingAccessory}</AccessorySlot>
        <ComposerWorkdirControl
          workingDirectory={workingDirectory}
          onChangeWorkingDirectory={onChangeWorkingDirectory}
          onPickWorkingDirectory={onPickWorkingDirectory}
          disabled={disabled}
          open={workdirOpen}
          draft={workdirDraft}
          position={workdirPosition}
          onToggle={toggleWorkdir}
          onDraftChange={setWorkdirDraft}
          onConfirm={confirmWorkdir}
          onClose={() => setWorkdirOpen(false)}
          t={t}
        />
        <AccessorySlot className="jini-composer-footer-accessories">{footerAccessories}</AccessorySlot>
        <ComposerPlusMenu items={plusMenuItems} t={t} />
        <ComposerSendGroup
          running={running}
          disabled={disabled}
          sendDisabled={sendDisabled}
          canSubmit={composer.canSubmit}
          onSend={onSend}
          onCancel={onCancel}
          sendDisabledReason={sendDisabledReason}
          sendDisabledReasonId={sendDisabledReasonId}
          t={t}
        />
      </div>
    </div>
  );
}

type Translate = ReturnType<typeof useT>;

interface OpenPopovers {
  discoveryMenuOpen: boolean;
  slashOpen: boolean;
  workdirOpen: boolean;
}

function anyPopoverOpen({ discoveryMenuOpen, slashOpen, workdirOpen }: OpenPopovers): boolean {
  return discoveryMenuOpen || slashOpen || workdirOpen;
}

/** A missing popover element counts as outside, so a stale open flag still closes. */
function isOutside(composerRoot: Element, selector: string, target: Node): boolean {
  return !composerRoot.querySelector(selector)?.contains(target);
}

/** Slash palette state derived from the live draft. */
function slashPalette({ draft, groups, dismissedSlashDraft }: { draft: string; groups: readonly ComposerDiscoveryGroup[]; dismissedSlashDraft: string | null }) {
  const query = parseComposerSlashQuery({ draft });
  const matches = query === null ? [] : filterComposerDiscovery({ groups, query });
  return {
    matches,
    open: matches.length > 0 && dismissedSlashDraft !== draft,
    /**
     * A bare "/" intentionally matches every item (`matchesFuzzyCommand`'s own doc) so the palette
     * doubles as a browse-everything view — but with nothing typed yet, nothing on screen tells a
     * first-time user that continuing to type narrows it, and a fuzzy substring match against full
     * descriptions stays broad for the first character or two regardless (owner-reported "it doesn't
     * narrow" — narrowing DOES fire on every keystroke, this is the one state where there's no visual
     * cue that it will). Shown only here, not once the user has started typing a real query — at that
     * point the shrinking list is its own feedback.
     */
    showFilterHint: query !== null && query.command === '' && query.argument === null,
  };
}

function slashTextareaAria(slashOpen: boolean, activeOption: number) {
  if (!slashOpen) return { 'aria-controls': undefined, 'aria-expanded': false, 'aria-activedescendant': undefined };
  return { 'aria-controls': 'jini-composer-slash-menu', 'aria-expanded': true, 'aria-activedescendant': `jini-composer-slash-option-${activeOption}` };
}

function AccessorySlot({ className, children }: { className: string; children: ReactNode }) {
  return children ? <div className={className}>{children}</div> : null;
}

/** The plain paperclip, shown only when there is no "+" discovery menu to carry attaching instead. */
function ComposerAttachButton({ attachmentPicker, hidden, disabled, inputRef, onChange, t }: {
  attachmentPicker: ComposerProps['attachmentPicker'];
  hidden: boolean;
  disabled: boolean;
  inputRef: RefObject<HTMLInputElement | null>;
  onChange: (event: ChangeEvent<HTMLInputElement>) => void;
  t: Translate;
}) {
  if (!attachmentPicker || hidden) return null;
  const uploading = attachmentPicker.uploading;
  const label = t(uploading ? 'Attaching files…' : 'Attach files');
  return (
    <div className="jini-composer-attachment-picker">
      <input
        ref={inputRef}
        className="jini-composer-file-input"
        data-testid="composer-attachment-input"
        type="file"
        multiple
        aria-label={t('Attach files')}
        accept={attachmentPicker.accept}
        disabled={disabled || uploading}
        onChange={onChange}
      />
      <button
        type="button"
        className="jini-composer-attach"
        disabled={disabled || uploading}
        onClick={() => inputRef.current?.click()}
        title={label}
        aria-label={label}
      >
        <RemixIcon
          name={uploading ? 'refresh-line' : 'add-line'}
          size={20}
          {...(uploading ? { className: 'jini-composer-spinner' } : {})}
        />
      </button>
    </div>
  );
}

function ComposerWorkdirControl({ workingDirectory, onChangeWorkingDirectory, onPickWorkingDirectory, disabled, open, draft, position, onToggle, onDraftChange, onConfirm, onClose, t }: {
  workingDirectory: string | null | undefined;
  onChangeWorkingDirectory: ComposerProps['onChangeWorkingDirectory'];
  onPickWorkingDirectory: ComposerProps['onPickWorkingDirectory'];
  disabled: boolean;
  open: boolean;
  draft: string;
  position: CSSProperties | undefined;
  onToggle: () => void;
  onDraftChange: (draft: string) => void;
  onConfirm: () => void;
  onClose: () => void;
  t: Translate;
}) {
  if (!onChangeWorkingDirectory && !onPickWorkingDirectory) return null;
  return (
    <div className="jini-composer-workdir" data-testid="composer-workdir">
      <button
        type="button"
        className="jini-composer-attach"
        data-testid="composer-workdir-trigger"
        disabled={disabled}
        onClick={onPickWorkingDirectory ? () => onPickWorkingDirectory() : onToggle}
        {...(onPickWorkingDirectory ? {} : { 'aria-haspopup': 'dialog' as const, 'aria-expanded': open })}
        title={workingDirectory ?? t('Set working directory')}
        aria-label={
          workingDirectory
            ? t('Working directory: {dir}', { dir: workingDirectory })
            : t('Set working directory')
        }
      >
        <RemixIcon name="folder-line" size={20} />
      </button>
      {!onPickWorkingDirectory && open ? (
        <div
          className="jini-composer-workdir-panel"
          data-testid="composer-workdir-panel"
          role="dialog"
          aria-label={t('Working directory')}
          style={position}
        >
          <input
            type="text"
            className="jini-composer-workdir-input"
            data-testid="composer-workdir-input"
            value={draft}
            onChange={(e) => onDraftChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                onConfirm();
              } else if (e.key === 'Escape') {
                e.preventDefault();
                onClose();
              }
            }}
            placeholder={t('Working directory path')}
            aria-label={t('Working directory path')}
            autoFocus
          />
          <button
            type="button"
            className="jini-composer-workdir-confirm"
            data-testid="composer-workdir-confirm"
            onClick={onConfirm}
          >
            {t('Set')}
          </button>
        </div>
      ) : null}
    </div>
  );
}

function ComposerPlusMenu({ items, t }: { items: readonly ComposerPlusItem[] | undefined; t: Translate }) {
  if (!items || items.length === 0) return null;
  return (
    <div className="jini-composer-plus-menu">
      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          className="jini-composer-plus-item"
          onClick={() => runComposerHostEffect('plusMenuItems.onSelect', () => item.onSelect())}
          title={t(item.label)}
        >
          {item.icon ?? null}
          <span>{t(item.label)}</span>
        </button>
      ))}
    </div>
  );
}

function ComposerSendGroup({ running, disabled, sendDisabled, canSubmit, onSend, onCancel, sendDisabledReason, sendDisabledReasonId, t }: {
  running: boolean;
  disabled: boolean;
  sendDisabled: boolean;
  canSubmit: boolean;
  onSend: () => void;
  onCancel: (() => void) | undefined;
  sendDisabledReason: string | undefined;
  sendDisabledReasonId: string | undefined;
  t: Translate;
}) {
  const canSend = !disabled && !sendDisabled && canSubmit;
  return (
    // While a run streams, Send sits beside Stop once there is something to send: a message
    // sent mid-run goes to the running agent (or next, if it cannot take it now). One group so
    // the footer's space-between keeps the two together at the trailing edge.
    <span className="jini-composer-send-group">
      {!running || canSend ? (
        <button type="button" className="jini-composer-send" disabled={!canSend} onClick={onSend} title={sendDisabledReason ?? t('Send')} aria-label={t('Send')} aria-describedby={sendDisabledReasonId}>
          <RemixIcon name="send-plane-2-line" size={16} />
        </button>
      ) : null}
      {running ? (
        <button type="button" className="jini-composer-send jini-composer-send--stop" onClick={onCancel} title={t('Stop run')} aria-label={t('Stop run')}>
          <RemixIcon name="stop-fill" size={14} />
        </button>
      ) : null}
    </span>
  );
}

/**
 * @module ConversationList
 *
 * The conversation switcher: new / select / delete / search / inline rename. Drop it
 * into `ChatPane`'s `leadingAccessory` slot — it needs no changes to `ChatPane` itself.
 *
 * Storage-agnostic by construction. It takes data and callbacks and owns nothing durable, so a
 * host backs it with `@jini-ai/sqlite-chat`'s `ChatHistoryStore`, an HTTP endpoint, or an in-memory
 * array without this file knowing the difference.
 *
 * Search is a **client-side filter by default**, and delegates to `onSearch` when a host provides
 * one. That default is not laziness: a host with no server search still gets a working filter,
 * and one whose list grows past a page swaps in a server query by passing a prop. The rule for
 * when to swap is concrete — a client filter over a *paginated* list silently searches only the
 * loaded page, so the moment a host paginates, it must provide `onSearch`.
 *
 * Rename has an explicit keyboard-accessible action as well as the legacy double-click shortcut.
 *
 * Unstyled semantic markup with `jini-conv-*` class names, matching every other component in this
 * package — a host supplies the CSS.
 */
import { useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { useT } from '../hooks/context.js';
import { Icon } from './Icon.js';
import { useConversationListTitles } from './ConversationList.hooks.js';
import { conversationTriggerAttributes } from './ConversationList.rules.js';
import { ConversationTitleEditor } from './ConversationTitleEditor.js';

/**
 * How long a click waits to see whether it is really the first half of a double-click.
 *
 * Covers the common OS double-click window, including deliberate clicks 300ms apart.
 */
const DOUBLE_CLICK_GRACE_MS = 500;

/** The minimum a row needs to render. Mirrors `@jini-ai/chat/core`'s `ChatConversation`. */
export interface ConversationListItem {
  id: string;
  title: string | null;
  messageCount?: number;
  updatedAt?: number;
}

export interface ConversationListProps {
  conversations: ConversationListItem[];
  activeConversationId: string | null;
  onSelect: (id: string) => void;
  onCreate: () => void | Promise<void>;
  onDelete: (id: string) => void | Promise<void>;
  onRename: (id: string, title: string) => void | Promise<void>;
  /**
   * Server-backed search. Omit for the built-in client filter.
   *
   * **Required once the list is paginated** — see this module's header.
   */
  onSearch?: (query: string) => Promise<ConversationListItem[]>;
  /**
   * Confirm before deleting. Defaults to `window.confirm`; pass a custom dialog, or
   * `() => Promise.resolve(true)` to delete without asking.
   */
  confirmDelete?: (item: ConversationListItem) => boolean | Promise<boolean>;
  /** Disables the "New" action — e.g. while the current conversation is still empty. */
  createDisabled?: boolean;
  emptyState?: React.ReactNode;
  /** Replaces the trigger's accessible name (default "Conversations — {active title}"). */
  triggerLabel?: string;
  /**
   * `false` drops the trigger's native `title` tooltip, for a host that draws its own tooltip over
   * the icon (the browser's dark tip would otherwise show on top of it). Defaults to true.
   */
  nativeTitle?: boolean;
}

function reportConversationListHostEffectFailure(effectName: string, error: unknown) {
  console.error(`[@jini-ai/chat] ConversationList ${effectName} host effect failed:`, error);
}

/** Invokes a host callback and reports a synchronous throw or async rejection without leaving it unhandled. */
function runConversationListHostEffect(effectName: string, effect: () => void | Promise<unknown>) {
  let result: void | Promise<unknown>;
  try {
    result = effect();
  } catch (error) {
    reportConversationListHostEffectFailure(effectName, error);
    return;
  }
  void Promise.resolve(result).catch((error: unknown) => {
    reportConversationListHostEffectFailure(effectName, error);
  });
}

function relativeTime(updatedAt: number | undefined, now: number): string {
  if (updatedAt === undefined) return '';
  const seconds = Math.max(0, Math.round((now - updatedAt) / 1000));
  if (seconds < 60) return 'just now';
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

export function ConversationList({
  conversations: savedConversations,
  activeConversationId,
  onSelect,
  onCreate,
  onDelete,
  onRename,
  onSearch,
  confirmDelete,
  createDisabled = false,
  emptyState,
  triggerLabel,
  nativeTitle = true,
}: ConversationListProps) {
  const t = useT();
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [savedServerResults, setServerResults] = useState<ConversationListItem[] | null>(null);
  const { conversations, serverResults, rawTitles } = useConversationListTitles({ conversations: savedConversations, serverResults: savedServerResults });
  const [editingId, setEditingId] = useState<string | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const deferredQuery = useDeferredValue(query);
  /**
   * Pending single-click selection, held so a double-click can cancel it.
   *
   * A double-click always delivers its first `click` too, so selecting immediately would close
   * the menu out from under the rename editor — the row would be selected and the switcher shut
   * before `dblclick` ever arrived. Open Design's original switcher has exactly this bug. The
   * delay is only perceptible if you are looking for it, and it costs nothing but a timer.
   */
  const pendingSelectRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cancelPendingSelect = useCallback(() => {
    if (pendingSelectRef.current === null) return;
    clearTimeout(pendingSelectRef.current);
    pendingSelectRef.current = null;
  }, []);

  // A timer that fires after unmount would call `setOpen` on a dead component.
  useEffect(() => cancelPendingSelect, [cancelPendingSelect]);

  /*
   * Closing the switcher also abandons a click that has not yet resolved into a selection.
   *
   * The grace window exists so a double-click can become a rename rather than a selection, which
   * means a single click stays pending for the grace window. Press Escape (or click outside) inside it
   * and the menu closes while the timer survives, so the row is selected anyway — and if the pending
   * click was on Delete, it selects an id that no longer exists.
   */
  useEffect(() => {
    if (!open) cancelPendingSelect();
  }, [open, cancelPendingSelect]);

  // Close on outside click / Escape. Registered only while open so a closed switcher costs
  // nothing on every document event.
  useEffect(() => {
    if (!open) return;
    // The root div is committed before any effect runs, so it is never null here. Capturing it
    // (rather than reading the ref per event) keeps a late event during unmount, after React has
    // detached the ref but before this cleanup runs, measured against the real node.
    const root = rootRef.current as HTMLDivElement;
    function onPointerDown(event: MouseEvent) {
      if (!root.contains(event.target as Node)) setOpen(false);
    }
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') setOpen(false);
    }
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open]);

  // A stale query is worse than no query: reopening to yesterday's filter looks like data loss.
  useEffect(() => {
    if (open) return;
    setQuery('');
    setServerResults(null);
    setEditingId(null);
  }, [open]);

  useEffect(() => {
    if (!onSearch) return;
    if (!deferredQuery) {
      setServerResults(null);
      return;
    }
    // `cancelled` guards the classic out-of-order response: a slow query for "a" resolving after
    // a fast one for "abc" would otherwise overwrite the newer, correct results.
    let cancelled = false;
    // A search failure just leaves the prior (possibly stale) results in place rather than
    // wiping the list — degraded, not wrong, so reporting the rejection is all that's warranted.
    runConversationListHostEffect('onSearch', () =>
      onSearch(deferredQuery).then((results) => {
        if (!cancelled) setServerResults(results);
      }),
    );
    return () => {
      cancelled = true;
    };
  }, [onSearch, deferredQuery]);

  const visible = useMemo(() => {
    if (onSearch) return serverResults ?? conversations;
    const needle = deferredQuery.trim().toLocaleLowerCase();
    if (!needle) return conversations;
    return conversations.filter((c) =>
      (c.title ?? t('Untitled')).toLocaleLowerCase().includes(needle),
    );
  }, [onSearch, serverResults, conversations, deferredQuery, t]);

  // One timestamp for the whole render so every row's "5m ago" is computed against the same
  // instant — otherwise rows drawn either side of a second boundary disagree.
  const now = Date.now();

  const commitRename = useCallback(
    (id: string, next: string) => {
      setEditingId(null);
      // No optimistic title update happens here — the row keeps rendering `item.title` from
      // props until the host's own state updates, so a rejection cannot leave the UI showing a
      // title the server didn't accept. Reporting the failure is what closes the remaining gap.
      runConversationListHostEffect('onRename', () => onRename(id, next));
    },
    [onRename],
  );

  const startRename = (id: string) => {
    cancelPendingSelect();
    setEditingId(id);
  };

  const requestDelete = useCallback(
    (item: ConversationListItem) => {
      const confirmer =
        confirmDelete ??
        // Only ever called from a click handler, so a browser `window` always exists here.
        ((c: ConversationListItem) =>
          window.confirm(t('Delete "{title}"? This cannot be undone.').replace('{title}', c.title ?? t('Untitled'))));
      // No optimistic removal — the row stays in `conversations` until the host's own state
      // drops it — so a rejected confirmer or `onDelete` cannot leave a deleted-looking row
      // behind; it only means the item silently never disappears. `onDelete` is the effect name
      // reported here since a rejecting confirmer is, from the host's perspective, also "the
      // delete didn't happen."
      runConversationListHostEffect('onDelete', async () => {
        if (await confirmer(item)) await onDelete(item.id);
      });
    },
    [confirmDelete, onDelete, t],
  );

  const active = conversations.find((c) => c.id === activeConversationId) ?? null;

  return (
    <div className="jini-conv" ref={rootRef}>
      {/* Icon-only, and the label lives on the panel instead. An earlier version put the active
          conversation's title in the trigger AND a "Conversations" heading in the panel, which
          read as the same word twice and pushed the pane header out of alignment. */}
      <button
        type="button"
        className={`jini-conv-trigger${open ? ' jini-conv-trigger-open' : ''}`}
        aria-haspopup="menu"
        aria-expanded={open}
        {...conversationTriggerAttributes({ activeTitle: active?.title, t }, { label: triggerLabel, nativeTitle })}
        data-testid="conversation-trigger"
        onClick={() => setOpen((v) => !v)}
      >
        <Icon name="comment" size={16} />
      </button>

      {open ? (
        <div className="jini-conv-menu" role="menu" data-testid="conversation-menu">
          <div className="jini-conv-head">
            <span className="jini-conv-heading">
              {t('Conversations')}
              {/* A separate element, not string concatenation: as one text node it rendered as
                  "Conversations0" with nothing to space or style the number against. */}
              <span className="jini-conv-count" data-testid="conversation-count">
                {conversations.length}
              </span>
            </span>
            <button
              type="button"
              className="jini-conv-new"
              disabled={createDisabled}
              data-testid="conversation-new"
              // `disabled` alone guards this: a disabled button never dispatches a click.
              onClick={() => {
                // No optimistic row is inserted — the list still comes straight from props — so a
                // rejection here cannot leave a phantom conversation on screen; it only means the
                // switcher closed without one actually being created. Reporting the failure closes
                // the remaining gap between "switcher closed" and "the host actually knows".
                runConversationListHostEffect('onCreate', () => onCreate());
                setOpen(false);
              }}
            >
              <Icon name="plus" size={12} />
              <span>{t('New')}</span>
            </button>
          </div>

          <label className="jini-conv-search">
            <Icon name="search" size={13} />
            <input
              type="search"
              value={query}
              placeholder={t('Search conversations')}
              data-testid="conversation-search"
              onChange={(event) => setQuery(event.currentTarget.value)}
            />
          </label>

          <div className="jini-conv-list" data-testid="conversation-list">
            {conversations.length === 0 ? (
              <div className="jini-conv-empty">{emptyState ?? t('No conversations yet')}</div>
            ) : visible.length === 0 ? (
              <div className="jini-conv-empty">{t('No conversations match')}</div>
            ) : (
              visible.map((item) => (
                <div
                  key={item.id}
                  className={`jini-conv-item${item.id === activeConversationId ? ' jini-conv-item-active' : ''}`}
                  data-testid={`conversation-item-${item.id}`}
                >
                  {editingId === item.id ? (
                    <ConversationTitleEditor
                      title={rawTitles.get(item.id) ?? null}
                      data-testid={`conversation-rename-${item.id}`}
                      onCommit={(next) => commitRename(item.id, next)}
                      onCancel={() => setEditingId(null)}
                    />
                  ) : (
                    <button
                      type="button"
                      className="jini-conv-item-select"
                      data-testid={`conversation-select-${item.id}`}
                      title={t('Double-click to rename')}
                      onClick={() => {
                        cancelPendingSelect();
                        pendingSelectRef.current = setTimeout(() => {
                          pendingSelectRef.current = null;
                          onSelect(item.id);
                          setOpen(false);
                        }, DOUBLE_CLICK_GRACE_MS);
                      }}
                      onDoubleClick={() => startRename(item.id)}
                    >
                      <span className="jini-conv-item-title">{item.title ?? t('Untitled')}</span>
                      <span className="jini-conv-item-meta">
                        {item.messageCount === undefined ? '' : `${item.messageCount} msg · `}
                        {relativeTime(item.updatedAt, now)}
                      </span>
                    </button>
                  )}
                  {editingId !== item.id ? <button
                    type="button"
                    className="jini-conv-item-rename"
                    aria-label={t('Rename chat')}
                    data-testid={`conversation-rename-button-${item.id}`}
                    onClick={() => startRename(item.id)}
                  >
                    <Icon name="pencil" size={12} />
                  </button> : null}
                  <button
                    type="button"
                    className="jini-conv-item-delete"
                    aria-label={t('Delete conversation')}
                    data-testid={`conversation-delete-${item.id}`}
                    onClick={(event) => {
                      event.stopPropagation();
                      requestDelete(item);
                    }}
                  >
                    <Icon name="close" size={12} />
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      ) : null}
    </div>
  );
}

/**
 * @module Markdown
 *
 * A pocket-sized markdown renderer for assistant chat message text. No
 * `dangerouslySetInnerHTML` — output is a tree of typed React elements, so
 * untrusted text can't smuggle markup through.
 *
 * DELIBERATE SUBSET, not a full port: OD's `runtime/markdown.tsx` (734
 * lines) additionally handles a code-comment directive syntax — reasonable
 * follow-up work, left out here since no host has a concrete requirement
 * for it yet. Fenced code blocks DO now carry a per-block copy button
 * (`CopyCodeButton` below), reusing `useCopyToClipboard`
 * (`../hooks/useCopyToClipboard.js`) — the same hook `MessageRow.tsx`'s
 * per-message copy button is built on, so both share one secure-context/
 * fallback implementation. The two stay separate *components*, not one
 * shared button: a per-message copy sits in a `.jini-message-actions` row
 * alongside future branch/feedback siblings, while a per-block copy sits
 * on the code block itself and copies only that block's own source, not
 * the whole message — different placement and different copy scope, so a
 * shared component would mean threading scope-specific behavior through a
 * control neither call site actually wants generic. This renderer now
 * also covers GFM pipe tables — ported from OD's `runtime/markdown.tsx`
 * (`splitTableCells`/`parseTableAlignRow`/table block parsing and
 * rendering), including a wide-table pop-out (`TableBlock` below): a table
 * whose rendered width exceeds its own box gets an "Expand table" affordance
 * that reopens it full-size in a native `<dialog>`, mirroring the same
 * overflow-detection + `<dialog>` pattern one existing downstream admin host
 * already built for its own "Show in modal" affordance on other overflowing
 * content (a matched `useOverflowDetection` hook + native-`<dialog>` modal
 * pair) — kept as a *self-contained* copy here rather than an import, since
 * `@jini-ai/chat` cannot depend on a downstream host package, and every
 * other Jini host gets the same affordance this way. Everything else this
 * renderer covers:
 * ATX headings (`#`…`###`), fenced code blocks, ordered/unordered lists,
 * blockquotes, a horizontal rule, paragraphs, and inline `` `code` ``/
 * `**bold**`/`*italic*`/`[label](url)` links/bare autolinks — including inside table cells, via
 * the same `renderInline` pass every other block uses. TODO(follow-up): port
 * the code-comment directive syntax once a host needs it.
 */
import { Fragment, useEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import { useCopyToClipboard } from '../hooks/useCopyToClipboard.js';
import { useT } from '../hooks/context.js';
import { Icon } from './Icon.js';

export interface MarkdownProps {
  children: string;
}

type TableAlign = 'left' | 'right' | 'center' | null;

type Block =
  | { kind: 'p'; text: string }
  | { kind: 'h'; level: 1 | 2 | 3; text: string }
  | { kind: 'ul'; items: string[] }
  | { kind: 'ol'; start: number; items: string[] }
  | { kind: 'bq'; text: string }
  | { kind: 'code'; lang: string | null; body: string }
  | { kind: 'table'; aligns: TableAlign[]; headers: string[]; rows: string[][] }
  | { kind: 'hr' };

export function Markdown({ children }: MarkdownProps) {
  const blocks = parseBlocks(children);
  return (
    <>
      {blocks.map((block, i) => (
        <Fragment key={i}>{renderBlock(block)}</Fragment>
      ))}
    </>
  );
}

// GFM pipe-table cell split, ported logic-for-logic from OD's
// `runtime/markdown.tsx`. Tokenizes rather than a naive `split('|')`
// so it can honor three cell-content rules without placeholder substitution:
// `\|` is a literal pipe inside a cell, a `|` inside a backtick code span is
// cell content rather than a column boundary, and a single optional leading
// `|` plus an unescaped trailing `|` are row terminators, not empty cells.
// Always returns at least one cell (an empty row yields `['']`).
const TABLE_ROW_LEAD = /^ *\|?/;
const TABLE_CELL_TOKEN = /\\\||`|\||[^`|\\]+|\\/g;

function splitTableCells(line: string): string[] {
  const cells: string[] = [];
  let cur = '';
  let inCode = false;
  for (const token of line.replace(TABLE_ROW_LEAD, '').match(TABLE_CELL_TOKEN) ?? []) {
    if (token === '|' && !inCode) {
      cells.push(cur.trim());
      cur = '';
      continue;
    }
    if (token === '`') inCode = !inCode;
    cur += token === '\\|' ? '|' : token;
  }
  const tail = cur.trim();
  if (cells.length === 0 || tail !== '') cells.push(tail);
  return cells;
}

const TABLE_ALIGN_CELL = /^:?-{1,}:?$/;
// Every cell `TABLE_ALIGN_CELL` accepts starts and ends with `:` or `-`, so its
// first + last character is always exactly one of these four keys.
const COLUMN_ALIGN = { '::': 'center', '-:': 'right', ':-': 'left', '--': null } as const;

// Recognizes a GFM alignment row (`| --- | :---: | ---: |`) and returns the
// per-column alignment, or `null` if `line` isn't one — used both to detect
// where a table starts and to read its column alignment.
function parseTableAlignRow(line: string): TableAlign[] | null {
  if (!line.includes('|')) return null;
  const cells = splitTableCells(line);
  if (!cells.every((cell) => TABLE_ALIGN_CELL.test(cell))) return null;
  return cells.map((cell) => COLUMN_ALIGN[`${cell[0]}${cell.at(-1)}` as keyof typeof COLUMN_ALIGN]);
}

// A table starts at `i` when `lines[i]` is a pipe-bearing header row
// immediately followed by a valid alignment row at `lines[i + 1]`.
function isTableStartAt(lines: string[], i: number): boolean {
  const sep = lines[i + 1];
  if (sep === undefined) return false;
  if (!lines[i]!.includes('|')) return false;
  return parseTableAlignRow(sep) !== null;
}

// Collects the body rows following a table's header + alignment row —
// every subsequent non-blank, pipe-bearing line, matching OD's greedy
// table-body rule. Called only once `isTableStartAt` has confirmed `i`
// through `i + 1` are the header/alignment pair; returns the new cursor.
function collectTableRows(lines: string[], start: number): { rows: string[][]; next: number } {
  const rows: string[][] = [];
  let i = start;
  while (i < lines.length) {
    const row = lines[i]!;
    if (row.trim() === '' || !row.includes('|')) break;
    rows.push(splitTableCells(row));
    i++;
  }
  return { rows, next: i };
}

const ORDERED_ITEM = /^\s*\d+[.)]\s+/;
const FENCE = /^```/;
const HEADING = /^(#{1,3})\s+(.*)$/;
const RULE = /^(-{3,}|\*{3,}|_{3,})\s*$/;
const QUOTE_LINE = /^>\s?/;
const BULLET_ITEM = /^\s*[-*]\s+/;

// Every `lines[i]` access in the block parsers below is guarded by an
// `i < lines.length` check (either `parseBlocks`' own loop condition or an
// inner `while`'s left-hand operand, short-circuited before the index is
// read) — `lines` is a `string[]` from `String.prototype.split`, which never
// contains `undefined` entries, so the index is always in range and always a
// string. The `?? ''`/non-null-assertion sites below are TS-only fallbacks
// for `noUncheckedIndexedAccess`-style indexing with no real runtime path;
// using `!` documents that instead of instrumenting an unreachable branch
// (same convention as `ToolCard.tsx`'s `baseName` comment).
type ParsedBlock = { block: Block; next: number };
type BlockParser = (lines: string[], i: number) => ParsedBlock | null;

function parseFence(lines: string[], i: number): ParsedBlock | null {
  const line = lines[i]!;
  if (!FENCE.test(line)) return null;
  const lang = line.slice(3).trim() || null;
  const body: string[] = [];
  let j = i + 1;
  while (j < lines.length && !FENCE.test(lines[j]!)) {
    body.push(lines[j]!);
    j += 1;
  }
  // `j + 1` skips the closing fence (or end of input if unterminated).
  return { block: { kind: 'code', lang, body: body.join('\n') }, next: j + 1 };
}

function parseHeading(lines: string[], i: number): ParsedBlock | null {
  const heading = HEADING.exec(lines[i]!);
  if (!heading) return null;
  // Both capture groups are mandatory (non-optional) in this pattern, so
  // whenever `heading` itself is truthy, `heading[1]`/`heading[2]` are
  // always matched strings (never `undefined`) — same dead-fallback
  // reasoning as the `lines[i]` accesses above.
  return { block: { kind: 'h', level: heading[1]!.length as 1 | 2 | 3, text: heading[2]! }, next: i + 1 };
}

function parseRule(lines: string[], i: number): ParsedBlock | null {
  return RULE.test(lines[i]!) ? { block: { kind: 'hr' }, next: i + 1 } : null;
}

// Collects the run of consecutive lines matching `marker`, each with that
// marker stripped — the shape of blockquotes.
function collectMarked(lines: string[], start: number, marker: RegExp): { items: string[]; next: number } {
  const items: string[] = [];
  let i = start;
  while (i < lines.length && marker.test(lines[i]!)) {
    items.push(lines[i]!.replace(marker, ''));
    i += 1;
  }
  return { items, next: i };
}

function parseQuote(lines: string[], i: number): ParsedBlock | null {
  if (!QUOTE_LINE.test(lines[i]!)) return null;
  const { items, next } = collectMarked(lines, i, QUOTE_LINE);
  return { block: { kind: 'bq', text: items.join('\n') }, next };
}

// A list item runs on over the following lines until a blank line or another block starts
// (CommonMark's lazy continuation). Without it, a wrapped item such as "- **Grafana Cloud (instance
// ID +\n  token)**" split into an item and a paragraph, and both halves showed raw `**`.
function collectItem(lines: string[], i: number, marker: RegExp): { item: string; next: number } {
  let item = lines[i]!.replace(marker, '');
  let j = i + 1;
  while (j < lines.length && lines[j]!.trim() !== '' && !isBlockStart(lines, j)) {
    item += `\n${lines[j]!.trim()}`;
    j += 1;
  }
  return { item, next: j };
}

function parseBulletList(lines: string[], i: number): ParsedBlock | null {
  if (!BULLET_ITEM.test(lines[i]!)) return null;
  const items: string[] = [];
  let j = i;
  while (j < lines.length && BULLET_ITEM.test(lines[j]!)) {
    const { item, next } = collectItem(lines, j, BULLET_ITEM);
    items.push(item);
    j = next;
  }
  return { block: { kind: 'ul', items }, next: j };
}

function parseTable(lines: string[], i: number): ParsedBlock | null {
  if (!isTableStartAt(lines, i)) return null;
  const aligns = parseTableAlignRow(lines[i + 1]!)!;
  const headers = splitTableCells(lines[i]!);
  const { rows, next } = collectTableRows(lines, i + 2);
  return { block: { kind: 'table', aligns, headers, rows }, next };
}

function parseOrderedList(lines: string[], i: number): ParsedBlock | null {
  const line = lines[i]!;
  if (!ORDERED_ITEM.test(line)) return null;
  const start = Number(/\d+/.exec(line)![0]);
  const items: string[] = [];
  let j = i;
  while (j < lines.length && ORDERED_ITEM.test(lines[j]!)) {
    const { item, next } = collectItem(lines, j, ORDERED_ITEM);
    items.push(item);
    j = nextLooseListLine(lines, next);
  }
  return { block: { kind: 'ol', start, items }, next: j };
}

// Tried in this order at each non-blank line; the first match wins, and a
// line none of them claims starts a paragraph.
const BLOCK_PARSERS: readonly BlockParser[] = [
  parseFence,
  parseHeading,
  parseRule,
  parseQuote,
  parseBulletList,
  parseTable,
  parseOrderedList,
];

function parseParagraph(lines: string[], i: number): ParsedBlock {
  const paragraph: string[] = [];
  let j = i;
  while (j < lines.length && lines[j]!.trim() !== '' && !isBlockStart(lines, j)) {
    paragraph.push(lines[j]!);
    j += 1;
  }
  return { block: { kind: 'p', text: paragraph.join('\n') }, next: j };
}

function parseBlockAt(lines: string[], i: number): ParsedBlock {
  for (const parse of BLOCK_PARSERS) {
    const parsed = parse(lines, i);
    if (parsed) return parsed;
  }
  return parseParagraph(lines, i);
}

function parseBlocks(input: string): Block[] {
  const lines = input.split(/\r?\n/);
  const blocks: Block[] = [];
  let i = 0;
  while (i < lines.length) {
    if (lines[i]!.trim() === '') {
      i += 1;
      continue;
    }
    const { block, next } = parseBlockAt(lines, i);
    blocks.push(block);
    i = next;
  }
  return blocks;
}

/**
 * A "loose" numbered list puts a blank line between items ("1. a\n\n2. b").
 * Skip those blank lines when the next non-blank line is another numbered
 * item, so the items stay in ONE `<ol>` (numbered 1..n) instead of n lists
 * that each show "1.". Otherwise return `i` unchanged and the list ends.
 */
function nextLooseListLine(lines: string[], i: number): number {
  let j = i;
  while (j < lines.length && lines[j]!.trim() === '') j += 1;
  return j > i && j < lines.length && ORDERED_ITEM.test(lines[j]!) ? j : i;
}

function isBlockStart(lines: string[], i: number): boolean {
  const line = lines[i]!;
  return (
    FENCE.test(line)
    || /^(#{1,3})\s+/.test(line)
    || RULE.test(line)
    || QUOTE_LINE.test(line)
    || BULLET_ITEM.test(line)
    || ORDERED_ITEM.test(line)
    || isTableStartAt(lines, i)
  );
}

function renderBlock(block: Block): ReactNode {
  switch (block.kind) {
    case 'h': {
      const Tag = (`h${block.level}` as const) as 'h1' | 'h2' | 'h3';
      return <Tag>{renderInline(block.text)}</Tag>;
    }
    case 'p':
      return <p>{renderInline(block.text)}</p>;
    case 'ul':
      return (
        <ul>
          {block.items.map((item, i) => (
            <li key={i}>{renderInline(item)}</li>
          ))}
        </ul>
      );
    case 'ol':
      return (
        <ol start={block.start === 1 ? undefined : block.start}>
          {block.items.map((item, i) => (
            <li key={i}>{renderInline(item)}</li>
          ))}
        </ol>
      );
    case 'bq':
      return <blockquote>{renderInline(block.text)}</blockquote>;
    case 'code':
      return <CodeBlock lang={block.lang} body={block.body} />;
    case 'table':
      return <TableBlock aligns={block.aligns} headers={block.headers} rows={block.rows} />;
    case 'hr':
      return <hr />;
  }
}

interface CodeBlockProps {
  lang: string | null;
  body: string;
}

// Fenced code block ('renderBlock' case 'code') plus its copy affordance. 'CopyCodeButton' below
// sits in its own small toolbar row above the '<pre>', not overlaid on top of it: an overlay
// button would sit over whatever code happens to render at that corner, and '.jini-message-
// content pre' already carries its own horizontal scrollbar at the bottom of the element -- a
// separate row above avoids colliding with either.
function CodeBlock({ lang, body }: CodeBlockProps): ReactNode {
  return (
    <div className="jini-md-code-block">
      <div className="jini-md-code-toolbar">
        <CopyCodeButton code={body} />
      </div>
      <pre>
        <code data-lang={lang ?? undefined}>{body}</code>
      </pre>
    </div>
  );
}

interface CopyCodeButtonProps {
  /** The fenced block's exact source text -- never a DOM/innerText read, so it survives the round trip byte-for-byte (indentation, trailing spaces, any markup-like characters inside the fence). */
  code: string;
}

// Per-block copy affordance for CodeBlock above. Mirrors MessageRow.tsx's CopyMessageButton
// one-for-one in shape -- same hook, same icon swap, same visually-hidden aria-live announce --
// but stays its own component rather than a shared one; see this module's header comment for why.
function CopyCodeButton({ code }: CopyCodeButtonProps): ReactNode {
  const t = useT();
  const { copied, copy } = useCopyToClipboard();
  return (
    <>
      <button
        type="button"
        className="jini-md-code-copy"
        aria-label={copied ? t('Copied') : t('Copy code')}
        onClick={() => {
          void copy(code);
        }}
      >
        <Icon name={copied ? 'check' : 'copy'} />
      </button>
      {/* Visually hidden, not decorative -- same reasoning as MessageRow.tsx's own copy-status
          span: the icon swap above says nothing to a screen reader on its own. */}
      <span className="jini-md-code-copy-status" aria-live="polite">
        {copied ? t('Copied to clipboard') : ''}
      </span>
    </>
  );
}

interface TableBlockProps {
  aligns: TableAlign[];
  headers: string[];
  rows: string[][];
}

// Renders the `<table>` element itself — shared between the inline (possibly
// scroll-clipped) copy and the pop-out modal's full-size copy, so the two
// never drift. Each cell goes through the same `renderInline` pass every
// other block uses, so `**bold**`/`` `code` ``/links inside a cell render as
// markup rather than literal text.
function renderTableElement({ aligns, headers, rows }: TableBlockProps): ReactNode {
  const cellStyle = (idx: number): { textAlign: 'left' | 'right' | 'center' } | undefined => {
    const align = aligns[idx];
    return align ? { textAlign: align } : undefined;
  };
  return (
    <table className="jini-md-table">
      <thead>
        <tr>
          {headers.map((cell, idx) => (
            <th key={idx} style={cellStyle(idx)}>{renderInline(cell)}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, rowIndex) => (
          <tr key={rowIndex}>
            {headers.map((_, cellIndex) => (
              <td key={cellIndex} style={cellStyle(cellIndex)}>{renderInline(row[cellIndex] ?? '')}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

// Width-only overflow check for the table wrap below — a *deliberately*
// narrower copy of the downstream host's own overflow-detection hook (see
// this file's own module doc), same `ResizeObserver` + mount-time-check
// shape, not an import of it: this package cannot depend on a downstream
// host's app code, and a table can only ever overflow horizontally (its
// wrap never constrains height), so this version skips that hook's
// vertical-axis branch entirely.
const TABLE_OVERFLOW_SLACK_PX = 1;

function useTableOverflow(): { wrapRef: RefObject<HTMLDivElement | null>; isOverflowing: boolean } {
  const wrapRef = useRef<HTMLDivElement>(null);
  const [isOverflowing, setIsOverflowing] = useState(false);

  useEffect(() => {
    // The wrap div renders unconditionally, so its ref is attached by the time this effect runs.
    const el = wrapRef.current!;
    if (typeof ResizeObserver !== 'function') return;
    const check = () => setIsOverflowing(el.scrollWidth > el.clientWidth + TABLE_OVERFLOW_SLACK_PX);
    const observer = new ResizeObserver(check);
    observer.observe(el);
    check();
    return () => observer.disconnect();
  }, []);

  return { wrapRef, isOverflowing };
}

// Wide-table pop-out: the inline table always renders (scroll-clipped by its
// own `.jini-md-table-wrap` if wider than the message column), and once it
// genuinely overflows its own box an "Expand table" button appears to reopen
// it full-size in a native `<dialog>` — same open/close/backdrop/Escape
// lifecycle as the downstream host's own overflow-modal component (see this
// file's own module doc), kept self-contained here for the same reason
// `useTableOverflow` above is: no downstream-host dependency, and every
// Jini host gets the affordance.
// `<dialog>`'s `showModal`/`close` methods are unimplemented in jsdom (and on any real browser too
// old to support the element at all) — falls back to the plain `open` attribute in either case,
// same guarded fallback shape that host component's own dialog lifecycle hook uses for the
// identical reason.
function openTableDialog(dialog: HTMLDialogElement): void {
  if (typeof dialog.showModal === 'function') {
    if (!dialog.open) dialog.showModal();
    return;
  }
  dialog.setAttribute('open', '');
}

function closeTableDialog(dialog: HTMLDialogElement): void {
  if (typeof dialog.close === 'function') {
    if (dialog.open) dialog.close();
    return;
  }
  dialog.removeAttribute('open');
}

function TableBlock(props: TableBlockProps): ReactNode {
  const { wrapRef, isOverflowing } = useTableOverflow();
  const [expanded, setExpanded] = useState(false);
  const dialogRef = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    // The `<dialog>` renders unconditionally, so its ref is attached by the time this effect runs.
    const dialog = dialogRef.current!;
    if (expanded) openTableDialog(dialog);
    else closeTableDialog(dialog);
  }, [expanded]);

  return (
    <div className="jini-md-table-block">
      <div className="jini-md-table-wrap" ref={wrapRef}>
        {renderTableElement(props)}
      </div>
      {isOverflowing ? (
        <button type="button" className="jini-md-table-expand" onClick={() => setExpanded(true)}>
          Expand table
        </button>
      ) : null}
      <dialog
        ref={dialogRef}
        className="jini-md-table-modal"
        onCancel={(e) => {
          e.preventDefault();
          setExpanded(false);
        }}
        onClick={(e) => {
          if (e.target === dialogRef.current) setExpanded(false);
        }}
      >
        <button type="button" className="jini-md-table-modal-close" onClick={() => setExpanded(false)} aria-label="Close">
          ×
        </button>
        <div className="jini-md-table-modal-body">{expanded ? renderTableElement(props) : null}</div>
      </dialog>
    </div>
  );
}

// Inline pass: `code`, [label](url) links, **bold**, *italic*/_italic_, bare http(s) autolinks.
// Processes left-to-right with a single regex alternation so spans never
// nest incorrectly across kinds.
//
// `_italic_` follows CommonMark's word-boundary rule: an `_` with a letter,
// digit or `_` on its outer side never opens or closes emphasis, and an `_`
// between two word characters inside the span is content. The plain
// `_[^_]+_` this replaced matched intraword, so a tool-result name like
// `ANALYTICS_ROOT_KEY_SEED` rendered as `ANALYTICS<em>ROOT</em>KEY_SEED`.
// `*` stays permissive — CommonMark allows intraword `*` emphasis.
const UNDERSCORE_EM = String.raw`(?<![\p{L}\p{N}_])_(?![\s_])(?:[^_]|_(?=[\p{L}\p{N}]))+?(?<!\s)_(?![\p{L}\p{N}_])`;
// `[label](url)`: the URL may hold one level of balanced parentheses (`Foo_(bar)`), and the whole
// link may itself sit inside parentheses (`([edit](/admin/pages/x))`) — the outer `)` is left as text.
const MD_LINK = String.raw`\[[^\]\n]+\]\((?:[^()\s]|\([^()\s]*\))+\)`;
const MD_LINK_PARTS = /^\[([^\]\n]+)\]\((.+)\)$/u;
const INLINE_RE = new RegExp(String.raw`(\x60[^\x60]+\x60)|(${MD_LINK})|(\*\*[^*]+\*\*)|(\*[^*]+\*|${UNDERSCORE_EM})|(https?:\/\/[^\s)]+)`, 'gu');

// Only these targets become anchors; anything else (`javascript:`, `data:`, protocol-relative
// `//host`) stays literal text, since the text is untrusted model output.
const SAFE_LINK_HREF = /^(?:https?:\/\/|mailto:|\/(?!\/)|#)/iu;
// Every link opens in a new tab — an in-app path too, so following one never navigates the tab the
// chat lives in (owner 2026-10-08). Only a `#` same-document anchor stays in place. ChatPane's
// click guard (`useChatPaneNewTabLinks`) covers links this renderer does not draw.
const NEW_TAB = { target: '_blank', rel: 'noopener noreferrer' } as const;

function renderMarkdownLink(source: string, key: number): ReactNode {
  // `MD_LINK` already matched `source`, so these two groups always capture.
  const [, label, href] = MD_LINK_PARTS.exec(source)!;
  if (!SAFE_LINK_HREF.test(href!)) return source;
  return (
    <a key={key} href={href} {...(href!.startsWith('#') ? {} : NEW_TAB)}>
      {renderInline(label!)}
    </a>
  );
}

function renderInline(text: string): ReactNode {
  const nodes: ReactNode[] = [];
  let lastIndex = 0;
  let key = 0;
  // A fresh copy per call, not the shared `g` regex: a link label recurses into this function
  // mid-loop, and a shared `lastIndex` would be reset under the outer scan.
  const inlineRe = new RegExp(INLINE_RE);
  let match: RegExpExecArray | null = inlineRe.exec(text);
  while (match !== null) {
    if (match.index > lastIndex) nodes.push(text.slice(lastIndex, match.index));
    const [whole, code, mdLink, bold, italic, link] = match;
    if (code) nodes.push(<code key={key++}>{code.slice(1, -1)}</code>);
    else if (mdLink) nodes.push(renderMarkdownLink(mdLink, key++));
    else if (bold) nodes.push(<strong key={key++}>{renderInline(bold.slice(2, -2))}</strong>);
    else if (italic) nodes.push(<em key={key++}>{renderInline(italic.slice(1, -1))}</em>);
    else if (link)
      nodes.push(
        <a key={key++} href={link} {...NEW_TAB}>
          {link}
        </a>,
      );
    // `whole` is `match[0]` — a successful `RegExpExecArray` always has a
    // defined (if possibly empty) full-match string at index 0, so this
    // fallback is unreachable (same dead-fallback reasoning as above).
    lastIndex = match.index + whole!.length;
    match = inlineRe.exec(text);
  }
  if (lastIndex < text.length) nodes.push(text.slice(lastIndex));
  return nodes;
}

/**
 * @module components/McpUiSurfaceCard
 *
 * Renders MCP-UI Views inline in a chat transcript, fed by a message's `kind: 'ext', name: 'mcp-ui'`
 * events — the same extensibility seam `A2uiSurfaceCard.tsx` uses, and registered the same way: a
 * host calls {@link registerMcpUiSurfaceRenderer} with its owned registry (or the compatibility
 * default) and matching events in that registry's chat tree render through it.
 *
 * Each event's `data` is expected to be an MCP `EmbeddedResource` carrying UI — exactly the object a
 * tool result's `content` array holds, unwrapped. One shape, deliberately: accepting several
 * wrappers would mean guessing which one an unfamiliar producer meant, and guessing wrong renders a
 * blank frame rather than an error.
 *
 * Events sharing a `ui://` URI are one View, not several: a stream may re-send an updated document
 * for a surface already on screen (a confirmation that became a result), so the LAST event for each
 * URI wins while first-appearance order is preserved. Re-keying by URI is also what stops an update
 * from being rendered as a second, duplicate dialog next to the first.
 *
 * Moved here from `@jini-ai/ui`'s `react/mcp-ui/` 2026-08-03, alongside the `@jini-ai/chat`
 * consolidation: this is an ext-event renderer for a chat transcript (chat-domain), not a generic
 * ui primitive, and its sibling `A2uiSurfaceCard.tsx` already lived here. Moving it also removed a
 * real `ui → chat` edge that would otherwise have formed a cycle with `@jini-ai/chat`'s own new
 * dependency on `@jini-ai/ui`. `McpUiHost`/`McpUiToolCallHandler`/`parseUIResource`/`readPreferredFrameSize` still
 * come from `@jini-ai/ui/mcp-ui`, which owns the actual sandboxed-iframe hosting and MCP-UI
 * resource vocabulary — genuinely ui-generic, with real consumers beyond this one component.
 *
 * ## The parent-DOM mirror
 *
 * A surface renders inside a real, `@mcp-ui/client`-managed sandboxed iframe (see
 * `@jini-ai/ui/mcp-ui`'s `useMcpUiHost.ts` module doc for the 2026-08-18 swap from a hand-rolled
 * `srcdoc` frame to the official `AppRenderer`), which — regardless of the exact sandbox attributes
 * that swap changed — still renders the View at arm's length from the surrounding page: nothing
 * this package or its caller controls directly reaches into that frame's DOM. `page.find_elements`
 * (`@jini-ai/agentic`'s page-control capability) scans the PARENT document only, so no amount of
 * `data-agent-*` tagging inside the frame (see `surfaces/document.ts`'s `renderActions`) makes a
 * surface's pending confirmation, or its buttons' labels, discoverable to it. `readActionPlan`
 * (this component's other new import)
 * gives this component the same `{title, actions}` a surface renders as real buttons, via a typed
 * `_meta` channel rather than scraping HTML — see `MCP_UI_ACTION_PLAN_META_KEY`'s own doc.
 *
 * What this component does with that plan is deliberately narrow: publish a single, `status`-role,
 * DISCOVERY-ONLY region per surface — `page.find_elements` can learn a confirmation is pending and
 * what its buttons are called, but NOTHING here carries a `data-agent-element` handle for an
 * individual action. `page.click` (`dom-page-driver.ts`) does not consult `data-agent-role` at all;
 * it activates whatever a handle resolves to, unconditionally. So there is no such thing as a
 * "safely" clickable mirror button — publishing one at all would let the same live agent that
 * raised the confirmation answer its own dialog, defeating the human gate the surface exists to
 * enforce. That capability may be built deliberately later (the owner has floated letting an agent
 * confirm non-destructive actions, e.g. on a timer) but it is a real policy decision — which tool
 * calls, what gates it, an audit trail — not a default this visibility fix should smuggle in.
 *
 * `aria-hidden="true"` plus `display: none`: the mirror exists purely for a DOM-attribute scanner,
 * never for a human — the real dialog is already visible (and, once resolved, readable) in the
 * iframe right next to it. Without `aria-hidden` a screen-reader user would hear the confirmation's
 * title and button labels announced twice, in slightly different words, once from the live dialog
 * and once from this region — `role="status"` is an implicit `aria-live="polite"` region, so it
 * would self-announce on mount even before being focused. Verified empirically, not assumed, that
 * hiding it this way does not also make it invisible to `find_elements`: that capability never
 * filters its result set by visibility (`dom-page-driver.ts`'s `findElements`), only annotates a
 * `visible` field in per-element STATE when a caller opts into it — see the regression tests added
 * against the real driver in `@jini-ai/agentic`.
 */
import { questionAnswerFromResult, questionAnswerLabel } from '../../core/question-answer.js';
import { MidRunUserMessage } from './MidRunUserMessage.js';
import { Fragment, useMemo } from 'react';
import {
  McpUiHost,
  parseUIResource,
  readActionPlan,
  readExpiresAt,
  readPreferredFrameSize,
  type McpUiActionPlan,
  type McpUiToolCallHandler,
  type UIResource,
} from '@jini-ai/ui/mcp-ui';
import { defaultExtEventRendererRegistry, type ExtEventRendererRegistry, type ExtEventCall, type ExtEventRenderProps } from '../ext-event-renderer-registry.js';
import { useT } from '../hooks/context.js';
import { useSurfaceExpiry, type SurfaceExpiryClock } from '../hooks/useSurfaceExpiry.js';
import { closedSurfaceLabel, reportDeliveredAnswer } from './mcp-ui-surface-state.js';
import { surfaceQuestionInput } from './mcp-ui-question-input.js';

/** The `kind: 'ext'` event name this renderer claims. */
export const MCP_UI_EXT_EVENT_NAME = 'mcp-ui';

export interface McpUiSurfaceCardProps extends ExtEventRenderProps {
  /**
   * Where the sandbox proxy page is served. Required since 2026-08-18, when this card's rendering
   * switched from a hand-rolled `srcdoc` iframe to the real `@mcp-ui/client` `AppRenderer`, which
   * mounts every View through a real, separately-served proxy page rather than inline HTML — see
   * `@jini-ai/ui/mcp-ui`'s `SANDBOX_PROXY_HTML` (in `sandbox-proxy.js`) for what must be running at
   * that URL and why this package cannot supply a default itself.
   */
  sandboxProxyUrl: URL;
  /** Executes a tool a View asked for. Omit and every `tools/call` is refused — visibly, in the dialog. */
  onToolCall?: McpUiToolCallHandler;
  onOpenLink?: (url: string) => void;
  /**
   * Ceiling for a View's self-reported height, forwarded to every `McpUiHost` this card renders.
   * Omit to keep `McpUiHost`'s own `DEFAULT_MAX_HEIGHT` (720px) — a reasonable default for a
   * full-width transcript, but well past what a narrow docked pane can show without excessive
   * scrolling for content taller than its `preferredFrameSize` guess. A host embedding this card in
   * a fixed-width sidebar should pass a cap sized to its own viewport.
   */
  maxHeight?: number | undefined;
  /**
   * Time source for a card's answer deadline (`MCP_UI_EXPIRES_AT_META_KEY`). Omit for the wall clock;
   * a test injects a fake one to step through the countdown.
   */
  expiryClock?: SurfaceExpiryClock;
}

/** Collapses the event stream to the newest resource per `ui://` URI, in first-appearance order. */
function latestResourcesByUri(events: readonly unknown[]): readonly UIResource[] {
  const byUri = new Map<string, UIResource>();
  for (const event of events) {
    const resource = parseUIResource(event);
    if (resource === undefined) continue;
    byUri.set(resource.resource.uri, resource);
  }
  return [...byUri.values()];
}

/**
 * Builds a valid `data-agent-element` handle from a surface's `ui://` URI.
 *
 * Handles are `[a-z0-9]+(-[a-z0-9]+)*` (`@jini-ai/agentic`'s `HANDLE_PATTERN`) — narrower than a
 * URI, which carries `:`, `/`, and whatever characters a producer's own id scheme uses. Rather than
 * assume every producer's URI already happens to satisfy that pattern (`agentHandle()` THROWS on a
 * handle that does not, which would take down the whole surface card's render for an otherwise
 * perfectly valid resource), this sanitizes unconditionally: lowercase, collapse every run of
 * disallowed characters to one hyphen, trim the ends. A URI already shaped like
 * `ui://host/deployment-execute-static-publish/<uuid>` survives this close to verbatim; this only
 * has teeth for a producer whose id scheme this package has never seen.
 */
function pendingMirrorHandle(uri: string): string {
  // Never empty: only resources whose URI starts with `ui://` reach a card (`@jini-ai/ui/mcp-ui`'s
  // resource parser rejects every other scheme), so the sanitized handle always keeps at least `ui`.
  const sanitized = uri.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return `mcp-ui-pending-${sanitized}`;
}

/** The one label a mirror region carries — what is pending, and what an agent could report or wait on. */
function pendingMirrorLabel(t: ReturnType<typeof useT>, plan: McpUiActionPlan): string {
  const actionLabels = plan.actions.map((action) => action.label).join(', ');
  return t('A confirmation is pending human response: "{title}". Buttons: {actions}.', {
    title: plan.title,
    actions: actionLabels === '' ? t('none') : actionLabels,
  });
}

/**
 * The parent-DOM, discovery-only echo of one surface's pending action plan — see this module's own
 * doc for what it is, why it carries no clickable handle, and why it is hidden from both sighted
 * and screen-reader users. A standalone component (rather than inline JSX in the `.map` below)
 * purely so its narrow job — one `<div>`, a handful of static attributes — reads as a complete,
 * self-contained unit rather than a growing side-branch of `McpUiSurfaceCard`'s own return.
 */
function PendingSurfaceMirror({ uri, plan, t }: { uri: string; plan: McpUiActionPlan; t: ReturnType<typeof useT> }) {
  return (
    <div
      aria-hidden="true"
      style={{ display: 'none' }}
      data-agent-element={pendingMirrorHandle(uri)}
      data-agent-role="status"
      data-agent-label={pendingMirrorLabel(t, plan)}
    />
  );
}

/** Keep one title/answer format for the collapsed card and standalone form's user bubble. */
function surfaceAnswerLabel({ call, label }: { call: ExtEventCall | undefined; label: string }, _options = {}): string {
  return questionAnswerLabel({ input: call?.input, text: label });
}

/** Prefer the question as the frame title; untitled resources retain their URI fallback.
 * @complexity O(h + c) for fallback markup and controls; metadata needs O(1), no effects.
 */
function surfaceQuestionTitle({ resource }: { resource: UIResource }, _options = {}): string {
  const input = surfaceQuestionInput({ resource, input: undefined }) as { title?: unknown } | undefined;
  return typeof input?.title === 'string' ? input.title : resource.resource.uri;
}

/** A closed card: the question's title, when the call gave one, and why it is closed. */
function ClosedSurface({ call, label }: { call: ExtEventCall | undefined; label: string }) {
  return (
    <div className="mcpui-surface-card mcpui-surface-card-closed" role="status">
      {surfaceAnswerLabel({ call, label })}
    </div>
  );
}

/** The live card's answer lifecycle: its deadline and delivery notification, using their existing owners. */
function surfaceInteraction(
  { resource, answered, onToolCall, onAnswered, onAnswerText, call }: {
    resource: UIResource | undefined;
    answered: boolean | undefined;
    onToolCall: McpUiToolCallHandler | undefined;
    onAnswered: (() => void) | undefined;
    onAnswerText: ((answerText: string) => void) | undefined;
    call: ExtEventCall | undefined;
  },
  _options: Record<string, never> = {},
) {
  // An answered card has no deadline left: its countdown goes, and the deadline passing while the
  // answer's work still runs must not relabel it "This question expired".
  const expiresAtMs = resource === undefined || answered === true ? undefined : readExpiresAt(resource);
  // Reports the person's delivered answer to the row, which stops the "Waiting for your answer" line.
  const toolCall = onToolCall === undefined || onAnswered === undefined ? onToolCall : reportDeliveredAnswer({ onToolCall, onAnswered, onAnswerText, input: call?.input });
  return { expiresAtMs, toolCall };
}

/** Registered against `ext-event-renderer-registry.ts`'s `'mcp-ui'` name — see module doc. */
export function McpUiSurfaceCard({ events, sandboxProxyUrl, onToolCall, onOpenLink, maxHeight, call, runStreaming, expiryClock, answered, onAnswered, onAnswerText, answerText, answerRecorded }: McpUiSurfaceCardProps) {
  const t = useT();
  const resources = useMemo(() => latestResourcesByUri(events), [events]);
  // One card per slot is the registered shape (`mcpUiSurfaceSlotKey`), so `call` belongs to exactly
  // that card. A group holding several URIs has no single call to judge them by, and stays live.
  const single = resources.length === 1 ? resources[0] : undefined;
  const { displayCall, input, standalone } = useSurfaceQuestionCall({ events, call });
  const { expiresAtMs, toolCall } = surfaceInteraction({ resource: single, answered, onToolCall, onAnswered, onAnswerText, call: displayCall });
  const expiry = useSurfaceExpiry(
    { expiresAtMs },
    expiryClock === undefined ? {} : { clock: expiryClock },
  );
  const closed = single === undefined
    ? undefined
    : closedSurfaceLabel({ t, call, runStreaming, documentsForUri: events.length, expired: expiry?.expired === true });
  // A completed call answered the original document; a replacement outcome or retry owns its view.
  const answer = (events.length === 1 ? questionAnswerFromResult({ result: call?.result, input }) : undefined) ?? answerText;
  return <SurfaceCardContent resources={resources} single={single} answerRecorded={answerRecorded}
    answer={answer} closed={closed} call={displayCall} standalone={standalone} t={t} sandboxProxyUrl={sandboxProxyUrl}
    toolCall={toolCall} onOpenLink={onOpenLink} maxHeight={maxHeight} expiry={expiry} />;
}

/** A standalone form's call may lack the question; its current document supplies the title and
 * option labels, so retry answers read as labels rather than raw values from the replaced question.
 * Receipt recovery retains the original document separately in useSurfaceAnswerContexts. */
function useSurfaceQuestionCall({ events, call }: { events: readonly unknown[]; call: ExtEventCall | undefined }, _options = {}) {
  const resource = parseUIResource(events.at(-1));
  const input = useMemo(() => surfaceQuestionInput({ resource, input: call?.input }),
    [resource?.resource.text, resource?.resource._meta, call?.input]);
  const displayCall: ExtEventCall = call === undefined ? { name: '', input } : { ...call, input };
  return { displayCall, input, standalone: input !== call?.input };
}

/** A recorded receipt closes the card even while its readable answer is still arriving. */
function recordedAnswerLabel({ answer, closed, t }: {
  answer: string | undefined; closed: string | undefined; t: ReturnType<typeof useT>;
}, _options = {}): string {
  return answer ?? closed ?? t('Answered');
}

/** A single answered card: closed with its label, plus the optimistic bubble until a receipt owns it.
 * @complexity O(1), no effects.
 */
function answeredSurface({ answerRecorded, answer, closed, call, standalone, t }: {
  answerRecorded: McpUiSurfaceCardProps['answerRecorded'];
  answer: string | undefined;
  closed: string | undefined;
  call: McpUiSurfaceCardProps['call'];
  standalone: boolean;
  t: ReturnType<typeof useT>;
}, _options = {}) {
  // MOVE: The accepted-input receipt owns its bubble; the closed card retains the question's context.
  if (answerRecorded) return <ClosedSurface call={call} label={recordedAnswerLabel({ answer, closed, t })} />;
  if (answer === undefined) return undefined;
  const label = answer === 'Declined' ? t('Declined') : answer;
  return <><ClosedSurface call={call} label={label} /><MidRunUserMessage events={[{ text: standalone ? surfaceAnswerLabel({ call, label }) : label }]} /></>;
}

/** Rendering priority stays receipt, answer, closure, then the live documents. */
function SurfaceCardContent({ resources, single, answerRecorded, answer, closed, call, standalone, t,
  sandboxProxyUrl, toolCall, onOpenLink, maxHeight, expiry }: {
  resources: readonly UIResource[];
  single: UIResource | undefined;
  answerRecorded: McpUiSurfaceCardProps['answerRecorded'];
  answer: string | undefined;
  closed: string | undefined;
  call: McpUiSurfaceCardProps['call'];
  standalone: boolean;
  t: ReturnType<typeof useT>;
  sandboxProxyUrl: URL;
  toolCall: McpUiToolCallHandler | undefined;
  onOpenLink: McpUiSurfaceCardProps['onOpenLink'];
  maxHeight: number | undefined;
  expiry: ReturnType<typeof useSurfaceExpiry>;
}) {
  const frameTitle = useMemo(() => single === undefined ? undefined : surfaceQuestionTitle({ resource: single }),
    [single?.resource.uri, single?.resource.text, single?.resource._meta]);
  const answered = single === undefined ? undefined : answeredSurface({ answerRecorded, answer, closed, call, standalone, t });
  if (answered !== undefined) return answered;
  if (closed !== undefined) return <ClosedSurface call={call} label={closed} />;

  if (resources.length === 0) {
    // Visible rather than silent: an `ext` event named `mcp-ui` that carries no parseable resource
    // is a producer bug, and a transcript that renders nothing for it hides the bug behind what
    // looks like an ordinary empty turn.
    return (
      <div className="mcpui-surface-card mcpui-surface-card-empty" role="status">
        {t('This MCP-UI event carried no renderable resource.')}
      </div>
    );
  }

  return (
    <div className="mcpui-surface-card">
      {resources.map((resource) => {
        const preferred = readPreferredFrameSize(resource);
        const height = preferred === undefined ? undefined : Number.parseInt(preferred[1], 10);
        const plan = readActionPlan(resource);
        return (
          <Fragment key={resource.resource.uri}>
            <McpUiHost
              title={frameTitle ?? surfaceQuestionTitle({ resource })}
              html={resource.resource.text}
              sandboxProxyUrl={sandboxProxyUrl}
              toolName={resource.resource.uri}
              // The whole document, not its LENGTH. `useMcpUiHost` already defaults `sessionKey` to
              // `html` — exact by construction — and this override replaced that with a digest so
              // coarse that any two documents of equal size under one URI collided: a genuine update
              // (a re-rendered dialog with the same-length body, a swapped confirmation token) reused
              // the previous iframe session, so the handshake never re-ran and the frame kept serving
              // the OLD document's state. The URI stays in the key because it is real identity; the
              // length was never a substitute for content.
              sessionKey={`${resource.resource.uri}:${resource.resource.text}`}
              {...(toolCall === undefined ? {} : { onToolCall: toolCall })}
              {...(onOpenLink === undefined ? {} : { onOpenLink })}
              {...(height === undefined || Number.isNaN(height) ? {} : { initialHeight: height })}
              maxHeight={maxHeight}
            />
            {plan !== undefined && <PendingSurfaceMirror uri={resource.resource.uri} plan={plan} t={t} />}
          </Fragment>
        );
      })}
      {expiry?.expired === false && (
        <p className="mcpui-surface-expiry" role="timer">{t('Expires in {time}', { time: expiry.remaining })}</p>
      )}
    </div>
  );
}

/**
 * The ext-event slot key for MCP-UI: one slot per `ui://` URI. Each resource is its own card, so a
 * run's second card renders where it arrived instead of inside the first card's slot, while a
 * re-emitted resource with the same URI still updates its card in place. Pass it as
 * `registerExtEventRenderer({ name: MCP_UI_EXT_EVENT_NAME, renderer }, { slotKey: mcpUiSurfaceSlotKey })`
 * when registering a custom MCP-UI renderer; {@link registerMcpUiSurfaceRenderer} already does.
 */
export function mcpUiSurfaceSlotKey({ data }: { data: unknown }): string | undefined {
  return parseUIResource(data)?.resource.uri;
}

/**
 * Registers {@link McpUiSurfaceCard} against the ext-event registry.
 *
 * @param options.sandboxProxyUrl - See {@link McpUiSurfaceCardProps.sandboxProxyUrl}. Required for
 * the same reason it is required there — every View this registers a renderer for now mounts
 * through a real, host-served sandbox proxy page rather than inline HTML.
 * @param options.onToolCall - The tool executor every View in the transcript calls through. This is
 * the one dependency a host must supply — the card cannot know what "run this tool" means, and
 * hardcoding a transport here would make the component unusable in any host with a different one.
 * @param options.name - Override the claimed event name. Only useful for a host multiplexing two
 * independent MCP-UI streams.
 * @param options.maxHeight - See {@link McpUiSurfaceCardProps.maxHeight}. A host with a fixed-width
 * pane (a docked sidebar rather than a full-width transcript) should set this once here instead of
 * accepting the library's full-width-oriented 720px default.
 * @param options.registry - Owned registry bound to JiniChatProvider; omitted for the global default.
 * @returns An unregister handle, so a test or a hot reload can dispose cleanly.
 */
export function registerMcpUiSurfaceRenderer(options: {
  sandboxProxyUrl: URL;
  onToolCall?: McpUiToolCallHandler;
  onOpenLink?: (url: string) => void;
  name?: string;
  maxHeight?: number;
  /** Register in owned state when supplied; otherwise preserve the global API. */
  registry?: ExtEventRendererRegistry;
}): () => void {
  return (options.registry ?? defaultExtEventRendererRegistry).register({ name: options.name ?? MCP_UI_EXT_EVENT_NAME, renderer: (props) => (
    <McpUiSurfaceCard
      {...props}
      sandboxProxyUrl={options.sandboxProxyUrl}
      {...(options.onToolCall === undefined ? {} : { onToolCall: options.onToolCall })}
      {...(options.onOpenLink === undefined ? {} : { onOpenLink: options.onOpenLink })}
      maxHeight={options.maxHeight}
    />
  ) }, { slotKey: mcpUiSurfaceSlotKey });
}

/**
 * @file `MessageList`'s scroll-anchoring state, split out of the component per this package's
 * hooks-file convention (see `AttachmentPreviewModal.hooks.ts`). Pure DOM scroll-anchoring via a ref
 * lives here (presentational), not in the headless `useConversation` hook, per that hook's own
 * "transport-agnostic hooks never touch DOM" contract.
 */
import { useCallback, useEffect, useMemo, useRef, useState, type RefObject, type UIEvent } from 'react';
import { conversationUsage, type ChatUsageSummary } from '../../core/turn-usage.js';
import { projectAcceptedInputEvents } from '../../core/accepted-input.js';
import type { ChatMessage } from '../../core/index.js';
import { nextStickToBottom, startsNewTurn } from './MessageList.rules.js';

export interface MessageListAutoScroll {
  containerRef: RefObject<HTMLDivElement | null>;
  onScroll: (event: UIEvent<HTMLElement>) => void;
  /** True while the user has scrolled up away from the newest messages. */
  awayFromLatest: boolean;
  /** Scrolls to the newest message and resumes following new output. */
  jumpToLatest: () => void;
}

const prefersReducedMotion = () =>
  typeof window !== 'undefined' && (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false);

/** Recompute costs once per immutable transcript snapshot, including saved history on reload. */
export function useConversationUsage({ messages }: { messages: readonly ChatMessage[] }, _optional = {}) {
  const previous = useRef(new Map<string, ChatUsageSummary>());
  return useMemo(() => {
    // Usage and rendering must see the same answer boundaries, including receipts rebuilt on reload.
    const next = conversationUsage({ messages: messages.map(message => message.events === undefined ? message : {
      ...message, events: projectAcceptedInputEvents({ events: message.events }),
    }) });
    // Keep an unchanged summary's identity so memoized rows skip re-rendering while a run streams.
    for (const [id, summary] of next) {
      const old = previous.current.get(id);
      if (old && JSON.stringify(old) === JSON.stringify(summary)) next.set(id, old);
    }
    return previous.current = next;
  }, [messages]);
}

export function useMessageListAutoScroll(
  { messages, scrollIntent }: { messages: ChatMessage[]; scrollIntent: boolean },
  { onScrolled, reducedMotion = prefersReducedMotion }: { onScrolled?: () => void; reducedMotion?: () => boolean } = {},
): MessageListAutoScroll {
  const containerRef = useRef<HTMLDivElement | null>(null);
  // Whether the transcript was scrolled to its bottom as of the last user scroll or programmatic
  // scroll-to-bottom — read by the ResizeObserver effect below, which only ever sees the DOM AFTER a
  // resize already happened and so cannot recompute "was this at the bottom" from current values.
  // Starts true: a freshly mounted pane opens on the latest turn, same as scrollIntent's own default.
  const stickToBottomRef = useRef(true);
  const previousMessagesRef = useRef<readonly ChatMessage[]>(messages);
  // `scrollTop` at the previous `scroll` event — `nextStickToBottom` needs the direction of travel.
  // Only scroll events write it (a browser fires one for programmatic scrolls too). Starts at
  // Infinity, "no position seen yet", so a first event away from the bottom unsticks as it always did.
  const lastScrollTopRef = useRef(Number.POSITIVE_INFINITY);
  // State mirror of `!stickToBottomRef.current` for the "Jump to latest" button; the ref stays the
  // source of truth for the scroll effects, which must not wait for a render.
  const [awayFromLatest, setAwayFromLatest] = useState(false);

  // Runs BEFORE the scroll effect below (effects run in declaration order), so a send re-sticks in
  // time for that same commit's scroll. The user's own send (or retry) is an explicit "take me to
  // the latest turn": without this, a user who had scrolled up to read history and then sent stayed
  // parked up there, because the stick gate below — correct for streamed chatter — also swallowed
  // their own send (owner-reported "Chat auto-scroll still sticks", todos audit 2026-10-04).
  useEffect(() => {
    if (startsNewTurn({ previous: previousMessagesRef.current, next: messages })) {
      stickToBottomRef.current = true;
      setAwayFromLatest(false);
    }
    previousMessagesRef.current = messages;
  }, [messages]);

  useEffect(() => {
    if (!scrollIntent) return;
    const el = containerRef.current;
    // Gated on `stickToBottomRef`, same as the ResizeObserver effect below: `scrollIntent` turns
    // true on EVERY streamed event (tool-call chatter included, not just a finished reply — see
    // `useConversation.applyRunToAssistantMessage`), so scrolling unconditionally here yanked a user
    // who had deliberately scrolled up to read history back to the bottom on the very next chunk
    // (owner-reported, 2026-08-30). `stickToBottomRef` already reflects the user's own last scroll
    // gesture via the `onScroll` handler below, captured BEFORE this content change, so it is safe
    // to trust here.
    if (el && stickToBottomRef.current) {
      el.scrollTop = el.scrollHeight;
    }
    onScrolled?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrollIntent, messages]);

  // Re-sticks to the bottom when a message ROW grows after mount with no accompanying `messages`
  // change — the exact case an embedded MCP-UI/A2UI surface hits: it mounts at an initial guessed
  // height (`preferredFrameSize` or `DEFAULT_INITIAL_HEIGHT`), then reports its real, often much
  // taller content height asynchronously via `ui/notifications/size-changed`, entirely inside that
  // surface's own React state (`McpUiHost`). The effect above never re-runs for that, so without this
  // a surface which grows after the one-shot scroll leaves its own action buttons — or, once it
  // resolves, the assistant's next reply — below the stale "bottom" with nothing to bring them back
  // into view. Observes each direct child (one per message row) rather than the scroll container
  // itself: the container's own box is held fixed by its flex/overflow layout, so only its CONTENT
  // grows, which `ResizeObserver` only reports for the element whose box is actually changing.
  // Re-created per `messages` change so a newly mounted row is observed too. Gated on
  // `stickToBottomRef` so a human who scrolled up to read history is never yanked back down by an
  // unrelated row resizing elsewhere in the transcript.
  useEffect(() => {
    const el = containerRef.current;
    if (!el || typeof ResizeObserver !== 'function') return;
    const observer = new ResizeObserver(() => {
      if (!stickToBottomRef.current) return;
      el.scrollTop = el.scrollHeight;
    });
    for (const child of Array.from(el.children)) observer.observe(child);
    return () => observer.disconnect();
  }, [messages]);

  const onScroll = (event: UIEvent<HTMLElement>) => {
    const el = event.currentTarget;
    stickToBottomRef.current = nextStickToBottom(el, { wasSticking: stickToBottomRef.current, previousScrollTop: lastScrollTopRef.current });
    lastScrollTopRef.current = el.scrollTop;
    setAwayFromLatest(!stickToBottomRef.current);
  };

  const jumpToLatest = useCallback(() => {
    const el = containerRef.current;
    if (!el) return;
    // Re-stick first: a smooth scroll's own events move DOWN, which never unsticks, so output that
    // streams in during the animation is followed too.
    stickToBottomRef.current = true;
    setAwayFromLatest(false);
    el.scrollTo({ top: el.scrollHeight, behavior: reducedMotion() ? 'auto' : 'smooth' });
  }, [reducedMotion]);

  return { containerRef, onScroll, awayFromLatest, jumpToLatest };
}

import { projectAcceptedInputEvents } from '../../core/accepted-input.js';
import { MidRunUserMessage, MID_RUN_USER_MESSAGE_EXT_EVENT_NAME } from './MidRunUserMessage.js';
import { useSurfaceAnswerContexts } from './mcp-ui-question-input.js';
import { terminalMessageNotice, continuingRunNotice } from '../../core/durable-projection.js';
import type { ChatUsageSummary } from '../../core/turn-usage.js';
import { usageEndLabel, usageLayout, usageLineMeetsActions, useMessageUsage, useUsageSummary } from './MessageRow.usage.js';
/**
 * @module MessageRow
 *
 * Renders one `ChatMessage` — a dumb, props-in/JSX-out composition of this
 * package's own leaves (`<Markdown>`, `<ToolCard>` via `useToolTimeline`,
 * `<QuestionForm>` via `splitOnQuestionForms`). Unlike `ToolCard`/
 * `QuestionForm`/`TodoCard`/`NextStepActions`, this component is NOT a
 * direct port of an OD file: the two source branches this package was built
 * from (`refactor/web-chat-pane-slice`, `refactor/web-chat-composer-slice-pr`)
 * decompose `ChatPane.tsx`/`ChatComposer.tsx`, not `AssistantMessage.tsx`
 * (3,317 lines) — that god-component's own vertical-slice extraction is a
 * separate, not-yet-dispatched task (see
 * `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §3's suggested "AssistantMessage
 * first" ordering, which this task's sources don't cover). This is
 * therefore a fresh, reasonable v1 composition of the already-ported leaves,
 * not a byte-for-byte port — text and question-forms interleave in original
 * order (via `splitOnQuestionForms`).
 *
 * Tool cards now interleave too (`../message-blocks.js`), which they did not in
 * v1. That original deferral fused the text on either side of a tool call into
 * one run — a message read as `"I'll look for a tool that changes the
 * language.Done — the language is now English."`, two thoughts from before and
 * after the call joined mid-sentence, with every card pooled at the bottom.
 * `AssistantMessage.tsx`'s richer derivations (`deriveFileOps`/
 * `stripTodoToolGroups`/etc.) remain a TODO for that god-component's own
 * extraction task; plain ordering did not need to wait for them.
 *
 * `interleaveMessageBlocks` returns `null` when it cannot prove the
 * reconstruction is lossless, and this component then renders exactly the flat
 * layout it always did. Both paths are live, so the fallback is not dead code —
 * see that module's header for the conditions.
 *
 * Both message roles also carry a per-message copy affordance
 * (`CopyMessageButton`), rendered inside a `.jini-message-actions` row.
 * Assistant rows render that row as an extension seam: `branch`/thumbs-up/
 * thumbs-down are meant to join `copy` there later, as siblings in the same
 * row, once their backends (conversation branching, feedback storage) exist
 * — see the seam comment at that row's call site. Copy always copies the raw
 * markdown *source* — `message.content` (user) or `visibleContent`
 * (assistant, post `stripArtifact`) — never a flattened read of the rendered
 * DOM, so a table, fence, or `**bold**` marker survives the round trip.
 *
 * The assistant action row is further withheld while `message.runStatus`
 * has not yet reached a terminal state (`isRunInProgress` below) — not just
 * while there is literally nothing to show (`isPendingWithNoContent`).
 * Text and tool rows can settle onto the screen before the run itself ends
 * (e.g. a trailing tool call still in flight), and the copy affordance must
 * not appear until the whole message is done, not merely until its current
 * chunk stopped arriving.
 */
import React, { memo, useMemo, type ReactNode } from 'react';
import type { AgentEvent, ChatAttachment, ChatMessage, ChatRunStatus, IsAnsweredCard } from '../../core/index.js';
import { assistantContentFromEvents, isAwaitingAnswer, isTerminalRunStatus, splitOnQuestionForms, stripArtifact } from '../../core/index.js';
import { useToolTimeline, type ToolTimelineRow } from '../hooks/useToolTimeline.js';
import { useExtEventGroups, type ExtEventGroup } from '../hooks/useExtEventGroups.js';
import { useRunActivity } from '../hooks/useRunActivity.js';
import { useAnsweredCards, type AnsweredCards } from '../hooks/useAnsweredCards.js';
import { interleaveMessageBlocks, splitMidRunBlocks, type MessageBlock } from '../message-blocks.js';
import { useT, useExtEventRendererRegistry } from '../hooks/context.js';
import type { ExtEventRendererRegistry } from '../ext-event-renderer-registry.js';
import { ExtEventErrorBoundary } from './ExtEventErrorBoundary.js';
import { AttachmentPreviewModal } from './AttachmentPreviewModal.js';
import { SentAttachmentButton } from './SentAttachment.js';
import { useAttachmentGallery } from './AttachmentGallery.hooks.js';
import { CopyMessageButton } from './CopyMessageButton.js';
import { Markdown } from './Markdown.js';
import { ToolCard } from './ToolCard.js';
import { QuestionForm } from './QuestionForm.js';
import { ToolCallGroup } from './ToolCallGroup.js';
import { applyToolCallDisplay, toolRowsForDisplay, type ToolCallDisplay } from '../tool-call-display.js';

export interface MessageRowProps {
  message: ChatMessage;
  /** Per-turn charge and prefix total derived from the complete conversation's persisted events. */
  usageSummary?: ChatUsageSummary;
  /** Append the chat's running total as of each reply ("· total $3.95") to its Done line. On by default
   * (owner, 2026-10-10: keep the total); pass `false` to show only each turn's own cost. */
  showUsageTotal?: boolean;
  /** Show the "Done · time · cost" line(s) at all. On by default; `false` hides every one, total
   * included (a host's "Done line" display choice, 2026-10-11). */
  showUsageLine?: boolean;
  /** How tool calls show (`../tool-call-display.ts`): every card (`'show'`, the default), one
   * fold-up line per turn (`'collapsed'`), or compact unrecovered failures (`'hidden'`). */
  toolCallDisplay?: ToolCallDisplay;
  /** Show the model's reasoning (`thinking` events) as a fold-up block where it happened. Off by
   * default — the transcript never showed it before this option. Needs the interleaved layout; a
   * message that falls back to the flat layout shows none. */
  showThinking?: boolean;
  /** Whether this message's own run is still streaming. */
  runStreaming?: boolean;
  /** Whether the server has yet to accept this reply's run (its user turn is still pending). */
  runSending?: boolean;
  runSucceeded?: boolean;
  /** Whether this message's question-form (if any) is still the active/answerable one. */
  questionFormInteractive?: boolean;
  questionFormSubmittedAnswers?: Record<string, string | string[]>;
  onQuestionFormSubmit?: (text: string, answers: Record<string, string | string[]>) => void;
  projectFileNames?: Set<string>;
  onRequestOpenFile?: (name: string) => void;
  /** Host-supplied renderer for a `ChatAttachment` chip. Falls back to a plain filename chip. */
  renderAttachment?: (attachment: ChatAttachment) => ReactNode;
}

/**
 * True while an assistant message is still fully pending — no visible text
 * and no tool rows have arrived yet. Shared by the "Thinking…" placeholder
 * and the action row's own visibility below, since the two are mutually
 * exclusive by construction: a message with nothing to show yet has nothing
 * worth a copy/branch/feedback row either. Pulled out of `MessageRow` itself
 * (rather than inlined at each call site, as it was before this row existed)
 * so the condition is asserted once instead of duplicated.
 * @param message - The message being rendered.
 * @param visibleContent - `message.content` with any `<artifact>` block stripped.
 * @param toolRowCount - `useToolTimeline(...).rows.length` for this message.
 * @complexity O(1) — three comparisons, no loops or recursion.
 */
function isPendingWithNoContent(message: ChatMessage, visibleContent: string, toolRowCount: number): boolean {
  return message.runStatus === 'running' && !visibleContent.trim() && toolRowCount === 0;
}

/**
 * True while an assistant message's own run has been handed a lifecycle status but has not yet
 * reached a terminal one (`succeeded` | `failed` | `canceled`) — this covers `running` and also
 * `queued`, the brief window before streaming starts. A message whose `runStatus` is `undefined`
 * (no live run ever attached — e.g. history loaded from storage) is never "in progress": only a
 * message actively wired to a lifecycle status can be mid-run, so those messages fall through to
 * "done" rather than being treated as perpetually running.
 *
 * This is deliberately broader than `isPendingWithNoContent` above: that predicate answers "is
 * there nothing to show yet" (content OR a tool row already arriving flips it to false), while
 * this one answers "has the run itself finished" — the actual reported bug was text/tool rows
 * already on screen while a trailing tool call was still in flight, i.e. not-pending but also
 * not-done. The two are combined at the copy-button call site rather than merged into one
 * predicate, since `isPendingWithNoContent` still owns the separate "Thinking…" placeholder.
 * @param runStatus - `message.runStatus` from the message being rendered.
 * @complexity O(1) — one comparison plus a set lookup via `isTerminalRunStatus`.
 */
function isRunInProgress(runStatus: ChatRunStatus | undefined): boolean {
  return runStatus !== undefined && !isTerminalRunStatus({ status: runStatus });
}

/** One "Done · 6m 29s · $0.41 · total $2.50" line from reported usage, never estimated (the total is
 * left off when `showTotal` is false). Partial usage stays partial; output tokens are available to
 * assistive technology and in the tooltip. */
function UsageSummary({ usage, showTotal, message, awaitingAnswer }: { usage: ChatUsageSummary; showTotal: boolean; message?: ChatMessage; awaitingAnswer?: boolean }) {
  const t = useT();
  const label = usageEndLabel({ usage, ...(message === undefined ? {} : { message }), ...(awaitingAnswer === undefined ? {} : { awaitingAnswer }) });
  const { text, title, ariaLabel } = useUsageSummary({ usage }, { showTotal, label });
  if (!text) return null;
  return (
    <div className="jini-message-usage" title={title} role="note" aria-label={ariaLabel}>
      {label === 'Done' ? <span className="jini-message-usage-dot" aria-hidden>●</span> : null}
      {t(label)} · {text}
    </div>
  );
}

function messageBlocks(
  { message, rows, registry, content = message.content }: { message: ChatMessage; rows: ToolTimelineRow[]; registry: ExtEventRendererRegistry; content?: string },
  { toolCallDisplay = 'show', includeThinking = false }: { toolCallDisplay?: ToolCallDisplay; includeThinking?: boolean } = {},
) {
  const blocks = interleaveMessageBlocks<ToolTimelineRow>(
    { events: message.events, content, rows },
    { slotOf: (ev) => registry.slot({ name: ev.name, data: ev.data }), includeThinking },
  );
  return blocks ? applyToolCallDisplay({ blocks, mode: toolCallDisplay }, { runFailed: message.runStatus === 'failed' }) : null;
}

/**
 * The flat layout's tool groups. Even when host text prevents interleaving, event ordering can still
 * prove tool recovery and reply boundaries, so hidden mode reconstructs the blocks from the events —
 * only for this display decision; the host's text is never replaced. Otherwise one flat list.
 * @complexity O(n) in events + rows.
 */
function flatToolGroups(
  { message, rows, registry, displayBlocks }: { message: ChatMessage; rows: ToolTimelineRow[]; registry: ExtEventRendererRegistry; displayBlocks: readonly MessageBlock<ToolTimelineRow>[] | null },
  { toolCallDisplay }: { toolCallDisplay: ToolCallDisplay },
): { rows: readonly ToolTimelineRow[]; key: string }[] {
  if (toolCallDisplay === 'hidden') {
    const recovery = displayBlocks
      ?? messageBlocks({ message, rows, registry, content: assistantContentFromEvents({ events: message.events ?? [] }) }, { toolCallDisplay });
    if (recovery) return recovery.flatMap((block) => (block.kind === 'tools' ? [{ rows: block.rows, key: block.key }] : []));
  }
  const flat = toolRowsForDisplay({ rows, mode: toolCallDisplay }, { runFailed: message.runStatus === 'failed' });
  return flat.length > 0 ? [{ rows: flat, key: 'tools' }] : [];
}

/** The model's reasoning, folded under a "Thinking" summary so it never crowds the answer. */
function ThinkingBlock({ text }: { text: string }) {
  const t = useT();
  if (!text.trim()) return null;
  return (
    <details className="jini-message-thinking">
      <summary>{t('Thinking')}</summary>
      <div className="jini-message-thinking__text">{text}</div>
    </details>
  );
}

function messageAwaitingAnswer(
  { runStreaming, runInProgress, events }: { runStreaming?: boolean; runInProgress: boolean; events: AgentEvent[] | undefined },
  { isAnsweredCard }: { isAnsweredCard?: IsAnsweredCard } = {},
): boolean {
  return runStreaming === true && runInProgress && isAwaitingAnswer({ events }, { isAnsweredCard });
}

function AssistantMessageFooter(
  { message, usageEvent, showUsageTotal, terminalNotice, pending, runInProgress, runStreaming, runSending, visibleContent, isAnsweredCard }: {
    message: ChatMessage; usageEvent: ChatUsageSummary | undefined; showUsageTotal: boolean; terminalNotice: string | null;
    pending: boolean; runInProgress: boolean; runStreaming?: boolean; runSending: boolean; visibleContent: string; isAnsweredCard: IsAnsweredCard;
  }, _optional = {},
) {
  const t = useT();
  return <>
      {usageEvent ? <UsageSummary usage={usageEvent} showTotal={showUsageTotal} message={message}
        awaitingAnswer={isAwaitingAnswer({ events: message.events }, { isAnsweredCard })} /> : null}
      {terminalNotice ? <div className="jini-message-error" role="status">{t(terminalNotice)}</div> : null}
      {!pending && !runInProgress ? (
        <div className="jini-message-actions jini-message-actions--assistant">
          <CopyMessageButton text={visibleContent} label={t('Copy message')} />
          {/* Extension seam: branch/thumbs-up/thumbs-down join here next, as siblings after copy,
              same .jini-message-action-btn ghost icon-button shape and fixed left-to-right order
              (copy, branch, thumbs-up, thumbs-down) — left unbuilt per this task's module doc
              above until their backends (conversation branching, feedback storage) exist. */}
        </div>
      ) : null}
      {runInProgress ? <RunActivityLine events={message.events} active={pending || (runStreaming === true && runInProgress)} isAnsweredCard={isAnsweredCard}
        sending={runSending} /> : null}
  </>;
}

/** Stable empty list for a message with no attachments. */
const NO_ATTACHMENTS: readonly ChatAttachment[] = [];

/** The display props `MessageRow` defaults, resolved — what `AssistantMessageRow` renders from. */
type ResolvedMessageRowProps = MessageRowProps
  & Required<Pick<MessageRowProps, 'showUsageTotal' | 'showUsageLine' | 'toolCallDisplay' | 'showThinking' | 'runStreaming' | 'runSending' | 'runSucceeded' | 'questionFormInteractive'>>;

type AssistantBlock = MessageBlock<ToolTimelineRow>;

/**
 * Memoized so a transcript re-render (a streaming update to the newest message, or a parent that
 * re-renders per composer keystroke) only re-renders rows whose props actually changed. Messages
 * are replaced, never mutated, so identity is a sound change signal.
 */
export const MessageRow = memo(function MessageRow({
  showUsageTotal = true,
  showUsageLine = true,
  toolCallDisplay = 'show',
  showThinking = false,
  runStreaming = false,
  runSending = false,
  runSucceeded = false,
  questionFormInteractive = false,
  ...props
}: MessageRowProps) {
  const answerContexts = useSurfaceAnswerContexts({ events: props.message.events });
  const message = useMemo(() => props.message.events === undefined ? props.message : {
    ...props.message, events: projectAcceptedInputEvents({ events: props.message.events }, answerContexts),
  }, [props.message, answerContexts]);
  if (message.role === 'user') return <UserMessageRow {...props} message={message} />;
  return <AssistantMessageRow {...props} message={message} {...{ showUsageTotal, showUsageLine, toolCallDisplay, showThinking, runStreaming, runSending, runSucceeded, questionFormInteractive }} />;
});

function UserMessageRow({ message, renderAttachment }: Pick<MessageRowProps, 'message' | 'renderAttachment'>) {
  const t = useT();
  // Which attachment chip (if any) this row's preview modal is open for. Row-local, not
  // module-level: two attachments in the same message can never be "open" at once, but two
  // different messages opening their own attachments independently is fine and expected.
  // Previous/next steps through this message's images only.
  const gallery = useAttachmentGallery({ attachments: message.attachments ?? NO_ATTACHMENTS });
  return (
    <div
      className="jini-message jini-message-user"
      data-message-id={message.id}
      data-agent-element={`chat-message-${message.id}`}
      data-agent-role="region"
      data-agent-label="A message from the user"
    >
      {message.attachments && message.attachments.length > 0 ? (
        <div className="jini-message-attachments">
          {/* Images this browser still holds draw as thumbnails; everything else is a filename chip. */}
          {message.attachments.map((a) => (
            <SentAttachmentButton key={a.path} attachment={a} onOpen={gallery.open} renderAttachment={renderAttachment} />
          ))}
        </div>
      ) : null}
      <div className="jini-message-content">{message.content}</div>
      <div className="jini-message-actions jini-message-actions--user">
        <CopyMessageButton text={message.content} label={t('Copy message')} />
      </div>
      {gallery.opened ? (
        <AttachmentPreviewModal attachment={gallery.opened} onClose={gallery.close} navigation={gallery.navigation} />
      ) : null}
    </div>
  );
}

function AssistantMessageRow({
  message,
  usageSummary,
  showUsageTotal,
  showUsageLine,
  toolCallDisplay,
  showThinking,
  runStreaming,
  runSending,
  runSucceeded,
  questionFormInteractive,
  questionFormSubmittedAnswers,
  onQuestionFormSubmit,
  projectFileNames,
  onRequestOpenFile,
}: ResolvedMessageRowProps) {
  const registry = useExtEventRendererRegistry();
  const messageUsage = useMessageUsage({ message, ...(usageSummary === undefined ? {} : { summary: usageSummary }) });
  const timeline = useToolTimeline({ events: message.events }, { runStreaming, runSucceeded });
  const extGroups = useExtEventGroups({ events: message.events }, { slotOf: (name, data) => registry.slot({ name, data }) });
  const answeredCards = useAnsweredCards({ slotOf: registry.slot, events: message.events ?? [], groups: extGroups, runStreaming, runStatus: message.runStatus });

  const terminalNotice = terminalMessageNotice({ message }, {});
  const visibleContent = stripArtifact({ content: message.content });

  const displayBlocks = messageBlocks({ message, rows: timeline.rows, registry }, { toolCallDisplay, includeThinking: showThinking });
  // Artifact stripping trims/replaces text, invalidating the event offsets for rendering. Keep the
  // flat layout there; displayBlocks still supplies the recovery decision from the original events.
  const blocks = visibleContent === message.content ? displayBlocks : null;
  const pending = isPendingWithNoContent(message, visibleContent, timeline.rows.length);
  const runInProgress = isRunInProgress(message.runStatus);
  const awaitingAnswer = messageAwaitingAnswer({ runStreaming, runInProgress, events: message.events }, { isAnsweredCard: answeredCards.isAnsweredCard });
  const usage = usageLayout({ usage: messageUsage, interleaved: blocks !== null, runInProgress }, {
    runStreaming: runStreaming && !isTerminalRunStatus({ status: message.runStatus }),
  });
  const footerUsage = showUsageLine ? usage.footer : undefined;
  const lastFinishedReply = !runInProgress && !usage.footer ? usage.replies.findLastIndex(value => value !== undefined) : -1;

  const renderToolCard = (row: ToolTimelineRow) => (
    <ToolCard
      key={row.id}
      use={row.use}
      result={row.result}
      runStreaming={runStreaming}
      runSucceeded={runSucceeded}
      {...(projectFileNames !== undefined ? { projectFileNames } : {})}
      {...(onRequestOpenFile !== undefined ? { onRequestOpenFile } : {})}
    />
  );

  // Hidden mode reuses the same disclosure and card renderer for unrecovered failures.
  const renderTools = (rows: readonly ToolTimelineRow[], key?: string) => (toolCallDisplay !== 'show'
    ? <ToolCallGroup key={key} rows={rows} renderRow={renderToolCard} failureOnly={toolCallDisplay === 'hidden'} />
    : <div className="jini-message-tools" key={key}>{rows.map(renderToolCard)}</div>);
  const flatTools = flatToolGroups({ message, rows: timeline.rows, registry, displayBlocks }, { toolCallDisplay });
  const flatExtGroups = extGroups.filter(group => group.name !== MID_RUN_USER_MESSAGE_EXT_EVENT_NAME);

  const renderExtGroup = (group: ExtEventGroup) => {
    const transcriptRow = group.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME;
    const renderer = registry.get({ name: group.name });
    if (!renderer && group.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME) return <MidRunUserMessage key={group.slot} events={group.events} runStreaming={runInProgress} transcriptRow />;
    if (!renderer) return null;
    const answerText = answeredCards.answerText(group.slot);
    const node = renderer({
      name: group.name,
      events: group.events,
      runStreaming: group.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME ? runInProgress : answeredCards.runStreaming,
      ...(group.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME ? { transcriptRow: true } : {}),
      runSucceeded,
      awaitingAnswer,
      runId: message.runId,
      ...(group.call === undefined ? {} : { call: group.call }),
      answered: answeredCards.isAnswered(group.slot),
      onAnswered: () => answeredCards.markAnswered(group.slot),
      onAnswerText: (text) => answeredCards.markAnswered(group.slot, text),
      ...answerRenderProps({ answeredCards, slot: group.slot, answerText }),
    });
    if (!node) return null;
    return (
      // `key` includes the event count so a group that failed on an earlier, shorter event list
      // gets a fresh boundary instance (not the still-tripped one) once a new event actually
      // arrives for it, instead of staying tombstoned for the message's whole lifetime.
      <ExtEventErrorBoundary key={`${group.slot}:${group.events.length}`} name={group.name}>
        {transcriptRow ? node : <div>{node}</div>}
      </ExtEventErrorBoundary>
    );
  };

  const renderTextSegments = (text: string, keyPrefix: string): ReactNode =>
    splitOnQuestionForms({ input: text }).map((segment, i) =>
      segment.kind === 'text' ? (
        segment.text.trim() ? (
          <div className="jini-message-content" key={`${keyPrefix}-${i}`}>
            <Markdown>{segment.text}</Markdown>
          </div>
        ) : null
      ) : (
        <QuestionForm
          key={`${keyPrefix}-${i}`}
          form={segment.form}
          interactive={questionFormInteractive}
          {...(questionFormSubmittedAnswers !== undefined ? { submittedAnswers: questionFormSubmittedAnswers } : {})}
          {...(onQuestionFormSubmit !== undefined ? { onSubmit: onQuestionFormSubmit } : {})}
        />
      ),
    );

  const renderBlock = (block: AssistantBlock): ReactNode => {
    if (block.kind === 'text') {
      return <React.Fragment key={block.key}>{renderTextSegments(block.text, block.key)}</React.Fragment>;
    }
    if (block.kind === 'reply-end') {
      const reply = usage.replies[block.index];
      // A trailing input may have no reply: its predecessor's usage belongs above that input.
      return reply && showUsageLine ? <UsageSummary key={block.key} usage={reply} showTotal={showUsageTotal}
        {...(block.index === lastFinishedReply ? { message } : {})} /> : null;
    }
    if (block.kind === 'tools') return renderTools(block.rows, block.key);
    if (block.kind === 'thinking') return <ThinkingBlock key={block.key} text={block.text} />;
    return renderExtBlock(block);
  };

  // A mid-run bubble is its own transcript row, so it skips the ext-events wrapper and its spacing.
  const renderExtBlock = (block: Extract<AssistantBlock, { kind: 'ext' }>): ReactNode => {
    const group = extGroups.find((g) => g.slot === block.slot);
    if (!group) return null;
    if (group.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME) return <React.Fragment key={block.key}>{renderExtGroup(group)}</React.Fragment>;
    return (
      <div className="jini-message-ext-events" key={block.key}>
        {renderExtGroup(group)}
      </div>
    );
  };

  const renderAssistantSection = ({ section, key, footer }: {
    section: readonly AssistantBlock[] | null; key: string; footer: boolean;
  }) => (
    <div
      key={key}
      className={usageLineMeetsActions({ footer: footerUsage, terminalNotice, pending, runInProgress }, { showTotal: showUsageTotal })
        ? 'jini-message jini-message-assistant jini-message-assistant--usage-actions'
        : 'jini-message jini-message-assistant'}
      data-message-id={message.id}
      data-run-status={message.runStatus}
      data-agent-element={`chat-message-${message.id}`}
      data-agent-role="region"
      data-agent-label="A reply from the assistant"
    >
      {message.agentName ? <div className="jini-message-agent">{message.agentName}</div> : null}
      {section
        ? section.map(renderBlock)
        : (
          <>
            {renderTextSegments(visibleContent, 'text')}
            {flatTools.map((group) => renderTools(group.rows, group.key))}
            {flatExtGroups.length > 0 ? <div className="jini-message-ext-events">{flatExtGroups.map(renderExtGroup)}</div> : null}
          </>
        )}
      {footer && <AssistantMessageFooter {...{ message, usageEvent: footerUsage, showUsageTotal, terminalNotice, pending, runInProgress, runStreaming, runSending, visibleContent, isAnsweredCard: answeredCards.isAnsweredCard }} />}
    </div>
  );
  // The lossless fallback keeps the host's text intact; user receipts still own separate rows,
  // in their original receipt order, outside the assistant's actions and usage footer.
  if (blocks === null) return <>
    {renderAssistantSection({ section: null, key: message.id, footer: true })}
    {extGroups.filter(group => group.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME).map(renderExtGroup)}
  </>;
  // A reply boundary without reported usage renders nothing; it must not create an empty row's gap.
  const visibleBlocks = blocks.filter(block => block.kind !== 'reply-end' || (showUsageLine && usage.replies[block.index] !== undefined));
  const { sections, footerIndex } = transcriptSections({ blocks: visibleBlocks, runInProgress });
  return <>{sections.map((section, index) => isUserSection({ section })
    ? <React.Fragment key={section[0]!.key}>{section.map(renderBlock)}</React.Fragment>
    : renderAssistantSection({ section, key: section[0]?.key ?? message.id, footer: index === footerIndex }))}</>;
}

/** Preserve optional render-prop presence for custom extension renderers. */
function answerRenderProps({ answeredCards, slot, answerText }: {
  answeredCards: AnsweredCards; slot: string; answerText: string | undefined;
}, _options = {}) {
  return { ...(answeredCards.isRecorded(slot) ? { answerRecorded: true } : {}),
    ...(answerText === undefined ? {} : { answerText }) };
}

/** Place the one footer on the last assistant section, never below a completed trailing input. */
function transcriptSections({ blocks, runInProgress }: {
  blocks: readonly AssistantBlock[]; runInProgress: boolean;
}, _options = {}) {
  const sections = splitMidRunBlocks({ blocks });
  if (sections.length === 0) sections.push([]);
  // A live trailing input starts the next reply. A completed run needs no empty assistant row
  // (its actions/usage used to leave a large gap below the final user bubble).
  if (runInProgress && isUserSection({ section: sections.at(-1) })) sections.push([]);
  const footerIndex = sections.findLastIndex(section => !isUserSection({ section }));
  return { sections, footerIndex };
}

/** A user receipt occupies its own section; every other block belongs to an assistant row. */
function isUserSection({ section }: { section: readonly AssistantBlock[] | undefined }, _options = {}): boolean {
  const block = section?.[0];
  return block?.kind === 'ext' && block.name === MID_RUN_USER_MESSAGE_EXT_EVENT_NAME;
}

/**
 * The live "what is it doing" line under a running reply (see `core/run-activity.ts`). Replaces the
 * old "Thinking…" placeholder, which vanished for good as soon as the first tool row appeared.
 * Kept a separate component so its one-second tick re-renders only this line, not the whole row.
 */
function RunActivityLine({ events, active, isAnsweredCard, sending }: { events: AgentEvent[] | undefined; active: boolean; isAnsweredCard: IsAnsweredCard; sending: boolean }) {
  const t = useT();
  const activityLabel = useRunActivity({ events: events, active: active }, { isAnsweredCard });
  // Until the server accepts the start the turn is still on its way: "Thinking…" there read as the
  // model working while the text had not even arrived (owner, 2026-10-27). No timeout.
  const label = active && sending ? t('Sending…') : continuingRunNotice({ events, active }, {}) ?? activityLabel;
  if (label === null) return null;
  return (
    <div className="jini-message-pending jini-run-activity" aria-live="off">
      {label}
    </div>
  );
}

import { useMemo } from 'react';
import type { ChatMessage } from '../../core/messages.js';
import { terminalMessageNotice } from '../../core/durable-projection.js';
import { conversationUsage, type ChatUsageSummary } from '../../core/turn-usage.js';
import { formatUsageCost } from '../../core/usage-format.js';
import { useI18n } from '../hooks/context.js';

/** A run's terminal state wins over its last model response; interrupted usage never claims success.
 * Missing lifecycle data keeps the legacy completed label. O(n) in terminal notice events. */
export function usageEndLabel(
  { usage, message, awaitingAnswer = false }: { usage: ChatUsageSummary; message?: ChatMessage; awaitingAnswer?: boolean }, _options = {},
): string {
  const status = message?.runStatus;
  if (status === 'failed') return 'Failed';
  if (status === 'canceled') {
    return canceledUsageLabel({ message: message! });
  }
  if (awaitingAnswer) return 'Waiting for your answer';
  const reason = usage.stopReason ?? '';
  if (/error|fail/i.test(reason)) return 'Failed';
  return /abort|interrupt|cancel|max_tokens|max_tool_turns|length|tool_use/i.test(reason) ? 'Interrupted' : 'Done';
}

function canceledUsageLabel({ message }: { message: ChatMessage }, _options = {}): string {
  return /stopped/i.test(terminalMessageNotice({ message }) ?? '') ? 'Stopped' : 'Canceled';
}

/** A standalone row has one turn; MessageList supplies the full conversation projection. */
export function useMessageUsage({ message, summary }: { message: ChatMessage; summary?: ChatUsageSummary }, _optional = {}): ChatUsageSummary | undefined {
  return useMemo(() => summary ?? conversationUsage({ messages: [message] }).get(message.id), [message, summary]);
}

/** Which "Done" lines a message shows. Each finished reply gets its own line where it ends; the reply
 * still running gets none, so a stale line never sits above live work (owner, 2026-10-10). Per-reply
 * lines need the ordered block layout to know where a reply ends; the flat fallback keeps one
 * whole-message line under the message once the run is over. A row still streaming counts as running
 * even when its `runStatus` was never set, so the previous reply's line cannot slide down under the
 * live tool rows above "Running …" (owner bug, 2026-10-10). O(r) for r replies.
 * @example usageLayout({ usage, interleaved: true, runInProgress: true }).footer // undefined */
export function usageLayout(
  { usage, interleaved, runInProgress }: { usage: ChatUsageSummary | undefined; interleaved: boolean; runInProgress: boolean },
  { runStreaming = false }: { runStreaming?: boolean } = {},
): { footer: ChatUsageSummary | undefined; replies: readonly (ChatUsageSummary | undefined)[] } {
  const segments = interleaved ? usage?.segments : undefined;
  const last = segments ? segments.at(-1) : usage;
  return { footer: runInProgress || runStreaming ? undefined : last, replies: segments ? segments.slice(0, -1) : [] };
}

/** Whether the footer's "Done" line renders directly above the copy row: a finished turn with a
 * non-empty usage line and no notice between them. Rows get a modifier class from this so a host can
 * lay the two out on one line with a plain class selector — a `:has(> usage + actions)` selector made
 * every keystroke restyle the whole page in long chats (2026-10-11). O(1).
 * @example usageLineMeetsActions({ footer: { kind: 'usage', costUsd: 0.1 }, terminalNotice: null, pending: false, runInProgress: false }) // true */
export function usageLineMeetsActions(
  { footer, terminalNotice, pending, runInProgress }: { footer: ChatUsageSummary | undefined; terminalNotice: string | null; pending: boolean; runInProgress: boolean },
  { showTotal = true }: { showTotal?: boolean } = {},
): boolean {
  const hasText = footer !== undefined && (footer.durationMs !== undefined || footer.costUsd !== undefined || (showTotal && footer.totalCostUsd !== undefined));
  return hasText && !terminalNotice && !pending && !runInProgress;
}

/** Build footer display values outside JSX; token counts remain available in the tooltip and accessible footer label.
 * Each line carries the chat's running total as of that reply, "Done · 16s · $0.39 · total $3.95" (owner,
 * 2026-10-10: keep the total, always shown, even on the first turn). Known totals remain visible when
 * the current turn's cost is unknown. `showTotal: false` turns the total off. */
export function useUsageSummary({ usage }: { usage: ChatUsageSummary }, { showTotal = true, label = 'Done' }: { showTotal?: boolean; label?: string } = {}) {
  const { t, locale } = useI18n();
  const parts = [usageDuration({ durationMs: usage.durationMs }), usageCost({ usage }, { showTotal })]
    .filter((part): part is string => part !== undefined);
  const text = parts.join(' · ');
  const title = usage.outputTokens === undefined ? undefined : t('{n} output tokens', { n: usage.outputTokens.toLocaleString(locale) });
  return { text, title, ariaLabel: title === undefined ? undefined : `${t(label)} · ${text} · ${title}` };
}

function usageDuration({ durationMs }: { durationMs: number | undefined }, _options = {}): string | undefined {
  if (durationMs === undefined) return undefined;
  const seconds = Math.round(durationMs / 1000);
  return seconds >= 60 ? `${Math.floor(seconds / 60)}m ${seconds % 60}s` : `${seconds}s`;
}

function usageCost({ usage }: { usage: ChatUsageSummary }, { showTotal = true }: { showTotal?: boolean } = {}): string | undefined {
  if (usage.costUsd !== undefined) {
    return formatUsageCost({ costUsd: usage.costUsd, ...(showTotal ? { totalCostUsd: usage.totalCostUsd ?? usage.costUsd } : {}) });
  }
  if (showTotal && usage.totalCostUsd !== undefined) return `total ${formatUsageCost({ costUsd: usage.totalCostUsd })}`;
  return undefined;
}

import { CREDENTIAL_CARD_GUIDANCE, SECRET_REDACTED_NOTICE, type UserTextRedactionOptions } from '../../core/user-text-redaction.js';
import { useUserTextGuard } from '../hooks/useUserTextGuard.js';
/**
 * @module QuestionForm
 *
 * Renders one parsed `<question-form>` as an interactive (or locked/
 * answered) set of controls. Ported from OD's `components/QuestionForm.tsx`
 * (verified 0 OD product references — the file only imports React,
 * `useT()`, and its own question-form types) against `@jini-ai/chat/core`'s
 * `QuestionForm`/`FormQuestion`/`FormOption`/`DirectionCard`/
 * `formatFormAnswers` (the same shapes, lifted verbatim into chat-core
 * already). className/structure kept verbatim (`question-form`/`qf-*`
 * classes — unstyled semantic markup, host supplies CSS); every user-facing
 * string wrapped in `useT()`.
 */
import { forwardRef, useEffect, useImperativeHandle, useMemo, useState, type ChangeEvent, type CSSProperties, type ReactNode } from 'react';
import type { DirectionCard, FormOption, QuestionForm as QuestionFormType } from '../../core/index.js';
import { formatFormAnswers, formOptionValueForLabel, redactQuestionAnswers, isSecretQuestion, withoutSecretQuestionDefaults, questionTextInputProps, questionTextareaProps } from '../../core/index.js';
import { useT } from '../hooks/context.js';
import { SecretInput, SecretTextarea } from '@jini-ai/ui';

export interface QuestionFormFileSubmission {
  questionId: string;
  questionLabel: string;
  files: File[];
}

export interface QuestionFormHandle {
  submit: () => void;
  /** Submit with no answers — every question is optional, so this records each as "(skipped)" and moves on. */
  skipAll: () => void;
}

export interface QuestionFormProps extends UserTextRedactionOptions {
  form: QuestionFormType;
  /** Whether the user can still submit answers — the host disables this once the turn is no longer the most recent one. */
  interactive: boolean;
  submittedAnswers?: Record<string, string | string[]>;
  /** When a host's own Continue button owns the submit, hide this form's footer button and report ready-state via `onReadyChange`. */
  hideInternalSubmit?: boolean;
  draftAnswers?: Record<string, string | string[]>;
  onReadyChange?: (ready: boolean) => void;
  onDraftChange?: (answers: Record<string, string | string[]>) => void;
  onAnswerChange?: (questionId: string, value: string | string[]) => void;
  onSubmit?: (text: string, answers: Record<string, string | string[]>, files?: QuestionFormFileSubmission[]) => void;
}

export const QuestionForm = forwardRef<QuestionFormHandle, QuestionFormProps>(function QuestionForm(
  { form: incomingForm, interactive, submittedAnswers, hideInternalSubmit = false, draftAnswers, onReadyChange, onDraftChange, onAnswerChange, onSubmit, redactUserText, onSecretRedacted },
  ref,
) {
  const t = useT();
  const form = useMemo(() => withoutSecretQuestionDefaults({ form: incomingForm }), [incomingForm]);
  const guard = useUserTextGuard({ ...(redactUserText ? { redactUserText } : {}), ...(onSecretRedacted ? { onSecretRedacted } : {}) });
  const locked = !interactive || !onSubmit || submittedAnswers !== undefined;
  const state = useQuestionAnswers({ form, submittedAnswers, draftAnswers, locked }, { onDraftChange, onAnswerChange });
  const currentAnswers = submittedAnswers ? redactQuestionAnswers({ form, answers: submittedAnswers }).answers : state.answers;
  const ready = answersReady(form, currentAnswers);

  function handleSubmit() {
    if (locked || !onSubmit) return;
    if (!ready) return;
    const safe = redactQuestionAnswers({ form, answers: state.answers }, { ...(redactUserText ? { redactUserText } : {}), onSecretRedacted: guard.notifyRedaction });
    state.setAnswers(safe.answers);
    const files = collectFileSubmissions(form, state.fileAnswers);
    if (files.length > 0) onSubmit(formatFormAnswers({ form: form, answers: safe.answers }), safe.answers, files);
    else onSubmit(formatFormAnswers({ form: form, answers: safe.answers }), safe.answers);
  }

  function handleSkipAll() {
    if (locked || !onSubmit) return;
    const empty: Record<string, string | string[]> = {};
    onSubmit(formatFormAnswers({ form: form, answers: empty }), empty);
  }

  useImperativeHandle(ref, () => ({ submit: handleSubmit, skipAll: handleSkipAll }));
  useEffect(() => {
    onReadyChange?.(!locked && ready);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onReadyChange, locked, ready]);

  return (
    <div className={`question-form${locked ? ' question-form-locked' : ''}`} data-form-id={form.id}>
      <QuestionFormHead form={form} locked={locked} />
      <div className="question-form-body">
        {form.questions.map((q) => (
          <QuestionField key={q.id} q={q} value={currentAnswers[q.id]} formId={form.id} locked={locked} t={t} {...state.handlers} />
        ))}
      </div>
      {guard.secretRedacted ? <div role="status">{t(SECRET_REDACTED_NOTICE)}</div> : null}
      {hideInternalSubmit ? null : <QuestionFormFoot locked={locked} answered={submittedAnswers !== undefined} ready={ready} submitLabel={form.submitLabel} onSubmit={handleSubmit} />}
    </div>
  );
});

type Question = QuestionFormType['questions'][number];
type Answers = Record<string, string | string[]>;

/** Owns the editable answers plus the picked files; every edit is a no-op once the form is locked. */
function useQuestionAnswers(
  { form, submittedAnswers, draftAnswers, locked }: { form: QuestionFormType; submittedAnswers: Answers | undefined; draftAnswers: Answers | undefined; locked: boolean },
  { onDraftChange, onAnswerChange }: { onDraftChange?: QuestionFormProps['onDraftChange'] | undefined; onAnswerChange?: QuestionFormProps['onAnswerChange'] | undefined } = {},
) {
  const initial = useMemo(() => buildInitialState(form, submittedAnswers, draftAnswers), [form, submittedAnswers, draftAnswers]);
  const [answers, setAnswers] = useState<Answers>(initial);
  const [fileAnswers, setFileAnswers] = useState<Record<string, File[]>>({});

  useEffect(() => {
    setFileAnswers({});
  }, [form.id]);

  useEffect(() => {
    setAnswers((prev) => backfillAnswers(prev, form, submittedAnswers));
  }, [form, submittedAnswers]);

  function update(id: string, value: string | string[]) {
    if (locked) return;
    const next = { ...answers, [id]: value };
    setAnswers(next);
    onDraftChange?.(redactQuestionAnswers({ form, answers: draftSafeAnswers(form, next) }).answers);
    onAnswerChange?.(id, redactQuestionAnswers({ form, answers: { [id]: value } }).answers[id]!);
  }

  function toggleCheckbox(id: string, option: string, maxSelections?: number) {
    if (locked) return;
    const current = Array.isArray(answers[id]) ? (answers[id] as string[]) : [];
    const has = current.includes(option);
    if (!has && maxSelections !== undefined && current.length >= maxSelections) return;
    const next = has ? current.filter((v) => v !== option) : [...current, option];
    const nextAnswers = { ...answers, [id]: next };
    setAnswers(nextAnswers);
    onDraftChange?.(redactQuestionAnswers({ form, answers: draftSafeAnswers(form, nextAnswers) }).answers);
    onAnswerChange?.(id, next);
  }

  function updateCheckboxCustom(q: Question, raw: string) {
    if (locked) return;
    const current = Array.isArray(answers[q.id]) ? (answers[q.id] as string[]) : [];
    const fixed = current.filter((entry) => questionValueIsKnown(q, entry));
    update(q.id, [...fixed, ...splitCustomEntries(raw)]);
  }

  function selectFiles(q: Question, list: FileList | null) {
    const files = Array.from(list ?? []);
    const names = files.map((file) => file.name);
    setFileAnswers((current) => ({ ...current, [q.id]: files }));
    update(q.id, q.multiple ? names : (names[0] ?? ''));
  }

  return { answers, setAnswers, fileAnswers, handlers: { update, toggleCheckbox, updateCheckboxCustom, selectFiles } };
}

function answersReady(form: QuestionFormType, answers: Answers): boolean {
  const withinSelectionLimits = form.questions.every((q) => {
    if (q.type !== 'checkbox' || q.maxSelections === undefined) return true;
    const v = answers[q.id];
    return !Array.isArray(v) || v.length <= q.maxSelections;
  });
  const requiredAnswered = form.questions.every((q) => {
    if (q.required !== true) return true;
    const v = answers[q.id];
    if (Array.isArray(v)) return v.length > 0;
    return typeof v === 'string' && v.trim().length > 0;
  });
  return withinSelectionLimits && requiredAnswered;
}

function QuestionFormHead({ form, locked }: { form: QuestionFormType; locked: boolean }) {
  const t = useT();
  return (
    <div className="question-form-head">
      <span className="question-form-icon" aria-hidden>
        ?
      </span>
      <div className="question-form-titles">
        <div className="question-form-title">{form.title}</div>
        {form.description ? <div className="question-form-desc">{form.description}</div> : null}
      </div>
      {locked ? <span className="question-form-pill">{t('Answered')}</span> : null}
    </div>
  );
}

function QuestionFormFoot({ locked, answered, ready, submitLabel, onSubmit }: { locked: boolean; answered: boolean; ready: boolean; submitLabel: string | undefined; onSubmit: () => void }) {
  const t = useT();
  return (
    <div className="question-form-foot">
      {locked ? <span className="qf-locked-note">{answered ? t('You answered this') : t('A newer message answered this')}</span> : <span className="qf-hint">{t('Answer above, then continue')}</span>}
      {!locked ? (
        <button type="button" className="primary" onClick={onSubmit} disabled={!ready} title={ready ? t('Submit your answers') : t('Answer the required questions first')}>
          {submitLabel ?? t('Continue')}
        </button>
      ) : null}
    </div>
  );
}

/** Everything one question's control needs: its value plus the form-level edit handlers. */
type FieldHandlers = ReturnType<typeof useQuestionAnswers>['handlers'];
interface FieldContext extends FieldHandlers {
  q: Question;
  value: string | string[] | undefined;
  formId: string;
  locked: boolean;
  t: ReturnType<typeof useT>;
}

function QuestionField(ctx: FieldContext) {
  const { q, t } = ctx;
  const renderControl = QUESTION_CONTROLS[q.type];
  return (
    <div className="qf-field">
      <label className="qf-label">
        <span>{q.label}</span>
        {q.required ? (
          <span className="qf-required" aria-label={t('required')}>
            *
          </span>
        ) : null}
      </label>
      {q.help ? <div className="qf-help">{q.help}</div> : null}
      {isSecretQuestion({ question: q }) ? <div className="qf-help">{t(CREDENTIAL_CARD_GUIDANCE)}</div> : null}
      {renderControl ? renderControl(ctx) : null}
    </div>
  );
}

function stringValue(value: string | string[] | undefined): string {
  return typeof value === 'string' ? value : '';
}

/** A range with no usable answer yet (e.g. mid-stream) shows its minimum, matching `emptyQuestionValue`. */
function rangeValue(q: Question, value: string | string[] | undefined): string {
  return typeof value === 'string' && value.trim() ? value : String(q.min ?? 0);
}

function customChoice({ q, t, locked }: FieldContext, value: string, onChange: (next: string) => void) {
  if (!shouldRenderCustomChoice(q)) return null;
  return <CustomChoiceInput label={q.customLabel ?? t('Something else')} value={value} placeholder={q.customPlaceholder ?? t('Type your own answer')} disabled={locked} onChange={onChange} />;
}

function singleCustomChoice(ctx: FieldContext) {
  return customChoice(ctx, customSingleValue(ctx.q, ctx.value), (next) => ctx.update(ctx.q.id, next));
}

function RadioControl(ctx: FieldContext) {
  const { q, value, formId, locked, update } = ctx;
  if (!q.options) return null;
  return (
    <>
      <div className="qf-options">
        {q.options.map((opt) => (
          <label key={opt.value} className={`qf-chip${value === opt.value ? ' qf-chip-on' : ''}`} title={opt.description}>
            <input type="radio" name={`${formId}-${q.id}`} value={opt.value} checked={value === opt.value} disabled={locked} aria-label={opt.label} onChange={() => update(q.id, opt.value)} />
            <OptionCopy option={opt} />
          </label>
        ))}
      </div>
      {singleCustomChoice(ctx)}
    </>
  );
}

function CheckboxControl(ctx: FieldContext) {
  const { q, value, locked, toggleCheckbox, updateCheckboxCustom } = ctx;
  if (!q.options) return null;
  const arr = Array.isArray(value) ? value : [];
  return (
    <>
      <div className="qf-options">
        {q.options.map((opt) => {
          const on = arr.includes(opt.value);
          const maxed = q.maxSelections !== undefined && !on && arr.length >= q.maxSelections;
          return (
            <label key={opt.value} title={opt.description} className={`qf-chip${on ? ' qf-chip-on' : ''}${maxed ? ' qf-chip-disabled' : ''}`}>
              <input type="checkbox" value={opt.value} checked={on} disabled={locked || maxed} aria-label={opt.label} onChange={() => toggleCheckbox(q.id, opt.value, q.maxSelections)} />
              <OptionCopy option={opt} />
            </label>
          );
        })}
      </div>
      {customChoice(ctx, customCheckboxValue(q, value), (next) => updateCheckboxCustom(q, next))}
    </>
  );
}

function SelectControl(ctx: FieldContext) {
  const { q, value, locked, t, update } = ctx;
  if (!q.options) return null;
  return (
    <>
      <select className="qf-select" value={typeof value === 'string' && questionValueIsKnown(q, value) ? value : ''} disabled={locked} onChange={(e) => update(q.id, e.target.value)}>
        <option value="" disabled>
          {q.placeholder ?? t('Choose one')}
        </option>
        {q.options.map((opt) => (
          <option key={opt.value} value={opt.value} title={opt.description}>
            {opt.label}
          </option>
        ))}
      </select>
      {singleCustomChoice(ctx)}
    </>
  );
}

function DirectionCardsControl(ctx: FieldContext) {
  const { q, value, formId, locked, update } = ctx;
  if (!q.cards || q.cards.length === 0) return null;
  return (
    <>
      <div className="qf-direction-cards">
        {q.cards.map((card) => (
          <DirectionCardView key={card.id} card={card} formId={formId} questionId={q.id} selected={value === card.id || value === card.label} disabled={locked} onSelect={() => update(q.id, card.id)} />
        ))}
      </div>
      {singleCustomChoice(ctx)}
    </>
  );
}

/** A credential-shaped text question gets the shared eye toggle (hidden by default). */
function TextControl({ q, value, locked, update, t }: FieldContext) {
  const shared = { className: 'qf-input', value: stringValue(value), placeholder: q.placeholder, disabled: locked, onChange: (e: ChangeEvent<HTMLInputElement>) => update(q.id, e.target.value) };
  const props = questionTextInputProps({ question: q });
  if (props.type === 'password') {
    const { type: _type, ...secretProps } = props;
    return <SecretInput {...secretProps} {...shared} aria-label={q.label} label={q.label} toggleLabels={{ show: `${t('Show')} ${q.label}`, hide: `${t('Hide')} ${q.label}` }} />;
  }
  return <input {...props} {...shared} />;
}

/** A credential-shaped textarea gets the same eye toggle; `SecretTextarea` owns the masking style. */
function TextareaControl({ q, value, locked, update, t }: FieldContext) {
  const shared = { className: 'qf-textarea', value: stringValue(value), placeholder: q.placeholder, disabled: locked, rows: 3, onChange: (e: ChangeEvent<HTMLTextAreaElement>) => update(q.id, e.target.value) };
  const props = questionTextareaProps({ question: q });
  if (isSecretQuestion({ question: q })) {
    return <SecretTextarea {...props} {...shared} aria-label={q.label} label={q.label} toggleLabels={{ show: `${t('Show')} ${q.label}`, hide: `${t('Hide')} ${q.label}` }} />;
  }
  return <textarea {...props} {...shared} />;
}

/** date/time/datetime-local and url/email/tel share one plain input whose `type` is the question type. */
function TypedInputControl({ q, value, locked, update }: FieldContext) {
  return <input type={q.type} className="qf-input" value={stringValue(value)} placeholder={q.placeholder} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />;
}

const QUESTION_CONTROLS: Record<Question['type'], (ctx: FieldContext) => ReactNode> = {
  radio: RadioControl,
  checkbox: CheckboxControl,
  select: SelectControl,
  'direction-cards': DirectionCardsControl,
  text: TextControl,
  number: ({ q, value, locked, update }) => <input type="number" className="qf-input" value={stringValue(value)} placeholder={q.placeholder} min={q.min} max={q.max} step={q.step} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />,
  range: ({ q, value, locked, update }) => (
    <div className="qf-range-wrap">
      <input type="range" className="qf-range" value={rangeValue(q, value)} min={q.min} max={q.max} step={q.step} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />
      <output className="qf-range-value">{rangeValue(q, value)}</output>
    </div>
  ),
  date: TypedInputControl,
  time: TypedInputControl,
  'datetime-local': TypedInputControl,
  url: TypedInputControl,
  email: TypedInputControl,
  tel: TypedInputControl,
  color: ({ q, value, locked, update }) => <input type="color" className="qf-color" value={normalizeColorInputValue(value)} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />,
  file: ({ q, value, locked, selectFiles }) => (
    <div className="qf-file-wrap">
      <input type="file" className="qf-file" multiple={q.multiple} accept={q.accept} disabled={locked} onChange={(e) => selectFiles(q, e.target.files)} />
      {fileValueLabel(value) ? <div className="qf-file-summary">{fileValueLabel(value)}</div> : null}
    </div>
  ),
  switch: ({ q, value, locked, update }) => (
    <label className="qf-switch">
      <input type="checkbox" role="switch" checked={value === 'true'} disabled={locked} onChange={(e) => update(q.id, e.target.checked ? 'true' : 'false')} />
      <span aria-hidden />
    </label>
  ),
  textarea: TextareaControl,
};

function OptionCopy({ option }: { option: FormOption }) {
  return (
    <span className="qf-chip-copy">
      <span>{option.label}</span>
      {option.description ? <span className="qf-chip-desc">{option.description}</span> : null}
    </span>
  );
}

function CustomChoiceInput({ label, value, placeholder, disabled, onChange }: { label: string; value: string; placeholder: string; disabled: boolean; onChange: (value: string) => void }) {
  const chars = customInputCharCount(value, placeholder);
  return (
    <label className="qf-custom">
      <span>{label}</span>
      <input type="text" className="qf-input" value={value} placeholder={placeholder} disabled={disabled} style={{ '--qf-custom-chars': String(chars) } as CSSProperties} onChange={(event) => onChange(event.target.value)} />
    </label>
  );
}

function DirectionCardView({ card, formId, questionId, selected, disabled, onSelect }: { card: DirectionCard; formId: string; questionId: string; selected: boolean; disabled: boolean; onSelect: () => void }) {
  const t = useT();
  return (
    <label className={`qf-card${selected ? ' qf-card-on' : ''}${disabled ? ' qf-card-disabled' : ''}`}>
      <input type="radio" name={`${formId}-${questionId}`} value={card.id} checked={selected} disabled={disabled} onChange={() => onSelect()} />
      <div className="qf-card-head">
        <div className="qf-card-title">{card.label}</div>
        {selected ? <span className="qf-card-pill">{t('Selected')}</span> : null}
      </div>
      {card.palette.length > 0 ? (
        <div className="qf-card-swatches" aria-hidden>
          {card.palette.slice(0, 6).map((c, i) => (
            <span key={i} className="qf-card-swatch" style={{ background: c }} title={c} />
          ))}
        </div>
      ) : null}
      <div className="qf-card-types" aria-hidden>
        <span className="qf-card-type-display" style={{ fontFamily: card.displayFont }}>
          Aa
        </span>
        <span className="qf-card-type-body" style={{ fontFamily: card.bodyFont }}>
          {t('The quick brown fox')}
        </span>
      </div>
      {card.mood ? <p className="qf-card-mood">{card.mood}</p> : null}
      {card.references.length > 0 ? (
        <p className="qf-card-refs">
          <span className="qf-card-refs-label">{t('References:')}</span> {card.references.slice(0, 4).join(' · ')}
        </p>
      ) : null}
    </label>
  );
}

function buildInitialState(form: QuestionFormType, submitted: Answers | undefined, draft: Answers | undefined): Answers {
  const out: Answers = {};
  for (const q of form.questions) out[q.id] = initialQuestionValue(q, submitted, draft);
  return out;
}

/** Submitted beats draft beats default beats empty; file drafts are never restored (the File objects are gone). */
function initialQuestionValue(q: Question, submitted: Answers | undefined, draft: Answers | undefined): string | string[] {
  if (submitted?.[q.id] !== undefined) return canonicalizeQuestionValue(q, submitted[q.id]!);
  if (draft?.[q.id] !== undefined && q.type !== 'file') return canonicalizeQuestionValue(q, draft[q.id]!);
  if (q.defaultValue !== undefined) return canonicalizeQuestionValue(q, q.defaultValue);
  return emptyQuestionValue(q);
}

/** Questions that stream in after mount get their initial value; answers already set are kept. */
function backfillAnswers(prev: Answers, form: QuestionFormType, submitted: Answers | undefined): Answers {
  let changed = false;
  const next = { ...prev };
  for (const q of form.questions) {
    if (next[q.id] !== undefined) continue;
    changed = true;
    next[q.id] = initialQuestionValue(q, submitted, undefined);
  }
  return changed ? next : prev;
}

function draftSafeAnswers(form: QuestionFormType, answers: Record<string, string | string[]>): Record<string, string | string[]> {
  const fileQuestionIds = new Set(form.questions.filter((q) => q.type === 'file').map((q) => q.id));
  if (fileQuestionIds.size === 0) return answers;
  const out: Record<string, string | string[]> = {};
  for (const [id, value] of Object.entries(answers)) {
    if (!fileQuestionIds.has(id)) out[id] = value;
  }
  return out;
}

function collectFileSubmissions(form: QuestionFormType, fileAnswers: Record<string, File[]>): QuestionFormFileSubmission[] {
  const out: QuestionFormFileSubmission[] = [];
  for (const q of form.questions) {
    if (q.type !== 'file') continue;
    const files = fileAnswers[q.id] ?? [];
    if (files.length === 0) continue;
    out.push({ questionId: q.id, questionLabel: q.label, files });
  }
  return out;
}

function emptyQuestionValue(q: QuestionFormType['questions'][number]): string | string[] {
  if (q.type === 'checkbox') return [];
  if (q.type === 'switch') return 'false';
  if (q.type === 'range') return String(q.min ?? 0);
  if (q.type === 'color') return normalizeColorInputValue('');
  return '';
}

function canonicalizeQuestionValue(q: QuestionFormType['questions'][number], value: string | string[]): string | string[] {
  if (Array.isArray(value)) return value.map((entry) => formOptionValueForLabel({ question: q, labelOrValue: entry }));
  return formOptionValueForLabel({ question: q, labelOrValue: value });
}

function shouldRenderCustomChoice(q: QuestionFormType['questions'][number]): boolean {
  return q.allowCustom !== false;
}

function questionValueIsKnown(q: QuestionFormType['questions'][number], value: string): boolean {
  if (q.options?.some((option) => option.value === value || option.label === value)) return true;
  if (q.cards?.some((card) => card.id === value || card.label === value)) return true;
  return false;
}

function customSingleValue(q: QuestionFormType['questions'][number], value: string | string[] | undefined): string {
  if (typeof value !== 'string' || value.length === 0) return '';
  return questionValueIsKnown(q, value) ? '' : value;
}

function customCheckboxValue(q: QuestionFormType['questions'][number], value: string | string[] | undefined): string {
  if (!Array.isArray(value)) return '';
  return value.filter((entry) => !questionValueIsKnown(q, entry)).join(', ');
}

function splitCustomEntries(raw: string): string[] {
  return raw
    .split(/[\n,]/)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function customInputCharCount(value: string, placeholder: string): number {
  const base = value.length > 0 ? value.length : Math.min(placeholder.length, 22);
  return Math.max(18, Math.min(base + 2, 72));
}

function normalizeColorInputValue(value: string | string[] | undefined): string {
  if (typeof value === 'string' && /^#[0-9a-fA-F]{6}$/.test(value)) return value;
  return '#000000';
}

function fileValueLabel(value: string | string[] | undefined): string {
  if (Array.isArray(value)) return value.join(', ');
  return typeof value === 'string' ? value : '';
}

import type { ReactNode } from 'react';
import type { ChatAttachment } from '../../core/index.js';
import { useT } from '../hooks/context.js';
import { useSentAttachmentThumbnail, type ObjectUrlPort } from './SentAttachment.hooks.js';

export interface SentAttachmentButtonProps {
  attachment: ChatAttachment;
  /** Opens the row's preview modal for this attachment. */
  onOpen: (attachment: ChatAttachment) => void;
  /** Host-supplied chip content; when given it wins over the built-in thumbnail/filename. */
  renderAttachment?: ((attachment: ChatAttachment) => ReactNode) | undefined;
  /** Blob-URL port for the thumbnail; defaults to the platform's (see `SentAttachment.hooks.ts`). */
  objectUrls?: ObjectUrlPort | undefined;
}

/**
 * One attachment on a sent user message: a small image thumbnail when this browser still holds the
 * image's bytes, otherwise the filename chip. Either way a click opens the preview modal, and the
 * accessible name stays "Open {name}".
 */
export function SentAttachmentButton({ attachment, onOpen, renderAttachment, objectUrls }: SentAttachmentButtonProps) {
  const t = useT();
  const { thumbnailUrl, onThumbnailError } = useSentAttachmentThumbnail(
    { attachment, hostRendered: renderAttachment !== undefined },
    objectUrls === undefined ? {} : { objectUrls },
  );
  return (
    <button
      type="button"
      className={`jini-message-attachment-chip${thumbnailUrl ? ' is-thumbnail' : ''}`}
      onClick={() => onOpen(attachment)}
      title={t('Open {name}', { name: attachment.name })}
      aria-label={t('Open {name}', { name: attachment.name })}
