/**
 * The one row shell every card shares: a real `<button>` head (Enter/Space toggle it) that reports
 * `aria-expanded` and points `aria-controls` at its panel. The panel's `children` mount only while
 * open: a long chat mounts hundreds of collapsed rows, and keeping every full detail mounted made a
 * 38-message chat carry ~13k DOM nodes and 3.45 MB of hidden text. Collapsed, the panel holds one
 * hidden node with the call's capped gist instead, so a `page.*` DOM reader still sees what was
 * called and what came back through `textContent` without anyone clicking.
 * `after` renders outside the panel, for content that must stay visible collapsed (an error, media).
 */
function ExpandableCard({ className, head, after, call, children }: { className: string; head: ReactNode; after?: ReactNode; call: CardProps; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const panelId = useId();
  return (
    <div className={`op-card ${className}`}>
      <button type="button" className="op-card-head" aria-expanded={open} aria-controls={panelId} onClick={() => setOpen((o) => !o)}>
        {head}
        <span className="op-expand-chev" aria-hidden>
          <Icon name={open ? 'chevron-down' : 'chevron-right'} size={11} />
        </span>
      </button>
      <div id={panelId} className={`accordion-collapsible${open ? ' open' : ''}`}>
        {open ? <div className="accordion-collapsible-inner">{children}</div> : <CollapsedReaderText call={call} />}
      </div>
      {after}
    </div>
  );
}

/** The collapsed row's stand-in for its panel — see {@link ExpandableCard} and `describeCollapsedToolCall`. */
function CollapsedReaderText({ call }: { call: CardProps }) {
  const text = describeCollapsedToolCall({ input: call.input, result: call.result }, { runStreaming: call.runStreaming, runSucceeded: call.runSucceeded });
  return <span className="op-card-reader-text" hidden>{text}</span>;
}

/** The call's input, its result (or why there is none), and any extra `children` — see `describeToolCallDetail` for the redaction and formatting rules. */
function ToolCallDetail({ input, result, runStreaming, runSucceeded, children }: CardProps & { children?: ReactNode }) {
  const t = useT();
  // Only mounted on expansion: keep the compact preview cheap without losing any of the stored
  // call when the person opens it. The core formatter still owns formatting and secret redaction.
  const detail = describeToolCallDetail({ input: input, result: result }, { runStreaming: runStreaming, runSucceeded: runSucceeded, maxChars: Infinity });
  return (
    <div className="op-card-detail">
      {detail.inputText !== null ? <pre className="op-command op-input">{detail.inputText}</pre> : null}
      {detail.outputText !== null ? <pre className="op-output">{detail.outputText}</pre> : null}
      {detail.noteKey !== null ? <p className="op-detail-note">{t(detail.noteKey)}</p> : null}
      {children}
    </div>
  );
}

function ResultBadge({ result, runStreaming, runSucceeded }: { result?: ToolResultEvent | undefined; runStreaming: boolean; runSucceeded: boolean }) {
  const t = useT();
  if (!result && runStreaming)
    return (
      <span className="op-status op-status-running" title={t('Running')}>
        <Icon name="spinner" size={14} />
      </span>
    );
  if (!result && !runSucceeded)
    return (
      <span className="op-status op-status-error" title={t('Error')}>
        <Icon name="close" size={14} />
      </span>
    );
  if (result?.isError)
    return (
      <span className="op-status op-status-error" title={describeToolCallDetail({ input: null, result }, { maxChars: COLLAPSED_DETAIL_MAX_CHARS }).outputText ?? t('Error')}>
        <Icon name="close" size={14} />
      </span>
    );
  return (
    <span className="op-status op-status-ok" title={t('Done')}>
      <Icon name="check" size={14} />
    </span>
  );
}

/**
 * Renders the `image` blocks a tool result's `media` field carries — the one media type this slice
 * proves end to end (`ToolResultMediaBlock`'s `text` arm is never collected into `media` in the
 * first place; see `@jini-ai/daemon`'s `tool-result-media.ts`, so there is nothing to render for
 * it). `null` for the overwhelming majority of results, which carry no `media` at all — every
 * existing card that renders this stays visually unchanged.
 *
 * Styled only with an inline `max-width` safety net, not a class-driven layout: this package ships
 * unstyled semantic markup (this module's own header) and a host supplies CSS via `.op-media`/
 * `.op-media-image`. Without the inline rule, a handler-supplied image at its native pixel size
 * could blow out the card's width before any host stylesheet loads.
 */
function ToolResultMedia({ result }: { result?: ToolResultEvent | undefined }) {
  const blocks = result?.media;
  if (!blocks || blocks.length === 0) return null;
  const images = blocks.filter((block): block is Extract<ToolResultMediaBlock, { type: 'image' }> => block.type === 'image');
  if (images.length === 0) return null;
  return (
    <div className="op-media">
      {images.map((block, index) => (
        <img
          key={index}
          className="op-media-image"
          src={`data:${block.mimeType};base64,${block.data}`}
          alt=""
          style={{ maxWidth: '100%', height: 'auto', display: 'block' }}
        />
      ))}
    </div>
  );
}

function FileErrorDetail({ result }: { result?: ToolResultEvent | undefined }) {
  if (!result?.isError) return null;
  // This block and the badge tooltip stay mounted even when collapsed. Share the reader's cap
  // and redactor so large failures cannot retain their full output in those alternate DOM sinks.
  const detail = describeToolCallDetail({ input: null, result }, { maxChars: COLLAPSED_DETAIL_MAX_CHARS });
  return detail.outputText === null ? null : <pre className="op-output">{detail.outputText}</pre>;
}

function describeInput(input: unknown): string {
  if (input == null) return '';
  if (typeof input === 'string') return input;
  if (typeof input !== 'object') return String(input);
  const obj = input as Record<string, unknown>;
  for (const key of ['file_path', 'path', 'pattern', 'url', 'query', 'name', 'command']) {
    const v = obj[key];
    if (typeof v === 'string') return v;
  }
  try {
    return JSON.stringify(obj);
  } catch {
    return '';
  }
}

/**
 * A head's one-line summary of an arbitrary argument. Heads stay mounted for every collapsed row,
 * and the fallback argument can be a 20k-char payload or a key, so it gets the reader text's
 * order: redact first (a cut could split a key past its pattern), then cap.
 */
function headSummary({ text }: { text: string }): string {
  return truncate(redactUserText({ text: text }).text, 200);
}

function truncate(s: string, n: number): string {
  if (s.length <= n) return s;
  return s.slice(0, n - 1) + '…';
}

import type { CSSProperties } from 'react';
import type { ComposerDiscoveryGroup, ComposerDiscoveryItem } from '../slots.js';

export interface ComposerDiscoveryMatch {
  groupId: string;
  groupLabel: string;
  item: ComposerDiscoveryItem;
}

/**
 * A parsed `/command` or `/command argument…` token, anchored to the WHOLE draft (`^...$`) —
 * matching non-null means the draft contains nothing but the trigger, which is what keeps
 * {@link replaceComposerSlashTrigger}'s whole-draft replacement safe with no separate span to
 * track (verified across three independent designs in the 2026-08-12 debate: a `[start, end]`
 * tuple is always `[0, draft.length]` under this grammar and would be dead generality).
 */
export interface ComposerSlashQuery {
  command: string;
  /**
   * `null` until a separator (one or more spaces) is typed after the command word; from then on
   * holds the verbatim trailing text — including internal spaces and slashes — never re-split.
   */
  argument: string | null;
}

const SLASH_QUERY_RE = /^\/([^\s/]*)(?:(\s+)([\s\S]*))?$/;

/**
 * Open Design's active slash-token rule (`/^\/([^\s/]*)$/`), extended to admit one optional
 * trailing argument while staying anchored end-to-end. The command segment itself is unchanged —
 * still no internal whitespace or slash — so every existing no-argument caller parses identically
 * to before this extension.
 */
export function parseComposerSlashQuery({ draft }: { draft: string }): ComposerSlashQuery | null {
  const match = SLASH_QUERY_RE.exec(draft);
  if (!match) return null;
  // The `as string` casts are guaranteed by SLASH_QUERY_RE itself, not assumed: group 1 is a bare
  // `*` capture outside any optional group, so it always participates (possibly as ''); group 3 is
  // `*` inside the same optional group as group 2, so it participates whenever a separator does.
  // `noUncheckedIndexedAccess` cannot see either guarantee, and the `?? ''` fallbacks that used to
  // satisfy it were unreachable branches.
  const [, command, separator, rest] = match;
  return { command: command as string, argument: separator === undefined ? null : (rest as string) };
}

/**
 * Once a separator has been typed, only an item whose declared `command` exactly equals the typed
 * command word survives. Required so that typing `/mcp supabase` cannot still surface an unrelated
 * `/mcp-docs` row (a substring match on "mcp" would keep it alive) and, worse, hand that row a
 * `server-id` argument that was typed for a different command. An item with no `command` is
 * dropped outright — it declared no argument grammar to lock onto.
 */
function matchesLockedCommand(item: ComposerDiscoveryItem, normalizedCommand: string): boolean {
  return item.command !== undefined && item.command.toLowerCase() === normalizedCommand;
}

/**
 * Still typing the command word: every item — command-bearing or not — is eligible via the
 * existing case-insensitive fuzzy match over `command`/`label`/`description`/`kind`/`keywords`.
 */
function matchesFuzzyCommand(item: ComposerDiscoveryItem, normalizedCommand: string): boolean {
  if (normalizedCommand === '') return true;
  const searchable = [item.command, item.label, item.description, item.kind, ...(item.keywords ?? [])]
    .filter((value): value is string => typeof value === 'string')
    .join(' ')
    .toLowerCase();
  return searchable.includes(normalizedCommand);
}

/**
 * Flattens non-empty groups while preserving host order, then filters.
 *
 * Two modes, selected by `query.argument`: {@link matchesFuzzyCommand} while the command word is
 * still being typed (`argument === null`), {@link matchesLockedCommand} once a separator has been
 * typed (`argument !== null`) — see each helper's own doc for why the rule changes at that point.
 */
export function filterComposerDiscovery(
  { groups, query }: { groups: readonly ComposerDiscoveryGroup[]; query: ComposerSlashQuery },
): ComposerDiscoveryMatch[] {
  const normalizedCommand = query.command.trim().toLowerCase();
  const matchesQuery = query.argument !== null ? matchesLockedCommand : matchesFuzzyCommand;
  const matches: ComposerDiscoveryMatch[] = [];

  for (const group of groups) {
    for (const item of group.items) {
      if (matchesQuery(item, normalizedCommand)) matches.push({ groupId: group.id, groupLabel: group.label, item });
    }
  }

  return matches;
}

export type ComposerSlashResolution =
  | {
      /**
       * The command word is not yet complete, or a required argument hasn't been typed yet.
       * Complete the trigger to `draft` and keep editing — no host effect fires.
       */
      type: 'complete';
      draft: string;
    }
  | {
      /** Ready to notify the host. `argument` is `undefined` for a plain macro item (no
       * `command` declared) — its own `insertText`/`label` drives the draft as before. */
      type: 'invoke';
      argument?: string | null;
    };

/**
 * Decides what selecting `item` (via click, Enter, or Tab) should do against the current `draft`.
 *
 * A plain item (no `command`) is unaffected — always resolves to `'invoke'`, preserving today's
 * one-step select-and-replace behavior exactly. A command-bearing item completes the trigger
 * instead of invoking whenever invoking now would be premature or meaningless:
 * - the typed command word is only a fuzzy/prefix match, not the declared word itself (Enter
 *   disambiguates rather than guessing which of several prefix-matched commands was meant);
 * - the item takes an argument and none has been typed yet (no separator);
 * - the argument is declared `required` and only whitespace follows the separator.
 *
 * Everything else invokes: a no-argument command the moment its exact word is typed, or an
 * argument-taking command the moment a separator exists and (if required) the argument is
 * non-blank.
 */
export function resolveComposerSlashInvocation(
  { draft, item }: { draft: string; item: ComposerDiscoveryItem },
): ComposerSlashResolution | null {
  const query = parseComposerSlashQuery({ draft });
  if (!query) return null;
  if (!item.command) return { type: 'invoke' };

  const completeTo = (): ComposerSlashResolution => ({
    type: 'complete',
    draft: `/${item.command}${item.argument ? ' ' : ''}`,
  });

  if (query.command.trim().toLowerCase() !== item.command.toLowerCase()) return completeTo();
  if (!item.argument) return { type: 'invoke', argument: query.argument };
  if (query.argument === null) return completeTo();
  if (item.argument.required && query.argument.trim() === '') return completeTo();

  return { type: 'invoke', argument: query.argument };
}

/** Replaces the complete active slash token; callers only invoke this after the parser matches. */
export function replaceComposerSlashTrigger({ draft, insertText }: { draft: string; insertText: string }): string {
  return parseComposerSlashQuery({ draft }) === null ? draft : insertText;
}

/** Adds a menu-selected resource to an existing prompt without concatenating words. */
export function appendComposerDiscovery({ draft, insertText }: { draft: string; insertText: string }): string {
  if (draft.trim() === '') return insertText;
  return `${draft.trimEnd()} ${insertText}`;
}

export type ComposerSlashKeyAction =
  | { type: 'move'; offset: -1 | 1 }
  | { type: 'select' }
  | { type: 'dismiss' }
  | { type: 'none' };

/** Maps palette keys without owning React state; arrows are intentionally circular at the caller. */
export function resolveComposerSlashKeyAction({ key, shiftKey }: { key: string; shiftKey: boolean }): ComposerSlashKeyAction {
  if (key === 'ArrowDown') return { type: 'move', offset: 1 };
  if (key === 'ArrowUp') return { type: 'move', offset: -1 };
  if ((key === 'Enter' || key === 'Tab') && !shiftKey) return { type: 'select' };
  if (key === 'Escape') return { type: 'dismiss' };
  return { type: 'none' };
}

/** The subset of `DOMRect` the popover-positioning math below actually reads, so a caller (or a
 *  test) can pass a plain object instead of constructing every read-only `DOMRect` accessor. */
export interface ComposerMenuAnchorRect {
  top: number;
  left: number;
  width: number;
}

/**
 * Vertical half of a composer popover's viewport-fixed position, shared by
 * {@link composerDiscoveryMenuPosition} and {@link composerSlashMenuPosition}.
 *
 * Both popovers were previously plain `position: absolute` descendants of `.jini-composer`, which
 * is itself nested inside `.jini-chat-pane__body` — an ancestor that sets `overflow: hidden`
 * unconditionally (`styles.ts`), plus whatever clipping box a host's own dock chrome adds on top
 * (a host admin's `.admin-chat-dock` is `overflow: hidden` too, and its mobile "peek" sheet caps the
 * whole dock at `58vh`). CSS alone cannot know how much room that leaves above the composer on a
 * given host; when the popover's natural content is taller than the available space, the
 * ancestor's hard clip boundary slices through whichever row sits at the clip line instead of the
 * popover's own internal scroll doing so — reported as the list reading "clipped mid-item" rather
 * than cleanly scrolled. `position: fixed` escapes every ancestor's `overflow` (none of them sets
 * `transform`/`filter`/`contain`/`will-change: transform`, which is the only thing that would trap
 * a fixed-position descendant), the same fix `useAgentRuntimePicker.hooks.ts`'s
 * `runtimePopoverPosition('up', ...)` already applies to the sibling runtime popover for the
 * identical reason.
 *
 * @complexity Time/space: O(1).
 */
function verticalUpPosition(anchorTop: number): Pick<CSSProperties, 'position' | 'bottom' | 'maxHeight' | 'zIndex'> {
  const gap = 6; // matches the reference stylesheet's `bottom: calc(100% + 6px)`
  const margin = 8; // keeps the popover off the literal viewport edge on a very short window
  const maxHeightCap = 280; // matches the reference stylesheet's unconditional `max-height: 280px`
  return {
    position: 'fixed',
    bottom: Math.max(margin, window.innerHeight - anchorTop + gap),
    maxHeight: Math.min(maxHeightCap, Math.max(0, anchorTop - gap - margin)),
    zIndex: 8, // matches the reference stylesheet's `.jini-composer-discovery-menu`/`-slash-menu`
  };
}

/**
 * Viewport-fixed position for the "+" discovery menu, anchored to `.jini-composer`'s live rect.
 * Keeps the menu's existing left-aligned, width-capped footprint (`inset-inline-start: 8px; width:
 * min(280px, 100vw - 32px)` in the reference stylesheet) — only the escape-the-ancestor-clip and
 * available-space clamp from {@link verticalUpPosition} are new.
 *
 * @complexity Time/space: O(1).
 */
export function composerDiscoveryMenuPosition({ composerRect }: { composerRect: ComposerMenuAnchorRect }): CSSProperties {
  const inset = 8;
  return {
    ...verticalUpPosition(composerRect.top),
    left: composerRect.left + inset,
    width: Math.min(280, window.innerWidth - 32),
  };
}

/**
 * Viewport-fixed position for the slash-command palette, anchored to `.jini-composer`'s live
 * rect. Keeps the palette's existing full-width-minus-insets footprint (`inset-inline: 8px` in
 * the reference stylesheet).
 *
 * @complexity Time/space: O(1).
 */
export function composerSlashMenuPosition({ composerRect }: { composerRect: ComposerMenuAnchorRect }): CSSProperties {
  const inset = 8;
  return {
    ...verticalUpPosition(composerRect.top),
    left: composerRect.left + inset,
    width: Math.max(0, composerRect.width - inset * 2),
  };
}

import { useEffect, useState } from 'react';
import type { ChatMessage } from '../../../../core/messages.js';
import { AGENT_PLUGIN_STATE_CHANGED, readAgentPluginChatState, writeAgentPluginChatState, type AgentPluginUsage as Usage } from '../../../../core/agent-plugin-chat-state.js';
import { useT } from '../../../hooks/context.js';

type AgentPluginChatState = ReturnType<typeof readAgentPluginChatState>;

/** The newest `agent_plugins` usage event across the transcript, if any turn reported one. */
function findLatestAgentPluginUsage(messages: readonly ChatMessage[]): Usage | undefined {
  let latest: Usage | undefined;
  for (const message of messages) for (const event of message.events ?? []) {
    if (event.kind === 'ext' && event.name === 'agent_plugins') latest = event.data as Usage;
  }
  return latest;
}

/** What the strip shows for this chat: the latest usage's plugins minus the ones the human
 * excluded — or `null` when the latest usage belongs to another chat or nothing is left. */
function resolveAgentPluginStrip(
  { messages }: { messages: readonly ChatMessage[] },
  { conversationId }: { conversationId?: string | null | undefined },
): { id: string; state: AgentPluginChatState; plugins: Usage['plugins'] } | null {
  const latest = findLatestAgentPluginUsage(messages);
  const id = conversationId ?? latest?.conversationId;
  if (!id || !latest || latest.conversationId !== id) return null;
  const state = readAgentPluginChatState({ conversationId: id });
  const plugins = latest.plugins.filter(plugin => !state.excluded.includes(plugin.id));
  if (!plugins.length) return null;
  return { id, state, plugins };
}

/** One per-chat usage strip; removing a name persists its exclusion for future turns. */
export function AgentPluginUsage({ conversationId, messages }: { conversationId?: string | null; messages: readonly ChatMessage[] }) {
  const t = useT();
  const [revision, setRevision] = useState(0);
  useEffect(() => {
    const refresh = () => setRevision(value => value + 1);
    window.addEventListener(AGENT_PLUGIN_STATE_CHANGED, refresh);
    window.addEventListener('storage', refresh);
    return () => { window.removeEventListener(AGENT_PLUGIN_STATE_CHANGED, refresh); window.removeEventListener('storage', refresh); };
  }, []);
  void revision;
  const strip = resolveAgentPluginStrip({ messages }, { conversationId });
  if (!strip) return null;
  const { id, state, plugins } = strip;
  return <div role="status" style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 6, padding: '6px 12px', fontSize: 12 }}>
    <span>{t('Using:')}</span>
    {plugins.map(plugin => <span key={plugin.id} style={{ display: 'inline-flex', alignItems: 'center', gap: 4, border: '1px solid currentColor', borderRadius: 12, padding: '1px 7px' }}>
      {plugin.name}<button type="button" aria-label={`${t('Stop using')} ${plugin.name}`} title={t('Stops future use in this chat. Guidance already loaded stays in the current context.')}
        onClick={() => writeAgentPluginChatState({ conversationId: id, state: { ...state, excluded: [...state.excluded, plugin.id] } })}
        style={{ background: 'none', border: 0, color: 'inherit', cursor: 'pointer', padding: '0 2px', fontSize: 16 }}>×</button>
    </span>)}
  </div>;
}

