/**
 * The `unavailable` banner's copy and, where reachable, its actual fix — distinguishing three
 * CLI-less states so a pointer at BYOK is never shown as an option that would not actually help:
 *
 * - `executionMode === 'local'` with BYOK available: switching mode is a real fix. When the host
 *   wired `onExecutionModeChange` (the same callback the runtime picker's own mode buttons already
 *   call — see `AgentRuntimePicker.tsx`), this renders as a button that performs the switch
 *   directly rather than prose telling the operator to go hunting for the control themselves. A
 *   host that reports `apiModeAvailable` without wiring the callback still gets an honest, if
 *   inert, pointer as plain copy.
 * - `executionMode === 'local'` with BYOK NOT available: switching would not help — offering it
 *   anyway would be a lie — so this falls back to the original, unconditional message.
 * - `executionMode === 'api'` already: the operator is already on the one path that could work,
 *   so a "switch to BYOK" pointer would be nonsensical here; whatever is still missing (e.g. no
 *   model chosen) is `RuntimeByokDetails`' own job to explain inside the runtime picker, not this
 *   banner's.
 */
function ChatPaneNoUsableCliMessage({
  executionMode,
  apiModeAvailable,
  onExecutionModeChange,
  t,
}: {
  executionMode: 'local' | 'api';
  apiModeAvailable: boolean;
  onExecutionModeChange: ((mode: 'local' | 'api') => void) | undefined;
  t: (key: string) => string;
}): ReactNode {
  const byokIsARealFix = executionMode === 'local' && apiModeAvailable;
  if (!byokIsARealFix) {
    return <div className="jini-chat-pane__error" role="alert">{t('No usable CLI is selected.')}</div>;
  }
  if (!onExecutionModeChange) {
    return (
      <div className="jini-chat-pane__error" role="alert">
        {t('No usable CLI is selected — switch to BYOK to use your own API key.')}
      </div>
    );
  }
  return (
    <div className="jini-chat-pane__error" role="alert">
      {t('No usable CLI is selected.')}{' '}
      <button
        type="button"
        className="jini-chat-pane__error-action"
        onClick={() => onExecutionModeChange('api')}
      >
        {t('Switch to BYOK')}
      </button>
    </div>
  );
}

interface ChatPaneAvailabilityStatusProps {
  unavailable: boolean;
  scanningAgents: boolean;
  connectingAgents: boolean;
  executionMode: 'local' | 'api';
  apiModeAvailable: boolean;
  onExecutionModeChange: ((mode: 'local' | 'api') => void) | undefined;
  t: (key: string) => string;
}

/**
 * `unavailable` alone conflates "inventory still loading" with "inventory loaded, nothing
 * usable" — both present as `selectedAgent === undefined`. `scanningAgents` is the signal
 * that tells them apart, mirroring the `workingDirectoryPending`/`workingDirectoryInvalid`
 * pair below: a pending detection is a `status`, only a *finished* detection that found
 * nothing is an `alert`. `connectingAgents` is a third state: the inventory could not be
 * read at all (the host is unreachable, typically a daemon restart) and a retry is
 * pending — a plain status too, never "No usable CLI", which only a SUCCESSFUL answer can
 * establish.
 */
function ChatPaneAvailabilityStatus({
  unavailable,
  scanningAgents,
  connectingAgents,
  executionMode,
  apiModeAvailable,
  onExecutionModeChange,
  t,
}: ChatPaneAvailabilityStatusProps): ReactNode {
  if (!unavailable) return null;
  if (connectingAgents) {
    return (
      <div className="jini-chat-pane__status" role="status">
        {t('Connecting to the assistant…')}
      </div>
    );
  }
  if (scanningAgents) {
    return (
      <div className="jini-chat-pane__status" role="status">
        {t('Loading available CLIs')}
      </div>
    );
  }
  return (
    <ChatPaneNoUsableCliMessage
      executionMode={executionMode}
      apiModeAvailable={apiModeAvailable}
      onExecutionModeChange={onExecutionModeChange}
      t={t}
    />
  );
}

function ChatPaneWorkingDirectoryStatus({
  workingDirectoryPending,
  workingDirectoryInvalid,
  t,
}: {
  workingDirectoryPending: boolean;
  workingDirectoryInvalid: boolean;
  t: (key: string) => string;
}): ReactNode {
  if (workingDirectoryPending) {
    return (
      <div className="jini-chat-pane__status" role="status">
        {t('Checking working directory…')}
      </div>
    );
  }
  if (!workingDirectoryInvalid) return null;
  return (
    <div className="jini-chat-pane__error" role="alert">
      {t('Working directory is unavailable.')}
    </div>
  );
}

/**
 * The typed-answer delivery notice. Only `'failed'` ever reaches it: `useChatPane` queues a
 * `'not-pending'` refusal as one ordinary message itself (`answerWaitingQuestion`), without a notice.
 *
 * MOVE (from the retired "Send as a new message" button this notice once rendered for
 * `'not-pending'`): the held answer's only way into a new run besides clearing the draft — an
 * explicit choice, so a closed question never turns an answer into a paid run on a second Enter.
 * The hook's automatic one-time fallback now owns that guarantee, which left the button unreachable.
 */
function ChatPaneTypedAnswerNotice({
  typedAnswerNotice,
  t,
}: {
  typedAnswerNotice: TypedAnswerNotice | null;
  t: (key: string) => string;
}): ReactNode {
  if (!typedAnswerNotice) return null;
  return (
    <div className="jini-chat-pane__error" role="alert">
      {t(describeTypedAnswerNotice({ notice: typedAnswerNotice }))}
    </div>
  );
}

/** A send the server never accepted. Its text went back into the composer if that was still empty;
 * Retry sends it again either way (see `useChatPane`'s `retrySend`). */
function ChatPaneSendError({ sendError, onRetry, t }: { sendError: Error | null; onRetry: () => void; t: (key: string) => string }): ReactNode {
  if (!sendError) return null;
  return (
    <div className="jini-chat-pane__error" role="alert">
      {t('Not sent:')} {sendError.message}{' '}
      <button type="button" className="jini-chat-pane__error-action" onClick={onRetry}>{t('Retry')}</button>
    </div>
  );
}

interface ChatPaneStatusMessagesProps extends ChatPaneAvailabilityStatusProps {
  sendError: Error | null;
  onRetrySend: () => void;
  attachmentError: Error | null;
  dropReadError: string | null;
  workingDirectoryError: Error | null;
  workingDirectoryPending: boolean;
  workingDirectoryInvalid: boolean;
  runtimeInventoryError: Error | null;
  typedAnswerNotice: TypedAnswerNotice | null;
}

/** The pane's stack of mutually-independent error/status banners — each condition is its own
 * source of truth, so they are rendered as siblings rather than folded into one derived state. */
function ChatPaneStatusMessages({
  sendError,
  onRetrySend,
  attachmentError,
  dropReadError,
  workingDirectoryError,
  workingDirectoryPending,
  workingDirectoryInvalid,
  runtimeInventoryError,
  typedAnswerNotice,
  ...availability
}: ChatPaneStatusMessagesProps): ReactNode {
  const { t } = availability;
  return (
    <>
      <ChatPaneAvailabilityStatus {...availability} />
      <ChatPaneSendError sendError={sendError} onRetry={onRetrySend} t={t} />
      {/* Run failures render once on their assistant message; pane banners remain for
          attachment, working-directory and other errors that have no message binding. */}
      {attachmentError ? (
        <div className="jini-chat-pane__error" role="alert">{attachmentError.message}</div>
      ) : null}
      {dropReadError ? (
        <div className="jini-chat-pane__error" role="alert">{dropReadError}</div>
      ) : null}
      {workingDirectoryError ? (
        <div className="jini-chat-pane__error" role="alert">{workingDirectoryError.message}</div>
      ) : null}
      <ChatPaneWorkingDirectoryStatus
        workingDirectoryPending={workingDirectoryPending}
        workingDirectoryInvalid={workingDirectoryInvalid}
        t={t}
      />
      {/* While connecting, the transport error is transient noise the retry is already handling. */}
      {runtimeInventoryError && !availability.connectingAgents ? (
        <div className="jini-chat-pane__error" role="alert">
          {runtimeInventoryError.message}
        </div>
      ) : null}
      <ChatPaneTypedAnswerNotice typedAnswerNotice={typedAnswerNotice} t={t} />
    </>
  );
}

interface ChatPaneWorkingDirectoryBlockProps {
  workingDirectoryAccess: ChatPaneWorkingDirectoryAccess | undefined;
  workingDirectoryControlPlacement: 'below' | 'composer' | 'none';
  pane: UseChatPaneResult;
  t: (key: string) => string;
}

function ChatPaneWorkingDirectoryBlock({
  workingDirectoryAccess,
  workingDirectoryControlPlacement,
  pane,
  t,
}: ChatPaneWorkingDirectoryBlockProps): ReactNode {
  if (workingDirectoryAccess && workingDirectoryControlPlacement === 'below') {
    return (
      <div className="jini-chat-pane__workdir">
        <WorkingDirPicker
          workingDir={pane.workingDirectory}
          recentDirs={[...pane.recentDirectories]}
          onPickDirectory={() => void pane.pickWorkingDirectory()}
          onSelectRecent={(directory) => void pane.selectRecentDirectory(directory)}
          placement="up"
          onClear={pane.clearWorkingDirectory}
          invalid={pane.workingDirectoryInvalid}
          onOpen={() => void pane.openWorkingDirectoryPicker()}
          labels={{ trigger: t('Select working directory') }}
        />
      </div>
    );
  }
  // Three cases render nothing here, for different reasons:
  // - No native `workingDirectoryAccess`: the static text line this replaced is gone entirely —
  //   see `ChatPaneComposerArea` below, which threads `pane.workingDirectory` and
  //   `pane.selectRecentDirectory` into `Composer`'s own folder-icon (popover) trigger instead.
  // - `workingDirectoryAccess` present but `workingDirectoryControlPlacement === 'composer'`: the
  //   host asked for the control next to "+" instead — `resolveComposerWorkingDirectory` wires
  //   `Composer`'s trigger straight to `pane.pickWorkingDirectory` in that case, so rendering this
  //   block too would put up a second, competing control below the composer.
  // - `workingDirectoryControlPlacement === 'none'`: the host asked for no working-directory
  //   control anywhere — `resolveComposerWorkingDirectory` supplies neither composer handler in
  //   this case either, so `Composer`'s own folder-icon gate (`onChangeWorkingDirectory ||
  //   onPickWorkingDirectory`) renders nothing too. Nothing here has a trigger to defer to.
  // In every case but `'none'`, the trigger this defers to already covers both "nothing set yet"
  // and "a value is set", so this block has nothing left to render.
  return null;
}

/** `uploadAttachments === undefined` gates BOTH of these — a temporarily-disabled composer still
 * consumes a file drop so the browser cannot navigate away to the local file (see
 * `useChatPaneFileDrop`'s module doc), so the drop handlers stay attached even when the picker
 * itself is hidden. Shared here so `ChatPaneComposerArea` pays for the branch once, at module
 * scope, instead of per call site. */
function resolveDropTargetProps(
  uploadAttachments: ChatPaneProps['uploadAttachments'],
  fileDrop: UseChatPaneFileDropResult,
): ChatPaneFileDropTargetProps | Record<string, never> {
  return uploadAttachments === undefined ? {} : fileDrop.targetProps;
}

function resolveComposerAttachmentPicker(
  uploadAttachments: ChatPaneProps['uploadAttachments'],
  pane: UseChatPaneResult,
  attachmentAccept: ChatPaneProps['attachmentAccept'],
): { attachmentPicker?: { onFiles: (files: File[]) => void; uploading: boolean; accept?: string } } {
  if (uploadAttachments === undefined) return {};
  return {
    attachmentPicker: definedProps({ source: {
      onFiles: pane.addAttachments,
      uploading: pane.isUploadingAttachments,
      accept: attachmentAccept,
    } }),
  };
}

/**
 * Resolves which of `Composer`'s two mutually-exclusive working-directory props (if either) this
 * render should supply, mirroring `ChatPaneWorkingDirectoryBlock`'s own four-way branch above so
 * the two never disagree about which control owns the composer's folder-icon slot:
 *
 * - `workingDirectoryControlPlacement === 'none'`: neither prop, regardless of whether
 *   `workingDirectoryAccess` is present — the host asked for no working-directory control
 *   anywhere, so `Composer`'s own gate (`onChangeWorkingDirectory || onPickWorkingDirectory`)
 *   renders nothing. Checked first because it overrides both cases below.
 * - No `workingDirectoryAccess`: the composer's lightweight text-input popover, via
 *   `onChangeWorkingDirectory`. `pane.selectRecentDirectory` is reused as the plain setter here
 *   rather than inventing one — `useChatPaneWorkingDirectory`'s own doc confirms it already writes
 *   the value directly (no native validation) whenever `access` is absent, which is exactly this
 *   case.
 * - `workingDirectoryAccess` present and `workingDirectoryControlPlacement === 'composer'`: the
 *   SAME folder-icon trigger, but wired to `onPickWorkingDirectory` instead — clicking it invokes
 *   the native OS dialog (`pane.pickWorkingDirectory`) directly, with no popover in between.
 * - `workingDirectoryAccess` present and placement is (default) `'below'`: neither prop — the
 *   composer renders no folder icon at all, and `ChatPaneWorkingDirectoryBlock` renders the richer
 *   `WorkingDirPicker` below instead, unchanged from every host's prior behavior.
 */
function resolveComposerWorkingDirectory(
  workingDirectoryAccess: ChatPaneWorkingDirectoryAccess | undefined,
  workingDirectoryControlPlacement: 'below' | 'composer' | 'none',
  pane: UseChatPaneResult,
): {
  workingDirectory?: string | null;
  onChangeWorkingDirectory?: (workingDirectory: string) => void;
  onPickWorkingDirectory?: () => void;
} {
  if (workingDirectoryControlPlacement === 'none') {
    return {};
  }
  if (!workingDirectoryAccess) {
    return {
      workingDirectory: pane.workingDirectory,
      onChangeWorkingDirectory: (directory: string) => void pane.selectRecentDirectory(directory),
    };
  }
  if (workingDirectoryControlPlacement === 'composer') {
    return {
      workingDirectory: pane.workingDirectory,
      onPickWorkingDirectory: () => void pane.pickWorkingDirectory(),
    };
  }
  return {};
}

interface ChatPaneComposerAreaProps {
  fileDrop: UseChatPaneFileDropResult;
  uploadAttachments: ChatPaneProps['uploadAttachments'];
  pane: UseChatPaneResult;
  disabled: boolean;
  unavailable: boolean;
  placeholder: string | undefined;
  slots: ComposerSlots;
  attachmentAccept: ChatPaneProps['attachmentAccept'];
  workingDirectoryAccess: ChatPaneWorkingDirectoryAccess | undefined;
  workingDirectoryControlPlacement: 'below' | 'composer' | 'none';
  t: (key: string) => string;
}

/** The drop target, composer, and working-directory block — everything below the status banners
 * that reads/writes the live pane. Cancelling an in-flight run is not a separate control here: it
 * lives in the composer's own trailing button, which swaps from send to stop while streaming (see
 * `Composer`'s `running`/`onCancel` props) — the same control an operator's attention is already
 * on, rather than a second affordance elsewhere in the pane they'd have to go find.
 *
 * The pending-turn strip previously lived here (a banner bolted above the composer). It now
 * renders inside `<MessageList>` itself, as the newest transcript entry — see that component's
 * `pendingPrompts` prop and this component's own call site below. */
function ChatPaneComposerArea({
  fileDrop,
  uploadAttachments,
  pane,
  disabled,
  unavailable,
  placeholder,
  slots,
  attachmentAccept,
  workingDirectoryAccess,
  workingDirectoryControlPlacement,
  t,
}: ChatPaneComposerAreaProps): ReactNode {
  const sendDisabledReasonId = useId();
  const sendDisabledReason = pane.sendBlocker && pane.sendBlocker !== 'streaming'
    ? t(describeChatPaneSendBlocker(pane.sendBlocker))
    : undefined;
  return (
    <div
      className={`jini-chat-pane__drop-target${fileDrop.draggingFiles ? ' is-dragging-files' : ''}`}
      data-testid="chat-pane-file-drop-target"
      data-dragging-files={fileDrop.draggingFiles ? 'true' : 'false'}
      {...resolveDropTargetProps(uploadAttachments, fileDrop)}
    >
      {fileDrop.draggingFiles ? (
        <span className="jini-chat-pane__drop-announcement" role="status">
          {t('Drop files to attach')}
        </span>
      ) : null}
      <Composer
        composer={pane.composer}
        onSend={() => void pane.send()}
        // Streaming no longer locks the textarea: `pane.send()` queues a turn typed during a run
        // rather than refusing it, so the operator can keep writing while the agent thinks.
        disabled={disabled || unavailable}
        // The one blocker `send()` handles itself. Every other refusal still greys out the button.
        sendDisabled={!pane.canSend && pane.sendBlocker !== 'streaming'}
        {...definedProps({ source: { sendDisabledReason, sendDisabledReasonId: sendDisabledReason ? sendDisabledReasonId : undefined } })}
        running={pane.conversation.isStreaming}
        onCancel={pane.conversation.cancel}
        onInterrupt={pane.interruptSend}
        {...definedProps({ source: { placeholder } })}
        slots={{ ...slots, footerAccessories: <>
          {sendDisabledReason ? <small id={sendDisabledReasonId} className="jini-composer-send-blocker">{sendDisabledReason}</small> : null}
          {slots.footerAccessories}
        </> }}
        {...resolveComposerAttachmentPicker(uploadAttachments, pane, attachmentAccept)}
        {...resolveComposerWorkingDirectory(workingDirectoryAccess, workingDirectoryControlPlacement, pane)}
      />
      <ChatPaneWorkingDirectoryBlock
        workingDirectoryAccess={workingDirectoryAccess}
        workingDirectoryControlPlacement={workingDirectoryControlPlacement}
        pane={pane}
        t={t}
      />
    </div>
  );
}

/** Every prop `ChatPane` defaults, and its default — applied only where the caller left the prop
 * `undefined`, exactly like the destructuring defaults this replaced. */
type ChatPaneDefaultedProp =
  | 'agents' | 'runtimeStatusPollMs' | 'variant' | 'scanningAgents' | 'daemonOnline' | 'executionMode'
  | 'apiModeAvailable' | 'suggestions' | 'workingDirectoryControlPlacement' | 'toolCallDisplay'
  | 'showUsageLine' | 'showThinking' | 'agentPluginsMode' | 'disabled' | 'runtimePickerPlacement';

type ResolvedChatPaneProps = ChatPaneProps & Required<Pick<ChatPaneProps, ChatPaneDefaultedProp>>;

const EMPTY_SUGGESTIONS: readonly string[] = [];

const CHAT_PANE_DEFAULTS: Required<Pick<ChatPaneProps, ChatPaneDefaultedProp>> = {
  agents: EMPTY_AGENTS,
  runtimeStatusPollMs: 5_000,
  variant: 'workspace',
  scanningAgents: false,
  daemonOnline: true,
  executionMode: 'local',
  apiModeAvailable: false,
  suggestions: EMPTY_SUGGESTIONS,
  workingDirectoryControlPlacement: 'below',
  toolCallDisplay: 'show',
  showUsageLine: true,
  showThinking: false,
  agentPluginsMode: 'auto',
  disabled: false,
  runtimePickerPlacement: 'up',
};

function applyChatPaneDefaults(props: ChatPaneProps): ResolvedChatPaneProps {
  const resolved: ResolvedChatPaneProps = { ...props, ...CHAT_PANE_DEFAULTS };
  for (const key of Object.keys(CHAT_PANE_DEFAULTS) as ChatPaneDefaultedProp[]) {
    if (props[key] !== undefined) Object.assign(resolved, { [key]: props[key] });
  }
  return resolved;
}

function resolveAgentControlOptions(agentControl: ChatPaneProps['agentControl']) {
  return definedProps({ source: {
    enabled: agentControl?.enabled ?? false,
    bridgeAccess: agentControl?.bridgeAccess,
    webmcp: agentControl?.webmcp,
  } });
}

function useComposerHandlePublisher(
  { pane }: { pane: UseChatPaneResult },
  { composerHandle }: { composerHandle?: ChatPaneProps['composerHandle'] },
): void {
  // Mirrors `Composer.tsx`'s own `draftRef`: `composerHandle.insertText` (below) is called from
  // OUTSIDE any render, so it cannot close over `pane.composer.draft` directly — that would freeze
  // it at whatever the draft was on the render that captured it. Reassigned unconditionally every
  // render, same as its counterpart.
  const composerDraftRef = useRef(pane.composer.draft);
  composerDraftRef.current = pane.composer.draft;
  useEffect(() => {
    if (!composerHandle) return;
    composerHandle.current = {
      insertText: (text) => {
        pane.composer.setDraft(appendComposerDiscovery({ draft: composerDraftRef.current, insertText: text }));
      },
    };
    return () => {
      composerHandle.current = null;
    };
    // `pane.composer` is a fresh object every render `useComposer` produces (see its own `useMemo`
    // deps), so depending on it here just means this effect re-publishes a new (equally correct)
    // closure on every render rather than genuinely skipping renders — cheap, and it keeps
    // `pane.composer.setDraft` from ever going stale if that reference ever changes.
  }, [composerHandle, pane.composer]);
}

function useChatPaneTranscriptProps(
  { pane }: { pane: UseChatPaneResult },
  { projectFileNames }: { projectFileNames?: ChatPaneProps['projectFileNames'] },
) {
  // `MessageList` is memoized so a composer keystroke does not re-render the transcript; these two
  // props would otherwise be fresh objects on every render and defeat it.
  const { queuedMessages, cancelQueuedMessage } = pane;
  const pendingPrompts = useMemo(
    () => queuedMessages.map(input => ({ ...input, onCancel: () => cancelQueuedMessage({ id: input.id }) })),
    [queuedMessages, cancelQueuedMessage],
  );
  const projectFileNameSet = useMemo(
    () => (projectFileNames === undefined ? undefined : new Set(projectFileNames)),
    [projectFileNames],
  );
  return { pendingPrompts, projectFileNameSet };
}

/** `composerSlots`'s type excludes both `leadingAccessories` and `footerAccessories` (see
 * `ChatPaneProps.composerSlots`'s doc), so the two explicit keys below are never overwriting a
 * caller-supplied value — they are the ONLY source for both. */
function buildChatPaneSlots(
  { surfaceSlots, embed, renderRuntimePicker }: {
    surfaceSlots: ReturnType<typeof useChatPaneSurface>['composerSlots'];
    embed: boolean;
    renderRuntimePicker: () => ReactNode;
  },
  { leadingAccessory }: { leadingAccessory?: ReactNode },
): ComposerSlots {
  return definedProps({ source: {
    ...surfaceSlots,
    leadingAccessories: embed ? undefined : leadingAccessory,
    footerAccessories: embed ? undefined : renderRuntimePicker(),
  } });
}

interface ChatPaneTranscriptProps {
  pane: UseChatPaneResult;
  emptyState: ReactNode;
  embed: boolean;
  suggestions: readonly string[];
  onSelectSuggestion: (suggestion: string) => void;
  pendingPrompts: ReturnType<typeof useChatPaneTranscriptProps>['pendingPrompts'];
  projectFileNameSet: Set<string> | undefined;
  toolCallDisplay: ResolvedChatPaneProps['toolCallDisplay'];
  showUsageLine: boolean;
  showThinking: boolean;
  t: (key: string) => string;
}

function ChatPaneTranscript({
  pane,
  emptyState,
  embed,
  suggestions,
  onSelectSuggestion,
  pendingPrompts,
  projectFileNameSet,
  toolCallDisplay,
  showUsageLine,
  showThinking,
  t,
}: ChatPaneTranscriptProps): ReactNode {
  if (pane.conversation.messages.length === 0 && emptyState) {
    return (
      <div className="jini-message-list jini-message-list--empty">
        {emptyState}
        {embed && <ChatPaneSuggestionsRow suggestions={suggestions} onSelect={onSelectSuggestion} t={t} />}
      </div>
    );
  }
  return (
    <MessageList
      messages={pane.conversation.messages}
      isStreaming={pane.conversation.isStreaming}
      scrollIntent={pane.conversation.scrollIntent}
      onScrolled={pane.conversation.acknowledgeScroll}
      pendingPrompts={pendingPrompts}
      toolCallDisplay={toolCallDisplay}
      showUsageLine={showUsageLine}
      showThinking={showThinking}
      {...(projectFileNameSet === undefined ? {} : { projectFileNames: projectFileNameSet })}
    />
  );
}

/** The controls-area suggestions row shows on every workspace surface, and on the embed surface
 * only when the empty transcript has no `emptyState` to host it instead. */
function showsControlsSuggestions(embed: boolean, messageCount: number, emptyState: ReactNode): boolean {
  return !embed || (messageCount === 0 && !emptyState);
}

/**
 * Renders the self-contained chat-pane composition, including runtime and
 * working-directory orchestration owned by `@jini-ai/chat-react`.
 *
 * @complexity Time/space: O(n) in rendered messages, agents, and suggestions.
 * @overallScore 100/100
 */
export function ChatPane(props: ChatPaneProps) {
  const p = applyChatPaneDefaults(props);
  const t = useT();
  const surface = useChatPaneSurface({
    variant: p.variant,
    composerSlots: p.composerSlots,
    workingDirectoryControlPlacement: p.workingDirectoryControlPlacement,
    uploadAttachments: p.uploadAttachments,
  });
  const composerPlaceholder = useChatPaneComposerPlaceholder({ placeholder: p.placeholder, placeholders: p.placeholders });
  const inventory = useChatPaneRuntimeInventory(definedProps({ source: {
    access: p.runtimeAccess,
    initialAgents: p.agents,
    pollIntervalMs: p.runtimeStatusPollMs,
  } }));
  const runtimeView = resolveRuntimeAccessView(
    p.runtimeAccess,
    p.agents,
    p.scanningAgents,
    p.daemonOnline,
    p.onRescanAgents,
    inventory,
  );
  // Computed once and threaded into both `useChatPane` (so `sendBlocker` agrees) and this
  // component's own `unavailable` below (so the status banner and composer agree) — see
  // `isChatPaneApiModeConfigured` for why API mode alone isn't enough.
  const apiModeConfigured = isChatPaneApiModeConfigured({
    executionMode: p.executionMode,
    apiModeAvailable: p.apiModeAvailable,
    byokRuntime: p.byokRuntime,
  });
  const pane = useChatPane(definedProps({ source: {
    transport: p.transport,
    agents: runtimeView.agents,
    initialMessages: p.initialMessages,
    refreshSignal: p.refreshSignal,
    conversationId: p.conversationId,
    initialSelection: p.initialSelection,
    selection: p.selection,
    onSelectionChange: p.onSelectionChange,
    runContext: p.runContext,
    initialDraft: p.initialDraft,
    composerHistoryScope: p.composerHistoryScope,
    composerHistoryStorage: p.composerHistoryStorage,
    composerHistoryCap: p.composerHistoryCap,
    validateAttachments: p.validateAttachments,
    uploadAttachments: p.uploadAttachments,
    onActivityChange: p.onActivityChange,
    onMessagesChange: p.onMessagesChange,
    redactUserText: p.redactUserText,
    onSecretRedacted: p.onSecretRedacted,
    workingDirectory: p.workingDirectory,
    initialWorkingDirectory: p.initialWorkingDirectory,
    onChangeWorkingDirectory: p.onChangeWorkingDirectory,
    workingDirectoryAccess: p.workingDirectoryAccess,
    apiModeConfigured,
    deliverTypedAnswer: p.deliverTypedAnswer,
    deliverMidRunMessage: p.deliverMidRunMessage,
  } }));
  useComposerHandlePublisher({ pane }, definedProps({ source: { composerHandle: p.composerHandle } }));
  // No `runContext` here on purpose: agent-driven sends go through `pane.sendPrompt`, which builds
  // the context from the SAME `runContext` already handed to `useChatPane` above. A second copy
  // would be a second source of truth that could silently drift from the composer's.
  useChatPaneAgentControl({ pane: pane }, resolveAgentControlOptions(p.agentControl));
  // Selection resolution only returns available agents, so absence normally means nothing usable
  // is selected — except a configured BYOK turn (`apiModeConfigured`, computed above), which calls
  // the provider directly over HTTP and never touches the CLI inventory.
  const unavailable = pane.selectedAgent === undefined && !apiModeConfigured;
  const fileDrop = useChatPaneFileDrop({
    enabled: isChatPaneFileDropEnabled({
      canUpload: surface.uploadAttachments !== undefined,
      disabled: p.disabled,
      unavailable,
      uploading: pane.isUploadingAttachments,
    }),
    onFiles: pane.addAttachments,
  });
  const slots = buildChatPaneSlots({
    surfaceSlots: surface.composerSlots,
    embed: surface.embed,
    renderRuntimePicker: () => (
      <AgentRuntimePicker
        agents={runtimeView.agents}
        value={pane.selection}
        onChange={pane.setSelection}
        {...definedProps({ source: { onRescan: runtimeView.rescanAgents } })}
        scanning={runtimeView.scanningAgents}
        daemonOnline={runtimeView.daemonOnline}
        placement={p.runtimePickerPlacement}
        executionMode={p.executionMode}
        apiModeAvailable={p.apiModeAvailable}
        {...definedProps({ source: {
          onExecutionModeChange: p.onExecutionModeChange,
          byokRuntime: p.byokRuntime,
          onByokModelChange: p.onByokModelChange,
        } })}
      />
    ),
  }, { leadingAccessory: p.leadingAccessory });

  const { rootRef, controlsRef } = useChatPaneControlsHeight();
  const selectSuggestion = useChatPaneSuggestion({ rootRef, setDraft: pane.composer.setDraft });
  const openLinkInNewTab = useChatPaneNewTabLinks();
  const { pendingPrompts, projectFileNameSet } = useChatPaneTranscriptProps(
    { pane },
    definedProps({ source: { projectFileNames: p.projectFileNames } }),
  );

  return (
    <section
      className={chatPaneClassName(p.variant, p.className)}
      style={p.style}
      data-activity={pane.activity}
      ref={rootRef}
      onClickCapture={openLinkInNewTab}
    >
      <style data-jini-chat-pane-styles="true">{CHAT_PANE_STYLES}</style>
      {/* The former forwarding helper only moved this nested `??` out of ChatPane's score. */}
      {p.header ?? defaultHeader(p.title, pane.reset, t)}
      {p.agentPluginsMode !== 'off' && <AgentPluginUsage conversationId={pane.conversation.conversationId} messages={pane.conversation.messages} />}
      <div className="jini-chat-pane__body">
        <ChatPaneTranscript
          pane={pane}
          emptyState={p.emptyState}
          embed={surface.embed}
          suggestions={p.suggestions}
          onSelectSuggestion={selectSuggestion}
          pendingPrompts={pendingPrompts}
          projectFileNameSet={projectFileNameSet}
          toolCallDisplay={p.toolCallDisplay}
          showUsageLine={p.showUsageLine}
          showThinking={p.showThinking}
          t={t}
        />
        <div className="jini-chat-pane__controls" ref={controlsRef}>
          {showsControlsSuggestions(surface.embed, pane.conversation.messages.length, p.emptyState) && (
            <ChatPaneSuggestionsRow suggestions={p.suggestions} onSelect={selectSuggestion} t={t} />
          )}
          {pane.secretRedacted ? <div className="jini-chat-pane__notice" role="status">{t(SECRET_REDACTED_NOTICE)}</div> : null}
          <ChatPaneStatusMessages
            unavailable={unavailable}
            scanningAgents={runtimeView.scanningAgents}
            connectingAgents={runtimeView.connectingAgents}
            executionMode={p.executionMode}
            apiModeAvailable={p.apiModeAvailable}
            onExecutionModeChange={p.onExecutionModeChange}
            sendError={pane.conversation.sendError}
            onRetrySend={() => void pane.retrySend()}
            attachmentError={pane.attachmentError}
            dropReadError={fileDrop.dropReadError}
            workingDirectoryError={pane.workingDirectoryError}
            workingDirectoryPending={pane.workingDirectoryPending}
            workingDirectoryInvalid={pane.workingDirectoryInvalid}
            runtimeInventoryError={inventory.runtimeInventoryError}
            typedAnswerNotice={pane.typedAnswerNotice}
            t={t}
          />
          <ChatPaneComposerArea
            fileDrop={fileDrop}
            uploadAttachments={surface.uploadAttachments}
            pane={pane}
            disabled={p.disabled}
            unavailable={unavailable}
            placeholder={composerPlaceholder}
            slots={slots}
            attachmentAccept={p.attachmentAccept}
            workingDirectoryAccess={p.workingDirectoryAccess}
            workingDirectoryControlPlacement={surface.workingDirectoryControlPlacement}
            t={t}
          />
        </div>
      </div>
      {p.footer}
    </section>
  );
}

import type { ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { RemixIcon, infoTipBubbleStyle, useInfoTip } from '@jini-ai/ui';

import { useRuntimeDropUp, type UseRuntimeDropUpResult } from '../hooks/useRuntimeDropUp.hooks.js';

export interface RuntimeDropUpProps {
  /** Names both the trigger (with the current value appended) and the menu. */
  label: string;
  /** What the trigger shows: the current choice's display label. */
  valueLabel: string;
  /** A shorter form the trigger shows instead (e.g. "Opus 5.5"); the full `valueLabel` then
   *  appears in a hover/focus tooltip and stays the trigger's accessible name. */
  triggerLabel?: string | undefined;
  value: string;
  options: readonly { id: string; label: string }[];
  onSelect: (id: string) => void;
  /** Small muted line above the options (e.g. the model catalog's "Cached · …" note). */
  note?: string | undefined;
  /** Menu width cap in px; the menu is also clamped to the viewport. */
  width: number;
  className?: string;
}

type RuntimeDropUpTip = ReturnType<typeof useInfoTip>;

/** The full `valueLabel` in the same white bubble `InfoTip` uses, portalled to `document.body`. */
function RuntimeDropUpTipBubble({ tip, valueLabel }: { tip: RuntimeDropUpTip; valueLabel: string }): ReactNode {
  return createPortal(
    <span
      ref={tip.bubbleRef}
      className={tip.placement === 'below' ? 'info-tip-bubble info-tip-bubble-below' : 'info-tip-bubble'}
      role="presentation"
      aria-hidden="true"
      style={infoTipBubbleStyle(tip.coords)}
    >
      {valueLabel}
    </span>,
    document.body,
  );
}

interface RuntimeDropUpMenuProps {
  dropUp: UseRuntimeDropUpResult;
  label: string;
  value: string;
  options: RuntimeDropUpProps['options'];
  onSelect: (id: string) => void;
  note: string | undefined;
}

function RuntimeDropUpMenu({ dropUp, label, value, options, onSelect, note }: RuntimeDropUpMenuProps): ReactNode {
  if (!dropUp.open || !dropUp.position) return null;
  return (
    <div
      ref={dropUp.menuRef}
      id={dropUp.menuId}
      role="menu"
      aria-label={label}
      className="jini-runtime-dropup"
      style={dropUp.position}
      onKeyDown={dropUp.handleMenuKeyDown}
    >
      {note ? <div className="jini-runtime-dropup__note">{note}</div> : null}
      {options.map((option) => {
        const active = option.id === value;
        return (
          <button
            type="button"
            role="menuitemradio"
            aria-checked={active}
            className={`jini-runtime-dropup__item${active ? ' is-active' : ''}`}
            key={option.id}
            onClick={() => dropUp.choose(() => onSelect(option.id))}
          >
            <span className="jini-runtime-dropup__item-label">{option.label}</span>
            {active ? <RemixIcon name="check-line" size={16} className="jini-runtime-check" /> : null}
          </button>
        );
      })}
    </div>
  );
}

/**
 * A compact, borderless "Label ⌄" trigger in the composer bar that opens a menu of choices above
 * itself. Used for the model and the reasoning effort; the selection itself stays with the caller.
 *
 * @complexity Time/space: O(n) in the option count.
 */
export function RuntimeDropUp({
  label,
  valueLabel,
  triggerLabel,
  value,
  options,
  onSelect,
  note,
  width,
  className,
}: RuntimeDropUpProps): ReactNode {
  const dropUp = useRuntimeDropUp({ width });
  const { menuId, open, triggerRef, toggleOpen, handleTriggerKeyDown } = dropUp;
  // The same white bubble as `InfoTip` (its hook places it), rather than the browser's own title
  // tooltip; only when the trigger shows a shortened label, so there is something to reveal.
  const tip = useInfoTip({}, { placement: 'top' });
  const shortened = triggerLabel !== undefined && triggerLabel !== valueLabel;
  // No tip over the open menu, which already lists the full name.
  const tipVisible = shortened && !open;
  const showTip = () => {
    if (tipVisible) tip.show();
  };

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        className={`jini-runtime-dropup-trigger${className ? ` ${className}` : ''}`}
        aria-label={`${label}: ${valueLabel}`}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={menuId}
        {...(shortened ? {} : { title: valueLabel })}
        onClick={() => {
          tip.hide();
          toggleOpen();
        }}
        onKeyDown={(event) => {
          if (event.key === 'Escape') tip.hide();
          handleTriggerKeyDown(event);
        }}
        onMouseEnter={showTip}
        onMouseLeave={tip.leave}
        onFocus={showTip}
        onBlur={tip.hide}
      >
        <span ref={tip.iconRef} className="jini-runtime-dropup-trigger__label">{triggerLabel ?? valueLabel}</span>
        <RemixIcon name="arrow-down-s-line" size={15} className="jini-runtime-trigger__chevron" />
      </button>
      {tip.open && tipVisible ? <RuntimeDropUpTipBubble tip={tip} valueLabel={valueLabel} /> : null}
      <RuntimeDropUpMenu dropUp={dropUp} label={label} value={value} options={options} onSelect={onSelect} note={note} />
    </>
  );
}

/**
 * @module create-daemon-attachment-uploader
 *
 * The client half of `@jini-ai/http-kit`'s attachment capability: a ready-made
 * `ChatPaneProps['uploadAttachments']` that talks to `POST`/`DELETE /api/attachments`.
 *
 * ```tsx
 * <ChatPane transport={transport} uploadAttachments={createDaemonAttachmentUploader({ baseUrl: daemonUrl, fetch })} />
 * ```
 *
 * That one line is the whole wire-up for composer drag-and-drop and the file picker — `ChatPane`
 * gates both on `uploadAttachments` being present (see `ChatPane.tsx`'s `resolveDropTargetProps`).
 *
 * **Why the client enforces quotas at all**, when the daemon enforces them anyway: a user who drags
 * in a 400 MB video should be told immediately, not after the browser has finished streaming it to
 * localhost. These checks are a courtesy, never the security boundary — the daemon re-derives every
 * one of them, and only its answer decides anything.
 *
 * **Bounded concurrency, preserved order.** Two workers pull from a shared index, so at most two
 * requests are in flight while results still land at their input positions. The first failure aborts
 * the rest and deletes whatever already landed, so a partly-uploaded turn never leaves files behind
 * on the daemon waiting for their TTL.
 *
 * **`content-type` is always `application/octet-stream`**, deliberately not `file.type`. The daemon
 * sniffs the real kind from the leading bytes and ignores this header entirely, so forwarding the
 * browser's guess buys nothing — and actively breaks things: a dropped `.json` file gets
 * `content-type: application/json` from the browser, which an app-wide `express.json()` on the
 * daemon then claims, draining the request stream before the upload route can read a byte. A fixed
 * octet-stream type is immune to every body parser.
 */
import type { ChatAttachment } from '@jini-ai/chat';
import type { ChatPaneAttachmentUploadOptions, ChatPaneProps } from './types.js';

export interface CreateDaemonAttachmentUploaderOptions {
  /** Per-file cap checked before any request is sent. Defaults to 20 MB, matching the route pack. */
  readonly maxAttachmentBytes?: number;
  /** Files per composer turn. Defaults to 10, matching the route pack. */
  readonly maxAttachmentCount?: number;
  /** Total bytes per composer turn. Defaults to 50 MB, matching the route pack. */
  readonly maxBatchBytes?: number;
  /** Abort deadline for one call, covering every file in it. Defaults to 30s. */
  readonly timeoutMs?: number;
  /** In-flight uploads. Defaults to 2 — enough to hide latency, few enough to stay ordered and cheap. */
  readonly concurrency?: number;
}

interface UploadResponse {
  attachment?: ChatAttachment;
}

/** Either error envelope a daemon may answer with: this package's `{ error }`, or a bare `{ message }`. */
interface ErrorResponseBody {
  error?: { message?: string };
  message?: string;
}

const DEFAULTS = {
  maxAttachmentBytes: 20 * 1024 * 1024,
  maxAttachmentCount: 10,
  maxBatchBytes: 50 * 1024 * 1024,
  timeoutMs: 30_000,
  concurrency: 2,
} as const;

const BATCH_USAGE_TTL_MS = 60 * 60 * 1_000;
const MAX_TRACKED_BATCHES = 100;

/** Renders a byte cap the way a person reads it, so the message a user sees says "20 MB". */
function formatByteLimit(bytes: number): string {
  const megabytes = bytes / (1024 * 1024);
  return Number.isInteger(megabytes) ? `${megabytes} MB` : `${bytes} bytes`;
}

interface BatchUsage {
  count: number;
  bytes: number;
  touchedAt: number;
}

/**
 * Per-uploader running totals, so a user who drops three files and then two more is held to the
 * same per-turn quota as one who drops five at once. Bounded in both age and size: a composer that
 * is open for days must not accumulate one entry per turn forever.
 */
function pruneBatchUsage(batchUsage: Map<string, BatchUsage>, now: number): void {
  for (const [batchId, usage] of batchUsage) {
    if (now - usage.touchedAt >= BATCH_USAGE_TTL_MS) batchUsage.delete(batchId);
  }
  if (batchUsage.size >= MAX_TRACKED_BATCHES) {
    // Evicts oldest-first (a Map iterates in insertion order) until there is room for one more. A
    // Map at or above the cap is necessarily non-empty, so slicing its keys is total — expressed
    // this way rather than as a `keys().next().value` loop, whose `undefined` case could not happen
    // and so could never be tested.
    const excess = [...batchUsage.keys()].slice(0, batchUsage.size - MAX_TRACKED_BATCHES + 1);
    for (const batchId of excess) batchUsage.delete(batchId);
  }
}

/** Pulls the most useful message out of whichever error envelope the daemon used. */
async function messageForFailedUpload(response: Response, fallback: string): Promise<string> {
  try {
    const body = (await response.json()) as ErrorResponseBody;
    return body.error?.message ?? body.message ?? fallback;
  } catch {
    // A non-JSON body (an HTML error page from a proxy, an empty 502) tells the user nothing useful.
    return fallback;
  }
}

interface UploadQuota {
  readonly maxAttachmentBytes: number;
  readonly maxAttachmentCount: number;
  readonly maxBatchBytes: number;
}

/** Refuses a selection that would break a per-file, per-turn count, or per-turn byte quota. */
function assertWithinQuota({ files, current, incomingBytes, quota }: {
  files: readonly File[];
  current: BatchUsage;
  incomingBytes: number;
  quota: UploadQuota;
}): void {
  if (files.some((file) => file.size > quota.maxAttachmentBytes)) {
    throw new Error(`Each attachment must be ${formatByteLimit(quota.maxAttachmentBytes)} or smaller.`);
  }
  if (current.count + files.length > quota.maxAttachmentCount) {
    throw new Error(`You can attach at most ${quota.maxAttachmentCount} files to one message.`);
  }
  if (current.bytes + incomingBytes > quota.maxBatchBytes) {
    throw new Error(`Attachments for one message must total ${formatByteLimit(quota.maxBatchBytes)} or less.`);
  }
}

/** Forwards the composer's abort (including one that already happened) into `controller`; returns the unlink. */
function linkParentAbort({ controller, parent }: {
  controller: AbortController;
  parent: AbortSignal | undefined;
}): () => void {
  if (parent === undefined) return () => {};
  const abortFromParent = () => controller.abort(parent.reason);
  parent.addEventListener('abort', abortFromParent, { once: true });
  if (parent.aborted) abortFromParent();
  return () => parent.removeEventListener('abort', abortFromParent);
}

/**
 * Runs `concurrency` workers over a shared index, writing each result at its input position in
 * `uploaded`. Never rejects: the first failure is returned (and aborts the rest) instead.
 */
async function uploadInOrder({ files, concurrency, controller, uploaded, uploadOne }: {
  files: readonly File[];
  concurrency: number;
  controller: AbortController;
  uploaded: Array<ChatAttachment | undefined>;
  uploadOne: (file: File) => Promise<ChatAttachment>;
}): Promise<unknown> {
  let nextIndex = 0;
  let firstError: unknown;
  const worker = async (): Promise<void> => {
    while (!controller.signal.aborted) {
      const index = nextIndex;
      nextIndex += 1;
      const file = files[index];
      if (file === undefined) return;
      try {
        uploaded[index] = await uploadOne(file);
      } catch (error) {
        // Kept, not thrown: aborting stops the sibling worker, and the *first* failure is the one
        // worth reporting — the aborts it causes are noise.
        firstError ??= error;
        controller.abort();
      }
    }
  };
  await Promise.all(Array.from({ length: concurrency }, worker));
  return firstError;
}

/** Throws the turn's first upload failure, else the abort that stopped it; returns when neither happened. */
function throwIfUploadFailed({ firstError, signal }: { firstError: unknown; signal: AbortSignal }): void {
  if (firstError !== undefined) throw firstError;
  if (signal.aborted) {
    throw signal.reason instanceof Error
      ? signal.reason
      : new Error('Attachment upload was canceled.');
  }
}

/**
 * Builds a `ChatPaneProps['uploadAttachments']` bound to one daemon.
 *
 * @param baseUrl Origin (or same-origin path prefix) the daemon's API is reachable at. Pass `''`
 * when the page is served through a proxy that already forwards `/api`.
 */
export function createDaemonAttachmentUploader({ baseUrl, fetch }: { baseUrl: string; fetch?: typeof globalThis.fetch }, options: CreateDaemonAttachmentUploaderOptions = {}
): NonNullable<ChatPaneProps['uploadAttachments']> {
  const quota: UploadQuota = {
    maxAttachmentBytes: options.maxAttachmentBytes ?? DEFAULTS.maxAttachmentBytes,
    maxAttachmentCount: options.maxAttachmentCount ?? DEFAULTS.maxAttachmentCount,
    maxBatchBytes: options.maxBatchBytes ?? DEFAULTS.maxBatchBytes,
  };
  const timeoutMs = options.timeoutMs ?? DEFAULTS.timeoutMs;
  const concurrency = options.concurrency ?? DEFAULTS.concurrency;
  const endpoint = `${baseUrl.replace(/\/$/u, '')}/api/attachments`;
  // Read per request rather than captured once, so a global installed after construction is used.
  const send: typeof globalThis.fetch = (input, init) => (fetch ?? globalThis.fetch)(input, init);
  // Per-uploader, not module-level: two panes pointed at two daemons must not share a quota.
  const batchUsage = new Map<string, BatchUsage>();

  async function uploadOne(file: File, batchId: string, signal: AbortSignal): Promise<ChatAttachment> {
    const query = new URLSearchParams({ batch: batchId, name: file.name });
    const response = await send(`${endpoint}?${query}`, {
      method: 'POST',
      // Fixed, not `file.type` — see this module's doc.
      headers: { 'content-type': 'application/octet-stream' },
      body: file,
      signal,
    });
    if (!response.ok) {
      throw new Error(await messageForFailedUpload(response, `Could not attach ${file.name}`));
    }
    const body = (await response.json()) as UploadResponse;
    if (!body.attachment) {
      throw new Error(`The daemon did not return an attachment for ${file.name}`);
    }
    return body.attachment;
  }

  async function deletePartialUpload(
    batchId: string,
    attachments: readonly ChatAttachment[],
  ): Promise<void> {
    if (attachments.length === 0) return;
    try {
      // QUICK, not `uploadOne`'s own composed timeout: unlike the upload itself, this has no
      // caller-supplied signal to compose with and no large body — it is a small best-effort JSON
      // DELETE, and an unprotected `fetch` here would hang `uploadAttachments`'s rejection (the
      // `await` below) on a stalled daemon instead of surfacing `firstError` promptly.
      await send(
        endpoint,
        {
          method: 'DELETE',
          signal: AbortSignal.timeout(15_000),
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ batchId, paths: attachments.map((attachment) => attachment.path) }),
        },
      );
    } catch {
      // Best effort by design: the daemon expires unclaimed uploads on its own, so a failed cleanup
      // costs disk until the TTL rather than leaking indefinitely. Never worth failing the turn for.
    }
  }

  return async function uploadAttachments(
    files: File[],
    uploadOptions?: ChatPaneAttachmentUploadOptions,
  ): Promise<ChatAttachment[]> {
    if (files.length === 0) return [];
    const now = Date.now();
    pruneBatchUsage(batchUsage, now);
    const batchId = uploadOptions?.batchId ?? crypto.randomUUID();
    const incomingBytes = files.reduce((total, file) => total + file.size, 0);
    const current = batchUsage.get(batchId) ?? { count: 0, bytes: 0, touchedAt: now };
    assertWithinQuota({ files, current, incomingBytes, quota });

    // Reserved up front and rolled back on failure, so two overlapping calls for the same turn
    // cannot each see the same free headroom.
    batchUsage.set(batchId, {
      count: current.count + files.length,
      bytes: current.bytes + incomingBytes,
      touchedAt: now,
    });
    const controller = new AbortController();
    const unlinkParentAbort = linkParentAbort({ controller, parent: uploadOptions?.signal });
    const timeout = globalThis.setTimeout(
      () => controller.abort(new DOMException('Attachment upload timed out', 'TimeoutError')),
      timeoutMs,
    );
    const uploaded: Array<ChatAttachment | undefined> = new Array(files.length);
    const settled = (): ChatAttachment[] =>
      uploaded.filter((attachment): attachment is ChatAttachment => attachment !== undefined);

    // The failure is captured rather than rethrown from inside the `try`, so that the timer/listener
    // teardown in `finally` has exactly two reachable paths (the turn succeeded, or it did not)
    // instead of a third that a rethrowing `catch` would create and nothing could ever exercise.
    let failure: unknown;
    let succeeded = false;
    try {
      const firstError = await uploadInOrder({
        files,
        concurrency,
        controller,
        uploaded,
        uploadOne: (file) => uploadOne(file, batchId, controller.signal),
      });
      throwIfUploadFailed({ firstError, signal: controller.signal });
      succeeded = true;
    } catch (error) {
      failure = error;
    } finally {
      globalThis.clearTimeout(timeout);
      unlinkParentAbort();
    }
    if (succeeded) return settled();
    // Roll the reservation back only after the daemon-side files are gone, so a retry of this turn
    // starts from a clean slate on both sides.
    await deletePartialUpload(batchId, settled());
    batchUsage.set(batchId, current);
    throw failure;
  };
}

import { pickerModelLabel } from '../model-options.js';
/**
 * All of `AgentRuntimePicker`'s behavior, so the component itself is only markup.
 *
 * What lives here is popover mechanics — open/close, dismissal, viewport-bounded positioning,
 * focus restoration, and roving/trapped keyboard focus — plus the two derived labels the view
 * shows. None of it is chat-specific; the only reason it is scoped to this feature rather than
 * promoted to `@jini-ai/ui` is noted at the bottom of this comment.
 *
 * The pure functions below are separated from the hook deliberately: geometry and key-to-index
 * resolution have real input/output contracts and edge cases (viewport clamping, `currentIndex`
 * of `-1`, Tab-at-an-edge) that are far cheaper to test directly than to drive through a rendered
 * popover with a mocked `getBoundingClientRect`. The hook itself owns only React lifecycle.
 *
 * **Not yet using `@jini-ai/ui`'s `useDismissOnOutsideOrEscape`**, which covers the same
 * outside-click/Escape ground and whose own doc notes six features had hand-rolled it before this
 * one. Two concrete mismatches block a drop-in: it takes a single `containerRef`, whereas here
 * "inside" means the trigger *or* the portaled popover (two disjoint subtrees, since the popover
 * renders into `document.body`); and it exposes one `onDismiss` with no indication of which input
 * dismissed, while this popover must restore focus on the next tick for a pointer and immediately
 * for Escape (see the comment on that timeout). Consolidating means extending the shared hook to
 * accept multiple containers and report the dismissal cause — worth doing, but as its own change
 * to a package other features already depend on, not as a side effect of this extraction.
 */
import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type RefObject,
} from 'react';

import { orderChatPaneAgents } from '../rules.js';
import type {
  ByokRuntimeSummary,
  ChatPaneAgent,
  ChatPaneAgentSelection,
  RuntimePickerPlacement,
} from '../types.js';

/** Everything in the popover a roving/trapping key handler is allowed to move focus between. */
const FOCUSABLE_CONTROLS = 'button:not(:disabled), select:not(:disabled), input:not(:disabled)';

/**
 * Resolves the user-facing label for a selected model or reasoning option.
 *
 * @complexity Time: O(n) in the supplied option count; space: O(1).
 * @overallScore 100/100
 */
export function runtimeOptionLabel({ options, value, fallback }: { options: readonly { id: string; label: string }[] | undefined; value: string | undefined; fallback: string }
): string {
  if (!value || value === 'default') return fallback;
  return options?.find((option) => option.id === value)?.label ?? value;
}

/**
 * Computes a viewport-bounded fixed position for the body-portaled picker, centred on the trigger
 * and clamped into the viewport and (when given) into `bounds`. `bounds` (the composer box) keeps a
 * popover centred on an icon near a narrow dock's left edge from spilling onto the page beside it,
 * the same clamp `runtimeDropUpPosition` applies to the model/effort drop-ups.
 *
 * @complexity Time/space: O(1).
 * @overallScore 100/100
 */
export function runtimePopoverPosition(
  { trigger, placement }: { trigger: DOMRect; placement: RuntimePickerPlacement },
  { bounds }: { bounds?: Pick<DOMRect, 'left' | 'right'> } = {},
): CSSProperties {
  const margin = 12;
  const gap = 8;
  const minLeft = Math.max(margin, bounds?.left ?? -Infinity);
  const maxRight = Math.min(window.innerWidth - margin, bounds?.right ?? Infinity);
  const width = Math.max(0, Math.min(320, maxRight - minLeft));
  const left = Math.min(
    Math.max(trigger.left + trigger.width / 2 - width / 2, minLeft),
    maxRight - width,
  );
  if (placement === 'up') {
    const availableHeight = Math.max(0, trigger.top - margin - gap);
    return {
      position: 'fixed',
      left,
      bottom: Math.max(margin, window.innerHeight - trigger.top + gap),
      width,
      maxHeight: Math.min(620, availableHeight),
      overflowY: 'auto',
      zIndex: 1000,
    };
  }
  const top = trigger.bottom + gap;
  const availableHeight = Math.max(0, window.innerHeight - top - margin);
  return {
    position: 'fixed',
    top,
    left,
    width,
    maxHeight: Math.min(620, availableHeight),
    overflowY: 'auto',
    zIndex: 1000,
  };
}

/** `Tab` wraps focus around the popover's control list instead of leaving it (the popover is a
 * modal-ish dialog). Returns the index to wrap TO, or `null` when `Tab` should behave natively
 * (not at an edge). `currentIndex` may be `-1` (active element not in `controls`); `atStart`/
 * `atEnd` below only matter when it legitimately is 0 or `count - 1`. */
export function resolveTabWrapIndex({ shiftKey, currentIndex, count }: { shiftKey: boolean; currentIndex: number; count: number }): number | null {
  if (shiftKey && currentIndex === 0) return count - 1;
  if (!shiftKey && currentIndex === count - 1) return 0;
  return null;
}

/** Arrow/Home/End roving-tabindex target, or `null` for any other key. `currentIndex === -1`
 * (nothing in `controls` focused yet) is a legitimate input — the modulo arithmetic below relies
 * on it wrapping the same way a real index would. */
export function resolveRovingIndex({ key, currentIndex, count }: { key: string; currentIndex: number; count: number }): number | null {
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  if (key === 'ArrowDown') return (currentIndex + 1 + count) % count;
  if (key === 'ArrowUp') return (currentIndex - 1 + count) % count;
  return null;
}

/**
 * The control index the popover's key handler should move focus to, or `null` to leave focus alone
 * (and, in the caller, to skip `preventDefault()`). `Tab` is resolved and returned immediately —
 * it must never fall through to the roving-tabindex logic below it.
 */
export function resolvePopoverKeyAction({ key, shiftKey, isButtonTarget, currentIndex, count }: { key: string; shiftKey: boolean; isButtonTarget: boolean; currentIndex: number; count: number }
): number | null {
  if (key === 'Tab') return resolveTabWrapIndex({ shiftKey: shiftKey, currentIndex: currentIndex, count: count });
  // Native selects own their arrow/Home/End behavior. Roving applies only
  // when a button (including the agent radios) has focus.
  if (!isButtonTarget) return null;
  return resolveRovingIndex({ key: key, currentIndex: currentIndex, count: count });
}

/** Builds the one-line "which runtime am I talking to" summary shown in the popover head. */
export function runtimeSummaryText({ selectedAgent, modelLabel, t }: { selectedAgent: ChatPaneAgent | undefined; modelLabel: string; t: (key: string) => string }
): string {
  if (selectedAgent === undefined) return t('No agent selected');
  const version = selectedAgent.version ? ` · ${selectedAgent.version}` : '';
  return `${selectedAgent.name}${version} · ${modelLabel}`;
}

/**
 * The head/trigger labels while `executionMode` is `'api'`.
 *
 * Separate from {@link runtimeSummaryText} rather than folded into it because the two describe
 * different things and fail differently: that one names a detected CLI and its model, this one
 * names a provider and the model the credential is configured for, and neither has a sensible
 * fallback to the other. A missing provider label here is not "no agent selected" — the API path is
 * still what will run — so the fallback is a generic mode name, never a CLI's.
 *
 * @complexity Time/space: O(1).
 */
export function byokSummaryText({ byokRuntime, t }: { byokRuntime: ByokRuntimeSummary | undefined; t: (key: string) => string }
): { title: string; modelLabel: string; summary: string } {
  const title = byokRuntime?.providerLabel?.trim() || t('API · BYOK');
  const model = byokRuntime?.model?.trim();
  const modelLabel = model || t('No model configured');
  return { title, modelLabel, summary: `${title} · ${modelLabel}` };
}

export interface UseAgentRuntimePickerOptions {
  agents: readonly ChatPaneAgent[];
  value: ChatPaneAgentSelection;
  placement: RuntimePickerPlacement;
  /** Translator, injected rather than read from context so this hook is testable without a provider. */
  t: (key: string) => string;
  /** Which runtime the labels below should describe. Defaults to `'local'`, preserving the
   *  pre-BYOK behavior for every caller that does not pass one. */
  executionMode?: 'local' | 'api';
  /** Only read when `executionMode` is `'api'`. Explicitly `| undefined` because the package builds
   *  under `exactOptionalPropertyTypes` and the component forwards its own optional prop straight
   *  through. */
  byokRuntime?: ByokRuntimeSummary | undefined;
}

export interface UseAgentRuntimePickerResult {
  /** Ties the trigger's `aria-controls` to the popover's `id`. */
  dialogId: string;
  open: boolean;
  /** Undefined until the trigger has been measured; the popover does not render before then. */
  position: CSSProperties | undefined;
  triggerRef: RefObject<HTMLButtonElement | null>;
  popoverRef: RefObject<HTMLDivElement | null>;
  /** Unavailable agents removed, then ordered — what the radio group renders. */
  orderedAgents: readonly ChatPaneAgent[];
  selectedAgent: ChatPaneAgent | undefined;
  modelLabel: string;
  runtimeSummary: string;
  /** What the collapsed trigger names as the runtime — the selected CLI in `'local'`, the provider
   *  in `'api'`. A separate field because the trigger must NOT fall back to `selectedAgent.name`
   *  while an API turn is what would actually run. */
  triggerTitle: string;
  /**
   * The `data-theme` of the place the popover was opened FROM, or `null` when the host pins none.
   *
   * The popover renders through `createPortal` into `document.body`, so it escapes any `data-theme`
   * on an ancestor of the trigger — and `@jini-ai/ui` themes entirely through `[data-theme]` token
   * blocks, with its DARK values on a bare `@media (prefers-color-scheme: dark) { :root { … } }`.
   * The consequence is not hypothetical: measured in a host admin on a dark-mode machine, the
   * popover itself looked right (the chat package's own `--jini-chat-*` tokens default light) while
   * the `@jini-ai/ui` control inside it — the BYOK model select — resolved against that dark `:root`
   * block and rendered dark-on-dark inside an all-light admin.
   *
   * So the popover carries its origin's theme with it, the same compensation `CustomSelect` already
   * makes for its own portaled menu. `null` leaves document-level theming untouched, so a host that
   * pins nothing is byte-identical to before.
   */
  originTheme: string | null;
  toggleOpen: () => void;
  handlePopoverKeyDown: (event: ReactKeyboardEvent<HTMLDivElement>) => void;
}

/**
 * Owns the runtime picker's popover state so the component stays presentational.
 *
 * @complexity Time: O(n) in the agent count for ordering/selection; space: O(n) for the ordered
 * snapshot. The DOM queries are O(c) in the popover's own control count.
 */
export function useAgentRuntimePicker({
  agents,
  value,
  placement,
  t,
  executionMode = 'local',
  byokRuntime,
}: UseAgentRuntimePickerOptions): UseAgentRuntimePickerResult {
  const dialogId = useId();
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState<CSSProperties>();
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const popoverRef = useRef<HTMLDivElement | null>(null);

  const orderedAgents = useMemo(
    () => orderChatPaneAgents({ agents: agents.filter((agent) => agent.available !== false && agent.id !== 'gemini') }),
    [agents],
  );
  const selectedAgent = orderedAgents.find((agent) => agent.id === value.agentId);

  // `selectedAgent` stays resolved in BOTH modes on purpose — the CLI selection is still the stored
  // one, and switching back to Local CLI must not have silently lost it. What changes in `'api'` is
  // only what gets DESCRIBED, because none of the CLI's labels are true of an API turn.
  const localModelLabel = pickerModelLabel(selectedAgent, value.model, t);
  const byok = byokSummaryText({ byokRuntime: byokRuntime, t: t });
  const isApi = executionMode === 'api';
  const modelLabel = isApi ? byok.modelLabel : localModelLabel;
  const runtimeSummary = isApi ? byok.summary : runtimeSummaryText({ selectedAgent: selectedAgent, modelLabel: localModelLabel, t: t });
  const triggerTitle = isApi ? byok.title : (selectedAgent?.name ?? t('Choose agent'));

  // Read during render rather than in an effect: the popover only mounts once `open` is true, which
  // is itself a re-render, and `triggerRef` is populated at the first commit — so by the time this
  // value is used it is always resolved. See `originTheme` on the result type for why it exists.
  const originTheme = triggerRef.current?.closest('[data-theme]')?.getAttribute('data-theme') ?? null;

  const focusTrigger = useCallback(() => {
    triggerRef.current?.focus();
  }, []);

  const toggleOpen = useCallback(() => {
    setOpen((current) => !current);
  }, []);

  useEffect(() => {
    if (!open) return;
    const closeOnOutsidePointer = (event: MouseEvent) => {
      const target = event.target as Node;
      if (
        triggerRef.current?.contains(target)
        || popoverRef.current?.contains(target)
        // A control INSIDE the popover may itself portal its menu to `document.body` —
        // `@jini-ai/ui`'s `CustomSelect` (and so `SearchableModelSelect`, which the BYOK model row
        // uses) does exactly that. Such a menu is a descendant of neither ref, so without this the
        // first mousedown on a model option would be read as an outside click and close the
        // popover out from under the selection the operator was making.
        || (target instanceof Element && target.closest('.jini-select-menu') !== null)
      ) return;
      setOpen(false);
      // Let the pointer's click complete before restoring focus. Otherwise the
      // browser focuses the clicked node after this mousedown handler runs.
      window.setTimeout(focusTrigger, 0);
    };
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      setOpen(false);
      focusTrigger();
    };
    document.addEventListener('mousedown', closeOnOutsidePointer);
    document.addEventListener('keydown', closeOnEscape);
    return () => {
      document.removeEventListener('mousedown', closeOnOutsidePointer);
      document.removeEventListener('keydown', closeOnEscape);
    };
  }, [focusTrigger, open]);

  useEffect(() => {
    if (!open) return;
    const update = () => {
      const rect = triggerRef.current?.getBoundingClientRect();
      const bounds = triggerRef.current?.closest('.jini-composer')?.getBoundingClientRect();
      if (rect) setPosition(runtimePopoverPosition({ trigger: rect, placement: placement }, bounds ? { bounds } : {}));
    };
    update();
    window.addEventListener('resize', update);
    // Capture phase: a scroll inside any ancestor moves the trigger too, and scroll does not bubble.
    window.addEventListener('scroll', update, true);
    return () => {
      window.removeEventListener('resize', update);
      window.removeEventListener('scroll', update, true);
    };
  }, [open, placement]);

  useEffect(() => {
    if (!open || !position) return;
    const popover = popoverRef.current;
    const selectedRadio = popover?.querySelector<HTMLElement>('[role="radio"][aria-checked="true"]');
    const fallback = popover?.querySelector<HTMLElement>(FOCUSABLE_CONTROLS);
    (selectedRadio ?? fallback)?.focus();
  }, [open, position]);

  const handlePopoverKeyDown = useCallback((event: ReactKeyboardEvent<HTMLDivElement>) => {
    // No `?? []` fallback for a null ref: this handler is only ever reachable via the
    // `onKeyDown` React wires to the exact element `popoverRef` is attached to, and
    // React attaches refs during commit — before that element can dispatch any event — so
    // `popoverRef.current` is guaranteed non-null by the time this runs.
    const controls = [...popoverRef.current!.querySelectorAll<HTMLElement>(FOCUSABLE_CONTROLS)];
    if (controls.length === 0) return;

    const currentIndex = controls.indexOf(document.activeElement as HTMLElement);
    const nextIndex = resolvePopoverKeyAction({ key: event.key, shiftKey: event.shiftKey, isButtonTarget: event.target instanceof HTMLButtonElement, currentIndex: currentIndex, count: controls.length }
    );
    if (nextIndex === null) return;
    event.preventDefault();
    controls[nextIndex]?.focus();
  }, []);

  return {
    dialogId,
    open,
    position,
    triggerRef,
    popoverRef,
    orderedAgents,
    selectedAgent,
    modelLabel,
    runtimeSummary,
    triggerTitle,
    originTheme,
    toggleOpen,
    handlePopoverKeyDown,
  };
}

