    const adoptingRef = useRef<Promise<string | null> | null>(null);
    /**
     * Bumped by {@link resetAdoption}. An adoption captures it and re-checks before publishing.
     *
     * `switchSeqRef` cannot do this job, and the version that tried was wrong in a way only a
     * specific ordering exposes: `select(B)` bumps the switch token *at call time*, so an
     * `onMessagesChange` arriving from the outgoing pane a moment later reads the ALREADY-bumped
     * value. B's load then commits (its own token still current), and the adoption resolves with a
     * token that still matches — so it published `activeId = A` while `paneKey` and `initialMessages`
     * were B's. The pane showed B's transcript and wrote it into A. Clearing `adoptingRef` in that
     * commit does not help either: it drops the reference, not the promise that is already running.
     *
     * So invalidation gets its own counter, bumped by the one function whose entire job is "this
     * adoption no longer belongs to anything".
     */
    const adoptionGenRef = useRef(0);
    /**
     * Makes each "fresh pane" key distinct.
     *
     * Resetting to a constant `"new"` is not enough: a pane that lazily adopted a conversation still
     * has `paneKey === "new"`, so deleting that conversation would set the key to the value it already
     * has, skip the remount, and leave the deleted chat's transcript sitting on screen.
     */
    const paneNonceRef = useRef(0);
    /** Stops a sleeping write retry from firing against a dock that is no longer mounted. */
    const disposedRef = useRef(false);

    useEffect(() => {
      // Reset on mount rather than only setting on unmount. StrictMode runs mount → unmount → mount
      // in development, so a cleanup-only version would latch `true` on the throwaway first pass and
      // leave every retry disabled for the real one — a bug that exists only in dev, which is the
      // worst place for it to hide.
      disposedRef.current = false;
      return () => {
        disposedRef.current = true;
      };
    }, []);

    /**
     * Bumped by every local mutation of the conversation list, so an older server snapshot cannot
     * overwrite it.
     *
     * The race without it: the mount `refresh()` is in flight and will resolve to `[]`. Before it
     * lands, the user creates (or lazily adopts) conversation A, which is inserted optimistically.
     * The stale response then arrives and replaces the list with `[]` — `activeId` still points at A,
     * but the switcher no longer lists it and the header falls back to the default title, so a real
     * conversation is invisible until some later write happens to refresh again.
     */
    const listSeqRef = useRef(0);
    /**
     * Titles whose PATCH is still in flight, by conversation id, each tagged with the rename that
     * queued it. Applied over every list read until that rename settles — see `refresh`.
     *
     * The version tag is what lets a settling rename clear only its OWN entry. A plain `delete(id)`
     * would drop a second, newer rename of the same conversation that queued while the first was in
     * flight, reopening the exact window this exists to close.
     */
    const pendingRenamesRef = useRef<Map<string, { version: number; title: string }>>(new Map());
    const renameVersionRef = useRef(0);
    /**
     * Mirrors the last `conversations` state this hook actually committed.
     *
     * The one consumer is `remove()`'s fallback, for exactly the case its own `refresh()` comes back
     * stale (a faster, concurrent mutation resolved first and is already reflected in state). Reading
     * `conversations` itself is not an option: the closure `remove` was built from can be arbitrarily
     * many renders behind by the time its `await`s resolve, and adding it as a dependency would just
     * reintroduce the identity churn `portRef`/`activeIdRef` exist to avoid.
     *
     * A plain `useEffect` is the right tool here, unlike for `portRef`/`activeIdRef` above: those had
     * to be current for a delta `ChatPane` — a CHILD — forwards inside the very commit that changed
     * them, and child effects run before parent effects, so an effect always lagged by exactly the
     * commit that mattered. `remove()`'s fallback is read from inside an already-`await`ed
     * continuation, at least one microtask after any mutation that would have updated it — well after
     * this hook's own effects for that commit have flushed. There is no same-commit reader to race.
     */
    const conversationsRef = useRef<AssistantConversation[]>([]);
    useEffect(() => {
      conversationsRef.current = conversations;
    }, [conversations]);

    /**
     * Re-reads the list, and reports whether the snapshot was still current when it arrived.
     *
     * The `fresh` flag is not decoration. An earlier version returned the list unconditionally with a
     * comment claiming `remove` needed the server's view regardless — which handed `remove` exactly
     * the snapshot this function had just decided was too stale to render: conversation A is active,
     * `remove(A)` starts a list read whose response still contains C, C is deleted meanwhile and a
     * newer refresh completes, then A's older response arrives, is correctly refused by
     * `setConversations`, and is still handed back. `remove` routes to C, so `activeId` lands on a
     * conversation that no longer exists and every subsequent message is written at a dead row.
     */
    const refresh = useCallback(async () => {
      const seq = ++listSeqRef.current;
      // `null` marks a failed read, so the mount-time restore can tell "not listed" from "no list".
      const read = await portRef.current.listConversations({}, {}).catch(() => null);
      const listed = read ?? [];
      /*
       * A rename whose PATCH has not settled wins over whatever the server just said.
       *
       * `markListMutated` cannot cover this, and assuming it did was the bug: that counter answers
       * "did a response from BEFORE my write land after it?", and says nothing about a read that
       * STARTS after the optimistic update but reaches a server which has not applied the PATCH yet.
       * Such a read is legitimately `fresh`, so it wrote the old title straight over the new one —
       * rename a conversation, let any unrelated activity trigger a refresh (a message save completing
       * elsewhere is enough), and the title visibly reverted until the rename's own trailing refresh
       * corrected it.
       */
      const pending = pendingRenamesRef.current;
      const conversations =
        pending.size === 0
          ? listed
          : listed.map((conversation) => {
              const rename = pending.get(conversation.id);
              return rename
                ? { ...conversation, title: rename.title, titleSource: "manual" as const }
                : conversation;
            });
      const fresh = listSeqRef.current === seq;
      // Not written to state when superseded: a local insert that landed while this was in flight is
      // strictly newer than this snapshot.
      if (fresh) setConversations(conversations);
      return { conversations, fresh, failed: read === null };
    }, []);

    /** Records a local list mutation, invalidating any `refresh` already in flight. */
    const markListMutated = useCallback(() => {
      listSeqRef.current += 1;
    }, []);

    /**
     * Discards any lazy adoption belonging to a pane that is about to be replaced.
     *
     * `adoptingRef` is scoped to exactly one pane — it names the conversation *that* pane adopted —
     * and every path that re-keys the pane has to clear it. The path that did not was a real fault:
     * delete your only conversation and `activeId` returns to `null`, which routes the next message
     * down the lazy-adoption branch, where `??=` found the previous pane's already-resolved promise
     * still naming the conversation that had just been deleted. The messages were `PUT` at a row that
     * no longer existed (404, silently), `activeId` was never set again, and no new conversation was
     * ever created — so the dock persisted nothing at all for the rest of the session. That is the
     * same user-visible symptom lazy adoption was introduced to fix, reachable by a different route.
     */
    /**
     * Sets `activeId` and its mirror ref together. Nothing may call `setActiveId` directly.
     *
     * The ref exists because `onMessagesChange` and `remove` have to know where writes go *now*, not
     * as of the render they closed over. It used to be kept current by a render-phase
     * `activeIdRef.current = activeId`, which is the same hazard the `portRef` comment above rejects:
     * a render React later discards has already published its id, and a delta from the still-
     * committed tree then routes a message into a conversation that was never actually selected.
     *
     * An effect is the usual remedy and is wrong here too — child effects run before parent effects,
     * so `ChatPane` can forward a delta before the sync effect runs, and the ref lags by a commit at
     * the exact moment it is being read. Writing both together at the point of decision avoids both:
     * every call site below is an event handler or a promise continuation, never a render, so the ref
     * is published only when the change is real and is never behind the state.
     */
    const commitActiveId = useCallback((id: string | null) => {
      activeIdRef.current = id;
      setActiveId(id);
      // The single point every active-conversation change passes through — select, create, lazy
      // adoption, and delete's landing — so the remembered id can never lag what is on screen.
      if (id === null) lastConversationRef.current?.clear();
      else lastConversationRef.current?.write(id);
    }, []);

    const resetAdoption = useCallback(() => {
      adoptingRef.current = null;
      // The half that actually stops an already-running adoption from publishing — see
      // `adoptionGenRef`. Dropping the reference alone only prevents *reuse*.
      adoptionGenRef.current += 1;
    }, []);

    /**
     * Publishes `activeId` and `initialMessages` in one commit, and only once the transcript is in
     * hand.
     *
     * Setting `activeId` first is what the obvious version does, and it is wrong in a way that is
     * invisible in tests: `activeId` is `ChatPane`'s `key`, so assigning it remounts the pane
     * *immediately*, while `initialMessages` still holds the conversation being navigated away from.
     * `ChatPane` reads `initialMessages` at mount only, so the fresh transcript — arriving a tick
     * later — was silently discarded and the pane displayed the previous chat's messages under the
     * new chat's title.
     *
     * The display fault was the mild half. The pane then reported that stale transcript through
     * `onMessagesChange`, and because `writtenRef` for the newly selected conversation was still
     * empty, every one of those messages was queued as an unsaved message *belonging to the new
     * conversation*. Observed live: selecting an empty chat fired four `PUT`s carrying the previous
     * chat's messages. They 404'd only because those message ids already existed under their real
     * conversation — an accident of the primary key, not a safeguard. Seeding `writtenRef` in the
     * same commit as the id is what actually closes that hole.
     *
     * React batches both setters (and the ref write precedes them), so the pane remounts exactly
     * once, already knowing what it holds and what has been persisted.
     */
    const select = useCallback(
      (id: string) => {
        const seq = ++switchSeqRef.current;
        const commit = (messages: ChatMessage[]) => {
          // A slower load for a conversation the user has since navigated away from must not land.
          if (switchSeqRef.current !== seq) return;
          writtenRef.current.set(id, new Set(messages.map(message => messageWriteKey({ message }, {}))));
          setInitialMessages(messages);
          commitActiveId(id);
          // A user-initiated switch is exactly when remounting the pane IS the intent.
          setPaneKey(id);
          resetAdoption();
        };
        void portRef.current
          .loadMessages({ conversationId: id }, {})
          .then(commit)
          // A failed load still switches, to an empty pane: leaving the user on the previous
          // conversation while its title says otherwise is the worse of the two failures.
          .catch(() => commit([]));
      },
      // `commitActiveId` added: it's a `useCallback([], ...)`-wrapped setter (see its own
      // declaration above), stable for the component's lifetime — no-op addition, not a suppression.
      [resetAdoption, commitActiveId],
    );

    /**
     * The mount-time list read, which also reopens the conversation this browser was last on.
     *
     * Declared after `select` because it calls it — moved here from beside `refresh` for that
     * reason only; the read itself is unchanged.
     *
     * The restore is skipped if the operator has already acted (switched, created, or started typing
     * into the empty pane, which adopts a conversation) before the list arrived: their own action is
     * newer intent than a memory from the previous page load. `switchSeqRef` covers select/create,
     * `activeIdRef`/`adoptingRef` cover lazy adoption. Under StrictMode's double mount the first
     * restore's `select` bumps `switchSeqRef`, so the second one stands down rather than loading twice.
     */
    useEffect(() => {
      const store = lastConversationRef.current;
      if (!store) {
        void refresh();
        return;
      }
      const remembered = store.read();
      const intentAtMount = switchSeqRef.current;
      void refresh().then(({ conversations, failed }) => {
        const decision = resolveRememberedConversation({ remembered, conversations, listFailed: failed });
        if (decision === "forget") forgetRemembered(store, remembered);
        const untouched = switchSeqRef.current === intentAtMount && activeIdRef.current === null && adoptingRef.current === null;
        if (decision === "restore" && untouched) select(remembered as string);
      });
    }, [refresh, select]);

    const create = useCallback(async () => {
      /*
       * The token is claimed BEFORE the request, and re-checked after.
       *
       * Claiming it after `createConversation()` resolved made "New" the winner of every race it
       * happened to finish last: click New, change your mind, pick chat B from the list, watch B load —
       * and then the earlier POST returns and yanks you into an empty new chat. Bumping up front
       * registers the intent at the moment of the click; re-checking means a selection made *after*
       * the click still wins, which is the ordering a user expects.
       *
       * The conversation row is still created either way. That is deliberate — it exists server-side,
       * and abandoning it silently would be worse than leaving an empty chat in the list.
       */
      const seq = ++switchSeqRef.current;
      const conversation = await portRef.current.createConversation({}, {});
      // Both branches insert locally, so both have to invalidate an in-flight `refresh` — otherwise a
      // list snapshot taken before this POST lands overwrites the row that was just added.
      markListMutated();
      if (switchSeqRef.current !== seq) {
        // Superseded: surface the new row in the list, but do not steal the user's current view.
        setConversations((current) => [conversation, ...current]);
        return;
      }
      setConversations((current) => [conversation, ...current]);
      commitActiveId(conversation.id);
      setInitialMessages([]);
      setPaneKey(conversation.id);
      writtenRef.current.set(conversation.id, new Set());
      resetAdoption();
      // `commitActiveId` added: stable `useCallback([], ...)` wrapper, see `select`'s identical note.
    }, [markListMutated, resetAdoption, commitActiveId]);

    const remove = useCallback(
      async (id: string) => {
        await portRef.current.deleteConversation({ id }, {});
        writtenRef.current.delete(id);
        const snapshot = await refresh();
        if (activeIdRef.current !== id) return;
        /*
         * A stale snapshot must not be trusted for routing: if this list read landed superseded (the
         * user deleted something else while it was in flight), it can still name a conversation that
         * has since been deleted, and routing there would strand `activeId` on a row no fresh list
         * will ever contain again — `select`'s `.catch(() => commit([]))` even dresses that up as a
         * successful switch to an empty pane.
         *
         * `fresh` is exactly the signal for that, and the earlier gap was checking it for nothing:
         * this used `snapshot.conversations` regardless of `fresh`. Falling back to `conversationsRef`
         * — mirroring the last state this hook actually committed, kept current by the effect above —
         * instead of an unguarded stale read closes it: by the time this snapshot is judged stale,
         * whatever concurrent mutation outraced it has already had its own `refresh()` commit, which
         * is what "stale" means here. `id` is filtered out regardless, so the row just deleted can
         * never be the landing spot even from the fallback.
         */
        const remaining = (snapshot.fresh ? snapshot.conversations : conversationsRef.current).filter(
          (conversation) => conversation.id !== id,
        );
        // Land on the next most recent chat rather than an empty pane with no way back.
        const next = remaining[0]?.id ?? null;
        if (!next) {
          // Nothing left to land on. Bump the token so a switch still in flight cannot resurrect a
          // transcript into the now-empty pane.
          switchSeqRef.current += 1;
          commitActiveId(null);
          setInitialMessages([]);
          paneNonceRef.current += 1;
          setPaneKey(`new-${paneNonceRef.current}`);
          // The branch `resetAdoption` exists for: this is the one place `activeId` goes back to
          // `null`, which is the only state that re-enters the lazy-adoption path. Without this the
          // fresh pane inherits the deleted conversation's adoption and never persists again.
          resetAdoption();
          return;
        }
        /*
         * `select` and ONLY `select` — deliberately no `setActiveId(next)` first.
         *
         * Setting the id here looks harmless and is not: `activeId` is `ChatPane`'s `key`, so it
         * remounts the pane immediately with `initialMessages` still empty, and then `select`'s own
         * commit sets `activeId` to the value it ALREADY has. The key never changes again, so the pane
         * is never remounted, and `ChatPane` seeds `initialMessages` at mount only — nothing resets it
         * on a prop change. The empty transcript is therefore permanent, not a flicker: deleting the
         * active chat landed on the next one showing no history at all, and the next prompt was sent
         * without it as context. `select` alone publishes id, transcript and written-ids in one commit.
         */
        select(next);
      },
      // `commitActiveId` added (used a few lines above, in the "nothing left to land on" branch):
      // stable `useCallback([], ...)` wrapper, see `select`'s identical note.
      [refresh, resetAdoption, select, commitActiveId],
    );

    const rename = useCallback(
      async (id: string, title: string) => {
        // Optimistic: a rename that only appears after a round-trip feels broken during the edit.
        // `markListMutated` for the same reason `create` needs it — this is a local write to the
        // list, so a refresh already in flight is now older than it. Without the mark, that older
        // response lands and the title visibly reverts to its previous value until the refresh below
        // corrects it a moment later.
        markListMutated();
        // Held until the PATCH settles, so any refresh landing in between re-applies this title
        // instead of trusting a server read that has not caught up yet.
        const version = ++renameVersionRef.current;
        pendingRenamesRef.current.set(id, { version, title });
        setConversations((current) =>
          current.map((c) => (c.id === id ? { ...c, title, titleSource: "manual" as const } : c)),
        );
        try {
          await portRef.current.renameConversation({ id, title }, {});
        } catch {
          // Swallowed as before — the trailing refresh shows whatever the server actually has, which
          // is the correct outcome for a failed rename too.
        } finally {
          // Only if no NEWER rename of this conversation has queued behind us.
          if (pendingRenamesRef.current.get(id)?.version === version) {
            pendingRenamesRef.current.delete(id);
          }
        }
        void refresh();
      },
      [markListMutated, refresh],
    );

    const saveTrackedMessage = useCallback(({ conversationId, message }: { conversationId: string; message: ChatMessage }, _optional = {}): Promise<SaveOutcome> => {
      const pending = messagePendingRef.current.get(conversationId) ?? new Map<string, Promise<SaveOutcome>>();
      messagePendingRef.current.set(conversationId, pending);
      const key = messageWriteKey({ message }, {});
      const existing = pending.get(key);
      if (existing) return existing;
      const write = (async () => {
        await runStubPendingRef.current.get(conversationId)?.get(key);
        return saveWithRetry(portRef.current, conversationId, message, () => disposedRef.current);
      })();
      pending.set(key, write);
      void write.then(() => {
        pending.delete(key);
        if (pending.size === 0) messagePendingRef.current.delete(conversationId);
      });
      return write;
    }, []);

    /** Writes whatever in `messages` has settled and is not already stored, into `conversationId`. */
    const flush = useCallback(
      (conversationId: string, messages: ChatMessage[]) => {
        const written = writtenRef.current.get(conversationId) ?? new Set<string>();
        writtenRef.current.set(conversationId, written);

        // Keyed by message id AND run id (see `messageWriteKey`), so a retry's new run is saved too.
        const pending = persistableMessages({ messages }, {}).filter((m) => !written.has(messageWriteKey({ message: m }, {})));
        if (pending.length === 0) return;

        // Marked before the request resolves so a second `onMessagesChange` arriving mid-flight —
        // which it will, since deltas keep coming — does not queue the same message twice.
        for (const message of pending) written.add(messageWriteKey({ message }, {}));

        void Promise.all(
          pending.map(async (message) => {
            return {
              message,
              outcome: await saveTrackedMessage({ conversationId, message }, {}),
            };
          }),
        ).then((results) => {
          /*
           * Un-marked ONLY when the write could plausibly succeed later.
           *
           * Un-marking on any failure — which this did — turns a permanent error into a permanent
           * load: the id goes back in the queue, the next `onMessagesChange` re-sends it, it fails
           * identically, and it is un-marked again. One 400 therefore issues a doomed request on
           * every subsequent delta for the rest of the session, and they accumulate as more messages
           * fail the same way. `saveWithRetry` has already spent its attempts by this point, so
           * "exhausted" is the only outcome where another try is worth queueing at all.
           *
           * `some`, not "all succeeded": one message failing must not suppress the list refresh for
           * the others. The first turn is what gives an untitled chat its name server-side, and
           * `messageCount` changes on every turn, so the list needs re-reading rather than patching.
           * A write that spent its whole ladder on 404s means this conversation may no longer exist —
           * re-read so the switcher stops showing a row the server has already forgotten, rather than
           * leaving the pane to grind out doomed writes with nothing visible anywhere in the UI.
           * See {@link summarizeFlushOutcomes} for the decision itself.
           */
          const { idsToRelease, shouldRefresh } = summarizeFlushOutcomes(
            results,
            activeIdRef.current === conversationId,
          );
          for (const id of idsToRelease) written.delete(id);
          if (shouldRefresh) void refresh();
        });
      },
      [refresh, saveTrackedMessage],
    );

    /**
     * Writes ONE user turn durably, right now, and reports nothing back but completion.
     *
     * Defect 2 of the 2026-09-11 chat-lifecycle repair. Until this existed, the only writer of a user
     * turn was {@link flush} — driven asynchronously off `onMessagesChange` deltas, with no ordering
     * relationship at all to `assistant-transport.ts`'s `POST /api/runs`. The two are not atomic: a
     * run could be (and was) dispatched while the message it was dispatched for had not been written
     * anywhere, so a failure in that window left the user's words in a browser tab and nowhere else.
     * `startRun` awaits this first, including any PUT already scheduled by `flush`. Acceptance also
     * persists the exact user payload with its stub, covering exhausted browser writes and tab loss.
     *
     * Shares `writtenRef` with `flush` deliberately — that is what makes the two writers cooperate
     * rather than duplicate. The id is marked before the request for the same reason `flush` marks
     * before its own resolves (a delta arriving mid-flight must not queue the same message again),
     * and released again on a failure `saveWithRetry` has already given up on, so `flush` still gets
     * its chance rather than the message being silently recorded as stored.
     *
     * @param conversationId - The conversation the turn belongs to. Supplied by the caller (which has
     *   just resolved it through {@link ensureConversationId}) rather than read from `activeIdRef`,
     *   so a run and its message can never land in two different conversations.
     * @param message - The exact `ChatMessage` being sent. Its `id` is the idempotency key:
     *   `saveMessage` PUTs to `/messages/<id>`, so writing the same message twice is one row.
     * @returns Nothing, always — never rejects. A caller that cannot make the turn durable must still
     *   be able to send it.
     * @complexity O(1) plus one PUT and its retry ladder.
     */
    const persistUserTurn = useCallback(async (conversationId: string, message: ChatMessage): Promise<void> => {
      const written = writtenRef.current.get(conversationId) ?? new Set<string>();
      writtenRef.current.set(conversationId, written);
      const key = messageWriteKey({ message }, {});
      // A new chat's first delta often reaches flush before transport reaches this method. The
      // dedup bit then means "scheduled", not "committed"; wait on the same PUT before dispatch.
      const pending = messagePendingRef.current.get(conversationId)?.get(key);
      if (pending) { await pending; return; }
      if (written.has(key)) return;
      written.add(key);

      const outcome = await saveTrackedMessage({ conversationId, message }, {});
      // Same rule `summarizeFlushOutcomes` applies to a settled batch, for the same reason: only an
      // outcome that could plausibly succeed later is worth handing back to `flush`. Re-queueing a
      // permanent failure would make every later delta re-send a doomed request.
      if (outcome !== "saved") written.delete(key);
    }, [saveTrackedMessage]);

    /**
     * Writes the ONE extra durable row a future reattach needs: a non-terminal assistant message's
     * `runId`, captured the moment it appears — see `assistant-chats.ts`'s {@link activeRunStub} for
     * why this is not already covered by {@link flush}.
     *
     * Deliberately best-effort and silent on a PERMANENT failure, unlike {@link persistUserTurn}: a
     * lost stub write only means a future reattach has nothing to find for this run, the same
     * degraded-but-safe outcome as today (nothing reattaches yet regardless — see the 2026-09-11
     * investigation this exists for). It must never surface as a chat-breaking error over what is, at
     * worst, a missed optimization. A TRANSIENT failure (503, a dropped connection) is left for the
     * next delta to retry for free: `id` is released so a later call with the same message id tries
     * again, exactly like {@link persistUserTurn}'s own release-on-failure.
     *
     * No retry ladder of its own (unlike `persistUserTurn`'s `saveWithRetry`): the run is still
     * streaming, so another `onMessagesChange` delta — and therefore another chance — arrives on its
     * own within moments. A run that ends before any further delta fires has nothing left worth
     * reattaching to anyway.
     *
     * Daemon acceptance now closes that former gap before dispatch. This best-effort path remains
     * only for request-bound BYOK/AG-UI; browser daemon stubs cannot own durable attempt state.
     * @complexity O(1) plus at most one `PUT`.
     */
    const persistRunStub = useCallback((conversationId: string, message: ChatMessage): void => {
      // Daemon acceptance commits the stub before dispatch; browser snapshots cannot own it.
      if (message.runId && !ports.requestRunPrefixes.some(prefix => message.runId!.startsWith(prefix))) return;
      const written = runStubWrittenRef.current.get(conversationId) ?? new Set<string>();
      runStubWrittenRef.current.set(conversationId, written);
      // Per run, not per message id: a retry reuses the id with a new run (see `messageWriteKey`).
      const key = messageWriteKey({ message }, {});
      if (written.has(key)) return;
      // This run's final result is already saved. A retry resets the message to `queued` while it still
      // carries the OLD run id; writing that would put a stale stub over the saved answer.
      if (writtenRef.current.get(conversationId)?.has(key)) return;
      written.add(key);
      const pending = runStubPendingRef.current.get(conversationId) ?? new Map<string, Promise<void>>();
      runStubPendingRef.current.set(conversationId, pending);
      const write = portRef.current.saveMessage({ conversationId, message }, {}).catch(() => {
        written.delete(key);
      }).finally(() => {
        pending.delete(key);
        if (pending.size === 0) runStubPendingRef.current.delete(conversationId);
      });
      pending.set(key, write);
    }, []);

    /**
     * This pane's conversation id, adopting one if that is what it takes — the single owner of lazy
     * adoption, awaited by {@link onMessagesChange} below and by `assistant-transport.ts`'s `startRun`
     * (via `AssistantDock`'s `useAssistantTransport`).
     *
     * `startRun` is the reason this is exposed rather than staying inline in `onMessagesChange`.
     * Adoption used to be reachable ONLY from a message delta, and `@jini-ai/chat`'s
     * `useChatPane.sendPrompt` freezes `runContext(...)` into the run's context object BEFORE it calls
     * `conversation.sendMessage(...)` — the very call that produces that first delta. So on turn 1 the
     * run was always dispatched with no `conversationId`, `agent-daemon-server.ts`'s `onStarted` skipped
     * its whole session-capture subscription (`if (conversationId !== undefined)`), and the agent-CLI
     * session id turn 2 needed to resume was never stored. Turn 2 then started cold while the client,
     * trusting that resume, had sent only the bare latest user message: the conversation's history was
     * gone, silently, at exactly the turn-1→turn-2 boundary of every chat.
     *
     * `setActiveId` WITHOUT `setPaneKey`: the pane may be mid-run and is keyed on `paneKey`, so leaving
     * that alone is what keeps this invisible to the user. Re-keying here would remount the pane and
     * destroy the reply currently streaming into it.
     *
     * @returns The conversation id writes and runs for this pane belong to, or `null` when creation
     *   failed. Never rejects — a caller that cannot get an id (`startRun`) must still be able to send
     *   the turn: one run with no resumable session is a far smaller loss than a run that never happens.
     * @complexity O(1) plus at most one `POST /conversations`, shared across concurrent callers.
     */
    const ensureConversationId = useCallback((): Promise<string | null> => {
      const active = activeIdRef.current;
      if (active) return Promise.resolve(active);

      /*
       * The adoption generation is READ here, and `resetAdoption` is the only thing that bumps it.
       *
       * Deliberately NOT `switchSeqRef`. That token is bumped at the *call* of `select`/`create`,
       * so an adoption starting after the click reads the already-bumped value, matches it when the
       * adoption resolves, and publishes `activeId` into a pane that has since been re-keyed to
       * someone else's transcript. `adoptionGenRef` moves with the commit rather than the intent,
       * which is the thing this actually needs to be later than.
       */
      const generation = adoptionGenRef.current;
      // `??=` so a run start and the deltas racing it await ONE creation, not two — otherwise a single
      // turn splits across two conversations, the run filed under one and the messages under the other.
      const adoption = (adoptingRef.current ??= portRef.current
        .createConversation({}, {})
        .then((conversation) => {
          markListMutated();
          setConversations((current) => [conversation, ...current]);
          writtenRef.current.set(conversation.id, new Set());
          // Superseded: the row exists and shows up in the list, but the pane that asked for it is
          // gone, so pointing `activeId` at it would send the NEXT pane's writes here. The caller's
          // own follow-up still runs either way — those messages came from the pane that asked for
          // this conversation, and dropping them would be the data loss adoption exists to prevent.
          if (adoptionGenRef.current === generation) commitActiveId(conversation.id);
          return conversation.id;
        })
        .catch(() => null));

      void adoption.then((id) => {
        /*
         * Cleared so a later turn can retry; keeping a rejected promise would wedge persistence for
         * the rest of the session.
         *
         * Guarded on identity, because a bare `adoptingRef.current = null` clears whatever is there
         * NOW, which need not be this promise. A stale adoption rejecting late would wipe a newer one
         * that is still in flight, and the next delta would start a third — two conversations created
         * for one turn, with the same messages flushed into both and whichever resolved last taking
         * `activeId`.
         */
        if (!id && adoptingRef.current === adoption) adoptingRef.current = null;
      });

      return adoption;
    }, [markListMutated, commitActiveId]);

    const onMessagesChange = useCallback(
      (messages: ChatMessage[]) => {
        // Computed once up front, independent of which branch below actually runs — both need it, and
        // it is O(1) (last element only, see `activeRunStub`'s own doc), so there is no cost to paying
        // it on every delta even on the branch that turns out not to use it.
        const stub = activeRunStub({ messages }, {});
        const conversationId = activeIdRef.current;
        if (conversationId) {
          if (stub) persistRunStub(conversationId, stub);
          flush(conversationId, messages);
          return;
        }

        /*
         * No conversation is active — and this is the DEFAULT state, not an edge case. Nothing selects
         * a conversation on mount, so opening the admin and typing straight into the dock (without
         * first clicking "New" or picking from history) landed here, where the old code simply
         * returned. The run worked on screen and neither turn was ever stored: the entire conversation
         * vanished on reload, silently, on the most common path through the feature.
         *
         * So adopt one lazily, at the first moment there is actually something to save. Created on
         * demand rather than on mount, because a row per admin page-load would litter the switcher with
         * empty conversations. `startRun` now usually gets here first (see {@link ensureConversationId}),
         * in which case `??=` makes this await that same creation rather than starting a second.
         */
        if (persistableMessages({ messages }, {}).length === 0 && !stub) return;

        void ensureConversationId().then((id) => {
          if (!id) return;
          if (stub) persistRunStub(id, stub);
          flush(id, messages);
        });
      },
      // Adoption itself now lives in `ensureConversationId` (stable `useCallback`, see its own doc),
      // so `markListMutated`/`commitActiveId` are no longer read here.
      [flush, ensureConversationId, persistRunStub],
    );

    // Boundary adapters keep the hook's stable action identities and lexical race guards intact.
    const actions = useMemo(() => ({
      select: ({ id }: { id: string }, _options: Record<string, never> = {}) => select(id),
      create: (_required: Record<string, never>, _options: Record<string, never> = {}) => create(),
      remove: ({ id }: { id: string }, _options: Record<string, never> = {}) => remove(id),
      rename: ({ id, title }: { id: string; title: string }, _options: Record<string, never> = {}) => rename(id, title),
      onMessagesChange: ({ messages }: { messages: ChatMessage[] }, _options: Record<string, never> = {}) => onMessagesChange(messages),
      ensureConversationId: (_required: Record<string, never>, _options: Record<string, never> = {}) => ensureConversationId(),
      persistUserTurn: ({ conversationId, message }: { conversationId: string; message: ChatMessage }, _options: Record<string, never> = {}) => persistUserTurn(conversationId, message),
    }), [select, create, remove, rename, onMessagesChange, ensureConversationId, persistUserTurn]);
    return { conversations, activeId, paneKey, initialMessages, ...actions };
  }

  return {
    giveUpOutcome: ({ error }: { error: unknown }, _options: Record<string, never> = {}) => giveUpOutcome(error),
    handleSaveFailure: ({ error, conversationId, message, attempt, isDisposed }: { error: unknown; conversationId: string; message: ChatMessage; attempt: number; isDisposed: () => boolean }, _options: Record<string, never> = {}) => handleSaveFailure(error, conversationId, message, attempt, isDisposed),
    attemptSave: ({ port, conversationId, message, attempt, isDisposed }: { port: AssistantChatsPort; conversationId: string; message: ChatMessage; attempt: number; isDisposed: () => boolean }, _options: Record<string, never> = {}) => attemptSave(port, conversationId, message, attempt, isDisposed),
    summarizeFlushOutcomes: ({ results, isConversationStillActive }: { results: Parameters<typeof summarizeFlushOutcomes>[0]; isConversationStillActive: boolean }, _options: Record<string, never> = {}) => summarizeFlushOutcomes(results, isConversationStillActive),
    resolveRememberedConversation: (required: Parameters<typeof resolveRememberedConversation>[0], _options: Record<string, never> = {}) => resolveRememberedConversation(required),
    useAssistantChats: ({ port }: { port: AssistantChatsPort }, options: { lastConversation?: LastConversationStore } = {}) => useAssistantChats(port, options),
  };
}

/**
 * @module useArtifactStream
 *
 * Streaming artifact buffer + resolved renderer + partial-vs-complete state,
 * built purely over a message's text content via `@jini-ai/chat/core`'s
 * `parseArtifacts` (completed `<artifact>` blocks) and `splitStreamingArtifact`
 * (the currently in-flight one, if any) plus an injected `RendererRegistry`.
 * Per `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §4.
 *
 * `ArtifactFile`/`ArtifactRenderer`/`RendererRegistry` are the local
 * placeholder shapes from `../../artifact-types.js` — see that file's
 * TODO(renderers-react) header for the follow-up to re-point this hook at
 * `@jini-ai/renderers-react`'s real exports.
 */
import { useMemo } from 'react';
import { parseArtifacts, splitStreamingArtifact } from '../../core/index.js';
import type { ArtifactFile, ArtifactRenderMatch, RendererRegistry } from '../artifact-types.js';

export interface ArtifactStreamItem {
  identifier: string;
  artifactType: string;
  title: string;
  content: string;
  status: 'streaming' | 'complete';
  file: ArtifactFile;
  match: ArtifactRenderMatch | null;
}

export interface UseArtifactStreamResult {
  /** Every artifact found in `content`, oldest first. */
  items: ArtifactStreamItem[];
  /** The last item — the one most likely to be "the artifact this turn produced". */
  current: ArtifactStreamItem | null;
}

type ArtifactStreamBase = Omit<ArtifactStreamItem, 'file' | 'match'>;
type ArtifactMeta = Pick<ArtifactStreamItem, 'identifier' | 'artifactType' | 'title'>;

function toItem(base: ArtifactStreamBase, { registry }: { registry?: RendererRegistry | undefined }): ArtifactStreamItem {
  const file: ArtifactFile = { name: base.identifier || base.title || 'artifact', kind: base.artifactType, content: base.content };
  return { ...base, file, match: registry?.resolve({ file }) ?? null };
}

/**
 * Completed artifacts in `head`, oldest first. Only `artifact:start` (for the
 * metadata) and `artifact:end` (whose `fullContent` is the whole body) are
 * needed — `artifact:chunk` deltas are already folded into `fullContent`.
 * `createArtifactParser` never nests and always emits an `artifact:end` with
 * the same identifier right after its `artifact:start`'s chunks, so `meta` is
 * always set when an end arrives.
 */
function collectCompleted(head: string, { registry }: { registry?: RendererRegistry | undefined }): ArtifactStreamItem[] {
  const items: ArtifactStreamItem[] = [];
  let meta: ArtifactMeta | null = null;
  for (const ev of parseArtifacts({ content: head })) {
    if (ev.type === 'artifact:start') {
      meta = { identifier: ev.identifier, artifactType: ev.artifactType, title: ev.title };
    } else if (ev.type === 'artifact:end') {
      items.push(toItem({ ...meta!, content: ev.fullContent, status: 'complete' }, { registry }));
    }
  }
  return items;
}

export function useArtifactStream({ content }: { content: string }, { registry }: { registry?: (RendererRegistry) | undefined } = {}): UseArtifactStreamResult {
  return useMemo(() => {
    // `splitStreamingArtifact` is the authority on "is there a trailing,
    // still-open artifact": split first so `parseArtifacts` (a one-shot
    // feed+flush that synthesizes an `artifact:end` for whatever is still
    // open when it's called — correct for a genuinely complete message, but
    // wrong here) only ever sees the CLOSED-artifact-only `head` portion.
    // Running it on the raw `content` would double-count a live artifact:
    // once (wrongly) as "complete" via the synthetic flush, and again (correctly)
    // as "streaming" below.
    const { head, live } = splitStreamingArtifact({ content: content });
    const items = collectCompleted(head, { registry });

    // A trailing artifact whose close tag hasn't streamed in yet — surfaced
    // separately so a live preview can render mid-generation.
    if (live) items.push(toItem({ ...live, status: 'streaming' }, { registry }));

    return { items, current: items.at(-1) ?? null };
  }, [content, registry]);
}

/**
 * @module useComposer
 *
 * Owns the composer's draft text, staged attachments, `@`-mention popover
 * state, and the selected agent/model/sessionMode. Per
 * `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §4: attachments reach the host
 * only through `ProjectContextValue.uploadFiles`/`ComposerSlots`; no direct
 * provider import. Draft persistence (OD's `ComposerDraftPort`,
 * localStorage-backed) is likewise injectable, not hard-wired — this hook
 * never touches `localStorage` itself; a host that wants persistence passes
 * `persistence` (falling back to in-memory/no persistence when omitted).
 *
 * Origin pattern: OD's `features/chat-composer/hooks/useComposerDraft.hooks.ts`
 * + `useComposerUpload.hooks.ts` + `useMentionPopover.hooks.ts` (branch
 * `refactor/web-chat-composer-slice-pr`), generalized: the Lexical-editor-ref
 * plumbing and localStorage port are OD/DOM-specific and dropped; the
 * draft/attachment/mention/agent-selection *state shape* is kept.
 *
 * `conversationId` (when supplied) keys the draft — and, on a change, the staged attachments and
 * mention popover — against `composer-draft-cache.ts`, so whatever was typed comes back on a switch
 * between conversations, on a `ChatPane` remount, and on a full page reload, without leaking into
 * the wrong conversation. That cache is a separate, always-on mechanism from `persistence` above,
 * which stays an opt-in host-owned slot this hook never touches directly and which still wins at
 * mount when a host wires one; the cache needs no host wiring and is what actually fixes the
 * reported data loss (see its module doc). Staged attachments and the mention popover are
 * deliberately NOT cached across a switch (unlike the draft text): they reference an in-flight
 * upload batch, and carrying them into a different conversation risks attaching the wrong files to
 * the wrong thread, so they are cleared instead.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ChatAttachment, ChatMessage } from '../../core/index.js';
import type { ComposerHistoryStoragePort } from '../../core/composer-history.js';
import { useComposerHistory, type ComposerHistoryController } from './useComposerHistory.hooks.js';
import {
  readCachedAttachments,
  readCachedDraft,
  rememberCachedDraft,
  writeCachedAttachments,
  writeCachedDraft,
} from './composer-draft-cache.js';
import { cacheAttachmentPreviewSource } from './attachment-preview-cache.js';
import type { AgentSelection, ComposerSlots, MentionResult, ProjectContextValue } from '../slots.js';

export interface ComposerDraftPersistence {
  read: () => string | null;
  write: (draft: string) => void;
}

export interface UseComposerOptions {
  initialDraft?: string;
  /** This principal's current transcript; only user-role text participates in recall. */
  historyMessages?: readonly ChatMessage[];
  /** Scopes recent prompts across conversations. Hosts with multiple users must supply an id. */
  historyScope?: string;
  historyStorage?: ComposerHistoryStoragePort;
  /** Recall retention; defaults to 100, with existing duplicate collapse. */
  historyCap?: number;
  initialAgent?: AgentSelection;
  project?: ProjectContextValue;
  composerSlots?: ComposerSlots;
  persistence?: ComposerDraftPersistence;
  /**
   * The active conversation, used to key the per-conversation draft cache (see this module's doc).
   * `null`/absent (an untitled, not-yet-created conversation) opts out of caching entirely — there is
   * nothing to key on yet, and the draft lives only in this hook's own React state until an id
   * exists.
   */
  conversationId?: string | null;
  /**
   * Confirms which of a conversation's previously staged attachments still exist, so a restored
   * draft never shows a chip for a file the host has since garbage-collected — that looks intact and
   * then fails at send, which is worse than not restoring it at all.
   *
   * Receives the cached references and returns the subset still valid (order need not be preserved;
   * an empty array means none survived). A rejection is treated as "none survived" — restoring
   * unverified references is the failure mode this option exists to prevent.
   *
   * **Omitting it disables attachment persistence entirely** — nothing is written and nothing is
   * restored, which is exactly the behavior before this option existed. Only the draft TEXT is
   * persisted then, so a host that cannot answer the liveness question loses nothing and risks
   * nothing. Text and attachments are stored under separate keys and degrade independently.
   *
   * Captured in a ref, so an inline arrow is safe and will not re-run the restore on every render.
   */
  validateAttachments?: (attachments: readonly ChatAttachment[]) => Promise<readonly ChatAttachment[]>;
  /**
   * Where the page-exit signals that flush a pending draft write come from (`pagehide` on the
   * window, `visibilitychange` to hidden on the document). Defaults to the browser's own
   * {@link browserPageLifecycle}; `null` means there is no page to leave (a non-DOM renderer runs
   * effects without `window`), so only unmount, send and switch flush. Captured once at mount.
   */
  pageLifecycle?: ComposerPageLifecycle | null;
}

/** The page-exit event sources {@link useComposer} listens to, injectable so a host or test can supply its own. */
export interface ComposerPageLifecycle {
  readonly window: Pick<Window, 'addEventListener' | 'removeEventListener'>;
  readonly document: Pick<Document, 'addEventListener' | 'removeEventListener' | 'visibilityState'>;
}

/**
 * The real window/document pair, or `null` when this runtime has no `window` — a non-DOM React
 * renderer still runs effects, and subscribing there would throw.
 * @complexity Time/space: O(1).
 */
export function browserPageLifecycle(): ComposerPageLifecycle | null {
  return typeof window === 'undefined' ? null : { window, document };
}

export interface MentionPopoverState {
  open: boolean;
  query: string;
  results: MentionResult[];
}

export interface UseComposerResult {
  draft: string;
  /** Optional for compatibility with host-created composer controllers. */
  history?: ComposerHistoryController;
  setDraft: (next: string) => void;
  attachments: ChatAttachment[];
  /** Uploads via `project.uploadFiles` (when supplied) and stages the results; no-ops (with a rejected promise) when no upload port is wired. */
  addAttachments: (files: File[]) => Promise<void>;
  addAttachment: (attachment: ChatAttachment) => void;
  removeAttachment: (id: string) => void;
  clearAttachments: () => void;
  agent: AgentSelection | undefined;
  setAgent: (next: AgentSelection) => void;
  mention: MentionPopoverState;
  openMention: (query: string) => Promise<void>;
  closeMention: () => void;
  /** Applies a picked mention result to the draft (appends `insertText` or `@label`), then closes the popover. */
  selectMention: (result: MentionResult) => void;
  /** `true` once the draft has content or an attachment — a `<Composer>` gates its send button on this. */
  canSubmit: boolean;
  /** Clears the draft and staged attachments (called after a successful send). */
  reset: () => void;
  /**
   * Writes a draft still waiting out {@link DRAFT_PERSIST_DEBOUNCE_MS} to storage and the host's
   * persistence port now. `<Composer>` calls it on blur. Optional for compatibility with
   * host-created composer controllers.
   */
  flushDraft?: () => void;
}

const EMPTY_MENTION: MentionPopoverState = { open: false, query: '', results: [] };

/**
 * How long typing must pause before the draft reaches `localStorage` and the host's persistence
 * port. Those writes used to run synchronously on every keystroke (owner report 2026-10-08: typing
 * lagged in a long conversation). The in-memory cache tier still updates per keystroke, and every
 * exit path (send, conversation switch, unmount, page hide, blur) writes or discards immediately,
 * so the delay can only cost a draft on a hard crash inside this window.
 */
export const DRAFT_PERSIST_DEBOUNCE_MS = 800;

interface DeferredDraftWrite {
  /** Replaces any pending write with `write`, run once typing pauses. */
  schedule: (write: () => void) => void;
  /** Runs the pending write now, if there is one. */
  flush: () => void;
  /** Drops the pending write without running it. */
  cancel: () => void;
}

/**
 * One pending durable draft write at a time, trailing-edge debounced. Flushes on unmount and when
 * the page is hidden (`pagehide`, or `visibilitychange` to hidden — the last event a mobile browser
 * reliably delivers before discarding the tab).
 * @param pageLifecycle The page-exit event sources, captured at mount; `undefined` resolves the
 *   browser's own, `null` subscribes to nothing (unmount still flushes).
 * @complexity Time/space: O(1) per call.
 */
function useDeferredDraftWrite(pageLifecycle: ComposerPageLifecycle | null | undefined): DeferredDraftWrite {
  const [lifecycle] = useState(() => (pageLifecycle === undefined ? browserPageLifecycle() : pageLifecycle));
  const pendingRef = useRef<{ timer: ReturnType<typeof setTimeout>; write: () => void } | null>(null);

  const cancel = useCallback(() => {
    const pending = pendingRef.current;
    if (!pending) return;
    pendingRef.current = null;
    clearTimeout(pending.timer);
  }, []);

  const flush = useCallback(() => {
    const pending = pendingRef.current;
    if (!pending) return;
    pendingRef.current = null;
    clearTimeout(pending.timer);
    pending.write();
  }, []);

  const schedule = useCallback((write: () => void) => {
    if (pendingRef.current) clearTimeout(pendingRef.current.timer);
    const timer = setTimeout(() => {
      pendingRef.current = null;
      write();
    }, DRAFT_PERSIST_DEBOUNCE_MS);
    pendingRef.current = { timer, write };
  }, []);

  useEffect(() => {
    if (lifecycle === null) return flush;
    const { window: page, document: doc } = lifecycle;
    const onVisibilityChange = () => {
      if (doc.visibilityState === 'hidden') flush();
    };
    page.addEventListener('pagehide', flush);
    doc.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      page.removeEventListener('pagehide', flush);
      doc.removeEventListener('visibilitychange', onVisibilityChange);
      flush();
    };
  }, [flush, lifecycle]);

  return useMemo(() => ({ schedule, flush, cancel }), [schedule, flush, cancel]);
}

export function useComposer(options: UseComposerOptions = {}): UseComposerResult {
  const { project, composerSlots, persistence, conversationId, validateAttachments } = options;
  const [draft, setDraftState] = useState<string>(
    () => options.initialDraft ?? persistence?.read() ?? readCachedDraft({ conversationId: conversationId }) ?? '',
  );
  const [attachments, setAttachments] = useState<ChatAttachment[]>([]);
  const [agent, setAgent] = useState<AgentSelection | undefined>(options.initialAgent);
  const [mention, setMention] = useState<MentionPopoverState>(EMPTY_MENTION);

  const deferredWrite = useDeferredDraftWrite(options.pageLifecycle);
  const commitDraft = useCallback(
    (next: string) => {
      setDraftState(next);
      rememberCachedDraft({ conversationId: conversationId, draft: next });
      const write = () => {
        persistence?.write(next);
        writeCachedDraft({ conversationId: conversationId, draft: next });
      };
      // A cleared draft (send, reset) is written at once and drops any pending write, so a stale
      // timer can never put the sent text back.
      if (next.trim() === '') {
        deferredWrite.cancel();
        write();
        return;
      }
      deferredWrite.schedule(write);
    },
    [persistence, conversationId, deferredWrite],
  );

  const history = useComposerHistory({ setRecalledDraft: setDraftState }, {
    ...(options.historyMessages === undefined ? {} : { messages: options.historyMessages }),
    ...(options.historyScope === undefined ? {} : { scope: options.historyScope }),
    ...(options.historyCap === undefined ? {} : { cap: options.historyCap }),
    ...(options.historyStorage === undefined ? {} : { storage: options.historyStorage }),
    ...(conversationId === undefined ? {} : { conversationId }),
  });
  const setDraft = useCallback((next: string) => {
    history.edit({});
    commitDraft(next);
  }, [commitDraft, history.edit]);

  // Lets the conversation-change effect below read the live draft without taking `draft` as a
  // dependency, which would re-run it on every keystroke.
  const draftRef = useRef(draft);
  draftRef.current = draft;

  // Re-keys the draft (and drops attachments/the mention popover — see this module's doc) when
  // `conversationId` changes WITHOUT a remount — a host that keeps the composer mounted across
  // conversations, unlike a host that remounts `ChatPane` via a conversation-keyed `key` (the
  // `useState` initializer above already handles that case at mount time). Skips the very first
  // render via the ref comparison so it never fights that initializer.
  const previousConversationIdRef = useRef(conversationId);
  useEffect(() => {
    const previousConversationId = previousConversationIdRef.current;
    if (conversationId === previousConversationIdRef.current) return;
    previousConversationIdRef.current = conversationId;
    // The pending write closed over the conversation being left, so this lands under its id.
    deferredWrite.flush();
    const restored = readCachedDraft({ conversationId: conversationId });

    // An id arriving where there was none is NOT a switch between two conversations — it is the one
    // the operator is already looking at finally getting a key (a new chat created server-side
    // mid-compose, or a host that resolves the active id asynchronously after mount). Adopt what
    // they have typed instead of wiping it: writes no-op while the id is absent, so that text
    // exists in this hook's state and nowhere else, and an empty restore must never clobber text
    // the person can currently see. Guarded to `previousConversationId == null` so a real
    // conversation-to-conversation switch still clears, and cannot leak one thread's half-written
    // message into another. Attachments and the mention popover are left alone here for the same
    // reason — nothing was switched away from.
    if (previousConversationId == null && conversationId != null && restored === null && draftRef.current.trim() !== '') {
      writeCachedDraft({ conversationId: conversationId, draft: draftRef.current });
      return;
    }

    setDraftState(restored ?? '');
    setAttachments([]);
    setMention(EMPTY_MENTION);
  }, [conversationId, deferredWrite]);

  // Held in a ref so an inline arrow from the host does not re-run the restore below on every
  // render. Reassigned each render so a host that swaps implementations still gets the new one.
  const validateAttachmentsRef = useRef(validateAttachments);
  validateAttachmentsRef.current = validateAttachments;

  // Which conversation the attachment restore has already settled for. Compared against the live
  // `conversationId` before any persist, so the switch effect's own `setAttachments([])` can never
  // race ahead and delete the conversation being switched TO. `undefined` means "not settled yet",
  // which is why this is not a boolean.
  const attachmentsHydratedForRef = useRef<string | null | undefined>(undefined);

  // Restores previously staged attachments, but only ones the host confirms still exist. Without a
  // validator this does nothing at all: attachment persistence stays off and only the draft text
  // survives, which is the documented default (see `validateAttachments`).
  useEffect(() => {
    const validate = validateAttachmentsRef.current;
    if (!validate || !conversationId) {
      attachmentsHydratedForRef.current = conversationId;
      return;
    }
    const cached = readCachedAttachments({ conversationId: conversationId });
    if (cached === null || cached.length === 0) {
      attachmentsHydratedForRef.current = conversationId;
      return;
    }
    let cancelled = false;
    void (async () => {
      let valid: readonly ChatAttachment[] = [];
      try {
        valid = await validate(cached);
      } catch {
        // A validator that throws tells us nothing about the files, so assume none survived rather
        // than restoring references we cannot vouch for.
        valid = [];
      }
      if (cancelled) return;
      if (valid.length > 0) {
        // Only seeds an untouched composer: anything the operator staged while validation was in
        // flight is theirs and outranks a restore.
        setAttachments((prev) => (prev.length === 0 ? [...valid] : prev));
      } else {
        // Every reference was dead. Purge them so the next load does not pay for this again.
        writeCachedAttachments({ conversationId: conversationId, attachments: [] });
      }
      attachmentsHydratedForRef.current = conversationId;
    })();
    return () => {
      cancelled = true;
    };
  }, [conversationId]);

  // Persists staged attachments once the restore for THIS conversation has settled. Gated on the
  // settle marker so a mount's initial empty `attachments` cannot delete what is still being
  // restored. An empty list deletes the entry, so a send (which clears attachments) also clears the
  // cached references, matching the draft text's own rule.
  useEffect(() => {
    if (!validateAttachmentsRef.current || !conversationId) return;
    if (attachmentsHydratedForRef.current !== conversationId) return;
    writeCachedAttachments({ conversationId: conversationId, attachments: attachments });
  }, [attachments, conversationId]);

  const addAttachment = useCallback((attachment: ChatAttachment) => {
    setAttachments((prev) => [...prev, attachment]);
  }, []);

  const addAttachments = useCallback(
    async (files: File[]) => {
      if (files.length === 0) return;
      if (!project?.uploadFiles) {
        throw new Error('addAttachments requires ProjectContextValue.uploadFiles to be wired by the host');
      }
      const uploaded = await project.uploadFiles(files);
      setAttachments((prev) => [...prev, ...uploaded]);
      // `uploadFiles` resolves 1:1 with `files`, in order, on success (see
      // `create-daemon-attachment-uploader.ts`'s "preserved order" doc) - any failure rejects the
      // whole call instead of returning a short array, so this zip never pairs the wrong bytes with
      // the wrong attachment. Caching the original `File` here, at the one moment this hook already
      // holds it, is what lets `AttachmentPreviewModal` show it again later - see
      // `attachment-preview-cache.ts`'s module doc for why the server cannot hand it back.
      uploaded.forEach((a, i) => {
        const file = files[i];
        if (file) cacheAttachmentPreviewSource({ path: a.path, file });
      });
      for (const a of uploaded) composerSlots?.onAttach?.(a);
    },
    [composerSlots, project],
  );

  const removeAttachment = useCallback((id: string) => {
    setAttachments((prev) => prev.filter((a) => a.path !== id));
  }, []);

  const clearAttachments = useCallback(() => setAttachments([]), []);

  const openMention = useCallback(
    async (query: string) => {
      setMention({ open: true, query, results: [] });
      const sources = composerSlots?.mentionSources ?? [];
      if (sources.length === 0) return;
      const results = (
        await Promise.all(
          sources.map(async (source) => {
            try {
              return await source.search(query);
            } catch {
              return [];
            }
          }),
        )
      ).flat();
      setMention((prev) => (prev.open && prev.query === query ? { ...prev, results } : prev));
    },
    [composerSlots],
  );

  const closeMention = useCallback(() => setMention(EMPTY_MENTION), []);

  const selectMention = useCallback(
    (result: MentionResult) => {
      const insertion = result.insertText ?? `@${result.label} `;
      setDraft(`${draft}${insertion}`);
      setMention(EMPTY_MENTION);
    },
    [draft, setDraft],
  );

  const reset = useCallback(() => {
    setDraft('');
    clearAttachments();
    closeMention();
  }, [clearAttachments, closeMention, setDraft]);

  const canSubmit = draft.trim().length > 0 || attachments.length > 0;

  return useMemo(
    () => ({
      draft,
      history,
      setDraft,
      attachments,
      addAttachments,
      addAttachment,
      removeAttachment,
      clearAttachments,
      agent,
      setAgent,
      mention,
      openMention,
      closeMention,
      selectMention,
      canSubmit,
      reset,
      flushDraft: deferredWrite.flush,
    }),
    [draft, history, setDraft, attachments, addAttachments, addAttachment, removeAttachment, clearAttachments, agent, mention, openMention, closeMention, selectMention, canSubmit, reset, deferredWrite.flush],
  );
}

import { useLayoutEffect, useReducer, useRef, type KeyboardEvent, type RefObject } from 'react';
import type { UseComposerResult } from './useComposer.js';

/** Measures visual lines as well as newlines, so a wrapped paragraph keeps native arrow motion. */
function visualLineBounds({ textarea }: { textarea: HTMLTextAreaElement }) {
  if (textarea.clientWidth === 0) return {};
  const computed = getComputedStyle(textarea);
  const mirror = document.createElement('div');
  for (const property of ['font', 'letter-spacing', 'word-spacing', 'line-height', 'text-indent', 'padding', 'tab-size', 'word-break', 'overflow-wrap', 'direction']) {
    mirror.style.setProperty(property, computed.getPropertyValue(property));
  }
  mirror.style.position = 'fixed';
  mirror.style.visibility = 'hidden';
  mirror.style.pointerEvents = 'none';
  mirror.style.whiteSpace = 'pre-wrap';
  mirror.style.overflowWrap = 'break-word';
  mirror.style.boxSizing = 'border-box';
  mirror.style.width = `${textarea.clientWidth}px`;
  const text = document.createTextNode(textarea.value);
  mirror.append(text, document.createTextNode('\u200b'));
  document.body.append(mirror);
  try {
    function lineAt(offset: number) {
      const range = document.createRange();
      range.setStart(text, offset);
      range.setEnd(text, offset);
      return range.getBoundingClientRect().top;
    }
    const first = lineAt(0);
    const last = lineAt(text.length);
    // Both selection endpoints must be on the boundary visual line. Selecting across soft
    // wraps should stay native just like selecting across explicit newline characters.
    const start = lineAt(textarea.selectionStart);
    const end = lineAt(textarea.selectionEnd);
    return { firstLine: Math.abs(start - first) < 1 && Math.abs(end - first) < 1, lastLine: Math.abs(start - last) < 1 && Math.abs(end - last) < 1 };
  } finally {
    mirror.remove();
  }
}

type CaretPlacement = 'start' | 'end';

function placeCaret(textarea: HTMLTextAreaElement, { placement }: { placement: CaretPlacement }): void {
  const offset = placement === 'start' ? 0 : textarea.value.length;
  textarea.setSelectionRange(offset, offset);
}

function hasModifier(event: KeyboardEvent<HTMLTextAreaElement>): boolean {
  return event.shiftKey || event.ctrlKey || event.altKey || event.metaKey;
}

/** Keys another handler or an IME already owns, or that an open popup should get instead. */
function isClaimedElsewhere(event: KeyboardEvent<HTMLTextAreaElement>, { popupOpen }: { popupOpen: boolean }): boolean {
  return event.defaultPrevented || popupOpen || event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229;
}

function isHistoryKey(event: KeyboardEvent<HTMLTextAreaElement>, { popupOpen }: { popupOpen: boolean }): boolean {
  if (hasModifier(event) || isClaimedElsewhere(event, { popupOpen })) return false;
  return ['ArrowUp', 'ArrowDown', 'Escape'].includes(event.key);
}

export function useComposerHistoryKeys(
  { composer, textareaRef }: { composer: UseComposerResult; textareaRef: RefObject<HTMLTextAreaElement | null> },
  { popupOpen = false }: { popupOpen?: boolean } = {},
) {
  const pendingCaretRef = useRef<CaretPlacement | null>(null);
  // A duplicate history entry can equal the current value, so setDraft may bail out.
  // Still commit the caret request now rather than carrying it into the next real edit.
  const [, requestCaretCommit] = useReducer((revision: number) => revision + 1, 0);
  useLayoutEffect(() => {
    const placement = pendingCaretRef.current;
    if (!placement) return;
    pendingCaretRef.current = null;
    const textarea = textareaRef.current;
    if (textarea) placeCaret(textarea, { placement });
  });

  return (event: KeyboardEvent<HTMLTextAreaElement>): boolean => {
    if (!isHistoryKey(event, { popupOpen })) return false;
    const textarea = event.currentTarget;
    const handled = composer.history?.navigate({
      key: event.key,
      text: textarea.value,
      selectionStart: textarea.selectionStart,
      selectionEnd: textarea.selectionEnd,
      shiftKey: event.shiftKey,
      ctrlKey: event.ctrlKey,
      altKey: event.altKey,
      metaKey: event.metaKey,
      ...visualLineBounds({ textarea }),
    }) ?? false;
    if (handled) {
      event.preventDefault();
      // React's controlled value lands on the following commit. Placing the caret before
      // that commit clamps it to the OLD draft's length and breaks multiline Down gating.
      // Up stays on the first line of even a multiline recall so repeated Up can browse
      // older entries. Down/Escape go to the end, including when restoring the draft.
      const placement: CaretPlacement = event.key === 'ArrowUp' ? 'start' : 'end';
      pendingCaretRef.current = placement;
      requestCaretCommit();
      // Recalling an identical string may not cause a render; the existing value is safe.
      placeCaret(textarea, { placement });
    }
    return handled;
  };
}

import { acceptedInputUserEvent, projectAcceptedInputEvents, type AcceptedChatInput } from '../../core/accepted-input.js';
import { redactUserHistory, redactUserMessage, type UserTextRedactionOptions } from '../../core/user-text-redaction.js';
import { preserveAssistantContent, mergeRunEvents } from '../../core/durable-projection.js';
/**
 * @module useConversation
 *
 * Owns the message array, an optimistic user-message append, a scroll-intent
 * flag, and the active conversation id. Reconciles `useRunStream`'s live
 * `AgentEvent[]` into the streaming assistant message's `events`/`content`
 * as they arrive, and finalizes it once the run reaches a terminal status.
 * Per `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §4.
 *
 * Mutations reach the transport only through the composed `useRunStream` —
 * this hook never imports `fetch`/`EventSource` itself.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { AgentEvent, ChatAttachment, ChatMessage, ChatRunStatus } from '../../core/index.js';
import { assistantContentFromEvents, isTerminalRunStatus } from '../../core/index.js';
import type { ChatTransport, RunContext } from '../../core/index.js';
import { useRunStream } from './useRunStream.js';

export interface UseConversationOptions extends UserTextRedactionOptions {
  transport: ChatTransport;
  initialMessages?: ChatMessage[];
  /** Optional host loader and browser ports, e.g. `{ loadMessages, visibility: document, focus: window }`; refresh stays passive. */
  refreshSignal?: { loadMessages: () => Promise<ChatMessage[]>; visibility: EventTarget & { readonly visibilityState: string }; focus: EventTarget };
  conversationId?: string | null;
  agentId?: string;
  /** Defaults to a `crypto.randomUUID()`-based id generator when available, else a counter. */
  createMessageId?: () => string;
}

export interface SendMessageOptions {
  /** Queue flushes reuse the input receipts recorded when they were queued. */
  acceptedInputs?: AcceptedChatInput[];
  /** Called after transport acceptance; rejection never consumes the draft or recall slot. */
  onAccepted?: (input: { inputs: AcceptedChatInput[] }) => void;
  /** Non-secret signal from a composer that already sanitized the content before this boundary. */
  secretRedaction?: ChatMessage['secretRedaction'];
  attachments?: ChatAttachment[];
  context?: RunContext;
  agentId?: string;
}

export interface UseConversationResult {
  messages: ChatMessage[];
  conversationId: string | null;
  isStreaming: boolean;
  error: Error | null;
  /**
   * Why the newest send never became a run (refused, unreachable, or the connection dropped before
   * acceptance), or `null`. Its optimistic bubbles are already gone, so a host shows this beside the
   * composer and offers to send the refused text again. Cleared by the next send.
   */
  sendError: Error | null;
  /** `true` when new content just arrived and nothing has told the hook the user already scrolled away — a `<MessageList>` reads this to decide whether to auto-scroll. */
  scrollIntent: boolean;
  sendMessage: (content: string, options?: SendMessageOptions) => Promise<void>;
  cancel: () => void;
  /** Re-send the same content as a failed/canceled assistant message's preceding user turn. */
  retry: (assistantMessageId: string) => Promise<void>;
  setMessages: (updater: ChatMessage[] | ((prev: ChatMessage[]) => ChatMessage[])) => void;
  /** Called by `<MessageList>` once it has scrolled to the newest content. */
  acknowledgeScroll: () => void;
  /** Called by `<MessageList>` when the user manually scrolls up, so the next event doesn't yank them back down. */
  suppressScroll: () => void;
}

let fallbackIdCounter = 0;
function defaultCreateMessageId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  fallbackIdCounter += 1;
  return `msg-${Date.now()}-${fallbackIdCounter}`;
}

function pendingUserMessage(
  { content, sendOptions, createMessageId }: { content: string; sendOptions: SendMessageOptions; createMessageId: () => string },
  options: UserTextRedactionOptions = {},
): ChatMessage {
  return redactUserMessage<ChatMessage>({ message: {
  id: createMessageId(),
  role: 'user',
  inputPending: true,
  ...(sendOptions.acceptedInputs ? { events: sendOptions.acceptedInputs.map(input => acceptedInputUserEvent({ input }, { receipt: 'accepted' })) } : {}),
  content,
  createdAt: Date.now(),
  ...(sendOptions.secretRedaction ? { secretRedaction: sendOptions.secretRedaction } : {}),
  ...(sendOptions.attachments ? { attachments: sendOptions.attachments } : {}),
} }, options).message;
}

export function useConversation(options: UseConversationOptions): UseConversationResult {
  const { transport, conversationId = null, agentId, createMessageId = defaultCreateMessageId } = options;
  const [messages, setMessagesState] = useState<ChatMessage[]>(() => redactUserHistory(
    { history: options.initialMessages ?? [] },
    { ...(options.redactUserText ? { redactUserText: options.redactUserText } : {}) },
  ));
  const [scrollIntent, setScrollIntent] = useState(false);
  const [sendRefused, setSendRefused] = useState(false);
  const run = useRunStream({ transport });
  // The assistant message id the currently-active run is writing into.
  const activeAssistantIdRef = useRef<string | null>(null);
  const messagesRef = useRef(messages);
  messagesRef.current = messages;

  const setMessages = useCallback((updater: ChatMessage[] | ((prev: ChatMessage[]) => ChatMessage[])) => {
    setMessagesState((prev) => (typeof updater === 'function' ? (updater as (p: ChatMessage[]) => ChatMessage[])(prev) : updater));
  }, []);

  // Map upserts preserve order in O(local + saved) time/space; cleanup fences late reads on switch/unmount/local runs.
  useEffect(() => {
    const source = options.refreshSignal;
    if (!source || run.isStreaming) return;
    let disposed = false, pending = false, timer: ReturnType<typeof setTimeout>;
    const refresh = async () => {
      if (pending) return;
      pending = true;
      try {
        const saved = await source.loadMessages();
        if (!disposed) setMessagesState(prev => [...new Map([...prev, ...saved].map(message => [message.id, message])).values()]);
      } catch (error) { if (!disposed) console.error('[chat] conversation refresh failed', error); }
      finally { pending = false; }
    };
    const schedule = () => {
      clearTimeout(timer);
      if (source.visibility.visibilityState === 'visible') timer = setTimeout(() => { void refresh(); }, 500);
    };
    const events: [EventTarget, string][] = [[source.visibility, 'visibilitychange'], [source.focus, 'focus']];
    for (const [target, event] of events) target.addEventListener(event, schedule);
    return () => { disposed = true; clearTimeout(timer); for (const [target, event] of events) target.removeEventListener(event, schedule); };
  }, [options.refreshSignal, run.isStreaming]);

  /**
   * The mount-time snapshot of `initialMessages`, captured once — the same "read once, never react
   * to a later identity change" contract `messages`'s own `useState` initializer above already has
   * for this same prop. A host's `initialMessages` array is expected to be a fresh identity on every
   * render (`ChatPane` remounts the whole pane with a fresh `key` on a real conversation switch
   * rather than pushing a new array into a live one), so depending on it directly in the effect below
   * would re-fire on every render of a host that does not itself memoize the prop.
   */
  const initialMessagesRef = useRef(options.initialMessages);

  /**
   * Resumes an interrupted run on mount instead of leaving it frozen forever.
   *
   * `run.reattach` (`useRunStream.ts`) has existed since 2026-07-29 and is fully implemented —
   * generation-guarded against double-subscription, abortable, race-safe — but until this effect,
   * nothing in this package or any host ever called it. The gap it left: once a browser's live
   * subscription to a run is torn down for ANY reason (this hook unmounting, a host remount, an HMR
   * reload, a daemon restart), the run keeps going server-side and nothing ever tells the browser
   * about it again — no more events, no more persistence, no error, just a frozen pane. The 2026-09-11 incident showed that teardown without remount reattachment
   * leaves a running server task invisible to the browser. Reattaching needs a durably-recorded, non-terminal `runId` to find
   * in `initialMessages` in the first place — the host is responsible for that half by persisting the run stub before starting the subscription.
   *
   * Mount-only (`[]` deps), by design: `useConversation` owns exactly one `useRunStream` instance for
   * its whole lifetime, and a host that wants a different transcript remounts the pane with a fresh
   * `key` rather than pushing a new `initialMessages` into a live one (see `initialMessagesRef`'s own
   * doc) — so "the moment this hook mounts" IS "the moment a stale subscription needs recovering",
   * and there is no later point in this hook's life that also needs this check.
   *
   * `activeAssistantIdRef.current` is set BEFORE calling `reattach`, not after: the reconciliation
   * effect below (`applyRunToAssistantMessage`) no-ops whenever that ref is `null` — a reattach whose
   * first event arrived before this assignment landed would be silently dropped on the floor instead
   * of reaching the message it belongs to.
   *
   * A message with a `runId` but no `runStatus` at all is treated as nothing to reattach to, not as
   * "assume non-terminal" — `useConversation`'s own reconciliation always writes both together, so
   * the combination only arises from data this hook did not itself produce (a host's legacy rows, a
   * different producer entirely), and there is no positive evidence there of an in-flight run worth
   * the network round trip.
   */
  useEffect(() => {
    const last = initialMessagesRef.current?.at(-1);
    if (!last || last.role !== 'assistant') return;
    if (last.runId === undefined || last.runStatus === undefined) return;
    if (isTerminalRunStatus({ status: last.runStatus })) return;
    activeAssistantIdRef.current = last.id;
    void run.reattach(last.runId, last.events);
    // Mount-only: see this effect's own doc for why `run` is deliberately not listed — it is a
    // `useCallback` (`useRunStream.ts`), stable for this hook instance's whole lifetime, so omitting
    // it changes nothing about correctness.
  }, []);

  const applyRunToAssistantMessage = useCallback(() => {
    const assistantId = activeAssistantIdRef.current;
    if (!assistantId) return;
    setMessagesState((prev) =>
      prev.map((m) => {
        if (m.id !== assistantId) return m;
        // A plain if/else chain (not a nested ternary) — deliberately, so
        // each of the four mapped statuses is its own independently
        // trackable branch under coverage instrumentation. The initial
        // value is asserted non-null: this reconciliation effect only ever
        // runs after `sendMessage`/`retry` has called `run.start()`/
        // `reattach` (both set the message's `runStatus: 'queued'` via
        // `activeAssistantIdRef` first), so `m.runStatus` is always defined
        // and `run.status` is never `'idle'` by the time this callback
        // fires — one of the four branches below always reassigns it.
        let runStatus: ChatRunStatus = m.runStatus!;
        if (run.status === 'streaming') runStatus = 'running';
        else if (run.status === 'done') runStatus = 'succeeded';
        else if (run.status === 'error') runStatus = 'failed';
        else if (run.status === 'canceled') runStatus = 'canceled';
        const nextRunId = run.runId ?? m.runId;
        const events = projectAcceptedInputEvents({ events: mergeRunEvents({ saved: m.events, incoming: run.events }, {}) });
        return {
          ...m,
          ...(nextRunId !== undefined ? { runId: nextRunId } : {}),
          events,
          // Replayed completion prefixes cannot erase a saved interrupted segment.
          content: preserveAssistantContent({ saved: m.content, incoming: assistantContentFromEvents({ events }) }, {}),
          runStatus,
          ...(isTerminalRunStatus({ status: runStatus }) ? { endedAt: Date.now() } : {}),
        };
      }),
    );
    setScrollIntent(true);
  }, [run.events, run.runId, run.status]);

  // Reconcile the live run's events onto the streaming assistant message
  // whenever any of them changes identity. `run.runId` must be included:
  // an event can arrive (and get reconciled) before `start()`'s promise
  // resolves with the real id, and if the id then resolves with no further
  // event/status change, omitting it here would leave the message's runId
  // permanently unset.
  useEffect(() => {
    applyRunToAssistantMessage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run.events, run.status, run.runId]);

  const sendMessage = useCallback(
    async (content: string, sendOptions: SendMessageOptions = {}) => {
      const userMessage = pendingUserMessage({ content, sendOptions, createMessageId }, options);
      const resolvedAgentId = sendOptions.agentId ?? agentId;
      const assistantMessage: ChatMessage = {
        id: createMessageId(),
        role: 'assistant',
        content: '',
        ...(resolvedAgentId !== undefined ? { agentId: resolvedAgentId } : {}),
        runStatus: 'queued',
        createdAt: Date.now(),
        startedAt: Date.now(),
      };
      activeAssistantIdRef.current = assistantMessage.id;
      setSendRefused(false);
      const history = redactUserHistory({ history: [...messagesRef.current, userMessage] }, options);
      // Functional, never `[...history, assistantMessage]`: `messagesRef` is the last RENDER's
      // snapshot, and a host that sends from an effect (`useChatPane`'s queued-prompt flush) runs in
      // the same commit as the reconciliation effect that just marked the previous turn terminal.
      // Replacing the array with the snapshot threw that pending update away, leaving the finished
      // turn `running` forever — and never persisted, since hosts persist only terminal turns
      // (host stuck-chat investigation, 2026-09-27).
      setMessagesState((prev) => [...prev, userMessage, assistantMessage]);
      setScrollIntent(true);
      const accepted = await run.start({
        assistantMessageId: assistantMessage.id,
        history,
        ...(resolvedAgentId !== undefined ? { agentId: resolvedAgentId } : {}),
        conversationId,
        ...(sendOptions.attachments !== undefined ? { attachments: sendOptions.attachments } : {}),
        ...(sendOptions.context !== undefined ? { context: sendOptions.context } : {}),
      });
      if (!accepted) {
        // The bubbles go, but the reason must not: it was rendered only on the assistant bubble.
        setMessagesState(prev => prev.filter(message => message.id !== userMessage.id && message.id !== assistantMessage.id));
        setSendRefused(true);
        return;
      }
      const inputs = sendOptions.acceptedInputs ?? [{ id: userMessage.id, text: userMessage.content }];
      setMessagesState(prev => prev.map(message => message.id === userMessage.id ? { ...message, inputPending: false } : message));
      sendOptions.onAccepted?.({ inputs });
    },
    [agentId, conversationId, createMessageId, run, options.redactUserText, options.onSecretRedacted],
  );

  const retry = useCallback(
    async (assistantMessageId: string) => {
      const idx = messagesRef.current.findIndex((m) => m.id === assistantMessageId);
      if (idx <= 0) return;
      const priorUser = messagesRef.current[idx - 1];
      if (!priorUser || priorUser.role !== 'user') return;
      const history = redactUserHistory({ history: messagesRef.current.slice(0, idx) }, options);
      const resetAssistant: ChatMessage = { ...messagesRef.current[idx]!, content: '', events: [], runStatus: 'queued' };
      activeAssistantIdRef.current = resetAssistant.id;
      // Functional for the same reason as `sendMessage`'s: keep a just-queued terminal update.
      setMessagesState((prev) => {
        const at = prev.findIndex((m) => m.id === assistantMessageId);
        return at < 0 ? [...history, resetAssistant] : [...prev.slice(0, at), resetAssistant];
      });
      setScrollIntent(true);
      const resolvedAgentId = resetAssistant.agentId ?? agentId;
      // `priorUser`'s attachments go back out with the retry. They were located above and then
      // dropped: `sendMessage` forwards `attachments` to `run.start`, this path did not, so
      // retrying an image or file prompt re-sent the TEXT alone. The model then answered a question
      // about a picture it could no longer see — and because the transcript still renders the
      // attachment beside the user turn, the failure reads as the model ignoring it rather than as
      // the client never having sent it.
      await run.start({
        assistantMessageId: resetAssistant.id,
        history,
        ...(resolvedAgentId !== undefined ? { agentId: resolvedAgentId } : {}),
        conversationId,
        ...(priorUser.attachments !== undefined ? { attachments: priorUser.attachments } : {}),
      });
    },
    [agentId, conversationId, run, options.redactUserText, options.onSecretRedacted],
  );

  const cancel = useCallback(() => run.cancel(), [run]);
  const acknowledgeScroll = useCallback(() => setScrollIntent(false), []);
  const suppressScroll = useCallback(() => setScrollIntent(false), []);

  return useMemo(
    () => ({
      messages,
      conversationId,
      isStreaming: run.isStreaming,
      error: run.error,
      // A Stop before acceptance also returns no run, but leaves no error: nothing to report.
      sendError: sendRefused ? run.error : null,
      scrollIntent,
      sendMessage,
      cancel,
      retry,
      setMessages,
      acknowledgeScroll,
      suppressScroll,
    }),
    [messages, conversationId, run.isStreaming, run.error, sendRefused, scrollIntent, sendMessage, cancel, retry, setMessages, acknowledgeScroll, suppressScroll],
  );
}

/**
 * @module useCopyToClipboard
 *
 * Copies a string to the system clipboard and exposes a transient `copied`
 * flag a UI affordance can key off of (icon swap, status text, ...). This is
 * the shared primitive behind the per-message copy button in `MessageRow.tsx`
 * -- kept here, not inlined there, so the per-block copy button
 * `Markdown.tsx` still has as a TODO can reuse the same copy/fallback logic
 * once it's built, without duplicating the secure-context handling below.
 *
 * Two copy paths, tried in order:
 * 1. `navigator.clipboard.writeText` -- the modern async Clipboard API.
 *    Requires a secure context (HTTPS, or `localhost`); rejects everywhere
 *    else, and can also reject in a secure context that denies clipboard
 *    permission.
 * 2. A hidden, focused, selected `<textarea>` + `document.execCommand('copy')`
 *    -- deprecated, but still the only synchronous copy path browsers expose
 *    outside a secure context. This package ships to hosts beyond localhost,
 *    so the secure-context requirement above can't be assumed.
 *
 * Both paths report their own success back to the caller (rather than being
 * assumed to have worked) so a caller can decide how to react to a copy that
 * silently failed instead of showing a false "Copied" state.
 */
import { useCallback, useEffect, useRef, useState } from 'react';

/** How long the `copied` flag stays true after a successful copy before it reverts on its own. */
const COPIED_RESET_MS = 1500;

/**
 * Synchronous fallback copy path for non-secure contexts: a hidden textarea
 * gets the text, is selected, and `execCommand('copy')` is invoked against
 * that selection. Returns whether the browser reports the command as
 * executed -- `execCommand` itself throws in some embedding contexts (e.g. a
 * sandboxed iframe without clipboard-write) rather than just returning
 * `false`, so this also guards with try/catch.
 * @param text - The exact string to place on the clipboard.
 * @returns Whether the copy command executed successfully.
 * @complexity O(1) -- one DOM node created, selected, and removed.
 */
function copyViaExecCommand(text: string): boolean {
  if (typeof document === 'undefined') return false;
  const textarea = document.createElement('textarea');
  textarea.value = text;
  // Off-screen but still focusable/selectable: a `display:none` element can't hold a selection.
  textarea.style.position = 'fixed';
  textarea.style.top = '-1000px';
  textarea.style.left = '-1000px';
  textarea.setAttribute('readonly', '');
  document.body.appendChild(textarea);
  textarea.focus();
  textarea.select();
  let ok = false;
  try {
    ok = document.execCommand('copy');
  } catch {
    ok = false;
  }
  document.body.removeChild(textarea);
  return ok;
}

export interface UseCopyToClipboardResult {
  /** `true` for `COPIED_RESET_MS` after a successful `copy()` call, then reverts to `false` on its own. */
  copied: boolean;
  /** Copies `text` verbatim. Resolves to whether the copy actually succeeded. */
  copy: (text: string) => Promise<boolean>;
}

/**
 * React hook wrapping the copy-to-clipboard logic above with the transient
 * `copied` UI flag callers use to drive an icon swap or status announcement.
 * @returns The current `copied` flag and a `copy` function to invoke it.
 * @complexity O(1) per `copy()` call (excluding the clipboard API's own cost).
 */
export function useCopyToClipboard(): UseCopyToClipboardResult {
  const [copied, setCopied] = useState(false);
  const resetTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  // Clears any pending reset on unmount so a copy just before navigating away never calls
  // setState on an unmounted component.
  useEffect(() => () => clearTimeout(resetTimer.current), []);

  const copy = useCallback(async (text: string): Promise<boolean> => {
    let ok = false;
    if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
      try {
        await navigator.clipboard.writeText(text);
        ok = true;
      } catch {
        // Denied permission, or a non-secure context where the API exists but rejects every call.
        ok = copyViaExecCommand(text);
      }
    } else {
      ok = copyViaExecCommand(text);
    }
    if (ok) {
      setCopied(true);
      clearTimeout(resetTimer.current);
      resetTimer.current = setTimeout(() => setCopied(false), COPIED_RESET_MS);
    }
    return ok;
  }, []);

  return { copied, copy };
}

/**
 * @module useExtEventGroups
 *
 * Groups a message's `kind: 'ext'` events by `name`. Groups are ordered by each name's first
 * occurrence; within a group, events keep arrival order regardless of what's interleaved between
 * them in the raw stream — `a2ui`, `a2ui`, `foo`, `a2ui` yields `[{name:'a2ui', events:[e1,e2,e3]},
 * {name:'foo', events:[e2]}]` (indices illustrative), since `ExtEventRenderer` needs the full
 * ordered sequence for a name, not just a contiguous run of it. Pure over `AgentEvent[]` — zero
 * I/O, no React state, unlike `useToolTimeline` (which also tracks expand/collapse UI state
 * ext-event renderers don't need since `MessageRow` doesn't own any generic collapsed/expanded
 * chrome for them).
 */
import { useMemo } from 'react';
import type { AgentEvent } from '../../core/index.js';
import type { ExtEventCall } from '../ext-event-renderer-registry.js';

export interface ExtEventGroup {
  name: string;
  /**
   * The render slot this group fills — `name`, or `name:key` for a renderer registered with a slot
   * key (see `ext-event-renderer-registry.ts`'s `ExtEventSlotKey`). One group per slot.
   */
  slot: string;
  events: unknown[];
  /** The tool call open when this group's first event arrived — see `ExtEventCall`. */
  call?: ExtEventCall;
}

type CallInfo = { name: string; input: unknown };
type ToolResult = { content: string; isError: boolean };
type SlotOf = (name: string, data: unknown) => string;

/** Per-pass state of the single walk over a message's events. */
interface GroupingState {
  slotOf: SlotOf;
  /** Groups keyed by slot; a Map keeps insertion order, i.e. each slot's first occurrence. */
  bySlot: Map<string, ExtEventGroup>;
  // Calls still open at this point in the stream, in the order they opened; the newest open one
  // is the call an ext event arrived inside.
  openCalls: Map<string, CallInfo>;
  ownerOf: Map<ExtEventGroup, CallInfo & { id: string }>;
  results: Map<string, ToolResult>;
}

function addExtEvent(state: GroupingState, { name, data }: { name: string; data: unknown }): void {
  const slot = state.slotOf(name, data);
  let group = state.bySlot.get(slot);
  if (!group) {
    group = { name, slot, events: [] };
    state.bySlot.set(slot, group);
    const owner = [...state.openCalls].at(-1);
    if (owner !== undefined) state.ownerOf.set(group, { id: owner[0], ...owner[1] });
  }
  group.events.push(data);
}

function visitEvent(state: GroupingState, ev: AgentEvent): void {
  if (ev.kind === 'tool_use') {
    state.openCalls.set(ev.id, { name: ev.name, input: ev.input });
  } else if (ev.kind === 'tool_result') {
    state.openCalls.delete(ev.toolUseId);
    state.results.set(ev.toolUseId, { content: ev.content, isError: ev.isError });
  } else if (ev.kind === 'ext') {
    addExtEvent(state, ev);
  }
}

function attachCalls({ bySlot, ownerOf, results }: GroupingState): ExtEventGroup[] {
  const order = [...bySlot.values()];
  for (const group of order) {
    const owner = ownerOf.get(group);
    if (owner === undefined) continue;
    const result = results.get(owner.id);
    group.call = { id: owner.id, name: owner.name, input: owner.input, ...(result === undefined ? {} : { result }) };
  }
  return order;
}

/**
 * @param slotOf - Which render slot an event belongs to. Defaults to its `name`, the one-slot-per-name
 *   grouping this hook always had; `MessageRow` passes the registry's `extEventSlot`.
 */
export function useExtEventGroups({ events }: { events: AgentEvent[] | undefined }, { slotOf = (name) => name }: { slotOf?: ((name: string, data: unknown) => string) | undefined } = {}
): ExtEventGroup[] {
  return useMemo(() => {
    const state: GroupingState = { slotOf, bySlot: new Map(), openCalls: new Map(), ownerOf: new Map(), results: new Map() };
    for (const ev of events ?? []) visitEvent(state, ev);
    return attachCalls(state);
  }, [events, slotOf]);
}

import { useCallback, useEffect, useMemo, useRef } from 'react';

/**
 * "Only the newest attempt may write state" — the rule every async hook in this package needs, and
 * the one that produced the worst complexity in the feature.
 *
 * Written by hand it is a `if (!mountedRef.current || generation !== generationRef.current) return;`
 * after *every* await, repeated again inside the `catch`, inside a `useCallback` inside a hook — so
 * each of those guards is scored at nesting level 2 or 3 and costs 3 cognitive points rather than 1.
 * `useChatPaneWorkingDirectory` carried four near-identical copies of the shape.
 *
 * Here the guard throws instead of returning, and {@link LatestOperation.run} swallows it. The body
 * then reads as a straight line of awaits with `token.ensureCurrent()` between them, and the branch
 * exists once — in this file.
 */

/**
 * Thrown by {@link OperationToken.ensureCurrent} once its operation has been superseded or the
 * component has unmounted. Never escapes {@link LatestOperation.run}, and callers neither construct
 * nor catch it.
 */
class SupersededOperation extends Error {
  constructor() {
    super('operation superseded');
    this.name = 'SupersededOperation';
  }
}

export interface OperationToken {
  /**
   * Abandons the surrounding {@link LatestOperation.run} body unless this is still the newest
   * operation on a mounted component. Call it after each await, in place of a guard clause.
   */
  ensureCurrent(): void;
  /** Whether this is still the newest operation and the component is still mounted. */
  isCurrent(): boolean;
}

export interface LatestOperation {
  /**
   * Runs `body` as the newest operation, superseding any still in flight.
   *
   * `onError` is invoked only for a genuine failure of an operation that is *still* current — a
   * superseded or unmounted one is discarded silently, which is what the hand-written guards did.
   */
  run(
    args: { body: (token: OperationToken) => Promise<void>; onError: (error: Error) => void },
  ): Promise<void>;
  /** Supersedes whatever is in flight without starting a new operation. */
  supersede(): void;
}

/** Preserves native Error objects while normalizing opaque host-bridge rejections. */
export function normalizeOperationError({ error }: { error: unknown }): Error {
  return error instanceof Error ? error : new Error(String(error));
}

/**
 * Owns the mounted flag and the generation counter that decide which async attempt is allowed to
 * write state. One instance per hook: every operation started through it supersedes the previous
 * one, so a validation still in flight cannot clobber the result of the pick that replaced it.
 *
 * @complexity Time/space: O(1).
 */
export function useLatestOperation(_requiredArgs: Record<string, never>): LatestOperation {
  const mountedRef = useRef(true);
  const generationRef = useRef(0);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      generationRef.current += 1;
    };
  }, []);

  const supersede = useCallback(() => {
    generationRef.current += 1;
  }, []);

  const run = useCallback(async (
    { body, onError }: { body: (token: OperationToken) => Promise<void>; onError: (error: Error) => void },
  ): Promise<void> => {
    const generation = ++generationRef.current;
    const isCurrent = () => mountedRef.current && generation === generationRef.current;
    const token: OperationToken = {
      isCurrent,
      ensureCurrent: () => {
        // A generation only ever increases and unmount bumps it, so once stale always stale —
        // which is why `run`'s catch needs no `instanceof` test to tell this apart from a real
        // failure. `isCurrent()` is already false for anything thrown from here.
        if (!isCurrent()) throw new SupersededOperation();
      },
    };
    try {
      await body(token);
    } catch (error) {
      if (!isCurrent()) return;
      onError(normalizeOperationError({ error: error }));
    }
  }, []);

  return useMemo(() => ({ run, supersede }), [run, supersede]);
}

/**
 * @module usePinnedTodos
 *
 * The latest `TodoWrite`-style plan snapshot across a conversation, a
 * dismissed-key so a user's dismissal sticks until the plan actually
 * changes again, and progress counts for a pinned progress-card UI. Pure
 * over `messages` — built on `@jini-ai/chat/core`'s
 * `latestTodoWriteInputForPinnedCard`/`parseTodoWriteInput`. Per
 * `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §4 (origin: OD's
 * `runtime/todos.ts` pinned-card logic, `components/ToolCard.tsx`'s
 * `TodoCard`'s `onDismiss` convention).
 */
import { useCallback, useMemo, useState } from 'react';
import type { ChatMessage, TodoItem } from '../../core/index.js';
import { latestTodoWriteInputForPinnedCard, parseTodoWriteInput } from '../../core/index.js';

export interface UsePinnedTodosResult {
  todos: TodoItem[];
  total: number;
  completed: number;
  inProgress: TodoItem | undefined;
  /** `true` once every todo in the latest plan is `completed`. */
  allComplete: boolean;
  /** `false` when there's no plan yet, or the user dismissed the current (all-complete) plan. */
  visible: boolean;
  /** Dismisses the currently-pinned card. Only meaningful once `allComplete`; re-appears automatically once the plan changes again. */
  dismiss: () => void;
}

export function usePinnedTodos({ messages }: { messages: ReadonlyArray<ChatMessage> | undefined }): UsePinnedTodosResult {
  const [dismissedKey, setDismissedKey] = useState<string | null>(null);

  const rawInput = useMemo(() => latestTodoWriteInputForPinnedCard({ messages: messages }), [messages]);
  const todos = useMemo(() => parseTodoWriteInput({ input: rawInput }), [rawInput]);
  const key = useMemo(() => (rawInput === null ? null : safeStableKey(rawInput)), [rawInput]);

  const total = todos.length;
  const completed = todos.filter((t) => t.status === 'completed').length;
  const allComplete = total > 0 && completed === total;
  const inProgress = todos.find((t) => t.status === 'in_progress');
  const visible = total > 0 && !(allComplete && key !== null && key === dismissedKey);

  const dismiss = useCallback(() => {
    if (key !== null) setDismissedKey(key);
  }, [key]);

  return { todos, total, completed, inProgress, allComplete, visible, dismiss };
}

// A plan-tool `input` is arbitrary JSON; stringify gives a cheap, stable
// identity for "has the plan actually changed since dismissal" without
// depending on object reference equality (a fresh event array on every
// stream tick would otherwise always look "new").
function safeStableKey(input: unknown): string {
  try {
    return JSON.stringify(input);
  } catch {
    return String(input);
  }
}

/**
 * @module useQuestionForms
 *
 * Parses `<question-form>` artifacts out of each assistant message via
 * `@jini-ai/chat/core`'s `findFirstQuestionForm`, tracks which one (if any) is
 * still the active/answerable one, and recovers already-submitted answers by
 * reading the next user message's `[form answers — ...]` payload. Pure parse
 * — `submit` only builds the next-user-message text; the host posts it via
 * its own `sendMessage`/transport call. Per
 * `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §4.
 *
 * `parseSubmittedAnswers` below generalizes OD's `components/QuestionForm.tsx`
 * function of the same name (verified 0 OD product references — it only
 * reverses `formatFormAnswers`'s own text format) into this package, since
 * chat-core intentionally ships only the forward direction
 * (`formatFormAnswers`).
 */
import { useCallback, useMemo } from 'react';
import type { ChatMessage, FormQuestion, QuestionForm } from '../../core/index.js';
import { findFirstQuestionForm, formOptionValueForLabel, formatFormAnswers } from '../../core/index.js';

export type QuestionFormAnswers = Record<string, string | string[]>;

export interface ParsedQuestionForm {
  form: QuestionForm;
  raw: string;
  /** The assistant message this form was found in. */
  messageId: string;
  /** `true` when this is the most recent assistant message with no reply after it yet — i.e. still answerable. */
  interactive: boolean;
  /** Recovered from the next user message's `[form answers — ...]` text, if one exists. */
  submittedAnswers: QuestionFormAnswers | undefined;
}

export interface UseQuestionFormsResult {
  /** Every question-form found across the conversation, oldest first. */
  forms: ParsedQuestionForm[];
  /** The most recent form that is still `interactive` (unanswered), or `null`. */
  activeForm: ParsedQuestionForm | null;
  /** Formats `answers` into the prose user-message text the host sends back. */
  buildSubmission: (form: QuestionForm, answers: QuestionFormAnswers) => string;
}

/**
 * The question-form on `messages[index]`, or `null` when that message is not
 * an assistant message or carries no form. Answers come from the message right
 * after it, and only when that one is a user reply.
 */
function parseFormAt(messages: ReadonlyArray<ChatMessage>, { index }: { index: number }): ParsedQuestionForm | null {
  // Only called with an index `flatMap` is visiting (it skips holes), so the
  // element is always defined.
  const message = messages[index]!;
  if (message.role !== 'assistant') return null;
  const found = findFirstQuestionForm({ input: message.content });
  if (!found) return null;
  const nextMessage = messages[index + 1];
  const submittedAnswers =
    nextMessage?.role === 'user' ? parseSubmittedAnswers({ form: found.form, userMessageContent: nextMessage.content }) ?? undefined : undefined;
  const interactive = submittedAnswers === undefined && index === messages.length - 1;
  return { form: found.form, raw: found.raw, messageId: message.id, interactive, submittedAnswers };
}

export function useQuestionForms({ messages }: { messages: ReadonlyArray<ChatMessage> | undefined }): UseQuestionFormsResult {
  const forms = useMemo<ParsedQuestionForm[]>(
    () => (messages ?? []).flatMap((_, index, all) => parseFormAt(all, { index }) ?? []),
    [messages],
  );

  const activeForm = useMemo(() => forms.findLast((form) => form.interactive) ?? null, [forms]);

  const buildSubmission = useCallback((form: QuestionForm, answers: QuestionFormAnswers) => formatFormAnswers({ form: form, answers: answers }), []);

  return { forms, activeForm, buildSubmission };
}

/**
 * Reverse of `formatFormAnswers` — given the user message that (maybe)
 * answered `form`, recover the answers map so the form can render in its
 * locked "answered" state with the user's picks visible.
 */
export function parseSubmittedAnswers({ form, userMessageContent }: { form: QuestionForm; userMessageContent: string }): QuestionFormAnswers | null {
  // `String.prototype.split` always returns an array of length >= 1 (even
  // `''.split('\n')` is `['']`), so `lines` can never be empty here — no
  // `lines.length === 0` guard is needed (removed as provably-dead). Index 0
  // of a non-empty array is always defined; TS just can't express that for
  // a plain numeric index, hence the assertion instead of a `?? ''` branch
  // that would never take its fallback path.
  const lines = userMessageContent.split('\n').map((l) => l.trim());
  const header = lines[0]!;
  if (!/^\[form answers/i.test(header)) return null;
  const answers: QuestionFormAnswers = {};
  const labelToId = new Map<string, string>();
  for (const q of form.questions) labelToId.set(q.label.toLowerCase(), q.id);
  for (let i = 1; i < lines.length; i += 1) {
    // `i < lines.length` is the loop condition, so this index is always
    // in-bounds and defined — same reasoning as `header` above.
    const line = lines[i]!;
    const m = /^[-*]\s*([^:]+):\s*(.*)$/.exec(line);
    if (!m) continue;
    // Both capture groups are required (non-optional) in this pattern, so
    // they're always defined once `m` is non-null — TS just can't express
    // that for regex capture groups.
    const labelKey = m[1]!.trim().toLowerCase();
    const value = m[2]!.trim();
    const id = labelToId.get(labelKey);
    if (!id) continue;
    // `id` only ever comes from `labelToId`, which was populated from this
    // same `form.questions` array immediately above, so a question with
    // this exact `id` is always found — the `!` reflects that invariant
    // rather than gaming an untestable defensive branch.
    const question = form.questions.find((x) => x.id === id)!;
    answers[id] = decodeAnswerValue(question, value);
  }
  return Object.keys(answers).length > 0 ? answers : null;
}

function decodeAnswerValue(question: FormQuestion, value: string): string | string[] {
  if (question.type === 'checkbox') {
    return value
      .split(',')
      .map((s) => s.trim())
      .filter((s) => s.length > 0 && s.toLowerCase() !== '(skipped)')
      .map((s) => formOptionValueForLabel({ question: question, labelOrValue: parseSubmittedOptionToken(s) }));
  }
  return value.toLowerCase() === '(skipped)' ? '' : formOptionValueForLabel({ question: question, labelOrValue: parseSubmittedOptionToken(value) });
}

function parseSubmittedOptionToken(raw: string): string {
  const match = /\s+\[value:\s*([^\]]+)\]\s*$/i.exec(raw);
  if (!match) return raw.trim();
  // The single capture group is non-optional in this pattern, so it's
  // always defined once `match` is non-null — same regex-capture-group
  // caveat as `parseSubmittedAnswers` above.
  return match[1]!.trim();
}

/**
 * @module useRunStream
 *
 * Owns the current `runId`, streaming flag, accumulated `AgentEvent[]`,
 * error/terminal state, and the ephemeral tool-input-delta buffer (keyed by
 * tool id) for a single active run. Calls `transport.startRun`/
 * `reattachRun`/`stopRun` — never touches `fetch`/`EventSource` itself; the
 * `ChatTransport` port (see `../../transport.js`) is the only I/O this hook
 * performs. Per `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §4's hook table.
 *
 * This hook IS the "single-instance orchestrator" the §4 accumulating-
 * subscription rule refers to: it owns the one active browser-side
 * subscription for whichever run it is currently attached to. Each
 * start/reattach bumps a generation counter; handlers from a superseded
 * generation are ignored, so a slow/duplicate callback from an aborted
 * subscription can never clobber a newer one's state (a plain `runId`
 * comparison can't do this — `start()`'s handlers must exist before the
 * transport's promise resolves with the real id).
 */
import { mergeRunEvents } from '../../core/durable-projection.js';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { AgentEvent } from '../../core/index.js';
import type { ChatTransport, RunHandlers, StartRunInput } from '../../core/index.js';

export type RunStreamStatus = 'idle' | 'streaming' | 'done' | 'error' | 'canceled';

export interface RunStreamState {
  runId: string | null;
  status: RunStreamStatus;
  events: AgentEvent[];
  error: Error | null;
  /** Ephemeral live tool-input fragments, keyed by tool-use id. Never persisted. */
  toolInputDeltas: Record<string, string>;
}

export type StartRunOptions = Omit<StartRunInput, 'signal' | 'cancelSignal'>;

export interface UseRunStreamResult extends RunStreamState {
  /** True while `status === 'streaming'`. Convenience for render conditions. */
  isStreaming: boolean;
  start: (input: StartRunOptions) => Promise<{ runId: string } | null>;
  /** Resume listening to an already-started run (reconnect/replay), optionally seeded with its persisted events. */
  reattach: (runId: string, initialEvents?: AgentEvent[]) => Promise<void>;
  /** Aborts the current browser-side subscription AND asks the transport to stop the run host-side. */
  cancel: () => void;
  /** Clears all state back to `idle` without touching the transport (e.g. moving to a fresh turn). */
  reset: () => void;
}

function reportRunStreamHostEffectFailure(effectName: string, error: unknown) {
  console.error(`[@jini-ai/chat] useRunStream ${effectName} host effect failed:`, error);
}

/**
 * Fire-and-forget teardown call to `transport.stopRun`. Invokes it synchronously, then observes
 * a synchronous throw or async rejection without leaving it unhandled — under Node's default
 * `--unhandled-rejections=throw` a rejecting transport would otherwise crash the process, and in
 * the browser it is a silent, undiagnosable console error. Neither call site awaits the result
 * or calls `setState`, so there is nothing here that could touch state after unmount.
 */
function runStopRunHostEffect(effectName: string, effect: () => Promise<void>) {
  let result: Promise<void>;
  try {
    result = effect();
  } catch (error) {
    reportRunStreamHostEffectFailure(effectName, error);
    return;
  }
  void result.catch((error: unknown) => {
    reportRunStreamHostEffectFailure(effectName, error);
  });
}

const INITIAL_STATE: RunStreamState = {
  runId: null,
  status: 'idle',
  events: [],
  error: null,
  toolInputDeltas: {},
};

export function useRunStream({ transport }: { transport: ChatTransport }): UseRunStreamResult {
  const [state, setState] = useState<RunStreamState>(INITIAL_STATE);
  // Acceptance/checkpoints can precede React's next commit. Cancellation needs the live id,
  // even when the Stop handler still belongs to the render that showed a pending start.
  const runIdRef = useRef<string | null>(null);
  const subscriptionAbortRef = useRef<AbortController | null>(null);
  const cancelAbortRef = useRef<AbortController | null>(null);
  // Bumped on every start/reattach/reset. A handler closes over the
  // generation it was created for and drops itself once superseded.
  const generationRef = useRef(0);
  /**
   * Generations that were CANCELLED (as opposed to merely superseded) while their `startRun` was
   * still in flight.
   *
   * `cancel()` can only stop a run it has an id for, and during that window there is no id yet.
   * The generation bump then routes the eventual resolution down the "not current" path, so the
   * run was left alive on the daemon with nothing on the client able to reach it. Recording the
   * intent here lets the resolution finish the job. A supersession by a new start/reattach is
   * deliberately NOT recorded — that case really does need no stop.
   */
  const canceledGenerations = useRef<Set<number>>(new Set());

  const teardownSubscription = useCallback(() => {
    subscriptionAbortRef.current?.abort();
    subscriptionAbortRef.current = null;
    cancelAbortRef.current = null;
  }, []);

  // Abort any in-flight subscription on unmount so a slow transport can't
  // call back into a hook instance that no longer exists.
  useEffect(() => teardownSubscription, [teardownSubscription]);

  const makeHandlers = useCallback((generation: number): RunHandlers => {
    const isStale = () => generationRef.current !== generation;
    return {
      onCheckpoint: (message) => {
        if (isStale()) return;
        runIdRef.current = message.runId ?? runIdRef.current;
        const statuses = { queued: 'streaming', running: 'streaming', succeeded: 'done', failed: 'error', canceled: 'canceled' } as const;
        setState((prev) => ({ ...prev, runId: message.runId ?? prev.runId,
          status: message.runStatus ? statuses[message.runStatus] : prev.status,
          events: mergeRunEvents({ saved: prev.events, incoming: message.events ?? [] }, {}),
        }));
      },
      onEvent: (ev: AgentEvent) => {
        if (isStale()) return;
        setState((prev) => ({ ...prev, status: 'streaming', events: [...prev.events, ev] }));
      },
      onToolInputDelta: (id: string, _name: string, delta: string) => {
        if (isStale()) return;
        setState((prev) => ({
          ...prev,
          toolInputDeltas: { ...prev.toolInputDeltas, [id]: (prev.toolInputDeltas[id] ?? '') + delta },
        }));
      },
      onError: (err: Error) => {
        if (isStale()) return;
        setState((prev) => ({ ...prev, status: 'error', error: err, events: [...prev.events, { kind: 'status', code: 'run_terminal', label: err.message }] }));
      },
      onDone: (finalEvents: AgentEvent[]) => {
        if (isStale()) return;
        setState((prev) => ({ ...prev, status: prev.status === 'error' || prev.status === 'canceled' ? prev.status : 'done', events: mergeRunEvents({ saved: prev.events, incoming: finalEvents }, {}) }));
      },
    };
  }, []);

  const start = useCallback(
    async (input: StartRunOptions): Promise<{ runId: string } | null> => {
      teardownSubscription();
      const generation = ++generationRef.current;
      runIdRef.current = null;
      const subscriptionAbort = new AbortController();
      const cancelAbort = new AbortController();
      subscriptionAbortRef.current = subscriptionAbort;
      cancelAbortRef.current = cancelAbort;
      setState({ ...INITIAL_STATE, status: 'streaming' });
      try {
        const { runId } = await transport.startRun(
          { ...input, signal: subscriptionAbort.signal, cancelSignal: cancelAbort.signal },
          makeHandlers(generation),
        );
        if (generationRef.current !== generation) {
          // Consumed rather than assumed: only a CANCEL leaves an orphan here.
          if (canceledGenerations.current.delete(generation)) {
            runStopRunHostEffect('transport.stopRun (orphaned generation)', () => transport.stopRun(runId));
          }
          return { runId };
        }
        runIdRef.current = runId;
        setState((prev) => ({ ...prev, runId }));
        return { runId };
      } catch (err) {
        // A start that never produced a run id has nothing to stop; drop the intent so the set does
        // not accumulate one entry per failed start for the lifetime of the hook.
        canceledGenerations.current.delete(generation);
        if (generationRef.current !== generation) return null;
        setState((prev) => ({ ...prev, status: 'error', error: toError(err) }));
        return null;
      }
    },
    [makeHandlers, teardownSubscription, transport],
  );

  const reattach = useCallback(
    async (runId: string, initialEvents: AgentEvent[] = []): Promise<void> => {
      teardownSubscription();
      const generation = ++generationRef.current;
      runIdRef.current = runId;
      const subscriptionAbort = new AbortController();
      const cancelAbort = new AbortController();
      subscriptionAbortRef.current = subscriptionAbort;
      cancelAbortRef.current = cancelAbort;
      setState({ ...INITIAL_STATE, runId, status: 'streaming', events: initialEvents });
      try {
        // The subscription controller reaches the transport, so `teardownSubscription()` (unmount,
        // reset, or a superseding start/reattach) actually detaches the stream. Without it the
        // generation guard still stops stale callbacks from clobbering state, but the connection
        // and its read loop stay open until the run ends on its own.
        await transport.reattachRun(runId, makeHandlers(generation), { signal: subscriptionAbort.signal });
      } catch (err) {
        if (generationRef.current !== generation) return;
        setState((prev) => ({ ...prev, status: 'error', error: toError(err) }));
      }
    },
    [makeHandlers, teardownSubscription],
  );

  const cancel = useCallback(() => {
    cancelAbortRef.current?.abort();
    const runId = runIdRef.current;
    // Recorded BEFORE the bump, so it names the generation currently in flight. When `runId` is
    // already known the `stopRun` below does the work and this entry is simply never consumed;
    // when it is not, this is the only thing that will ever stop that run.
    if (runId == null) canceledGenerations.current.add(generationRef.current);
    generationRef.current += 1;
    teardownSubscription();
    setState((prev) => ({ ...prev, status: 'canceled' }));
    if (runId) runStopRunHostEffect('transport.stopRun (cancel)', () => transport.stopRun(runId));
  }, [teardownSubscription, transport]);

  const reset = useCallback(() => {
    generationRef.current += 1;
    runIdRef.current = null;
    teardownSubscription();
    setState(INITIAL_STATE);
  }, [teardownSubscription]);

  return { ...state, isStreaming: state.status === 'streaming', start, reattach, cancel, reset };
}

function toError(err: unknown): Error {
  return err instanceof Error ? err : new Error(String(err));
}

/**
 * @module message-blocks
 *
 * Restores the original event-stream ordering of an assistant message: text and tool cards
 * interleaved where they actually happened, instead of all the text followed by all the tools.
 *
 * ## Why this needs computing at all
 *
 * A rendered assistant message draws from three different shapes of the same turn.
 * `ChatMessage.content` is a single string — `useConversation.ts` builds it by concatenating every
 * `kind: 'text'` event (`out += ev.text`) — tool cards come from `ChatMessage.events`'s `tool_use`
 * entries, and interactive surfaces (MCP-UI, A2UI) come from that same array's `kind: 'ext'`
 * entries. Rendering `content`, then the tool timeline, then every `ext` group is the
 * straightforward composition, and it is what `MessageRow.tsx` shipped in v1 (its own header
 * records this as a known deferral pending the `AssistantMessage.tsx` extraction).
 *
 * The cost is not merely cosmetic ordering. Because the text runs on either side of a tool call (or
 * an interactive surface) get concatenated with nothing between them, a message reads as
 * `"I'll look for a tool that changes the site language.Done — the language is now English."` —
 * two separate thoughts, from before and after the tool ran, fused mid-sentence. Worse for an `ext`
 * surface specifically: a reply narrating what the human just submitted through an MCP-UI form (a
 * `text` event that only exists BECAUSE the form's `ext` event was answered) renders ABOVE that
 * form instead of below it — the answer appears to precede the question. The reader cannot tell
 * which claims preceded the evidence and which followed it.
 *
 * Since `content` is exactly the concatenation of the text events, the split points are recoverable:
 * walk the events in order, and every tool call or ext surface marks a boundary in that
 * concatenation.
 *
 * ## Refuses rather than guesses
 *
 * {@link interleaveMessageBlocks} returns `null` whenever it cannot prove the reconstruction is
 * lossless, and the caller falls back to the old flat layout. Losing the ordering is a presentation
 * regression; dropping or duplicating a chunk of the assistant's actual words is a correctness one,
 * so every check below prefers the former.
 *
 * It refuses when:
 * - there are no events, or no tool rows AND no ext events (AND no thinking, when the caller asked
 *   for it) to interleave (nothing to do — the flat path is identical);
 * - the concatenated text events do not reproduce `content` byte for byte. This is the load-bearing
 *   check. A message persisted before the events schema settled, one rebuilt by a host that
 *   assembles `content` some other way, or any future divergence between the two, all land here;
 * - the walk does not emit exactly the rows it was given (a `tool_use` with no matching row, or a
 *   row never reached), which would mean silently dropping a tool card.
 *
 * Artifacts are handled by the caller, not here — see `MessageRow.tsx`.
 */
import type { AgentEvent } from '../core/index.js';
import { assistantContentFromEvents, isReplyBoundary, legacyAssistantContentFromEvents } from '../core/index.js';
import { isAssistantStepBoundary } from '../core/assistant-content.js';
import { MID_RUN_USER_MESSAGE_EVENT_NAME } from '../core/turn-usage.js';

/**
 * One rendered block. Consecutive tool cards are coalesced into a single `tools` block so they keep
 * rendering inside one `.jini-message-tools` container, exactly as the flat layout did — a run of
 * back-to-back calls should stay one visual group, not become N separately-boxed ones. An `ext`
 * block marks where a `kind: 'ext'` group of a given `name` (an MCP-UI/A2UI surface, or any other
 * host-registered ext renderer) belongs in reading order — one block per name, at its FIRST
 * occurrence, since `MessageRow.tsx`'s `useExtEventGroups` already folds every event sharing that
 * name (however many arrive, however late) into one evolving render slot; this block only fixes
 * WHERE that slot sits relative to the surrounding text, not what it renders.
 */
export type MessageBlock<Row> =
  | { readonly kind: 'text'; readonly text: string; readonly key: string }
  | { readonly kind: 'tools'; readonly rows: readonly Row[]; readonly key: string }
  | { readonly kind: 'ext'; readonly name: string; readonly slot: string; readonly key: string }
  /** Where reply `index` of a run ends: just before the mid-run user message that started the next
   * reply (`isReplyBoundary`). `MessageRow` hangs that reply's own "Done" line here. */
  | { readonly kind: 'reply-end'; readonly index: number; readonly key: string }
  /** The model's reasoning (`kind: 'thinking'` events), where it happened. Emitted only when the
   * caller passes `includeThinking` (a host's "show thinking" display choice, 2026-10-11);
   * back-to-back thinking events with no text between them join into one block. */
  | { readonly kind: 'thinking'; readonly text: string; readonly key: string };

/** Split assistant sections around user receipts so each bubble can be an ordinary transcript row.
 * @complexity O(b) time/space for b blocks; preserves every block and its order.
 */
export function splitMidRunBlocks<Row>(
  { blocks }: { blocks: readonly MessageBlock<Row>[] }, _options = {},
): MessageBlock<Row>[][] {
  const sections: MessageBlock<Row>[][] = [];
  let assistant: MessageBlock<Row>[] = [];
  for (const block of blocks) {
    if (block.kind === 'ext' && block.name === MID_RUN_USER_MESSAGE_EVENT_NAME) {
      if (assistant.length > 0) sections.push(assistant);
      sections.push([block]);
      assistant = [];
    } else assistant.push(block);
  }
  if (assistant.length > 0) sections.push(assistant);
  return sections;
}

/** Mutable walk state threaded through the per-event helpers of {@link interleaveMessageBlocks}. */
interface WalkState<Row> {
  readonly rowById: ReadonlyMap<string, Row>;
  readonly blocks: MessageBlock<Row>[];
  readonly emitted: Set<string>;
  readonly emittedExtSlots: Set<string>;
  buffer: string;
  replies: number;
}

type SlotOf = (ev: { readonly name: string; readonly data: unknown }) => string;

/** Whether there is anything besides plain text to place: a tool row, an ext event, or (when asked
 * for) non-blank thinking. With none of these the flat path is identical. */
function hasSomethingToInterleave(
  { events, rows }: { events: readonly AgentEvent[]; rows: readonly unknown[] },
  { includeThinking }: { includeThinking: boolean },
): boolean {
  if (rows.length > 0) return true;
  return events.some((ev) => isAssistantStepBoundary({ event: ev }) || (includeThinking && ev.kind === 'thinking' && ev.text.trim() !== ''));
}

/** Whether `content` is demonstrably built from the text events. */
function contentMatchesEvents({ events, content }: { events: readonly AgentEvent[]; content: string }): boolean {
  // Both producers' shapes count: today's (a paragraph break between steps, see
  // `assistantContentFromEvents`) and the old plain concatenation older saved rows carry.
  return content === assistantContentFromEvents({ events }) || content === legacyAssistantContentFromEvents({ events });
}

function flushText<Row>({ state }: { state: WalkState<Row> }): void {
  if (state.buffer.length === 0) return;
  state.blocks.push({ kind: 'text', text: state.buffer, key: `text-${state.blocks.length}` });
  state.buffer = '';
}

function placeThinking<Row>({ state, text }: { state: WalkState<Row>; text: string }): void {
  flushText({ state });
  const { blocks } = state;
  const last = blocks[blocks.length - 1];
  if (last && last.kind === 'thinking') blocks[blocks.length - 1] = { kind: 'thinking', text: last.text + text, key: last.key };
  else blocks.push({ kind: 'thinking', text, key: `thinking-${blocks.length}` });
}

function placeReplyEnd<Row>({ state }: { state: WalkState<Row> }): void {
  flushText({ state });
  state.blocks.push({ kind: 'reply-end', index: state.replies, key: `reply-end-${state.replies}` });
  state.replies += 1;
}

function placeExt<Row>(
  { state, ev }: { state: WalkState<Row>; ev: { readonly name: string; readonly data: unknown } },
  { slotOf }: { slotOf: SlotOf },
): void {
  // One block per SLOT, at its first occurrence — later events in the same slot fold into it
  // (`useExtEventGroups`'s job in `MessageRow.tsx`), not a second block. A slot is the `name`
  // unless its renderer keys events into separate surfaces (see `ExtEventSlotKey`).
  const slot = slotOf(ev);
  if (state.emittedExtSlots.has(slot)) return;
  state.emittedExtSlots.add(slot);
  flushText({ state });
  state.blocks.push({ kind: 'ext', name: ev.name, slot, key: `ext-${slot}` });
}

function placeToolUse<Row>({ state, id }: { state: WalkState<Row>; id: string }): void {
  const row = state.rowById.get(id);
  // A `tool_use` the timeline did not surface (deduped away as a repeat of one already seen).
  // Skipping it keeps this function's output consistent with `rows`, which is the authority on
  // what gets a card.
  if (!row || state.emitted.has(id)) return;
  state.emitted.add(id);

  flushText({ state });
  const { blocks } = state;
  const last = blocks[blocks.length - 1];
  if (last && last.kind === 'tools') {
    blocks[blocks.length - 1] = { kind: 'tools', rows: [...last.rows, row], key: last.key };
  } else {
    blocks.push({ kind: 'tools', rows: [row], key: `tools-${blocks.length}` });
  }
}

function placeEvent<Row>(
  { state, ev }: { state: WalkState<Row>; ev: AgentEvent },
  { slotOf, includeThinking }: { slotOf: SlotOf; includeThinking: boolean },
): void {
  if (ev.kind === 'text') {
    state.buffer += ev.text;
    return;
  }
  if (ev.kind === 'thinking') {
    if (includeThinking) placeThinking({ state, text: ev.text });
    return;
  }
  // Usage and step-start markers separate paragraphs even when no tool/card renders there.
  // Tool and card events keep their own placement rules (a folded card or repeated tool id never splits).
  if ((ev.kind === 'usage' || ev.kind === 'status') && isAssistantStepBoundary({ event: ev })) flushText({ state });
  // Emitted per boundary, before any slot dedupe below, so every reply gets its own end marker.
  if (isReplyBoundary({ event: ev })) placeReplyEnd({ state });
  if (ev.kind === 'ext') placeExt({ state, ev }, { slotOf });
  else if (ev.kind === 'tool_use') placeToolUse({ state, id: ev.id });
}

/**
 * Rebuilds an assistant message as ordered blocks, or returns `null` if that cannot be done
 * losslessly.
 *
 * @param events - The message's event array, in arrival order.
 * @param content - The message's `content`, expected to equal the concatenated text events.
 * @param rows - The tool timeline rows, already deduped and paired by `useToolTimeline`. Only rows
 *   present here are emitted, so a row the timeline chose to drop stays dropped.
 * @param slotOf - The render slot an ext event belongs to (default: its `name`).
 * @param includeThinking - Emit `thinking` blocks for the model's reasoning (default `false`: thinking
 *   events are skipped, the layout every host had before this option). Thinking text is not part of
 *   `content`, so it never affects the lossless check below.
 * @returns Ordered blocks, or `null` to signal "render the flat layout instead".
 * @complexity O(n + m) in the event and row counts.
 */
export function interleaveMessageBlocks<Row extends { id: string }>(
  { events, content, rows }: { events: readonly AgentEvent[] | undefined; content: string; rows: readonly Row[] },
  { slotOf = (ev) => ev.name, includeThinking = false }: {
    slotOf?: SlotOf;
    includeThinking?: boolean;
  } = {},
): MessageBlock<Row>[] | null {
  if (!events || events.length === 0) return null;
  if (!hasSomethingToInterleave({ events, rows }, { includeThinking })) return null;

  // The reconstruction is only trustworthy if the text events are demonstrably the source `content`
  // was built from. Anything else and the offsets below are fiction.
  if (!contentMatchesEvents({ events, content })) return null;

  const state: WalkState<Row> = {
    rowById: new Map(rows.map((row) => [row.id, row])),
    blocks: [],
    emitted: new Set<string>(),
    emittedExtSlots: new Set<string>(),
    buffer: '',
    replies: 0,
  };
  for (const ev of events) placeEvent({ state, ev }, { slotOf, includeThinking });
  flushText({ state });

  // Every row must have found its place. If one did not, the message would render with a tool card
  // missing entirely — strictly worse than the flat layout it would have had.
  if (state.emitted.size !== rows.length) return null;

  return state.blocks;
}

import { recoveredRunEvents, type AgentEvent } from "../../core/index.js";
import { classifyAgentServiceFailure } from "@jini-ai/agent-runtime";
import { continuationRequest } from "../../core/durable-runs/continuation.js";
import { isAwaitingAnswer } from "../../core/run-activity.js";
import type { DurableRecovery, DurableRun, RecoveryPorts, RecoveryResult, RecoveryTrigger, RunProbe } from "../../core/durable-runs/ports.js";

import { RECOVERY_LIMIT, RECOVERY_WINDOW_MS, RUN_STALENESS_MS, SAVED_WORK_NOTICE, AWAITING_ANSWER_NOTICE, EXHAUSTED_NOTICE } from "../../core/durable-runs/policies.js";
export { RECOVERY_LIMIT, RECOVERY_WINDOW_MS, RUN_STALENESS_MS, SAVED_WORK_NOTICE, AWAITING_ANSWER_NOTICE, EXHAUSTED_NOTICE } from "../../core/durable-runs/policies.js";
// Older saved run error frames hold only their message: the daemon's MCP_BRIDGE_UNAVAILABLE
// code was dropped, so the bridge failure is still matched by its text.
const MCP_BRIDGE_FAILURE = /The assistant's tools did not load \(MCP bridge "jini" status: [^\r\n]*/;
const STOPPED_NOTICE = "Stopped. Saved work is above.";
type FailureClass = "retryable" | "permanent" | "auth-failure" | "inactivity-watchdog";

/** Index of the last event matching `match`, or -1.
 * @complexity O(e) time, O(1) space, no effects. */
function lastIndexWhere({ events, match }: { events: readonly AgentEvent[]; match: (event: AgentEvent) => boolean }, _optional = {}): number {
  // Reverse scan preserves the last-marker rule on the desktop's ES2022 target.
  for (let index = events.length - 1; index >= 0; index--) if (match(events[index]!)) return index;
  return -1;
}

/** One complete stdout line's contribution to executor diagnostics. */
function diagnosticLine({ line }: { line: string }, _optional = {}): string[] {
  try {
    const result = JSON.parse(line) as { type?: unknown; subtype?: unknown; is_error?: unknown } | null;
    // Successful CLI summaries contain usage metadata and answer prose, not failure evidence.
    if (result?.type === "result" && result.is_error === false) return [];
    // A subagent report can discuss billing/auth in completed work; it is not executor evidence.
    if (result?.type === "system" && result.subtype === "task_notification") return [];
  } catch {
    // Non-JSON stdout can still contain the executor's failure reason.
  }
  return [line];
}

/** A saved raw event may hold several JSONL lines; filter each before failure classification.
 * A status's typed code counts too: a launch `*_UNSUPPORTED` code (any CLI) cannot heal on retry. */
function diagnosticLines({ event }: { event: AgentEvent }, _optional = {}): string[] {
  if (event.kind === "status") return [event.code ?? "", event.label, event.detail ?? ""];
  if (event.kind !== "raw") return [];
  return event.line.split(/\r?\n/).flatMap(line => diagnosticLine({ line }));
}

/** Retryability is independent of session resumability. Inspect executor diagnostics, never
 * answer text or tool results: those can quote unrelated failures from completed work. Old
 * attempt diagnostics remain visible but cannot decide the fate of their continuation. */
function attemptDiagnostics({ run }: { run: DurableRun }, _optional = {}): string {
  const events = run.message.events ?? [];
  // Checkpoints merge adjacent text, so a base's event count is not a durable offset. The
  // coordinator's recovery marker separates attempts and survives that compaction.
  const marker = run.attemptBase.length
    ? lastIndexWhere({ events, match: (event) => event.kind === "status" && event.code === "run_recovering" })
    : -1;
  return events.slice(marker >= 0 ? marker + 1 : run.attemptBase.length).flatMap((event) => diagnosticLines({ event })).join("\n");
}

/** Quota/billing and bad requests need human repair. A 429 for rate throttling and a 5xx
 * overload remain retryable; the provider's coarse RATE_LIMITED class also includes billing. */
function needsHumanRepair({ diagnostics }: { diagnostics: string }, _optional = {}): boolean {
  const requestStatuses = diagnostics.matchAll(/\b(?:http(?:[ /]?\d(?:\.\d)?)?|(?:status|error|response)(?:[ _-]?code)?|code(?=\s*[:=#]))[\s:=#-]*(4\d\d)\b/gi);
  if ([...requestStatuses].some((match) => match[1] !== "408" && match[1] !== "429")) return true;
  return /another answer in this chat is still running|invalid[_ -]?request|context[_ -](length|window)|maximum context|model.*(?:not[_ -]found|does not exist|not supported)|unsupported|does not support|permission denied|forbidden|insufficient[_ -]?(quota|balance|credit|funds)|credit balance is too low|exceeded your current quota|quota[_ -]?exceeded|usage limit|billing|payment required/i.test(diagnostics);
}

function attemptFailure({ diagnostics }: { diagnostics: string }, _optional = {}): FailureClass {
  // MCP_BRIDGE_UNAVAILABLE needs bridge repair; another attempt repeats the same failure.
  // Classify it before interpreting the bridge's stderr as an agent auth/watchdog failure.
  if (MCP_BRIDGE_FAILURE.test(diagnostics)) return "permanent";
  if (/inactivity[_ -]?(timeout|watchdog)|watchdog.*(kill|stop)/i.test(diagnostics)) return "inactivity-watchdog";
  if (classifyAgentServiceFailure({ text: diagnostics }) === "AGENT_AUTH_REQUIRED") return "auth-failure";
  return needsHumanRepair({ diagnostics }) ? "permanent" : "retryable";
}

/** Keep the notice bounded and scoped to the same executor diagnostics as failure classification. */
function lastDiagnosticLine({ diagnostics }: { diagnostics: string }, _optional = {}): string | undefined {
  return diagnostics.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).at(-1)?.slice(0, 300);
}

function attemptFailureDetail({ run }: { run: DurableRun }, _optional = {}): string | undefined {
  return lastDiagnosticLine({ diagnostics: attemptDiagnostics({ run }) });
}

function exclusion(run: DurableRun): string | null {
  if (run.cancelReason) return run.cancelReason;
  if (!run.principalId || run.engine !== "daemon") return "excluded";
  return null;
}

/** Preflight cards precede model tools, so the normal open-tool activity scan cannot see them.
 * Chat saves the bare resource without its wire toolUseId. Saved consent or subsequent model
 * execution closes this preflight wait, including cards saved before this fix.
 * A model tool closes the wait and no later card can reopen it, so the wait is pending exactly
 * when no tool ran and the last card follows the last consent for this conversation.
 * @complexity O(e) time, O(1) space, no effects.
 */
function awaitingAnswer({ run }: { run: DurableRun }, _options = {}): boolean {
  if (isAwaitingAnswer({ events: run.message.events })) return true;
  const events = run.message.events ?? [];
  if (events.some((event) => event.kind === "tool_use")) return false;
  const card = lastIndexWhere({ events, match: (event) => event.kind === "ext" && event.name === "mcp-ui" });
  const consent = lastIndexWhere({ events, match: (event) => event.kind === "ext" && event.name === "agent_plugins"
    && (event.data as { conversationId?: unknown } | null)?.conversationId === run.conversationId });
  return card > consent;
}

function budgetNotice(run: DurableRun, now: number): string | null {
  if (now - run.lastProgressAt >= RUN_STALENESS_MS) return awaitingAnswer({ run }) ? AWAITING_ANSWER_NOTICE : SAVED_WORK_NOTICE;
  if (run.recoveryCount >= RECOVERY_LIMIT) return EXHAUSTED_NOTICE;
  if (run.recoveryDeadline !== null && now >= run.recoveryDeadline) return EXHAUSTED_NOTICE;
  return null;
}

/** The exhausted notice's detail: the attempt's last diagnostic, else which budget ended. */
function exhaustedDetail({ run }: { run: DurableRun }, _optional = {}): string {
  return attemptFailureDetail({ run }) ?? (run.recoveryCount >= RECOVERY_LIMIT ? `Tried ${RECOVERY_LIMIT} times` : "Recovery window ended");
}

/** Saved work to carry into the next attempt, seeding the saved content when no text event holds it. */
function savedWork({ run }: { run: DurableRun }, _optional = {}): AgentEvent[] {
  const saved = [...(run.message.events ?? [])];
  if (!saved.some((event) => event.kind === "text") && run.message.content) saved.unshift({ kind: "text", text: run.message.content });
  return saved;
}

/** A dead attempt continues now; a fresh queued one waits (see the caller's comment). */
function continuesNow({ run, trigger, now }: { run: DurableRun; trigger: RecoveryTrigger; now: number }, _optional = {}): boolean {
  return trigger === "attempt-failed" || now - run.attemptStartedAt >= 10_000;
}

/** One recovery decision plus the evidence it was based on, for the metadata log line. */
interface Decision { readonly decision: RecoveryResult; readonly probe?: RunProbe; readonly failure?: FailureClass }

/** Recovery coordinator behind explicit host ports. One CAS owns both the attempt and its conversation slot.
 * Each recovery decision logs one `logger.info` line (default console) of run metadata. */
export function createDurableRecovery(ports: RecoveryPorts, { logger = console }: { logger?: Pick<Console, "info"> } = {}): DurableRecovery {
  async function finalize(run: DurableRun, notice: string, { canceled = false, detail }: { canceled?: boolean; detail?: string | undefined } = {}): Promise<RecoveryResult> {
    await ports.cancelAttempt(run, {}).catch(() => undefined);
    // Persist the notice as an event: hook errors are live-only and would leave a reloaded
    // terminal message without its explanation. Only this coordinator decides exhaustion.
    const events: AgentEvent[] = [...(run.message.events ?? []), { kind: "status", label: notice, ...(detail ? { detail } : {}) }];
    await ports.settle({ ...run, content: run.message.content, events, status: canceled ? "canceled" : "failed", endedAt: ports.now() }, {});
    return "finalized";
  }

  async function nativeAllowed(run: DurableRun): Promise<boolean> {
    if (!run.sessionConfirmed || !run.sessionId || !run.child) return false;
    if (!ports.supportsNativeResume({ agentId: run.request.agentId ?? "claude" }, {})) return false;
    return ports.verifyChildDead(run.child, {}).catch(() => false);
  }

  async function launchNext({ run, next, native }: { run: DurableRun; next: DurableRun; native: boolean }, _optional = {}): Promise<void> {
    try {
      await ports.launch({ run: next, request: continuationRequest({ run: { ...run, message: next.message, transcript: next.transcript }, native }, {}) }, {});
      await ports.store.recoveryClock({ runId: next.runId, now: ports.now(), active: false }, {});
    } catch {
      // A rejected/lost start response is uncertain: the daemon may already be executing. The
      // same idempotent attempt is probed by the attached watcher before another CAS is possible.
    }
  }

  async function continueDead(run: DurableRun): Promise<RecoveryResult> {
    await ports.cancelAttempt(run, {}).catch(() => undefined);
    // A locator captured before a hard cancel can outlive its rollout. Reuse reconstruction,
    // including prior turns/tool outcomes, instead of retrying a known missing native session.
    const missingResume = run.request.agentId === 'codex' && /no rollout found for thread id/.test(attemptDiagnostics({ run }, {}));
    const native = !missingResume && await nativeAllowed(run);
    const nextRunId = ports.mintRunId();
    const events = recoveredRunEvents({ saved: savedWork({ run }) }, { notice: missingResume ? 'silent' : 'visible' });
    if (!await ports.store.advance({ run, nextRunId, now: ports.now(), events }, {})) return "superseded";
    const next = await ports.store.load({ messageId: run.messageId }, {});
    // Cancel/deletion can win while the old attempt is being fenced. Re-read after CAS and do
    // not launch against a removed binding or a newer generation.
    if (!next || next.runId !== nextRunId) return "superseded";
    if (next.cancelReason) return finalize(next, STOPPED_NOTICE, { canceled: true });
    await launchNext({ run, next, native });
    ports.attach(next, {});
    return "continued";
  }

  async function probeAttempt({ run, trigger, liveRunId }: { run: DurableRun; trigger: RecoveryTrigger; liveRunId: string | undefined }, _optional = {}): Promise<RunProbe> {
    // A terminal executor end confirms this attempt is dead even when the daemon retains its
    // replayable record (HTTP 200). Other triggers must obtain fresh liveness evidence.
    if (trigger === "attempt-failed") return "dead";
    return liveRunId === run.runId ? "live" : ports.probe(run, {});
  }

  async function reattach(run: DurableRun): Promise<RecoveryResult> {
    await ports.store.recoveryClock({ runId: run.runId, now: ports.now(), active: false }, {});
    ports.attach(run, {});
    return "reattached";
  }

  async function finalizeFailure({ run, failure, diagnostics }: { run: DurableRun; failure: "permanent" | "auth-failure" | "inactivity-watchdog"; diagnostics: string }, _optional = {}): Promise<RecoveryResult> {
    if (failure !== "permanent") return finalize(run, failure === "auth-failure" ? "Not logged in. Saved work is above." : STOPPED_NOTICE, { canceled: true });
    // A bridge failure shows its own reason (and stderr): the generic notice hides what needs repair.
    const bridgeNotice = diagnostics.match(MCP_BRIDGE_FAILURE)?.[0];
    return finalize(run, bridgeNotice ?? EXHAUSTED_NOTICE, { detail: bridgeNotice ? undefined : lastDiagnosticLine({ diagnostics }) });
  }

  async function decide(run: DurableRun, trigger: RecoveryTrigger, liveRunId: string | undefined): Promise<Decision> {
    if (exclusion(run)) return { decision: await finalize(run, STOPPED_NOTICE, { canceled: true }) };
    const probe = await probeAttempt({ run, trigger, liveRunId });
    // HTTP/storage awaits can cross cancellation, settlement, or an attempt-generation change.
    // Re-read before attaching or applying diagnostics to the probed attempt.
    const current = await reload(run);
    if (typeof current === "string") return { probe, decision: current };
    if (probe === "live") return { probe, decision: await reattach(current) };
    if (probe === "uncertain") {
      // Transport uncertainty is not proof of death and spends no restart/time budget. The
      // existing watcher waits and probes again; even an expired budget cannot kill a live child.
      await reattach(current);
      return { probe, decision: "waiting" };
    }
    return decideDead(current, trigger);
  }

  async function decideDead(run: DurableRun, trigger: RecoveryTrigger): Promise<Decision> {
    const probe = "dead";
    // A pending human answer takes precedence over executor exit diagnostics.
    if (awaitingAnswer({ run })) return { probe, decision: await resolveMissing(run, trigger) };
    // Diagnostics decide only the fate of an attempt that is no longer running. Read before the
    // probe, raw stdout quoting a tool description ("OAuth-authenticated") canceled a live turn
    // as "Not logged in" (luvira, 2026-10-08).
    const diagnostics = attemptDiagnostics({ run });
    const failure = attemptFailure({ diagnostics });
    const decision = failure === "retryable" ? await resolveMissing(run, trigger) : await finalizeFailure({ run, failure, diagnostics });
    return { probe, failure, decision };
  }

  async function resolveMissing(run: DurableRun, trigger: RecoveryTrigger): Promise<RecoveryResult> {
    await ports.store.recoveryClock({ runId: run.runId, now: ports.now(), active: true }, {});
    const timed = await reload(run);
    return typeof timed === "string" ? timed : resolveDead(timed, trigger);
  }

  /** The saved row after an await, or the outcome that ends this decision. O(1) store reads. */
  async function reload(run: DurableRun): Promise<DurableRun | RecoveryResult> {
    const current = await ports.store.load({ messageId: run.messageId }, {});
    if (!current) return "gone";
    // A probe only speaks about the generation it inspected. Never apply its dead result to
    // a newer attempt committed by another caller while this one was awaiting storage/HTTP.
    if (current.runId !== run.runId) return "superseded";
    if (current.message.runStatus !== "queued" && current.message.runStatus !== "running") return "terminal";
    if (exclusion(current)) return finalize(current, STOPPED_NOTICE, { canceled: true });
    return current;
  }

  async function resolveDead(run: DurableRun, trigger: RecoveryTrigger): Promise<RecoveryResult> {
    // A dead process cannot resume its question. End this turn with the existing card intact,
    // rather than minting an attempt that runs preflight and asks the same question again.
    if (awaitingAnswer({ run })) return finalize(run, AWAITING_ANSWER_NOTICE);
    const notice = budgetNotice(run, ports.now());
    if (notice) return finalize(run, notice, { detail: notice === EXHAUSTED_NOTICE ? exhaustedDetail({ run }) : undefined });
    // A queued attempt may be between durable acceptance and the daemon's start transaction.
    // Give that idempotent launch time to appear before a 404 can advance its generation.
    if (continuesNow({ run, trigger, now: ports.now() })) return continueDead(run);
    ports.attach(run, {});
    return "waiting";
  }

  return {
    async recover({ messageId, trigger, expectedRunId }, options) {
      const run = await ports.store.load({ messageId }, {});
      if (!run) return "gone";
      if (run.message.runStatus !== "queued" && run.message.runStatus !== "running") return "terminal";
      if (expectedRunId && expectedRunId !== run.runId) return "superseded";
      const { decision, probe, failure } = await decide(run, trigger, options.liveRunId);
      // The watcher re-confirms its own live run every resolution window; log only real recovery
      // decisions. Metadata only: diagnostics, answers and cancel reasons can hold secrets.
      if (options.liveRunId !== run.runId) logger.info("[durable-recovery] " + JSON.stringify({ runId: run.runId, trigger, probe, decision, failureClass: failure }));
      return decision;
    },
  };
}

import type { Clock } from '@jini-ai/core/primitives';
/** Saves completed run output independently of a connected client, through host ports. */

import type { ChatMessage } from '../../core/messages.js';
import { isTerminalRunStatus } from '../../core/messages.js';
import type { AgentEvent } from '../../core/events.js';
import { readSseFrames, runContentFromEvents, runEventsForSave, runInterruptedNotice, translateRunFrame, type RunNotices } from '../../core/run-events/entry.js';
import type { RunDaemonClient, RunLedger, Scheduler, RunIdClassifier, RunSettlement } from './ports.js';
export type { RunDaemonClient, RunLedger, Scheduler, RunIdClassifier, RunRef, RunProgress, RunSettlement } from './ports.js';

/** All infrastructure and host messages are explicit; this factory opens no storage. */
export interface AssistantRunFinalizerArgs {
  readonly ledger: RunLedger;
  readonly daemon: RunDaemonClient;
  readonly clock: Clock;
  readonly scheduler: Scheduler;
  readonly runIdClassifier: RunIdClassifier;
  readonly notices: RunNotices;
  readonly onError: (args: { operation: 'checkpoint' | 'watch'; runId: string; error: unknown }) => void;
}

/** Reconnect delay: 2000ms; retry count: 30; checkpoint interval: 1000ms. */
export interface AssistantRunFinalizerOptions {

  readonly reconnectDelayMs?: number;

  readonly maxReconnects?: number;

  readonly checkpointIntervalMs?: number;
}

export interface AssistantRunFinalizer {

  /** Ignore non-assistant, terminal, missing-status and externally held runs; deduplicate by run ID. */
  watch(input: { principalId: string; conversationId: string; message: ChatMessage }): void;

  /** Wait for current watches to finish; terminal writes may overtake pending checkpoints. */
  idle(args: Record<string, never>): Promise<void>;

  activeCount(args: Record<string, never>): number;
}

interface Watch {
  readonly principalId: string;
  readonly conversationId: string;
  readonly messageId: string;
  readonly runId: string;
  events: AgentEvent[];
  failed: boolean;

  checkpointedEvents: number;
  checkpointedAt: number;

  checkpointPending: boolean;

  terminal: boolean;

  trailing?: { handle: unknown } | undefined;
}

type StreamResult = { kind: "ended"; status: RunSettlement["status"] } | { kind: "gone" } | { kind: "dropped" };
type OpenedStream = { kind: "open"; body: ReadableStream<Uint8Array> } | StreamResult;

/** An error frame keeps a later successful end from settling as a success. */
function endStatus({ failed, terminal }: { failed: boolean; terminal: RunSettlement["status"] }, _optional = {}): RunSettlement["status"] {
  return failed && terminal === "succeeded" ? "failed" : terminal;
}

/** Follow replayable run streams and save through atomic host ledger operations.
 * The host retains authorization, owner scope, kernel transactions, boot reconciliation, HTTP
 * credentials and excluded run-ID prefixes. Replay starts at zero; error-before-success and
 * reconnect exhaustion must not falsely settle a run. Checkpoints are throttled with a trailing
 * write, and checkpoint/settle atomically reject other runs or terminal rows: first terminal wins.
 * Frame vocabulary, paragraph boundaries and compaction are shared with the run-event reducer.
 * Non-success bodies are cancelled and progress scheduling stops at completion. Real database
 * restart/race coverage remains a host responsibility; this factory never opens storage. */
export function createAssistantRunFinalizer(args: AssistantRunFinalizerArgs, options: AssistantRunFinalizerOptions = {}): AssistantRunFinalizer {
  const { daemon, scheduler } = args;
  const now = () => args.clock.nowMs();
  const reconnectDelayMs = options.reconnectDelayMs ?? 2_000;
  const maxReconnects = options.maxReconnects ?? 30;
  const checkpointIntervalMs = options.checkpointIntervalMs ?? 1_000;
  // Diagnostics must not change run/checkpoint behavior, even when the host callback throws.
  function reportError(input: Parameters<AssistantRunFinalizerArgs["onError"]>[0]): void {
    try { args.onError(input); } catch { /* The host owns reporting failures. */ }
  }
  const active = new Map<string, { watch: Watch; done: Promise<void> }>();

  function clearTrailing(watch: Watch): void {
    if (watch.trailing) scheduler.cancel({ handle: watch.trailing.handle });
    watch.trailing = undefined;
  }

  async function settle(watch: Watch, status: RunSettlement["status"], events: AgentEvent[]): Promise<void> {
    watch.terminal = true;
    clearTrailing(watch);
    await args.ledger.settle({
      conversationId: watch.conversationId,
      messageId: watch.messageId,
      runId: watch.runId,
      status,
      content: runContentFromEvents({ events }),
      events: runEventsForSave({ events }),
      endedAt: now(),
    });
  }

  function settleInterrupted(watch: Watch): Promise<void> {
    return settle(watch, "canceled", [...watch.events, runInterruptedNotice({ notice: args.notices.interrupted })]);
  }

  // Coalesce one pending write and one trailing timer. Never block frame consumption on storage.
  // Growth-only checkpointing avoids shrinking a saved answer during replay from event zero.
  async function checkpoint(watch: Watch): Promise<void> {
    if (watch.terminal || watch.checkpointPending) return;
    if (watch.events.length <= watch.checkpointedEvents) return;
    const wait = checkpointIntervalMs - (now() - watch.checkpointedAt);
    if (wait > 0) {
      if (!watch.trailing) {
        watch.trailing = { handle: scheduler.schedule({ task: () => {
          watch.trailing = undefined;
          void checkpoint(watch);
        }, delayMs: wait }) };
      }
      return;
    }
    clearTrailing(watch);
    watch.checkpointedEvents = watch.events.length;
    watch.checkpointedAt = now();
    watch.checkpointPending = true;
    await args.ledger
      .checkpoint({
        conversationId: watch.conversationId,
        messageId: watch.messageId,
        runId: watch.runId,
        content: runContentFromEvents({ events: watch.events }),
        events: runEventsForSave({ events: watch.events }),
      })
      .catch((error: unknown) => reportError({ operation: "checkpoint", runId: watch.runId, error }))
      .finally(() => {
        watch.checkpointPending = false;
        void checkpoint(watch);
      });
  }

  /** The connection's event body, or why it cannot be followed. Non-success bodies are cancelled. */
  async function openStream(watch: Watch): Promise<OpenedStream> {
    const response = await daemon.openEvents({ runId: watch.runId, principalId: watch.principalId });
    if (response.ok && response.body) return { kind: "open", body: response.body };
    await response.body?.cancel().catch(() => undefined);
    return response.status === 404 ? { kind: "gone" } : { kind: "dropped" };
  }

  async function consumeFrames(watch: Watch, body: ReadableStream<Uint8Array>): Promise<StreamResult> {
    // Each connection replays the complete history, rather than appending duplicate deltas.
    watch.events = [];
    watch.failed = false;
    const carry = {};
    for await (const frame of readSseFrames({ body })) {
      const outcome = translateRunFrame({ kind: frame.event, raw: frame.data, notices: args.notices }, { carry });
      watch.events.push(...outcome.events);
      if (outcome.error) watch.failed = true;
      if (outcome.terminal) {
        watch.terminal = true;
        return { kind: "ended", status: endStatus({ failed: watch.failed, terminal: outcome.terminal }) };
      }
      void checkpoint(watch);
    }
    return { kind: "dropped" };
  }

  async function readStream(watch: Watch): Promise<StreamResult> {
    const opened = await openStream(watch);
    return opened.kind === "open" ? consumeFrames(watch, opened.body) : opened;
  }

  async function follow(watch: Watch): Promise<void> {
    for (let attempt = 0; attempt <= maxReconnects; attempt += 1) {
      const result = await readStream(watch).catch((): StreamResult => ({ kind: "dropped" }));
      if (result.kind === "ended") return settle(watch, result.status, watch.events);
      if (result.kind === "gone") return settleInterrupted(watch);
      if ((await daemon.runStatus({ runId: watch.runId, principalId: watch.principalId })) === 404) return settleInterrupted(watch);
      await scheduler.sleep({ delayMs: reconnectDelayMs });
    }
    // Exhaustion alone is not evidence of a terminal run; the host can reattach or repair at boot.
  }

  return {
    watch({ principalId, conversationId, message }) {
      const runId = message.runId;
      if (message.role !== "assistant" || !runId || !args.runIdClassifier.isDaemonRunId({ runId })) return;
      if (message.runStatus === undefined || isTerminalRunStatus({ status: message.runStatus })) return;
      if (active.has(runId)) return;

      const watch: Watch = {
        principalId,
        conversationId,
        messageId: message.id,
        runId,
        events: [],
        failed: false,
        checkpointedEvents: 0,
        checkpointedAt: Number.NEGATIVE_INFINITY,
        checkpointPending: false,
        terminal: false,
      };
      const done = follow(watch)
        .catch((error: unknown) => {
          reportError({ operation: "watch", runId, error });
        })
        .finally(() => {
          watch.terminal = true;
          clearTrailing(watch);
          active.delete(runId);
        });
      active.set(runId, { watch, done });
    },

    async idle(_args) {
      while (active.size > 0) await Promise.all([...active.values()].map((entry) => entry.done));
    },

    activeCount: (_args) => active.size,
  };
}

import type { Clock } from '@jini-ai/core/primitives';
import type { AgentEvent } from '../../core/events.js';
import type { ChatRunStatus } from '../../core/messages.js';

import type { RunRef, RunProgress, RunSettlement } from "../../core/durable-runs/run-contracts.js";
export type { RunRef, RunProgress, RunSettlement } from "../../core/durable-runs/run-contracts.js";
/** Storage contract only. Both methods must atomically reject a different run or terminal row.
 * First terminal write wins; a late checkpoint cannot reopen or replace that row. */
export interface RunLedger {
  checkpoint(args: RunProgress): Promise<boolean>;
  settle(args: RunSettlement): Promise<boolean>;
}
/** Host adapter owns URL, auth, headers and transport timeout policy. Events replay from zero. */
export interface RunDaemonClient {
  openEvents(args: { runId: string; principalId: string }): Promise<Response>;
  runStatus(args: { runId: string; principalId: string }): Promise<number | null>;
}

/** Scheduling returns an opaque handle; a host Node adapter can unref its timer here. */
export interface Scheduler {
  schedule(args: { task: () => void; delayMs: number }): unknown;
  cancel(args: { handle: unknown }): void;
  sleep(args: { delayMs: number }): Promise<void>;
}
export interface RunIdClassifier { isDaemonRunId(args: { runId: string }): boolean }

/** Owner-scoped, provider-neutral durable transcripts. See README for paging and composition. */
// The contract stays with chat's message model: placing it in a lower-level dependency would
// require a reverse dependency on ChatMessage or a second, drifting definition of that shape.
// Types only belong here; drivers, database lifetime and migration execution belong to adapters.
import type { ChatMessage } from '../core/messages.js';

export type ChatOwnerKind = 'user' | 'guest';
// Separate owner kinds preserve different disclosure/retention rules: an anonymous identifier is
// a bearer credential stored as a hash, while authenticated account history can be non-expiring.
export type ChatTitleSource = 'fallback' | 'generated' | 'manual';

export interface ChatOwnerScope {
  readonly scopeId: string;
  readonly ownerKind: ChatOwnerKind;
  /** Guest identifier is already hashed by the host. Never a raw bearer token. */
  readonly ownerId: string;
}

export interface ChatConversation {
  readonly id: string;
  readonly title: string | null;
  readonly titleSource: ChatTitleSource;
  // Compute counts with the conversation projection; fetching them one conversation at a time
  // would turn a list into N+1 database round trips.
  readonly messageCount: number;
  readonly createdAt: number;
  readonly updatedAt: number;
  /** Epoch milliseconds; absence means retained until explicitly deleted. */
  readonly expiresAt?: number;
}

export interface CreateChatConversationInput {
  readonly id: string;
  readonly title?: string | null;
  readonly titleSource?: ChatTitleSource;
  readonly expiresAt?: number;
}

/** Versioned opaque continuation, not an offset or a driver cursor object. */
export type ChatPageCursor = string;

export interface ChatPageOptions {
  /** Default 50; integer from 1 through 200. */
  readonly limit?: number;
  readonly cursor?: ChatPageCursor;
}

export interface ChatPage<T> {
  readonly items: readonly T[];
  /** Absent when this page has no continuation. */
  readonly nextCursor?: ChatPageCursor;
}

export interface ChatMessagePageInput {
  readonly conversationId: string;
}

export interface ChatSearchInput {
  /** Plain human text, never an FTS expression or SQL fragment. */
  readonly query: string;
  readonly conversationId?: string;
}

export interface ChatSearchHit {
  readonly conversationId: string;
  readonly messageId: string;
  readonly excerpt: string;
  /** Relative relevance within this response only, never cross-provider comparable. */
  readonly score?: number;
}

/** Optional capability. No implementation of this interface is promised in this move. */
export interface ChatSearchCapability {
  readonly consistency: 'immediate' | 'eventual';
  search(
    input: ChatSearchInput,
    options?: ChatPageOptions,
  ): Promise<ChatPage<ChatSearchHit>>;
}

/**
 * Every instance is permanently bound to one immutable owner scope.
 * Required identity/payload arguments and optional policy/paging arguments occupy separate bags.
 * Omitted rename source is manual; omitted touch expiry preserves the persisted expiry.
 * @example store.rename({ id, title }, { source: 'generated' }); store.pageConversations({}, { limit: 50 })
 */
// Binding authentication once removes the per-call opportunity to forget the owner predicate.
// A bare ID may name somebody else's conversation; the store must never expose an unscoped read.
export interface ChatStore {
  /** Bounded history discovery/read capability; always uses this store's immutable owner scope. */
  readonly history?: ChatHistoryReader;
  /** Compatibility read: all owned conversations, updatedAt descending. */
  list(): Promise<ChatConversation[]>;
  /** Unknown and other-owned IDs both return null. */
  // Distinguishing these misses would disclose that another owner's conversation exists.
  get(required: { readonly id: string }, optional?: Record<string, never>): Promise<ChatConversation | null>;
  create(input: CreateChatConversationInput, optional?: Record<string, never>): Promise<ChatConversation>;
  /** A generated title must not overwrite a manual title. Default source: manual. */
  // Persist title provenance and enforce this in the adapter, so hosts cannot accidentally let
  // an automatic title replace an operator's rename.
  rename(
    required: { readonly id: string; readonly title: string },
    optional?: { readonly source?: ChatTitleSource },
  ): Promise<ChatConversation | null>;
  touch(required: { readonly id: string }, optional?: { readonly expiresAt?: number }): Promise<void>;
  /** Cascades messages; unknown/other-owned IDs are no-ops. */
  delete(required: { readonly id: string }, optional?: Record<string, never>): Promise<void>;
  /** Compatibility read: all messages in stored position order; unauthorized returns []. */
  messages(required: ChatMessagePageInput, optional?: Record<string, never>): Promise<ChatMessage[]>;
  /** Idempotent update by message ID within its original conversation; unauthorized: null. */
  appendMessage(
    required: { readonly conversationId: string; readonly message: ChatMessage },
    optional?: Record<string, never>,
  ): Promise<ChatMessage | null>;
  pageConversations(required: Record<string, never>, optional?: ChatPageOptions): Promise<ChatPage<ChatConversation>>;
  pageMessages(
    input: ChatMessagePageInput,
    options?: ChatPageOptions,
  ): Promise<ChatPage<ChatMessage>>;
  readonly search?: ChatSearchCapability;
}

/** Eight-method compatibility subset plus optional bounded history; old hosts/fakes still fit. */
export type ChatHistoryStore = Pick<
  ChatStore,
  | 'list' | 'get' | 'create' | 'rename' | 'touch' | 'delete'
  | 'messages' | 'appendMessage' | 'history'
>;

/** Internal persistence projections. Model-facing tools redact and cap these before returning. */
export interface ChatHistoryReader {
  list(required: Record<string, never>, optional?: { query?: string; limit?: number }): Promise<readonly (ChatConversation & { firstUserLine: string })[]>;
  read(required: { chatId: string }, optional?: { fromPosition?: number; limit?: number; includeToolEvents?: boolean }): Promise<{ messages: readonly (ChatMessage & { position: number })[]; hasMore: boolean }>;
}

/** Authority for cross-owner retention must never reach ordinary request handlers. */
export interface ChatHistoryMaintenance {
  /** Delete at most limit conversations; default 500, integer 1..500. */
  sweepExpired(required: { readonly now: number }, optional?: { readonly limit?: number }): Promise<number>;
}

/** Bind one immutable owner scope; no per-call escape to an unscoped store. */
export type ChatStoreFactory = (required: { readonly scope: ChatOwnerScope }, optional?: Record<string, never>) => ChatStore;

export type ChatStoreErrorCode =
  | 'invalid-input'
  | 'invalid-cursor'
  | 'conflict'
  | 'unavailable';

/** Runtime error class in src/store/errors.ts; preserve the original error as cause. */
export interface ChatStoreError extends Error {
  readonly name: 'ChatStoreError';
  readonly code: ChatStoreErrorCode;
}

import type { RunIdPolicy } from "../../core/durable-runs/ports.js";
import type { ChatOwnerScope, ChatStore } from "../ports.js";
import { createSqliteChatStore } from "../sqlite/index.js";
// Owner isolation versus legacy project-only storage: packages/chat/src/store/sqlite/index.ts.
import { createPgliteChatStore } from "../pglite/index.js";
import { createPostgresChatStore } from "../postgres/index.js";

import type { ChatDatabase, ChatKernel } from "./kernel.js";
import { chatKernelTables } from "../sql/boundary.js";
import type { ChatMessage } from "../../core/index.js";

function isOrphanDaemonAnswer(
  { previous, answer, isDaemonRunId }: { previous: ChatMessage | undefined; answer: ChatMessage; isDaemonRunId: RunIdPolicy }, _optional = {},
): boolean {
  return previous?.role !== "user" && answer.role === "assistant" && Boolean(answer.runId && isDaemonRunId({ runId: answer.runId }));
}

function isEarlierOrEqualQuestion({ question, answer }: { question: ChatMessage; answer: ChatMessage }, _optional = {}): boolean {
  return question.role === "user" && question.createdAt !== undefined && answer.createdAt !== undefined
    && question.createdAt <= answer.createdAt;
}

function repairLegacyTurnOrder({ messages, isDaemonRunId }: { messages: ChatMessage[]; isDaemonRunId: RunIdPolicy }, _optional = {}): ChatMessage[] {
  const ordered: ChatMessage[] = [];
  for (let index = 0; index < messages.length; index++) {
    const answer = messages[index]!;
    const question = messages[index + 1];
    // Legacy acceptance saved no question ID. Repair only an orphan daemon answer immediately
    // followed by an earlier/equal-clock user row; a preceding question already owns its answer.
    // A global timestamp sort would reorder valid follow-ups when browser/server clocks disagree.
    if (isOrphanDaemonAnswer({ previous: ordered.at(-1), answer, isDaemonRunId }) && question !== undefined
      && isEarlierOrEqualQuestion({ question, answer })) {
      ordered.push(question, answer);
      index++;
    } else ordered.push(answer);
  }
  return ordered;
}

// Transcript-isolation rationale: Jini packages/chat/src/store/sql/store.ts.
/**
 * Host compatibility factory over Jini's owner-scoped transcript adapters (PLAN C3).
 * Borrows the exact migrated kernel: the adapter's append joins the host's run-ledger transaction.
 * The host retains principal hashing, migrations and connection lifetime.
 * @param kernel The already-open chat kernel; never wrap or open a second connection here.
 * @param scope The authenticated owner tuple; guest ownerId is already hashed by tenant-scope.
 * @param now Injectable epoch-millisecond clock.
 * @returns Full ChatStore, also assignable to existing eight-method ChatHistoryStore consumers.
 */
export function createChatHistoryStore<DB extends ChatDatabase>(
  { kernel: hostKernel, scope, isDaemonRunId }: { kernel: ChatKernel<DB>; scope: ChatOwnerScope; isDaemonRunId: RunIdPolicy },
  { now = Date.now }: { now?: () => number } = {},
): ChatStore {
  const kernel = chatKernelTables<DB, ChatDatabase>({ kernel: hostKernel }, {});
  const required = { kernel, scope };
  const optional = { clock: { nowMs: now } };
  const store = kernel.transport === "better-sqlite3" ? createSqliteChatStore(required, optional)
    : kernel.transport === "pglite" || kernel.transport === "pglite-socket" ? createPgliteChatStore(required, optional)
    : createPostgresChatStore(required, optional);
  return { ...store,
    // Admin reload and recovery use this full-transcript compatibility read. Preserve stored
    // positions (and Jini's position-based page cursors); existing user databases need no migration.
    async messages(required, optional = {}) {
      return repairLegacyTurnOrder({ messages: await store.messages(required, optional), isDaemonRunId }, {});
    },
  };
}

import type { RunIdPolicy } from "../../core/durable-runs/ports.js";
import { recoveredRunEvents, type AgentEvent, type ChatMessage } from "../../core/index.js";
import type { ChatKernel, ChatDatabase } from "./kernel.js";
import { chatKernelTables } from "../sql/boundary.js";
import { sql, type Selectable } from "kysely";
import { hasUnknownToolCall, CONTINUATION_DIVIDER } from "../../core/durable-runs/continuation.js";
import { RECOVERY_WINDOW_MS } from "../../core/durable-runs/policies.js";
import type { DurableRun, DurableRunHead, DurableRunStore } from "../../core/durable-runs/ports.js";
import type { RunRef } from "../../core/durable-runs/ledger-contracts.js";
import type { ChatStore } from "../ports.js";
import { createChatHistoryStore } from "./chat-history-store.js";
import { runLockKey } from "../../core/durable-runs/run-lock.js";
import { runContentFromEvents } from "../../core/run-events/entry.js";
import { toMessage } from "../sql/store.js";

export const RUN_SLOT_BUSY = "Another answer in this chat is still running. This turn is queued in your browser.";
export class RunSlotBusyError extends Error { constructor() { super(RUN_SLOT_BUSY); } }

type RunRow = Selectable<ChatDatabase["ai_chat_messages"]> & { owner_id: string; owner_kind: string; scope_id: string };
/** Where a run read finds its message row: by its id, or by the attempt id it currently holds. */
type RunMatch = { column: "ai_chat_messages.id" | "ai_chat_messages.run_id"; value: string };
/** `events`: parse the run's own saved events. `transcript`: also read every message of its conversation. */
type ReadOptions = { events?: boolean; transcript?: boolean };
/** A run read: its head, and the transcript only when that read loaded one. */
type RunRead = { head: DurableRunHead; transcript: readonly ChatMessage[] };
type Metadata = ChatDatabase["assistant_run_attempts"] | undefined;

function isAcceptedUserShape({ message }: { message: ChatMessage }, _optional = {}): boolean {
  return Boolean(message) && typeof message.id === "string" && Boolean(message.id) && message.role === "user" && typeof message.content === "string"
    && (message.createdAt === undefined || Number.isFinite(message.createdAt));
}

function areAcceptedAttachments({ attachments }: { attachments: unknown }, _optional = {}): boolean {
  return Array.isArray(attachments) && attachments.every((attachment) =>
    attachment && typeof attachment.path === "string" && typeof attachment.name === "string"
    && (attachment.kind === "file" || attachment.kind === "image"));
}

function acceptedUserMessage(
  { request, now }: { request: DurableRun["request"]; now: number }, _optional = {},
): ChatMessage | null {
  const context = JSON.parse(request.contextRef) as { userMessage?: ChatMessage };
  // Older clients supplied only a prompt; never invent a user identity from that transcript.
  const message = context.userMessage;
  if (message === undefined) return null;
  if (!isAcceptedUserShape({ message }, {})) throw new Error("Invalid accepted user message");
  if (message.attachments !== undefined && !areAcceptedAttachments({ attachments: message.attachments }, {})) throw new Error("Invalid accepted user attachments");
  // User input cannot claim an assistant run's status/events. Keep the same identity and payload
  // as its browser PUT, including the original clock and attachment order.
  return { id: message.id, role: "user", content: message.content, createdAt: message.createdAt ?? now,
    ...(message.attachments ? { attachments: message.attachments } : {}) };
}

function recoveryFields({ row, metadata }: { row: RunRow; metadata: Metadata }, _optional = {}) {
  const saved: Partial<NonNullable<Metadata>> = metadata ?? {};
  return { recoveryCount: saved.recovery_count ?? 0, recoveryDeadline: saved.recovery_deadline ?? null,
    attemptStartedAt: saved.attempt_started_at ?? 0, lastProgressAt: saved.last_progress_at ?? row.started_at ?? row.created_at,
    cancelReason: saved.cancel_reason ?? null };
}

function sessionFields({ metadata }: { metadata: Metadata }, _optional = {}) {
  return { sessionId: metadata?.session_id ?? null, sessionConfirmed: metadata?.session_confirmed === 1,
    child: metadata?.child_pid && metadata.child_started_at ? { pid: metadata.child_pid, startedAt: metadata.child_started_at } : null,
    attemptBase: savedRunEvents({ json: metadata?.attempt_base_json ?? null }, {}) };
}

function acceptedRequest({ row, metadata, transcript }: { row: RunRow; metadata: Metadata; transcript: readonly ChatMessage[] }, _optional = {}) {
  if (metadata) return JSON.parse(metadata.accepted_json);
  return { agentId: row.agent_id ?? "claude", contextRef: JSON.stringify({ conversationId: row.conversation_id,
    prompt: transcript.map((item) => `${item.role}: ${item.content}`).join("\n\n") }) };
}

function runHead(
  { row, runId, metadata, message, transcript }: { row: RunRow; runId: string; metadata: Metadata; message: ChatMessage; transcript: readonly ChatMessage[] },
  { isDaemonRunId }: { isDaemonRunId: RunIdPolicy },
): DurableRunHead {
  return {
    messageId: row.id, conversationId: row.conversation_id, runId,
    workspaceId: row.scope_id,
    principalId: row.owner_kind === "user" ? row.owner_id : null,
    engine: metadata?.engine ?? (isDaemonRunId({ runId }) ? "daemon" : "request"), message,
    request: acceptedRequest({ row, metadata, transcript }, {}),
    ...recoveryFields({ row, metadata }, {}), ...sessionFields({ metadata }, {}),
  };
}

function metadataForRun({ run }: { run: DurableRunHead }, _optional = {}) {
  return { message_id: run.messageId, engine: run.engine, accepted_json: JSON.stringify(run.request),
    recovery_count: run.recoveryCount, recovery_deadline: run.recoveryDeadline, recovery_elapsed_ms: 0,
    attempt_started_at: run.attemptStartedAt, last_progress_at: run.lastProgressAt,
    cancel_reason: run.cancelReason, session_id: run.sessionId, session_confirmed: run.sessionConfirmed ? 1 : 0,
    child_pid: null, child_started_at: null, attempt_base_json: JSON.stringify(run.attemptBase) };
}

export function attemptCanExecute({ run }: { run: DurableRunHead | null }, _optional = {}): boolean {
  return Boolean(run && !run.cancelReason && ["queued", "running"].includes(run.message.runStatus ?? ""));
}

export function savedRunEvents({ json }: { json: string | null }, _optional = {}): AgentEvent[] {
  try { const value: unknown = JSON.parse(json ?? "[]"); return Array.isArray(value) ? value as AgentEvent[] : []; }
  catch { return []; }
}

/** Index of the latest matching event, or -1. */
function lastIndexOf(
  { events, matches }: { events: readonly AgentEvent[]; matches: (event: AgentEvent) => boolean }, _optional = {},
): number {
  // Scan backward to keep the latest match without requiring ES2023 array methods.
  for (let index = events.length - 1; index >= 0; index--) if (matches(events[index]!)) return index;
  return -1;
}

/** Saved projection, with legacy content restored as text when no text event carries it. */
function savedProjection({ current }: { current: DurableRunHead }, _optional = {}): AgentEvent[] {
  const saved = [...(current.message.events ?? [])];
  if (!saved.some((event) => event.kind === "text") && current.message.content) saved.unshift({ kind: "text", text: current.message.content });
  return saved;
}

function continuationEvents(
  { current, incoming }: { current: DurableRunHead; incoming: readonly AgentEvent[] }, _optional = {},
): readonly AgentEvent[] {
  const separator = lastIndexOf({ events: incoming, matches: (event) => event.kind === "text" && event.text === CONTINUATION_DIVIDER });
  const saved = savedProjection({ current });
  // A trailing checkpoint/tool barrier may land after the recovery probe but before its CAS.
  // Build the continuation segment from the projection inside the transaction, never that probe.
  if (separator >= 0) return [...saved, ...incoming.slice(separator)];
  // Empty startup retries have a recovery marker but no divider. Rebase their saved work under
  // the same lock too: a checkpoint may have arrived since the recovery probe.
  const marker = lastIndexOf({ events: incoming, matches: (event) => event.kind === "status" && event.code === "run_recovering" });
  if (marker >= 0) {
    const event = incoming[marker]!;
    const notice = event.kind === 'status' && event.label === '' ? 'silent' : 'visible';
    return [...recoveredRunEvents({ saved }, { notice }), ...incoming.slice(marker + 1)];
  }
  return runContentFromEvents({ events: incoming }).length >= current.message.content.length ? incoming : saved;
}

/** `events_json` with one more event, built in SQL: no dialect parses or re-serializes the saved
 * array in JS. Writers store `JSON.stringify` output (no whitespace), so a non-empty array is
 * `[...]` and gains `,event`; `[]`, NULL and anything not array-shaped (a truncated legacy value,
 * which the old JS read also treated as no events) become `[event]`. Plain `substr`/`length`/`||`
 * run unchanged on SQLite and PostgreSQL. */
function appendedEventsJson({ event }: { event: AgentEvent }, _optional = {}) {
  const item = sql<string>`cast(${JSON.stringify(event)} as text)`;
  return sql<string>`case when events_json like '[_%]' then substr(events_json, 1, length(events_json) - 1) || ',' || ${item} || ']' else '[' || ${item} || ']' end`;
}

function sameOwner(
  { run, required }: { run: DurableRunHead; required: { principalId: string; conversationId: string } }, _optional = {},
): boolean {
  return run.principalId === required.principalId && run.conversationId === required.conversationId;
}

/** Same kernel and message lock as checkpoint/settle. Claim changes run_id before any spawn;
 * old attempts cannot write projections or dispatch tools after that transaction commits. */
export function createDurableRunStore<DB extends ChatDatabase>({ kernel: hostKernel, isDaemonRunId }: { kernel: ChatKernel<DB>; isDaemonRunId: RunIdPolicy }, _optional = {}): DurableRunStore {
  const kernel = chatKernelTables<DB, ChatDatabase>({ kernel: hostKernel }, {});
  /** The run's own message row, with its events only when asked: never another message's. */
  async function runRow({ match }: { match: RunMatch }, { events = false }: ReadOptions = {}): Promise<RunRow | undefined> {
    const eventsColumn = events ? sql<string | null>`${sql.ref("ai_chat_messages.events_json")}` : sql<string | null>`null`;
    return kernel.run((db) => db.selectFrom("ai_chat_messages")
      .innerJoin("ai_chats", "ai_chats.id", "ai_chat_messages.conversation_id")
      .select(["ai_chat_messages.id", "conversation_id", "role", "content", "agent_id", "agent_name", "attachments_json",
        "run_id", "run_status", "position", "ai_chat_messages.created_at", "started_at", "ended_at", "owner_kind", "owner_id", "scope_id"])
      .select(eventsColumn.as("events_json"))
      .where(match.column, "=", match.value).where("role", "=", "assistant").executeTakeFirst());
  }

  /** Every message of the run's conversation; only `load` and legacy rows without attempt metadata pay this. */
  async function conversationTranscript({ row }: { row: RunRow }, _options = {}): Promise<ChatMessage[]> {
    const history = createChatHistoryStore({ kernel, isDaemonRunId, scope: { scopeId: row.scope_id, ownerKind: row.owner_kind as "user" | "guest", ownerId: row.owner_id } }, {});
    return history.messages({ conversationId: row.conversation_id });
  }

  /** One run's head, plus its transcript when that was read (`[]` otherwise). */
  async function readRun({ match }: { match: RunMatch }, options: ReadOptions = {}): Promise<RunRead | null> {
    const row = await runRow({ match }, options);
    if (!row || !row.run_id) return null;
    const messageId = row.id;
    const metadata = await kernel.run((db) => db.selectFrom("assistant_run_attempts").selectAll().where("message_id", "=", messageId).executeTakeFirst());
    // A legacy row's accepted request is derived from its transcript, so only it reads one here.
    const transcript = options.transcript || !metadata ? await conversationTranscript({ row }) : [];
    const message = options.transcript ? transcript.find((item) => item.id === messageId) : toMessage(row);
    if (!message) return null; // Deletion may have cascaded between the two reads.
    return { head: runHead({ row, runId: row.run_id, metadata, message, transcript }, { isDaemonRunId }), transcript };
  }

  /** Locked read of one message; `transcript` decides whether it is a whole run or only its head. */
  async function lockedRead(
    { messageId, conversationId }: { messageId: string; conversationId: string }, options: ReadOptions = {},
  ): Promise<RunRead | null> {
    return kernel.transaction(async () => {
      // Message, attempt metadata and transcript must describe the same generation. A CAS in
      // the gap between independent reads must never pair a new projection with an old session.
      await kernel.lockKey(runLockKey({ messageId, conversationId, runId: "" }));
      return readRun({ match: { column: "ai_chat_messages.id", value: messageId } }, options);
    });
  }

  async function load({ messageId }: { messageId: string }, _options = {}): Promise<DurableRun | null> {
    const binding = await kernel.run((db) => db.selectFrom("ai_chat_messages").select("conversation_id")
      .where("id", "=", messageId).executeTakeFirst());
    if (!binding) return null;
    // The message comes from the transcript, so its row's events are not selected twice.
    const read = await lockedRead({ messageId, conversationId: binding.conversation_id }, { transcript: true });
    return read && { ...read.head, transcript: read.transcript };
  }

  /** Unlocked probe: the message and conversation an attempt id currently names. */
  async function probeRun({ runId }: { runId: string }, _options = {}) {
    return kernel.run((db) => db.selectFrom("ai_chat_messages").select(["id", "conversation_id"])
      .where("run_id", "=", runId).where("role", "=", "assistant").executeTakeFirst());
  }

  async function find({ runId, principalId }: { runId: string; principalId?: string }, _options = {}): Promise<DurableRunHead | null> {
    const row = await probeRun({ runId });
    if (!row) return null;
    const run = (await lockedRead({ messageId: row.id, conversationId: row.conversation_id }, { events: true }))?.head ?? null;
    return principalId !== undefined && run?.principalId !== principalId ? null : run;
  }

  /** Slot and run locks, then the owner-scoped conversation; null when the caller does not own it. */
  async function lockOwnedConversation(
    { required }: { required: RunRef & { principalId: string; workspaceId: string } }, _options = {},
  ): Promise<ChatStore | null> {
    await kernel.lockKey(`chat-slot:${required.conversationId}`);
    await kernel.lockKey(runLockKey(required));
    const history = createChatHistoryStore({ kernel, isDaemonRunId, scope: { scopeId: required.workspaceId, ownerKind: "user", ownerId: required.principalId } }, {});
    return await history.get({ id: required.conversationId }) ? history : null;
  }

  async function assertSlotFree({ conversationId }: { conversationId: string }, _options = {}): Promise<void> {
    const occupied = await kernel.run((db) => db.selectFrom("ai_chat_messages").select("id")
      .where("conversation_id", "=", conversationId).where("role", "=", "assistant")
      .where("run_status", "in", ["queued", "running"]).executeTakeFirst());
    if (occupied) throw new RunSlotBusyError();
  }

  async function appendAcceptedQuestion(
    { history, required, userMessage }: { history: ChatStore; required: Parameters<DurableRunStore["accept"]>[0]; userMessage: ChatMessage }, _options = {},
  ): Promise<void> {
    if (userMessage.id === required.messageId) throw new Error("User and assistant messages must have different IDs");
    // A pending/failed browser PUT must never let the assistant take the first position.
    // Nested appends join this transaction and retain the conversation lock through both
    // writes, so either arrival order of the idempotent PUT yields user then assistant.
    const saved = await history.appendMessage({ conversationId: required.conversationId, message: userMessage });
    if (!saved || saved.role !== "user") throw new Error("Accepted user message could not be persisted");
  }

  /** @returns false when the answer id collides and no question was written. */
  async function appendQueuedAnswer(
    { history, required, hasQuestion }: { history: ChatStore; required: Parameters<DurableRunStore["accept"]>[0]; hasQuestion: boolean }, _options = {},
  ): Promise<boolean> {
    const message: ChatMessage = { id: required.messageId, role: "assistant", content: "", events: [],
      runId: required.runId, runStatus: "queued", createdAt: required.now, startedAt: required.now,
      ...(required.request.agentId ? { agentId: required.request.agentId } : {}) };
    const savedMessage = await history.appendMessage({ conversationId: required.conversationId, message });
    if (savedMessage?.role === "assistant") return true;
    // Returning null here would commit the question alone after an ID collision.
    if (hasQuestion) throw new Error("Accepted assistant message could not be persisted");
    return false;
  }

  async function accept(required: Parameters<DurableRunStore["accept"]>[0], _options = {}): Promise<DurableRun | null> {
    return kernel.transaction(async () => {
      const history = await lockOwnedConversation({ required });
      if (!history) return null;
      const existing = await load({ messageId: required.messageId }, {});
      if (existing) return sameOwner({ run: existing, required }) ? existing : null;
      await assertSlotFree({ conversationId: required.conversationId });
      const userMessage = acceptedUserMessage({ request: required.request, now: required.now }, {});
      if (userMessage) await appendAcceptedQuestion({ history, required, userMessage });
      if (!await appendQueuedAnswer({ history, required, hasQuestion: userMessage !== null })) return null;
      await kernel.run((db) => db.insertInto("assistant_run_attempts").values({
        message_id: required.messageId, engine: "daemon", accepted_json: JSON.stringify(required.request),
        recovery_count: 0, recovery_deadline: null, last_progress_at: required.now, cancel_reason: null,
        recovery_elapsed_ms: 0, attempt_started_at: required.now,
        session_id: null, session_confirmed: 0, child_pid: null, child_started_at: null, attempt_base_json: "[]",
      }).execute());
      return load({ messageId: required.messageId }, {});
    });
  }

  async function advance({ run, nextRunId, now, events }: Parameters<DurableRunStore["advance"]>[0], _options = {}): Promise<boolean> {
    return kernel.transaction(async () => {
      await kernel.lockKey(runLockKey(run));
      // The projection rebase needs this run's events, never the rest of its conversation.
      const current = (await lockedRead(run, { events: true }))?.head;
      if (!current || current.cancelReason || current.runId !== run.runId) return false;
      const projection = continuationEvents({ current, incoming: events }, {});
      const result = await kernel.run((db) => db.updateTable("ai_chat_messages")
        .set({ run_id: nextRunId, run_status: "queued", content: runContentFromEvents({ events: projection }), events_json: JSON.stringify(projection) })
        .where("id", "=", run.messageId).where("run_id", "=", run.runId)
        .where("run_status", "in", ["queued", "running"]).executeTakeFirst());
      if (Number(result.numUpdatedRows) === 0) return false;
      await kernel.run((db) => db.insertInto("assistant_run_attempts").values({
        message_id: run.messageId, engine: run.engine, accepted_json: JSON.stringify(run.request),
        recovery_count: current.recoveryCount + 1, recovery_deadline: current.recoveryDeadline ?? now + RECOVERY_WINDOW_MS,
        recovery_elapsed_ms: 0, attempt_started_at: now,
        last_progress_at: current.lastProgressAt, cancel_reason: null, session_id: null,
        session_confirmed: 0, child_pid: null, child_started_at: null, attempt_base_json: JSON.stringify(projection),
      }).onConflict((oc) => oc.column("message_id").doUpdateSet({
        recovery_count: current.recoveryCount + 1, recovery_deadline: current.recoveryDeadline ?? now + RECOVERY_WINDOW_MS,
        attempt_started_at: now,
        session_id: null, session_confirmed: 0, child_pid: null, child_started_at: null, attempt_base_json: JSON.stringify(projection),
      })).execute());
      return true;
    });
  }

  /** Probe without the run lock, take it, then read: a run deleted or advanced in the gap reads as gone.
   * One read under the lock serves the whole operation; the unlocked probe only names the lock.
   * @returns The run as of the lock, or null when the attempt id is unknown or no longer current. */
  async function lockedRun({ runId }: { runId: string }, options: ReadOptions = {}): Promise<DurableRunHead | null> {
    const probe = await probeRun({ runId });
    if (!probe) return null;
    await kernel.lockKey(runLockKey({ messageId: probe.id, conversationId: probe.conversation_id, runId }));
    return (await readRun({ match: { column: "ai_chat_messages.run_id", value: runId } }, options))?.head ?? null;
  }

  async function cancel({ runId, reason }: Parameters<DurableRunStore["cancel"]>[0], _options = {}): Promise<void> {
    await kernel.transaction(async () => {
      const run = await lockedRun({ runId });
      if (!run) return;
      await kernel.run((db) => db.insertInto("assistant_run_attempts").values({ ...metadataForRun({ run }, {}), cancel_reason: reason })
        .onConflict((oc) => oc.column("message_id").doUpdateSet({ cancel_reason: reason })).execute());
    });
  }

  async function cancelPending(required: Parameters<DurableRunStore["cancelPending"]>[0], _options = {}): Promise<DurableRun | null> {
    return kernel.transaction(async () => {
      const history = await lockOwnedConversation({ required });
      if (!history) return null;
      const existing = await load({ messageId: required.messageId }, {});
      if (existing) {
        if (!sameOwner({ run: existing, required })) return null;
        await cancel({ runId: existing.runId, reason: "user-stop" }, {}); return load({ messageId: existing.messageId }, {});
      }
      // Stop may beat acceptance or its response. A terminal tombstone for the same logical
      // identity makes any later duplicate acceptance a no-op, without reserving the chat slot.
      await history.appendMessage({ conversationId: required.conversationId, message: { id: required.messageId, role: "assistant", content: "",
        events: [{ kind: "status", label: "Stopped." }], runId: required.runId, runStatus: "canceled", createdAt: required.now, endedAt: required.now } });
      return load({ messageId: required.messageId }, {});
    });
  }

  async function captureSession({ runId, sessionId, child, confirmed = true }: Parameters<DurableRunStore["captureSession"]>[0], _options = {}): Promise<boolean> {
    return kernel.transaction(async () => {
      const run = await lockedRun({ runId });
      if (!run || !attemptCanExecute({ run }, {})) return false;
      const fields = { session_id: sessionId, session_confirmed: confirmed ? 1 : 0, ...(child ? { child_pid: child.pid, child_started_at: child.startedAt } : {}) };
      await kernel.run((db) => db.insertInto("assistant_run_attempts").values({ ...metadataForRun({ run }, {}), ...fields })
        .onConflict((oc) => oc.column("message_id").doUpdateSet(fields)).execute());
      // Session and generation share the same lock/transaction; an old callback cannot write
      // the conversation's locator in the gap between a successful guard and a later CAS.
      await kernel.run((db) => db.insertInto("assistant_agent_sessions").values({ conversation_id: run.conversationId,
        agent_id: run.request.agentId ?? "claude", session_id: sessionId, updated_at: Date.now() })
        .onConflict((oc) => oc.columns(["conversation_id", "agent_id"]).doUpdateSet({ session_id: sessionId, updated_at: Date.now() })).execute());
      return true;
    });
  }

  async function clearSession({ runId, sessionId }: Parameters<DurableRunStore["clearSession"]>[0], _options = {}): Promise<void> {
    await kernel.transaction(async () => {
      const run = await lockedRun({ runId });
      if (!run) return;
      await kernel.run((db) => db.deleteFrom("assistant_agent_sessions").where("conversation_id", "=", run.conversationId)
        .where("agent_id", "=", run.request.agentId ?? "claude").where("session_id", "=", sessionId).execute());
      await kernel.run((db) => db.updateTable("assistant_run_attempts").set({ session_id: null, session_confirmed: 0 })
        .where("message_id", "=", run.messageId).where("session_id", "=", sessionId).execute());
    });
  }

  async function guardTool(required: Parameters<DurableRunStore["guardTool"]>[0], _options = {}): Promise<"allowed" | "unknown" | "stale"> {
    return kernel.transaction(async () => {
      // The unknown-call check needs this run's saved events (one row), never other messages'.
      const run = await lockedRun({ runId: required.runId }, { events: true });
      if (!run || !attemptCanExecute({ run }, {})) return "stale";
      const events = run.message.events ?? [];
      const canonical = events.filter((event) => event.kind !== "tool_use" || event.name === required.toolId);
      if (hasUnknownToolCall({ ...required, events: run.attemptBase }, {}) || hasUnknownToolCall({ ...required, events: canonical }, {})) return "unknown";
      if (required.toolUseId) await writeToolEvent(run, { kind: "tool_use", id: required.toolUseId, name: required.toolId, input: required.input });
      return "allowed";
    });
  }

  async function writeToolEvent(run: DurableRunHead, event: AgentEvent): Promise<void> {
    await kernel.run((db) => db.updateTable("ai_chat_messages").set({ events_json: appendedEventsJson({ event }) })
      .where("id", "=", run.messageId).where("run_id", "=", run.runId).where("run_status", "in", ["queued", "running"]).execute());
    await kernel.run((db) => db.updateTable("assistant_run_attempts")
      .set({ recovery_count: 0, recovery_deadline: null, recovery_elapsed_ms: 0, last_progress_at: Date.now() })
      .where("message_id", "=", run.messageId).execute());
  }

  async function completeTool({ runId, toolUseId, content }: Parameters<DurableRunStore["completeTool"]>[0], _options = {}): Promise<void> {
    await kernel.transaction(async () => {
      const run = await lockedRun({ runId });
      if (run) await writeToolEvent(run, { kind: "tool_result", toolUseId, content, isError: false });
    });
  }

  async function recoveryClock({ runId, now, active }: Parameters<DurableRunStore["recoveryClock"]>[0], _options = {}): Promise<void> {
    await kernel.transaction(async () => {
      const run = await lockedRun({ runId });
      if (!run) return;
      const row = await kernel.run((db) => db.selectFrom("assistant_run_attempts").selectAll().where("message_id", "=", run.messageId).executeTakeFirst())
        ?? metadataForRun({ run }, {});
      let deadline = row.recovery_deadline;
      let elapsed = row.recovery_elapsed_ms;
      if (active && deadline === null) deadline = now + Math.max(0, RECOVERY_WINDOW_MS - elapsed);
      if (!active && deadline !== null) { elapsed = Math.max(0, RECOVERY_WINDOW_MS - (deadline - now)); deadline = null; }
      await kernel.run((db) => db.insertInto("assistant_run_attempts").values({ ...row, recovery_deadline: deadline, recovery_elapsed_ms: elapsed })
        .onConflict((oc) => oc.column("message_id").doUpdateSet({ recovery_deadline: deadline, recovery_elapsed_ms: elapsed })).execute());
    });
  }

  return { load, find, accept, advance, cancel, cancelPending, captureSession, clearSession, guardTool, completeTool, recoveryClock };
}

/** Model-facing history tools over an authenticated owner-scoped store; no database handles. */
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, ToolInputError,
  type AgentToolDefinition, type AgentToolSideEffect, type ToolExecutionContext, type ToolRegistration } from '@jini-ai/core';
import { redactUserText, type RedactUserText } from '../../core/user-text-redaction.js';
import type { ChatHistoryReader, ChatHistoryStore } from '../ports.js';
import type { AgentEvent } from '../../core/events.js';
import { assistantHistoryToolMetadata } from '../../core/history-tool-metadata.js';

export const HISTORY_MESSAGE_CHAR_CAP = 8_000;
export const HISTORY_TOTAL_CHAR_CAP = 40_000;
const TOOL_EVENT_CAP = 50;

export const assistantHistoryDerivedRisk: ReadonlyMap<string, AgentToolSideEffect> = new Map([
  ['assistant_chats_list', 'none'], ['assistant_chat_read', 'none'],
]);
/** Exported so host contract tests can pin each registration to its catalog entry. */
export const assistantHistoryToolCatalog = indexCatalogById<AgentToolDefinition>({ catalog: [
  { name: 'assistant_chats_list', sideEffects: 'none', authorization: { permission: 'admin.assistant.use' },
    description: "Lists the CURRENT user's own conversations on this site, newest first, optionally searching titles and message content. Returns id, title, updatedAt, messageCount and firstUserLine, with redacted, capped text. When the user refers to an earlier or interrupted chat ('continue what we were doing'), list first, then assistant_chat_read to read its tail, summarise the state and continue. No other user's chats are accessible; unavailable history is an error.",
    inputSchema: { type: 'object', additionalProperties: false, properties: {
      query: { type: 'string', maxLength: 200 }, limit: { type: 'integer', minimum: 1, maximum: 50, default: 20 },
    } } },
  { name: 'assistant_chat_read', sideEffects: 'none', authorization: { permission: 'admin.assistant.use' },
    description: "Reads one of the CURRENT user's own chats in stored message order. Omit fromPosition to read the latest tail (default 50 messages); use fromPosition and nextPosition for forward pagination. List chats first when resuming earlier work, read the tail, summarise the state, then continue. Returns redacted messages, positions, continuation and truncated flags; each serialized message is capped at 8,000 characters and the result at 40,000 characters. Tool events, when requested, contain only tool name and outcome, never payloads. Attachments are omitted. Missing and other-user chats receive the same refusal.",
    inputSchema: { type: 'object', additionalProperties: false, required: ['chatId'], properties: {
      chatId: { type: 'string', minLength: 1, maxLength: 128 },
      fromPosition: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, maximum: 100, default: 50 },
      includeToolEvents: { type: 'boolean', default: false },
    } } },
] });

/** Auth is resolved by the host using execution identity, never from model input. */
export interface AssistantHistoryToolPorts {
  getStore(required: { principalId: string }, optional?: Record<string, never>): Promise<ChatHistoryStore>;
}
interface ToolSummary { name: string; outcome: 'succeeded' | 'failed' | 'unknown' }
interface HistoryMessageView {
  id: string; role: string; position: number; content: string; truncated: boolean;
  toolEvents?: ToolSummary[];
}

/** Cap a fresh projection including JSON escapes and tool summaries, before the total-page cap.
 * The projection is local to this call, so trimming it cannot mutate stored messages or events.
 * @complexity Bounded content/summary serialization; no I/O or unbounded output accumulation.
 */
function capMessage({ view }: { view: HistoryMessageView }, _options = {}): HistoryMessageView {
  while (JSON.stringify(view).length > HISTORY_MESSAGE_CHAR_CAP) {
    view.truncated = true;
    if (view.content.length > 0) view.content = view.content.slice(0, Math.floor(view.content.length / 2));
    else view.toolEvents?.pop();
  }
  return view;
}

function toolOutcome({ isError }: { isError: unknown }, _options = {}): ToolSummary['outcome'] {
  if (isError === true) return 'failed';
  return isError === false ? 'succeeded' : 'unknown';
}

/** Outcome per tool-use id; malformed historical events are ignored. */
function toolOutcomes({ events }: { events: readonly unknown[] }, _options = {}): Map<string, ToolSummary['outcome']> {
  const outcomes = new Map<string, ToolSummary['outcome']>();
  for (const raw of events) {
    const event = raw as Partial<Extract<AgentEvent, { kind: 'tool_result' }>> | null;
    if (event?.kind === 'tool_result' && typeof event.toolUseId === 'string') outcomes.set(event.toolUseId, toolOutcome({ isError: event.isError }));
  }
  return outcomes;
}

/** Well-formed tool-use events in stored order; malformed historical events are ignored. */
function toolUses({ events }: { events: readonly unknown[] }, _options = {}): { name: string; id?: string }[] {
  return events.filter((raw): raw is { name: string; id?: string } => {
    const event = raw as Partial<Extract<AgentEvent, { kind: 'tool_use' }>> | null;
    return event?.kind === 'tool_use' && typeof event.name === 'string';
  });
}

/** Only bounded names and status cross this boundary; malformed historical events are ignored.
 * @complexity O(e) time/space in persisted events; output is capped at 50 summaries.
 */
function summarizeTools({ events, redact }: { events: unknown; redact: RedactUserText }, _options = {}): { items: ToolSummary[]; truncated: boolean } {
  if (!Array.isArray(events)) return { items: [], truncated: false };
  const outcomes = toolOutcomes({ events });
  const items: ToolSummary[] = [];
  let truncated = false;
  for (const event of toolUses({ events })) {
    if (items.length === TOOL_EVENT_CAP) { truncated = true; break; }
    const name = redact({ text: event.name }).text;
    if (name.length > 120) truncated = true;
    items.push({ name: name.slice(0, 120), outcome: outcomes.get(event.id ?? '') ?? 'unknown' });
  }
  return { items, truncated };
}

/** Validate advertised integer bounds even when a transport bypasses JSON schema validation. */
function integerOption({ input, key, fallback, max, min = 1 }: { input: Record<string, unknown>; key: string; fallback: number; max: number; min?: number }, _options = {}): number {
  const value = input[key] === undefined ? fallback : input[key];
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < min || value > max) {
    throw new ToolInputError({ message: `${key} must be an integer from ${min} through ${max}.` });
  }
  return value;
}

/** Strict allowlist prevents model-supplied identity from ever reaching the host scope factory. */
function inputRecord({ input, keys }: { input: unknown; keys: readonly string[] }, _options = {}): Record<string, unknown> {
  const record = requireInputRecord({ input });
  if (Object.keys(record).some(key => !keys.includes(key))) throw new ToolInputError({ message: 'Unexpected chat history input field. Use the published schema.' });
  return record;
}

/** The scoped store's bounded reader; hosts without one fail closed for both tools. */
async function openHistory(
  { ports, principalId }: { ports: AssistantHistoryToolPorts; principalId: string }, _options = {},
): Promise<{ store: ChatHistoryStore; history: ChatHistoryReader }> {
  const store = await ports.getStore({ principalId }, {});
  if (!store.history) throw new ToolInputError({ message: 'Chat history is unavailable on this site.' });
  return { store, history: store.history };
}

function listInput({ input: raw }: { input: unknown }, _options = {}): { query?: string; limit: number } {
  const input = inputRecord({ input: raw, keys: ['query', 'limit'] });
  if (input.query !== undefined && (typeof input.query !== 'string' || input.query.length > 200)) throw new ToolInputError({ message: 'query must be a string of at most 200 characters.' });
  const limit = integerOption({ input, key: 'limit', fallback: 20, max: 50 });
  return { ...(input.query === undefined ? {} : { query: input.query }), limit };
}

type ChatListRow = Awaited<ReturnType<ChatHistoryReader['list']>>[number];
interface ChatListView { id: string; title: string; updatedAt: number; messageCount: number; firstUserLine: string }

function projectChatRow({ row, redact }: { row: ChatListRow; redact: RedactUserText }, _options = {}): { chat: ChatListView; truncated: boolean } {
  // Redact BEFORE slicing: a cap must not turn a credential into an undetectable fragment.
  const title = redact({ text: row.title ?? '' }).text;
  const first = redact({ text: row.firstUserLine }).text.split(/\r?\n/, 1)[0]!;
  const truncated = title.length > 300 || first.length > 500 || row.id.length > 128;
  return { truncated, chat: { id: redact({ text: row.id }).text.slice(0, 128), title: title.slice(0, 300), updatedAt: row.updatedAt,
    messageCount: row.messageCount, firstUserLine: first.slice(0, 500) } };
}

async function listChats(
  { ports, redact, ctx }: { ports: AssistantHistoryToolPorts; redact: RedactUserText; ctx: ToolExecutionContext }, _options = {},
): Promise<{ chats: ChatListView[]; truncated: boolean }> {
  const options = listInput({ input: ctx.input });
  const { history } = await openHistory({ ports, principalId: ctx.principal.id });
  const projected = (await history.list({}, options)).map(row => projectChatRow({ row, redact }));
  const chats = projected.map(item => item.chat);
  let truncated = projected.some(item => item.truncated);
  // List is bounded too; serialized escaping can make text larger than its character count.
  while (JSON.stringify({ chats, truncated }).length > HISTORY_TOTAL_CHAR_CAP) { chats.pop(); truncated = true; }
  return { chats, truncated };
}

interface ReadInput { chatId: string; limit: number; fromPosition?: number; includeToolEvents: boolean }

function readInput({ input: raw }: { input: unknown }, _options = {}): ReadInput {
  const input = inputRecord({ input: raw, keys: ['chatId', 'fromPosition', 'limit', 'includeToolEvents'] });
  if (typeof input.chatId !== 'string' || !input.chatId.trim() || input.chatId.length > 128) throw new ToolInputError({ message: 'chatId must be an id returned by assistant_chats_list.' });
  const limit = integerOption({ input, key: 'limit', fallback: 50, max: 100 });
  const fromPosition = input.fromPosition === undefined ? undefined : integerOption({ input, key: 'fromPosition', fallback: 0, max: Number.MAX_SAFE_INTEGER, min: 0 });
  if (input.includeToolEvents !== undefined && typeof input.includeToolEvents !== 'boolean') throw new ToolInputError({ message: 'includeToolEvents must be boolean.' });
  return { chatId: input.chatId, limit, ...(fromPosition === undefined ? {} : { fromPosition }), includeToolEvents: input.includeToolEvents === true };
}

type HistoryRow = Awaited<ReturnType<ChatHistoryReader['read']>>['messages'][number];

function projectMessage({ row, includeToolEvents, redact }: { row: HistoryRow; includeToolEvents: boolean; redact: RedactUserText }, _options = {}): HistoryMessageView {
  const content = redact({ text: row.content }).text;
  const tools = includeToolEvents ? summarizeTools({ events: row.events, redact }) : undefined;
  return capMessage({ view: { id: redact({ text: row.id }).text.slice(0, 128), role: row.role === 'user' ? 'user' : 'assistant', position: row.position,
    content: content.slice(0, HISTORY_MESSAGE_CHAR_CAP), truncated: content.length > HISTORY_MESSAGE_CHAR_CAP || row.id.length > 128 || tools?.truncated === true,
    ...(tools ? { toolEvents: tools.items } : {}) } });
}

/** Fill the serialized page budget in candidate order; the first row always fits. */
function fillPage(
  { candidates, project }: { candidates: readonly HistoryRow[]; project: (row: HistoryRow) => HistoryMessageView }, _options = {},
): { messages: HistoryMessageView[]; truncated: boolean } {
  const messages: HistoryMessageView[] = [];
  let truncated = false;
  // Reserve result envelope/continuation space; measure serialized messages, including escapes.
  let remaining = HISTORY_TOTAL_CHAR_CAP - 512;
  for (const row of candidates) {
    const view = project(row);
    if (JSON.stringify(view).length > remaining && messages.length > 0) { truncated = true; break; }
    // Advance only over returned positions; the next page must include the omitted row.
    messages.push(view); remaining -= JSON.stringify(view).length + 1;
    if (view.truncated) truncated = true;
  }
  return { messages, truncated };
}

async function readChat(
  { ports, redact, ctx }: { ports: AssistantHistoryToolPorts; redact: RedactUserText; ctx: ToolExecutionContext }, _options = {},
) {
  const { chatId, limit, fromPosition, includeToolEvents } = readInput({ input: ctx.input });
  const { store, history } = await openHistory({ ports, principalId: ctx.principal.id });
  if (!await store.get({ id: chatId }, {})) throw new ToolInputError({ message: 'Chat is unavailable to this caller. Choose an id from assistant_chats_list.' });
  const tail = fromPosition === undefined;
  const page = await history.read({ chatId }, { ...(tail ? {} : { fromPosition }), limit, includeToolEvents });
  const filled = fillPage({ candidates: tail ? [...page.messages].reverse() : page.messages, project: row => projectMessage({ row, includeToolEvents, redact }) });
  return pageResult({ chatId: redact({ text: chatId }).text, tail, page, filled });
}

/** Continuation envelope: positions come only from returned rows, so no row is ever skipped. */
function pageResult(
  { chatId, tail, page, filled }: { chatId: string; tail: boolean; page: { messages: readonly HistoryRow[]; hasMore: boolean }; filled: { messages: HistoryMessageView[]; truncated: boolean } },
  _options = {},
) {
  const messages = tail ? filled.messages.reverse() : filled.messages;
  const last = messages.at(-1), first = messages.at(0);
  const more = messages.length < page.messages.length || page.hasMore;
  return { chatId, messages, truncated: page.hasMore || filled.truncated, hasMore: !tail && more,
    ...(last ? { nextPosition: last.position + 1 } : {}),
    ...(first ? { firstPosition: first.position } : {}),
    hasMoreBefore: tail && more };
}

/** Build both history registrations, using the existing catalog/risk/metadata contract.
 * @param ports Authenticated scoped-store port; denied/missing history must fail closed.
 * @param options Optional stricter redaction policy (the secret-card policy is the default).
 * @returns Read-only tool registrations. @throws ToolInputError for malformed or refused reads.
 * @complexity Bounded projections; persistence owns search cost and message ordering.
 */
export function buildAssistantHistoryRegistrations(
  { ports }: { ports: AssistantHistoryToolPorts }, { redact = redactUserText }: { redact?: RedactUserText } = {},
): ToolRegistration[] {
  return buildDomainRegistrations({ domain: 'assistant-history', catalogModule: 'chat/store/runtime/history-tools', catalog: assistantHistoryToolCatalog,
    derivedRisk: assistantHistoryDerivedRisk, metadata: assistantHistoryToolMetadata,
    handlers: {
      assistant_chats_list: ctx => listChats({ ports, redact, ctx }),
      assistant_chat_read: ctx => readChat({ ports, redact, ctx }),
    },
  });
}

import type { AgentEvent } from "../../core/index.js";
import { dedupeToolUsesById } from "../../core/tool-events.js";
import type { ExpressionBuilder } from "kysely";

import type { ChatDatabase, ChatKernel } from "./kernel.js";
import { chatKernelTables } from "../sql/boundary.js";
import { createDurableRunStore } from "./durable-run-store.js";
import type { RunIdPolicy } from "../../core/durable-runs/ports.js";

/**
 * @file The run-status half of chat history: the writes that decide how an assistant turn ENDS.
 *
 * Purpose:
 * The browser formerly competed with the finalizer to finish daemon rows. Daemon acceptance
 * and recovery now own those rows, while request-bound BYOK/AG-UI keep their browser writes.
 * For one attempt the first terminal write wins; subsequent checkpoints or settlements are
 * ignored. Continuation changes the attempt id by CAS while retaining the logical message;
 * an older attempt cannot write afterward. Terminal rows remain absorbing during recovery.
 *
 * How it stays race-free with async storage: every "is it settled?" check and the write it guards
 * run in ONE kernel transaction holding the run's lock ({@link runLockKey}), and {@link
 * ChatRunLedger.settle} takes the same lock. On SQLite that is `BEGIN IMMEDIATE` (the write lock);
 * on Postgres a transaction-scoped advisory lock, since a plain transaction does not serialize there.
 *
 * Architectural role:
 * ONE Kysely body over the chat kernel (`platform/db/chat-kernel.ts`), for every dialect. Nothing
 * here exposes history to request handlers; the cross-owner boot operation
 * ({@link ChatRunLedger.reconcileInterrupted}) supplies a recovery port with the persisted owner
 * and run stub. The recovery coordinator decides whether to reattach, continue or finalize;
 * rows it cannot adopt receive an atomic cancellation fallback rather than spinning forever.
 */

const TERMINAL_STATUSES = ["succeeded", "failed", "canceled"] as const;

export type * from "../../core/durable-runs/ledger-contracts.js";
import type { RunRef, RunProgress, ChatRunLedger } from "../../core/durable-runs/ledger-contracts.js";
import { runLockKey } from "../../core/durable-runs/run-lock.js";
export { runLockKey } from "../../core/durable-runs/run-lock.js";

function isTerminal(status: unknown): boolean {
  return typeof status === "string" && (TERMINAL_STATUSES as readonly string[]).includes(status);
}

type MessagesBuilder = ExpressionBuilder<ChatDatabase, "ai_chat_messages">;

/** `run_status` is not terminal (NULL counts as not terminal). */
const notTerminal = (eb: MessagesBuilder) =>
  eb.or([eb("run_status", "is", null), eb("run_status", "not in", TERMINAL_STATUSES)]);

/** The assistant row of exactly this run. */
const isRunRow = (eb: MessagesBuilder, run: RunRef) =>
  eb.and([
    eb("id", "=", run.messageId),
    eb("conversation_id", "=", run.conversationId),
    eb("run_id", "=", run.runId),
    eb("role", "=", "assistant"),
  ]);

function readEvents(eventsJson: string | null): AgentEvent[] {
  let events: unknown = [];
  try {
    events = eventsJson ? JSON.parse(eventsJson) : [];
  } catch {
    events = [];
  }
  return Array.isArray(events) ? (events as AgentEvent[]) : [];
}

/** Tool identity shared by progress detection and checkpoint merging; "" for non-tool events. */
function toolKey(event: AgentEvent): string {
  if (event.kind === "tool_use") return `use:${event.id}`;
  if (event.kind === "tool_result") return `result:${event.toolUseId}`;
  return "";
}

function hasNewToolProgress(current: readonly AgentEvent[], next: readonly AgentEvent[]): boolean {
  const saved = new Set(current.map(toolKey));
  return next.some((event) => { const id = toolKey(event); return id !== "" && !saved.has(id); });
}

/** Retain a longer checkpoint's text and merge non-text replay events under the shared ID rule.
 * @complexity O(b + n) time and space for b serialized bytes across n events. */
function retainSavedEvents(saved: readonly AgentEvent[], incoming: readonly AgentEvent[]): AgentEvent[] {
  const keys = new Set(saved.map((event) => JSON.stringify(event)));
  const additions = incoming.filter((event) => event.kind !== "text" && !keys.has(JSON.stringify(event)));
  return dedupeToolUsesById({ events: [...saved, ...additions] });
}

/** The saved columns a checkpoint compares against. */
interface SavedProgress { readonly content: string; readonly events_json: string | null; readonly run_status: string | null }

/**
 * The row a checkpoint writes, whether it is progress, and whether it changes anything.
 *
 * The saved `events_json` is parsed ONCE and reused by both the merge and the progress check:
 * a long turn's column is many MB, and a host checkpoints every second (memory cause 3).
 * Appending only new events instead of rewriting the column is NOT equivalent: storage coalesces
 * text deltas (the last text event grows in place) and the merge puts saved-only tool barriers
 * after the replay's events, so an existing element or the tail changes on most checkpoints.
 * @complexity O(b + n) time and space for b serialized bytes across n events; one parse, one stringify.
 */
function planCheckpoint({ current, progress }: { current: SavedProgress; progress: RunProgress }, _optional = {}) {
  const saved = readEvents(current.events_json);
  const events = keepToolCheckpoints(saved, progress.events);
  const eventsJson = JSON.stringify(events);
  // A checkpoint is the run producing output, so an accepted (`queued`) row is now `running`;
  // nothing else moves it there, and a streaming answer must not read as still waiting.
  const runStatus = current.run_status === "queued" ? "running" : current.run_status;
  return {
    eventsJson,
    runStatus,
    grown: progress.content.length > current.content.length || hasNewToolProgress(saved, events),
    unchanged: runStatus === current.run_status && progress.content === current.content && eventsJson === current.events_json,
  };
}

/** Preserve tool barriers absent from a replay, with one persisted use per tool ID.
 * @complexity O(n) time and space in the combined saved and incoming event count. */
function keepToolCheckpoints(saved: readonly AgentEvent[], incoming: readonly AgentEvent[]): AgentEvent[] {
  const seen = new Set(incoming.map(toolKey));
  // Deduplicate after merging: a legacy checkpoint or replay can repeat an ID with different
  // serialized input. The shared ID rule owns identity; JSON equality does not.
  return dedupeToolUsesById({ events: [...incoming, ...saved.filter((event) => { const id = toolKey(event); return id !== "" && !seen.has(id); })] });
}

/**
 * @param store the chat kernel, or the open `chat.db` handle `createChatStoreFactory` also wraps.
 * @param now Injectable epoch-millisecond clock for progress stamps and the default cancel time.
 * @complexity each method is one or two indexed statements, except `reconcileInterrupted`, which
 *   is O(stuck rows).
 */
export function createChatRunLedger<DB extends ChatDatabase>(
  { kernel: hostKernel, isDaemonRunId }: { kernel: ChatKernel<DB>; isDaemonRunId: RunIdPolicy },
  { now = () => Date.now() }: { now?: () => number } = {},
): ChatRunLedger {
  const kernel = chatKernelTables<DB, ChatDatabase>({ kernel: hostKernel }, {});

  async function isSettled(run: RunRef): Promise<boolean> {
    const row = await kernel.run((db) =>
      db
        .selectFrom("ai_chat_messages")
        .select("run_status")
        .where("id", "=", run.messageId)
        .where("conversation_id", "=", run.conversationId)
        .where("run_id", "=", run.runId)
        .executeTakeFirst()
    );
    return isTerminal(row?.run_status);
  }

  return {
    durable: createDurableRunStore({ kernel, isDaemonRunId }, {}),
    unlessSettled({ run, write }, _optional = {}) {
      return kernel.transaction(async () => {
        await kernel.lockKey(runLockKey(run));
        if (await isSettled(run)) return { written: false } as const;
        return { written: true, value: await write() } as const;
      });
    },

    settle(settlement, _optional = {}) {
      return kernel.transaction(async () => {
        await kernel.lockKey(runLockKey(settlement));
        const saved = await kernel.run((db) => db.selectFrom("ai_chat_messages").select(["content", "events_json"])
          .where((eb) => eb.and([isRunRow(eb, settlement), notTerminal(eb)])).executeTakeFirst());
        if (!saved) return false;
        const content = settlement.content.length >= saved.content.length ? settlement.content : saved.content;
        let events = keepToolCheckpoints(readEvents(saved.events_json), settlement.events);
        if (content !== settlement.content) {
          events = retainSavedEvents(readEvents(saved.events_json), settlement.events);
          if (!events.some((event) => event.kind === "text")) events.unshift({ kind: "text", text: saved.content });
        }
        const result = await kernel.run((db) =>
          db
            .updateTable("ai_chat_messages")
            .set({
              content,
              events_json: JSON.stringify(events),
              run_status: settlement.status,
              ended_at: settlement.endedAt,
            })
            .where((eb) => eb.and([isRunRow(eb, settlement), notTerminal(eb)]))
            .executeTakeFirst()
        );
        if (Number(result.numUpdatedRows) === 0) return false;
        await kernel.run((db) =>
          db
            .updateTable("ai_chats")
            .set({ updated_at: settlement.endedAt })
            .where("id", "=", settlement.conversationId)
            .execute()
        );
        return true;
      });
    },

    async checkpoint(progress, _optional = {}) {
      return kernel.transaction(async () => {
      await kernel.lockKey(runLockKey(progress));
      const current = await kernel.run((db) => db.selectFrom("ai_chat_messages").select(["content", "events_json", "run_status"])
        .where((eb) => eb.and([isRunRow(eb, progress), notTerminal(eb)])).executeTakeFirst());
      if (!current || progress.content.length < current.content.length) return false;
      const { eventsJson, runStatus, grown, unchanged } = planCheckpoint({ current, progress });
      // An identical checkpoint would rewrite the same multi-MB column for nothing. Under this lock
      // the row was just matched by the update's own predicate, so the update would match (true),
      // and identical content and events are never progress (`grown` is false), so skipping it
      // leaves the row and the recovery budget exactly as the write would have.
      if (unchanged) return true;
      const result = await kernel.run((db) =>
        db
          .updateTable("ai_chat_messages")
          .set({ content: progress.content, events_json: eventsJson, run_status: runStatus })
          .where((eb) => eb.and([isRunRow(eb, progress), notTerminal(eb)]))
          .executeTakeFirst()
      );
      if (Number(result.numUpdatedRows) > 0 && grown) {
        // Progress earns a fresh recovery budget. Replayed prefixes and the coordinator's
        // divider are not progress and cannot keep a repeatedly failing attempt alive forever.
        await kernel.run((db) => db.updateTable("assistant_run_attempts")
          .set({ recovery_count: 0, recovery_deadline: null, recovery_elapsed_ms: 0, last_progress_at: now() })
          .where("message_id", "=", progress.messageId).execute());
      }
      return Number(result.numUpdatedRows) > 0;
      });
    },

    async reconcileInterrupted(required = {}, optional = {}) {
      const stuck = await kernel.run((db) =>
        db
          .selectFrom("ai_chat_messages")
          .innerJoin("ai_chats", "ai_chats.id", "ai_chat_messages.conversation_id")
          .select(["ai_chat_messages.id", "conversation_id", "run_id", "run_status", "content", "events_json", "owner_kind", "owner_id"])
          .where("ai_chat_messages.role", "=", "assistant")
          .where("ai_chat_messages.run_status", "in", ["queued", "running"])
          .orderBy("ai_chat_messages.id")
          .execute()
      );
      let count = 0;
      for (const row of stuck) {
        const dispatched = await optional.recover?.({
          principalId: row.owner_kind === "user" ? row.owner_id : null,
          conversationId: row.conversation_id,
          message: {
            id: row.id, role: "assistant", content: row.content, events: readEvents(row.events_json),
            ...(row.run_id ? { runId: row.run_id } : {}),
            runStatus: row.run_status as "queued" | "running",
          },
        });
        if (dispatched) { count += 1; continue; }
        // A legacy stub without an attempt id, or a host without durable recovery, cannot ever
        // be adopted. Preserve the latest checkpoint under the same lock as settle: discovery's
        // snapshot may be old, and acceptance/recovery may have replaced its run id meanwhile.
        const canceled = await kernel.transaction(async () => {
          await kernel.lockKey(runLockKey({ conversationId: row.conversation_id, messageId: row.id, runId: row.run_id ?? "" }));
          const matches = (eb: MessagesBuilder) => eb.and([
            eb("id", "=", row.id), eb("conversation_id", "=", row.conversation_id), eb("role", "=", "assistant"),
            row.run_id === null ? eb("run_id", "is", null) : eb("run_id", "=", row.run_id),
            notTerminal(eb),
          ]);
          const current = await kernel.run((db) => db.selectFrom("ai_chat_messages").select("events_json")
            .where(matches).executeTakeFirst());
          if (!current) return false;
          const endedAt = required.now ?? now();
          const events = [...readEvents(current.events_json), { kind: "status", label: "Stopped. Saved work is above." }];
          const result = await kernel.run((db) => db.updateTable("ai_chat_messages")
            .set({ run_status: "canceled", ended_at: endedAt, events_json: JSON.stringify(events) })
            .where(matches).executeTakeFirst());
          if (Number(result.numUpdatedRows) === 0) return false;
          await kernel.run((db) => db.updateTable("ai_chats").set({ updated_at: endedAt })
            .where("id", "=", row.conversation_id).execute());
          return true;
        });
        if (canceled) count += 1;
      }
      return count;
    },
  };
}

/** SQL boundary validation and opaque driver error translation. */
import type { StorageKernel, StorageTransport } from '@jini-ai/db/kernel';
import type { Kysely } from 'kysely';
import type { ChatDatabase } from './tables.js';
import type { ChatOwnerScope } from '../ports.js';
import { ChatStoreError } from '../errors.js';

/** Construction is validation-only: never query, migrate, reconfigure, open or close a kernel. */
export function validateKernel<DB>({ kernel, transports, dialect }: { kernel: StorageKernel<DB>; transports: readonly StorageTransport[]; dialect: 'sqlite' | 'postgres' }): void {
  if (!kernel || kernel.dialect !== dialect || !transports.includes(kernel.transport)) throw new ChatStoreError({ code: 'invalid-input' });
}

/** Copy primitive identity fields so subsequent caller mutation cannot rebind the store. */
export function copyScope({ scope }: { scope: ChatOwnerScope }): ChatOwnerScope {
  if (!scope || typeof scope.scopeId !== 'string' || !scope.scopeId || typeof scope.ownerId !== 'string' || !scope.ownerId || !['user', 'guest'].includes(scope.ownerKind)) {
    throw new ChatStoreError({ code: 'invalid-input' });
  }
  return { scopeId: scope.scopeId, ownerKind: scope.ownerKind, ownerId: scope.ownerId };
}

/** Preserve structured errors and causes; no driver details appear in public messages. */
export async function atStoreBoundary<T>({ operation }: { operation: () => Promise<T> }): Promise<T> {
  try { return await operation(); }
  catch (cause) {
    if (cause instanceof ChatStoreError) throw cause;
    throw new ChatStoreError({ code: 'unavailable' }, { cause });
  }
}

/** The single audited table-subset projection. Required table types are proven by DB's bound;
 * host extra tables and all transaction/locking effects stay on the original kernel object.
 * Kysely's invariant DB parameter requires this one erasure; it never bridges driver/version copies.
 * @returns The original kernel with only the required table types exposed.
 * @complexity O(1) time and space; no wrapper, connection or transaction is created.
 */
export function chatKernelTables<DB extends Tables, Tables extends ChatDatabase = ChatDatabase>(
  { kernel }: { kernel: StorageKernel<DB> }, _optional = {},
): StorageKernel<Tables> {
  return kernel as unknown as StorageKernel<Tables>;
}

/** Execute a transcript query through the shared table-subset projection. */
export function runChatQuery<DB extends ChatDatabase, T>({ kernel, body }: { kernel: StorageKernel<DB>; body: (db: Kysely<ChatDatabase>) => T | Promise<T> }): Promise<T> {
  return chatKernelTables<DB>({ kernel }, {}).run(body);
}

/** Versioned keyset continuations. Encoding grants no authority; all queries remain scoped. */
import type { ChatOwnerScope, ChatPageOptions } from '../ports.js';
import { ChatStoreError } from '../errors.js';

type ReadKind = 'conversations' | 'messages';
export type Anchor = readonly [number, string];

/** Reject bad limits before accessing any storage. */
export function pageLimit({ options }: { options: ChatPageOptions | undefined }): number {
  const limit = options?.limit === undefined ? 50 : options.limit;
  if (!Number.isInteger(limit) || limit < 1 || limit > 200) throw new ChatStoreError({ code: 'invalid-input' });
  return limit;
}

/** Scope binding uses the host's already-hashed guest ID, never a bearer token. */
function ownerTuple(scope: ChatOwnerScope): readonly string[] {
  return [scope.scopeId, scope.ownerKind, scope.ownerId];
}

/** UTF-8/base64url preserves arbitrary opaque IDs; cursors represent live views, not snapshots. */
export function encodeCursor({ kind, scope, conversation, anchor }: { kind: ReadKind; scope: ChatOwnerScope; conversation: string | null; anchor: Anchor }): string {
  const bytes = new TextEncoder().encode(JSON.stringify([1, kind, ownerTuple(scope), conversation, anchor]));
  const binary = Array.from(bytes, byte => String.fromCharCode(byte)).join('');
  return btoa(binary).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
}

/** Every structural failure is the same refusal; callers never learn which check rejected it. */
function invalidCursor(): never {
  throw new ChatStoreError({ code: 'invalid-cursor' });
}

/** Shape check before decoding: a non-empty, bounded base64url string. Carries no cause. */
function assertCursorText({ cursor }: { cursor: string }): void {
  if (typeof cursor !== 'string' || cursor.length === 0 || cursor.length > 8192 || !/^[A-Za-z0-9_-]+$/.test(cursor)) invalidCursor();
}

/** base64url -> strict UTF-8 -> JSON; any decode failure is wrapped with its cause attached. */
function decodeBody({ cursor }: { cursor: string }): unknown {
  try {
    const binary = atob(cursor.replaceAll('-', '+').replaceAll('_', '/'));
    const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
    return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
  }
  catch (cause) { throw new ChatStoreError({ code: 'invalid-cursor' }, { cause }); }
}

/** Version, exact length, read kind and conversation binding. */
function readEnvelope({ value, kind, conversation }: { value: unknown; kind: ReadKind; conversation: string | null }): unknown[] {
  if (!Array.isArray(value) || value.length !== 5 || value[0] !== 1 || value[1] !== kind || value[3] !== conversation) invalidCursor();
  return value;
}

/** The cursor must carry exactly this scope's owner tuple. */
function assertOwner({ owner, scope }: { owner: unknown; scope: ChatOwnerScope }): void {
  const expected = ownerTuple(scope);
  if (!Array.isArray(owner) || owner.length !== 3 || owner.some((part, i) => part !== expected[i])) invalidCursor();
}

/** A [finite number, string] pair; message positions must also be non-negative safe integers. */
function readAnchor({ anchor, kind }: { anchor: unknown; kind: ReadKind }): Anchor {
  if (!Array.isArray(anchor) || anchor.length !== 2 || typeof anchor[0] !== 'number' || !Number.isFinite(anchor[0]) || typeof anchor[1] !== 'string') {
    invalidCursor();
  }
  if (kind === 'messages' && (!Number.isSafeInteger(anchor[0]) || anchor[0] < 0)) invalidCursor();
  return [anchor[0], anchor[1]];
}

/** Validate version, exact structure, scope and read bindings before a query can run. */
export function decodeCursor({ cursor, kind, scope, conversation }: { cursor: string | undefined; kind: ReadKind; scope: ChatOwnerScope; conversation: string | null }): Anchor | undefined {
  if (cursor === undefined) return undefined;
  assertCursorText({ cursor });
  const envelope = readEnvelope({ value: decodeBody({ cursor }), kind, conversation });
  assertOwner({ owner: envelope[2], scope });
  return readAnchor({ anchor: envelope[4], kind });
}

/** One SQL query body upstreamed from the existing host adapter; no resource/schema ownership. */
// Legacy project/conversation CRUD trusts access to a local database file; this owner-bound store
// serves shared databases instead. Choose by trust model: borrowing a handle must not grant access
// to every tenant, and this adapter neither chooses that handle's file nor owns its lifetime.
/**
 * Every read/write uses the authenticated (scope_id, owner_kind, owner_id) tuple; store construction
 * must not turn a shared database into access to other owners' conversations. Append reads and
 * assigns position in one transaction under the conversation lock: PostgreSQL READ COMMITTED alone
 * cannot serialize two appends as SQLite BEGIN IMMEDIATE does. The unique conversation/position
 * constraint remains the backstop, and nested appends join the host's existing transaction.
 */
import { sql, type Kysely } from 'kysely';
import { createSystemClock, type Clock } from '@jini-ai/core/primitives';
import { isUniqueViolation, type StorageKernel } from '@jini-ai/db/kernel';
import { redactUserMessage, type UserTextRedactionOptions } from '../../core/user-text-redaction.js';
import type { ChatMessage } from '../../core/messages.js';
import { MID_RUN_USER_MESSAGE_EVENT_NAME } from '../../core/turn-usage.js';
import type { ChatConversation, ChatStore, ChatOwnerScope, ChatTitleSource, CreateChatConversationInput, ChatPageOptions, ChatMessagePageInput } from '../ports.js';
import type { ChatDatabase } from './tables.js';
import { ChatStoreError } from '../errors.js';
import { copyScope, atStoreBoundary, runChatQuery } from './boundary.js';
import { pageLimit, decodeCursor, encodeCursor } from './cursor.js';

/** UTF-8 byte ordinal ordering, identical on SQLite BINARY and PostgreSQL C collation. */
function ordinalId(dialect: 'sqlite' | 'postgres', column: 'c.id' | 'm.id') {
  return dialect === 'sqlite' ? sql<string>`${sql.ref(column)} collate BINARY` : sql<string>`${sql.ref(column)} collate "C"`;
}

/** The lock every position-assigning append to one conversation takes. */
function conversationLockKey(conversationId: string): string {
  return `chat-conversation:${conversationId}`;
}

interface ConversationRow {
  id: string;
  title: string | null;
  title_source: string;
  created_at: number;
  updated_at: number;
  expires_at: number | null;
  message_count: number | string | bigint | null;
}

interface MessageRow {
  id: string;
  role: string;
  content: string;
  agent_id: string | null;
  agent_name: string | null;
  events_json: string | null;
  attachments_json: string | null;
  run_id: string | null;
  run_status: string | null;
  created_at: number;
  started_at: number | null;
  ended_at: number | null;
}

function toConversation(row: ConversationRow): ChatConversation {
  return {
    id: row.id,
    title: row.title,
    titleSource: row.title_source as ChatTitleSource,
    // COUNT(*) never yields null; Number() also maps a driver's string/bigint count.
    messageCount: Number(row.message_count),
    createdAt: Number(row.created_at),
    updatedAt: Number(row.updated_at),
    ...(row.expires_at === null ? {} : { expiresAt: Number(row.expires_at) }),
  };
}

/**
 * A malformed JSON column yields `undefined` rather than throwing: one half-written `events_json`
 * must not make the whole conversation unreadable (same rule as Jini's store).
 */
function safeParse(value: string): any {
  try {
    return JSON.parse(value);
  } catch {
    return undefined;
  }
}

/** A NULL (or empty) JSON column is absent; anything else goes through {@link safeParse}. */
function parseJsonColumn(value: string | null): any {
  return value ? safeParse(value) : undefined;
}

/** Project only existing ai_* fields: resumable and lastRunEventId belong to run state. */
// Both fields disappear on a transcript round trip today. Adding columns alone would let the
// browser persist claims about a run it does not own. First associate the run with its conversation
// and let the daemon persist authoritative stream/terminal state, then extend storage for it.
// The legacy messages store does retain last_run_event_id; that is a separate trust model, not
// evidence that this projection preserves it. A schema extension also needs host-owned follow-up
// migrations, because changing the DDL constant cannot update databases already migrated.
export function toMessage(row: MessageRow): ChatMessage {
  return {
    id: row.id, role: row.role as ChatMessage['role'], content: row.content,
    ...agentFields(row),
    ...jsonFields(row),
    ...runFields(row),
    createdAt: Number(row.created_at),
    ...(row.started_at === null ? {} : { startedAt: Number(row.started_at) }),
    ...(row.ended_at === null ? {} : { endedAt: Number(row.ended_at) }),
  };
}

/** Empty agent columns are omitted, not projected as empty strings. */
function agentFields(row: MessageRow): Pick<ChatMessage, 'agentId' | 'agentName'> {
  return {
    ...(row.agent_id ? { agentId: row.agent_id } : {}),
    ...(row.agent_name ? { agentName: row.agent_name } : {}),
  };
}

/** Unparseable or absent JSON columns are omitted rather than failing the read. */
function jsonFields(row: MessageRow): Pick<ChatMessage, 'events' | 'attachments'> {
  const events = parseJsonColumn(row.events_json);
  const attachments = parseJsonColumn(row.attachments_json);
  return {
    ...(events === undefined ? {} : { events }),
    ...(attachments === undefined ? {} : { attachments }),
  };
}

/** Empty run columns are omitted. */
function runFields(row: MessageRow): Pick<ChatMessage, 'runId' | 'runStatus'> {
  return {
    ...(row.run_id ? { runId: row.run_id } : {}),
    ...(row.run_status ? { runStatus: row.run_status as NonNullable<ChatMessage['runStatus']> } : {}),
  };
}

/** The bounded history reader's projection: no attachment, agent or run column is selected. */
interface HistoryRow {
  id: string;
  role: string;
  content: string;
  position: number;
  created_at: number;
  events_json: string | null;
}

/** Reject an unbounded or malformed history read before any query runs. */
function assertHistoryReadBounds({ limit, fromPosition }: { limit: number; fromPosition: number | undefined }): void {
  if (!Number.isInteger(limit) || limit < 1 || limit > 100 || (fromPosition !== undefined && (!Number.isSafeInteger(fromPosition) || fromPosition < 0))) {
    throw new ChatStoreError({ code: 'invalid-input' });
  }
}

/** Project one history row; `events` is present (possibly undefined) only when tool events were asked for. */
function toHistoryMessage(row: HistoryRow, { includeToolEvents }: { includeToolEvents: boolean }) {
  return { id: row.id, role: row.role as ChatMessage['role'], content: row.content,
    position: Number(row.position), createdAt: Number(row.created_at),
    ...(includeToolEvents ? { events: parseJsonColumn(row.events_json) } : {}),
  };
}

/**
 * Returns a {@link ChatHistoryStore} that can only ever see `scope`'s own conversations.
 *
 * @param kernel the borrowed kernel. Nothing here opens, closes or configures a database; SQLite's
 *   `ON DELETE CASCADE` needs `foreign_keys = ON`, which the host must enable.
 * @param scope the isolation predicate, resolved from the host's authentication. For a guest,
 *   `ownerId` must already be a hash of the session key (`tenant-scope.ts`).
 * @param optional Optional core Clock for deterministic host/tests; defaults to system wall time.
 * @complexity each method is one to four indexed statements; conversation summaries scan their
 *   messages and embedded events in SQL; `messages` is O(messages in the conversation).
 */
export function createSqlChatStore<DB extends ChatDatabase>(
  { kernel, scope: inputScope }: { kernel: StorageKernel<DB>; scope: ChatOwnerScope },
  { clock = createSystemClock(), ...redactionOptions }: { clock?: Clock } & UserTextRedactionOptions = {},
): ChatStore {
  const scope = copyScope({ scope: inputScope });
  const { scopeId, ownerKind, ownerId } = scope;
  // The single subset boundary: DB must contain both required table definitions. Extra host tables
  // stay on the exact borrowed kernel; its transaction context is never projected or recreated.
  const run = <T>(body: (db: Kysely<ChatDatabase>) => T | Promise<T>): Promise<T> =>
    runChatQuery({ kernel: kernel, body: body });

  // Count embedded user messages in SQL: list/get still return summaries, never whole transcripts.
  // Writers store `JSON.stringify` output (no whitespace, as appendedEventsJson also relies on), so
  // each mid-run event holds this exact text once; text inside a JSON string has escaped quotes and
  // cannot match, and invalid JSON stays readable (it counts what it holds, never throws). Plain
  // length/replace run on SQLite and PostgreSQL 14+, unlike `IS JSON` (PostgreSQL 16+).
  const needle = `"name":"${MID_RUN_USER_MESSAGE_EVENT_NAME}"`;
  const midRunCount = sql<number>`((length(coalesce(m.events_json, '')) - length(replace(coalesce(m.events_json, ''), ${sql.lit(needle)}, ''))) / ${sql.lit(needle.length)})`;

  /** This scope's conversations, projected as {@link ConversationRow}s with their message count. */
  function ownedConversations(db: Kysely<ChatDatabase>) {
    return db
      .selectFrom("ai_chats as c")
      .select((eb) => [
        "c.id",
        "c.title",
        "c.title_source",
        "c.created_at",
        "c.updated_at",
        "c.expires_at",
        eb
          .selectFrom("ai_chat_messages as m")
          .select(sql<number>`coalesce(sum(1 + case when m.role = 'assistant' then ${midRunCount} else 0 end), 0)`.as("n"))
          .whereRef("m.conversation_id", "=", "c.id")
          .as("message_count"),
      ])
      .where("c.scope_id", "=", scopeId)
      .where("c.owner_kind", "=", ownerKind)
      .where("c.owner_id", "=", ownerId);
  }

  /** One owner-filtered indexed lookup; missing and foreign IDs both return null. */
  async function get({ id }: { readonly id: string }, _optional: Record<string, never> = {}): Promise<ChatConversation | null> {
    const row = await run((db) => ownedConversations(db).where("c.id", "=", id).executeTakeFirst());
    return row ? toConversation(row as ConversationRow) : null;
  }

  /** One scoped projection for all message reads, including the row returned by an upsert. */
  function ownedMessages(db: Kysely<ChatDatabase>, conversationId: string) {
    return db
        .selectFrom("ai_chat_messages as m")
        .innerJoin("ai_chats as c", "c.id", "m.conversation_id")
        .select([
          "m.id",
          "m.role",
          "m.content",
          "m.agent_id",
          "m.agent_name",
          "m.events_json",
          "m.attachments_json",
          "m.run_id",
          "m.run_status",
          "m.created_at",
          "m.started_at",
          "m.ended_at",
        ])
        .where("m.conversation_id", "=", conversationId)
        .where("c.scope_id", "=", scopeId)
        .where("c.owner_kind", "=", ownerKind)
        .where("c.owner_id", "=", ownerId);
  }

  /** Read owned messages in persisted position order; foreign IDs produce no rows. */
  async function messages({ conversationId }: ChatMessagePageInput, _optional: Record<string, never> = {}): Promise<ChatMessage[]> {
    const rows = await run(db => ownedMessages(db, conversationId).orderBy('m.position').execute());
    return rows.map(toMessage);
  }

  /** Writes and projects one message inside the borrowed transaction; null for absent/foreign IDs. */
  function writeMessage(conversationId: string, m: ChatMessage): Promise<ChatMessage | null> {
    return kernel.transaction(async () => {
      await kernel.lockKey(conversationLockKey(conversationId));
      const owned = await run((db) =>
        db
          .selectFrom("ai_chats")
          .select("id")
          .where("id", "=", conversationId)
          .where("scope_id", "=", scopeId)
          .where("owner_kind", "=", ownerKind)
          .where("owner_id", "=", ownerId)
          .executeTakeFirst()
      );
      if (!owned) return null;

      const existing = await run((db) =>
        db
          .selectFrom("ai_chat_messages")
          .select("position")
          .where("id", "=", m.id)
          .where("conversation_id", "=", conversationId)
          .executeTakeFirst()
      );
      const position = existing ? Number(existing.position) : await nextPosition(conversationId);

      // The conflict target is `id`, the GLOBAL key: the `where` keeps an id that already lives in
      // another conversation from updating THAT row (the contract's "colliding id to its OWN chat" case).
      await run((db) =>
        db
          .insertInto("ai_chat_messages")
          .values({
            id: m.id,
            conversation_id: conversationId,
            role: m.role,
            content: m.content,
            agent_id: m.agentId ?? null,
            agent_name: m.agentName ?? null,
            events_json: m.events ? JSON.stringify(m.events) : null,
            attachments_json: m.attachments ? JSON.stringify(m.attachments) : null,
            run_id: m.runId ?? null,
            run_status: m.runStatus ?? null,
            position,
            created_at: m.createdAt ?? clock.nowMs(),
            started_at: m.startedAt ?? null,
            ended_at: m.endedAt ?? null,
          })
          .onConflict((oc) =>
            oc
              .column("id")
              .doUpdateSet((eb) => ({
                content: eb.ref("excluded.content"),
                events_json: eb.ref("excluded.events_json"),
                attachments_json: eb.ref("excluded.attachments_json"),
                run_id: eb.ref("excluded.run_id"),
                run_status: eb.ref("excluded.run_status"),
                started_at: eb.ref("excluded.started_at"),
                ended_at: eb.ref("excluded.ended_at"),
              }))
              .where((eb) => eb("ai_chat_messages.conversation_id", "=", eb.ref("excluded.conversation_id")))
          )
          .execute()
      );

      // A new message is activity: the list orders by `updated_at`.
      await run((db) => db.updateTable("ai_chats").set({ updated_at: clock.nowMs() }).where("id", "=", conversationId).execute());
      // Re-read only the written row, while still in the same transaction and conversation lock.
      const saved = await run(db => ownedMessages(db, conversationId).where('m.id', '=', m.id).executeTakeFirst());
      return saved ? toMessage(saved) : null;
    });
  }

  async function nextPosition(conversationId: string): Promise<number> {
    const row = await run((db) =>
      db
        .selectFrom("ai_chat_messages")
        .select((eb) => eb.fn.max("position").as("max"))
        .where("conversation_id", "=", conversationId)
        .executeTakeFirst()
    );
    return row?.max === null || row?.max === undefined ? 0 : Number(row.max) + 1;
  }

  const store: ChatStore = {
    history: {
      /** Literal search uses two scoped projections, not a transcript fetch per conversation.
       * @complexity The database scans owned content for search; only limit rows cross the port.
       */
      async list(_required, { query, limit = 20 } = {}) {
        if (!Number.isInteger(limit) || limit < 1 || limit > 50 || (query !== undefined && (typeof query !== 'string' || query.length > 200))) {
          throw new ChatStoreError({ code: 'invalid-input' });
        }
        const rows = await run(db => {
          let statement = ownedConversations(db).select(eb => eb.selectFrom('ai_chat_messages as first')
            .select('first.content').whereRef('first.conversation_id', '=', 'c.id').where('first.role', '=', 'user')
            .orderBy('first.position').limit(1).as('first_user_line'));
          if (query?.trim()) {
            // Escape LIKE wildcards: user search is literal text, never an SQL/FTS expression.
            const pattern = '%' + query.trim().toLowerCase().replace(/[!%_]/g, char => '!' + char) + '%';
            statement = statement.where(eb => eb.or([
              sql<boolean>`lower(c.title) like ${pattern} escape '!'`,
              eb.exists(eb.selectFrom('ai_chat_messages as found').select('found.id')
                .whereRef('found.conversation_id', '=', 'c.id')
                .where(sql<boolean>`lower(found.content) like ${pattern} escape '!'`)),
            ]));
          }
          return statement.orderBy('c.updated_at', 'desc').orderBy(ordinalId(kernel.dialect, 'c.id')).limit(limit).execute();
        });
        return rows.map(row => ({ ...toConversation(row as ConversationRow), firstUserLine: row.first_user_line ?? '' }));
      },
      /** No attachment column is read. O(limit) rows; default tail is reversed into position order. */
      async read({ chatId }, { fromPosition, limit = 50, includeToolEvents = false } = {}) {
        assertHistoryReadBounds({ limit, fromPosition });
        const rows = await run(db => {
          let statement = ownedMessages(db, chatId).clearSelect().select([
            'm.id', 'm.role', 'm.content', 'm.position', 'm.created_at',
          ]);
          if (fromPosition !== undefined) statement = statement.where('m.position', '>=', fromPosition);
          return statement.select(includeToolEvents ? sql<string | null>`m.events_json`.as('events_json') : sql<null>`null`.as('events_json'))
            .orderBy('m.position', fromPosition === undefined ? 'desc' : 'asc').limit(limit + 1).execute();
        });
        const page = rows.slice(0, limit);
        if (fromPosition === undefined) page.reverse();
        return { messages: page.map(row => toHistoryMessage(row, { includeToolEvents })), hasMore: rows.length > limit };
      },
    },
    async list() {
      const rows = await run((db) => ownedConversations(db).orderBy("c.updated_at", "desc").execute());
      return rows.map((row) => toConversation(row as ConversationRow));
    },

    get,

    async create(input: CreateChatConversationInput, _optional: Record<string, never> = {}) {
      const ts = clock.nowMs();
      try {
      await run((db) =>
        db
          .insertInto("ai_chats")
          .values({
            id: input.id,
            scope_id: scopeId,
            owner_kind: ownerKind,
            owner_id: ownerId,
            title: input.title ?? null,
            title_source: input.titleSource ?? "fallback",
            created_at: ts,
            updated_at: ts,
            expires_at: input.expiresAt ?? null,
          })
          .execute()
      );
      } catch (cause) {
        if (isUniqueViolation(cause)) throw new ChatStoreError({ code: 'conflict' }, { cause });
        throw cause;
      }
      const created = await get({ id: input.id });
      // Unreachable: the insert used this exact scope. Asserted so a future change to either
      // statement fails loudly instead of returning a malformed conversation.
      if (!created) throw new Error(`ai_chats: created conversation ${input.id} was not readable in its own scope`);
      return created;
    },

    async rename({ id, title }: { readonly id: string; readonly title: string }, { source = "manual" }: { readonly source?: ChatTitleSource } = {}) {
      // A generated title never overwrites a typed one: in the WHERE clause, so a concurrent
      // rename cannot slip between a read and this write.
      await run((db) =>
        db
          .updateTable("ai_chats")
          .set({ title, title_source: source, updated_at: clock.nowMs() })
          .where("id", "=", id)
          .where("scope_id", "=", scopeId)
          .where("owner_kind", "=", ownerKind)
          .where("owner_id", "=", ownerId)
          .$if(source === "generated", (qb) => qb.where("title_source", "<>", "manual"))
          .execute()
      );
      return get({ id });
    },

    async touch({ id }: { readonly id: string }, options: { readonly expiresAt?: number } = {}) {
      const ts = clock.nowMs();
      await run((db) =>
        db
          .updateTable("ai_chats")
          .set(options?.expiresAt === undefined ? { updated_at: ts } : { updated_at: ts, expires_at: options.expiresAt })
          .where("id", "=", id)
          .where("scope_id", "=", scopeId)
          .where("owner_kind", "=", ownerKind)
          .where("owner_id", "=", ownerId)
          .execute()
      );
    },

    async delete({ id }: { readonly id: string }, _optional: Record<string, never> = {}) {
      // Messages, agent sessions and tool approvals go with it through `ON DELETE CASCADE`.
      await run((db) =>
        db
          .deleteFrom("ai_chats")
          .where("id", "=", id)
          .where("scope_id", "=", scopeId)
          .where("owner_kind", "=", ownerKind)
          .where("owner_id", "=", ownerId)
          .execute()
      );
    },

    messages,

    async appendMessage({ conversationId, message }: { readonly conversationId: string; readonly message: ChatMessage }, _optional: Record<string, never> = {}) {
      const prepared = redactUserMessage({ message }, { ...(redactionOptions.redactUserText ? { redactUserText: redactionOptions.redactUserText } : {}) });
      const saved = await writeMessage(conversationId, prepared.message);
      if (!saved || !prepared.secretRedacted) return saved;
      const signal = { secretRedacted: true as const, count: prepared.count };
      redactionOptions.onSecretRedacted?.(signal);
      return { ...saved, secretRedaction: signal };
    },

    async pageConversations(_required: Record<string, never>, options: ChatPageOptions = {}) {
      const limit = pageLimit({ options: options });
      const anchor = decodeCursor({ cursor: options?.cursor, kind: 'conversations', scope: scope, conversation: null });
      const id = ordinalId(kernel.dialect, 'c.id');
      const rows = await run(db => {
        let query = ownedConversations(db);
        if (anchor) query = query.where(eb => eb.or([
          eb('c.updated_at', '<', anchor[0]),
          eb.and([eb('c.updated_at', '=', anchor[0]), eb(id, '>', anchor[1])]),
        ]));
        return query.orderBy('c.updated_at', 'desc').orderBy(id, 'asc').limit(limit + 1).execute();
      });
      const items = rows.slice(0, limit).map(row => toConversation(row as ConversationRow));
      const last = items.at(-1);
      return { items, ...(rows.length > limit && last ? {
        nextCursor: encodeCursor({ kind: 'conversations', scope: scope, conversation: null, anchor: [last.updatedAt, last.id] }),
      } : {}) };
    },

    async pageMessages(input: ChatMessagePageInput, options: ChatPageOptions = {}) {
      const limit = pageLimit({ options: options });
      const anchor = decodeCursor({ cursor: options?.cursor, kind: 'messages', scope: scope, conversation: input.conversationId });
      const id = ordinalId(kernel.dialect, 'm.id');
      // One join, at most limit+1 rows, including the ownership check; no parent pre-read.
      const rows = await run(db => {
        let query = ownedMessages(db, input.conversationId).select('m.position');
        if (anchor) query = query.where(eb => eb.or([
          eb('m.position', '>', anchor[0]),
          eb.and([eb('m.position', '=', anchor[0]), eb(id, '>', anchor[1])]),
        ]));
        return query.orderBy('m.position', 'asc').orderBy(id, 'asc').limit(limit + 1).execute();
      });
      const page = rows.slice(0, limit), last = page.at(-1);
      return { items: page.map(toMessage), ...(rows.length > limit && last ? {
        nextCursor: encodeCursor({ kind: 'messages', scope: scope, conversation: input.conversationId, anchor: [Number(last.position), last.id] }),
      } : {}) };
    },
  };
  return {
    history: {
      list: (required, optional = {}) => atStoreBoundary({ operation: () => store.history!.list(required, optional) }),
      read: (required, optional = {}) => atStoreBoundary({ operation: () => store.history!.read(required, optional) }),
    },
    list: () => atStoreBoundary({ operation: () => store.list() }),
    get: (required, optional = {}) => atStoreBoundary({ operation: () => store.get(required, optional) }),
    create: (required, optional = {}) => atStoreBoundary({ operation: () => store.create(required, optional) }),
    rename: (required, optional = {}) => atStoreBoundary({ operation: () => store.rename(required, optional) }),
    touch: (required, optional = {}) => atStoreBoundary({ operation: () => store.touch(required, optional) }),
    delete: (required, optional = {}) => atStoreBoundary({ operation: () => store.delete(required, optional) }),
    messages: (required, optional = {}) => atStoreBoundary({ operation: () => store.messages(required, optional) }),
    appendMessage: (required, optional = {}) => atStoreBoundary({ operation: () => store.appendMessage(required, optional) }),
    pageConversations: (required, optional = {}) => atStoreBoundary({ operation: () => store.pageConversations(required, optional) }),
    pageMessages: (required, optional = {}) => atStoreBoundary({ operation: () => store.pageMessages(required, optional) }),
  };
}

/**
 * @module daemon-command
 *
 * `daemon status` / `daemon stop` — concrete commands over `@jini-ai/http-kit`'s
 * `daemonStatusRoute`/`daemonShutdownRoute` (`packages/http/src/daemon-status.ts`).
 * `packages/cli/archived provenance ledger`'s original UNCLEAR verdict on these two
 * blocked on `@jini-ai/http-kit` being a stub with no `/status`/`/shutdown` route to
 * call; that blocker no longer holds (both routes exist and are tested), and
 * `run-command.ts` is now a real, established "first concrete command"
 * precedent this file follows rather than pioneers.
 *
 * `daemon status` is a plain read (`GET`, no `requireSameOrigin`).
 * `daemon stop` posts to a `requireSameOrigin: true` route — a bare CLI
 * `fetch()` sends no `Origin` header, so `guardSameOrigin` falls through to
 * its Host-header check (`isLocalSameOrigin`'s `origin == null` branch),
 * which passes as long as the resolved daemon URL's host:port is one the
 * daemon itself considers local. No special headers are added here for
 * that — it is the same call shape `run-command.ts` already uses.
 */
import { exitWithStructuredError, type ExitCodeTable } from './errors.js';
import { getJsonFromDaemon, postJsonToDaemon } from './http.js';
import { renderUsage } from './usage.js';
import type { CommandRegistry } from './command-registry.js';

export interface DaemonCommandDeps {
  /** Resolves the daemon HTTP base URL once per command invocation (e.g. wraps `resolveDaemonUrl`). */
  resolveBaseUrl: () => Promise<string> | string;
  /** Defaults to `process.stdout.write`; inject for tests. Used for successful command output. */
  write?: (requiredArgs: { text: string }) => void;
  /** Defaults to `process.stderr.write`; inject for tests. Used for usage/validation errors. */
  writeErr?: (requiredArgs: { text: string }) => void;
  /** Defaults to the global `fetch`; inject for tests. */
  fetchImpl?: typeof fetch;
  /** Defaults to `process.exit`; inject for tests (must not return). */
  exit?: (requiredArgs: { code: number }) => never;
  /** Extra/overriding `code -> exitCode` entries layered on the package default table. */
  exitCodes?: ExitCodeTable;
}

function defaultWrite({ text }: { text: string }): void {
  process.stdout.write(text);
}

function defaultWriteErr({ text }: { text: string }): void {
  process.stderr.write(text);
}

const DAEMON_STATUS_USAGE = renderUsage({ usage: ['daemon status'] }, { description: 'Reports the running daemon\'s version/host/port/dataDir/shutdown state.' });

const DAEMON_STOP_USAGE = renderUsage({ usage: ['daemon stop'] }, { description: 'Schedules a graceful daemon shutdown. Responds once the shutdown is scheduled, not once the process has actually exited.' });

const DAEMON_USAGE = renderUsage({ usage: ['daemon <status|stop> ...'] }, { description: 'Inspect or control a running Jini daemon over HTTP.' });

/** Builds `{write, exit, exitCodes?}` for `errors.ts`'s structured-error helpers, never assigning `exitCodes` when unset (required under `exactOptionalPropertyTypes`). */
function errorOptions(deps: DaemonCommandDeps): { write: (requiredArgs: { text: string }) => void; exit: (requiredArgs: { code: number }) => never; exitCodes?: ExitCodeTable } {
  return {
    write: deps.writeErr ?? defaultWriteErr,
    exit: deps.exit ?? (({ code }: { code: number }) => process.exit(code)),
    ...(deps.exitCodes !== undefined ? { exitCodes: deps.exitCodes } : {}),
  };
}

/** Builds the transport-call options object for `postJsonToDaemon`/`getJsonFromDaemon`, only ever including a key when its value is actually set. */
function transportOptions(deps: DaemonCommandDeps): {
  fetchImpl?: typeof fetch;
  write?: (requiredArgs: { text: string }) => void;
  exit?: (requiredArgs: { code: number }) => never;
  exitCodes?: ExitCodeTable;
} {
  return {
    ...(deps.fetchImpl !== undefined ? { fetchImpl: deps.fetchImpl } : {}),
    ...(deps.writeErr !== undefined ? { write: deps.writeErr } : {}),
    ...(deps.exit !== undefined ? { exit: deps.exit } : {}),
    ...(deps.exitCodes !== undefined ? { exitCodes: deps.exitCodes } : {}),
  };
}

function invalidFlag(deps: DaemonCommandDeps, message: string): never {
  return exitWithStructuredError({ code: 'invalid-flag', message }, errorOptions(deps));
}

function printJsonResult(deps: DaemonCommandDeps, value: unknown): void {
  (deps.write ?? defaultWrite)({ text: `${JSON.stringify(value)}\n` });
}

/** `daemon status` */
export async function daemonStatusCommand({ args, resolveBaseUrl }: { args: readonly string[]; resolveBaseUrl: DaemonCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<DaemonCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: DaemonCommandDeps = { resolveBaseUrl, ...optionalArgs };
  if (args.includes('--help') || args.includes('-h')) {
    (deps.write ?? defaultWrite)({ text: `${DAEMON_STATUS_USAGE}\n` });
    return;
  }
  const baseUrl = await deps.resolveBaseUrl();
  const result = await getJsonFromDaemon({ base: baseUrl, route: '/api/daemon/status' }, transportOptions(deps));
  printJsonResult(deps, result);
}

/** `daemon stop` */
export async function daemonStopCommand({ args, resolveBaseUrl }: { args: readonly string[]; resolveBaseUrl: DaemonCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<DaemonCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: DaemonCommandDeps = { resolveBaseUrl, ...optionalArgs };
  if (args.includes('--help') || args.includes('-h')) {
    (deps.write ?? defaultWrite)({ text: `${DAEMON_STOP_USAGE}\n` });
    return;
  }
  const baseUrl = await deps.resolveBaseUrl();
  const result = await postJsonToDaemon({ base: baseUrl, route: '/api/daemon/shutdown', body: {} }, transportOptions(deps));
  printJsonResult(deps, result);
}

/** Registers `daemon` (dispatching `status`/`stop` on the first remaining token) against `registry`. */
export function registerDaemonCommands({ registry, resolveBaseUrl }: { registry: CommandRegistry; resolveBaseUrl: DaemonCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<DaemonCommandDeps, "resolveBaseUrl"> = {}): void {
  const deps: DaemonCommandDeps = { resolveBaseUrl, ...optionalArgs };
  registry.add({ name: 'daemon', handler: async ({ args }) => {
      const [sub, ...rest] = args;
      switch (sub) {
        case 'status':
          return daemonStatusCommand({ args: rest, resolveBaseUrl: resolveBaseUrl }, optionalArgs);
        case 'stop':
          return daemonStopCommand({ args: rest, resolveBaseUrl: resolveBaseUrl }, optionalArgs);
        case undefined:
        case '--help':
        case '-h':
          (deps.write ?? defaultWrite)({ text: `${DAEMON_USAGE}\n` });
          return;
        default:
          invalidFlag(deps, `unknown "daemon" subcommand: ${sub}`);
      }
    } }, { usage: DAEMON_USAGE });
}

/**
 * @module flags
 *
 * Generic `argv` → flags parsing, ported from OD's `apps/daemon/src/cli.ts`
 * `parseFlags`/`positionalArgs`/`collectCliPositionals` (see `archived provenance ledger`).
 * Zero product nouns: callers declare which `--flag` names take a string
 * value vs. are booleans, and get back a flat map plus the leftover
 * positional tokens.
 */

/** A flag's value: `true` for a bare boolean flag, otherwise its string value. */
export type FlagValue = string | boolean;

/** The parsed `--flag`/`--flag=value` map produced by {@link parseFlags}. */
export type ParsedFlags = Record<string, FlagValue>;

export interface ParseFlagsOptions {
  /** Flag names (without leading `--`) that always consume the next token as a string value. */
  string?: ReadonlySet<string>;
  /** Flag names (without leading `--`) that never consume a value — presence alone means `true`. */
  boolean?: ReadonlySet<string>;
}

/**
 * Parse `--flag value`, `--flag=value`, and bare boolean `--flag` tokens out
 * of `argv`. Non-`--`-prefixed tokens (positionals) are silently skipped —
 * use {@link positionalArgs} to collect those.
 *
 * When either `string` or `boolean` is non-empty, an unrecognized `--flag`
 * throws (fail-fast: a hallucinated flag from an LLM-driven caller should
 * error immediately rather than silently no-op). When both are empty, every
 * `--flag` is accepted and a heuristic decides string-vs-boolean: if the
 * next token doesn't itself look like a flag, it's consumed as the value.
 */
export function parseFlags({ argv }: { argv: readonly string[] }, opts: ParseFlagsOptions = {}): ParsedFlags {
  const stringFlags = opts.string ?? new Set<string>();
  const booleanFlags = opts.boolean ?? new Set<string>();
  const knownFlags = new Set<string>([...stringFlags, ...booleanFlags]);
  const out: ParsedFlags = {};

  for (let i = 0; i < argv.length; i++) {
    // Loop is bounded by argv.length, so this index is always in range —
    // noUncheckedIndexedAccess types it as possibly-undefined regardless.
    const a = argv[i]!;
    if (!a.startsWith('--')) continue;

    const { key, inlineValue } = splitFlagToken({ token: a });
    if (knownFlags.size > 0 && !knownFlags.has(key)) {
      throw new Error(`unknown flag: --${key}. Run with --help for the list of accepted flags.`);
    }
    const { value, consumesNext } = resolveFlagValue({ key, inlineValue, next: argv[i + 1] }, { stringFlags, booleanFlags });
    out[key] = value;
    if (consumesNext) i++;
  }
  return out;
}

/** Split a `--key` / `--key=value` token; `inlineValue` is everything after the first `=`, if any. */
function splitFlagToken({ token }: { token: string }): { key: string; inlineValue: string | undefined } {
  const eq = token.indexOf('=');
  return eq >= 0 ? { key: token.slice(2, eq), inlineValue: token.slice(eq + 1) } : { key: token.slice(2), inlineValue: undefined };
}

/**
 * Decide one flag's value, in precedence order: an inline `=value`, then a declared boolean
 * (`true`), then a declared string flag (always takes `next`, which must exist), then the
 * undeclared heuristic (`next` when it does not itself start with `--`, else `true`).
 */
function resolveFlagValue(
  { key, inlineValue, next }: { key: string; inlineValue: string | undefined; next: string | undefined },
  { stringFlags, booleanFlags }: { stringFlags: ReadonlySet<string>; booleanFlags: ReadonlySet<string> },
): { value: FlagValue; consumesNext: boolean } {
  if (inlineValue !== undefined) return { value: inlineValue, consumesNext: false };
  if (booleanFlags.has(key)) return { value: true, consumesNext: false };
  if (stringFlags.has(key)) {
    if (next === undefined) throw new Error(`flag --${key} requires a value`);
    return { value: next, consumesNext: true };
  }
  if (next !== undefined && !next.startsWith('--')) return { value: next, consumesNext: true };
  return { value: true, consumesNext: false };
}

export interface PositionalArgsOptions {
  /** String-valued flag names whose value token must be skipped, not collected as a positional. */
  string?: ReadonlySet<string>;
  /**
   * When `true`, a bare `--` token stops flag-skipping and every remaining
   * token (including ones that look like `--flags`) is collected verbatim.
   * Mirrors the shell `--` convention (`collectCliPositionals` in the OD
   * source). Defaults to `false`.
   */
  stopAtDoubleDash?: boolean;
}

/**
 * Collect every non-flag token from `argv`, skipping the value token that
 * follows a known string flag (so `od run start --project p1 foo` yields
 * `['foo']`, not `['p1', 'foo']`).
 */
export function positionalArgs({ argv }: { argv: readonly string[] }, opts: PositionalArgsOptions = {}): string[] {
  const stringFlags = opts.string ?? new Set<string>();
  const stopAtDoubleDash = opts.stopAtDoubleDash === true;
  const out: string[] = [];

  for (let i = 0; i < argv.length; i++) {
    // Loop is bounded by argv.length, so this index is always in range —
    // noUncheckedIndexedAccess types it as possibly-undefined regardless.
    const a = argv[i]!;
    if (stopAtDoubleDash && a === '--') {
      out.push(...argv.slice(i + 1));
      break;
    }
    if (!a.startsWith('--')) {
      out.push(a);
      continue;
    }
    const { key, inlineValue } = splitFlagToken({ token: a });
    if (inlineValue === undefined && stringFlags.has(key)) i++;
  }
  return out;
}

/** The native type {@link coerceCliValue} can produce from a raw string flag value. */
export type CoercedCliValue = boolean | number | string;

const NUMERIC_LITERAL_RE = /^-?\d+(\.\d+)?$/;

/**
 * Coerce a raw `--flag <value>` string into its likely native type:
 * `'true'`/`'false'` become booleans, a numeric-looking string becomes a
 * `number`, and anything else passes through unchanged. Ported from OD's
 * `cli.ts` `coerceCliValue` (see `archived provenance ledger`) — used wherever a CLI
 * accepts an untyped string flag value that application code should receive
 * as its natural type (e.g. a config `set` command, or a plugin's dynamic
 * `--input` flags forwarded as a JSON-typed payload).
 */
export function coerceCliValue({ raw }: { raw: string }): CoercedCliValue {
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  if (NUMERIC_LITERAL_RE.test(raw)) return Number(raw);
  return raw;
}

/**
 * @module http
 *
 * HTTP-client-mode transport plumbing, ported from OD's
 * `apps/daemon/src/cli.ts` `surfaceFetchError`/`postJsonToDaemon` (see
 * `archived provenance ledger`). This is the "HTTP-client mode default" half of
 * extraction-plan §3's `@jini-ai/cli` spec: fetch a daemon route, translate a
 * network failure or a daemon error envelope into the structured exit-code
 * contract from `errors.ts`.
 */

import { DEFAULT_CLI_EXIT_CODES, exitWithStructuredError, structuredErrorData, type ExitCodeTable } from './errors.js';
import { sanitizeDaemonUrlForDisplay } from './daemon-url.js';
import { sanitizeUntrustedText } from '@jini-ai/core/text';

export interface SurfaceFetchErrorOptions {
  /** Defaults to `process.stderr.write`; inject for tests. */
  write?: (requiredArgs: { text: string }) => void;
}

function writeToStderr({ text }: { text: string }): void {
  process.stderr.write(text);
}

function exitProcess({ code }: { code: number }): never {
  return process.exit(code);
}

/** `err.message` for an `Error`, `String(err)` for anything else. */
function errorText(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

/** `value[key]` when `value` is an object whose `key` field is a string; `null` otherwise. */
function stringField(value: unknown, key: 'code' | 'message'): string | null {
  if (value === null || typeof value !== 'object') return null;
  const field = (value as Record<string, unknown>)[key];
  return typeof field === 'string' ? field : null;
}

/** `cause.code` (with `cause.message` when present), else `cause.message`, else the error's own text. */
function describeFetchFailure(err: unknown): { code: string | null; detail: string } {
  const cause = err !== null && typeof err === 'object' ? (err as { cause?: unknown }).cause : null;
  const code = stringField(cause, 'code');
  const causeMessage = stringField(cause, 'message') ?? '';
  // Stringified up front, before the cause-based choice below, exactly as the original did — so a
  // value whose String() throws still throws even when a cause code is present.
  const ownText = errorText(err);
  if (code !== null) return { code, detail: causeMessage.length > 0 ? `${code} — ${causeMessage}` : code };
  return { code, detail: causeMessage.length > 0 ? causeMessage : ownText };
}

/** Cause codes that indicate an outbound connect denied by a sandbox policy rather than a down daemon. */
const SANDBOX_DENIAL_CODES: ReadonlySet<string> = new Set(['EPERM', 'ENETUNREACH']);

/**
 * Format a `fetch()` rejection (network-unreachable, sandbox-denied) into a
 * human-readable stderr line, with a hint when the underlying cause looks
 * like a sandboxed-environment outbound-connect denial. Per CR-004/SEC-RB-009,
 * `daemonUrl` and the failure detail are both sanitized before they reach
 * stderr — a `daemonUrl` with embedded userinfo, or a cause message that
 * embeds terminal control sequences or a leaked credential, must not be
 * printed verbatim.
 */
export function surfaceFetchError({ err, daemonUrl }: { err: unknown; daemonUrl: string }, options: SurfaceFetchErrorOptions = {}): void {
  const write = options.write ?? writeToStderr;
  const { code, detail } = describeFetchFailure(err);
  write({ text: `failed to reach daemon at ${sanitizeDaemonUrlForDisplay({ url: daemonUrl })}: ${sanitizeUntrustedText({ text: detail })}\n` });
  if (code !== null && SANDBOX_DENIAL_CODES.has(code)) {
    write({ text:
      'hint: outbound connect was denied, likely by a sandbox policy. ' +
        'If this command ran inside an agent sandbox, check its network policy — ' +
        'the daemon itself is unaffected and can be reached from a regular shell.\n',
    });
  }
}

interface DaemonJsonErrorBody {
  error?: { code?: unknown; message?: unknown; data?: unknown };
}

/** Default request deadline. Generous enough for a slow agent run kickoff, short enough that a stalled daemon doesn't hang a CLI invocation forever. */
const DEFAULT_TIMEOUT_MS = 15_000;
/** Default cap on a daemon response body. Comfortably larger than any real status/error envelope, small enough to bound worst-case memory from a hostile/broken daemon. */
const DEFAULT_MAX_RESPONSE_BYTES = 10 * 1024 * 1024;

/** Thrown internally by {@link readJsonWithLimit} when a response exceeds its byte cap; never escapes {@link postJsonToDaemon}. */
class ResponseTooLargeError extends Error {
  constructor(public readonly limitBytes: number) {
    super(`response exceeded the ${limitBytes}-byte limit`);
    this.name = 'ResponseTooLargeError';
  }
}

/** Rejects up front when `resp` declares a numeric `content-length` above `maxBytes`; a missing or non-numeric header is left to the byte-counting read. */
function assertDeclaredLengthWithin(resp: Response, maxBytes: number): void {
  const contentLength = resp.headers?.get?.('content-length');
  if (contentLength === null || contentLength === undefined) return;
  const declared = Number(contentLength);
  if (Number.isFinite(declared) && declared > maxBytes) throw new ResponseTooLargeError(maxBytes);
}

/** Drains `body` as UTF-8 text, throwing {@link ResponseTooLargeError} as soon as the running byte count passes `maxBytes`. */
async function readStreamText(body: ReadableStream<Uint8Array>, maxBytes: number): Promise<string> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let text = '';
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done === true) break;
      if (value === undefined) continue;
      total += value.byteLength;
      if (total > maxBytes) throw new ResponseTooLargeError(maxBytes);
      text += decoder.decode(value, { stream: true });
    }
    return text + decoder.decode();
  } finally {
    reader.releaseLock();
  }
}

/** `resp.text()`, byte-checked against `maxBytes` before it is parsed. */
async function readTextWithin(resp: Response, maxBytes: number): Promise<string> {
  const text = await resp.text();
  if (Buffer.byteLength(text, 'utf8') > maxBytes) throw new ResponseTooLargeError(maxBytes);
  return text;
}

/** Parses `text` as JSON; an empty or non-JSON body resolves to `{}`. */
function parseJsonOrEmpty(text: string): unknown {
  if (text.length === 0) return {};
  try {
    return JSON.parse(text);
  } catch {
    return {};
  }
}

/**
 * Read `resp`'s body as JSON without ever buffering past `maxBytes`. Prefers streaming via
 * `resp.body`'s reader (what a real `fetch()` `Response` provides) so a huge response is
 * rejected mid-stream instead of first being buffered whole; falls back to `resp.text()` (still
 * byte-checked before parsing) and finally to `resp.json()` for response-like objects that
 * implement neither — the shape test doubles in this package's own suite use. A body that isn't
 * valid JSON resolves to `{}`, matching this module's previous behavior.
 */
async function readJsonWithLimit(resp: Response, maxBytes: number): Promise<unknown> {
  assertDeclaredLengthWithin(resp, maxBytes);
  const body = resp.body;
  if (body != null && typeof body.getReader === 'function') return parseJsonOrEmpty(await readStreamText(body, maxBytes));
  if (typeof (resp as { text?: unknown }).text === 'function') return parseJsonOrEmpty(await readTextWithin(resp, maxBytes));
  return await resp.json().catch(() => ({}));
}

export interface PostJsonToDaemonOptions {
  headers?: Record<string, string>;
  exitCodes?: ExitCodeTable;
  /** Defaults to the global `fetch`; inject for tests. */
  fetchImpl?: typeof fetch;
  /** Defaults to `process.stderr.write`; inject for every structured failure path. */
  write?: (requiredArgs: { text: string }) => void;
  /** Defaults to `process.exit`; inject for every structured failure path (must not return). */
  exit?: (requiredArgs: { code: number }) => never;
  /** Caller-supplied cancellation signal; combined with the internal timeout signal, so either one aborts the request. */
  signal?: AbortSignal;
  /** Request deadline in ms. Defaults to {@link DEFAULT_TIMEOUT_MS}. */
  timeoutMs?: number;
  /** Maximum daemon response size in bytes before the read is aborted. Defaults to {@link DEFAULT_MAX_RESPONSE_BYTES}. */
  maxResponseBytes?: number;
}

/** `GET`'s options are identical to {@link PostJsonToDaemonOptions} minus the (POST-only) request body. */
export type GetJsonFromDaemonOptions = PostJsonToDaemonOptions;

interface RequestInit_ {
  readonly method: 'GET' | 'POST';
  readonly body?: unknown;
}

/** The `{write, exit, exitCodes?}` options every structured exit in this module shares. */
interface StructuredExitOptions {
  readonly write: (requiredArgs: { text: string }) => void;
  readonly exit: (requiredArgs: { code: number }) => never;
  readonly exitCodes?: ExitCodeTable;
}

function structuredExitOptions(options: PostJsonToDaemonOptions): StructuredExitOptions {
  return {
    write: options.write ?? writeToStderr,
    exit: options.exit ?? exitProcess,
    ...(options.exitCodes !== undefined ? { exitCodes: options.exitCodes } : {}),
  };
}

interface Deadline {
  readonly controller: AbortController;
  /** The deadline's own signal, combined with the caller's when one was given. */
  readonly signal: AbortSignal;
  readonly clear: () => void;
}

/** Arms the request deadline: aborts `controller` with a route-naming error after `timeoutMs`. */
function startDeadline({ route, timeoutMs }: { route: string; timeoutMs: number }, { signal }: { signal?: AbortSignal | undefined }): Deadline {
  const controller = new AbortController();
  const handle = setTimeout(() => {
    controller.abort(new Error(`request to ${route} timed out after ${timeoutMs}ms`));
  }, timeoutMs);
  // A short-lived CLI invocation shouldn't be kept alive purely by this timer.
  (handle as unknown as { unref?: () => void }).unref?.();
  return {
    controller,
    signal: signal !== undefined ? AbortSignal.any([signal, controller.signal]) : controller.signal,
    clear: () => { clearTimeout(handle); },
  };
}

/** POST adds a JSON content-type (a caller header of the same name still wins) and the serialized body; GET sends only the caller headers. */
function buildFetchInit(init: RequestInit_, headers: Record<string, string> | undefined, signal: AbortSignal): RequestInit {
  if (init.method === 'POST') {
    return { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: JSON.stringify(init.body), signal };
  }
  return { method: 'GET', headers: { ...headers }, signal };
}

/** A rejected `fetch()` (or a request init that could not be built) exits as `daemon-not-running`, carrying {@link surfaceFetchError}'s lines as diagnostics. */
function exitForFetchFailure({ err, base }: { err: unknown; base: string }, structured: StructuredExitOptions): never {
  const diagnostics: string[] = [];
  surfaceFetchError({ err, daemonUrl: base }, { write: ({ text }) => { diagnostics.push(text.trimEnd()); } });
  return exitWithStructuredError({ code: 'daemon-not-running', message: `Cannot reach daemon at ${sanitizeDaemonUrlForDisplay({ url: base })}` }, { data: { diagnostics }, ...structured });
}

/** A body-read failure: an oversized body aborts the in-flight request and exits `response-too-large`; anything else exits `request-failed`. */
function exitForReadFailure({ err, base, route, controller }: { err: unknown; base: string; route: string; controller: AbortController }, structured: StructuredExitOptions): never {
  if (err instanceof ResponseTooLargeError) {
    controller.abort(err);
    return exitWithStructuredError({ code: 'response-too-large', message: `response from ${sanitizeDaemonUrlForDisplay({ url: base })}${route} exceeded the ${err.limitBytes}-byte limit; aborting.` }, structured);
  }
  return exitWithStructuredError({ code: 'request-failed', message: sanitizeUntrustedText({ text: errorText(err) }) }, structured);
}

/**
 * Fetches `<base><route>` and reads its JSON body under one deadline. The timeout signal stays
 * live through both the initial fetch *and* the body read — a daemon that returns headers
 * promptly but then drips its body slowly should still be bounded by the same deadline, not
 * just the connection phase.
 */
async function fetchJsonWithinDeadline(
  { base, route, init }: { base: string; route: string; init: RequestInit_ },
  { options, structured }: { options: PostJsonToDaemonOptions; structured: StructuredExitOptions },
): Promise<{ resp: Response; data: unknown }> {
  const fetchImpl = options.fetchImpl ?? fetch;
  const maxResponseBytes = options.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES;
  const deadline = startDeadline({ route, timeoutMs: options.timeoutMs ?? DEFAULT_TIMEOUT_MS }, { signal: options.signal });
  try {
    let resp: Response;
    try {
      // The init is built inside this try on purpose: a body JSON.stringify cannot serialize is
      // reported through the same daemon-not-running path as a rejected fetch, as it always was.
      resp = await fetchImpl(`${base}${route}`, buildFetchInit(init, options.headers, deadline.signal));
    } catch (err) {
      return exitForFetchFailure({ err, base }, structured);
    }
    try {
      return { resp, data: await readJsonWithLimit(resp, maxResponseBytes) };
    } catch (err) {
      return exitForReadFailure({ err, base, route, controller: deadline.controller }, structured);
    }
  } finally {
    deadline.clear();
  }
}

/** Maps a non-2xx daemon response to a structured exit: a recognized `error.code` keeps its own exit code and sanitized message/data; anything else exits with a bounded, redacted payload excerpt. */
function exitForDaemonError(
  { resp, data, method, route }: { resp: Response; data: unknown; method: RequestInit_['method']; route: string },
  structured: StructuredExitOptions,
): never {
  const errorObj = (data as DaemonJsonErrorBody | null)?.error;
  const exitCodes: ExitCodeTable = { ...DEFAULT_CLI_EXIT_CODES, ...structured.exitCodes };
  const rawCode = errorObj?.code;
  if (typeof rawCode === 'string' && rawCode in exitCodes) {
    const rawMessage = typeof errorObj?.message === 'string' ? errorObj.message : `HTTP ${resp.status}`;
    const errorData = structuredErrorData({ error: errorObj });
    return exitWithStructuredError({ code: rawCode, message: sanitizeUntrustedText({ text: rawMessage }) }, { ...(errorData !== undefined ? { data: errorData } : {}), ...structured });
  }
  const fallbackCode = typeof rawCode === 'string' ? sanitizeUntrustedText({ text: rawCode }) : 'http-error';
  return exitWithStructuredError({ code: fallbackCode, message: `${method} ${route} failed: ${resp.status}${describeUnrecognizedDaemonPayload(data)}` }, structured);
}

/**
 * Shared transport core behind {@link postJsonToDaemon} and {@link getJsonFromDaemon}: fetch
 * `<base><route>` with a bounded timeout and response-size cap, and map a network failure or a
 * non-2xx daemon response through the structured error contract (`errors.ts`) instead of
 * returning — this function either resolves with the parsed body or never returns. Per
 * CR-004/SEC-RB-009, daemon-supplied error detail is redacted before it reaches stderr rather than
 * dumped verbatim. Both public wrappers exist only to fix `init.method`/`init.body` at their own
 * call site — nothing method-specific lives here beyond that.
 */
async function requestJsonFromDaemon(
  { base, route, init }: { base: string; route: string; init: RequestInit_ },
  options: PostJsonToDaemonOptions,
): Promise<unknown> {
  const structured = structuredExitOptions(options);
  const { resp, data } = await fetchJsonWithinDeadline({ base, route, init }, { options, structured });
  if (!resp.ok) return exitForDaemonError({ resp, data, method: init.method, route }, structured);
  return data;
}

/**
 * `POST` a JSON body to `<base><route>` and return the parsed JSON response.
 * A network failure or a non-2xx daemon response both exit via the
 * structured error contract (`errors.ts`) instead of returning — this
 * function either resolves with the parsed body or never returns.
 *
 * Per CR-004/SEC-RB-009, this now enforces a request deadline (combined with
 * an optional caller `signal`) and a maximum response size, and redacts
 * daemon-supplied error detail before it reaches stderr instead of dumping
 * it verbatim.
 */
export async function postJsonToDaemon(
  { base, route, body }: { base: string; route: string; body: unknown },
  options: PostJsonToDaemonOptions = {},
): Promise<unknown> {
  return requestJsonFromDaemon({ base, route, init: { method: 'POST', body } }, options);
}

/**
 * `GET` `<base><route>` and return the parsed JSON response. Same transport contract as
 * {@link postJsonToDaemon} (timeout, response-size cap, structured-error mapping, redaction) with
 * no request body — for read-only daemon routes such as `@jini-ai/http-kit`'s `GET /api/runs` and
 * `GET /api/runs/:runId`.
 */
export async function getJsonFromDaemon(
  { base, route }: { base: string; route: string },
  options: GetJsonFromDaemonOptions = {},
): Promise<unknown> {
  return requestJsonFromDaemon({ base, route, init: { method: 'GET' } }, options);
}

/** A bounded, redacted excerpt of an unrecognized daemon error payload — never the full raw body. */
function describeUnrecognizedDaemonPayload(data: unknown): string {
  let raw: string;
  try {
    raw = JSON.stringify(data) ?? '';
  } catch {
    raw = String(data);
  }
  if (raw.length === 0) return '';
  return ` (daemon response, redacted/truncated): ${sanitizeUntrustedText({ text: raw })}`;
}

#!/usr/bin/env node
/**
 * @module main
 *
 * The bootable `jini` binary (`package.json`'s `"bin": { "jini": "./dist/main.js" }`). Every
 * other module in this package is a library building block — `run-command.ts`,
 * `daemon-command.ts`, and `version-command.ts` each export a `register*Commands(registry,
 * deps)` function ready for a pack to call, but until this file, nothing actually parsed
 * `process.argv` and called them: `packages/cli/archived provenance ledger`'s "Not built" note on
 * `run-command.ts`'s original addition said as much — "no wiring of this file's commands into
 * an actual bootable CLI entrypoint." This closes that gap.
 *
 * Deliberately **not** re-exported from `index.ts`. `index.ts` is this package's library
 * barrel — importing it must be side-effect-free. This file's whole purpose is a
 * process.argv-parsing, stdout/stderr-writing, potentially process.exit-calling side effect;
 * bundling that into the library barrel would mean simply `import`ing `@jini-ai/cli` as a
 * dependency could start acting like a CLI invocation. The guarded top-level block at the
 * bottom of this file (only runs `main()` for real when this module is the actual process
 * entrypoint, not merely imported) exists for the same reason, one level down: importing the
 * named `main` export for testing (or for a consumer that wants to build its own bin wrapper
 * around it) must not itself trigger a real run.
 *
 * **Daemon-URL resolution.** `resolveDaemonUrl` (`daemon-url.ts`) has no baked-in default —
 * this package has never had a locked default daemon port to fall back to (see
 * `archived provenance ledger`: `@jini-ai/server`'s `createLocalNodeDaemon` binds an ephemeral port, not a
 * fixed one). This binary wires the three real, already-built pieces together instead of
 * inventing a new one: an explicit `--daemon-url <url>` flag (highest precedence), a
 * `JINI_DAEMON_URL` env var, and — when `--data-dir <path>` or `--registry-path <path>` is
 * given — `local-daemon-discovery.ts`'s `createLocalDaemonDiscovery`, the CLI-side reader for
 * a `@jini-ai/server`-written on-disk daemon registry record. That discovery module's own doc
 * already flagged it as built-but-unconsumed ("no pack has registered against
 * `CommandRegistry` yet"); this is that consumer. If none of the three resolve, there is still
 * no silent fallback — `resolveDaemonUrl` throws, and this file's own catch boundary (below)
 * turns that into a clean structured-error exit instead of a raw stack trace.
 *
 * **Global flags are stripped before dispatch, not left for `CommandRegistry`'s `valueFlags`
 * skip-ahead.** `CommandRegistry.dispatch`'s `valueFlags` option (see `command-registry.ts`)
 * correctly *finds* the command-name token when a global flag with a value precedes it (e.g.
 * `--daemon-url http://x run` picks `run`, not the URL) — but the `rest` array it then hands
 * the matched handler still *contains* that leading global flag and its value, ahead of
 * whatever the handler expects as its own first token. That's harmless for a flat command, but
 * `run-command.ts`/`daemon-command.ts`'s own registered handlers immediately do a *second*
 * `const [sub, ...rest] = args` dispatch of their own, assuming `args[0]` is their immediate
 * subcommand (`start`/`status`/etc.) with no tolerance for a stray leading flag — exactly what
 * a global flag ahead of the command name would produce. Rather than change that (well-tested,
 * out-of-scope) nested-dispatch assumption, {@link partitionGlobalArgv} below removes this
 * binary's own three global flags (and their values) from `argv` in a single pass *before*
 * dispatch, so `run`/`daemon`/`version` always land as a clean first token no matter where on
 * the command line `--daemon-url`/`--data-dir`/`--registry-path` were typed.
 *
 * **`--version`/`-v`.** This package has its own published semver, but this transport command reports
 * the daemon it is controlling so operators can identify the running service. Accordingly,
 * `jini --version`/`jini -v` (recognized only as the very first token — see {@link main}) is a
 * plain alias for `jini version` (`version-command.ts`): it prints the *running daemon's* real
 * version. That is arguably more useful to a user of this transport-only CLI than this
 * package's own transport version would be, and it means `--version` has exactly one
 * implementation to keep correct, not two.
 *
 * **Error boundary.** `parseFlags` (`flags.ts`) throws a plain `Error` for an unrecognized
 * `--flag` or a string flag with no value — by design (see that module's own doc: "a
 * hallucinated flag from an LLM-driven caller should error immediately"), but every existing
 * command handler (`run-command.ts`, `daemon-command.ts`, `version-command.ts`) calls it
 * un-wrapped, so that throw would otherwise surface as an unhandled rejection with a raw stack
 * trace instead of the clean `{ error: { code, message } }` envelope every *other* failure
 * path in this package produces. {@link main} wraps its dispatch in a boundary that converts
 * any such raw throw into the same structured-error contract. Distinguishing "a raw,
 * unexpected throw" from "a nested command already exited cleanly through
 * `exitWithStructuredError`" (the latter must never be re-wrapped — that would double-report
 * the same failure, or worse, mask the original exit code with a generic one) uses a local
 * flag set by this file's own `exit` wrapper: if the wrapped `exit` was ever invoked before the
 * catch fires, the original error is re-thrown untouched instead of reformatted. In real
 * operation this distinction is moot — `process.exit` never returns, so nothing downstream of
 * a real exit call ever reaches the catch — but it matters for this file's own tests, which
 * (like every other test in this package) inject a throwing `exit` double to make
 * `process.exit`'s real "never returns" behavior observable without ending the test process.
 */
import { existsSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { CommandRegistry, type CommandDispatchResult } from './command-registry.js';
import { registerDaemonCommands } from './daemon-command.js';
import { resolveDaemonUrl, type ResolveDaemonUrlOptions } from './daemon-url.js';
import { exitWithStructuredError } from './errors.js';
import { createLocalDaemonDiscovery } from './local-daemon-discovery.js';
import { registerRunCommands } from './run-command.js';
import { renderUsage } from './usage.js';
import { registerVersionCommand } from './version-command.js';

export interface MainDeps {
  /** Defaults to `process.stdout.write`; inject for tests. */
  write?: (requiredArgs: { text: string }) => void;
  /** Defaults to `process.stderr.write`; inject for tests. */
  writeErr?: (requiredArgs: { text: string }) => void;
  /** Defaults to `process.exit`; inject for tests (must not return). */
  exit?: (requiredArgs: { code: number }) => never;
  /** Defaults to the global `fetch`; inject for tests. */
  fetchImpl?: typeof fetch;
  /** Defaults to `process.env`; inject for tests. */
  env?: NodeJS.ProcessEnv;
}

function defaultWrite({ text }: { text: string }): void {
  process.stdout.write(text);
}

function defaultWriteErr({ text }: { text: string }): void {
  process.stderr.write(text);
}

function defaultExit({ code }: { code: number }): never {
  return process.exit(code);
}

/** Name of the environment variable {@link resolveDaemonUrl} checks when `--daemon-url` is absent. */
const DAEMON_URL_ENV_VAR = 'JINI_DAEMON_URL';

const ROOT_USAGE = renderUsage({ usage: ['jini <command> [...args]'] }, { description: 'CLI transport for a Jini daemon over HTTP. Commands: run, daemon, version.', options: [
    { flag: '--daemon-url <url>', description: 'Explicit daemon base URL. Takes precedence over JINI_DAEMON_URL and local discovery.' },
    { flag: '--data-dir <path>', description: "Resolve a locally running daemon's URL from this data directory's on-disk registry (see @jini-ai/server's createLocalNodeDaemon)." },
    { flag: '--registry-path <path>', description: "Exact registry file path, overriding --data-dir's derived default." },
    { flag: '--help, -h', description: 'Show this help.' },
    { flag: '--version, -v', description: 'Print the running daemon\'s version (alias for "jini version"; recognized only as the first argument).' },
  ] });

const GLOBAL_FLAG_NAMES = ['daemon-url', 'data-dir', 'registry-path'] as const;
type GlobalFlagName = (typeof GLOBAL_FLAG_NAMES)[number];

interface PartitionedArgv {
  readonly globals: Partial<Record<GlobalFlagName, string>>;
  /** `argv` with every recognized global flag (and its value) removed, original order preserved. */
  readonly rest: string[];
}

/**
 * Single-pass extraction of this binary's own global `--daemon-url`/`--data-dir`/
 * `--registry-path` flags out of the full `argv`, returning both their values and every other
 * token untouched (including the command name and all of its own subcommand-specific flags) as
 * `rest` — see this file's own module doc, "Global flags are stripped before dispatch," for why
 * a dedicated single-pass scanner is used here instead of `flags.ts`'s `parseFlags` (whose
 * strict mode would throw on an unrelated subcommand flag, and whose permissive/heuristic mode
 * doesn't reliably agree with "always consume the very next token" for a value-taking flag
 * immediately followed by another `--flag`).
 *
 * @throws A plain `Error` when a recognized global flag is the last token with no value
 * following it — caught by {@link main}'s own error boundary, same as any other malformed-input
 * failure.
 */
function partitionGlobalArgv(argv: readonly string[]): PartitionedArgv {
  const globals: Partial<Record<GlobalFlagName, string>> = {};
  const rest: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    // Loop is bounded by argv.length, so this index is always in range —
    // noUncheckedIndexedAccess types it as possibly-undefined regardless.
    const token = argv[i]!;
    const match = matchGlobalFlag(token);
    if (match === null) {
      rest.push(token);
      continue;
    }
    if (match.inlineValue !== undefined) {
      globals[match.key] = match.inlineValue;
      continue;
    }
    const value = argv[i + 1];
    if (value === undefined) throw new Error(`flag --${match.key} requires a value`);
    globals[match.key] = value;
    i++;
  }
  return { globals, rest };
}

const GLOBAL_FLAG_SET: ReadonlySet<string> = new Set(GLOBAL_FLAG_NAMES);

/** Recognizes `--<global>` / `--<global>=<value>`; `null` for any token that is not one of this binary's own global flags. */
function matchGlobalFlag(token: string): { key: GlobalFlagName; inlineValue: string | undefined } | null {
  if (!token.startsWith('--')) return null;
  const eq = token.indexOf('=');
  const key = eq >= 0 ? token.slice(2, eq) : token.slice(2);
  if (!GLOBAL_FLAG_SET.has(key)) return null;
  return { key: key as GlobalFlagName, inlineValue: eq >= 0 ? token.slice(eq + 1) : undefined };
}

/** Builds a `resolveDaemonUrl`-backed `resolveBaseUrl` closure from this binary's own parsed global flags. */
function buildResolveBaseUrl(globals: PartitionedArgv['globals'], env: NodeJS.ProcessEnv, warn: (requiredArgs: { message: string }) => void): () => Promise<string> {
  const { 'daemon-url': daemonUrl, 'data-dir': dataDir, 'registry-path': registryPath } = globals;
  const discover: ResolveDaemonUrlOptions['discover'] =
    registryPath !== undefined
      ? createLocalDaemonDiscovery({ registryPath })
      : dataDir !== undefined
        ? createLocalDaemonDiscovery({ dataDir })
        : undefined;
  return () =>
    resolveDaemonUrl({}, {
      flagUrl: daemonUrl ?? null,
      env,
      envVarName: DAEMON_URL_ENV_VAR,
      ...(discover !== undefined ? { discover } : {}),
      warn,
    });
}

/** The resolved write/exit ports {@link main} hands every command it registers. */
interface ResolvedMainDeps {
  readonly write: (requiredArgs: { text: string }) => void;
  readonly writeErr: (requiredArgs: { text: string }) => void;
  readonly exit: (requiredArgs: { code: number }) => never;
}

function isRootHelpRequest(argv: readonly string[]): boolean {
  return argv.length === 0 || argv[0] === '--help' || argv[0] === '-h';
}

// `--version`/`-v` as the very first token is a plain alias for `jini version` — see this
// file's own module doc for why there is no separate "this package's own version" surface.
function expandVersionAlias(argv: readonly string[]): readonly string[] {
  return argv[0] === '--version' || argv[0] === '-v' ? ['version', ...argv.slice(1)] : argv;
}

/** Strips the global flags, registers `run`/`daemon`/`version` against a fresh registry and dispatches the remaining argv. */
async function dispatchArgv(
  { argv, env }: { argv: readonly string[]; env: NodeJS.ProcessEnv },
  { ports, fetchImpl }: { ports: ResolvedMainDeps; fetchImpl: typeof fetch | undefined },
): Promise<CommandDispatchResult> {
  const { globals, rest } = partitionGlobalArgv(argv);
  const resolveBaseUrl = buildResolveBaseUrl(globals, env, ({ message }) => ports.writeErr({ text: message }));
  const registry = new CommandRegistry({});
  const commandDeps = { ...ports, ...(fetchImpl === undefined ? {} : { fetchImpl }) };
  registerRunCommands({ registry, resolveBaseUrl }, commandDeps);
  registerDaemonCommands({ registry, resolveBaseUrl }, commandDeps);
  registerVersionCommand({ registry, resolveBaseUrl }, commandDeps);
  return registry.dispatch({ argv: rest });
}

/** A dispatch that matched no handler: no command at all prints root usage, an unknown one exits `invalid-flag`. */
function reportUnmatchedDispatch(result: CommandDispatchResult, ports: ResolvedMainDeps): void {
  if (result.kind === 'empty') {
    ports.write({ text: `${ROOT_USAGE}\n` });
    return;
  }
  if (result.kind === 'not-found') {
    exitWithStructuredError({ code: 'invalid-flag', message: `unknown command: "${result.name}". Run "jini --help" for usage.` }, { write: ports.writeErr, exit: ports.exit });
  }
}

/**
 * Parse `argv` (already stripped of `node`/script-path, i.e. `process.argv.slice(2)`) and
 * dispatch to the registered `run`/`daemon`/`version` commands. Never throws a raw error to its
 * caller under normal use — usage errors and daemon failures both exit through this package's
 * structured-error contract (`errors.ts`), via the injected (or default, real) `exit`.
 */
export async function main({ argv }: { argv: readonly string[] }, deps: MainDeps = {}): Promise<void> {
  const write = deps.write ?? defaultWrite;
  const writeErr = deps.writeErr ?? defaultWriteErr;
  const rawExit = deps.exit ?? defaultExit;

  if (isRootHelpRequest(argv)) {
    write({ text: `${ROOT_USAGE}\n` });
    return;
  }

  // Tracks whether `exit` was ever invoked, so the catch block below can tell "a nested command
  // already exited cleanly" (re-throw untouched) apart from "a genuinely raw, unhandled throw"
  // (reformat into a structured error) — see this file's own module doc, "Error boundary."
  let exitCalled = false;
  const exit = ({ code }: { code: number }): never => {
    exitCalled = true;
    return rawExit({ code });
  };
  const ports: ResolvedMainDeps = { write, writeErr, exit };

  let result: CommandDispatchResult;
  try {
    result = await dispatchArgv({ argv: expandVersionAlias(argv), env: deps.env ?? process.env }, { ports, fetchImpl: deps.fetchImpl });
  } catch (error) {
    if (exitCalled) throw error;
    const message = error instanceof Error ? error.message : String(error);
    exitWithStructuredError({ code: 'invalid-flag', message }, { write: writeErr, exit });
    return;
  }
  reportUnmatchedDispatch(result, ports);
}

// Only run for real when this module is the actual process entrypoint (`node dist/main.js
// ...`, or the `jini` bin shim pnpm/npm links to it) — not merely imported, e.g. by this
// file's own tests importing the named `main` export above. Mirrors Node's CommonJS
// `require.main === module` idiom for ESM; see this file's own module doc.
// Canonical paths recognize npm bin symlinks; a missing argv path is an unrelated import.
const isMainModule = process.argv[1] !== undefined && existsSync(process.argv[1])
  && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
if (isMainModule) {
  await main({ argv: process.argv.slice(2) });
}

/**
 * @module run-command
 *
 * `run start` / `run list` / `run get` / `run cancel` / `run watch` — the
 * first concrete commands registered against this package's
 * `CommandRegistry` (`command-registry.ts`'s own docblock notes none existed
 * yet because no HTTP-client-mode pack had landed to call). Built directly
 * against `@jini-ai/http-kit`'s real run transport (`packages/http/src/runs.ts`:
 * `POST /api/runs`, `GET /api/runs`, `GET /api/runs/:runId`,
 * `POST /api/runs/:runId/cancel`, `GET /api/runs/:runId/events` SSE) — a
 * thin HTTP-transport-mode CLI over the kernel's own `Run` noun, with no
 * project/agent/plugin vocabulary anywhere in this file.
 *
 * Every network call goes through this package's already-hardened
 * `postJsonToDaemon`/`getJsonFromDaemon` (bounded timeout, response-size cap,
 * structured-error mapping, redaction) — nothing here re-implements that.
 * `run watch`'s SSE consumption is new (this package's own `archived provenance ledger`
 * calls the mechanics — GET an SSE endpoint, translate frames to one NDJSON
 * line per event on stdout, stop at a terminal `'end'` event — a clean
 * pattern that had no route to call until now).
 */
import { decodeSseFrames } from '@jini-ai/core/primitives';
import { parseFlags, positionalArgs } from './flags.js';
import { exitWithStructuredError, structuredHttpFailure, type ExitCodeTable } from './errors.js';
import { getJsonFromDaemon, postJsonToDaemon } from './http.js';
import { sanitizeUntrustedText, stripControlSequences } from '@jini-ai/core/text';
import { renderUsage } from './usage.js';
import type { CommandRegistry } from './command-registry.js';

export interface RunCommandDeps {
  /** Resolves the daemon HTTP base URL once per command invocation (e.g. wraps `resolveDaemonUrl`). */
  resolveBaseUrl: () => Promise<string> | string;
  /** Defaults to `process.stdout.write`; inject for tests. Used for successful command output. */
  write?: (requiredArgs: { text: string }) => void;
  /** Defaults to `process.stderr.write`; inject for tests. Used for usage/validation errors. */
  writeErr?: (requiredArgs: { text: string }) => void;
  /** Defaults to the global `fetch`; inject for tests. */
  fetchImpl?: typeof fetch;
  /** Defaults to `process.exit`; inject for tests (must not return). */
  exit?: (requiredArgs: { code: number }) => never;
  /** Extra/overriding `code -> exitCode` entries layered on the package default table. */
  exitCodes?: ExitCodeTable;
}

function defaultWrite({ text }: { text: string }): void {
  process.stdout.write(text);
}

function defaultWriteErr({ text }: { text: string }): void {
  process.stderr.write(text);
}

const RUN_START_USAGE = renderUsage({ usage: ['run start --context-ref <ref> [--agent-id <id>] [--idempotency-key <key>]'] }, { description: 'Starts a new run for the given contextRef.', options: [
    { flag: '--context-ref', description: 'Opaque caller-supplied identity the run belongs to (required).' },
    { flag: '--agent-id', description: 'Which registered agent should drive this run.' },
    { flag: '--idempotency-key', description: 'Starting twice with the same key returns the original run.' },
  ] });

const RUN_LIST_USAGE = renderUsage({ usage: ['run list [--context-ref <ref>]'] }, { description: 'Lists runs, optionally scoped to a contextRef.', options: [{ flag: '--context-ref', description: 'Only list runs belonging to this contextRef.' }] });

const RUN_GET_USAGE = renderUsage({ usage: ['run get <runId>'] }, { description: 'Fetches a single run by id.' });

const RUN_CANCEL_USAGE = renderUsage({ usage: ['run cancel <runId> [--reason <text>]'] }, { description: 'Requests cancellation of an in-progress run. A no-op on an already-terminal run.', options: [{ flag: '--reason', description: 'Optional human-readable cancellation reason.' }] });

const RUN_WATCH_USAGE = renderUsage({ usage: ['run watch <runId> [--after-cursor <cursor>]'] }, { description: 'Streams a run\'s protocol events as one NDJSON line per event on stdout until a terminal event arrives.', options: [{ flag: '--after-cursor', description: 'Resume streaming after this event cursor (reconnect support).' }] });

const RUN_USAGE = renderUsage({ usage: ['run <start|list|get|cancel|watch> ...'] }, { description: 'Manage runs against a Jini daemon over HTTP.' });

/** Builds `{write, exit, exitCodes?}` for `errors.ts`'s structured-error helpers, never assigning `exitCodes` when unset (required under `exactOptionalPropertyTypes`). */
function errorOptions(deps: Omit<RunCommandDeps, "resolveBaseUrl">): { write: (requiredArgs: { text: string }) => void; exit: (requiredArgs: { code: number }) => never; exitCodes?: ExitCodeTable } {
  return {
    write: deps.writeErr ?? defaultWriteErr,
    exit: deps.exit ?? (({ code }: { code: number }) => process.exit(code)),
    ...(deps.exitCodes !== undefined ? { exitCodes: deps.exitCodes } : {}),
  };
}

/** Builds the transport-call options object for `postJsonToDaemon`/`getJsonFromDaemon`, only ever including a key when its value is actually set. */
function transportOptions(deps: RunCommandDeps): {
  fetchImpl?: typeof fetch;
  write?: (requiredArgs: { text: string }) => void;
  exit?: (requiredArgs: { code: number }) => never;
  exitCodes?: ExitCodeTable;
} {
  return {
    ...(deps.fetchImpl !== undefined ? { fetchImpl: deps.fetchImpl } : {}),
    ...(deps.writeErr !== undefined ? { write: deps.writeErr } : {}),
    ...(deps.exit !== undefined ? { exit: deps.exit } : {}),
    ...(deps.exitCodes !== undefined ? { exitCodes: deps.exitCodes } : {}),
  };
}

function missingInput(deps: RunCommandDeps, message: string): never {
  return exitWithStructuredError({ code: 'missing-input', message }, errorOptions(deps));
}

function invalidFlag(deps: RunCommandDeps, message: string): never {
  return exitWithStructuredError({ code: 'invalid-flag', message }, errorOptions(deps));
}

function printJsonResult(deps: RunCommandDeps, value: unknown): void {
  (deps.write ?? defaultWrite)({ text: `${JSON.stringify(value)}\n` });
}

/** Prints `usage` and reports `true` when `args` asks for help (`--help`/`-h` anywhere), so the command returns before touching the daemon. */
function printUsageIfHelp({ args, usage }: { args: readonly string[]; usage: string }, deps: RunCommandDeps): boolean {
  if (!args.includes('--help') && !args.includes('-h')) return false;
  (deps.write ?? defaultWrite)({ text: `${usage}\n` });
  return true;
}

/** `run start --context-ref <ref> [--agent-id <id>] [--idempotency-key <key>]` */
export async function runStartCommand({ args, resolveBaseUrl: resolveBaseUrlPort }: { args: readonly string[]; resolveBaseUrl: RunCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: RunCommandDeps = { resolveBaseUrl: resolveBaseUrlPort, ...optionalArgs };
  if (printUsageIfHelp({ args, usage: RUN_START_USAGE }, deps)) return;
  const flags = parseFlags({ argv: args }, { string: new Set(['context-ref', 'agent-id', 'idempotency-key']) });
  const contextRef = flags['context-ref'];
  if (typeof contextRef !== 'string' || contextRef.length === 0) {
    missingInput(deps, '--context-ref is required');
  }
  const body: Record<string, unknown> = { contextRef };
  if (typeof flags['agent-id'] === 'string') body.agentId = flags['agent-id'];
  if (typeof flags['idempotency-key'] === 'string') body.idempotencyKey = flags['idempotency-key'];

  const baseUrl = await deps.resolveBaseUrl();
  const result = await postJsonToDaemon({ base: baseUrl, route: '/api/runs', body }, transportOptions(deps));
  printJsonResult(deps, result);
}

/** `run list [--context-ref <ref>]` */
export async function runListCommand({ args, resolveBaseUrl: resolveBaseUrlPort }: { args: readonly string[]; resolveBaseUrl: RunCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: RunCommandDeps = { resolveBaseUrl: resolveBaseUrlPort, ...optionalArgs };
  if (printUsageIfHelp({ args, usage: RUN_LIST_USAGE }, deps)) return;
  const flags = parseFlags({ argv: args }, { string: new Set(['context-ref']) });
  const contextRef = flags['context-ref'];
  const route = typeof contextRef === 'string' && contextRef.length > 0
    ? `/api/runs?contextRef=${encodeURIComponent(contextRef)}`
    : '/api/runs';

  const baseUrl = await deps.resolveBaseUrl();
  const result = await getJsonFromDaemon({ base: baseUrl, route }, transportOptions(deps));
  printJsonResult(deps, result);
}

/** `run get <runId>` */
export async function runGetCommand({ args, resolveBaseUrl: resolveBaseUrlPort }: { args: readonly string[]; resolveBaseUrl: RunCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: RunCommandDeps = { resolveBaseUrl: resolveBaseUrlPort, ...optionalArgs };
  if (printUsageIfHelp({ args, usage: RUN_GET_USAGE }, deps)) return;
  const runId = positionalArgs({ argv: args })[0];
  if (typeof runId !== 'string' || runId.length === 0) {
    missingInput(deps, 'runId is required: run get <runId>');
  }

  const baseUrl = await deps.resolveBaseUrl();
  const result = await getJsonFromDaemon({ base: baseUrl, route: `/api/runs/${encodeURIComponent(runId)}` }, transportOptions(deps));
  printJsonResult(deps, result);
}

/** `run cancel <runId> [--reason <text>]` */
export async function runCancelCommand({ args, resolveBaseUrl: resolveBaseUrlPort }: { args: readonly string[]; resolveBaseUrl: RunCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: RunCommandDeps = { resolveBaseUrl: resolveBaseUrlPort, ...optionalArgs };
  if (printUsageIfHelp({ args, usage: RUN_CANCEL_USAGE }, deps)) return;
  const flags = parseFlags({ argv: args }, { string: new Set(['reason']) });
  const runId = positionalArgs({ argv: args }, { string: new Set(['reason']) })[0];
  if (typeof runId !== 'string' || runId.length === 0) {
    missingInput(deps, 'runId is required: run cancel <runId>');
  }
  const body: Record<string, unknown> = {};
  if (typeof flags.reason === 'string') body.reason = flags.reason;

  const baseUrl = await deps.resolveBaseUrl();
  const result = await postJsonToDaemon({ base: baseUrl, route: `/api/runs/${encodeURIComponent(runId)}/cancel`, body }, transportOptions(deps));
  printJsonResult(deps, result);
}

/** Cap on total buffered-but-not-yet-frame-terminated SSE text — a daemon that never sends a blank-line frame terminator must not grow this without bound (retains the historical 10 MiB-sized text cap; TextDecoder output is measured in UTF-16 units). */
const MAX_SSE_BUFFER_CHARS = 10 * 1024 * 1024;

/** One parsed SSE frame: the `data:` line(s) joined, plus optional `id`/`event` fields. */
interface SseFrame {
  readonly id?: string;
  readonly event?: string;
  readonly data: string;
}

/** Reads complete records; this adapter releases the lock without canceling the host's body. */
async function* readSseFrames(body: ReadableStream<Uint8Array>): AsyncGenerator<SseFrame> {
  const reader = body.getReader();
  async function* chunks(): AsyncGenerator<Uint8Array> {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return;
      if (value !== undefined) yield value;
    }
  }
  try {
    for await (const frame of decodeSseFrames({ source: chunks() }, {
      flushFinalFrame: false, maxBufferChars: MAX_SSE_BUFFER_CHARS,
    })) {
      if (frame.dataLines.length === 0) continue;
      yield { ...(frame.id !== undefined ? { id: frame.id } : {}),
        ...(frame.event !== null ? { event: frame.event } : {}), data: frame.data };
    }
  } finally {
    reader.releaseLock();
  }
}

/** True when a parsed SSE frame's `data` is the canonical `RunProtocolEvent` terminal `'end'` event. */
function isTerminalEventFrame(frame: SseFrame): boolean {
  try {
    const parsed = JSON.parse(frame.data) as { kind?: unknown };
    return parsed.kind === 'end';
  } catch {
    return false;
  }
}

/**
 * Streams `GET /api/runs/:runId/events` and writes one NDJSON line per event to `deps.write`,
 * stopping once a terminal `'end'` event arrives (or the stream closes on its own). Each frame's
 * `data` is stripped of terminal control sequences before being written — it originates from a
 * prompt-influenced agent run and is not trusted to be safe to print verbatim (same posture as
 * `redact.ts`'s other daemon-sourced-text handling), though it is not truncated or secret-redacted
 * the way a diagnostic error message is, since it is the run's actual event payload, not incidental
 * error detail.
 */
export async function watchRunEvents({ baseUrl, runId, args }: { baseUrl: string; runId: string; args: readonly string[] }, deps: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const headers = resumeHeaders(args);
  const fetchImpl = deps.fetchImpl ?? fetch;
  const write = deps.write ?? defaultWrite;

  const resp = await fetchImpl(`${baseUrl}/api/runs/${encodeURIComponent(runId)}/events`, { headers });
  if (!resp.ok || resp.body === null) {
    return structuredHttpFailure({ resp }, { fallbackCode: 'daemon-not-running', ...errorOptions(deps) });
  }
  try {
    await writeEventsUntilEnd({ body: resp.body, write });
  } catch (error) {
    // A broken/hostile stream (e.g. the unbounded-buffer guard above) must exit through the same
    // structured contract as every other failure here, not surface as an unhandled rejection.
    const message = error instanceof Error ? error.message : String(error);
    return exitWithStructuredError({ code: 'daemon-not-running', message: sanitizeUntrustedText({ text: message }) }, errorOptions(deps));
  }
}

/** `last-event-id` from a non-empty `--after-cursor`, so a reconnect resumes after that cursor; no header otherwise. */
function resumeHeaders(args: readonly string[]): Record<string, string> {
  const afterCursor = parseFlags({ argv: args }, { string: new Set(['after-cursor']) })['after-cursor'];
  return typeof afterCursor === 'string' && afterCursor.length > 0 ? { 'last-event-id': afterCursor } : {};
}

/** Writes one control-sequence-stripped NDJSON line per SSE frame, stopping after the terminal `'end'` event or when the stream closes. */
async function writeEventsUntilEnd({ body, write }: { body: ReadableStream<Uint8Array>; write: (requiredArgs: { text: string }) => void }): Promise<void> {
  for await (const frame of readSseFrames(body)) {
    write({ text: `${stripControlSequences({ text: frame.data })}\n` });
    if (isTerminalEventFrame(frame)) return;
  }
}

/** `run watch <runId> [--after-cursor <cursor>]` */
export async function runWatchCommand({ args, resolveBaseUrl: resolveBaseUrlPort }: { args: readonly string[]; resolveBaseUrl: RunCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: RunCommandDeps = { resolveBaseUrl: resolveBaseUrlPort, ...optionalArgs };
  if (printUsageIfHelp({ args, usage: RUN_WATCH_USAGE }, deps)) return;
  const runId = positionalArgs({ argv: args }, { string: new Set(['after-cursor']) })[0];
  if (typeof runId !== 'string' || runId.length === 0) {
    missingInput(deps, 'runId is required: run watch <runId>');
  }
  const baseUrl = await deps.resolveBaseUrl();
  await watchRunEvents({ baseUrl, runId, args }, deps);
}

/** Registers `run` (dispatching `start`/`list`/`cancel`/`watch` on the first remaining token) against `registry`. */
export function registerRunCommands({ registry, resolveBaseUrl: resolveBaseUrlPort }: { registry: CommandRegistry; resolveBaseUrl: RunCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<RunCommandDeps, "resolveBaseUrl"> = {}): void {
  const deps: RunCommandDeps = { resolveBaseUrl: resolveBaseUrlPort, ...optionalArgs };
  registry.add({ name: 'run', handler: async ({ args }) => {
      const [sub, ...rest] = args;
      switch (sub) {
        case 'start':
          return runStartCommand({ args: rest, resolveBaseUrl: resolveBaseUrlPort }, optionalArgs);
        case 'list':
          return runListCommand({ args: rest, resolveBaseUrl: resolveBaseUrlPort }, optionalArgs);
        case 'get':
          return runGetCommand({ args: rest, resolveBaseUrl: resolveBaseUrlPort }, optionalArgs);
        case 'cancel':
          return runCancelCommand({ args: rest, resolveBaseUrl: resolveBaseUrlPort }, optionalArgs);
        case 'watch':
          return runWatchCommand({ args: rest, resolveBaseUrl: resolveBaseUrlPort }, optionalArgs);
        case undefined:
        case '--help':
        case '-h':
          (deps.write ?? defaultWrite)({ text: `${RUN_USAGE}\n` });
          return;
        default:
          invalidFlag(deps, `unknown "run" subcommand: ${sub}`);
      }
    } }, { usage: RUN_USAGE });
}

/**
 * @module version-command
 *
 * `version` — prints just the running daemon's version string. Sourced from
 * `GET /api/daemon/status`'s `version` field (`packages/http/src/daemon-status.ts`,
 * `DaemonStatusResponse.version`) — the same route `daemon-command.ts`'s `daemon status`
 * already calls. `packages/cli/archived provenance ledger`'s original UNCLEAR verdict on a standalone
 * `version` command noted "@jini-ai/http-kit has no version route yet ... nothing to call"; that
 * blocker never actually required a *separate* route — `daemonStatusRoute`'s response body
 * already carries a `version` field, so no new HTTP route was added for this command. It just
 * extracts and prints that one field instead of the full status envelope `daemon status` prints.
 *
 * Same DI/testing/`resolveBaseUrl` conventions as `daemon-command.ts`'s `daemon status`/`daemon
 * stop` (this file duplicates rather than imports their small `errorOptions`/`transportOptions`
 * helpers, matching that file's own precedent of each command module owning its own copy rather
 * than sharing a not-otherwise-needed abstraction across files).
 */
import { exitWithStructuredError, type ExitCodeTable } from './errors.js';
import { getJsonFromDaemon } from './http.js';
import { renderUsage } from './usage.js';
import type { CommandRegistry } from './command-registry.js';

export interface VersionCommandDeps {
  /** Resolves the daemon HTTP base URL once per command invocation (e.g. wraps `resolveDaemonUrl`). */
  resolveBaseUrl: () => Promise<string> | string;
  /** Defaults to `process.stdout.write`; inject for tests. Used for the printed version string. */
  write?: (requiredArgs: { text: string }) => void;
  /** Defaults to `process.stderr.write`; inject for tests. Used for usage/validation errors. */
  writeErr?: (requiredArgs: { text: string }) => void;
  /** Defaults to the global `fetch`; inject for tests. */
  fetchImpl?: typeof fetch;
  /** Defaults to `process.exit`; inject for tests (must not return). */
  exit?: (requiredArgs: { code: number }) => never;
  /** Extra/overriding `code -> exitCode` entries layered on the package default table. */
  exitCodes?: ExitCodeTable;
}

function defaultWrite({ text }: { text: string }): void {
  process.stdout.write(text);
}

function defaultWriteErr({ text }: { text: string }): void {
  process.stderr.write(text);
}

const VERSION_USAGE = renderUsage({ usage: ['version'] }, { description: 'Prints the running daemon\'s version string (nothing else — see "daemon status" for the full status envelope).' });

/** Builds `{write, exit, exitCodes?}` for `errors.ts`'s structured-error helpers, never assigning `exitCodes` when unset (required under `exactOptionalPropertyTypes`). */
function errorOptions(deps: VersionCommandDeps): { write: (requiredArgs: { text: string }) => void; exit: (requiredArgs: { code: number }) => never; exitCodes?: ExitCodeTable } {
  return {
    write: deps.writeErr ?? defaultWriteErr,
    exit: deps.exit ?? (({ code }: { code: number }) => process.exit(code)),
    ...(deps.exitCodes !== undefined ? { exitCodes: deps.exitCodes } : {}),
  };
}

/** Builds the transport-call options object for `getJsonFromDaemon`, only ever including a key when its value is actually set. */
function transportOptions(deps: VersionCommandDeps): {
  fetchImpl?: typeof fetch;
  write?: (requiredArgs: { text: string }) => void;
  exit?: (requiredArgs: { code: number }) => never;
  exitCodes?: ExitCodeTable;
} {
  return {
    ...(deps.fetchImpl !== undefined ? { fetchImpl: deps.fetchImpl } : {}),
    ...(deps.writeErr !== undefined ? { write: deps.writeErr } : {}),
    ...(deps.exit !== undefined ? { exit: deps.exit } : {}),
    ...(deps.exitCodes !== undefined ? { exitCodes: deps.exitCodes } : {}),
  };
}

/**
 * Extracts a non-empty `version` string out of `/api/daemon/status`'s parsed JSON body. A daemon
 * that responds 2xx but omits (or mistypes) `version` is exactly as "not behaving like a Jini
 * daemon" as an unreachable one — this reuses the `daemon-not-running` code (the same fallback
 * `structuredHttpFailure` itself defaults to elsewhere in this package) rather than inventing a
 * new exit code for this one caller.
 */
function extractVersion(deps: VersionCommandDeps, body: unknown): string {
  if (typeof body === 'object' && body !== null) {
    const version = (body as { version?: unknown }).version;
    if (typeof version === 'string' && version.length > 0) return version;
  }
  return exitWithStructuredError({ code: 'daemon-not-running', message: '/api/daemon/status response did not include a version string' }, errorOptions(deps));
}

/** `version` */
export async function versionCommand({ args, resolveBaseUrl }: { args: readonly string[]; resolveBaseUrl: VersionCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<VersionCommandDeps, "resolveBaseUrl"> = {}): Promise<void> {
  const deps: VersionCommandDeps = { resolveBaseUrl, ...optionalArgs };
  if (args.includes('--help') || args.includes('-h')) {
    (deps.write ?? defaultWrite)({ text: `${VERSION_USAGE}\n` });
    return;
  }
  const baseUrl = await deps.resolveBaseUrl();
  const result = await getJsonFromDaemon({ base: baseUrl, route: '/api/daemon/status' }, transportOptions(deps));
  const version = extractVersion(deps, result);
  (deps.write ?? defaultWrite)({ text: `${version}\n` });
}

/** Registers `version` against `registry`. */
export function registerVersionCommand({ registry, resolveBaseUrl }: { registry: CommandRegistry; resolveBaseUrl: VersionCommandDeps["resolveBaseUrl"] }, optionalArgs: Omit<VersionCommandDeps, "resolveBaseUrl"> = {}): void {
  const deps: VersionCommandDeps = { resolveBaseUrl, ...optionalArgs };
  registry.add({ name: 'version', handler: ({ args }) => versionCommand({ args, resolveBaseUrl: resolveBaseUrl }, optionalArgs) }, { usage: VERSION_USAGE });
}

/** Pure field/submission validation and honeypot decisions. Error order and stored value normalization are stable. */
import type { FieldDescriptor, FormDefinitionRecord } from "./types.js";

// Domain validation stays independent of feature manifests, and returns decisions without I/O
// or exceptions so write and submission services can choose their own error presentation.
// Published tool schemas and render-time defensive checks use these exported bounds/patterns
// instead of restating them; validation owns the enforcement rule.
const MIN_FIELDS = 1;
export const MAX_FIELDS = 20;
const MIN_LABEL_LENGTH = 1;
export const MAX_LABEL_LENGTH = 200;
export const MIN_MAX_LENGTH = 1;
export const MAX_MAX_LENGTH = 5000;
export const FIELD_ID_PATTERN = /^[a-z][a-z0-9_]*$/;
export const FIELD_TYPES = new Set(["text", "email", "textarea", "checkbox"]);

export const MAX_CLASS_NAME_LENGTH = 300;
export const MAX_ATTRIBUTES_PER_FIELD = 12;
export const MAX_ATTRIBUTE_VALUE_LENGTH = 300;

/**
 * Escaping makes an attribute value inert, but cannot make a name such as onclick safe. Names
 * are deny-by-default: only aria-* and data-* namespaces and a fixed closed list are accepted.
 * Event handlers, style/formaction/href/src/srcdoc can inject behavior; id/name/type overrides
 * can break label association, submission keys or the renderer's declared field vocabulary.
 */
export const ATTRIBUTE_NAME_PATTERN =
  /^(aria-[a-z0-9-]+|data-[a-z0-9-]+|placeholder|autocomplete|inputmode|pattern|title|min|max|step|minlength|spellcheck|readonly)$/;

// Accepted as submission metadata, never as a declared field or stored answer.
export const HONEYPOT_KEY = "_hp";

export interface FieldError {
  field: string;
  reason: string;
}

export type FieldValidationResult = { valid: true } | { valid: false; fieldErrors: FieldError[] };

// Malformed IDs are never claimed: repeated malformed IDs must each report their shape error
// rather than misleading the second field's author with a duplicate-ID diagnosis.
function fieldIdErrors(descriptor: FieldDescriptor, label: string, claimedIds: Set<string>): FieldError[] {
  if (!descriptor.id || !FIELD_ID_PATTERN.test(descriptor.id)) {
    return [{ field: label, reason: "id must match ^[a-z][a-z0-9_]*$" }];
  }
  if (claimedIds.has(descriptor.id)) {
    return [{ field: descriptor.id, reason: "duplicate field id" }];
  }
  claimedIds.add(descriptor.id);
  return [];
}

function fieldTypeErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  if (!FIELD_TYPES.has(descriptor.type)) {
    return [{ field: label, reason: `type '${descriptor.type}' is not in the registered vocabulary` }];
  }
  return [];
}

function labelLengthErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  if (descriptor.label.length < MIN_LABEL_LENGTH || descriptor.label.length > MAX_LABEL_LENGTH) {
    return [{ field: label, reason: `label must be ${MIN_LABEL_LENGTH}-${MAX_LABEL_LENGTH} characters` }];
  }
  return [];
}

// A checkbox carries a boolean, so no character cap can be honored. Report that prohibition
// before any numeric range error, rather than asking the author to fix a number they must remove.
function maxLengthErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  if (descriptor.maxLength == null) return [];
  if (descriptor.type === "checkbox") {
    return [{ field: label, reason: "maxLength is forbidden for checkbox fields" }];
  }
  if (descriptor.maxLength < MIN_MAX_LENGTH || descriptor.maxLength > MAX_MAX_LENGTH) {
    return [{ field: label, reason: `maxLength must be ${MIN_MAX_LENGTH}-${MAX_MAX_LENGTH}` }];
  }
  return [];
}

function checkboxValueErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  if (descriptor.checkboxValue === undefined) return [];
  if (descriptor.type !== "checkbox" || typeof descriptor.checkboxValue !== "string") {
    return [{ field: label, reason: "checkboxValue must be a string on a checkbox field" }];
  }
  return [];
}

// HTML-escaped class names are inert; only their length is bounded. Check type defensively
// because real inputs include parsed request bodies, regardless of the descriptor's static type.
function classNameErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  const { className } = descriptor;
  if (className == null) return [];
  if (typeof className !== "string") {
    return [{ field: label, reason: "className must be a string" }];
  }
  if (className.length > MAX_CLASS_NAME_LENGTH) {
    return [{ field: label, reason: `className must be at most ${MAX_CLASS_NAME_LENGTH} characters` }];
  }
  return [];
}

// A refused name will never render, so its value is moot. Reporting value errors as well would
// imply that correcting a value could make a structurally unsafe attribute acceptable.
function attributeEntryErrors(label: string, attrName: string, attrValue: unknown): FieldError[] {
  if (!ATTRIBUTE_NAME_PATTERN.test(attrName)) {
    return [{ field: label, reason: `attribute '${attrName}' is not allowed` }];
  }
  if (typeof attrValue !== "string") {
    return [{ field: label, reason: `attribute '${attrName}' value must be a string` }];
  }
  if (attrValue.length > MAX_ATTRIBUTE_VALUE_LENGTH) {
    return [{ field: label, reason: `attribute '${attrName}' value must be at most ${MAX_ATTRIBUTE_VALUE_LENGTH} characters` }];
  }
  return [];
}

// Exceeding the count cap still checks every attribute so the author sees unsafe names in one
// round trip. This visits O(a) caller-supplied attributes; the reported cap does not truncate work.
function attributeErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  const { attributes } = descriptor;
  if (attributes == null) return [];

  const entries = Object.entries(attributes);
  const errors: FieldError[] = [];
  if (entries.length > MAX_ATTRIBUTES_PER_FIELD) {
    errors.push({ field: label, reason: `at most ${MAX_ATTRIBUTES_PER_FIELD} attributes are allowed` });
  }
  for (const [attrName, attrValue] of entries) {
    errors.push(...attributeEntryErrors(label, attrName, attrValue));
  }
  return errors;
}

/**
 * Collect every violation, not just the first: arity errors, then descriptors in array order,
 * then each rule in the fixed order below. Callers display this list as-is, so order is observable.
 * Empty helper results mean a satisfied rule. Bounds are 1-20 fields, labels 1-200 characters,
 * and maxLength 1-5000 (never on checkboxes), with unique lowercase field IDs.
 */
export function validateFieldDescriptors({ fields }: { fields: FieldDescriptor[] }): FieldValidationResult {
  const fieldErrors: FieldError[] = [];

  if (fields.length < MIN_FIELDS) {
    fieldErrors.push({ field: "fields", reason: `at least ${MIN_FIELDS} field is required` });
  }
  if (fields.length > MAX_FIELDS) {
    fieldErrors.push({ field: "fields", reason: `at most ${MAX_FIELDS} fields are allowed` });
  }

  const claimedIds = new Set<string>();
  for (const descriptor of fields) {
    const label = descriptor.id || "(unknown)";
    fieldErrors.push(
      ...fieldIdErrors(descriptor, label, claimedIds),
      ...fieldTypeErrors(descriptor, label),
      ...labelLengthErrors(descriptor, label),
      ...maxLengthErrors(descriptor, label),
      ...checkboxValueErrors(descriptor, label),
      ...classNameErrors(descriptor, label),
      ...attributeErrors(descriptor, label),
    );
  }

  if (fieldErrors.length > 0) return { valid: false, fieldErrors };
  return { valid: true };
}

export interface ValidateSubmissionPayloadInput {
  definition: FormDefinitionRecord;
  body: Record<string, unknown>;
}

export type SubmissionValidationResult =
  | { valid: true; data: Record<string, string | boolean> }
  | { valid: false; fieldErrors: FieldError[] };

// Absence is distinct from acceptance: treating an omitted optional field as an accepted value
// would write undefined and violate the guarantee that stored answers contain only declared keys.
type SubmittedValue =
  | { kind: "absent" }
  | { kind: "rejected"; reason: string }
  | { kind: "accepted"; value: string | boolean };

// The honeypot is tolerated in the raw body, but is excluded from stored answers.
function unregisteredKeyErrors(body: Record<string, unknown>, fieldsById: ReadonlyMap<string, FieldDescriptor>): FieldError[] {
  const errors: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (key === HONEYPOT_KEY) continue;
    if (!fieldsById.has(key)) {
      errors.push({ field: key, reason: "unregistered_key" });
    }
  }
  return errors;
}

// Whitespace is rejected only for required text; optional whitespace is an answer the definition
// permits. Preserve the submitted string instead of silently trimming its stored value.
function resolveTextValue(field: FieldDescriptor, value: unknown): SubmittedValue {
  if (typeof value !== "string") return { kind: "rejected", reason: "must be a string" };
  if (field.required && value.trim() === "") return { kind: "rejected", reason: "required" };
  if (field.maxLength != null && value.length > field.maxLength) return { kind: "rejected", reason: "too_long" };
  return { kind: "accepted", value };
}

// Native URL-encoded forms submit "on" for checked boxes without a value attribute; accepting
// only JSON booleans would reject every checked checkbox when client JavaScript is disabled.
// An unticked native checkbox omits its key; submission resolution treats that as absence.
const HTML_CHECKBOX_ON_VALUE = "on";

function resolveCheckboxValue(field: FieldDescriptor, value: unknown): SubmittedValue {
  if (field.checkboxValue !== undefined && typeof value === "string") return { kind: "accepted", value };
  if (typeof value === "boolean") return { kind: "accepted", value };
  if (value === HTML_CHECKBOX_ON_VALUE) return { kind: "accepted", value: true };
  return { kind: "rejected", reason: "must be a boolean" };
}

// JSON and native forms differ in how they represent missing values, so null/undefined both
// mean absence. Boolean false is a real checkbox answer, including for a required checkbox.
function resolveSubmittedValue(field: FieldDescriptor, value: unknown): SubmittedValue {
  if (value === undefined || value === null) {
    return field.required ? { kind: "rejected", reason: "required" } : { kind: "absent" };
  }
  if (field.type === "checkbox") return resolveCheckboxValue(field, value);
  return resolveTextValue(field, value);
}

/**
 * Only declared, accepted fields reach data; the reserved honeypot never does. Report unknown
 * body keys first, then declared-field errors in definition order, independent of body key order.
 * This keeps the declared-field portion of the error list stable across equivalent submissions.
 */
export function validateSubmissionPayload(input: ValidateSubmissionPayloadInput): SubmissionValidationResult {
  const { definition, body } = input;
  const fieldsById = new Map<string, FieldDescriptor>(definition.fields.map((f) => [f.id, f]));

  const fieldErrors: FieldError[] = unregisteredKeyErrors(body, fieldsById);
  const data: Record<string, string | boolean> = {};

  for (const field of definition.fields) {
    const resolved = resolveSubmittedValue(field, body[field.id]);
    if (resolved.kind === "rejected") {
      fieldErrors.push({ field: field.id, reason: resolved.reason });
    } else if (resolved.kind === "accepted") {
      data[field.id] = resolved.value;
    }
  }

  if (fieldErrors.length > 0) return { valid: false, fieldErrors };
  return { valid: true, data };
}

// Only a non-empty trimmed string trips the trap; absent, non-string or whitespace-only values
// do not reject an otherwise valid submission.
export function isHoneypotTripped(input: { hp: unknown }): boolean {
  if (typeof input.hp !== "string") return false;
  return input.hp.trim().length > 0;
}

import type { Logger } from "@jini-ai/core/primitives";
/** Notification subscriber with host sender, mail and logging ports. Each recipient receives a stable per-submission dedup key; delivery and repository failures never block sibling subscribers. */
import type { DomainEvent, EventBusPort } from "@jini-ai/cms/core";
import type { MailerPort,  EmailAddress } from "./ports.js";
import type { FormDefinitionRepoPort, FormSubmissionRepoPort } from "./ports.js";

// Domain behavior owns its event contract; reading a host manifest back would invert dependency flow.
const FORM_SUBMISSION_RECEIVED_TOPIC = "form.submission.received";

interface FormSubmissionReceivedPayload {
  workspaceId: string;
  formDefinitionId: string;
  submissionId: string;
}

export interface RegisterFormNotifySubscriberDeps {
  bus: EventBusPort;
  sender: EmailAddress;
  logger: Pick<Logger, 'warn'>;
  mailer: MailerPort;
  formDefinitionRepo: FormDefinitionRepoPort;
  formSubmissionRepo: FormSubmissionRepoPort;
}

export async function registerFormNotifySubscriber(
  deps: RegisterFormNotifySubscriberDeps
): Promise<() => Promise<void>> {
  return deps.bus.subscribe<FormSubmissionReceivedPayload>(
    { eventName: FORM_SUBMISSION_RECEIVED_TOPIC,
    handler: async (event: DomainEvent<FormSubmissionReceivedPayload>) => {
      try {
        const { workspaceId, formDefinitionId, submissionId } = event.payload;

        const definition = await deps.formDefinitionRepo.findById({ workspaceId, id: formDefinitionId });
        if (!definition || !definition.notify.enabled || definition.notify.recipients.length === 0) {
          return;
        }

        const submission = await deps.formSubmissionRepo.findById({ workspaceId, id: submissionId });
        if (!submission) return;

        for (const recipient of definition.notify.recipients) {
          try {
            const result = await deps.mailer.send({
              message: {
                workspaceId,
                to: { email: recipient },
                from: deps.sender,
                subject: `New submission: ${definition.name}`,
                text: JSON.stringify(submission.data),
              },
              options: {
                // Include the recipient so a shared dedup ledger never suppresses a sibling send.
                idempotencyKey: `forms:notify:${submissionId}:${recipient}`,
                workspaceId,
                sourceContext: { module: "forms", ref: formDefinitionId },
                purpose: "transactional",
                // Background notifications use the host mailer's durable-outbox readiness gate,
                // rather than the interactive send lane, when production delivery requires it.
                lane: "notification",
              }
            });
            if (!result.ok) {
              warn(deps.logger,
                `[forms:notify] mail send failed for submission '${submissionId}' recipient '${recipient}': ${result.errorCode} (${result.message})`
              );
            }
          } catch (err) {
            // A send failure is terminal for this delivery: log, never retry inline or alter
            // the persisted submission, and continue so the other recipients can still receive it.
            warn(deps.logger,
              `[forms:notify] mail send threw for submission '${submissionId}' recipient '${recipient}':`,
              err
            );
          }
        }
      } catch (err) {
        // Repository failures must not escape the bus's subscriber loop and break sibling handlers.
        warn(deps.logger, "[forms:notify] subscriber failed:", err);
      }
    } }
  );
}

/** Failure reporting is isolated too: a logger cannot interrupt sibling event subscribers. */
function warn(logger: Pick<Logger, 'warn'>, message: string, error?: unknown): void {
  try { logger.warn({ message }, error === undefined ? {} : { error }); } catch { /* Host logging failure is terminal. */ }
}

import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
/** Audited definition writes through the CMS command gateway. Host permissions and reserved slugs are explicit policies; notify, idempotency and optional outbox wiring live in the second argument. */
import type { ChangeSetRepoPort } from "@jini-ai/cms/core";
import type { Clock, IdGenerator, UUID } from "@jini-ai/core/primitives";
import type {
  AuthorizeFn,
  CommandActor,
} from "@jini-ai/cms/core";
import { FormDefinitionNotFoundError, FormFieldValidationError } from "./errors.js";
import { validateFieldDescriptors } from "./forms.js";
import type { FormCommandExecutorPort, FormDefinitionRepoPort } from "./ports.js";
import type {
  FieldDescriptor,
  FormDefinitionRecord,
  FormDefinitionStatus,
  NotifyConfig,
} from "./types.js";

export interface FormWriteServiceDeps {
  /** Host-bound audited command gateway; no runtime CMS implementation is imported. */
  executeCommand: FormCommandExecutorPort;
  repo: FormDefinitionRepoPort;
  clock: Clock;
  idGen: IdGenerator;
  changeSets: ChangeSetRepoPort;
  permission: string;
  reservedSlugs: ReadonlySet<string>;
  authorize: AuthorizeFn;
}

// Export validation bounds so host tool schemas can share them rather than drift from the service.
export const MAX_NOTIFY_RECIPIENTS = 10;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export const SLUG_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MIN_NAME_LENGTH = 1;
export const MAX_NAME_LENGTH = 200;

function defaultNotify(): NotifyConfig {
  return { enabled: false, recipients: [] };
}

function validateNotify(notify: NotifyConfig | undefined): NotifyConfig {
  const resolved = notify ?? defaultNotify();
  if (!Array.isArray(resolved.recipients)) {
    throw new FormFieldValidationError({ message: "notify.recipients must be an array", fieldErrors: [
      { field: "notify.recipients", reason: "must be an array" },
    ] });
  }
  if (typeof resolved.enabled !== "boolean") {
    throw new FormFieldValidationError({ message: "notify.enabled must be a boolean", fieldErrors: [
      { field: "notify.enabled", reason: "must be a boolean" },
    ] });
  }
  if (resolved.recipients.length > MAX_NOTIFY_RECIPIENTS) {
    throw new FormFieldValidationError({ message: `notify.recipients may not exceed ${MAX_NOTIFY_RECIPIENTS} addresses`, fieldErrors: [{ field: "notify.recipients", reason: `at most ${MAX_NOTIFY_RECIPIENTS} recipients are allowed` }] });
  }
  for (const recipient of resolved.recipients) {
    if (!EMAIL_PATTERN.test(recipient)) {
      throw new FormFieldValidationError({ message: `'${recipient}' is not a valid email address`, fieldErrors: [
        { field: "notify.recipients", reason: `'${recipient}' is not a valid email address` },
      ] });
    }
  }
  return resolved;
}

function validateNameAndSlug(name: string, slug: string, reservedSlugs: ReadonlySet<string>): void {
  if (name.length < MIN_NAME_LENGTH || name.length > MAX_NAME_LENGTH) {
    throw new FormFieldValidationError({ message: `name must be ${MIN_NAME_LENGTH}-${MAX_NAME_LENGTH} characters`, fieldErrors: [
      { field: "name", reason: `must be ${MIN_NAME_LENGTH}-${MAX_NAME_LENGTH} characters` },
    ] });
  }
  if (!SLUG_PATTERN.test(slug)) {
    throw new FormFieldValidationError({ message: "slug must match ^[a-z0-9][a-z0-9-]{0,63}$", fieldErrors: [
      { field: "slug", reason: "must match ^[a-z0-9][a-z0-9-]{0,63}$" },
    ] });
  }
  if (reservedSlugs.has(slug)) {
    throw new FormFieldValidationError({ message: `slug '${slug}' is reserved`, fieldErrors: [
      { field: "slug", reason: `'${slug}' is reserved by the host` },
    ] });
  }
}

function assertValidFields(fields: FieldDescriptor[]): void {
  const validation = validateFieldDescriptors({ fields });
  if (!validation.valid) {
    throw new FormFieldValidationError({ message: "one or more field descriptors are invalid", fieldErrors: validation.fieldErrors });
  }
}

export interface CreateFormDefinitionRequired {
  deps: FormWriteServiceDeps;
  input: {
    workspaceId: UUID;
    actor: CommandActor;
    name: string;
    slug: string;
    fields: FieldDescriptor[];
  };
}

/**
 * All definition writes pass through the injected command gateway for authorization, audit
 * capture and optional change-set event enqueue. There is no delete here: permanent removal
 * belongs to a separate trash purge, and the definition repository exposes no delete method.
 * Slug uniqueness is enforced by the repository's unique index, avoiding a racy pre-insert check;
 * repository slug-conflict errors propagate unchanged from the mutation.
 */
export async function createFormDefinition(
  required: CreateFormDefinitionRequired,
  optional: CreateFormDefinitionOptional = {}
): Promise<{ definition: FormDefinitionRecord }> {
  const { deps, input } = required;
  validateNameAndSlug(input.name, input.slug, deps.reservedSlugs);
  assertValidFields(input.fields);
  const notify = validateNotify(optional.notify);

  const definitionId = deps.idGen.newId();

  const { result } = await deps.executeCommand({
    deps: {
      clock: deps.clock,
      idGen: deps.idGen,
      changeSets: deps.changeSets,
      outbox: optional.outbox,
      authorize: deps.authorize,
    },
    command: {
      workspaceId: input.workspaceId,
      actor: input.actor,
      summary: `Create form definition '${input.slug}'`,
      idempotencyKey: optional.idempotencyKey,
      permission: deps.permission,
    },
    mutation: {
      entityType: "form_definition",
      entityId: definitionId,
      operation: "create",
      captureInverse: async () => null,
      execute: async () => {
        const now = kernelNowIso({ clock: deps.clock });
        const definition: FormDefinitionRecord = {
          id: definitionId,
          workspaceId: input.workspaceId,
          name: input.name,
          slug: input.slug,
          fields: input.fields,
          notify,
          status: "active",
          createdAt: now,
          updatedAt: now,
          // Start the optimistic-concurrency version at 1 for the trash compare-and-set lifecycle.
          version: 1,
        };
        await deps.repo.create(definition);
        return { definition };
      },
    },
  });

  return result;
}

export interface UpdateFormDefinitionRequired {
  deps: FormWriteServiceDeps;
  input: {
    workspaceId: UUID;
    actor: CommandActor;
    formId: UUID;

    // Accept a supplied slug for compatibility but ignore it: updates never rename stored slugs.
    patch: {
      name?: string;
      fields?: FieldDescriptor[];
      notify?: NotifyConfig;
      slug?: string;
    };
  };
}

export async function updateFormDefinition(
  required: UpdateFormDefinitionRequired,
  optional: FormWriteOptional = {}
): Promise<{ definition: FormDefinitionRecord }> {
  const { deps, input } = required;

  const { result } = await deps.executeCommand({
    deps: {
      clock: deps.clock,
      idGen: deps.idGen,
      changeSets: deps.changeSets,
      outbox: optional.outbox,
      authorize: deps.authorize,
    },
    command: {
      workspaceId: input.workspaceId,
      actor: input.actor,
      summary: `Update form definition '${input.formId}'`,
      idempotencyKey: optional.idempotencyKey,
      permission: deps.permission,
    },
    mutation: {
      entityType: "form_definition",
      entityId: input.formId,
      operation: "update",
      captureInverse: async () => null,
      execute: async () => {
        const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.formId });
        if (!existing) {
          throw new FormDefinitionNotFoundError({ message: `form definition '${input.formId}' was not found` });
        }

        const name = input.patch.name !== undefined ? input.patch.name : existing.name;
        if (input.patch.name !== undefined) {
          validateNameAndSlug(name, existing.slug, deps.reservedSlugs);
        }

        let fields = existing.fields;
        if (input.patch.fields !== undefined) {
          assertValidFields(input.patch.fields);
          const existingIds = new Set(existing.fields.map((f) => f.id));
          const newIds = new Set(input.patch.fields.map((f) => f.id));
          const missing = [...existingIds].filter((id) => !newIds.has(id));
          if (missing.length > 0) {
            throw new FormFieldValidationError({ message: `patch omits existing field id(s): ${missing.join(", ")} (behavior.spec.md §1.2)`, fieldErrors: missing.map((id) => ({ field: id, reason: "existing field ids cannot be removed" })) });
          }
          fields = input.patch.fields;
        }

        const notify = input.patch.notify !== undefined ? validateNotify(input.patch.notify) : existing.notify;

        const definition: FormDefinitionRecord = {
          ...existing,
          name,
          fields,
          notify,
          slug: existing.slug,
          updatedAt: kernelNowIso({ clock: deps.clock }),
        };
        await deps.repo.update(definition);
        return { definition };
      },
    },
  });

  return result;
}

export interface SetFormDefinitionStatusRequired {
  deps: FormWriteServiceDeps;
  input: {
    workspaceId: UUID;
    actor: CommandActor;
    formId: UUID;
    status: FormDefinitionStatus;
  };
}

/** Status changes preserve the row; deletion requires the separate trash lifecycle. */
export async function setFormDefinitionStatus(
  required: SetFormDefinitionStatusRequired,
  optional: FormWriteOptional = {}
): Promise<{ definition: FormDefinitionRecord }> {
  const { deps, input } = required;

  const { result } = await deps.executeCommand({
    deps: {
      clock: deps.clock,
      idGen: deps.idGen,
      changeSets: deps.changeSets,
      outbox: optional.outbox,
      authorize: deps.authorize,
    },
    command: {
      workspaceId: input.workspaceId,
      actor: input.actor,
      summary: `Set form definition '${input.formId}' status to '${input.status}'`,
      idempotencyKey: optional.idempotencyKey,
      permission: deps.permission,
    },
    mutation: {
      entityType: "form_definition",
      entityId: input.formId,
      operation: "update",
      captureInverse: async () => null,
      execute: async () => {
        const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.formId });
        if (!existing) {
          throw new FormDefinitionNotFoundError({ message: `form definition '${input.formId}' was not found` });
        }
        const definition: FormDefinitionRecord = {
          ...existing,
          status: input.status,
          updatedAt: kernelNowIso({ clock: deps.clock }),
        };
        await deps.repo.update(definition);
        return { definition };
      },
    },
  });

  return result;
}

export interface FormWriteOptional {
  idempotencyKey?: string;
  outbox?: import("@jini-ai/cms/core").OutboxPort;
}
export interface CreateFormDefinitionOptional extends FormWriteOptional { notify?: NotifyConfig; }

/**
 * @file A comments-scoped body sanitizer (SPEC-033 Non-Goals — no shared core `text` library
 * exists anywhere in this codebase for this to extract into; ADR-031 §2/§4's "core `text`
 * library" reference is design-forward, not something this spec can reuse). Strips HTML tags
 * entirely (comments render as plain text, never `dangerouslySetInnerHTML`-equivalent raw HTML on
 * any read path this spec builds) and collapses excess whitespace. Bounded, non-Turing-complete —
 * a fixed regex pass, not a parser.
 */
const TAG_PATTERN = /<[^>]*>/g;
const EXCESS_WHITESPACE = /[ \t]{2,}/g;
const EXCESS_BLANK_LINES = /\n{3,}/g;

/** Strips tags and normalizes whitespace; returns plain text without mutating the input.
 * @complexity O(n) time and space for n input characters.
 * @example sanitizeCommentBody({ raw: "<b>Hello</b>" }, {})
 */
export function sanitizeCommentBody({ raw }: { raw: string }, _optional: Record<string, never> = {}): string {
  return raw
    .replace(TAG_PATTERN, "")
    .replace(EXCESS_WHITESPACE, " ")
    .replace(EXCESS_BLANK_LINES, "\n\n")
    .trim();
}

const LINK_PATTERN = /https?:\/\/\S+/gi;

/** Counts HTTP(S) links in text; performs no I/O.
 * @complexity O(n) time and space for n input characters.
 * @example countLinks({ text: "https://example.com" }, {})
 */
export function countLinks({ text }: { text: string }, _optional: Record<string, never> = {}): number {
  return (text.match(LINK_PATTERN) ?? []).length;
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
/**
 * @file ADR-031 §3/§8 — the moderation write-service: wraps `CommentRepoPort.applyModeration`/
 * `purge` with outbox event emission and the `comments.statusChanged` action hook. Routes call
 * `authorize()` first (ADR-021 flat `comments.*` strings), then this service, never the repo
 * directly — the same "typed, core-owned write, no side-door" discipline ADR-023 §7 requires of
 * the repo itself, one layer up.
 */
import type { Clock as ClockPort, IdGenerator as IdGeneratorPort, UUID } from "@jini-ai/core/primitives";
import type { OutboxPort } from "../core/index.js";
import type { CommentHookRegistry } from "./hooks.js";
import type { CommentEventName, CommentRepoPort } from "./ports.js";
import type { CommentRecord, CommentStatus, ModerationAction, ModerationLogEntry } from "./types.js";

/**
 * Hands one comment's removal to whoever owns removal in this composition.
 *
 * Structurally typed ON PURPOSE — this file imports nothing from `features/trash`, exactly as
 * `post.ts`'s `RemovePostFn` does not. The composition root binds the real implementation (which
 * records the item for the Trash screen) and hands it in already bound to this domain's entity
 * type, so the moderation service never learns that a Trash exists.
 *
 * `display` is REQUIRED because the caller already holds the record: `applyModeration` returns the
 * updated row, so the two strings the Trash screen shows come from columns, with no second read and
 * no payload parse.
 */
export type RemoveCommentFn = (required: {
  workspaceId: string;
  id: string;
  display: { title: string; subtitle?: string | null };
  at: string;
  expectedVersion: number | null;
  actor: { principalId: string; pluginId?: string | null };
}) => Promise<{ ok: true; version: number | null } | { ok: false; reason: "not-found" | "version-changed" }>;

/**
 * Drops any removal record for a comment that has come back out of `trash` by a route other than a
 * Trash-screen restore — i.e. an ordinary moderation decision.
 *
 * This is the half of the pair it is easy to forget, and forgetting it is the expensive mistake:
 * without it, approving a trashed comment leaves a row in the index pointing at a comment that is
 * live on the page again, so the Trash screen offers to permanently delete published content.
 */
export type ForgetRemovedCommentFn = (required: { workspaceId: string; id: string }) => Promise<void>;

/**
 * Runs `fn` inside one database transaction. MUST be reentrant — see the composition root's runner.
 *
 * Structurally typed for the same reason as {@link RemoveCommentFn}: no trash import here.
 */
export type CommentTransactionRunner = <T>(fn: () => Promise<T>) => Promise<T>;

export interface CommentWriteServiceDeps {
  repo: CommentRepoPort;
  outbox: OutboxPort;
  hooks: CommentHookRegistry;
  clock: ClockPort;
  idGen: IdGeneratorPort;
  /** See {@link RemoveCommentFn}. Called only on the transition INTO `trash`. */
  remove: RemoveCommentFn;
  /** See {@link ForgetRemovedCommentFn}. Called only on the transition OUT of `trash`. */
  forgetRemoved: ForgetRemovedCommentFn;
  /**
   * Wraps the moderation write and the index write so they are both-or-neither. `applyModeration`
   * opens its own `better-sqlite3` transaction, which nests as a SAVEPOINT when one is already
   * open, so this runner may be the outer one.
   */
  runInTransaction: CommentTransactionRunner;
}

/** The one `CommentStatus` value that means "deleted" — the marker the Trash index mirrors. */
const TRASHED_STATUS: CommentStatus = "trash";

/** Longest body excerpt stored as the Trash row's subtitle; matches the backfill's `substr(...,120)`. */
const TRASH_SUBTITLE_MAX = 120;

/**
 * Raised when the moderation write landed but its Trash index write could not.
 *
 * Only reachable if the comment row changed between two statements of the same transaction, which
 * it cannot — so this is an invariant breach, not a runtime condition. It is thrown rather than
 * returned so the enclosing transaction rolls the moderation back: a comment hidden with no Trash
 * row is unrecoverable from the UI, which is strictly worse than a failed moderation the operator
 * can retry.
 */
export class CommentRemovalIndexError extends Error {}

export type ModerationResult =
  | { ok: true }
  | { ok: false; reason: "not-found" | "conflict"; currentVersion?: number | undefined };

const EVENT_NAME_BY_ACTION: Partial<Record<ModerationAction, CommentEventName>> = {
  approve: "comments.approved",
  mark_spam: "comments.marked_spam",
  trash: "comments.trashed",
};

// Inline object literal at the enqueue() call site (not a `CommentDomainEvent`-typed
// intermediate) — see ingress.ts's identical note on why: TS only infers a
// `Record<string, unknown>`-compatible index signature for a FRESH literal argument.
async function emitEvent(
  deps: CommentWriteServiceDeps,
  required: { workspaceId: UUID; name: CommentEventName; commentId: UUID; entryId: UUID; status: CommentStatus }
): Promise<void> {
  await deps.outbox.enqueue({
    id: deps.idGen.newId(),
    name: required.name,
    occurredAt: clockNowIso({ clock: deps.clock }),
    aggregateId: required.commentId,
    workspaceId: required.workspaceId,
    payload: { commentId: required.commentId, entryId: required.entryId, status: required.status },
  });
}

export interface CommentWriteService {
  applyModeration(required: {
    workspaceId: UUID;
    id: UUID;
    expectedVersion: number;
    action: ModerationAction;
    toStatus: CommentStatus;
    actorPrincipalId: UUID;
    /** The assistant's AI marker on the Trash row's `actor.pluginId` (2026-09-21, trash T4c) —
     *  unset by every non-assistant caller (the admin moderation route), so a human's own moderation
     *  stays human-only. Held here only for the transition into `trash` ({@link syncRemovalIndex});
     *  never persisted onto this domain's OWN moderation log, which has no such column. */
    actorPluginId?: UUID | null;
    note: string | null;
  }, optional?: Record<string, never>): Promise<ModerationResult>;

  purge(required: { workspaceId: UUID; id: UUID; actorPrincipalId: UUID; note: string | null }, optional?: Record<string, never>): Promise<ModerationResult>;
}

/**
 * Keeps the Trash index in step with a moderation decision that just landed.
 *
 * Keys off the TRANSITION, not off the target status, and takes the transition from
 * `log.fromStatus` — which `applyModeration` reads inside its own compare-and-set, so it is the one
 * signal here that cannot race a concurrent moderation. That is what makes both failure modes
 * unreachable rather than merely unlikely:
 *
 *  - **double index write** — `fromStatus !== trash` fires at most once per entry into the Trash,
 *    so a repeated `trash` action cannot add a second row (the index's own uniqueness is a second
 *    net, not the first one);
 *  - **stranded index row** — `fromStatus === trash` with any other target fires on every exit,
 *    including the ones that never touch the Trash screen, so an approved comment cannot stay
 *    listed as deleted.
 *
 * Runs inside the caller's transaction, so a throw here rolls the moderation back with it.
 *
 * @complexity O(1) — at most one delegated write.
 */
async function syncRemovalIndex(
  deps: CommentWriteServiceDeps,
  required: { at: string; log: ModerationLogEntry; record: CommentRecord; actorPluginId: UUID | null }
): Promise<void> {
  const from = required.log.fromStatus;
  const to = required.record.status;

  if (to === TRASHED_STATUS && from !== TRASHED_STATUS) {
    const removed = await deps.remove({
      workspaceId: required.record.workspaceId,
      id: required.record.id,
      // From the row `applyModeration` just returned — columns only, no second read.
      display: {
        title: `Comment on ${required.record.entryId}`,
        subtitle: required.record.bodyText.slice(0, TRASH_SUBTITLE_MAX),
      },
      at: required.at,
      // The version AFTER the flip: what the sweeper's compare-and-delete checks, and what a
      // restore bumps past so the item always survives a race.
      expectedVersion: required.record.version,
      actor: { principalId: required.log.actorPrincipalId, pluginId: required.actorPluginId },
    });
    if (!removed.ok) {
      throw new CommentRemovalIndexError(
        `comments: comment '${required.record.id}' was moved to trash but could not be indexed (${removed.reason})`
      );
    }
    return;
  }

  if (from === TRASHED_STATUS && to !== TRASHED_STATUS) {
    await deps.forgetRemoved({ workspaceId: required.record.workspaceId, id: required.record.id });
  }
}

export function createCommentWriteService(deps: CommentWriteServiceDeps, _optional: Record<string, never> = {}): CommentWriteService {
  return {
    async applyModeration(required) {
      // Pulled out before the spread below: `deps.repo.applyModeration` persists this domain's OWN
      // moderation log, which has no `actorPluginId` column — spreading it in would be an excess
      // property on a fresh object literal (a real `tsc` error, not just a lint nit). The Trash's
      // `actor.pluginId` is a SEPARATE concern, carried only as far as `syncRemovalIndex` below.
      const { actorPluginId, ...repoRequired } = required;
      const at = clockNowIso({ clock: deps.clock });
      const result = await deps.runInTransaction(async () => {
        const applied = await deps.repo.applyModeration({ ...repoRequired, at });
        if (!applied.ok) return applied;
        await syncRemovalIndex(deps, { at, log: applied.log, record: applied.record, actorPluginId: actorPluginId ?? null });
        return applied;
      });
      if (!result.ok) return result;

      await deps.hooks.runStatusChangedHooks({
        workspaceId: required.workspaceId,
        commentId: required.id,
        fromStatus: result.log.fromStatus,
        toStatus: result.record.status,
      });

      const eventName = EVENT_NAME_BY_ACTION[required.action];
      if (eventName) {
        await emitEvent(deps, {
          workspaceId: required.workspaceId,
          name: eventName,
          commentId: required.id,
          entryId: result.record.entryId,
          status: result.record.status,
        });
      }

      return { ok: true };
    },

    async purge(required) {
      const at = clockNowIso({ clock: deps.clock });
      const before = await deps.repo.findById({ workspaceId: required.workspaceId, id: required.id });
      const result = await deps.runInTransaction(async () => {
        const purged = await deps.repo.purge({ ...required, at });
        // The row is gone for good, so its index row would otherwise outlive it and offer the Trash
        // screen a "Restore" that can never succeed. Same both-or-neither transaction as the
        // moderation path above.
        if (purged.ok) await deps.forgetRemoved({ workspaceId: required.workspaceId, id: required.id });
        return purged;
      });
      if (!result.ok) return result;

      if (before) {
        await emitEvent(deps, {
          workspaceId: required.workspaceId,
          name: "comments.purged",
          commentId: required.id,
          entryId: before.entryId,
          status: before.status,
        });
      }

      return { ok: true };
    },
  };
}

/** A deliberately small CSS grammar: qualified rules, optionally inside width media queries.
 * Comments, strings and balanced functions are tokenized before structural punctuation is read.
 * The HTML resource scanner classifies remote URLs, not declarations/selectors; customization
 * needs this stricter grammar. Unknown CSS is rejected rather than repaired. */
export interface ConsentCssToken { kind: 'text' | 'string' | 'symbol' | 'space'; value: string; offset: number }
export interface ConsentCssDeclaration { property: string; value: string; offset: number }
export interface ConsentCssRule { selector: string; declarations: ConsentCssDeclaration[]; offset: number; media?: string }

export class ConsentCssSyntaxError extends Error {
  constructor(message: string, readonly offset: number) { super(message); }
}

/** Read a quoted CSS string; escape syntax is excluded by the compiler before parsing.
 * @throws ConsentCssSyntaxError for an unterminated string. @complexity O(string length). */
function quotedToken({ css, start }: { css: string; start: number }): ConsentCssToken {
  const end = css.indexOf(css[start]!, start + 1);
  if (end === -1 || /[\n\r\f]/.test(css.slice(start, end))) throw new ConsentCssSyntaxError('Unterminated CSS string.', start);
  return { kind: 'string', value: css.slice(start, end + 1), offset: start };
}

/** Read one lexical token; comment boundaries remain whitespace so identifiers never fuse.
 * @throws ConsentCssSyntaxError for unterminated comments/strings. @complexity O(token length). */
function nextToken({ css, state }: { css: string; state: { cursor: number } }): ConsentCssToken {
  const start = state.cursor;
  const char = css[start]!;
  if (css.startsWith('/*', start)) {
    const end = css.indexOf('*/', start + 2);
    if (end === -1) throw new ConsentCssSyntaxError('Unterminated CSS comment.', start);
    state.cursor = end + 2;
    return { kind: 'space', value: ' ', offset: start };
  }
  if ('"\''.includes(char)) {
    const token = quotedToken({ css, start }); state.cursor += token.value.length; return token;
  }
  state.cursor++;
  if ('{}:;(),!@[]'.includes(char)) return { kind: 'symbol', value: char, offset: start };
  if (/\s/.test(char)) return { kind: 'space', value: ' ', offset: start };
  while (state.cursor < css.length && !/[\s{}:;(),!@\[\]"']/.test(css[state.cursor]!) && !css.startsWith('/*', state.cursor)) state.cursor++;
  return { kind: 'text', value: css.slice(start, state.cursor), offset: start };
}

/** @throws ConsentCssSyntaxError for invalid tokens. @complexity O(n) time/space. */
function tokenize({ css }: { css: string }): ConsentCssToken[] {
  const tokens: ConsentCssToken[] = [];
  const state = { cursor: 0 };
  while (state.cursor < css.length) tokens.push(nextToken({ css, state }));
  return tokens;
}

/** @throws ConsentCssSyntaxError on mismatched brackets/functions. @complexity O(1). */
function trackGroup(token: ConsentCssToken, closing: string[]): void {
  if (token.kind !== 'symbol') return;
  if (token.value === '(') closing.push(')');
  if (token.value === '[') closing.push(']');
  if ([')', ']'].includes(token.value) && closing.pop() !== token.value) throw new ConsentCssSyntaxError('Unbalanced CSS group.', token.offset);
}

/** Consume structural delimiters only outside strings and balanced parentheses/brackets.
 * @throws ConsentCssSyntaxError for unbalanced groups. @complexity O(consumed tokens). */
function takeUntil({ tokens, state, delimiters }: { tokens: ConsentCssToken[]; state: { cursor: number }; delimiters: string }): string {
  const parts: string[] = [];
  const closing: string[] = [];
  while (state.cursor < tokens.length) {
    const token = tokens[state.cursor]!;
    if (token.kind === 'symbol' && !closing.length && delimiters.includes(token.value)) break;
    trackGroup(token, closing);
    parts.push(token.value); state.cursor++;
  }
  // A non-empty `closing` means this loop consumed the opener, so `cursor - 1` is a real token.
  if (closing.length) throw new ConsentCssSyntaxError('Unclosed CSS group.', tokens[state.cursor - 1]!.offset);
  return parts.join('').trim();
}

/** Parse a flat declaration list without splitting quoted/function semicolons.
 * @throws ConsentCssSyntaxError for malformed declarations. @complexity O(consumed tokens). */
function declarations({ tokens, state }: { tokens: ConsentCssToken[]; state: { cursor: number } }): ConsentCssDeclaration[] {
  const result: ConsentCssDeclaration[] = [];
  while (state.cursor < tokens.length) {
    if (tokens[state.cursor]!.kind === 'space') { state.cursor++; continue; }
    if (tokens[state.cursor]!.value === '}') { state.cursor++; return result; }
    if (tokens[state.cursor]!.value === ';') { state.cursor++; continue; }
    result.push(declaration({ tokens, state }));
  }
  // Only entered after the rule's `{` was consumed, so `cursor - 1` is always a real token.
  throw new ConsentCssSyntaxError('Unclosed CSS rule.', tokens[state.cursor - 1]!.offset);
}

/** @throws ConsentCssSyntaxError for malformed properties/values. @complexity O(consumed tokens). */
function declaration({ tokens, state }: { tokens: ConsentCssToken[]; state: { cursor: number } }): ConsentCssDeclaration {
  const offset = tokens[state.cursor]!.offset;
  const property = takeUntil({ tokens, state, delimiters: ':;{}' });
  if (tokens[state.cursor]?.value !== ':') throw new ConsentCssSyntaxError('Expected a CSS property followed by a colon.', offset);
  state.cursor++;
  const value = takeUntil({ tokens, state, delimiters: ';{}' });
  if (![';', '}'].includes(tokens[state.cursor]?.value ?? '')) throw new ConsentCssSyntaxError('Expected a semicolon or closing brace.', offset);
  if (tokens[state.cursor]?.value === ';') state.cursor++;
  return { property: property.toLowerCase(), value, offset };
}

type RuleInput = { tokens: ConsentCssToken[]; state: { cursor: number }; media?: string };

/** Read one non-nested rule; the compiler validates every selector and declaration.
 * @throws ConsentCssSyntaxError for unsupported syntax. @complexity O(consumed tokens). */
function qualifiedRule({ tokens, state, media }: RuleInput, _options = {}): ConsentCssRule {
  const offset = tokens[state.cursor]!.offset;
  const selector = takeUntil({ tokens, state, delimiters: '{};@' });
  if (!selector || tokens[state.cursor]?.value !== '{') throw new ConsentCssSyntaxError('Expected a scoped CSS rule.', offset);
  state.cursor++;
  return { selector, declarations: declarations({ tokens, state }), offset, ...(media === undefined ? {} : { media }) };
}

/** Width queries are the only supported at-rule; no imports, nested queries or feature rules.
 * @throws ConsentCssSyntaxError for unsupported queries. @complexity O(consumed tokens). */
function mediaRules({ tokens, state, media }: RuleInput, _options = {}): ConsentCssRule[] {
  const offset = tokens[state.cursor]!.offset;
  if (media !== undefined) throw new ConsentCssSyntaxError('Nested media queries are not supported.', offset);
  state.cursor++;
  const header = takeUntil({ tokens, state, delimiters: '{};@' });
  const match = /^media\s*((?:screen\s+and\s+)?\((?:min|max)-width:\s*\d{1,4}(?:\.\d+)?px\)(?:\s+and\s+\((?:min|max)-width:\s*\d{1,4}(?:\.\d+)?px\))?)$/.exec(header);
  if (!match || tokens[state.cursor]?.value !== '{') throw new ConsentCssSyntaxError('Only width @media queries are supported.', offset);
  state.cursor++;
  return ruleList({ tokens, state, media: match[1]! });
}

/** Flatten one level of media rules, preserving their conditions for safe emission.
 * @throws ConsentCssSyntaxError for unclosed/nested blocks. @complexity O(consumed tokens). */
function ruleList(input: RuleInput, _options = {}): ConsentCssRule[] {
  const { tokens, state, media } = input;
  const rules: ConsentCssRule[] = [];
  while (state.cursor < tokens.length) {
    const token = tokens[state.cursor]!;
    if (token.kind === 'space') { state.cursor++; continue; }
    if (token.value === '}' && media !== undefined) { state.cursor++; return rules; }
    if (token.value === '@') { rules.push(...mediaRules(input)); continue; }
    rules.push(qualifiedRule(input));
  }
  if (media !== undefined) throw new ConsentCssSyntaxError('Unclosed media query.', tokens[state.cursor - 1]!.offset);
  return rules;
}

/** Internal AST parser; the compiler adds size/character, selector and declaration allowlists.
 * @example parseConsentCss({ css: '@media(max-width:640px){#jini-consent{padding:12px}}' })
 * @throws ConsentCssSyntaxError for unsupported/malformed syntax. @complexity O(n) time/space. */
export function parseConsentCss({ css }: { css: string }, _options = {}): ConsentCssRule[] {
  return ruleList({ tokens: tokenize({ css }), state: { cursor: 0 } });
}

import type { ConsentAppearanceTokens } from './types.js';
import { ConsentCssSyntaxError, parseConsentCss, type ConsentCssDeclaration, type ConsentCssRule } from './css-parser.js';

export const CONSENT_CSS_SCOPE = '#jini-consent[data-has-record="false"]';
export const CONSENT_MAX_CSS_LENGTH = 16_384;
/** Exact surfaces only: Reject/Accept share styling; the no-sale text row has its own surface. */
export const CONSENT_CSS_SELECTORS = Object.freeze([
  CONSENT_CSS_SCOPE, `${CONSENT_CSS_SCOPE} h2`, `${CONSENT_CSS_SCOPE} p`,
  `${CONSENT_CSS_SCOPE} button`, `${CONSENT_CSS_SCOPE} a`,
  `${CONSENT_CSS_SCOPE} summary`, `${CONSENT_CSS_SCOPE} details`,
  `${CONSENT_CSS_SCOPE} #jini-consent-do-not-sell`,
  `${CONSENT_CSS_SCOPE} .jini-consent-initial`, `${CONSENT_CSS_SCOPE} .jini-consent-actions`,
]);

export interface ConsentCssProblem {
  code: 'size' | 'syntax' | 'selector' | 'property' | 'value' | 'contrast';
  message: string;
  /** Zero-based customCss offset; token diagnostics use 0, aggregate diagnostics omit it. */
  offset?: number;
  selector?: string;
  property?: string;
}
export interface ConsentCssResult {
  /** Validated customization followed by the engine parity block; safe defaults on any problem. */
  css: string;
  problems: ConsentCssProblem[];
}

const TOKEN_PROPERTIES: Record<keyof ConsentAppearanceTokens, string> = {
  backgroundColor: 'background-color', textColor: 'color', borderColor: 'border-color',
  borderRadius: 'border-radius', padding: 'padding', fontSize: 'font-size', maxWidth: 'max-width',
};
const DEFAULT_COLORS = { background: '#ffffff', text: '#222222' };
type Colors = typeof DEFAULT_COLORS;

/** Opaque hex only: functions, variables, alpha and currentColor cannot hide notice text.
 * @complexity O(1); accepted color length is fixed. */
function isColor(value: string): boolean { return /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(value); }

/** Absolute lengths keep bounds independent of the host's root font/viewport dimensions.
 * @complexity O(value length). */
function pixels(value: string): number {
  if (value === '0') return 0;
  const match = /^(\d+(?:\.\d+)?)px$/.exec(value);
  return match ? Number(match[1]) : NaN;
}

/** @complexity O(value length); no negative, percentage, viewport or calculated dimensions. */
function boundedLength(value: string, min: number, max: number): boolean {
  const size = pixels(value);
  return Number.isFinite(size) && size >= min && size <= max;
}

/** Bounded non-negative spacing cannot move required controls off screen.
 * @complexity O(value length), with at most four accepted lengths. */
function lengthList({ value, min = 0, max = 32, count = 4 }: { value: string; min?: number; max?: number; count?: number }, _options = {}): boolean {
  const parts = value.split(/\s+/);
  return parts.length <= count && parts.every(part => boundedLength(part, min, max));
}

/** Alpha is permitted only for shadows, never for text or control fills.
 * @complexity O(value length); channels and alpha have fixed bounds. */
function shadowColor({ value }: { value: string }, _options = {}): boolean {
  if (isColor(value)) return true;
  const match = /^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(0(?:\.\d+)?|1(?:\.0+)?|\.\d+)\s*\)$/.exec(value);
  return match !== null && match.slice(1, 4).every(channel => Number(channel) <= 255);
}

/** A bounded shadow cannot cover the page or disguise the banner with a huge spread.
 * @complexity O(value length). */
function isShadow({ value }: { value: string }, _options = {}): boolean {
  if (value === 'none') return true;
  const colorStart = value.search(/#|rgba\(/i);
  const prefix = value.slice(0, colorStart);
  if (colorStart < 0 || !/\s$/.test(prefix)) return false;
  const lengths = prefix.trim().split(/\s+/);
  if (lengths.length < 3 || lengths.length > 4) return false;
  return lengths.every((part, index) => boundedLength(part, 0, [24, 24, 64, 8][index]!)) && shadowColor({ value: value.slice(colorStart) });
}

const VALUE_RULES: Record<string, (value: string) => boolean> = {
  'background-color': isColor, color: isColor, 'border-color': isColor,
  'border-radius': value => lengthList({ value }),
  padding: value => lengthList({ value }),
  margin: value => lengthList({ value }),
  'margin-top': value => boundedLength(value, 0, 32),
  'margin-left': value => boundedLength(value, 0, 32),
  gap: value => lengthList({ value, count: 2 }),
  'line-height': value => /^(?:1(?:\.\d+)?|2(?:\.0+)?)$/.test(value),
  'min-height': value => boundedLength(value, 24, 64),
  'font-size': value => boundedLength(value, 12, 24),
  'max-width': value => value === '100%' || boundedLength(value, 256, 960),
  'box-shadow': value => isShadow({ value }),
};
const ROOT_ONLY: ReadonlySet<string> = new Set(['background-color', 'color', 'max-width', 'box-shadow']);

/** Decode an already validated opaque hex color to sRGB channels. @complexity O(1). */
function colorChannels({ color }: { color: string }, _options = {}): number[] {
  const hex = color.length === 4 ? color.slice(1).split('').map(char => char + char).join('') : color.slice(1);
  return [0, 2, 4].map(offset => parseInt(hex.slice(offset, offset + 2), 16) / 255);
}

/** WCAG relative luminance of normalized sRGB channels. @complexity O(1). */
function luminance({ channels }: { channels: number[] }, _options = {}): number {
  const linear = channels.map(value => value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
  return linear[0]! * 0.2126 + linear[1]! * 0.7152 + linear[2]! * 0.0722;
}

/** Fail closed on low-contrast banner and button fills, including declarations overriding tokens.
 * @complexity O(1). */
function hasContrast({ background, text }: Colors, _options = {}): boolean {
  const bg = colorChannels({ color: background }); const fg = colorChannels({ color: text });
  const b = luminance({ channels: fg });
  // Match the base CSS's sRGB mixes before linearizing for WCAG contrast.
  return [0, 0.07, 0.13].every(weight => {
    const a = luminance({ channels: bg.map((channel, index) => channel * (1 - weight) + fg[index]! * weight) });
    return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05) >= 4.5;
  });
}

/** Normalize only the two public root spellings and whitespace; no general selector rewriting.
 * @complexity O(selector length). */
function scopedSelector(selector: string): string {
  const normalized = selector.trim().replace(/\s+/g, ' ');
  if (normalized === CONSENT_CSS_SCOPE || normalized.startsWith(`${CONSENT_CSS_SCOPE} `)) return normalized;
  return normalized.replace(/^(?:#jini-consent|\.jini-consent)(?= |$)/, CONSENT_CSS_SCOPE);
}

/** One declaration policy shared by tokens and parsed CSS; only bounded shadow functions pass.
 * @complexity O(value length). */
function declarationProblem({ declaration, selector, media }: { declaration: ConsentCssDeclaration; selector: string; media?: string }, _options = {}): ConsentCssProblem | null {
  const { property, value, offset } = declaration;
  if (!Object.hasOwn(VALUE_RULES, property)) return { code: 'property', message: `The property "${property}" is not allowed.`, offset, selector, property };
  const validate = VALUE_RULES[property]!;
  if (ROOT_ONLY.has(property) && selector !== CONSENT_CSS_SCOPE) return { code: 'property', message: `Set "${property}" on the banner root so all controls inherit the same readable appearance.`, offset, selector, property };
  const context = contextProblem({ declaration, selector, ...(media === undefined ? {} : { media }) });
  if (context) return context;
  if (!validate(value)) return { code: 'value', message: `The value of "${property}" is outside the supported safe subset. Resources and !important are not allowed.`, offset, selector, property };
  return null;
}

/** Context restrictions protect readable palettes and prevent inflated text blocks.
 * @complexity O(value length), bounded by the compiler input cap. */
function contextProblem({ declaration, selector, media }: { declaration: ConsentCssDeclaration; selector: string; media?: string }, _options = {}): ConsentCssProblem | null {
  const { property, value, offset } = declaration;
  // MOVE: Conditional palettes need per-query contrast analysis; width queries customize geometry only.
  if (media && ['background-color', 'color'].includes(property)) return { code: 'property', message: 'Set text and background colors outside media queries so contrast is verified for every viewport.', offset, selector, property };
  if (property === 'padding' && selector === CONSENT_CSS_SCOPE && !lengthList({ value, min: 8 })) return { code: 'value', message: 'Banner padding must be between 8px and 32px on every side.', offset, selector, property };
  if (property === 'min-height' && !['button', 'a', 'summary', '#jini-consent-do-not-sell'].some(control => selector === `${CONSENT_CSS_SCOPE} ${control}`)) return { code: 'property', message: 'Set min-height only on buttons, links and summaries.', offset, selector, property };
  return null;
}

/** Validate all rules before emitting any user CSS; one bad member rejects the entire batch.
 * @complexity O(n) time/space for bounded CSS bytes; selector list and property table are fixed. */
function validateRules({ rules }: { rules: ConsentCssRule[] }): ConsentCssProblem[] {
  return rules.flatMap(rule => [...new Set(rule.selector.split(',').map(scopedSelector))]
    .flatMap(selector => surfaceProblems({ rule, selector })));
}

/** Deduplicated valid selectors have a fixed allowlist, bounding declaration checks.
 * @complexity O(declarations) for a known surface, O(1) otherwise. */
function surfaceProblems({ rule, selector }: { rule: ConsentCssRule; selector: string }, _options = {}): ConsentCssProblem[] {
  if (!CONSENT_CSS_SELECTORS.includes(selector)) return [{ code: 'selector', message: 'Use an allowlisted banner surface selector; separate Reject/Accept selectors and pseudo-elements are not allowed.', offset: rule.offset, selector }];
  return rule.declarations.map(declaration => declarationProblem({ declaration, selector, ...(rule.media === undefined ? {} : { media: rule.media }) })).filter((problem): problem is ConsentCssProblem => problem !== null);
}

/** Convert host tokens to the same declaration AST instead of introducing another validator.
 * @complexity O(token count), bounded by the CSS size check in the compiler. */
function tokenRule(tokens: ConsentAppearanceTokens): ConsentCssRule {
  const declarations = Object.entries(tokens).map(([key, value]) => ({
    property: Object.hasOwn(TOKEN_PROPERTIES, key) ? TOKEN_PROPERTIES[key as keyof ConsentAppearanceTokens] : key,
    value: Object.hasOwn(TOKEN_PROPERTIES, key) && typeof value === 'string' ? value : '', offset: 0,
  }));
  return { selector: CONSENT_CSS_SCOPE, declarations, offset: 0 };
}

/** Last root color declaration wins across tokens and user rules, matching emitted cascade.
 * Null means no color was customized, so the theme-token colors of the base styles stay in charge;
 * one customized side is checked against the engine default of the other.
 * @complexity O(n) for declarations; never mutates caller input. */
function finalColors(rules: ConsentCssRule[]): Colors | null {
  let colors: Colors | null = null;
  const declarations = rules.filter(rule => rule.selector.split(',').some(selector => scopedSelector(selector) === CONSENT_CSS_SCOPE)).flatMap(rule => rule.declarations);
  for (const { property, value } of declarations) {
    if (property === 'background-color') colors = { ...(colors ?? DEFAULT_COLORS), background: value };
    if (property === 'color') colors = { ...(colors ?? DEFAULT_COLORS), text: value };
  }
  return colors;
}

/** Engine-owned lock follows all customization. Native details/hidden semantics remain intact;
 * placement stays shared by the initial banner and saved-choice panel. Controls inherit the
 * root's colors; shared action fills/borders use engine variables, while links and summaries stay
 * unboxed. With no customized colors, theme-token colors and typography remain in charge.
 * @complexity O(1). */
function parityCss({ colors }: { colors: Colors | null }, _options = {}): string {
  const root = CONSENT_CSS_SCOPE;
  // MOVE: Derived text and button fills must use the same validated palette as the root.
  const rootColors = colors ? `--consent-bg:${colors.background}!important;--consent-fg:${colors.text}!important;background:${colors.background}!important;color:${colors.text}!important;` : '';
  return `\n/* ENGINE PARITY BLOCK */
#jini-consent{position:fixed!important;z-index:2147483647!important;visibility:visible!important;opacity:1!important;transform:none!important;clip:auto!important;clip-path:none!important;filter:none!important;pointer-events:auto!important;isolation:isolate!important}
${root}{display:block!important;${rootColors}background-image:none!important;min-width:0!important;max-height:85dvh!important;overflow:auto!important;box-sizing:border-box!important}
${root} :is(h2,p,label,legend,fieldset,details,form,.jini-consent-initial,.jini-consent-actions){background:transparent!important}
${root} :is(h2,p,label,legend,details,form,.jini-consent-initial,.jini-consent-actions){color:inherit!important}
${root} .jini-consent-actions{display:grid!important}
${root} :is(button,a,summary){visibility:visible!important;opacity:1!important;transform:none!important;clip-path:none!important;filter:none!important;pointer-events:auto!important;color:inherit!important}
${root} :is(a,summary){background:transparent!important;border:0!important}
${root} .jini-consent-actions button{background:var(--consent-button-bg)!important;border:1px solid var(--consent-button-border)!important}
${root} .jini-consent-actions button:hover{background:var(--consent-button-hover-bg)!important}
${root} #jini-consent-do-not-sell{background:transparent!important;border:0!important}
${root} button{display:inline-flex!important;align-items:center!important;justify-content:center!important;min-width:0!important;max-width:100%!important;white-space:normal!important;overflow-wrap:anywhere!important}
${root} a{display:inline-flex!important;align-items:center!important;max-width:100%!important;overflow-wrap:anywhere!important;text-decoration:underline!important}
#jini-consent :focus-visible{outline:3px solid currentColor!important;outline-offset:2px!important}
@media(max-width:640px){#jini-consent{inset:auto 0 0!important;width:100%!important;margin:0!important}}
`;
}

/** Reject syntax that could change token boundaries or break out of the HTML style sink.
 * CSS resource functions, unsupported at-rules and selectors are rejected by AST policy too.
 * @complexity O(n). */
function inputProblem(css: unknown): ConsentCssProblem | null {
  // Stored settings are JSON from the host; a wrong shape must not turn every page inert.
  if (typeof css !== 'string') return { code: 'syntax', message: 'Custom CSS and appearance tokens must be text and an object of text values.' };
  if (css.length > CONSENT_MAX_CSS_LENGTH) return { code: 'size', message: `Custom CSS must be at most ${CONSENT_MAX_CSS_LENGTH} characters.` };
  // `>` stays parseable so a child combinator gets a selector diagnostic; `<` alone can open `</style`.
  if (/[\\<\x00-\x08\x0b\x0e-\x1f\x7f]/.test(css)) return { code: 'syntax', message: 'CSS escapes, HTML delimiters and control characters are not allowed.' };
  return null;
}

/** Tokens are bounded by their serialized size; a non-object shape is reported, never thrown.
 * @complexity O(token bytes). */
function tokenText(tokens: unknown): string | null {
  return tokens !== null && typeof tokens === 'object' && !Array.isArray(tokens) ? JSON.stringify(tokens) : null;
}

/** Emit the validated AST, or discard the complete appearance on a policy/contrast problem.
 * @complexity O(n) time/space; all emitted values have passed the shared declaration policy. */
function compileRules({ rules }: { rules: ConsentCssRule[] }, _options = {}): ConsentCssResult {
  const problems = validateRules({ rules });
  const colors = problems.length ? null : finalColors(rules);
  if (colors && !hasContrast(colors)) problems.push({ code: 'contrast', message: 'Banner text must have at least 4.5:1 contrast against the background and button fills.' });
  if (problems.length) return { css: parityCss({ colors: null }), problems };
  const compiled = rules.filter(rule => rule.declarations.length).map(rule => emitRule({ rule })).join('\n');
  return { css: `${compiled ? '\n' + compiled : ''}${parityCss({ colors })}`, problems: [] };
}

/** Emit only validated selectors/declarations, retaining their optional width condition.
 * @complexity O(rule bytes) time/space; does not evaluate authored code. */
function emitRule({ rule }: { rule: ConsentCssRule }, _options = {}): string {
  const css = `${rule.selector.split(',').map(scopedSelector).join(',')}{${rule.declarations.map(({ property, value }) => `${property}:${value}`).join(';')}}`;
  return rule.media === undefined ? css : `@media ${rule.media}{${css}}`;
}

/** Validate/compile first-visit appearance for both admin preview and delivery. No DOM or I/O.
 * Presets render first, then tokens, then parsed allowlisted CSS, then engine visibility/parity.
 * Any problem discards the complete customization and returns safe engine defaults plus diagnostics.
 * @example compileConsentCss({ css: '#jini-consent{font-size:13.5px;padding:14px 16px}' })
 * @complexity O(n) time/space, with custom CSS and tokens each capped at 16 KiB. */
export function compileConsentCss({ css = '', tokens = {} }: { css?: string; tokens?: ConsentAppearanceTokens }, _options = {}): ConsentCssResult {
  const problem = inputProblem(css) ?? inputProblem(tokenText(tokens));
  if (problem) return { css: parityCss({ colors: null }), problems: [problem] };
  let rules: ConsentCssRule[];
  try { rules = [tokenRule(tokens), ...parseConsentCss({ css })]; }
  catch (error) {
    if (!(error instanceof ConsentCssSyntaxError)) throw error;
    return { css: parityCss({ colors: null }), problems: [{ code: 'syntax', message: error.message, offset: error.offset }] };
  }
  return compileRules({ rules });
}

import { randomUUID } from 'node:crypto';
import express, { type Express, type Request, type Response } from 'express';
import { createConsentRecord, googleConsentSignals, readConsentRecord, resolveConsentChoices, resolveConsentRegion } from '../policy.js';
import { CONSENT_MAX_AGE_MS, DENIED_CHOICES, type ConsentChoices, type ConsentConfig, type ConsentRecord, type ConsentRecordPort, type ConsentAnalyticsProof } from '../types.js';
export type { ConsentAnalyticsProof } from '../types.js';
import { gateConsentHtml } from '../html/index.js';
import { inertConsentBody, captureConsentHtml, CONSENT_MAX_HTML_BYTES } from './response.js';
import type { ConsentGateOptions } from '../html/gate.js';
export { captureConsentHtml } from './response.js';

export type ConsentReceiptProof = { id: string | null; present: boolean };

/** All host effects are explicit. Region defaults to unknown; no geo service is required. */
export interface ConsentHttpPorts {
  config: { get(required: Record<string, never>, optional?: Record<string, never>): Promise<ConsentConfig> };
  records: ConsentRecordPort;
  clock: { nowMs(): number; nowIso(): string };
  ids: { newId(): string };
  /** Prefer { id, present }; legacy null readers use the configured cookie name to retain invalid presence. */
  readReceiptId(required: { cookieHeader: string }, optional?: Record<string, never>): string | null | ConsentReceiptProof;
  origin(required: { request: Request }, optional?: Record<string, never>): string;
  region(required: { request: Request }, optional?: Record<string, never>): string | null;
  allowWrite(required: { request: Request }, optional?: Record<string, never>): Promise<boolean>;
  reportError(required: { operation: 'read' | 'save'; error: unknown }, optional?: Record<string, never>): void;
}

/** Receipt reads need only these ports, so request-level readers can take a narrower bag. */
type ConsentReceiptPorts = Pick<ConsentHttpPorts, 'records' | 'clock' | 'readReceiptId' | 'reportError'>;

/** Shared by the page gate, the choice endpoint and request-level reads. */
const DEFAULT_CONSENT_COOKIE_NAME = 'jini_consent';

/** Whether a request can serve consent-gated public HTML; admin/API validators stay intact.
 * @example isPublicPage({ request }); @complexity O(path length), O(1) space, no I/O. */
export function isPublicPage({ request }: { request: Pick<Request, 'method' | 'path'> }, _options = {}): boolean {
  return ['GET', 'HEAD'].includes(request.method) && !/^\/(?:admin|api|theme-assets|assets|\.well-known)(?:\/|$)/.test(request.path);
}

/** Structured readers retain malformed-cookie presence. Legacy readers returning null are
 * checked against the configured cookie name, so they cannot mistake invalid proof for absence.
 * @complexity O(cookie header length), bounded by the HTTP server. */
function receiptProof({ cookieHeader, cookieName, ports }: { cookieHeader: string; cookieName: string; ports: Pick<ConsentHttpPorts, 'readReceiptId'> }): ConsentReceiptProof {
  const value = ports.readReceiptId({ cookieHeader });
  if (value !== null && typeof value === 'object') return value;
  const present = value !== null || cookieHeader.split(';').some(part => part.split('=', 1)[0]?.trim() === cookieName);
  return { id: value, present };
}

/** Missing/malformed IDs never reach storage. Changed policy versions require another choice.
 * Only a visitor without a receipt cookie is new: a cookie whose receipt is missing (evicted,
 * deleted, another store) is failed proof, so opt-out regions cannot turn a lost rejection into a grant.
 * @complexity O(1) and at most one bounded record read. */
async function currentRecord({ request, ports, config }: { request: Request; ports: ConsentReceiptPorts; config: ConsentConfig }, { cookieName }: { cookieName: string }): Promise<{ record: ConsentRecord | null; failed: boolean }> {
  try {
    const { id, present } = receiptProof({ cookieHeader: request.get('cookie') ?? '', cookieName, ports });
    if (!present) return { record: null, failed: false };
    if (typeof id !== 'string' || !/^[a-zA-Z0-9_-]{16,128}$/.test(id)) throw new Error('The consent receipt cookie is invalid. Optional content stays denied; choose cookie preferences again.');
    const value = await ports.records.read({ id });
    const record = readConsentRecord({ value, policyVersion: config.policyVersion, nowMs: ports.clock.nowMs() });
    if (record === null) {
      ports.reportError({ operation: 'read', error: new Error(value === null || value === undefined ? 'The consent receipt named by the visitor cookie is unavailable; optional content stays denied until the visitor chooses again.' : 'The stored consent receipt is invalid or expired. Optional content stays denied; choose cookie preferences again.') });
      return { record: null, failed: true };
    }
    return { record, failed: false };
  } catch (error) {
    // Corrupt, oversized or unreadable proof is absence, never a visitor-wide outage.
    ports.reportError({ operation: 'read', error });
    return { record: null, failed: true };
  }
}

/** Browsers supply Origin on normal POST; Referer supports progressively enhanced no-JS forms.
 * Refuse a request with neither, and ignore caller-selected redirect destinations.
 * @complexity O(header length), bounded by the HTTP server. */
function sameOrigin(request: Request, origin: string): boolean {
  const source = request.get('origin') ?? request.get('referer');
  if (!source) return false;
  try { return new URL(source).origin === new URL(origin).origin; } catch { return false; }
}

function respondError(response: Response, status: number, error: string): void {
  response.status(status).json({ error });
}

export type ConsentDelivery = 'live' | 'static';
export type ConsentHttpOptions = { endpoint?: string; cookieName?: string; nonce?: string | ((required: { request: Request; response: Response }) => string | undefined); necessaryScripts?: ConsentGateOptions['necessaryScripts']; resourceOrigins?: ConsentGateOptions['resourceOrigins'] | ((required: { request: Request }) => readonly string[]); categoryOrigins?: ConsentGateOptions['categoryOrigins']; delivery?: ConsentDelivery | ((required: { request: Request }) => ConsentDelivery); maxHtmlBytes?: number };

const UNAVAILABLE_CONFIG: ConsentConfig = { enabled: true, regionMode: 'opt-in', policyVersion: 'unavailable', privacyPolicyUrl: '', title: 'Cookie preferences', message: 'Optional content is paused while preferences are unavailable.', acceptLabel: 'Accept all', rejectLabel: 'Reject non-essential', preferencesLabel: 'Cookie preferences' };

/** A port or validation failure while building the receipt is the visitor's 400, never a 500.
 * @complexity O(form fields). */
function newRecord({ request, ports, config }: { request: Request; ports: ConsentHttpPorts; config: ConsentConfig }): { record: ConsentRecord } | { error: string } {
  const gpc = request.get('sec-gpc') === '1' || request.body?.gpc === '1';
  try {
    return { record: createConsentRecord({ fields: request.body ?? {}, config, id: ports.ids.newId(), timestamp: ports.clock.nowIso(), regionMode: resolveConsentRegion({ configuredMode: config.regionMode, region: ports.region({ request }) }), gpc }) };
  } catch (error) { return { error: error instanceof Error ? error.message : 'Invalid cookie preferences.' }; }
}

/** Return to the same-origin page that posted the no-JS form, else home. The caller has already
 * checked sameOrigin for this request. @complexity O(header length). */
function redirectDestination({ request, origin }: { request: Request; origin: string }): string {
  const referer = request.get('referer');
  if (!referer) return '/';
  const url = new URL(referer, origin);
  // A root path beginning // would become a cross-origin Location header.
  return url.origin === new URL(origin).origin && !url.pathname.startsWith('//') ? url.pathname + url.search : '/';
}

/** Durable proof precedes cookie issuance. @complexity O(1), one durable write. */
async function saveChoice({ request, response, ports }: { request: Request; response: Response; ports: ConsentHttpPorts }, { cookieName }: { cookieName: string }): Promise<void> {
  const origin = ports.origin({ request });
  if (!sameOrigin(request, origin)) return respondError(response, 403, 'Cookie preferences must be saved from this site.');
  if (!await ports.allowWrite({ request })) return respondError(response, 429, 'Too many cookie preference changes. Please try again later.');
  const config = await ports.config.get({});
  if (!config.enabled) return respondError(response, 409, 'Cookie consent is disabled on this site.');
  const created = newRecord({ request, ports, config });
  if ('error' in created) return respondError(response, 400, created.error);
  const { record } = created;
  const previous = receiptProof({ cookieHeader: request.get('cookie') ?? '', cookieName, ports }).id;
  await ports.records.save({ record });
  await retirePreviousReceipt({ previous, ports });
  response.cookie(cookieName, record.id, { httpOnly: true, sameSite: 'lax', secure: new URL(origin).protocol === 'https:', path: '/', maxAge: CONSENT_MAX_AGE_MS });
  if (request.get('accept')?.includes('application/json')) { response.json({ record, signals: googleConsentSignals({ choices: record.choices }) }); return; }
  response.redirect(303, redirectDestination({ request, origin }));
}

async function retirePreviousReceipt({ previous, ports }: { previous: string | null; ports: ConsentHttpPorts }): Promise<void> {
  // A replaced receipt must not authorize detached work. Retire before the new receipt is
  // acknowledged; adapters retain the immutable original outside active lookup.
  if (previous && /^[a-zA-Z0-9_-]{16,128}$/.test(previous)) await ports.records.retire?.({ id: previous });
}

/** On a read failure retain only an enabled last good policy; otherwise deny optional content.
 * A stale OFF policy cannot establish that a newer publication still allows ungated HTML.
 * @complexity O(1), one config read. */
async function deliveryConfig({ ports, state }: { ports: ConsentHttpPorts; state: { lastGood?: ConsentConfig } }, _options = {}): Promise<{ config: ConsentConfig; failed: boolean }> {
  try {
    const config = await ports.config.get({});
    state.lastGood = config;
    return { config, failed: false };
  } catch (error) {
    ports.reportError({ operation: 'read', error });
    return { config: state.lastGood?.enabled ? state.lastGood : UNAVAILABLE_CONFIG, failed: true };
  }
}

/** @complexity O(1). */
function gateOptions({ request, response }: { request: Request; response: Response }, { nonce, necessaryScripts, resourceOrigins, categoryOrigins }: ConsentHttpOptions): ConsentGateOptions {
  const requestNonce = typeof nonce === 'function' ? nonce({ request, response }) : nonce;
  const origins = typeof resourceOrigins === 'function' ? resourceOrigins({ request }) : resourceOrigins;
  return { runtimeToken: randomUUID(), ...(requestNonce === undefined ? {} : { nonce: requestNonce }), ...(necessaryScripts === undefined ? {} : { necessaryScripts }), ...(origins === undefined ? {} : { resourceOrigins: origins }), ...(categoryOrigins === undefined ? {} : { categoryOrigins }) };
}

/** Gate one enabled HTML body; any failure returns inert text under the blocking policy.
 * @complexity O(HTML bytes), at most one receipt read. */
async function gatedBody({ body, request, response, ports, config, failed, mode, endpoint }: { body: Buffer; request: Request; response: Response; ports: ConsentHttpPorts; config: ConsentConfig; failed: boolean; mode: ConsentDelivery; endpoint: string }, options: ConsentHttpOptions = {}): Promise<Buffer> {
  try {
    const encoding = response.getHeader('Content-Encoding');
    if (encoding && encoding !== 'identity') throw new Error('Consent requires uncompressed HTML. Mount consent before compression and retry this page.');
    const receipt = failed ? { record: null, failed: false } : await currentRecord({ request, ports, config }, { cookieName: options.cookieName ?? DEFAULT_CONSENT_COOKIE_NAME });
    const regionMode = failed || receipt.failed ? 'opt-in' : resolveConsentRegion({ configuredMode: config.regionMode, region: ports.region({ request }) });
    return Buffer.from(gateConsentHtml({ html: body.toString('utf8'), config, record: receipt.record, regionMode, gpc: mode === 'live' && request.get('sec-gpc') === '1', endpoint }, { ...gateOptions({ request, response }, options), pageOrigin: ports.origin({ request }), ensureReopenLink: mode === 'static' }));
  } catch (error) {
    ports.reportError({ operation: 'read', error });
    // Fetch CSP cannot block meta refresh or first-party pixels, so never return failed HTML.
    return inertConsentBody({ response });
  }
}

type DeliveryPolicy = { config: ConsentConfig; failed: boolean; mode: ConsentDelivery } | null;

/** Shared preflight for ordinary and oversized HTML. Disabled sites remain byte-identical;
 * static exports use denied defaults rather than publishing the exporter's saved grants.
 * @complexity O(1), one config read and no receipt access. */
async function prepareDelivery({ request, response, ports, state }: { request: Request; response: Response; ports: ConsentHttpPorts; state: { lastGood?: ConsentConfig } }, { delivery }: ConsentHttpOptions = {}): Promise<DeliveryPolicy> {
  const policy = await deliveryConfig({ ports, state });
  if (!policy.config.enabled) return null;
  response.set('Cache-Control', 'private, no-store');
  response.vary('Cookie'); response.vary('Sec-GPC');
  response.removeHeader('Content-Length'); response.removeHeader('ETag');
  const mode = typeof delivery === 'function' ? delivery({ request }) : delivery;
  if (mode !== 'static') return { ...policy, mode: 'live' };
  // Static bytes are shared by all visitors: never bake the exporter's receipt or region into them.
  return { config: policy.config, failed: true, mode };
}

/** Mount before public renderers, outside admin/API HTML. Durable proof precedes cookie issuance.
 * This is a basic Consent Mode implementation: no Google script or denied cookieless ping loads.
 * Errors are reported through the injected port, and never silently grant optional categories.
 * @complexity Per page O(HTML bytes), one config/receipt read; per choice O(1), one durable write.
 */
export function registerConsentHttp({ app, ports }: { app: Express; ports: ConsentHttpPorts }, options: ConsentHttpOptions = {}): void {
  const { endpoint = '/api/site-consent', cookieName = DEFAULT_CONSENT_COOKIE_NAME, delivery = 'live', maxHtmlBytes = CONSENT_MAX_HTML_BYTES } = options;
  if (!Number.isSafeInteger(maxHtmlBytes) || maxHtmlBytes < 1) throw new Error(`Consent maxHtmlBytes must be a positive whole number of bytes; got ${maxHtmlBytes}.`);
  const state: { lastGood?: ConsentConfig } = {};
  app.get(`${endpoint}/status`, async (_request, response) => {
    response.set('Cache-Control', 'no-store').json({ ready: true });
  });
  app.post(endpoint, express.urlencoded({ extended: false, limit: '2kb', parameterLimit: 12 }), async (request, response) => {
    response.set('Cache-Control', 'no-store');
    try {
      await saveChoice({ request, response, ports }, { cookieName });
    } catch (error) {
      ports.reportError({ operation: 'save', error });
      respondError(response, 500, 'Cookie preferences could not be saved. Your previous choices still apply. Please try again.');
    }
  });
  app.use((request, response, next) => {
    if (!isPublicPage({ request })) { next(); return; }
    const prepare = () => prepareDelivery({ request, response, ports, state }, { delivery });
    captureConsentHtml({ response, transform: async ({ body }) => {
      const policy = await prepare();
      if (policy === null) return body;
      return gatedBody({ body, request, response, ports, ...policy, endpoint }, { ...options, cookieName });
    } }, {
      reportError: ({ error }) => ports.reportError({ operation: 'read', error }), maxBytes: maxHtmlBytes,
      overflow: async () => {
        const policy = await prepare();
        if (policy === null) return null;
        return inertConsentBody({ response });
      },
    });
    next();
  });
}

/** What this request's visitor currently allows, for server-side decisions such as forwarding an
 * analytics hit to a vendor. Mirrors the page gate: disabled consent gates nothing, failed proof
 * is read under opt-in (so an opt-out region never turns a lost rejection into a grant), and GPC
 * wins. A config or region failure is reported and denies optional categories; never throws.
 * @complexity O(cookie header length), one config read and at most one receipt read. */
export async function readRequestConsentChoices({ ports, request }: { ports: Pick<ConsentHttpPorts, 'config' | 'records' | 'clock' | 'readReceiptId' | 'region' | 'reportError'>; request: Request }, { cookieName = DEFAULT_CONSENT_COOKIE_NAME }: { cookieName?: string } = {}): Promise<ConsentChoices> {
  try {
    const config = await ports.config.get({});
    if (!config.enabled) return { necessary: true, functional: true, analytics: true, marketing: true };
    const { record, failed } = await currentRecord({ request, ports, config }, { cookieName });
    const regionMode = failed ? 'opt-in' : resolveConsentRegion({ configuredMode: config.regionMode, region: ports.region({ request }) });
    return resolveConsentChoices({ choices: record?.choices, gpc: request.get('sec-gpc') === '1', regionMode });
  } catch (error) {
    ports.reportError({ operation: 'read', error });
    return { ...DENIED_CHOICES };
  }
}

/** Analytics needs an explicit, current choice even when optional tags use regional defaults.
 * GPC and DNT always deny external identified analytics. O(1), one receipt read. */
export async function readRequestAnalyticsProof(
  { ports, request }: { ports: Pick<ConsentHttpPorts, 'config' | 'records' | 'clock' | 'readReceiptId' | 'reportError'>; request: Request },
  { cookieName = DEFAULT_CONSENT_COOKIE_NAME }: { cookieName?: string } = {},
): Promise<ConsentAnalyticsProof | undefined> {
  if (request.get('sec-gpc') === '1' || request.get('dnt') === '1' || !ports.records.retire) return undefined;
  try {
    const config = await ports.config.get({});
    const { record } = await currentRecord({ ports, request, config }, { cookieName });
    if (!record?.choices.analytics || record.gpc) return undefined;
    return { receiptId: record.id, policyVersion: record.policyVersion };
  } catch { return undefined; }
}

/** Recheck detached work against the active receipt, expiry and published policy. A changed
 * choice retires its previous proof; missing adapters/proofs fail closed. O(1), one receipt read. */
export async function allowsAnalyticsProof(
  { ports, proof }: { ports: Pick<ConsentHttpPorts, 'config' | 'records' | 'clock'>; proof: ConsentAnalyticsProof },
  _optional = {},
): Promise<boolean> {
  if (!ports.records.retire) return false;
  try {
    const config = await ports.config.get({});
    if (config.policyVersion !== proof.policyVersion) return false;
    const record = readConsentRecord({ value: await ports.records.read({ id: proof.receiptId }), policyVersion: config.policyVersion, nowMs: ports.clock.nowMs() });
    return record?.choices.analytics === true && record.gpc !== true;
  } catch { return false; }
}

/** Browser collection requires a current explicit choice, including rejection for anonymous counts.
 * This does not expose receipt evidence to the browser adapter. Read/config failures stay pending.
 * @complexity O(1), one config and one receipt read; no external I/O. */
export async function readRequestBrowserAnalyticsMode(
  { ports, request }: { ports: Pick<ConsentHttpPorts, 'config' | 'records' | 'clock' | 'readReceiptId' | 'reportError'>; request: Request },
  { cookieName = DEFAULT_CONSENT_COOKIE_NAME }: { cookieName?: string } = {},
): Promise<'pending' | 'anonymous' | 'full'> {
  try {
    const config = await ports.config.get({});
    const { record } = await currentRecord({ ports, request, config }, { cookieName });
    if (!record) return 'pending';
    return record.choices.analytics && !record.gpc && request.get('sec-gpc') !== '1' && request.get('dnt') !== '1' ? 'full' : 'anonymous';
  } catch { return 'pending'; }
}

import type { Response } from 'express';

/** Last-resort browser enforcement accompanies an inert response after a transform failure.
 * Existing CSP remains enforced alongside this policy. @complexity O(existing header length). */
export function blockConsentResponse({ response }: { response: Response }, _options = {}): void {
  const policy = "default-src 'none'; script-src 'none'; frame-src 'none'; object-src 'none'; connect-src 'none'; img-src 'none'; media-src 'none'; font-src 'none'; style-src 'none'; base-uri 'none'; form-action 'none'";
  const existing = response.getHeader('Content-Security-Policy');
  response.setHeader('Content-Security-Policy', existing ? [...(Array.isArray(existing) ? existing.map(String) : [String(existing)]), policy] : policy);
  response.setHeader('Cache-Control', 'private, no-store');
  response.removeHeader('Content-Length'); response.removeHeader('ETag');
}


/** Default capture bound; ordinary rendered pages are far smaller. */
export const CONSENT_MAX_HTML_BYTES = 5 * 1024 * 1024;

/** A CSP cannot stop meta refresh or distinguish first-party pixels from essential images.
 * Serve only inert text on any processing failure, including compressed input. @complexity O(1). */
export function inertConsentBody({ response }: { response: Response }, _options = {}): Buffer {
  blockConsentResponse({ response });
  response.removeHeader('Content-Encoding');
  response.setHeader('Content-Type', 'text/plain; charset=utf-8');
  return Buffer.from('This page could not be delivered with cookie preferences enforced. Please try again or contact the site owner.');
}

type Reporter = (required: { error: unknown }) => void;
type Overflow = (required: Record<string, never>) => Promise<Buffer | null>;

/** An observability outage must never hold completion or grant optional requests. @complexity O(1). */
function reportSafely({ reportError, error }: { reportError: Reporter; error: unknown }): void {
  try { reportError({ error }); } catch { console.error('Consent error reporter failed; optional content is blocked.'); }
}

/** Resolve enabled/static policy before selecting overflow behavior. null is an explicit disabled
 * policy and preserves every original byte; any replacement discards all later chunks.
 * @complexity O(1), excluding the injected policy read. */
async function overflowResult({ response, overflow, maxBytes, reportError }: { response: Response; overflow: Overflow; maxBytes: number; reportError: Reporter }): Promise<Buffer | null> {
  if (!isHtmlResponse({ response })) return null;
  try {
    const body = await overflow({});
    if (body !== null) reportSafely({ reportError, error: new Error(`Consent HTML exceeded ${maxBytes} bytes, so delivery was refused or replaced with inert text. Raise maxHtmlBytes if pages are legitimately larger.`) });
    return body;
  } catch (error) {
    reportSafely({ reportError, error });
    return inertConsentBody({ response });
  }
}

/** Pause piped producers while policy resolves. Disabled sites flush the captured prefix and
 * resume native streaming; enabled sites acknowledge and discard chunks until end. Callers must
 * honor Node write backpressure, just as with the native response. @complexity O(chunk bytes). */
function writeOverflow({ response, result, body, write, writeHead, flushHeaders, done }: { response: Response; result: Promise<Buffer | null>; body: Buffer; write: Response['write']; writeHead: Response['writeHead']; flushHeaders: Response['flushHeaders']; done: unknown }): boolean {
  void result.then(replacement => {
    if (response.destroyed) return;
    if (replacement === null) {
      // Native write must be able to flush headers after the disabled-policy decision.
      response.writeHead = writeHead; response.flushHeaders = flushHeaders;
      if (!Reflect.apply(write, response, [body, typeof done === 'function' ? done : undefined])) return;
    } else if (typeof done === 'function') done();
    queueMicrotask(() => response.emit('drain'));
  });
  return false;
}

/** @complexity O(chunk length). */
function toBuffer({ chunk, encoding }: { chunk: unknown; encoding: unknown }): Buffer {
  if (Buffer.isBuffer(chunk)) return chunk;
  if (chunk instanceof Uint8Array) return Buffer.from(chunk);
  return Buffer.from(String(chunk), typeof encoding === 'string' ? encoding as BufferEncoding : 'utf8');
}

/** Node accepts writeHead headers as an object or a flat [name, value, ...] list. @complexity O(headers). */
function setHeaders({ response, values }: { response: Response; values: unknown }): void {
  if (Array.isArray(values)) {
    for (let i = 0; i < values.length; i += 2) response.setHeader(String(values[i]), values[i + 1] as string);
    return;
  }
  if (!values || typeof values !== 'object') return;
  for (const [name, value] of Object.entries(values)) if (value !== undefined) response.setHeader(name, value);
}

/** end(cb), end(chunk, cb) and end(chunk, encoding, cb) all complete the same callback. @complexity O(1). */
function endCallback({ chunk, encoding, callback }: { chunk: unknown; encoding: unknown; callback: unknown }): unknown {
  if (typeof chunk === 'function') return chunk;
  return typeof encoding === 'function' ? encoding : callback;
}

/** Unknown content type must stay captured until it can be classified. @complexity O(header length). */
function isHtmlResponse({ response }: { response: Response }): boolean {
  const type = response.getHeader('content-type');
  return !type || String(type).toLowerCase().includes('text/html');
}

/** Headerless streams may split their opening tag across chunks; inspect the complete body. @complexity O(n). */
function isHtmlBody({ type, body }: { type: unknown; body: Buffer }): boolean {
  return String(type).toLowerCase().includes('text/html') || (!type && /^\s*<[a-z!]/i.test(body.toString('utf8')));
}

/** Transform a complete HTML body, then finish natively; failure serves inert text under the blocking policy.
 * @complexity O(n) plus the injected transformation. */
async function completeBody({ response, collected, transform, reportError, finish }: { response: Response; collected: Buffer; transform: (required: { body: Buffer }) => Promise<Buffer>; reportError: (required: { error: unknown }) => void; finish: (body: Buffer) => void }): Promise<void> {
  const html = isHtmlBody({ type: response.getHeader('content-type'), body: collected });
  const body = await Promise.resolve().then(() => html ? transform({ body: collected }) : collected).catch(error => {
    reportSafely({ reportError, error });
    return response.destroyed ? Buffer.alloc(0) : inertConsentBody({ response });
  });
  if (!response.destroyed) finish(body);
}

/** Intercept actual HTML at the common write/end boundary, including sendFile and pipes.
 * Non-HTML output uses native methods without invoking policy/storage. HTML must be complete
 * before parsing; callbacks acknowledge buffered writes and final completion remains native.
 * At most maxBytes (plus one chunk) is captured before resolving overflow policy. The returned
 * replacement is inert; an explicit disabled policy resumes streaming without changing bytes.
 * @complexity O(min(n, maxBytes)) space and O(n) time for n response bytes, plus the injected transformation. */
export function captureConsentHtml({ response, transform }: { response: Response; transform: (required: { body: Buffer }) => Promise<Buffer> }, { reportError = () => console.error("Consent HTML transform failed; optional content is blocked."), maxBytes = CONSENT_MAX_HTML_BYTES, overflow = async () => inertConsentBody({ response }) }: { reportError?: Reporter; maxBytes?: number; overflow?: Overflow } = {}): void {
  const write = response.write, end = response.end, writeHead = response.writeHead, flushHeaders = response.flushHeaders;
  const chunks: Buffer[] = [];
  let bytes = 0, buffering = false;
  let overflowing: Promise<Buffer | null> | undefined;
  const isHtml = (_chunk: unknown) => isHtmlResponse({ response });
  const restore = () => { response.write = write; response.end = end; response.writeHead = writeHead; response.flushHeaders = flushHeaders; };
  const collect = (chunk: unknown, encoding: unknown) => { const value = toBuffer({ chunk, encoding }); chunks.push(value); bytes += value.length; };
  // Explicit header flushes must wait for the HTML transform, including sendFile/stream output.
  response.writeHead = function (this: Response, status: number, reasonOrHeaders?: unknown, headers?: unknown): Response {
    response.statusCode = status;
    if (typeof reasonOrHeaders === 'string') response.statusMessage = reasonOrHeaders;
    setHeaders({ response, values: typeof reasonOrHeaders === 'string' ? headers : reasonOrHeaders });
    return this;
  } as Response['writeHead'];
  response.flushHeaders = function (this: Response) { if (!isHtml('')) { restore(); flushHeaders.call(this); } };
  response.write = function (this: Response, chunk: unknown, encoding?: unknown, callback?: unknown): boolean {
    if (!buffering && !isHtml(chunk)) { restore(); return Reflect.apply(write, this, [chunk, encoding, callback]); }
    buffering = true;
    const done = typeof encoding === 'function' ? encoding : callback;
    if (overflowing) return writeOverflow({ response, result: overflowing, body: toBuffer({ chunk, encoding }), write, writeHead, flushHeaders, done });
    collect(chunk, encoding);
    if (bytes > maxBytes) {
      overflowing = overflowResult({ response, overflow, maxBytes, reportError });
      const body = Buffer.concat(chunks, bytes);
      chunks.length = 0;
      return writeOverflow({ response, result: overflowing, body, write, writeHead, flushHeaders, done });
    }
    if (typeof done === 'function') queueMicrotask(() => done());
    return true;
  } as Response['write'];
  response.end = function (this: Response, chunk?: unknown, encoding?: unknown, callback?: unknown): Response {
    if (!buffering && !isHtml(chunk)) { restore(); return Reflect.apply(end, this, [chunk, encoding, callback]); }
    const done = endCallback({ chunk, encoding, callback });
    const value = endChunk({ chunk, encoding });
    const finish = (body: Buffer) => { restore(); Reflect.apply(end, response, [body, typeof done === 'function' ? done : undefined]); };
    if (overflowing) { void finishOverflow({ response, result: overflowing, original: value, finish }); return this; }
    collect(value, undefined);
    const collected = Buffer.concat(chunks, bytes);
    chunks.length = 0;
    if (bytes > maxBytes) {
      overflowing = overflowResult({ response, overflow, maxBytes, reportError });
      void finishOverflow({ response, result: overflowing, original: collected, finish });
    } else void completeBody({ response, collected, transform, reportError, finish });
    return this;
  } as Response['end'];
}

/** end callbacks/null are not body chunks. @complexity O(chunk bytes). */
function endChunk({ chunk, encoding }: { chunk: unknown; encoding: unknown }): Buffer {
  return chunk === undefined || chunk === null || typeof chunk === 'function' ? Buffer.alloc(0) : toBuffer({ chunk, encoding });
}

/** Complete only once policy is known; never append the original suffix to inert text.
 * @complexity O(1). */
async function finishOverflow({ response, result, original, finish }: { response: Response; result: Promise<Buffer | null>; original: Buffer; finish: (body: Buffer) => void }): Promise<void> {
  const replacement = await result;
  if (!response.destroyed) finish(replacement ?? original);
}

import { defaultTreeAdapter, parse, serializeOuter, type DefaultTreeAdapterMap, type TreeAdapter } from 'parse5';
import { escapeHtml } from '@jini-ai/core/text';
import { type ConsentConfig, type ConsentRecord, type ConsentRegionMode } from '../types.js';
import { renderConsentHead, renderConsentUi, type ConsentCategoryOrigins } from './render.js';
import { CONSENT_CLIENT } from './client.js';
import { cssRequestsRemote, external } from './resources.js';

type Node = DefaultTreeAdapterMap['childNode'];
type Element = DefaultTreeAdapterMap['element'];
type Attribute = Element['attrs'][number];
type ElementLocation = NonNullable<Element['sourceCodeLocation']>;
type Edit = { start: number; end: number; text: string };
type Attrs = Map<string, string>;
/** Exact host manifest entries, never declarations taken from page HTML. */
export interface ConsentGateOptions {
  nonce?: string;
  /** Static pages need a native reopening control even when the host omitted its footer link. */
  ensureReopenLink?: boolean;
  /** Host-resolved page origin, used only to retain first-party preloads. */
  pageOrigin?: string;
  runtimeToken?: string;
  /** Host-reviewed theme origins allowed by the pre-consent resource policy. */
  resourceOrigins?: readonly string[];
  /** Host-reviewed origins each granted category may reach before a marketing grant. */
  categoryOrigins?: ConsentCategoryOrigins;
  necessaryScripts?: readonly ({ src: string; content?: never } | { content: string; src?: never })[];
}

const RESERVED_IDS = ['jini-consent', 'jini-consent-config', 'jini-consent-preferences'];
const RESOURCE_HINTS = ['preload', 'modulepreload', 'prefetch', 'prerender', 'preconnect', 'dns-prefetch'];
const METADATA_RELS = ['canonical', 'alternate', 'author', 'license'];
// These metadata rels make the browser fetch (icons, manifests, Firefox's rel=next prefetch), and
// the resource CSP has no manifest/prefetch directive, so only trusted URLs skip the resource policy.
const FETCHING_METADATA_RELS = ['icon', 'apple-touch-icon', 'manifest', 'next', 'prev'];
const PRELOAD_RELS = ['preload', 'modulepreload'];
const DATA_SCRIPT_TYPES = ['application/json', 'application/ld+json', 'text/plain', 'text/template', 'text/x-template'];
const URL_ATTRIBUTES = ['src', 'href', 'poster', 'data', 'srcset', 'background'];
const RESOURCE_TAGS = ['iframe', 'frame', 'object', 'embed'];
const IMAGE_TAGS = ['img', 'image', 'input'];
const NAVIGATION_TAGS = ['a', 'area', 'form', 'html', 'head', 'body', 'script'];
const STRUCTURAL_TAGS = ['html', 'head', 'body', 'script', 'noscript'];
const OPTIONAL_CATEGORIES = ['functional', 'analytics', 'marketing'];
const HTML_NAMESPACE = 'http://www.w3.org/1999/xhtml';

/** Direct text children only, matching what a browser executes for an inline script. @complexity O(children). */
function directText({ element }: { element: Element }): string {
  return element.childNodes.filter((child): child is DefaultTreeAdapterMap['textNode'] => child.nodeName === '#text').map(child => child.value).join('');
}

/** A marker exempts only our exact runtime in this response, never the surrounding page. @complexity O(script length). */
function isRuntimeScript({ element, attrs, text }: { element: Element; attrs: Attrs; text: string }, { runtimeToken }: ConsentGateOptions): boolean {
  return element.tagName === 'script' && runtimeToken !== undefined && attrs.get('data-jini-consent-runtime') === runtimeToken && text === CONSENT_CLIENT;
}

/** Authored markers cannot become another release owner or shadow our UI/state IDs. @complexity O(attributes). */
function reservedAttributes({ element }: { element: Element }): Attribute[] {
  return element.attrs.filter(attr => (attr.name.startsWith('data-jini-consent-') && attr.name !== 'data-jini-consent-open') || (attr.name === 'id' && RESERVED_IDS.includes(attr.value)));
}

/** @complexity O(rel tokens). */
function linkRels({ attrs }: { attrs: Attrs }): string[] {
  return (attrs.get('rel') ?? '').toLowerCase().split(/\s+/).filter(Boolean);
}

/** Relative URLs, the host-resolved page origin and host-reviewed resourceOrigins are first-party;
 * authored HTML never supplies trusted origins. @complexity O(URL length + trusted origins). */
function isTrustedUrl({ url }: { url: string }, { pageOrigin, resourceOrigins = [] }: ConsentGateOptions = {}): boolean {
  if (!external({ url })) return true;
  try {
    const origin = new URL(url, pageOrigin).origin;
    return (pageOrigin !== undefined && new URL(pageOrigin).origin === origin) || resourceOrigins.includes(origin);
  } catch { return false; }
}

/** A link fetches its href and, as an image preload, every imagesrcset candidate. Unparseable
 * candidates (e.g. data: URLs with commas) fail closed. @complexity O(URL length + trusted origins). */
function linkFetchesTrusted({ attrs }: { attrs: Attrs }, options: ConsentGateOptions = {}): boolean {
  const href = attrs.get('href');
  const candidates = (attrs.get('imagesrcset') ?? '').split(',').map(candidate => candidate.trim().split(/\s+/)[0]!).filter(Boolean);
  return Boolean(href) && [href!, ...candidates].every(url => isTrustedUrl({ url }, options));
}

/** Only first-party/trusted preloads survive; other hints can initiate uncontrolled requests.
 * @complexity O(rel tokens + URL length + trusted origins). */
function isAllowedPreload({ tagName, attrs }: { tagName: string; attrs: Attrs }, options: ConsentGateOptions = {}): boolean {
  const rels = tagName === 'link' ? linkRels({ attrs }) : [];
  return rels.length > 0 && rels.every(rel => PRELOAD_RELS.includes(rel)) && linkFetchesTrusted({ attrs }, options);
}

/** Metadata describes the page even when an author mistakenly labels it optional: crawlers never
 * consent. Mixed resource rels and untrusted fetching rels still follow the resource policy.
 * Meta refresh is removed before this check. @complexity O(rel tokens + URL length + trusted origins). */
function isMetadata({ tagName, attrs }: { tagName: string; attrs: Attrs }, options: ConsentGateOptions = {}): boolean {
  if (tagName === 'meta') return true;
  // HTML never executes this type, whatever its label, src or handlers (handlers are stripped).
  if (tagName === 'script') return (attrs.get('type') ?? '').trim().toLowerCase() === 'application/ld+json';
  const rels = tagName === 'link' ? linkRels({ attrs }) : [];
  if (!rels.length || !rels.every(rel => METADATA_RELS.includes(rel) || FETCHING_METADATA_RELS.includes(rel))) return false;
  return rels.every(rel => METADATA_RELS.includes(rel)) || linkFetchesTrusted({ attrs }, options);
}

/** Refresh/base can navigate; untrusted hints can fetch outside the resource policy.
 * @complexity O(rel tokens + trusted origins). */
function isRemovedElement({ tagName, attrs }: { tagName: string; attrs: Attrs }, options: ConsentGateOptions = {}): boolean {
  if (tagName === 'base') return true;
  if (tagName === 'meta') return attrs.get('http-equiv')?.toLowerCase() === 'refresh';
  const hint = tagName === 'link' && linkRels({ attrs }).some(value => RESOURCE_HINTS.includes(value));
  return hint && !isAllowedPreload({ tagName, attrs }, options);
}

/** Exempt markup must never carry executable attributes into the browser or a release payload.
 * @complexity O(attributes). */
function exemptEdits({ element, reserved, location }: { element: Element; reserved: Attribute[]; location: Element['sourceCodeLocation'] }, _options = {}): Edit[] {
  const unsafe = element.attrs.filter(attr => /^on/i.test(attr.name) || isDeferredAttribute(attr) || (URL_ATTRIBUTES.includes(attr.name) && isJavascriptUrl({ value: attr.value })));
  return removeAttributes({ element, attrs: [...reserved, ...unsafe], location });
}

/** @complexity O(attribute length). */
function hasRemoteUrl({ attrs }: { attrs: Attrs }): boolean {
  const srcset = attrs.get('srcset');
  if (srcset !== undefined && /(?:^|[,\s])(?:https?:|\/\/)/i.test(srcset)) return true;
  return URL_ATTRIBUTES.some(key => attrs.has(key) && external({ url: attrs.get(key)! }));
}

/** Labelled or 1px images are tracking pixels even when local. @complexity O(1). */
function isTrackingImage({ attrs }: { attrs: Attrs }): boolean {
  return attrs.has('data-consent-category') || attrs.get('width') === '1' || attrs.get('height') === '1';
}

/** @complexity O(text length). */
function isResource({ tagName, attrs, text, remote }: { tagName: string; attrs: Attrs; text: string; remote: boolean }): boolean {
  if (RESOURCE_TAGS.includes(tagName)) return true;
  if (IMAGE_TAGS.includes(tagName) && (remote || isTrackingImage({ attrs }))) return true;
  if (remote && !NAVIGATION_TAGS.includes(tagName)) return true;
  if (tagName === 'style' && cssRequestsRemote({ css: text })) return true;
  // noscript must stay visible without JavaScript; its children are gated by the same walk.
  return attrs.has('data-consent-category') && !STRUCTURAL_TAGS.includes(tagName);
}

/** Page labels may select optional categories; they can never grant necessity. @complexity O(1). */
function categoryFor({ declared, fetches }: { declared: string | undefined; fetches: boolean }): string {
  if (declared === undefined || declared === 'necessary') return fetches ? 'marketing' : 'functional';
  return OPTIONAL_CATEGORIES.includes(declared) ? declared : 'blocked';
}

/** Host-reviewed external exceptions retain exact matching. @complexity O(k) for k manifest entries. */
function isNecessaryScript({ attrs, text }: { attrs: Attrs; text: string }, { necessaryScripts = [] }: ConsentGateOptions): boolean {
  return necessaryScripts.some(entry => entry.src !== undefined ? attrs.get('src') === entry.src : !attrs.has('src') && text === entry.content);
}

/** Inline speculation rules stay gated: like the removed resource hints, they prefetch/prerender
 * other origins outside the resource CSP. Foreign scripts also fetch href/xlink:href.
 * @complexity O(attributes + URL bytes). */
function scriptFetches({ element, attrs, type }: { element: Element; attrs: Attrs; type: string }, _options = {}): boolean {
  // parse5 stores both href and xlink:href with the local name href in foreign content.
  const foreignUrl = element.namespaceURI !== HTML_NAMESPACE && element.attrs.some(attr => attr.name === 'href' && external({ url: attr.value }));
  return foreignUrl || type === 'speculationrules' || (attrs.has('src') && external({ url: attrs.get('src')! }));
}

/** Unlabelled inline/local code runs by default; explicit optional labels always win over host
 * exceptions. External code (including legacy MIME types/import maps) stays gated. @complexity O(k). */
function isOptionalScript({ element, attrs, text, runtime }: { element: Element; attrs: Attrs; text: string; runtime: boolean }, options: ConsentGateOptions): boolean {
  if (element.tagName !== 'script' || runtime) return false;
  const declared = attrs.get('data-consent-category');
  if (declared !== undefined && declared !== 'necessary') return true;
  const type = (attrs.get('type') ?? '').trim().toLowerCase();
  if (DATA_SCRIPT_TYPES.includes(type)) return false;
  return scriptFetches({ element, attrs, type }) && !isNecessaryScript({ attrs, text }, options);
}

/** A wrapper consumes its subtree, so retain its strictest optional label; unknown labels block.
 * Authored HTML templates stay inert and do not impose requirements on their surroundings.
 * @complexity O(subtree nodes + attributes) time/O(subtree nodes) space. */
function wrappedCategory({ element, category }: { element: Element; category: string }, _options = {}): string {
  const ordered = [...OPTIONAL_CATEGORIES, 'blocked'];
  let rank = ordered.indexOf(category);
  const stack: Node[] = [...element.childNodes];
  while (stack.length) {
    const node = stack.pop()!;
    if (!('tagName' in node)) continue;
    if (node.tagName === 'template' && node.namespaceURI === HTML_NAMESPACE) continue;
    const declared = node.attrs.find(attr => attr.name === 'data-consent-category')?.value;
    rank = Math.max(rank, ordered.indexOf(categoryFor({ declared, fetches: false })));
    stack.push(...node.childNodes);
  }
  return ordered[rank]!;
}

/** Defer an HTML subtree under its strictest label, or remove a live foreign resource.
 * @complexity O(subtree size) time and space. */
function wrapEdit({ element, location, category }: { element: Element; location: ElementLocation; category: string }, _options = {}): Edit {
  // Normalize ignored/misnested end tags so they cannot escape the new template boundary.
  const source = serializeOuter(element, { scriptingEnabled: false });
  // A template in SVG/MathML is not an inert HTML template. Remove foreign scripts/resources.
  const marker = element.tagName === 'script' ? 'data-jini-consent-script' : 'data-jini-consent-resource';
