import type { Clock } from "@jini-ai/core/primitives";
/**
 * @file Content-types' half of the agent-tool authorization wiring: maps `agent-tools.ts`'s catalog entries onto the
 * `write-service.ts`/`lifecycle.ts` functions the admin HTTP routes call, as `ToolRegistration`s.
 *
 * Colocated with the domain rather than in `assistant/`, so the knowledge this file depends on —
 * which domain function each tool id runs, and therefore what it actually costs — lives next to
 * those functions. `assistant/tool-registrations.ts` only assembles what every domain returns.
 *
 * Scope: 6 of 7 entries are wired — the 5 non-cleanup mutations plus the read-only
 * `collections_content_type_list`. `collections_plan_cleanup`/`collections_execute_cleanup` are
 * declared unwired — the destructive token-gated ceremony, whose mapping is deferred per this
 * catalog's own deferred list. `ToolRegistry.list()` will not show them, which is intentional: no silent stub
 * registrations that could look like a bug if ever actually invoked.
 *
 * `ToolPolicy.authorize` is a pass-through for every entry here (see `buildDomainRegistrations`).
 * For the five mutations, that is the "one evaluator" rule: each domain entrypoint —
 * `registerContentType`, `updateContentTypeFields` (`write-service.ts`), `deprecateContentType`,
 * `reactivateContentType`, `tombstoneContentType` (`lifecycle.ts`) — opens with an
 * `await deps.authorize({ permission: 'admin.collections.manage', ... })` that returns
 * `ForbiddenError` before any repo read, repo write, or index-provisioner call, and
 * `admin.collections.manage` is exactly what each of their five catalog entries declares under
 * `authorization.permission`. `assistant/__tests__/tool-registrations.authorization.test.ts` drives
 * all five through a denying `authorize` and asserts each refuses and writes nothing, deriving its
 * expectations from the catalog itself — so a future tool wired here whose handler does NOT
 * self-enforce fails rather than silently inheriting the pass-through.
 *
 * `collections_content_type_list` is the exception: `listContentTypes` (`list.ts`) is a pure
 * pass-through read with no `authorize()` call of its own — exactly like `routes/admin/content-
 * types/list.ts`, which checks `admin.collections.read` in the route BEFORE calling it. Its handler
 * below does the identical explicit `requireToolPermission` check, in the route's place, the same
 * pattern `comments/tool-registrations.ts` uses for `comments_list_moderation_queue`.
 */
import type { AuthorizeFn } from "../core/commands/command.js";
import type { OutboxPort } from "../core/ports.js";
import { AGENT_TOOL_PRINCIPAL_KIND, buildDomainRegistrations, decorateWithSchema, fromResult, indexCatalogById, requireInputRecord, requireNoInput, requireNumber, requireString, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration } from "@jini-ai/core";
import { adaptLegacyAuthorize, requireToolPermission } from "../core/tools/index.js";
import { contentTypesAgentToolCatalog } from "./agent-tools.js";
import { parseContentTypeFieldDefs } from "./field-defs.js";
import { listContentTypes, type ContentTypeListPort } from "./list.js";
import { deprecateContentType, reactivateContentType, tombstoneContentType, type TeardownIndexProvisionerPort } from "./lifecycle.js";
import { toContentTypeOutbox } from "./repo.memory.js";
import type { ContentTypeFieldDef, ContentTypeRecord } from "./types.js";
import { registerContentType, updateContentTypeFields, type ContentTypeRepoPort, type IndexProvisionerPort } from "./write-service.js";

const CATALOG_BY_ID = indexCatalogById({ catalog: contentTypesAgentToolCatalog });

/**
 * The exact slice of the route-deps bag Content-Types' tool handlers read. Declared structurally
 * (rather than importing `server/routes/types`'s `RouteDeps`) so this module carries no back-edge
 * into the composition root. `server/routes/*` satisfies this structurally by passing its existing
 * `RouteDeps` object with the kernel clock/ID contracts.
 */
export interface ContentTypesToolDeps {
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  idGen: IdGenerator;
  outbox: OutboxPort;
  contentTypeRepo: ContentTypeRepoPort & ContentTypeListPort;
  contentTypeIndexProvisioner: IndexProvisionerPort & TeardownIndexProvisionerPort;
  /** The same host route policy applied to direct content-type registration. */
  reservedContentTypeKeys?: ReadonlySet<string>;
}

/** Descriptors for the 2 cleanup tools this pass does not wire — see file header. */
const UNWIRED_CONTENT_TYPES_TOOL_IDS = new Set(["collections_plan_cleanup", "collections_execute_cleanup"]);

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls — deliberately a second, independent source rather than a read of the catalog's own
 * `sideEffects` field. See `DerivedRiskByToolId` in the kit for why that independence matters.
 */
export const contentTypesDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> listContentTypes (list.ts): one repo.listByWorkspace read, no write of any kind.
  ["collections_content_type_list", "none"],
  // -> registerContentType (write-service.ts): repo.save + appendRevision in one tx.
  ["collections_content_type_define", "mutates-durable-state"],
  // -> updateContentTypeFields (write-service.ts): full field-schema replace + index transitions.
  ["collections_content_type_update_fields", "mutates-durable-state"],
  // -> deprecateContentType (lifecycle.ts): status flip + revision.
  ["collections_content_type_deprecate", "mutates-durable-state"],
  // -> reactivateContentType (lifecycle.ts): status flip + revision.
  ["collections_content_type_reactivate", "mutates-durable-state"],
  // -> tombstoneContentType (lifecycle.ts): one-way terminal transition that tears down every
  //    provisioned index BEFORE persisting the flip. The heaviest of the five.
  ["collections_content_type_tombstone", "mutates-durable-state"],
]);

/**
 * Validates `input.fields` through the SAME boundary parser the admin HTTP routes use
 * (`field-defs.ts`), then re-throws any rejection with the tool's published `inputSchema` appended.
 *
 * The appended schema is the error-recovery half of the contract: a model that gets back only
 * "fields[0].queryable must be a boolean" has to guess the rest of the shape, whereas one that
 * gets the schema alongside it can correct the call in a single turn.
 *
 * @complexity O(f) in the field count, delegated to the parser.
 * @overallScore 100
 */
function requireFields(input: Record<string, unknown>, toolId: string): ContentTypeFieldDef[] {
  const parsed = parseContentTypeFieldDefs({ value: input.fields });
  if (parsed.ok) return parsed.value;
  throw decorateWithSchema({ toolId, catalog: CATALOG_BY_ID, message: parsed.error.message });
}

/** What a content-type tool returns to the model — see {@link toContentTypeView}. */
interface ContentTypeToolView {
  key: string;
  label: string;
  status: ContentTypeRecord["status"];
  version: number;
  fields: ContentTypeFieldDef[];
  tombstonedAt?: string | null;
}

/**
 * Projects a `ContentTypeRecord` into the explicit model-facing shape, instead of returning the
 * domain record verbatim.
 *
 * Two reasons this is a named projection rather than a pass-through. `workspaceId` is dropped: the
 * agent is already scoped to one workspace it did not choose and cannot change, so echoing the id
 * back spends model attention on a value that can never inform a decision. And an explicit view
 * means a future field added to `ContentTypeRecord` — for a plugin, an internal counter, an
 * operator note — does not silently begin flowing to the model as a side effect of a domain change.
 *
 * `version` is deliberately kept: every mutating tool requires `expectedVersion`, so the model
 * needs the post-write value to make a correct follow-up call without re-reading.
 *
 * @param record - The content type as the domain returned it.
 * @returns The model-facing view. `tombstonedAt` is present only when set, so an active type's
 * payload carries no always-null key.
 * @complexity O(f) in the field count (the array is copied so the caller cannot alias domain state).
 * @overallScore 100
 */
function toContentTypeView(record: ContentTypeRecord): ContentTypeToolView {
  const view: ContentTypeToolView = {
    key: record.key,
    label: record.label,
    status: record.status,
    version: record.version,
    fields: [...record.fields],
  };
  if (record.tombstonedAt) view.tombstonedAt = record.tombstonedAt;
  return view;
}

function fromContentTypeResult(
  fn: () => Promise<{ ok: true; value: { contentType: ContentTypeRecord } } | { ok: false; error: Error }>,
): Promise<{ contentType: ContentTypeToolView }> {
  return fromResult({ fn: fn }).then(({ contentType }) => ({ contentType: toContentTypeView(contentType) }));
}

function contentTypesDeps(routeDeps: ContentTypesToolDeps) {
  return {
    repo: routeDeps.contentTypeRepo,
    clock: routeDeps.clock,
    ids: routeDeps.idGen,
    authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }),
    // Widened through `toContentTypeOutbox`, as `entries/tool-registrations.ts` does: the domain
    // enqueues only `{name,payload}`, but `routeDeps.outbox` is the real `core/ports` port whose
    // `DomainEvent` requires `id`/`workspaceId`/`occurredAt`. Passing it through raw typechecked (method
    // bivariance) yet delivered events with none of the three.
    outbox: toContentTypeOutbox(routeDeps),
    indexProvisioner: routeDeps.contentTypeIndexProvisioner,
    ...(routeDeps.reservedContentTypeKeys !== undefined ? { reservedKeys: routeDeps.reservedContentTypeKeys } : {}),
  };
}

export function buildContentTypesRegistrations(routeDeps: ContentTypesToolDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    collections_content_type_list: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.collections.read" }, { entityType: "content-type" });
      const { items } = await listContentTypes({ repo: routeDeps.contentTypeRepo, workspaceId: routeDeps.workspaceId });
      return { contentTypes: items.map(toContentTypeView) };
    },
    collections_content_type_define: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      return fromContentTypeResult(() =>
        registerContentType({
          deps: contentTypesDeps(routeDeps),
          input: {
            actorId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            workspaceId: routeDeps.workspaceId,
            key: requireString({ input, key: "key" }),
            label: requireString({ input, key: "label" }),
            fields: requireFields(input, "collections_content_type_define"),
          },
        }),
      );
    },
    collections_content_type_update_fields: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      return fromContentTypeResult(() =>
        updateContentTypeFields({
          deps: contentTypesDeps(routeDeps),
          input: {
            actorId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            workspaceId: routeDeps.workspaceId,
            key: requireString({ input, key: "key" }),
            fields: requireFields(input, "collections_content_type_update_fields"),
            expectedVersion: requireNumber({ input, key: "expectedVersion" }),
          },
        }),
      );
    },
    collections_content_type_deprecate: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      return fromContentTypeResult(() =>
        deprecateContentType({
          deps: contentTypesDeps(routeDeps),
          input: {
            actorId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            workspaceId: routeDeps.workspaceId,
            key: requireString({ input, key: "key" }),
            expectedVersion: requireNumber({ input, key: "expectedVersion" }),
          },
        }),
      );
    },
    collections_content_type_reactivate: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      return fromContentTypeResult(() =>
        reactivateContentType({
          deps: contentTypesDeps(routeDeps),
          input: {
            actorId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            workspaceId: routeDeps.workspaceId,
            key: requireString({ input, key: "key" }),
            expectedVersion: requireNumber({ input, key: "expectedVersion" }),
          },
        }),
      );
    },
    collections_content_type_tombstone: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      return fromContentTypeResult(() =>
        tombstoneContentType({
          deps: contentTypesDeps(routeDeps),
          input: {
            actorId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            workspaceId: routeDeps.workspaceId,
            key: requireString({ input, key: "key" }),
            expectedVersion: requireNumber({ input, key: "expectedVersion" }),
          },
        }),
      );
    },
  };

  return buildDomainRegistrations({
    domain: "content-types",
    catalogModule: "features/content-types/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: contentTypesDerivedRisk,
  }, { unwiredToolIds: UNWIRED_CONTENT_TYPES_TOOL_IDS });
}

import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
import { EntityNotLiveError } from "../core/entity-liveness.js";
import type { Clock } from "@jini-ai/core/primitives";
import {
  ContentTypeAlreadyExistsError,
  ContentTypeNotFoundError,
  ForbiddenError,
  InvalidFieldKindError,
  InvalidFieldNameGrammarError,
  InvalidKeyGrammarError,
  QueryableFieldCapExceededError,
  ReservedContentTypeKeyError,
  StorageOnlyFieldNotQueryableError,
  ValidationError,
  VersionConflictError,
} from "./errors.js";
import { resolveFieldIndexTransition, validateIdentifierGrammar } from "./index-provisioning.js";
import { type Result } from "@jini-ai/core/primitives";
import { type ActorIdentityInput, type ActorPrincipalKind, type ContentTypeFieldDef, type ContentTypeRecord, isContentTypeFieldKind, isIndexableFieldKind } from "./types.js";

/**
 * @file Write-service — `registerContentType`/`updateContentTypeFields`, the single write
 * chokepoint for the `content_types` registry.
 *
 * Purpose:
 * The ONLY path that creates or full-replaces a content type's field schema. Every export here:
 * `authorize` first (fail-closed) -> the fixed definition-time guard sequence ->
 * same-transaction row + revision write (+ watermark stamp when supplied) -> index provisioning.
 *
 * `registerContentType`'s guard order is binding, not incidental: key grammar ->
 * reserved-key -> field-name grammar -> field-kind -> storage-only-not-queryable -> queryable-cap,
 * evaluation stops at the first failure. The storage-only check is numbered 4b rather than
 * renumbering 5, because the fixed order is pinned by name in the certified suite and the existing
 * five guards keep both their relative order and their identity: 4b sits strictly between the
 * field-kind check and the queryable-cap check, and can only fire on a field whose kind already
 * passed guard 4. `updateContentTypeFields` additionally requires `expectedVersion`
 * to be checked BEFORE the `fields_empty` floor and before any per-field guard, so a stale
 * `expectedVersion` combined with `fields: []` reports `VERSION_CONFLICT`, never
 * `VALIDATION_ERROR(fields_empty)`.
 *
 * How it relates to the project:
 * `deps.watermark` and the actor-identity delegation fields
 * (`delegatedByWorkspaceId`/`delegatedById`) are both optional/additive — every
 * pre-existing call site that omits them is unaffected; `watermark-stamping.integration.test.ts`
 * exercises both.
 *
 * Architectural role:
 * `features/content-types` domain logic. Depends only on `core/ports` and this package's own
 * `errors.ts`/`index-provisioning.ts`/`types.ts` — no adapter, no other feature.
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */

/**
 * Matches every other feature's chokepoint `AuthorizeFn` shape structurally — no shared import,
 * kept decoupled. `entityType`/`entityId` let `registerContentType`/`updateContentTypeFields`
 * (and `lifecycle.ts`'s three transitions, which import this same type) pass
 * `entityType: "content-type"` — matching every fronting HTTP route's own
 * `entityType: "content-type"` pre-check. See `entries/write-service.ts`'s identical `AuthorizeFn`
 * doc for why an omitted `entityType` here previously denied a content-type-scoped-only grant with
 * `resource_scope_mismatch` even though the route's pre-check allowed it, and why this chokepoint —
 * not the route — is the one that must stay at least as expressive.
 */
export type { AuthorizationPort as AuthorizeFn } from '../core/authorization.js';
import type { AuthorizationPort as AuthorizeFn } from '../core/authorization.js';

export interface ContentTypeRevisionInput {
  contentTypeKey: string;
  workspaceId: string;
  op: "register" | "field-change";
  stateJson: ContentTypeRecord;
  actorId: string;
  /**
   * Audit provenance — the actor CLASS behind `actorId` (`'user'` for a human admin request,
   * `'agent'` for a write made through the assistant's tool surface, `'system'` for an internal
   * boot-time registration). `null` when the caller did not supply one; see
   * `ActorIdentityInput.principalKind` for why `actorId` alone cannot answer the audit question.
   */
  principalKind: ActorPrincipalKind | null;
  delegatedByWorkspaceId: string | null;
  delegatedById: string | null;
  recordedAt: string;
}

export interface ContentTypeRepoPort {
  save(row: ContentTypeRecord): Promise<void>;
  appendRevision(revision: ContentTypeRevisionInput): Promise<void>;
  findByKey(params: { workspaceId: string; key: string }): Promise<ContentTypeRecord | null>;
  transaction<T>(required: { fn: () => Promise<T> }): Promise<T>;
}

export interface IndexProvisionerPort {
  provisionIndexesForNewContentType(input: {
    workspaceId: string;
    contentTypeKey: string;
    fields: ContentTypeFieldDef[];
  }): Promise<void>;
  applyFieldIndexTransitions(input: {
    workspaceId: string;
    contentTypeKey: string;
    transitions: Array<{ fieldName: string; action: "provision" | "teardown" | "reprovision" }>;
  }): Promise<void>;
}

export interface OutboxPort {
  enqueue(event: { name: string; payload: Record<string, unknown> }): Promise<void>;
}

/** Optional — advances `database_write_watermark` by exactly 1 when supplied. See docs/decisions/DR-001-safe-schema-and-index-transitions.md. */
export interface WatermarkPort {
  stampWatermark(input: { workspaceId: string }): Promise<number>;
}

export interface ContentTypeWriteServiceDeps {
  repo: ContentTypeRepoPort;
  clock: Clock;
  ids: { newId: () => string };
  authorize: AuthorizeFn;
  indexProvisioner: IndexProvisionerPort;
  outbox: OutboxPort;
  watermark?: WatermarkPort;
  /** Host-owned public route segments which a collection key cannot claim. */
  reservedKeys?: ReadonlySet<string>;
}

/**
 * Field-name guards shared by register and update, in order: every name passes the identifier
 * grammar (`InvalidFieldNameGrammarError`), THEN no name appears twice
 * (`VALIDATION_ERROR(fields_duplicate_name)`). Duplicates are refused because entry values are
 * stored keyed by field name and the index-transition diff builds a name-keyed map, so two defs
 * sharing a name leave one of them unaddressable (last one wins). Returns `null` when both pass.
 *
 * @complexity O(f) in the number of submitted fields.
 */
function fieldNameError(fields: ReadonlyArray<{ name: string }>): Error | null {
  for (const field of fields) {
    if (!validateIdentifierGrammar({ value: field.name })) {
      return new InvalidFieldNameGrammarError({ message: `field name '${field.name}' fails the identifier grammar gate` });
    }
  }
  const seen = new Set<string>();
  for (const field of fields) {
    if (seen.has(field.name)) {
      return new ValidationError({ message: `field name '${field.name}' appears more than once`, reason: "fields_duplicate_name" });
    }
    seen.add(field.name);
  }
  return null;
}

/** Reserved forever for the legacy `posts` table — an operator Collection can never take these keys. */
const RESERVED_CONTENT_TYPE_KEYS = new Set(["post", "page"]);

/** Per-type cap on `queryable` fields (queryable-index sprawl mitigation). */
const QUERYABLE_FIELD_CAP = 20;

function countQueryableFields(fields: ContentTypeFieldDef[]): number {
  return fields.filter((f) => f.queryable).length;
}

/**
 * Register-only key guards, in binding order: key grammar (guard 1) -> owner grammar (guard 1b)
 * -> reserved key (guard 2, legacy then host-reserved). Returns `null` when all pass.
 *
 * @complexity O(1) — bounded-length grammar checks and two set lookups.
 */
function registerKeyError(
  required: { key: string; owner: string | undefined },
  optional: { reservedKeys?: ReadonlySet<string> | undefined } = {},
): Error | null {
  const { key, owner } = required;
  // Guard 1: key grammar.
  if (!validateIdentifierGrammar({ value: key })) {
    return new InvalidKeyGrammarError({ message: `content-type key '${key}' fails the identifier grammar gate ^[a-z][a-z0-9_]{0,63}$` });
  }
  // Guard 1b: owner grammar, only when one is given. It becomes an object key inside every entry's
  // `fieldsJson.ext`, so it gets the same identifier gate as the type key.
  if (owner !== undefined && !validateIdentifierGrammar({ value: owner })) {
    return new InvalidKeyGrammarError({ message: `content-type owner '${owner}' fails the identifier grammar gate ^[a-z][a-z0-9_]{0,63}$` });
  }
  // Guard 2: reserved key.
  if (RESERVED_CONTENT_TYPE_KEYS.has(key)) {
    return new ReservedContentTypeKeyError({ message: `key '${key}' is permanently reserved for the legacy 'posts' table` });
  }
  if (optional.reservedKeys?.has(key.toLowerCase())) {
    return new ReservedContentTypeKeyError({ message: `key '${key}' is reserved for a host route` });
  }
  return null;
}

/**
 * Per-field guards shared by register and update, in binding order and stop-at-first-failure:
 * field-name grammar then uniqueness (guard 3) -> field-kind (guard 4) -> storage-only-not-
 * queryable (guard 4b) -> queryable-cap (guard 5). Returns `null` when all pass.
 *
 * @complexity O(f) in the number of submitted fields.
 */
function fieldSchemaError(required: { key: string; fields: ContentTypeFieldDef[] }): Error | null {
  const { key, fields } = required;
  // Guard 3: field-name grammar, then uniqueness (every field, before any kind/cap check).
  const nameError = fieldNameError(fields);
  if (nameError) return nameError;
  // Guard 4: field-kind, closed enum.
  const badKind = fields.find((field) => !isContentTypeFieldKind({ value: field.kind }));
  if (badKind) {
    return new InvalidFieldKindError({ message: `field '${badKind.name}' has kind '${badKind.kind}', not one of the closed field-kind enum` });
  }
  // Guard 4b: a storage-only kind cannot be queryable. Placed strictly between guard 4 and guard 5
  // so a bad kind still reports as a kind error, and a legal-but-unindexable kind is rejected
  // BEFORE the cap count and long before `resolveFieldIndexTransition` could hand it to the index
  // provisioner. This is the check that keeps a kind with no CAST target off the DDL path.
  const storageOnly = fields.find((field) => field.queryable && !isIndexableFieldKind({ value: field.kind }));
  if (storageOnly) {
    return new StorageOnlyFieldNotQueryableError({ message: `field '${storageOnly.name}' has storage-only kind '${storageOnly.kind}' and cannot be queryable` });
  }
  // Guard 5: queryable-field cap, submitted array alone.
  if (countQueryableFields(fields) > QUERYABLE_FIELD_CAP) {
    return new QueryableFieldCapExceededError({ message: `content type '${key}' submits more than ${QUERYABLE_FIELD_CAP} queryable fields` });
  }
  return null;
}

/**
 * Writes the row and its revision (+ watermark stamp when that port is supplied). Must be called
 * inside `deps.repo.transaction` so all three land or none do.
 *
 * @complexity O(1) — three port calls.
 */
async function persistWithRevision(required: {
  deps: ContentTypeWriteServiceDeps;
  input: ActorIdentityInput & { workspaceId: string; key: string };
  op: ContentTypeRevisionInput["op"];
  row: ContentTypeRecord;
  recordedAt: string;
}): Promise<void> {
  const { deps, input, op, row, recordedAt } = required;
  await deps.repo.save(row);
  await deps.repo.appendRevision({
    contentTypeKey: input.key,
    workspaceId: input.workspaceId,
    op,
    stateJson: row,
    actorId: input.actorId,
    principalKind: input.principalKind ?? null,
    delegatedByWorkspaceId: input.delegatedByWorkspaceId ?? null,
    delegatedById: input.delegatedById ?? null,
    recordedAt,
  });
  if (deps.watermark) await deps.watermark.stampWatermark({ workspaceId: input.workspaceId });
}

export interface RegisterContentTypeRequired {
  deps: ContentTypeWriteServiceDeps;
  input: ActorIdentityInput & {
    workspaceId: string;
    key: string;
    label: string;
    fields: ContentTypeFieldDef[];
    /**
     * The `fieldsJson.ext.<owner>` namespace this type's entries are stored under; omit for the
     * default `"site"`. For code that registers its OWN type (e.g. a host's widgets feature); the
     * agent tool and HTTP surfaces deliberately never pass it. See `ContentTypeRecord.owner`.
     */
    owner?: string | undefined;
  };
}

/**
 * 08 — registers a new content type. Guard order is, fixed and stop-at-first-
 * failure: key grammar -> reserved-key -> field-name grammar -> field-kind -> queryable-cap.
 *
 * @complexity O(f) in the number of submitted fields (two guard passes over `fields`).
 * @overallScore 100
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */
export async function registerContentType(
  required: RegisterContentTypeRequired
): Promise<Result<{ contentType: ContentTypeRecord }, Error>> {
  const { deps, input } = required;

  const authResult = await deps.authorize({
    principalId: input.actorId,
    permission: "admin.collections.manage",
    workspaceId: input.workspaceId }, { entityType: "content-type" });
  if (!authResult.allowed) {
    return { ok: false, error: new ForbiddenError({ message: `principal '${input.actorId}' cannot register a content type (${authResult.reason})` }) };
  }

  const keyError = registerKeyError({ key: input.key, owner: input.owner }, { reservedKeys: deps.reservedKeys });
  if (keyError) return { ok: false, error: keyError };
  const schemaError = fieldSchemaError({ key: input.key, fields: input.fields });
  if (schemaError) return { ok: false, error: schemaError };

  // Row 7 — a pre-check outside the transaction. Not race-safe by itself (that's the in-tx check
  // below), but it avoids opening a transaction for the overwhelmingly common not-found case.
  const existingBeforeTx = await deps.repo.findByKey({ workspaceId: input.workspaceId, key: input.key });
  if (existingBeforeTx) {
    return { ok: false, error: new ContentTypeAlreadyExistsError({ key: input.key, tombstoned: existingBeforeTx.status === "tombstone" }) };
  }

  const now = kernelNowIso({ clock: deps.clock });
  const contentType: ContentTypeRecord = {
    workspaceId: input.workspaceId,
    key: input.key,
    label: input.label,
    fields: input.fields,
    status: "active",
    version: 1,
    tombstonedAt: null,
    // Only set when given, so a type registered without one stays byte-identical to before `owner` existed.
    ...(input.owner !== undefined ? { owner: input.owner } : {}),
  };

  try {
    await deps.repo.transaction({ fn: async () => {
      // The check that actually closes the race: two concurrent first-widget creates both see the
      // pre-check above return null, but only one of them can win this in-tx re-check before save.
      const existingInTx = await deps.repo.findByKey({ workspaceId: input.workspaceId, key: input.key });
      if (existingInTx) {
        throw new ContentTypeAlreadyExistsError({ key: input.key, tombstoned: existingInTx.status === "tombstone" });
      }
      await persistWithRevision({ deps, input, op: "register", row: contentType, recordedAt: now });
    } });
  } catch (err) {
    if (err instanceof ContentTypeAlreadyExistsError) return { ok: false, error: err };
    throw err;
  }

  // Index provisioning runs only once the transaction has committed a new row — never on the
  // already-exists path above.
  await deps.indexProvisioner.provisionIndexesForNewContentType({
    workspaceId: input.workspaceId,
    contentTypeKey: input.key,
    fields: input.fields,
  });

  return { ok: true, value: { contentType } };
}

export interface UpdateContentTypeFieldsRequired {
  deps: ContentTypeWriteServiceDeps;
  input: ActorIdentityInput & {
    workspaceId: string;
    key: string;
    fields: ContentTypeFieldDef[];
    expectedVersion: number;
    /**
     * J1 (plan-publish-all-types-2026-09-25.md §0.2) — optional and additive. Before this, no
     * write path could ever change `label` after `registerContentType`, so a publish that carried
     * an imported `label` change hashed it (the planned publish factory's `transferred` field) but
     * had nothing to call that would apply it — a permanent false "still changed" on every
     * subsequent plan. Omitted, the current label is kept unchanged, exactly as before this field
     * existed.
     */
    label?: string | undefined;
  };
}

/**
 * — full-replace of a content type's field schema. : `expectedVersion` is
 * checked BEFORE the `fields_empty` floor and before any per-field guard, so a stale version
 * combined with an empty array reports `VERSION_CONFLICT`, never `VALIDATION_ERROR`.
 *
 * @complexity O(f) in the number of submitted fields.
 * @overallScore 100
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */
export async function updateContentTypeFields(
  required: UpdateContentTypeFieldsRequired
): Promise<Result<{ contentType: ContentTypeRecord }, Error>> {
  const { deps, input } = required;

  const authResult = await deps.authorize({
    principalId: input.actorId,
    permission: "admin.collections.manage",
    workspaceId: input.workspaceId }, { entityType: "content-type" });
  if (!authResult.allowed) {
    return { ok: false, error: new ForbiddenError({ message: `principal '${input.actorId}' cannot update content type '${input.key}' (${authResult.reason})` }) };
  }

  const current = await deps.repo.findByKey({ workspaceId: input.workspaceId, key: input.key });
  if (!current) {
    return { ok: false, error: new ContentTypeNotFoundError({ message: `content type '${input.key}' was not found in workspace '${input.workspaceId}'` }) };
  }
  // Row 15's sibling — a tombstoned type is terminal; this check runs before the version. See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
  // check so a stale-version update against a tombstoned row still reports "tombstoned", not
  // "version conflict" (the tombstone tore down every queryable index, so the schema is moot).
  if (current.status === "tombstone") {
    return { ok: false, error: new EntityNotLiveError({ entityType: "content type", entityId: input.key, state: "tombstoned" }) };
  }

  // expectedVersion checked FIRST — before fields_empty, before any per-field guard. See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
  if (input.expectedVersion !== current.version) {
    return { ok: false, error: new VersionConflictError({ message: `expected version ${input.expectedVersion} for content type '${input.key}', found ${current.version}` }) };
  }

  if (input.fields.length === 0) {
    return { ok: false, error: new ValidationError({ message: `content type '${input.key}' update submitted an empty fields array`, reason: "fields_empty" }) };
  }

  const schemaError = fieldSchemaError({ key: input.key, fields: input.fields });
  if (schemaError) return { ok: false, error: schemaError };

  const before = current.fields;
  const after = input.fields;
  const now = kernelNowIso({ clock: deps.clock });
  const updated: ContentTypeRecord = { ...current, fields: after, label: input.label ?? current.label, version: current.version + 1 };

  await deps.repo.transaction({ fn: async () => {
    await persistWithRevision({ deps, input, op: "field-change", row: updated, recordedAt: now });
  } });

  await deps.indexProvisioner.applyFieldIndexTransitions({
    workspaceId: input.workspaceId,
    contentTypeKey: input.key,
    transitions: computeFullReplaceTransitions(before, after),
  });

  return { ok: true, value: { contentType: updated } };
}

/**
 * composition — resolves an index transition for every field name present on either
 * side of a full-replace update (union of before/after names), one before/after comparison per
 * name, and returns only the actionable (non-`"none"`) transitions.
 *
 * @complexity O(f) in the number of distinct field names across both arrays.
 * @overallScore 100
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */
function computeFullReplaceTransitions(
  before: ContentTypeFieldDef[],
  after: ContentTypeFieldDef[]
): Array<{ fieldName: string; action: "provision" | "teardown" | "reprovision" }> {
  const beforeByName = new Map(before.map((f) => [f.name, f]));
  const afterByName = new Map(after.map((f) => [f.name, f]));
  const allNames = new Set([...beforeByName.keys(), ...afterByName.keys()]);

  const transitions: Array<{ fieldName: string; action: "provision" | "teardown" | "reprovision" }> = [];
  for (const name of allNames) {
    const b = beforeByName.get(name);
    const a = afterByName.get(name);
    const transition = resolveFieldIndexTransition({
      before: b ? { kind: b.kind, queryable: b.queryable } : undefined,
      after: a ? { kind: a.kind, queryable: a.queryable } : undefined,
    });
    if (transition.action !== "none") {
      transitions.push({ fieldName: name, action: transition.action });
    }
  }
  return transitions;
}

import type { Clock } from "@jini-ai/core/primitives";
/**
 * @file Core port contracts for the CMS runtime.
 *
 * Purpose:
 * Defines the stable interfaces that domain/application code depends on.
 *
 * How it relates to the project:
 * - `features/*` import these contracts to stay framework/provider-agnostic.
 * - `core/memory-bus.ts` provides in-memory implementations for local dev/tests.
 * - `core/outbox-worker.ts` orchestrates reliable async delivery using these ports.
 * - `server/app.ts` composes concrete implementations and runs the slice.
 *
 * Architectural role:
 * This file is the dependency inversion seam. Concrete infrastructure can change
 * without changing feature logic as long as implementations satisfy these types.
 */
/**
 * Shared primitives and runtime ports used by the CMS core.
 *
 * Design goal:
 * Core/domain code depends on interfaces from this file only, never on concrete
 * infrastructure SDKs or framework-specific implementations.
 */
import type { UUID, ISODateTime } from "@jini-ai/core/primitives";

/**
 * Immutable domain event emitted by synchronous command handlers and delivered
 * asynchronously via the outbox pipeline.
 */
export interface DomainEvent<TPayload = Record<string, unknown>> {
  /** Unique identifier for the event record. */
  id: UUID;
  /** Stable event name, e.g. `workspace.created`. */
  name: string;
  /** ISO timestamp describing when the event was produced. */
  occurredAt: ISODateTime;
  /** Optional aggregate root identifier related to this event. */
  aggregateId?: UUID;
  /**
   * Tenant/workspace boundary. Required: every domain event belongs to a
   * workspace. Platform-level events must be a deliberate future
   * decision, not an omission.
   */
  workspaceId: UUID;
  /**
   * Principal (user or AI agent) that caused this event. Reserved change-set
   * vocabulary; optional until the identity library lands.
   */
  actorId?: UUID;
  /**
   * Change set this event belongs to, enabling propose/preview/apply/revert
   * grouping. Reserved change-set vocabulary.
   */
  changeSetId?: UUID;
  /** Event-specific payload. */
  payload: TPayload;
  /** Free-form metadata (trace IDs, source, etc.). */
  metadata?: Record<string, unknown>;
}

/**
 * Event bus abstraction used by the application layer.
 *
 * This is intentionally generic so implementations can be in-memory, queue-based,
 * broker-based, or provider-managed without changing domain logic.
 */
export interface EventBusPort {
  /** Publish a single event to subscribers. */
  publish<TPayload>(event: DomainEvent<TPayload>): Promise<void>;
  /** Publish multiple events in order. */
  publishBatch<TPayload>(required: { events: Array<DomainEvent<TPayload>> }, optional?: Record<string, never>): Promise<void>;
  /**
   * Subscribe a handler to an event name.
   * Returns an async unsubscriber function.
   */
  subscribe<TPayload>(
    required: { eventName: string; handler: (event: DomainEvent<TPayload>) => Promise<void> },
    optional?: Record<string, never>
  ): Promise<() => Promise<void>>;
  /**
   * Subscribe a handler to every event published on this bus, regardless of name. Additive to
   * `subscribe` — existing per-name callers are unaffected.
   * The Integrations fan-out (`registerWebhookFanout`) is the first real consumer: it narrows
   * by topic itself rather than requiring a fixed list of event names up front.
   */
  subscribeAll(required: { handler: (event: DomainEvent) => Promise<void> }, optional?: Record<string, never>): Promise<() => Promise<void>>;
}

/**
 * Persisted outbox row used for reliable async event delivery.
 */
export interface OutboxRecord {
  /** Primary key for the outbox row (same as `event.id`). */
  id: UUID;
  /**
   * The full event envelope. The outbox must preserve everything the producer
   * emitted (workspaceId, aggregateId, actorId, occurredAt, metadata) so
   * delivery replays the original event, not a reconstruction.
   */
  event: DomainEvent;
  /** Delivery lifecycle state. */
  status: "pending" | "processing" | "delivered" | "failed";
  /** Number of delivery attempts so far. */
  attempts: number;
  /** Retry eligibility timestamp. */
  nextAttemptAt: ISODateTime;
  /** Most recent delivery failure reason. */
  lastError?: string;
  /** Row creation timestamp. */
  createdAt: ISODateTime;
}

/**
 * Reliable outbox contract.
 *
 * Command handlers enqueue events here in the same unit of work as the write.
 * A worker later claims and delivers rows to the event bus.
 */
export interface OutboxPort {
  /** Append an event for later delivery. */
  enqueue(event: DomainEvent): Promise<void>;
  /** Claim pending rows for processing. */
  claimPending(required: { batchSize: number; nowIso: ISODateTime }, optional?: Record<string, never>): Promise<OutboxRecord[]>;
  /** Mark a row as delivered. */
  markDelivered(required: { id: UUID }, optional?: Record<string, never>): Promise<void>;
  /**
   * Mark a row as failed and set its next retry time.
   *
   * `nextStatus` is decided by the CALLER (the retry-policy owner, e.g. a worker that tracks an
   * attempt cap) — an implementation must persist exactly what it is told, not re-derive the
   * decision from the row's own stored `attempts` (2026-09-06: this parameter replaced that
   * adapter-side re-derivation, mirroring `WebhookDeliveryRepoPort.markFailed`'s `nextStatus`
   * shape in the host). `"pending"` re-enters the retry queue at `nextAttemptAt`; `"failed"`
   * is terminal — `claimPending` only ever selects `"pending"` rows, so a `"failed"` row is
   * permanently excluded from retry regardless of `nextAttemptAt`.
   */
  markFailed(
    required: {
      id: UUID;
      error: string;
      nextAttemptAt: ISODateTime;
      nextStatus: Extract<OutboxRecord["status"], "pending" | "failed">;
    },
    optional?: Record<string, never>
  ): Promise<void>;
}

/** Clock and ID generator contracts are owned by the shared kernel primitives. */

/**
 * Opens/commits/rolls back one transaction around `fn` — the same shape and contract as this
 * codebase's other write chokepoints that need one (`RedirectsWriteDeps.transaction`,
 * `SqliteSettingsRepo.transaction`).
 *
 * `deleteTerm`/`deleteTaxonomy` run their ENTIRE body — every guard read (`findById`,
 * `countChildren`, `countByTerm`) AND every write (`delete`, `revisions.insert`, `outbox.enqueue`)
 * — inside one call to this. Two failure modes this closes that a guard-then-transaction split
 * would not:
 *
 * 1. **TOCTOU on the guard.** A guard read taken BEFORE the transaction opens can go stale the
 *    instant it returns — content can be assigned to the term in the gap between the read and the
 *    delete, and the delete would proceed having checked a now-wrong count. Putting the read
 *    inside the same transaction as the delete is what makes the guard's answer still true at the
 *    moment the delete actually runs.
 * 2. **Partial cascade.** `deleteTaxonomy` deletes N member terms then the taxonomy row itself,
 *    with no FK/CASCADE at the schema level (`db/schema.ts` — `taxonomies`/`terms`/`entry_terms`/
 *    `taxonomy_revisions` are plain columns, no foreign keys) to undo a mid-cascade failure. A
 *    real transaction is the only thing that can.
 *
 * A caller-supplied identity/no-op implementation is a valid choice for a backend that has no
 * separate transaction primitive to offer (see `repo.memory.ts`'s `InMemoryTaxonomyRepo` for the
 * disclosed rationale) — the port exists so `deleteTerm`/`deleteTaxonomy` never have to know which
 * kind of backend they're running against.
 */
export interface TransactionalRepoPort {
  transaction<T>({ fn }: { fn: () => Promise<T> }): Promise<T>;
}

import type { OwningContentType } from "./types.js";

/**
 * @file Typed error surface for the `entries` package.
 *
 * `class X extends Error {}` does NOT give an instance a `.name` of `"X"` on this runtime unless
 * the constructor sets `this.name` explicitly — every class below sets it, matching the
 * `content-types` package's own convention.
 *
 * Architectural role:
 * `features/entries` domain logic. No dependencies.
 */

export class ForbiddenError extends Error {
  constructor({ message }: { message: string }, _optional: Record<string, never> = {}) {
    super(message);
    this.name = "ForbiddenError";
  }
}

export class EntryNotFoundError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "ENTRY_NOT_FOUND";
  }
}

/** — the owning content type does not exist, or exists only in a different workspace. See docs/decisions/DR-002-content-lifecycle-and-cleanup.md. */
export class ContentTypeNotFoundError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "CONTENT_TYPE_NOT_FOUND";
  }
}

/** (create) / (update/publish/unpublish) — the owning content type's status forbids this write. See docs/decisions/DR-002-content-lifecycle-and-cleanup.md. */
export class ContentTypeNotActiveError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "ContentTypeNotActiveError";
  }
}

/** — a second entry submitted with an identical `(workspaceId, type, slug)`. See docs/decisions/DR-002-content-lifecycle-and-cleanup.md. */
export class EntrySlugConflictError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "ENTRY_SLUG_CONFLICT";
  }
}

export class VersionConflictError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "VersionConflictError";
  }
}

/** The compare-and-set loss every `EntryRepoPort.save` adapter throws (one wording for all of them).
 *  `expectedVersion: null` is a create that found the id taken. */
export function entryVersionConflictError(required: { id: string; expectedVersion: number | null; found: number | null }): VersionConflictError {
  const expected = required.expectedVersion === null ? "no entry" : `version ${required.expectedVersion} for entry`;
  return new VersionConflictError({ message: `expected ${expected} '${required.id}', found ${required.found ?? "none"}` });
}

/** — `fieldsJson` failed `validateFieldsAgainstSchema` against the owning type's current schema. See docs/decisions/DR-002-content-lifecycle-and-cleanup.md. */
export class EntryFieldValidationError extends Error {
  readonly fieldErrors: Array<{ field: string; reason: string }>;
  /** Complete declared field schema and its owning namespace, for one-turn correction. */
  readonly entitySchema: { type: string; owner: string; fields: OwningContentType["fields"] } | undefined;

  constructor(requiredArgs: { fieldErrors: Array<{ field: string; reason: string }>; entitySchema?: { type: string; owner: string; fields: OwningContentType["fields"] } }, optionalArgs: Record<string, never> = {}) {
    const { fieldErrors, entitySchema } = requiredArgs;
    super(`fieldsJson failed schema validation: ${fieldErrors.map((e) => `${e.field}: ${e.reason}`).join("; ")}${entitySchema ? `. Entity schema: ${JSON.stringify(entitySchema)}` : ""}`);
    this.name = "EntryFieldValidationError";
    this.fieldErrors = fieldErrors;
    this.entitySchema = entitySchema;
  }
}

import type { ContentTypeFieldDef, ContentTypeFieldKind } from "../content-types/types.js";

/**
 * @file `validateFieldsAgainstSchema`'s envelope-shape-first ordering and
 * `selectVisibleEntryFields`'s orphaned-field read tolerance ("Failure modes",
 * schema drift / dangling fields: "validation is strict on write, tolerant on read").
 *
 * Purpose:
 * The single pure-logic implementation of "does this `fieldsJson` conform to this content type's
 * current schema" — reused identically by `write-service.ts`'s `createEntry`/`updateEntry` and by
 * any future validate-only route, so there is exactly one place this rule can drift.
 * `fieldsJson` must already be wrapped in the `{ ext: { <owner>: {...} } }` namespaced envelope
 * — a flat/unwrapped payload is rejected as a distinct envelope-shape violation
 * BEFORE any per-field check runs, never conflated with a per-field error for a key
 * that happens to share a field's name.
 *
 * Owner namespace (2026-07-21): `validateFieldsAgainstSchema` takes an optional `owner`, defaulting
 * to `"site"` — every caller that omits it keeps the originally-shipped, single-namespace
 * behavior byte-for-byte (same envelope, same error message, same certified test suite).
 * This is the fix for a real, confirmed gap: this module previously hardcoded the literal `site`
 * namespace with no way for a content type to declare its own, contradicting this engine's
 * documented `fields.ext.{owner}.*` promise (first surfaced by a widgets feature, which needs
 * `ext.widget`/`ext.widgets`, not `ext.site`, for data that structurally belongs to a different
 * feature).
 * Since 2026-10-04 `write-service.ts` passes the OWNING TYPE's `owner` here, never a caller's: the
 * caller-chosen version let the generic entries route (which passed none) validate a widget
 * payload under `ext.site` and write a row the widgets reader can never parse.
 * `selectVisibleEntryFields` is intentionally left untouched — it has no production caller anywhere
 * in this codebase today, so widening it now would be speculative; extend it the same way once a
 * real caller needs a non-`site` read projection.
 *
 * Architectural role:
 * `features/entries` domain logic. Type-only dependency on `features/content-types/types`.
 */

export interface FieldValidationError {
  field: string;
  reason: string;
}

export interface ValidateFieldsResult {
  valid: boolean;
  fieldErrors: FieldValidationError[];
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Maximum nesting depth a `json` field's value may reach.
 *
 * A resource bound, not a product rule — the same role `MAX_FIELD_DEFS` plays in
 * `content-types/field-defs.ts`. It is also what makes this check total: a self-referential value
 * (`a.self = a`) is a legal JS object that `JSON.stringify` throws on, and it is the depth cap,
 * not a visited-set, that guarantees this function terminates on one. Deliberately far above any
 * plausible content payload so it can never act as a product constraint.
 */
const MAX_JSON_DEPTH = 32;

/**
 * Maximum number of values (scalars, arrays and objects, counted together) one `json` field may
 * contain. The second half of the termination guarantee above, and the bound that stops a
 * pathological wide-but-shallow payload from making validation the expensive part of a write.
 */
const MAX_JSON_NODES = 10_000;

/**
 * True only for objects that are structurally plain — prototype `Object.prototype` or `null`.
 *
 * Stricter than this module's {@link isPlainObject}, and deliberately so: a `Map`, `Set`, or class
 * instance passes a `typeof === "object"` test and then `JSON.stringify`s to `{}`, silently
 * discarding every value it held. A `Date` survives, but as a string — its type changes at the
 * storage boundary, so a later read gets a different kind of value than the one written. Both are
 * exactly the "accepted here, mangled downstream" class this check exists to reject.
 *
 * Takes an already-narrowed non-null, non-array object: its only caller,
 * {@link isBoundedJsonContainer}, has ruled out `null` and arrays before reaching here.
 */
function isStructurallyPlainObject(value: object): value is Record<string, unknown> {
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/**
 * Verifies that a value is a JSON value — `null`, a boolean, a FINITE number, a string, an array
 * of JSON values, or a plain object whose values are JSON values — within a bounded depth and node
 * budget.
 *
 * This exists because "storage-only" means "not indexed", never "not checked". The obvious
 * alternative — accepting every value for the `json` kind — is not a validator: it admits
 * functions, `symbol`, `bigint`, `undefined`, `NaN`/`Infinity`, and circular references, each of
 * which either throws inside `JSON.stringify` or is silently dropped/coerced by it, downstream of
 * the validator whose entire job was to catch them. Rejecting them here turns a serialization
 * crash (or a silent data loss) at the storage boundary into a named per-field validation error.
 *
 * Symbol-keyed properties are rejected rather than ignored for the same reason `field-defs.ts`
 * rejects an unrecognized key instead of dropping it: `JSON.stringify` discards them, so accepting
 * one would persist a value the caller did not get told was thrown away.
 *
 * @complexity O(n) in the number of contained values, hard-bounded by {@link MAX_JSON_NODES}, and
 * O(d) stack depth bounded by {@link MAX_JSON_DEPTH}. Total on every input, including cyclic ones.
 * @overallScore 100
 */
function isBoundedJsonValue(value: unknown, budget: { nodes: number }, depth = 0): boolean {
  if (depth > MAX_JSON_DEPTH) return false;
  if (budget.nodes <= 0) return false;
  budget.nodes -= 1;

  if (value === null) return true;
  if (typeof value === "object") return isBoundedJsonContainer({ value, budget, depth });
  return isJsonScalar(value);
}

/**
 * The non-container half of {@link isBoundedJsonValue}: true for a boolean, a string, or a FINITE
 * number; false for every other primitive.
 *
 * @complexity O(1).
 */
function isJsonScalar(value: unknown): boolean {
  switch (typeof value) {
    case "boolean":
    case "string":
      return true;
    case "number":
      // `NaN`/`Infinity` are numbers that `JSON.stringify` silently rewrites to `null` — a value
      // that reads back as a different type than the one written.
      return Number.isFinite(value);
    default:
      // `undefined`, `function`, `symbol`, `bigint`: dropped, dropped, dropped, and throws.
      return false;
  }
}

/**
 * The container half of {@link isBoundedJsonValue}: an array of JSON values, or a structurally
 * plain object with no symbol keys whose values are JSON values. Each child is checked one level
 * deeper against the SAME shared node budget.
 *
 * @complexity O(n) in the number of contained values, bounded as {@link isBoundedJsonValue} is.
 */
function isBoundedJsonContainer(required: { value: object; budget: { nodes: number }; depth: number }): boolean {
  const { value, budget, depth } = required;
  const isChildJson = (child: unknown): boolean => isBoundedJsonValue(child, budget, depth + 1);
  if (Array.isArray(value)) return value.every(isChildJson);
  if (!isStructurallyPlainObject(value)) return false;
  if (Object.getOwnPropertySymbols(value).length > 0) return false;
  return Object.values(value).every(isChildJson);
}

/**
 * Runtime-conformance check for one field's value against its declared kind. Loose by design
 * (e.g. `datetime` accepts any string) — kind-conformance here is about JS runtime shape, not
 * full ISO-8601/format validation, which is out of this package's scope.
 *
 * The `default: return false` arm is load-bearing: a kind added to `ContentTypeFieldKind` without
 * an arm here does not fail the build, it produces a field that can be DECLARED but whose every
 * value is rejected on write. Any future kind must be added here in the same change.
 *
 * @complexity O(1) for every scalar kind; O(n) bounded by `MAX_JSON_NODES` for `json`.
 * @overallScore 100
 */
function conformsToKind(value: unknown, kind: ContentTypeFieldKind): boolean {
  switch (kind) {
    case "text":
    case "datetime":
    // A foreign entity id. String-shaped exactly like `text`; referential integrity is NOT checked
    // here and is not checked anywhere — this function is a pure runtime-shape check with no repo
    // access, and giving it one would put an I/O dependency into a module whose header commits to
    // having none. The gap is real and belongs to the application layer.
    case "relation":
      return typeof value === "string";
    case "integer":
      return typeof value === "number" && Number.isInteger(value);
    case "real":
      return typeof value === "number";
    case "boolean":
      return typeof value === "boolean";
    // Storage-only: no scalar shape is imposed, but the value must still be something that
    // survives the `JSON.stringify` boundary intact. See `isBoundedJsonValue`.
    case "json":
      return isBoundedJsonValue(value, { nodes: MAX_JSON_NODES });
    default:
      return false;
  }
}

/**
 * — validates a candidate `fieldsJson` payload against a content type's current field
 * schema: envelope shape first, then per-key unrecognized-field rejection and
 * kind-conformance, then a required-field-missing pass.
 *
 * @complexity O(f) in the number of schema fields plus O(k) in the number of submitted keys.
 * @overallScore 100
 * See docs/decisions/DR-002-content-lifecycle-and-cleanup.md.
 */
export function validateFieldsAgainstSchema(required: {
  schema: ContentTypeFieldDef[];
  fieldsJson: unknown;
}, optional: {
  /** The `ext` sub-key this content type's fields live under. Defaults to `"site"` — every existing caller keeps identical behavior unless it opts into a different owner namespace. */
  owner?: string | undefined;
} = {}): ValidateFieldsResult {
  const { schema, fieldsJson } = required;
  const { owner = "site" } = optional;

  const ownerBag = readOwnerBag({ fieldsJson, owner });
  if (!ownerBag) {
    return {
      valid: false,
      fieldErrors: [{ field: "__envelope__", reason: `fieldsJson must be wrapped in the { ext: { ${owner}: {...} } } envelope shape` }],
    };
  }

  const fieldErrors = [...collectSubmittedKeyErrors({ schema, ownerBag }), ...collectMissingRequiredErrors({ schema, ownerBag })];
  return { valid: fieldErrors.length === 0, fieldErrors };
}

/**
 * Unwraps `fieldsJson.ext[owner]`, or returns `undefined` when any level of the
 * `{ ext: { <owner>: {...} } }` envelope is missing or not a plain object. The one envelope reader
 * shared by the strict write-side check and the tolerant read-side projection.
 *
 * @complexity O(1).
 */
function readOwnerBag(required: { fieldsJson: unknown; owner: string }): Record<string, unknown> | undefined {
  const { fieldsJson, owner } = required;
  const ext = isPlainObject(fieldsJson) ? fieldsJson.ext : undefined;
  const ownerBag = isPlainObject(ext) ? ext[owner] : undefined;
  return isPlainObject(ownerBag) ? ownerBag : undefined;
}

/**
 * The per-key pass: every submitted key must name a field in the current schema, and its value
 * must conform to that field's declared kind. Errors are reported in submitted-key order.
 *
 * @complexity O(f + k) in schema fields and submitted keys.
 */
function collectSubmittedKeyErrors(required: { schema: ContentTypeFieldDef[]; ownerBag: Record<string, unknown> }): FieldValidationError[] {
  const schemaByName = new Map(required.schema.map((f) => [f.name, f]));
  const fieldErrors: FieldValidationError[] = [];
  for (const [key, value] of Object.entries(required.ownerBag)) {
    const def = schemaByName.get(key);
    if (!def) {
      fieldErrors.push({ field: key, reason: "unrecognized field: not present in the current content-type schema" });
    } else if (!conformsToKind(value, def.kind)) {
      fieldErrors.push({ field: key, reason: `value does not conform to the declared kind '${def.kind}'` });
    }
  }
  return fieldErrors;
}

/**
 * The required-field pass: every `required` schema field must be an OWN key of the owner bag.
 * Errors are reported in schema order.
 *
 * @complexity O(f) in schema fields.
 */
function collectMissingRequiredErrors(required: { schema: ContentTypeFieldDef[]; ownerBag: Record<string, unknown> }): FieldValidationError[] {
  return required.schema
    .filter((def) => def.required && !Object.prototype.hasOwnProperty.call(required.ownerBag, def.name))
    .map((def) => ({ field: def.name, reason: "required field is missing" }));
}

/**
 * Projects an entry's `fieldsJson.ext.site` down to only the keys still present in
 * the content type's CURRENT schema, silently dropping orphaned keys left behind by a prior field
 * removal rather than erroring ("Failure modes": "validation is strict on write, tolerant
 * on read").
 *
 * @complexity O(k) in the number of keys present on the entry's stored fields bag.
 * @overallScore 100
 */
export function selectVisibleEntryFields(required: {
  entry: { fieldsJson: unknown };
  contentType: { fields: ContentTypeFieldDef[] };
}): Record<string, unknown> {
  const site = readOwnerBag({ fieldsJson: required.entry.fieldsJson, owner: "site" });
  const allowedNames = new Set(required.contentType.fields.map((f) => f.name));

  const visible: Record<string, unknown> = {};
  if (!site) return visible;
  for (const [key, value] of Object.entries(site)) {
    if (allowedNames.has(key)) visible[key] = value;
  }
  return visible;
}

import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
import type { Clock } from "@jini-ai/core/primitives";
import { entryVersionConflictError } from "./errors.js";
import type { EntryRepoPort, EntryRevisionInput, EntrySaveOptions, OutboxPort } from "./write-service.js";
import type { EntryListPort } from "./list.js";
import type { EntryRecord, EntryStatus } from "./types.js";

/**
 * @file In-memory `EntryRepoPort` + `EntryListPort` double (same disclosed rule-of-two-until-a-
 * real-adapter-exists precedent as `features/content-types/repo.memory.ts` — see that file's
 * header for the full disclosure, which applies identically here).
 */
export class InMemoryEntryRepo implements EntryRepoPort, EntryListPort {
  private readonly byId = new Map<string, EntryRecord>();
  private revisions: EntryRevisionInput[] = [];

  private static slugKey(workspaceId: string, type: string, slug: string): string {
    return `${workspaceId}::${type}::${slug}`;
  }

  async findBySlug(params: { workspaceId: string; type: string; slug: string }): Promise<EntryRecord | null> {
    const target = InMemoryEntryRepo.slugKey(params.workspaceId, params.type, params.slug);
    for (const row of this.byId.values()) {
      if (InMemoryEntryRepo.slugKey(row.workspaceId, row.type, row.slug) === target) return { ...row };
    }
    return null;
  }

  async findById(params: { workspaceId: string; id: string }): Promise<EntryRecord | null> {
    const row = this.byId.get(params.id);
    return row && row.workspaceId === params.workspaceId ? { ...row } : null;
  }

  async save(row: EntryRecord, options: EntrySaveOptions = {}): Promise<void> {
    if (options.expectedVersion !== undefined) {
      const stored = this.byId.get(row.id);
      // A create (`null`) needs the id free in every workspace: the id is the key here, as the
      // primary key is in a SQL adapter, so a foreign row with it would be overwritten.
      const found = stored && (options.expectedVersion === null || stored.workspaceId === row.workspaceId) ? stored.version : null;
      if (found !== options.expectedVersion) throw entryVersionConflictError({ id: row.id, expectedVersion: options.expectedVersion, found });
    }
    this.byId.set(row.id, { ...row });
  }

  async appendRevision(revision: EntryRevisionInput): Promise<void> {
    this.revisions.push(revision);
  }

  /** Memory-only purge seam: removes the scoped entry and its revision history. Missing or foreign
   * entries are unchanged. @complexity O(r) time and space over stored revisions. */
  async hardDelete(required: { workspaceId: string; id: string }, _optional: Record<string, never> = {}): Promise<void> {
    const row = this.byId.get(required.id);
    if (!row || row.workspaceId !== required.workspaceId) return;
    this.byId.delete(required.id);
    this.revisions = this.revisions.filter(revision => revision.workspaceId !== required.workspaceId || revision.entryId !== required.id);
  }

  async transaction<T>({ fn }: { fn: () => Promise<T> }): Promise<T> {
    return fn();
  }

  async listByWorkspace(required: { workspaceId: string }, optional: {
    type?: string | undefined;
    status?: EntryStatus | undefined;
    orderBy?: "updatedAt" | undefined;
    orderDirection?: "asc" | "desc" | undefined;
    limit?: number | undefined;
  } = {}): Promise<EntryRecord[]> {
    let rows = [...this.byId.values()]
      .filter((row) => row.workspaceId === required.workspaceId)
      .filter((row) => !optional.type || row.type === optional.type)
      .filter((row) => !optional.status || row.status === optional.status);

    if (optional.orderBy === "updatedAt") {
      const dir = optional.orderDirection === "asc" ? 1 : -1;
      rows = rows.sort((a, b) => (a.updatedAt < b.updatedAt ? -dir : a.updatedAt > b.updatedAt ? dir : 0));
    }
    if (typeof optional.limit === "number") {
      rows = rows.slice(0, optional.limit);
    }
    return rows.map((row) => ({ ...row }));
  }
}

/** Adapts a real `core/ports` `OutboxPort` into the narrower `{enqueue({name,payload})}` shape
 * `entries/write-service.ts` declares locally — same pattern as
 * `features/content-types/repo.memory.ts`'s `toContentTypeOutbox`.
 *
 * `workspaceId` is REQUIRED and is declared on the wrapped port's event type on purpose. A real
 * `core/ports` `DomainEvent` carries `workspaceId` as a non-optional tenant boundary, and
 * persistent adapters store it in a NOT NULL column. This wrapper previously under-declared the
 * wrapped port as `{id,name,occurredAt,payload}` and constructed an event without `workspaceId`, so
 * a host binding a SQLite outbox typechecked cleanly and then threw
 * `NOT NULL constraint failed: outbox_events.workspace_id` on every write. Sourcing it from `deps`
 * rather than from `event.payload` is deliberate: the narrow local port carries only `{name,payload}`
 * and payload contents are per-event convention, not a contract. */
export function toEntryOutbox(deps: {
  outbox: {
    enqueue(event: {
      id: string;
      workspaceId: string;
      name: string;
      occurredAt: string;
      payload: Record<string, unknown>;
    }): Promise<void>;
  };
  clock: Clock;
  idGen: { newId(): string };
  workspaceId: string;
}): OutboxPort {
  return {
    enqueue: async (event) => {
      await deps.outbox.enqueue({
        id: deps.idGen.newId(),
        workspaceId: deps.workspaceId,
        name: event.name,
        occurredAt: kernelNowIso({ clock: deps.clock }),
        payload: event.payload,
      });
    },
  };
}

/** Definition constraints beyond the original four-type schema; every invalid definition fails closed. */
import type { FieldDescriptor } from "./types.js";
import { FIELD_TYPE_REGISTRY, isBrowserSafeFieldPattern, isSafeFieldPattern, MAX_FORM_FILE_BYTES, resolveFormField, SAFE_FORM_FILE_TYPES } from "./field-registry.js";
import type { FieldError } from "./forms.js";
const KEYS: ReadonlySet<string> = new Set(["id", "name", "label", "type", "required", "placeholder", "helpText", "default", "options", "minLength", "maxLength", "pattern", "min", "max", "step", "accept", "maxFileSize", "checkboxValue", "className", "attributes"]);
const TEMPORAL: ReadonlySet<string> = new Set(["date", "time", "datetime"]);
const WILDCARD_ACCEPTS: readonly string[] = ["image/*", "video/*", "*/*"];
type BoundAxis = "numeric" | "temporal" | "none";
type Option = NonNullable<FieldDescriptor["options"]>[number];

/** Explicit numeric properties win; legacy string attributes are read as numbers. */
const numberOrAttribute = (explicit: number | undefined, attribute: string | undefined): number | undefined =>
  explicit ?? (attribute === undefined ? undefined : Number(attribute));
const kindFlags = (field: FieldDescriptor): { textual?: boolean; choices?: boolean } => FIELD_TYPE_REGISTRY[field.type] as { textual?: boolean; choices?: boolean };

function minLengthErrors(field: FieldDescriptor, textual: boolean): string[] {
  const minLength = numberOrAttribute(field.minLength, field.attributes?.minlength);
  if (minLength === undefined) return [];
  const inBounds = Number.isInteger(minLength) && minLength >= 0 && minLength <= (field.maxLength ?? 5000);
  return textual && inBounds ? [] : ["minLength must be an integer within the text length bounds"];
}
function maxLengthErrors(field: FieldDescriptor, textual: boolean): string[] {
  if (field.type === "checkbox" || field.maxLength == null) return [];
  return textual && Number.isInteger(field.maxLength) ? [] : ["maxLength is only supported on text fields and must be an integer"];
}
function patternErrors(field: FieldDescriptor, textual: boolean): string[] {
  const pattern = field.pattern ?? field.attributes?.pattern;
  if (pattern === undefined) return [];
  if (!textual || typeof pattern !== "string" || !isSafeFieldPattern({ pattern })) return ["pattern must be a safe text pattern (no groups, alternation, backreferences or multiple repetitions)"];
  return isBrowserSafeFieldPattern({ pattern }) ? [] : ["pattern is ignored by browsers: escape '-' and other symbols inside [...] with a backslash, e.g. [0-9 +.\\-]"];
}
/** Text rules apply to explicit descriptor properties and their legacy attributes alike. */
function textConstraints(field: FieldDescriptor): string[] {
  const textual = kindFlags(field).textual === true;
