  if (typeof descriptor.label !== "string") return [{ field: label, reason: "label must be a string" }];
  if (descriptor.label.length < MIN_LABEL_LENGTH || descriptor.label.length > MAX_LABEL_LENGTH) {
    return [{ field: label, reason: `label must be ${MIN_LABEL_LENGTH}-${MAX_LABEL_LENGTH} characters` }];
  }
  return [];
}

// A checkbox carries a boolean, so no character cap can be honored. Report that prohibition
// before any numeric range error, rather than asking the author to fix a number they must remove.
function maxLengthErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  if (descriptor.maxLength == null) return [];
  if (descriptor.type === "checkbox") {
    return [{ field: label, reason: "maxLength is forbidden for checkbox fields" }];
  }
  if (descriptor.maxLength < MIN_MAX_LENGTH || descriptor.maxLength > MAX_MAX_LENGTH) {
    return [{ field: label, reason: `maxLength must be ${MIN_MAX_LENGTH}-${MAX_MAX_LENGTH}` }];
  }
  return [];
}

function checkboxValueErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  if (descriptor.checkboxValue === undefined) return [];
  if (descriptor.type !== "checkbox" || typeof descriptor.checkboxValue !== "string") {
    return [{ field: label, reason: "checkboxValue must be a string on a checkbox field" }];
  }
  return [];
}

// HTML-escaped class names are inert; only their length is bounded. Check type defensively
// because real inputs include parsed request bodies, regardless of the descriptor's static type.
function classNameErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  const { className } = descriptor;
  if (className == null) return [];
  if (typeof className !== "string") {
    return [{ field: label, reason: "className must be a string" }];
  }
  if (className.length > MAX_CLASS_NAME_LENGTH) {
    return [{ field: label, reason: `className must be at most ${MAX_CLASS_NAME_LENGTH} characters` }];
  }
  return [];
}

// A refused name will never render, so its value is moot. Reporting value errors as well would
// imply that correcting a value could make a structurally unsafe attribute acceptable.
function attributeEntryErrors(label: string, attrName: string, attrValue: unknown): FieldError[] {
  if (!ATTRIBUTE_NAME_PATTERN.test(attrName)) {
    return [{ field: label, reason: `attribute '${attrName}' is not allowed` }];
  }
  if (typeof attrValue !== "string") {
    return [{ field: label, reason: `attribute '${attrName}' value must be a string` }];
  }
  if (attrValue.length > MAX_ATTRIBUTE_VALUE_LENGTH) {
    return [{ field: label, reason: `attribute '${attrName}' value must be at most ${MAX_ATTRIBUTE_VALUE_LENGTH} characters` }];
  }
  return [];
}

// Exceeding the count cap still checks every attribute so the author sees unsafe names in one
// round trip. This visits O(a) caller-supplied attributes; the reported cap does not truncate work.
function attributeErrors(descriptor: FieldDescriptor, label: string): FieldError[] {
  const { attributes } = descriptor;
  if (attributes == null) return [];

  const entries = Object.entries(attributes);
  const errors: FieldError[] = [];
  if (entries.length > MAX_ATTRIBUTES_PER_FIELD) {
    errors.push({ field: label, reason: `at most ${MAX_ATTRIBUTES_PER_FIELD} attributes are allowed` });
  }
  for (const [attrName, attrValue] of entries) {
    errors.push(...attributeEntryErrors(label, attrName, attrValue));
  }
  return errors;
}

/**
 * Collect every violation, not just the first: arity errors, then descriptors in array order,
 * then each rule in the fixed order below. Callers display this list as-is, so order is observable.
 * Empty helper results mean a satisfied rule. Bounds are 1-20 fields, labels 1-200 characters,
 * and maxLength 1-5000 (never on checkboxes), with unique lowercase field IDs.
 */
export function validateFieldDescriptors({ fields }: { fields: FieldDescriptor[] }, _optional = {}): FieldValidationResult {
  if (!Array.isArray(fields)) return { valid: false, fieldErrors: [{ field: "fields", reason: "must be an array" }] };
  const fieldErrors: FieldError[] = arityErrors(fields);

  const claimedIds = new Set<string>();
  for (const descriptor of fields) fieldErrors.push(...descriptorErrors(descriptor, claimedIds));

  if (fieldErrors.length > 0) return { valid: false, fieldErrors };
  return { valid: true };
}

function arityErrors(fields: FieldDescriptor[]): FieldError[] {
  if (fields.length < MIN_FIELDS) return [{ field: "fields", reason: `at least ${MIN_FIELDS} field is required` }];
  if (fields.length > MAX_FIELDS) return [{ field: "fields", reason: `at most ${MAX_FIELDS} fields are allowed` }];
  return [];
}

// One descriptor's violations, each rule in the fixed order validateFieldDescriptors documents.
function descriptorErrors(descriptor: FieldDescriptor, claimedIds: Set<string>): FieldError[] {
  if (!descriptor || typeof descriptor !== "object" || Array.isArray(descriptor)) return [{ field: "fields", reason: "each field must be an object" }];
  const label = descriptor.id || "(unknown)";
  return [
    ...fieldIdErrors(descriptor, label, claimedIds),
    ...fieldTypeErrors(descriptor, label),
    ...labelLengthErrors(descriptor, label),
    ...maxLengthErrors(descriptor, label),
    ...checkboxValueErrors(descriptor, label),
    ...classNameErrors(descriptor, label),
    ...attributeErrors(descriptor, label),
    ...commonDescriptorErrors({ field: descriptor }),
  ];
}

export interface ValidateSubmissionPayloadInput {
  definition: FormDefinitionRecord;
  body: Record<string, unknown>;
}

export type SubmissionValidationResult =
  | { valid: true; data: Record<string, FormAnswer>; files?: Record<string, FormFileInput> }
  | { valid: false; fieldErrors: FieldError[] };

// Absence is distinct from acceptance: treating an omitted optional field as an accepted value
// would write undefined and violate the guarantee that stored answers contain only declared keys.
// The honeypot is tolerated in the raw body, but is excluded from stored answers.
// Whitespace is rejected only for required text; optional whitespace is an answer the definition
// permits. Preserve the submitted string instead of silently trimming its stored value.
// Native URL-encoded forms submit "on" for checked boxes without a value attribute; accepting
// only JSON booleans would reject every checked checkbox when client JavaScript is disabled.
// An unticked native checkbox omits its key; submission resolution treats that as absence.
// JSON and native forms differ in how they represent missing values, so null/undefined both
// mean absence. Boolean false is a real checkbox answer, only for optional native checkboxes; required consent must be checked.
function unregisteredKeyErrors(body: Record<string, unknown>, fieldsById: ReadonlyMap<string, FieldDescriptor>): FieldError[] {
  return Object.keys(body).filter((key) => key !== HONEYPOT_KEY && !fieldsById.has(key)).map((field) => ({ field, reason: "unregistered_key" }));
}

/**
 * Only declared, accepted fields reach data; the reserved honeypot never does. Report unknown
 * body keys first, then declared-field errors in definition order, independent of body key order.
 * This keeps the declared-field portion of the error list stable across equivalent submissions.
 */
export function validateSubmissionPayload(input: ValidateSubmissionPayloadInput, optional: { files?: Pick<FormFileStoragePort, "detectContentType"> } = {}): SubmissionValidationResult {
  const { definition, body } = input;
  if (!body || typeof body !== "object" || Array.isArray(body)) return { valid: false, fieldErrors: [{ field: "body", reason: "must be an object" }] };
  const fieldsById = new Map<string, FieldDescriptor>(definition.fields.map((f) => [f.id, f]));

  const fieldErrors: FieldError[] = unregisteredKeyErrors(body, fieldsById);
  const data: Record<string, FormAnswer> = {};
  const files: Record<string, FormFileInput> = {};

  for (const field of definition.fields) {
    const resolved = resolveFormField({ field, value: Object.hasOwn(body, field.id) ? body[field.id] : undefined }, optional);
    recordResolvedField({ fieldId: field.id, resolved, fieldErrors, data, files });
  }

  if (fieldErrors.length > 0) return { valid: false, fieldErrors };
  return Object.keys(files).length ? { valid: true, data, files } : { valid: true, data };
}

// Absent fields land nowhere: neither an error, nor a stored answer, nor an upload.
function recordResolvedField({ fieldId, resolved, fieldErrors, data, files }: {
  fieldId: string;
  resolved: FieldResolution;
  fieldErrors: FieldError[];
  data: Record<string, FormAnswer>;
  files: Record<string, FormFileInput>;
}): void {
  if (resolved.kind === "rejected") fieldErrors.push({ field: fieldId, reason: resolved.reason });
  else if (resolved.kind === "accepted") data[fieldId] = resolved.value;
  else if (resolved.kind === "upload") files[fieldId] = resolved.file;
}

// Only a non-empty trimmed string trips the trap; absent, non-string or whitespace-only values
// do not reject an otherwise valid submission.
export function isHoneypotTripped(input: { hp: unknown }, _optional = {}): boolean {
  if (typeof input.hp !== "string") return false;
  return input.hp.trim().length > 0;
}

/** Framework-free HTML renderer, kept separate for extraction into @jini-ai/cms/forms.
 * Local prototype authorized 2026-10-04; that original dispatch kept Jini read-only.
 * The host owns the endpoint and the form's styling hook; author markup and CSS refine it. */
import type { FieldDescriptor } from "./types.js";
import { ATTRIBUTE_NAME_PATTERN, FIELD_TYPE_REGISTRY, isSafeFieldPattern } from "./field-registry.js";

// Renderers need the shared retry copy without importing the forms service/repository barrel.
export { FORM_SUBMISSION_TOO_FAST_MESSAGE } from "./errors.js";

/** Attribute names are trusted host constants, not visitor input. Values are always escaped. */
export interface FormHtmlHooks { field: string; form: string; success: string; error: string; }

export function escapeFormHtml({ value }: { value: string }, _optional = {}): string {
  return value.replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!);
}

/** Renderer hooks retain the CMS's established styling/error anchors without defining a theme. */
export interface FormBodyOptions {
  submitLabel?: string;
  idPrefix?: string;
  fieldClass?: string;
  errorClass?: string;
}
const attr = (name: string, value: string | number): string => ` ${name}="${escapeFormHtml({ value: String(value) })}"`;

/** Extra attributes cannot override structural or server-backed constraints. Values are escaped at this sink. */
function extraAttributes(field: FieldDescriptor, claimed: ReadonlySet<string>): string {
  return Object.entries(field.attributes ?? {}).filter(([name, value]) => ATTRIBUTE_NAME_PATTERN.test(name) && !claimed.has(name) && typeof value === "string" && (name !== "pattern" || isSafeFieldPattern({ pattern: value }))).map(([name, value]) => attr(name, value)).join("");
}
type RenderKind = { control: string; htmlType: string; multiple?: boolean; attributes?: Readonly<Record<string, string>> };
/** What every control shape of one field shares, computed once per field. */
interface FieldMarkup { field: FieldDescriptor; kind: RenderKind; id: string; label: string; describedBy: string; required: string; base: string; extra: string; help: string; error: string; fieldClass: string; defaultValues: unknown[] }

const isRenderableField = (field: FieldDescriptor): boolean =>
  Boolean(field) && typeof field.id === "string" && typeof field.label === "string" && Object.hasOwn(FIELD_TYPE_REGISTRY, field.type);
const requiredMark = (field: FieldDescriptor): string => (field.required ? " *" : "");
const constraintEntries = (field: FieldDescriptor) => [
  ["placeholder", field.placeholder], ["minlength", field.minLength], ["maxlength", field.maxLength], ["pattern", field.pattern],
  ["min", field.min], ["max", field.max], ["step", field.step],
] as const;
/** Lengths must be integers (maxlength positive) and patterns safe, or the attribute is dropped. */
function isRenderableConstraint(name: string, value: string | number): boolean {
  if (name === "maxlength") return Number.isInteger(value) && Number(value) > 0;
  if (name === "minlength") return Number.isInteger(value) && Number(value) >= 0;
  return name !== "pattern" || isSafeFieldPattern({ pattern: String(value) });
}
/** Class, validated constraints, then registry attributes, then any unclaimed authored extras. */
function controlAttributes(field: FieldDescriptor, kind: RenderKind): string {
  const claimed = new Set(["aria-describedby"]);
  let extra = field.className ? attr("class", field.className) : "";
  for (const [name, value] of constraintEntries(field)) {
    if (value == null || !isRenderableConstraint(name, value)) continue;
    extra += attr(name, value); claimed.add(name);
  }
  // Registry-owned control semantics take precedence over authored extra attributes.
  for (const [name, value] of Object.entries(kind.attributes ?? {})) {
    extra += attr(name, value); claimed.add(name);
  }
  return extra + extraAttributes(field, claimed);
}
function fieldIds(field: FieldDescriptor, options: FormBodyOptions): { id: string; helpId: string; errorId: string; describedBy: string } {
  const id = `${options.idPrefix ?? "form"}-${field.id}`;
  const helpId = `${id}-help`; const errorId = `${id}-error`;
  const describedBy = [field.helpText ? helpId : "", errorId, field.attributes?.["aria-describedby"] ?? ""].filter(Boolean).join(" ");
  return { id, helpId, errorId, describedBy };
}
function fieldSlots(field: FieldDescriptor, { helpId, errorId, options }: { helpId: string; errorId: string; options: FormBodyOptions }): { help: string; error: string } {
  const help = field.helpText ? `<div${attr("id", helpId)} class="widget-form-field-help">${escapeFormHtml({ value: field.helpText })}</div>` : "";
  const error = `<div${attr("class", options.errorClass ?? "widget-form-field-error")}${attr("data-field", field.id)}${attr("id", errorId)} hidden></div>`;
  return { help, error };
}
function fieldMarkup(field: FieldDescriptor, { hooks, options }: { hooks: Pick<FormHtmlHooks, "field">; options: FormBodyOptions }): FieldMarkup {
  const kind = FIELD_TYPE_REGISTRY[field.type] as RenderKind;
  const { id, helpId, errorId, describedBy } = fieldIds(field, options);
  return {
    field, kind, id, describedBy,
    label: escapeFormHtml({ value: field.label }),
    required: field.required ? " required" : "",
    base: attr("name", field.name ?? field.id) + attr(hooks.field, field.id) + attr("toolparamtitle", field.label) + attr("toolparamdescription", field.helpText ?? field.label) + attr("aria-describedby", describedBy),
    extra: controlAttributes(field, kind),
    ...fieldSlots(field, { helpId, errorId, options }),
    fieldClass: options.fieldClass ?? "widget-form-field",
    defaultValues: Array.isArray(field.default) ? field.default : [field.default],
  };
}
function renderGroupOption(markup: FieldMarkup, { option, index }: { option: { value: string; label: string }; index: number }): string {
  const { id, kind, base, extra, required, defaultValues } = markup;
  const optionId = `${id}-${index}`;
  const checked = defaultValues.includes(option.value) ? " checked" : "";
  // Native checkbox-group required on each box means ALL, so server enforces one-or-more;
  // aria-required communicates the group's requirement without changing that invariant.
  const optionRequired = kind.multiple ? "" : required;
  return `<label${attr("for", optionId)}><input${attr("id", optionId)}${attr("type", kind.htmlType)}${base}${attr("value", option.value)}${checked}${optionRequired}${extra}>${escapeFormHtml({ value: option.label })}</label>`;
}
function renderGroup(markup: FieldMarkup): string {
  const { field, id, describedBy, label, help, error } = markup;
  const inputs = (field.options ?? []).map((option, index) => renderGroupOption(markup, { option, index })).join("");
  return `<fieldset${attr("id", id)}${attr("class", markup.fieldClass)}${attr("aria-describedby", describedBy)}${field.required ? ' aria-required="true"' : ""}><legend>${label}${requiredMark(field)}</legend>${inputs}${help}${error}</fieldset>`;
}
function renderSelect({ field, kind, id, base, required, extra, defaultValues }: FieldMarkup): string {
  const placeholder = kind.multiple ? "" : `<option value="">${escapeFormHtml({ value: field.placeholder ?? "Choose an option" })}</option>`;
  const choices = (field.options ?? []).map((option) => `<option${attr("value", option.value)}${defaultValues.includes(option.value) ? " selected" : ""}>${escapeFormHtml({ value: option.label })}</option>`).join("");
  return `<select${attr("id", id)}${base}${kind.multiple ? " multiple" : ""}${required}${extra}>${placeholder}${choices}</select>`;
}
function checkboxValueAttributes(field: FieldDescriptor): string {
  const value = field.checkboxValue !== undefined ? attr("value", field.checkboxValue) : "";
  return value + (field.default === true || field.default === field.checkboxValue && field.default !== undefined ? " checked" : "");
}
function inputValueAttributes(field: FieldDescriptor, kind: RenderKind): string {
  if (field.type === "file") return field.accept ? attr("accept", field.accept.join(",")) : "";
  if (kind.htmlType === "checkbox") return checkboxValueAttributes(field);
  return field.default !== undefined ? attr("value", String(field.default)) : "";
}
function renderControl(markup: FieldMarkup): string {
  const { field, kind, id, base, required, extra } = markup;
  if (kind.control === "select") return renderSelect(markup);
  if (kind.control === "textarea") return `<textarea${attr("id", id)}${base}${required}${extra}>${escapeFormHtml({ value: String(field.default ?? "") })}</textarea>`;
  return `<input${attr("type", kind.htmlType)}${attr("id", id)}${base}${field.type === "toggle" ? ' role="switch"' : ""}${required}${inputValueAttributes(field, kind)}${extra}>`;
}
/** One registry control rendered with label/legend, help/error associations and escaped defaults. */
function renderField(field: FieldDescriptor, hooks: Pick<FormHtmlHooks, "field">, options: FormBodyOptions): string {
  if (!isRenderableField(field)) return "";
  const markup = fieldMarkup(field, { hooks, options });
  if (markup.kind.control === "group") return renderGroup(markup);
  const control = renderControl(markup);
  if (field.type === "hidden") return control;
  // The checkbox modifier lets the baseline put the box before its label on one line (owner report
  // 2026-10-05: stacked and stretched like a text input, its glyph drew centred under the label).
  const fieldClass = markup.fieldClass + (markup.kind.htmlType === "checkbox" ? " widget-form-field-checkbox" : "");
  return `<div${attr("class", fieldClass)}><label${attr("for", markup.id)}>${markup.label}${requiredMark(field)}</label>${control}${markup.help}${markup.error}</div>`;
}

/** Shared body for authored and builder forms; every field's HTML semantics come from the registry.
 * @complexity O(f + o) for fields and their bounded option lists, no I/O. */
export function renderHtmlFormBody(
  { fields, hooks }: { fields: readonly FieldDescriptor[]; hooks: Pick<FormHtmlHooks, "field"> },
  options: FormBodyOptions = {},
): string {
  return fields.map((field) => renderField(field, hooks, options)).join("\n") + `\n<button type="submit">${escapeFormHtml({ value: options.submitLabel ?? "Send" })}</button>`;
}

/** `className` is the host's styling hook (the host passes its form CSS class so the active theme's form rules
 * apply); author CSS stays free to override it. Whitespace-separated, de-duplicated, never replaced. */
export function renderHtmlForm(
  { slug, fields, action, hooks }: { slug: string; fields: readonly FieldDescriptor[]; action: string; hooks: FormHtmlHooks },
  { html, successMessage = "Thanks — your message has been sent.", className }: { html?: string; successMessage?: string; className?: string } = {},
): string {
  const escapedSlug = escapeFormHtml({ value: slug });
  const slugHook = `data-form-slug="${escapedSlug}"`;
  const classes = [...new Set((className ?? "").split(/\s+/).filter(Boolean))].join(" ");
  const classAttr = classes ? `class="${escapeFormHtml({ value: classes })}" ` : "";
  return `<div ${hooks.success} ${slugHook} role="status" hidden>${escapeFormHtml({ value: successMessage })}</div>` +
    `<form ${classAttr}${hooks.form}="${escapedSlug}" ${slugHook} toolname="form_${escapeFormHtml({ value: slug.replace(/[^A-Za-z0-9_.-]/g, '_').slice(0, 123) })}" tooldescription="${escapedSlug}" method="post"${fields.some((field) => field.type === "file") ? ' enctype="multipart/form-data"' : ""} action="${escapeFormHtml({ value: action })}">` +
    `<div ${hooks.error} ${slugHook} role="alert" hidden></div>` +
    (html ?? renderHtmlFormBody({ fields, hooks }, { idPrefix: `form-${slug}` })) +
    // Hidden container requires neither a theme class nor inline CSS; bots still see the input.
    `<div hidden aria-hidden="true"><input type="text" name="_hp" tabindex="-1" autocomplete="off"></div></form>`;
}

/* Migration rationale retained from the host renderer:

 * Renders one field descriptor's `class`/extra-attribute string, both attached to the SAME
 * rendered input element the field's own `id`/`name`/`required`/`type` already get. Re-checks
 * `ATTRIBUTE_NAME_PATTERN` here rather than trusting that every stored field passed through
 * `forms.ts`'s `validateFieldDescriptors` (this is the public render path, REQ-37/ADR-047) —
 * defense in depth, since an attribute NAME is not something `escapeHtml` can make safe the way it
 * can a value (`onclick` is structurally dangerous regardless of how its own text is escaped).
 * `className` carries no such risk once escaped, so it is not re-validated, only escaped.

 One `<textarea>`/checkbox/text-or-email `<input>` for a contact-form field descriptor — pulled out
 *  of {@link renderField}'s old three-way nested ternary so each shape is a flat, separately
 *  readable branch rather than one expression whose nesting depth drove the field-renderer's cognitive
 *  complexity. `requiredAttr` is computed once and reused across all three shapes, same value the old
 *  nested ternary recomputed per-branch. `describedByAttr` wires the field to its own (initially empty
 *  and hidden) error slot for assistive tech — see {@link renderField}'s own doc for why
 *  that slot exists even though nothing fills it in on the very first render.
 The field's own `maxLength` as a `maxlength` attribute, so the browser stops input at the same
 *  limit `forms.ts`'s `validateSubmissionPayload` enforces (`too_long`) instead of letting a visitor
 *  type past it and lose the submission to a server rejection. Only a positive integer renders —
 *  the value comes from stored JSON, so anything else is dropped rather than interpolated.
 *  @complexity O(1).
 One contact-form field descriptor -> its `<div class="widget-form-field">` markup — extracted from
 *  {@link renderWidgetContactForm}'s old inline `.map()` callback so the field's own render logic is a
 *  named, independently measured function rather than an anonymous closure.
 *
 *  Carries its own `<div class="widget-form-field-error" data-field="ID" hidden></div>` slot, hidden
 *  and empty on every ordinary render — `renderWidgetContactForm` has no request in scope (this is a
 *  pure prop-to-HTML function, no I/O), so it cannot know at render time whether THIS submission
 *  failed validation on THIS field. The slot exists purely as a stable, pre-built anchor
 *  {@link injectFormSubmissionResultIntoHtml} fills in and un-hides after the fact, on the
 *  Post/Redirect/Get reload that follows a failed submission (see that function's own doc for the
 *  full mechanism).
 */

/** HTML authoring adapter. Unsanitized, admin/owner trusted markup, like HTML Pages.
 * parse5 supplies real HTML semantics (comments/scripts are never mistaken for inputs).
 * Prototype belongs in @jini-ai/cms/forms later; its published release lacks HTML authoring. */
import { parseFragment, serialize, type DefaultTreeAdapterMap } from "parse5";
import { FormFieldValidationError } from "../errors.js";
import type { FieldDescriptor } from "../types.js";
import { FIELD_TYPE_REGISTRY } from "../field-registry.js";
export { decodeFormFields, encodeFormFields, type FormAuthoring, type HtmlFormDefinitionRecord } from "../fields-json.js";

type Node = DefaultTreeAdapterMap["childNode"];
type Element = DefaultTreeAdapterMap["element"];

function invalid(reason: string): never {
  throw new FormFieldValidationError({ message: reason, fieldErrors: [{ field: "html", reason }] });
}

function elements(nodes: readonly Node[]): Element[] {
  const found: Element[] = [];
  const stack = [...nodes].reverse();
  while (stack.length) {
    const node = stack.pop()!;
    if (!("tagName" in node)) continue;
    found.push(node);
    // Templates are inert and do not contribute successful controls.
    if (node.tagName !== "template") stack.push(...[...node.childNodes].reverse());
  }
  return found;
}

function attr(element: Element, name: string): string | undefined {
  return element.attrs.find((item) => item.name === name)?.value;
}

/** Native `type="url"` refuses scheme-less domains (owner bug 2026-10-13); the registry's text control keeps URL hints. */
function toUrlTextControl(element: Element): void {
  for (const [name, value] of Object.entries({ type: FIELD_TYPE_REGISTRY.url.htmlType, ...FIELD_TYPE_REGISTRY.url.attributes })) {
    removeAttributes(element, [name]);
    element.attrs.push({ name, value });
  }
}

function labelText(node: Element): string {
  const stack: Node[] = [...node.childNodes].reverse();
  let text = "";
  while (stack.length) {
    const child = stack.pop()!;
    if ("value" in child) text += child.value;
    else if ("tagName" in child && !["input", "select", "textarea", "script", "style"].includes(child.tagName)) {
      stack.push(...[...child.childNodes].reverse());
    }
  }
  return text.trim();
}

/** Read only the nearest fieldset's direct legend; blank/missing text keeps control-label fallback.
 * No I/O or mutation; O(d + c + t) time for ancestor depth, fieldset children and legend text,
 * with labelText's O(t) traversal space. */
function groupLabel({ element }: { element: Element }): string | undefined {
  for (let parent = element.parentNode; parent && "tagName" in parent; parent = parent.parentNode) {
    if (parent.tagName !== "fieldset") continue;
    const legend = parent.childNodes.find((child): child is Element => "tagName" in child && child.tagName === "legend");
    return legend ? labelText(legend) || undefined : undefined;
  }
  return undefined;
}

/** Keep the author's required-attribute spelling while retaining parser normalization that
 * discards dangling outer form closers. Both attribute ranges come from parse5, not a regex
 * that could mistake a script string for a control. No attribute value is synthesized here. */
function serializeAuthoredRequired({ fragment, html }: { fragment: DefaultTreeAdapterMap["documentFragment"]; html: string }): string {
  const required = elements(fragment.childNodes).filter((element) => attr(element, "required") !== undefined)
    .map((element) => element.sourceCodeLocation?.attrs?.required)
    .map((location) => location ? html.slice(location.startOffset, location.endOffset) : undefined);
  let output = serialize(fragment);
  const generated = elements(parseFragment(output, { sourceCodeLocationInfo: true }).childNodes)
    .filter((element) => attr(element, "required") !== undefined);
  for (let index = generated.length - 1; index >= 0; index--) {
    // The reverse loop indexes only elements in the generated array.
    const location = generated[index]!.sourceCodeLocation?.attrs?.required;
    if (location && required[index]) output = output.slice(0, location.startOffset) + required[index] + output.slice(location.endOffset);
  }
  return output;
}

/** Forms saved before 2026-10-13 store native `type="url"` controls, served as-is on the public page.
 * Upgrade them on read so bare domains stop being blocked without an owner re-save; other markup is untouched. */
export function upgradeLegacyUrlControls({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const fragment = parseFragment(html, { sourceCodeLocationInfo: true });
  const legacy = elements(fragment.childNodes).filter((element) => element.tagName === "input" && attr(element, "type")?.toLowerCase() === "url");
  if (legacy.length === 0) return html;
  legacy.forEach(toUrlTextControl);
  return serializeAuthoredRequired({ fragment, html });
}

/** Attributes that would let a submit button or a control bypass the server-owned endpoint. */
const TRANSPORT_OVERRIDES = ["form", "formaction", "formmethod", "formenctype", "formtarget"];
const CONTROL_TAGS = ["input", "textarea", "select", "button"];
const RESERVED_NAMES = ["_hp", "__proto__", "constructor", "prototype"];
const ACTION_INPUT_TYPES = ["submit", "reset", "button", "image"];
/** Existing field types a repeated control of this input type may join. A Map, not an object
 * literal, so an authored type such as "constructor" cannot reach Object.prototype. */
const GROUP_JOINS: ReadonlyMap<string, readonly string[]> = new Map<string, readonly string[]>([["radio", ["radio"]], ["checkbox", ["checkbox", "checkbox-group"]]]);

function removeAttributes(element: Element, names: readonly string[]): void {
  element.attrs = element.attrs.filter((attribute) => !names.includes(attribute.name));
}

function wrappingLabel(element: Element): Element | undefined {
  const parent = element.parentNode;
  return parent && "tagName" in parent && parent.tagName === "label" ? parent : undefined;
}

/** Spread helper: an absent attribute adds no descriptor key, so stored JSON keeps its old shape. */
function ifPresent(value: string | undefined, toFields: (value: string) => Partial<FieldDescriptor>): Partial<FieldDescriptor> {
  return value === undefined ? {} : toFields(value);
}

/** Lift the single optional outer `<form>` wrapper's children into its place; the server owns the real form. */
function unwrapOuterForm(all: readonly Element[]): void {
  const forms = all.filter((element) => element.tagName === "form");
  if (forms.length > 1) invalid("Use a form body or one outer form wrapper");
  const [form] = forms;
  if (!form) return;
  // elements() only returns nodes it found in a childNodes list, so a form always has a parent.
  const parent = form.parentNode!;
  parent.childNodes.splice(parent.childNodes.indexOf(form), 1, ...form.childNodes);
  for (const child of form.childNodes) child.parentNode = parent;
}

/** The submission column a control posts under, or undefined for non-controls, actions and unnamed
 * controls. Refuses reserved names and passwords; strips the name from actions so they never post. */
function columnName({ element, inputType }: { element: Element; inputType: string }): string | undefined {
  if (!CONTROL_TAGS.includes(element.tagName)) return undefined;
  if (element.tagName === "button") {
    removeAttributes(element, ["name"]); // Buttons are actions, not submission columns.
    return undefined;
  }
  const name = attr(element, "name");
  if (!name) return undefined;
  if (RESERVED_NAMES.includes(name)) invalid(`Reserved field name '${name}'`);
  if (element.tagName !== "input") return name;
  if (ACTION_INPUT_TYPES.includes(inputType)) {
    removeAttributes(element, ["name"]);
    return undefined;
  }
  if (inputType === "password") invalid("Password fields are not supported");
  return name;
}

/** Add a repeated radio/checkbox control to its existing field's options; any other repeat is refused. */
function addGroupOption({ element, inputType, existing, name }: { element: Element; inputType: string; existing: FieldDescriptor; name: string }): void {
  // Radio/checkbox controls share a successful-control name by design; collect their allowed
  // values rather than admitting arbitrary strings as the old HTML compatibility view did.
  if (!GROUP_JOINS.get(inputType)?.includes(existing.type)) invalid(`Duplicate field name '${name}'`);
  const value = attr(element, "value") ?? "on";
  if (existing.type === "checkbox") {
    existing.type = "checkbox-group";
    existing.options = [{ value: existing.checkboxValue ?? "on", label: existing.label }];
    // Seed option one before replacing its standalone label with the group's legend.
    existing.label = groupLabel({ element }) ?? existing.label;
    delete existing.checkboxValue;
  }
  const parentLabel = wrappingLabel(element);
  existing.options!.push({ value, label: (parentLabel && labelText(parentLabel)) || value });
  existing.required = existing.required || attr(element, "required") !== undefined;
}

/** Map a control to its registry type; URL-hinted text inputs count as URL fields. */
function controlType({ element, inputType }: { element: Element; inputType: string }): FieldDescriptor["type"] {
  if (element.tagName === "select") return attr(element, "multiple") !== undefined ? "multi-select" : "select";
  if (element.tagName === "textarea") return "textarea";
  if (inputType === "checkbox" && attr(element, "role") === "switch") return "toggle";
  if (inputType === "url" || inputType === "text" && attr(element, "inputmode") === FIELD_TYPE_REGISTRY.url.attributes.inputmode) return "url";
  return inputFieldType(inputType);
}

/** The first registry input kind with this native type; an unregistered radio stays "radio", anything else is text. */
function inputFieldType(inputType: string): FieldDescriptor["type"] {
  const registered = Object.entries(FIELD_TYPE_REGISTRY).find(([, kind]) => kind.control === "input" && kind.htmlType === inputType)?.[0];
  return (registered as FieldDescriptor["type"] | undefined) ?? (inputType === "radio" ? "radio" : "text");
}

/** The allowlist a select or radio control declares; other controls have none. */
function controlChoices({ element, inputType, label, name }: { element: Element; inputType: string; label: Element | undefined; name: string }): FieldDescriptor["options"] {
  if (element.tagName === "select") {
    return elements(element.childNodes).filter((child) => child.tagName === "option")
      .map((option) => ({ value: attr(option, "value") ?? labelText(option), label: labelText(option) }))
      .filter((option) => option.value !== "");
  }
  if (inputType !== "radio") return undefined;
  const value = attr(element, "value") ?? "on";
  return [{ value, label: label ? labelText(label) || name : value }];
}

/** A radio group's legend wins; then the control's label text, aria-label, and finally its name. */
function fieldLabel({ element, type, label, name }: { element: Element; type: FieldDescriptor["type"]; label: Element | undefined; name: string }): string {
  const legend = type === "radio" ? groupLabel({ element }) : undefined;
  return legend ?? ((label ? labelText(label) : attr(element, "aria-label")) || name);
}

/** Authored constraint attributes, in the key order earlier releases stored them. */
function constraintFields({ element, type }: { element: Element; type: FieldDescriptor["type"] }): Partial<FieldDescriptor> {
  const numeric = type === "number" || type === "range";
  const bound = (value: string): string | number => numeric ? Number(value) : value;
  return {
    ...ifPresent(attr(element, "placeholder"), (placeholder) => ({ placeholder })),
    ...ifPresent(attr(element, "pattern"), (pattern) => ({ pattern })),
    ...ifPresent(attr(element, "min"), (min) => ({ min: bound(min) })),
    ...ifPresent(attr(element, "max"), (max) => ({ max: bound(max) })),
    ...ifPresent(attr(element, "minlength"), (minLength) => ({ minLength: Number(minLength) })),
    ...ifPresent(attr(element, "step"), (step) => ({ step: Number(step) })),
    ...ifPresent(type === "file" ? attr(element, "accept") : undefined, (accept) => ({ accept: accept.split(",").map((item) => item.trim()) })),
  };
}

/** Describe a control's first occurrence. Converts URL controls to text controls in place. */
function describeControl({ element, inputType, name, labels }: { element: Element; inputType: string; name: string; labels: readonly Element[] }): FieldDescriptor {
  // Earlier Jini releases stored only boolean checkboxes and forced the native "on" wire value.
  // Record attribute presence instead: authored strings survive while no-value boxes stay boolean.
  const checkboxValue = inputType === "checkbox" ? attr(element, "value") : undefined;
  const id = attr(element, "id");
  const label = labels.find((item) => id !== undefined && attr(item, "for") === id) ?? wrappingLabel(element);
  const type = controlType({ element, inputType });
  // Keep URL validation on text controls, and remove legacy native scheme validation on save.
  if (type === "url") toUrlTextControl(element);
  const choices = controlChoices({ element, inputType, label, name });
  return {
    id: name,
    label: fieldLabel({ element, type, label, name }),
    type,
    required: attr(element, "required") !== undefined,
    ...(checkboxValue !== undefined && type === "checkbox" ? { checkboxValue } : {}),
    ...ifPresent(attr(element, "maxlength"), (maxLength) => ({ maxLength: Number(maxLength) })),
    ...(choices ? { options: choices } : {}),
    ...constraintFields({ element, type }),
  };
}

/** Derives the submission allowlist at save time and removes server-owned transport overrides.
 * Parsing normalizes HTML syntax; scripts and authored styling remain unsanitized.
 * @complexity O(n * l) for n elements and l labels (label lookup per control); O(n) space. */
export function deriveHtmlForm(
  { html }: { html: string },
  _optional: Record<string, never> = {},
): { mode: "html"; html: string; fields: FieldDescriptor[] } {
  if (typeof html !== "string" || html.length > 200_000) invalid("HTML must be a string of at most 200000 characters");
  const fragment = parseFragment(html, { sourceCodeLocationInfo: true });
  const all = elements(fragment.childNodes);
  unwrapOuterForm(all);
  const labels = all.filter((element) => element.tagName === "label");
  const fields = new Map<string, FieldDescriptor>();
  for (const element of all) {
    // A submit button's overrides or a control's `form` attribute must not bypass our endpoint.
    removeAttributes(element, TRANSPORT_OVERRIDES);
    const inputType = (attr(element, "type") ?? "text").toLowerCase();
    const name = columnName({ element, inputType });
    if (name === undefined) continue;
    const existing = fields.get(name);
    if (existing) addGroupOption({ element, inputType, existing, name });
    else fields.set(name, describeControl({ element, inputType, name, labels }));
  }
  // Re-serialization also discards ignored/dangling </form> tokens: they must never close our
  // server-owned wrapper early. Raw-text script contents are preserved by the HTML serializer.
  return { mode: "html", html: serializeAuthoredRequired({ fragment, html }), fields: [...fields.values()] };
}

/**
 * @file `registerFormNotifySubscriber` — the Forms-owned outbox subscriber (SPEC-010 REQ-12,
 * ADR-PIPE-010 C-009).
 *
 * Purpose:
 * Subscribes `form.submission.received`; on a notify-enabled definition, calls `MailerPort.send()`
 * per configured recipient. The one piece of Forms-owned business logic riding the outbox — kept
 * separate from the webhook-fanout forwarding (which is not Forms-owned logic; see
 * `server/app.ts`'s wiring). A send failure (thrown or `{ ok: false }`) is logged, never thrown
 * back into `EventBusPort.publish()`'s subscriber loop (`core/events/memory-bus.ts`'s `publish`
 * does not catch handler errors itself — a subscriber that fails to catch its own errors would
 * break every OTHER subscriber to the same event, including the webhook fan-out).
 *
 * Takes the `'form.submission.received'` topic name from `types.ts`, never from `./manifest` —
 * see `FORM_SUBMISSION_RECEIVED_EVENT` there for why domain code never reads the manifest back.
 */
import type { Logger } from "@jini-ai/core/primitives";
/** Notification subscriber with host sender, mail and logging ports. Each recipient receives a stable per-submission dedup key; delivery and repository failures never block sibling subscribers. */
import type { DomainEvent, EventBusPort } from "../core/index.js";
import type { MailerPort,  EmailAddress } from "./ports.js";
import type { FormDefinitionRepoPort, FormSubmissionRepoPort } from "./ports.js";
import { FORM_SUBMISSION_RECEIVED_EVENT } from "./types.js";

interface FormSubmissionReceivedPayload {
  workspaceId: string;
  formDefinitionId: string;
  submissionId: string;
}

export interface RegisterFormNotifySubscriberDeps {
  bus: EventBusPort;
  sender: EmailAddress;
  logger: Pick<Logger, 'warn'>;
  mailer: MailerPort;
  formDefinitionRepo: FormDefinitionRepoPort;
  formSubmissionRepo: FormSubmissionRepoPort;
}

export async function registerFormNotifySubscriber(
  deps: RegisterFormNotifySubscriberDeps,
  _optional: Record<string, never> = {},
): Promise<() => Promise<void>> {
  return deps.bus.subscribe<FormSubmissionReceivedPayload>(
    { eventName: FORM_SUBMISSION_RECEIVED_EVENT,
    handler: async (event: DomainEvent<FormSubmissionReceivedPayload>) => {
      try {
        const { workspaceId, formDefinitionId, submissionId } = event.payload;

        const definition = await deps.formDefinitionRepo.findById({ workspaceId, id: formDefinitionId });
        if (!definition || !definition.notify.enabled || definition.notify.recipients.length === 0) {
          return;
        }

        const submission = await deps.formSubmissionRepo.findById({ workspaceId, id: submissionId });
        if (!submission) return;

        for (const recipient of definition.notify.recipients) {
          try {
            const result = await deps.mailer.send({
              message: {
                workspaceId,
                to: { email: recipient },
                from: deps.sender,
                subject: `New submission: ${definition.name}`,
                text: JSON.stringify(submission.data),
              },
              options: {
                // Include the recipient so a shared dedup ledger never suppresses a sibling send.
                idempotencyKey: `forms:notify:${submissionId}:${recipient}`,
                workspaceId,
                sourceContext: { module: "forms", ref: formDefinitionId },
                purpose: "transactional",
                // Background notifications use the host mailer's durable-outbox readiness gate,
                // rather than the interactive send lane, when production delivery requires it.
                lane: "notification",
              }
            });
            if (!result.ok) {
              warn(deps.logger,
                `[forms:notify] mail send failed for submission '${submissionId}' recipient '${recipient}': ${result.errorCode} (${result.message})`
              );
            }
          } catch (err) {
            // A send failure is terminal for this delivery: log, never retry inline or alter
            // the persisted submission, and continue so the other recipients can still receive it.
            warn(deps.logger,
              `[forms:notify] mail send threw for submission '${submissionId}' recipient '${recipient}':`,
              err
            );
          }
        }
      } catch (err) {
        // Repository failures must not escape the bus's subscriber loop and break sibling handlers.
        warn(deps.logger, "[forms:notify] subscriber failed:", err);
      }
    } }
  );
}

/** Failure reporting is isolated too: a logger cannot interrupt sibling event subscribers. */
function warn(logger: Pick<Logger, 'warn'>, message: string, error?: unknown): void {
  try { logger.warn({ message }, error === undefined ? {} : { error }); } catch { /* Host logging failure is terminal. */ }
}

import { deleteMapRecord } from "@jini-ai/core/records";
// The local trash fork was removed; @jini-ai/cms/trash owns the shared adapter/hooks.
import { encodeKeysetCursor } from "../core/keyset-cursor.js";
import type { UUID } from "@jini-ai/core/primitives";
import { FormSlugConflictError } from "./errors.js";
import type { FormDefinitionRepoPort, FormSubmissionRepoPort } from "./ports.js";
import type { FormDefinitionRecord, FormSubmissionPage, FormSubmissionRecord } from "./types.js";

/**
 * @file In-memory adapters for `forms` (rule-of-two half #1, ADR-006).
 *
 * Purpose:
 * Test/dev-default implementations of `FormDefinitionRepoPort`/`FormSubmissionRepoPort`. Emulates
 * the real DB unique index on `(workspaceId, slug)` (behavior.spec.md §6.1) so `create` throws the
 * same `FormSlugConflictError` shape a `repo.sqlite.ts` unique-constraint violation would map to —
 * write-service.ts's error handling is identical against either adapter.
 *
 * `InMemoryFormDefinitionRepo` stores `deletedAt` internally (mirroring `form_definitions.deleted_at`,
 * owner ruling 2026-09-21) but never returns it through `FormDefinitionRepoPort` — those methods are
 * trash-aware and fail-closed, same as `repo.sqlite.ts`'s `isNull(deletedAt)` reads. `findAnyById`/
 * `save`/`hardDelete` are the deliberate, memory-ONLY exception: a trash-blind seam for the hermetic
 * composition's `createRecordStoreTrashAdapter` (`@jini-ai/cms/trash`), which
 * needs to see and flip a hidden row directly. They are not part of `FormDefinitionRepoPort`.
 */

/** Internal storage shape — the one place in this file allowed to know about `deletedAt`. */
interface StoredFormDefinition extends FormDefinitionRecord {
  deletedAt: string | null;
}

function cloneStored(row: StoredFormDefinition): StoredFormDefinition {
  return {
    ...row,
    fields: structuredClone(row.fields),
    notify: { ...row.notify, recipients: [...row.notify.recipients] },
  };
}

/** Strips the internal-only `deletedAt` before a row crosses `FormDefinitionRepoPort`'s boundary. */
function toPublicRecord(row: StoredFormDefinition): FormDefinitionRecord {
  const { deletedAt: _deletedAt, ...record } = cloneStored(row);
  return record;
}

export class InMemoryFormDefinitionRepo implements FormDefinitionRepoPort {
  private readonly rows = new Map<UUID, StoredFormDefinition>();

  /** Trash-aware: never returns a row with `deletedAt` set. */
  async findById(required: { workspaceId: UUID; id: UUID }): Promise<FormDefinitionRecord | null> {
    const row = this.rows.get(required.id);
    if (!row || row.workspaceId !== required.workspaceId || row.deletedAt !== null) return null;
    return toPublicRecord(row);
  }

  /** Trash-aware: never returns a row with `deletedAt` set. */
  async findBySlug(required: { workspaceId: UUID; slug: string }): Promise<FormDefinitionRecord | null> {
    for (const row of this.rows.values()) {
      if (row.workspaceId === required.workspaceId && row.slug === required.slug && row.deletedAt === null) {
        return toPublicRecord(row);
      }
    }
    return null;
  }

  /** Trash-aware: never lists a row with `deletedAt` set. */
  async list(required: { workspaceId: UUID }): Promise<FormDefinitionRecord[]> {
    return [...this.rows.values()]
      .filter((row) => row.workspaceId === required.workspaceId && row.deletedAt === null)
      .map(toPublicRecord);
  }

  async create(record: FormDefinitionRecord): Promise<void> {
    const conflicting = [...this.rows.values()].find(
      (row) => row.workspaceId === record.workspaceId && row.slug === record.slug
    );
    if (conflicting) {
      // Trash-blind, deliberately — see `ports.ts`'s doc on `create` for why a trashed row still
      // conflicts, and `repo.sqlite.ts`'s identical message for why the two adapters must agree.
      const message =
        conflicting.deletedAt !== null
          ? `a form with slug '${record.slug}' is in the Trash — restore it, or delete it permanently from the Trash, to reuse the slug`
          : `a form with slug '${record.slug}' already exists`;
      throw new FormSlugConflictError({ message, slug: record.slug });
    }
    this.rows.set(record.id, { ...cloneStored({ ...record, deletedAt: null }) });
  }

  /**
   * Update-only path for a LIVE row. A stale in-hand copy of a row that has since been trashed is
   * silently a no-op (mirrors `repo.sqlite.ts`'s `isNull(deletedAt)` WHERE guard) — it can never
   * clear a marker it never knew was set. A record with no existing row at all is still accepted
   * (pre-existing behavior of this in-memory double, unrelated to trashing).
   */
  async update(record: FormDefinitionRecord): Promise<void> {
    const existing = this.rows.get(record.id);
    if (existing && existing.deletedAt !== null) return;
    this.rows.set(record.id, cloneStored({ ...record, deletedAt: existing?.deletedAt ?? null }));
  }

  /** Trash-BLIND — see `ports.ts`'s doc for why this is the one deliberate exception. */
  async isSlugTaken(required: { workspaceId: UUID; slug: string }): Promise<boolean> {
    for (const row of this.rows.values()) {
      if (row.workspaceId === required.workspaceId && row.slug === required.slug) return true;
    }
    return false;
  }

  /**
   * Trash-BLIND — memory-only, NOT part of `FormDefinitionRepoPort`. The hermetic composition's
   * `createRecordStoreTrashAdapter` reads through this to flip `deletedAt` directly, the same way
   * the real adapter reads columns without going through the trash-aware port reads.
   */
  async findAnyById(required: { workspaceId: UUID; id: UUID }): Promise<StoredFormDefinition | null> {
    const row = this.rows.get(required.id);
    if (!row || row.workspaceId !== required.workspaceId) return null;
    return cloneStored(row);
  }

  /** Trash-BLIND write — memory-only, NOT part of `FormDefinitionRepoPort`. See `findAnyById`'s doc. */
  async save(record: StoredFormDefinition): Promise<void> {
    this.rows.set(record.id, cloneStored(record));
  }

  /** Memory-only, NOT part of `FormDefinitionRepoPort`. Removes only the definition row — the
   *  composition root pairs this with `InMemoryFormSubmissionRepo.deleteAllForDefinition` the same
   *  way `features/trash/adapters/form.ts` deletes submissions before the definition. */
  async hardDelete(required: { workspaceId: UUID; id: UUID }): Promise<void> {
    deleteMapRecord({ records: this.rows, key: required.id, fields: { workspaceId: required.workspaceId } });
  }
}

/** A stored submission: the port's record plus the two Trash columns only the Trash touches. */
export interface StoredFormSubmission extends FormSubmissionRecord {
  deletedAt: string | null;
  version: number;
}

function cloneSubmission(row: StoredFormSubmission): StoredFormSubmission {
  return { ...row, data: structuredClone(row.data) };
}

/** The port's view of a stored row: the Trash columns stay inside this adapter. */
function toSubmissionRecord(row: StoredFormSubmission): FormSubmissionRecord {
  const { deletedAt: _deletedAt, version: _version, ...record } = row;
  return { ...record, data: structuredClone(record.data) };
}

export class InMemoryFormSubmissionRepo implements FormSubmissionRepoPort {
  private readonly rows = new Map<UUID, StoredFormSubmission>();
  private turn: Promise<unknown> = Promise.resolve();

  /** Trash-aware, like `repo.sqlite.ts`: a trashed submission reads as missing. */
  async findById(required: { workspaceId: UUID; id: UUID }): Promise<FormSubmissionRecord | null> {
    const row = this.rows.get(required.id);
    if (!row || row.workspaceId !== required.workspaceId || row.deletedAt !== null) return null;
    return toSubmissionRecord(row);
  }

  async create(record: FormSubmissionRecord): Promise<void> {
    this.rows.set(record.id, { ...record, data: structuredClone(record.data), deletedAt: null, version: 1 });
  }

  /** Rolls this repo's rows back when `work` throws, as the SQL adapter's transaction does. Calls
   *  take turns (as the SQLite kernel's do) so one rollback cannot erase another call's row; a
   *  nested call would wait on itself. Other in-memory stores (the outbox) are not covered.
   *  @complexity O(n) snapshot of the stored rows. */
  transaction<T>(work: () => Promise<T>): Promise<T> {
    const run = this.turn.then(async () => {
      const snapshot = new Map(this.rows);
      try {
        return await work();
      } catch (error) {
        this.rows.clear();
        for (const [id, row] of snapshot) this.rows.set(id, row);
        throw error;
      }
    });
    this.turn = run.catch(() => undefined);
    return run;
  }

  async listByDefinition(required: {
    workspaceId: UUID;
    formDefinitionId: UUID;
    limit: number;
  }, optional: { cursor?: string | null } = {}): Promise<FormSubmissionPage> {
    const all = [...this.rows.values()]
      .filter(
        (row) =>
          row.workspaceId === required.workspaceId &&
          row.formDefinitionId === required.formDefinitionId &&
          row.deletedAt === null
      )
      // Newest-first (behavior.spec.md §2.1): submittedAt desc, id desc tie-break.
      .sort((a, b) => {
        if (a.submittedAt !== b.submittedAt) return b.submittedAt.localeCompare(a.submittedAt);
        return b.id.localeCompare(a.id);
      });

    // Keep the published id cursor (unknown ids restart at the first page). Internally the
    // shared keyset owner identifies a position by its timestamp and id, without another codec.
    const cursorRow = optional.cursor ? all.find((row) => row.id === optional.cursor) : undefined;
    const position = cursorRow ? encodeKeysetCursor({ createdAt: cursorRow.submittedAt, id: cursorRow.id }) : undefined;
    const startIndex = position
      ? all.findIndex((row) => encodeKeysetCursor({ createdAt: row.submittedAt, id: row.id }) === position) + 1
      : 0;
    const page = all.slice(startIndex, startIndex + required.limit);
    const nextCursor =
      startIndex + required.limit < all.length ? page[page.length - 1]?.id ?? null : null;

    return { items: page.map(toSubmissionRecord), nextCursor };
  }

  /** Trash-BLIND — memory-only, NOT part of `FormSubmissionRepoPort`. The hermetic composition's
   *  record-store `TrashAdapter` reads and writes the marker through these three, the way the real
   *  adapter reads columns without going through the trash-aware port reads. */
  async findAnyById(required: { workspaceId: UUID; id: UUID }): Promise<StoredFormSubmission | null> {
    const row = this.rows.get(required.id);
    return row && row.workspaceId === required.workspaceId ? cloneSubmission(row) : null;
  }

  /** Trash-BLIND write — see `findAnyById`. */
  async save(record: StoredFormSubmission): Promise<void> {
    this.rows.set(record.id, cloneSubmission(record));
  }

  /** Trash-BLIND purge — see `findAnyById`. */
  async hardDelete(required: { workspaceId: UUID; id: UUID }): Promise<void> {
    deleteMapRecord({ records: this.rows, key: required.id, fields: { workspaceId: required.workspaceId } });
  }

  /** Memory-only, NOT part of `FormSubmissionRepoPort`. Bulk cascade for a form purge — see
   *  `InMemoryFormDefinitionRepo.hardDelete`'s doc for why the composition root pairs the two. */
  async deleteAllForDefinition(required: { workspaceId: UUID; formDefinitionId: UUID }): Promise<void> {
    for (const [id, row] of this.rows) {
      if (row.workspaceId === required.workspaceId && row.formDefinitionId === required.formDefinitionId) {
        this.rows.delete(id);
      }
    }
  }

  /** Trash-blind memory seam: enumerate a form's submissions before its purge cascade, so the host
   * can forget their Trash index rows too. @complexity O(n) time and space over stored submissions. */
  async listAllForDefinition(required: { workspaceId: UUID; formDefinitionId: UUID }, _optional: Record<string, never> = {}): Promise<StoredFormSubmission[]> {
    return [...this.rows.values()]
      .filter(row => row.workspaceId === required.workspaceId && row.formDefinitionId === required.formDefinitionId)
      .map(cloneSubmission);
  }
}

import { decodeFormFields, encodeFormFields } from "../fields-json.js";
import { upgradeLegacyUrlControls } from "../html/html-authoring.js";
import type { Insertable, Selectable } from "kysely";

import type { FormDefinitionTable, FormSubmissionTable } from "./tables.js";
import type {
  FormDefinitionRecord,
  FormDefinitionStatus,
  FormSubmissionRecord,
  NotifyConfig,
} from "../types.js";

/**
 * @file Row mapping for `form_definitions` / `form_submissions`, shared by every dialect: the columns
 * are the generated `ContentDatabase` types (snake_case, JSON as compact text). Neutral on purpose —
 * no repo, no driver.
 */

export type FormDefinitionRow = Selectable<FormDefinitionTable>;
export type FormSubmissionRow = Selectable<FormSubmissionTable>;

/** One `form_definitions` row as a {@link FormDefinitionRecord}. */
export function toDefinitionRecord(row: FormDefinitionRow, _optional: Record<string, never> = {}): FormDefinitionRecord {
  const authoring = decodeFormFields({ json: row.fields_json });
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    name: row.name,
    slug: row.slug,
    ...authoring,
    // Every stored definition is read here, so legacy HTML-mode URL controls are upgraded once for all readers.
    ...(authoring.mode === "html" ? { html: upgradeLegacyUrlControls({ html: authoring.html ?? "" }) } : {}),
    notify: JSON.parse(row.notify_json) as NotifyConfig,
    status: row.status as FormDefinitionStatus,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    version: row.version,
  };
}

/**
 * The `form_definitions` row an INSERT writes. `version` is included for `create`; `update()` strips
 * it (see {@link updatableDefinitionColumns}) because only the Trash's compare-and-set may move it.
 */
export function toDefinitionRow(record: FormDefinitionRecord, _optional: Record<string, never> = {}): Insertable<FormDefinitionTable> {
  return {
    id: record.id,
    workspace_id: record.workspaceId,
    name: record.name,
    slug: record.slug,
    fields_json: encodeFormFields({ definition: record }),
    notify_json: JSON.stringify(record.notify),
    status: record.status,
    created_at: record.createdAt,
    updated_at: record.updatedAt,
    version: record.version,
  };
}

/** The columns `update()` writes: everything but the key and `version`. */
export function updatableDefinitionColumns(row: ReturnType<typeof toDefinitionRow>, _optional: Record<string, never> = {}) {
  const { id: _id, workspace_id: _workspaceId, version: _version, ...rest } = row;
  return rest;
}

/** One `form_submissions` row as a {@link FormSubmissionRecord}. */
export function toSubmissionRecord(row: FormSubmissionRow, _optional: Record<string, never> = {}): FormSubmissionRecord {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    formDefinitionId: row.form_definition_id,
    data: JSON.parse(row.data_json) as FormSubmissionRecord["data"],
    // cms-forms <0.2.2 required a string (0.2.2 allows null). Since nullable migration 0006, an
    // expired IP has an empty display value until the host adopts the nullable package DTO.
    sourceIp: row.source_ip ?? "",
    submittedAt: row.submitted_at,
  };
}

/** The `form_submissions` row a submit writes (compact JSON data). */
export function toSubmissionRow(record: FormSubmissionRecord, _optional: Record<string, never> = {}): Insertable<FormSubmissionTable> {
  return {
    id: record.id,
    workspace_id: record.workspaceId,
    form_definition_id: record.formDefinitionId,
    data_json: JSON.stringify(record.data),
    source_ip: record.sourceIp,
    submitted_at: record.submittedAt,
  };
}

/**
 * @file `submit-service.ts` — the sole public submission write path (SPEC-010 REQ-05..09/16,
 * ADR-PIPE-010 C-008).
 *
 * Purpose:
 * `submitForm` deliberately bypasses `executeCommand` (no actor/permission fits an anonymous
 * visitor — ADR-PIPE-010 Pattern Evaluation); mirrors `routes/site/analytics-ingest.ts`'s
 * `ingestHit` shape. Order: resolve slug -> honeypot check -> validate -> rate-limit -> persist ->
 * enqueue `form.submission.received` -> return, WITHOUT awaiting outbox drainage.
 *
 * CRITICAL (INV-05/REQ-16/AC-24, tasks.md T023): the package kicks off the bound dispatcher without
 * awaiting it. An inline route drain may await delivery when its subscribers are cheap; that is
 * directly unacceptable here, where a subscriber calls `MailerPort.send()`. Copying that pattern
 * verbatim would silently reintroduce the exact response-blocking bug REQ-16/INV-05 forbid.
 * Do not await the dispatcher at the submission boundary — see T023/T049 for the standing
 * Code Review gate on this exact line.
 *
 * Double submit (2026-10-05): a double-clicked Send posts the same form twice and the rendered form
 * ships no script, so the dedupe is server-side — see `submission-attempts.ts` for the attempt token,
 * its cached/static fallback and why it lives in process memory. Ids are random; the submission row
 * and its event are written in one transaction, so a failed enqueue leaves nothing a retry could
 * mistake for a finished submission.
 */
import type { SubmitFormInput } from "./types.js";
export type { SubmitFormInput } from "./types.js";
import type { Logger } from "@jini-ai/core/primitives";
import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
/** Anonymous submission path: active lookup, honeypot, validation, rate check, persistence + event enqueue in one host transaction, then background dispatch. */
import { buildFormsRateLimitKey } from "./rate-limit-key.js";
import type { RateLimiterPort, FormOutboxPort, OutboxDispatcherPort, SubmissionTransactionPort } from "./ports.js";
import type { Clock, IdGenerator, UUID } from "@jini-ai/core/primitives";
import {
  FormDefinitionNotFoundError,
  FormRateLimitExceededError,
  FormSubmissionValidationError,
  FormSubmissionTooFastError,
} from "./errors.js";
import { HONEYPOT_KEY, isHoneypotTripped, validateSubmissionPayload, type SubmissionValidationResult } from "./forms.js";
import type { FormDefinitionRepoPort, FormSubmissionRepoPort } from "./ports.js";
import type { FormDefinitionViewPort } from "./ports.js";
import { assertSubmissionEmails } from "./submission-email-validation.js";
import { DUPLICATE_ATTEMPT, FORM_ATTEMPT_FIELD, MIN_FORM_SUBMISSION_AGE_MS, type SubmissionAttempts } from "./submission-attempts.js";
import { FORM_SUBMISSION_RECEIVED_EVENT, type FormDefinitionRecord, type FormSubmissionRecord, type FormFileStoragePort, type FormFileReference, type FormFileInput } from "./types.js";

export interface SubmitFormDeps {
  definitionRepo: FormDefinitionRepoPort;
  submissionRepo: FormSubmissionRepoPort;
  outbox: FormOutboxPort;
  dispatcher: OutboxDispatcherPort;
  logger: Pick<Logger, 'warn'>;
  clock: Clock;
  idGen: IdGenerator;
  rateLimiter: RateLimiterPort;
  /** Anonymous uploads go through the host media owner only after validation/rate/dedupe. */
  files?: FormFileStoragePort;
  /** Omitted: the two writes run back to back with no rollback between them. */
  transaction?: SubmissionTransactionPort;
}

export interface SubmitFormRequired {
  deps: SubmitFormDeps;
  input: SubmitFormInput;
}

// Anonymous visitors have no actor/permission for an administrative command gateway; this public
// path instead owns validation, throttling and durable submission/event persistence directly.
/**
 * Binds the host's outbox delivery to Jini's anonymous submission service. The package awaits the
 * object-shaped limiter check and queues delivery without awaiting notifications.
 *
 * A repeat of an attempt accepted within the window (same token, or for a request without one the
 * same IP and body) is answered exactly like the original — `accepted` — with no row, no event and
 * no notification. It still passes the slug, honeypot, validation and rate checks first (and so
 * consumes a rate-limit slot, as any request does): the attempt is claimed only where the package
 * opens its persistence transaction, and a copy that must wait for the first copy waits there,
 * outside any database transaction. The `_attempt` field is removed from the body before
 * validation; it is never stored.
 * Known live-issued tokens are additionally checked after rate admission and before claims or
 * uploads. A retryable timing error leaves no durable effects; unavailable evidence skips timing.
 * @returns Accepted for a valid submission, a duplicate, or a honeypot discard; package errors propagate.
 * @complexity O(f + k) package validation plus O(b log b) attempt hashing; fixed-count persistence
 * effects, background dispatch.
 * @example await submitForm({ deps, input: { workspaceId, slug, body, sourceIp } });
 */
export async function submitForm(required: SubmitFormRequired, optional: SubmitFormOptional = {}): Promise<{ status: "accepted" }> {
  const { deps } = required;
  const { input, attemptToken } = splitAttemptToken({ input: required.input }, optional);
  const definition = await resolveActiveDefinition({ deps, input }, optional);

  // Discard before validation, rate limiting or writes; a bot sees the same accepted response
  // without consuming capacity or creating a submission/event.
  if (isHoneypotTripped({ hp: input.body[HONEYPOT_KEY] })) {
    return { status: "accepted" };
  }

  const validation = assertValidSubmission({ deps, definition, body: input.body });
  assertSubmissionTiming({ deps, input, attemptToken }, optional);
  await assertWithinRateLimit({ deps, input, definition });

  const records = buildSubmissionRecords({ deps, input, definition, data: validation.data });
  const persist = () => persistSubmission({ deps, input, ...records, files: validation.files ?? {} });
  if (optional.attempts) {
    // The attempt is claimed only where persistence begins, after validation and rate limiting.
    // A copy waits outside the database transaction; failed first copies free the claim for retry.
    const outcome = await optional.attempts.once({
      key: optional.attempts.key({ input, attemptToken }),
      nowMs: () => deps.clock.nowMs(),
      submit: persist,
    });
    if (outcome === DUPLICATE_ATTEMPT) return { status: "accepted" };
  } else {
    await persist();
  }

  dispatchInBackground({ deps }, optional);
  return { status: "accepted" };
}

type AcceptedSubmission = Extract<SubmissionValidationResult, { valid: true }>;

/** Known live issuance is a conservative filter, not proof of humanity. Missing timing evidence
 * leaves API/static/cached callers compatible; refusal creates no claim or persistence effects.
 * @throws FormSubmissionTooFastError for a matching server age below one second.
 * @complexity O(1). */
function assertSubmissionTiming(
  { deps, input, attemptToken }: { deps: SubmitFormDeps; input: SubmitFormInput; attemptToken: unknown },
  { attempts }: Pick<SubmitFormOptional, "attempts"> = {},
): void {
  const age = attempts?.ageMs({ workspaceId: input.workspaceId, slug: input.slug, attemptToken, nowMs: deps.clock.nowMs() });
  if (age !== undefined && age < MIN_FORM_SUBMISSION_AGE_MS) throw new FormSubmissionTooFastError({}, {});
}

// Only hosts that opted into attempt dedupe send the token; elsewhere `_attempt` stays in the
// body and is validated like any other key.
function splitAttemptToken(
  { input }: { input: SubmitFormInput },
  { attempts }: Pick<SubmitFormOptional, "attempts"> = {},
): { input: SubmitFormInput; attemptToken: unknown } {
  if (!attempts) return { input, attemptToken: undefined };
  const { [FORM_ATTEMPT_FIELD]: attemptToken, ...body } = input.body;
  return { input: { ...input, body }, attemptToken };
}

async function resolveActiveDefinition(
  { deps, input }: { deps: SubmitFormDeps; input: SubmitFormInput },
  { definitionView, validateEmails }: Pick<SubmitFormOptional, "definitionView" | "validateEmails"> = {},
): Promise<FormDefinitionRecord> {
  // Missing and disabled slugs are deliberately indistinguishable to public callers.
  const stored = await deps.definitionRepo.findBySlug({ workspaceId: input.workspaceId, slug: input.slug });
  const definition = stored && definitionView ? definitionView({ definition: stored, body: input.body }) : stored;
  if (!definition || definition.status !== "active") {
    throw new FormDefinitionNotFoundError({ message: `form '${input.slug}' was not found` });
  }
  if (validateEmails) assertSubmissionEmails({ definition, body: input.body });
  return definition;
}

function assertValidSubmission(
  { deps, definition, body }: { deps: SubmitFormDeps; definition: FormDefinitionRecord; body: Record<string, unknown> },
  _optional: Record<string, never> = {},
): AcceptedSubmission {
  const validation = validateSubmissionPayload({ definition, body }, deps.files ? { files: deps.files } : {});
  if (!validation.valid) {
    throw new FormSubmissionValidationError({ message: "submission failed field validation", fieldErrors: validation.fieldErrors });
  }

  if (validation.files && !deps.transaction) {
    // Without rollback, a failed outbox write would leave a stored row pointing at compensated
    // files. Existing scalar-only hosts retain their legacy optional-transaction contract.
    throw new FormSubmissionValidationError({ message: "file submissions require transactional storage", fieldErrors: Object.keys(validation.files).map((field) => ({ field, reason: "file_storage_unavailable" })) });
  }
  return validation;
}

async function assertWithinRateLimit(
  { deps, input, definition }: { deps: SubmitFormDeps; input: SubmitFormInput; definition: FormDefinitionRecord },
  _optional: Record<string, never> = {},
): Promise<void> {
  // Scope by both IP and form so one client's different forms cannot cross-throttle each other.
  const rateLimitKey = buildFormsRateLimitKey({ sourceIp: input.sourceIp, formDefinitionId: definition.id });
  const rateLimitResult = await deps.rateLimiter.check({ key: rateLimitKey });
  if (!rateLimitResult.allowed) {
    throw new FormRateLimitExceededError({ message: `rate limit exceeded for form '${definition.id}'`, retryAfterSeconds: rateLimitResult.retryAfterSeconds });
  }
}

type SubmissionEvent = Parameters<FormOutboxPort["enqueue"]>[0];

function buildSubmissionRecords(
  { deps, input, definition, data }: { deps: SubmitFormDeps; input: SubmitFormInput; definition: FormDefinitionRecord; data: AcceptedSubmission["data"] },
  _optional: Record<string, never> = {},
): { submission: FormSubmissionRecord; event: SubmissionEvent } {
  const now = kernelNowIso({ clock: deps.clock });
  const submissionId = deps.idGen.newId();
  const submission: FormSubmissionRecord = {
    id: submissionId,
    workspaceId: input.workspaceId,
    formDefinitionId: definition.id,
    data,
    sourceIp: input.sourceIp,
    submittedAt: now,
  };
  const event = {
    id: deps.idGen.newId(),
    name: FORM_SUBMISSION_RECEIVED_EVENT,
    occurredAt: now,
    workspaceId: input.workspaceId,
    aggregateId: submissionId,
    payload: { workspaceId: input.workspaceId, formDefinitionId: definition.id, submissionId },
  };
  return { submission, event };
}

async function persistSubmission(
  { deps, input, submission, event, files }: { deps: SubmitFormDeps; input: SubmitFormInput; submission: FormSubmissionRecord; event: SubmissionEvent; files: Record<string, FormFileInput> },
  _optional: Record<string, never> = {},
): Promise<void> {
  // Only a persisted accepted submission gets this event; honeypot discards emit nothing. Row and
  // event commit together: a failed enqueue must not leave a stored submission nobody is told about.
  const transaction: SubmissionTransactionPort = deps.transaction ?? ((work) => work());
  // Blob backends cannot participate in a SQL transaction. Store within the dedupe claim,
  // then compensate only this attempt's new media assets when any upload/row/event write fails.
  // Byte buffers never reach data_json, notifications or the outbox payload.
  const uploaded: FormFileReference[] = [];
  try {
    for (const [fieldId, file] of Object.entries(files)) {
      const reference = await deps.files!.store({ workspaceId: input.workspaceId, submissionId: submission.id, fieldId, file });
      uploaded.push(reference);
      submission.data[fieldId] = reference;
    }
    await transaction(async () => {
      await deps.submissionRepo.create(submission);
      await deps.outbox.enqueue(event);
    });
  } catch (error) {
    await discardUploads({ deps, input, uploaded });
    throw error;
  }
}

async function discardUploads(
  { deps, input, uploaded }: { deps: SubmitFormDeps; input: SubmitFormInput; uploaded: FormFileReference[] },
  _optional: Record<string, never> = {},
): Promise<void> {
  for (const reference of uploaded) {
    try { await deps.files!.discard({ workspaceId: input.workspaceId, reference }); }
    catch (cleanupError) {
      // Retain the original submission failure; a failed cleanup is visible to operators.
      try { deps.logger.warn({ message: "form upload cleanup failed" }, { error: cleanupError }); } catch { /* Logging cannot replace the original error. */ }
    }
  }
}

function dispatchInBackground({ deps }: { deps: SubmitFormDeps }, { dispatch }: Pick<SubmitFormOptional, "dispatch"> = {}): void {
  // Dispatch failures cannot affect an accepted submission or create an unhandled rejection.
  // Never await delivery here: a subscriber sends mail, so awaiting it would reintroduce the
  // response-blocking bug. Persistence/enqueue are awaited; outbox drainage remains background work.
  void Promise.resolve().then(() => (dispatch ?? deps.dispatcher.dispatch.bind(deps.dispatcher))({})).catch((error: unknown) => {
    try { deps.logger.warn({ message: "form outbox dispatch failed" }, { error }); } catch { /* Logging must not reject background work. */ }
  });
}

/** All extensions are opt-in: omitted options preserve the original package submission behavior. */
export interface SubmitFormOptional {
  definitionView?: FormDefinitionViewPort;
  validateEmails?: boolean;
  dispatch?: OutboxDispatcherPort["dispatch"];
  attempts?: SubmissionAttempts;
}

/**
 * @file `write-service.ts` — the admin-CRUD write chokepoint (SPEC-010 REQ-01..04, ADR-PIPE-010).
 *
 * Purpose:
 * `createFormDefinition`/`updateFormDefinition`/`setFormDefinitionStatus`, each wrapping the
 * existing core/commands `executeCommand` gateway (mirrors `posts/create.ts`'s pattern — the
 * gateway captures the auditable change-set record, authorizes `admin.forms.manage`, and enqueues
 * `change-set.applied` onto the outbox). Never exposes a delete: a form definition is removed
 * permanently only by a Trash purge (owner ruling 2026-09-21, superseding the original INV-08
 * "never deleted" wording) — the repo port itself has no delete method for this file to call.
 *
 * Slug-uniqueness relies on the DB unique index (`db/schema.sqlite.ts`), not an app-level check
 * (behavior.spec.md §6.1) — `repo.memory.ts`/`repo.ts` both map a conflicting insert to
 * `FormSlugConflictError`, which this file lets propagate unchanged out of `mutation.execute()`.
 */
import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
/** Audited definition writes through the CMS command gateway. Host permissions and reserved slugs are explicit policies; notify, idempotency and optional outbox wiring live in the second argument. */
import type { ChangeSetRepoPort } from "../core/index.js";
import type { Clock, IdGenerator, UUID } from "@jini-ai/core/primitives";
import type {
  AuthorizeFn,
  CommandActor,
} from "../core/index.js";
import { FormDefinitionNotFoundError, FormFieldValidationError } from "./errors.js";
import { validateFieldDescriptors } from "./forms.js";
import type { FormAuthoringPort, FormCommandExecutorPort, FormDefinitionRepoPort } from "./ports.js";
import type {
  FieldDescriptor,
  FormDefinitionRecord,
  FormDefinitionStatus,
  NotifyConfig,
} from "./types.js";

import type { FormAuthoring, HtmlFormDefinitionRecord } from "./fields-json.js";

export interface FormWriteServiceDeps {
  /** Host-bound audited command gateway; no runtime CMS implementation is imported. */
  executeCommand: FormCommandExecutorPort;
  repo: FormDefinitionRepoPort;
  clock: Clock;
  idGen: IdGenerator;
  changeSets: ChangeSetRepoPort;
  permission: string;
  reservedSlugs: ReadonlySet<string>;
  authorize: AuthorizeFn;
}

// Export validation bounds so host tool schemas can share them rather than drift from the service.
export const MAX_NOTIFY_RECIPIENTS = 10;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export const SLUG_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MIN_NAME_LENGTH = 1;
export const MAX_NAME_LENGTH = 200;

function defaultNotify(): NotifyConfig {
  return { enabled: false, recipients: [] };
}

function validateNotify(notify: NotifyConfig | undefined): NotifyConfig {
  const resolved = notify ?? defaultNotify();
  if (!Array.isArray(resolved.recipients)) {
    throw new FormFieldValidationError({ message: "notify.recipients must be an array", fieldErrors: [
      { field: "notify.recipients", reason: "must be an array" },
    ] });
  }
  if (typeof resolved.enabled !== "boolean") {
    throw new FormFieldValidationError({ message: "notify.enabled must be a boolean", fieldErrors: [
      { field: "notify.enabled", reason: "must be a boolean" },
    ] });
  }
  if (resolved.recipients.length > MAX_NOTIFY_RECIPIENTS) {
    throw new FormFieldValidationError({ message: `notify.recipients may not exceed ${MAX_NOTIFY_RECIPIENTS} addresses`, fieldErrors: [{ field: "notify.recipients", reason: `at most ${MAX_NOTIFY_RECIPIENTS} recipients are allowed` }] });
  }
  for (const recipient of resolved.recipients) {
    if (!EMAIL_PATTERN.test(recipient)) {
      throw new FormFieldValidationError({ message: `'${recipient}' is not a valid email address`, fieldErrors: [
        { field: "notify.recipients", reason: `'${recipient}' is not a valid email address` },
      ] });
    }
  }
  return resolved;
}

function validateNameAndSlug(name: string, slug: string, reservedSlugs: ReadonlySet<string>): void {
  if (name.length < MIN_NAME_LENGTH || name.length > MAX_NAME_LENGTH) {
    throw new FormFieldValidationError({ message: `name must be ${MIN_NAME_LENGTH}-${MAX_NAME_LENGTH} characters`, fieldErrors: [
      { field: "name", reason: `must be ${MIN_NAME_LENGTH}-${MAX_NAME_LENGTH} characters` },
    ] });
  }
  if (!SLUG_PATTERN.test(slug)) {
    throw new FormFieldValidationError({ message: "slug must match ^[a-z0-9][a-z0-9-]{0,63}$", fieldErrors: [
      { field: "slug", reason: "must match ^[a-z0-9][a-z0-9-]{0,63}$" },
    ] });
  }
  if (reservedSlugs.has(slug)) {
    throw new FormFieldValidationError({ message: `slug '${slug}' is reserved`, fieldErrors: [
      { field: "slug", reason: `'${slug}' is reserved by the host` },
    ] });
  }
}

function assertValidFields(fields: FieldDescriptor[]): void {
  const validation = validateFieldDescriptors({ fields });
  if (!validation.valid) {
    throw new FormFieldValidationError({ message: "one or more field descriptors are invalid", fieldErrors: validation.fieldErrors });
  }
}

export interface CreateFormDefinitionRequired {
  deps: FormWriteServiceDeps;
  input: {
    workspaceId: UUID;
    actor: CommandActor;
    name: string;
    slug: string;
    fields: FieldDescriptor[];
  } & FormAuthoring;
}

/**
 * All definition writes pass through the injected command gateway for authorization, audit
 * capture and optional change-set event enqueue. There is no delete here: permanent removal
 * belongs to a separate trash purge, and the definition repository exposes no delete method.
 * Slug uniqueness is enforced by the repository's unique index, avoiding a racy pre-insert check;
 * repository slug-conflict errors propagate unchanged from the mutation.
 */
export async function createFormDefinition(
  required: CreateFormDefinitionRequired,
  optional: CreateFormDefinitionOptional = {}
): Promise<{ definition: FormDefinitionRecord }> {
  let { deps, input } = required;
  if (optional.authoring) {
    const authored = await optional.authoring.prepare({ deps, input });
    if (authored) {
      deps = { ...deps, repo: optional.authoring.with({ repo: deps.repo, authoring: authored }) };
      input = { ...input, ...(authored.fields ? { fields: authored.fields } : {}) };
    }
  }
  validateNameAndSlug(input.name, input.slug, deps.reservedSlugs);
  assertValidFields(input.fields);
  const notify = validateNotify(optional.notify);

  const definitionId = deps.idGen.newId();

  const { result } = await deps.executeCommand({
    deps: {
      clock: deps.clock,
      idGen: deps.idGen,
      changeSets: deps.changeSets,
      outbox: optional.outbox,
      authorize: deps.authorize,
    },
    command: {
      workspaceId: input.workspaceId,
      actor: input.actor,
      summary: `Create form definition '${input.slug}'`,
      idempotencyKey: optional.idempotencyKey,
      permission: deps.permission,
    },
    mutation: {
      entityType: "form_definition",
      entityId: definitionId,
      operation: "create",
      captureInverse: async () => null,
      execute: async () => {
        const now = kernelNowIso({ clock: deps.clock });
        const definition: FormDefinitionRecord = {
          id: definitionId,
          workspaceId: input.workspaceId,
          name: input.name,
          slug: input.slug,
          fields: input.fields,
          notify,
          status: "active",
          createdAt: now,
          updatedAt: now,
          // Start the optimistic-concurrency version at 1 for the trash compare-and-set lifecycle.
          version: 1,
        };
        await deps.repo.create(definition);
        return { definition };
      },
    },
  });

  return result;
}

export interface UpdateFormDefinitionRequired {
  deps: FormWriteServiceDeps;
  input: {
    workspaceId: UUID;
    actor: CommandActor;
    formId: UUID;

    // Accept a supplied slug for compatibility but ignore it: updates never rename stored slugs.
    patch: {
      name?: string;
      fields?: FieldDescriptor[];
      notify?: NotifyConfig;
      slug?: string;
    } & FormAuthoring;
  };
}

export async function updateFormDefinition(
  required: UpdateFormDefinitionRequired,
  optional: UpdateFormDefinitionOptional = {}
): Promise<{ definition: FormDefinitionRecord }> {
  if (optional.authoring) return updateAuthoredFormDefinition(required, optional);
  const { deps, input } = required;

  const { result } = await deps.executeCommand({
    deps: {
      clock: deps.clock,
      idGen: deps.idGen,
      changeSets: deps.changeSets,
      outbox: optional.outbox,
      authorize: deps.authorize,
    },
    command: {
      workspaceId: input.workspaceId,
      actor: input.actor,
      summary: `Update form definition '${input.formId}'`,
      idempotencyKey: optional.idempotencyKey,
      permission: deps.permission,
    },
    mutation: {
      entityType: "form_definition",
      entityId: input.formId,
      operation: "update",
      captureInverse: async () => null,
      execute: async () => {
        const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.formId });
        if (!existing) {
          throw new FormDefinitionNotFoundError({ message: `form definition '${input.formId}' was not found` });
        }

        const name = input.patch.name !== undefined ? input.patch.name : existing.name;
        if (input.patch.name !== undefined) {
          validateNameAndSlug(name, existing.slug, deps.reservedSlugs);
        }

        let fields = existing.fields;
        if (input.patch.fields !== undefined) {
          assertValidFields(input.patch.fields);
          const existingIds = new Set(existing.fields.map((f) => f.id));
          const newIds = new Set(input.patch.fields.map((f) => f.id));
          const missing = [...existingIds].filter((id) => !newIds.has(id));
          if (missing.length > 0) {
            throw new FormFieldValidationError({ message: `patch omits existing field id(s): ${missing.join(", ")} (behavior.spec.md §1.2)`, fieldErrors: missing.map((id) => ({ field: id, reason: "existing field ids cannot be removed" })) });
          }
          fields = input.patch.fields;
        }

        const notify = input.patch.notify !== undefined ? validateNotify(input.patch.notify) : existing.notify;

        const definition: FormDefinitionRecord = {
          ...existing,
          name,
          fields,
          notify,
          slug: existing.slug,
          updatedAt: kernelNowIso({ clock: deps.clock }),
        };
        await deps.repo.update(definition);
        return { definition };
      },
    },
  });

  return result;
}

export interface SetFormDefinitionStatusRequired {
  deps: FormWriteServiceDeps;
  input: {
    workspaceId: UUID;
    actor: CommandActor;
    formId: UUID;
    status: FormDefinitionStatus;
  };
}

/** Status changes preserve the row; deletion requires the separate trash lifecycle. */
export async function setFormDefinitionStatus(
  required: SetFormDefinitionStatusRequired,
  optional: FormWriteOptional = {}
): Promise<{ definition: FormDefinitionRecord }> {
  const { deps, input } = required;

  const { result } = await deps.executeCommand({
    deps: {
      clock: deps.clock,
      idGen: deps.idGen,
      changeSets: deps.changeSets,
      outbox: optional.outbox,
      authorize: deps.authorize,
    },
    command: {
      workspaceId: input.workspaceId,
      actor: input.actor,
      summary: `Set form definition '${input.formId}' status to '${input.status}'`,
      idempotencyKey: optional.idempotencyKey,
      permission: deps.permission,
    },
    mutation: {
      entityType: "form_definition",
      entityId: input.formId,
      operation: "update",
      captureInverse: async () => null,
      execute: async () => {
        const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.formId });
        if (!existing) {
          throw new FormDefinitionNotFoundError({ message: `form definition '${input.formId}' was not found` });
        }
        const definition: FormDefinitionRecord = {
          ...existing,
          status: input.status,
          updatedAt: kernelNowIso({ clock: deps.clock }),
        };
        await deps.repo.update(definition);
        return { definition };
      },
    },
  });

  return result;
}

export interface FormWriteOptional {
  idempotencyKey?: string;
  outbox?: import("../core/index.js").OutboxPort;
}
export interface CreateFormDefinitionOptional extends FormWriteOptional { notify?: NotifyConfig; authoring?: FormAuthoringPort; }
export interface UpdateFormDefinitionOptional extends FormWriteOptional { authoring?: FormAuthoringPort; }

/** Authoring pre-reads are authorized once; the audited gateway replays that decision.
 * @complexity O(f + h) authoring/validation, with fixed-count repository and command calls. */
async function updateAuthoredFormDefinition(
  { deps, input }: UpdateFormDefinitionRequired,
  optional: UpdateFormDefinitionOptional,
): Promise<{ definition: FormDefinitionRecord }> {
  // Authorize BEFORE the authoring pre-read below, so a denied caller is refused before any
  // lookup and the refusal never discloses whether the form exists (5e9f338f6 put the read
  // first). The gateway then replays this one decision instead of evaluating a second time —
  // ADR-021 §2 "one evaluator". Its only authorize() caller is executeCommand's single gate,
  // pinned to FORMS_PERMISSION by packageDeps; prepareFormAuthoring keeps the real authorize.
  const decision = await deps.authorize({
    principalId: input.actor.id,
    permission: deps.permission,
    workspaceId: input.workspaceId,
    entityType: "form_definition",
    entityId: input.formId,
  });
  const gatewayDeps = { ...deps, authorize: async () => decision };
  const { mode, html, ...builderPatch } = input.patch;
  const { authoring, ...writeOptions } = optional;
  // Denied: skip the pre-read entirely; the gateway throws its own ForbiddenError.
  if (!decision.allowed) {
    return updateFormDefinition({ deps: gatewayDeps, input: { ...input, patch: builderPatch } }, writeOptions);
  }
  const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.formId }) as HtmlFormDefinitionRecord | null;
  const authored = await authoring!.prepare({
    deps, input: { workspaceId: input.workspaceId, actor: input.actor, ...input.patch }, ...(existing ? { existing } : {}),
  });
  const boundDeps = authored ? {
    ...gatewayDeps,
    repo: authoring!.with({ repo: deps.repo, authoring: authored }, { replaceFields: authored.mode === "html" || (existing?.mode === "html" && input.patch.fields !== undefined) }),
  } : gatewayDeps;
  return updateFormDefinition({
    deps: boundDeps, input: { ...input, patch: { ...builderPatch, ...(authored?.fields ? { fields: authored.fields } : {}) } },
  }, writeOptions);
}

import { LISTING_AFTER_MAX, type ListingSource } from './batch.js';
import { isRefusedPage } from './paths.js';

/**
 * Numbered listing pages: the no-JS, crawlable counterpart of a see-more listing. Page 1 is the
 * listing page itself (`/`, `/blog`); page N is `<pagePath>/page/<N>` (`/page/2`, `/blog/page/2`),
 * the same plain-directory shape as a batch URL, so a static export writes `.../page/2/index.html`
 * and every static host serves it. Unlike a batch, a page is a whole document, so its links are
 * real `<a rel="prev|next">` links ({@link renderListingPageNav}) a reader and a crawler can follow.
 */

/** Highest page number a page URL may name; a forged huge page is refused, not scanned toward. */
export const LISTING_PAGE_MAX = 10_000;
/** Source rows {@link readListingPage} reads per round while counting. */
const LISTING_PAGE_CHUNK = 500;

const PAGE_PATH = /^((?:\/[^/]+)*)\/page\/([1-9]\d{0,4})\/?$/;

/** One page of a paged listing: where it sits, how many there are, and its neighbours' URLs. */
export interface ListingPageInfo {
  /** 1-based page number. */
  readonly page: number;
  readonly pageSize: number;
  /** Visible items across every page. */
  readonly total: number;
  /** At least 1: an empty listing is one empty page. */
  readonly totalPages: number;
  /** Visible items before this page. */
  readonly offset: number;
  /** The newer page's URL; absent on page 1. */
  readonly prevHref?: string;
  /** The older page's URL; absent on the last page. */
  readonly nextHref?: string;
}

/** {@link ListingPageInfo} plus the page's own items. */
export interface ListingPage<T> extends ListingPageInfo {
  readonly items: readonly T[];
}

/** A page URL's parts: the listing page's own path (`/` for home) and the page number (≥ 2). */
export interface ListingPageRequest {
  readonly pagePath: string;
  readonly page: number;
}

/** `pagePath` itself for page 1, else `<pagePath>/page/<page>`. @complexity O(n) over `pagePath`. */
export function listingPagePath({ pagePath, page }: ListingPageRequest, _optional: Record<string, never> = {}): string {
  if (page <= 1) return pagePath;
  return `${pagePath.replace(/\/+$/, '')}/page/${page}`;
}

/**
 * The page request a URL path names, or `undefined`: page 1 (its canonical URL is the page itself),
 * a leading zero, a page past {@link LISTING_PAGE_MAX}, a `.`/`..`/`_more` segment, or an
 * `admin`/`api` page are refused, never normalized. @complexity O(n) over `path`.
 */
export function parseListingPagePath({ path }: { path: string }, _optional: Record<string, never> = {}): ListingPageRequest | undefined {
  const match = PAGE_PATH.exec(path);
  if (!match) return undefined;
  const [, rawPage = '', rawNumber = ''] = match;
  const page = Number(rawNumber);
  if (page < 2 || page > LISTING_PAGE_MAX || isRefusedPage({ page: rawPage })) return undefined;
  return { pagePath: rawPage === '' ? '/' : rawPage, page };
}

/**
 * The paging math for page `page` of `total` items, `pageSize` (floored, at least 1) per page, or
 * `undefined` when `page` is not a whole number in `[1, totalPages]` (the caller answers 404).
 * @complexity O(n) over `pagePath`.
 */
export function computeListingPage(
  { total, page, pageSize }: { total: number; page: number; pageSize: number },
  { pagePath = '/' }: { pagePath?: string } = {},
): ListingPageInfo | undefined {
  const size = Math.max(1, Math.floor(pageSize));
  const totalPages = Math.max(1, Math.ceil(total / size));
  if (!Number.isInteger(page) || page < 1 || page > totalPages) return undefined;
  return {
    page,
    pageSize: size,
    total,
    totalPages,
    offset: (page - 1) * size,
    ...(page > 1 ? { prevHref: listingPagePath({ pagePath, page: page - 1 }) } : {}),
    ...(page < totalPages ? { nextHref: listingPagePath({ pagePath, page: page + 1 }) } : {}),
  };
}

/**
 * Page `page` of a listing's visible items, with the visible total, or `undefined` when the page is
 * out of range. A visible total needs every row's visibility, so this reads the source in chunks
 * to the end (at most {@link LISTING_AFTER_MAX} rows, the same ceiling a batch cursor has) and keeps
 * only the requested page's items.
 * @complexity O(rows / chunkSize) source reads, O(rows) `isVisible` calls, O(pageSize) memory.
 */
export async function readListingPage<T>(
  { source, page, pageSize }: { source: ListingSource<T>; page: number; pageSize: number },
  { isVisible = () => true, pagePath = '/', chunkSize = LISTING_PAGE_CHUNK }: { isVisible?: (item: T) => boolean; pagePath?: string; chunkSize?: number } = {},
): Promise<ListingPage<T> | undefined> {
  const size = Math.max(1, Math.floor(pageSize));
  const start = (page - 1) * size;
  const items: T[] = [];
  let total = 0;
  for (let offset = 0; offset < LISTING_AFTER_MAX; offset += chunkSize) {
    const rows = await source({ offset, limit: Math.min(chunkSize, LISTING_AFTER_MAX - offset) });
    total = collectPageRows({ rows, items, total, start, size, isVisible });
    if (rows.length < chunkSize) break;
  }
  const info = computeListingPage({ total, page, pageSize: size }, { pagePath });
  return info === undefined ? undefined : { ...info, items };
}

/** Counts `rows`' visible rows onto `total`, appending those whose visible index falls in
 *  `[start, start + size)` to `items`; returns the new total. @complexity O(rows). */
function collectPageRows<T>(
  { rows, items, total, start, size, isVisible }: { rows: readonly T[]; items: T[]; total: number; start: number; size: number; isVisible: (item: T) => boolean },
  _optional: Record<string, never> = {},
): number {
  let count = total;
  for (const row of rows) {
    if (!isVisible(row)) continue;
    if (count >= start && count < start + size) items.push(row);
    count += 1;
  }
  return count;
}

function escapeHtml(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * The default paging nav for a listing page: a plain `<nav aria-label>` with `rel="prev"`/`rel="next"`
 * links and a "Page N of M" status, unstyled so it inherits the theme's own link/nav styles; `''`
 * when there is only one page. @complexity O(n) over the hrefs and labels.
 */
export function renderListingPageNav(
  { page }: { page: ListingPageInfo },
  { label = 'Pagination', newerLabel = 'Newer posts', olderLabel = 'Older posts' }: { label?: string; newerLabel?: string; olderLabel?: string } = {},
): string {
  if (page.totalPages <= 1) return '';
  const parts = [
    page.prevHref === undefined ? '' : `<a class="jini-pagination-prev" rel="prev" href="${escapeHtml(page.prevHref)}">${escapeHtml(newerLabel)}</a>`,
    `<span class="jini-pagination-status">Page ${page.page} of ${page.totalPages}</span>`,
    page.nextHref === undefined ? '' : `<a class="jini-pagination-next" rel="next" href="${escapeHtml(page.nextHref)}">${escapeHtml(olderLabel)}</a>`,
  ].filter(Boolean);
  return `<nav class="jini-pagination" aria-label="${escapeHtml(label)}">${parts.join(' ')}</nav>`;
}

const PAGINATION_NAV = /<nav class="jini-pagination"[^<>]*>([\s\S]*?)<\/nav>/g;
const PAGE_LINK = /<a\b[^<>]*\brel="(?:prev|next)"[^<>]*\bhref="([^"]*)"/g;

/** Every prev/next href inside {@link renderListingPageNav} navs in `html`, for a static exporter to
 *  follow so every page is written. @complexity O(n). */
export function extractListingPageHrefs({ html }: { html: string }, _optional: Record<string, never> = {}): readonly string[] {
  const hrefs: string[] = [];
  for (const [, inner = ''] of html.matchAll(PAGINATION_NAV)) {
    for (const [, href = ''] of inner.matchAll(PAGE_LINK)) hrefs.push(href.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&'));
  }
  return hrefs;
}

import { LISTING_AFTER_MAX } from './batch.js';

/**
 * Batch URLs: `<pagePath>/_more/<key>/<after>` (home: `/_more/1/12`). `_` is not a legal slug, so a
 * batch URL can never collide with content, and it is a plain directory route, so a static export
 * writes `.../<after>/index.html` that every static host serves unchanged. The JSON form of the same
 * batch is `<pagePath>/_more/<key>/<after>.json`, exported as that file.
 */

/** Most see-more listings one page may carry; keys are their 1-based document-order ordinals. */
export const LISTING_KEY_MAX = 10;

const BATCH_PATH = /^((?:\/[^/]+)*)\/_more\/([1-9]\d?)\/(\d{1,6})(?:(\.json)|\/?)$/;
const RESERVED_FIRST_SEGMENTS: ReadonlySet<string> = new Set(['admin', 'api']);
const REFUSED_SEGMENTS: ReadonlySet<string> = new Set(['.', '..', '_more']);

export interface ListingBatchRequest {
  /** The listing page's own path (`/` for home). */
  readonly pagePath: string;
  readonly key: number;
  readonly after: number;
  /** `'json'` for the `.json` form ({@link ListingJsonPage}); absent for the HTML batch. */
  readonly format?: 'json';
}

/** A JSON batch's body: one page of a listing's public items plus the cursor for the next, or `null` after the last. */
export interface ListingJsonPage<T> {
  readonly items: readonly T[];
  readonly nextCursor: number | null;
}

/** The batch URL for `key`'s listing on `pagePath`, starting at source cursor `after`. @complexity O(n) over `pagePath`. */
export function listingBatchPath({ pagePath, key, after, format }: ListingBatchRequest, _optional: Record<string, never> = {}): string {
  return `${pagePath.replace(/\/+$/, '')}/_more/${key}/${after}${format === 'json' ? '.json' : ''}`;
}

/**
 * The batch request a URL path names, or `undefined` when it is not a well-formed batch URL: a bad
 * key or cursor, a `.`/`..` segment, or an `admin`/`api` page are refused, never normalized.
 * @complexity O(n) over `path`.
 */
export function parseListingBatchPath({ path }: { path: string }, _optional: Record<string, never> = {}): ListingBatchRequest | undefined {
  const match = BATCH_PATH.exec(path);
  if (!match) return undefined;
  const [, page = '', rawKey = '', rawAfter = '', json] = match;
  const key = Number(rawKey);
  const after = Number(rawAfter);
  if (isRefusedPage({ page }) || isOutOfBounds({ key, after })) return undefined;
  return { pagePath: page === '' ? '/' : page, key, after, ...(json ? { format: 'json' as const } : {}) };
}

/** A page path holding a `.`/`..`/`_more` segment, or starting with an `admin`/`api` segment; shared
 *  by batch and page URLs (`paging.ts`). @complexity O(n) over `page`. */
export function isRefusedPage({ page }: { page: string }, _optional: Record<string, never> = {}): boolean {
  const segments = page.split('/').filter(Boolean);
  return RESERVED_FIRST_SEGMENTS.has(segments[0] ?? '') || segments.some((segment) => REFUSED_SEGMENTS.has(segment));
}

/** A key past {@link LISTING_KEY_MAX} or a cursor past {@link LISTING_AFTER_MAX}. @complexity O(1). */
function isOutOfBounds({ key, after }: { key: number; after: number }, _optional: Record<string, never> = {}): boolean {
  return key > LISTING_KEY_MAX || after > LISTING_AFTER_MAX;
}

/**
 * @file Magic-byte content-type sniffer for media originals.
 *
 * Purpose:
 * `uploadMedia` (`media-service.ts`) validates only a client-supplied `contentType`
 * STRING against an advisory allowlist — it never inspects the actual bytes (see
 * that file's header, point 4: "an attacker-controlled `contentType` header is
 * trusted, which the real ingress policy would never do"). Neither `media` nor
 * `asset_blobs` persists a real content type at all (no column exists). Any route
 * that serves an asset's original bytes back out therefore cannot trust either the
 * upload-time string or any stored column for `Content-Type` — it must derive the
 * type itself, from the bytes it is about to send, every time it serves them. That
 * is a host route's job, not this module's — this module only supplies the sniff.
 *
 * This is an ALLOWLIST sniffer, not a general-purpose one: {@link sniffContentType}
 * recognizes exactly the binary signatures named below and returns
 * `application/octet-stream` for anything else. The one deliberate exception is
 * markup that looks like HTML or SVG — see {@link isHtmlLike}/{@link isSvgLike} —
 * which this module DOES detect and label, specifically so a caller can single out
 * "textual markup that is a same-origin stored-XSS vector if ever served as its own
 * content type" from "an arbitrary unrecognized blob" and act on it explicitly
 * (a serving route can force `Content-Disposition: attachment` for the former). This
 * module does not attempt general-purpose HTML/XML sniffing beyond that.
 *
 * Detection windows: every binary signature check below only ever reads the first
 * 12 bytes; the markup checks decode up to {@link TEXT_SNIFF_WINDOW} leading bytes
 * (the same 512-byte order of magnitude the WHATWG MIME Sniffing Standard uses for
 * its "read the first N bytes" unknown-type algorithms —
 * https://mimesniff.spec.whatwg.org/#reading-the-resource-header — this module
 * borrows only that window-size convention, not the spec's actual algorithm).
 */

/** Recognized outputs. Anything not covered here falls back to the network's
 * default-safe unknown-binary label — see {@link sniffContentType}'s doc. */
export type SniffedContentType =
  | "image/png"
  | "image/jpeg"
  | "image/gif"
  | "image/webp"
  | "image/avif"
  | "video/mp4"
  | "video/webm"
  | "audio/wav"
  | "audio/mpeg"
  | "audio/flac"
  | "audio/mp4"
  | "text/html"
  | "image/svg+xml"
  | "application/octet-stream";

/** Bounded leading window used only for the textual (HTML/SVG) checks — see file header. */
const TEXT_SNIFF_WINDOW = 512;

/** `true` iff `bytes` is long enough and holds `expected` starting at `offset`. Never throws on a
 * short input — a too-short buffer simply fails the length check, matching every other predicate
 * in this file's "no exceptions, just non-matches" contract. */
function bytesEqualAt(bytes: Uint8Array, offset: number, expected: readonly number[]): boolean {
  if (bytes.length < offset + expected.length) return false;
  for (let i = 0; i < expected.length; i++) {
    if (bytes[offset + i] !== expected[i]) return false;
  }
  return true;
}

function asciiEqualAt(bytes: Uint8Array, offset: number, expected: string): boolean {
  return bytesEqualAt(
    bytes,
    offset,
    Array.from(expected, (ch) => ch.charCodeAt(0))
  );
}

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
const JPEG_SIGNATURE = [0xff, 0xd8, 0xff];
/** EBML header — shared by the whole Matroska family (`.mkv`/`.webm`); this sniffer only ever
 * labels it `video/webm` since WebM is the only Matroska-family format in this route's scope. */
const EBML_SIGNATURE = [0x1a, 0x45, 0xdf, 0xa3];

function isPng(bytes: Uint8Array): boolean {
  return bytesEqualAt(bytes, 0, PNG_SIGNATURE);
}

function isJpeg(bytes: Uint8Array): boolean {
  return bytesEqualAt(bytes, 0, JPEG_SIGNATURE);
}

function isGif(bytes: Uint8Array): boolean {
  return asciiEqualAt(bytes, 0, "GIF87a") || asciiEqualAt(bytes, 0, "GIF89a");
}

/** RIFF container with a `WEBP` form type — bytes 4-7 are a chunk size (variable, not checked). */
function isWebp(bytes: Uint8Array): boolean {
  return asciiEqualAt(bytes, 0, "RIFF") && asciiEqualAt(bytes, 8, "WEBP");
}

/** ISO-BMFF: a leading box whose 4-byte type tag at offset 4 is `ftyp`. The box's own size field
 * (offset 0-3) is deliberately not checked here — it varies by file. This says only "some member
 * of the ISO-BMFF family", NOT "MP4": AVIF, HEIC and MP4 all match it, which is why
 * {@link isAvif} must run first and why {@link sniffContentType} treats this as the family's
 * last-resort fallback rather than a positive MP4 identification. */
function isIsoBmffFtyp(bytes: Uint8Array): boolean {
  return asciiEqualAt(bytes, 4, "ftyp");
}

/** ISO-BMFF brands that identify AVIF: a still image (`avif`) or an image sequence (`avis`). */
const AVIF_BRANDS = ["avif", "avis"] as const;

const FTYP_MAJOR_BRAND_OFFSET = 8;
/** Compatible brands follow the major brand (offset 8) and 4-byte minor version (offset 12). */
const FTYP_COMPATIBLE_BRANDS_OFFSET = 16;
/** Bound on the compatible-brand list scan — real `ftyp` boxes carry a handful, never dozens. */
const MAX_SCANNED_COMPATIBLE_BRANDS = 16;

/** The `ftyp` box's declared end offset (big-endian size at bytes 0-3), clamped to the bytes
 * actually present so a truncated or size-inflating file can never push the brand scan past the
 * buffer or into unrelated trailing boxes. Only called after {@link isIsoBmffFtyp}, which already
 * guarantees the four size bytes (and the `ftyp` tag through offset 8) are present. */
function ftypBoxEnd(bytes: Uint8Array): number {
  const declared = ((bytes[0]! << 24) | (bytes[1]! << 16) | (bytes[2]! << 8) | bytes[3]!) >>> 0;
  return Math.min(declared, bytes.length);
}

function hasAvifBrandAt(bytes: Uint8Array, offset: number): boolean {
  return AVIF_BRANDS.some((brand) => asciiEqualAt(bytes, offset, brand));
}

/**
 * AVIF, distinguished from its ISO-BMFF siblings by brand rather than by the shared `ftyp` tag.
 * The major brand alone is not sufficient: a great many real AVIF files declare the generic
 * `mif1` (HEIF image) major brand and name `avif` only in the compatible-brand list, so both are
 * checked. HEIC declares neither and is therefore never matched here — deliberate, since the
 * installed libvips decodes AVIF but not HEIC.
 */
function isAvif(bytes: Uint8Array): boolean {
  if (!isIsoBmffFtyp(bytes)) return false;
  if (hasAvifBrandAt(bytes, FTYP_MAJOR_BRAND_OFFSET)) return true;

  const boxEnd = ftypBoxEnd(bytes);
  for (let index = 0; index < MAX_SCANNED_COMPATIBLE_BRANDS; index++) {
    const offset = FTYP_COMPATIBLE_BRANDS_OFFSET + index * 4;
    if (offset + 4 > boxEnd) return false;
    if (hasAvifBrandAt(bytes, offset)) return true;
  }
  return false;
}

function isWebm(bytes: Uint8Array): boolean {
  return bytesEqualAt(bytes, 0, EBML_SIGNATURE);
}

const UTF8_BOM = [0xef, 0xbb, 0xbf];

/** Decodes up to {@link TEXT_SNIFF_WINDOW} leading bytes as latin1 (byte-for-byte, never throws on
 * invalid UTF-8 the way a strict "utf8" decode could), strips a leading UTF-8 BOM plus any leading
 * ASCII whitespace, and lowercases — mirrors the "skip leading noise before sniffing markup" step
 * browsers perform before matching tag prefixes. */
function leadingText(bytes: Uint8Array): string {
  const window = bytes.subarray(0, Math.min(bytes.length, TEXT_SNIFF_WINDOW));
  const decoded = Buffer.from(window).toString("latin1");
  const withoutBom = bytesEqualAt(window, 0, UTF8_BOM) ? decoded.slice(UTF8_BOM.length) : decoded;
  return withoutBom.replace(/^\s+/, "").toLowerCase();
}

const HTML_PREFIXES = ["<!doctype html", "<html", "<head", "<script", "<body", "<iframe", "<title", "<frameset"];

/** Matches a leading HTML tag prefix directly, or an XHTML document whose `<?xml ...?>` prolog is
 * followed by `<html` within the sniffed window — either shape is `text/html`-equivalent for this
 * module's purpose (a same-origin-render XSS vector), so both collapse to `"text/html"` rather than
 * a separate `application/xhtml+xml` value (a serving route still blocks that literal string too, as
 * defense in depth against a future caller adding it here). */
function isHtmlLike(text: string): boolean {
  if (HTML_PREFIXES.some((prefix) => text.startsWith(prefix))) return true;
  if (text.startsWith("<?xml")) return text.includes("<html");
  return false;
}

/** Matches a leading `<svg` root element, or an XML prolog followed by `<svg` within the sniffed
 * window (`<?xml version="1.0"?><svg ...>`, the common real-world SVG file shape). */
function isSvgLike(text: string): boolean {
  if (text.startsWith("<svg")) return true;
  if (text.startsWith("<?xml")) return text.includes("<svg");
  return false;
}

/** Untagged MPEG audio: sync bits plus non-reserved version, layer, bitrate and sample rate. */
function isUntaggedMpegAudio(bytes: Uint8Array): boolean {
  return bytes.length >= 4 && bytes[0] === 0xff && (bytes[1]! & 0xe0) === 0xe0 &&
    (bytes[1]! & 0x18) !== 0x08 && (bytes[1]! & 0x06) !== 0 &&
    (bytes[2]! & 0xf0) !== 0 && (bytes[2]! & 0xf0) !== 0xf0 && (bytes[2]! & 0x0c) !== 0x0c;
}

/** Binary signatures in precedence order; the first match wins. */
const BINARY_SIGNATURES: ReadonlyArray<readonly [(bytes: Uint8Array) => boolean, SniffedContentType]> = [
  [isPng, "image/png"],
  [isJpeg, "image/jpeg"],
  [isGif, "image/gif"],
  [isWebp, "image/webp"],
  // MUST precede the MP4 check: AVIF is ISO-BMFF too, so the brand-blind `ftyp` test below would
  // otherwise claim every AVIF as video/mp4 (the 2026-09-06 regression).
  [isAvif, "image/avif"],
  // Audio support (owner-approved mediawidget, 2026-10-10/11) shares the original-byte
  // path. Distinguish explicit M4A brands before the existing ISO-BMFF video fallback.
  [(bytes) => isIsoBmffFtyp(bytes) && asciiEqualAt(bytes, 8, "M4A "), "audio/mp4"],
  [isIsoBmffFtyp, "video/mp4"],
  [isWebm, "video/webm"],
  [(bytes) => asciiEqualAt(bytes, 0, "RIFF") && asciiEqualAt(bytes, 8, "WAVE"), "audio/wav"],
  [(bytes) => asciiEqualAt(bytes, 0, "fLaC"), "audio/flac"],
  [(bytes) => asciiEqualAt(bytes, 0, "ID3"), "audio/mpeg"],
  [isUntaggedMpegAudio, "audio/mpeg"],
];

/**
 * Identifies a media type from `bytes`' leading magic bytes. Allowlist-shaped: only the formats
 * named in {@link SniffedContentType} are ever returned as something other than
 * `"application/octet-stream"` — an input this function does not recognize (including a truncated,
 * corrupt, or genuinely unknown-format file) always falls back to the safe default, it never
 * guesses. `text/html`/`image/svg+xml` are the one case this module positively looks for rather
 * than falls back to, precisely so a caller can treat them as hostile rather than merely unknown
 * (see file header).
 *
 * @complexity O(1) — every binary check reads at most 12 bytes; the textual checks decode at most
 * {@link TEXT_SNIFF_WINDOW} bytes, a fixed constant independent of `bytes.length`.
 * @overallScore 100
 */
export function sniffContentType({ bytes }: { bytes: Uint8Array }, _optional: Record<string, never> = {}): SniffedContentType {
  const binary = BINARY_SIGNATURES.find(([matches]) => matches(bytes));
  if (binary) return binary[1];

  const text = leadingText(bytes);
  if (isHtmlLike(text)) return "text/html";
  if (isSvgLike(text)) return "image/svg+xml";

  return "application/octet-stream";
}

import type { MediaRecord } from "./types.js";
import type { MediaRepoPort } from "./ports.js";

/** Bind creation writes to one authenticated caller without shared mutable actor state.
 * Useful when adapting an older upload service that predates asset-level attribution. */
export function mediaRepoWithCreator(required: { mediaRepo: MediaRepoPort; principalId: string },
  _optional: Record<string, never> = {}): MediaRepoPort {
  const { mediaRepo, principalId } = required;
  return {
    findById: input => mediaRepo.findById(input),
    findBySlug: input => mediaRepo.findBySlug(input),
    list: input => mediaRepo.list(input),
    remove: input => mediaRepo.remove(input),
    save: record => mediaRepo.save({ ...record, createdBy: principalId }),
  };
}

/** An update retains creation attribution, privacy kind and the immutable original filename.
 * Kind cannot be downgraded through metadata writes; legacy unknown attribution remains unknown.
 * Omitting an unknown field preserves compatibility with legacy serialized records. */
export function preserveMediaCreator(required: { record: MediaRecord; original: MediaRecord },
  _optional: Record<string, never> = {}): MediaRecord {
  const { createdBy: _ignored, kind: _kind, originalFilename: _filename, ...metadata } = required.record;
  return { ...metadata, ...(required.original.kind !== undefined ? { kind: required.original.kind } : {}),
    ...(required.original.originalFilename !== undefined ? { originalFilename: required.original.originalFilename } : {}), ...(required.original.createdBy !== undefined
    ? { createdBy: required.original.createdBy } : {}) };
}

import { MediaValidationError } from './types.js';

/** Private Library documents have a smaller cap than a host's image/video uploads. */
export const MAX_DOCUMENT_BYTES = 10 * 1024 * 1024;
export const DOCUMENT_CONTENT_TYPES = {
  md: 'text/markdown', txt: 'text/plain', csv: 'text/csv', json: 'application/json',
  doc: 'application/msword', xls: 'application/vnd.ms-excel', rtf: 'application/rtf',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  pages: 'application/vnd.apple.pages', key: 'application/vnd.apple.keynote',
  pdf: 'application/pdf', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
} as const;

/** Streaming archive port: the existing host archive adapter supplies entries; never extract to disk.
 * File entries must include their ZIP compressed size for ratio checks.
 * Adapters must reject encryption and report links/special files rather than following them. */
export interface DocumentArchiveReaderPort {
  entries(required: { archive: Uint8Array }, optional?: Record<string, never>): AsyncIterable<{
    kind: string; entryPath: string; declaredSize?: number | undefined; compressedSize?: number | undefined;
    openReadStream?: (required: Record<string, never>, optional?: Record<string, never>) => AsyncIterable<Uint8Array>;
  }>;
}

function invalid(message: string): never { throw new MediaValidationError({ message }); }

/** Names are display metadata only. Refuse path syntax rather than trying to normalize it. */
export function documentContentType(required: { filename: string }, _optional: Record<string, never> = {}): string {
  const name = required.filename;
  if (!name.trim() || name.length > 255 || /[\\/\u0000-\u001f\u007f]/u.test(name)) invalid('document filename must be a plain filename of at most 255 characters');
  const dot = name.lastIndexOf('.');
  if (dot <= 0) invalid('document filename must include an allowed extension');
  const extension = name.slice(dot + 1).toLowerCase();
  if (!Object.hasOwn(DOCUMENT_CONTENT_TYPES, extension)) invalid(`document type must be ${Object.keys(DOCUMENT_CONTENT_TYPES).map(ext => '.' + ext).join(', ')}`);
  return DOCUMENT_CONTENT_TYPES[extension as keyof typeof DOCUMENT_CONTENT_TYPES];
}

/** Fatal decoding and control checks reject binary content disguised with a text extension. */
export function decodeDocumentUtf8(required: { bytes: Uint8Array }, _optional: Record<string, never> = {}): string {
  let text: string;
  try { text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(required.bytes); }
  catch { return invalid('document text must be valid UTF-8'); }
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/u.test(text)) invalid('document text contains binary controls');
  return text;
}

const MAX_DOCUMENT_COMPRESSION_RATIO = 100;

/** OOXML variants share the archive policy; only the main part and XML contract differ. */
const OFFICE_PACKAGES = {
  docx: { part: 'word/document.xml', root: 'document', family: 'wordprocessingml', mainType: 'wordprocessingml.document', label: 'Word' },
  xlsx: { part: 'xl/workbook.xml', root: 'workbook', family: 'spreadsheetml', mainType: 'spreadsheetml.sheet', label: 'Excel' },
  pptx: { part: 'ppt/presentation.xml', root: 'presentation', family: 'presentationml', mainType: 'presentationml.presentation', label: 'PowerPoint' },
} as const;
type OfficeExtension = keyof typeof OFFICE_PACKAGES;
type ArchiveExtension = OfficeExtension | 'pages' | 'key';

type ArchiveEntry = DocumentArchiveReaderPort['entries'] extends (...args: never[]) => AsyncIterable<infer Entry> ? Entry : never;
const MAX_ARCHIVE_ENTRIES = 2048;
const MAX_EXPANDED_BYTES = 40 * 1024 * 1024;
const isArchiveExtension = (extension: string): extension is ArchiveExtension => extension in OFFICE_PACKAGES || extension === 'pages' || extension === 'key';

/** Running state for one archive walk: names seen, captured OOXML members and observed totals. */
interface ArchiveScan {
  readonly label: string;
  readonly extension: ArchiveExtension;
  readonly office: (typeof OFFICE_PACKAGES)[OfficeExtension] | undefined;
  readonly archiveBytes: number;
  readonly names: Set<string>;
  readonly members: Map<string, string>;
  count: number;
  total: number;
  iworkMarker: boolean;
}

const isUnsafeArchivePath = (path: string) => !path || /[\\:\u0000-\u001f\u007f]/u.test(path) || path.startsWith('/') ||
  path.split('/').some(part => !part || part === '.' || part === '..');
const isMacroPayload = (path: string, extension: ArchiveExtension) =>
  /vba|macro|activex|(^|\/)embeddings\//i.test(path) || /\.(exe|dll)$/i.test(path) || (extension === 'docx' && /\.bin$/i.test(path));

/** Path policy applies to directories too; a case-folded duplicate could shadow a checked member. */
function assertArchivePath(scan: ArchiveScan, path: string): void {
  if (isUnsafeArchivePath(path)) invalid(`${scan.label} contains an unsafe archive path`);
  const folded = path.toLowerCase();
  if (scan.names.has(folded)) invalid(`${scan.label} contains duplicate archive paths`);
  scan.names.add(folded);
  if (isMacroPayload(path, scan.extension)) invalid(`${scan.label} contains a macro or embedded payload`);
}

/** Header sizes are checked before any byte is read; observed bytes are checked again while streaming. */
function assertDeclaredSizes(scan: ArchiveScan, entry: ArchiveEntry): asserts entry is ArchiveEntry & { declaredSize: number; compressedSize: number; openReadStream: NonNullable<ArchiveEntry['openReadStream']> } {
  if (entry.kind !== 'file' || !entry.openReadStream) invalid(`${scan.label} contains a link or special entry`);
  if (!Number.isSafeInteger(entry.declaredSize) || entry.declaredSize! < 0 || scan.total + entry.declaredSize! > MAX_EXPANDED_BYTES) invalid(`${scan.label} expanded size exceeds its limit`);
  if (!Number.isSafeInteger(entry.compressedSize) || entry.compressedSize! < 0 || entry.compressedSize! > scan.archiveBytes) invalid(`${scan.label} archive compressed size is invalid`);
}

/** Streams one file entry, enforcing size and ratio limits per chunk; buffers only captured members. */
async function readArchiveFile(scan: ArchiveScan, entry: ArchiveEntry & { declaredSize: number; compressedSize: number; openReadStream: NonNullable<ArchiveEntry['openReadStream']> },
  { capture }: { capture: boolean }): Promise<Uint8Array[]> {
  let size = 0;
  const chunks: Uint8Array[] = [];
  for await (const chunk of entry.openReadStream({})) {
    scan.total += chunk.byteLength; size += chunk.byteLength;
    if (scan.total > MAX_EXPANDED_BYTES || size > entry.declaredSize) invalid(`${scan.label} expanded size exceeds its limit`);
    // 100:1 permits ordinary Office XML but cuts off cheap decompression bombs even below
    // the absolute cap. Check observed bytes before buffering; entry limits resist ZIP padding.
    if (size > entry.compressedSize * MAX_DOCUMENT_COMPRESSION_RATIO ||
      scan.total > scan.archiveBytes * MAX_DOCUMENT_COMPRESSION_RATIO) invalid(`${scan.label} compression ratio exceeds 100:1`);
    if (capture) chunks.push(chunk);
  }
  if (size !== entry.declaredSize) invalid(`${scan.label} archive entry size is incorrect`);
  return chunks;
}

/** Reader failures (corrupt or encrypted ZIPs) are reported by application, never as ZIP jargon. */
function archiveApplication({ office, extension }: ArchiveScan): string {
  if (office) return office.label;
  return extension === 'pages' ? 'Pages' : 'Keynote';
}

async function scanArchiveEntry(scan: ArchiveScan, entry: ArchiveEntry): Promise<void> {
  if (++scan.count > MAX_ARCHIVE_ENTRIES) invalid(`${scan.label} has too many archive entries`);
  const name = entry.entryPath;
  const path = name.endsWith('/') ? name.slice(0, -1) : name;
  assertArchivePath(scan, path);
  if (entry.kind === 'directory') return;
  assertDeclaredSizes(scan, entry);
  const capture = !!scan.office && ['[Content_Types].xml', '_rels/.rels', scan.office.part].includes(path);
  const chunks = await readArchiveFile(scan, entry, { capture });
  if (path === 'Index/Document.iwa' || path === 'Index.zip') scan.iworkMarker = true;
  if (capture) scan.members.set(path, decodeDocumentUtf8({ bytes: Buffer.concat(chunks) }));
}

/** Validate every entry, not just required members: hidden payloads and combined expansion matter.
 * 2048 entries / 40 MiB expanded bound both metadata work and decompression, before any persistence.
 * O(expanded bytes + entries) work/space, bounded independently of compressed upload size. */
async function validateDocumentArchive(required: { bytes: Uint8Array; extension: ArchiveExtension; archiveReader?: DocumentArchiveReaderPort | undefined },
  _optional: Record<string, never> = {}): Promise<void> {
  const label = required.extension.toUpperCase();
  const office = required.extension in OFFICE_PACKAGES ? OFFICE_PACKAGES[required.extension as OfficeExtension] : undefined;
  if (!required.archiveReader) invalid(`${label} validation requires an archive reader`);
  const scan: ArchiveScan = { label, extension: required.extension, office, archiveBytes: required.bytes.byteLength,
    names: new Set(), members: new Map(), count: 0, total: 0, iworkMarker: false };
  try {
    for await (const entry of required.archiveReader.entries({ archive: required.bytes })) await scanArchiveEntry(scan, entry);
  } catch (error) {
    if (error instanceof MediaValidationError) throw error;
    invalid(`This file isn't a valid ${archiveApplication(scan)} file (or it's password-protected).`);
  }
  if (office) await validateOfficePackage({ members: scan.members, extension: required.extension as OfficeExtension });
  else if (!scan.iworkMarker) invalid(`${label} is missing its required iWork package members`);
}

const CONTENT_TYPES_NAMESPACE = 'http://schemas.openxmlformats.org/package/2006/content-types';
const RELATIONSHIPS_NAMESPACE = 'http://schemas.openxmlformats.org/package/2006/relationships';
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- These are OOXML namespace/relationship identifiers, never network request URLs; changing their schemes breaks format validation.
const OFFICE_DOCUMENT_RELATIONSHIPS = ['http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument', 'http://purl.oclc.org/ooxml/officeDocument/relationships/officeDocument'];
type OfficeSpec = (typeof OFFICE_PACKAGES)[OfficeExtension];

/** The content-types Override must name the main part with this format's main content type. */
const hasMainOverride = (typesRoot: Element, spec: OfficeSpec) => [...typesRoot.children].some(node => node.localName === 'Override' && node.namespaceURI === CONTENT_TYPES_NAMESPACE &&
  node.getAttribute('PartName') === '/' + spec.part && node.getAttribute('ContentType') === `application/vnd.openxmlformats-officedocument.${spec.mainType}.main+xml`);
/** The package relationship must point at the internal main part as the office document. */
const hasOfficeDocumentRelationship = (relsRoot: Element, spec: OfficeSpec) => [...relsRoot.children].some(node => node.localName === 'Relationship' && node.namespaceURI === RELATIONSHIPS_NAMESPACE &&
  [spec.part, '/' + spec.part].includes(node.getAttribute('Target') ?? '') && node.getAttribute('TargetMode') !== 'External' &&
  OFFICE_DOCUMENT_RELATIONSHIPS.includes(node.getAttribute('Type') ?? ''));
const isOfficeMainRoot = (root: Element, spec: OfficeSpec) => root.localName === spec.root &&
  [`http://schemas.openxmlformats.org/${spec.family}/2006/main`, `http://purl.oclc.org/ooxml/${spec.family}/main`].includes(root.namespaceURI ?? '');

function assertOfficeXml({ documents: [types, rels, document], spec, label }: { documents: readonly Document[]; spec: OfficeSpec; label: string }): void {
  if ([types!, rels!, document!].some(xml => xml.querySelector('parsererror'))) invalid(`${label} contains invalid package XML`);
  const typesRoot = types!.documentElement;
  const relsRoot = rels!.documentElement;
  // Package markers count only as direct children of the real OPC roots, never nested decoys.
  if (typesRoot.localName !== 'Types' || typesRoot.namespaceURI !== CONTENT_TYPES_NAMESPACE ||
    relsRoot.localName !== 'Relationships' || relsRoot.namespaceURI !== RELATIONSHIPS_NAMESPACE) invalid(`${label} contains invalid package roots`);
  // Inspect decoded MIME values: XLM macro sheets need not have macro-looking part names.
  if ([...typesRoot.children].some(node => /macroEnabled|vbaProject|vbaData|(?:intl)?macrosheet\+xml/i.test(node.getAttribute('ContentType') ?? ''))) invalid(`${label} macros are not allowed`);
  if (!hasMainOverride(typesRoot, spec) || !hasOfficeDocumentRelationship(relsRoot, spec) || !isOfficeMainRoot(document!.documentElement, spec)) invalid(`${label} is missing its required ${spec.label} package members`);
}

/** Use the installed XML parser rather than treating marker strings inside an arbitrary ZIP as
 * an Office package. Parsing detached XML runs no scripts and performs no network requests. */
async function validateOfficePackage(required: { members: ReadonlyMap<string, string>; extension: OfficeExtension },
  _optional: Record<string, never> = {}): Promise<void> {
  const spec = OFFICE_PACKAGES[required.extension];
  const label = required.extension.toUpperCase();
  const sources = ['[Content_Types].xml', '_rels/.rels', spec.part].map(name => required.members.get(name) ?? '');
  if (sources.some(xml => /<!DOCTYPE|<!ENTITY|macroEnabled|vbaProject/i.test(xml))) invalid(`${label} DTDs, entities and macros are not allowed`);
  const { JSDOM } = await import('jsdom');
  const window = new JSDOM('').window;
  try {
    assertOfficeXml({ documents: sources.map(source => new window.DOMParser().parseFromString(source, 'application/xml')), spec, label });
  } finally { window.close(); }
}

const OLE_SIGNATURE = Buffer.from([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]);
/** Byte-signature policies for download-only and PDF formats, keyed by extension. */
const SIGNATURE_CHECKS: Partial<Record<keyof typeof DOCUMENT_CONTENT_TYPES, (required: { bytes: Uint8Array }) => void>> = {
  doc: ({ bytes }) => { if (!Buffer.from(bytes.subarray(0, 8)).equals(OLE_SIGNATURE)) invalid("This file isn't a valid Word file."); },
  xls: ({ bytes }) => { if (!Buffer.from(bytes.subarray(0, 8)).equals(OLE_SIGNATURE)) invalid("This file isn't a valid Excel file."); },
  rtf: ({ bytes }) => { if (Buffer.from(bytes.subarray(0, 5)).toString('latin1') !== '{\\rtf') invalid("This file isn't a valid RTF file."); },
  pdf: ({ bytes }) => {
    // latin1 preserves high bits: ASCII decoding would turn counterfeit bytes into a valid header.
    const header = Buffer.from(bytes.subarray(0, 8)).toString('latin1');
    if (!/^%PDF-(?:1\.[0-7]|2\.0)/u.test(header)) invalid('document bytes do not have a PDF signature');
  },
};

function assertDocumentText({ bytes, contentType }: { bytes: Uint8Array; contentType: string }): void {
  const text = decodeDocumentUtf8({ bytes });
  if (contentType !== DOCUMENT_CONTENT_TYPES.json) return;
  try { JSON.parse(text.replace(/^\uFEFF/u, '')); } catch { invalid('document JSON is invalid'); }
}

/** Extension selects a policy; actual bytes must satisfy it. Client MIME never grants admission.
 * Throws MediaValidationError before persistence; O(bytes) work/space, capped at 10 MiB input
 * and 40 MiB expanded archive data. Legacy OLE/RTF checks identify formats, not malware. */
export async function validateDocumentIngress(required: { filename: string; bytes: Uint8Array },
  optional: { archiveReader?: DocumentArchiveReaderPort | undefined } = {}): Promise<{ contentType: string }> {
  if (!required.bytes.byteLength || required.bytes.byteLength > MAX_DOCUMENT_BYTES) invalid('document must be non-empty and at most 10 MiB');
  const contentType = documentContentType({ filename: required.filename });
  const extension = required.filename.slice(required.filename.lastIndexOf('.') + 1).toLowerCase();
  const signatureCheck = SIGNATURE_CHECKS[extension as keyof typeof DOCUMENT_CONTENT_TYPES];
  if (isArchiveExtension(extension)) await validateDocumentArchive({ bytes: required.bytes, extension, ...optional });
  else if (signatureCheck) signatureCheck({ bytes: required.bytes });
  else assertDocumentText({ bytes: required.bytes, contentType });
  return { contentType };
}

/** Preserve the immutable extension while the editable title supplies the display-name stem. */
export function documentDisplayFilename(required: { title: string; originalFilename?: string | null | undefined },
  _optional: Record<string, never> = {}): string {
  const original = required.originalFilename ?? '';
  return required.title + (original.includes('.') ? original.slice(original.lastIndexOf('.')) : '');
}

/** Binary URL import; the outbound adapter owns per-hop SSRF controls, while this module enforces caller MIME/byte policy and preserves source provenance. */
// URL/byte rules are separate from tool permissions and persistence so a fake HTTP port or a byte
// array can exercise them directly. Composition supplies the guarded client; never construct an
// unguarded one here. It must check/pin DNS peers and recheck every redirect to prevent SSRF/rebinding.
import type { FetchImageRequired, FetchImageOptional, ValidateImageBytesRequired } from "./ports.js";
import { mediaFileExtension } from "../file-extension.js";

// Request/fetched-content refusal is distinct from an upload validator's already-in-hand byte checks.
export class MediaImportValidationError extends Error {
  constructor({ message }: { message: string }) { super(message); }
}

export interface FetchedImage {
  readonly bytes: Uint8Array;
  // Remote Content-Type is attacker-controlled metadata; accepted types come from the byte sniffer.
  readonly contentType: string;

  // Follow the bytes: recording the requested URL once mislabeled CDN redirects with a source that
  // served no bytes. Provenance and default filenames both need the last reported valid hop.
  readonly url: URL;
}

// Early scheme/embedded-credential rejection gives callers actionable errors; it supplements,
// rather than replaces, the outbound guard's independent connect-time controls.
export function parseImportUrl({ raw }: { raw: string }): URL {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new MediaImportValidationError({ message: `'url' must be an absolute URL including the scheme (for example 'https://example.com/image.png') — got '${raw}'.` });
  }
  if (url.protocol !== "https:") {
    throw new MediaImportValidationError({ message: `'url' must use https — got '${url.protocol.replace(":", "")}'. Only https URLs can be imported.` });
  }
  if (url.username || url.password) {
    throw new MediaImportValidationError({ message: "'url' must not embed credentials (user:password@host)." });
  }
  return url;
}

// Bound/sanitize path punctuation, controls, and traversal-like names. This labels an upload, not
// its filesystem location: content-addressed storage must not derive a path from this display name.
export function buildImportFilename({ url, contentType }: { url: URL; contentType: string }, { override }: { override?: string } = {}): string {
  const extension = mediaFileExtension({ contentType });
  const rawName = override ?? decodeLastPathSegment(url);
  const slug = rawName
    .replace(/\.[a-zA-Z0-9]{1,5}$/, "")
    .replace(/[^a-zA-Z0-9\s-]/g, " ")
    .trim()
    .replace(/\s+/g, "-")
    .slice(0, 60)
    .replace(/^-+|-+$/g, "");
  return `${slug || "imported-image"}.${extension}`;
}

// A malformed escape should not fail an otherwise valid import; the name sanitizer handles it.
function decodeLastPathSegment(url: URL): string {
  const segment = url.pathname.split("/").filter(Boolean).pop() ?? "";
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

// Distinguish expired signed URLs (often 403/404) from a broken upstream host, so callers request a
// fresh link instead of repeating a doomed fetch. Keep recovery wording separate from network I/O.
function buildStatusError(url: URL, status: number): MediaImportValidationError {
  const hint =
    status === 403 || status === 404
      ? " Signed or time-limited image URLs expire quickly — ask for a fresh URL rather than retrying this one."
      : "";
  return new MediaImportValidationError({ message: `fetching '${url.href}' returned HTTP ${status}, not an image.${hint}` });
}

// Check clipping BEFORE magic bytes: a truncated image can still sniff as PNG but is a corrupt file,
// not a smaller image. Never create a successful media row from a silently partial payload.
// The sniffer and allowlist decide type; remote headers/local filename extensions cannot authorize
// HTML, PDFs, or unsanitized SVG masquerading as images.
export function validateImageBytes({ source, bytes, bytesTruncated, maxBytes, allowedContentTypes, sniffer }: ValidateImageBytesRequired): string {
  assertMaxBytes(maxBytes);
  // Keep URL error labels for remote imports while letting local root-relative paths label refusals.
  const isRemote = source instanceof URL;
  const label = isRemote ? source.href : source;
  if (bytesTruncated || bytes.byteLength > maxBytes) {
    throw new MediaImportValidationError({ message: isRemote
        ? `the image at '${label}' exceeds the ${maxBytes}-byte import limit. Nothing was saved — a partially downloaded image would be a corrupt file, not a smaller one.`
        : `file '${label}' exceeds the ${maxBytes}-byte import limit. Nothing was saved.` });
  }
  if (bytes.byteLength === 0) {
    throw new MediaImportValidationError({ message: isRemote
      ? `'${label}' returned an empty response body — there is nothing to import.`
      : `file '${label}' is empty — there is nothing to import.` });
  }
  const contentType = sniffer.sniff({ bytes });
  if (!allowedContentTypes.has(contentType)) {
    throw new MediaImportValidationError({ message: `'${label}' is not an importable file: its actual bytes are '${contentType}'. ` +
        `Only ${[...allowedContentTypes].join(", ")} can be imported (${isRemote ? 'the served Content-Type header' : 'the file extension'} is deliberately ignored — the bytes decide).` });
  }
  return contentType;
}

export async function fetchImage(required: FetchImageRequired, { timeoutMs = 20_000 }: FetchImageOptional = {}): Promise<FetchedImage> {
  const url = parseImportUrl({ raw: required.url });
  assertMaxBytes(required.maxBytes);

  const response = await required.outboundGuard.send({
    httpClient: required.httpClient,
    request: {
      method: "GET",
      url: url.href,
      headers: { Accept: [...required.allowedContentTypes].join(", ") },
      timeoutMs,
      maxResponseBytes: required.maxBytes,
    },
  });
  if (response.status < 200 || response.status >= 300) {
    throw buildStatusError(url, response.status);
  }
  // Lossy UTF-8 decoding cannot reconstruct binary media. Fail loudly for clients missing raw bytes
  // rather than store a mangled image and call it success; transport failures retain their own type.
  const bytes = response.bodyBytes;
  if (bytes === undefined) {
    throw new MediaImportValidationError({ message: `the HTTP client returned no raw bytes for '${url.href}' — refusing to reconstruct image data from its lossy text decoding.` });
  }
  // A byte-specific verdict wins over truncation of the lossy text representation.
  // The coarse flag ORs byte and text truncation: honoring it when a precise byte verdict exists
  // once rejected complete images whose unused UTF-8 decode alone exceeded the cap. A legacy client
  // with no precise verdict must still fail safe on the coarse flag.
  const bytesTruncated = response.bodyBytesTruncated ?? response.bodyTruncated === true;
  const contentType = validateImageBytes({ ...required, source: url, bytes, bytesTruncated });
  return { bytes, contentType, url: resolveSourceUrl(url, response.finalUrl) };
}

// An older adapter may omit finalUrl; a malformed report can come from a hand-written port. Keep
// the requested URL as a less precise label instead of rejecting good bytes or blanking provenance.
function resolveSourceUrl(requested: URL, reported: string | undefined): URL {
  if (reported === undefined) return requested;
  try {
    return new URL(reported);
  } catch {
    return requested;
  }
}
function assertMaxBytes(maxBytes: number): void {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 1) throw new MediaImportValidationError({ message: "maxBytes must be a positive safe integer" });
}

import { ToolInputError } from '@jini-ai/core';
import { decodeKeysetCursor, encodeKeysetCursor, type KeysetPosition } from '../core/keyset-cursor.js';
import type { MediaRepoPort } from './ports.js';
import type { MediaRecord } from './types.js';

export interface MediaListTypeStore {
  getMany(required: { workspaceId: string; sha256s: readonly string[] }): Promise<ReadonlyMap<string, string>>;
}
const KINDS = ['media', 'image', 'video', 'audio', 'document', 'other'];

/** Validate tool bounds before storage reads. @throws ToolInputError for invalid filters/paging.
 * @complexity O(query + cursor length). */
function listOptions({ input }: { input: Record<string, unknown> }, _options = {}) {
  const { query = '', kind, limit = 50, cursor } = input;
  const normalizedQuery = normalizeQuery({ query });
  if (kind !== undefined && !KINDS.includes(kind as string)) throw new ToolInputError({ message: `kind must be ${KINDS.join('|')}` });
  if (cursor !== undefined && typeof cursor !== 'string') throw new ToolInputError({ message: 'cursor must be a string' });
  return { query: normalizedQuery, kind: kind as string | undefined, limit: pageLimit({ limit }),
    after: cursor === undefined ? undefined : decodeKeysetCursor({ cursor }) };
}

/** Bound search text before storage reads, independently of pagination filters. */
function normalizeQuery({ query }: { query: unknown }, _options = {}): string {
  if (typeof query !== 'string' || query.length > 1000) throw new ToolInputError({ message: 'query must be a string of at most 1000 characters' });
  return query.toLowerCase();
}

/** Keep runtime paging validation identical to the published schema. */
function pageLimit({ limit }: { limit: unknown }, _options = {}): number {
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 100) throw new ToolInputError({ message: 'limit must be an integer from 1 to 100' });
  return limit;
}

/** Classify using the persisted sniff or the host's existing legacy MIME store, without blob I/O. */
function matchesKind({ row, kind, types }: { row: MediaRecord; kind: string | undefined; types: ReadonlyMap<string, string> }, _options = {}): boolean {
  if (!kind) return true;
  if (kind === 'document') return row.kind === 'document';
  if (row.kind === 'document') return false;
  if (kind === 'media') return true;
  const family = (types.get(row.source.sha256) ?? row.source.contentType ?? '').split('/')[0]!;
  return kind === 'other' ? !['image', 'video', 'audio'].includes(family) : family === kind;
}

/** Ascending total order, including tied timestamps; the cursor does not depend on row existence. */
function comparePosition(a: KeysetPosition, b: KeysetPosition): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id === b.id ? 0 : a.id < b.id ? -1 : 1;
}

/** Shared Media/Library page owner. Library remains private documents only and active only.
 * @returns A bounded page and nextCursor, null when exhausted. Storage failures propagate.
 * @complexity O(n log n) time/O(n) memory for n workspace rows: the existing repository exposes
 * a whole-workspace list. Only the selected page incurs URL/size lookups; no blob bytes are read.
 */
export async function listMediaPage(required: {
  mediaRepo: MediaRepoPort; workspaceId: string; input: Record<string, unknown>; library: boolean;
}, optional: { contentTypes?: MediaListTypeStore | undefined } = {}): Promise<{ media: MediaRecord[]; nextCursor: string | null }> {
  const options = listOptions({ input: required.input });
  const rows = await required.mediaRepo.list({ workspaceId: required.workspaceId });
  const types = optional.contentTypes && options.kind
    ? await optional.contentTypes.getMany({ workspaceId: required.workspaceId, sha256s: [...new Set(rows.map(row => row.source.sha256))] })
    : new Map<string, string>();
  const scope = required.library || options.kind === 'document' ? 'document' : 'media';
  const matching = rows.filter(row => (row.kind ?? 'media') === scope)
    .filter(row => !required.library || row.status === 'active')
    .filter(row => matchesKind({ row, kind: options.kind, types }))
    .filter(row => [row.title, row.alt, row.originalFilename ?? '', row.slug].some(text => text.toLowerCase().includes(options.query)))
    .filter(row => !options.after || comparePosition(row, options.after) > 0)
    .sort(comparePosition);
  const media = matching.slice(0, options.limit);
  return { media, nextCursor: continuation({ matching, media }) };
}

/** Never advertise a continuation for an exhausted or empty result set. */
function continuation({ matching, media }: { matching: MediaRecord[]; media: MediaRecord[] }, _options = {}): string | null {
  const last = media.at(-1);
  return matching.length > media.length && last ? encodeKeysetCursor(last) : null;
}

