export {
  MediaConflictError,
  MediaNotFoundError,
  MediaSourceImmutableError,
  MediaStillReferencedError,
  MediaValidationError,
};

/** Default byte-size cap (this pass's stand-in for the real ingress policy's streaming cap). */
export const DEFAULT_MAX_UPLOAD_BYTES = 10 * 1024 * 1024; // 10 MiB

/**
 * Renders a byte count as a human-readable MB figure for the size-cap rejection below (2026-09-21).
 * Every real caller passes a MiB-scale `maxUploadBytes` (10 MiB default, or a host override such as
 * a host's 50 MiB), so one decimal place is enough precision without ever showing a raw byte count —
 * the whole point of this fix (see `uploadMedia`'s size-cap check, and `agent-tools.ts`'s file header
 * for why the catalog description can no longer state a specific number either). `toFixed(1)`'s
 * trailing `.0` is trimmed so a clean multiple of 1 MB (the common case) reads as `10 MB`, not `10.0
 * MB`.
 *
 * @complexity O(1).
 */
function formatMaxUploadBytesAsMb(bytes: number): string {
  const mb = bytes / (1024 * 1024);
  const rounded = mb.toFixed(1);
  return `${rounded.endsWith(".0") ? rounded.slice(0, -2) : rounded} MB`;
}

/**
 * Advisory MIME allowlist. SVG is sanitized by sanitizeSvg before hashing and storage;
 * hosts serve its original without requesting raster transforms.
 *
 * `image/avif` (owner-directed, 2026-09-06): a fifth still-image type, on the
 * same footing as the four above — `content-type-sniffer.ts` identifies it by
 * ISO-BMFF brand and the installed `sharp`/libvips build decodes it, so it
 * flows through the ordinary transform/rendition pipeline and is re-encoded
 * like any other image. Adding it required a matching sniffer fix, not just
 * this line: AVIF shares MP4's `ftyp` container tag, so before that fix an
 * AVIF was sniffed as `video/mp4` and served as an unplayable video.
 *
 * `video/mp4`/`video/webm` (owner-directed, 2026-08-24): the two formats
 * `content-type-sniffer.ts` already recognizes by magic bytes. Unlike the four
 * image types above, an accepted video is never re-encoded — there is no
 * `TransformFormat` for video (`transform-types.ts`'s union is image-only), so
 * a video asset's public URL bypasses the transform/rendition pipeline
 * entirely and serves the original bytes as-is (host concern; see the host's
 * `routes/site/media-rendition.ts`). This widens the SAME advisory,
 * client-declared-string check item 4 above already discloses as untrusted —
 * no new ingress hardening was added for video.
 *
 * Audio (owner-approved mediawidget, 2026-10-10/11) follows that same original-byte
 * lifecycle. Only formats recognized by the shared sniffer are allowed; no image
 * transform is requested for them.
 */
export const DEFAULT_ALLOWED_MIME_TYPES: ReadonlySet<string> = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "image/avif",
  "image/svg+xml",
  "video/mp4",
  "video/webm",
  "audio/wav",
  "audio/mpeg",
  "audio/flac",
  "audio/mp4",
]);

/**
 * Enforces the "settable-once-from-absent" write-once rule for
 * `source.sha256`: absent -> set exactly once, then immutable.
 *
 * Not currently reachable through any exposed write path — `uploadMedia` only
 * ever calls it with `existing = undefined` (a brand-new row), and
 * `UpdateMediaMetadataInput` has no `sha256` field at all, so
 * `updateMediaMetadata` can't trigger the rejection branch even by accident.
 * Kept as an explicit, directly-testable invariant (see
 * `__tests__/media-service.test.ts`) rather than an implicit one enforced only
 * by "the type doesn't have the field" — and it's the seam any future
 * "replace source" operation would have to go through.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export function resolveWriteOnceSource(
  required: { existing: MediaSource | undefined; requestedSha256: string },
  _optional: Record<string, never> = {}
): MediaSource {
  const { existing, requestedSha256 } = required;
  if (existing && existing.sha256 !== requestedSha256) {
    throw new MediaSourceImmutableError({ message: `source.sha256 is write-once: cannot change '${existing.sha256}' to '${requestedSha256}'` }
    );
  }
  return { sha256: requestedSha256 };
}

function deriveTitleFromFilename(filename: string): string {
  const base = filename.trim().replace(/\.[^./\\]+$/, "");
  return base.trim() || "Untitled";
}

/** Shared slug max-length rule (2026-09-07) — same bound as `post.ts`'s `MAX_SLUG_LENGTH`, reused
 *  rather than inventing a second number. `post.ts` only enforces this on its EXPLICIT/caller-
 *  supplied slug path (`resolveExplicitSlug`, reject-with-error); its own title-derived path is
 *  uncapped. Media applies the same bound to BOTH paths, but differently per path's nature: an
 *  explicit edit ({@link resolveSlugForUpdate}) rejects with an error, exactly like `post.ts`,
 *  because a human typed it and should see why it was refused; a derived slug
 *  ({@link deriveUniqueMediaSlug}) truncates instead of rejecting, because nothing is prompting a
 *  human for a shorter value — silently truncating an internally-derived value is the same
 *  "coerce, don't fail" convention `deriveTitleFromFilename`/`slugifyMediaTitle` already use. */
const MEDIA_MAX_SLUG_LENGTH = 120;

/** Truncates a slug candidate to `maxLength`, stripping a trailing dash the cut can introduce (so a
 *  truncation never leaves a slug ending mid-word with a dangling "-"). A no-op when `candidate` is
 *  already within bounds.
 *
 *  The cut can never leave an empty string, so there is no fallback here: every candidate
 *  {@link deriveUniqueMediaSlug} passes starts with an alphanumeric (`slugifyMediaTitle` trims
 *  leading dashes and an empty slug was already replaced by `"untitled"`), and `maxLength` is
 *  {@link MEDIA_MAX_SLUG_LENGTH} minus a `-N` suffix, which stays positive for any suffix below
 *  10^119 collisions. Keeping the first character therefore always keeps something legible. */
function capSlugCandidate(candidate: string, maxLength: number): string {
  if (candidate.length <= maxLength) return candidate;
  return candidate.slice(0, Math.max(maxLength, 0)).replace(/-+$/, "");
}

/** Turns free text into a slug candidate: lowercase, non-alphanumeric runs collapsed to one dash,
 *  leading/trailing dashes trimmed. Same algorithm as `post.ts`'s private `slugify` (duplicated, not
 *  imported — cross-repo: `post.ts` lives in the host, this file in `@jini-ai/cms`; this codebase's own
 *  precedent for a small hand-copied helper mirrored across a repo boundary is `DEFAULT_ALLOWED_MIME_TYPES`
 *  vs. the host's `FILE_HANDLER_ALLOWED_MIME_TYPES`/`IMPORTABLE_CONTENT_TYPES`). Never throws and never
 *  returns `undefined` — an all-punctuation input collapses to `""`, which every caller here treats
 *  as "derive nothing, fall back to a fixed default" rather than a malformed-input error. */
function slugifyMediaTitle(title: string): string {
  return title
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Derives a unique-per-workspace slug from `title`, suffixing `-2`, `-3`, … on collision — the
 * identical loop shape `post.ts`'s `createPost` uses for its own derived-slug path. Shared by
 * {@link uploadMedia} (derive-on-create) and the backfill a host runs once for pre-existing rows
 * with no slug yet (see the host's `development/scripts/backfill-media-slugs.ts`).
 *
 * `base` falls back to `"untitled"` when `title` slugifies to the empty string (all-punctuation or
 * non-Latin titles that `slugifyMediaTitle` strips to nothing) — `uploadMedia`'s own title is never
 * empty (`deriveTitleFromFilename` guarantees a non-empty string), but the backfill script
 * (`development/scripts/backfill-media-slugs.ts`, host-side) calls this against arbitrary pre-existing
 * titles, so this fallback is load-bearing there, not just a defensive floor. Note this is the SAME
 * fallback base every empty-slugifying title collapses onto, so two such titles in one workspace
 * collide on `"untitled"` and are disambiguated by the ordinary suffix loop below exactly like any
 * other collision — an empty derived slug is never inserted as a bare empty string (which a unique
 * index would treat as one specific value, not "no value," and a SECOND empty string would then
 * violate it outright rather than surfacing a friendly conflict).
 *
 * `base` (after the empty-string fallback) is also capped at {@link MEDIA_MAX_SLUG_LENGTH} via
 * {@link capSlugCandidate} before any suffix is considered — a long machine-generated title must not
 * produce an equally long slug. When a collision forces a suffix, the BASE (never the suffix itself)
 * is re-truncated just enough to keep the whole `base-suffix` candidate within the cap, so every
 * candidate this loop ever checks already obeys the length bound, not just the first one.
 *
 * @complexity O(n) repo round-trips in the worst case, where n is the number of prior collisions on
 * the same base slug — bounded in practice by how many same-titled uploads exist in one workspace.
 */
async function deriveUniqueMediaSlug(mediaRepo: MediaRepoPort, workspaceId: UUID, title: string): Promise<string> {
  const base = capSlugCandidate(slugifyMediaTitle(title) || "untitled", MEDIA_MAX_SLUG_LENGTH);
  let slug = base;
  let suffix = 1;
  while (await mediaRepo.findBySlug({ workspaceId, slug })) {
    suffix += 1;
    const suffixText = `-${suffix}`;
    const truncatedBase = capSlugCandidate(base, MEDIA_MAX_SLUG_LENGTH - suffixText.length);
    slug = `${truncatedBase}${suffixText}`;
  }
  return slug;
}

// ---------------------------------------------------------------------------
// uploadMedia
// ---------------------------------------------------------------------------

export interface UploadMediaInput {
  /** Safe per-item origin; omitted uploads are recorded as upload, legacy rows remain unknown. */
  provenance?: import('./types.js').MediaProvenance | undefined;
  kind?: MediaKind | undefined;
  workspaceId: UUID;
  bytes: Uint8Array;
  filename: string;
  contentType: string;
  alt?: string | undefined;
  caption?: string | undefined;
  credit?: string | undefined;
  /** Acting principal, stamped on each media row and on a newly created asset_blobs row. */
  createdByPrincipal: string;
}

export interface UploadMediaDeps {
  clock: Clock;
  idGen: IdGenerator;
  mediaRepo: MediaRepoPort;
  blobRepo: AssetBlobRepoPort;
  renditionRepo: AssetRenditionRepoPort;
  blobStore: BlobStorePort;
  documentArchiveReader?: DocumentArchiveReaderPort | undefined;
}

export interface UploadMediaRequired {
  deps: UploadMediaDeps;
  input: UploadMediaInput;
}

export interface UploadMediaOptional {
  maxUploadBytes?: number | undefined;
  allowedMimeTypes?: ReadonlySet<string> | undefined;
}

/**
 * Validates, hashes, dedups by `(workspaceId, sha256)`, and writes a new media
 * asset. Ordering : bytes are written (or found already
 * present via dedup) BEFORE the media row is saved — a media row never exists
 * without corresponding bytes.
 *
 * Blob dedup is per-hash, not per-upload: uploading the same bytes twice
 * always creates two `MediaRecord`s (two distinct library entries, matching
 * common CMS behavior) but writes the blob bytes only once. The dedup
 * check-then-act sequence runs inside {@link withSha256Lock} (`blob-gc-lock.ts`)
 * so it can't interleave with a concurrent `blob-gc.ts` delete-pass on the
 * same sha256 (the "Serialization" invariant). If the existing blob row
 * is `tombstoned` (a pending GC candidate), this resurrects it back to
 * `active` in the same locked section instead of writing a duplicate blob —
 * the dedup rule's explicit resurrect case.
 *
 * @complexity O(1) — one hash, one blob lookup, at most one blob write, one
 * media write, one rendition write (the lock itself adds O(1) scheduling
 * overhead, not a scan) — plus {@link deriveUniqueMediaSlug}'s own O(n) in the number of prior
 * same-base-slug collisions (see that function's doc).
 * @overallScore 100
 * See docs/decisions/DR-004-journaled-blob-gc.md.
 */
/** Upload-time text fields are trimmed; omitted ones start empty. */
const uploadText = ({ alt, caption, credit }: UploadMediaRequired["input"]) => ({ alt: alt?.trim() ?? "", caption: caption?.trim() ?? "", credit: credit?.trim() ?? "" });

type UploadKind = "media" | "document";

function resolveUploadKind(input: UploadMediaRequired["input"]): UploadKind {
  const kind = input.kind ?? "media";
  if (kind !== "media" && kind !== "document") throw new MediaValidationError({ message: "invalid media kind" });
  return kind;
}

function assertWithinUploadCap(byteLength: number, maxUploadBytes: number): void {
  if (byteLength > maxUploadBytes) {
    throw new MediaValidationError({ message: `uploaded file exceeds the ${formatMaxUploadBytesAsMb(maxUploadBytes)} size cap` });
  }
}

/** Applies the MIME, empty-file and size policy for this kind; returns the cap that applied. */
function assertUploadAdmissible({ input, kind }: { input: UploadMediaRequired["input"]; kind: UploadKind }, optional: UploadMediaOptional): number {
  const maxUploadBytes = kind === "document" ? MAX_DOCUMENT_BYTES : optional.maxUploadBytes ?? DEFAULT_MAX_UPLOAD_BYTES;
  const allowedMimeTypes = optional.allowedMimeTypes ?? DEFAULT_ALLOWED_MIME_TYPES;
  if (kind === "media" && !allowedMimeTypes.has(input.contentType)) {
    throw new MediaValidationError({ message: `content type '${input.contentType}' is not allowed for upload` });
  }
  if (input.bytes.byteLength === 0) {
    throw new MediaValidationError({ message: "uploaded file is empty" });
  }
  assertWithinUploadCap(input.bytes.byteLength, maxUploadBytes);
  return maxUploadBytes;
}

async function storedUploadBytes({ input, kind }: { input: UploadMediaRequired["input"]; kind: UploadKind }): Promise<Uint8Array> {
  // Inspect the bytes too: a mislabeled SVG must never bypass sanitization.
  const isSvg = kind === "media" && (input.contentType === "image/svg+xml" || sniffContentType({ bytes: input.bytes }) === "image/svg+xml");
  return isSvg ? await sanitizeSvg({ bytes: input.bytes }) : input.bytes;
}

/** Dedup check-then-act; must run inside the sha256 lock. Returns the blob's storage key. */
async function claimUploadBlob(
  { deps, input, kind, sha256, bytes, nowIso }: { deps: UploadMediaRequired["deps"]; input: UploadMediaRequired["input"]; kind: UploadKind; sha256: string; bytes: Uint8Array; nowIso: string },
): Promise<string> {
  const documentOwnership = kind === "document" ? { documentOwned: true } : {};
  const existingBlob = await deps.blobRepo.findByHash({ workspaceId: input.workspaceId, sha256 });
  if (existingBlob) {
    if (existingBlob.status === "tombstoned" || (kind === "document" && !existingBlob.documentOwned)) {
      // Record ownership before saving the editorial row: purge must never declassify bytes.
      // Resurrect: cancel the pending GC in the same locked section rather
      // than writing a duplicate blob ( dedup rule). See docs/decisions/DR-004-journaled-blob-gc.md.
      await deps.blobRepo.save({ ...existingBlob, status: "active", tombstonedAt: undefined, ...documentOwnership });
    }
    return existingBlob.storageKey;
  }

  const written = await deps.blobStore.put({
    workspaceId: input.workspaceId,
    sha256,
    bytes,
  });
  await deps.blobRepo.save({
    id: deps.idGen.newId(),
    workspaceId: input.workspaceId,
    sha256,
    storageKey: written.storageKey,
    ...documentOwnership,
    status: "active",
    createdByPrincipal: input.createdByPrincipal,
    createdAt: nowIso,
  });
  return written.storageKey;
}

export async function uploadMedia(
  required: UploadMediaRequired,
  optional: UploadMediaOptional = {}
): Promise<{ media: MediaRecord }> {
  const { deps, input } = required;
  const kind = resolveUploadKind(input);
  const provenance = safeMediaProvenance({ source: input.provenance });
  // Document policy is mandatory even if a host overrides the ordinary media MIME/size policy.
  if (kind === "document") await validateDocumentIngress({ filename: input.filename, bytes: input.bytes }, { archiveReader: deps.documentArchiveReader });
  const maxUploadBytes = assertUploadAdmissible({ input, kind }, optional);

  const bytes = await storedUploadBytes({ input, kind });
  assertWithinUploadCap(bytes.byteLength, maxUploadBytes);
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  const nowIso = kernelNowIso({ clock: deps.clock });

  const storageKey = await withSha256Lock({ key: sha256, criticalSection: () => claimUploadBlob({ deps, input, kind, sha256, bytes, nowIso }) });

  const title = deriveTitleFromFilename(input.filename);
  const slug = await deriveUniqueMediaSlug(deps.mediaRepo, input.workspaceId, title);

  const media: MediaRecord = {
    kind,
    originalFilename: input.filename.replace(/^.*[\\/]/, ''),
    id: deps.idGen.newId(),
    workspaceId: input.workspaceId,
    createdBy: input.createdByPrincipal,
    title,
    slug,
    ...uploadText(input),
    source: { ...resolveWriteOnceSource({ existing: undefined, requestedSha256: sha256 }),
      contentType: kind === 'document' ? documentContentType({ filename: input.filename }) : sniffContentType({ bytes }), provenance },
    status: "active",
    createdAt: nowIso,
    updatedAt: nowIso,
    version: 1,
    // No sizing UI on upload yet (only the edit panel got one — see `UpdateMediaMetadataInput`
    // below) — every freshly uploaded asset starts with no override, set via a follow-up PATCH.
    width: null,
    height: null,
    cssClass: null,
    htmlAttributes: null,
  };
  await deps.mediaRepo.save(media);

  await deps.renditionRepo.save({
    id: deps.idGen.newId(),
    workspaceId: input.workspaceId,
    assetId: media.id,
    transformName: "original",
    version: 1,
    storageKey,
    createdAt: nowIso,
  });

  return { media };
}

// ---------------------------------------------------------------------------
// listMedia / getMediaById
// ---------------------------------------------------------------------------

export interface ListMediaRequired {
  deps: { mediaRepo: MediaRepoPort };
  input: { workspaceId: UUID; kind?: MediaKind | undefined };
}

/**
 * Lists one kind in a workspace (media by default; all statuses — active + trashed; admin sees
 * everything, mirrors an admin post listing). Purged assets are absent by
 * construction (`purgeMedia` removes the row), not filtered here.
 *
 * @complexity O(1) repo call; the returned array is bounded by the
 * workspace's media row count (repo-dependent — no pagination cap added in
 * this pass, acceptable at walking-skeleton scale).
 * @overallScore 100
 */
export async function listMedia(
  required: ListMediaRequired,
  _optional: Record<string, never> = {}
): Promise<{ media: MediaRecord[] }> {
  const media = await required.deps.mediaRepo.list({ workspaceId: required.input.workspaceId });
  return { media: media.filter(row => (row.kind ?? "media") === (required.input.kind ?? "media")) };
}

export interface GetMediaByIdRequired {
  deps: { mediaRepo: MediaRepoPort };
  input: { workspaceId: UUID; id: UUID };
}

/**
 * Fetches one media asset by id, scoped to its workspace.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export async function getMediaById(
  required: GetMediaByIdRequired,
  _optional: Record<string, never> = {}
): Promise<{ media: MediaRecord }> {
  const { workspaceId, id } = required.input;
  const media = await required.deps.mediaRepo.findById({ workspaceId, id });
  if (!media) throw new MediaNotFoundError({ message: `media '${id}' was not found` });
  return { media };
}

export interface FindMediaByIdOrSlugRequired {
  deps: { mediaRepo: MediaRepoPort };
  input: { workspaceId: UUID; idOrSlug: string };
}

/**
 * Resolves a media asset by either its id or its slug — ID FIRST, slug second. The slug is the
 * handle a human typed into an embed marker or a hand-authored `<img>`/`<video>` tag; the id is the
 * opaque UUID every existing reference already uses, and every URL a host's renderer emits.
 *
 * THE ORDER IS A SECURITY PROPERTY, not a preference (2026-09-07). This resolved slug-first, on the
 * documented assumption that "an id never collides with a slug in practice since slugs pass through
 * {@link isValidMediaSlugFormat}". That assumption was false: a lowercase UUID matched the old slug
 * pattern `[a-z0-9-]+` exactly, so setting asset B's slug to asset A's id made every `/m/{A.id}/…`
 * URL — the ones a renderer emitted for A, already live in published pages — resolve to B instead.
 * An id is minted by the system and is never a value a human chooses, so it must always win; the
 * write path additionally refuses UUID-shaped slugs now (see
 * {@link MEDIA_SLUG_UUID_SHAPE_PATTERN}), but ordering is what protects rows written before that
 * rule existed. Id-first costs nothing on the slug path: a real slug simply misses the id lookup and
 * falls through.
 *
 * Never throws (unlike {@link getMediaById}): every call site that needs this (an embed resolver, a
 * public rendition route) already has its own -style non-throwing-miss contract, so this
 * returns `null` on failure and lets the caller apply its own not-found handling rather than forcing
 * one shape on every caller.
 *
 * @complexity O(1) — at most two indexed repo lookups, short-circuited on the first hit.
 * See docs/decisions/DR-004-journaled-blob-gc.md.
 */
export async function findMediaByIdOrSlug(
  required: FindMediaByIdOrSlugRequired,
  _optional: Record<string, never> = {}
): Promise<MediaRecord | null> {
  const { deps, input } = required;
  const byId = await deps.mediaRepo.findById({ workspaceId: input.workspaceId, id: input.idOrSlug });
  if (byId) return byId;
  return deps.mediaRepo.findBySlug({ workspaceId: input.workspaceId, slug: input.idOrSlug });
}

// ---------------------------------------------------------------------------
// updateMediaMetadata
// ---------------------------------------------------------------------------

export interface UpdateMediaMetadataInput {
  workspaceId: UUID;
  id: UUID;
  title?: string | undefined;
  alt?: string | undefined;
  caption?: string | undefined;
  credit?: string | undefined;
  /**
   * Quick-and-dirty sizing override fields (see `MediaRecord.width`/`height`/`cssClass` doc).
   * `undefined` (the key omitted, or explicitly `undefined`) leaves the stored value unchanged —
   * same optional-field/partial-patch contract every other field on this input already has.
   * `null` explicitly CLEARS a previously-set override back to "not set". A provided number must be
   * a positive integer (rejected with `MediaValidationError` otherwise) — this is public HTML output
   * sizing, not a field worth silently coercing.
   */
  width?: number | null | undefined;
  height?: number | null | undefined;
  /** Same undefined/null/value contract as `width`/`height` above. A non-empty string is trimmed;
   *  a string that trims to empty is stored as `null` (equivalent to clearing it), matching the
   *  "empty means unset" convention `title`/`alt`/etc. already follow via `.trim()`. */
  cssClass?: string | null | undefined;
  /**
   * Explicit slug edit (2026-09-07). `undefined` (key omitted) leaves the stored slug unchanged —
   * in particular, changing `title` on the SAME call never touches `slug`; they are independent
   * fields by design (see `MediaRecord.slug`'s doc). Unlike `title`/`cssClass`, `slug` has no
   * "empty means unset" fallback: a media asset's slug is never null once assigned, so a caller
   * cannot clear it back to absent, only replace it with a different valid slug.
   */
  slug?: string | undefined;
  /**
   * Same undefined/null/value contract as `cssClass` above (2026-09-07). A provided non-empty string
   * is validated against `html-attributes.ts`'s allowlist BEFORE it is trimmed and stored — an `on*`
   * handler, a `javascript:` value, or any disallowed name throws `MediaValidationError` naming the
   * exact rejected attribute, and NOTHING is written (this field included) when that happens. A
   * string that validates but trims to empty is stored as `null`, matching `cssClass`'s identical
   * "empty means unset" convention.
   */
  htmlAttributes?: string | null | undefined;
}

export interface UpdateMediaMetadataDeps {
  clock: Clock;
  mediaRepo: MediaRepoPort;
}

export interface UpdateMediaMetadataRequired {
  deps: UpdateMediaMetadataDeps;
  input: UpdateMediaMetadataInput;
}

/**
 * Updates editorial-only fields (title/alt/caption/credit/slug/width/height/cssClass).
 * `source.sha256` is write-once — this function's input type has no `sha256` field,
 * so there is no code path here that can touch it (see `resolveWriteOnceSource`
 * doc for the directly-tested invariant this relies on).
 *
 * `slug` (2026-09-07) is validated and uniqueness-checked by {@link resolveSlugForUpdate} when
 * provided; every other field keeps its pre-existing undefined-means-unchanged contract.
 *
 * @complexity O(1) plus {@link resolveSlugForUpdate}'s own O(1) when `input.slug` is provided.
 * @overallScore 100
 */
/** Validates a `width`/`height` override: must be a positive integer. `null` (explicit clear) and
 *  `undefined` (leave unchanged) both bypass this — only a real provided number is checked. */
function assertPositiveIntegerOrThrow(value: number, field: "width" | "height"): void {
  if (!Number.isInteger(value) || value <= 0) {
    throw new MediaValidationError({ message: `media.${field} must be a positive integer, got ${value}` });
  }
}

/**
 * Validates and normalizes an explicit `slug` edit, then enforces per-workspace uniqueness against
 * every OTHER row — an app-level courtesy check, not the enforcement itself (see `MediaRecord.slug`'s
 * doc): the host's DB unique index is what actually prevents two rows from landing on the same slug
 * under a concurrent write; this check only exists so a normal, non-racing caller sees a clear
 * `MediaConflictError` naming the conflict instead of a raw constraint-violation message surfacing
 * from whatever the host's repo adapter throws. Mirrors `post.ts`'s `assertSlugAvailableForUpdate`
 * (same "claiming your own current slug is not a conflict" rule).
 *
 * @complexity O(1) — one format check, one uniqueness lookup.
 */
async function resolveSlugForUpdate(mediaRepo: MediaRepoPort, workspaceId: UUID, id: UUID, rawSlug: string): Promise<string> {
  const slug = rawSlug.trim().toLowerCase();
  if (!slug || !isValidMediaSlugFormat({ slug: slug })) {
    throw new MediaValidationError({ message: "slug must use lowercase letters, numbers, and dashes, and must not be shaped like a UUID" }
    );
  }
  // Same bound and rejection style as `post.ts`'s `resolveExplicitSlug` — a human typed this value,
  // so it is refused with a clear reason rather than silently truncated (unlike the derived-on-
  // upload path, see `MEDIA_MAX_SLUG_LENGTH`'s doc).
  if (slug.length > MEDIA_MAX_SLUG_LENGTH) {
    throw new MediaValidationError({ message: `slug must be ${MEDIA_MAX_SLUG_LENGTH} characters or fewer` });
  }
  const duplicate = await mediaRepo.findBySlug({ workspaceId, slug });
  if (duplicate && duplicate.id !== id) {
    throw new MediaConflictError({ message: `slug '${slug}' is already used by media '${duplicate.id}'` });
  }
  return slug;
}

/**
 * Validates an explicit `htmlAttributes` edit against `html-attributes.ts`'s allowlist — a stored-
 * XSS boundary, not a syntax convenience (see `MediaRecord.htmlAttributes`'s own doc). Throws
 * `MediaValidationError` naming the exact rejected attribute the moment `parseMediaHtmlAttributes`
 * reports one; the caller (`updateMediaMetadata`) must never reach its own `save()` call when this
 * throws, so an invalid value is never partially or fully persisted. A value that validates but
 * trims to empty stores as `null`, matching `cssClass`'s identical "empty means unset" convention.
 *
 * @complexity O(n) in the input string's length (one `parseMediaHtmlAttributes` pass).
 */
function resolveHtmlAttributesForUpdate(rawValue: string): string | null {
  const trimmed = rawValue.trim();
  if (trimmed === "") return null;
  const parsed = parseMediaHtmlAttributes({ text: trimmed });
  if (parsed.error) {
    throw new MediaValidationError({ message: `media.htmlAttributes: ${describeMediaHtmlAttributeError(parsed.error)}` });
  }
  return trimmed;
}

function assertDocumentTitle(existing: MediaRecord, title: string | undefined): void {
  if (existing.kind !== "document" || title === undefined) return;
  if (!title.trim() || title.trim().length > 240 || /[\\/\u0000-\u001f\u007f]/u.test(title)) {
    throw new MediaValidationError({ message: "document title must be a non-empty display stem of at most 240 characters" });
  }
}

const trimmedEdit = (value: string | undefined, current: string): string => (value !== undefined ? value.trim() : current);
/** `undefined` keeps the stored value; `null` is a real edit that clears it. */
const editedOr = <T>(value: T | undefined, current: T): T => (value !== undefined ? value : current);

function resolveHtmlAttributesEdit(value: string | null | undefined, current: string | null): string | null {
  if (value === undefined) return current;
  return value === null ? null : resolveHtmlAttributesForUpdate(value);
}

function resolveCssClassEdit(value: string | null | undefined, current: string | null): string | null {
  if (value === undefined) return current;
  return value === null ? null : value.trim() || null;
}

/** Builds the edited record from already-validated edits. */
function applyMetadataEdits(
  { existing, input, slug, htmlAttributes, updatedAt }: { existing: MediaRecord; input: UpdateMediaMetadataRequired["input"]; slug: string; htmlAttributes: string | null; updatedAt: string },
): MediaRecord {
  return {
    ...existing,
    // `title` and `slug` are deliberately independent (see `MediaRecord.slug`'s doc): renaming the
    // title never recomputes `slug`, and editing `slug` never touches `title`.
    title: trimmedEdit(input.title, existing.title) || existing.title,
    slug,
    alt: trimmedEdit(input.alt, existing.alt),
    caption: trimmedEdit(input.caption, existing.caption),
    credit: trimmedEdit(input.credit, existing.credit),
    width: editedOr(input.width, existing.width),
    height: editedOr(input.height, existing.height),
    cssClass: resolveCssClassEdit(input.cssClass, existing.cssClass),
    htmlAttributes,
    updatedAt,
    version: existing.version + 1,
  };
}

export async function updateMediaMetadata(
  required: UpdateMediaMetadataRequired,
  _optional: Record<string, never> = {}
): Promise<{ media: MediaRecord }> {
  const { deps, input } = required;
  const existing = await deps.mediaRepo.findById({ workspaceId: input.workspaceId, id: input.id });
  if (!existing) throw new MediaNotFoundError({ message: `media '${input.id}' was not found` });
  assertEntityLive({ entityType: "media", entityId: input.id, state: existing.status === "trashed" ? "trashed" : "live" });
  assertDocumentTitle(existing, input.title);

  if (input.width !== undefined && input.width !== null) assertPositiveIntegerOrThrow(input.width, "width");
  if (input.height !== undefined && input.height !== null) assertPositiveIntegerOrThrow(input.height, "height");
  const slug =
    input.slug !== undefined
      ? await resolveSlugForUpdate(deps.mediaRepo, input.workspaceId, input.id, input.slug)
      : existing.slug;
  // Validated BEFORE the record is built (same "fail before any write" discipline `assertPositive
  // IntegerOrThrow` above already follows) — an invalid value must never reach `save()`.
  const htmlAttributes = resolveHtmlAttributesEdit(input.htmlAttributes, existing.htmlAttributes);

  const media = applyMetadataEdits({ existing, input, slug, htmlAttributes, updatedAt: kernelNowIso({ clock: deps.clock }) });
  await deps.mediaRepo.save(media);
  return { media };
}

// ---------------------------------------------------------------------------
// trashMedia / purgeMedia (deletion ladder)
// ---------------------------------------------------------------------------

export interface TrashMediaDeps {
  clock: Clock;
  mediaRepo: MediaRepoPort;
}

export interface TrashMediaRequired {
  deps: TrashMediaDeps;
  input: { workspaceId: UUID; id: UUID };
}

/**
 * Soft delete. Idempotent — trashing an already-trashed asset is a no-op
 * (mirrors `disableMember`'s idempotency), not an error.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export async function trashMedia(
  required: TrashMediaRequired,
  _optional: Record<string, never> = {}
): Promise<{ media: MediaRecord }> {
  const { deps, input } = required;
  const existing = await deps.mediaRepo.findById(input);
  if (!existing) throw new MediaNotFoundError({ message: `media '${input.id}' was not found` });
  if (existing.status === "trashed") return { media: existing };

  const media: MediaRecord = {
    ...existing,
    status: "trashed" as MediaStatus,
    updatedAt: kernelNowIso({ clock: deps.clock }),
    version: existing.version + 1,
  };
  await deps.mediaRepo.save(media);
  return { media };
}

export interface PurgeMediaDeps {
  referenceCheck: MediaReferenceCheckPort;
  mediaRepo: MediaRepoPort;
  blobRepo: AssetBlobRepoPort;
  renditionRepo: AssetRenditionRepoPort;
  blobStore: BlobStorePort;
  /**
   * Optional — only used to timestamp the blob-GC tombstone-pass this
   * function triggers after the media row is removed (`tombstoneBlobIfUnreferenced`,
   * `blob-gc.ts`). Falls back to the system clock when omitted so a caller
   * that doesn't wire a clock into `PurgeMediaDeps` keeps compiling and
   * behaving correctly unchanged.
   */
  clock?: Clock | undefined;
}

export interface PurgeMediaRequired {
  deps: PurgeMediaDeps;
  input: { workspaceId: UUID; id: UUID };
}

/**
 * Hard delete. Deletion ladder (mirrors `deleteMenu`): purge is
 * rejected with `MediaStillReferencedError` (409-style) unless the asset has
 * already been trashed first.
 *
 * The host must check current content through `referenceCheck`, including slug-based references.
 * The trashed status is a separate prerequisite, never proof that no content references the asset.
 * Lookup errors propagate before any removal. Hosts without a checker fail closed.
 *
 * Once past the guard: rendition rows are removed, then the media row is
 * removed. After that removal commits, the blob-GC tombstone-pass
 * (`tombstoneBlobIfUnreferenced`, `blob-gc.ts`) runs for the asset's sha256 —
 * it marks the blob `tombstoned` if-and-only-if the real "unreferenced"
 * predicate holds (no other non-purged media row shares the hash, plus the
 * disclosed `entry_refs`/retained-snapshot stubs). This function does **not**
 * delete blob bytes itself anymore: the delete-pass (`runBlobGcDeletePass`)
 * is grace-period-gated (`gc_grace`, default 30 days) and the unlink-pass
 * (`runBlobGcUnlinkPass`) that actually removes bytes runs as a separate,
 * explicit step — nothing schedules either automatically yet (see
 * `blob-gc.ts`'s file header). This is a real behavior change from this
 * function's prior "delete row, best-effort unlink immediately" shortcut,
 * which is exactly the gap this task closes.
 *
 * @complexity O(n) in the workspace's media row count, inherited from the
 * tombstone-pass's `isBlobUnreferenced` scan (see `blob-gc.ts`).
 * @overallScore 100
 */
export async function purgeMedia(
  required: PurgeMediaRequired,
  _optional: Record<string, never> = {}
): Promise<{ purged: true }> {
  const { deps, input } = required;
  const existing = await deps.mediaRepo.findById(input);
  if (!existing) throw new MediaNotFoundError({ message: `media '${input.id}' was not found` });

  if (existing.status !== "trashed") {
    throw new MediaStillReferencedError({ message: `media '${input.id}' must be trashed before it can be purged`, referencing: [
        `media '${input.id}' is still active`,
      ] }
    );
  }

  const referencing = await deps.referenceCheck.findReferences({ workspaceId: input.workspaceId, media: existing });
  if (referencing.length > 0) {
    throw new MediaStillReferencedError({ message: `media '${input.id}' is still referenced`, referencing: [...referencing] });
  }

  await removeMediaRowsAndTombstoneBlob(deps, {
    workspaceId: input.workspaceId,
    id: input.id,
    sha256: existing.source.sha256,
  });

  return { purged: true };
}

/** Deps shared by both callers of {@link removeMediaRowsAndTombstoneBlob} — the subset of
 *  `PurgeMediaDeps` that cleanup actually needs (no `blobStore`: neither caller deletes bytes
 *  directly, only tombstones the row via `tombstoneBlobIfUnreferenced`). */
export interface MediaRowCleanupDeps {
  mediaRepo: MediaRepoPort;
  blobRepo: AssetBlobRepoPort;
  renditionRepo: AssetRenditionRepoPort;
  /** Optional — see `PurgeMediaDeps.clock`'s identical doc. */
  clock?: Clock | undefined;
}

/**
 * Shared row/blob cleanup: removes an asset's renditions and media row, then tombstones its blob
 * if-and-only-if no other active media row in the workspace still references the same sha256 (the
 * same predicate {@link tombstoneBlobIfUnreferenced} always applies). Used by both `purgeMedia`
 * (after its trash guard passes) and {@link rollbackUploadedMedia} (an unconditional internal
 * compensating rollback) — the same three-step deletion, triggered from two different callers.
 *
 * @complexity O(n) in the workspace's media row count, inherited from the tombstone-pass's
 * `isBlobUnreferenced` scan.
 */
async function removeMediaRowsAndTombstoneBlob(
  deps: MediaRowCleanupDeps,
  input: { workspaceId: UUID; id: UUID; sha256: string }
): Promise<void> {
  await deps.renditionRepo.removeByAsset({ workspaceId: input.workspaceId, assetId: input.id });
  await deps.mediaRepo.remove({ workspaceId: input.workspaceId, id: input.id });

  const clock = deps.clock ?? createSystemClock();
  await tombstoneBlobIfUnreferenced({
    deps: { mediaRepo: deps.mediaRepo, blobRepo: deps.blobRepo, clock },
    input: { workspaceId: input.workspaceId, sha256: input.sha256 },
  });
}

export interface RollbackUploadedMediaRequired {
  deps: MediaRowCleanupDeps;
  input: { workspaceId: UUID; media: MediaRecord };
}

/**
 * Compensating rollback for {@link uploadMedia}: removes the rendition + media rows it just wrote
 * and tombstones the blob if no other active media row in the workspace still references its
 * sha256 (delegates to {@link removeMediaRowsAndTombstoneBlob}, `purgeMedia`'s own cleanup step).
 *
 * For a caller-side step that runs AFTER `uploadMedia()` has already committed and then fails
 * (e.g. `tool-registrations.ts`'s optional `recordUploadContentType` hook) — without this, the
 * rows `uploadMedia()` wrote survive as orphans (bytes and/or rows nothing points at) even though
 * the caller sees the whole upload as failed. Unlike `purgeMedia`, this performs no trashed-status
 * guard: it is an internal compensating action for a partially-failed operation, not a user-facing
 * delete.
 *
 * @complexity O(n) in the workspace's media row count, inherited from
 * {@link removeMediaRowsAndTombstoneBlob}.
 */
export async function rollbackUploadedMedia(
  required: RollbackUploadedMediaRequired,
  _optional: Record<string, never> = {}
): Promise<void> {
  const { deps, input } = required;
  await removeMediaRowsAndTombstoneBlob(deps, {
    workspaceId: input.workspaceId,
    id: input.media.id,
    sha256: input.media.source.sha256,
  });
}

import { MediaValidationError, type MediaProvenance } from './types.js';

/** Keep only a relative origin label; reject absolute, encoded traversal and control characters.
 * @throws MediaValidationError before storage for unsafe paths. @complexity O(path length). */
function relativeOrigin({ path }: { path: string }, _options = {}): string {
  let decoded: string;
  try { decoded = decodeURIComponent(path).replace(/\\/g, '/'); }
  catch { throw new MediaValidationError({ message: 'source path must be a safe relative path' }); }
  const parts = decoded.split('/');
  if (/^[~/]|:|[\x00-\x1f\x7f?#%]/.test(decoded) || parts.some(part => !part || part === '..' || part === '.')) {
    throw new MediaValidationError({ message: 'source path must be a safe relative path' });
  }
  return decoded;
}

/** Project origin metadata through an allowlist, removing URL credentials, queries and fragments.
 * Call before any upload effects; never persist filesystem roots or signed URL credentials.
 * @throws MediaValidationError for an invalid URL, kind or path. @complexity O(origin length). */
export function safeMediaProvenance({ source }: { source?: MediaProvenance | undefined }, _options = {}): MediaProvenance {
  if (!source) return { kind: 'upload' };
  if (source.kind === 'url') {
    let url: URL;
    try { url = new URL(source.url); }
    catch { throw new MediaValidationError({ message: 'source URL must be HTTP or HTTPS' }); }
    if (!['https:', 'http:'].includes(url.protocol)) throw new MediaValidationError({ message: 'source URL must be HTTP or HTTPS' });
    url.username = ''; url.password = ''; url.search = ''; url.hash = '';
    return { kind: 'url', url: url.href };
  }
  if (source.kind === 'picked-folder') return { kind: source.kind, path: relativeOrigin({ path: source.path }) };
  if (source.kind === 'upload' || source.kind === 'generated') {
    return source.path === undefined ? { kind: source.kind } : { kind: source.kind, path: relativeOrigin({ path: source.path }) };
  }
  throw new MediaValidationError({ message: 'unknown source kind' });
}

import { createHash } from 'node:crypto';
import { nowIso, type Clock, type IdGenerator } from '@jini-ai/core/primitives';
import type { AssetBlobRepoPort, BlobStorePort, MediaRepoPort } from './ports.js';
import type { AssetRenditionRecord, MediaProvenance, MediaRecord } from './types.js';
import { withSha256Lock } from './blob-gc-lock.js';
import { sanitizeSvg } from './sanitize-svg.js';
import { MediaValidationError } from './types.js';
import { DEFAULT_MAX_UPLOAD_BYTES } from './media-service.js';
import { safeMediaProvenance } from './provenance.js';
import { sniffContentType } from './content-type-sniffer.js';

/** Atomic source switch supplied by the host's versioned persistence adapter. */
export interface MediaFileReplacementRepoPort extends MediaRepoPort {
  /** Explicit replacement is separate from metadata/import's write-once source rule. The source
   * compare-and-set and rendition invalidation MUST commit atomically. Hosts without that
   * transaction capability omit this method and callers refuse the command. Old shared blobs
   * are retained; replacing a file is never a purge. */
  replaceFileIfVersion?(required: {
    workspaceId: string; id: string; ifVersion: number; sha256: string; storageKey: string;
    originalRenditionId: string; updatedAt: string; contentType: string; provenance: MediaProvenance;
  }, optional?: Record<string, never>): Promise<{ applied: boolean }>;
  /** A transform begun against an old source must not resurrect its invalidated preview. */
  saveRenditionIfSource?(required: { record: AssetRenditionRecord; sourceSha256: string },
    optional?: Record<string, never>): Promise<{ applied: boolean }>;
}

export interface ReplaceMediaFileDeps {
  workspaceId: string;
  clock: Clock;
  idGen: IdGenerator;
  mediaRepo: MediaFileReplacementRepoPort;
  assetBlobRepo: AssetBlobRepoPort;
  blobStore: BlobStorePort;
  mediaContentTypeStore: { set(input: { workspaceId: string; sha256: string; contentType: string }): Promise<void> };
}

/** Stage verified bytes before the atomic source switch, under the existing GC/dedup lock.
 * No temporary media identity is created. If the CAS fails, an unreferenced staged blob may
 * remain for the normal orphan sweep; deleting it here could destroy another upload's bytes.
 * Callers authorize and validate/sniff bounded bytes before invoking this operation.
 * @returns The updated asset, preserving its identity and metadata, or null on a version conflict.
 * @throws Storage failures propagate; callers must check replacement capabilities first.
 * @complexity O(bytes.length) hashing; constant indexed blob reads/writes under the shared GC lock. */
export async function replaceMediaFile({ deps, media, bytes, contentType, principalId, provenance }: {
  deps: ReplaceMediaFileDeps; media: MediaRecord; bytes: Uint8Array; contentType: string; principalId: string;
  provenance?: MediaProvenance | undefined;
}, { maxUploadBytes = DEFAULT_MAX_UPLOAD_BYTES }: { maxUploadBytes?: number } = {}): Promise<MediaRecord | null> {
  // Library v1 supports metadata rename, never byte replacement under an immutable document name.
  if (media.kind === 'document') throw new MediaValidationError({ message: 'document file replacement is unavailable' });
  if (bytes.byteLength === 0 || bytes.byteLength > maxUploadBytes) {
    throw new MediaValidationError({ message: 'replacement file is empty or exceeds the upload size cap' });
  }
  // Replacement bypasses uploadMedia, so it must call the same SVG sanitizer before hashing.
  const safeBytes = contentType === 'image/svg+xml' ? await sanitizeSvg({ bytes }) : bytes;
  if (safeBytes.byteLength > maxUploadBytes) throw new MediaValidationError({ message: 'sanitized file exceeds the upload size cap' });
  const sha256 = createHash('sha256').update(safeBytes).digest('hex');
  const source = { sha256, contentType: sniffContentType({ bytes: safeBytes }), provenance: safeMediaProvenance({ source: provenance }) };
  const updatedAt = nowIso({ clock: deps.clock });
  return withSha256Lock({ key: sha256, criticalSection: async () => {
    let blob = await deps.assetBlobRepo.findByHash({ workspaceId: deps.workspaceId, sha256 });
    if (!blob) {
      const { storageKey } = await deps.blobStore.put({ workspaceId: deps.workspaceId, sha256, bytes: safeBytes });
      blob = { id: deps.idGen.newId(), workspaceId: deps.workspaceId, sha256, storageKey,
        status: 'active', createdAt: updatedAt, createdByPrincipal: principalId };
      await deps.assetBlobRepo.save(blob);
    } else if (blob.status === 'tombstoned') {
      blob = { ...blob, status: 'active', tombstonedAt: undefined };
      await deps.assetBlobRepo.save(blob);
    }
    await deps.mediaContentTypeStore.set({ workspaceId: deps.workspaceId, sha256, contentType: source.contentType });
    const { applied } = await deps.mediaRepo.replaceFileIfVersion!({ workspaceId: deps.workspaceId,
      id: media.id, ifVersion: media.version, sha256, storageKey: blob.storageKey,
      originalRenditionId: deps.idGen.newId(), updatedAt, contentType: source.contentType, provenance: source.provenance });
    return applied ? { ...media, source, updatedAt, version: media.version + 1 } : null;
  } });
}

import { sniffContentType } from "./content-type-sniffer.js";
import { MediaValidationError } from "./types.js";

const SVG_NAMESPACE = "http://www.w3.org/2000/svg";
const LOCAL_REFERENCE = /^#[a-z_][\w:.-]*$/i;
const RASTER_DATA_IMAGE = /^data:(image\/(?:png|jpeg|gif|webp|avif));base64,([a-z\d+/=\s]+)$/i;

function isRasterDataImage(value: string): boolean {
  const match = RASTER_DATA_IMAGE.exec(value);
  return match !== null && sniffContentType({ bytes: Buffer.from(match[2]!, "base64") }) === match[1]!.toLowerCase();
}

// DOMPurify does not sanitize CSS. Keep ordinary logo styles and local paint servers, but
// discard escaped/comment-obfuscated CSS, at-rules, and every non-document URL.
function hasUnsafeCss(value: string): boolean {
  const withoutLocalUrls = value.replace(/url\(\s*(["']?)(#[a-z_][\w:.-]*)\1\s*\)/gi, "");
  return /[\\@]|\/\*|(?:url|(?:-webkit-)?image-set|src|expression)\s*\(/i.test(withoutLocalUrls);
}

async function createRuntime() {
  // Load the DOM only for SVG; ordinary image uploads keep their existing lightweight path.
  const [{ JSDOM }, { default: createDOMPurify }] = await Promise.all([import("jsdom"), import("dompurify")]);
  const window = new JSDOM("").window;
  const purifier = createDOMPurify(window);
  purifier.addHook("uponSanitizeElement", (node) => {
    // A node named "style" is an Element, and an Element's textContent is always a string (the DOM
    // returns null only for Document/DocumentType), so no null fallback is needed here.
    if (node.nodeName.toLowerCase() === "style" && hasUnsafeCss(node.textContent as string)) node.textContent = "";
  });
  purifier.addHook("uponSanitizeAttribute", (node, attribute) => {
    const name = attribute.attrName.toLowerCase();
    const value = attribute.attrValue.trim();
    if (name.startsWith("on") || name === "xml:base" || hasUnsafeCss(value)) attribute.keepAttr = false;
    if (name === "href" || name === "xlink:href" || name === "src") {
      attribute.keepAttr = LOCAL_REFERENCE.test(value) ||
        (node.nodeName.toLowerCase() === "image" && isRasterDataImage(value));
    }
  });
  return { window, purifier };
}

let runtime: ReturnType<typeof createRuntime> | undefined;

/** Sanitizes a standalone SVG before hashing/storage or inline serving, including legacy blobs.
 * Rejects malformed XML, DTDs/entities and SVG fonts. No scripts or external resources are loaded.
 * @complexity O(n) in the size-bounded SVG document.
 */
export async function sanitizeSvg(
  { bytes }: { bytes: Uint8Array },
  _options: Record<string, never> = {}
): Promise<Uint8Array> {
  const { window, purifier } = await (runtime ??= createRuntime());
  let source: string;
  try {
    source = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    throw new MediaValidationError({ message: "SVG must be valid UTF-8" });
  }
  // Reject before XML parsing: no external entities, SVG font documents, or DTD expansion.
  if (/<!DOCTYPE|<!ENTITY/i.test(source)) throw new MediaValidationError({ message: "SVG DTDs and entities are not allowed" });
  const document = new window.DOMParser().parseFromString(source, "image/svg+xml");
  const root = document.documentElement;
  if (document.querySelector("parsererror") || root.localName !== "svg" || root.namespaceURI !== SVG_NAMESPACE) {
    throw new MediaValidationError({ message: "invalid SVG document" });
  }
  if ([...document.getElementsByTagName("*")].some((element) => ["font", "font-face"].includes(element.localName.toLowerCase()))) {
    throw new MediaValidationError({ message: "SVG fonts are not allowed" });
  }
  purifier.sanitize(root, {
    IN_PLACE: true,
    USE_PROFILES: { svg: true, svgFilters: true },
    ADD_TAGS: ["use"],
    // Animation can rewrite a safe reference after sanitization. Foreign HTML is never media.
    FORBID_TAGS: ["script", "foreignObject", "animate", "animateMotion", "animateTransform", "set", "discard"],
    FORBID_ATTR: ["xml:base"],
    ALLOW_DATA_ATTR: false,
  });
  return new TextEncoder().encode(new window.XMLSerializer().serializeToString(root));
}

import { spawn } from 'node:child_process';
import { constants } from 'node:fs';
import { access, mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { performance } from 'node:perf_hooks';
import { delimiter, isAbsolute, join } from 'node:path';
import { sniffContentType } from './content-type-sniffer.js';
import { getVideoFrameEdge, parseVideoProbe, planVideoFrames, planVideoContactSheets, VIDEO_EXTRACTION_TIMEOUT_MS, VIDEO_MAX_SHEET_BYTES, VIDEO_MAX_FRAME_BYTES, VIDEO_MAX_INPUT_BYTES, VIDEO_MAX_OUTPUT_BYTES, type VideoFrameExtractor, type VideoFrameResult } from './video-frames.js';

export interface VideoBinaries { readonly nice: string; readonly ffmpeg: string; readonly ffprobe: string }
export type VideoBinaryFinder = (required: Record<string, never>, optional: { env?: NodeJS.ProcessEnv; platform?: NodeJS.Platform }) => Promise<VideoBinaries | undefined>;
export type VideoProcessRunner = (required: { command: string; args: readonly string[] }, optional: { timeoutMs: number; maxOutputBytes: number; signal?: AbortSignal }) => Promise<Uint8Array>;
class VideoProcessError extends Error {
  constructor(readonly reason: 'unavailable' | 'timeout' | 'canceled' | 'invalid', message: string) { super(message); }
}

async function executable(required: { name: string }, { configured, env }: { configured?: string | undefined; env: NodeJS.ProcessEnv }): Promise<string | undefined> {
  const candidates = configured ? [configured] : [
    ...(env['PATH'] ?? '').split(delimiter).filter(isAbsolute).map(directory => join(directory, required.name)),
    join('/opt/homebrew/bin', required.name), join('/usr/local/bin', required.name), join('/usr/bin', required.name),
  ];
  for (const candidate of candidates) {
    if (!isAbsolute(candidate)) continue;
    try { await access(candidate, constants.X_OK); if ((await stat(candidate)).isFile()) return candidate; } catch { /* Try the next host executable. */ }
  }
  return undefined;
}

/** Discovery never executes a version/probe command. Configured paths are host configuration,
 * never tool arguments, and all subprocesses (including ffprobe) still go through nice. */
export const findVideoBinaries: VideoBinaryFinder = async (_required, { env = process.env, platform = process.platform } = {}) => {
  if (platform === 'win32') return undefined; // Never silently omit the low-priority guarantee.
  const nice = await executable({ name: 'nice' }, { env });
  const ffmpeg = await executable({ name: 'ffmpeg' }, { configured: env['FFMPEG_PATH'], env });
  const ffprobe = await executable({ name: 'ffprobe' }, { configured: env['FFPROBE_PATH'], env });
  return nice && ffmpeg && ffprobe ? { nice, ffmpeg, ffprobe } : undefined;
};

/** detached creates a group including nice and its eventual executable; killing the group prevents
 * a wrapper from leaving a decoder alive. Waiting for close keeps the extraction lock until exit. */
export const runLowPriorityVideoProcess = async (
  { command, args, spawnProcess = spawn, killGroup = ({ pid }: { pid: number }) => { process.kill(-pid, 'SIGKILL'); } }: {
    command: string; args: readonly string[]; spawnProcess?: typeof spawn;
    killGroup?: (required: { pid: number }, optional: Record<string, never>) => void;
  },
  { timeoutMs, maxOutputBytes, signal }: { timeoutMs: number; maxOutputBytes: number; signal?: AbortSignal },
): Promise<Uint8Array> => {
  if (signal?.aborted) throw new VideoProcessError('canceled', 'Video preview canceled.');
  if (timeoutMs <= 0) throw new VideoProcessError('timeout', 'Video preview timed out.');
  return new Promise((resolve, reject) => {
    const child = spawnProcess(command, [...args], { detached: true, stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true });
    const chunks: Buffer[] = [];
    let bytes = 0;
    let stopped: VideoProcessError | undefined;
    let settled = false;
    const stop = (error: VideoProcessError) => {
      if (stopped || settled) return;
      stopped = error;
      try { if (child.pid === undefined) child.kill('SIGKILL'); else killGroup({ pid: child.pid }, {}); }
      catch { child.kill('SIGKILL'); }
    };
    const timer = setTimeout(() => stop(new VideoProcessError('timeout', 'Video preview timed out.')), timeoutMs);
    const abort = () => stop(new VideoProcessError('canceled', 'Video preview canceled.'));
    const finish = (error?: Error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener('abort', abort);
      if (error) reject(error); else resolve(Buffer.concat(chunks));
    };
    child.stdout?.on('data', (chunk: Buffer) => {
      if (stopped) return;
      bytes += chunk.length;
      if (bytes > maxOutputBytes) { stop(new VideoProcessError('invalid', 'Video preview exceeded its output limit.')); return; }
      chunks.push(chunk);
    });
    // Drain diagnostics but do not retain unbounded stderr or expose host paths to the model.
    child.stderr?.resume();
    child.once('error', (error: NodeJS.ErrnoException) => finish(new VideoProcessError(error.code === 'ENOENT' || error.code === 'EACCES' ? 'unavailable' : 'invalid', 'Video preview process could not start.')));
    child.once('close', (code: number | null) => finish(stopped ?? (code === 0 ? undefined : new VideoProcessError('invalid', 'Video preview could not decode this clip.'))));
    signal?.addEventListener('abort', abort, { once: true });
    if (signal?.aborted) abort();
  });
};

export interface VideoExtractionLock {
  /** Synchronous acquisition prevents races before the first awaited probe. */
  tryAcquire(required: Record<string, never>, optional: Record<string, never>): (() => void) | undefined;
}
/** A host may share this lock across its adapters to enforce a decoder budget.
 * Returns a synchronous try-acquire port; release follows decoder cleanup. @complexity O(1). */
export function createVideoExtractionLock(_required: Record<string, never>, _optional: Record<string, never> = {}): VideoExtractionLock {
  let extracting = false;
  return { tryAcquire() {
    if (extracting) return undefined;
    extracting = true;
    let released = false;
    return () => { if (!released) { released = true; extracting = false; } };
  } };
}
// Shared across ALL adapter instances: a second catalog/tenant cannot run a second ffmpeg in this
// process. Fail busy instead of holding arbitrary numbers of uploaded videos in a pending queue.
const defaultExtractionLock = createVideoExtractionLock({});
const UNAVAILABLE = 'video preview unavailable on this host (nice, ffmpeg and ffprobe are required).';
// Eight amortizes process/seek overhead while bounding expensive source decoders to
// one eighth of the 64-frame maximum. Thread caps alone do not bound decoder memory.
// This is a decoder-count limit, not a measured host RSS guarantee.
const SOURCE_BATCH_SIZE = 8;
const localInputFlags = ['-threads', '1', '-protocol_whitelist', 'file', '-format_whitelist', 'mov,matroska,webm'];

type VideoFrameFailure = Extract<VideoFrameResult, { ok: false }>;
type ContactSheetLayout = ReturnType<typeof planVideoContactSheets>[number];
const TOTAL_OUTPUT_LIMIT = 'Video preview exceeded its total output limit (8 MiB).';
const DIAGNOSTIC_OUTPUT_BYTES = 64 * 1024;

/** Size and container checks that need neither the lock nor a host binary. */
function rejectVideoInput({ bytes }: { bytes: Uint8Array }): VideoFrameFailure | undefined {
  if (bytes.byteLength > VIDEO_MAX_INPUT_BYTES) return { ok: false, reason: 'too-large', message: `Video preview input exceeds ${VIDEO_MAX_INPUT_BYTES} bytes.` };
  const type = sniffContentType({ bytes });
  if (type !== 'video/mp4' && type !== 'video/webm') return { ok: false, reason: 'invalid', message: 'Video preview requires stored MP4 or WebM bytes.' };
  return undefined;
}

function toVideoFailure(error: unknown): VideoFrameFailure {
  if (!(error instanceof VideoProcessError)) return { ok: false, reason: 'invalid', message: 'Video preview could not read or decode this clip.' };
  return { ok: false, reason: error.reason, message: error.reason === 'unavailable' ? UNAVAILABLE : error.message };
}

interface ExtractionRun {
  readonly checkDeadline: () => void;
  readonly run: (required: { binary: string; args: readonly string[] }, optional: { maxOutputBytes: number }) => Promise<Uint8Array>;
}
/** One deadline shared by the probe and every ffmpeg pass; each process gets only what is left. */
function createExtractionRun(
  { binaries, runProcess, nowMs, deadline }: { binaries: VideoBinaries; runProcess: VideoProcessRunner; nowMs: () => number; deadline: number },
  { signal }: { signal?: AbortSignal | undefined },
): ExtractionRun {
  const checkDeadline = () => {
    if (signal?.aborted) throw new VideoProcessError('canceled', 'Video preview canceled.');
    if (nowMs() >= deadline) throw new VideoProcessError('timeout', 'Video preview timed out.');
  };
  const run: ExtractionRun['run'] = (required, optional) => {
    checkDeadline();
    const timeoutMs = deadline - nowMs();
    if (timeoutMs <= 0) throw new VideoProcessError('timeout', 'Video preview timed out.');
    return runProcess({ command: binaries.nice, args: ['-n', '19', required.binary, ...required.args] },
      { timeoutMs, maxOutputBytes: optional.maxOutputBytes, ...(signal ? { signal } : {}) });
  };
  return { checkDeadline, run };
}

interface OutputPlan {
  readonly sheetLayouts: readonly ContactSheetLayout[] | undefined;
  readonly edge: number;
  readonly perImageLimit: number;
  readonly fileLimit: number;
  readonly paths: readonly string[];
  readonly tilePaths: readonly string[];
  readonly tileLimit: number;
}
const imagePaths = ({ directory, count, prefix }: { directory: string; count: number; prefix: string }) =>
  Array.from({ length: count }, (_, index) => join(directory, `${prefix}-${index}.jpg`));

function planFrameOutputs({ directory, times }: { directory: string; times: readonly number[] }): OutputPlan {
  // Preallocate a fair share for each output, so all file limits together fit the total budget.
  const fileLimit = Math.min(VIDEO_MAX_FRAME_BYTES, Math.floor(VIDEO_MAX_OUTPUT_BYTES / times.length));
  const paths = imagePaths({ directory, count: times.length, prefix: 'image' });
  return { sheetLayouts: undefined, edge: getVideoFrameEdge({ frameCount: times.length }, {}), perImageLimit: VIDEO_MAX_FRAME_BYTES, fileLimit, paths, tilePaths: paths, tileLimit: fileLimit };
}

function planSheetOutputs({ directory, times }: { directory: string; times: readonly number[] }): OutputPlan {
  const sheetLayouts = planVideoContactSheets({ times }, {});
  return {
    sheetLayouts,
    // planVideoContactSheets throws on no timestamps, so there is always a first sheet.
    edge: sheetLayouts[0]!.tileEdgePx,
    perImageLimit: VIDEO_MAX_SHEET_BYTES,
    fileLimit: Math.min(VIDEO_MAX_SHEET_BYTES, Math.floor(VIDEO_MAX_OUTPUT_BYTES / sheetLayouts.length)),
    paths: imagePaths({ directory, count: sheetLayouts.length, prefix: 'image' }),
    tilePaths: imagePaths({ directory, count: times.length, prefix: 'tile' }),
    // Intermediates have their own bounded allocation; never spend a sheet's 2 MiB per tile.
    tileLimit: Math.min(VIDEO_MAX_FRAME_BYTES, Math.floor(VIDEO_MAX_OUTPUT_BYTES / times.length)),
  };
}

const ffmpegArgs = () => ['-hide_banner', '-loglevel', 'error', '-nostdin', '-filter_threads', '1', '-filter_complex_threads', '1'];
// Framerate mode is per output (ffmpeg >=5.1); preserve each selected frame
// for both source extraction and contact-sheet assembly without resync.
const appendOutput = ({ args, label, path, limit }: { args: string[]; label: string; path: string; limit: number }) => args.push(
  '-map', label, '-an', '-sn', '-dn', '-frames:v', '1', '-c:v', 'mjpeg', '-threads', '1',
  '-q:v', '5', '-fs', String(limit), '-f', 'mjpeg', '-fps_mode', 'passthrough', path,
);
const isJpeg = (image: Uint8Array) => image.length >= 4 && image[0] === 255 && image[1] === 216 && image[image.length - 2] === 255 && image[image.length - 1] === 217;

async function readImage({ path, perImageLimit, fileLimit }: { path: string; perImageLimit: number; fileLimit: number }, { checkDeadline }: Pick<ExtractionRun, 'checkDeadline'>): Promise<Uint8Array> {
  checkDeadline();
  // -fs is packet-granular: check size before allocating and refuse overshoot.
  const size = (await stat(path)).size;
  checkDeadline();
  if (size > perImageLimit) throw new VideoProcessError('invalid', 'Video preview exceeded its output limit.');
  if (size > fileLimit) throw new VideoProcessError('invalid', TOTAL_OUTPUT_LIMIT);
  const image = await readFile(path);
  checkDeadline();
  if (!isJpeg(image)) throw new VideoProcessError('invalid', 'Video preview returned no JPEG frame.');
  return image;
}

function sourceBatchArgs({ batch, offset, input, plan }: { batch: readonly number[]; offset: number; input: string; plan: OutputPlan }): string[] {
  const { edge, sheetLayouts } = plan;
  const scale = `scale=w='min(${edge},iw)':h='min(${edge},ih)':force_original_aspect_ratio=decrease`;
  const pad = sheetLayouts ? `,pad=${edge}:${edge}:(ow-iw)/2:(oh-ih)/2:color=black` : '';
  const args = ffmpegArgs();
  // Seek each source input before opening it; no full-clip select/decode scan.
  for (const at of batch) args.push(...localInputFlags, '-ss', String(at), '-i', input);
  const filters = batch.map((_, index) => `[${index}:V:0]trim=end_frame=1,setpts=PTS-STARTPTS,${scale},setsar=1${pad}[tile${index}]`);
  args.push('-filter_complex', filters.join(';'));
  for (let index = 0; index < batch.length; index++) appendOutput({ args, label: `[tile${index}]`, path: plan.tilePaths[offset + index]!, limit: plan.tileLimit });
  return args;
}

/** Extracts every sampled frame in serial source batches; frames layout keeps them, sheet layout leaves tiles on disk. */
async function extractSourceTiles(
  { input, times, plan, ffmpeg }: { input: string; times: readonly number[]; plan: OutputPlan; ffmpeg: string },
  extraction: ExtractionRun,
): Promise<Uint8Array[]> {
  const images: Uint8Array[] = [];
  let tileBytes = 0;
  // Await exit and validate this batch before starting another: <=8 source contexts alive.
  for (let offset = 0; offset < times.length; offset += SOURCE_BATCH_SIZE) {
    extraction.checkDeadline();
    const batch = times.slice(offset, offset + SOURCE_BATCH_SIZE);
    const args = sourceBatchArgs({ batch, offset, input, plan });
    // Raw MJPEG with one frame writes one JPEG through the file muxer (-fs applies).
    await extraction.run({ binary: ffmpeg, args }, { maxOutputBytes: DIAGNOSTIC_OUTPUT_BYTES });
    extraction.checkDeadline();
    for (let index = 0; index < batch.length; index++) {
      const image = await readImage({ path: plan.tilePaths[offset + index]!, perImageLimit: VIDEO_MAX_FRAME_BYTES, fileLimit: plan.tileLimit }, extraction);
      tileBytes += image.byteLength;
      if (tileBytes > VIDEO_MAX_OUTPUT_BYTES) throw new VideoProcessError('invalid', TOTAL_OUTPUT_LIMIT);
      if (!plan.sheetLayouts) images.push(image); // Sheet tiles remain on disk, not retained in memory.
    }
  }
  return images;
}

function sheetArgs({ inputs, sheet, edge, path, limit }: { inputs: readonly string[]; sheet: ContactSheetLayout; edge: number; path: string; limit: number }): string[] {
  const args = ffmpegArgs();
  // These decoders see only small, validated JPEGs, never the source video.
  for (const input of inputs) args.push('-threads', '1', '-protocol_whitelist', 'file', '-format_whitelist', 'mjpeg', '-f', 'mjpeg', '-i', input);
  const filters = inputs.map((_, tile) => `[${tile}:v:0]trim=end_frame=1,setpts=PTS-STARTPTS[tile${tile}]`);
  const labels = inputs.map((_, tile) => `[tile${tile}]`).join('');
  const positions = sheet.tiles.map(tile => `${(tile.column - 1) * edge}_${(tile.row - 1) * edge}`).join('|');
  const stack = inputs.length === 1 ? 'null' : `xstack=inputs=${inputs.length}:layout=${positions}:fill=black:shortest=1`;
  // Pad the grid if unused bottom-right cells do not establish the full extent.
  filters.push(`${labels}${stack},pad=${sheet.columns * edge}:${sheet.rows * edge}:0:0:color=black[sheet]`);
  args.push('-filter_complex', filters.join(';'));
  appendOutput({ args, label: '[sheet]', path, limit });
  return args;
}

/** Assembles each contact sheet from its validated on-disk tiles, one JPEG-only ffmpeg pass per sheet. */
async function assembleSheets(
  { sheetLayouts, plan, ffmpeg }: { sheetLayouts: readonly ContactSheetLayout[]; plan: OutputPlan; ffmpeg: string },
  extraction: ExtractionRun,
): Promise<Uint8Array[]> {
  const images: Uint8Array[] = [];
  let offset = 0;
  let outputBytes = 0;
  for (const [index, sheet] of sheetLayouts.entries()) {
    extraction.checkDeadline();
    const inputs = plan.tilePaths.slice(offset, offset + sheet.tiles.length);
    const path = plan.paths[index]!;
    await extraction.run({ binary: ffmpeg, args: sheetArgs({ inputs, sheet, edge: plan.edge, path, limit: plan.fileLimit }) }, { maxOutputBytes: DIAGNOSTIC_OUTPUT_BYTES });
    const image = await readImage({ path, perImageLimit: plan.perImageLimit, fileLimit: plan.fileLimit }, extraction);
    outputBytes += image.byteLength;
    if (outputBytes > VIDEO_MAX_OUTPUT_BYTES) throw new VideoProcessError('invalid', TOTAL_OUTPUT_LIMIT);
    images.push(image);
    // Retire tiles as soon as their sheet is verified; finally still cleans on any failure.
    for (const tilePath of inputs) { extraction.checkDeadline(); await rm(tilePath); }
    offset += inputs.length;
  }
  return images;
}

interface ExtractorDeps {
  readonly findBinaries: VideoBinaryFinder;
  readonly runProcess: VideoProcessRunner;
  readonly nowMs: () => number;
  readonly env: NodeJS.ProcessEnv | undefined;
  readonly platform: NodeJS.Platform | undefined;
}
const discoverBinaries = ({ findBinaries, env, platform }: Pick<ExtractorDeps, 'findBinaries' | 'env' | 'platform'>) =>
  findBinaries({}, { ...(env ? { env } : {}), ...(platform ? { platform } : {}) });
/** The locked part of one extraction: discovery, private input, probe, frames and optional sheets.
 * Records the temporary directory in `workspace` as soon as it exists so the caller always removes it. */
async function extractLocked(
  { bytes, options, deadline, workspace }: { bytes: Uint8Array; options: Parameters<VideoFrameExtractor['extract']>[1]; deadline: number; workspace: { directory?: string } },
  { findBinaries, runProcess, nowMs, env, platform }: ExtractorDeps,
): Promise<VideoFrameResult> {
  if (options.signal?.aborted) throw new VideoProcessError('canceled', 'Video preview canceled.');
  if (options.layout !== undefined && options.layout !== 'frames' && options.layout !== 'sheet') throw new VideoProcessError('invalid', 'Video layout must be frames or sheet.');
  const binaries = await discoverBinaries({ findBinaries, env, platform });
  if (!binaries) return { ok: false, reason: 'unavailable', message: UNAVAILABLE };
  const directory = workspace.directory = await mkdtemp(join(tmpdir(), 'video-preview-'));
  const input = join(directory, 'input');
  await writeFile(input, bytes, { mode: 0o600, flag: 'wx' });
  const extraction = createExtractionRun({ binaries, runProcess, nowMs, deadline }, { signal: options.signal });
  const probe = await extraction.run({ binary: binaries.ffprobe, args: ['-v', 'error', ...localInputFlags, '-show_entries', 'format=duration,format_name:stream=codec_type,codec_name,width,height,duration:stream_disposition=attached_pic', '-of', 'json', '-i', input] }, { maxOutputBytes: DIAGNOSTIC_OUTPUT_BYTES });
  const metadata = parseVideoProbe({ output: Buffer.from(probe).toString('utf8'), sizeBytes: bytes.byteLength }, {});
  const times = planVideoFrames({ duration: metadata.duration }, options);
  const plan = options.layout === 'sheet' ? planSheetOutputs({ directory, times }) : planFrameOutputs({ directory, times });
  const frames = await extractSourceTiles({ input, times, plan, ffmpeg: binaries.ffmpeg }, extraction);
  const { sheetLayouts } = plan;
  if (!sheetLayouts) {
    extraction.checkDeadline();
    return { ok: true, metadata, frames: times.map((at, index) => ({ at, mimeType: 'image/jpeg', bytes: frames[index]! })) };
  }
  const sheets = await assembleSheets({ sheetLayouts, plan, ffmpeg: binaries.ffmpeg }, extraction);
  extraction.checkDeadline();
  return { ok: true, metadata, frames: [], sheets: sheetLayouts.map((sheet, index) => ({ ...sheet, mimeType: 'image/jpeg', bytes: sheets[index]! })) };
}

async function removeWorkspace({ directory }: { directory?: string }): Promise<VideoFrameFailure | undefined> {
  try { if (directory) await rm(directory, { recursive: true, force: true }); }
  catch { return { ok: false, reason: 'invalid', message: 'Video preview temporary files could not be removed.' }; }
  return undefined;
}

export function createFfmpegVideoFrameExtractor(
  { findBinaries = findVideoBinaries, runProcess = runLowPriorityVideoProcess, nowMs = () => performance.now(), lock = defaultExtractionLock, env, platform }: { lock?: VideoExtractionLock; env?: NodeJS.ProcessEnv; platform?: NodeJS.Platform; findBinaries?: VideoBinaryFinder; runProcess?: VideoProcessRunner; nowMs?: (required: Record<string, never>, optional: Record<string, never>) => number },
  _optional: Record<string, never> = {},
): VideoFrameExtractor {
  const deps: ExtractorDeps = { findBinaries, runProcess, nowMs: () => nowMs({}, {}), env, platform };
  return { extract: async ({ bytes }, options): Promise<VideoFrameResult> => {
    const rejected = rejectVideoInput({ bytes });
    if (rejected) return rejected;
    const release = lock.tryAcquire({}, {});
    if (!release) return { ok: false, reason: 'busy', message: 'Video preview is busy. Try again after the current extraction finishes.' };
    const deadline = deps.nowMs() + VIDEO_EXTRACTION_TIMEOUT_MS;
    const workspace: { directory?: string } = {};
    const result = await extractLocked({ bytes, options, deadline, workspace }, deps).catch(toVideoFailure);
    // Neither step throws, so the lock is always released, and only after cleanup.
    const cleanupFailure = await removeWorkspace(workspace);
    release();
    return cleanupFailure ?? result;
  } };
}

/** Video preview contract and sampling policy, independent of a host, codec or AI provider. */
export const VIDEO_MAX_FRAMES = 64;
export const VIDEO_DEFAULT_FRAMES = 16;
export const VIDEO_MAX_EDGE_PX = 768;
export const VIDEO_MAX_INPUT_BYTES = 64 * 1024 * 1024;
export const VIDEO_MAX_FRAME_BYTES = 512 * 1024;
/** Aggregate raw JPEG payload budget; base64 expands this to about 10.67 MiB plus metadata. */
export const VIDEO_MAX_OUTPUT_BYTES = 8 * 1024 * 1024;
export const VIDEO_MAX_SHEET_BYTES = 2 * 1024 * 1024;
export const VIDEO_MAX_SHEETS = 4;
// One shared deadline: serial source batches and JPEG sheet assembly need launch/seek
// headroom at nice 19. This remains a hard bound, not a per-process allowance.
export const VIDEO_EXTRACTION_TIMEOUT_MS = 60_000;

export interface VideoMetadata {
  readonly duration: number;
  readonly width: number;
  readonly height: number;
  readonly codec: string;
  readonly container: string;
  readonly sizeBytes: number;
  readonly hasAudio: boolean;
}
export interface VideoFrame { readonly at: number; readonly mimeType: 'image/jpeg'; readonly bytes: Uint8Array }
export interface VideoSheetTile { readonly index: number; readonly row: number; readonly column: number; readonly at: number }
export interface VideoSheetLayout {
  readonly columns: number;
  readonly rows: number;
  readonly tileEdgePx: number;
  /** One-based row-major positions; timestamp order and repetitions are preserved. */
  readonly tiles: readonly VideoSheetTile[];
}
export interface VideoContactSheet extends VideoSheetLayout { readonly mimeType: 'image/jpeg'; readonly bytes: Uint8Array }
export interface VideoFrameOptions {
  readonly layout?: 'frames' | 'sheet';
  readonly frames?: number;
  readonly at?: readonly number[];
  readonly every?: number;
  readonly start?: number;
  readonly signal?: AbortSignal;
}
export type VideoFrameResult =
  | { readonly ok: true; readonly metadata: VideoMetadata; readonly frames: readonly VideoFrame[]; readonly sheets?: readonly VideoContactSheet[] }
  | { readonly ok: false; readonly reason: 'unavailable' | 'busy' | 'too-large' | 'timeout' | 'canceled' | 'invalid'; readonly message: string };
/** Implementations return <=64 sampled frames: separate JPEGs <=512KiB or <=4 sheets <=2MiB.
 * The count-dependent pixel policy and <=8MiB aggregate budget apply in both modes.
 * Sheet mode returns frames: [] plus sheets; separate mode omits sheets. Overflow fails in full.
 * Inputs are authorized bytes, never caller paths. No provider or CMS-owner concepts live here. */
export interface VideoFrameExtractor {
  extract(required: { bytes: Uint8Array }, optional: VideoFrameOptions): Promise<VideoFrameResult>;
}

/** Keep sixteen square 768px images worth of pixels (about 12.6k tokens at pixels/750).
 * Even pixel sizes are codec-friendly; flooring never increases the budget. */
export function getVideoFrameEdge(
  { frameCount }: { frameCount: number }, _optional: Record<string, never> = {},
): number {
  if (!Number.isInteger(frameCount) || frameCount < 1 || frameCount > VIDEO_MAX_FRAMES) throw new Error('Frame count must be an integer from 1 to 64.');
  return 2 * Math.floor(VIDEO_MAX_EDGE_PX * Math.min(1, Math.sqrt(VIDEO_DEFAULT_FRAMES / frameCount)) / 2);
}

/** Grid pixels, including black unused cells, share the separate-frame pixel budget.
 * Metadata provides labels without requiring a host font or ffmpeg drawtext support. */
export function planVideoContactSheets(
  { times }: { times: readonly number[] }, _optional: Record<string, never> = {},
): VideoSheetLayout[] {
  if (!Array.isArray(times) || times.length < 1 || times.length > VIDEO_MAX_FRAMES || times.some(time => typeof time !== 'number' || !Number.isFinite(time) || time < 0)) {
    throw new Error('Sheets require 1 to 64 finite nonnegative timestamps.');
  }
  const groups: VideoSheetLayout[] = [];
  for (let offset = 0; offset < times.length; offset += 16) {
    const group = times.slice(offset, offset + 16);
    const columns = Math.min(4, Math.ceil(Math.sqrt(group.length)));
    const rows = Math.ceil(group.length / columns);
    groups.push({ columns, rows, tileEdgePx: 0, tiles: group.map((at, index) => ({ index: index + 1, row: Math.floor(index / columns) + 1, column: index % columns + 1, at })) });
  }
  const frameCount = groups.reduce((sum, group) => sum + group.columns * group.rows, 0);
  const tileEdgePx = getVideoFrameEdge({ frameCount }, {});
  return groups.map(group => ({ ...group, tileEdgePx }));
}

const isFiniteNumber = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value);

function assertDurationAndCount({ duration, frames }: { duration: number; frames: number | undefined }): void {
  if (!Number.isFinite(duration) || duration <= 0) throw new Error('Video duration must be positive and finite.');
  if (frames !== undefined && !isFiniteNumber(frames)) throw new Error('Frame count must be finite.');
  if (frames !== undefined && frames < 0) throw new Error('Frame count must be nonnegative.');
}

function assertTimestamps({ at }: { at: readonly number[] | undefined }): void {
  if (at !== undefined && (!Array.isArray(at) || !at.length || at.some(time => !isFiniteNumber(time)))) {
    throw new Error('at must contain finite timestamps in seconds.');
  }
  if (at?.some(time => time < 0)) throw new Error('at timestamps must be nonnegative.');
}

function assertSpacing({ at, every, start }: { at: readonly number[] | undefined; every: number | undefined; start: number }): void {
  if (every !== undefined && (!isFiniteNumber(every) || every <= 0)) throw new Error('every must be a positive finite number of seconds.');
  if (!isFiniteNumber(start) || start < 0) throw new Error('start must be a nonnegative finite number of seconds.');
  if (at !== undefined && every !== undefined) throw new Error('every cannot be combined with at.');
}

/** Fixed-interval sampling from start; see planVideoFrames for the count/EOF rules. */
function planEveryFrames({ count, start, every, end, countGiven }: { count: number; start: number; every: number; end: number; countGiven: boolean }): number[] {
  const times: number[] = [];
  for (let index = 0; index < count; index++) {
    const time = start + index * every;
    // Multiplication can round a fitting boundary just above end. Only tolerate arithmetic
    // roundoff; a materially later timestamp must not add an EOF sample when count is omitted.
    const tolerance = Number.EPSILON * Math.max(end, Math.abs(time)) * 4;
    if (!countGiven && index > 0 && (!Number.isFinite(time) || time - end > tolerance)) break;
    times.push(Math.min(end, time));
  }
  return times;
}

/** Avoid seeking to exact EOF, which commonly has no decodable frame. Preserve explicit order,
 * including repeated timestamps, so image positions continue to match the requested positions.
 * With every and no count, stop when the next timestamp cannot fit (always emit the first clamped
 * position). An explicit count preserves the requested count, clamping positions beyond the clip.
 * start only affects every; at overrides count/start, but at + every is invalid. */
export function planVideoFrames(
  { duration }: { duration: number },
  { frames, at, every, start = 0 }: Pick<VideoFrameOptions, 'frames' | 'at' | 'every' | 'start'> = {},
): number[] {
  assertDurationAndCount({ duration, frames });
  assertTimestamps({ at });
  assertSpacing({ at, every, start });
  const inset = Math.min(0.1, duration / 10);
  const end = duration - inset;
  if (at !== undefined) {
    return at.slice(0, VIDEO_MAX_FRAMES).map(time => Math.max(0, Math.min(end, time)));
  }
  const count = Math.max(1, Math.min(VIDEO_MAX_FRAMES, Math.floor(frames ?? (every !== undefined ? VIDEO_MAX_FRAMES : VIDEO_DEFAULT_FRAMES))));
  if (every !== undefined) return planEveryFrames({ count, start, every, end, countGiven: frames !== undefined });
  if (count === 1) return [duration / 2];
  return Array.from({ length: count }, (_, index) => inset + (end - inset) * index / (count - 1));
}

type ProbeStream = { codec_type?: string; codec_name?: string; width?: number; height?: number; duration?: string; disposition?: { attached_pic?: number } };
type ProbeOutput = { streams?: ProbeStream[]; format?: { duration?: string; format_name?: string } };
type ProbedVideo = ProbeStream & { width: number; height: number };

/** The container duration wins when usable; otherwise fall back to the video stream's own. */
function probeDuration(raw: ProbeOutput, video: ProbeStream | undefined): number {
  const formatDuration = Number(raw?.format?.duration);
  return Number.isFinite(formatDuration) && formatDuration > 0 ? formatDuration : Number(video?.duration);
}

function isUsableVideo(video: ProbeStream | undefined, duration: number): video is ProbedVideo {
  return !!video && Number.isFinite(duration) && duration > 0 && Number.isInteger(video.width) && Number.isInteger(video.height) && video.width! > 0 && video.height! > 0;
}

/** Parse only the ffprobe fields requested by the adapter. File size is measured from authorized
 * input bytes, never from a possibly stale container header. Cover art is not a video stream. */
export function parseVideoProbe(
  { output, sizeBytes }: { output: string; sizeBytes: number }, _optional: Record<string, never> = {},
): VideoMetadata {
  const raw = JSON.parse(output) as ProbeOutput;
  const streams = Array.isArray(raw?.streams) ? raw.streams : [];
  const video = streams.find(stream => stream.codec_type === 'video' && stream.disposition?.attached_pic !== 1);
  const duration = probeDuration(raw, video);
  if (!isUsableVideo(video, duration)) throw new Error('Video metadata is missing or invalid.');
  return { duration, width: video.width, height: video.height, codec: video.codec_name ?? 'unknown', container: raw.format?.format_name ?? 'unknown', sizeBytes, hasAudio: streams.some(stream => stream.codec_type === 'audio') };
}

import type { AgentToolDefinition, AgentToolSideEffect, AgentToolActorClassRule } from "@jini-ai/core";
/**
 * @file The Navigation (Menus) agent-tool catalog — this domain's instance of the
 * per-domain `agent-tools.ts` convention `forms/agent-tools.ts` and `identity/agent-tools.ts`
 * already use.
 *
 * Purpose:
 * A static, in-process catalog describing every agent-callable tool this domain exposes and the
 * permission each carries. Every entry maps 1:1 onto a real exported function of
 * `navigation/menu-service.ts` (plus two pure reads over `MenuRepoPort`) — this catalog never names
 * an operation the domain cannot perform.
 *
 * Precedent already in this library: `navigation/contracts.ts` declares `NAVIGATION_AI_TOOLS` — a
 * design-note list of an intended future AI tool surface (`navigation.search`/`.get`/`.where_used`/
 * `.update`/`.assign`) for a DIFFERENT, not-yet-built delivery mechanism (a "change-set review
 * layer" HITL gateway; the list itself is unused anywhere in this build today). Two of its five
 * names do not correspond to any real, callable capability in this build: `navigation.search` has
 * no implementation beyond `MenuRepoPort.list` (folded into `menus_list_menus` below — there is no
 * separate text-search capability, matching how `identity_user_list`/`identity_role_list` are
 * likewise this library's "search" for their own domains), and `navigation.where_used` has no
 * implementation anywhere (`NavWhereUsedResult` is declared in `contracts.ts` but no function in
 * `navigation/` computes it — `entry_refs`-backed where-used, unlike `widgets`/`media`, was never
 * built for menus). Wrapping either literally would invent backend capability this catalog's own
 * discipline forbids; `menus_list_menus` + `menus_get_menu` are this build's honest equivalents of
 * "search"/"get".
 *
 * Deliberate absence (the point of a catalog, not an oversight):
 * - There is NO `menus_delete_menu` (nor a separate trash-only tool). `deleteMenu` is ONE function
 *   that performs BOTH steps of the deletion ladder, keyed off the menu's CURRENT status:
 *   a first call trashes (safe, unconditional), but a second call against an already-trashed menu
 *   PURGES it — a hard, irreversible delete, blocked only by a still-bound-location guard that
 *   itself can be bypassed with `force` (gated behind the separate `admin.menus.delete.force`
 *   permission). Unlike `widgets`/`media` (which expose trash and purge as two SEPARATE domain
 *   functions, letting a catalog safely wire trash alone), navigation has no decomposed trash-only
 *   entrypoint to call — the very same tool call, made twice, silently escalates from a reversible
 *   soft-delete into a permanent one. That is exactly the shape of risk `identity/agent-tools.ts`
 *   excludes `resetUserPassword` for: a single lever whose second pull does something categorically
 *   more dangerous than its first, reachable by an agent re-invoking a tool it already called once
 *   (e.g. after losing track of a prior call, or via prompt injection through ordinary operator
 *   content). Left human-UI-only.
 *
 * How it relates to the project:
 * A host's own tool-registration layer maps these entries into `ToolRegistration`s (see
 * `tool-registrations.ts`). Unlike Forms/Identity/Widgets, `menu-service.ts`'s functions perform NO
 * internal `authorize()` call of their own (confirmed: `CreateMenuDeps`/`UpdateMenuTreeDeps`/
 * `AssignLocationDeps` carry no `authorize` field) — every admin HTTP route a host builds is expected
 * to check `deps.authorize(...)` inline, before calling the service function (mirrors `media`'s
 * identical gap, see `media/agent-tools.ts`'s header). `tool-registrations.ts` therefore performs
 * that SAME inline `authorize()` call itself (the identical permission string and `entityType:
 * "menu"` the HTTP route uses) rather than relying on a domain-layer gate that does not exist for
 * this library.
 *
 * Architectural role:
 * `navigation` domain declaration. Imports only `VALID_TARGET_KINDS`-equivalent constants are not
 * exported from `menu-service.ts` as public data (the target-kind allowlist is enforced, not
 * published, there), so the target schema below is hand-authored against `types.ts`'s `NavTarget`
 * union and cross-checked by this catalog's own contract test rather than imported.
 */

