// updateMenuTree
// ---------------------------------------------------------------------------

export interface UpdateMenuTreeDeps {
  /** Required for submitted HTML; omitted markup retains the already-normalized stored value. */
  normalizeMenuHtml?: MenuHtmlNormalizer | undefined;
  repo: MenuRepoPort;
  clock: Clock;
  /** Not previously present on this deps bag — needed to mint the outbox event's id. */ 
  idGen: IdGenerator;
  /** Enqueues `navigation.menu.updated` after a successful save. */ 
  outbox: OutboxPort;
}

export interface UpdateMenuTreeServiceInput {
  workspaceId: UUID;
  id: UUID;
  /** The entry `version` this edit was based on — OCC guard. */ 
  expectedVersion: number;
  title?: string | undefined;
  slug?: string | undefined;
  /** The full replacement tree (whole-tree edit). Omitted keeps the stored tree (an HTML-only edit). */ 
  items?: readonly NavItemNode[] | undefined;
  /** HTML mode (`menu-html.ts`); omitted keeps the stored value. The host gates raw HTML first. */
  mode?: NavMenuMode | undefined;
  html?: string | undefined;
}

export interface UpdateMenuTreeRequired {
  deps: UpdateMenuTreeDeps;
  input: UpdateMenuTreeServiceInput;
}

export interface UpdateMenuTreeOptional {
  limits?: TreeValidationLimits | undefined;
}

/** The stored `entryRef` hint fields a whole-tree save carries forward when the submitted target omits them. */
const ENTRY_HINT_KEYS = ["entryType", "lastKnownHref"] as const;

function entryTargetsById(nodes: readonly NavItemNode[], into = new Map<string, NavEntryTarget>()): Map<string, NavEntryTarget> {
  for (const node of nodes) {
    if (node.target?.kind === "entryRef") into.set(node.id, node.target);
    if (node.children) entryTargetsById(node.children, into);
  }
  return into;
}

function withStoredHints(target: NavTarget, stored: NavEntryTarget | undefined): NavTarget {
  if (target.kind !== "entryRef" || !stored || stored.entryId !== target.entryId) return target;
  const merged: Record<string, unknown> = { ...target };
  for (const key of ENTRY_HINT_KEYS) {
    if (merged[key] === undefined && stored[key] !== undefined) merged[key] = stored[key];
  }
  return merged as unknown as NavEntryTarget;
}

/**
 * Whole-tree saves arrive from callers that may not know an item's stored hint fields (an agent
 * echoing a read through a schema, an older editor build). Dropping them on every save made an
 * untouched menu look changed (dry run 2026-10-05: ~30 header page links lost `entryType: "page"`
 * on one assistant save and the menu showed pending-to-live). So a hint is kept when the same item
 * id still points at the same entry and the submitted target leaves that hint out; a re-pointed
 * link or an explicitly submitted hint is taken as sent.
 */
export function carryForwardEntryHints(
  { previous, next }: { previous: readonly NavItemNode[]; next: readonly NavItemNode[] },
  _optional = {}
): NavItemNode[] {
  const stored = entryTargetsById(previous);
  const walk = (nodes: readonly NavItemNode[]): NavItemNode[] =>
    nodes.map((node) => ({
      ...node,
      target: withStoredHints(node.target, stored.get(node.id)),
      children: node.children ? walk(node.children) : undefined,
    }));
  return walk(next);
}

/**
 * Replaces a menu's whole item tree, guarded by optimistic concurrency on the
 * entry `version` (matches the host's `updatePost` pattern): `expectedVersion` must equal the version
 * read, and the repo's `save` compares it again atomically with the write; either miss throws
 * `MenuVersionConflictError`.
 *
 * Id-stability note ("an update may not renumber surviving items"):
 * this build enforces only that ids are present and unique within the
 * submitted tree (`validateAndCloneTree`). Detecting whether a *specific*
 * surviving node kept its original id would require diffing against the
 * previous tree and is deferred — a caller-discipline requirement for now,
 * not a runtime-enforced invariant.
 *
 * @complexity O(n) in the new tree size for validation; O additional repo
 * calls (one read, at most one slug-uniqueness read, one write).
 * @overallScore 90
 * @findings Medium: id-stability across edits (ids not renumbered on survive)
 * is documented but not runtime-enforced — see doc comment above. Deferred
 * pending a tree-diff mechanism; would need the previous tree's id set passed
 * in to check "no id vanished and reappeared elsewhere," which is more than
 * this slice's scope calls for.
 */ 
export async function updateMenuTree(
  required: UpdateMenuTreeRequired,
  optional: UpdateMenuTreeOptional = {}
): Promise<{ menu: NavMenuEntry }> {
  const { deps, input } = required;
  const existing = await findMenuOrThrow({ repo: deps.repo, workspaceId: input.workspaceId, id: input.id });
  assertMenuLive({ menu: existing });
  // The new record is built from this read, so a basis that differs from it must not reach the save:
  // it could match a version another writer lands after this read and overwrite that writer.
  if (existing.version !== input.expectedVersion) {
    throw menuVersionConflictError({ id: input.id, expectedVersion: input.expectedVersion, found: existing.version });
  }

  const title = (input.title ?? existing.title).trim();
  const slug = (input.slug ?? existing.slug).trim().toLowerCase();
  assertValidTitleAndSlug(title, slug);

  if (slug !== existing.slug) {
    await assertSlugAvailable({ repo: deps.repo, workspaceId: input.workspaceId, slug }, { ownerId: existing.id });
  }

  const items = input.items === undefined ? existing.doc.items : carryForwardEntryHints({
    previous: existing.doc.items,
    next: validateAndCloneTree({ items: input.items }, optional.limits),
  });
  // Every writer (admin, agent tool, publish repoint, reverters) comes through here, so the stored
  // HTML-mode fields are carried forward unless this write sets them — an items-only save never drops them.
  const htmlFields = menuHtmlFields({ input, existing: existing.doc, normalizeHtml: deps.normalizeMenuHtml });

  const menu: NavMenuEntry = {
    ...existing,
    title,
    slug,
    doc: { type: NAV_DOC_TYPE, version: existing.doc.version, items, ...htmlFields },
    updatedAt: kernelNowIso({ clock: deps.clock }),
    version: existing.version + 1,
  };

  // The version check is ALSO the save's compare-and-set, not only the read above: a check before
  // the write alone let two editors that read the same version both land (wm S4).
  await deps.repo.save(menu, { expectedVersion: input.expectedVersion });

  await enqueueEvent({
    deps,
    name: "navigation.menu.updated",
    workspaceId: menu.workspaceId,
    aggregateId: menu.id,
    payload: { menuId: menu.id, slug: menu.slug },
  });

  return { menu };
}

// ---------------------------------------------------------------------------
// assignLocation
// ---------------------------------------------------------------------------

export interface AssignLocationDeps {
  repo: MenuRepoPort;
  bindingRepo: NavLocationBindingRepoPort;
  clock: Clock;
  /** Not previously present on this deps bag — needed to mint outbox event ids. */ 
  idGen: IdGenerator;
  /** Enqueues `navigation.location.assigned` (+ `.unassigned` on reassignment). */ 
  outbox: OutboxPort;
}

export interface AssignLocationServiceInput {
  workspaceId: UUID;
  menuId: UUID;
  locationKey: NavLocationKey;
}

export interface AssignLocationRequired {
  deps: AssignLocationDeps;
  input: AssignLocationServiceInput;
}

export interface AssignLocationOptional {}

/**
 * Assigns a menu to a theme location. This writes two
 * representations that must stay in lockstep:
 * 1. the menu's own `locations` field (source of truth, revisioned), and
 * 2. the derived `nav_location_bindings` row (uniqueness index).
 *
 * If the location was already bound to a *different* menu, that menu is
 * **reassigned away** (last-writer-wins, the chosen
 * default) and its `locations` field is updated to drop the key — recorded as
 * its own revision-worthy write.
 *
 * Atomicity: these writes are ONE transaction (`repo.transaction`) — the displaced
 * menu's save, this menu's save, the binding upsert and the outbox events commit
 * together or not at all. Both menu saves are compare-and-set, so the second can
 * lose to another editor AFTER the first landed: without the transaction, that
 * left the displaced menu's `locations` without the key while the binding still
 * pointed at it, and a binding rebuild then dropped the assignment. A
 * `MenuVersionConflictError` (or any other throw) rolls the whole unit back in a
 * store that can roll back; `InMemoryMenuRepo` cannot (see its `transaction`).
 *
 * @complexity O repo calls (bounded: at most two menu reads/writes plus one
 * binding upsert), independent of workspace size.
 * @overallScore 100
 */ 
export async function assignLocation(
  required: AssignLocationRequired,
  _optional: AssignLocationOptional = {}
): Promise<{ menu: NavMenuEntry; binding: NavLocationBindingRow; displacedMenu: NavMenuEntry | null }> {
  const { deps, input } = required;
  const menu = await findMenuOrThrow({ repo: deps.repo, workspaceId: input.workspaceId, id: input.menuId });
  assertMenuLive({ menu });

  const now = kernelNowIso({ clock: deps.clock });

  const updatedMenu: NavMenuEntry = {
    ...menu,
    locations: menu.locations.includes(input.locationKey)
      ? menu.locations
      : [...menu.locations, input.locationKey],
    updatedAt: now,
    version: menu.version + 1,
  };

  return deps.repo.transaction({ fn: async () => {
    const existingBinding = await deps.bindingRepo.findByLocation({
      workspaceId: input.workspaceId,
      locationKey: input.locationKey,
    });

    let displacedMenu: NavMenuEntry | null = null;
    if (existingBinding && existingBinding.menuId !== input.menuId) {
      const displaced = await deps.repo.findById({
        workspaceId: input.workspaceId,
        id: existingBinding.menuId,
      });
      if (displaced) {
        const updatedDisplaced: NavMenuEntry = {
          ...displaced,
          locations: displaced.locations.filter((key) => key !== input.locationKey),
          updatedAt: now,
          version: displaced.version + 1,
        };
        await deps.repo.save(updatedDisplaced, { expectedVersion: displaced.version });
        displacedMenu = updatedDisplaced;
      }
    }

    await deps.repo.save(updatedMenu, { expectedVersion: menu.version });

    const binding = await deps.bindingRepo.upsert({
      workspaceId: input.workspaceId,
      locationKey: input.locationKey,
      menuId: input.menuId,
      boundAt: now,
    });

    if (displacedMenu) {
      await enqueueEvent({
        deps,
        name: "navigation.location.unassigned",
        workspaceId: input.workspaceId,
        aggregateId: displacedMenu.id,
        payload: { locationKey: input.locationKey, menuId: displacedMenu.id },
      });
    }

    await enqueueEvent({
      deps,
      name: "navigation.location.assigned",
      workspaceId: input.workspaceId,
      aggregateId: input.menuId,
      payload: { locationKey: input.locationKey, menuId: input.menuId },
    });

    return { menu: updatedMenu, binding, displacedMenu };
  } });
}

// ---------------------------------------------------------------------------
// deleteMenu (trash → purge ladder, mirrors the media library's deletion ladder)
// ---------------------------------------------------------------------------

export interface DeleteMenuDeps {
  repo: MenuRepoPort;
  bindingRepo: NavLocationBindingRepoPort;
  clock: Clock;
  /** Not previously present on this deps bag — needed to mint outbox event ids. */ 
  idGen: IdGenerator;
  /** Enqueues `navigation.menu.updated` (trash) or `navigation.menu.deleted` (purge); nothing on a blocked purge. */ 
  outbox: OutboxPort;
}

export interface DeleteMenuServiceInput {
  workspaceId: UUID;
  id: UUID;
  /** Force past the 409 dangling-location guard (needs `navigation.delete.force`). */ 
  force?: boolean | undefined;
}

export interface DeleteMenuRequired {
  deps: DeleteMenuDeps;
  input: DeleteMenuServiceInput;
}

export interface DeleteMenuOptional {}

/**
 * Deletion ladder (mirrors the media library's):
 * 1. First call on a non-trashed menu **soft-deletes** it (`status: 'trash'`,
 * revisioned) and returns — no purge yet.
 * 2. A second call on an already-trashed menu attempts the **hard purge** If
 * the menu is still bound to any location, purge is rejected with
 * `MenuLocationBoundError` (409-style) listing the bound keys, unless
 * `force` is set — permission-gating that error behind
 * `navigation.delete.force` is the caller's (gateway's) job, not this
 * function's; this function only enforces the *shape* of the guard.
 * 3. On a successful purge, the menu row and all of its location bindings are
 * removed.
 *
 * @complexity O repo calls; O(k) bindings scanned where k = locations this
 * menu holds (small, bounded by registered locations).
 * @overallScore 100
 */ 
export async function deleteMenu(
  required: DeleteMenuRequired,
  _optional: DeleteMenuOptional = {}
): Promise<{ menu: NavMenuEntry | null; purged: boolean }> {
  const { deps, input } = required;
  const existing = await findMenuOrThrow({ repo: deps.repo, workspaceId: input.workspaceId, id: input.id });

  if (existing.status !== "trash") {
    const trashed: NavMenuEntry = {
      ...existing,
      status: "trash",
      updatedAt: kernelNowIso({ clock: deps.clock }),
      version: existing.version + 1,
    };
    await deps.repo.save(trashed);

    await enqueueEvent({
      deps,
      name: "navigation.menu.updated",
      workspaceId: trashed.workspaceId,
      aggregateId: trashed.id,
      payload: { menuId: trashed.id, slug: trashed.slug },
    });

    return { menu: trashed, purged: false };
  }

  const bindings = await deps.bindingRepo.listByMenu({
    workspaceId: input.workspaceId,
    menuId: input.id,
  });

  if (bindings.length > 0 && !input.force) {
    const boundLocations = bindings.map((row) => row.locationKey);
    throw new MenuLocationBoundError({ message: `menu '${input.id}' is still bound to location(s): ${boundLocations.join(", ")} — unassign before purging, or use force`, boundLocations: boundLocations }
    );
  }

  await deps.repo.remove({ workspaceId: input.workspaceId, id: input.id });
  await deps.bindingRepo.removeByMenu({ workspaceId: input.workspaceId, menuId: input.id });

  await enqueueEvent({
    deps,
    name: "navigation.menu.deleted",
    workspaceId: existing.workspaceId,
    aggregateId: existing.id,
    payload: { menuId: existing.id, slug: existing.slug },
  });

  return { menu: null, purged: true };
}

/**
 * @file In-memory adapters for the `navigation` library.
 *
 * Purpose:
 * Provides the two dev/test persistence adapters this build needs:
 *
 * - `InMemoryNavLocationBindingRepo` — the real `NavLocationBindingRepoPort`
 *   adapter (`ports.ts`) for the derived `nav_location_bindings` index, honoring
 *   its `UNIQUE (workspace_id, location_key)` constraint via last-writer-wins
 *   `upsert`.
 * - `InMemoryMenuRepo` — a **self-contained** menu store. The original design is explicit
 *   that a menu "adds NO new persistence port" because it should ride the
 *   generic entries repo. That generic entries system is not yet
 *   implemented as reusable code (only `post` exists as a concrete type in the
 *   host that first built this), so this build stores menu records directly
 *   instead of force-fitting the not-yet-generic entries system. `MenuRepoPort`
 *   below is a local, navigation-owned interface (not part of the frozen
 *   `ports.ts` surface) that exists only to make this simplification
 *   swappable later without touching `menu-service.ts` call sites. When the
 *   generic entries system ships, this repo should be deleted in favor of the
 *   entries repo, and `MenuRepoPort` should be deleted in favor of typed reads
 *   over it.
 *
 * How it relates to the project:
 * - `menu-service.ts` and `resolver.ts` depend on `MenuRepoPort`, not this
 *   concrete class, so a host-supplied SQLite/entries-backed adapter is a
 *   drop-in.
 *
 * Architectural role:
 * Adapters only. No validation or business rules live here (that is
 * `menu-service.ts`'s job) — these classes are dumb, uniqueness-enforcing
 * collections.
 */
import type { UUID } from "@jini-ai/core/primitives";
import { menuVersionConflictError } from "./menu-service.js";
import type { NavLocationBindingRepoPort } from "./ports.js";
import type { NavLocationBindingRow, NavLocationKey, NavMenuEntry } from "./types.js";

// ---------------------------------------------------------------------------
// Local, navigation-owned menu repo port (deliberately NOT in ports.ts —
// see file header: menus ride the entries repo once it exists generically).
// ---------------------------------------------------------------------------

/**
 * Storage seam for menu records, standing in for the generic entries
 * repo until that generic system exists as reusable code. Shape mirrors the
 * `post` feature's own repo port plus a `remove` for hard purge, since menus
 * have a real hard-delete step in their deletion ladder (mirrors the media
 * library's).
 */
export interface MenuRepoPort {
  findById(required: { workspaceId: UUID; id: UUID }): Promise<NavMenuEntry | null>;
  findBySlug(required: { workspaceId: UUID; slug: string }): Promise<NavMenuEntry | null>;
  list(required: { workspaceId: UUID }): Promise<NavMenuEntry[]>;
  /**
   * Writes `record` by id. With `expectedVersion`, the write is a compare-and-set: it lands only when
   * the stored row is live (not `status: "trash"`) and still holds that version, checked atomically
   * with the write (one conditional UPDATE in a SQL adapter), so two writers that read the same
   * version cannot both land. With `expectedVersion: null` it is insert-if-absent (a create that
   * keeps a caller-given id, e.g. a host's id-preserving import; `INSERT ... ON CONFLICT DO NOTHING`
   * in a SQL adapter), so two creates of one id cannot both land either. Without it, the write is
   * unconditional (`createMenu`'s freshly minted id, trash seams).
   * @throws MenuVersionConflictError ``menu '<id>' was modified concurrently (expected version <n>, found <stored|none>)``,
   *         or ``menu '<id>' already exists (expected no menu, found version <n>)`` for a create
   *         ({@link menuVersionConflictError}).
   */
  save(record: NavMenuEntry, options?: MenuSaveOptions): Promise<void>;
  /** Hard-remove a menu row. Only called after the trash step. */
  remove(required: { workspaceId: UUID; id: UUID }): Promise<void>;
  /**
   * Runs `fn` as ONE unit of work: every menu save, binding write and outbox enqueue inside it commits
   * together or not at all, and a nested call joins the outer one. `assignLocation` needs it because it
   * writes two menus, then the binding: a conflict on the second menu must not leave the first one's
   * `locations` changed while the binding still points at it. A SQL adapter runs its connection's
   * transaction, and the binding repo and outbox must write through that same connection (a wiring
   * obligation of the host). A store with nothing to roll back may just call `fn` (see
   * `InMemoryMenuRepo.transaction`).
   */
  transaction<T>(required: { fn: () => Promise<T> }): Promise<T>;
}

/** Options for {@link MenuRepoPort.save}. */
export interface MenuSaveOptions {
  /** The version the caller read; the save throws `MenuVersionConflictError` unless the stored live row still holds it.
   *  `null` is a create: the save throws unless no row (live, trashed, or in another workspace) holds the id. */
  expectedVersion?: number | null | undefined;
}

/** Re-exported from here, where it has always been exported from; it lives in `menu-service.ts` so that
 *  module's own read check can throw it without a value import cycle. */
export { menuVersionConflictError };

/**
 * In-memory `MenuRepoPort` adapter for dev/tests. See file header for why a
 * self-contained repo exists instead of an entries-backed one.
 *
 * @complexity Every operation is O(n) in the workspace's menu count via a
 * linear scan; acceptable for the in-memory/dev-test adapter this library
 * builds now. A SQLite adapter would index `(workspace_id, id)` /
 * `(workspace_id, slug)` instead.
 * @overallScore 100
 */
export class InMemoryMenuRepo implements MenuRepoPort {
  private rows: NavMenuEntry[];

  constructor(requiredArgs: Record<string, never>, optionalArgs: { initialRows?: NavMenuEntry[] } = {}) {
    const { initialRows = [] } = optionalArgs;
    this.rows = [...initialRows];
  }

  async findById(required: { workspaceId: UUID; id: UUID }): Promise<NavMenuEntry | null> {
    return (
      this.rows.find(
        (row) => row.workspaceId === required.workspaceId && row.id === required.id
      ) ?? null
    );
  }

  async findBySlug(required: { workspaceId: UUID; slug: string }): Promise<NavMenuEntry | null> {
    return (
      this.rows.find(
        (row) => row.workspaceId === required.workspaceId && row.slug === required.slug
      ) ?? null
    );
  }

  async list(required: { workspaceId: UUID }): Promise<NavMenuEntry[]> {
    return this.rows.filter((row) => row.workspaceId === required.workspaceId);
  }

  async save(record: NavMenuEntry, options: MenuSaveOptions = {}): Promise<void> {
    const index = this.rows.findIndex(
      (row) => row.workspaceId === record.workspaceId && row.id === record.id
    );
    if (options.expectedVersion === null) {
      // A create needs the id free in every workspace and status, as a SQL primary key on `id` does.
      const holder = this.rows.find((row) => row.id === record.id);
      if (holder) throw menuVersionConflictError({ id: record.id, expectedVersion: null, found: holder.version });
    } else if (options.expectedVersion !== undefined) {
      const stored = this.rows[index];
      const found = stored && stored.status !== "trash" ? stored.version : null;
      if (found !== options.expectedVersion) {
        throw menuVersionConflictError({ id: record.id, expectedVersion: options.expectedVersion, found });
      }
    }
    if (index === -1) {
      this.rows.push(record);
      return;
    }
    this.rows[index] = record;
  }

  /**
   * Just runs `fn`: nothing here rolls back, the same disclosed choice as `InMemoryEntryRepo`'s. A
   * partial write can only be left by a version conflict on a later save of the same unit, which in
   * this single-process store needs another writer to land between that unit's awaits; dev and test
   * hosts accept that, and every durable host adapter must roll back.
   * @complexity O(1) beyond `fn`.
   */
  async transaction<T>(required: { fn: () => Promise<T> }): Promise<T> {
    return required.fn();
  }

  async remove(required: { workspaceId: UUID; id: UUID }): Promise<void> {
    this.rows = this.rows.filter(
      (row) => !(row.workspaceId === required.workspaceId && row.id === required.id)
    );
  }
}

// ---------------------------------------------------------------------------
// NavLocationBindingRepoPort — the one real port this library declares
// ---------------------------------------------------------------------------

/**
 * In-memory `NavLocationBindingRepoPort` adapter for dev/tests. Enforces the
 * derived index's `UNIQUE (workspace_id, location_key)` constraint by storing
 * at most one row per `(workspaceId, locationKey)` pair: `upsert` replaces
 * whatever row previously held that key (last-writer-wins).
 *
 * @complexity O(n) linear scan per operation over the workspace's binding
 * count; `n` is bounded by the number of registered locations, which is small
 * by construction (never a user-scale collection).
 * @overallScore 100
 */
export class InMemoryNavLocationBindingRepo implements NavLocationBindingRepoPort {
  private rows: NavLocationBindingRow[];

  constructor(requiredArgs: Record<string, never>, optionalArgs: { initialRows?: NavLocationBindingRow[] } = {}) {
    const { initialRows = [] } = optionalArgs;
    this.rows = [...initialRows];
  }

  async findByLocation(required: {
    workspaceId: UUID;
    locationKey: NavLocationKey;
  }): Promise<NavLocationBindingRow | null> {
    return (
      this.rows.find(
        (row) =>
          row.workspaceId === required.workspaceId && row.locationKey === required.locationKey
      ) ?? null
    );
  }

  async listByMenu(required: {
    workspaceId: UUID;
    menuId: UUID;
  }): Promise<NavLocationBindingRow[]> {
    return this.rows.filter(
      (row) => row.workspaceId === required.workspaceId && row.menuId === required.menuId
    );
  }

  async listByWorkspace(required: { workspaceId: UUID }): Promise<NavLocationBindingRow[]> {
    return this.rows.filter((row) => row.workspaceId === required.workspaceId);
  }

  async upsert(required: {
    workspaceId: UUID;
    locationKey: NavLocationKey;
    menuId: UUID;
    boundAt: string;
  }): Promise<NavLocationBindingRow> {
    const row: NavLocationBindingRow = {
      workspaceId: required.workspaceId,
      locationKey: required.locationKey,
      menuId: required.menuId,
      boundAt: required.boundAt,
    };
    const index = this.rows.findIndex(
      (existing) =>
        existing.workspaceId === required.workspaceId &&
        existing.locationKey === required.locationKey
    );
    if (index === -1) {
      this.rows.push(row);
    } else {
      // Last-writer-wins reassignment: the UNIQUE(workspace_id, location_key)
      // constraint means there is never more than one row for this key.
      this.rows[index] = row;
    }
    return row;
  }

  async remove(required: { workspaceId: UUID; locationKey: NavLocationKey }): Promise<void> {
    this.rows = this.rows.filter(
      (row) =>
        !(row.workspaceId === required.workspaceId && row.locationKey === required.locationKey)
    );
  }

  async removeByMenu(required: { workspaceId: UUID; menuId: UUID }): Promise<void> {
    this.rows = this.rows.filter(
      (row) => !(row.workspaceId === required.workspaceId && row.menuId === required.menuId)
    );
  }

  async rebuildForWorkspace(required: {
    workspaceId: UUID;
    bindings: readonly NavLocationBindingRow[];
  }): Promise<void> {
    const others = this.rows.filter((row) => row.workspaceId !== required.workspaceId);
    this.rows = [...others, ...required.bindings];
  }
}

/**
 * @file Render-time read model for the `navigation` library.
 *
 * Purpose:
 * `resolveForLocation` is the one typed call a theme renderer makes: look up
 * the menu bound to a location, then walk its stored item tree into a
 * `ResolvedNav` — concrete hrefs, `available` flags, active-state — so the
 * theme "receives resolved data, never resolves refs".
 *
 * How it relates to the project:
 * - `entryRef`/`termRef`/`route` targets need a resolver over entries/taxonomy/
 *   routing. Those are host-owned concerns and are not this library's running
 *   code, so this module does NOT import them. Instead it takes an injected
 *   `resolveTargetHref` function as a dependency — the exact seam a host's own
 *   routing layer later backs. This keeps `resolver.ts` compiling and testable
 *   today with a fake, and wiring a real routing implementation in later is a
 *   pure DI swap, not a rewrite.
 * - `url` targets are already-resolved hrefs (validated at write time in
 *   `menu-service.ts`) and pass straight through.
 * - `termRef` targets: term-link
 *   integrity has **no compatible schema yet** (`entry_refs` is
 *   entry-to-entry only) — this is a named blocker, not an oversight.
 *   This resolver does not special-case `termRef`; it is passed to the same
 *   injected `resolveTargetHref` as `entryRef`/`route`, and a fake/real
 *   resolver that has no term schema to consult should return `null`, which
 *   this module already turns into `available: false` on that node only (the
 *   rest of the tree still resolves).
 *
 * Architectural role:
 * Pure read-side feature logic. No storage writes; no theme code reachable
 * from here reads storage directly (render-IR boundary honored by
 * returning only `ResolvedNav`/`ResolvedNavItem` data).
 */
import type { MenuRepoPort } from "./repo.memory.js";
import type { NavLocationBindingRepoPort, NavResolveContext } from "./ports.js";
import type {
  NavItemNode,
  NavLocationKey,
  NavMenuDoc,
  NavMenuEntry,
  NavTarget,
  ResolvedNav,
  ResolvedNavItem,
} from "./types.js";

/**
 * A resolved, already-known-available href for a `url` target, or the outcome
 * of resolving a ref/route target: `path` plus whether it is currently
 * reachable. `null` means "could not resolve at all" (unknown/deleted/no
 * schema yet, e.g. `termRef` per the Round-3 fold) — distinct from
 * `available: false`, which means "resolved to a real target that is
 * currently unavailable" (e.g. trashed). Both cases end up `available: false`
 * on the `ResolvedNavItem`; the distinction is for the resolver implementation's
 * own diagnostics, not surfaced further.
 */
export interface ResolvedTargetHref {
  readonly path: string;
  readonly available: boolean;
}

/**
 * The injected seam standing in for a host's own routing library. Resolves
 * one non-`url` target (`entryRef`, `termRef`, or `route`) to an href, or
 * `null` if it cannot be resolved at all (deleted target, or — for `termRef`
 * today — no schema yet to resolve against).
 */
export type ResolveTargetHrefFn = (
  required: { target: NavTarget; context: NavResolveContext },
  optional?: Record<string, never>
) => Promise<ResolvedTargetHref | null>;

export interface ResolveForLocationDeps {
  menuRepo: MenuRepoPort;
  bindingRepo: NavLocationBindingRepoPort;
  resolveTargetHref: ResolveTargetHrefFn;
}

export interface ResolveForLocationServiceInput {
  workspaceId: string;
  locationKey: NavLocationKey;
  /** Current request path, for `isCurrent`/`isActive` computation. */
  currentPath?: string | undefined;
}

export interface ResolveForLocationRequired {
  deps: ResolveForLocationDeps;
  input: ResolveForLocationServiceInput;
}

export interface ResolveForLocationOptional {}

/**
 * Resolves the menu bound to a theme location into a render-ready
 * `ResolvedNav`, or `null` if the location has no menu bound.
 *
 * Defensive note: if the binding index points at a menu id the menu repo no
 * longer has (a stale derived row — the index is declared rebuildable —
 * this resolves to `null` rather than throwing, since a
 * missing nav fragment is a theme-recoverable degradation and a hard error at
 * render time is not.
 *
 * @complexity O(n) over the resolved menu's total node count — one
 * `resolveTargetHref` call per non-`url` node, awaited depth-first. No bound
 * on concurrency is applied since menu trees are bounded (
 * `DEFAULT_MAX_ITEM_COUNT` in `menu-service.ts`) and are not a user-scale
 * collection at render time.
 * @overallScore 100
 */
export async function resolveForLocation(
  required: ResolveForLocationRequired,
  _optional: ResolveForLocationOptional = {}
): Promise<ResolvedNav | null> {
  const { deps, input } = required;

  const menu = await findBoundMenu({ deps, input });
  if (!menu) return null;

  const context: NavResolveContext = {
    workspaceId: input.workspaceId,
    currentPath: input.currentPath,
  };

  const items = await resolveMenuDoc({ doc: menu.doc, context, resolveTargetHref: deps.resolveTargetHref });

  return {
    menuId: menu.id,
    locationKey: input.locationKey,
    title: menu.title,
    items,
  };
}

/** Select a location's stored menu without resolving its presentation. Shared by tree and HTML
 * renderers; stale bindings and cross-workspace ids return null so hosts can retain their fallback.
 * @returns The bound menu, or null when the binding or menu is missing.
 * @complexity Two indexed repository reads, O(1) additional space. Repository faults propagate.
 */
export async function findBoundMenu(
  required: {
    deps: Pick<ResolveForLocationDeps, "menuRepo" | "bindingRepo">;
    input: Pick<ResolveForLocationServiceInput, "workspaceId" | "locationKey">;
  },
  _optional: Record<string, never> = {},
): Promise<NavMenuEntry | null> {
  const { deps, input } = required;
  const binding = await deps.bindingRepo.findByLocation({ workspaceId: input.workspaceId, locationKey: input.locationKey });
  if (!binding) return null;
  return deps.menuRepo.findById({ workspaceId: input.workspaceId, id: binding.menuId });
}

export interface ResolveMenuDocRequired {
  doc: NavMenuDoc;
  context: NavResolveContext;
  resolveTargetHref: ResolveTargetHrefFn;
}

/**
 * Resolves a menu document's item tree into render-ready `ResolvedNavItem`s, independent of any
 * location binding — the doc-level building block `resolveForLocation` composes on top of (menu
 * lookup + location-binding lookup), and the seam a caller with a menu already in hand (e.g. a
 * `widgets`-style `menu` widget type) needs to get real hrefs without duplicating the href-walking
 * logic `resolveForLocation` already owns (`resolveItemList`/`resolveItem` below stay
 * module-private; this is the one exported entry point to their behavior).
 *
 * @complexity O(n) over the doc's total node count — see `resolveItemList`.
 * @overallScore 100
 */
export async function resolveMenuDoc(required: ResolveMenuDocRequired): Promise<ResolvedNavItem[]> {
  const { doc, context, resolveTargetHref } = required;
  return resolveItemList(doc.items, context, resolveTargetHref);
}

/**
 * Resolves a sibling list of item nodes, depth-first, preserving order.
 *
 * @complexity O(n) over the subtree's node count.
 * @overallScore 100
 */
async function resolveItemList(
  nodes: readonly NavItemNode[],
  context: NavResolveContext,
  resolveTargetHref: ResolveTargetHrefFn
): Promise<ResolvedNavItem[]> {
  const resolved: ResolvedNavItem[] = [];
  for (const node of nodes) {
    resolved.push(await resolveItem(node, context, resolveTargetHref));
  }
  return resolved;
}

/**
 * Resolves one node: `url` targets pass through directly (already validated
 * hrefs, `menu-service.ts`); every other kind goes through the injected
 * `resolveTargetHref` seam. A `null`/unavailable result never throws and never
 * drops the node — it is returned with `available: false, href: null` so the
 * rest of the tree keeps resolving (themes must omit unavailable
 * links, never render dead ones, but core still hands back a full model for
 * the theme to filter).
 *
 * Label-fallback simplification: `types.ts`'s `NavItemNode.label` doc says it
 * "falls back to the target's title when absent." Deriving a target's title
 * needs entry/taxonomy metadata that `ResolveTargetHrefFn` does not return
 * (only `{ path, available }`); doing that fallback for real is deferred to
 * whenever the injected resolver is widened to return a title alongside the
 * href. For now an absent `label` resolves to `""`, which is a documented gap,
 * not a silent behavior claim.
 *
 * @complexity O(1) at this node plus the cost of resolving its `children`
 * subtree (accounted in the caller's overall O(n)).
 * @overallScore 90
 * @findings Low: label fallback to target title is not implemented (see note
 * above) — deferred pending a richer `ResolveTargetHrefFn` return shape.
 */
async function resolveItem(
  node: NavItemNode,
  context: NavResolveContext,
  resolveTargetHref: ResolveTargetHrefFn
): Promise<ResolvedNavItem> {
  const children = node.children
    ? await resolveItemList(node.children, context, resolveTargetHref)
    : [];

  let href: string | null = null;
  let available: boolean;

  if (node.target.kind === "url") {
    href = node.target.href;
    available = true;
  } else {
    // entryRef / termRef / route: resolved via the injected seam standing in
    // for the host's own routing layer, which is not this library's running
    // code. termRef in particular has no compatible entry_refs schema today
    // — a resolver with no term schema to
    // consult returns null here, same as any other "cannot resolve" outcome.
    const result = await resolveTargetHref({ target: node.target, context });
    if (result === null) {
      href = null;
      available = false;
    } else {
      href = result.path;
      available = result.available;
    }
  }

  const isCurrent =
    available && href !== null && context.currentPath !== undefined && href === context.currentPath;
  const isActive = isCurrent || children.some((child) => child.isActive);

  return {
    id: node.id,
    label: node.label ?? "",
    href: available ? href : null,
    available,
    isCurrent,
    isActive,
    attrs: node.attrs,
    children,
  };
}

import type { IdGenerator } from "@jini-ai/core/primitives";
import { adaptLegacyAuthorize } from "../core/tools/index.js";
import type { Clock } from "@jini-ai/core/primitives";
/**
 * @file Navigation's (Menus') half of the agent-tool authorization wiring: maps `agent-tools.ts`'s five
 * catalog entries onto `menu-service.ts`'s read/create/update/assign operations, as
 * `ToolRegistration`s. The entire catalog is wired — `deleteMenu` is deliberately absent from the
 * catalog rather than present-but-unwired; see `navigation/agent-tools.ts`'s own header.
 *
 * Authorization shape: like Media and unlike Forms/Identity/Widgets, `menu-service.ts`'s functions
 * perform NO internal `authorize()` call of their own — every admin HTTP route a host builds gates
 * inline. Every handler here does the same via the kit's `requireToolPermission`, which is the
 * single evaluation for these tools, located where the real route locates it.
 */
import { ToolInputError } from "@jini-ai/core";
import type { AuthorizeFn } from "../core/commands/command.js";
import type { OutboxPort } from "../core/ports.js";
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, requireNumber, requireString, withSchemaOnRejection, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration } from "@jini-ai/core";
import { requireToolPermission } from "../core/tools/index.js";
import { menusAgentToolCatalog } from "./agent-tools.js";
import { assignLocation, createMenu, MenuNotFoundError, MenuValidationError, updateMenuTree } from "./menu-service.js";
import { isMenuHtmlAuthoring, type MenuHtmlNormalizer } from "./menu-html.js";
import type { NavLocationBindingRepoPort } from "./ports.js";
import type { MenuRepoPort } from "./repo.memory.js";
import type { NavItemNode, NavMenuEntry, NavMenuMode } from "./types.js";

const CATALOG_BY_ID = indexCatalogById({ catalog: menusAgentToolCatalog });

/**
 * The exact slice of the route-deps bag Menus' tool handlers read. Declared structurally (rather
 * than importing a host's own `RouteDeps`) so this module carries no back-edge into any host's
 * composition root. A host's `server/routes/*` satisfies this structurally by passing its existing
 * route-deps object after binding the kernel clock/ID contracts.
 */
export interface MenusToolDeps {
  /** Environment-owned fragment normalizer, forwarded to the audited menu write services. */
  normalizeMenuHtml?: MenuHtmlNormalizer | undefined;
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  idGen: IdGenerator;
  outbox: OutboxPort;
  menuRepo: MenuRepoPort;
  navLocationBindingRepo: NavLocationBindingRepoPort;
  /**
   * The host's raw-HTML permission (host example: `pages.edit_html`, the one HTML-mode forms use). A write
   * carrying menu HTML is checked against it on top of the menu permission; unset, HTML menus are refused.
   */
  rawHtmlPermission?: string | undefined;
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const menusDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> menuRepo.list: reads only.
  ["menus_list_menus", "none"],
  // -> menuRepo.findById: reads only.
  ["menus_get_menu", "none"],
  // -> createMenu (menu-service.ts): repo.save + outbox.enqueue.
  ["menus_create_menu", "mutates-durable-state"],
  // -> updateMenuTree (menu-service.ts): repo.save + outbox.enqueue.
  ["menus_update_menu_tree", "mutates-durable-state"],
  // -> assignLocation (menu-service.ts): repo.save (maybe twice, on displacement) + bindingRepo.upsert
  //    + outbox.enqueue. Never a delete: deleteMenu is deliberately not exposed (see
  //    navigation/agent-tools.ts's file header).
  ["menus_assign_location", "mutates-durable-state"],
]);

/** The only Menus rejection worth decorating with the published schema — a shape problem a different input would fix. */
function isMenusShapeRejection(error: unknown): boolean {
  return error instanceof MenuValidationError;
}

/** What a Menus tool returns to the model — see {@link toMenuToolView}. */
interface MenuToolView {
  id: string;
  slug: string;
  title: string;
  status: NavMenuEntry["status"];
  items: NavItemNode[];
  mode?: NavMenuMode | undefined;
  html?: string | undefined;
  locations: string[];
  version: number;
}

/**
 * Projects a `NavMenuEntry` into an explicit model-facing shape rather than returning the domain
 * record verbatim — the same discipline Forms' `toFormDefinitionView` applies. `items` is
 * deep-cloned via a JSON round-trip (the tree is JSON-serializable by construction, `types.ts`'s
 * `NavMenuDoc` doc comment) rather than shallow-copied, since a tool caller pushing onto a nested
 * `children` array must not be able to mutate domain state through the returned view the way a
 * single top-level spread could not protect against.
 */
function toMenuToolView(menu: NavMenuEntry): MenuToolView {
  return {
    id: menu.id,
    slug: menu.slug,
    title: menu.title,
    status: menu.status,
    items: JSON.parse(JSON.stringify(menu.doc.items)) as NavItemNode[],
    ...(menu.doc.mode !== undefined ? { mode: menu.doc.mode } : {}),
    ...(menu.doc.html !== undefined ? { html: menu.doc.html } : {}),
    locations: [...menu.locations],
    version: menu.version,
  };
}

/** A write's HTML-mode fields as sent; `menu-service.ts` validates their values. */
function htmlAuthoring(input: Record<string, unknown>): { mode?: NavMenuMode; html?: string } {
  return {
    ...(input.mode !== undefined ? { mode: input.mode as NavMenuMode } : {}),
    ...(input.html !== undefined ? { html: input.html as string } : {}),
  };
}

/**
 * Raw HTML is the host's trust boundary (HTML Pages, HTML-mode forms), so a write that authors menu
 * HTML also needs that permission. Checked before the write, like forms' `prepareFormAuthoring`.
 */
async function requireHtmlAuthoringPermission(
  { routeDeps, principalId, authoring, menuId }: { routeDeps: MenusToolDeps; principalId: string; authoring: { mode?: NavMenuMode; html?: string }; menuId?: string },
): Promise<void> {
  if (!isMenuHtmlAuthoring(authoring)) return;
  if (!routeDeps.rawHtmlPermission) throw new ToolInputError({ message: "HTML menus are not enabled on this site" });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId, permission: routeDeps.rawHtmlPermission }, { entityType: "menu", ...(menuId ? { entityId: menuId } : {}) });
}

function menusDeps(routeDeps: MenusToolDeps) {
  return { repo: routeDeps.menuRepo, clock: routeDeps.clock, idGen: routeDeps.idGen, outbox: routeDeps.outbox, normalizeMenuHtml: routeDeps.normalizeMenuHtml };
}

/**
 * Normalize the update target's legacy menuId to id before the executor's schema/policy gates.
 * Retain menuId for 90 days from the coordinated release, including the key spellings the shared
 * normalizer previously accepted. Read selectors and assignment references keep their own ABI.
 * Direct handler callers use this same adapter to retain their legacy input contract.
 * @returns Canonical input and value-free rewrite notes; never mutates the caller's record.
 * @throws {ToolInputError} If more than one spelling supplies the update target, even if equal.
 * @complexity O(k) time and space for k top-level input keys; no I/O.
 */
function normalizeMenuUpdateInput(
  { input }: { input: Readonly<Record<string, unknown>> },
  _options: Record<string, never> = {},
): { input: Readonly<Record<string, unknown>>; notes: readonly string[] } {
  const aliases = Object.keys(input).filter((key) => key.replace(/[_-]/g, "").toLowerCase() === "menuid");
  const alias = aliases[0];
  if (alias === undefined) return { input, notes: [] };
  if (Object.hasOwn(input, "id") || aliases.length > 1) {
    throw new ToolInputError({ message: "Conflicting inputs for the menu target. Send only 'id', not multiple id/menuId spellings." });
  }
  const { [alias]: menuId, ...rest } = input;
  return { input: { ...rest, id: menuId }, notes: [`${alias}→id`] };
}

export function buildMenusRegistrations(routeDeps: MenusToolDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    menus_list_menus: async (ctx) => {
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.read" }, { entityType: "menu" });
      const menus = await routeDeps.menuRepo.list({ workspaceId: routeDeps.workspaceId });
      return { menus: menus.map(toMenuToolView) };
    },

    menus_get_menu: async (ctx) => {
      const menuId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "menuId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.read" }, { entityType: "menu", entityId: menuId });
      const menu = await routeDeps.menuRepo.findById({ workspaceId: routeDeps.workspaceId, id: menuId });
      if (!menu) throw new MenuNotFoundError({ message: `menu '${menuId}' was not found` });
      return { menu: toMenuToolView(menu) };
    },

    menus_create_menu: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.create" }, { entityType: "menu" });
      if (input.items !== undefined && !Array.isArray(input.items)) {
        throw new ToolInputError({ message: "'items' must be an array of nav items" });
      }
      const authoring = htmlAuthoring(input);
      await requireHtmlAuthoringPermission({ routeDeps, principalId: ctx.principal.id, authoring });
      return withSchemaOnRejection({ toolId: "menus_create_menu", catalog: CATALOG_BY_ID, isShapeRejection: ({ error }) => isMenusShapeRejection(error), fn: async () => {
        const { menu } = await createMenu({
          deps: menusDeps(routeDeps),
          input: {
            workspaceId: routeDeps.workspaceId,
            title: requireString({ input: input, key: "title" }),
            slug: requireString({ input: input, key: "slug" }),
            items: Array.isArray(input.items) ? (input.items as NavItemNode[]) : undefined,
            ...authoring,
          },
        });
        return { menu: toMenuToolView(menu) };
      } });
    },

    menus_update_menu_tree: async (ctx) => {
      const { input } = normalizeMenuUpdateInput({ input: requireInputRecord({ input: ctx.input }) });
      const menuId = requireString({ input: input, key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.update" }, { entityType: "menu", entityId: menuId });
      const authoring = htmlAuthoring(input);
      if (input.items === undefined && authoring.mode === undefined && authoring.html === undefined) {
        throw new Error("'items' (array), 'html' or 'mode' is required");
      }
      if (input.items !== undefined && !Array.isArray(input.items)) throw new Error("'items' must be an array of nav items");
      await requireHtmlAuthoringPermission({ routeDeps, principalId: ctx.principal.id, authoring, menuId });
      return withSchemaOnRejection({ toolId: "menus_update_menu_tree", catalog: CATALOG_BY_ID, isShapeRejection: ({ error }) => isMenusShapeRejection(error), fn: async () => {
        const { menu } = await updateMenuTree({
          deps: menusDeps(routeDeps),
          input: {
            workspaceId: routeDeps.workspaceId,
            id: menuId,
            expectedVersion: requireNumber({ input: input, key: "expectedVersion" }),
            title: typeof input.title === "string" ? input.title : undefined,
            slug: typeof input.slug === "string" ? input.slug : undefined,
            items: input.items as NavItemNode[] | undefined,
            ...authoring,
          },
        });
        return { menu: toMenuToolView(menu) };
      } });
    },

    menus_assign_location: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const menuId = requireString({ input: input, key: "menuId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.assign" }, { entityType: "menu", entityId: menuId });
      const { menu, binding, displacedMenu } = await assignLocation({
        deps: { ...menusDeps(routeDeps), bindingRepo: routeDeps.navLocationBindingRepo },
        input: { workspaceId: routeDeps.workspaceId, menuId, locationKey: requireString({ input: input, key: "locationKey" }) },
      });
      return {
        menu: toMenuToolView(menu),
        binding: { locationKey: binding.locationKey, menuId: binding.menuId },
        displacedMenu: displacedMenu ? toMenuToolView(displacedMenu) : null,
      };
    },
  };

  // No `unwiredToolIds`: Menus wires its ENTIRE catalog, same tripwire discipline as Forms.
  return buildDomainRegistrations({
    domain: "menus",
    catalogModule: "navigation/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    inputNormalizers: { menus_update_menu_tree: normalizeMenuUpdateInput },
    derivedRisk: menusDerivedRisk,
  });
}

/**
 * @file Core type definitions for the `navigation` library.
 *
 * Purpose:
 * Menus/nav are **navigation trees as editable content**. A menu is a generic
 * content entry (type `menu`); its ordered, nested item tree lives in the
 * entry's validated `bodyJson` as a `navigation`-namespaced block vocabulary.
 * Link targets that point at other content (entries, taxonomy terms) are `ref`
 * values so the write-chokepoint extracts them into the rebuildable
 * `entry_refs` index (where-used + safe-delete), exactly as the media library reuses it
 * for media. External URLs and named routes carry no ref.
 *
 * How it relates to the project:
 * - `core/ports.ts` supplies the shared primitives (`UUID`, `JsonObject`, …).
 * - `navigation/ports.ts` declares the one rule-of-two port this library adds
 *   (`NavLocationBindingRepoPort`) plus the typed-call resolver contract.
 * - The theme renderer consumes `ResolvedNav` (data only — no theme code
 *   resolves refs; the render-IR boundary).
 *
 * Architectural role:
 * INTERFACES + TYPES ONLY (no feature logic). This is the design-frozen shape
 * this library introduces; the entries repo, revisions, `entry_refs`, and the command
 * gateway are reused unchanged from the generic entries model.
 */
import type { ISODateTime, JsonObject, UUID } from "@jini-ai/core/primitives";

// ---------------------------------------------------------------------------
// Content-type identity
// ---------------------------------------------------------------------------

/**
 * `menu` ships as a **seeded content-type registry row**, like
 * `post`/`page`/`media`. Core may special-case it in admin UI/rendering, never
 * in storage. The extension-field owner namespace for menu-level fields
 * (`fields.ext.navigation.*`) is `navigation`.
 */
export const NAV_MENU_CONTENT_TYPE = "menu" as const;
export const NAV_FIELD_NAMESPACE = "navigation" as const;

/** Discriminator marking an entry's `bodyJson` as a navigation tree document. */
export const NAV_DOC_TYPE = "menu" as const;

// ---------------------------------------------------------------------------
// Link targets
// ---------------------------------------------------------------------------

/**
 * The v1 link-target kinds. `entryRef`/`termRef` are integrity-tracked (their
 * ids are extracted to `entry_refs`); `url`/`route` are validated-only.
 */
export type NavTargetKind = "entryRef" | "termRef" | "url" | "route";

/**
 * Reserved-but-rejected target kinds — the named deferred seams.
 * Recognized by the validator and **rejected with a clear "coming later" error**
 * until their resolver stage ships, so the discriminant never has to widen in a
 * breaking way. `dynamicQuery` needs a total/bounded expression
 * language; `content` needs a mega-menu block-embed resolver.
 */
export type ReservedNavTargetKind = "dynamicQuery" | "content";

/** A link to another content entry (page/post/media/…). Integrity-tracked. */
export interface NavEntryTarget {
  readonly kind: "entryRef";
  /** Optional content-type hint for editors; reference integrity and routing still use entryId. */
  readonly entryType?: string;
  /** Author's last known URL, retained for exports and routing misses. A known unavailable
   * entry must remain hidden; this snapshot never overrides an availability decision. */
  readonly lastKnownHref?: string;
  /** Target entry id. Extracted to `entry_refs` at the write chokepoint. */
  readonly entryId: UUID;
}

/** A link to a taxonomy term (category/tag archive). Integrity-tracked. */
export interface NavTermTarget {
  readonly kind: "termRef";
  /** Target term id. Extracted to `entry_refs` (target kind = term). */
  readonly termId: UUID;
  /** Taxonomy the term belongs to, for archive-route resolution. */
  readonly taxonomy: string;
}

/** An absolute or site-relative external URL. Validated, not ref-tracked. */
export interface NavUrlTarget {
  readonly kind: "url";
  /** Sanitized/validated at write time (scheme allowlist, no `javascript:`). */
  readonly href: string;
}

/** A named core route (e.g. `home`, `search`), resolved by the routing lib. */
export interface NavRouteTarget {
  readonly kind: "route";
  readonly route: string;
  /** Optional static params passed to the route resolver. */
  readonly params?: JsonObject | undefined;
}

/** v1 discriminated union of link targets. */
export type NavTarget = NavEntryTarget | NavTermTarget | NavUrlTarget | NavRouteTarget;

// ---------------------------------------------------------------------------
// The stored item tree (lives in entry `bodyJson`)
// ---------------------------------------------------------------------------

/**
 * Presentational attributes carried on an item, kept separate from identity and
 * target so the render model can pass them through without interpreting them.
 */
export interface NavItemAttrs {
  readonly openInNewTab?: boolean | undefined;
  /** `rel` tokens (e.g. `nofollow`), validated against an allowlist. */
  readonly rel?: string | undefined;
  /** Theme-facing CSS class hint. */
  readonly cssClass?: string | undefined;
  /** Optional description/subtitle (mega-menu-adjacent, cosmetic in v1). */
  readonly description?: string | undefined;
  /** Icon token resolved by the theme's icon set, if any. */
  readonly icon?: string | undefined;
}

/**
 * One node in the menu tree. **Ordering = array order** among siblings;
 * **nesting = `children`**. `id` is a **stable ULID minted on item creation and
 * preserved across edits/moves** (never regenerated on reorder) — the stable
 * identity `entry_refs` locators and per-item caches depend on (a discipline
 * discipline applied within the doc). The chokepoint validator enforces id
 * stability and bounded depth/breadth.
 */
export interface NavItemNode {
  readonly id: UUID;
  /** Editable display label. Falls back to the target's title when absent. */
  readonly label?: string | undefined;
  readonly target: NavTarget;
  readonly attrs?: NavItemAttrs | undefined;
  /** Child items (one level of nesting per depth). */
  readonly children?: readonly NavItemNode[] | undefined;
}

/**
 * The full navigation document stored in a menu entry's `bodyJson`. Shaped so it
 * satisfies `JsonObject` structurally (all fields are JSON-serializable), which
 * keeps it inside the storage contract and the serializable
 * ABI.
 */
export interface NavMenuDoc {
  readonly type: typeof NAV_DOC_TYPE;
  /** Doc-schema version, so the validator can migrate shapes later. */
  readonly version: number;
  readonly items: readonly NavItemNode[];
  /** What renders at the menu's marker; absent means `"items"`. See `menu-html.ts`. */
  readonly mode?: NavMenuMode | undefined;
  /** Author-written HTML for `"html"` mode, kept even while the menu renders its items. */
  readonly html?: string | undefined;
}

/** `"items"` renders the item tree; `"html"` renders the author's own markup (`menu-html.ts`). */
export type NavMenuMode = "items" | "html";

// ---------------------------------------------------------------------------
// The menu read model (a typed view over the generic entries row)
// ---------------------------------------------------------------------------

export type MenuStatus = "draft" | "published" | "trash";

/**
 * A typed read model over a `type='menu'` entries row (universal
 * columns) plus the parsed `bodyJson` tree and the `navigation`-namespaced
 * fields. This is a **projection**, not a new table — menus are entries.
 */
export interface NavMenuEntry {
  readonly id: UUID;
  readonly workspaceId: UUID;
  /** Stable machine handle, e.g. `primary-nav` (the entry `slug`). */
  readonly slug: string;
  /** Human menu name (the entry `title`). */
  readonly title: string;
  readonly status: MenuStatus;
  /** The parsed navigation tree (entry `bodyJson`). */
  readonly doc: NavMenuDoc;
  /**
   * Theme-location keys this menu is assigned to fill
   * (`fields.ext.navigation.locations`). Source of truth for assignment;
   * the binding index (below) is the derived, uniqueness-enforcing projection.
   */
  readonly locations: readonly string[];
  readonly updatedAt: ISODateTime;
  readonly version: number;
}

// ---------------------------------------------------------------------------
// Location binding index (derived, rebuildable — the one new core table)
// ---------------------------------------------------------------------------

/** A theme-registered location key (e.g. `primary`, `footer`, `social`). */
export type NavLocationKey = string;

/**
 * A row of the derived `nav_location_bindings` index.
 * **Derived + rebuildable** from `NavMenuEntry.locations` at the write
 * chokepoint (same species as `entry_refs`), NOT a source of truth
 * and NOT revision-generating. Its purpose is a single indexed location→menu
 * lookup at render time and a **`UNIQUE (workspace_id, location_key)`**
 * constraint that enforces *exactly one menu per location* — an invariant a
 * per-entry JSON field cannot express.
 */
export interface NavLocationBindingRow {
  readonly workspaceId: UUID;
  readonly locationKey: NavLocationKey;
  /** The menu entry currently bound to this location. */
  readonly menuId: UUID;
  /** When the binding was last (re)assigned; for audit/debug only. */
  readonly boundAt: ISODateTime;
}

/**
 * A theme/plugin-registered navigation location (registered via
 * `navigation.locations.register`). Registration is data; a menu may be bound to
 * an **unregistered** key so assignments survive a theme switch (fixes WP's
 * "lose your menus on theme change" sin).
 */
export interface NavLocationDescriptor {
  readonly key: NavLocationKey;
  /** Admin-facing label. */
  readonly label: string;
  /** Which theme/plugin registered it (attribution + orphan detection). */
  readonly registeredBy: string;
  readonly description?: string | undefined;
}

// ---------------------------------------------------------------------------
// The resolved render model (data handed to themes)
// ---------------------------------------------------------------------------

/**
 * A single item after resolution: target → concrete `href` + display `label` +
 * `isActive`/`isCurrent` computed against the current route. Refs are resolved
 * by core (routing/entries/taxonomy), never by theme code. Items whose target
 * has been trashed/deleted are resolved to `available: false` so the theme can
 * omit them rather than emit a dead link.
 */
export interface ResolvedNavItem {
  readonly id: UUID;
  readonly label: string;
  /** Fully-resolved href, or `null` when the target is unavailable. */
  readonly href: string | null;
  readonly available: boolean;
  /** True when this item's href matches the current route. */
  readonly isCurrent: boolean;
  /** True when this or a descendant is current (for open/expanded state). */
  readonly isActive: boolean;
  readonly attrs?: NavItemAttrs | undefined;
  readonly children: readonly ResolvedNavItem[];
}

/** A fully-resolved menu ready for a theme to render at a location. */
export interface ResolvedNav {
  readonly menuId: UUID;
  readonly locationKey: NavLocationKey;
  readonly title: string;
  readonly items: readonly ResolvedNavItem[];
}

/**
 * @file `RedirectMatcher` implementation (SPEC-009 REQ-07/19/20/22;
 * behavior.spec.md §1, §2, §4, §7).
 *
 * Purpose:
 * Pure, bounded, no-I/O matching of a request path against a set of redirect
 * rules: match-type precedence (`exact` > `prefix` (longest) > `wildcard`),
 * the priority/recency/id tie-break chain, and wildcard capture
 * interpolation. Also owns `validatePattern`, the write-time pattern safety
 * gate that hard-rejects `matchType: 'regex'` in v1 (REQ-22/INV-05).
 *
 * How it relates to the project:
 * `phase-handler.ts` (C-006) gathers phase-eligible candidate rules from
 * `RedirectRepoPort` (exact/prefix/dynamic lookups) into one array and hands
 * them to `match()`, which applies the FULL precedence + tie-break logic
 * itself — this keeps every precedence/tie-break rule in one pure,
 * exhaustively unit-testable place (matcher.test.ts), rather than splitting
 * it between the repo adapters and this file. `RedirectRepoPort.lookupExact`/
 * `lookupLongestPrefix`/`listDynamic` remain index-backed *retrieval*
 * optimizations for the real request-serving hot path; they do not need to
 * duplicate this file's tie-break logic since `match()` re-derives the
 * correct winner regardless of the input array's order (idempotent to
 * already-sorted input, matching behavior.spec.md §2.2's "never re-sort what
 * the repo returns" invariant for the already-optimal case).
 *
 * Architectural role: INTERNAL SEAM (not an ADR-006 port, see `ports.ts`'s
 * file header) — pure functions only, no I/O.
 */
import { sameRedirectPath } from "./path-key.js";
import type { RedirectMatcher } from "./ports.js";
import type { RedirectMatchType, RedirectRecord, RedirectRequest, RedirectResolution } from "./types.js";

const MIN_PATTERN_LENGTH = 1;
const MAX_PATTERN_LENGTH = 2048;

/** Precedence order, highest first — index doubles as the sort key. */
const PRECEDENCE_ORDER: Readonly<Record<RedirectMatchType, number>> = {
  exact: 0,
  prefix: 1,
  wildcard: 2,
  regex: 3, // never actually reachable — validatePattern always rejects it at write time.
};

export interface ValidatePatternRequired {
  matchType: RedirectMatchType;
  fromPattern: string;
}

/**
 * Write-time pattern safety gate (REQ-07/19/20/22). Total — never throws.
 *
 * @complexity O(1).
 */
export function validatePattern(
  required: ValidatePatternRequired,
  _optional: Record<string, never> = {},
): { ok: true } | { ok: false; reason: string } {
  const { matchType, fromPattern } = required;

  if (matchType === "regex") {
    return { ok: false, reason: "matchType 'regex' is not enabled in v1" };
  }

  const length = fromPattern.length;
  if (length < MIN_PATTERN_LENGTH || length > MAX_PATTERN_LENGTH) {
    return {
      ok: false,
      reason: `fromPattern must be ${MIN_PATTERN_LENGTH}-${MAX_PATTERN_LENGTH} characters (got ${length})`,
    };
  }

  if (!fromPattern.startsWith("/")) {
    return { ok: false, reason: "fromPattern must start with '/'" };
  }

  return { ok: true };
}

// ---------------------------------------------------------------------------
// Candidate matching per match type (internal)
// ---------------------------------------------------------------------------

interface CandidateMatch {
  rule: RedirectRecord;
  /** Fully-interpolated destination (captures/tail already applied). */
  location: string;
  /** Higher = more specific within its own match-type band (used only for the wildcard tie-break). */
  specificity: number;
}

// Each matcher below is reached only from `matchOne`'s switch case for its own `matchType`, so none
// re-checks the type (the switch is the single dispatch point).
function matchExact(rule: RedirectRecord, path: string): CandidateMatch | null {
  // Trailing slash and percent-encoding never decide a literal match (Bug A, see path-key.ts).
  if (!sameRedirectPath({ a: rule.fromPattern, b: path }, {})) return null;
  return { rule, location: rule.toTarget, specificity: rule.fromPattern.length };
}

function matchPrefix(rule: RedirectRecord, path: string): CandidateMatch | null {
  const pattern = rule.fromPattern;
  const isExactPrefix = path === pattern;
  const isNestedPrefix = path.startsWith(pattern.endsWith("/") ? pattern : `${pattern}/`);
  if (!isExactPrefix && !isNestedPrefix) return null;
  const tail = isExactPrefix ? "" : path.slice(pattern.length);
  return { rule, location: `${rule.toTarget}${tail}`, specificity: pattern.length };
}

/** Compile a `*`-glob wildcard pattern into an anchored, non-backtracking capture regex. */
function compileWildcard(pattern: string): RegExp {
  const escaped = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
  const withCaptures = escaped.replace(/\*/g, "([^/]+)");
  return new RegExp(`^${withCaptures}$`);
}

function interpolate(template: string, captures: string[]): string {
  return template.replace(/\$(\d+)/g, (whole, indexStr: string) => {
    const index = Number(indexStr) - 1;
    return index >= 0 && index < captures.length ? captures[index]! : whole;
  });
}

function matchWildcard(rule: RedirectRecord, path: string): CandidateMatch | null {
  const regex = compileWildcard(rule.fromPattern);
  const result = regex.exec(path);
  if (!result) return null;
  const captures = result.slice(1);
  return {
    rule,
    location: interpolate(rule.toTarget, captures),
    specificity: rule.fromPattern.length,
  };
}

function matchOne(rule: RedirectRecord, path: string): CandidateMatch | null {
  switch (rule.matchType) {
    case "exact":
      return matchExact(rule, path);
    case "prefix":
      return matchPrefix(rule, path);
    case "wildcard":
      return matchWildcard(rule, path);
    case "regex":
      // Deferred (ADR-033 §8) — never authored in v1 (validatePattern rejects it at write
      // time), so no live rule should ever carry this matchType. Defensive no-match.
      return null;
    default:
      return null;
  }
}

/**
 * Tie-break comparator (behavior.spec.md §2.1/§6.1): higher `priority` wins;
 * else more recent `updatedAt` (falling back to `createdAt`) wins; else the
 * lexicographically smaller `id` wins. Returns <0 if `a` should win over `b`.
 */
function compareTieBreak(a: CandidateMatch, b: CandidateMatch): number {
  if (a.rule.priority !== b.rule.priority) return b.rule.priority - a.rule.priority;
  const aRecency = a.rule.updatedAt || a.rule.createdAt;
  const bRecency = b.rule.updatedAt || b.rule.createdAt;
  if (aRecency !== bRecency) return aRecency > bRecency ? -1 : 1;
  return a.rule.id < b.rule.id ? -1 : a.rule.id > b.rule.id ? 1 : 0;
}

/** Within a precedence band, longest/most-specific `fromPattern` wins first, then the tie-break chain. */
function compareWithinBand(a: CandidateMatch, b: CandidateMatch): number {
  if (a.specificity !== b.specificity) return b.specificity - a.specificity;
  return compareTieBreak(a, b);
}

export interface MatchRequired {
  request: RedirectRequest;
  rules: RedirectRecord[];
}

/**
 * Resolve the highest-precedence, tie-broken match for `request.path` among
 * `rules` (behavior.spec.md §1.1, §2.1, §2.2, §6.1). Total — never throws.
 *
 * @complexity O(n) in `rules.length`.
 */
export const match: RedirectMatcher["match"] = (required: MatchRequired, _optional: Record<string, never> = {}): RedirectResolution => {
  const { request, rules } = required;

  const candidates: CandidateMatch[] = [];
  for (const rule of rules) {
    const candidate = matchOne(rule, request.path);
    if (candidate) candidates.push(candidate);
  }
  if (candidates.length === 0) return { matched: false };

  candidates.sort((a, b) => {
    const precedenceDelta = PRECEDENCE_ORDER[a.rule.matchType] - PRECEDENCE_ORDER[b.rule.matchType];
    if (precedenceDelta !== 0) return precedenceDelta;
    return compareWithinBand(a, b);
  });

  const winner = candidates[0]!;
  return {
    matched: true,
    redirectId: winner.rule.id,
    location: winner.location,
    statusCode: winner.rule.statusCode,
    matchType: winner.rule.matchType,
  };
};

export const redirectMatcher: RedirectMatcher = { match, validatePattern };

/**
 * @file The rule orderings both `RedirectRepoPort` adapters apply (`repo.ts` on SQL, `repo.memory.ts`
 * in memory). One module so the two adapters cannot drift: the shared contract suite
 * (`repo.contract.test.ts`) only checks the cases it seeds, while every comparator arm is pinned
 * here directly (`order.test.ts`).
 */
import type { RedirectRecord } from "./types.js";

/**
 * Shared tie-break between rules that match equally well: higher `priority` first, then the more
 * recent `updatedAt` (falling back to `createdAt` when `updatedAt` is empty), then `id` ascending.
 * Returns 0 only for the same id, as a sort comparator must.
 */
export function compareTieBreak({ a, b }: { a: RedirectRecord; b: RedirectRecord }, _optional: Record<string, never> = {}): number {
  if (a.priority !== b.priority) return b.priority - a.priority;
  const aRecency = a.updatedAt || a.createdAt;
  const bRecency = b.updatedAt || b.createdAt;
  if (aRecency !== bRecency) return aRecency > bRecency ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/** Longest pattern first, then the shared tie-break (`lookupLongestPrefix`, `listDynamic`). */
export function compareLongestFirst({ a, b }: { a: RedirectRecord; b: RedirectRecord }, _optional: Record<string, never> = {}): number {
  return b.fromPattern.length - a.fromPattern.length || compareTieBreak({ a, b }, {});
}

/**
 * `findByFromPattern`'s order among active rules sharing one `fromPattern`: an `exact` rule before
 * any other match type, then `id` ascending.
 */
export function compareSamePatternExactFirst({ a, b }: { a: RedirectRecord; b: RedirectRecord }, _optional: Record<string, never> = {}): number {
  return (a.matchType === "exact" ? 0 : 1) - (b.matchType === "exact" ? 0 : 1) || (a.id < b.id ? -1 : 1);
}

/**
 * @file Port + seam contracts for the `redirects` Tier-2 library (ADR-033).
 *
 * ADR-006 accounting (rule-of-two):
 * - `RedirectRepoPort` is a genuine port — it rides the ADR-015 seam with two
 *   adapters built now (in-memory for tests + Drizzle/SQLite for persistence),
 *   matching every other feature in `src/features/*`.
 * - `RedirectMatcher` and `RedirectHitSink` are declared here as ordinary
 *   INTERNAL SEAMS, not ADR-006 ports. Neither has a second adapter under
 *   construction today: the matcher's plausible-second is an edge/CDN compiler
 *   (emit an nginx `map` / Cloudflare ruleset), the hit sink's is an external
 *   analytics store — both real, neither built now. Per ADR-006 they stay
 *   ordinary code with a documented seam, promoted to a port the day the second
 *   adapter is real. They are typed as interfaces purely for testability.
 *
 * Architectural role:
 * INTERFACES ONLY — no feature logic.
 *
 * Grounding: ADR-006 (rule-of-two), ADR-015 (repo behind a port), ADR-009
 * (typed calls / outbox / hooks), ADR-022 (chokepoint writes record a revision
 * in the same tx; bounded matching = the totality/bounded-cost trust primitive),
 * ADR-021 (permission strings enforced by the calling gateway, not the repo).
 */
import type { ISODateTime, UUID } from "@jini-ai/core/primitives";
import type { RedirectLocationRefusalReason } from "./target-gate.js";
import type { DomainEvent } from "../core/index.js";
import type {
  ListRedirectsFilter,
  RedirectHitStats,
  RedirectRecord,
  RedirectRequest,
  RedirectResolution,
  RedirectRevision,
} from "./types.js";

/**
 * Persistence port for redirect rules + their revision ledger + tombstones.
 * The single write chokepoint (ADR-022 §4a): `save` MUST persist the record and
 * its {@link RedirectRevision} in one transaction; no other module writes the
 * `redirects` / `redirect_revisions` tables (CI import-graph canary, ADR-027
 * precedent).
 */
export interface RedirectRepoPort {
  findById(required: { workspaceId: UUID; id: UUID }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /** Index-backed O(1) exact-path lookup (active rules only). */
  lookupExact(required: {
    workspaceId: UUID;
    path: string;
    includeOverrideOnly: boolean;
  }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /** Longest-prefix match over active `prefix` rules (index/trie-backed). */
  lookupLongestPrefix(required: {
    workspaceId: UUID;
    path: string;
    includeOverrideOnly: boolean;
  }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /**
   * The bounded "dynamic" set: active `wildcard` + `regex` rules in evaluation
   * order (specificity → priority → recency). Returned capped; callers evaluate
   * them through {@link RedirectMatcher} only after exact/prefix miss.
   */
  listDynamic(required: {
    workspaceId: UUID;
    includeOverrideOnly: boolean;
    limit: number;
  }, optional?: Record<string, never>): Promise<RedirectRecord[]>;

  list(filter: ListRedirectsFilter, optional?: Record<string, never>): Promise<RedirectRecord[]>;

  /**
   * Resolve where an existing rule with the given `fromPattern` already points,
   * used at write time for cycle detection + chain collapsing (ADR-033 §6).
   */
  findByFromPattern(required: {
    workspaceId: UUID;
    fromPattern: string;
  }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /** Chokepoint write: upsert the record and append its revision in one tx. */
  save(required: { record: RedirectRecord; revision: RedirectRevision }, optional?: Record<string, never>): Promise<void>;

  /** Tombstone (soft-delete): flip status + append a tombstone revision in one tx. */
  tombstone(required: { workspaceId: UUID; id: UUID; revision: RedirectRevision }, optional?: Record<string, never>): Promise<void>;
}

/**
 * INTERNAL SEAM (not an ADR-006 port). Pure, bounded matching of a request
 * against the dynamic rule set. Implementations MUST be total and
 * bounded-cost — linear-time / RE2 semantics, an anchored pattern, and a
 * per-request evaluation cap — because this is the request-hot-path expression
 * evaluator ADR-022's amendment designates a trust-boundary primitive. No
 * backtracking regex engine may back this.
 */
export interface RedirectMatcher {
  /**
   * Return the first matching rule with captures interpolated into `location`,
   * or `{ matched: false }`. `rules` is the already-ordered, already-capped
   * dynamic set from {@link RedirectRepoPort.listDynamic}.
   */
  match(required: {
    request: RedirectRequest;
    rules: RedirectRecord[];
  }, optional?: Record<string, never>): RedirectResolution;

  /**
   * Compile-time validation of a single pattern (called at the write
   * chokepoint): rejects unbounded/backtracking constructs before a rule is
   * ever stored, so an unsafe pattern cannot reach the hot path.
   */
  validatePattern(required: {
    matchType: RedirectRecord["matchType"];
    fromPattern: string;
  }, optional?: Record<string, never>): { ok: true } | { ok: false; reason: string };
}

/**
 * INTERNAL SEAM (not an ADR-006 port). Best-effort, off-hot-path hit
 * aggregation. The resolver emits a {@link RedirectHitEvent} via the outbox
 * (ADR-009 async lane); an idempotent handler folds it into the
 * `redirect_hits` sidecar through this sink. A dropped increment loses a
 * statistic, never a redirect.
 */
export interface RedirectHitSink {
  record(required: { workspaceId: UUID; redirectId: UUID; at: ISODateTime }, optional?: Record<string, never>): Promise<void>;
  getStats(required: { workspaceId: UUID; redirectId: UUID }, optional?: Record<string, never>): Promise<RedirectHitStats | null>;
  listStats(required: { workspaceId: UUID }, optional?: Record<string, never>): Promise<RedirectHitStats[]>;
}

/**
 * Application service consulted by the routing resolution chain. It is invoked
 * twice per request lifecycle: `pre_content` (override rules only) and
 * `post_content` (the 404-fill pass). The exact registration contract with the
 * (not-yet-designed) `routing` library is OWED by the future routing ADR —
 * ADR-033 §4 specifies the redirects side and flags the seam as co-dependent.
 */
export interface RedirectResolver {
  resolve(request: RedirectRequest, optional?: Record<string, never>): Promise<RedirectResolution>;
}

/* ------------------------------------------------------------------ *
 * Events (ADR-009 lane 2 — outbox, async) + Hooks (lane 3 — sync)     *
 * ------------------------------------------------------------------ */

export interface RedirectMutatedEventPayload {
  workspaceId: UUID;
  redirectId: UUID;
