export interface ContentLookupPort {
  resolve(params: { contentType: string; contentId: string }): Promise<{ workspaceId: string; kind: string } | null>;
}

/** : the content_types registry's per-type taxonomy allow-list for Collections entries
 * (parallel to, never folded into, TAXONOMY_ALLOWED_CONTENT_TYPES — see the decision note).
 * `null` = not a live registry type (not applicable).
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */
export interface ContentTypeTaxonomyPolicyPort {
  taxonomiesFor(params: { contentType: string }): Promise<"all" | ReadonlySet<string> | null>;
}

/** The hardcoded post/page taxonomy allow-list (permanent, see
 * `docs/decisions/taxonomy-content-type-allow-list.md`) — every taxonomy is applicable to
 * `post`/`page` content. This set is never grown to admit a Collection's content-type key; a
 * Collection entry instead becomes eligible through {@link ContentTypeTaxonomyPolicyPort} above,
 * an intentionally parallel (not layered) per-content-type policy carried by a host's own
 * `content_types` registry. */
export const TAXONOMY_ALLOWED_CONTENT_TYPES: ReadonlySet<string> = new Set(["post", "page"]);

export function isContentTypeOnAllowList(requiredArgs: { contentType: string }, optionalArgs: Record<string, never> = {}): boolean {
  const { contentType } = requiredArgs;
  return TAXONOMY_ALLOWED_CONTENT_TYPES.has(contentType);
}

export interface TaxonomyRevisionRow {
  taxonomyId: string;
  /** `"delete"` added for `deleteTerm`/`deleteTaxonomy` below — unlike `mergeTerm`'s reuse of
   * `"deprecate"` (that ceremony's own header explains why widening this union was out of its
   * scope), a delete has no honest fit among the other four ops, so this widens the union rather
   * than overloading an existing member. */
  op: "create" | "rename" | "reparent" | "deprecate" | "delete" | "import";
  previousState: Record<string, unknown> | null;
  actorId: string;
  recordedAt: string;
}

export interface TaxonomyRevisionRepoPort {
  insert(row: TaxonomyRevisionRow): Promise<unknown>;
}


export interface WriteServiceDeps {
  authorize: AuthorizeFn;
  clock: Clock;
  idGen: IdGenerator;
  taxonomies: TaxonomyRepoPort;
  terms: TermRepoPort;
  entryTerms: EntryTermRepoPort;
  revisions: TaxonomyRevisionRepoPort;
  /** `core/gated-mutations.stampWatermark`-shaped, injected — same-transaction stamp per mutation.
   * May be sync (SQLite) or async (PGlite/Postgres); every call site awaits it, so an async stamp
   * finishes, and its failure fails the write, before the mutation returns. */
  stampWatermark: (required: Record<string, never>, optional?: { tx?: unknown }) => Promise<void> | void;
  outbox: { enqueue: ({ event }: { event: unknown }) => Promise<void> };
  /** The caller's own workspace — `validateContentJoin`'s `callerWorkspaceId` (Finding 1 fix). */
  workspaceId: string;
  /** Resolves a `(contentType, contentId)` pair's real workspace/kind for `assignTerms`'s
   * content-join validation (Finding 1 fix). */
  contentLookup: ContentLookupPort;
  /** Per-content-type taxonomy allow-list for Collections entries (A1, taxonomy plan). Optional so
   * other hosts (and every existing test double) don't break — a host that omits it simply never
   * makes a non-post/page `contentType` resolvable, matching today's behavior exactly. */
  contentTypeTaxonomyPolicy?: ContentTypeTaxonomyPolicyPort;
}

export class TaxonomyRecordNotFoundError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "TaxonomyRecordNotFoundError";
  }
}

export class TermRecordNotFoundError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "TermRecordNotFoundError";
  }
}

/** Finding 1 fix — the target of an `assignTerms` call does not resolve to any real content row. */
export class ContentRecordNotFoundError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "ContentRecordNotFoundError";
  }
}

/**
 * J1 (plan-publish-all-types-2026-09-25.md) — `importTaxonomy`/`importTerm`'s optimistic-concurrency
 * rejection. Neither `Taxonomy` nor `Term` had a version-checked write before this slice
 * (`createTaxonomy`/`createTerm` always insert a fresh row; `renameTerm` doesn't check a caller-
 * supplied version either), so this is a new class rather than a reused one — `content-types`' and
 * `entries`' own `VersionConflictError`s are each that package's own, per this file's header's
 * "catch the one it actually called into" rule.
 */
export class TaxonomyVersionConflictError extends Error {
  constructor(requiredArgs: { message: string }, optionalArgs: Record<string, never> = {}) {
    const { message } = requiredArgs;
    super(message);
    this.name = "TaxonomyVersionConflictError";
  }
}

/** `admin.taxonomy.manage` (the flat-string permission convention) — must run before any other
 * side effect of every write-service export in this file. */
async function authorizeTaxonomyManage(deps: WriteServiceDeps, principalId: string): Promise<void> {
  const result = await deps.authorize({ principalId, permission: "admin.taxonomy.manage" });
  if (!result.allowed) {
    throw new ForbiddenError({
      message: `principal '${principalId}' is not authorized for 'admin.taxonomy.manage' (${result.reason})`,
      permission: "admin.taxonomy.manage",
      reason: result.reason,
    });
  }
}

export interface CreateTaxonomyRequired {
  deps: WriteServiceDeps;
  principalId: string;
  name: string;
  hierarchical: boolean;
}

/** Creates a taxonomy row (hierarchical=true -> "category"-shaped, false -> "tag"-shaped — same
 * shared table). Ordinary mutation, no plan()/confirmation ceremony. */
export async function createTaxonomy(
  required: CreateTaxonomyRequired,
  _optional: Record<string, never> = {}
): Promise<Taxonomy> {
  const { deps, principalId, name, hierarchical } = required;
  await authorizeTaxonomyManage(deps, principalId);

  const now = kernelNowIso({ clock: deps.clock });
  const taxonomy: Taxonomy = {
    id: deps.idGen.newId(),
    name,
    hierarchical,
    status: "active",
    updatedAt: now,
    version: 1,
  };

  await deps.taxonomies.insert(taxonomy);
  await deps.revisions.insert({
    taxonomyId: taxonomy.id,
    op: "create",
    previousState: null,
    actorId: principalId,
    recordedAt: now,
  });
  await deps.stampWatermark({});
  await deps.outbox.enqueue({ event: { name: "taxonomy.created", taxonomyId: taxonomy.id, actorId: principalId, occurredAt: now } });

  return taxonomy;
}

/** The owning-taxonomy lookup `createTerm`/`importTerm` both run before touching any term. */
async function requireTaxonomy(required: { taxonomies: TaxonomyRepoPort; taxonomyId: string }): Promise<{ id: string; hierarchical: boolean }> {
  const { taxonomies, taxonomyId } = required;
  const taxonomy = await taxonomies.findById({ id: taxonomyId });
  if (!taxonomy) {
    throw new TaxonomyRecordNotFoundError({ message: `taxonomy '${taxonomyId}' was not found` });
  }
  return taxonomy;
}

/** `validateHierarchyAssignment`'s `resolvedParent` input: `"not-applicable"` when no parent was
 * requested, `null` when the requested parent does not exist, else its id + taxonomy. */
async function resolveCandidateParent(required: {
  terms: TermRepoPort;
  candidateParentId: string | null;
}): Promise<{ id: string; taxonomyId: string } | null | "not-applicable"> {
  const { terms, candidateParentId } = required;
  if (candidateParentId === null) return "not-applicable";
  const parentTerm = await terms.findById({ id: candidateParentId });
  return parentTerm ? { id: parentTerm.id, taxonomyId: parentTerm.taxonomyId } : null;
}

export interface CreateTermRequired {
  deps: WriteServiceDeps;
  principalId: string;
  taxonomyId: string;
  name: string;
}

export interface CreateTermOptional {
  parentId?: string | null | undefined;
}

/** — validates `parentId` via `validateHierarchyAssignment` before writing. A
 * freshly-created term has no descendants yet, so it structurally cannot be a cycle source; the
 * cycle check is therefore always a no-op (` => false`) here, unlike a reparent of an existing
 * term (not yet built — no certified test in this slice exercises it).
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */
export async function createTerm(
  required: CreateTermRequired,
  optional: CreateTermOptional = {}
): Promise<Term> {
  const { deps, principalId, taxonomyId, name } = required;
  const { parentId } = optional;
  await authorizeTaxonomyManage(deps, principalId);

  const taxonomy = await requireTaxonomy({ taxonomies: deps.taxonomies, taxonomyId });

  const candidateParentId = parentId ?? null;
  const resolvedParent = await resolveCandidateParent({ terms: deps.terms, candidateParentId });

  validateHierarchyAssignment({
    childTaxonomyId: taxonomyId,
    taxonomyIsHierarchical: taxonomy.hierarchical,
    candidateParentId,
    resolvedParent,
    wouldCreateCycle: () => false,
    termId: "__new__",
  });

  const now = kernelNowIso({ clock: deps.clock });
  const term: Term = {
    id: deps.idGen.newId(),
    taxonomyId,
    parentId: candidateParentId,
    name,
    status: "active",
    updatedAt: now,
    version: 1,
  };

  await deps.terms.insert(term);
  await deps.revisions.insert({ taxonomyId, op: "create", previousState: null, actorId: principalId, recordedAt: now });
  await deps.stampWatermark({});
  await deps.outbox.enqueue({ event: { name: "taxonomy.term_created", termId: term.id, actorId: principalId, occurredAt: now } });

  return term;
}

/**
 * Additive capability beyond the certified `TaxonomyRepoPort` — `findById`'s narrow return
 * (`{id, hierarchical, allowList?}`) doesn't carry `version`/`name`/`status`/`updatedAt`, which
 * `importTaxonomy`'s CAS check and update-in-place both need, and `insert`-only leaves no way to
 * write an existing row back. Same beyond-the-certified-port precedent as `DeletableTaxonomyRepoPort`.
 */
export interface ImportableTaxonomyRepoPort {
  findByIdFull({ id }: { id: string }): Promise<Taxonomy | null>;
  update(row: Taxonomy): Promise<unknown>;
}

export interface ImportTaxonomyRequired {
  deps: WriteServiceDeps & { taxonomies: TaxonomyRepoPort & ImportableTaxonomyRepoPort };
  principalId: string;
  /** The source's own id, preserved verbatim — unlike `createTaxonomy`, which always mints a fresh
   * one. Anything referencing this taxonomy by id (its member terms) needs it to survive a publish
   * round trip unchanged. */
  id: string;
  name: string;
  hierarchical: boolean;
  /** Same three-way CAS contract as `importEntry`'s `expectedVersion`: `undefined` means "this id
   * must not already exist" (import-as-create); a number means "a row at exactly this version must
   * exist" (import-as-update). Either mismatch is a `TaxonomyVersionConflictError`, never a silent
   * overwrite or a silent no-op. */
  expectedVersion: number | undefined;
}

/**
 * `importTaxonomy`/`importTerm`'s shared three-way CAS check (see
 * `ImportTaxonomyRequired.expectedVersion`): `undefined` requires that no row exists yet; a number
 * requires a row at exactly that version. Either mismatch is a `TaxonomyVersionConflictError`.
 */
function assertImportVersion(required: {
  entity: "taxonomy" | "term";
  id: string;
  expectedVersion: number | undefined;
  existing: { version: number } | null;
}): void {
  const { entity, id, expectedVersion, existing } = required;
  if (expectedVersion === undefined) {
    if (existing) {
      throw new TaxonomyVersionConflictError({ message: `${entity} '${id}' already exists, but no expectedVersion was supplied for import` });
    }
    return;
  }
  if (!existing) {
    throw new TaxonomyVersionConflictError({ message: `expected version ${expectedVersion} for ${entity} '${id}', but no such ${entity} exists` });
  }
  if (existing.version !== expectedVersion) {
    throw new TaxonomyVersionConflictError({ message: `expected version ${expectedVersion} for ${entity} '${id}', found ${existing.version}` });
  }
}

/**
 * Slice J1 — the publish-content import chokepoint for `taxonomies`. Address (name) uniqueness is
 * deliberately not checked here: the publish factory's own `address` precheck (F1's
 * `config.address`) owns that refusal before this is ever called, mirroring `importEntry`'s
 * identical split from slug-uniqueness.
 *
 * @complexity O(1) — one id lookup, one insert-or-update, one revision append, all outside a
 * transaction (this package has no SQLite adapter to open one against yet — see `repo.memory.ts`'s
 * header).
 */
export async function importTaxonomy(
  required: ImportTaxonomyRequired,
  _optional: Record<string, never> = {}
): Promise<Taxonomy> {
  const { deps, principalId, id, name, hierarchical, expectedVersion } = required;
  await authorizeTaxonomyManage(deps, principalId);

  const existing = await deps.taxonomies.findByIdFull({ id: id });
  assertImportVersion({ entity: "taxonomy", id, expectedVersion, existing });

  const now = kernelNowIso({ clock: deps.clock });
  const taxonomy: Taxonomy = {
    id,
    name,
    hierarchical,
    status: "active",
    updatedAt: now,
    version: existing ? existing.version + 1 : 1,
  };

  if (existing) {
    await deps.taxonomies.update(taxonomy);
  } else {
    await deps.taxonomies.insert(taxonomy);
  }
  await deps.revisions.insert({
    taxonomyId: taxonomy.id,
    op: "import",
    previousState: existing ? { name: existing.name, hierarchical: existing.hierarchical } : null,
    actorId: principalId,
    recordedAt: now,
  });
  await deps.stampWatermark({});
  await deps.outbox.enqueue({ event: { name: "taxonomy.imported", taxonomyId: taxonomy.id, actorId: principalId, occurredAt: now } });

  return taxonomy;
}

/**
 * Additive capability beyond the certified `TermRepoPort` — `findById`'s narrow return
 * (`{id, taxonomyId, name?}`) doesn't carry `version`, which `importTerm`'s CAS check needs.
 * `TermRepoPort` already has `update`, unlike taxonomies, so no additive `update` is needed here.
 */
export interface ImportableTermRepoPort {
  findByIdFull({ id }: { id: string }): Promise<Term | null>;
}

/**
 * Loads `startId`'s ancestor chain (`termId -> parentId`, `startId` included) so the synchronous,
 * certified `wouldCreateCycle` walk can run over the destination's REAL tree. Stops at a root, a
 * missing row, or an already-seen id — the last bounds the loop against pre-existing malformed
 * parent data, mirroring `wouldCreateCycle`'s own `visited` guard.
 *
 * @complexity O(d) repo reads for a chain of depth `d`.
 */
async function loadAncestorChain(terms: ImportableTermRepoPort, startId: string): Promise<Map<string, string | null>> {
  const chain = new Map<string, string | null>();
  let current: string | null = startId;
  while (current !== null && !chain.has(current)) {
    const parentId: string | null = (await terms.findByIdFull({ id: current }))?.parentId ?? null;
    chain.set(current, parentId);
    current = parentId;
  }
  return chain;
}

export interface ImportTermRequired {
  deps: WriteServiceDeps & { terms: TermRepoPort & ImportableTermRepoPort };
  principalId: string;
  /** The source's own id, preserved verbatim — unlike `createTerm`, which always mints a fresh one. */
  id: string;
  taxonomyId: string;
  name: string;
  /** Same three-way CAS contract as `importTaxonomy.expectedVersion`. */
  expectedVersion: number | undefined;
}

export interface ImportTermOptional {
  parentId?: string | null | undefined;
}

/**
 * Slice J1 — the publish-content import chokepoint for `terms`. Address (name within
 * `(taxonomyId, parentId)`) uniqueness is the publish factory's own precheck, not this function's
 * job — same split as `importTaxonomy`/`importEntry`.
 *
 * Unlike `createTerm`, an import can MOVE an existing term (an import-as-update with a new
 * `parentId`), so the destination's real ancestor chain is loaded first (`loadAncestorChain`) and
 * handed to the certified `wouldCreateCycle` walk — a publish must never write a parent loop into
 * live taxonomy, where every tree walk over it would spin forever.
 *
 * @complexity O(d) — one taxonomy lookup, one id lookup, one optional parent lookup, `d` ancestor
 * lookups (the candidate parent's depth), one insert-or-update, one revision append.
 */
export async function importTerm(
  required: ImportTermRequired,
  optional: ImportTermOptional = {}
): Promise<Term> {
  const { deps, principalId, id, taxonomyId, name, expectedVersion } = required;
  const { parentId } = optional;
  await authorizeTaxonomyManage(deps, principalId);

  const taxonomy = await requireTaxonomy({ taxonomies: deps.taxonomies, taxonomyId });

  const existing = await deps.terms.findByIdFull({ id: id });
  assertImportVersion({ entity: "term", id, expectedVersion, existing });
  // A cross-taxonomy move would leave the term's children parented across taxonomies.
  // (Only reachable with a matched `expectedVersion`: an `undefined` one over an existing row has
  // already been refused above.)
  if (existing && existing.taxonomyId !== taxonomyId) {
    throw new TaxonomyVersionConflictError({ message: `term '${id}' belongs to taxonomy '${existing.taxonomyId}', not '${taxonomyId}'; an import cannot move a term between taxonomies` });
  }

  const candidateParentId = parentId ?? null;
  await validateImportedTermParent({ terms: deps.terms, taxonomyId, taxonomyIsHierarchical: taxonomy.hierarchical, termId: id, candidateParentId, isExistingTerm: existing !== null });

  return writeImportedTerm({ deps, principalId, existing, term: { id, taxonomyId, parentId: candidateParentId, name } });
}

/**
 * `importTerm`'s hierarchy check: resolves the candidate parent and loads its REAL ancestor chain
 * (`loadAncestorChain`) so the certified `wouldCreateCycle` walk sees the destination's actual
 * tree — an import-as-update can move an existing term, unlike `createTerm`.
 */
async function validateImportedTermParent(required: {
  terms: TermRepoPort & ImportableTermRepoPort;
  taxonomyId: string;
  taxonomyIsHierarchical: boolean;
  termId: string;
  candidateParentId: string | null;
  isExistingTerm: boolean;
}): Promise<void> {
  const { terms, taxonomyId, taxonomyIsHierarchical, termId, candidateParentId, isExistingTerm } = required;
  const resolvedParent = await resolveCandidateParent({ terms, candidateParentId });
  const ancestors = candidateParentId === null ? new Map<string, string | null>() : await loadAncestorChain(terms, candidateParentId);

  validateHierarchyAssignment({
    childTaxonomyId: taxonomyId,
    taxonomyIsHierarchical,
    candidateParentId,
    resolvedParent,
    wouldCreateCycle: ({ candidateParentId }) => wouldCreateCycle({ termId, candidateParentId, tree: { getParentId: ({ termId }) => ancestors.get(termId) ?? null } }),
    termId: isExistingTerm ? termId : "__new__",
  });
}

/** `importTerm`'s write half: insert-or-update at the next version, one `"import"` revision
 * carrying the pre-import name/parentId (or `null` on a create), watermark, outbox. */
async function writeImportedTerm(required: {
  deps: ImportTermRequired["deps"];
  principalId: string;
  existing: Term | null;
  term: { id: string; taxonomyId: string; parentId: string | null; name: string };
}): Promise<Term> {
  const { deps, principalId, existing } = required;
  const { id, taxonomyId, parentId, name } = required.term;
  const now = kernelNowIso({ clock: deps.clock });
  const term: Term = {
    id,
    taxonomyId,
    parentId,
    name,
    status: "active",
    updatedAt: now,
    version: existing ? existing.version + 1 : 1,
  };

  if (existing) {
    await deps.terms.update(term);
  } else {
    await deps.terms.insert(term);
  }
  await deps.revisions.insert({
    taxonomyId,
    op: "import",
    previousState: existing ? { name: existing.name, parentId: existing.parentId } : null,
    actorId: principalId,
    recordedAt: now,
  });
  await deps.stampWatermark({});
  await deps.outbox.enqueue({ event: { name: "taxonomy.term_imported", termId: term.id, actorId: principalId, occurredAt: now } });

  return term;
}

export interface RenameTermRequired {
  deps: WriteServiceDeps & {
    /** Required shared transaction. All repos, the watermark and outbox
     * must share the store/connection opened by this port. */
    transaction: TransactionalRepoPort["transaction"];
  };
  principalId: string;
  termId: string;
  newName: string;
}

/** — same-tx rename + revision (carrying the pre-rename state) +
 * watermark + outbox. `authorize` runs before the term lookup, so a denied caller produces zero
 * side effects of any kind. A missing transaction capability fails closed before any lookup
 * or write; a caller must supply a real shared transaction for durable atomicity.
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */
export async function renameTerm(
  required: RenameTermRequired,
  _optional: Record<string, never> = {}
): Promise<Term> {
  const { deps, principalId, termId, newName } = required;
  await authorizeTaxonomyManage(deps, principalId);

  // The narrow taxonomy repo stays independent; the host binds the shared transaction explicitly.
  const transaction = deps.transaction;
  if (!transaction) throw new Error("term rename requires a transaction port");
  return transaction({ fn: async () => {
    const current = await deps.terms.findById({ id: termId });
    if (!current) {
      throw new TermRecordNotFoundError({ message: `term '${termId}' was not found` });
    }

    const now = kernelNowIso({ clock: deps.clock });
    const updated: Term = {
      id: current.id,
      taxonomyId: current.taxonomyId,
      parentId: (current as { parentId?: string | null }).parentId ?? null,
      name: newName,
      status: (current as { status?: string }).status ?? "active",
      updatedAt: now,
      version: ((current as { version?: number }).version ?? 1) + 1,
    };

    await deps.terms.update(updated);
    await deps.revisions.insert({
      taxonomyId: current.taxonomyId,
      op: "rename",
      previousState: { name: current.name },
      actorId: principalId,
      recordedAt: now,
    });
    await deps.stampWatermark({});
    await deps.outbox.enqueue({ event: { name: "taxonomy.term_renamed", termId, actorId: principalId, occurredAt: now } });

    return updated;
  } });
}

export interface AssignTermsRequired {
  deps: WriteServiceDeps;
  principalId: string;
  contentType: string;
  contentId: string;
  termIds: string[];
}

/**
 * A1 (taxonomy plan) — shared by `assignTerms` and `unassignTerms`: resolves whether
 * `(contentType, contentId)` is a real, eligible target and validates every `termId` against it,
 * BEFORE either caller writes anything. Extracted from `assignTerms` verbatim (same order, same
 * errors) so `unassignTerms` inherits the exact same content-join guarantees rather than a
 * re-derived copy that could drift.
 *
 * `post`/`page` keep today's behavior exactly: `isPostOrPage` short-circuits before
 * `contentTypeTaxonomyPolicy` is ever consulted. A non-post/page `contentType` is
 * resolvable only when a policy is wired AND that policy doesn't return `null` (not applicable) —
 * an unknown `contentType` (no policy, or a policy returning `null`) stays unresolvable, so it
 * still fails at `validateContentJoin`'s allow-list check (`TaxonomyNotApplicableError`), not a
 * `ContentRecordNotFoundError` — this is what keeps `"product"` a 400, not a 404.
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */
async function validateAssignmentTarget(required: {
  deps: WriteServiceDeps;
  contentType: string;
  contentId: string;
  termIds: string[];
}): Promise<void> {
  const { deps, contentType, contentId, termIds } = required;
  const { isPostOrPage, policy } = await resolveTaxonomyPolicy({ deps, contentType });
  const content = await resolveAssignmentContent({ deps, contentType, contentId, isResolvable: isPostOrPage || policy !== null });

  for (const termId of termIds) {
    const term = await deps.terms.findById({ id: termId });
    if (!term) {
      throw new TermRecordNotFoundError({ message: `term '${termId}' was not found` });
    }
    validateContentJoin({
      taxonomyId: term.taxonomyId,
      isOnAllowList: isTaxonomyAllowedForTarget({ isPostOrPage, policy, taxonomyId: term.taxonomyId }),
      callerWorkspaceId: deps.workspaceId,
      // `SqliteTermRepo`/`SqliteEntryTermRepo` are workspace-BOUND at construction (single
      // workspace per content.db) — a term/content row that resolves via those adapters at all
      // is, by construction, already in the caller's own workspace. See this file's header.
      resolvedTermWorkspaceId: deps.workspaceId,
      resolvedContentWorkspaceId: content?.workspaceId ?? deps.workspaceId,
      suppliedContentType: contentType,
      resolvedContentKind: content?.kind ?? contentType,
    });
  }
}

/** `post`/`page` short-circuit before `contentTypeTaxonomyPolicy` is ever consulted; any other
 * `contentType` gets the wired policy's answer, or `null` (not applicable) when none is wired. */
async function resolveTaxonomyPolicy(required: {
  deps: WriteServiceDeps;
  contentType: string;
}): Promise<{ isPostOrPage: boolean; policy: "all" | ReadonlySet<string> | null }> {
  const { deps, contentType } = required;
  const isPostOrPage = isContentTypeOnAllowList({ contentType: contentType });
  if (isPostOrPage || !deps.contentTypeTaxonomyPolicy) return { isPostOrPage, policy: null };
  return { isPostOrPage, policy: await deps.contentTypeTaxonomyPolicy.taxonomiesFor({ contentType }) };
}

/** Resolves the assignment target once per call. An unresolvable `contentType` is never looked up
 * (`null`) so it fails later at the allow-list check, not here; a resolvable one must exist. */
async function resolveAssignmentContent(required: {
  deps: WriteServiceDeps;
  contentType: string;
  contentId: string;
  isResolvable: boolean;
}): Promise<{ workspaceId: string; kind: string } | null> {
  const { deps, contentType, contentId, isResolvable } = required;
  if (!isResolvable) return null;
  const content = await deps.contentLookup.resolve({ contentType, contentId });
  if (!content) {
    throw new ContentRecordNotFoundError({ message: `content '${contentType}:${contentId}' was not found` });
  }
  return content;
}

/** Whether a term's taxonomy is applicable to the target: always for `post`/`page`, else per the
 * policy (`"all"`, or membership in its Set). */
function isTaxonomyAllowedForTarget(required: {
  isPostOrPage: boolean;
  policy: "all" | ReadonlySet<string> | null;
  taxonomyId: string;
}): boolean {
  const { isPostOrPage, policy, taxonomyId } = required;
  return isPostOrPage || policy === "all" || (policy instanceof Set && policy.has(taxonomyId));
}

/** — upserts every `entry_terms` row (idempotent on-conflict per
 * `entry_terms_unique`), then stamps the watermark and enqueues the outbox event exactly
 * ONCE per call regardless of `termIds.length` — never once per term. Never produces a
 * `taxonomy_revisions` row (see this file's header for the disclosed narrowing this implements).
 *
 * Finding 1 fix (TM-adr041-043-044-045-audit-001): every `termId` is validated via
 * `validateContentJoin` (allow-list -> workspace -> lens, `validation-chain.ts`'s fixed order)
 * BEFORE any `entry_terms` row is written — every termId must resolve to a real term, and the
 * target content must resolve to a real row whose kind matches the caller-supplied `contentType`.
 * Validation runs for ALL termIds before ANY write, so a failure partway through never leaves a
 * partial assignment. Content is resolved once per call (not once per term) since every term in
 * one call shares the same `(contentType, contentId)` target.
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */
export async function assignTerms(
  required: AssignTermsRequired,
  _optional: Record<string, never> = {}
): Promise<void> {
  const { deps, principalId, contentType, contentId, termIds } = required;
  await authorizeTaxonomyManage(deps, principalId);

  await validateAssignmentTarget({ deps, contentType, contentId, termIds });

  const now = kernelNowIso({ clock: deps.clock });
  for (const termId of termIds) {
    await deps.entryTerms.upsert({ contentType, contentId, termId, addedAt: now });
  }

  await deps.stampWatermark({});
  await deps.outbox.enqueue({ event: {
    name: "taxonomy.terms_assigned",
    contentType,
    contentId,
    termIds,
    actorId: principalId,
    occurredAt: now,
  } });
}

/** A2 (taxonomy plan) — the removal half of `assignTerms`. `remove()` lives on an additive port
 * (`UnassignableEntryTermRepoPort`) rather than widening the certified `EntryTermRepoPort`, the
 * same precedent `AssignmentCountEntryTermRepoPort` already set for `deleteTerm`/`deleteTaxonomy`. */
export interface UnassignableEntryTermRepoPort {
  remove(row: { contentType: string; contentId: string; termId: string }): Promise<number>;
}

export interface UnassignTermsRequired {
  deps: Omit<WriteServiceDeps, "entryTerms"> & { entryTerms: EntryTermRepoPort & UnassignableEntryTermRepoPort };
  principalId: string;
  contentType: string;
  contentId: string;
  termIds: string[];
}

/** — spec debt this codebase never built (the spec
 * always named "assign/unassign tools"; only `assignTerms` shipped). Same
 * authorize -> validateAssignmentTarget -> write -> stamp -> outbox chokepoint as `assignTerms`,
 * and — like `assignTerms` — never produces a `taxonomy_revisions` row ( disclosed
 * narrowing applies equally to removal). Idempotent: unassigning a row that isn't there is a no-op,
 * not an error. Only removed ids are returned, stamped, and emitted; an entirely absent set is a no-op. Chosen over
 * a "set terms" replace call — see the taxonomy plan's "What the docs settle" #3 for why replace
 * risks silently erasing a concurrent assignment.
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */
export async function unassignTerms(
  required: UnassignTermsRequired,
  _optional: Record<string, never> = {}
): Promise<{ removedTermIds: string[] }> {
  const { deps, principalId, contentType, contentId, termIds } = required;
  await authorizeTaxonomyManage(deps, principalId);

  await validateAssignmentTarget({ deps, contentType, contentId, termIds });

  const removedTermIds: string[] = [];
  for (const termId of termIds) {
    if (await deps.entryTerms.remove({ contentType, contentId, termId }) > 0) removedTermIds.push(termId);
  }
  if (removedTermIds.length === 0) return { removedTermIds };

  const now = kernelNowIso({ clock: deps.clock });
  await deps.stampWatermark({});
  await deps.outbox.enqueue({ event: {
    name: "taxonomy.terms_unassigned",
    contentType,
    contentId,
    termIds: removedTermIds,
    actorId: principalId,
    occurredAt: now,
  } });
  return { removedTermIds };
}

export interface EntryTermsCleanupPort {
  deleteByContent(params: { workspaceId: string; contentType: string; contentId: string }): Promise<number>;
}

export interface OnContentDeletedRequired {
  event: { workspaceId: string; contentType: string; contentId: string };
  entryTerms: EntryTermsCleanupPort;
}

/** Content-deletion event subscriber. Best-effort (a missed event leaves an orphaned
 * `entry_terms` row that is inert on read; a periodic/boot reconciliation sweep — modeled by
 * re-invoking this same function for the orphan — is the backstop, never a hard failure). A
 * no-op for content with no
 * assigned terms, never an error. Repository failures are warnings through the optional
 * logger port; logger failure also cannot turn cleanup into a hard failure. Hosts should
 * wire the logger for diagnostics; legacy callers without it remain silent. */
export async function onContentDeleted(
  required: OnContentDeletedRequired,
  optional: { logger?: {
    warn(required: { message: string; error: unknown; event: OnContentDeletedRequired["event"] }): void | Promise<void>;
  } } = {}
): Promise<void> {
  const { event, entryTerms } = required;
  try {
    await entryTerms.deleteByContent({
      workspaceId: event.workspaceId,
      contentType: event.contentType,
      contentId: event.contentId,
    });
  } catch (error) {
    try {
      await optional.logger?.warn({ message: "content-deletion taxonomy cleanup failed", error, event });
    } catch {
      // Cleanup is best effort even when its diagnostic sink is unavailable.
    }
  }
}

/**
 * Additive capabilities beyond the certified `TaxonomyRepoPort`/`TermRepoPort`/`EntryTermRepoPort`
 * — same beyond-the-certified-port precedent `MergeableEntryTermRepoPort` established in this
 * package's consuming host (`gated-hooks.ts`'s `buildMergeTermHooks`) for `mergeTerm`, applied
 * here for the ordinary (non-gated) `deleteTerm`/`deleteTaxonomy` mutations below. Implemented on
 * both `InMemory*Repo` (`repo.memory.ts`) and a host's own SQLite adapters (this package ships no
 * SQLite adapter of its own — see this file's header and `repo.memory.ts`'s header for why).
 */
export interface DeletableTaxonomyRepoPort {
  delete({ id }: { id: string }): Promise<void>;
}

export interface DeletableTermRepoPort {
  delete({ id }: { id: string }): Promise<void>;
  /** Direct-child count for `termId` as a parent. `deleteTerm` refuses to delete a term with
   * children still pointing `parentId` at it — that reference would otherwise dangle the moment
   * the parent row is gone, corrupting the hierarchy `validateHierarchyAssignment` polices on the
   * write side. This dispatch's own finding, not a named requirement — no cascading delete of
   * children is attempted; the caller must clear them first (bottom-up), same as the
   * content-assignment guard below forces "unassign first." */
  countChildren(params: { parentId: string }): Promise<number>;
}

export interface AssignmentCountEntryTermRepoPort {
  /** Count of `entry_terms` rows currently pointing at `termId` — the guard `deleteTerm` (and, by
   * summing across a taxonomy's member terms, `deleteTaxonomy`) uses to refuse destroying an
   * assignment live content still depends on. Deliberately the opposite direction from
   * `onContentDeleted` above: that subscriber cleans up `entry_terms` when CONTENT goes away
   * (content is the thing being removed, so orphaned assignment rows are safe to sweep silently);
   * here the TAXONOMY/TERM is what would be removed while the content stays live, so a silent
   * sweep would delete a real, still-visible link out from under an unrelated content item —
   * refusing the delete instead is the correct direction. */
  countByTerm(params: { termId: string }): Promise<number>;
}

/** `deleteTerm`/`deleteTaxonomy` refuse rather than silently orphan when content is still
 * assigned. Carries `assignedCount` so a caller (route/UI) can render "N items are still
 * assigned" instead of a generic failure. */
export class TermHasAssignedContentError extends Error {
  public readonly assignedCount: number;
  constructor(requiredArgs: { message: string; assignedCount: number }, _optionalArgs: Record<string, never> = {}) {
    const { message, assignedCount } = requiredArgs;
    super(message);
    this.assignedCount = assignedCount;
    this.name = "TermHasAssignedContentError";
  }
}

/** See `DeletableTermRepoPort.countChildren`'s doc comment for why this guard exists. Carries
 * `childCount` for the same reason `TermHasAssignedContentError` carries `assignedCount`. */
export class TermHasChildTermsError extends Error {
  public readonly childCount: number;
  constructor(requiredArgs: { message: string; childCount: number }, _optionalArgs: Record<string, never> = {}) {
    const { message, childCount } = requiredArgs;
    super(message);
    this.childCount = childCount;
    this.name = "TermHasChildTermsError";
  }
}

/** `deleteTaxonomy`'s content-assignment guard — `assignedCount` is the sum across every member
 * term, not a single term's count. */
export class TaxonomyHasAssignedContentError extends Error {
  public readonly assignedCount: number;
  constructor(requiredArgs: { message: string; assignedCount: number }, _optionalArgs: Record<string, never> = {}) {
    const { message, assignedCount } = requiredArgs;
    super(message);
    this.assignedCount = assignedCount;
    this.name = "TaxonomyHasAssignedContentError";
  }
}


export interface DeleteTermRequired {
  deps: WriteServiceDeps & {
    terms: DeletableTermRepoPort;
    entryTerms: AssignmentCountEntryTermRepoPort;
    /** See `TransactionalRepoPort`'s doc comment. Any one repo's `.transaction()` method is a
     * valid source — the route/composition-root wiring picks one (this package stays agnostic to
     * which); every write inside `fn` must land on the SAME underlying connection that opened it,
     * which is a wiring obligation the caller owns, not something this function can verify. */
    transaction: TransactionalRepoPort["transaction"];
  };
  principalId: string;
  termId: string;
}

/**
 * Deletes a single term. Refuses (never cascades) when the term still has children or is still
 * assigned to content — both checks run, and either alone is enough to block, before any write.
 * An unassigned, childless term is destroying nothing recoverable, so this is a direct delete with
 * no plan()/confirmation ceremony (`mergeTerm` earns that ceremony because it migrates data this
 * does not).
 *
 * `authorize()` runs before the transaction opens (a pure permission check, no side effect, so it
 * doesn't need transactional protection); everything from the existence check onward — both
 * guards and the delete itself — runs inside `deps.transaction()` (see that port's doc comment for
 * why). Does NOT cascade-delete the term's `taxonomy_revisions` rows: that table is an append-only
 * audit trail (mirrors `redirect_hits`/`asset_renditions`'s disclosed audit-not-referential-
 * integrity precedent), and erasing a term's history the moment the term itself is deleted would
 * destroy the very "this term existed and was deleted" record this call's own revision insert
 * below creates. Confirmed by grepping `db/schema.ts`: no other table has a `taxonomyId`/`termId`
 * column, so `taxonomy_revisions` is the only thing this decision applies to.
 *
 * @complexity O(1) — one `countChildren` call, one `countByTerm` call, one delete, all inside one
 * transaction.
 * @overallScore 100
 */
export async function deleteTerm(
  required: DeleteTermRequired,
  _optional: Record<string, never> = {}
): Promise<{ deletedTermId: string }> {
  const { deps, principalId, termId } = required;
  await authorizeTaxonomyManage(deps, principalId);

  return deps.transaction({ fn: async () => {
    const current = await deps.terms.findById({ id: termId });
    if (!current) {
      throw new TermRecordNotFoundError({ message: `term '${termId}' was not found` });
    }

    const childCount = await deps.terms.countChildren({ parentId: termId });
    if (childCount > 0) {
      throw new TermHasChildTermsError({ message: `term '${termId}' has ${childCount} child term(s) and cannot be deleted`, childCount: childCount });
    }

    const assignedCount = await deps.entryTerms.countByTerm({ termId });
    if (assignedCount > 0) {
      throw new TermHasAssignedContentError({ message: `term '${termId}' is assigned to ${assignedCount} content item(s) and cannot be deleted`, assignedCount: assignedCount }
      );
    }

    await deps.terms.delete({ id: termId });

    const now = kernelNowIso({ clock: deps.clock });
    await deps.revisions.insert({
      taxonomyId: current.taxonomyId,
      op: "delete",
      previousState: { termId, name: current.name ?? null },
      actorId: principalId,
      recordedAt: now,
    });
    await deps.stampWatermark({});
    await deps.outbox.enqueue({ event: {
      name: "taxonomy.term_deleted",
      termId,
      taxonomyId: current.taxonomyId,
      actorId: principalId,
      occurredAt: now,
    } });

    return { deletedTermId: termId };
  } });
}

export interface DeleteTaxonomyRequired {
  deps: WriteServiceDeps & {
    taxonomies: DeletableTaxonomyRepoPort;
    terms: TermListPort & DeletableTermRepoPort;
    entryTerms: AssignmentCountEntryTermRepoPort;
    /** See `TransactionalRepoPort`'s doc comment. */
    transaction: TransactionalRepoPort["transaction"];
  };
  principalId: string;
  taxonomyId: string;
}

/**
 * Deletes a taxonomy together with its member terms, refusing when ANY member term is still
 * assigned to content (the sum across all member terms, reported as one `assignedCount`). Unlike
 * `deleteTerm`, this does cascade — but only over terms this same call has just confirmed, INSIDE
 * the same transaction, are unassigned, so nothing recoverable is lost. `deleteTerm`'s own "has
 * children" guard does not apply here: a member term's children are, by construction, also members
 * of the same taxonomy (hierarchy never crosses taxonomies — `validateHierarchyAssignment`'s
 * `ParentCrossTaxonomyError` enforces that on the write side), so deleting the full member set in
 * one pass never leaves a `parentId` dangling outside the set being deleted.
 *
 * Same transaction-boundary and `taxonomy_revisions`-retention rationale as `deleteTerm` — see its
 * doc comment. The taxonomy-level version of the same TOCTOU risk: `listByTaxonomy` and every
 * per-term `countByTerm` call must see the SAME committed state the delete loop is about to act
 * on, which is only guaranteed inside one transaction, not across N separate queries beforehand.
 *
 * @complexity O(t) in the taxonomy's own term count — one `countByTerm` per member term to total
 * the guard, then one delete per member term plus one taxonomy delete, all inside one transaction.
 * @overallScore 100
 */
export async function deleteTaxonomy(
  required: DeleteTaxonomyRequired,
  _optional: Record<string, never> = {}
): Promise<{ deletedTaxonomyId: string; deletedTermIds: string[] }> {
  const { deps, principalId, taxonomyId } = required;
  await authorizeTaxonomyManage(deps, principalId);

  return deps.transaction({ fn: async () => {
    const taxonomy = await deps.taxonomies.findById({ id: taxonomyId });
    if (!taxonomy) {
      throw new TaxonomyRecordNotFoundError({ message: `taxonomy '${taxonomyId}' was not found` });
    }

    const memberTerms = await deps.terms.listByTaxonomy({ taxonomyId });

    let totalAssigned = 0;
    for (const term of memberTerms) {
      totalAssigned += await deps.entryTerms.countByTerm({ termId: term.id });
    }
    if (totalAssigned > 0) {
      throw new TaxonomyHasAssignedContentError({ message: `taxonomy '${taxonomyId}' has ${totalAssigned} content assignment(s) across its terms and cannot be deleted`, assignedCount: totalAssigned }
      );
    }

    for (const term of memberTerms) {
      await deps.terms.delete({ id: term.id });
    }
    await deps.taxonomies.delete({ id: taxonomyId });

    const now = kernelNowIso({ clock: deps.clock });
    const deletedTermIds = memberTerms.map((term) => term.id);
    await deps.revisions.insert({
      taxonomyId,
      op: "delete",
      previousState: { deletedTermIds },
      actorId: principalId,
      recordedAt: now,
    });
    await deps.stampWatermark({});
    await deps.outbox.enqueue({ event: {
      name: "taxonomy.deleted",
      taxonomyId,
      deletedTermIds,
      actorId: principalId,
      occurredAt: now,
    } });

    return { deletedTaxonomyId: taxonomyId, deletedTermIds };
  } });
}

/**
 * @file Column/record contracts for snapshot-only trash listing and atomic marker/index changes.
 * A trash operation never round-trips an entity payload, and listing never reads the entity at all.
 * Parsing a payload merely to flip its status fails on the corrupt rows a user most wants gone.
 * `trash` requires a caller-held display snapshot. Adapters expose only hide/unhide/purge, with no
 * describe method: a read that can throw must never become a dependency of trash listing.
 */
export type TrashEntityType = string;

/** The two display strings captured from columns at trash time. Never derived by the port. */
export interface TrashDisplay {
  title: string;
  subtitle?: string | null;
}

export interface TrashActor {
  principalId: string;
  pluginId?: string | null;
}

/**
 * Outcome of a marker flip.
 *
 * `version` is the entity's version AFTER the flip — that is what lands in
 * `trashed_items.entity_version` and what the sweeper's compare-and-delete later checks, so a
 * restore (which bumps the version again) always wins a race against a purge. `null` for a domain
 * with no version column.
 *
 * `priorMarker` is OPTIONAL and additive (migration 0072): a status-marker adapter (`menu`, `term`,
 * `taxonomy`) reports the status the row carried immediately before `hide` flipped it to `trash`, so
 * `restore` can put it back exactly rather than to a fixed fallback. A caller that omits the key
 * entirely (timestamp adapters) keeps the exact `{ ok: true, version }` shape — do not set this to
 * `undefined`; leave the key out. `trash.contract.test.ts`'s pinned `assert.deepEqual(trashed, {
 * ok: true, version: 2 })` depends on that: Node's `assert.deepEqual` treats an extra own-enumerable
 * property, even one valued `undefined`, as a mismatch.
 *
 * `noop` is OPTIONAL and additive (T1c, `follow-ups.test.ts`): host table adapters' `hide`/`unhide`
 * set it to `true` on their idempotent "already in the target state" branch — the ONE signal that
 * distinguishes that branch from a real transition, both of which otherwise report the same
 * `ok: true`. `withFollowUps` (`@jini-ai/cms/trash`) reads it to decide whether a hook actually finished
 * something. Same leave-the-key-out rule as `priorMarker`: a real transition leaves it absent, so exact-shape assertions remain
 * valid, so their pinned exact-shape assertions are
 * unaffected.
 *
 * `"blocked"` (T1 item 2, migration-free — no new column) is a THIRD failure reason, alongside
 * `"not-found"`/`"version-changed"`: the row exists and the version matches, but the host's
 * declared blocker found rows that must move or be deleted first (a term with child terms). `code`
 * and `count` are always present together on this branch — the host registry defines their meaning.
 */
export type TrashMarkerResult =
  | { ok: true; version: number | null; priorMarker?: string | null; noop?: true; }
  | { ok: false; reason: "not-found" | "version-changed"; }
  | { ok: false; reason: "blocked"; code: string; count: number; };

/** Outcome of a physical row removal. `still-referenced` retains the entity and its Trash index. */
export type TrashPurgeOutcome = "purged" | "version-changed" | "already-gone" | "still-referenced";

/**
 * One per domain. Built and registered into a plain `Map` at the composition root and resolved
 * **at call time**, never at registration time: this codebase's module registries (`ToolRegistry`,
 * routing's `phaseRegistry`) are append-only with no unregister, so anything that filters at
 * registration runs exactly once. Two real bugs already came from that.
 *
 * Persistent host implementations MUST be column-only SQL. No payload parse, no ORM entity hydration, no domain
 * write-service call that re-validates a record.
 */
export interface TrashAdapter {
  readonly entityType: TrashEntityType;
  /**
   * Move the domain's own marker to hidden.
   *
   * `at` is supplied by the caller rather than read from an adapter-local clock so the marker's
   * timestamp is byte-identical to the one the calling domain writes into its revision ledger.
     */
  hide(required: {
    workspaceId: string;
    entityId: string;
    at: string;
    expectedVersion: number | null;

  }, optional?: { actor?: TrashActor; }): Promise<TrashMarkerResult>;
  /**
   * Move it back. Same no-parse rule as {@link TrashAdapter.hide}.
   *
   * `priorMarker` (migration 0072) is what {@link TrashItem.priorMarker} stored at trash time —
   * additive and optional, so every adapter's existing signature stays structurally compatible. A
   * status-marker adapter restores to `priorMarker ?? restoreFallback`; a timestamp-marker adapter
   * (timestamp adapters) ignores it, since clearing the marker column needs no prior value.
     */
  unhide(required: {
    workspaceId: string;
    entityId: string;
    at: string;
    expectedVersion: number | null;
  }, optional?: { priorMarker?: string | null; actor?: TrashActor; }): Promise<TrashMarkerResult>;
  /** Physically remove the row. Compare-and-delete on `expectedVersion`. */
  purge(required: {
    workspaceId: string;
    entityId: string;
    expectedVersion: number | null;

  }, optional?: { actor?: TrashActor; }): Promise<TrashPurgeOutcome>;
}

/** One row of the Trash list. Rendered entirely from the snapshot — no entity read. */
export interface TrashItem {
  id: string;
  workspaceId: string;
  entityType: TrashEntityType;
  entityId: string;
  trashedAt: string;
  purgeAfter: string;
  actorPrincipalId: string;
  actorPluginId: string | null;
  displayTitle: string;
  displaySubtitle: string | null;
  entityVersion: number | null;

  priorMarker: string | null;
}

export interface TrashPage {
  items: TrashItem[];
  /** Keyset cursor on `(trashed_at, id)`; `null` when the page is the last one. */
  nextCursor: string | null;
}

/** Per-item outcome of {@link TrashPort.purgeSelected}. */
export type PurgeItemOutcome =
  | "purged"
  | "already-gone"
  | "version-changed"
  | "still-referenced"
  | "not-found"
  | "adapter-unavailable"
  | "forbidden";

/**
 * Decides whether the caller may permanently destroy ONE already-resolved trash row.
 *
 * Purge addresses rows by trash row id, and the per-kind permission has to be checked against the
 * kind the STORED row actually has. A caller that supplied the kind alongside the id could name
 * `comment` for a post's row and destroy a post holding only `comments.moderate`. So the gate is
 * handed the row `purgeSelected` looked up, inside the same call that then purges it — which closes
 * the read-then-act window as well as the escalation.
 *
 * Returning `false` (rather than throwing) keeps a denial a per-item outcome: one forbidden row in
 * a hand-ticked selection must not abort the rows the caller may destroy.
 */
export type TrashItemAuthorizer = (required: { item: TrashItem; }) => Promise<boolean>;

export interface PurgeReport {
  purged: number;
  results: { id: string; outcome: PurgeItemOutcome; }[];
}

/** Outcome of a restore. `adapter-unavailable` is honest degradation, not a throw: the row lists
 *  from its snapshot even when its plugin has been uninstalled. */
export type RestoreOutcome = "restored" | "not-found" | "version-changed" | "adapter-unavailable";

export interface TrashPort {
  /**
   * Hide the entity AND index it, as ONE transaction. There is deliberately no public seam that
   * performs only one of the two writes — a failure between them would leave an item that is in the
   * Trash and still live on the site, or hidden with no Trash row, which is unrecoverable from the UI.
     */
  trash(required: {
    workspaceId: string;
    entityType: TrashEntityType;
    entityId: string;
    actor: TrashActor;
    display: TrashDisplay;
    at: string;
    expectedVersion: number | null;

  }, optional?: { priorMarker?: string | null; }): Promise<TrashMarkerResult>;

  restore(required: {
    workspaceId: string;
    entityType: TrashEntityType;
    entityId: string;
    at: string;

  }, optional?: { actor?: TrashActor; }): Promise<RestoreOutcome>;
  /** Excludes `purge_after <= now`: a dormant site shows nothing expired on its first render, with
   *  no wait for a sweep. */
  list(required: {
    workspaceId: string;
    now: string;
    limit: number;
  }, optional?: { entityTypes?: readonly TrashEntityType[]; cursor?: string | null; }): Promise<TrashPage>;
  /**
   * Human-confirmed: the admin Trash screen and `permanent-delete` tools may reach this port only
   * after confirmation. Tool input cannot self-confirm; see the confirmed-call contract tests.
   *
   * `authorizeItem` is REQUIRED, not optional. A permission check a call site may omit is a
   * permission check some call site eventually omits, and this operation is the one that cannot be
   * undone. See {@link TrashItemAuthorizer} for why the gate takes the resolved row.
     */
  purgeSelected(required: {
    workspaceId: string;
    ids: readonly string[];
    actor: TrashActor;
    authorizeItem: TrashItemAuthorizer;
  }): Promise<PurgeReport>;
}

export type RemoveEntity = (required: {
  workspaceId: string;
  id: string;
  display: TrashDisplay;
  at: string;
  expectedVersion: number | null;
  actor: TrashActor;

}, optional?: { priorMarker?: string | null; }) => Promise<TrashMarkerResult>;

/**
 * The function a domain's delete path receives to DROP an index row.
 *
 * Needed by any domain that can leave the trashable state by a route other than a Trash-screen
 * restore or purge: a comment approved back out of `trash` by ordinary moderation, a media asset
 * hard-purged from the admin delete rung. Without it the index row outlives the condition it
 * records, and the Trash screen offers a Restore or a permanent delete for something that is either
 * live again or already gone.
 *
 * NOT a half of {@link TrashPort.trash}. It writes no marker and hides nothing — it only forgets a
 * removal that some other owner has already undone or completed.
 */
export type ForgetRemovedEntity = (required: { workspaceId: string; id: string; }) => Promise<void>;

/** A claimed batch of due rows, handed to the sweeper. */
export interface TrashSweepClaim {
  id: string;
  workspaceId: string;
  entityType: TrashEntityType;
  entityId: string;
  entityVersion: number | null;
}

/**
 * Storage for `trashed_items`. Adapters: host persistence + in-memory reference adapter.
 *
 * Every method is column-only. Nothing here ever reaches into a domain table.
 */
export interface TrashRepoPort {
  /** Idempotent by `(workspace_id, entity_type, entity_id)` — re-trashing is a no-op, not a
   *  duplicate row. */
  insert(required: { row: TrashItem; }): Promise<void>;

  findByEntity(required: {
    workspaceId: string;
    entityType: TrashEntityType;
    entityId: string;
  }): Promise<TrashItem | null>;

  findByIds(required: { workspaceId: string; ids: readonly string[]; }): Promise<TrashItem[]>;
  /** Removes the index row. This IS the restore — there is no second marker to clear. */
  deleteById(required: { workspaceId: string; id: string; }): Promise<void>;

  deleteByEntity(required: {
    workspaceId: string;
    entityType: TrashEntityType;
    entityId: string;
  }): Promise<void>;

  list(required: {
    workspaceId: string;
    now: string;
    limit: number;
  }, optional?: { entityTypes?: readonly TrashEntityType[]; cursor?: string | null; }): Promise<TrashPage>;
  /** Atomic claim of due, unleased rows across EVERY workspace in the file (the `purge_after`
   *  index is global for exactly this query). */
  claimDue(required: {
    now: string;
    leaseOwner: string;
    leaseUntil: string;
    limit: number;
  }): Promise<TrashSweepClaim[]>;
  /** Explicitly release a claim. The built-in sweep retains stood-down leases for retry backoff. */
  releaseLease(required: { id: string; }): Promise<void>;
}

/**
 * Marker/index writes and follow-ups must share one reentrant transaction. A domain may already
 * hold a transaction around its marker/revision writes; nesting must join rather than open another
 * BEGIN, and a propagated failure must roll back the entire unit.
 */
export type TransactionRunner = <T>(required: { work: () => Promise<T>; }) => Promise<T>;

/** Host-owned allowlist evaluated at call time; listing still uses snapshots for missing domains. */
export type TrashEntityPolicy = (required: { entityType: TrashEntityType; }) => boolean;

/**
 * @file In-memory `TrashRepoPort` (rule-of-two adapter #1), mirroring the convention
 * host in-memory repository conventions established: a real adapter used by tests, not a stub.
 *
 * Ordering, the lazy `purge_after` filter and the keyset cursor are implemented here the same way
 * persistent adapters implement them, and both share this package's cursor codec, so a test that passes against
 * this double is testing the behaviour the durable adapter has.
 */
import { decodeTrashCursor, encodeTrashCursor } from "./cursor.js";
import type { TrashEntityType, TrashItem, TrashPage, TrashRepoPort, TrashSweepClaim } from "./ports.js";

function identityKey(workspaceId: string, entityType: string, entityId: string): string {
  return `${workspaceId}\u0000${entityType}\u0000${entityId}`;
}

/**
 * Newest first, `id` breaking ties so the keyset cursor is total. @complexity O(1).
 *
 * The `id` comparison is written branch-free: `rows` is a `Map` keyed by `id`, so two distinct rows
 * never share one and an `id` tie can only arise from a self-comparison — which still correctly
 * yields `0` here, without a dedicated `return 0` branch no stored data can reach.
 */
function compareDesc(a: TrashItem, b: TrashItem): number {
  if (a.trashedAt !== b.trashedAt) return a.trashedAt < b.trashedAt ? 1 : -1;
  return Number(a.id < b.id) - Number(a.id > b.id);
}

export class InMemoryTrashRepo implements TrashRepoPort {
  constructor(_required: Record<string, never>) { }
  private readonly rows = new Map<string, TrashItem>();
  private readonly leases = new Map<string, { owner: string; expiresAt: string; }>();
  /** Test-only view of everything stored, including expired rows the list hides. */
  all(_required: Record<string, never>): TrashItem[] {
    return [...this.rows.values()].sort(compareDesc);
  }
  /** @complexity O(n) over stored rows (the identity scan); n is a test fixture. */
  async insert({ row }: { row: TrashItem; }): Promise<void> {
    for (const existing of this.rows.values()) {
      if (identityKey(existing.workspaceId, existing.entityType, existing.entityId) ===
        identityKey(row.workspaceId, row.entityType, row.entityId)) {
        return; // INSERT OR IGNORE against `trashed_items_identity_unique`
      }
    }
    this.rows.set(row.id, { ...row });
  }

  async findByEntity(required: { workspaceId: string; entityType: TrashEntityType; entityId: string; }): Promise<TrashItem | null> {
    const wanted = identityKey(required.workspaceId, required.entityType, required.entityId);
    for (const row of this.rows.values()) {
      if (identityKey(row.workspaceId, row.entityType, row.entityId) === wanted) return { ...row };
    }
    return null;
  }

  async findByIds(required: { workspaceId: string; ids: readonly string[]; }): Promise<TrashItem[]> {
    return required.ids
      .map((id) => this.rows.get(id))
      .filter((row): row is TrashItem => row !== undefined && row.workspaceId === required.workspaceId)
      .map((row) => ({ ...row }));
  }

  async deleteById(required: { workspaceId: string; id: string; }): Promise<void> {
    const row = this.rows.get(required.id);
    if (row && row.workspaceId === required.workspaceId) {
      this.rows.delete(required.id);
      this.leases.delete(required.id);
    }
  }

  async deleteByEntity(required: { workspaceId: string; entityType: TrashEntityType; entityId: string; }): Promise<void> {
    const found = await this.findByEntity(required);
    if (found) {
      this.rows.delete(found.id);
      this.leases.delete(found.id);
    }
  }
  /** @complexity O(n log n) — sorts the workspace's rows; fixture-sized by construction. */
  async list(required: {
    workspaceId: string;
    now: string;
    limit: number;
  }, optional: { entityTypes?: readonly TrashEntityType[]; cursor?: string | null; } = {}): Promise<TrashPage> {
    const after = decodeTrashCursor({ cursor: optional.cursor });
    const types = optional.entityTypes && optional.entityTypes.length > 0 ? new Set(optional.entityTypes) : null;

    const matched = [...this.rows.values()]
      .filter((row) => row.workspaceId === required.workspaceId)

      // Expired rows vanish immediately on list, even if a sweeper has never run in this host.
      .filter((row) => row.purgeAfter > required.now)
      .filter((row) => (types ? types.has(row.entityType) : true))
      .sort(compareDesc)
      .filter((row) => {
        if (!after) return true;
        if (row.trashedAt !== after.trashedAt) return row.trashedAt < after.trashedAt;
        return row.id < after.id;
      });

    const items = matched.slice(0, required.limit).map((row) => ({ ...row }));
    const last = items.at(-1);
    const nextCursor = matched.length > required.limit && last ? encodeTrashCursor(last) : null;
    return { items, nextCursor };
  }
  /** @complexity O(n log n). */
  async claimDue(required: { now: string; leaseOwner: string; leaseUntil: string; limit: number; }): Promise<TrashSweepClaim[]> {
    const due = [...this.rows.values()]
      .filter((row) => row.purgeAfter <= required.now)
      .filter((row) => {
        const lease = this.leases.get(row.id);
        return !lease || lease.expiresAt <= required.now;
      })
      .sort((a, b) => (a.purgeAfter < b.purgeAfter ? -1 : a.purgeAfter > b.purgeAfter ? 1 : 0))
      .slice(0, required.limit);

    for (const row of due) {
      this.leases.set(row.id, { owner: required.leaseOwner, expiresAt: required.leaseUntil });
    }

    return due.map((row) => ({
      id: row.id,
      workspaceId: row.workspaceId,
      entityType: row.entityType,
      entityId: row.entityId,
      entityVersion: row.entityVersion,
    }));
  }

  async releaseLease(required: { id: string; }): Promise<void> {
    this.leases.delete(required.id);
  }
}

/**
 * @file The retention auto-purge backstop (60 days by default) — claim, compare, delete, in that order.
 *
 * Two halves on purpose, because they fail in completely different ways:
 *
 *  - {@link createTrashSweep} is the decision half. It has no clock, no timer and no randomness, so
 *    every branch below (the restore race, a stale version, a missing adapter) is a plain function
 *    call in a test rather than something you have to wait for.
 *  - {@link startTrashSweeper} is the effect half: a non-overlapping loop over an injected scheduler. The host owns timer cancellation and
 *    `unref`, so the loop stays portable without changing its first-turn and shutdown behavior.
 *
 * **A concurrent restore always wins.** That is the whole safety property, and it is bought twice
 * over, because either guard alone has a hole:
 *
 *  1. Inside the purge transaction the index row is re-read by id. A restore deletes that row in
 *     its own transaction, so a sweep whose claim is already in hand finds nothing and never calls
 *     `purge` at all. Version alone would not cover a domain whose `entity_version` is `null`
 *     (comments and redirects both are) — there is no version there to have changed.
 *  2. `adapter.purge` is still a compare-and-delete on the version captured at trash time, so a
 *     domain that does carry a version stands down even if the row somehow survived step 1.
 *
 * The lease is the third leg: a claimed row is invisible to other sweeps until `leaseUntil`, so two
 * processes serving the same file cannot both purge it, and a sweep that dies mid-batch releases
 * its rows by expiry rather than wedging them forever.
 */
import { nowIso as kernelNowIso } from "@jini-ai/core/primitives";
import type { Clock } from "@jini-ai/core/primitives";
/** Claim then re-read inside the purge transaction; a concurrent restore always wins. */
import type {
  PurgeItemOutcome,
  TrashAdapter,
  TrashEntityType,
  TrashEntityPolicy,
  TrashRepoPort,
  TransactionRunner,
} from "./ports.js";

/** Idle wait between sweeps. Retention is measured in days, so an hour of lateness costs nothing,
 *  and a desktop site that is only open for minutes still sweeps once at boot. */
export const DEFAULT_TRASH_SWEEP_INTERVAL_MS = 60 * 60 * 1000;

/** Rows claimed per sweep. Each one costs a transaction, so this bounds a single sweep's hold on
 *  the write lock; a full batch sweeps again immediately rather than waiting out the interval. */
export const DEFAULT_TRASH_SWEEP_BATCH_SIZE = 50;

/** How long a claim hides a row from other sweeps. Also the retry backoff for a row that stood
 *  down: nothing releases it early, so it is re-tried at most once per lease. */
export const DEFAULT_TRASH_SWEEP_LEASE_MS = 5 * 60 * 1000;

export interface TrashSweepDeps {
  repo: TrashRepoPort;
  /** The same call-time `Map` the write service resolves against — never a module-level registry. */
  adapters: ReadonlyMap<TrashEntityType, TrashAdapter>;
  /** Reentrant; see {@link TransactionRunner}. */
  transaction: TransactionRunner;
  entityPolicy: TrashEntityPolicy;
}

export interface TrashSweepReport {
  /** Rows this sweep leased. `claimed === limit` means there is probably more due right now. */
  claimed: number;
  purged: number;
  results: { id: string; outcome: PurgeItemOutcome; }[];
}

/**
 * One pass of the backstop. Time, identity and batch size are arguments rather than dependencies so
 * the decision logic stays deterministic.
 */
export type TrashSweepOnce = (required: {
  now: string;
  leaseOwner: string;
  leaseUntil: string;
  limit: number;
}) => Promise<TrashSweepReport>;

export interface TrashSweeper {
  /** Stops scheduling sweeps, then resolves once a sweep already running has settled. Idempotent. */
  stop(required: Record<string, never>): Promise<void>;
}

/**
 * Builds the sweep pass.
 *
 * @param deps the trash repo, the call-time adapter map and a reentrant transaction runner.
 * @returns a {@link TrashSweepOnce}. It never throws for a single bad row — one missing adapter or
 *          one stale version is recorded as that row's outcome and the rest of the batch continues.
 *          A repo-level failure (a locked database) does propagate; the caller's `onError` owns it.
 * @complexity O(limit) transactions per pass, each O(1); one indexed claim query.
 */
export function createTrashSweep(deps: TrashSweepDeps): TrashSweepOnce {
  return async function sweepTrashOnce(required): Promise<TrashSweepReport> {
    const claims = await deps.repo.claimDue(required);
    const results: { id: string; outcome: PurgeItemOutcome; }[] = [];

    for (const claim of claims) {
      const adapter = deps.adapters.get(claim.entityType);
      if (!adapter) {

        // Keep the lease: immediately retrying an uninstalled domain would starve the batch.
        // Its snapshot stays listed until expiry, and removal can resume when the domain returns.
        results.push({ id: claim.id, outcome: "adapter-unavailable" });
        continue;
      }
      if (!deps.entityPolicy({ entityType: claim.entityType })) { results.push({ id: claim.id, outcome: "forbidden" }); continue; }

      const outcome = await deps.transaction({
        work: async (): Promise<PurgeItemOutcome> => {

          // Restore removes the index in its own transaction, including unversioned domains.
          const [row] = await deps.repo.findByIds({ workspaceId: claim.workspaceId, ids: [claim.id] });
          if (!row) return "not-found";

          // Versioned domains also stand down on a compare-and-delete mismatch.
          const result = await adapter.purge({
            workspaceId: row.workspaceId,
            entityId: row.entityId,
            expectedVersion: row.entityVersion,
          });
          if (result === "purged" || result === "already-gone") {
            await deps.repo.deleteById({ workspaceId: row.workspaceId, id: row.id });
          }
          return result;
        }
      });
      results.push({ id: claim.id, outcome });
    }

    return {
      claimed: claims.length,
      purged: results.filter((r) => r.outcome === "purged").length,
      results,
    };
  };
}

/** Host scheduler owns timers, unref and cancellation. schedule must defer run to a later turn. */
export interface TrashSchedulerPort {
  schedule(required: { delayMs: number; run: () => void; }): unknown;
  cancel(required: { handle: unknown; }): void;
}
export function startTrashSweeper(
  required: { sweep: TrashSweepOnce; clock: Clock; scheduler: TrashSchedulerPort; leaseOwner: string; },
  optional: { intervalMs?: number; batchSize?: number; leaseMs?: number; onError?: (required: { error: unknown; }) => void; } = {},
): TrashSweeper {
  const intervalMs = optional.intervalMs ?? DEFAULT_TRASH_SWEEP_INTERVAL_MS;
  const batchSize = optional.batchSize ?? DEFAULT_TRASH_SWEEP_BATCH_SIZE;
  const leaseMs = optional.leaseMs ?? DEFAULT_TRASH_SWEEP_LEASE_MS;
  for (const value of [intervalMs, batchSize, leaseMs]) {
    if (!Number.isSafeInteger(value) || value <= 0) throw new RangeError("trash sweep bounds must be positive integers");
  }
  if (!required.leaseOwner) throw new RangeError("trash sweep leaseOwner must not be empty");
  let stopped = false;
  let timer: unknown;
  let inFlight: Promise<void> = Promise.resolve();
  const schedule = (delayMs: number): void => {
    if (stopped) return;
    timer = required.scheduler.schedule({ delayMs, run: () => { inFlight = sweep(); } });
  };
  const sweep = async (): Promise<void> => {
    let claimed = 0;
    try {
      const now = kernelNowIso({ clock: required.clock });
      const report = await required.sweep({
        now, leaseOwner: required.leaseOwner,
        leaseUntil: new Date(Date.parse(now) + leaseMs).toISOString(), limit: batchSize
      });
      claimed = report.claimed;
    } catch (error) {
      try { optional.onError?.({ error }); } catch { /* reporter cannot stop the loop */ }
    }
    schedule(claimed >= batchSize ? 0 : intervalMs);
  };
  schedule(0);
  return { async stop(_required) { stopped = true; required.scheduler.cancel({ handle: timer }); await inFlight; } };
}

/**
 * @file The Trash write chokepoint (design §2.2).
 *
 * The one thing to understand before editing: **`trash` performs BOTH writes — the domain's marker
 * flip and the `trashed_items` index insert — inside a single transaction.** The design as first
 * written had the caller do two writes (`port.trash()` then `adapter.hide()`), and nothing made
 * them atomic; a failure between them leaves an item that is in the Trash *and still live on the
 * site*, or hidden with no Trash row, which is unrecoverable through the UI. Removing that seam is
 * the point of this module, so there is deliberately no exported way to perform half of it.
 *
 * Domains do not import this file. They receive {@link RemoveEntity} through their own dependency
 * object, pre-bound at the composition root with their `entityType` — see `bindRemoveEntity`.
 */
import type { IdGenerator } from "@jini-ai/core/primitives";
import type {
  ForgetRemovedEntity,
  PurgeItemOutcome,
  PurgeReport,
  RemoveEntity,
  RestoreOutcome,
  TrashAdapter,
  TrashEntityType,
  TrashEntityPolicy,
  TrashItem,
  TrashMarkerResult,
  TrashPage,
  TrashPort,
  TrashRepoPort,
  TransactionRunner,
} from "./ports.js";

/** What {@link TrashServiceOptional.onChanged} receives. One event per state change — a no-op outcome
 *  (`not-found`, `version-changed`, `already-gone`, `forbidden`, `adapter-unavailable`) never fires
 *  it, because nothing changed. */
export interface TrashChangeEvent {
  workspaceId: string;
  entityType: TrashEntityType;
  entityId: string;
  change: "trash" | "restore" | "purge";
}

export interface TrashServiceDeps {
  repo: TrashRepoPort;
  /**
   * Plain `Map`, built at the composition root, resolved on EVERY call — never a module-level
   * registry. This codebase's registries are append-only with no unregister, so any filtering done
   * at registration time runs exactly once (two real bugs already).
     */
  adapters: ReadonlyMap<TrashEntityType, TrashAdapter>;
  idGen: IdGenerator;
  entityPolicy: TrashEntityPolicy;
  transaction: TransactionRunner;

}

/**
 * Calls `optional.onChanged`, if present, and never lets it throw. See
 * {@link TrashServiceOptional.onChanged} for why a failure here must not propagate.
 *
 * @complexity O(1) beyond the hook itself.
 */
async function notifyChanged(optional: TrashServiceOptional, event: TrashChangeEvent): Promise<void> {
  if (!optional.onChanged) return;
  try {
    await optional.onChanged(event);
  } catch (error) {

    try { optional.onError?.({ error }); } catch { /* reporting never undoes a state transition */ }
  }
}

/** Notifications are best effort inside the operation; transactional follow-ups use withFollowUps. */
export interface TrashServiceOptional {
  /** Retention is stamped once when removed; defaults to 60 days. */
  retentionDays?: number;
  /**
   * Fires inside the same transaction after successful marker/index changes. Hosts may stamp a
   * recovery watermark and enqueue an outbox event here; per-type revisions/events use follow-ups.
   * Failures are reported and swallowed so notification failure cannot undo the completed writes.
   */
  onChanged?: (required: TrashChangeEvent) => void | Promise<void>;
  onError?: (required: { error: unknown; }) => void;
}

/** A host composition error: fail fast rather than hide an entity that can never be restored. */
export class TrashAdapterMissingError extends Error {
  constructor({ message }: { message: string; }, optional: { cause?: unknown; } = {}) {
    super(message, optional);
  }
}

/** Stamp retention once at removal; later policy changes cannot shorten an existing promise. */
export const DEFAULT_TRASH_RETENTION_DAYS = 60;

/**
 * `at` + {@link DEFAULT_TRASH_RETENTION_DAYS}, as an ISO timestamp.
 *
 * Stamped at trash time, not computed at read time, so changing the constant later never
 * retroactively purges what a user was already promised.
 *
 * @complexity O(1).
 */
export function computePurgeAfter({ at }: { at: string; }, optional: { retentionDays?: number; } = {}): string {
  const retentionDays = optional.retentionDays ?? DEFAULT_TRASH_RETENTION_DAYS;
  if (!Number.isFinite(retentionDays) || retentionDays < 0) throw new RangeError("trash retentionDays must be non-negative and finite");
  const base = new Date(at);
  if (Number.isNaN(base.getTime())) {
    throw new RangeError(`trash: 'at' is not a parseable timestamp (received ${JSON.stringify(at)})`);
  }
  return new Date(base.getTime() + retentionDays * 24 * 60 * 60 * 1000).toISOString();
}

/**
 * Builds the Trash service.
 *
 * @param deps repo, the call-time adapter map, an id generator and a reentrant transaction runner.
 * @returns the {@link TrashPort} surface. `purgeSelected` requires host-owned human confirmation and per-row authorization.
 * @complexity O(1) to build.
 */
export function createTrashService(deps: TrashServiceDeps, optional: TrashServiceOptional = {}): TrashPort {
  const retentionDays = optional.retentionDays ?? DEFAULT_TRASH_RETENTION_DAYS;
  computePurgeAfter({ at: "2000-01-01T00:00:00.000Z" }, { retentionDays });

  /** Resolved on every call — see {@link TrashServiceDeps.adapters}. @complexity O(1). */
  function requireAdapter(entityType: TrashEntityType): TrashAdapter {
    const adapter = deps.adapters.get(entityType);
    if (!adapter || !deps.entityPolicy({ entityType })) {
      throw new TrashAdapterMissingError({ message: `trash: no adapter is registered for entity type '${entityType}'` });
    }
    return adapter;
  }

  return {
    /**
     * Hides the entity and indexes it as one unit.
     *
     * @complexity O(1) — one marker UPDATE plus one index INSERT, both inside one transaction.
         */
    async trash(required, trashOptional = {}): Promise<TrashMarkerResult> {
      const adapter = requireAdapter(required.entityType);
      return deps.transaction({
        work: async () => {
          const marker = await adapter.hide({
            workspaceId: required.workspaceId,
            entityId: required.entityId,
            at: required.at,
            expectedVersion: required.expectedVersion,
          }, { actor: required.actor });
          if (!marker.ok) return marker;

          const row: TrashItem = {
            id: deps.idGen.newId(),
            workspaceId: required.workspaceId,
            entityType: required.entityType,
            entityId: required.entityId,
            trashedAt: required.at,
            purgeAfter: computePurgeAfter({ at: required.at }, { retentionDays }),
            actorPrincipalId: required.actor.principalId,
            actorPluginId: required.actor.pluginId ?? null,
            displayTitle: required.display.title,
            displaySubtitle: required.display.subtitle ?? null,
            entityVersion: marker.version,

            // The adapter's marker reading wins; caller state only fills in for adapters without one.
            priorMarker: marker.priorMarker ?? trashOptional.priorMarker ?? null,
          };
          await deps.repo.insert({ row });
          // A successful noop may repair a missing index, but did not change the domain marker.
          // Repeated removal must not emit another recovery watermark or outbox event (F1487).
          if (!marker.noop) {
            await notifyChanged(optional, {
              workspaceId: required.workspaceId,
              entityType: required.entityType,
              entityId: required.entityId,
              change: "trash",
            });
          }
          return marker;
        }
      });
    },
    /**
     * Clears the domain marker and removes the index row, as one unit.
     *
     * An entity whose row was deleted out from under the index returns `"not-found"` and the index
     * row is LEFT IN PLACE — purge is the only path that removes an index row, and the user can
     * still select it there. One deletion path, not two.
     *
     * @complexity O(1).
         */
    async restore(required, restoreOptional = {}): Promise<RestoreOutcome> {
      const row = await deps.repo.findByEntity(required);
      if (!row) return "not-found";
      const adapter = deps.adapters.get(required.entityType);
      if (!adapter || !deps.entityPolicy({ entityType: required.entityType })) return "adapter-unavailable";

      return deps.transaction({
        work: async () => {
          const marker = await adapter.unhide({
            workspaceId: required.workspaceId,
            entityId: required.entityId,
            at: required.at,
            expectedVersion: row.entityVersion,
          }, {
            priorMarker: row.priorMarker,
            ...(restoreOptional.actor !== undefined ? { actor: restoreOptional.actor } : {}),
          });
          if (!marker.ok) return marker.reason === "not-found" ? "not-found" : "version-changed";
          await deps.repo.deleteById({ workspaceId: required.workspaceId, id: row.id });
          // An already-clear marker still needs index cleanup, without a duplicate notification.
          if (!marker.noop) {
            await notifyChanged(optional, {
              workspaceId: required.workspaceId,
              entityType: required.entityType,
              entityId: required.entityId,
              change: "restore",
            });
          }
          return "restored";
        }
      });
    },
    /** @complexity one indexed keyset read; see `TrashRepoPort.list`. */
    async list(required, listOptional = {}): Promise<TrashPage> {
      return deps.repo.list(required, listOptional);
    },
    /**
     * Permanent deletion of selected rows. Called by the admin Trash screen or the assistant's
     * human-confirmed permanent-delete tools; callers own confirmation, this service owns row auth.
     *
     * Per item, and per item only: one unavailable adapter, one stale version or one row the caller
     * may not touch must not abort the rest of the selection, so each row gets its own permission
     * check, its own transaction and its own recorded outcome.
     *
     * The gate runs on the row this method looked up, BEFORE the adapter is resolved: a caller who
     * may not destroy a row must not learn from the outcome whether its domain is still installed.
     *
     * @complexity O(k) authorization calls and at most O(k) transactions for k selected ids.
         */
    async purgeSelected(required): Promise<PurgeReport> {
      const rows = await deps.repo.findByIds({ workspaceId: required.workspaceId, ids: required.ids });
      const byId = new Map(rows.map((row) => [row.id, row]));
      const results: { id: string; outcome: PurgeItemOutcome; }[] = [];

      for (const id of required.ids) {
        const row = byId.get(id);
        if (!row) {
          results.push({ id, outcome: "not-found" });
          continue;
        }
        if (!(await required.authorizeItem({ item: row }))) {
          results.push({ id, outcome: "forbidden" });
          continue;
        }
        const adapter = deps.adapters.get(row.entityType);
        if (!adapter) {
          results.push({ id, outcome: "adapter-unavailable" });
          continue;
        }
        if (!deps.entityPolicy({ entityType: row.entityType })) { results.push({ id, outcome: "forbidden" }); continue; }
        const outcome = await deps.transaction({
          work: async (): Promise<PurgeItemOutcome> => {
            const result = await adapter.purge({
              workspaceId: row.workspaceId,
              entityId: row.entityId,
              expectedVersion: row.entityVersion,
            }, { actor: required.actor });

            // A changed version leaves the index in place: the safe outcome of a restore/edit race
            // is that the item survives. Live references likewise retain the entity and its index.
            // Only completed or already-completed removals drop the index.
            if (result === "purged" || result === "already-gone") {
              await deps.repo.deleteById({ workspaceId: row.workspaceId, id: row.id });
            }

            // Already-gone is a no-op: nothing changed here, so no notification fires.
            if (result === "purged") {
              await notifyChanged(optional, {
                workspaceId: row.workspaceId,
                entityType: row.entityType,
                entityId: row.entityId,
                change: "purge",
              });
            }
            return result;
          }
        });
        results.push({ id, outcome });
      }

      return { purged: results.filter((r) => r.outcome === "purged").length, results };
    },
  };
}

/**
 * Pre-binds an index-row drop to one `entityType`, producing the function a domain receives as
 * `deps.forgetRemoved` (see {@link ForgetRemovedEntity} for when a domain needs one).
 *
 * Binds against the repo rather than the service on purpose: there is no marker to move here, and
 * routing it through `TrashPort` would put a method on that port which does half of a `trash`.
 *
 * @complexity O(1).
 */
export function bindForgetRemovedEntity({ repo, entityType }: { repo: TrashRepoPort; entityType: TrashEntityType; }): ForgetRemovedEntity {
  return (required) =>
    repo.deleteByEntity({ workspaceId: required.workspaceId, entityType, entityId: required.id });
}

/** Bind a domain without making its callers depend on trash vocabulary. */
export function bindRemoveEntity({ trash, entityType }: { trash: TrashPort; entityType: TrashEntityType; }): RemoveEntity {
  return (required, optional = {}) =>
    trash.trash({
      workspaceId: required.workspaceId,
      entityType,
      entityId: required.id,
      actor: required.actor,
      display: required.display,
      at: required.at,
      expectedVersion: required.expectedVersion,

    }, optional);
}

import { parseGalleryConfig } from "./markers/gallery.js";
import { isNonArrayRecord } from "@jini-ai/core";

/**
 * @file A minimal JSON-Schema-subset validator for `fields.ext.widget.*` config bags (SPEC-043
 * REQ-02, INV-01).
 *
 * Purpose:
 * `widgets/registry.ts`'s `WidgetTypeRegistration.configSchema` records use a small, deliberately
 * bounded JSON-Schema subset (`object`/`string`/`integer`/`array`, `properties`/`required`/
 * `additionalProperties`/`items`/`maxItems`/`minimum`/`maximum` — exactly what `registry.ts`'s five
 * v1 registrations actually use, no more). No JSON-Schema library is a dependency of this repo
 * (confirmed: no `ajv`/`jsonschema` entry in `package.json`), so this is a small, purpose-built
 * validator over that exact subset rather than a new third-party dependency for one feature.
 *
 * Architectural role:
 * `widgets` domain logic, internal helper. Used by `write-service.ts` before every widget-instance
 * write (REQ-01/02) — not part of this feature's frozen public contract list, so its shape is not
 * design-frozen the way `types.ts`/`ports.ts`/`errors.ts` are.
 */

interface WidgetConfigJsonSchema {
  readonly type?: string;
  readonly properties?: Readonly<Record<string, WidgetConfigJsonSchema>>;
  readonly required?: readonly string[];
  readonly additionalProperties?: boolean;
  readonly items?: WidgetConfigJsonSchema;
  readonly maxItems?: number;
  readonly minimum?: number;
  readonly maximum?: number;
  /** A field naming other content by id (`registry.ts`'s `categoryTermId`/`menuRef`/`formDefinitionId`). */
  readonly "x-ref-target"?: string;
}

export interface WidgetConfigFieldError {
  readonly field: string;
  readonly reason: string;
}

export interface ValidateWidgetConfigResult {
  readonly valid: boolean;
  readonly fieldErrors: WidgetConfigFieldError[];
}

/** Reports every key in `schema.required` that is missing from `value`. */
function validateRequiredKeys(
  value: Record<string, unknown>,
  schema: WidgetConfigJsonSchema,
  path: string,
  errors: WidgetConfigFieldError[]
): void {
  for (const key of schema.required ?? []) {
    if (!(key in value)) errors.push({ field: `${path}.${key}`, reason: "required field is missing" });
  }
}

/** Recurses into each `value` key that has a declared `schema.properties` entry; flags the rest when `additionalProperties` is `false`. */
function walkObjectProperties(
  value: Record<string, unknown>,
  schema: WidgetConfigJsonSchema,
  path: string,
  errors: WidgetConfigFieldError[]
): void {
  for (const [key, fieldValue] of Object.entries(value)) {
    const propSchema = schema.properties?.[key];
    if (!propSchema) {
      if (schema.additionalProperties === false) {
        errors.push({ field: `${path}.${key}`, reason: "unrecognized field: not present in the registered schema" });
      }
      continue;
    }
    walk(fieldValue, propSchema, `${path}.${key}`, errors);
  }
}

/** Checks `required` keys are present and recurses into each declared property (schema.type === "object"). */
function walkObject(value: unknown, schema: WidgetConfigJsonSchema, path: string, errors: WidgetConfigFieldError[]): void {
  const record = { value };
  if (!isNonArrayRecord(record)) {
    errors.push({ field: path, reason: "expected an object" });
    return;
  }
  validateRequiredKeys(record.value, schema, path, errors);
  walkObjectProperties(record.value, schema, path, errors);
}

/** schema.type === "string": type check only, no length/pattern constraint in this subset. */
function walkString(value: unknown, path: string, errors: WidgetConfigFieldError[]): void {
  if (typeof value !== "string") errors.push({ field: path, reason: "expected a string" });
}

/** schema.type === "integer": type check plus optional `minimum`/`maximum` bounds. */
function walkInteger(value: unknown, schema: WidgetConfigJsonSchema, path: string, errors: WidgetConfigFieldError[]): void {
  if (typeof value !== "number" || !Number.isInteger(value)) {
    errors.push({ field: path, reason: "expected an integer" });
    return;
  }
  if (schema.minimum !== undefined && value < schema.minimum) {
    errors.push({ field: path, reason: `below the minimum of ${schema.minimum}` });
  }
  if (schema.maximum !== undefined && value > schema.maximum) {
    errors.push({ field: path, reason: `above the maximum of ${schema.maximum}` });
  }
}

/** schema.type === "array": type check, optional `maxItems` bound, and recursion into `items`. */
function walkArray(value: unknown, schema: WidgetConfigJsonSchema, path: string, errors: WidgetConfigFieldError[]): void {
  if (!Array.isArray(value)) {
    errors.push({ field: path, reason: "expected an array" });
    return;
  }
  if (schema.maxItems !== undefined && value.length > schema.maxItems) {
    errors.push({ field: path, reason: `exceeds the maximum item count of ${schema.maxItems}` });
  }
  if (schema.items) {
    value.forEach((item, index) => {
      walk(item, schema.items as WidgetConfigJsonSchema, `${path}[${index}]`, errors);
    });
  }
}

/** Dispatches to the per-type walker for `schema.type` (object/string/integer/array); unspecified or boolean types accept anything. */
function walk(value: unknown, schema: WidgetConfigJsonSchema, path: string, errors: WidgetConfigFieldError[]): void {
  switch (schema.type) {
    case "object":
      walkObject(value, schema, path, errors);
      return;
    case "string":
      walkString(value, path, errors);
      return;
    case "integer":
      walkInteger(value, schema, path, errors);
      return;
    case "array":
      walkArray(value, schema, path, errors);
      return;
    default:
      // boolean / unspecified schema type: accept anything (no v1 registration needs this).
      return;
  }
}

/**
 * Validates `config` against a widget type's registered `configSchema` (REQ-02). The registered
 * schema is always the authority — a type's own `clamps` (e.g. `recent-entries`' `maxItems: 20`)
 * are already expressed as `maximum` constraints inside the schema itself (`registry.ts`), so no
 * separate clamp check is needed here to satisfy AC-02.
 *
 * @complexity O(n) over the config bag's total node count.
 * @overallScore 100
 */
export function validateWidgetConfig(
  required: {
  schema: Record<string, unknown>;
  config: Record<string, unknown>;
},
  _optional: Record<string, never> = {},
): ValidateWidgetConfigResult {
  const errors: WidgetConfigFieldError[] = [];
  walk(required.config, required.schema as WidgetConfigJsonSchema, "config", errors);
  // The shared parser owns layout, id and CSS-ratio invariants; the schema narrows widgets to library images.
  if (required.schema["x-gallery-config"] === true) {
    for (const reason of parseGalleryConfig({ config: required.config }, { allowEmpty: true }).errors) errors.push({ field: "config", reason });
  }
  return { valid: errors.length === 0, fieldErrors: errors };
}

/** Pushes each declared free-text string under `schema` (recursion into declared `properties` and
 *  `items` only). @complexity O(n) over the config's declared nodes. */
function collectStrings(value: unknown, schema: WidgetConfigJsonSchema, out: string[]): void {
  if (schema.type === "string") collectString(value, schema, out);
  else if (schema.type === "array") collectArrayStrings(value, schema, out);
  else if (schema.type === "object") collectObjectStrings(value, schema, out);
}

/** A declared string counts unless it is a ref field (`x-ref-target` names other content by id). */
function collectString(value: unknown, schema: WidgetConfigJsonSchema, out: string[]): void {
  if (typeof value === "string" && schema["x-ref-target"] === undefined) out.push(value);
}

/** Recurses into each item of an array value, only when the schema declares `items`. */
function collectArrayStrings(value: unknown, schema: WidgetConfigJsonSchema, out: string[]): void {
  if (!Array.isArray(value) || !schema.items) return;
  for (const item of value) collectStrings(item, schema.items, out);
}

/** Recurses into each declared property of a (non-array) record value. */
function collectObjectStrings(value: unknown, schema: WidgetConfigJsonSchema, out: string[]): void {
  const record = { value };
  if (!isNonArrayRecord(record)) return;
  for (const [key, propSchema] of Object.entries(schema.properties ?? {})) collectStrings(record.value[key], propSchema, out);
}

/**
 * Every free-text string `config` holds where its type's `configSchema` declares one — a `text`
 * widget's `body`, each social link's `url`. Ref fields (`x-ref-target`) are left out (they name
 * other content by id) and so is anything the schema does not declare (`recent-entries`' `where`).
 * The publish carry-along (`publish-content.ts`) reads media URLs out of these.
 *
 * @complexity O(n) over the config's declared nodes.
 */
export function collectWidgetConfigStrings(required: { schema: Record<string, unknown>; config: Record<string, unknown> }, _optional: Record<string, never> = {}): string[] {
  const out: string[] = [];
  collectStrings(required.config, required.schema as WidgetConfigJsonSchema, out);
  return out;
}

import { isNonArrayRecord } from "@jini-ai/core";
/**
 * @file Server-side, versioned document-mutation command for `widgetEmbed` nodes (SPEC-043
 * REQ-44/45, ADR-047 Debate Fold-In Amendment 6).
 *
 * Purpose:
 * The second entry point into the SAME document-mutation contract the live TipTap editor's own
 * Save path uses — both ultimately write through `features/entries/write-service.ts`'s
 * `updateEntry` chokepoint, the same `expectedVersion` OCC guard, and the same revision machinery.
 * Usable with no browser editor session open (an AI agent, or a server-side script). Enforces
 * REQ-19/20's guardrails (no widget-in-widget recursion, per-document embed-count clamp) via
 * `embed-validation.ts`'s `validateWidgetEmbedMutation` — the ONE validator both this path and the
 * live editor's own chokepoint-side hook must call, so the two paths can never silently diverge
 * (INV-04).
 *
 * Closes a real, previously-disclosed gap this file's own domain depends on: `updateEntry` had no
 * parameter to change `bodyJson` after creation (only `createEntry` did) — fixed additively in
 * `features/entries/write-service.ts` as part of this same dispatch (see that file's `bodyJson`
 * doc comment) rather than worked around here.
 *
 * Architectural role:
 * `widgets` domain logic (implementation outline C-007), landing in this later routes/UI/AI-tools
 * dispatch rather than the earlier domain-layer session, since it composes `updateEntry`'s new
 * `bodyJson` capability which did not exist yet at that time.
 */
import type { Clock as ClockPort, JsonObject, JsonValue, UUID } from "@jini-ai/core/primitives";
import type { ChangeSetRepoPort, CommandActor, OutboxPort } from "../core/index.js";
import { ForbiddenError, executeCommand } from "../core/index.js";
import type { EntryRefsRepoPort } from "./ports.js";

import type { ContentTypeRepoPort } from "../content-types/index.js";
import type { EntryRecord, EntryRepoPort } from "../entries/index.js";
import type { WidgetHostPorts, BeforeSaveHookPort, PostRecord, ForgetRemovedPostFn, PostRepoPort } from "./host-ports.js";
import {
  PRE_AUTHORIZED,
  requireWidgetPermission,
  type WidgetsAuthorizeFn,
} from "./authorize-helper.js";
import { withEntryLock, type EntryLockState } from "./concurrency.js";
import { validateWidgetEmbedMutation } from "./embed-validation.js";
import { parseWidgetInstancePayload } from "./entry-payload.js";
import {
  WidgetEmbedGuardrailError,
  WidgetEmbedHostNotFoundError,
  WidgetEmbedHostUnsupportedError,
  WidgetEmbedPlacementNotFoundError,
  WidgetForbiddenError,
  WidgetInstanceNotFoundError,
  WidgetVersionConflictError,
} from "./errors.js";
import { WIDGET_AREA_CONTENT_TYPE, WIDGET_CONTENT_TYPE } from "./types.js";
import type { WidgetEmbedNode } from "./types.js";

/** Matches the certified `embed-validation.unit.test.ts` suite's own value — no separate policy
 * config surface exists yet for this (OQ-level detail, same disclosure posture as OQ-01's resolver
 * timeout). */
const DEFAULT_MAX_EMBEDS_PER_DOCUMENT = 50;

export interface EmbedServiceDeps {
  /** One store-owned state shared by write, embed and region services; omission preserves compatibility. */
  entryLocks?: EntryLockState;
  host: Pick<WidgetHostPorts, "entries" | "entryRefs" | "posts">;
  entryRepo: EntryRepoPort;
  contentTypeRepo: ContentTypeRepoPort;
  entryRefsRepo: EntryRefsRepoPort;
  /** REQ-44 — a post/page host is a second, separate table (see `loadEmbedHost`'s doc). */
  postRepo: PostRepoPort;
  /**
   * Required by `restorePostForward`, which this service's `rollback` calls. Nothing here ever
   * trashes a post, so it can never actually fire — but the dependency is required rather than
   * optional on purpose: an optional compensation port is how one gets wired at three call sites
   * out of four. See `post.ts`'s {@link ForgetRemovedPostFn}.
   */
  forgetRemovedPost: ForgetRemovedPostFn;
  /** The same command-gateway change-set store the live editor's own post-save route uses, so a
   *  post/page embed write records an auditable, revertible change set identically (ADR-047
   *  Amendment 6). */
  changeSets: ChangeSetRepoPort;
  clock: ClockPort;
  ids: { newId: () => string };
  authorize: WidgetsAuthorizeFn;
  outbox: OutboxPort;
  /** Same optional "absent = zero-plugin behavior unchanged" contract as `UpdatePostDeps.beforeSaveHook`. */
  beforeSaveHook?: BeforeSaveHookPort;
  /** REQ-20 — policy-bounded, not hardcoded; defaults to `DEFAULT_MAX_EMBEDS_PER_DOCUMENT`. */
  maxEmbedsPerDocument?: number;
}

/** The `attrs` record of a `widgetEmbed` node, or `undefined` for any other node (or non-record attrs). */
function widgetEmbedAttrs(node: unknown): Record<string, unknown> | undefined {
  const candidate = { value: node };
  const attrs = { value: isNonArrayRecord(candidate) && candidate.value.type === "widgetEmbed" ? candidate.value.attrs : undefined };
  return isNonArrayRecord(attrs) ? attrs.value : undefined;
}

/** A record node's `content` array, or `undefined` when it has none. */
function contentOf(node: unknown): unknown[] | undefined {
  const candidate = { value: node };
  return isNonArrayRecord(candidate) && Array.isArray(candidate.value.content) ? candidate.value.content : undefined;
}

/** Pre-order walk over every non-array node, stopping as soon as `visit` returns true. */
function someNode({ root, visit }: { root: unknown; visit: (node: unknown) => boolean }, _optional = {}): boolean {
  const stack: unknown[] = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    if (Array.isArray(node)) {
      for (let i = node.length - 1; i >= 0; i--) stack.push(node[i]);
      continue;
    }
    if (visit(node)) return true;
    const content = contentOf(node);
    if (content) stack.push(content);
  }
  return false;
}

/** Walks a TipTap-shaped `bodyJson` tree collecting every `widgetEmbed` node, in document order. */
function collectEmbeds(root: unknown, out: WidgetEmbedNode[]): void {
  // An explicit stack, not recursion: a host body's nesting depth is caller/import-controlled and a
  // 5000-deep body overflowed the call stack here on every embed save (same class as f646ba397's
  // GET-path walkers). Children are pushed in reverse so the walk stays pre-order — document order,
  // which `reorderWidgetEmbeds` relies on.
  someNode({ root, visit: (node) => {
    const attrs = widgetEmbedAttrs(node);
    if (attrs && typeof attrs.placementId === "string" && typeof attrs.widgetEntryId === "string") {
      out.push({ type: "widgetEmbed", placementId: attrs.placementId, widgetEntryId: attrs.widgetEntryId });
    }
    return false;
  } });
}

function widgetEmbedNode(placementId: UUID, widgetEntryId: UUID): JsonValue {
  return { type: "widgetEmbed", attrs: { placementId, widgetEntryId } };
}

/** Appends one new `widgetEmbed` node to the end of the document's top-level `content` array — the
 * simplest well-defined "insert" position for a server-side/no-editor caller (an arbitrary cursor
 * position is a live-editor-only concept; REQ-44 requires the mutation exist, not that it target an
 * arbitrary offset). Falls back to a fresh empty doc if `bodyJson` isn't already a TipTap-shaped
 * doc node (e.g. a still-empty entry). */
function appendEmbed(bodyJson: unknown, placementId: UUID, widgetEntryId: UUID): JsonValue {
  const body = { value: bodyJson };
  const doc = isNonArrayRecord(body) && body.value.type === "doc" ? body.value : { type: "doc", content: [] };
  const content = Array.isArray(doc.content) ? doc.content : [];
  return { ...doc, content: [...content, widgetEmbedNode(placementId, widgetEntryId)] };
}

/** Removes every `widgetEmbed` node matching `placementId`, at any depth, preserving every other
 * node's position — mirrors the tree-shape-preserving discipline `reorderEmbeds` below also uses. */
function isEmbedWithPlacementId(node: unknown, placementId: UUID): boolean {
  return widgetEmbedAttrs(node)?.placementId === placementId;
}

/** Whether `removeEmbedByPlacementId` would remove anything — same match, so the two never disagree. */
function containsEmbedWithPlacementId({ node: root, placementId }: { node: unknown; placementId: UUID }, _optional = {}): boolean {
  // Stored/imported nesting is unbounded; keep the complete walk off the JavaScript call stack.
  return someNode({ root, visit: (node) => isEmbedWithPlacementId(node, placementId) });
}

type RewriteTask = { node: unknown; assign: (value: unknown) => void };

/** Queues a copy of `children` (assigned to its parent now, filled in as each child's task runs). */
function pushArrayCopy(stack: RewriteTask[], children: unknown[], assign: (value: unknown) => void): void {
  const copy: unknown[] = new Array(children.length);
  assign(copy);
  // Reverse push preserves pre-order, including new placement-id allocation order.
  for (let i = children.length - 1; i >= 0; i--) {
    stack.push({ node: children[i], assign: (value) => { copy[i] = value; } });
  }
}

/** A shallow copy of a record node whose `content` is queued for rewriting, or the node itself. */
function copyWithContent(stack: RewriteTask[], node: unknown): unknown {
  const candidate = { value: node };
  if (!isNonArrayRecord(candidate) || !Array.isArray(candidate.value.content)) return node;
  const copy = { ...candidate.value };
  stack.push({ node: candidate.value.content, assign: (value) => { copy.content = value; } });
  return copy;
}

/**
 * Rebuilds `root` as a copy: array children failing `keepChild` are dropped, and a non-array node
 * for which `replace` returns a value is swapped for it (anything else is copied, descending into
 * its `content`).
 */
function rewriteTree({ root }: { root: unknown }, { keepChild = () => true, replace = () => undefined }: {
  keepChild?: (child: unknown) => boolean;
  replace?: (node: unknown) => JsonValue | undefined;
} = {}): unknown {
  let result: unknown;
  // Each task assigns one transformed child to its copied parent; no recursive reconstruction
  // or mutation of the original document (which is also the write's inverse/revision state).
  const stack: RewriteTask[] = [
    { node: root, assign: (value) => { result = value; } },
  ];
  while (stack.length > 0) {
    const { node, assign } = stack.pop()!;
    if (Array.isArray(node)) pushArrayCopy(stack, node.filter(keepChild), assign);
    else assign(replace(node) ?? copyWithContent(stack, node));
  }
  return result;
}

function removeEmbedByPlacementId({ node: root, placementId }: { node: unknown; placementId: UUID }, _optional = {}): unknown {
  return rewriteTree({ root }, { keepChild: (child) => !isEmbedWithPlacementId(child, placementId) });
}

/** Reassigns which widget occupies which EXISTING embed slot, in document order, per
 * `orderedWidgetEntryIds` — the document's shape (surrounding paragraphs/headings, slot count and
 * position) is unchanged; only each slot's `widgetEntryId` is swapped. `placementId`s move with
 * their new `widgetEntryId` (a fresh placement identity per REQ-44's "reorder" being a distinct
 * operation from "insert") so `entry_refs` re-extraction after the write reflects the new mapping
 * cleanly rather than aliasing stale target ids to a slot that no longer represents them. */
function reorderEmbedSlots({ node: root, newIds, orderedWidgetEntryIds }: {
  node: unknown;
  newIds: () => UUID;
  orderedWidgetEntryIds: readonly UUID[];
}, _optional = {}): unknown {
  let index = 0;
  return rewriteTree({ root }, {
    // reorderWidgetEmbeds validates one supplied id per existing embed slot.
    replace: (node) => (widgetEmbedAttrs(node) ? widgetEmbedNode(newIds(), orderedWidgetEntryIds[index++]!) : undefined),
  });
}

async function extractAndStoreEmbedRefs(
  deps: EmbedServiceDeps,
  workspaceId: string,
  host: { id: UUID; type: string; bodyJson: unknown }
): Promise<void> {
  const refs = deps.host.entryRefs.extract({
    workspaceId,
    sourceEntryId: host.id,
    sourceEntryType: host.type,
    bodyJson: host.bodyJson,
    fieldsExt: {},
  });
  await deps.entryRefsRepo.replaceForSource({ workspaceId, sourceEntryId: host.id, refs });
}

/** A `widgetEmbed` host is either a custom content-type `entries` row (the original host table) or
 *  a `posts` row (REQ-44) — a Post/Page is NOT an `entries` row (`resolver-service.ts:60-67`
 *  documents this same split for the render-time lookup this mirrors on the write side). Checked
 *  entries-first so every existing entries-host behavior stays byte-identical (D1); IDs are UUIDs,
 *  so a same-id collision across the two tables is not a realistic case. */
type EmbedHost = { kind: "entry"; record: EntryRecord } | { kind: "post"; record: PostRecord };

async function loadEmbedHost(deps: EmbedServiceDeps, workspaceId: UUID, hostEntryId: UUID): Promise<EmbedHost> {
  const entry = await deps.entryRepo.findById({ workspaceId, id: hostEntryId });
  if (entry) {
    if (entry.type === WIDGET_AREA_CONTENT_TYPE) {
      // REQ-17 (D4) — a widget_area entry is itself a region's composition document; it must never
      // also be a widgetEmbed host (no recursion into a region from inside a region).
      throw new WidgetEmbedHostUnsupportedError({ message: `host '${hostEntryId}' is a widget_area entry, which can never host a widgetEmbed node`, reason: "widget-area" }
      );
    }
    return { kind: "entry", record: entry };
  }

  const post = await deps.postRepo.findById({ workspaceId, id: hostEntryId });
  if (!post || deps.host.posts.isTrashed(post)) {
    throw new WidgetEmbedHostNotFoundError({ message: `host entry '${hostEntryId}' was not found in workspace '${workspaceId}' (it must be the id of an existing, non-trashed post, page, or content entry)` }
    );
  }
  if (post.bodyFormat === "html") {
    // An html-format Page (SPEC-047) has no Tiptap body — `data-embed-config` markers are its embed
    // mechanism instead (`html-embeds.ts`), not a `widgetEmbed` node.
    throw new WidgetEmbedHostUnsupportedError({ message: `host '${hostEntryId}' is an HTML-format page, which has no rich-text body for widgetEmbed nodes; embed widgets in it with a data-embed-config marker of type "widget" via pages_write_region or pages_write_html instead`, reason: "html-page" }
    );
  }
  return { kind: "post", record: post };
}

/** The content/entity type `assertGuardrails` validates against — an entry's registered content
 *  type for an entries host, or the post/page `kind` for a posts-table host. */
function hostBodyType(host: EmbedHost): string {
  return host.kind === "entry" ? host.record.type : host.record.kind;
}

/**
 * REQ-16/17 (Fable adversarial-review fix, 2026-07-21, Finding E): mirrors
 * `region-area-service.ts`'s identical REQ-16 placement check, previously asymmetric — a region
 * placement referencing a nonexistent/trashed/wrong-type widget was rejected before any write, but
 * `insertWidgetEmbed` inserted the embed node regardless, silently degrading to the render-time
 * placeholder instead of failing at write time the way region placement does. Also enforces REQ-17
 * (a `widget_area` entry must never itself be an embed target) via the same `type !==
 * WIDGET_CONTENT_TYPE` check region placement already uses to exclude it.
 */
async function assertEmbedTargetIsLiveWidget(deps: EmbedServiceDeps, workspaceId: UUID, widgetEntryId: UUID): Promise<void> {
  const widget = await deps.entryRepo.findById({ workspaceId, id: widgetEntryId });
  if (!widget || widget.type !== WIDGET_CONTENT_TYPE) {
    throw new WidgetInstanceNotFoundError({ message: `embed references widget '${widgetEntryId}', which does not exist in workspace '${workspaceId}'` });
  }
  const payload = parseWidgetInstancePayload({ fieldsJson: widget.fieldsJson });
  if (payload.status === "trash" || payload.status === "purged") {
    throw new WidgetInstanceNotFoundError({ message: `embed references widget '${widgetEntryId}', which is trashed` });
  }
}

/** REQ-19/20: validates the resulting embed set BEFORE writing — the same guardrail the live
 * editor's own chokepoint-side hook must call (INV-04), never bypassable from this path. */
function assertGuardrails(deps: EmbedServiceDeps, hostEntryType: string, resultingBodyJson: unknown): void {
  const resultingEmbeds: WidgetEmbedNode[] = [];
  collectEmbeds(resultingBodyJson, resultingEmbeds);
  const result = validateWidgetEmbedMutation({
    hostEntryType,
    resultingEmbeds,
    maxEmbedsPerDocument: deps.maxEmbedsPerDocument ?? DEFAULT_MAX_EMBEDS_PER_DOCUMENT,
  });
  if (!result.valid) {
    throw new WidgetEmbedGuardrailError({ message: `widgetEmbed mutation on host entry rejected: ${result.reason}`, reason: result.reason }
    );
  }
}

async function writeHostBody(
  deps: EmbedServiceDeps,
  workspaceId: UUID,
  actor: { principalId: UUID },
  current: EntryRecord,
  baseVersion: number,
  nextBodyJson: unknown
): Promise<EntryRecord> {
  const result = await deps.host.entries.updateEntry({
    deps: {
      entryRepo: deps.entryRepo,
      contentTypeRepo: deps.contentTypeRepo,
      clock: deps.clock,
      authorize: PRE_AUTHORIZED,
      // Bridges the raw, full-`DomainEvent` infra port (`EmbedServiceDeps.outbox`) into the
      // narrower `{enqueue({name,payload})}` shape `updateEntry` declares locally — same fix,
      // same reasoning as `write-service.ts`'s `entriesWriteDeps` helper (only one call site
      // here, so inlined rather than factored out). Previously `deps.outbox` was forwarded
      // unwrapped, which compiled but threw `NOT NULL constraint failed: outbox_events.id`
      // against the real SQLite outbox on every embed insert/remove/reorder.
      outbox: deps.host.entries.toEntryOutbox({ outbox: deps.outbox, clock: deps.clock, idGen: deps.ids, workspaceId }),
      onWritten: (entry) => extractAndStoreEmbedRefs(deps, workspaceId, entry),
    },
    input: {
      actorId: actor.principalId,
      workspaceId,
      id: current.id,
      bodyJson: nextBodyJson,
      expectedVersion: baseVersion,
    },
  });
  if (!result.ok) {
    if (deps.host.entries.isVersionConflict(result.error)) {
      const latest = await deps.entryRepo.findById({ workspaceId, id: current.id });
      throw new WidgetVersionConflictError({ message: result.error.message, currentVersion: latest?.version ?? current.version });
    }
    throw result.error;
  }
  return result.value.entry;
}

/** REQ-44's post/page host arm — writes through the SAME command-gateway + `updatePost` chokepoint
 *  the live TipTap editor's own Save path uses (`routes/posts/update.ts`), so a post/page embed
 *  mutation gets an identical change-set/rollback unit of work (ADR-047 Amendment 6, D2). Only
 *  `bodyJson` actually changes; every other field travels through unchanged from `current`.
 *
 *  Unlike the entries arm above — which re-extracts `entry_refs` inside `updateEntry`'s `onWritten`,
 *  within that chokepoint's own transaction — the refs refresh here runs AFTER `executeCommand` has
 *  committed, because the command gateway exposes no in-transaction hook. A refs write that fails
 *  therefore leaves the post saved with stale refs (where-used over-reports, and the non-force purge
 *  guard fails safe by blocking). Accepted, not overlooked. */
async function writePostHostBody(
  deps: EmbedServiceDeps,
  workspaceId: UUID,
  actor: { principalId: UUID; kind: string },
  current: PostRecord,
  baseVersion: number,
  nextBodyJson: unknown
): Promise<PostRecord> {
  let priorPost: PostRecord | null = null;
  try {
    const { result } = await executeCommand({
      deps: {
        clock: deps.clock,
        idGen: deps.ids,
        changeSets: deps.changeSets,
        outbox: deps.outbox,
        authorize: deps.authorize,
      },
      command: {
        workspaceId,
        actor: { id: actor.principalId, kind: actor.kind as CommandActor["kind"] },
        summary: `Update widgetEmbed placements on post ${current.id}`,
        permission: "content.write",
      },
      mutation: {
        entityType: "post",
        entityId: current.id,
        operation: "update",
        captureInverse: async () => {
          priorPost = await deps.postRepo.findById({ workspaceId, id: current.id });
          if (!priorPost) return null;
          return {
            title: priorPost.title,
            slug: priorPost.slug,
            bodyJson: priorPost.bodyJson,
            status: priorPost.status,
            templateChoice: priorPost.templateChoice ?? null,
            overridesThemePage: priorPost.overridesThemePage ?? null,
            ...(priorPost.ext !== undefined ? { ext: priorPost.ext } : {}),
          };
        },
        execute: () =>
          deps.host.posts.updatePost({
            deps: {
              repo: deps.postRepo,
              clock: deps.clock,
              outbox: deps.outbox,
              beforeSaveHook: deps.beforeSaveHook,
            },
            input: {
              workspaceId,
              id: current.id,
              title: current.title,
              slug: current.slug,
              status: current.status,
              bodyJson: nextBodyJson as JsonObject,
              expectedVersion: baseVersion,
              actorId: actor.principalId,
              // `actor.kind` is this call's real provenance ("user" for the admin HTTP routes,
              // "agent" for the widget tool surface — see `InsertWidgetEmbedInput.actor`'s own
              // doc). Only a non-"user" kind is delegated — mirrors `tool-registrations.ts`'s
              // identical delegatedBy* convention for `post_revisions` attribution.
              delegatedByWorkspaceId: actor.kind === "user" ? undefined : workspaceId,
              delegatedById: actor.kind === "user" ? undefined : actor.principalId,
            },
          }),
        captureEntityVersion: ({ result }) => result.post.version,
        rollback: async () => {
          if (!priorPost) return;
          await deps.host.posts.restorePostForward({
            deps: {
              repo: deps.postRepo,
              clock: deps.clock,
              outbox: deps.outbox,
              forgetRemoved: deps.forgetRemovedPost,
            },
            input: {
              prior: priorPost,
              actorId: actor.principalId,
              // Mirrors the forward write's own delegatedBy* convention just above.
              delegatedByWorkspaceId: actor.kind === "user" ? undefined : workspaceId,
              delegatedById: actor.kind === "user" ? undefined : actor.principalId,
            },
          });
        },
      },
    });
    await extractAndStoreEmbedRefs(deps, workspaceId, { id: result.post.id, type: result.post.kind, bodyJson: result.post.bodyJson });
    return result.post;
  } catch (err) {
    if (deps.host.posts.isVersionConflict(err)) {
      throw new WidgetVersionConflictError({ message: err.message, currentVersion: err.currentVersion });
    }
    if (deps.host.posts.isNotFound(err)) {
      // Trash race between `loadEmbedHost`'s check and this write — same not-found shape either way.
      throw new WidgetEmbedHostNotFoundError({ message: `host entry '${current.id}' was not found in workspace '${workspaceId}' (it must be the id of an existing, non-trashed post, page, or content entry)` }
      );
    }
    if (err instanceof ForbiddenError) {
      // Reformatted to match `authorize-helper.ts`'s `requireWidgetPermission` wording (not
      // `executeCommand`'s own message verbatim) so `widgetForbiddenToResponse`'s regex extracts
      // `permission`/`reason` identically regardless of which of the two gates rejected the caller.
      throw new WidgetForbiddenError({ message: `principal '${actor.principalId}' lacks permission 'content.write' (${err.reason})` });
    }
    throw err;
  }
}

/** Writes `nextBodyJson` through the chokepoint of whichever table the host lives in. */
function writeEmbedHost({ deps, input, host, nextBodyJson }: {
  deps: EmbedServiceDeps;
  input: { workspaceId: UUID; actor: { principalId: UUID; kind: string }; baseVersion: number };
  host: EmbedHost;
  nextBodyJson: unknown;
}, _optional: Record<string, never> = {}): Promise<EntryRecord | PostRecord> {
  return host.kind === "entry"
    ? writeHostBody(deps, input.workspaceId, input.actor, host.record, input.baseVersion, nextBodyJson)
    : writePostHostBody(deps, input.workspaceId, input.actor, host.record, input.baseVersion, nextBodyJson);
}

export interface InsertWidgetEmbedInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID; readonly kind: string };
  readonly hostEntryId: UUID;
  readonly baseVersion: number;
  readonly widgetEntryId: UUID;
}

export interface InsertWidgetEmbedRequired {
  deps: EmbedServiceDeps;
  input: InsertWidgetEmbedInput;
}

/** REQ-44/45: inserts a new `widgetEmbed` node referencing `widgetEntryId`, appended to the host
 * entry's body — one atomic, version-guarded write through the same chokepoint the live editor's
 * Save uses. Returns the newly-minted `placementId` so the caller (an agent tool, or the
 * server-side embed-mutation routes) can address this exact placement afterward. */
export async function insertWidgetEmbed(required: InsertWidgetEmbedRequired, _optional: Record<string, never> = {}): Promise<{ entry: EntryRecord | PostRecord; placementId: UUID }> {
  const { deps, input } = required;
  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.place",
  });

  return withEntryLock({ key: `${input.workspaceId}::${input.hostEntryId}`, fn: async () => {
    const host = await loadEmbedHost(deps, input.workspaceId, input.hostEntryId);
    await assertEmbedTargetIsLiveWidget(deps, input.workspaceId, input.widgetEntryId);
    const placementId = deps.ids.newId();
    const nextBodyJson = appendEmbed(host.record.bodyJson, placementId, input.widgetEntryId);
    assertGuardrails(deps, hostBodyType(host), nextBodyJson);
    const entry = await writeEmbedHost({ deps, input, host, nextBodyJson });
    return { entry, placementId };
  } }, deps.entryLocks ? { locks: deps.entryLocks } : {});
}

export interface RemoveWidgetEmbedInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID; readonly kind: string };
  readonly hostEntryId: UUID;
  readonly baseVersion: number;
  readonly placementId: UUID;
}

export interface RemoveWidgetEmbedRequired {
  deps: EmbedServiceDeps;
  input: RemoveWidgetEmbedInput;
}

/** REQ-44/45: removes the `widgetEmbed` node matching `placementId` from the host entry's body —
 * the placement itself is removed (the widget instance it referenced is untouched). */
export async function removeWidgetEmbed(required: RemoveWidgetEmbedRequired, _optional: Record<string, never> = {}): Promise<{ entry: EntryRecord | PostRecord }> {
  const { deps, input } = required;
  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.place",
  });

  return withEntryLock({ key: `${input.workspaceId}::${input.hostEntryId}`, fn: async () => {
    const host = await loadEmbedHost(deps, input.workspaceId, input.hostEntryId);
    if (!containsEmbedWithPlacementId({ node: host.record.bodyJson, placementId: input.placementId })) {
      // C4d fix: `removeEmbedByPlacementId` is a no-op filter — without this check a stale/bogus
      // placementId fell through to `writeHostBody` unchanged and reported success while writing
      // nothing.
      throw new WidgetEmbedPlacementNotFoundError({ message: `no widget embed with placementId '${input.placementId}' was found in host '${input.hostEntryId}'` }
      );
    }
    const nextBodyJson = removeEmbedByPlacementId({ node: host.record.bodyJson, placementId: input.placementId });
    assertGuardrails(deps, hostBodyType(host), nextBodyJson);
    const entry = await writeEmbedHost({ deps, input, host, nextBodyJson });
    return { entry };
  } }, deps.entryLocks ? { locks: deps.entryLocks } : {});
}

export interface ReorderWidgetEmbedsInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID; readonly kind: string };
  readonly hostEntryId: UUID;
  readonly baseVersion: number;
  /** The new widget-entry order, one id per EXISTING embed slot in the host's body, in document
   * order — must be the same length as the number of `widgetEmbed` nodes currently present. */
  readonly orderedWidgetEntryIds: readonly UUID[];
}

export interface ReorderWidgetEmbedsRequired {
  deps: EmbedServiceDeps;
  input: ReorderWidgetEmbedsInput;
}

export class WidgetEmbedReorderCountMismatchError extends Error {
  readonly expectedCount: number;
  readonly actualCount: number;
  constructor({ message, expectedCount, actualCount }: { message: string; expectedCount: number; actualCount: number }, _optional: Record<string, never> = {}
  ) {
    super(message);
    this.expectedCount = expectedCount;
    this.actualCount = actualCount;
    this.name = "WidgetEmbedReorderCountMismatchError";
  }
}

/** REQ-44/45: reassigns which widget occupies which existing embed slot, in document order — the
 * document's own shape (slot count/position, surrounding content) is unchanged. Rejects a count
 * mismatch before writing anything (the caller must supply exactly one id per existing slot). */
export async function reorderWidgetEmbeds(required: ReorderWidgetEmbedsRequired, _optional: Record<string, never> = {}): Promise<{ entry: EntryRecord | PostRecord }> {
  const { deps, input } = required;
  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.place",
  });

  return withEntryLock({ key: `${input.workspaceId}::${input.hostEntryId}`, fn: async () => {
    const host = await loadEmbedHost(deps, input.workspaceId, input.hostEntryId);

    const existing: WidgetEmbedNode[] = [];
    collectEmbeds(host.record.bodyJson, existing);
    if (existing.length !== input.orderedWidgetEntryIds.length) {
      throw new WidgetEmbedReorderCountMismatchError({ message: `reorder must supply exactly one widgetEntryId per existing embed slot (${existing.length} present, ${input.orderedWidgetEntryIds.length} supplied)`, expectedCount: existing.length, actualCount: input.orderedWidgetEntryIds.length }
      );
    }

    // Round-2 external-audit fix (2026-07-21, codex WIDGETS-R2-001/blocker): reorder assigns NEW
    // widgetEntryId values to slots (see reorderEmbedSlots below) exactly like insertWidgetEmbed
    // does, but never got the same REQ-16/17 target-existence/liveness/type check — an authorized
    // widgets.place caller could persist a nonexistent, wrong-type, trashed, or cross-workspace id
    // (codex reproduced both a numeric id and a dangling entry_refs row for "does-not-exist").
    // Every distinct replacement target is validated before the host document or entry_refs change.
    for (const widgetEntryId of new Set(input.orderedWidgetEntryIds)) {
      if (typeof widgetEntryId !== "string" || widgetEntryId.length === 0) {
        throw new WidgetInstanceNotFoundError({ message: "reorder contains an invalid widgetEntryId" });
      }
      await assertEmbedTargetIsLiveWidget(deps, input.workspaceId, widgetEntryId);
    }

    const nextBodyJson = reorderEmbedSlots({ node: host.record.bodyJson, newIds: () => deps.ids.newId(), orderedWidgetEntryIds: input.orderedWidgetEntryIds });
    assertGuardrails(deps, hostBodyType(host), nextBodyJson);
    const entry = await writeEmbedHost({ deps, input, host, nextBodyJson });
    return { entry };
  } }, deps.entryLocks ? { locks: deps.entryLocks } : {});
}

import { escapeHtml } from '@jini-ai/core/text';
import type { JsonObject } from '@jini-ai/core/primitives';
import { parseEmbedHtmlAttributes } from '../markers/html-attributes.js';
import { parseGalleryConfig, type GalleryConfig, type GalleryImage } from '../markers/gallery.js';

/** Layout-only baseline; host themes override jini classes/custom properties without palette coupling. */
export const GALLERY_STYLE = `<style data-jini-gallery-style>
.jini-gallery{gap:var(--jini-gallery-gap,1rem)}
.jini-gallery-item{margin:0;min-width:0;break-inside:avoid}
.jini-gallery audio{display:block;width:100%}
.jini-gallery img,.jini-gallery video{display:block;width:100%;height:auto;aspect-ratio:var(--jini-gallery-ratio,auto);object-fit:cover}
.jini-gallery-single{display:grid;grid-template-columns:1fr}
.jini-gallery-grid{display:grid;grid-template-columns:repeat(var(--jini-gallery-columns,3),minmax(0,1fr))}
.jini-gallery-masonry{columns:var(--jini-gallery-columns,3);column-gap:var(--jini-gallery-gap,1rem)}
.jini-gallery-masonry .jini-gallery-item{margin-block-end:var(--jini-gallery-gap,1rem)}
.jini-gallery-carousel{display:flex;overflow-x:auto;scroll-snap-type:x mandatory}
.jini-gallery-carousel .jini-gallery-item{flex:0 0 min(85%,36rem);scroll-snap-align:start}
@media(max-width:48rem){.jini-gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.jini-gallery-masonry{columns:2}}
@media(max-width:30rem){.jini-gallery-grid{grid-template-columns:1fr}.jini-gallery-masonry{columns:1}}
</style>`;

export type GalleryImageRenderer = (required: { image: GalleryImage & { alt: string }; media: JsonObject | undefined }, optional?: Record<string, never>) => string;
type GalleryRawHtmlRenderer = (required: { html: string; media: Record<string, JsonObject> }, optional?: Record<string, never>) => string;

function mediaRecords(media: unknown): Record<string, JsonObject> {
  return typeof media === 'object' && media !== null && !Array.isArray(media) ? media as Record<string, JsonObject> : {};
}

/** Own-property lookup only, so a slug such as `toString` never resolves to an inherited member. */
function recordFor({ key, records }: { key: string | undefined; records: Record<string, JsonObject> }): JsonObject | undefined {
  return key !== undefined && Object.hasOwn(records, key) ? records[key] : undefined;
}

function storedAlt(media: JsonObject | undefined): string | undefined {
  return typeof media?.alt === 'string' && media.alt.length > 0 ? media.alt : undefined;
}

/** Render one ordered figure using the host's established image renderer and alt fallback.
 * Missing alt is flagged in markup as well as validation; an explicit empty alt stays decorative.
 */
function renderFigure({ image, records, renderImage }: { image: GalleryImage; records: Record<string, JsonObject>; renderImage: GalleryImageRenderer }): string {
  const key = image.slug ?? image.mediaId;
  const media = recordFor({ key, records });
  if (key !== undefined && !media) return '';
  const alt = image.alt ?? storedAlt(media);
  const missingAlt = alt === undefined ? ' data-jini-alt-missing="true"' : '';
  const markup = renderImage({ image: { ...image, alt: alt ?? '' }, media });
  const caption = image.caption === undefined ? '' : `<figcaption>${escapeHtml({ text: image.caption })}</figcaption>`;
  return `<figure class="jini-gallery-item"${missingAlt}>${markup}${caption}</figure>`;
}

function emptyGalleryNote(gallery: GalleryConfig): string {
  // Media-mode configs come from the Media widget editor; naming the Gallery editor there misleads.
  return `<div class="jini-gallery jini-gallery-empty" role="note">${gallery.mode === 'media' ? 'Choose media in the Media widget editor.' : 'Choose images in the Gallery widget editor.'}</div>`;
}

/** Wrapper attributes in emission order, with class and style split out for merging into the base. */
function wrapperAttributes(gallery: GalleryConfig): { extra: string; extraClass: string; authoredStyle: string | undefined } {
  // TODO: bind data-jini-lightbox through a host theme's lightbox script slot when one exists.
  // Until then the gallery stays readable and keyboard-scrollable without any client script.
  const attributes: Record<string, string> = {
    role: 'region', 'aria-label': gallery.mode === 'media' ? 'Media' : 'Image gallery',
    ...(gallery.layout === 'carousel' ? { tabindex: '0', 'aria-roledescription': 'carousel' } : {}),
    ...(gallery.lightbox === true ? { 'data-jini-lightbox': 'true' } : {}),
    ...parseEmbedHtmlAttributes({ text: gallery.htmlAttributes ?? '' }).attributes,
  };
  const extraClass = [gallery.cssClass, attributes.class].filter(Boolean).join(' ');
  delete attributes.class;
  // Layout styles remain the base; authored safe style declarations override them in order.
  const authoredStyle = attributes.style;
  delete attributes.style;
  const extra = Object.entries(attributes).map(([name, value]) => ` ${name}="${escapeHtml({ text: value })}"`).join('');
  return { extra, extraClass, authoredStyle };
}

function renderGalleryWrapper({ gallery, figures }: { gallery: GalleryConfig; figures: string }): string {
  const { extra, extraClass, authoredStyle } = wrapperAttributes(gallery);
  const ratio = gallery.aspectRatio === undefined ? '' : `;--jini-gallery-ratio:${gallery.aspectRatio}`;
  const className = `jini-gallery jini-gallery-${gallery.layout}${extraClass ? ` ${escapeHtml({ text: extraClass })}` : ''}`;
  const style = `--jini-gallery-columns:${gallery.columns ?? 3}${ratio}${authoredStyle ? `;${escapeHtml({ text: authoredStyle })}` : ''}`;
  return GALLERY_STYLE + `<div class="${className}"${extra} style="${style}">${figures}</div>`;
}

/** Server-render accessible gallery markup. Image URLs, metadata and srcset belong to the host
 * image pipeline supplied as a port, never templated here. Invalid config produces no output.
 * @complexity O(n) time and output space for at most 50 images, without I/O.
 */
export function renderGallery(
  { config, media, renderImage, renderRawHtml }: { config: unknown; media?: unknown; renderImage: GalleryImageRenderer; renderRawHtml?: GalleryRawHtmlRenderer },
  _optional: Record<string, never> = {},
): string {
  const gallery = parseGalleryConfig({ config }, { allowEmpty: true }).config;
  if (!gallery) return '';
  const records = mediaRecords(media);
  // parseGalleryConfig only admits html mode with a string `html`, so the cast cannot widen.
  if (gallery.mode === 'html') return renderRawHtml?.({ html: gallery.html as string, media: records }) ?? '';
  if (gallery.images.length === 0) return emptyGalleryNote(gallery);
  const figures = gallery.images.map(image => renderFigure({ image, records, renderImage })).join('');
  return renderGalleryWrapper({ gallery, figures });
}

import { decodeMarkerHtmlAttribute } from './marker.js';
import { isPlausibleMediaRefId } from './media-reference.js';

/** Inline gallery configuration; media resolution remains owned by the media embed pipeline. */
export interface GalleryImage {
  readonly mediaId?: string;
  readonly slug?: string;
  readonly src?: string;
  readonly alt?: string;
  readonly caption?: string;
}

export interface GalleryConfig {
  readonly images: readonly GalleryImage[];
  readonly layout: 'single' | 'grid' | 'carousel' | 'masonry';
  readonly mode?: 'media' | 'html';
  readonly html?: string;
  readonly htmlAttributes?: string;
  readonly cssClass?: string;
  readonly columns?: number;
  readonly aspectRatio?: string;
  readonly lightbox?: boolean;
}

export const MAX_GALLERY_IMAGES = 50;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Same bounded, single-path-segment contract the media resolver accepts. No I/O. */
function validMediaId(value: unknown): value is string {
  return isPlausibleMediaRefId({ value });
}

/** Native URL parsing validates browser-loaded sources; hosts may enforce stricter URL policy. */
function validSource(value: unknown): value is string {
  if (typeof value !== 'string' || value.length === 0 || value.length > 2048) return false;
  try {
    const url = new URL(value);
    return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password;
  } catch {
    return false;
  }
}

/** Numeric CSS ratio only: prevents configuration text becoming arbitrary CSS declarations. */
function validRatio(value: unknown): value is string {
  if (typeof value !== 'string' || !/^\d+(?:\.\d+)?(?:\s*\/\s*\d+(?:\.\d+)?)?$/.test(value)) return false;
  return value.split('/').every(part => Number.isFinite(Number(part)) && Number(part) > 0);
}

const ASPECT_RATIO_ERROR = 'aspectRatio must be a positive number or ratio such as 16/9';
const LEGACY_LAYOUTS: readonly string[] = ['grid', 'carousel', 'masonry'];
const MEDIA_LAYOUTS: readonly string[] = ['single', ...LEGACY_LAYOUTS];

/** `${path}.alt`/`${path}.caption` (or bare `${key}` with no path) type errors for optional text fields. */
function stringFieldErrors({ record, keys }: { record: Record<string, unknown>; keys: readonly string[] }, { path }: { path?: string } = {}): string[] {
  return keys.filter(key => record[key] !== undefined && typeof record[key] !== 'string')
    .map(key => `${path === undefined ? '' : `${path}.`}${key} must be a string`);
}

/** Columns are optional; when present they must be an integer in [min, 6]. */
function invalidColumns({ columns }: { columns: unknown }, { min }: { min: number }): boolean {
  return columns !== undefined && (!Number.isInteger(columns) || Number(columns) < min || Number(columns) > 6);
}

function invalidAspectRatio(value: unknown): boolean {
  return value !== undefined && !validRatio(value);
}

/** Validate one image independently so a bad sibling never hides another image's diagnostics. */
function imageErrors(value: unknown, index: number): string[] {
  const path = `images[${index}]`;
  if (!isRecord(value)) return [`${path} must be an object`];
  const errors: string[] = [];
  if ((value.mediaId !== undefined) === (value.src !== undefined)) errors.push(`${path} requires exactly one of mediaId or src`);
  if (value.mediaId !== undefined && !validMediaId(value.mediaId)) errors.push(`${path}.mediaId must be a nonempty media id of at most 200 characters, without slashes or whitespace`);
  if (value.src !== undefined && !validSource(value.src)) errors.push(`${path}.src must be an HTTP(S) image URL without credentials, at most 2048 characters`);
  errors.push(...stringFieldErrors({ record: value, keys: ['alt', 'caption'] }, { path }));
  return errors;
}

function missingAltWarnings(images: readonly unknown[]): string[] {
  return images.flatMap((image, index) => isRecord(image) && image.alt === undefined
    ? [`images[${index}].alt is missing; supply alt text or an explicit empty string for a decorative image`] : []);
}

function validImageCount(images: unknown, { allowEmpty }: { allowEmpty: boolean }): images is unknown[] {
  return Array.isArray(images) && (allowEmpty || images.length > 0) && images.length <= MAX_GALLERY_IMAGES;
}

function legacyOptionErrors(config: Record<string, unknown>): string[] {
  const errors: string[] = [];
  if (typeof config.layout !== 'string' || !LEGACY_LAYOUTS.includes(config.layout)) errors.push('layout must be grid, carousel or masonry');
  if (invalidColumns({ columns: config.columns }, { min: 2 })) errors.push('columns must be an integer between 2 and 6');
  if (invalidAspectRatio(config.aspectRatio)) errors.push(ASPECT_RATIO_ERROR);
  if (config.lightbox !== undefined && typeof config.lightbox !== 'boolean') errors.push('lightbox must be a boolean');
  return errors;
}

/** Pure validation result, with missing-alt warnings separate from fatal configuration errors.
 * Explicit alt="" denotes decorative content. Unknown keys remain available to host authoring.
 * @complexity O(n) time and space for at most 50 images; oversized arrays are rejected before walking.
 */
export function parseGalleryConfig({ config }: { config: unknown }, { allowEmpty = false }: { allowEmpty?: boolean } = {}): {
  config?: GalleryConfig;
  errors: string[];
  warnings: string[];
} {
  if (!isRecord(config)) return { errors: ['gallery config must be an object'], warnings: [] };
  if (config.mode !== undefined || config.items !== undefined || config.html !== undefined) return parseMediaContent({ config });
  const images = config.images;
  if (!validImageCount(images, { allowEmpty })) {
    return { errors: [`images must contain between 1 and ${MAX_GALLERY_IMAGES} images`], warnings: [] };
  }
  const errors = [...images.flatMap(imageErrors), ...legacyOptionErrors(config)];
  const warnings = missingAltWarnings(images);
  if (errors.length > 0) return { errors, warnings };
  return { config: config as unknown as GalleryConfig, errors, warnings };
}

/** Authored items, else legacy images, else nothing. */
function authoredItems(config: Record<string, unknown>): readonly unknown[] {
  if (Array.isArray(config.items)) return config.items;
  return Array.isArray(config.images) ? config.images : [];
}

/** References describe authored intent even when another config field is invalid. Do not gate
 * safe-delete or export on successful rendering: that would hide the broken page needing protection.
 * Images beyond the renderable image cap cannot render and do not expand the reference index.
 * @complexity O(min(n,50)) time and space over the authored image list; no I/O or resolution.
 */
export function galleryMediaReferences({ config }: { config: unknown }, _optional: Record<string, never> = {}): readonly { mediaId: string; index: number }[] {
  if (!isRecord(config)) return [];
  const refs: { mediaId: string; index: number }[] = [];
  for (const [index, item] of authoredItems(config).slice(0, MAX_GALLERY_IMAGES).entries()) {
    const key = isRecord(item) ? item.slug ?? item.mediaId : undefined;
    if (validMediaId(key)) refs.push({ mediaId: key, index });
  }
  if (typeof config.html === 'string') {
    for (const key of mediaHtmlSlugs({ html: config.html })) refs.push({ mediaId: key, index: refs.length });
  }
  if (isRecord(config.content)) refs.push(...galleryMediaReferences({ config: config.content }));
  return refs;
}

function mediaItemErrors(item: unknown, index: number): string[] {
  const path = `items[${index}]`;
  if (!isRecord(item)) return [`${path} must be an object`];
  const errors: string[] = [];
  if (!validMediaId(item.slug)) errors.push(`${path}.slug must be a nonempty slug of at most 200 characters without slashes or whitespace`);
  if (item.src !== undefined || item.mediaId !== undefined) errors.push(`${path} uses slug, never src or mediaId`);
  errors.push(...stringFieldErrors({ record: item, keys: ['alt', 'caption'] }, { path }));
  return errors;
}

function mediaOptionErrors(config: Record<string, unknown>): string[] {
  const errors: string[] = [];
  if (!MEDIA_LAYOUTS.includes(config.layout as string ?? 'single')) errors.push('layout must be single, grid, carousel or masonry');
  if (invalidColumns({ columns: config.columns }, { min: 1 })) errors.push('columns must be an integer between 1 and 6');
  if (invalidAspectRatio(config.aspectRatio)) errors.push(ASPECT_RATIO_ERROR);
  return errors;
}

function parseHtmlContent({ config, errors }: { config: Record<string, unknown>; errors: string[] }): ReturnType<typeof parseGalleryConfig> {
  if (typeof config.html !== 'string' || config.html.length > 65536) errors.push('html must be a string of at most 65536 characters');
  return errors.length ? { errors, warnings: [] } : { config: { ...config, mode: 'html', images: [], layout: 'single' }, errors, warnings: [] };
}

function parseMediaItems({ config, errors }: { config: Record<string, unknown>; errors: string[] }): ReturnType<typeof parseGalleryConfig> {
  const items = config.items;
  if (!Array.isArray(items) || items.length > MAX_GALLERY_IMAGES) return { errors: ['items must be an array of at most 50 slug items'], warnings: [] };
  errors.push(...items.flatMap(mediaItemErrors), ...mediaOptionErrors(config));
  if (errors.length) return { errors, warnings: [] };
  // Validated above: every item is a record and the layout is one of MEDIA_LAYOUTS.
  const layout = (config.layout ?? 'single') as GalleryConfig['layout'];
  const normalized: GalleryConfig = { ...config, mode: 'media', images: [...items] as GalleryImage[], layout };
  return { config: normalized, errors, warnings: [] };
}

/** Normalize the new slug-first content into the existing gallery render contract. Legacy images
 * remain read-only compatibility input; authored media items never accept raw URLs. O(n), n<=50. */
function parseMediaContent({ config }: { config: Record<string, unknown> }): ReturnType<typeof parseGalleryConfig> {
  const mode = config.mode ?? (config.html !== undefined ? 'html' : 'media');
  const errors = mode === 'media' || mode === 'html' ? [] : ['mode must be media or html'];
  errors.push(...stringFieldErrors({ record: config, keys: ['htmlAttributes', 'cssClass'] }));
  return mode === 'html' ? parseHtmlContent({ config, errors }) : parseMediaItems({ config, errors });
}

/** Authored slug references, independent of render validity. Tokens and quoted data attributes
 * share the media reference key rules. Marker values are already entity-decoded by the scanner. */
export function mediaHtmlSlugs({ html }: { html: string }, _optional: Record<string, never> = {}): readonly string[] {
  const keys: string[] = [];
  for (const match of html.matchAll(/\{\{media:([^{}]+)\}\}/g)) {
    const key = decodeMarkerHtmlAttribute({ value: match[1]! });
    if (validMediaId(key)) keys.push(key);
  }
  for (const match of html.matchAll(/\bdata-media-slug\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/gi)) {
    // Exactly one of the three value alternatives (double-quoted, single-quoted, bare) always matches.
    const key = decodeMarkerHtmlAttribute({ value: (match[1] ?? match[2] ?? match[3])! });
    if (validMediaId(key)) keys.push(key);
  }
  return keys;
}

/**
 * @file The ONE render-time HTML-attribute allowlist for every free-text `htmlAttributes` field this
 * codebase re-parses at render time: media assets, media post-nodes, and (from this task on) widget
 * post-nodes (2026-09-23 embed-attributes-everywhere plan, decision §2). It replaces two prior,
 * narrower boundaries in the same render path:
 *
 * - `@jini-ai/cms/media`'s `parseMediaHtmlAttributes` (the Jini-side twin of
 *   the media admin `parseMediaHtmlAttributes` adapter, which this file's
 *   tokenizer and name pattern are ported from) — rejected `style`/`id`/`class` outright and failed
 *   the WHOLE string closed on the first bad token.
 * - `render.ts`'s own `restrictToDataAriaAttributes` — an extra widget-only restriction down to
 *   `data-*`/`aria-*`, now folded into this one list instead of being a second filter layered on top.
 *
 * Two behavior changes from that prior boundary, both owner-directed:
 * 1. **The allowlist widens** to include `class`, `id`, `style`, `title`, `role`, `tabindex`, `lang`,
 *    `dir`, `hidden`, `translate` and `draggable` — global HTML attributes an author styling or
 *    animating a widget/media embed needs — on top of the open-ended `data-*`/`aria-*` families and
 *    today's `<img>`/`<video>`-only extras (`loading`, `decoding`, `playsinline`, `muted`, `loop`,
 *    `autoplay`, `poster`). One shared list for every element shape, not a list per tag: the owner
 *    rejected per-element name filtering (an extra `loading` on a `<div>` wrapper is harmless).
 * 2. **One bad token drops only that token**, not the whole string. Once a name/value pair has been
 *    tokenized, it is self-contained — dropping it cannot change how its neighbors are read — so
 *    `data-x="1" onclick="…" style="color:red"` keeps `data-x` and `style`, drops only `onclick`. The
 *    exception is `malformed`: the tokenizer itself lost sync (e.g. a stray quote), so token
 *    boundaries downstream of that point cannot be trusted (value text could re-parse as a name) —
 *    that failure mode still discards everything and fails the WHOLE string closed, same as before.
 *
 * The media admin adapter delegates to this browser-safe parser for UX hints, retaining its
 * own error messages. Hints never gate `save()` (incident `a7cce060`): a bad attribute must not
 * prevent saving unrelated metadata. The server independently enforces write/render policy;
 * the narrower CMS media write validator remains a separate boundary.
 */

/** Why one parsed attribute token was rejected. `unsafe-url` replaces the old `javascript-url` name
 *  (it now also covers `vbscript:`/`data:` schemes, not just `javascript:`) — the admin's own i18n
 *  message key for it is unchanged. `unsafe-style` is new: a `style` value carrying a known CSS
 *  injection/escape vector. `malformed` is the one reason that still discards the WHOLE parsed
 *  result, not just its own token — see this file's header for why. */
export type EmbedHtmlAttributeRejectionReason = "disallowed-name" | "event-handler" | "unsafe-url" | "unsafe-style" | "malformed";

export interface EmbedHtmlAttributeError {
  reason: EmbedHtmlAttributeRejectionReason;
  /** The exact attribute name (or, for `malformed`, the unparsable fragment) a caller's error
   *  message must name — never a generic "invalid input". */
  attribute: string;
}

export interface ParsedEmbedHtmlAttributes {
  /** Lowercased attribute name -> value, for every token that WAS accepted. Never all-or-nothing
   *  except on `malformed` (see this file's header): a rejected token is simply absent here while
   *  every other accepted token in the same string still lands. A boolean attribute (`muted`,
   *  written with no `="..."`) maps to `""`. */
  attributes: Record<string, string>;
  /** Every rejection found, in the order encountered — zero or more. Unlike `attributes`, this is
   *  never reset to empty except that a `malformed` entry is always the last one recorded (parsing
   *  stops there). */
  errors: EmbedHtmlAttributeError[];
  /** The FIRST rejection in `errors`, or `null` when every token was accepted — kept as its own field
   *  for the existing admin-hint callers that only ever showed one reason at a time. */
  error: EmbedHtmlAttributeError | null;
}

/**
 * Exact-match attribute names accepted beyond the open-ended `data-`/`aria-` prefix families (see
 * {@link isAllowedEmbedHtmlAttributeName}). Two groups, kept in one flat list because the owner
 * rejected per-element filtering (§2): global attributes any element can carry (styling/animation/
 * a11y), and the pre-existing `<img>`/`<video>`-only extras that are harmless, if meaningless, on
 * any other element.
 */
export const EMBED_HTML_ATTRIBUTE_ALLOWED_NAMES = [
  // Global attributes.
  "class",
  "id",
  "style",
  "title",
  "role",
  "tabindex",
  "lang",
  "dir",
  "hidden",
  "translate",
  "draggable",
  // Pre-existing <img>/<video> extras, kept everywhere (one list, not one per element).
  "loading",
  "decoding",
  "playsinline",
  "muted",
  "loop",
  "autoplay",
  "poster",
] as const;

/**
 * The shape EVERY accepted attribute name must have, checked before allowlist membership
 * (2026-09-07 stored-XSS fix; the narrower `@jini-ai/cms/media` write validator also enforces
 * this name shape).
 *
 * The `data-`/`aria-` families below are open-ended by design — no fixed suffix list — so the
 * prefix check alone accepted whatever characters {@link HTML_ATTRIBUTE_TOKEN}'s name class
 * (`[^\s="']+`, which excludes only whitespace, `=` and quotes) let through. `<`, `>` and `/` are
 * all legal in that class, and the server renderer templating a name into ` name="value"` escapes
 * only the VALUE — so a stored `data-x><svg/onload=alert(1)` closed the `<img>` and opened a live
 * `<svg onload>` on the public page. Constraining the NAME to the characters a real HTML attribute
 * name can contain is what makes "the value is escaped" sufficient.
 */
const EMBED_HTML_ATTRIBUTE_NAME_PATTERN = /^[a-z][a-z0-9-]*$/;

/** Whether `name` is on the allowlist — a well-formed name ({@link EMBED_HTML_ATTRIBUTE_NAME_PATTERN})
 *  that is either an exact match against {@link EMBED_HTML_ATTRIBUTE_ALLOWED_NAMES} or carries a
 *  `data-`/`aria-` prefix. Case-insensitive, since HTML attribute names are themselves
 *  case-insensitive.
 *
 * @complexity O(n) in the name's length (one anchored regex test), then O(1).
 */
export function isAllowedEmbedHtmlAttributeName({ name }: { name: string }, _optional: Record<string, never> = {}): boolean {
  const lower = name.toLowerCase();
  if (!EMBED_HTML_ATTRIBUTE_NAME_PATTERN.test(lower)) return false;
  if (lower.startsWith("data-") || lower.startsWith("aria-")) return true;
  return (EMBED_HTML_ATTRIBUTE_ALLOWED_NAMES as readonly string[]).includes(lower);
}

/** The highest ASCII code point {@link isUnsafeUrlValue} strips: every C0 control character plus
 *  the ordinary space, i.e. code points `0`-`32` inclusive. Named rather than written as an inline
 *  regex control-character range so the linter never has to reason about a literal control
 *  character inside a pattern. */
const ASCII_WHITESPACE_OR_CONTROL_MAX_CODE_POINT = 0x20;

/**
 * Whether `value`'s scheme, once every ASCII whitespace/control character (code points `0`-`32`) is
 * stripped and the result lowercased, starts with `javascript:`, `vbscript:` or `data:` — the three
 * schemes a browser will still execute or navigate to even when the URL carries interior whitespace
 * a naive end-trim (the old `.trim()`-only check) would miss, e.g. `java\tscript:x`: browsers strip
 * tabs and newlines from inside a URL before parsing its scheme, so this check must too. The
 * admin media hint delegates here so this scheme policy cannot drift. Filtering code points
 * avoids writing literal control characters in a regex pattern.
 *
 * @complexity O(n) in the value's length (one filter pass, one prefix test).
 */
function isUnsafeUrlValue(value: string): boolean {
  let stripped = "";
  for (const char of value) {
    // A `for...of` step always yields one whole code point, so `codePointAt(0)` is never undefined.
    if (char.codePointAt(0)! > ASCII_WHITESPACE_OR_CONTROL_MAX_CODE_POINT) stripped += char;
  }
  stripped = stripped.toLowerCase();
  return stripped.startsWith("javascript:") || stripped.startsWith("vbscript:") || stripped.startsWith("data:");
}

/**
 * Whether a `style` value carries a known CSS injection or CSS-escape-bypass vector:
 * `expression(...)` (legacy IE script-in-CSS), a `javascript:`/`vbscript:` value inside a CSS
 * `url(...)`, `-moz-binding`/`behavior:` (XBL/HTC script bindings), `@import` (pulls in a second,
 * unvetted stylesheet), or ANY backslash in an inline attribute — a CSS escape sequence (`\65`
 * is `e`) can respell any of the above past a plain substring check, so a backslash anywhere in
 * an inline value is rejected outright rather than decoding every possible CSS escape.
 * Plain `url(...)` values (background images) are otherwise allowed — authors here are the
 * owner/admins, not anonymous input.
 * Stylesheets additionally allow non-ASCII scalar hex escapes (e.g. `\2713` for a checkmark).
 * They cannot respell the ASCII injection vocabulary. Only the validation projection changes;
 * the accepted value remains byte-for-byte authored CSS. ASCII/invalid/other escapes still fail.
 *
 * @complexity O(n) time/space in the value's length; escape matches consume at most six digits.
 */
const UNSAFE_STYLE_PATTERN = /expression\(|javascript:|vbscript:|-moz-binding|behavior:|@import|\\/i;
function isUnsafeStyleValue(value: string, { styleContext }: { styleContext?: "stylesheet" } = {}): boolean {
  const inspected = styleContext === "stylesheet"
    ? value.replace(/\\([0-9a-f]{1,6})(?:\r\n|[ \t\n\r\f])?/gi, (escape, hex: string) => {
      const codePoint = Number.parseInt(hex, 16);
      if (codePoint < 0xa0 || codePoint > 0x10ffff || (codePoint >= 0xd800 && codePoint <= 0xdfff)) return escape;
      return String.fromCodePoint(codePoint);
    })
    : value;
  return UNSAFE_STYLE_PATTERN.test(inspected);
}

/** Classifies one already-tokenized `name`/`value` pair. Split out of {@link parseEmbedHtmlAttributes}
 *  so each rejection reason is its own directly testable branch, and so the loop below reads as
 *  "tokenize, then classify" rather than one function doing both.
 *
 * Order matters:
 * `on*` is checked FIRST (so an `onerror` always reports as `event-handler`, the more actionable
 * reason, never the generic `disallowed-name`), then the URL-scheme check runs against EVERY value
 * regardless of name (matching the pre-existing `javascript:` check this is ported from), then
 * allowlist membership, then — only for an already-allowed `style` — the CSS-specific unsafe-value
 * check. `poster` is the only allowlisted URL-shaped attribute, but checking every value adds
 * no gap. Keeping these checks separate also keeps the classifier's own complexity low.
 *
 * @complexity O(1) — four fixed checks against one already-extracted token; each check's own O(n) in
 * the token's length is linear, not nested.
 */
function classifyEmbedHtmlAttributeToken(name: string, value: string, options: { styleContext?: "stylesheet" } = {}): EmbedHtmlAttributeError | null {
  if (name.startsWith("on")) return { reason: "event-handler", attribute: name };
  if (isUnsafeUrlValue(value)) return { reason: "unsafe-url", attribute: name };
  if (!isAllowedEmbedHtmlAttributeName({ name })) return { reason: "disallowed-name", attribute: name };
  if (name === "style" && isUnsafeStyleValue(value, options)) return { reason: "unsafe-style", attribute: name };
  return null;
}

/** Matches one `name`, or one `name="value"`/`name='value'`/`name=value` pair — the same loose shape
 *  real HTML attribute syntax allows, ported unchanged from the admin's tokenizer. */
const HTML_ATTRIBUTE_TOKEN = /([^\s="']+)(?:=(?:"([^"]*)"|'([^']*)'|([^\s"']+)))?/g;

/** The value of one {@link HTML_ATTRIBUTE_TOKEN} match: whichever of the double-quoted, single-quoted
 *  or bare value groups matched, or `""` for a bare boolean name (`muted`). */
function tokenValue(match: RegExpExecArray): string {
  return match[2] ?? match[3] ?? match[4] ?? "";
}

/** The fail-closed result for a fragment the tokenizer could not parse: everything parsed so far is
 *  discarded and the `malformed` entry is recorded last (see this file's header for why). */
function malformedResult({ errors, fragment }: { errors: EmbedHtmlAttributeError[]; fragment: string }): ParsedEmbedHtmlAttributes {
  const malformed: EmbedHtmlAttributeError = { reason: "malformed", attribute: fragment.trim() };
  errors.push(malformed);
  return { attributes: {}, errors, error: malformed };
}

/**
 * Parses free-text HTML attributes (`name="value" name2="value2"`, or a bare boolean `name`) into a
 * validated attribute map, per-token: an accepted token lands in `attributes`, a rejected one lands
 * in `errors` and is simply omitted — this string never fails closed as a whole EXCEPT when the
 * tokenizer itself loses sync (a stray quote or other unparseable fragment between/after matches),
 * in which case `attributes` is `{}` and the sole entry in `errors` has `reason: "malformed"` (see
 * this file's header for why that one case is different).
 *
 * This is a SECURITY boundary, not a syntax convenience: every string this parses was authored in an
 * admin/owner context but rendered on the public site, so free-text HTML-attribute pass-through is a
 * stored-XSS vector the moment it reaches a public page. {@link isAllowedEmbedHtmlAttributeName} is
 * therefore the ONLY path to acceptance for a name; nothing here tries to sanitize an otherwise-
 * disallowed name or value into something safe.
 *
 * @param options.styleContext Use `stylesheet` only for a style element's CSS text; allows
 *   non-ASCII scalar hex escapes for glyphs while preserving the inline escape restriction.
 *
 * @complexity Time O(n) in `text`'s length (one regex pass over it), space O(k) for k accepted
 *   attributes plus O(e) for e rejected tokens.
 */
export function parseEmbedHtmlAttributes({ text }: { text: string }, options: { styleContext?: "stylesheet" } = {}): ParsedEmbedHtmlAttributes {
  const trimmed = text.trim();
  if (trimmed === "") return { attributes: {}, errors: [], error: null };

  const attributes: Record<string, string> = {};
  const errors: EmbedHtmlAttributeError[] = [];
  HTML_ATTRIBUTE_TOKEN.lastIndex = 0;
  let consumed = 0;
  // A `for` loop (rather than `while ((match = …exec(trimmed)) !== null)`) keeps every assignment
  // to `match` in statement position, never inside the loop's own test expression.
  for (let match = HTML_ATTRIBUTE_TOKEN.exec(trimmed); match !== null; match = HTML_ATTRIBUTE_TOKEN.exec(trimmed)) {
    // Non-whitespace text between the previous match and this one is a fragment the token pattern
    // could not parse as a name (e.g. a stray quote) — the tokenizer has lost sync, so everything
    // parsed so far is discarded rather than trusted (see this file's header).
    const skipped = trimmed.slice(consumed, match.index);
    if (skipped.trim() !== "") return malformedResult({ errors, fragment: skipped });
    consumed = match.index + match[0].length;

    // Group 1 (the name) is the one non-optional group in HTML_ATTRIBUTE_TOKEN, so it is always set.
    const name = match[1]!.toLowerCase();
    const value = tokenValue(match);
    const rejection = classifyEmbedHtmlAttributeToken(name, value, options);
    if (rejection) errors.push(rejection);
    else attributes[name] = value;
  }

  const trailing = trimmed.slice(consumed);
  if (trailing.trim() !== "") return malformedResult({ errors, fragment: trailing });
  return { attributes, errors, error: errors[0] ?? null };
}

/**
 * @file The ONE parser for embed markers (`data-embed-config`), shared by every consumer.
 *
 * Purpose:
 * Before the 2026-08-10 marker-spine unification there were four independent scanners, each with its
 * own regex, matching two different attribute vocabularies that had drifted apart:
 *
 * - `widgets/html-embeds.ts` — `data-embed-type`/`data-embed-id` in a Page's `body_html`
 * - `features/theme/static-render.ts` — the same pair for menu/post markers, PLUS
 *   host slot attributes alongside `data-nav-current`/`data-slot-variant` for theme partials
 * - `core/entry-refs/extractor.ts` — the same pair again, for reference extraction
 *
 * Four regexes for one concept is four places a fix has to land and four ways they can disagree
 * (they already did: the widgets pipeline only matched a self-closing `<div></div>`, while the theme
 * path deliberately matched a marker WITH authored fallback content inside it). This module is the
 * single definition. Consumers ask it what a piece of HTML references; none of them owns a pattern.
 *
 * The vocabulary is one attribute carrying JSON:
 *
 *     <div data-embed-config='{"type":"partial","id":"nav","current":"index"}'></div>
 *     <nav data-embed-config='{"type":"menu","id":"docs-nav","variant":"tree"}'>fallback</nav>
 *
 * Forms may request plain output with `{"type":"form","id":"contact","mode":"html"}`;
 * `mode` is resolver-owned config, so the parser carries it through unchanged.
 *
 * `type` and `id` are ordinary keys, not separate attributes, so a new key never requires a new
 * attribute name. The attribute is single-quoted precisely so the JSON's own double quotes need no
 * escaping.
 *
 * Architectural role:
 * PURE. No I/O, no DOM, no resolution — it reports what a marker *says*, never what it resolves to.
 * Lives in `core/` because all three consumers above sit in different features and `core/entry-refs`
 * (the integrity path) is already here.
 *
 * ## Why regex and not a parser
 *
 * Same reason the code it replaces used one: this runs server-side against theme-authored markup and
 * Page bodies with no DOM available, and every consumer needs the marker's *source offsets* to
 * substitute in place. A real HTML parse would also have to round-trip the document back to a string
 * byte-identically, which is a much harder guarantee than locating one attribute.
 */

/** A `data-embed-config` marker located in a piece of HTML. */
export interface EmbedMarker {
  /** `config.type` — which resolver handles this. Always present; a marker without it is invalid. */
  readonly type: string;
  /**
   * `config.id` — which instance. `undefined` for a type that needs no target (none today, but the
   * shape allows one rather than forcing a meaningless id).
   */
  readonly id: string | undefined;
  /** The whole parsed object, `type`/`id` included, so a resolver reads its own keys off one place. */
  readonly config: Readonly<Record<string, unknown>>;
  /** The marker element's tag name, for consumers that rebuild the open tag. */
  readonly tag: string;
  /** The marker's attribute string, verbatim, so other authored attributes survive a substitution. */
  readonly attrs: string;
  /** The full matched element including its inner content and closing tag. */
  readonly whole: string;
  /**
   * The marker's own original inner content (between its open and close tag), exactly as authored.
   * The mirror image of {@link withInnerContent}'s parameter: that function takes NEW inner content
   * and keeps the marker's existing tag/attrs; this field is for a caller going the other way —
   * keeping (or transforming) the marker's existing inner content while changing its attrs/config,
   * e.g. {@link withAddedId} filling in a missing `id` without disturbing whatever fallback markup
   * the author put inside the marker.
   */
  readonly inner: string;
  /** Index of `whole` within the scanned html — substitution without re-searching. */
  readonly index: number;
  /** 1-based position among all markers found, for stable locators (`entry_refs` `fieldPath`). */
  readonly occurrence: number;
}

/** Why a marker was rejected. Consumers decide whether to warn, skip, or refuse a write. */
export type EmbedMarkerProblem =
  | { readonly kind: "invalid-json"; readonly raw: string; readonly message: string }
  | { readonly kind: "not-an-object"; readonly raw: string }
  | { readonly kind: "missing-type"; readonly raw: string };

/** One rejected marker, with enough context to name it in an error a human can act on. */
export interface EmbedMarkerRejection {
  readonly problem: EmbedMarkerProblem;
  readonly occurrence: number;
  readonly index: number;
}

export interface ScanEmbedMarkersResult {
  readonly markers: readonly EmbedMarker[];
  /**
   * Markers that carry the attribute but could not be understood. **Never silently empty-on-error**:
   * `entry-refs/extractor.ts` builds the where-used index that safe-delete trusts, and a marker that
   * fails to parse would otherwise drop a reference from that index without a trace — letting a
   * delete proceed against something still in use. Extraction and the write chokepoint must treat a
   * non-empty `rejected` as loud; render-time consumers may degrade quietly.
   */
  readonly rejected: readonly EmbedMarkerRejection[];
}

/**
 * Matches the OPEN tag of one element carrying `data-embed-config`, capturing its tag name and its
 * attribute text. It stops at the open tag's own `>` and makes no assumption about what closes it —
 * {@link scanEmbedMarkers} locates the matching close tag separately, via {@link findBalancedClose}'s
 * depth count over the masked html.
 *
 * Before 2026-09-23 this pattern captured inner content itself, up to a backreferenced `<\/\1>`. That
 * was only safe for a marker with no same-named descendant — true for every marker convention in this
 * codebase at the time, and the same assumption `injectMenuEmbed` documented before this module
 * existed — but it meant `<div data-embed-config='...'><div>…</div></div>` (an inner element sharing
 * the marker's own tag name) closed at the FIRST `</div>`, truncating the marker's real inner content.
 * {@link findBalancedClose} removes that assumption by counting depth instead of matching nearest text.
 *
 * The tag name pattern (`[a-z][a-z0-9-]*`) accepts any HTML element name, including a custom element
 * (`<my-card>`), not just the historical letters-only set.
 *
 * Carries the `d` (`hasIndices`) flag so {@link scanEmbedMarkers} can read every field back out of
 * the ORIGINAL html at each capture group's own offsets, rather than out of whatever string was
 * actually scanned (see {@link maskNonRenderableRegions}) — see that function's doc for why the two
 * must never be the same string.
 *
 * Accepts the value single-quoted (group 3, the authored convention) OR double-quoted (group 4).
 * Before 2026-09-26 only the single-quoted form matched, but every DOM serializer — the admin's
 * Interactive canvas (GrapesJS), `innerHTML`, parse5 — re-emits the SAME attribute as
 * `data-embed-config="{&quot;type&quot;:…}"`, so one canvas save silently turned a working marker into
 * inert markup (the live /pages "That marker, live:" contact-form example rendered an empty box).
 * A double-quoted value is HTML-decoded before parsing ({@link decodeAttributeValue}); a single-quoted
 * one is still read verbatim, as it always was.
 */
const MARKER_PATTERN = /<([a-z][a-z0-9-]*)((?:\s+[^>]*?)?\sdata-embed-config=(?:'([^']*)'|"([^"]*)")(?:\s+[^>]*?)?)\s*>/gid;

/** The `data-embed-config` attribute itself, either quoting — for the rebuild helpers that rewrite or
 *  drop it inside a marker's {@link EmbedMarker.attrs}. Group 1 is set only for the double-quoted form. */
const MARKER_ATTRIBUTE_PATTERN = /\s+data-embed-config=(?:'[^']*'|("[^"]*"))/;

/** Named character references a serializer actually emits inside an attribute value. Any other named
 *  reference is left as written rather than guessed at. */
const NAMED_CHARACTER_REFERENCES: Readonly<Record<string, string>> = { quot: '"', amp: "&", apos: "'", lt: "<", gt: ">", nbsp: " " };

/**
 * A double-quoted attribute value as a browser reads it: `&quot;`/`&amp;`/`&apos;`/`&lt;`/`&gt;`/
 * `&nbsp;` and decimal/hex numeric references decoded. Kept local (this module stays import-free).
 *
 * @complexity O(n) over `value`.
 */
function decodeAttributeValue(value: string): string {
  return value.replace(/&(?:#(\d{1,7})|#[xX]([0-9a-fA-F]{1,6})|([a-z]+));/g, (whole, dec?: string, hex?: string, name?: string) => {
    if (name !== undefined) return NAMED_CHARACTER_REFERENCES[name] ?? whole;
    const codePoint = dec !== undefined ? Number.parseInt(dec, 10) : Number.parseInt(hex as string, 16);
    return codePoint > 0 && codePoint <= 0x10ffff ? String.fromCodePoint(codePoint) : whole;
  });
}

/** Shared decoding seam for authored media references; parsing and indexing use one entity policy. */
export function decodeMarkerHtmlAttribute({ value }: { value: string }, _optional: Record<string, never> = {}): string {
  return decodeAttributeValue(value);
}

/** The inverse of {@link decodeAttributeValue} for a value written back double-quoted. */
function encodeDoubleQuotedValue(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
}

/** Every character of `text` replaced by a space, except newlines (left alone so a masked span
 * cannot change how many lines the surrounding string has). Same length in, same length out. */
function blank(text: string): string {
  return text.replace(/[^\n]/g, " ");
}

/** An HTML comment, open to close, non-greedy so two separate comments never merge into one span. */
const HTML_COMMENT_PATTERN = /<!--[\s\S]*?-->/g;

/** A `<script>` or `<style>` element, capturing its tag name (for the backreferenced close) and its
 * raw-text content — the part a browser never parses as markup. */
const RAW_TEXT_ELEMENT_PATTERN = /<(script|style)\b[^>]*>([\s\S]*?)<\/\1>/gi;

/**
 * Produce a same-length copy of `html` with every HTML comment, and the raw-text content of every
 * `<script>`/`<style>` element, replaced by space filler. {@link scanEmbedMarkers} runs
 * {@link MARKER_PATTERN} against this copy — never the original — so a well-formed
 * `data-embed-config` marker written inside an authoring note (`<!-- ... -->`) or inside a
 * `<style>` block's CSS comment can never be matched: neither is ever parsed as an element by a
 * browser, so the scanner must not treat either as one either. A marker outside both is untouched
 * here and matches exactly as before.
 *
 * Same length is load-bearing, not cosmetic: every offset {@link scanEmbedMarkers} reports (and
 * {@link substituteMarkers}'s index-based splice back into the ORIGINAL html) depends on a masked
 * span occupying exactly the same positions as what it replaces. Deleting the comment/raw-text
 * content instead of blanking it would shift every later offset out from under those callers.
 *
 * EXPORTED (2026-09-09) for `features/pages/regions.ts`, which scans the SAME page bodies for
 * `data-agent-element` region elements and needs the identical "text inside a comment or inside a
 * <style> block is not markup" rule with the identical offset-preserving guarantee. A second copy
 * of this masking is exactly the four-scanners-for-one-concept drift this module's own header
 * exists to close: region scanning is a different question about the same bytes, not a second
 * vocabulary.
 */
export function maskNonRenderableRegions({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const withoutComments = html.replace(HTML_COMMENT_PATTERN, blank);
  return withoutComments.replace(RAW_TEXT_ELEMENT_PATTERN, (whole, tagName: string, content: string) => {
    const closingTagLength = tagName.length + 3; // "</" + tagName + ">"
    const openTagLength = whole.length - content.length - closingTagLength;
    return whole.slice(0, openTagLength) + blank(content) + whole.slice(openTagLength + content.length);
  });
}

/**
 * One capture group's `[start, end)` offsets from a `d`-flagged match's `indices` array, for a group
 * `MARKER_PATTERN` never leaves unmatched — every group read here sits on a mandatory part of the
 * pattern, never inside an optional alternation (group 3 is read only when the double-quoted
 * alternative, group 4, did not participate, so the single-quoted one did). A missing entry would
 * mean the pattern changed underneath this function, not a normal runtime path.
 *
 * That guarantee is stated to the type checker here rather than re-checked at runtime: the former
 * `if (!range) throw` could not be reached by any input (removed in the J3 coverage pass). A pattern
 * edit that broke the guarantee still fails loudly, not silently — the caller destructures/spreads
 * the returned range, which throws a `TypeError` on `undefined`.
 */
function requireGroupRange(indices: RegExpIndicesArray, group: 0 | 1 | 2 | 3): readonly [number, number] {
  return indices[group] as readonly [number, number];
}

/**
 * Validate one marker's raw attribute text. Split out from {@link scanEmbedMarkers} so the scan stays
 * a plain loop: all three rejection branches live here, and the caller only chooses which list to
 * push onto.
 *
 * EXPORTED (2026-09-23, Bug A / interactive-bugs plan Slice A1) so a consumer that only has the raw
 * `data-embed-config` string in hand — the admin's canvas placeholder describer, which reads an
 * already-authored DOM attribute rather than re-running {@link scanEmbedMarkers} — can apply the exact
 * same parse-and-reject rule `scanEmbedMarkers` itself uses, instead of growing its own copy of it.
 */
export function parseEmbedMarkerConfig({ raw }: { raw: string }, _optional: Record<string, never> = {}): { config: Record<string, unknown> } | { problem: EmbedMarkerProblem } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return { problem: { kind: "invalid-json", raw, message: (err as Error).message } };
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return { problem: { kind: "not-an-object", raw } };
  }
  const config = parsed as Record<string, unknown>;
  if (typeof config.type !== "string" || config.type === "") {
    return { problem: { kind: "missing-type", raw } };
  }
  return { config };
}

/** A tag token's `[start, end)` span in the masked html — from its `<` through its first `>`. */
type TagSpan = readonly [number, number];

/**
 * Every `<tagName`/`</tagName` token in `masked` from `fromIndex` onward, in document order. The
 * boundary lookahead (`[\s/>]`) stops `<my-card` matching a longer name like `<my-card-extra`; each
 * token ends at its first `>`, and the scan resumes there, so a token's own attribute text is never
 * re-read as another token. Stops at a trailing malformed tag with no `>` at all.
 *
 * Runs against the MASKED copy only, so a tag written inside a comment or a `<script>`/`<style>`
 * element's raw text (already blanked by {@link maskNonRenderableRegions}) is invisible here,
 * exactly as it is invisible to {@link MARKER_PATTERN} itself.
 *
 * @complexity O(n) over the remaining length of `masked`.
 */
function* tagTokens(masked: string, tagName: string, fromIndex: number): Generator<{ readonly isClose: boolean; readonly span: TagSpan }> {
  const token = new RegExp(`<(/?)${tagName}(?=[\\s/>])`, "gi");
  token.lastIndex = fromIndex;
  for (let match = token.exec(masked); match !== null; match = token.exec(masked)) {
    const closeAngle = masked.indexOf(">", match.index);
    if (closeAngle === -1) return;
    yield { isClose: match[1] === "/", span: [match.index, closeAngle + 1] };
    token.lastIndex = closeAngle + 1;
  }
}

/**
 * The depth-balanced close for the open tag whose match ended at `fromIndex`, by counting
 * {@link tagTokens} from there: `<div><div>…</div></div>` closes at the tag that actually balances the
 * one already open, not at the first `</div>` found. Falls back to the first close found when the
 * region never rebalances (a genuinely unclosed inner tag) — the result the old backreferenced pattern
 * produced, so malformed markup degrades as it did before. `null` when there is no close at all.
 *
 * Only {@link findBalancedClose}'s fallback for an open tag {@link indexTagTokens} tokenized
 * differently (its JSON config holds a `>`); every other lookup is answered from that index.
 *
 * @complexity O(n) over the remaining length of `masked`.
 */
function scanForBalancedClose(masked: string, tagName: string, fromIndex: number): TagSpan | null {
  let depth = 1;
  let firstClose: TagSpan | null = null;
  for (const { isClose, span } of tagTokens(masked, tagName, fromIndex)) {
    if (!isClose) {
      depth += 1;
      continue;
    }
    firstClose ??= span;
    depth -= 1;
    if (depth === 0) return span;
  }
  return firstClose;
}

/** One tag name's tokens over the whole masked html, paired once with a stack. */
interface TagTokenIndex {
  /** Each open token's start → the span of the close that balances it, or `null` if none does. */
  readonly partners: ReadonlyMap<number, TagSpan | null>;
  /** Every close token's span, in document order (so sorted by start). */
  readonly closes: readonly TagSpan[];
}

/**
 * Pairs every `<tagName`/`</tagName` token in `masked` in ONE pass. Stack pairing gives each open the
 * same close {@link scanForBalancedClose}'s depth count from that open would find (both match a close
 * with the nearest still-open tag), but for every open at once — so a page of k unbalanced markers
 * costs O(n), not the O(k·n) of rescanning to the end of the document once per marker.
 *
 * @complexity O(n) time, O(t) space for t tokens.
 */
function indexTagTokens(masked: string, tagName: string): TagTokenIndex {
  const partners = new Map<number, TagSpan | null>();
  const closes: TagSpan[] = [];
  const openStarts: number[] = [];
  for (const { isClose, span } of tagTokens(masked, tagName, 0)) {
    if (!isClose) {
      partners.set(span[0], null);
      openStarts.push(span[0]);
      continue;
    }
    closes.push(span);
    const opener = openStarts.pop();
    if (opener !== undefined) partners.set(opener, span);
  }
  return { partners, closes };
}

/** The first span in `closes` (sorted by start) starting at or after `fromIndex`, or `null`.
 * @complexity O(log c) — binary search. */
function firstCloseFrom(closes: readonly TagSpan[], fromIndex: number): TagSpan | null {
  let low = 0;
  let high = closes.length;
  while (low < high) {
    const mid = (low + high) >>> 1;
    // low < high keeps mid within the sorted closes array.
    if (closes[mid]![0] < fromIndex) low = mid + 1;
    else high = mid;
  }
  return closes[low] ?? null;
}

/**
 * The `[start, end)` span (in `masked`) of the close tag that balances the marker open tag spanning
 * `[openStart, openEnd)` — see {@link scanForBalancedClose} for the balancing and first-close
 * fallback rules — or `null` when no close exists at all (a void element such as `<img>`, or an
 * unclosed marker): the caller then treats the open tag alone as the whole marker, rather than
 * letting it swallow the rest of the document.
 *
 * Answers from a per-tag-name {@link indexTagTokens} built once per scan and kept in `cache`. When
 * that index tokenized this open tag differently from the marker pattern (the index ends a tag at its
 * first `>`, and a `>` inside the JSON config ends it early), it falls back to the exact linear count.
 *
 * @complexity O(log c) amortized once the tag name's O(n) index exists; O(n) on the fallback.
 */
function findBalancedClose(
  masked: string,
  tag: { readonly name: string; readonly openStart: number; readonly openEnd: number },
  cache: Map<string, TagTokenIndex>,
): TagSpan | null {
  const key = tag.name.toLowerCase();
  let index = cache.get(key);
  if (index === undefined) {
    index = indexTagTokens(masked, key);
    cache.set(key, index);
  }
  const partner = index.partners.get(tag.openStart);
  const aligned = partner !== undefined && masked.indexOf(">", tag.openStart) + 1 === tag.openEnd;
  if (!aligned) return scanForBalancedClose(masked, key, tag.openEnd);
  return partner ?? firstCloseFrom(index.closes, tag.openEnd);
}

/**
 * Locate and parse every embed marker in `html`. Pure; allocates one result per marker.
 *
 * Scans {@link maskNonRenderableRegions}'s masked copy so a marker sitting inside an HTML comment or
 * a `<script>`/`<style>` element's raw text is never matched, and so tags inside either are invisible
 * to {@link findBalancedClose}'s depth count too. Every field on the resulting {@link EmbedMarker}
 * (`whole`, `tag`, `attrs`, `inner`, the parsed config) is read back out of the ORIGINAL `html` at
 * that match's own offsets — masking only decides which spans are eligible to be a marker or to count
 * toward a close tag's depth, it must never change what an eligible marker's own fields report.
 *
 * Uses a private copy of {@link MARKER_PATTERN} (same source/flags) for the `exec` loop below, rather
 * than mutating the shared module-level regex's `lastIndex` directly — this function is PURE, and a
 * shared mutable scan cursor would corrupt a reentrant or recursive call.
 */
export function scanEmbedMarkers({ html }: { html: string }, _optional: Record<string, never> = {}): ScanEmbedMarkersResult {
  const markers: EmbedMarker[] = [];
  const rejected: EmbedMarkerRejection[] = [];
  let occurrence = 0;

  const masked = maskNonRenderableRegions({ html: html });
  const pattern = new RegExp(MARKER_PATTERN.source, MARKER_PATTERN.flags);
  const closeIndexCache = new Map<string, TagTokenIndex>();
  for (let match = pattern.exec(masked); match !== null; match = pattern.exec(masked)) {
    occurrence += 1;
    const indices = (match as RegExpExecArray & { indices: RegExpIndicesArray }).indices;
    const [wholeStart, openTagEnd] = requireGroupRange(indices, 0);
    const tagRange = requireGroupRange(indices, 1);
    const attrsRange = requireGroupRange(indices, 2);
    const doubleQuotedRange = indices[4];
    const rawRange = doubleQuotedRange ?? requireGroupRange(indices, 3);
    const tag = html.slice(...tagRange);

    // No close at all (a void `<img>` marker): the open tag alone is the whole marker, inner empty.
    const [closeStart, closeEnd] = findBalancedClose(masked, { name: tag, openStart: wholeStart, openEnd: openTagEnd }, closeIndexCache) ?? [
      openTagEnd,
      openTagEnd,
    ];
    pattern.lastIndex = closeEnd; // resume past this marker's whole balanced span, never re-entering it

    const index = wholeStart;
    const whole = html.slice(wholeStart, closeEnd);
    const attrs = html.slice(...attrsRange);
    const raw = doubleQuotedRange ? decodeAttributeValue(html.slice(...rawRange)) : html.slice(...rawRange);
    const inner = html.slice(openTagEnd, closeStart);
    const result = parseEmbedMarkerConfig({ raw: raw });

    if ("problem" in result) {
      rejected.push({ problem: result.problem, occurrence, index });
      continue;
    }
    const { config } = result;
    markers.push({
      type: config.type as string,
      id: typeof config.id === "string" ? config.id : undefined,
      config,
      tag,
      attrs,
      whole,
      inner,
      index,
      occurrence,
    });
  }

  return { markers, rejected };
}

/**
 * The JSON text of a decoded marker value, made safe to sit verbatim inside a single-quoted
 * attribute: `'` and `&` become the JSON escapes `\u0027`/`\u0026`. Both can only occur inside a
 * JSON string, where those escapes mean the same character, so `JSON.parse` returns the identical
 * value. Deliberately not `&#39;`/`&amp;`: {@link scanEmbedMarkers} reads a single-quoted value
 * verbatim, so an entity there would reach `JSON.parse` undecoded and change the config.
 *
 * @complexity O(n) over `json`.
 */
function toSingleQuotedValue(json: string): string {
  return json.replace(/'/g, "\\u0027").replace(/&/g, "\\u0026");
}

/**
 * Rewrites every double-quoted, entity-encoded `data-embed-config="{&quot;type&quot;:…}"` (what a DOM
 * serializer such as the admin's Interactive canvas emits) back to the authored, readable form
 * `data-embed-config='{"type":…}'`, so the stored page source reads the way it was written. Every
 * Page HTML write runs through this (`PagesHtmlDocumentStore`), and the admin applies it to what the
 * canvas hands back.
 *
 * Exact at the config level: a rewritten marker scans to the same `config`, `attrs` and `inner` it did
 * before. Only the quoted value changes; the tag, other attributes and content are untouched. Left
 * as written: a single-quoted marker, a marker inside a comment or `<script>`/`<style>` (never matched,
 * see {@link maskNonRenderableRegions}), and a value that is not valid JSON, so a broken marker still
 * reaches {@link scanEmbedMarkers}'s rejection with its original text.
 *
 * @complexity O(n) over `html`.
 */
export function normalizeEmbedMarkerQuoting({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const masked = maskNonRenderableRegions({ html: html });
  const pattern = new RegExp(MARKER_PATTERN.source, MARKER_PATTERN.flags);
  let result = "";
  let copiedUpTo = 0;
  for (let match = pattern.exec(masked); match !== null; match = pattern.exec(masked)) {
    const valueRange = (match as RegExpExecArray & { indices: RegExpIndicesArray }).indices[4];
    if (!valueRange) continue;
    const decoded = decodeAttributeValue(html.slice(...valueRange));
    try {
      JSON.parse(decoded);
    } catch {
      continue;
    }
    // The value's quotes sit one character outside its capture group on either side.
    result += `${html.slice(copiedUpTo, valueRange[0] - 1)}'${toSingleQuotedValue(decoded)}'`;
    copiedUpTo = valueRange[1] + 1;
  }
  return result + html.slice(copiedUpTo);
}

/** Every marker of one type, in document order. The common "which menus does this theme name" shape. */
export function markersOfType({ html, type }: { html: string; type: string }, _optional: Record<string, never> = {}): readonly EmbedMarker[] {
  return scanEmbedMarkers({ html: html }).markers.filter((m) => m.type === type);
}

/**
 * The two marker `type` values this module parses but never itself resolves — owned end-to-end by
 * `features/theme/static-render.ts` (`injectMenuEmbeds` for {@link MENU_MARKER_TYPE}, `resolveSlots`
 * for {@link PARTIAL_MARKER_TYPE}), which run AFTER `widgets/resolver-service.ts`'s page-embed stage
 * on every static-tier page render.
 *
 * Hoisted here (2026-08-17) so that ownership fact has exactly one spelling. Before this, it existed
 * only as inline string-literal comparisons inside `static-render.ts` itself
 * (`marker.type !== "menu"`, `marker.type !== "partial"`), and `resolver-service.ts`'s own
 * `THEME_OWNED_MARKER_TYPES` carried an independently-typed copy of the same two strings as a
 * documented stopgap pending this exact hoist (`ADS-memory/reports/
 * 2026-08-16-embed-placeholder-gap.md`, "Reuse decision") — two spellings of one fact is exactly the
 * kind of drift risk this module exists to close for marker *parsing*; these two constants close it
 * for marker *type naming* the same way.
 *
 * Deliberately NOT the same question `isPageEmbedType()` (`widgets/resolver-service.ts`) answers —
 * that function tests registry membership (`Object.hasOwn(HTML_EMBED_RESOLVERS, type)`), which is
 * `false` for these two AND for a genuine unregistered/typo type alike. These constants name the
 * "owned elsewhere, not a typo" fact directly instead; see `isPageEmbedType`'s own doc for why
 * conflating the two would silence a real warning.
 */
export const MENU_MARKER_TYPE = "menu";
export const PARTIAL_MARKER_TYPE = "partial";

/**
 * The post-previews marker type (2026-09-03) — a theme/page marker that renders a bounded list of
 * published post previews wherever it appears, so any authored Page (a static theme's own marketing
 * page, or a Page/Post rendered through a `theme.json` `templates` entry) can host a post listing.
 * Same ownership shape as {@link MENU_MARKER_TYPE}/{@link PARTIAL_MARKER_TYPE} immediately above:
 * resolved end-to-end by `features/theme/static-render.ts`'s `injectPostPreviewsEmbeds`, never
 * registered in `widgets/resolver-service.ts`'s `HTML_EMBED_RESOLVERS` — see that file's
 * `THEME_OWNED_MARKER_TYPES`, which carries a matching literal entry for the same disclosed
 * "duplicated, not imported" reason its own doc already states for the other two.
 *
 * Config shape: `{"type":"post-previews","limit":6}` — `limit` is optional (defaults to
 * `DEFAULT_POST_PREVIEWS_LIMIT`, `static-render.ts`) and is always clamped, never trusted verbatim,
 * before it reaches the bounded repo query that feeds this marker.
 */
export const POST_PREVIEWS_MARKER_TYPE = "post-previews";

/**
 * The collection marker type (2026-09-23) — a theme/page marker that renders a bounded, filtered,
 * sorted list of entries from one custom content type wherever it appears. Same ownership shape as
 * {@link MENU_MARKER_TYPE}/{@link PARTIAL_MARKER_TYPE}/{@link POST_PREVIEWS_MARKER_TYPE} immediately
 * above: resolved end-to-end by `features/theme/static-render.ts`'s `injectCollectionEmbeds`, never
 * registered in `widgets/resolver-service.ts`'s `HTML_EMBED_RESOLVERS` — see that file's
 * `THEME_OWNED_MARKER_TYPES`, which carries a matching literal entry for the same disclosed
 * "duplicated, not imported" reason its own doc gives for the other three.
 *
 * Config shape (validated by `entries/public-list.ts`'s `parseCollectionListConfig`, not by this
 * module): `{"type":"collection","id":"recipe", …}` (`typeKey` accepted as an alias) plus the type's own filter/sort/limit/layout
 * keys. Unlike {@link POST_PREVIEWS_MARKER_TYPE}, a resolved collection marker's wrapper is stripped
 * of `data-embed-config` on the hit path ({@link withInnerContentFinal}) so a later re-scan of the
 * same output can never rediscover and re-resolve it.
 */
export const COLLECTION_MARKER_TYPE = "collection";

/**
 * The featured-image marker type (2026-10-05) — a post template's slot for the current post's
 * featured image. A static-tier theme has no template language to read `post.featuredImage` (the
 * Liquid/Handlebars tiers' theme data), so before this marker a static theme had no way to show the
 * image at all; it only reached `og:image`. Same ownership shape as {@link COLLECTION_MARKER_TYPE}:
 * resolved end-to-end by `features/theme/static-render.ts`'s `injectFeaturedImage`, listed in
 * `resolver-service.ts`'s `THEME_OWNED_MARKER_TYPES`.
 *
 * Config shape: `{"type":"featured-image"}` — no target; it always means the entity the route is
 * rendering. A hit fills the authored element with the `<img>` and strips the marker; no image
 * (none set, unresolved, or a page with no current post) removes the WHOLE element, wrapper and
 * fallback included, so a theme's figure/margins never render around nothing.
 */
export const FEATURED_IMAGE_MARKER_TYPE = "featured-image";

/**
 * The longest a target value ({@link embedMarkerTarget}'s `id`/`slug`/`typeKey`) may be before it
 * counts as absent rather than a usable reference. A duplicate of `features/widgets/html-embeds.ts`'s
 * `MAX_EMBED_ID_LENGTH` (same number, same reasoning: a bound too long to safely carry into a
 * `Map`/`Set` key or an `entry_refs` row), not a shared import — this module stays import-free (see
 * {@link maskNonRenderableRegions}'s file header and `marker-target-parity.unit.test.ts`'s boundary
 * assertion), the same "duplicated fact, disclosed in a comment" tradeoff {@link MENU_MARKER_TYPE} and
 * {@link PARTIAL_MARKER_TYPE} already document for their own server-side twins.
 */
const MAX_TARGET_VALUE_LENGTH = 200;

/**
 * One marker type's `data-embed-config` keys that can name its resolution target, in the exact
 * precedence order the server tries them — `embedMarkerTarget` returns the FIRST of these keys with a
 * usable string value. This is the "which key names the target" rule Bug A's root cause report
 * (2026-09-23 interactive-bugs plan) found spread across four different resolvers
 * (`resolver-service.ts`'s widget/media/post/content, `routes/site/pages.ts`'s collection) with no
 * single shared table — the admin's own placeholder describer could not reuse it because nothing here
 * exposed it. Hoisting it as data (not a switch statement) is what lets both the server's own resolvers
 * and the admin's UI-only describer read the identical precedence rule.
 *
 * - `widget`/`form`/`media`/`post`/`content`: `id`, else `slug` — registered in
 *   `resolver-service.ts`'s `HTML_EMBED_RESOLVERS` (see `marker-target-parity.unit.test.ts`, which fails
 *   loudly if a registered type has no matching row or incorrect target keys).
 * - `plugin`: canonical manifest id in `plugin`; `component` identifies its declared export.
 * - `taxonomy`: `id` only — `widgets/resolvers/taxonomy.ts` reads `ref.id`, accepting a real
 *   taxonomy id or a unique taxonomy name through that key; `ref.slug` is never consulted.
 * - {@link COLLECTION_MARKER_TYPE}: `id`, else `typeKey` — `routes/site/pages.ts`'s
 *   `collectionMarkerTypeKey` tries `config.id` before `config.typeKey`; `slug` is never consulted.
 * - {@link MENU_MARKER_TYPE} / {@link PARTIAL_MARKER_TYPE}: `id` only — `static-render.ts` resolves
 *   both purely by id.
 * - {@link POST_PREVIEWS_MARKER_TYPE}: no keys at all — this marker needs no target
 *   ({@link embedMarkerTarget} reports that as its own `{ key: "none" }` outcome, never `undefined`,
 *   which means "target missing").
 *
 * An unknown type (not a key of this table) is not a member of it; {@link embedMarkerTarget} falls back
 * to `["id"]` for that case rather than treating an unrecognized type as needing no target — a display
 * must never claim a slug resolves for a type no resolver has ever registered.
 */
/** Target keys are identities; plugin component/props remain in the complete marker config. */
export type EmbedMarkerTargetKey = "id" | "slug" | "typeKey" | "plugin";
export const EMBED_MARKER_TARGET_KEYS: Readonly<Record<string, readonly EmbedMarkerTargetKey[]>> = {
  plugin: ["plugin"],
  widget: ["id", "slug"],
  form: ["id", "slug"],
  taxonomy: ["id"],
  media: ["id", "slug"],
  // Inline ordered images, not a persisted gallery entity; each mediaId is its own reference.
  gallery: [],
  post: ["id", "slug"],
  content: ["id", "slug"],
  [COLLECTION_MARKER_TYPE]: ["id", "typeKey"],
  [MENU_MARKER_TYPE]: ["id"],
  [PARTIAL_MARKER_TYPE]: ["id"],
  [POST_PREVIEWS_MARKER_TYPE]: [],
};

/** The default target-key list for a type absent from {@link EMBED_MARKER_TARGET_KEYS} — an unknown
 *  or typo'd type is assumed id-addressable like most types, but never slug-addressable: no resolver
 *  has ever registered to read a slug for it, so claiming one would resolve is always wrong. */
const UNKNOWN_TYPE_TARGET_KEYS: readonly ("id" | "slug" | "typeKey")[] = ["id"];

/**
 * One marker's resolved target, from {@link embedMarkerTarget}: either a key/value pair naming what
 * the marker points at, or the `"none"` marker for a type that needs no target at all. Kept distinct
 * from `undefined` (target missing) — see {@link embedMarkerTarget}'s own doc.
 */
export type EmbedMarkerTarget = { readonly key: EmbedMarkerTargetKey; readonly value: string } | { readonly key: "none" };

/** `value` trimmed down to a usable target string, or `undefined` if it is not a non-empty string of
 *  at most {@link MAX_TARGET_VALUE_LENGTH} characters — the same absent-vs-present rule
 *  `features/widgets/html-embeds.ts`'s `normalizeEmbedId`/`normalizeEmbedSlug` apply to their own
 *  config reads. @complexity O(1). */
function normalizeTargetValue(value: unknown): string | undefined {
  if (typeof value !== "string" || value.length === 0 || value.length > MAX_TARGET_VALUE_LENGTH) return undefined;
  return value;
}

/**
 * Which `data-embed-config` key names `type`'s resolution target, and that key's value, per
 * {@link EMBED_MARKER_TARGET_KEYS}'s precedence order. Three distinct outcomes:
 *
 * - `{ key, value }` — the first target key present with a usable string value.
 * - `{ key: "none" }` — this type ({@link POST_PREVIEWS_MARKER_TYPE}) needs no target; a caller must
 *   never read this as "target missing".
 * - `undefined` — the type has one or more target keys, but the marker's config supplies none of them
 *   (or only with an unusable value per {@link normalizeTargetValue}) — "target missing".
 *
 * `type` is compared lower-cased, matching `toEmbedRef`'s own `marker.type.toLowerCase()` in
 * `resolver-service.ts` — a hand-authored `"Widget"` must resolve exactly as `"widget"` does.
 *
 * @complexity O(k) in the number of candidate keys for `type` (at most 2 today) — independent of the
 * surrounding document's size.
 */
export function embedMarkerTarget({ type, config }: { type: string; config: Readonly<Record<string, unknown>> }, _optional: Record<string, never> = {}): EmbedMarkerTarget | undefined {
  const keys = EMBED_MARKER_TARGET_KEYS[type.toLowerCase()] ?? UNKNOWN_TYPE_TARGET_KEYS;
  if (keys.length === 0) return { key: "none" };
  for (const key of keys) {
    const value = normalizeTargetValue(config[key]);
    if (value !== undefined) return { key, value };
  }
  return undefined;
}

/**
 * The "Copy embed code" snippet for any marker type: the same `<div data-embed-config='{"type":…,
 * "<key>":"<value>"}'></div>` wrapper {@link scanEmbedMarkers}/{@link parseEmbedMarkerConfig} already
 * parse back — generalised (readable-slugs S5b) out of the collections admin
 * `collectionEmbedSnippet` adapter, the one admin-generated marker that existed before this: that function is
 * now a one-line call onto this (`embedMarkerSnippet("collection", "id", key)`), byte-for-byte
 * unchanged. `features/media`'s own "Copy embed code" button (S5a) is the second caller, with
 * `("media", "slug", asset.slug)` — see {@link EMBED_MARKER_TARGET_KEYS}'s `media` row for why `slug`
 * is a real, resolvable target key for this type.
 *
 * No escaping beyond the plain template: `key`/`value` are expected to already be validated,
 * quote-free identifiers (a slug, a type key, an id) by the time a caller reaches for a copy button —
 * the same assumption `collectionEmbedSnippet` always made.
 *
 * @complexity O(1) — one template string.
 */
export function embedMarkerSnippet(
  { type, key, value }: { type: string; key: "id" | "slug" | "typeKey"; value: string },
  _optional: Record<string, never> = {},
): string {
  return `<div data-embed-config='{"type":"${type}","${key}":"${value}"}'></div>`;
}

/** Serialize complete configs through the marker's existing single-attribute encoder.
 * Unknown config keys survive; apostrophes cannot terminate the attribute.
 * @complexity O(n) in the serialized config length.
 */
export function embedMarkerSnippetFromConfig(
  { config }: { config: Readonly<Record<string, unknown>> },
  _optional: Record<string, never> = {},
): string {
  return `<div data-embed-config='${toSingleQuotedValue(JSON.stringify(config))}'></div>`;
}

/**
 * Rebuild a marker's element around new inner content, keeping its own tag and every authored
 * attribute (`class`, `aria-label`, …). The counterpart to a wholesale replace: a menu marker keeps
 * its `<nav class="docs-nav">` wrapper and only swaps what's inside, whereas a partial slot marker
 * disappears entirely and is replaced by the partial.
 *
 * Synthesizing the open tag from `config` alone instead of using this is a silent bug — it drops the
 * theme's styling hooks and accessible names with nothing failing.
 */
export function withInnerContent({ marker, inner }: { marker: EmbedMarker; inner: string }, _optional: Record<string, never> = {}): string {
  return `<${marker.tag}${marker.attrs}>${inner}</${marker.tag}>`;
}

/**
 * Rebuild a marker's element with `id` added to its `data-embed-config`, keeping every other
 * authored config key, the marker's own tag, its other attributes, and its authored inner content
 * ({@link EmbedMarker.inner}) completely unchanged. The counterpart to {@link withInnerContent} for a
 * caller that needs to SUPPLY a marker's target rather than its content — e.g. the unified `content`
 * marker (2026-08-11): a theme-authored `{"type":"content"}` with no `id` means "the entity the route
 * already resolved", and the route fills that id in here before the marker is ever resolved, so every
 * downstream consumer (the scanner, the resolver, a later re-scan) sees an ordinary id-carrying marker
 * rather than needing its own "no id means current entity" special case.
 *
 * Callers must check `marker.id === undefined` themselves before calling this — an author's own
 * explicit id always wins over a caller-supplied default, and this function does not re-check that
 * (it would silently overwrite an explicit reference otherwise, which is the one thing the unified
 * marker's id-vs-no-id contract must never do).
 *
 * @complexity O(n) over the marker's own attrs length (one JSON stringify of a small object, one
 * regex replace over `attrs`) — independent of the surrounding document's size.
 */
export function withAddedId({ marker, id }: { marker: EmbedMarker; id: string }, _optional: Record<string, never> = {}): string {
  const config = JSON.stringify({ ...marker.config, id });
  // Keeps the marker's own quoting: a double-quoted value is re-encoded, a single-quoted one is not.
  const attrsWithId = marker.attrs.replace(MARKER_ATTRIBUTE_PATTERN, (_whole, doubleQuoted?: string) =>
    doubleQuoted === undefined ? ` data-embed-config='${config}'` : ` data-embed-config="${encodeDoubleQuotedValue(config)}"`,
  );
  return `<${marker.tag}${attrsWithId}>${marker.inner}</${marker.tag}>`;
}

/**
 * Rebuild a marker's element around new inner content, like {@link withInnerContent}, but ALSO strips
 * the marker's own `data-embed-config` attribute from the rebuilt tag — every other authored attribute
 * (`class`, `aria-label`, …) survives, only the marker-ness is removed.
 *
 * For a caller that performs its OWN final resolution outside the shared registry/render pipeline
 * (`pages.ts`'s recursive `content`-marker pre-splice, which fetches and inlines an `"html"`-format
 * entity's own body ahead of the normal `resolveHtmlPageEmbeds`/`renderHtmlPageBody` pass) and must
 * guarantee the result is not rediscovered and re-resolved by a LATER marker scan over the same output
 * — an ordinary {@link withInnerContent} splice would leave `data-embed-config` intact, and the next
 * scan would see what looks like a fresh, unresolved marker and try to resolve it again.
 *
 * @complexity O(n) over the marker's own attrs length (one regex replace) — independent of the
 * surrounding document's size.
 */
export function withInnerContentFinal({ marker, inner }: { marker: EmbedMarker; inner: string }, _optional: Record<string, never> = {}): string {
  const attrsWithoutMarker = marker.attrs.replace(MARKER_ATTRIBUTE_PATTERN, "");
  return `<${marker.tag}${attrsWithoutMarker}>${inner}</${marker.tag}>`;
}

/**
 * Replace each marker's WHOLE element with what `resolve` returns for it.
 *
 * Whole-element rather than inner-content because the two consumers genuinely differ: a partial slot
 * marker is scaffolding that vanishes once the partial is spliced in, while a menu marker is real
 * theme markup that must survive with only its contents swapped. Callers in the second camp wrap
 * their output in {@link withInnerContent}; making that explicit at the call site is better than a
 * mode flag, because the choice is a real per-type decision and not a preference.
 *
 * `resolve` returning `undefined` means "leave this marker exactly as authored", and that default is
 * load-bearing: a menu that does not exist, a target that was deleted, or a render that produces
 * nothing must fall back to the theme's authored content rather than blanking a nav. Every consumer
 * wants that rule, so it lives here rather than being re-implemented per call site.
 *
 * Applies right-to-left so each splice leaves the earlier markers' offsets valid.
 */
export function substituteMarkers(
  { html, resolve }: { html: string; resolve: (marker: EmbedMarker) => string | undefined },
  _optional: Record<string, never> = {},

): string {
  const { markers } = scanEmbedMarkers({ html: html });
  let out = html;
  for (let i = markers.length - 1; i >= 0; i -= 1) {
    // The reverse loop keeps i within the scanner result.
    const m = markers[i]!;
    const replacement = resolve(m);
    if (replacement === undefined) continue;
    out = out.slice(0, m.index) + replacement + out.slice(m.index + m.whole.length);
  }
  return out;
}

/**
 * One HTML attribute authored directly on a marker element (2026-09-16 — owner: "regular attributes
 * that somebody puts on a data-embed-config should work on the rendered tag"). Produced by
 * {@link parseMarkerAttributes}, consumed by callers that forward some or all of a marker's authored
 * attributes onto whatever it resolves to.
 */
export interface MarkerAttribute {
  readonly name: string;
  /** Source text, exactly as authored — never entity-decoded (see {@link parseMarkerAttributes}'s
   *  own doc for why). `null` means the attribute was written with no `="..."` at all (a boolean
   *  attribute like a bare `autoplay`), not that it had an empty value. */
  readonly value: string | null;
}

/**
 * The shape every attribute name {@link parseMarkerAttributes} accepts must have — deliberately
 * narrower than the full HTML spec's own name production, sized for real attribute names (`class`,
 * `data-*`, `aria-*`, `autoplay`, …), the same "narrower on purpose" discipline
 * `@jini-ai/cms/media`'s `html-attributes.ts` applies to its own allowlisted names. A token whose name
 * fails this is skipped, not thrown — this parser runs over already-authored page HTML (page trust,
 * no allowlist; see the 2026-09-16 embed-attributes plan §0), so "not a well-formed attribute name" is
 * a shape problem this parser degrades past, not a security boundary.
 */
const MARKER_ATTRIBUTE_NAME_PATTERN = /^[a-z_:][-a-z0-9_:.]*$/;

/**
 * Quote-aware attribute-token scanner: matches one `name`, or one `name=unquoted`, `name="value"`, or
 * `name='value'` pair. The identical loose shape `@jini-ai/cms/media`'s `html-attributes.ts` uses for
 * its own `HTML_ATTRIBUTE_TOKEN` — quote-aware so a `data-embed-config='{"type":"media"}'` token
 * (double quotes living inside a single-quoted value) is consumed as ONE token rather than corrupting
 * the scan at its first interior `"`.
 */
const MARKER_ATTRIBUTE_TOKEN = /([^\s="']+)(?:=(?:"([^"]*)"|'([^']*)'|([^\s"']+)))?/g;

/**
 * Parses a marker's verbatim {@link EmbedMarker.attrs} text into structured attributes, in authored
 * order, with `data-embed-config` itself removed (it is the marker, not an attribute a caller would
 * ever want to forward) — the read half of the 2026-09-16 embed-attributes contract:
 * {@link formatMarkerAttributes} is its inverse.
 *
 * - Names are lowercased (HTML attribute names are case-insensitive).
 * - A token whose (lowercased) name is not a valid attribute name per
 *   {@link MARKER_ATTRIBUTE_NAME_PATTERN} is skipped, never thrown.
 * - A duplicate name keeps its FIRST occurrence — the same rule a real HTML parser applies, so this
 *   parser's result matches what a browser would actually expose on the element.
 * - Every value is kept as SOURCE TEXT: never entity-decoded. Re-decoding `&amp;` here and
 *   re-escaping on output (see {@link formatMarkerAttributes}) would double-escape a value like
 *   `title="a &amp; b"` into `&amp;amp;` — this module never round-trips through a decoded form.
 *
 * @complexity O(n) in the marker's own attrs length (one regex pass) — independent of the surrounding
 * document's size.
 */
export function parseMarkerAttributes({ marker }: { marker: EmbedMarker }, _optional: Record<string, never> = {}): MarkerAttribute[] {
  const seenNames = new Set<string>();
  const attributes: MarkerAttribute[] = [];
  MARKER_ATTRIBUTE_TOKEN.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = MARKER_ATTRIBUTE_TOKEN.exec(marker.attrs)) !== null) {
    const name = match[1]!.toLowerCase();
    if (name === "data-embed-config") continue;
    if (!MARKER_ATTRIBUTE_NAME_PATTERN.test(name)) continue;
    if (seenNames.has(name)) continue;
    seenNames.add(name);
    const value = match[2] ?? match[3] ?? match[4] ?? null;
    attributes.push({ name, value });
  }
  return attributes;
}

/**
 * Formats parsed attributes back into attribute-string text, the inverse of
 * {@link parseMarkerAttributes}: a valueless attribute is emitted as a bare ` name`; a valued one as
 * ` name="value"`. The ONLY transform applied to a value is `"` -> `&quot;` (a value may itself
 * contain a literal `"`, e.g. carried over from a single-quoted authored attribute) — `&` is never
 * touched, so source text that already reads `&amp;` is emitted unchanged rather than
 * double-escaping into `&amp;amp;`.
 *
 * @complexity O(n) in the total length of every attribute's name and value.
 */
export function formatMarkerAttributes({ attrs }: { attrs: readonly MarkerAttribute[] }, _optional: Record<string, never> = {}): string {
  return attrs.map((attr) => (attr.value === null ? ` ${attr.name}` : ` ${attr.name}="${attr.value.replace(/"/g, "&quot;")}"`)).join("");
}

/** Whether a marker carries any authored attribute besides `data-embed-config` itself — the "bare
 *  marker" test {@link withElementKeptIfAttributed} uses to decide whether an element survives a
 *  whole-marker substitution.
 *
 * @complexity O(n) in the marker's own attrs length (delegates to {@link parseMarkerAttributes}).
 */
export function hasAuthoredAttributes({ marker }: { marker: EmbedMarker }, _optional: Record<string, never> = {}): boolean {
  return parseMarkerAttributes({ marker: marker }).length > 0;
}

/**
 * Rebuild a marker's element around new inner content using an EXPLICIT attribute list (rather than
 * the marker's own verbatim {@link EmbedMarker.attrs}) — for a caller that has partitioned a marker's
 * authored attributes and needs only a subset on the rebuilt wrapper (e.g. {@link substituteHtmlEmbeds}
 * moving media-element attribute names off a non-media wrapper onto the resolved `<video>`/`<img>`,
 * keeping the rest on the wrapper). The counterpart to {@link withInnerContent}, which always keeps
 * every authored attribute verbatim.
 */
export function withInnerContentAndAttributes(
  { marker, attrs, inner }: { marker: EmbedMarker; attrs: readonly MarkerAttribute[]; inner: string },
  _optional: Record<string, never> = {},
): string {
  return `<${marker.tag}${formatMarkerAttributes({ attrs: attrs })}>${inner}</${marker.tag}>`;
}

/**
 * Whole-element replace UNLESS the marker carries authored attributes, in which case its element
 * survives (minus `data-embed-config`) around the resolved content — the 2026-09-16 rule for marker
 * types (`widget`, `partial`) that default to disappearing entirely: a bare marker keeps disappearing,
 * byte-identical to before, while an attributed one keeps whatever styling/accessibility hook the
 * author put on it. Delegates to {@link withInnerContentFinal} for the attributed case so the kept
 * wrapper's attribute text is the marker's own verbatim {@link EmbedMarker.attrs} (not a
 * parse-then-reformat round trip) — the same byte-identical-when-nothing-moves discipline
 * {@link withInnerContentFinal} itself already provides.
 */
export function withElementKeptIfAttributed({ marker, inner }: { marker: EmbedMarker; inner: string }, _optional: Record<string, never> = {}): string {
  return hasAuthoredAttributes({ marker: marker }) ? withInnerContentFinal({ marker: marker, inner: inner }) : inner;
}

/**
 * Human-readable one-liner for a rejection, for a warning line or a write-time validation error.
 * Deliberately quotes the offending JSON: the author needs to see what they typed, and the raw text
 * is theme- or admin-authored, never end-user input.
 */
export function describeRejection({ rejection }: { rejection: EmbedMarkerRejection }, _optional: Record<string, never> = {}): string {
  const { problem, occurrence } = rejection;
  const where = `embed marker #${occurrence}`;
  if (problem.kind === "invalid-json") return `${where}: data-embed-config is not valid JSON (${problem.message}) — ${problem.raw}`;
  if (problem.kind === "not-an-object") return `${where}: data-embed-config must be a JSON object — ${problem.raw}`;
  return `${where}: data-embed-config is missing a "type" — ${problem.raw}`;
}

/**
 * @file Widget-instance READ accessors (SPEC-043 REQ-04) — `write-service.ts` only ever exported
 * create/update/trash/purge; this file is the missing `widgets.read`-gated get/list side, named
 * separately per `features/entries`' own `write-service.ts`/`list.ts` split convention.
 *
 * External /audit-work finding (2026-07-21, ADR-047): confirmed no read/list accessor existed in
 * this package at all — the admin `get-by-id`/`list` routes (`routes/admin/widgets/*.ts`) this
 * dispatch builds depend on it directly.
 *
 * Disclosed, not silently omitted: REQ-04 also asks for "its full revision history." No revision-
 * READ capability exists anywhere in `features/entries` today for ANY content type (confirmed:
 * `EntryRepoPort` only exposes `appendRevision`, never a corresponding list/read method — neither
 * `InMemoryEntryRepo` nor `SqliteEntryRepo` exposes one either, even as an extra, non-port method).
 * That is a real, pre-existing gap in the shared chokepoint, not a widgets-specific hole, and
 * meaningfully larger than the two additive fixes this dispatch already made to
 * `features/entries/write-service.ts` (the `onWritten` hook, the `bodyJson` parameter) — it needs
 * its own port + both adapters, a bigger shared-module change than this dispatch is authorized to
 * make unilaterally. `getWidgetInstance` below returns current state only; `revisions: []` is
 * returned as an honest placeholder shape (not a silently-dropped field) so callers/tests have a
 * stable contract to code against once the underlying capability lands.
 *
 * Architectural role:
 * `widgets` domain logic, read side.
 */
import type { UUID } from "@jini-ai/core/primitives";
import type { EntryListPort, EntryRepoPort } from "../entries/index.js";
import { requireWidgetPermission, type WidgetsAuthorizeFn } from "./authorize-helper.js";
import { WidgetInstanceNotFoundError } from "./errors.js";
import { toWidgetInstanceEntry } from "./entry-payload.js";
import { WIDGET_CONTENT_TYPE } from "./types.js";
import type { WidgetInstanceEntry } from "./types.js";

export interface WidgetReadServiceDeps {
  entryRepo: EntryRepoPort & EntryListPort;
  authorize: WidgetsAuthorizeFn;
}

export interface GetWidgetInstanceInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID };
  readonly widgetInstanceId: UUID;
}

export interface GetWidgetInstanceRequired {
  deps: WidgetReadServiceDeps;
  input: GetWidgetInstanceInput;
}

/** REQ-04: read a widget instance's current state (+ revision history — see this file's header for
 * the disclosed gap on that half). Returns any status (`active`/`trash`/`purged`) — the caller
 * decides whether a non-`active` instance is presentable (e.g. an admin editor still shows a
 * trashed instance so it can be restored/inspected).
 *
 * `widgetInstanceId` is resolved slug-first, id-second — same order/rationale as posts'
 * `getAdminPostByIdOrSlug` (`src/features/post/post.ts`) and forms'
 * `resolveFormDefinitionByIdOrSlug` (`server/inbound/admin-http/routes/forms/resolve-definition.ts`):
 * the admin widget editor's URL now carries the widget's slug (`WidgetsLibrary.tsx`'s row link,
 * `use-widget-instance-editor.hooks.ts`'s create-navigate), so this param may itself BE that slug.
 * An old id-based bookmark/link still resolves via the `findById` fallback. */
export async function getWidgetInstance(required: GetWidgetInstanceRequired, _optional: Record<string, never> = {}): Promise<{ instance: WidgetInstanceEntry; revisions: [] }> {
  const { deps, input } = required;
  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.read",
  });

  const bySlug = await deps.entryRepo.findBySlug({
    workspaceId: input.workspaceId,
    type: WIDGET_CONTENT_TYPE,
    slug: input.widgetInstanceId.trim().toLowerCase(),
  });
  const entry = bySlug ?? (await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.widgetInstanceId }));
  if (!entry || entry.type !== WIDGET_CONTENT_TYPE) {
    throw new WidgetInstanceNotFoundError({ message: `widget instance '${input.widgetInstanceId}' was not found` });
  }
  return { instance: toWidgetInstanceEntry({ entry: entry }), revisions: [] };
}

export interface ListWidgetInstancesInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID };
  /** Narrow to one widget type; omitted lists every type (mirrors `EntryListPort.listByWorkspace`'s
   * own optional-`type` shape). */
  readonly widgetType?: string;
  /** Excludes `trash`/`purged` instances by default — the library screen's default view (REQ-04
   * read access still covers reading a specific trashed instance directly via `getWidgetInstance`,
   * this is only the list's default filter). */
  readonly includeInactive?: boolean;
}

export interface ListWidgetInstancesRequired {
  deps: WidgetReadServiceDeps;
  input: ListWidgetInstancesInput;
}

export async function listWidgetInstances(
  required: ListWidgetInstancesRequired, _optional: Record<string, never> = {}
): Promise<{ instances: WidgetInstanceEntry[]; skippedCount: number; skippedIds: string[] }> {
  const { deps, input } = required;
  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.read",
  });

  const rows = await deps.entryRepo.listByWorkspace({ workspaceId: input.workspaceId }, { type: WIDGET_CONTENT_TYPE });
  const instances: WidgetInstanceEntry[] = [];
  let skippedCount = 0;
  const skippedIds: string[] = [];
  for (const row of rows) {
    let instance: WidgetInstanceEntry;
    try {
      instance = toWidgetInstanceEntry({ entry: row });
    } catch {
      // A malformed widget-instance row (e.g. wiped by an unrelated generic-entry update that
      // bypassed this feature's own write path) is skipped, not a 500 for the whole admin library
      // screen (Fable adversarial-review fix, 2026-07-21, Finding B).
      //
      // 2026-08-03 (dossier C5 follow-up): the skip itself was silent — nothing recorded that a row
      // never reached the caller, so a genuinely corrupted widget could vanish from the library with
      // zero trace. Kept the skip (a malformed row must not 500 the whole screen), added a
      // server-side log line plus returned count and IDs so it's observable instead of invisible.
      // Deliberately logs only `row.id`/`workspaceId`, never `row.fieldsJson` — a malformed payload
      // may hold arbitrary caller-supplied content, and this line is not the place to disclose it.
      console.warn("[widgets] listWidgetInstances: skipping malformed widget-instance row", {
        entryId: row.id,
        workspaceId: input.workspaceId,
      });
      skippedCount += 1;
      skippedIds.push(row.id);
      continue;
    }
    if (input.widgetType && instance.widgetType !== input.widgetType) continue;
    if (!input.includeInactive && instance.status !== "active") continue;
    instances.push(instance);
  }
  return { instances, skippedCount, skippedIds };
}

import type { PluginExportsPort } from "./html/plugin-export.js";
import { isNonArrayRecord } from "@jini-ai/core";
import { resolveGalleryEmbeds } from "./gallery-resolver.js";
import { isPlausibleMediaRefId } from "./markers/media-reference.js";
/**
 * @file `resolvePageWidgets` — the batch-first page-render resolution orchestrator (SPEC-043
 * REQ-23..28; ADR-047 Debate Fold-In Amendment 2).
 *
 * Purpose:
 * The single seam that turns "a page's widget references" (region-bound + inline-embedded) into
 * data the theme can render — one batched entry-load query, grouped by type, at most one
 * `resolveWidgetType` call per type present on the page (REQ-24). Mirrors the `render.ts` "theme is
 * data, core resolves" stance — the theme never calls this directly or resolves a reference itself.
 *
 * `EntryRepoPort` (this task's frozen, real chokepoint contract) has no `findByIds`/batch-by-id
 * primitive — only `findById` (one row) and `EntryListPort.listByWorkspace` (a full-type scan).
 * REQ-24's "one batched query" is satisfied here via ONE `listByWorkspace({workspaceId}, {type: 'widget'})` call
 * per render (not one query per placement/type), which is the batching guarantee AC-16 actually
 * tests (via `resolveWidgetType`'s single-`resolveMany`-call assertion) — a literal `WHERE id IN
 * (...)` primitive does not exist on the real, frozen `EntryRepoPort` this task must compose
 * against without modifying `features/entries`.
 *
 * Architectural role:
 * `widgets` domain logic (implementation outline C-004).
 */
import type { JsonObject, UUID } from "@jini-ai/core/primitives";
import type { EntryListPort, EntryRecord, EntryRepoPort } from "../entries/index.js";
import type { WidgetHostPorts, PostRecord, PostRepoPort, MediaContentTypeStorePort } from "./host-ports.js";
import type { MediaRepoPort, TransformDefinitionRepoPort } from "../media/index.js";
import type { TaxonomyListPort, TermListPort } from "../taxonomy/index.js";
import { resolveTaxonomyEmbeds } from "./resolvers/taxonomy.js";


import { parseWidgetAreaPayload, parseWidgetInstancePayload } from "./entry-payload.js";

import type { PageHtmlEmbedRef } from "./html/html-embeds.js";
import type { PageEmbedType } from "./page-embed-types.js";
import type { WidgetRegionBindingRepoPort } from "./ports.js";
import { resolveWidgetType } from "./resolvers/index.js";
import { WIDGET_AREA_CONTENT_TYPE, WIDGET_CONTENT_TYPE } from "./types.js";
import { resolveSiteTimeZoneSafely, type SiteTimeZonePort } from "./date-label.js";
import type {
  WidgetInstanceView,
  WidgetPlacementNode,
  WidgetRegionKey,
  WidgetRenderIR,
  WidgetResolveContext,
  WidgetResolveResult,
  WidgetTypeKey,
} from "./types.js";

export interface ResolvePageWidgetsDeps {
  bindingRepo: WidgetRegionBindingRepoPort;
  entryRepo: EntryRepoPort & EntryListPort;
}

/**
 * The narrower dependency slice widget-instance resolution alone needs — `resolveWidgetInstances`
 * and `resolveHtmlPageEmbeds` (below) never touch `bindingRepo` (that repo only backs region
 * placements, which an `"html"`-format Page has no concept of). `ResolvePageWidgetsDeps` remains a
 * structural supertype of this, so `resolvePageWidgets` passes its own full deps through unchanged.
 */
type WidgetInstanceResolutionDeps = Pick<ResolvePageWidgetsDeps, "entryRepo">;

export interface ResolvePageWidgetsInput {
  readonly workspaceId: UUID;
  /**
   * The already-fetched host document's `bodyJson`, when the caller has one to scan for inline
   * `widgetEmbed` nodes (REQ-21) — e.g. a `PostRecord.bodyJson` on the `home`/`post` site routes.
   * Passed as content rather than an id-to-fetch (unlike the old `pageEntryId` this replaces)
   * because the only real callers already hold the document: `PostRecord` (`features/post`) is a
   * separate, pre-ADR-022 table an `EntryRepoPort.findById` call can never resolve, which is why
   * `pageEntryId` had no real caller and every `widgetEmbed` node in a post body rendered the
   * REQ-28 placeholder forever, never real content. `undefined` when there is no host document
   * (the home route) or nothing to scan.
   */
  readonly pageBodyJson?: unknown;
  /** Region keys the current theme/template declares for this page. */
  readonly resolvedRegions: readonly WidgetRegionKey[];
}

export interface ResolvePageWidgetsRequired {
  deps: ResolvePageWidgetsDeps;
  input: ResolvePageWidgetsInput;
}

export interface ResolvePageWidgetsResult {
  readonly regions: Readonly<Record<WidgetRegionKey, readonly WidgetRenderIR[]>>;
  /** Keyed by `placementId` — one entry per `widgetEmbed` node in the page's `bodyJson`. */
  readonly inlineResolved: ReadonlyMap<UUID, WidgetRenderIR>;
}

/** REQ-28: a widget resolution failure renders an isolated placeholder — no internal detail in public output. */
const PLACEHOLDER_IR: WidgetRenderIR = { componentId: "widget-placeholder", props: {} };

function toRenderIr(result: WidgetResolveResult | undefined): WidgetRenderIR {
  return result?.ok ? result.ir : PLACEHOLDER_IR;
}

interface InlineEmbedRef {
  placementId: UUID;
  widgetEntryId: UUID;
  content?: JsonObject;
}

/** Pre-order visit of every non-array record node in a TipTap-shaped tree, kept off the call stack. */
function forEachDocNode(root: unknown, visit: (node: Record<string, unknown>) => void): void {
  const stack: unknown[] = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    if (Array.isArray(node)) {
      for (let i = node.length - 1; i >= 0; i--) stack.push(node[i]);
      continue;
    }
    const candidate = { value: node };
    if (!isNonArrayRecord(candidate)) continue;
    visit(candidate.value);
    if (Array.isArray(candidate.value.content)) stack.push(candidate.value.content);
  }
}

/** The inline ref a `widgetEmbed` node carries, or `undefined` for any other node or malformed attrs. */
function inlineEmbedRef(node: Record<string, unknown>): InlineEmbedRef | undefined {
  const attrs = { value: node.type === "widgetEmbed" ? node.attrs : undefined };
  if (!isNonArrayRecord(attrs) || typeof attrs.value.widgetEntryId !== "string" || typeof attrs.value.placementId !== "string") return undefined;
  return { placementId: attrs.value.placementId, widgetEntryId: attrs.value.widgetEntryId, ...(isNonArrayRecord({ value: attrs.value.content }) ? { content: attrs.value.content as JsonObject } : {}) };
}

/** Walks a TipTap-shaped bodyJson tree collecting every `widgetEmbed` node (REQ-21) — same shape `core/entry-refs/extractor.ts` walks, kept separate since this module has no dependency on `core/entry-refs`. */
function collectWidgetEmbeds(root: unknown, out: InlineEmbedRef[]): void {
  // An explicit stack, not recursion: a stored document's nesting depth is attacker/import-controlled
  // and a 5000-deep list overflowed the call stack here (GET /:slug -> 500) before `render.ts`'s own
  // MAX_RENDER_DEPTH placeholder could ever apply. Children are pushed in reverse so the walk stays
  // pre-order, the same visit order the recursive version had.
  forEachDocNode(root, (node) => {
    const embed = inlineEmbedRef(node);
    if (embed) out.push(embed);
  });
}

/**
 * Batch-loads and resolves every widget instance in `referencedIds` (REQ-24's "one batched query,
 * at most one `resolveWidgetType` call per type" guarantee) into a `widgetEntryId ->
 * WidgetResolveResult` map. Extracted so this exact batching contract has ONE implementation rather
 * than two that could silently diverge (SPEC-047 Slice 2 inline refactor beat) — `resolvePageWidgets`
 * (below, region + TipTap-inline-embed callers) and `resolveHtmlPageEmbeds` (an `"html"`-format
 * Page's `data-widget-embed` callers) both call this.
 *
 * Never throws (REQ-27's contract, unchanged by this extraction) — a malformed widget-instance
 * payload is skipped, not thrown; the caller's own placeholder-degradation step (REQ-28) handles a
 * ref that never made it into the returned map.
 *
 * @complexity O(1) plus one batched `listByWorkspace` query plus at most one `resolveWidgetType`
 * call per distinct widget type present among `referencedIds` (REQ-24).
 * @overallScore 100
 */
/** Parses one entries row into a {@link WidgetInstanceView}, or `null` when it should be skipped
 *  (REQ-27: a malformed payload, or an instance already trashed/purged). */
function parseWidgetInstanceRow(row: EntryRecord): WidgetInstanceView | null {
  let payload: ReturnType<typeof parseWidgetInstancePayload>;
  try {
    payload = parseWidgetInstancePayload({ fieldsJson: row.fieldsJson });
  } catch {
    // REQ-27: a malformed widget-instance payload is skipped, not thrown — the reference that
    // pointed at it simply has no resolved result, so the caller degrades it to the REQ-28
    // placeholder like any other unresolved reference.
    return null;
  }
  if (payload.status === "trash" || payload.status === "purged") return null;
  return { id: row.id, widgetType: payload.widgetType, config: payload.config as JsonObject };
}

/** Groups every referenced, resolvable widget row by its widget type (REQ-24's "one `resolveWidgetType`
 *  call per type" grouping step). */
function groupWidgetInstancesByType(
  widgetRows: readonly EntryRecord[],
  referencedIds: ReadonlySet<UUID>
): Map<WidgetTypeKey, WidgetInstanceView[]> {
  const byType = new Map<WidgetTypeKey, WidgetInstanceView[]>();
  for (const row of widgetRows) {
    if (!referencedIds.has(row.id)) continue;
    const instance = parseWidgetInstanceRow(row);
    if (!instance) continue;
    const list = byType.get(instance.widgetType) ?? [];
    list.push(instance);
    byType.set(instance.widgetType, list);
  }
  return byType;
}

async function resolveWidgetInstances(
  deps: WidgetInstanceResolutionDeps,
  workspaceId: UUID,
  referencedIds: ReadonlySet<UUID>,
  context: WidgetResolveContext,
  overrides: readonly { key: string; widgetEntryId: string; content: JsonObject }[] = [],
  originalIds: ReadonlySet<UUID> = referencedIds,
): Promise<ReadonlyMap<UUID, WidgetResolveResult>> {
  const widgetRows =
    referencedIds.size > 0 ? await deps.entryRepo.listByWorkspace({ workspaceId }, { type: WIDGET_CONTENT_TYPE }) : [];
  const byType = groupWidgetInstancesByType(widgetRows, originalIds);
  const rowsById = new Map(widgetRows.map(row => [row.id, row]));

  for (const override of overrides) {
    const row = rowsById.get(override.widgetEntryId);
    const saved = row ? parseWidgetInstanceRow(row) : null;
    if (!saved) continue;
    const instances = byType.get(saved.widgetType) ?? [];
    instances.push({ ...saved, id: override.key, config: { ...saved.config, ...override.content } });
    byType.set(saved.widgetType, instances);
  }
  const resolvedById = new Map<UUID, WidgetResolveResult>();
  for (const [typeKey, instances] of byType) {
    const results = await resolveWidgetType({ typeKey, instances, context });
    for (const [id, result] of results) resolvedById.set(id, result);
  }
  return resolvedById;
}

/**
 * Never throws (REQ-27's contract) — every per-widget failure is isolated to a placeholder IR node
 * (REQ-28) before this function returns.
 *
 * @complexity O(r) over `resolvedRegions` plus one batched widget-listing query plus one
 * `resolveWidgetType` call per distinct widget type present on the page (REQ-24).
 * @overallScore 100
 */
/** Step 1: region -> widget_area -> ordered, enabled placement list. A malformed widget_area
 *  payload or an unresolvable binding/area degrades that one region to "no widgets" (REQ-27) rather
 *  than throwing. */
async function resolveRegionPlacements(
  deps: ResolvePageWidgetsDeps,
  workspaceId: UUID,
  resolvedRegions: readonly WidgetRegionKey[]
): Promise<Map<WidgetRegionKey, WidgetPlacementNode[]>> {
  const regionPlacements = new Map<WidgetRegionKey, WidgetPlacementNode[]>();
  for (const regionKey of resolvedRegions) {
    regionPlacements.set(regionKey, []);
    const binding = await deps.bindingRepo.findByRegion({ workspaceId, regionKey });
    if (!binding) continue;
    const areaEntry = await deps.entryRepo.findById({ workspaceId, id: binding.areaEntryId });
    if (!areaEntry || areaEntry.type !== WIDGET_AREA_CONTENT_TYPE) continue;
    try {
      const payload = parseWidgetAreaPayload({ fieldsJson: areaEntry.fieldsJson });
      regionPlacements.set(
        regionKey,
        payload.doc.placements.filter((placement) => placement.enabled)
      );
    } catch {
      // REQ-27: a malformed widget_area payload (e.g. wiped by an unrelated generic-entry update
      // that bypassed this feature's own write path) degrades this one region to "no widgets" —
      // this function must never throw, matching the doc comment above it that this call site was
      // violating (Fable adversarial-review fix, 2026-07-21, Finding B).
    }
  }
  return regionPlacements;
}

/** Step 3: every distinct widget id referenced on the page, from BOTH region placements and inline
 *  embeds — the set `resolveWidgetInstances` batch-loads against (REQ-24). */
function collectReferencedWidgetIds(
  regionPlacements: ReadonlyMap<WidgetRegionKey, WidgetPlacementNode[]>,
  inlineEmbeds: readonly InlineEmbedRef[]
): Set<UUID> {
  const referencedIds = new Set<UUID>();
  for (const placements of regionPlacements.values()) {
    for (const placement of placements) referencedIds.add(placement.widgetEntryId);
  }
  for (const embed of inlineEmbeds) referencedIds.add(embed.widgetEntryId);
  return referencedIds;
}

export async function resolvePageWidgets(required: ResolvePageWidgetsRequired, _optional: Record<string, never> = {}): Promise<ResolvePageWidgetsResult> {
  const { deps, input } = required;
  const context: WidgetResolveContext = { workspaceId: input.workspaceId, preview: false };

  const regionPlacements = await resolveRegionPlacements(deps, input.workspaceId, input.resolvedRegions);

  // 2. Inline embeds from the host document's bodyJson (REQ-21/23).
  const inlineEmbeds: InlineEmbedRef[] = [];
  if (input.pageBodyJson !== undefined) collectWidgetEmbeds(input.pageBodyJson, inlineEmbeds);

  // 3. One batched widget-instance load for every distinct widget referenced on the page (REQ-24 —
  // see this file's header for why `listByWorkspace` stands in for a literal `WHERE id IN (...)`).
  const referencedIds = collectReferencedWidgetIds(regionPlacements, inlineEmbeds);

  // 4/5. Batch-load + resolve (skipping missing/trashed/purged targets — REQ-27's failure taxonomy
  // handles them as "unresolved", not a crash), at most one `resolveWidgetType` call per distinct
  // type present (REQ-24) — see `resolveWidgetInstances`'s own doc for why this is shared rather
  // than inlined here.
  const allPlacements = [...inlineEmbeds, ...[...regionPlacements.values()].flat()];
  const originalIds = new Set(allPlacements.filter(placement => !placement.content).map(placement => placement.widgetEntryId));
  const resolvedById = await resolveWidgetInstances(deps, input.workspaceId, referencedIds, context, inlineContentOverrides(allPlacements), originalIds);

  // 6. Assemble region -> IR[] (missing/failed placements degrade to the REQ-28 placeholder).
  const regions: Record<WidgetRegionKey, WidgetRenderIR[]> = {};
  for (const [regionKey, placements] of regionPlacements) {
    regions[regionKey] = placements.map((placement) => toRenderIr(resolvedById.get(placement.content ? placement.placementId : placement.widgetEntryId)));
  }

  // 7. Assemble placementId -> IR for inline embeds.
  return { regions, inlineResolved: assembleInlineResolved(inlineEmbeds, resolvedById) };
}

/** Placement config merges before asset resolution; a repeated widget never shares overridden IR. */
function inlineContentOverrides(embeds: readonly InlineEmbedRef[]): { key: string; widgetEntryId: string; content: JsonObject }[] {
  return embeds.flatMap(embed => embed.content ? [{ key: embed.placementId, widgetEntryId: embed.widgetEntryId, content: embed.content }] : []);
}

/** placementId -> IR for every inline embed; a missing/trashed/failed widget degrades to the REQ-28
 *  placeholder IR. Shared by {@link resolvePageWidgets} and {@link resolvePostContentWidgetContext}. */
function assembleInlineResolved(
  inlineEmbeds: readonly InlineEmbedRef[],
  resolvedById: ReadonlyMap<UUID, WidgetResolveResult>
): Map<UUID, WidgetRenderIR> {
  const inlineResolved = new Map<UUID, WidgetRenderIR>();
  for (const embed of inlineEmbeds) {
    inlineResolved.set(embed.placementId, toRenderIr(resolvedById.get(embed.content ? embed.placementId : embed.widgetEntryId)));
  }
  return inlineResolved;
}

// ---------------------------------------------------------------------------
// HTML Page embeds (SPEC-047 Slice 2, registry-restructured 2026-08-07 per
// `generic-embed-contract`) — resolves `html-embeds.ts`'s `data-embed-type`
// placeholder convention. A parallel entry point to `resolvePageWidgets` above, not a mode of it: an
// `"html"`-format Page has no `bodyJson` tree and is not an `entries` row `pageEntryId` could
// resolve (see `routes/site/pages.ts`'s `resolveWidgetsForRender`, which documents that same gap for
// the TipTap inline-embed path on the live `home`/`post` routes) — its references live in a plain
// HTML string instead, so they need their own scan step, not a `bodyJson` walk. Everything
// downstream of "which ids are referenced" is shared with `resolvePageWidgets`
// (`resolveWidgetInstances`, `resolveWidgetType`, the REQ-27/28 failure taxonomy).
// ---------------------------------------------------------------------------

/**
 * One embed type's resolver: given every {@link PageHtmlEmbedRef} of that type found on the page,
 * resolve as many as possible into a map keyed by the referenced id. A ref whose `id` is `null`
 * (missing or out-of-bounds `id` key in the marker config) can never be resolved — a resolver skips it and should
 * log a resolver-internal miss (see `HTML_EMBED_RESOLVERS`'s own doc for why this is a DIFFERENT log
 * line from "unknown embed type"). The returned map's "present-with-placeholder-vs-absent" shape
 * (a genuinely nonexistent target is ABSENT; a found-but-broken target is PRESENT with a placeholder
 * IR) mirrors {@link resolveWidgetInstances}'s own convention — both render identically via
 * `render.ts`'s `renderHtmlPageBody`, so this is not a behavior bug, same as the pre-restructuring
 * `widgetResolved`/`formResolved` shape this replaces.
 */
/**
 * `resolveHtmlPageEmbeds`'s full dependency set — a structural superset of
 * {@link WidgetInstanceResolutionDeps} (the `widget` resolver's own narrower need) plus the
 * OPTIONAL `mediaRepo`/`transformRepo` pair the `media` resolver needs. Optional, not required
 * (mirrors `PagesHtmlDocumentStoreDeps.entryRefsRepo`'s own "optional dependency" precedent), so
 * every pre-existing widget-only call site and test keeps compiling and behaving unchanged; a
 * `media` embed present with no `mediaRepo`/`transformRepo` supplied simply cannot resolve (logged,
 * degrades to the REQ-28 placeholder like any other unresolved reference) rather than forcing every
 * call site that never touches media to thread media dependencies through anyway.
 */
export interface ResolveHtmlPageEmbedsDeps extends WidgetInstanceResolutionDeps {
  /** Optional host admission port. Absence keeps the plugin marker's authored fallback. */
  readonly pluginExports?: PluginExportsPort;
  readonly host: Pick<WidgetHostPorts, "media" | "posts">;
  readonly mediaRepo?: MediaRepoPort;
  readonly transformRepo?: TransformDefinitionRepoPort;
  readonly postRepo?: PostRepoPort;
  readonly taxonomyRepo?: TaxonomyListPort;
  readonly termRepo?: TermListPort;
  /**
   * Video/embed capability (2026-08-24) — optional, same "degrade gracefully when absent" contract
   * `mediaRepo`/`transformRepo` already have. When present, {@link resolveMediaTypeEmbeds} uses it
   * to tell a video asset from an image one (keyed by `MediaRecord.source.sha256`, the same key
   * `routes/admin/media/upload.ts` already records under). Absent (every pre-existing call site
   * before this feature, and any future one that never touches media) means every asset resolves as
   * an image exactly as it always has — this is additive, not a behavior change for images.
   */
  readonly mediaContentTypeStore?: MediaContentTypeStorePort;
  /**
   * The site's zone (Bug D, 2026-10-22). When present, every `"post-content"` IR carries it as
   * `props.timeZone` so the host renders the header's date label as the site's calendar day; absent
   * leaves the props exactly as before (the host then renders UTC).
   */
  readonly siteTimeZone?: SiteTimeZonePort;
  /**
   * Template-preview pending-body fix (2026-08-12) — an explicitly-passed, per-call override for
   * exactly one entity id's content, consulted ONLY by {@link resolveContentTypeEmbeds}. Lets
   * `routes/admin/posts/template-preview.ts` preview the operator's unsaved, in-editor `bodyJson`
   * through the real render pipeline: without this, the current entity's own `{"type":"content"}`
   * slot (`injectCurrentEntityContentId`) always re-fetches by id via {@link findPublishedPostById},
   * which returns the last-SAVED row and silently discards any in-memory override the caller built
   * (`ADS-memory/reports/implementation/2026-08-11-template-preview-render-bug.md` documents the
   * sibling `templateChoice`-only bug this closes the `bodyJson` half of).
   *
   * Deliberately per-call, never a shared/global/module-level cache — threaded fresh through this
   * `deps` object on every `resolveHtmlPageEmbeds` call, so two concurrent preview requests for
   * different posts (or the same post from two browser tabs) can never observe each other's pending
   * body. `undefined` for every pre-existing call site; behavior for those is byte-identical to
   * before this field existed.
   *
   * `title`/`slug`/`updatedAt` are carried alongside `bodyJson` because {@link resolveContentTypeEmbeds}'s
   * resolved `"post-content"` IR needs all four regardless of source — this is the same shape a real
   * `findPublishedPostById` result already provides, just supplied directly instead of fetched.
   */
  readonly pendingContentOverride?: {
    readonly id: UUID;
    readonly title: string;
    readonly slug: string;
    readonly updatedAt: string;
    /** The row's go-live time — the date line shows it over `updatedAt` (`postDisplayDateIso`). */
    readonly publishAt?: string | null;
    readonly bodyJson: JsonObject;
  };
}

type HtmlEmbedResolver = (
  refs: readonly PageHtmlEmbedRef[],
  deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext
) => Promise<ReadonlyMap<string, WidgetRenderIR>>;

/**
 * Resolves every DISTINCT `slug` among `refs` (id-less refs only — {@link resolveWidgetTypeEmbeds}
 * never consults `slug` when `id` is present, see that function's own doc) to its widget entry's real
 * id, via one {@link EntryRepoPort.findBySlug} call per distinct slug, run concurrently
 * (`Promise.all`) — mirrors `resolveMediaTypeEmbeds`'s own per-ref fan-out for a lookup this port has
 * no batch primitive for. A slug with no matching widget warns and is simply absent from the returned
 * map — {@link resolveWidgetTypeEmbeds} degrades that exactly like a nonexistent `id` (REQ-27/28's
 * never-throws, degrade-to-placeholder discipline, unchanged for this new lookup path).
 *
 * `entries_workspace_type_slug_unique` (`workspaceId, type, slug`) makes "more than one match"
 * structurally impossible — unlike the dormant `name` fallback's own design, which had to hedge
 * against ambiguity because nothing backed it with a real unique index. That is why this function has
 * no "zero or >1 matches -> placeholder" branch: zero is the only failure shape a `findBySlug` call
 * against a UNIQUE-constrained column can produce.
 *
 * @complexity O(s) over the distinct slugs present, one `findBySlug` call each, run concurrently.
 */
async function resolveWidgetSlugsToIds(
  slugRefs: readonly PageHtmlEmbedRef[],
  deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext
): Promise<ReadonlyMap<string, UUID>> {
  const distinctSlugs = new Set(slugRefs.map((ref) => ref.slug as string));
  const idBySlug = new Map<string, UUID>();

  await Promise.all(
    Array.from(distinctSlugs).map(async (slug) => {
      const entry = await deps.entryRepo.findBySlug({ workspaceId: context.workspaceId, type: WIDGET_CONTENT_TYPE, slug });
      if (!entry) {
        console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "widget" reference — no widget with that slug', {
          workspaceId: context.workspaceId,
          slug,
        });
        return;
      }
      idBySlug.set(slug, entry.id);
    })
  );

  return idBySlug;
}

/** `data-embed-type="widget"` batches through the same {@link resolveWidgetInstances}
 * `resolvePageWidgets` uses — any widget type, any placement context; no widget-embed-specific
 * resolver logic exists or is needed beyond this thin adapter (plus, as of 2026-08-31, the `slug`
 * lookup {@link resolveWidgetSlugsToIds} performs). Behavior for an `id`-carrying ref is carried over
 * unchanged from the pre-restructuring `resolveHtmlPageEmbeds` widget path.
 *
 * **`id` is authoritative when present; `slug` is consulted only for a ref with no `id` at all** —
 * matches `html-embeds.ts`'s own doc on the two keys. A ref's `slug` is resolved to a real entry id
 * FIRST, then folded into the SAME `ids` set the id-carrying refs already populate, so id- and
 * slug-addressed widgets share {@link resolveWidgetInstances}'s one batched `listByWorkspace` query
 * (REQ-24) rather than paying for a second one. The returned map is keyed by whatever the MARKER
 * itself carried (`ref.id` for an id-based ref, `ref.slug` for a slug-based one) — never by the
 * resolved id a slug-based ref never had in its own markup — because `render.ts`'s
 * `renderHtmlPageBody` looks results up using that same marker-authored key (`ref.id ?? ref.slug`);
 * see that function's own doc.
 *
 * @complexity O(r) over `refs`, plus {@link resolveWidgetSlugsToIds}'s own O(s) slug-lookup cost, plus
 * {@link resolveWidgetInstances}'s one batched query and at most one `resolveWidgetType` call per
 * distinct widget type present (REQ-24) — unchanged from before this function gained `slug` support.
 */
/** Every id {@link resolveWidgetInstances} must batch-load for `refs` — an id-carrying ref's own
 * `id` directly, plus every slug-carrying ref's resolved id (`idBySlug`) folded into the SAME set,
 * so id- and slug-addressed widgets share one batched query (REQ-24). Warns once per ref carrying
 * neither a usable `id` nor `slug` at all. Split out of {@link resolveWidgetTypeEmbeds} to keep that
 * function's own complexity low (Programmer workflow 5a3) — this loop is pure bookkeeping, not a
 * second decision. */
function collectWidgetIdsToLoad(
  refs: readonly PageHtmlEmbedRef[],
  idBySlug: ReadonlyMap<string, UUID>,
  context: WidgetResolveContext
): Set<UUID> {
  const ids = new Set<UUID>();
  for (const ref of refs) {
    if (ref.id !== null) {
      ids.add(ref.id);
    } else if (ref.slug === null) {
      console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "widget" reference — missing or invalid "id"/"slug" in data-embed-config', {
        workspaceId: context.workspaceId,
      });
    }
  }
  for (const id of idBySlug.values()) ids.add(id);
  return ids;
}

/** Builds the final result, keyed by whatever the MARKER itself carried (`ref.id` for an id-based
 * ref, `ref.slug` for a slug-based one — never the resolved id a slug-based ref never had in its own
 * markup, see {@link resolveWidgetTypeEmbeds}'s own doc for why). `resolvedRaw` only carries an entry
 * for an id that named a REAL, non-trashed widget row (`resolveWidgetInstances`'s own doc) — a
 * nonexistent id/slug must stay ABSENT from the result, never present-with-placeholder, preserving
 * this file's present-vs-absent convention (`resolveHtmlPageEmbeds`'s own doc) unchanged from before
 * `slug` support existed. Split out of {@link resolveWidgetTypeEmbeds} for the same complexity reason
 * as {@link collectWidgetIdsToLoad}. */
function buildResolvedWidgetMap(
  refs: readonly PageHtmlEmbedRef[],
  idBySlug: ReadonlyMap<string, UUID>,
  resolvedRaw: ReadonlyMap<UUID, WidgetResolveResult>
): Map<string, WidgetRenderIR> {
  const resolved = new Map<string, WidgetRenderIR>();
  for (const ref of refs) {
    const resolvedId = ref.id ?? (ref.slug !== null ? idBySlug.get(ref.slug) : undefined);
    const lookupKey = ref.id ?? ref.slug;
    if (resolvedId !== undefined && lookupKey !== null && resolvedRaw.has(resolvedId)) {
      resolved.set(lookupKey, toRenderIr(resolvedRaw.get(resolvedId)));
    }
  }
  return resolved;
}

async function resolveWidgetTypeEmbeds(
  refs: readonly PageHtmlEmbedRef[],
  deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext
): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  const slugRefs = refs.filter((ref) => ref.id === null && ref.slug !== null);
  const idBySlug = await resolveWidgetSlugsToIds(slugRefs, deps, context);
  const ids = collectWidgetIdsToLoad(refs, idBySlug, context);
  const overrides = refs.flatMap(ref => {
    const content = ref.config?.content;
    const widgetEntryId = ref.id ?? (ref.slug ? idBySlug.get(ref.slug) : undefined);
    return widgetEntryId && ref.placementKey && isNonArrayRecord({ value: content })
      ? [{ key: ref.placementKey, widgetEntryId, content: content as JsonObject }] : [];
  });
  const originalIds = new Set(refs.filter(ref => !ref.placementKey).flatMap(ref => {
    const id = ref.id ?? (ref.slug ? idBySlug.get(ref.slug) : undefined);
    return id ? [id] : [];
  }));
  const resolvedRaw = await resolveWidgetInstances(deps, context.workspaceId, ids, context, overrides, originalIds);
  const resolved = buildResolvedWidgetMap(refs, idBySlug, resolvedRaw);
  for (const override of overrides) if (resolvedRaw.has(override.key)) resolved.set(override.key, toRenderIr(resolvedRaw.get(override.key)));
  return resolved;
}

/** A form slug/id is a synthetic contact-form instance, resolved through the widget pipeline. */
async function resolveFormTypeEmbeds(
  refs: readonly PageHtmlEmbedRef[],
  _deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext,
): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  const keys = [...new Set(refs.map((ref) => ref.id ?? ref.slug).filter((key): key is string => key !== null))];
  const results = await resolveWidgetType({
    typeKey: "contact-form",
    context,
    instances: keys.map((id) => ({ id, widgetType: "contact-form", config: { formDefinitionRef: id } })),
  });
  return new Map(keys.map((key) => [key, toRenderIr(results.get(key))]));
}

/**
 * `data-embed-type="media"` resolver (SPEC-047, 2026-08-07) — NEW logic, not adapted from
 * `resolveWidgetType`: a media embed targets an assets-domain record (`MediaRepoPort`), never a
 * `widget`-type entries row, so it shares nothing with `resolveWidgetInstances`'s batching shape
 * beyond the same REQ-27/28 never-throws/degrade-to-absent discipline every resolver here follows.
 *
 * `data-embed-id` is the `assetId`; `data-embed-variant` is the transform name, defaulting to
 * {@link CORE_PUBLIC_TRANSFORM_NAME} (`"public"`, confirmed live against `media/bootstrap.ts`'s own
 * boot registration, not assumed from the plan doc) when the author omits `data-embed-variant`.
 * Builds the same `/m/{assetId}/{transformName}.v{version}/...` URL contract `render.ts`'s TipTap
 * `image` case already uses — this function only resolves the DATA (`{assetId, transformName,
 * version, alt, width, height, cssClass}`); `render.ts`'s `renderWidgetMediaImage`/`renderImageTag`
 * own the actual URL templating and escaping (the "reuse, don't reimplement" split this dispatch was
 * asked for, mirroring how `resolveWidgetTypeEmbeds` resolves data and `renderWidgetIr` renders it).
 *
 * **Scope limitation versus the original implementation plan — CLOSED for video, still open for
 * everything else (2026-08-24).** The plan's step 3 called for dispatching by the asset's STORED
 * MIME TYPE. `MediaRecord` (`@jini-ai/cms/media`) still has no mime/contentType field of its own —
 * that remains an upstream `@jini-ai/cms` gap, not fixed here — but this host now has a
 * host-owned side channel for it: `mediaContentTypeStore` (`media/content-type-store.ts`), keyed by
 * `record.source.sha256`, already populated at upload time (`routes/admin/media/upload.ts`) for the
 * admin Media screen's own Images/Videos filter. When present and it knows the asset's type as
 * `video/*`, this resolver now skips the image-transform lookup entirely and resolves a `video`-kind
 * IR instead — `render.ts`'s `renderWidgetMediaImage` branches on it. Everything else (no store
 * supplied, a sha256 miss, or a non-video type) falls through to the exact image-only behavior this
 * resolver has always had. Audio is still unhandled — no audio player exists anywhere in this
 * codebase to dispatch to, and nothing in this pass's scope asked for one.
 *
 * Never throws (REQ-27): a missing `mediaRepo`/`transformRepo` dependency, an id/name that fails
 * {@link isPlausibleMediaRefId}'s shape check, a nonexistent asset, or an unregistered transform name
 * all leave that ref's id absent from the returned map — `render.ts`'s `renderHtmlPageBody` degrades
 * an absent id to the REQ-28 placeholder exactly as it does for every other resolver here.
 *
 * @complexity O(e) over the media refs present (already capped at `MAX_HTML_EMBEDS_PER_PAGE`
 * upstream by `scanHtmlEmbeds`) — one `MediaRepoPort.findById` plus, for a non-video asset, at most
 * one `getLatestTransformDefinition` call per ref, run concurrently via `Promise.all` (mirrors
 * `pages.ts`'s `resolveMediaAssetMetadataForRender`'s own per-asset `findById` fan-out — the same
 * frozen-no-batch-primitive situation `MediaRepoPort` discloses there). A video asset additionally
 * costs one `mediaContentTypeStore.getMany` call (single-element, same no-batch shape) but skips the
 * transform lookup entirely, so the per-ref cost never exceeds the pre-existing image path's.
 * @overallScore 100
 */
/** One resolved `MediaRepoPort.findById` row — inferred rather than imported since this file has no
 *  standing `MediaRecord` import (see `resolveMediaPublicUrls`'s own file for why `media/`'s public
 *  types stay narrow at each import site). */
type ResolvedMediaRecord = NonNullable<Awaited<ReturnType<MediaRepoPort["findById"]>>>;

/** The IR's `slug` for a resolved asset: `null` means "has none" (`MediaAssetRenderMeta`'s own
 *  contract), and a pre-backfill row stores that as `""`, so an empty slug is normalized to `null`
 *  rather than passed through. Shared by every media IR builder in this file. */
function mediaIrSlug(record: ResolvedMediaRecord): string | null {
  return record.slug || null;
}

/** Shape-narrows a media ref into a usable `{assetId, transformName}` pair, or `undefined` when the
 *  ref's `id`/`variant` fails {@link isPlausibleMediaRefId}'s check — split out of
 *  {@link resolveOneMediaEmbed} so that function's own branch count stays proportional to "which
 *  resolution step failed", not also this shape check. */
/**
 * T10 (2026-09-16 embed-attributes plan): `ref.id ?? ref.slug` — a `"media"` marker accepts a `slug`
 * the same way a `"widget"` marker already does ({@link resolveWidgetTypeEmbeds}'s own doc,
 * 2026-08-31): `id` wins when both are present and `slug` is never even consulted, matching
 * `resolveOneMediaEmbed`'s own doc on its `refAssetId` — the value returned here IS that map key, and
 * is passed straight into `findMediaByIdOrSlug`, which has always accepted either shape; only this
 * shape-check gate was missing it before. Named `assetId` still (not `idOrSlug`) since that field is
 * renamed at its one call site immediately.
 */
function parseMediaEmbedRef(
  ref: PageHtmlEmbedRef,
  context: WidgetResolveContext,
  host: Pick<WidgetHostPorts, "media">
): { assetId: string; transformName: string } | undefined {
  const assetId = ref.id ?? ref.slug;
  const transformName = ref.variant ?? host.media.publicTransformName;
  if (assetId === null || !isPlausibleMediaRefId({ value: assetId }) || !isPlausibleMediaRefId({ value: transformName })) {
    console.warn(
      '[widgets] resolveHtmlPageEmbeds: unresolved "media" reference — missing or invalid "id"/"slug"/"variant" in data-embed-config',
      { workspaceId: context.workspaceId }
    );
    return undefined;
  }
  return { assetId, transformName };
}

/** Builds the non-video (image-transform) IR for a resolved asset — the transform lookup + prop
 *  assembly {@link resolveOneMediaEmbed} defers to once it knows the asset isn't a video. `undefined`
 *  when `transformName` names no registered transform. */
async function buildMediaImageIr(
  assetId: string,
  transformName: string,
  transformRepo: TransformDefinitionRepoPort,
  record: ResolvedMediaRecord,
  context: WidgetResolveContext,
  host: Pick<WidgetHostPorts, "media">
): Promise<WidgetRenderIR | undefined> {
  const definition = await host.media.getLatestTransformDefinition({
    deps: { transformRepo },
    input: { workspaceId: context.workspaceId, name: transformName },
  });
  if (!definition) {
    console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "media" reference — transform not registered', {
      workspaceId: context.workspaceId,
      assetId,
      transformName,
    });
    return undefined;
  }
  return {
    componentId: "media-image",
    props: {
      assetId,
      // Readable-slugs S3: `render.ts`'s `renderWidgetMediaImage` reads this to build the emitted
      // `/m/...` URL via `mediaUrlKey` — `null`/absent falls back to `assetId`, same as every other
      // emitter. See the rewritten comment at this function's own caller for why emitting the slug
      // here is now safe (S2a/S2b's `media_slug_history` rename safety).
      slug: mediaIrSlug(record),
      sha256: record.source.sha256,
      transformName,
      version: definition.version,
      alt: record.alt,
      width: record.width,
      height: record.height,
      cssClass: record.cssClass,
      htmlAttributes: record.htmlAttributes,
    },
  };
}

/** The marker's asset record: a slug-only marker is looked up by slug, anything else by id-or-slug. */
function findMediaEmbedRecord({ ref, refAssetId, mediaRepo, context, host }: {
  ref: PageHtmlEmbedRef;
  refAssetId: string;
  mediaRepo: MediaRepoPort;
  context: WidgetResolveContext;
  host: Pick<WidgetHostPorts, "media">;
}): Promise<ResolvedMediaRecord | null> {
  return ref.id === null && ref.slug !== null
    ? mediaRepo.findBySlug({ workspaceId: context.workspaceId, slug: ref.slug })
    : host.media.findMediaByIdOrSlug({ deps: { mediaRepo }, input: { workspaceId: context.workspaceId, idOrSlug: refAssetId } });
}

/** The recorded content type of `record`'s bytes, or `undefined` with no store or no recorded type. */
async function lookupMediaContentType(
  { record, context }: { record: ResolvedMediaRecord; context: WidgetResolveContext },
  { mediaContentTypeStore }: { mediaContentTypeStore?: MediaContentTypeStorePort | undefined } = {},
): Promise<string | undefined> {
  if (!mediaContentTypeStore) return undefined;
  const types = await mediaContentTypeStore.getMany({ workspaceId: context.workspaceId, sha256s: [record.source.sha256] });
  return types.get(record.source.sha256);
}

/** Video and audio render through the native player, never the image-transform pipeline. */
function isPlayerContentType(contentType: string | undefined): contentType is string {
  return contentType?.startsWith("video/") === true || contentType?.startsWith("audio/") === true;
}

function playerMediaIr({ canonicalAssetId, record, contentType }: { canonicalAssetId: string; record: ResolvedMediaRecord; contentType: string }): WidgetRenderIR {
  return {
    componentId: "media-image",
    props: {
      assetId: canonicalAssetId,
      slug: mediaIrSlug(record),
      sha256: record.source.sha256,
      contentType,
      alt: record.alt,
      width: record.width,
      height: record.height,
      cssClass: record.cssClass,
      htmlAttributes: record.htmlAttributes,
    },
  };
}

/** One media ref's resolved id + IR, or `undefined` when it could not be resolved — extracted so
 *  {@link resolveMediaTypeEmbeds}'s own `Promise.all` callback is a thin per-ref dispatch, never the
 *  decision itself. `mediaRepo`/`transformRepo` are passed non-optional here: the caller has already
 *  guarded their absence before ever constructing this per-ref work. */
async function resolveOneMediaEmbed(
  ref: PageHtmlEmbedRef,
  mediaRepo: MediaRepoPort,
  transformRepo: TransformDefinitionRepoPort,
  mediaContentTypeStore: MediaContentTypeStorePort | undefined,
  context: WidgetResolveContext,
  host: Pick<WidgetHostPorts, "media">
): Promise<{ assetId: string; ir: WidgetRenderIR } | undefined> {
  const parsed = parseMediaEmbedRef(ref, context, host);
  if (!parsed) return undefined;
  // `refAssetId` is exactly what the marker's `data-embed-id` says — a theme author may write
  // either the asset's `id` or its `slug` (2026-09-07). It stays the MAP KEY this function returns
  // (`resolveMediaTypeEmbeds`'s caller looks up the resolved map by the marker's own literal id, so
  // the key must match what was typed, not what it resolved to). `props.assetId` below is still
  // normalized to the canonical `record.id` (the gate/lookup identifier), but `render.ts` no longer
  // builds the served `/m/...` URL straight from it: as of readable-slugs S3, `props.slug` (added
  // below) is what `mediaUrlKey` actually emits into `src`, falling back to `props.assetId` only when
  // there is no valid slug. A later slug rename no longer risks breaking a URL already baked into
  // previously-rendered HTML — that used to be `record.id`'s whole reason for being the emitted
  // value; now it is `media_slug_history` (S2a/S2b) keeping the OLD slug resolving too.
  const { assetId: refAssetId, transformName } = parsed;

  const record = await findMediaEmbedRecord({ ref, refAssetId, mediaRepo, context, host });
  if (!record || record.status !== "active") {
    console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "media" reference — no such asset', {
      workspaceId: context.workspaceId,
      assetId: refAssetId,
    });
    return undefined;
  }
  const canonicalAssetId = record.id;

  const contentType = await lookupMediaContentType({ record, context }, { mediaContentTypeStore });
  if (isPlayerContentType(contentType)) {
    // Video/audio need no image transform lookup: the shared native-player renderer points at
    // `/m/{assetId}/original` (the byte-passthrough route — see that route's own doc for why
    // video can't go through the image-transform pipeline below), so `transformName`/`version`
    // would be unused props for this IR.
    return { assetId: refAssetId, ir: playerMediaIr({ canonicalAssetId, record, contentType }) };
  }

  const ir = await buildMediaImageIr(canonicalAssetId, transformName, transformRepo, record, context, host);
  return ir ? { assetId: refAssetId, ir } : undefined;
}

async function resolveMediaTypeEmbeds(
  refs: readonly PageHtmlEmbedRef[],
  deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext
): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  const resolved = new Map<string, WidgetRenderIR>();
  const { mediaRepo, transformRepo, mediaContentTypeStore } = deps;
  if (!mediaRepo || !transformRepo) {
    if (refs.length > 0) {
      console.warn(
        '[widgets] resolveHtmlPageEmbeds: "media" embeds present but no mediaRepo/transformRepo dependency was supplied — every occurrence degrades to the placeholder',
        { workspaceId: context.workspaceId, occurrences: refs.length }
      );
    }
    return resolved;
  }

  const entries = await Promise.all(
    refs.map((ref) => resolveOneMediaEmbed(ref, mediaRepo, transformRepo, mediaContentTypeStore, context, deps.host))
  );
  for (const entry of entries) {
    if (entry) resolved.set(entry.assetId, entry.ir);
  }

  return resolved;
}

/** Gallery widget adapter over the same media owner used by gallery HTML embeds. */
export function resolveGalleryWidgetMedia(
  { refs, deps, context }: { refs: readonly PageHtmlEmbedRef[]; deps: ResolveHtmlPageEmbedsDeps; context: WidgetResolveContext },
  _optional: Record<string, never> = {},
): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  return resolveMediaTypeEmbeds(refs, deps, context);
}

/** Scans a TipTap-shaped `bodyJson` tree for every ref-based `image`/`media` node's `assetId`
 *  (ADR-027 §4's `{assetId, transformName}` shape) — both the legacy image-only ref shape and the
 *  generic `media` node (2026-09-11, `render.ts`'s `renderDocMedia`'s own doc) share this collection,
 *  since both key their sizing/content-type override off the SAME `mediaAssetMetadata` map by
 *  `assetId` alone. Widened 2026-09-11 (owner-reported, verifying the admin Preview-tab fix: a
 *  `media` node embedded in a post's body rendered as a placeholder through this exact
 *  "post-content" IR path, even with the asset/transform fine, because this collector only ever
 *  recognized `"image"`) to match `routes/site/pages.ts`'s own `collectMediaRefAssetIds`, which was
 *  widened the same day — renamed from `isRefBasedImageNode`/`collectImageAssetIds` accordingly. Same
 *  walk shape as that module's copy, still duplicated rather than imported: that module sits above
 *  this one in the codebase's layering (this file's `resolveMediaTypeEmbeds`'s own doc discloses the
 *  same constraint for `render.ts`). A legacy `image` node (only `attrs.src`, no `assetId`) is never
 *  added — nothing here needs a sizing/version override for that shape. */
/** A TipTap `image` or `media` node carrying the `{assetId, transformName}` ref shape (vs. a legacy
 *  `image` node's `attrs.src`-only shape, which `media` has no equivalent of at all — see this file's
 *  header on `Media`/`renderDocMedia` for why). */
function isRefBasedMediaNode(obj: Record<string, unknown>): obj is Record<string, unknown> & { attrs: Record<string, unknown> } {
  return (obj.type === "image" || obj.type === "media") && typeof obj.attrs === "object" && obj.attrs !== null;
}

function collectMediaRefAssetIds(root: unknown, out: Set<string>): void {
  // Iterative for the same reason as {@link collectWidgetEmbeds} (a 5000-deep post overflowed here).
  forEachDocNode(root, (node) => {
    if (isRefBasedMediaNode(node) && typeof node.attrs.assetId === "string") out.add(node.attrs.assetId);
  });
}

/**
 * Owner-reported bug (2026-08-12, widened 2026-09-11 to also collect the generic `media` node — see
 * {@link collectMediaRefAssetIds}'s own doc) — resolves the `mediaTransformVersions`/
 * `mediaAssetMetadata` context a "post-content" IR's embedded TipTap doc needs to render its OWN
 * ref-based `image`/`media` nodes as real pictures instead of the filename-labelled placeholder.
 * Before this function existed,
 * NEITHER value was ever resolved for this render path at all: `render.ts`'s `renderWidgetPostContent`
 * called `renderDocNode(bodyJson)` with no media context, which silently defaults both to empty maps
 * — every ref-based image's transform lookup was unconditionally a miss, regardless of whether the
 * asset/transform genuinely existed (confirmed live: asset uploaded, `"public"` transform
 * registered, `/m/` rendition route returning 200 — and still a placeholder, because nothing upstream
 * ever looked any of that up for this render path). See `renderWidgetPostContent`'s own doc in
 * `render.ts` for the full trace.
 *
 * Mirrors `routes/site/pages.ts`'s `resolveMediaTransformVersionsForRender`/
 * `resolveMediaAssetMetadataForRender` — the identical resolution the generic (non-template) render
 * path already performs for `renderSite` — reusing THIS file's own `getLatestTransformDefinition`/
 * `mediaRepo.findById` primitives (already proven correct here by {@link resolveMediaTypeEmbeds}, the
 * sibling `"media"` embed resolver) rather than a third implementation of either lookup.
 *
 * Returns plain JSON, not `Map`s: `WidgetRenderIR.props` is a `JsonObject`, and this file must not
 * import `render.ts` (see this file's layering note above) to build a real `Map` and hand it across
 * that boundary directly. `render.ts`'s `readMediaTransformVersions`/`readMediaAssetMetadata`
 * reconstruct the `Map`s `renderDocNode` needs from this exact shape.
 *
 * Never throws (REQ-27, same discipline every resolver in this file follows): a `bodyJson` with no
 * ref-based images, or missing `mediaRepo`/`transformRepo` deps, resolves to empty objects —
 * `render.ts`'s `image` case already degrades an absent transform-version/metadata entry to the
 * placeholder, never a crash.
 *
 * Single-transform-name shortcut deliberately mirrored from `resolveMediaTransformVersionsForRender`
 * (not a per-node scan of every distinct `transformName` present): `registerTransform` has exactly
 * one caller anywhere in this codebase (`ensureCoreMediaTransform`), which only ever registers
 * {@link CORE_PUBLIC_TRANSFORM_NAME} — see that function's own doc for the full disclosure and what
 * widening this would take.
 *
 * Widened 2026-09-11 to also resolve `contentType` (`render.ts`'s `MediaAssetRenderMeta.contentType`'s
 * own doc), closing the gap that doc's own history section used to describe: this function's caller
 * is NOT limited to "a page embeds this post" — `routes/site/pages.ts`'s `renderViaTemplate` reaches
 * this same function (via `resolveContentTypeEmbeds`'s DB branch) for a post rendered at its OWN
 * public URL through a static-tier theme template, so a video asset in a post's own body was
 * silently rendering as `<img>` there too, not only when embedded into a page. Resolved via
 * `deps.mediaContentTypeStore`, keyed by the resolved record's `source.sha256` (the bytes' identity,
 * not the asset id) — the identical mechanism `resolveOneMediaEmbed` (this file's own sibling `media`
 * embed-type resolver) and `resolveMediaAssetMetadataForRender` (`routes/site/pages.ts`) both already
 * use, batched into ONE `getMany` call across every resolved asset rather than one call per asset
 * (that function's own shape, not `resolveOneMediaEmbed`'s per-ref shape, since this function already
 * gathers every ref up front). `mediaContentTypeStore` absent, or a sha256 with no recorded type,
 * both degrade `contentType` to `null` — read by `render.ts`'s `renderDocMedia` as "not video", never
 * a crash or a guess.
 *
 * @complexity O(a) over the distinct ref-based `assetId`s the body references, each behind one
 * `mediaRepo.findById` call, run concurrently via `Promise.all` alongside the single transform-
 * definition lookup — same shape `resolveMediaAssetMetadataForRender` and `resolveMediaTypeEmbeds`
 * both already use for their own per-asset fan-out — PLUS one further batched
 * `MediaContentTypeStorePort.getMany` call across every resolved asset's sha256 at once, run after
 * that fan-out resolves (its input is those results), mirroring `resolveMediaAssetMetadataForRender`'s
 * identical two-step shape.
 */
async function resolvePostContentMediaContext(
  deps: ResolveHtmlPageEmbedsDeps,
  bodyJson: JsonObject,
  context: WidgetResolveContext
): Promise<{ mediaTransformVersions: JsonObject; mediaAssetMetadata: JsonObject }> {
  const { mediaRepo, transformRepo, mediaContentTypeStore } = deps;
  const assetIds = new Set<string>();
  collectMediaRefAssetIds(bodyJson, assetIds);
  if (assetIds.size === 0 || !mediaRepo || !transformRepo) {
    return { mediaTransformVersions: {}, mediaAssetMetadata: {} };
  }

  const [definition, resolvedRecords] = await Promise.all([
    deps.host.media.getLatestTransformDefinition({
      deps: { transformRepo },
      input: { workspaceId: context.workspaceId, name: deps.host.media.publicTransformName },
    }),
    Promise.all(
      Array.from(assetIds).map(async (assetId): Promise<readonly [string, ResolvedMediaRecord] | undefined> => {
        const record = await mediaRepo.findById({ workspaceId: context.workspaceId, id: assetId });
        return record ? ([assetId, record] as const) : undefined;
      })
    ),
  ]);
  const found = resolvedRecords.filter((entry): entry is readonly [string, ResolvedMediaRecord] => entry !== undefined);

  const contentTypes =
    found.length > 0 && mediaContentTypeStore
      ? await mediaContentTypeStore.getMany({ workspaceId: context.workspaceId, sha256s: found.map(([, record]) => record.source.sha256) })
      : undefined;

  return {
    mediaTransformVersions: definition ? { [deps.host.media.publicTransformName]: definition.version } : {},
    mediaAssetMetadata: Object.fromEntries(
      found.map(([assetId, record]) => [
        assetId,
        {
          width: record.width,
          height: record.height,
          cssClass: record.cssClass,
          htmlAttributes: record.htmlAttributes,
          slug: mediaIrSlug(record),
          sha256: record.source.sha256,
          contentType: contentTypes?.get(record.source.sha256) ?? null,
        },
      ])
    ),
  };
}

/**
 * Owner-reported bug (2026-09-22) — the inline-widget half of a "post-content" IR's render context,
 * the sibling of {@link resolvePostContentMediaContext}. A `widgetEmbed` node in the embedded body
 * used to render as the placeholder on every template-rendered post, because `render.ts`'s
 * `renderWidgetPostContent` had no `inlineResolved` map to look its `placementId` up in. Resolves
 * through the SAME `collectWidgetEmbeds`/`resolveWidgetInstances`/`assembleInlineResolved` chain
 * `resolvePageWidgets` uses for the non-template path, and returns plain JSON
 * (`placementId -> WidgetRenderIR`) for the same layering reason that function's doc gives;
 * `render.ts`'s `readInlineWidgets` rebuilds the `Map`.
 *
 * @complexity O(w) over the body's `widgetEmbed` nodes plus, only when there is at least one, one
 * batched widget-instance load and one `resolveWidgetType` call per distinct type (REQ-24).
 */
async function resolvePostContentWidgetContext(
  deps: ResolveHtmlPageEmbedsDeps,
  bodyJson: JsonObject,
  context: WidgetResolveContext
): Promise<{ inlineWidgets: JsonObject }> {
  const inlineEmbeds: InlineEmbedRef[] = [];
  collectWidgetEmbeds(bodyJson, inlineEmbeds);
  if (inlineEmbeds.length === 0) return { inlineWidgets: {} };
  const referencedIds = new Set(inlineEmbeds.map((embed) => embed.widgetEntryId));
  const resolvedById = await resolveWidgetInstances(deps, context.workspaceId, referencedIds, context, inlineContentOverrides(inlineEmbeds), new Set(inlineEmbeds.filter(embed => !embed.content).map(embed => embed.widgetEntryId)));
  const inlineResolved = assembleInlineResolved(inlineEmbeds, resolvedById);
  return { inlineWidgets: Object.fromEntries(inlineResolved) as unknown as JsonObject };
}

/** Everything a "post-content" IR's embedded body needs to render beyond the body itself — media
 *  context plus inline widgets — spread into the IR's `props` by all three "post-content" builders. */
async function resolvePostContentRenderContext(
  deps: ResolveHtmlPageEmbedsDeps,
  bodyJson: JsonObject,
  context: WidgetResolveContext
): Promise<JsonObject> {
  const [mediaContext, widgetContext, timeZone] = await Promise.all([
    resolvePostContentMediaContext(deps, bodyJson, context),
    resolvePostContentWidgetContext(deps, bodyJson, context),
    deps.siteTimeZone ? resolveSiteTimeZoneSafely({ workspaceId: context.workspaceId }, { siteTimeZone: deps.siteTimeZone }) : undefined,
  ]);
  return { ...mediaContext, ...widgetContext, ...(timeZone === undefined ? {} : { timeZone }) };
}

/**
 * Resolves a post/page row by whichever key a {@link PageHtmlEmbedRef} carries — `id` authoritative
 * when present, `slug` consulted only for a ref with no `id` at all. Same order
 * {@link resolveWidgetTypeEmbeds}'s slug fallback and `resolveMediaTypeEmbeds`'s `parseMediaEmbedRef`
 * already use for `widget`/`media` markers (S3, 2026-09-23 widget-attrs plan — `post`/`content` gain
 * the identical treatment those two got in 2026-08-31/2026-09-16, deliberately deferred until now;
 * see the retired paragraph this replaces in git history for why it was left out of those passes).
 * `posts.slug` is unique per workspace (`posts_workspace_slug_unique`), so — like the widget/media
 * cases — there is no "more than one match" branch to hedge against.
 *
 * Shared by {@link resolvePostTypeEmbeds} and {@link resolveContentTypeEmbeds} so both go through the
 * ONE id-else-slug lookup, via the identical visibility guard ({@link findPublishedPostById}/
 * {@link findPublishedPostBySlug}), rather than two copies that could drift apart.
 *
 * Non-throwing: `null` means "not found or not visible" — the same
 * REQ-27 degrade-to-placeholder contract every resolver in this registry follows.
 *
 * @complexity O(1) — one guarded repo lookup (by id or by slug, never both), no iteration.
 */
async function findPublishedPostByRef(
  postRepo: PostRepoPort,
  ref: Pick<PageHtmlEmbedRef, "id" | "slug">,
  context: WidgetResolveContext,
  host: Pick<WidgetHostPorts, "posts">
): Promise<PostRecord | null> {
  if (ref.id !== null) {
    return host.posts.findPublishedPostById({ deps: { repo: postRepo }, input: { workspaceId: context.workspaceId, id: ref.id } });
  }
  // `slug` is non-null here: both callers (`resolvePostTypeEmbeds`, `resolveOneContentEmbed`) return
  // before calling this when `ref.id ?? ref.slug` is null, so an id-less ref always carries a slug.
  return host.posts.findPublishedPostBySlug({ deps: { repo: postRepo }, input: { workspaceId: context.workspaceId, slug: ref.slug! } });
}

/**
 * `data-embed-type="post"` resolver — the post-template-picker feature (post-template.md's own
 * design conversation, first shipped 2026-08-10). `data-embed-id`/`data-embed-slug` name the post's
 * stored id or its unique slug, resolved by {@link findPublishedPostByRef} immediately above (id
 * authoritative when both are present).
 *
 * Returns RAW post data (title/bodyJson/updatedAt/slug), not rendered HTML — this file (`widgets/`)
 * must not depend on `server/http/site/render.ts` (that module sits above this one in the codebase's
 * layering, the same constraint `resolveMediaTypeEmbeds`'s own doc discloses for why it returns
 * `{assetId, transformName, ...}` instead of an `<img>` string). `render.ts`'s `renderWidgetIr`
 * `"post-content"` case (which already has `renderDocNode` in scope) does the actual TipTap-to-HTML
 * render from this data.
 *
 * A caller with no `postRepo` supplied (every pre-existing call site) behaves exactly like a `media`
 * embed with no `mediaRepo` — every occurrence degrades to the placeholder, logged once, not silently.
 *
 * **Visibility fix, 2026-08-11**: was `postRepo.findById` directly — `PostRepoPort.findById` is
 * trash- and status-BLIND by design (`post.ts`'s own doc on that port), so this resolver could
 * previously pull ANY row by id, including an unpublished draft or a trashed one, onto the public
 * site. That hole predates and is independent of this date's `content`-marker work, but is fixed
 * here alongside it (same file, same class of hazard, same fix already being built for
 * {@link resolveContentTypeEmbeds}'s guard) rather than left live next to a freshly-hardened sibling
 * resolver. See {@link findPublishedPostById}'s own doc for why this differs from the raw port call.
 */
async function resolvePostTypeEmbeds(
  refs: readonly PageHtmlEmbedRef[],
  deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext
): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  const resolved = new Map<string, WidgetRenderIR>();
  const { postRepo } = deps;
  if (!postRepo) {
    if (refs.length > 0) {
      console.warn(
        '[widgets] resolveHtmlPageEmbeds: "post" embeds present but no postRepo dependency was supplied — every occurrence degrades to the placeholder',
        { workspaceId: context.workspaceId, occurrences: refs.length }
      );
    }
    return resolved;
  }

  await Promise.all(
    refs.map(async (ref) => {
      const key = ref.id ?? ref.slug;
      if (key === null) {
        console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "post" reference — missing or invalid "id"/"slug" in data-embed-config', {
          workspaceId: context.workspaceId,
        });
        return;
      }
      const post = await findPublishedPostByRef(postRepo, ref, context, deps.host);
      if (!post) {
        console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "post" reference — no such published post', {
          workspaceId: context.workspaceId,
          postId: key,
        });
        return;
      }
      const renderContext = await resolvePostContentRenderContext(deps, post.bodyJson, context);
      resolved.set(key, {
        componentId: "post-content",
        props: { title: post.title, slug: post.slug, updatedAt: post.updatedAt, publishAt: post.publishAt ?? null, bodyJson: post.bodyJson, ...renderContext },
      });
    })
  );

  return resolved;
}

/** Whether the preview override stands in for `ref`: by id when the ref carries one, else by slug. */
function matchesPendingOverride(
  ref: Pick<PageHtmlEmbedRef, "id" | "slug">,
  override: NonNullable<ResolveHtmlPageEmbedsDeps["pendingContentOverride"]>,
): boolean {
  return ref.id !== null ? ref.id === override.id : ref.slug === override.slug;
}

/** The `"post-content"` IR for one post body source (a saved post or the preview override). */
async function postContentIr({ source, ref, deps, context }: {
  source: Pick<PostRecord, "title" | "slug" | "updatedAt" | "bodyJson"> & { readonly publishAt?: string | null | undefined };
  ref: PageHtmlEmbedRef;
  deps: ResolveHtmlPageEmbedsDeps;
  context: WidgetResolveContext;
}): Promise<WidgetRenderIR> {
  const renderContext = await resolvePostContentRenderContext(deps, source.bodyJson, context);
  return {
    componentId: "post-content",
    props: {
      title: source.title,
      slug: source.slug,
      updatedAt: source.updatedAt,
      publishAt: source.publishAt ?? null,
      bodyJson: source.bodyJson,
      header: ref.header,
      ...renderContext,
    },
  };
}

/** Resolves one `"content"` ref into `resolved` (keyed by its id, else slug), or logs why it stays unresolved. */
async function resolveOneContentEmbed({ ref, deps, context, resolved }: {
  ref: PageHtmlEmbedRef;
  deps: ResolveHtmlPageEmbedsDeps;
  context: WidgetResolveContext;
  resolved: Map<string, WidgetRenderIR>;
}): Promise<void> {
  const { postRepo, pendingContentOverride } = deps;
  const key = ref.id ?? ref.slug;
  if (key === null) {
    console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "content" reference — missing or invalid "id"/"slug" in data-embed-config', {
      workspaceId: context.workspaceId,
    });
    return;
  }

  // Preview override, checked BEFORE any DB call (see `pendingContentOverride`'s own doc):
  // the operator's pending, unsaved body for this exact row, never a fetch. Matches by `id` when
  // the ref carries one (id authoritative, same order `findPublishedPostByRef` uses below), by
  // `slug` only for a slug-only ref. Routes through the identical `"post-content"` IR/props shape
  // the DB branch below builds, so this substitutes only the DATA SOURCE — every downstream
  // render/sanitization step (`render.ts`'s `renderWidgetPostContent` -> `renderDocNode`) is the
  // SAME code the saved-body path runs, never a second, parallel render path with its own
  // escaping rules.
  if (pendingContentOverride && matchesPendingOverride(ref, pendingContentOverride)) {
    resolved.set(key, await postContentIr({ source: pendingContentOverride, ref, deps, context }));
    return;
  }

  // No DB source for this ref (postRepo absent) and it didn't match the override above: nothing
  // safe to do but leave it unresolved — degrades to the REQ-28 placeholder like any other miss.
  if (!postRepo) return;

  const entity = await findPublishedPostByRef(postRepo, ref, context, deps.host);
  if (!entity) {
    console.warn('[widgets] resolveHtmlPageEmbeds: unresolved "content" reference — no such published entity', {
      workspaceId: context.workspaceId,
      entityId: key,
    });
    return;
  }
  if (entity.bodyFormat === "html") {
    console.warn(
      '[widgets] resolveHtmlPageEmbeds: unresolved "content" reference — html-format entity reached the registry resolver instead of the recursive pre-splice pass (depth/budget guard, or a direct reference outside a template render)',
      { workspaceId: context.workspaceId, entityId: key }
    );
    return;
  }
  resolved.set(key, await postContentIr({ source: entity, ref, deps, context }));
}

/**
 * `data-embed-type="content"` resolver — the unified content marker's registry-owned half
 * (2026-08-11, `ADS-memory/reports/design/2026-08-11-unified-content-marker-and-templates.md`).
 * Handles `"doc"`-format targets ONLY: an `"html"`-format target's own body, and any FURTHER
 * `content` markers nested inside it, are fetched, recursively resolved, and spliced in BEFORE this
 * stage ever runs (`pages.ts`'s `resolveHtmlFormatContentMarkers` pre-pass, called ahead of
 * `resolveHtmlPageEmbeds` from the template render path) — by the time the shared marker scan reaches
 * this registry, an `html`-format reference has either already been consumed by that pre-pass or hit
 * its depth/budget guard (below). Either way there is nothing safe to do here but degrade to the
 * placeholder, same as any other unresolved reference: this resolver must never splice raw HTML
 * itself, which is exactly what would collapse guard 1's doc/html escaping split into one branchless
 * path (a TipTap doc renders through `renderDocNode`'s node-aware escaping; stored Page HTML is
 * spliced at the trust level `PagesHtmlDocumentStore`/`pages.edit_html` already assume for it — the
 * two must stay on separate code paths, never merged behind one generic "just render whatever this
 * is" function).
 *
 * Reuses the EXISTING `"post-content"` render IR (`renderWidgetPostContent` in `render.ts`) rather
 * than a new componentId: that function already renders ANY `{title, bodyJson, updatedAt}` bag
 * regardless of the source row's `kind` — nothing in it is Post-specific — so a `kind: "page"`
 * doc-format row (e.g. `our-story`) renders through the identical, already-vetted path a `kind:
 * "post"` row does. The `"post-content"` label itself is pre-existing and not renamed here (`render.ts`
 * is not in this change's file list); a follow-up rename to a kind-neutral label is low-priority tech
 * debt, disclosed rather than silently left unmentioned.
 *
 * Visibility-filtered via {@link findPublishedPostByRef} (guard 2, the highest-risk part of the
 * unified-marker design): an id OR slug supplied by an author, OR an id auto-filled by
 * `injectCurrentEntityContentId` for the entity the route already resolved (never a slug —
 * `injectCurrentEntityContentId` skips any marker already carrying a `slug`, its own doc explains
 * why), can in principle name ANY row — this is the one place in the new marker's resolution chain
 * that decides whether that row is allowed to reach the public page. The guard is on the ROW
 * {@link findPublishedPostByRef} returns, identical regardless of which key found it.
 *
 * `pendingContentOverride` (2026-08-12; slug matching added S3 2026-09-23) bypasses this specific
 * `findPublishedPostByRef` call, but NOT the visibility guard's intent: it only ever matches ONE
 * row — the exact one `routes/admin/posts/template-preview.ts` already fetched (any status, but
 * through its own `content.read`-authorized, session-gated lookup) and is previewing back to the
 * SAME authenticated operator who owns that unsaved edit. It matches by `id` when the ref carries
 * one (never falling through to `slug` for that same ref — the identical authoritative-when-present
 * order {@link findPublishedPostByRef} uses below), by `slug` only for a slug-only ref. It can never
 * be used to inject content for a DIFFERENT row than the one the caller resolved and authorized —
 * see the override's own doc on {@link ResolveHtmlPageEmbedsDeps.pendingContentOverride}.
 *
 * `ref.header` (2026-09-04, {@link PageHtmlEmbedRef.header}'s own doc) is threaded into IR
 * `props.header` unchanged in BOTH branches below — the DB lookup and the `pendingContentOverride`
 * short-circuit both read it off the SAME scanned `ref`. This value is only ever a STAGING default,
 * though, not what actually renders: `resolved` below is keyed by `ref.id`, one IR per id, so if the
 * same id is embedded twice with different `header` options the two `resolved.set` calls race and
 * one silently overwrites the other here — the `fc1a506a` bug (2026-09-05). `render.ts`'s
 * `renderHtmlPageBody`/`withOccurrenceHeader` is what actually makes this safe: it discards this
 * staged `header` and re-applies the CURRENT occurrence's own `ref.header` at substitution time,
 * where the real per-occurrence ref is available. See the `resolved` map's own comment immediately
 * below before adding another per-occurrence option here — the same collision reopens unless it
 * gets the same substitution-time treatment.
 *
 * @complexity O(e) over the `content` refs present (already capped upstream at
 * `MAX_HTML_EMBEDS_PER_PAGE`) — one `findPublishedPostById` call per ref not satisfied by
 * {@link ResolveHtmlPageEmbedsDeps.pendingContentOverride}, run concurrently via `Promise.all`,
 * mirroring every other resolver in this registry.
 */
async function resolveContentTypeEmbeds(
  refs: readonly PageHtmlEmbedRef[],
  deps: ResolveHtmlPageEmbedsDeps,
  context: WidgetResolveContext
): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  // Keyed by `ref.id`, ONE staged IR per id — not per occurrence. Any prop set here from
  // occurrence-specific data (e.g. `header` in `props` below) is only a default: if the same id is
  // embedded more than once on a page with different per-occurrence options, the concurrent
  // `resolved.set` calls below race and whichever ref wins decides that prop for every occurrence,
  // silently dropping the others' — the exact bug `fc1a506a` (2026-09-05) fixed for `header`.
  // Occurrence-specific options must be re-applied at SUBSTITUTION time instead, where the real
  // per-occurrence `ref` is available (`render.ts`'s `renderHtmlPageBody`/`withOccurrenceHeader` is
  // `header`'s own fix); staging one here is fine only as long as every consumer of this Map applies
  // that same override for its own option.
  const resolved = new Map<string, WidgetRenderIR>();
  const { postRepo, pendingContentOverride } = deps;
  if (!postRepo && !pendingContentOverride) {
    if (refs.length > 0) {
      console.warn(
        '[widgets] resolveHtmlPageEmbeds: "content" embeds present but no postRepo dependency was supplied — every occurrence degrades to the placeholder',
        { workspaceId: context.workspaceId, occurrences: refs.length }
      );
    }
    return resolved;
  }

  await Promise.all(refs.map((ref) => resolveOneContentEmbed({ ref, deps, context, resolved })));

  return resolved;
}

/**
 * Registry of known embed types (SPEC-047, generalized 2026-08-07). Adding a new embed type is
 * registering one more entry here — no other file in `resolveHtmlPageEmbeds`'s call chain changes,
 * and `html-embeds.ts`'s scanner already reports any type token it finds regardless of whether an
 * entry exists here (see that file's own doc). A type ABSENT from this registry is the "unknown
 * embed type" log path in {@link resolveHtmlPageEmbeds}; a type PRESENT here whose resolver still
 * can't find a given id/name is the "resolver-internal miss" log path inside that resolver
 * (`resolveWidgetTypeEmbeds`/`resolveMediaTypeEmbeds` above) — DECIDED (2026-08-07) to keep these
 * two distinguishable in logs even though both render the identical REQ-28 placeholder externally:
 * an author's markup typo (unknown type) and an author's stale reference (known type, dead id) are
 * different problems needing different fixes.
 *
 * Historically `form` was removed (2026-08-10) because it was shorthand for a synthetic
 * contact-form widget. The owner explicitly restores both spellings (2026-10-04): keep that
 * synthetic instance on the SAME registered contact-form resolver so the two cannot drift.
 */
export const HTML_EMBED_RESOLVERS: Readonly<Record<string, HtmlEmbedResolver>> = {
  // Template filling needs parse5, which this universal module must not load: the node-only
  // `resolveHtmlPageEmbeds` (`html/resolve-html-page-embeds.ts`) overrides this entry with the real
  // resolver. Reached from here, every plugin occurrence keeps its authored fallback.
  plugin: async () => new Map(),
  widget: resolveWidgetTypeEmbeds,
  form: resolveFormTypeEmbeds,
  taxonomy: (refs, deps) => resolveTaxonomyEmbeds({ refs, deps }),
  media: async (refs, deps, context) => {
    const inline = refs.filter(ref => ref.config?.content !== undefined || ref.config?.items !== undefined || ref.config?.html !== undefined);
    const ordinary = refs.filter(ref => !inline.includes(ref));
    const media = await resolveMediaTypeEmbeds(ordinary, deps, context);
    const content = await resolveGalleryEmbeds({
      refs: inline.map(ref => ({ ...ref, config: (ref.config?.content ?? ref.config) as Readonly<Record<string, unknown>> })),
      resolveMedia: ({ refs }) => resolveMediaTypeEmbeds(refs, deps, context),
    }, { reportIssue: ({ key, messages }) => console.warn('[widgets] unresolved media content', { key, messages }) });
    return new Map([...media, ...content]);
  },
  gallery: (refs, deps, context) => resolveGalleryEmbeds({
    refs,
    resolveMedia: ({ refs: mediaRefs }) => resolveMediaTypeEmbeds(mediaRefs, deps, context),
  }, {
    reportIssue: ({ key, messages }) => console.warn('[widgets] unresolved gallery embed', { workspaceId: context.workspaceId, key, messages }),
  }),
  post: resolvePostTypeEmbeds,
  content: resolveContentTypeEmbeds,
} satisfies Record<PageEmbedType, HtmlEmbedResolver>;

/**
 * Marker types that exist in the shared `data-embed-config` vocabulary (`core/embeds/marker.ts`) but
 * are deliberately absent from {@link HTML_EMBED_RESOLVERS} — a theme's own structural markers, owned
 * end-to-end by `features/theme/static-render.ts`'s `resolveSlots` (`"partial"`) and
 * `injectMenuEmbeds` (`"menu"`), which run AFTER this stage on every static-tier page render
 * (`routes/site/pages.ts`'s `renderViaTemplate`: `resolveHtmlPageEmbeds` first, then
 * `renderStaticPage`). `isPageEmbedType`'s own doc already tells `render.ts`'s `renderHtmlPageBody` to
 * leave these two untouched rather than substitute a placeholder over the nav — that fixed the
 * SUBSTITUTION half of "this stage sees markers it does not own" (2026-08-10). This constant fixes the
 * matching LOGGING half, which that earlier fix did not touch.
 *
 * Without this, {@link resolveHtmlPageEmbeds}'s "unknown embed type" warning fired for `menu`/`partial`
 * on every single static-tier render — confirmed live during the 2026-08-16 GitHub Pages export
 * (`gh-pages` commit `c0e52de2`, published demo): the log claimed "every
 * occurrence degrades to the placeholder," which was false — curling the published page showed real,
 * resolved `<a href>` links in both the nav and footer, zero placeholder markup anywhere. The page was
 * never broken; only the diagnostic was. Left uncorrected, that false alarm fires on every render and
 * trains a reader to ignore this log line, burying the ONE case it exists to catch: an author's actual
 * markup typo (`HTML_EMBED_RESOLVERS`'s own doc on why "unknown type" and "known type, dead id" must
 * stay distinguishable applies equally to "known-and-owned-elsewhere" vs. "owned nowhere").
 *
 * A type in this set must stay absent from `HTML_EMBED_RESOLVERS` — do not "fix" the warning by adding
 * a resolver entry instead; see `isPageEmbedType`'s own doc for why that would reintroduce the
 * substitution bug this file already fixed once.
 *
 * **Why this isn't just `!isPageEmbedType(type)`.** `isPageEmbedType` is membership in `PAGE_EMBED_TYPES`,
 * which the compiler holds equal to `HTML_EMBED_RESOLVERS`'s keys — exactly the same fact this loop's own
 * `HTML_EMBED_RESOLVERS[type]` lookup already tests, one
 * bit: "is this resolver-service's own type." That bit is `false` for `partial`/`menu` AND for a genuine
 * unregistered/typo type alike, so it cannot distinguish "known, owned by a later stage" from "owned
 * nowhere" — using it to gate the warning would silence the ONE case the warning exists for, not just
 * the two it shouldn't fire for. This set names the missing fact directly instead. It intentionally
 * duplicates `static-render.ts`'s own `marker.type !== "menu"`/`!== "partial"` literals rather than
 * importing them (that file is a different feature's territory in this change's dispatch) — the real
 * fix, hoisting a shared constant into `core/embeds/marker.ts` for both files to import, is proposed but
 * not yet authorized; see `ADS-memory/reports/2026-08-16-embed-placeholder-gap.md`'s "Reuse decision"
 * section. Keep this set's members in sync with those two literals, not with `isPageEmbedType`.
 *
 * `"post-previews"` (2026-09-03) joins the set for the identical reason: it is resolved by
 * `static-render.ts`'s `injectPostPreviewsEmbeds`, AFTER this stage, on every static-tier page
 * render that reaches `renderStaticPage` — same duplicated-literal debt as the other two entries
 * (see `POST_PREVIEWS_MARKER_TYPE`, `core/embeds/marker.ts`), not yet hoisted for the same reason.
 *
 * `"collection"` (2026-09-23) joins the set for the identical reason: it is resolved by
 * `static-render.ts`'s `injectCollectionEmbeds`, AFTER this stage — same duplicated-literal debt as
 * the other three entries (see `COLLECTION_MARKER_TYPE`, `core/embeds/marker.ts`).
 *
 * `"featured-image"` (2026-10-05) joins for the identical reason: `static-render.ts`'s
 * `injectFeaturedImage` resolves it (see `FEATURED_IMAGE_MARKER_TYPE`, `core/embeds/marker.ts`).
 *
 * `"post-author"` (2026-10-11) joins for the identical reason: `static-render.ts`'s
 * `injectPostAuthor` fills the byline. Without it this stage warned once per post render while the
 * byline rendered correctly.
 */
export const THEME_OWNED_MARKER_TYPES: ReadonlySet<string> = new Set(["partial", "menu", "post-previews", "collection", "featured-image", "post-author", "comments"]);

/**
 * `isPageEmbedType` (the "does this stage OWN the marker type" question, with its own doc) lives in
 * the dependency-free `page-embed-types.ts` so `render.ts` and the theme render workers can ask it
 * without loading this file's service graph. Re-exported so existing importers keep working.
 */
export { isPageEmbedType } from "./page-embed-types.js";

import type { JsonObject } from "@jini-ai/core/primitives";
import type { NavMenuReadModel, ResolvedNavItem, ResolveTargetHrefFn } from "../../navigation/index.js";
import type { MenusPort } from "./ports.js";
import type { WidgetResolveResult, WidgetResolver } from "../types.js";

/**
 * @file `menu` (menu-as-widget) resolver (SPEC-043 REQ-09, ADR-047 §1/§9 — "the primary menu as a
 * widget in the footer region costs nothing new").
 *
 * Purpose:
 * Delegates to `navigation`'s own read model — zero menu STORAGE logic duplicated in `widgets/`
 * (`getMenu`, a real `NavMenuReadModel` call, not a reimplementation of `MenuRepoPort`) — and now
 * also zero menu-HREF-RESOLUTION logic duplicated, via `navigation/resolver.ts`'s exported
 * `resolveMenuDoc` (the doc-level building block `resolveForLocation` itself composes on top of).
 * `resolveItemList`/`resolveItem` stay module-private in `navigation/resolver.ts`; `resolveMenuDoc`
 * is the one exported entry point to their behavior, added specifically so this resolver would not
 * need either an export-widening of those internals or a location-shaped call it doesn't have.
 *
 * Historical limitation (retained to explain the fallback): real href resolution for non-`url` targets (`entryRef`/`termRef`/
 * `route`) needs `src/platform/routing` (ADR-039), which is being built in parallel and is not running code
 * yet anywhere in this codebase — not even `navigation`'s own production callers have a real
 * `ResolveTargetHrefFn` today (`resolveForLocation` takes it as an injected dependency precisely so
 * a fake can stand in until routing lands, per `navigation/resolver.ts`'s own header). This resolver
 * is in the same honest position as the rest of the system, not a special-cased worse one: `url`-kind
 * targets (already-resolved hrefs, no injected dependency needed) now resolve to real, concrete
 * `href`/`available`/`isActive` data; `entryRef`/`termRef`/`route` targets resolve to
 * `available: false, href: null` via the placeholder `resolveTargetHref` below, exactly the outcome
 * `navigation/resolver.ts`'s own doc describes for "cannot resolve" — swap the placeholder for the
 * real routing-backed implementation in one place (`DEFAULT_RESOLVE_TARGET_HREF` below) once
 * `src/platform/routing` ships; no other change needed here.
 * 2026-10-04: runtime roots now inject the routing-backed page/entry resolver. The default remains
 * useful for diagnostics; public widget assembly omits unavailable leaves while retaining parents
 * that still contain visible descendants, matching the static menu's availability contract.
 */
export interface MenuResolverDeps {
  menus: MenusPort;
  navMenuReadModel: NavMenuReadModel;
  /** Public widgets omit unavailable leaves; diagnostics may retain the complete resolved tree. */
  publicOnly?: boolean;
  /** Host routing injection; callers without it retain the diagnostic placeholder documented above. */
  resolveTargetHref?: ResolveTargetHrefFn;
}

/** Before host routing was wired every non-URL target was unresolved; retain that safe null fallback. */
const DEFAULT_RESOLVE_TARGET_HREF: ResolveTargetHrefFn = async () => null;

function toMenuItemProps(items: readonly ResolvedNavItem[], publicOnly: boolean): JsonObject {
  // Cast: ResolvedNavItem is a plain, JSON-serializable read model (navigation/types.ts) with no
  // index signature of its own — the resolved IR contract only requires structural JSON-compatibility.
  const visible = publicOnly ? items.flatMap((item) => {
    const children = toMenuItemProps(item.children, true) as unknown as ResolvedNavItem[];
    return item.available || children.length ? [{ ...item, children }] : [];
  }) : items;
  return visible as unknown as JsonObject;
}

/**
 * Resolve menu widgets through navigation's read model: stored HTML or resolved items by doc mode.
 * HTML is trusted and balanced by navigation's save path (`mergeMenuHtml`), like static menus;
 * forwarding it adds no second parser or sanitization policy. Read failures propagate to dispatch.
 * @param deps - Navigation read/resolution ports and host routing/public-filter policy.
 * @returns A resolver producing mode-specific menu IR, or existing typed config/target failures.
 * @complexity One read per instance; item resolution/filtering scales with the selected item trees.
 */
export function createMenuResolver(deps: MenuResolverDeps, _optional: Record<string, never> = {}): WidgetResolver {
  const resolveTargetHref = deps.resolveTargetHref ?? DEFAULT_RESOLVE_TARGET_HREF;

  return {
    async resolveMany(instances, context) {
      const results = new Map<string, WidgetResolveResult>();
      for (const instance of instances) {
        const menuRef = typeof instance.config.menuRef === "string" ? instance.config.menuRef : undefined;
        if (!menuRef) {
          results.set(instance.id, { ok: false, reason: "invalid-config" });
          continue;
        }

        const menu = await deps.navMenuReadModel.getMenu({ workspaceId: context.workspaceId, menuId: menuRef });
        if (!menu) {
          results.set(instance.id, { ok: false, reason: "target-disabled" });
          continue;
        }

        let props: JsonObject;
        if (menu.doc.mode === "html") {
          props = { title: menu.title, mode: "html", html: menu.doc.html ?? "" };
        } else {
          const items = await deps.menus.resolveMenuDoc({
            doc: menu.doc,
            context: { workspaceId: context.workspaceId },
            resolveTargetHref,
          });
          props = { title: menu.title, items: toMenuItemProps(items, deps.publicOnly === true) };
        }

        results.set(instance.id, {
          ok: true,
          ir: { componentId: "menu", props },
          dependencyKeys: [menu.id],
        });
      }
      return results;
    },
  };
}

import type { TaxonomyListPort, TermListPort } from "../../taxonomy/index.js";
import type { PageHtmlEmbedRef } from "../html/html-embeds.js";
import type { WidgetRenderIR } from "../types.js";

/** Workspace-scoped read ports are supplied by the host, like the other HTML embed resolvers. */
export async function resolveTaxonomyEmbeds(
  { refs, deps }: { refs: readonly PageHtmlEmbedRef[]; deps: { taxonomyRepo?: TaxonomyListPort; termRepo?: TermListPort } },
  _optional = {},

): Promise<ReadonlyMap<string, WidgetRenderIR>> {
  const resolved = new Map<string, WidgetRenderIR>();
  if (!deps.taxonomyRepo || !deps.termRepo) return resolved;
  const taxonomies = (await deps.taxonomyRepo.list()).filter((taxonomy) => taxonomy.status !== "trash" && taxonomy.status !== "purged");
  const termsById = new Map<string, Awaited<ReturnType<TermListPort["listByTaxonomy"]>>>();
  for (const ref of refs) {
    const key = ref.id;
    if (!key) continue;
    // Names are human-readable targets, but unlike slugs are not guaranteed unique.
    // An ambiguous name is unresolved, never an arbitrary choice; real ids win.
    const matches = taxonomies.filter((taxonomy) => taxonomy.name === key);
    const taxonomy = taxonomies.find((candidate) => candidate.id === key) ?? (matches.length === 1 ? matches[0] : undefined);
    if (!taxonomy) continue;
    let terms = termsById.get(taxonomy.id);
    if (!terms) {
      terms = await deps.termRepo.listByTaxonomy({ taxonomyId: taxonomy.id });
      termsById.set(taxonomy.id, terms);
    }
    resolved.set(key, {
      componentId: "taxonomy-list",
      props: {
        id: taxonomy.id, name: taxonomy.name, hierarchical: taxonomy.hierarchical,
        terms: terms.filter((term) => term.taxonomyId === taxonomy.id && term.status !== "trash" && term.status !== "purged")
          .map((term) => ({ id: term.id, name: term.name, parentId: term.parentId })),
      },
    });
  }
  return resolved;
}

/**
 * @file Core type definitions for the host `widgets` library (ADR-047, SPEC-043).
 *
 * Purpose:
 * Widgets are placeable, reusable, individually-configured components (a contact
 * form, a recent-posts list, a text block, social links, a menu) placed either
 * into a theme-declared region (an ordered list, backed by a seeded
 * `widget_area` entry) or embedded inline inside a page's rich-text body (a
 * `widgetEmbed` TipTap node). A widget instance is a seeded ADR-022 content
 * entry (type `widget`), exactly as a menu is (ADR-029) — this file mirrors
 * `navigation/types.ts` deliberately, per the ADR-047 debate's finding that the
 * region-binding mechanism must structurally match `nav_location_bindings`
 * (source-of-truth-on-the-entry + a derived, reconciled binding index), not
 * merely resemble it.
 *
 * How it relates to the project:
 * - `core/ports.ts` supplies the shared primitives (`UUID`, `JsonObject`, …).
 * - `widgets/ports.ts` declares the one rule-of-two port this library adds
 *   (`WidgetRegionBindingRepoPort`, mirroring `NavLocationBindingRepoPort`).
 * - `widgets/registry.ts` declares the v1 widget-type registry as plain data —
 *   see that file for why type *registration* and type *behavior* are split.
 * - The theme renderer never resolves a widget reference itself (ADR-020 §7 /
 *   ADR-029 §7's "theme receives resolved data" boundary, unchanged here).
 *
 * Architectural role:
 * INTERFACES + TYPES ONLY (no feature logic). This is the design-frozen shape
 * ADR-047 (as amended by its 2026-07-21 debate fold-in) introduces; the entries
 * repo, revisions, and the command gateway are reused unchanged from ADR-022 /
 * ADR-008.
 */
import type { ISODateTime, JsonObject, UUID } from "@jini-ai/core/primitives";

// ---------------------------------------------------------------------------
// Content-type identity
// ---------------------------------------------------------------------------

/** `widget` ships as a seeded content-type registry row (ADR-022 §1), like `post`/`page`/`menu`. */
export const WIDGET_CONTENT_TYPE = "widget" as const;

/**
 * `widget_area` ships as a seeded, **system-managed** content-type registry
 * row — never publicly routable, never itself placeable as a widget, never a
 * valid `widgetEmbed` target (REQ-17 — no recursion into a region from inside
 * a region).
 */
export const WIDGET_AREA_CONTENT_TYPE = "widget_area" as const;

/** The extension-field owner namespace for widget-level fields (`fields.ext.widget.*`). */
export const WIDGET_FIELD_NAMESPACE = "widget" as const;

/** The extension-field owner namespace for a `widget_area` entry's region assignment. */
export const WIDGET_AREA_FIELD_NAMESPACE = "widgets" as const;

// ---------------------------------------------------------------------------
// Widget-type registry (data — see registry.ts for the registration/behavior split)
// ---------------------------------------------------------------------------

/**
 * The v1 widget-type keys (SPEC-043 REQ-09). Kept as a closed union rather than
 * a bare `string` so a typo in a registration or a call site is a compile error,
 * not a runtime `unknown-type` surprise.
 */
export type WidgetTypeKey = "text" | "social-links" | "recent-entries" | "menu" | "contact-form" | "gallery" | "media";

/**
 * A widget type's declared capability class (ADR-047 Debate Fold-In Amendment
 * 3). `static` types render validated config directly with no resolver;
 * `query`/`form`/`entry-reference` types have a registered resolver in the
 * closed `CORE_RESOLVERS` map (`resolvers/index.ts`).
 */
export type WidgetCapability = "static" | "query" | "form" | "entry-reference";

/** Where a widget type may legally be placed. */
export type WidgetPlacementContext = "region" | "inline";

/**
 * A widget type's **registration** — plain, JSON-serializable data (SPEC-043
 * REQ-07). Never imports or references executable behavior; the only pointer
 * to code this record carries is `resolverId`, which must resolve *only*
 * through the closed `CORE_RESOLVERS` map (REQ-08) — never a module path,
 * function name, query string, or expression.
 */
export interface WidgetTypeRegistration {
  readonly typeKey: WidgetTypeKey;
  readonly capability: WidgetCapability;
  /** JSON-Schema-shaped description of `fields.ext.widget.*`'s valid shape for this type. */
  readonly configSchema: JsonObject;
  readonly placementContexts: readonly WidgetPlacementContext[];
  /** Cost clamps enforced by core at the orchestration layer, never by the resolver's own discipline (REQ-25). */
  readonly clamps: {
    readonly maxItems?: number;
    readonly timeoutMs: number;
  };
  /** `undefined` for `static`-capability types (REQ-10). Indexes into `CORE_RESOLVERS` only. */
  readonly resolverId?: string;
}

// ---------------------------------------------------------------------------
// The widget instance (a typed view over an ADR-022 `entries` row)
// ---------------------------------------------------------------------------

/**
 * `purged` is observably distinct from `trash` (REQ-43): both are treated identically everywhere a
 * widget instance's availability is checked (resolution, placement validation — see
 * `resolver-service.ts`/`region-area-service.ts`), but only `purged` records that the instance was
 * force-deleted past a known reference (`purgeWidgetInstance({ force: true })`), vs. an ordinary
 * `trash` that may still be restored with no prior reference conflict. No real hard-delete exists in
 * this codebase for any content type (`EntryRepoPort` has no delete method) — this status is the
 * cheap, in-model way to keep that distinction visible without one.
 *
 * No `draft` member (Fable adversarial-review fix, 2026-07-21, Finding F) — `write-service.ts`
 * creates every widget instance directly as `active`; nothing anywhere in this codebase ever writes
 * `draft`. A prior version of this union carried it anyway, which was a live landmine: the
 * resolver/placement-validation skip lists above only ever checked for `trash`/`purged`, so a
 * `draft` status — had anything ever produced one — would have rendered publicly instead of being
 * held back. Removed rather than defensively added to the skip lists, since there is no real
 * "draft" concept for widget instances to guard.
 */
export type WidgetInstanceStatus = "active" | "trash" | "purged";

/**
 * A typed read model over a `type='widget'` entries row (ADR-022 §2 universal
 * columns) plus the parsed `fields.ext.widget.*` config bag. A projection, not
 * a new table — widget instances are entries (REQ-01).
 */
export interface WidgetInstanceEntry {
  readonly id: UUID;
  readonly workspaceId: UUID;
  readonly slug: string;
  readonly title: string;
  readonly status: WidgetInstanceStatus;
  readonly widgetType: WidgetTypeKey;
  /** Validated against the type's registered `configSchema` on every write (REQ-02). */
  readonly config: JsonObject;
  readonly updatedAt: ISODateTime;
  readonly version: number;
}

// ---------------------------------------------------------------------------
// Region composition (a typed view over a `widget_area` entry)
// ---------------------------------------------------------------------------

/** A theme-registered region key (e.g. `header`, `footer`, `sidebar`). */
export type WidgetRegionKey = string;

/** One entry in a `widget_area`'s ordered placement list (lives in the area entry's `bodyJson`). */
export interface WidgetPlacementNode {
  /** Stable ULID, minted once, preserved across reorders — for diagnostics and `entry_refs` locators. */
  readonly placementId: UUID;
  readonly widgetEntryId: UUID;
  readonly enabled: boolean;
  /** Optional per-placement config overlay, resolved before media lookup. */
  readonly content?: JsonObject;
}

/** The full region-composition document stored in a `widget_area` entry's `bodyJson`. */
export interface WidgetAreaDoc {
  readonly schemaVersion: number;
  readonly placements: readonly WidgetPlacementNode[];
}

/**
 * A typed read model over a `type='widget_area'` entries row. `regionKey` is
 * the **source of truth** for which region this area fills
 * (`fields.ext.widgets.regionKey`) — mirrors `NavMenuEntry.locations` exactly
 * (ADR-047 Debate Fold-In Amendment 1).
 */
export interface WidgetAreaEntry {
  readonly id: UUID;
  readonly workspaceId: UUID;
  readonly regionKey: WidgetRegionKey;
  readonly doc: WidgetAreaDoc;
  readonly updatedAt: ISODateTime;
  readonly version: number;
}

// ---------------------------------------------------------------------------
// Region binding index (derived, rebuildable — the one new widgets-owned table)
// ---------------------------------------------------------------------------

/**
 * A row of the derived `widget_region_bindings` index. **Derived + rebuildable**
 * from `WidgetAreaEntry.regionKey` at the write chokepoint (same species as
 * `nav_location_bindings` and ADR-022 §5 `entry_refs`), NOT a source of truth
 * and NOT revision-generating (INV-02). Reconciled by exactly one code path
 * (`region-area-service.ts`'s `reconcileWidgetRegionBindings`) — never
 * hand-authored.
 */
export interface WidgetRegionBindingRow {
  readonly workspaceId: UUID;
  readonly regionKey: WidgetRegionKey;
  readonly areaEntryId: UUID;
  readonly updatedAt: ISODateTime;
}

/** A theme/plugin-registered widget region (mirrors `NavLocationDescriptor`). */
export interface WidgetRegionDescriptor {
  readonly key: WidgetRegionKey;
  readonly label: string;
  readonly registeredBy: string;
  readonly description?: string;
}

// ---------------------------------------------------------------------------
// Inline embed (a node inside any entry's TipTap `bodyJson`)
// ---------------------------------------------------------------------------

/**
 * The `widgetEmbed` node's persisted shape. A block-level atom (REQ-18) — never
 * nested inside a widget instance's own `bodyJson` (REQ-19, INV-04), enforced
 * by `embed-validation.ts`'s `validateWidgetEmbedMutation`, the single
 * validator both the live-editor path and the server-side/AI path call.
 */
export interface WidgetEmbedNode {
  readonly type: "widgetEmbed";
  readonly placementId: UUID;
  readonly widgetEntryId: UUID;
}

// ---------------------------------------------------------------------------
// Resolution (the render-time contract — Debate Fold-In Amendment 2)
// ---------------------------------------------------------------------------

/** The internal render IR node shape every resolved widget produces (ADR-020's canonical render IR). */
export interface WidgetRenderIR {
  readonly componentId: string;
  readonly props: JsonObject;
  readonly children?: readonly WidgetRenderIR[];
}

/** Context passed to a resolver for one page render (REQ-23). */
export interface WidgetResolveContext {
  readonly workspaceId: UUID;
  readonly locale?: string;
  readonly preview: boolean;
}

/** A minimal, read-only view of a widget instance passed into a resolver — never a raw DB handle (SPEC-043's REQ-24 batching contract). */
export interface WidgetInstanceView {
  readonly id: UUID;
  readonly widgetType: WidgetTypeKey;
  readonly config: JsonObject;
}

/** Why a widget resolution failed (SPEC-043 REQ-27's closed failure taxonomy). */
export type WidgetResolveFailureReason =
  | "unknown-type"
  | "invalid-config"
  | "target-disabled"
  | "timeout"
  | "resolver-error";

export type WidgetResolveResult =
  | { readonly ok: true; readonly ir: WidgetRenderIR; readonly dependencyKeys: readonly string[] }
  | { readonly ok: false; readonly reason: WidgetResolveFailureReason };

/**
 * The typed resolver contract every dynamic (non-`static`) widget type
 * implements (REQ-23/24). **Batch-first by design** — `resolveMany` is called
 * at most once per type per page render (REQ-24), never once per placement, so
 * N+1 query cost is a contract violation, not an optimization opportunity.
 */
export interface WidgetResolver {
  resolveMany(
    instances: readonly WidgetInstanceView[],
    context: WidgetResolveContext
  ): Promise<ReadonlyMap<UUID, WidgetResolveResult>>;
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
/**
 * @file Widget-instance CRUD through the existing entries chokepoint (SPEC-043 REQ-01..06, REQ-42/43).
 *
 * Purpose:
 * Same chokepoint discipline as `posts`/`menus`/`forms` — no parallel mutation path. A widget
 * instance is a `type='widget'` entries row (ADR-022 §1); every write here composes
 * `features/entries/write-service.ts`'s real `createEntry`/`updateEntry` chokepoint (never
 * reimplemented) so revisions and slug-uniqueness come for free.
 *
 * Deleting (2026-09-21, generic Trash): `trashWidgetInstance` moves a widget to the Trash through
 * the injected `remove` and is UNCONDITIONAL (EC-07 — a trashed target degrades to the REQ-28
 * placeholder). The old second rung, `purgeWidgetInstance` (a `purged` payload status that never
 * removed the row, REQ-42/43), is retired: "delete permanently" is now the Trash's purge, and
 * `adoptLegacyTrashedWidgets` moves the widgets it left behind into the Trash, and
 * `restoreWidgetPriorStatus` makes one of them active again when it is restored.
 *
 * `entry_refs` extraction (INV-06) runs inside the same DB transaction as the triggering
 * `createEntry`/`updateEntry` call, via that chokepoint's optional `deps.onWritten` hook (added
 * 2026-07-21 — a narrow, additive extension to `features/entries/write-service.ts`, invoked after
 * `save`/`appendRevision` but before commit, so a failed extraction rolls back the whole write; see
 * the implementation report for why this was previously sequenced after instead).
 *
 * Architectural role:
 * `widgets` domain logic (implementation outline C-005).
 */
import type { Clock as ClockPort, JsonObject, UUID } from "@jini-ai/core/primitives";
import type { OutboxPort } from "../core/index.js";
import type { EntryRefsRepoPort } from "./ports.js";

import type { ContentTypeRepoPort } from "../content-types/index.js";
import type { EntryListPort, EntryRecord, EntryRepoPort } from "../entries/index.js";
import {
  PRE_AUTHORIZED,
  requireWidgetPermission,
  type WidgetsAuthorizeFn,
} from "./authorize-helper.js";
import { withEntryLock, type EntryLockState } from "./concurrency.js";
import { validateWidgetConfig, type WidgetConfigFieldError } from "./config-validation.js";
import {
  buildWidgetInstanceFieldsJson,
  ensureWidgetContentTypesRegistered,
  parseWidgetInstancePayload,
  toWidgetInstanceEntry,
} from "./entry-payload.js";
import {
  WidgetConfigValidationError,
  WidgetInstanceNotFoundError,
  WidgetTypeUnregisteredError,
  WidgetVersionConflictError,
} from "./errors.js";
import { findWidgetTypeRegistration } from "./registry.js";
import { WIDGET_CONTENT_TYPE, WIDGET_FIELD_NAMESPACE } from "./types.js";
import type { RemoveWidgetFn } from "./ports.js";
import type { WidgetInstanceEntry, WidgetInstanceStatus, WidgetTypeKey, WidgetTypeRegistration } from "./types.js";
import type { WidgetHostPorts } from "./host-ports.js";

export interface WidgetWriteServiceDeps {
  /** One store-owned state shared by write, embed and region services; omission preserves compatibility. */
  entryLocks?: EntryLockState;
  host: Pick<WidgetHostPorts, "entries" | "contentTypes" | "entryRefs" | "slugify">;
  entryRepo: EntryRepoPort & EntryListPort;
  contentTypeRepo: ContentTypeRepoPort;
  entryRefsRepo: EntryRefsRepoPort;
  clock: ClockPort;
  ids: { newId: () => string };
  authorize: WidgetsAuthorizeFn;
  outbox: OutboxPort;
}

function slugify(title: string, host: Pick<WidgetHostPorts, "slugify">): string {
  const base = host.slugify(title);
  return base.length > 0 ? base : "widget";
}

async function extractAndStoreInstanceRefs(deps: WidgetWriteServiceDeps, workspaceId: string, entry: EntryRecord): Promise<void> {
  const payload = parseWidgetInstancePayload({ fieldsJson: entry.fieldsJson });
  const refs = deps.host.entryRefs.extract({
    workspaceId,
    sourceEntryId: entry.id,
    sourceEntryType: WIDGET_CONTENT_TYPE,
    bodyJson: entry.bodyJson,
    fieldsExt: { [WIDGET_FIELD_NAMESPACE]: { widgetType: payload.widgetType, config: payload.config } },
  });
  await deps.entryRefsRepo.replaceForSource({ workspaceId, sourceEntryId: entry.id, refs });
}

/**
 * The one shared shape every `createEntry`/`updateEntry` call in this file needs — mirrors
 * `region-area-service.ts`'s identical `entriesWriteDeps` helper. Bridges `deps.outbox` (the raw,
 * full-`DomainEvent` infra port — see `WidgetWriteServiceDeps.outbox`) through `toEntryOutbox` into
 * the narrower `{enqueue({name,payload})}` shape `createEntry`/`updateEntry` declare locally.
 * Previously each of the four call sites below passed `deps.outbox` straight through unwrapped —
 * compiled fine (`features/entries/write-service.ts`'s own narrow `OutboxPort` accepted it via a
 * structural/bivariance loophole), but threw `NOT NULL constraint failed: outbox_events.id` against
 * the real SQLite outbox in production on every widget create/update/trash/purge, invisible against
 * the in-memory test double (which accepts any shape). One composer means the bridge can't be
 * missed at a fifth call site later — see `ADS-memory/.local-artifacts/agent-reports/
 * 20260803-widget-delete-outbox-bug.md` and `20260803-jini-outbox-contract.md` for the full
 * investigation. `onWritten` is deliberately NOT included — it differs per call site (or is absent
 * entirely, as in `trashWidgetInstance`), so each caller still supplies its own.
 */
function entriesWriteDeps(deps: WidgetWriteServiceDeps, workspaceId: UUID) {
  return {
    entryRepo: deps.entryRepo,
    contentTypeRepo: deps.contentTypeRepo,
    clock: deps.clock,
    ids: deps.ids,
    authorize: PRE_AUTHORIZED,
    outbox: deps.host.entries.toEntryOutbox({ outbox: deps.outbox, clock: deps.clock, idGen: deps.ids, workspaceId }),
  };
}

/**
 * Keep every write's rejection actionable when the tool only describes a generic config bag.
 * The registration owns the expected keys; fieldErrors also stay structured for admin HTTP.
 * @complexity O(f + k) time and space for field errors and declared config keys; no I/O.
 */
function widgetConfigValidationError(
  required: { registration: WidgetTypeRegistration; fieldErrors: WidgetConfigFieldError[] },
  _optional: Record<string, never> = {},
): WidgetConfigValidationError {
  const { registration, fieldErrors } = required;
  const requiredKeys = new Set(registration.configSchema.required as readonly string[] | undefined);
  // Every registration's configSchema declares `properties` (pinned by `registry.unit.test.ts`), so
  // the former `?? {}` fallback was unreachable — the registry is a static table, not caller input.
  const configKeys = new Set([...requiredKeys, ...Object.keys(registration.configSchema.properties as JsonObject)]);
  const expectedKeys = [...configKeys].map((key) => requiredKeys.has(key) ? `${key} (required)` : key).join(", ");
  return new WidgetConfigValidationError({
    message: `config for widget type '${registration.typeKey}' failed schema validation: ${fieldErrors.map((e) => `${e.field}: ${e.reason}`).join("; ")}. Expected config keys: ${expectedKeys}`,
    fieldErrors,
  });
}

export interface CreateWidgetInstanceInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID };
  readonly widgetType: WidgetTypeKey;
  readonly title: string;
  readonly config: Record<string, unknown>;
  readonly slug?: string;
}

export interface CreateWidgetInstanceRequired {
  deps: WidgetWriteServiceDeps;
  input: CreateWidgetInstanceInput;
}

/** REQ-01/02/03: authorize → validate config against the type's registered schema → create via the chokepoint. */
export async function createWidgetInstance(required: CreateWidgetInstanceRequired, _optional: Record<string, never> = {}): Promise<{ instance: WidgetInstanceEntry }> {
  const { deps, input } = required;

  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.create",
  });

  // `input.widgetType` is typed `WidgetTypeKey` but only ASSERTED to be one — HTTP routes
  // (`server/routes/admin/widgets/create.ts`/`agent-tools.ts`) cast an unvalidated request-body
  // string to it. `findWidgetTypeRegistration` is the correct accessor here: `undefined` is
  // genuinely reachable, and this check is what catches an unregistered type at this boundary.
  const registration = findWidgetTypeRegistration({ raw: input.widgetType });
  if (!registration) {
    throw new WidgetTypeUnregisteredError({ message: `widget type '${input.widgetType}' is not registered`, widgetType: input.widgetType });
  }

  const validation = validateWidgetConfig({ schema: registration.configSchema, config: input.config });
  if (!validation.valid) {
    throw widgetConfigValidationError({ registration, fieldErrors: validation.fieldErrors });
  }

  await ensureWidgetContentTypesRegistered({ deps, workspaceId: input.workspaceId });

  const slug = input.slug ?? `${slugify(input.title, deps.host)}-${deps.ids.newId().slice(0, 8)}`;

  const created = await deps.host.entries.createEntry({
    deps: {
      ...entriesWriteDeps(deps, input.workspaceId),
      onWritten: (entry) => extractAndStoreInstanceRefs(deps, input.workspaceId, entry),
    },
    input: {
      actorId: input.actor.principalId,
      workspaceId: input.workspaceId,
      type: WIDGET_CONTENT_TYPE,
      slug,
      title: input.title,
      fieldsJson: buildWidgetInstanceFieldsJson({ payload: { widgetType: input.widgetType, config: input.config, status: "active" } }),
    },
  });
  if (!created.ok) throw created.error;

  return { instance: toWidgetInstanceEntry({ entry: created.value.entry }) };
}

export interface UpdateWidgetInstanceInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID };
  readonly widgetInstanceId: UUID;
  readonly baseVersion: number;
  readonly config: Record<string, unknown>;
  /** Optional (SPEC-043 ui.spec §4.3): omitted keeps the current title, forwarded to
   *  `updateEntry`'s own `title` field (`input.title ?? current.title`) the same way create's
   *  `title` reaches the entry row — never folded into `fieldsJson`, which only carries
   *  widget-domain payload (`widgetType`/`config`/`status`). */
  readonly title?: string;
}

export interface UpdateWidgetInstanceRequired {
  deps: WidgetWriteServiceDeps;
  input: UpdateWidgetInstanceInput;
}

/** REQ-05/06: update via the chokepoint, rejecting a stale `baseVersion` with a typed conflict. */
export async function updateWidgetInstance(required: UpdateWidgetInstanceRequired, _optional: Record<string, never> = {}): Promise<{ instance: WidgetInstanceEntry }> {
  const { deps, input } = required;

  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.update",
  });

  return withEntryLock({ key: `${input.workspaceId}::${input.widgetInstanceId}`, fn: async () => {
    const current = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.widgetInstanceId });
    if (!current || current.type !== WIDGET_CONTENT_TYPE) {
      throw new WidgetInstanceNotFoundError({ message: `widget instance '${input.widgetInstanceId}' was not found` });
    }

    const currentPayload = parseWidgetInstancePayload({ fieldsJson: current.fieldsJson });
    // `currentPayload.widgetType` is typed `WidgetTypeKey` but only ASSERTED to be one —
    // `parseWidgetInstancePayload` casts decoded, stored JSON (`entry-payload.ts`), so
    // `findWidgetTypeRegistration` is the correct, honestly-partial accessor here too.
    const registration = findWidgetTypeRegistration({ raw: currentPayload.widgetType });
    if (!registration) {
      throw new WidgetTypeUnregisteredError({ message: `widget type '${currentPayload.widgetType}' is not registered`, widgetType: currentPayload.widgetType });
    }

    const validation = validateWidgetConfig({ schema: registration.configSchema, config: input.config });
    if (!validation.valid) {
      throw widgetConfigValidationError({ registration, fieldErrors: validation.fieldErrors });
    }

    const result = await deps.host.entries.updateEntry({
      deps: {
        ...entriesWriteDeps(deps, input.workspaceId),
        onWritten: (entry) => extractAndStoreInstanceRefs(deps, input.workspaceId, entry),
      },
      input: {
        actorId: input.actor.principalId,
        workspaceId: input.workspaceId,
        id: input.widgetInstanceId,
        title: input.title,
        fieldsJson: buildWidgetInstanceFieldsJson({ payload: { widgetType: currentPayload.widgetType, config: input.config, status: currentPayload.status } }),
        expectedVersion: input.baseVersion,
      },
    });

    if (!result.ok) {
      if (deps.host.entries.isVersionConflict(result.error)) {
        const latest = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.widgetInstanceId });
        throw new WidgetVersionConflictError({ message: result.error.message, currentVersion: latest?.version ?? current.version });
      }
      throw result.error;
    }

    return { instance: toWidgetInstanceEntry({ entry: result.value.entry }) };
  } }, deps.entryLocks ? { locks: deps.entryLocks } : {});
}

export interface ImportWidgetInstanceInput {
  readonly workspaceId: UUID;
  readonly actor: { readonly principalId: UUID };
  /** The source's own id, kept so a publish round trip lands on the same row (and placements that
   *  name it still resolve). */
  readonly id: UUID;
  readonly slug: string;
  readonly title: string;
  readonly widgetType: WidgetTypeKey;
  readonly config: Record<string, unknown>;
  /** `undefined` = the row must not exist yet; a number = it must exist at exactly this version. */
  readonly expectedVersion: number | undefined;
}

export interface ImportWidgetInstanceRequired {
  deps: WidgetWriteServiceDeps;
  input: ImportWidgetInstanceInput;
}

/**
 * Publish-content's widget write: create-or-update at a caller-given id, with the same permission,
 * type-registration and config checks as {@link createWidgetInstance}/{@link updateWidgetInstance},
 * through Jini's `importEntry` (the id-keeping chokepoint). Always writes an `active` instance.
 */
export async function importWidgetInstance(required: ImportWidgetInstanceRequired, _optional: Record<string, never> = {}): Promise<{ instance: WidgetInstanceEntry }> {
  const { deps, input } = required;

  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: input.expectedVersion === undefined ? "widgets.create" : "widgets.update",
  });

  const registration = findWidgetTypeRegistration({ raw: input.widgetType });
  if (!registration) {
    throw new WidgetTypeUnregisteredError({ message: `widget type '${input.widgetType}' is not registered`, widgetType: input.widgetType });
  }
  const validation = validateWidgetConfig({ schema: registration.configSchema, config: input.config });
  if (!validation.valid) {
    throw widgetConfigValidationError({ registration, fieldErrors: validation.fieldErrors });
  }

  await ensureWidgetContentTypesRegistered({ deps, workspaceId: input.workspaceId });

  return withEntryLock({ key: `${input.workspaceId}::${input.id}`, fn: async () => {
    const current = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.id });
    const result = await deps.host.entries.importEntry({
      deps: {
        ...entriesWriteDeps(deps, input.workspaceId),
        onWritten: (entry) => extractAndStoreInstanceRefs(deps, input.workspaceId, entry),
      },
      input: {
        actorId: input.actor.principalId,
        workspaceId: input.workspaceId,
        id: input.id,
        type: WIDGET_CONTENT_TYPE,
        slug: input.slug,
        title: input.title,
        status: current?.status ?? "draft",
        fieldsJson: buildWidgetInstanceFieldsJson({ payload: { widgetType: input.widgetType, config: input.config, status: "active" } }),
        publishedAt: current?.publishedAt ?? null,
        expectedVersion: input.expectedVersion,
      },
    });
    if (!result.ok) throw result.error;
    return { instance: toWidgetInstanceEntry({ entry: result.value.entry }) };
  } }, deps.entryLocks ? { locks: deps.entryLocks } : {});
}

export interface TrashWidgetInstanceInput {
  readonly workspaceId: UUID;
  readonly actor: {
    readonly principalId: UUID;
    /** The assistant's AI marker on the Trash row's `actor.pluginId` (2026-09-21, trash T4c) —
     *  unset by every non-assistant caller, so a human's own trash from the admin screen stays
     *  human-only. See {@link RemoveWidgetFn}'s `actor.pluginId`. */
    readonly pluginId?: UUID | null;
  };
  readonly widgetInstanceId: UUID;
}

/** {@link WidgetWriteServiceDeps} plus the Trash, injected: `remove` (bound to `"widget"` at the
 *  composition root). */
export interface WidgetTrashDeps extends WidgetWriteServiceDeps {
  remove: RemoveWidgetFn;
}

export interface TrashWidgetInstanceRequired {
  deps: Pick<WidgetTrashDeps, "entryRepo" | "clock" | "authorize" | "remove" | "entryLocks">;
  input: TrashWidgetInstanceInput;
}

/**
 * Deleting a widget = moving it to the Trash (the injected `remove`). UNCONDITIONAL, per ADR-047 §7
 * and feature.spec.md EC-07: a widget still placed somewhere can be trashed, and every placement
 * then renders the REQ-28 placeholder until it is restored. Only a purge from the Trash removes it
 * for good.
 *
 * Never parses the payload, so a widget whose `fields_json` is corrupt can still be deleted, and
 * never touches its outgoing `entry_refs` (a restore needs them).
 *
 * @throws WidgetInstanceNotFoundError when the widget is missing, already trashed, or not a widget.
 * @throws WidgetVersionConflictError when the row changed between the read and the move.
 * @complexity O(1): one read, one `remove` call (and one more read only on a version conflict).
 */
export async function trashWidgetInstance(
  required: TrashWidgetInstanceRequired, _optional: Record<string, never> = {}
): Promise<{ widgetInstanceId: UUID; version: number | null }> {
  const { deps, input } = required;

  await requireWidgetPermission({
    authorize: deps.authorize,
    actor: input.actor,
    workspaceId: input.workspaceId,
    permission: "widgets.delete",
  });

  return withEntryLock({ key: `${input.workspaceId}::${input.widgetInstanceId}`, fn: async () => {
    const notFound = () => new WidgetInstanceNotFoundError({ message: `widget instance '${input.widgetInstanceId}' was not found` });
    const current = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.widgetInstanceId });
    if (!current || current.type !== WIDGET_CONTENT_TYPE) throw notFound();

    const removed = await deps.remove({
      workspaceId: input.workspaceId,
      id: current.id,
      display: { title: current.title, subtitle: current.slug },
      at: clockNowIso({ clock: deps.clock }),
      expectedVersion: current.version,
      actor: { principalId: input.actor.principalId, pluginId: input.actor.pluginId ?? null },
    });
    if (removed.ok) return { widgetInstanceId: current.id, version: removed.version };
    if (removed.reason === "not-found") throw notFound();

    const fresh = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.widgetInstanceId });
    if (!fresh) throw notFound();
    throw new WidgetVersionConflictError({ message: `widget instance '${input.widgetInstanceId}' changed while it was being deleted — reload and try again`, currentVersion: fresh.version }
    );
  } }, deps.entryLocks ? { locks: deps.entryLocks } : {});
}

/** The payload statuses the old delete ladder left behind: `trash` (step 1) and `purged` (its
 *  "delete permanently", which never removed the row). */
const LEGACY_DELETED_STATUSES: ReadonlySet<string> = new Set(["trash", "purged"]);

/** Who the Trash records as having moved an adopted widget there. */
const ADOPTION_ACTOR = { principalId: "system" } as const;

/** The status a restore brings an adopted widget back to — recorded as its Trash row's prior marker. */
const ADOPTED_WIDGET_PRIOR_STATUS = "active" satisfies WidgetInstanceStatus;

export interface AdoptLegacyTrashedWidgetsRequired {
  deps: Pick<WidgetTrashDeps, "entryRepo" | "clock" | "remove">;
  input: { readonly workspaceId: UUID };
}

/**
 * One-time, idempotent boot step (owner decision 6): every widget the old delete ladder left with
 * payload status `trash` or `purged` goes into the Trash, so it gets the same 60 days as anything
 * else deleted today.
 *
 * The payload is NOT touched: while the widget is in the Trash it keeps saying `trash`/`purged`,
 * because an older site build that knows nothing about `entries.deleted_at` may still read it and
 * would otherwise show the widget as live. The Trash row records `"active"` as its prior marker;
 * restoring it runs {@link restoreWidgetPriorStatus}, which applies that status to the payload.
 *
 * A second run finds nothing: an adopted widget is in the Trash, so the entries reads no longer
 * return it. A widget whose payload does not parse is skipped; nothing about it says it was deleted.
 *
 * @returns the id and title of each widget it moved to the Trash (the boot step logs them).
 * @throws when the Trash refuses a widget (it changed under the adoption) — boot logs it and the
 *         next boot retries the rest.
 * @complexity O(w) over the workspace's live widgets: one list, then one `remove` per adopted widget.
 */
export async function adoptLegacyTrashedWidgets(
  required: AdoptLegacyTrashedWidgetsRequired, _optional: Record<string, never> = {}
): Promise<{ adopted: Array<{ id: UUID; title: string }> }> {
  const { deps, input } = required;
  const widgets = await deps.entryRepo.listByWorkspace({ workspaceId: input.workspaceId }, { type: WIDGET_CONTENT_TYPE });
  const adopted: Array<{ id: UUID; title: string }> = [];

  for (const widget of widgets) {
    let status: string;
    try {
      status = parseWidgetInstancePayload({ fieldsJson: widget.fieldsJson }).status;
    } catch {
      continue;
    }
    if (!LEGACY_DELETED_STATUSES.has(status)) continue;

    const removed = await deps.remove({
      workspaceId: input.workspaceId,
      id: widget.id,
      display: { title: widget.title, subtitle: widget.slug },
      at: clockNowIso({ clock: deps.clock }),
      expectedVersion: widget.version,
      actor: ADOPTION_ACTOR,
      priorMarker: ADOPTED_WIDGET_PRIOR_STATUS,
    });
    if (!removed.ok) throw new Error(`widget '${widget.id}' could not be moved to the Trash: ${removed.reason}`);
    adopted.push({ id: widget.id, title: widget.title });
  }

  return { adopted };
}

export interface RestoreWidgetPriorStatusRequired {
  deps: WidgetWriteServiceDeps;
  input: { readonly workspaceId: UUID; readonly widgetInstanceId: UUID; readonly priorStatus: string };
}

/**
 * Runs as a widget comes back from the Trash with a recorded prior status — only an adopted legacy
 * widget has one (see {@link adoptLegacyTrashedWidgets}). Sets the payload's `trash`/`purged` status
 * back to `active` and re-derives the widget's outgoing refs (the old purge had retracted them), in
 * the restore's own transaction.
 *
 * Leaves the widget alone when there is nothing to fix: a prior status other than `active`, a
 * payload that does not parse (a restore must still bring a corrupt widget back byte-identical), or
 * a payload already live.
 *
 * @throws WidgetInstanceNotFoundError when the widget does not read back (the restore just cleared
 *         its marker, so this means the row is not a widget) — the restore rolls back with it.
 * @complexity O(1): one read and at most one `updateEntry`.
 */
export async function restoreWidgetPriorStatus(required: RestoreWidgetPriorStatusRequired, _optional: Record<string, never> = {}): Promise<void> {
  const { deps, input } = required;
  if (input.priorStatus !== ADOPTED_WIDGET_PRIOR_STATUS) return;

  const widget = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.widgetInstanceId });
  if (!widget || widget.type !== WIDGET_CONTENT_TYPE) {
    throw new WidgetInstanceNotFoundError({ message: `widget instance '${input.widgetInstanceId}' was not found` });
  }
  let payload: ReturnType<typeof parseWidgetInstancePayload>;
  try {
    payload = parseWidgetInstancePayload({ fieldsJson: widget.fieldsJson });
  } catch {
    return;
  }
  if (!LEGACY_DELETED_STATUSES.has(payload.status)) return;

  const updated = await deps.host.entries.updateEntry({
    deps: {
      ...entriesWriteDeps(deps, input.workspaceId),
      onWritten: (entry) => extractAndStoreInstanceRefs(deps, input.workspaceId, entry),
    },
    input: {
      actorId: ADOPTION_ACTOR.principalId,
      workspaceId: input.workspaceId,
      id: widget.id,
      fieldsJson: buildWidgetInstanceFieldsJson({ payload: { ...payload, status: ADOPTED_WIDGET_PRIOR_STATUS } }),
      expectedVersion: widget.version,
    },
  });
  if (!updated.ok) throw updated.error;
}

/**
 * @file THE single writer of payment intent state, refunds, disputes and the payment's derived
 * caches (commerce design item 2). Synchronous provider responses, webhooks and `retrieve`
 * snapshots all arrive here as evidence; nothing else in the kernel writes those columns. Today's
 * `lipay-plugin.ts` had two writers of the refunded total (`:825` and `:456-459`) — bug B2.
 *
 * Every function runs INSIDE the caller's ledger transaction and starts with `lockPayment`, so two
 * concurrent applies (a webhook racing the synchronous response, two refunds at once) serialize
 * on the payment. Each apply appends the observation to the evidence log (append-only), merges it
 * through the pure planner (`plan-evidence.ts`), writes what changed, re-derives the caches from
 * the rows and enqueues outbox events. Evidence the planner refuses is quarantined with the
 * observation kept, never dropped and never capped.
 *
 * Known limit (L3 review, left to L5): refs are checked within ONE payment. A provider ref already
 * held by another payment makes the insert throw `LedgerConstraintError`, rolling back the whole
 * apply. On Postgres the transaction is poisoned, so the quarantine cannot be written inside it:
 * the inbox worker must catch the error, roll back, and dead-letter/quarantine in a new transaction.
 */
import type { PaymentsAlertPort } from "../contract/alerts.js";
import type { DisputeEvidence, PaymentEvidence, RefundEvidence } from "../contract/evidence.js";
import type { PaymentMode } from "../contract/scope.js";
import type { LedgerTx } from "../ledger/repo.js";
import type { EvidenceSource, EvidenceSubject, LedgerOutboxTopic, PaymentRecord, RefundRecord } from "../ledger/rows.js";
import { disputedMinor, refundTotals, refundableMinor } from "../state/status.js";
import {
  computeTotals, planDisputeEvidence, planIntentEvidence, planRefundEvidence,
  type EvidenceQuarantineReason, type PaymentState, type Quarantined,
} from "./plan-evidence.js";

export interface WriterDeps {
  readonly now: () => number;
  readonly newId: () => string;
  /** Raised (never capping anything) when withdrawn money exceeds captured. Absent = no alerts. */
  readonly alerts?: PaymentsAlertPort;
}

export interface WriterInput {
  readonly tx: LedgerTx;
  readonly deps: WriterDeps;
  /** The payment's workspace + mode: `lockPayment` is fenced by them, so a foreign-scope id reads as missing. */
  readonly workspaceId: string;
  readonly mode: PaymentMode;
  readonly paymentId: string;
  readonly source: EvidenceSource;
}

export type ApplyResult =
  | {
      readonly kind: "applied"; readonly quarantined: readonly EvidenceQuarantineReason[]; readonly outbox: readonly LedgerOutboxTopic[];
      /** Refund observations that could not be matched yet; the caller parks and retries the whole observation. */
      readonly deferred: number;
    }
  | { readonly kind: "deferred" }
  | { readonly kind: "quarantined"; readonly reason: EvidenceQuarantineReason }
  | { readonly kind: "missing" };

interface Ctx extends WriterInput {
  /** Reassigned once the intent patch is known, so refunds are checked against the new captured amount. */
  payment: PaymentRecord;
  readonly inboxId: string | null;
  readonly outbox: LedgerOutboxTopic[];
  readonly quarantined: EvidenceQuarantineReason[];
  deferred: number;
}

/**
 * The evidence amount column takes only a safe integer. A malformed amount (fractional, unsafe) is
 * validated out BEFORE the insert: written as-is it would throw in the integer encoder and roll back
 * the whole apply, losing the observation the planner then quarantines as `bad-amount` (R1-F3). The
 * observation, malformed amount included, is kept whole in the quarantine row's JSON.
 */
function storableMinor({ amount }: { amount: { minorUnits: number } | undefined }): number | null {
  return amount !== undefined && Number.isSafeInteger(amount.minorUnits) ? amount.minorUnits : null;
}

async function appendEvidence(ctx: Ctx, entry: { subject: EvidenceSubject; subjectRef: string; status: string; amount?: { minorUnits: number; currency: string } }): Promise<void> {
  await ctx.tx.appendEvidence({
    evidence: {
      id: ctx.deps.newId(), paymentId: ctx.payment.id, workspaceId: ctx.payment.workspaceId, siteId: ctx.payment.siteId,
      providerId: ctx.payment.providerId, providerAccountId: ctx.payment.providerAccountId, mode: ctx.payment.mode, source: ctx.source, subject: entry.subject, subjectRef: entry.subjectRef, observedStatus: entry.status,
      currency: entry.amount?.currency ?? null, amountMinor: storableMinor({ amount: entry.amount }), inboxId: ctx.inboxId, recordedAt: ctx.deps.now(),
    },
  });
}

async function quarantine(ctx: Ctx, subject: EvidenceSubject, plan: Quarantined, evidence: unknown): Promise<void> {
  ctx.quarantined.push(plan.reason);
  await ctx.tx.insertQuarantine({
    entry: {
      id: ctx.deps.newId(), workspaceId: ctx.payment.workspaceId, mode: ctx.payment.mode, paymentId: ctx.payment.id,
      subject, reason: plan.reason, evidenceJson: JSON.stringify(evidence), createdAt: ctx.deps.now(),
    },
  });
}

async function enqueue(ctx: Ctx, topics: readonly LedgerOutboxTopic[], payload: Record<string, unknown>): Promise<void> {
  for (const topic of topics) {
    ctx.outbox.push(topic);
    // Ids and amounts only: no personal data leaves through the outbox (gap check item 4).
    await ctx.tx.enqueueOutbox({
      message: {
        id: ctx.deps.newId(), workspaceId: ctx.payment.workspaceId, mode: ctx.payment.mode, topic, aggregateId: ctx.payment.id,
        payloadJson: JSON.stringify({ paymentId: ctx.payment.id, ...payload }), createdAt: ctx.deps.now(),
      },
    });
  }
}

function stateOf(payment: PaymentRecord): PaymentState {
  return {
    id: payment.id, currency: payment.currency, amountMinor: payment.amountMinor, capturedMinor: payment.capturedMinor,
    intentStatus: payment.intentStatus, providerRef: payment.providerRef,
  };
}

function newRefundRecord(ctx: Ctx, row: { id: string; providerRefundRef: string | null; amountMinor: number; status: RefundRecord["status"] }): RefundRecord {
  const p = ctx.payment;
  return {
    ...row, paymentId: p.id, workspaceId: p.workspaceId, siteId: p.siteId, providerId: p.providerId, providerAccountId: p.providerAccountId,
    mode: p.mode, idempotencyKey: null, currency: p.currency, reason: null, createdAt: ctx.deps.now(), updatedAt: ctx.deps.now(),
  };
}

async function applyOneRefund(ctx: Ctx, evidence: RefundEvidence): Promise<void> {
  await appendEvidence(ctx, { subject: "refund", subjectRef: evidence.providerRefundRef, status: evidence.status, amount: evidence.amount });
  const refunds = await ctx.tx.listRefunds({ paymentId: ctx.payment.id });
  const plan = planRefundEvidence({ payment: stateOf(ctx.payment), refunds, evidence, newId: ctx.deps.newId() });
  if (plan.kind === "quarantined") return quarantine(ctx, "refund", plan, evidence);
  if (plan.kind === "deferred") {
    ctx.deferred += 1;
    return;
  }
  if (plan.write === "insert") await ctx.tx.insertRefund({ refund: newRefundRecord(ctx, plan.row) });
  if (plan.write === "update") {
    await ctx.tx.updateRefund({ id: plan.row.id, patch: { status: plan.row.status, providerRefundRef: plan.row.providerRefundRef, updatedAt: ctx.deps.now() } });
  }
  await enqueue(ctx, plan.outbox, { refundId: plan.row.id, amountMinor: plan.row.amountMinor, currency: ctx.payment.currency });
}

async function applyOneDispute(ctx: Ctx, evidence: DisputeEvidence): Promise<void> {
  await appendEvidence(ctx, { subject: "dispute", subjectRef: evidence.providerDisputeRef, status: evidence.status, amount: evidence.amount });
  const disputes = await ctx.tx.listDisputes({ paymentId: ctx.payment.id });
  const plan = planDisputeEvidence({ payment: stateOf(ctx.payment), disputes, evidence, newId: ctx.deps.newId() });
  if (plan.kind === "quarantined") return quarantine(ctx, "dispute", plan, evidence);
  if (plan.amountChanged) {
    // Owner 2026-10-21: the close is applied with the stored amount; only the difference waits for a person.
    const { storedMinor, observedMinor } = plan.amountChanged;
    await quarantine(ctx, "dispute", { kind: "quarantined", reason: "dispute-amount-changed" }, {
      evidence, storedMinor, observedMinor, differenceMinor: observedMinor - storedMinor,
    });
  }
  const p = ctx.payment;
  if (plan.write === "insert") {
    await ctx.tx.insertDispute({
      dispute: {
        ...plan.row, paymentId: p.id, workspaceId: p.workspaceId, siteId: p.siteId, providerId: p.providerId, providerAccountId: p.providerAccountId, mode: p.mode,
        currency: p.currency, dueBy: plan.row.dueBy ?? null, createdAt: ctx.deps.now(), updatedAt: ctx.deps.now(),
      },
    });
  }
  if (plan.write === "update") {
    await ctx.tx.updateDispute({ id: plan.row.id, patch: { status: plan.row.status, dueBy: plan.row.dueBy ?? null, updatedAt: ctx.deps.now() } });
  }
  await enqueue(ctx, plan.outbox, { disputeId: plan.row.id, status: plan.row.status });
}

/** Re-derives the caches from the rows and writes them with whatever intent patch applies. */
async function writeCaches(ctx: Ctx, intent: Partial<PaymentRecord>): Promise<void> {
  const base = { ...stateOf(ctx.payment), ...intent } as PaymentState;
  const refunds = await ctx.tx.listRefunds({ paymentId: ctx.payment.id });
  const disputes = await ctx.tx.listDisputes({ paymentId: ctx.payment.id });
  const totals = computeTotals({ payment: base, refunds, disputes });
  const written = await ctx.tx.updatePayment({
    id: ctx.payment.id, expectedVersion: ctx.payment.version,
    patch: { ...intent, ...totals, updatedAt: ctx.deps.now() },
  });
  // The payment lock is held, so a lost version race means a writer bypassed this module.
  if (!written) throw new Error(`payments ledger: payment ${ctx.payment.id} changed under its lock`);
  await alertOverWithdrawn(ctx, { capturedMinor: base.capturedMinor, withdrawnMinor: totals.refundedMinor + totals.disputedMinor });
}

/**
 * Owner 2026-10-21: succeeded refunds + disputed money above captured is ALERTED, never capped or
 * refused (it is real money that left). Raised once, when an apply first crosses the line, so
 * webhook redeliveries do not repeat it. A failing alert port never rolls back the money facts.
 */
async function alertOverWithdrawn(ctx: Ctx, now: { capturedMinor: number; withdrawnMinor: number }): Promise<void> {
  const before = ctx.payment.refundedMinor + ctx.payment.disputedMinor > ctx.payment.capturedMinor;
  if (before || now.withdrawnMinor <= now.capturedMinor || !ctx.deps.alerts) return;
  const detail = `withdrawn ${now.withdrawnMinor} > captured ${now.capturedMinor} ${ctx.payment.currency} (minor units)`;
  await ctx.deps.alerts
    .raise({ alert: { kind: "over-withdrawn", workspaceId: ctx.payment.workspaceId, mode: ctx.payment.mode, paymentId: ctx.payment.id, detail } })
    .catch(() => undefined);
}

async function open(input: WriterInput, inboxId: string | null): Promise<Ctx | null> {
  const payment = await input.tx.lockPayment({ workspaceId: input.workspaceId, mode: input.mode, id: input.paymentId });
  return payment ? { ...input, payment, inboxId, outbox: [], quarantined: [], deferred: 0 } : null;
}

function settlementPatch(evidence: PaymentEvidence): Partial<PaymentRecord> {
  const s = evidence.settlement;
  return {
    ...(s?.fee ? { feeCurrency: s.fee.currency, feeMinor: s.fee.minorUnits } : {}),
    ...(s?.net ? { netCurrency: s.net.currency, netMinor: s.net.minorUnits } : {}),
    ...(s?.settlement ? { settlementCurrency: s.settlement.currency, settlementMinor: s.settlement.minorUnits } : {}),
  };
}

/** Intent statuses where the shopper has nothing left to do: any stored action is over. */
const ACTION_OVER: ReadonlySet<string> = new Set(["authorized", "succeeded", "failed", "canceled"]);
const NO_ACTION = JSON.stringify({ kind: "none" });

/**
 * The next-action column follows the MERGED intent status, not the observation (R1-F5): once the
 * intent is past the shopper's step it is cleared, even when the success evidence omits `next`; and
 * an observation whose status lost the merge (stale) cannot restore or replace the action.
 */
function nextActionPatch({ evidence, intentStatus }: { evidence: PaymentEvidence; intentStatus: string }): Partial<PaymentRecord> {
  if (ACTION_OVER.has(intentStatus)) return { nextActionJson: NO_ACTION };
  return evidence.next && evidence.status === intentStatus ? { nextActionJson: JSON.stringify(evidence.next) } : {};
}

function failuresFirst(refunds: readonly RefundEvidence[]): RefundEvidence[] {
  return [...refunds.filter((r) => r.status === "failed"), ...refunds.filter((r) => r.status !== "failed")];
}

/**
 * Apply a full payment observation: the intent first (a quarantined intent stops the whole
 * observation — its refunds cannot be trusted to belong to this payment), then each refund and
 * dispute, then the derived caches.
 */
export async function applyPaymentEvidence(
  required: WriterInput & { evidence: PaymentEvidence },
  optional: { inboxId?: string } = {}
): Promise<ApplyResult> {
  const ctx = await open(required, optional.inboxId ?? null);
  if (!ctx) return { kind: "missing" };
  const { evidence } = required;
  await appendEvidence(ctx, { subject: "payment", subjectRef: evidence.providerRef, status: evidence.status, ...(evidence.amount ? { amount: evidence.amount } : {}) });
  const plan = planIntentEvidence({ payment: stateOf(ctx.payment), evidence });
  if (plan.kind === "quarantined") {
    await quarantine(ctx, "payment", plan, evidence);
    return { kind: "quarantined", reason: plan.reason };
  }
  const intent: Partial<PaymentRecord> = {
    intentStatus: plan.payment.intentStatus, providerRef: plan.payment.providerRef, capturedMinor: plan.payment.capturedMinor,
    ...nextActionPatch({ evidence, intentStatus: plan.payment.intentStatus }),
    ...settlementPatch(evidence),
  };
  ctx.payment = { ...ctx.payment, ...intent } as PaymentRecord;
  // The intent's topics first: consumers must see payment.succeeded before any refund of it.
  await enqueue(ctx, plan.outbox, { amountMinor: ctx.payment.capturedMinor, currency: ctx.payment.currency });
  // Failures first: a snapshot listing a later refund before an earlier one's failure must not
  // trip the over-refund cap on money the failure already returned (L3 review).
  for (const refund of failuresFirst(evidence.refunds)) await applyOneRefund(ctx, refund);
  for (const dispute of evidence.disputes) await applyOneDispute(ctx, dispute);
  await writeCaches(ctx, intent);
  return { kind: "applied", quarantined: ctx.quarantined, outbox: ctx.outbox, deferred: ctx.deferred };
}

/**
 * Apply one refund observation (a synchronous refund response, or a refund-only webhook).
 * `refundId` = the reservation this response answers: a synchronous response belongs to the row
 * that was dispatched even when the provider does not echo our correlation id.
 */
export async function applyRefundEvidence(
  required: WriterInput & { evidence: RefundEvidence },
  optional: { inboxId?: string; refundId?: string } = {}
): Promise<ApplyResult> {
  const ctx = await open(required, optional.inboxId ?? null);
  if (!ctx) return { kind: "missing" };
  const correlationId = required.evidence.correlationId ?? optional.refundId;
  await applyOneRefund(ctx, { ...required.evidence, ...(correlationId === undefined ? {} : { correlationId }) });
  await writeCaches(ctx, {});
  const [reason] = ctx.quarantined;
  if (reason) return { kind: "quarantined", reason };
  return ctx.deferred > 0 ? { kind: "deferred" } : { kind: "applied", quarantined: [], outbox: ctx.outbox, deferred: 0 };
}

export type ReserveResult =
  | { readonly kind: "reserved"; readonly refund: RefundRecord }
  | { readonly kind: "insufficient"; readonly refundableMinor: number }
  | { readonly kind: "invalid-amount" }
  | { readonly kind: "not-refundable"; readonly status: PaymentRecord["status"] }
  | { readonly kind: "missing" };

/**
 * Reserve money for a refund BEFORE dispatching it: under the payment lock, check
 * `captured − succeeded − held` and insert a `reserved` row. The row id is the correlation id
 * sent to the provider. A reserved/unknown/pending refund keeps holding money until evidence
 * settles it, so two concurrent refunds can never both take the last refundable cent.
 */
export async function reserveRefund(
  required: Omit<WriterInput, "source"> & { refundId: string; amountMinor: number; idempotencyKey: string },
  optional: { reason?: string } = {}
): Promise<ReserveResult> {
  const ctx = await open({ ...required, source: "response" }, null);
  if (!ctx) return { kind: "missing" };
  if (ctx.payment.intentStatus !== "succeeded") return { kind: "not-refundable", status: ctx.payment.status };
  const refunds = await ctx.tx.listRefunds({ paymentId: ctx.payment.id });
  // Money withdrawn by an open or lost dispute is not refundable too: refund + chargeback would pay twice.
  const disputes = await ctx.tx.listDisputes({ paymentId: ctx.payment.id });
  const base = ctx.payment.capturedMinor - disputedMinor({ disputes });
  const available = refundableMinor({ capturedMinor: base, totals: refundTotals({ refunds }) });
  if (!Number.isSafeInteger(required.amountMinor) || required.amountMinor <= 0) return { kind: "invalid-amount" };
  if (required.amountMinor > available) return { kind: "insufficient", refundableMinor: available };
  const refund: RefundRecord = {
    ...newRefundRecord(ctx, { id: required.refundId, providerRefundRef: null, amountMinor: required.amountMinor, status: "reserved" }),
    idempotencyKey: required.idempotencyKey, reason: optional.reason ?? null,
  };
  await ctx.tx.insertRefund({ refund });
  await writeCaches(ctx, {});
  return { kind: "reserved", refund };
}

/**
 * Record what a dispatched refund call answered when it carried no evidence: `rejected` (provably
 * no money moved) → `failed`, releasing the hold; `unknown` (timeout, 5xx) → `unknown`, keeping
 * the hold until a webhook or `retrieve` settles it — never `failed` (bug B4).
 *
 * Only a `reserved` row moves: once a row is `unknown`, `pending` or settled, the provider may
 * already have moved the money, and a later retry being rejected ("already refunded") proves
 * nothing — flipping it to `failed` would release the hold and allow a double refund (L3 review
 * blocker). Those rows settle only through evidence.
 */
export async function recordRefundDispatchOutcome(
  required: Omit<WriterInput, "source"> & { refundId: string; outcome: "rejected" | "unknown" },
  _optional: Record<string, never> = {}
): Promise<ApplyResult> {
  const ctx = await open({ ...required, source: "response" }, null);
  if (!ctx) return { kind: "missing" };
  const refunds = await ctx.tx.listRefunds({ paymentId: ctx.payment.id });
  const row = refunds.find((r) => r.id === required.refundId);
  if (!row) return { kind: "missing" };
  if (row.status === "reserved") {
    const status = required.outcome === "rejected" ? "failed" : "unknown";
    await ctx.tx.updateRefund({ id: row.id, patch: { status, updatedAt: ctx.deps.now() } });
    await writeCaches(ctx, {});
  }
  return { kind: "applied", quarantined: [], outbox: [], deferred: 0 };
}

/**
 * Record what a dispatched `createIntent` answered when it carried no evidence. `rejected`
 * (provably no money moved) → `failed`; `unknown` (timeout, 5xx) leaves the intent `unknown` until
 * a webhook, the reconciler's `retrieve` or an operator settles it — never `failed` (bug B4).
 *
 * Only an `unknown` payment with NO provider ref moves: once any evidence bound a ref or a status
 * (a webhook that beat the response), the provider has spoken and only evidence may change it.
 */
export async function recordIntentDispatchOutcome(
  required: Omit<WriterInput, "source"> & { outcome: "rejected" | "unknown" },
  _optional: Record<string, never> = {}
): Promise<ApplyResult> {
  const ctx = await open({ ...required, source: "response" }, null);
  if (!ctx) return { kind: "missing" };
  const untouched = ctx.payment.intentStatus === "unknown" && ctx.payment.providerRef === null;
  if (required.outcome === "rejected" && untouched) await writeCaches(ctx, { intentStatus: "failed" });
  return { kind: "applied", quarantined: [], outbox: [], deferred: 0 };
}

/** What settling an `unknown` record did. `not-unknown` = it had already moved; nothing was written. */
export type SettleResult =
  | { readonly kind: "settled"; readonly outbox: readonly LedgerOutboxTopic[] }
  | { readonly kind: "not-unknown"; readonly status: string }
  | { readonly kind: "missing" };

/**
 * Settle an `unknown` refund WITHOUT provider evidence of the refund itself: the reconciler's
 * owner rule (the provider's full snapshot lists no such refund → `failed`, source `retrieve`) and
 * an operator's audited resolution (source `operator`). Only from `unknown`: a reserved row has not
 * been dispatched, and a pending/settled one has provider evidence that outranks this. Appends the
 * observation, emits `refund.succeeded` / `refund.failed` (payload `previousStatus: "unknown"`, so a
 * consumer can tell it never counted the money) and re-derives the hold.
 */
export async function settleUnknownRefund(
  required: WriterInput & { refundId: string; status: "succeeded" | "failed" },
  _optional: Record<string, never> = {}
): Promise<SettleResult> {
  const ctx = await open(required, null);
  if (!ctx) return { kind: "missing" };
  const row = (await ctx.tx.listRefunds({ paymentId: ctx.payment.id })).find((r) => r.id === required.refundId);
  if (!row) return { kind: "missing" };
  if (row.status !== "unknown") return { kind: "not-unknown", status: row.status };
  const amount = { minorUnits: row.amountMinor, currency: row.currency };
  await appendEvidence(ctx, { subject: "refund", subjectRef: row.providerRefundRef ?? row.id, status: required.status, amount });
  await ctx.tx.updateRefund({ id: row.id, patch: { status: required.status, updatedAt: ctx.deps.now() } });
  const topic: LedgerOutboxTopic = required.status === "succeeded" ? "refund.succeeded" : "refund.failed";
  await enqueue(ctx, [topic], { refundId: row.id, amountMinor: row.amountMinor, currency: row.currency, previousStatus: "unknown" });
  await writeCaches(ctx, {});
  return { kind: "settled", outbox: ctx.outbox };
}

/**
 * Settle an `unknown` payment intent from an operator's audited resolution (source `operator`):
 * `succeeded` captures the full amount and emits `payment.succeeded`; `failed` moves no money. Only
 * from `unknown`; anything else already has provider evidence.
 */
export async function settleUnknownIntent(
  required: WriterInput & { status: "succeeded" | "failed" },
  _optional: Record<string, never> = {}
): Promise<SettleResult> {
  const ctx = await open(required, null);
  if (!ctx) return { kind: "missing" };
  const p = ctx.payment;
  if (p.intentStatus !== "unknown") return { kind: "not-unknown", status: p.intentStatus };
  const amount = { minorUnits: p.amountMinor, currency: p.currency };
  await appendEvidence(ctx, { subject: "payment", subjectRef: p.providerRef ?? p.id, status: required.status, amount });
  const succeeded = required.status === "succeeded";
  const intent: Partial<PaymentRecord> = succeeded ? { intentStatus: "succeeded", capturedMinor: p.amountMinor } : { intentStatus: "failed" };
  ctx.payment = { ...p, ...intent } as PaymentRecord;
  await enqueue(ctx, succeeded ? ["payment.succeeded"] : [], { amountMinor: p.amountMinor, currency: p.currency });
  await writeCaches(ctx, intent);
  return { kind: "settled", outbox: ctx.outbox };
}

/**
 * @file The pure half of the SINGLE writer: given what the ledger holds for one payment and one
 * piece of evidence, decide what changes. No I/O — `apply-evidence.ts` reads the rows under the
 * payment lock, calls these, and writes the result. Keeping the decision pure is what lets the
 * race tests replay every delivery order cheaply.
 *
 * The rules, each traced to a bug in today's `lipay-plugin.ts`:
 *   - The refunded total is RE-DERIVED from refund rows on every apply, never incremented
 *     (B2: the direct refund and its webhook echo each added the amount).
 *   - A refund is matched by OUR correlation id first, then by the provider's refund id, so a
 *     webhook that beats the synchronous response lands on the reserved row instead of creating a
 *     second one.
 *   - Evidence whose amount disagrees with the row it matched, whose currency differs from the
 *     payment's, or that would refund more than was captured is QUARANTINED, never silently capped
 *     (B1: refund webhooks carried the charge's amount).
 *   - Record statuses merge along the L1 transition tables, so reordered or stale evidence cannot
 *     regress a row.
 */
import type { DisputeEvidence, PaymentEvidence, RefundEvidence } from "../contract/evidence.js";
import {
  derivePaymentStatus,
  disputedMinor,
  mergeDisputeStatus,
  mergeIntentStatus,
  mergeRefundStatus,
  refundTotals,
  type DerivedPaymentStatus,
  type DisputeStatus,
  type IntentStatus,
  type RefundStatus,
} from "../state/status.js";
import type { LedgerOutboxTopic } from "../ledger/rows.js";

/** The ledger's view of one payment, as the planner needs it. */
export interface PaymentState {
  readonly id: string;
  readonly currency: string;
  readonly amountMinor: number;
  readonly capturedMinor: number;
  readonly intentStatus: IntentStatus;
  readonly providerRef: string | null;
}

export interface RefundState {
  readonly id: string;
  readonly providerRefundRef: string | null;
  readonly amountMinor: number;
  readonly status: RefundStatus;
}

export interface DisputeState {
  readonly id: string;
  readonly providerDisputeRef: string;
  readonly amountMinor: number;
  readonly status: DisputeStatus;
  /** The response deadline (epoch ms); `null`/absent = none known yet. */
  readonly dueBy?: number | null;
}

export type EvidenceQuarantineReason =
  | "bad-amount"
  | "currency-mismatch"
  | "amount-mismatch"
  | "ref-conflict"
  | "over-refund"
  /** Evidence that money moved contradicts a terminal record (refund failed → succeeded, intent canceled → succeeded). */
  | "terminal-conflict"
  /**
   * A dispute CLOSED (won/lost) with an amount different from the one it opened with. Owner
   * 2026-10-21: the status is applied and the stored amount kept; only the difference is quarantined.
   */
  | "dispute-amount-changed";

type OutboxTopic = LedgerOutboxTopic;

/**
 * The evidence cannot be matched YET: it carries no correlation id, no row has its provider ref,
 * and one of our refunds is still in flight without a provider ref. Inserting it as a new
 * (unsolicited) row would count the same money twice once our response binds the ref, so the
 * caller parks it and retries after the attempt settles (Opus R3: providers that cannot echo).
 */
export interface Deferred {
  readonly kind: "deferred";
}

export interface Quarantined {
  readonly kind: "quarantined";
  readonly reason: EvidenceQuarantineReason;
}

/** The derived caches the writer stores on the payment row after every apply. */
export interface PaymentTotals {
  readonly refundedMinor: number;
  readonly refundHeldMinor: number;
  readonly disputedMinor: number;
  readonly status: DerivedPaymentStatus;
}

export interface RefundPlan {
  readonly kind: "refund";
  /** `insert` = no row matched (an unsolicited refund made at the provider). */
  readonly write: "insert" | "update" | "none";
  readonly row: RefundState;
  readonly refunds: readonly RefundState[];
  readonly outbox: readonly OutboxTopic[];
}

export interface DisputePlan {
  readonly kind: "dispute";
  readonly write: "insert" | "update" | "none";
  readonly row: DisputeState;
  readonly disputes: readonly DisputeState[];
  readonly outbox: readonly OutboxTopic[];
  /** Set when a closing observation carried a different amount: the writer quarantines the difference. */
  readonly amountChanged?: { readonly storedMinor: number; readonly observedMinor: number };
}

export interface IntentPlan {
  readonly kind: "intent";
  readonly changed: boolean;
  readonly payment: PaymentState;
  readonly outbox: readonly OutboxTopic[];
}

/**
 * `allowZero`: a captured total may be zero (an authorization has captured nothing yet — R1-F4);
 * a charge, refund or dispute amount must be strictly positive.
 */
function amountProblem({ currency, amountMinor, minorUnits, evidenceCurrency }: {
  currency: string; amountMinor?: number; minorUnits: number; evidenceCurrency: string;
}, optional: { allowZero?: boolean } = {}): EvidenceQuarantineReason | null {
  const floor = optional.allowZero === true ? 0 : 1;
  if (!Number.isSafeInteger(minorUnits) || minorUnits < floor) return "bad-amount";
  if (evidenceCurrency !== currency) return "currency-mismatch";
  if (amountMinor !== undefined && amountMinor !== minorUnits) return "amount-mismatch";
  return null;
}

/** Correlation id first (it is OUR id, so it cannot collide), then the provider's refund id. */
export function matchRefund(
  { refunds, evidence }: { refunds: readonly RefundState[]; evidence: RefundEvidence },
  _optional: Record<string, never> = {}
): RefundState | undefined {
  const byCorrelation = evidence.correlationId === undefined ? undefined : refunds.find((r) => r.id === evidence.correlationId);
  return byCorrelation ?? refunds.find((r) => r.providerRefundRef === evidence.providerRefundRef);
}

const isUnboundInFlight = (r: RefundState): boolean => r.providerRefundRef === null && r.status !== "failed" && r.status !== "succeeded";

function refundOutbox(previous: RefundStatus | undefined, next: RefundStatus): OutboxTopic[] {
  if (next === previous) return [];
  if (next === "succeeded") return ["refund.succeeded"];
  // Only a refund that had SUCCEEDED and then failed returns money the consumer already counted.
  return next === "failed" && previous === "succeeded" ? ["refund.failed"] : [];
}

function nextRefundRow({ existing, evidence, newId }: { existing: RefundState | undefined; evidence: RefundEvidence; newId: string }): RefundState {
  if (!existing) {
    return { id: newId, providerRefundRef: evidence.providerRefundRef, amountMinor: evidence.amount.minorUnits, status: evidence.status };
  }
  return {
    ...existing,
    providerRefundRef: evidence.providerRefundRef,
    status: mergeRefundStatus({ current: existing.status, incoming: evidence.status }),
  };
}

function writeKind<T>(existing: T | undefined, row: T): "insert" | "update" | "none" {
  if (!existing) return "insert";
  return JSON.stringify(existing) === JSON.stringify(row) ? "none" : "update";
}

/**
 * Which row this evidence is about. Correlation id or provider ref first. For a provider that
 * does not echo our id:
 *  - while any of our refunds still awaits its synchronous response (`reserved`/`pending`, no
 *    ref), DEFER: the response will bind the ref, then this evidence matches by ref or is a new
 *    refund. Guessing here could let a dashboard refund of the same amount take our row and cancel
 *    our hold (re-review blocker);
 *  - a refund whose outcome was lost (`unknown`, no ref) has no response coming, so a SUCCESS of
 *    exactly that amount binds to it when it is the only such row — otherwise a timeout would wait
 *    forever. A failure never binds by amount (it would release our hold on a guess), and neither
 *    does a PENDING (R1-F1): binding it hands our row the foreign ref, so that refund later failing
 *    would release our hold while our dispatch is still unresolved. Both defer until a success
 *    arrives or the reconciler settles the row. If a success guess picked a foreign refund, totals
 *    stay right: our own refund then arrives by ref as a new row; only the label on the unknown row
 *    is the other refund's.
 */
function resolveRefund({ refunds, evidence }: { refunds: readonly RefundState[]; evidence: RefundEvidence }): { existing: RefundState | undefined } | Deferred {
  const matched = matchRefund({ refunds, evidence });
  if (matched || evidence.correlationId !== undefined) return { existing: matched };
  const unbound = refunds.filter(isUnboundInFlight);
  if (unbound.some((r) => r.status !== "unknown")) return { kind: "deferred" };
  const candidates = unbound.filter((r) => r.amountMinor === evidence.amount.minorUnits);
  if (candidates.length === 0) return { existing: undefined };
  return candidates.length === 1 && evidence.status === "succeeded" ? { existing: candidates[0] } : { kind: "deferred" };
}

function refundProblem({ payment, existing, evidence }: { payment: PaymentState; existing: RefundState | undefined; evidence: RefundEvidence }): EvidenceQuarantineReason | null {
  const bad = amountProblem({
    currency: payment.currency, minorUnits: evidence.amount.minorUnits, evidenceCurrency: evidence.amount.currency,
    ...(existing ? { amountMinor: existing.amountMinor } : {}),
  });
  if (bad) return bad;
  if (!existing) return null;
  if (existing.providerRefundRef !== null && existing.providerRefundRef !== evidence.providerRefundRef) return "ref-conflict";
  // Nothing leaves `failed`, but a success after it means money left after all: surface it, never drop it.
  return existing.status === "failed" && evidence.status === "succeeded" ? "terminal-conflict" : null;
}

/**
 * Plan one refund observation. `newId` names the row only when nothing matches (an unsolicited
 * refund issued at the provider's dashboard is still money that left).
 */
export function planRefundEvidence(
  { payment, refunds, evidence, newId }: {
    payment: PaymentState; refunds: readonly RefundState[]; evidence: RefundEvidence; newId: string;
  },
  _optional: Record<string, never> = {}
): RefundPlan | Quarantined | Deferred {
  const resolved = resolveRefund({ refunds, evidence });
  if ("kind" in resolved) return resolved;
  const { existing } = resolved;
  const problem = refundProblem({ payment, existing, evidence });
  if (problem) return { kind: "quarantined", reason: problem };
  const row = nextRefundRow({ existing, evidence, newId });
  const next = existing ? refunds.map((r) => (r.id === row.id ? row : r)) : [...refunds, row];
  if (refundTotals({ refunds: next }).succeeded > payment.capturedMinor) return { kind: "quarantined", reason: "over-refund" };
  return { kind: "refund", write: writeKind(existing, row), row, refunds: next, outbox: refundOutbox(existing?.status, row.status) };
}

function disputeOutbox(previous: DisputeStatus | undefined, next: DisputeStatus): OutboxTopic[] {
  if (previous === undefined) return next === "open" ? ["dispute.opened"] : ["dispute.opened", "dispute.closed"];
  return previous !== next ? ["dispute.closed"] : [];
}

/**
 * The dispute row after `evidence`. Its deadline is taken from an observation whose status won the
 * merge — also when the status is unchanged, so a later or corrected `dueBy` is persisted (R1-F6) —
 * and never from a stale one; an observation without `dueBy` keeps the stored deadline.
 */
function nextDisputeRow({ existing, evidence, newId }: { existing: DisputeState | undefined; evidence: DisputeEvidence; newId: string }): DisputeState {
  const deadline = evidence.dueBy === undefined ? {} : { dueBy: evidence.dueBy };
  if (!existing) return { id: newId, providerDisputeRef: evidence.providerDisputeRef, amountMinor: evidence.amount.minorUnits, status: evidence.status, ...deadline };
  const status = mergeDisputeStatus({ current: existing.status, incoming: evidence.status });
  return { ...existing, status, ...(evidence.status === status ? deadline : {}) };
}

/** Plan one dispute observation. Disputes are a separate dimension: they never change the intent status. */
export function planDisputeEvidence(
  { payment, disputes, evidence, newId }: {
    payment: PaymentState; disputes: readonly DisputeState[]; evidence: DisputeEvidence; newId: string;
  },
  _optional: Record<string, never> = {}
): DisputePlan | Quarantined {
  const existing = disputes.find((d) => d.providerDisputeRef === evidence.providerDisputeRef);
  const bad = amountProblem({
    currency: payment.currency, minorUnits: evidence.amount.minorUnits, evidenceCurrency: evidence.amount.currency,
    ...(existing ? { amountMinor: existing.amountMinor } : {}),
  });
  const row = nextDisputeRow({ existing, evidence, newId });
  const amountChanged = closingAmountChange({ bad, existing, row, evidence });
  if (bad && !amountChanged) return { kind: "quarantined", reason: bad };
  const next = existing ? disputes.map((d) => (d.id === row.id ? row : d)) : [...disputes, row];
  return {
    kind: "dispute", write: writeKind(existing, row), row, disputes: next, outbox: disputeOutbox(existing?.status, row.status),
    ...(amountChanged ? { amountChanged } : {}),
  };
}

/**
 * Only `amount-mismatch` comes with an `existing` row. A CLOSING observation with a new amount is
 * applied (owner 2026-10-21) and only the difference is flagged; an open or stale one is not.
 */
function closingAmountChange(
  { bad, existing, row, evidence }: { bad: EvidenceQuarantineReason | null; existing: DisputeState | undefined; row: DisputeState; evidence: DisputeEvidence }
): DisputePlan["amountChanged"] {
  if (bad !== "amount-mismatch" || row.status === existing?.status) return undefined;
  return { storedMinor: row.amountMinor, observedMinor: evidence.amount.minorUnits };
}

/**
 * Captured never decreases. Evidence without `captured` leaves it UNCHANGED — except the first
 * move to `succeeded` with nothing captured yet, which means the full amount (auto capture).
 * Defaulting to the full amount on every success would let a later snapshot widen a partial
 * capture and open refund room that was never captured (L3 review).
 */
function nextCaptured({ payment, evidence, intent }: { payment: PaymentState; evidence: PaymentEvidence; intent: IntentStatus }): number {
  if (evidence.captured) return Math.max(payment.capturedMinor, evidence.captured.minorUnits);
  return intent === "succeeded" && payment.capturedMinor === 0 ? payment.amountMinor : payment.capturedMinor;
}

const MONEY_MOVED: ReadonlySet<string> = new Set(["authorized", "succeeded"]);

function intentAmountProblem({ payment, evidence }: { payment: PaymentState; evidence: PaymentEvidence }): EvidenceQuarantineReason | null {
  const checks = [{ reported: evidence.amount, allowZero: false }, { reported: evidence.captured, allowZero: true }];
  for (const { reported, allowZero } of checks) {
    if (reported === undefined) continue;
    const bad = amountProblem({ currency: payment.currency, minorUnits: reported.minorUnits, evidenceCurrency: reported.currency }, { allowZero });
    if (bad) return bad;
  }
  if (evidence.amount !== undefined && evidence.amount.minorUnits !== payment.amountMinor) return "amount-mismatch";
  if (evidence.captured !== undefined && evidence.captured.minorUnits > payment.amountMinor) return "amount-mismatch";
  return null;
}

function intentProblem({ payment, evidence }: { payment: PaymentState; evidence: PaymentEvidence }): EvidenceQuarantineReason | null {
  if (payment.providerRef !== null && payment.providerRef !== evidence.providerRef) return "ref-conflict";
  if (evidence.correlationId !== undefined && evidence.correlationId !== payment.id) return "ref-conflict";
  if (payment.intentStatus === "canceled" && MONEY_MOVED.has(evidence.status)) return "terminal-conflict";
  return intentAmountProblem({ payment, evidence });
}

/** Plan the intent half of a payment observation (status, provider ref, captured amount). */
export function planIntentEvidence(
  { payment, evidence }: { payment: PaymentState; evidence: PaymentEvidence },
  _optional: Record<string, never> = {}
): IntentPlan | Quarantined {
  const problem = intentProblem({ payment, evidence });
  if (problem) return { kind: "quarantined", reason: problem };
  const intentStatus = mergeIntentStatus({ current: payment.intentStatus, incoming: evidence.status });
  const next: PaymentState = {
    ...payment,
    intentStatus,
    providerRef: evidence.providerRef,
    capturedMinor: nextCaptured({ payment, evidence, intent: intentStatus }),
  };
  const changed = JSON.stringify(next) !== JSON.stringify(payment);
  const becameSucceeded = intentStatus === "succeeded" && payment.intentStatus !== "succeeded";
  return { kind: "intent", changed, payment: next, outbox: becameSucceeded ? ["payment.succeeded"] : [] };
}

/** The derived caches for the payment row, from its current rows. */
export function computeTotals(
  { payment, refunds, disputes }: { payment: PaymentState; refunds: readonly RefundState[]; disputes: readonly DisputeState[] },
  _optional: Record<string, never> = {}
): PaymentTotals {
  const totals = refundTotals({ refunds });
  return {
    refundedMinor: totals.succeeded,
    refundHeldMinor: totals.held,
    disputedMinor: disputedMinor({ disputes }),
    status: derivePaymentStatus({ intent: payment.intentStatus, capturedMinor: payment.capturedMinor, refundedMinor: totals.succeeded }),
  };
}

import { AsyncLocalStorage } from "node:async_hooks";

import {
  ATTEMPT_PATCH_COLUMNS, DISPUTE_PATCH_COLUMNS, LEDGER_MODES, LEDGER_TABLE_RULES, LEDGER_TABLES, OPEN_INBOX_STATES,
  PAYMENT_PATCH_COLUMNS, REFUND_PATCH_COLUMNS,
  attemptFromRow, attemptToRow, disputeFromRow, disputeToRow, encodeColumns, encodeMinor, evidenceFromRow, evidenceToRow,
  inboxFromRow, inboxToRow, outboxFromRow, outboxToRow, patchColumns, paymentFromRow, paymentToRow, quarantineFromRow,
  quarantineToRow, refundFromRow, refundToRow, operatorActionFromRow, operatorActionToRow, revivedPayload, UNSETTLED_REFUND_STATUSES,
  OPEN_ATTEMPT_OUTCOMES, type AttemptOp, type OperatorActionRecord, type AttemptPatch, type AttemptRecord, type DisputePatch, type DisputeRecord, type EvidenceRecord, type InboxRecord,
  type LedgerTableName, type LedgerTableRules, type NewInbox, type NewOutbox, type NewPayment, type NewQuarantine,
  type OutboxRecord, type PaymentPatch, type PaymentRecord, type QuarantineRecord, type RefundPatch, type RefundRecord,
} from "./rows.js";
import {
  LedgerConstraintError, type LedgerKeyScope, type LedgerTx, type PaymentsLedger, type ProviderRefScope, type ScanOptions,
} from "./repo.js";

/**
 * @file The in-memory `PaymentsLedger`: same semantics as `repo.sql.ts`, proven by the shared
 * contract suite — NOT NULL / CHECK rules, unique keys (a NULL part never conflicts, as in SQL),
 * scoped payment references, optimistic versions, insert-or-ignore inbox with guarded state
 * transitions, append-only evidence. For tests and fakes; one process only.
 *
 * Every write goes through the same `rows.ts` codecs as the SQL adapter: a record is encoded to its
 * row (integers through `encodeMinor`), checked against `LEDGER_TABLE_RULES`, and decoded back, and
 * a patch is applied to the row through the same `*_PATCH_COLUMNS` allow-list. So a value the
 * database would refuse or store differently is refused or normalized here too.
 *
 * Transactions are serialized (one at a time, FIFO) and roll back on throw by restoring a snapshot
 * taken at the start. Snapshots are cheap shallow `Map` copies because a stored record is never
 * mutated — every write replaces the record object. A nested `transaction` joins the outer one,
 * matching the storage kernel (no savepoint).
 */

type Row = { readonly id: string };
type Columns = Record<string, unknown>;
/** One unique key over a row; `null` when any part is NULL (SQL: NULLs never collide). */
type UniqueKey<R> = (row: R) => string | null;
/** The record ↔ row codec of one table (the `rows.ts` mappers). */
interface Codec<R> {
  readonly toRow: (record: R) => Columns;
  readonly fromRow: (row: Columns) => R;
}
/** What a child row names: its payment, in its own workspace + mode (the composite foreign key). */
type ParentRef = { readonly paymentId: string; readonly workspaceId: string; readonly mode: string };

function key(parts: readonly (string | null)[]): string | null {
  return parts.includes(null) ? null : JSON.stringify(parts);
}

function codec<R>(toRow: (record: R) => object, fromRow: (row: never) => R): Codec<R> {
  return { toRow: toRow as (record: R) => Columns, fromRow: fromRow as (row: Columns) => R };
}

/** True when `row` breaks the table's NOT NULL or CHECK rules, exactly as the migration declares them. */
function breaksCheck({ rules, row }: { rules: LedgerTableRules; row: Columns }): boolean {
  if (!(LEDGER_MODES as readonly unknown[]).includes(row.mode)) return true;
  const missing = Object.entries(row).some(([column, value]) => (value === null || value === undefined) && !rules.nullable.includes(column));
  return missing || rules.nonNegative.some((column) => (row[column] as number) < 0);
}

/** A table: rows by id plus the rules, unique keys and payment reference the SQL schema enforces. */
class MemoryTable<R extends Row> {
  rows = new Map<string, R>();
  private readonly rules: LedgerTableRules;

  constructor(
    readonly required: { name: LedgerTableName; codec: Codec<R> },
    private readonly optional: { uniques?: readonly UniqueKey<R>[]; parentOf?: (row: R) => ParentRef } = {}
  ) {
    this.rules = LEDGER_TABLE_RULES[required.name];
  }

  private fail(kind: LedgerConstraintError["kind"]): never {
    throw new LedgerConstraintError({ kind, table: this.required.name });
  }

  /** The record a row decodes to, after the NOT NULL / CHECK rules (checked first, as SQL does). */
  private checked(row: Columns): R {
    if (breaksCheck({ rules: this.rules, row })) this.fail("check");
    return this.required.codec.fromRow(row);
  }

  private conflict(row: R): boolean {
    return (this.optional.uniques ?? []).some((unique) => {
      const value = unique(row);
      return value !== null && [...this.rows.values()].some((other) => other.id !== row.id && unique(other) === value);
    });
  }

  /** The child's payment must exist in the child's own workspace + mode. */
  private orphan(row: R, payments: ReadonlyMap<string, PaymentRecord>): boolean {
    if (this.optional.parentOf === undefined) return false;
    const ref = this.optional.parentOf(row);
    const parent = payments.get(ref.paymentId);
    return parent === undefined || parent.workspaceId !== ref.workspaceId || parent.mode !== ref.mode;
  }

  /** `record` as it would be stored (encoded, rule-checked, decoded); throws what an insert would. */
  validate(record: R): R {
    return this.checked(this.required.codec.toRow(record));
  }

  /** Stores `record` (round-tripped through its row) and returns what was stored. */
  insert(required: { record: R; payments: ReadonlyMap<string, PaymentRecord> }): R {
    const stored = this.validate(required.record);
    if (this.rows.has(stored.id) || this.conflict(stored)) this.fail("unique");
    if (this.orphan(stored, required.payments)) this.fail("foreign-key");
    this.rows.set(stored.id, stored);
    return stored;
  }

  /**
   * Applies the column `set` (already encoded) to the row with `id`; false when there is none, or
   * when `when` refuses the current row (the SQL `WHERE version = ?` / `state IN (...)` fence).
   */
  update(required: { id: string; set: (current: R) => Columns }, optional: { when?: (current: R) => boolean } = {}): boolean {
    const current = this.rows.get(required.id);
    if (current === undefined || optional.when?.(current) === false) return false;
    const next = this.checked({ ...this.required.codec.toRow(current), ...required.set(current) });
    if (this.conflict(next)) this.fail("unique");
    this.rows.set(required.id, next);
    return true;
  }

  find(match: (row: R) => boolean): R | null {
    return [...this.rows.values()].find(match) ?? null;
  }

  /** Ordered by `order`, ties by id in code-unit order (deterministic; see the SQL adapter on collation). */
  list(match: (row: R) => boolean, order: (row: R) => number): R[] {
    return [...this.rows.values()].filter(match).sort((a, b) => order(a) - order(b) || Number(a.id > b.id) - Number(a.id < b.id));
  }
}

/** The inbox's dedupe key: one provider event per workspace + mode + provider account. */
const inboxEventKey = (r: Pick<InboxRecord, "workspaceId" | "mode" | "providerId" | "providerAccountId" | "providerEventId">) =>
  key([r.workspaceId, r.mode, r.providerId, r.providerAccountId, r.providerEventId]);

const inScope = (scope: LedgerKeyScope) => (row: { workspaceId: string; mode: string }) =>
  row.workspaceId === scope.workspaceId && row.mode === scope.mode;
const ofPayment = (paymentId: string) => (row: { paymentId: string | null }) => row.paymentId === paymentId;
const isOpen = (row: InboxRecord) => OPEN_INBOX_STATES.includes(row.state);

type Scanned = { readonly id: string; readonly workspaceId: string; readonly mode: string; readonly updatedAt: number };

/** A scan's shared filters, as the SQL adapter's: the cutoff, the optional scope, and the resume cursor. */
function scanMatch({ updatedBefore, options }: { updatedBefore: number; options: ScanOptions }): (row: Scanned) => boolean {
  const { scope, after } = options;
  return (row) => row.updatedAt < updatedBefore
    && (scope === undefined || inScope(scope)(row))
    && (after === undefined || row.updatedAt > after.updatedAt || (row.updatedAt === after.updatedAt && row.id > after.id));
}
const parentRef = (row: ParentRef): ParentRef => row;

class MemoryLedgerTables {
  /** The outbox enqueue order (the SQL `seq` column, 0002): ties on `createdAt` keep enqueue order. */
  outboxSeq = new Map<string, number>();

  readonly payments = new MemoryTable<PaymentRecord>({ name: LEDGER_TABLES.payments, codec: codec(paymentToRow, paymentFromRow) }, {
    uniques: [
      (r) => key([r.workspaceId, r.mode, r.idempotencyKey]),
      (r) => key([r.workspaceId, r.mode, r.providerId, r.providerAccountId, r.providerRef]),
    ],
  });
  readonly attempts = new MemoryTable<AttemptRecord>({ name: LEDGER_TABLES.attempts, codec: codec(attemptToRow, attemptFromRow) }, {
    uniques: [(r) => key([r.workspaceId, r.mode, r.operationKey])],
    parentOf: parentRef,
  });
  readonly refunds = new MemoryTable<RefundRecord>({ name: LEDGER_TABLES.refunds, codec: codec(refundToRow, refundFromRow) }, {
    uniques: [
      (r) => key([r.workspaceId, r.mode, r.providerId, r.providerAccountId, r.providerRefundRef]),
      (r) => key([r.workspaceId, r.mode, r.idempotencyKey]),
    ],
    parentOf: parentRef,
  });
  readonly disputes = new MemoryTable<DisputeRecord>({ name: LEDGER_TABLES.disputes, codec: codec(disputeToRow, disputeFromRow) }, {
    uniques: [(r) => key([r.workspaceId, r.mode, r.providerId, r.providerAccountId, r.providerDisputeRef])],
    parentOf: parentRef,
  });
  readonly evidence = new MemoryTable<EvidenceRecord>({ name: LEDGER_TABLES.evidence, codec: codec(evidenceToRow, evidenceFromRow) }, {
    parentOf: parentRef,
  });
  readonly inbox = new MemoryTable<InboxRecord>({ name: LEDGER_TABLES.inbox, codec: codec(inboxToRow, inboxFromRow) }, { uniques: [inboxEventKey] });
  readonly outbox = new MemoryTable<OutboxRecord>({ name: LEDGER_TABLES.outbox, codec: codec(outboxToRow, outboxFromRow) });
  readonly quarantine = new MemoryTable<QuarantineRecord>({ name: LEDGER_TABLES.quarantine, codec: codec(quarantineToRow, quarantineFromRow) });
  readonly operatorActions = new MemoryTable<OperatorActionRecord>(
    { name: LEDGER_TABLES.operatorActions, codec: codec(operatorActionToRow, operatorActionFromRow) },
    { parentOf: parentRef }
  );

  private all(): MemoryTable<Row>[] {
    return [
      this.payments, this.attempts, this.refunds, this.disputes, this.evidence, this.inbox, this.outbox, this.quarantine, this.operatorActions,
    ] as unknown as MemoryTable<Row>[];
  }

  /** Sequence bookkeeping must roll back with the rows, so retried ids cannot change enqueue order. */
  snapshot(): { rows: Map<string, Row>[]; outboxSeq: Map<string, number> } {
    return { rows: this.all().map((table) => new Map(table.rows)), outboxSeq: new Map(this.outboxSeq) };
  }

  restore(snapshot: ReturnType<MemoryLedgerTables["snapshot"]>): void {
    this.all().forEach((table, index) => {
      table.rows = snapshot.rows[index] as Map<string, Row>;
    });
    this.outboxSeq = snapshot.outboxSeq;
  }
}

class MemoryLedgerTx implements LedgerTx {
  constructor(
    private readonly t: MemoryLedgerTables,
    private readonly inTransaction: () => boolean
  ) {}

  private insert<R extends Row>({ table, record }: { table: MemoryTable<R>; record: R }): R {
    return table.insert({ record, payments: this.t.payments.rows });
  }

  // Payments ------------------------------------------------------------------------------------

  async insertPayment({ payment }: { payment: NewPayment }): Promise<PaymentRecord> {
    return this.insert({ table: this.t.payments, record: { ...payment, version: 1 } });
  }

  async getPayment(required: LedgerKeyScope & { id: string }): Promise<PaymentRecord | null> {
    const scoped = inScope(required);
    return this.t.payments.find((r) => scoped(r) && r.id === required.id);
  }

  async findPaymentByIdempotencyKey(required: LedgerKeyScope & { key: string }): Promise<PaymentRecord | null> {
    const scoped = inScope(required);
    return this.t.payments.find((r) => scoped(r) && r.idempotencyKey === required.key);
  }

  async findPaymentByProviderRef(required: ProviderRefScope & { providerRef: string }): Promise<PaymentRecord | null> {
    const scoped = inScope(required);
    return this.t.payments.find(
      (r) => scoped(r) && r.providerId === required.providerId && r.providerAccountId === required.providerAccountId && r.providerRef === required.providerRef
    );
  }

  /**
   * Transactions are already serialized here, so holding the payment's lock is implicit — but only
   * inside one, so outside a transaction this throws exactly where the SQL kernel's `lockKey` does.
   */
  async lockPayment(required: LedgerKeyScope & { id: string }): Promise<PaymentRecord | null> {
    if (!this.inTransaction()) throw new Error("ledger: lockPayment() must be called inside transaction()");
    return this.getPayment(required);
  }

  async updatePayment({ id, expectedVersion, patch }: { id: string; expectedVersion: number; patch: PaymentPatch }): Promise<boolean> {
    const set = { ...patchColumns({ patch, columns: PAYMENT_PATCH_COLUMNS }), version: encodeMinor({ value: expectedVersion + 1 }) };
    return this.t.payments.update({ id, set: () => set }, { when: (r) => r.version === expectedVersion });
  }

  // Attempts ------------------------------------------------------------------------------------

  async insertAttempt({ attempt }: { attempt: AttemptRecord }): Promise<void> {
    this.insert({ table: this.t.attempts, record: attempt });
  }

  async updateAttempt({ id, patch }: { id: string; patch: AttemptPatch }): Promise<boolean> {
    const set = patchColumns({ patch, columns: ATTEMPT_PATCH_COLUMNS });
    return this.t.attempts.update({ id, set: () => set });
  }

  async findAttemptByOperationKey(required: LedgerKeyScope & { operationKey: string }): Promise<AttemptRecord | null> {
    const scoped = inScope(required);
    return this.t.attempts.find((r) => scoped(r) && r.operationKey === required.operationKey);
  }

  async listAttempts({ paymentId }: { paymentId: string }): Promise<AttemptRecord[]> {
    return this.t.attempts.list(ofPayment(paymentId), (r) => r.createdAt);
  }

  // Refunds -------------------------------------------------------------------------------------

  async insertRefund({ refund }: { refund: RefundRecord }): Promise<void> {
    this.insert({ table: this.t.refunds, record: refund });
  }

  async updateRefund({ id, patch }: { id: string; patch: RefundPatch }): Promise<boolean> {
    const set = patchColumns({ patch, columns: REFUND_PATCH_COLUMNS });
    return this.t.refunds.update({ id, set: () => set });
  }

  async findRefund(
    { paymentId }: { paymentId: string },
    optional: { correlationId?: string; providerRefundRef?: string } = {}
  ): Promise<RefundRecord | null> {
    const own = ofPayment(paymentId);
    const byCorrelation = optional.correlationId === undefined ? null : this.t.refunds.find((r) => own(r) && r.id === optional.correlationId);
    if (byCorrelation !== null || optional.providerRefundRef === undefined) return byCorrelation;
    return this.t.refunds.find((r) => own(r) && r.providerRefundRef === optional.providerRefundRef);
  }

  async findRefundByIdempotencyKey(required: LedgerKeyScope & { key: string }): Promise<RefundRecord | null> {
    const scoped = inScope(required);
    return this.t.refunds.find((r) => scoped(r) && r.idempotencyKey === required.key);
  }

  async listRefunds({ paymentId }: { paymentId: string }): Promise<RefundRecord[]> {
    return this.t.refunds.list(ofPayment(paymentId), (r) => r.createdAt);
  }

  // Disputes ------------------------------------------------------------------------------------

  async insertDispute({ dispute }: { dispute: DisputeRecord }): Promise<void> {
    this.insert({ table: this.t.disputes, record: dispute });
  }

  async updateDispute({ id, patch }: { id: string; patch: DisputePatch }): Promise<boolean> {
    const set = patchColumns({ patch, columns: DISPUTE_PATCH_COLUMNS });
    return this.t.disputes.update({ id, set: () => set });
  }

  async findDispute({ paymentId, providerDisputeRef }: { paymentId: string; providerDisputeRef: string }): Promise<DisputeRecord | null> {
    return this.t.disputes.find((r) => r.paymentId === paymentId && r.providerDisputeRef === providerDisputeRef);
  }

  async listDisputes({ paymentId }: { paymentId: string }): Promise<DisputeRecord[]> {
    return this.t.disputes.list(ofPayment(paymentId), (r) => r.createdAt);
  }

  // Evidence ------------------------------------------------------------------------------------

  async appendEvidence({ evidence }: { evidence: EvidenceRecord }): Promise<void> {
    this.insert({ table: this.t.evidence, record: evidence });
  }

  async listEvidence({ paymentId }: { paymentId: string }): Promise<EvidenceRecord[]> {
    return this.t.evidence.list(ofPayment(paymentId), (r) => r.recordedAt);
  }

  // Webhook inbox -------------------------------------------------------------------------------

  async insertInbox({ entry }: { entry: NewInbox }): Promise<{ inserted: boolean; id: string }> {
    // SQL checks the row (integers, NOT NULL, CHECK) before ON CONFLICT can skip it, so a bad redelivery still throws.
    const record = this.t.inbox.validate({ ...entry, state: "received", attempts: 0, lastError: null, appliedAt: null, purgedAt: null });
    const eventKey = inboxEventKey(record);
    const existing = this.t.inbox.find((r) => inboxEventKey(r) === eventKey);
    if (existing !== null) return { inserted: false, id: existing.id };
    return { inserted: true, id: this.insert({ table: this.t.inbox, record }).id };
  }

  async getInbox({ id }: { id: string }): Promise<InboxRecord | null> {
    return this.t.inbox.rows.get(id) ?? null;
  }

  async markInboxApplied({ id, appliedAt }: { id: string; appliedAt: number }): Promise<boolean> {
    const set = encodeColumns({ state: "applied", facts_json: null, applied_at: appliedAt, purged_at: appliedAt });
    return this.t.inbox.update({ id, set: () => set }, { when: isOpen });
  }

  async parkInbox({ id, error, nextAttemptAt }: { id: string; error: string; nextAttemptAt: number }): Promise<boolean> {
    const set = encodeColumns({ state: "parked", last_error: error, next_attempt_at: nextAttemptAt });
    return this.t.inbox.update({ id, set: (r) => ({ ...set, attempts: r.attempts + 1 }) }, { when: isOpen });
  }

  async deadInbox({ id, error }: { id: string; error: string }): Promise<boolean> {
    const set = encodeColumns({ state: "dead", last_error: error });
    return this.t.inbox.update({ id, set: () => set }, { when: isOpen });
  }

  async reviveInbox(
    { id, nextAttemptAt }: { id: string; nextAttemptAt: number },
    optional: { payload?: { factsJson: string; bodySha256: string } } = {}
  ): Promise<boolean> {
    const set = encodeColumns({ state: "received", attempts: 0, next_attempt_at: nextAttemptAt, ...revivedPayload(optional) });
    return this.t.inbox.update({ id, set: () => set }, { when: (r) => r.state === "dead" });
  }

  async listDueInbox({ now, limit }: { now: number; limit: number }): Promise<InboxRecord[]> {
    const due = (r: InboxRecord) => isOpen(r) && r.nextAttemptAt <= now;
    return this.t.inbox.list(due, (r) => r.nextAttemptAt).slice(0, limit);
  }

  // Outbox --------------------------------------------------------------------------------------

  async enqueueOutbox({ message }: { message: NewOutbox }): Promise<void> {
    this.insert({ table: this.t.outbox, record: { ...message, publishedAt: null } });
    this.t.outboxSeq.set(message.id, this.t.outboxSeq.size + 1);
  }

  async listPendingOutbox({ limit }: { limit: number }): Promise<OutboxRecord[]> {
    const seq = (r: OutboxRecord) => this.t.outboxSeq.get(r.id) as number;
    return this.t.outbox.list((r) => r.publishedAt === null, (r) => r.createdAt).sort((a, b) => a.createdAt - b.createdAt || seq(a) - seq(b)).slice(0, limit);
  }

  async markOutboxPublished({ id, publishedAt }: { id: string; publishedAt: number }): Promise<boolean> {
    const set = encodeColumns({ published_at: publishedAt });
    return this.t.outbox.update({ id, set: () => set });
  }

  // Quarantine ----------------------------------------------------------------------------------

  async insertQuarantine({ entry }: { entry: NewQuarantine }): Promise<void> {
    this.insert({ table: this.t.quarantine, record: { ...entry, resolvedAt: null } });
  }

  async listQuarantine(required: LedgerKeyScope, optional: { unresolvedOnly?: boolean } = {}): Promise<QuarantineRecord[]> {
    const scoped = inScope(required);
    const visible = (r: QuarantineRecord) => scoped(r) && (optional.unresolvedOnly !== true || r.resolvedAt === null);
    return this.t.quarantine.list(visible, (r) => r.createdAt);
  }

  async resolveQuarantine({ id, resolvedAt }: { id: string; resolvedAt: number }): Promise<boolean> {
    const set = encodeColumns({ resolved_at: resolvedAt });
    return this.t.quarantine.update({ id, set: () => set });
  }

  // Reconciliation scans ------------------------------------------------------------------------

  async listUnknownPayments({ updatedBefore, limit }: { updatedBefore: number; limit: number }, optional: ScanOptions = {}): Promise<PaymentRecord[]> {
    const due = scanMatch({ updatedBefore, options: optional });
    return this.t.payments.list((r) => r.intentStatus === "unknown" && due(r), (r) => r.updatedAt).slice(0, limit);
  }

  async listUnsettledRefunds({ updatedBefore, limit }: { updatedBefore: number; limit: number }, optional: ScanOptions = {}): Promise<RefundRecord[]> {
    const due = scanMatch({ updatedBefore, options: optional });
    return this.t.refunds.list((r) => UNSETTLED_REFUND_STATUSES.includes(r.status) && due(r), (r) => r.updatedAt).slice(0, limit);
  }

  async listOpenAttempts(
    { ops, updatedBefore, limit }: { ops: readonly AttemptOp[]; updatedBefore: number; limit: number },
    optional: ScanOptions = {}
  ): Promise<AttemptRecord[]> {
    const due = scanMatch({ updatedBefore, options: optional });
    const open = (r: AttemptRecord) => ops.includes(r.op) && OPEN_ATTEMPT_OUTCOMES.includes(r.outcome) && due(r);
    return this.t.attempts.list(open, (r) => r.updatedAt).slice(0, limit);
  }

  // Operator actions ----------------------------------------------------------------------------

  async appendOperatorAction({ action }: { action: OperatorActionRecord }): Promise<void> {
    this.insert({ table: this.t.operatorActions, record: action });
  }

  async listOperatorActions({ paymentId }: { paymentId: string }): Promise<OperatorActionRecord[]> {
    return this.t.operatorActions.list(ofPayment(paymentId), (r) => r.createdAt);
  }
}

/**
 * A fresh, empty in-memory ledger.
 *
 * @example const ledger = memoryPaymentsLedger(); await ledger.transaction({ fn: (tx) => tx.insertPayment({ payment }) });
 */
export function memoryPaymentsLedger(_required: Record<string, never> = {}, _optional: Record<string, never> = {}): PaymentsLedger {
  const tables = new MemoryLedgerTables();
  const active = new AsyncLocalStorage<true>();
  const tx = new MemoryLedgerTx(tables, () => active.getStore() === true);
  let tail: Promise<unknown> = Promise.resolve();

  async function attempt<T>(fn: (tx: LedgerTx) => Promise<T>): Promise<T> {
    const snapshot = tables.snapshot();
    try {
      return await fn(tx);
    } catch (error) {
      tables.restore(snapshot);
      throw error;
    }
  }

  return {
    transaction<T>({ fn }: { fn: (tx: LedgerTx) => Promise<T> }, _optional: Record<string, never> = {}): Promise<T> {
      if (active.getStore() === true) return fn(tx);
      const run = tail.then(() => active.run(true, () => attempt(fn)));
      // The queue must keep moving past a failed transaction; the caller still sees the failure via `run`.
      tail = run.catch(() => undefined);
      return run;
    },
  };
}

/**
 * @file Shared steps of every payments operation: typed refusals, request checks, the provider
 * context, the provider-call wrapper, attempt rows, alerts and the idempotency-race retry.
 *
 * Runtime conditions are returned as typed `PaymentError`s, never thrown. What still throws is a
 * composition or storage fault (a ledger that cannot write), which the host must see.
 */
import { moneyProblem, type Money } from "../../money/money.js";
import type { PaymentsAlertKind } from "../contract/alerts.js";
import {
  paymentError, supportsCurrency, type Outcome, type PaymentError, type PaymentErrorCode, type PaymentProvider, type ProviderContext,
} from "../contract/provider.js";
import type { RiskDecision } from "../contract/risk.js";
import { sameScope, scopeProblem, type PaymentScope } from "../contract/scope.js";
import type { ApplyResult } from "../accounting/apply-evidence.js";
import { LedgerConstraintError, type LedgerTx } from "../ledger/repo.js";
import type { AttemptOp, AttemptRecord, PaymentRecord } from "../ledger/rows.js";
import type { OpsDeps } from "./deps.js";
import { scopeOf } from "./view.js";

export interface Failure {
  readonly ok: false;
  readonly error: PaymentError;
}

/** A typed refusal. `optional.retryable`: the same request may succeed later (e.g. once a conflicting call is reconciled). */
export function fail(
  { code, message }: { code: PaymentErrorCode; message: string },
  optional: { retryable?: boolean } = {}
): Failure {
  return { ok: false, error: paymentError({ code, message }, optional) };
}

/** A replayed operation re-reads its result; the original risk decision is not stored, so this says so. */
export const REPLAY_RISK: RiskDecision = { verdict: "allow", reasons: ["idempotent-replay"], fallback: false };
/** Capture/void act on an intent the risk gate already passed (and a person approved). */
export const NOT_ASSESSED_RISK: RiskDecision = { verdict: "allow", reasons: ["not-assessed"], fallback: false };

/** The scope is usable and names a registered provider. */
export function checkProvider(
  { deps, scope }: { deps: OpsDeps; scope: PaymentScope },
  _optional: Record<string, never> = {}
): { readonly ok: true; readonly provider: PaymentProvider } | Failure {
  const problem = scopeProblem({ scope });
  if (problem) return fail({ code: "INVALID_REQUEST", message: problem });
  const registered = deps.providers.get({ id: scope.providerId });
  if (!registered) return fail({ code: "PROVIDER_NOT_REGISTERED", message: `no payment provider '${scope.providerId}' is registered` });
  return { ok: true, provider: registered.provider };
}

/** Valid, positive Money in a currency the provider accepts. */
export function checkAmount({ amount, provider }: { amount: Money; provider: PaymentProvider }, _optional: Record<string, never> = {}): Failure | null {
  const problem = moneyProblem({ money: amount });
  if (problem) return fail({ code: "INVALID_REQUEST", message: `amount: ${problem}` });
  if (!supportsCurrency({ capabilities: provider.capabilities, currency: amount.currency })) {
    return fail({ code: "CURRENCY_UNSUPPORTED", message: `provider '${provider.id}' does not accept ${amount.currency}` });
  }
  return null;
}

/** Each named field must be a non-empty string. */
export function checkText({ fields }: { fields: Readonly<Record<string, unknown>> }, _optional: Record<string, never> = {}): Failure | null {
  const blank = Object.entries(fields).find(([, value]) => typeof value !== "string" || value.trim().length === 0);
  return blank ? fail({ code: "INVALID_REQUEST", message: `${blank[0]} must be a non-empty string` }) : null;
}

export async function resolveContext(
  { deps, scope, provider }: { deps: OpsDeps; scope: PaymentScope; provider: PaymentProvider },
  _optional: Record<string, never> = {}
): Promise<{ readonly ok: true; readonly ctx: ProviderContext } | Failure> {
  const resolved = await deps.contexts.resolve({ scope, provider });
  return resolved.ok ? resolved : { ok: false, error: resolved.error };
}

/** The record when it belongs to `scope` in full (site, provider account too), else null. */
export function owned<R extends PaymentRecord | null>(
  { record, scope }: { record: R; scope: PaymentScope },
  _optional: Record<string, never> = {}
): R | null {
  return record !== null && sameScope({ a: scopeOf(record), b: scope }) ? record : null;
}

export function readPayment(
  { tx, scope, paymentId }: { tx: LedgerTx; scope: PaymentScope; paymentId: string },
  _optional: Record<string, never> = {}
): Promise<PaymentRecord | null> {
  return tx.getPayment({ workspaceId: scope.workspaceId, mode: scope.mode, id: paymentId }).then((record) => owned({ record, scope }));
}

function unknownOutcome({ message }: { message: string }): { readonly kind: "unknown"; readonly error: PaymentError } {
  return { kind: "unknown", error: paymentError({ code: "PROVIDER_ERROR", message }, { retryable: true }) };
}

/**
 * Calls the provider. Its contract is to return an Outcome and never throw; a plugin that throws,
 * or answers something that is not a readable Outcome, is treated as `unknown` — money MAY have
 * moved, so it is reconciled, never marked failed.
 */
export async function dispatch<T>({ call }: { call: () => Promise<Outcome<T>> }, _optional: Record<string, never> = {}): Promise<Outcome<T>> {
  let outcome: Outcome<T> | null | undefined;
  try {
    outcome = await call();
  } catch (error) {
    return unknownOutcome({ message: `provider threw: ${error instanceof Error ? error.message : String(error)}` });
  }
  return readable({ outcome }) ? outcome : unknownOutcome({ message: "provider returned no readable Outcome" });
}

/** `ok` with a non-null payload, or a `rejected`/`unknown` carrying a complete PaymentError. An unreadable rejection is NOT trusted as "no money moved". */
function readable<T>(holder: { outcome: Outcome<T> | null | undefined }): holder is { outcome: Outcome<T> } {
  const { outcome } = holder;
  if (!outcome) return false;
  if (outcome.kind === "ok") return outcome.value !== undefined && outcome.value !== null;
  return (outcome.kind === "rejected" || outcome.kind === "unknown") && typeof outcome.error?.code === "string"
    && typeof outcome.error.message === "string" && typeof outcome.error.retryable === "boolean";
}

/** A `dispatched` attempt row, written BEFORE the provider call. `optional.amount`: what a capture requested. */
export function newAttempt(
  { deps, payment, op, operationKey }: { deps: OpsDeps; payment: PaymentRecord; op: AttemptOp; operationKey: string },
  optional: { refundId?: string; amount?: Money } = {}
): AttemptRecord {
  const at = deps.now();
  return {
    id: deps.newId(), paymentId: payment.id, workspaceId: payment.workspaceId, siteId: payment.siteId, providerId: payment.providerId,
    providerAccountId: payment.providerAccountId, mode: payment.mode, op, operationKey, refundId: optional.refundId ?? null,
    outcome: "dispatched", errorCode: null, errorMessage: null, createdAt: at, updatedAt: at,
    currency: optional.amount?.currency ?? null, amountMinor: optional.amount?.minorUnits ?? null,
  };
}

/** Records what the provider call answered on its attempt row. */
export async function markAttempt(
  { tx, deps, attemptId, outcome }: { tx: LedgerTx; deps: OpsDeps; attemptId: string; outcome: Outcome<unknown> },
  _optional: Record<string, never> = {}
): Promise<void> {
  const error = outcome.kind === "ok" ? {} : { errorCode: outcome.error.code, errorMessage: outcome.error.message };
  await tx.updateAttempt({ id: attemptId, patch: { outcome: outcome.kind, ...error, updatedAt: deps.now() } });
}

/**
 * What a non-ok outcome reports. A `rejected` attempt spends its idempotency key: a retry under it
 * only replays this answer (`rejectedReplay`), so it is never retryable whatever the provider said
 * (a 429's `retryable` means "try again", which here needs a new key — and a new grant).
 */
export function outcomeError({ outcome }: { outcome: Exclude<Outcome<unknown>, { kind: "ok" }> }, _optional: Record<string, never> = {}): PaymentError {
  return outcome.kind === "rejected" ? { ...outcome.error, retryable: false } : outcome.error;
}

/** The suffix a replayed failure carries: the key is spent, nothing moved, a new attempt needs a new key. */
export const SPENT_KEY = "moved no money; a new attempt needs a new idempotencyKey";

/**
 * A replay of a key whose attempt was `rejected` reports that rejection again — never `ok` (C-1).
 * `markAttempt` writes `errorCode`/`errorMessage` for every non-ok outcome, so both are present.
 */
export function rejectedReplay({ attempt }: { attempt: AttemptRecord }, _optional: Record<string, never> = {}): Failure | null {
  if (attempt.outcome !== "rejected") return null;
  const message = `${attempt.errorMessage as string} (replayed: the earlier ${attempt.op} under this idempotencyKey was rejected and ${SPENT_KEY})`;
  return fail({ code: attempt.errorCode as PaymentErrorCode, message });
}

/** Raises an alert; a failing sink never fails the money operation that raised it. */
export async function raiseAlert(
  { deps, kind, payment, detail }: { deps: OpsDeps; kind: PaymentsAlertKind; payment: Pick<PaymentRecord, "workspaceId" | "mode" | "id">; detail: string },
  _optional: Record<string, never> = {}
): Promise<void> {
  const alert = { kind, workspaceId: payment.workspaceId, mode: payment.mode, paymentId: payment.id, detail };
  await deps.alerts.raise({ alert }).catch(() => undefined);
}

/**
 * True when the single writer applied the observation's subject (the intent, or the refund). Any
 * quarantine — of the subject or of a refund/dispute riding along — raises a `quarantine` alert.
 */
export async function noteApplied(
  { deps, payment, result }: { deps: OpsDeps; payment: Pick<PaymentRecord, "workspaceId" | "mode" | "id">; result: ApplyResult },
  _optional: Record<string, never> = {}
): Promise<boolean> {
  const applied = result.kind === "applied";
  if (!applied || result.quarantined.length > 0) {
    await raiseAlert({ deps, kind: "quarantine", payment, detail: `evidence not applied cleanly: ${JSON.stringify(result)}` });
  }
  return applied;
}

/**
 * Runs `open`; when it loses an idempotency race (a concurrent call with the same key inserted
 * first, so the unique key refused this one), re-reads with `lookup` in a fresh transaction and
 * returns that call's result instead. Any other failure propagates.
 */
export async function onUniqueRace<T>(
  { open, lookup }: { open: () => Promise<T>; lookup: () => Promise<T | null> },
  _optional: Record<string, never> = {}
): Promise<T> {
  try {
    return await open();
  } catch (error) {
    if (!(error instanceof LedgerConstraintError) || error.kind !== "unique") throw error;
    const winner = await lookup();
    if (winner === null) throw error;
    return winner;
  }
}

/**
 * @file The payments status model (gap check item 3). Evidence is append-only; each RECORD's
 * status merges forward along a transition table; the PAYMENT's status is DERIVED from its intent,
 * refunds and disputes — never stored as the source of truth.
 *
 * Why not "statuses only move forward" for the payment: a Stripe refund can go succeeded → failed
 * (returning money to the merchant), and a won dispute returns withdrawn money. A forward-only
 * payment status could not express either. Each merge function below takes the CURRENT and the
 * INCOMING status and returns the one to keep, so reversed delivery order and stale `retrieve`
 * snapshots can never regress a record.
 *
 * Replaces `state-machine.ts` once `lipay-plugin.ts` is split (L4).
 */
import type { ProviderDisputeStatus, ProviderPaymentStatus } from "../contract/evidence.js";

/** A payment intent's own status. `unknown` is ours: a dispatched call whose outcome we could not tell. */
export type IntentStatus = ProviderPaymentStatus | "unknown";

/** `reserved` = held by us before dispatch; `unknown` = dispatched, outcome not known. Both still hold money. */
export type RefundStatus = "reserved" | "unknown" | "pending" | "succeeded" | "failed";

export type DisputeStatus = ProviderDisputeStatus;

export type DerivedPaymentStatus = IntentStatus | "partially_refunded" | "refunded";

/** Where each status may go next. Absent targets are ignored (stale or reordered evidence). */
const INTENT_NEXT: Readonly<Record<IntentStatus, readonly IntentStatus[]>> = {
  unknown: ["requires_action", "pending", "authorized", "succeeded", "failed", "canceled"],
  requires_action: ["pending", "authorized", "succeeded", "failed", "canceled"],
  // `pending → requires_action`: a provider may report CREATED first and ask for 3-D Secure / payer action after.
  pending: ["requires_action", "authorized", "succeeded", "failed", "canceled"],
  authorized: ["succeeded", "canceled"],
  succeeded: [],
  // Evidence that money moved beats an earlier decline: a shopper can retry the same intent after a
  // decline (Stripe `requires_payment_method` maps to `failed`), and dropping the later success would
  // re-create bug B4 (charged but "failed"). L0/L1 review.
  failed: ["authorized", "succeeded"],
  canceled: [],
};

// `succeeded → failed` is the Stripe late refund failure; nothing leaves `failed`.
const REFUND_NEXT: Readonly<Record<RefundStatus, readonly RefundStatus[]>> = {
  reserved: ["unknown", "pending", "succeeded", "failed"],
  unknown: ["pending", "succeeded", "failed"],
  pending: ["succeeded", "failed"],
  succeeded: ["failed"],
  failed: [],
};

const DISPUTE_NEXT: Readonly<Record<DisputeStatus, readonly DisputeStatus[]>> = {
  open: ["won", "lost"],
  won: [],
  lost: [],
};

function merge<S extends string>(table: Readonly<Record<S, readonly S[]>>, current: S, incoming: S): S {
  return table[current].includes(incoming) ? incoming : current;
}

/** The intent status to keep after `incoming` evidence. */
export function mergeIntentStatus(
  { current, incoming }: { current: IntentStatus; incoming: IntentStatus },
  _optional: Record<string, never> = {}
): IntentStatus {
  return merge(INTENT_NEXT, current, incoming);
}

/** The refund status to keep after `incoming` evidence. */
export function mergeRefundStatus(
  { current, incoming }: { current: RefundStatus; incoming: RefundStatus },
  _optional: Record<string, never> = {}
): RefundStatus {
  return merge(REFUND_NEXT, current, incoming);
}

/** The dispute status to keep after `incoming` evidence. */
export function mergeDisputeStatus(
  { current, incoming }: { current: DisputeStatus; incoming: DisputeStatus },
  _optional: Record<string, never> = {}
): DisputeStatus {
  return merge(DISPUTE_NEXT, current, incoming);
}

export interface RefundTotals {
  /** Sum of succeeded refunds — THE refunded total. Never an increment (bugs B1/B2). */
  readonly succeeded: number;
  /** Reserved + unknown + pending: money promised back but not yet confirmed. */
  readonly held: number;
}

/** Derived refund totals over one payment's refund rows. */
export function refundTotals(
  { refunds }: { refunds: readonly { readonly status: RefundStatus; readonly amountMinor: number }[] },
  _optional: Record<string, never> = {}
): RefundTotals {
  let succeeded = 0;
  let held = 0;
  for (const refund of refunds) {
    if (refund.status === "succeeded") succeeded += refund.amountMinor;
    else if (refund.status !== "failed") held += refund.amountMinor;
  }
  return { succeeded, held };
}

/** Money currently withdrawn by disputes: open and lost ones. A won dispute returns its amount. */
export function disputedMinor(
  { disputes }: { disputes: readonly { readonly status: DisputeStatus; readonly amountMinor: number }[] },
  _optional: Record<string, never> = {}
): number {
  return disputes.reduce((sum, dispute) => (dispute.status === "won" ? sum : sum + dispute.amountMinor), 0);
}

/**
 * The payment's status, derived. Refunds only shape a SUCCEEDED intent; any other intent status
 * is reported as is. `capturedMinor` is the refund base, not the requested amount, so a partial
 * capture refunded in full reads `refunded`.
 */
export function derivePaymentStatus(
  { intent, capturedMinor, refundedMinor }: { intent: IntentStatus; capturedMinor: number; refundedMinor: number },
  _optional: Record<string, never> = {}
): DerivedPaymentStatus {
  if (intent !== "succeeded" || refundedMinor <= 0) return intent;
  return refundedMinor >= capturedMinor ? "refunded" : "partially_refunded";
}

/** What may still be refunded: captured − succeeded − held. Never negative. */
export function refundableMinor(
  { capturedMinor, totals }: { capturedMinor: number; totals: RefundTotals },
  _optional: Record<string, never> = {}
): number {
  return Math.max(0, capturedMinor - totals.succeeded - totals.held);
}

/**
 * @file A deterministic LiPay FAKE on the new provider contract: an in-memory LiPay "server" plus a
 * `PaymentProvider` that talks to it. LiPay has no live API (design: "LiPay stays a contract-tested
 * fake until its real API exists"), so this is where the kernel's race and property tests get a
 * provider whose timing they control: the test decides whether a call answers, times out (money
 * moved, outcome `unknown`) or is rejected, and when each webhook is delivered.
 *
 * It reuses LiPay's real webhook signing (`signLipayWebhook`: timestamped HMAC-SHA256 over the
 * exact bytes, header `x-lipay-signature`), so `verifyWebhook` exercises a real signature check.
 * The payload shapes are this fake's own; LiPay's real ones do not exist yet.
 */
import { timingSafeEqual } from "node:crypto";
import type { HttpClientPort } from "@jini-ai/core/primitives";
import type { Money } from "../../money/money.js";
import type { PaymentEvidence, RefundEvidence, WebhookFact } from "../contract/evidence.js";
import { paymentError, type Outcome, type PaymentProvider, type ProviderContext } from "../contract/provider.js";
import { signLipayWebhook } from "../providers/lipay-gateway.js";

/** What the next call of an operation does. `timeout` = the server ACTS but the caller never hears back. */
export type FakeBehaviour = "ok" | "timeout" | "reject";

interface FakeRefund { id: string; chargeId: string; amount: Money; status: "pending" | "succeeded" | "failed"; correlationId: string }
interface FakeCharge { id: string; amount: Money; status: PaymentEvidence["status"]; correlationId: string }

export interface LipayFakeServer {
  /** Queue behaviours for the next calls of an operation (default `ok`). */
  script(required: { op: "createIntent" | "refund"; behaviours: readonly FakeBehaviour[] }, optional?: Record<string, never>): void;
  /** Move a refund to a new status at the "provider" (e.g. pending → succeeded, succeeded → failed). */
  settleRefund(required: { refundId: string; status: FakeRefund["status"] }, optional?: Record<string, never>): void;
  /** A signed webhook delivery for a refund (`refund.updated`) or the charge with all its refunds (`charge.refunded`). */
  webhook(
    required: { type: "refund.updated" | "charge.refunded" | "charge.succeeded"; id: string; eventId: string },
    optional?: { echoCorrelation?: boolean }
  ): { rawBody: Uint8Array; headers: Record<string, string> };
  /** Snapshot of a refund as the provider holds it. */
  refundOf(required: { refundId: string }, optional?: Record<string, never>): Readonly<FakeRefund> | undefined;
}

export const LIPAY_FAKE_SECRET = "whsec_lipay_fake";
const HEADER = "x-lipay-signature";

function nextBehaviour(queue: FakeBehaviour[]): FakeBehaviour {
  return queue.shift() ?? "ok";
}

function refundEvidence(refund: FakeRefund, echo: boolean): RefundEvidence {
  return { providerRefundRef: refund.id, amount: refund.amount, status: refund.status, ...(echo ? { correlationId: refund.correlationId } : {}) };
}

function verify(required: { rawBody: Uint8Array; header: string | undefined; secret: string | undefined; nowMs: number }): boolean {
  const match = /^t=(\d+),v1=([0-9a-f]{64})$/.exec(required.header ?? "");
  if (!match || !required.secret) return false;
  const expected = signLipayWebhook({ secret: required.secret, rawBody: Buffer.from(required.rawBody), timestampSeconds: Number(match[1]) });
  const ok = timingSafeEqual(Buffer.from(expected), Buffer.from(`t=${match[1]},v1=${match[2]}`));
  return ok && Math.abs(required.nowMs - Number(match[1]) * 1000) <= 300_000;
}

const unknown = () => ({ kind: "unknown" as const, error: paymentError({ code: "TRANSPORT_ERROR", message: "lipay fake: timed out" }, { retryable: true }) });
const rejected = (message: string) => ({ kind: "rejected" as const, error: paymentError({ code: "DECLINED", message }) });

/** Builds the fake server and its provider. `now` is the test's clock (epoch ms). */
export function createLipayFake(
  { now }: { now: () => number },
  optional: { echoesCorrelation?: boolean } = {}
): { server: LipayFakeServer; provider: PaymentProvider } {
  const echo = optional.echoesCorrelation ?? true;
  const charges = new Map<string, FakeCharge>();
  const refunds = new Map<string, FakeRefund>();
  const scripts: Record<"createIntent" | "refund", FakeBehaviour[]> = { createIntent: [], refund: [] };
  let seq = 0;

  const chargeEvidence = (charge: FakeCharge, withEcho: boolean): PaymentEvidence => ({
    providerRef: charge.id, status: charge.status, amount: charge.amount,
    ...(withEcho ? { correlationId: charge.correlationId } : {}),
    refunds: [...refunds.values()].filter((r) => r.chargeId === charge.id).map((r) => refundEvidence(r, withEcho)),
    disputes: [],
  });

  const factFor = (body: { type: string; id: string; eventId: string; echo: boolean }): WebhookFact => {
    const refund = refunds.get(body.id);
    const charge = charges.get(refund?.chargeId ?? body.id) as FakeCharge;
    const evidence = chargeEvidence(charge, body.echo);
    const only = body.type === "refund.updated" && refund ? { ...evidence, refunds: [refundEvidence(refund, body.echo)] } : evidence;
    return { providerEventId: body.eventId, providerRef: charge.id, evidence: only };
  };

  const server: LipayFakeServer = {
    script: ({ op, behaviours }) => { scripts[op].push(...behaviours); },
    settleRefund: ({ refundId, status }) => { (refunds.get(refundId) as FakeRefund).status = status; },
    refundOf: ({ refundId }) => refunds.get(refundId),
    webhook: ({ type, id, eventId }, o = {}) => {
      const rawBody = Buffer.from(JSON.stringify({ type, id, eventId, echo: o.echoCorrelation ?? echo }));
      return { rawBody, headers: { [HEADER]: signLipayWebhook({ secret: LIPAY_FAKE_SECRET, rawBody, timestampSeconds: Math.floor(now() / 1000) }) } };
    },
  };

  const provider: PaymentProvider = {
    id: "lipay",
    displayName: "LiPay (fake)",
    credentialKeys: ["webhookSecret"],
    capabilities: {
      refunds: "partial", capture: "auto", void: false, disputes: false, retrieve: "payment+refunds",
      echoesCorrelation: echo, confirmation: ["none"], currencies: "any",
    },
    createIntent: async ({ req }) => {
      const behaviour = nextBehaviour(scripts.createIntent);
      if (behaviour === "reject") return rejected("card_declined");
      const charge: FakeCharge = { id: `ch_${++seq}`, amount: req.amount, status: "succeeded", correlationId: req.correlationId };
      charges.set(charge.id, charge);
      if (behaviour === "timeout") return unknown();
      return { kind: "ok", value: { evidence: chargeEvidence(charge, echo), next: { kind: "none" } } };
    },
    refund: async ({ req }) => {
      const behaviour = nextBehaviour(scripts.refund);
      if (behaviour === "reject") return rejected("refund refused");
      const refund: FakeRefund = { id: `re_${++seq}`, chargeId: req.providerRef, amount: req.amount, status: "pending", correlationId: req.correlationId };
      refunds.set(refund.id, refund);
      return behaviour === "timeout" ? unknown() : { kind: "ok", value: refundEvidence(refund, echo) };
    },
    retrieve: async ({ providerRef }): Promise<Outcome<PaymentEvidence>> => {
      const charge = charges.get(providerRef);
      return charge ? { kind: "ok", value: chargeEvidence(charge, echo) } : rejected(`no charge ${providerRef}`);
    },
    verifyWebhook: async ({ rawBody, headers, ctx }: { rawBody: Uint8Array; headers: Readonly<Record<string, string>>; ctx: ProviderContext }) => {
      if (!verify({ rawBody, header: headers[HEADER], secret: ctx.credentials.webhookSecret, nowMs: ctx.now() })) {
        return { kind: "rejected", error: paymentError({ code: "SIGNATURE_INVALID", message: "lipay fake: bad signature" }) };
      }
      const body = JSON.parse(Buffer.from(rawBody).toString("utf8")) as { type: string; id: string; eventId: string; echo: boolean };
      return { kind: "ok", value: [factFor(body)] };
    },
  };
  return { server, provider };
}

/** A `ProviderContext` for the fake: the fake secret and a test clock. The fake makes no HTTP calls, so the port is empty. */
export function lipayFakeContext({ now }: { now: () => number }, _optional: Record<string, never> = {}): ProviderContext {
  const httpClient = {} as HttpClientPort;
  return {
    credentials: { webhookSecret: LIPAY_FAKE_SECRET }, account: { providerAccountId: "acct_fake", mode: "test" },
    httpClient, now, webhookUrl: "https://example.test/payments/webhook/site/lipay", returnUrl: "https://example.test/return",
  };
}

/**
 * @file The model-facing catalog of the payments agent tools (lot L7) and this layer's own risk
 * classification of them.
 *
 * Two read tools (a payment's view, the registered providers) and three money-moving tools
 * (`refund`, `capture`, `void`). The money tools carry `confirmer-must-equal-own-delegatedBy`, so
 * the registration kit refuses to wire them unless their handler asks a human through the host's
 * confirmation transport; nothing in a tool input can approve a money movement.
 *
 * Every schema is strict (`additionalProperties: false`): a field the model invents is refused, not
 * ignored, so it can never believe an option it made up was applied.
 */
import type { AgentToolDefinition, AgentToolSideEffect } from "@jini-ai/core";

export const PAYMENTS_TOOLS_DOMAIN = "commerce-payments";
export const PAYMENTS_TOOLS_CATALOG_MODULE = "packages/commerce/src/payments/tools/catalog.ts";

export const PAYMENTS_TOOL_IDS = {
  get: "commerce_payments_get",
  listProviders: "commerce_payments_list_providers",
  refund: "commerce_payments_refund",
  capture: "commerce_payments_capture",
  void: "commerce_payments_void",
} as const;

/** The two permissions the tools check; a host maps them onto its own role model. */
export interface PaymentsToolPermissions {
  /** Read a payment or the provider list. */
  readonly read: string;
  /** Refund, capture or void (each still needs a human yes). */
  readonly manage: string;
}

export const DEFAULT_PAYMENTS_TOOL_PERMISSIONS: PaymentsToolPermissions = {
  read: "commerce.payments.read",
  manage: "commerce.payments.manage",
};

/** Upper bounds the handlers enforce too (`input.ts`); the schema only advises the model. */
export const MAX_ID_LENGTH = 200;
export const MAX_REASON_LENGTH = 500;

const PAYMENT_ID = { type: "string", minLength: 1, maxLength: MAX_ID_LENGTH, description: "The payment id, as commerce_payments_get returns it." } as const;
const AMOUNT = {
  type: "object",
  additionalProperties: false,
  required: ["minorUnits", "currency"],
  description: "The exact amount, in the payment's currency.",
  properties: {
    minorUnits: { type: "integer", minimum: 1, maximum: Number.MAX_SAFE_INTEGER, description: "Whole minor units (cents for USD, yen for JPY). Never a decimal." },
    currency: { type: "string", pattern: "^[A-Z]{3}$", description: "Uppercase ISO-4217 code, e.g. USD." },
  },
} as const;
const IDEMPOTENCY_KEY = {
  type: "string", minLength: 1, maxLength: MAX_ID_LENGTH,
  description: "Optional. Pass the key an earlier call returned to retry that exact request safely; omit it for a new request and one is generated.",
} as const;
const REASON = { type: "string", minLength: 1, maxLength: MAX_REASON_LENGTH, description: "Optional note recorded with the refund." } as const;

function strict(properties: Readonly<Record<string, unknown>>, required: readonly string[]): Readonly<Record<string, unknown>> {
  return { type: "object", additionalProperties: false, required, properties };
}

const APPROVAL = "Shows the human a confirmation card naming the payment, amount, mode (live/test) and idempotency key; nothing happens unless they confirm. Returns {ok:false, reason} when refused, declined, expired or abandoned.";

/**
 * Builds the catalog with the host's permission names.
 * @param optional.permissions - Permission names; defaults to {@link DEFAULT_PAYMENTS_TOOL_PERMISSIONS}.
 * @returns Five definitions with fixed ids, schemas and risk.
 * @example paymentsToolCatalog({}, { permissions: { read: "shop.read", manage: "shop.money" } });
 */
export function paymentsToolCatalog(
  _required: Record<string, never> = {},
  { permissions = DEFAULT_PAYMENTS_TOOL_PERMISSIONS }: { permissions?: PaymentsToolPermissions } = {}
): AgentToolDefinition[] {
  const read = { permission: permissions.read };
  const manage = { permission: permissions.manage };
  const human = "confirmer-must-equal-own-delegatedBy" as const;
  return [
    {
      name: PAYMENTS_TOOL_IDS.get,
      description: "Reads one payment of the run's payment account: status, amount, captured, refunded, held and disputed money, reference and any next action. Read-only.",
      sideEffects: "none", authorization: read, inputSchema: strict({ paymentId: PAYMENT_ID }, ["paymentId"]),
    },
    {
      name: PAYMENTS_TOOL_IDS.listProviders,
      description: "Lists the registered payment providers and what each supports (refunds none/full/partial, capture auto/manual). Read-only; says nothing about credentials.",
      sideEffects: "none", authorization: read, inputSchema: strict({}, []),
    },
    {
      name: PAYMENTS_TOOL_IDS.refund,
      description: `Refunds money from a succeeded payment back to the payer. Irreversible. ${APPROVAL}`,
      sideEffects: "mutates-durable-state", authorization: manage, actorClassRule: human,
      inputSchema: strict({ paymentId: PAYMENT_ID, amount: AMOUNT, reason: REASON, idempotencyKey: IDEMPOTENCY_KEY }, ["paymentId", "amount"]),
    },
    {
      name: PAYMENTS_TOOL_IDS.capture,
      description: `Captures (collects) an authorized manual-capture payment, up to the authorized amount. Irreversible. ${APPROVAL}`,
      sideEffects: "mutates-durable-state", authorization: manage, actorClassRule: human,
      inputSchema: strict({ paymentId: PAYMENT_ID, amount: AMOUNT, idempotencyKey: IDEMPOTENCY_KEY }, ["paymentId", "amount"]),
    },
    {
      name: PAYMENTS_TOOL_IDS.void,
      description: `Voids (releases) an uncaptured authorization so the payer is never charged. Irreversible. ${APPROVAL}`,
      sideEffects: "mutates-durable-state", authorization: manage, actorClassRule: human,
      inputSchema: strict({ paymentId: PAYMENT_ID, idempotencyKey: IDEMPOTENCY_KEY }, ["paymentId"]),
    },
  ];
}

/**
 * Independently derived from what each handler calls (`read-tools.ts`, `money-tools.ts`).
 *
 * Core's side-effect vocabulary has no money member, so a money movement is classified as the
 * strongest fitting one, `mutates-durable-state` (it writes ledger rows and moves money at the
 * provider). Its irreversibility is carried by the human-confirmation rule and by the approval
 * plan never offering a remembered grant, not by this word.
 */
// Spell out the readonly map because the guard cannot resolve the registration kit's type alias.
export const paymentsToolsDerivedRisk: ReadonlyMap<string, AgentToolSideEffect> = new Map([
  // PaymentsPort.getPayment: one ledger read.
  [PAYMENTS_TOOL_IDS.get, "none"],
  // PaymentsPort.listProviders: the in-memory provider registry.
  [PAYMENTS_TOOL_IDS.listProviders, "none"],
  // MoneyGrantPort.mint + PaymentsPort.refund / capture / void: ledger writes and a provider call.
  [PAYMENTS_TOOL_IDS.refund, "mutates-durable-state"],
  [PAYMENTS_TOOL_IDS.capture, "mutates-durable-state"],
  [PAYMENTS_TOOL_IDS.void, "mutates-durable-state"],
]);

/**
 * @file The three money-moving tools (`commerce_payments_refund`, `_capture`, `_void`), each built on
 * core's `createApprovalHandler`:
 *
 *   prepare  — strict input, the run's scope (never input), the manage permission, the payment as
 *              the ledger has it, and the idempotency key, fixed ONCE here so the request the human
 *              approves and the effect that runs share it;
 *   describe — always asks; names the exact payment, reference, amount, operation, live/test mode
 *              and key. No `rememberKey`: a money movement is irreversible, so a yes is never
 *              remembered and every call needs its own;
 *   run      — only after an explicit human yes: the permission again (it may have been revoked
 *              while the card was open), then `grants.mint` bound to exactly op + workspace + mode +
 *              payment + amount + key, then the `PaymentsPort` call with that grant and the same
 *              values.
 *
 * The tool is not the enforcement point. The payments service redeems the grant itself, against the
 * binding it derives from its OWN arguments, so a tool that minted for one amount and asked for
 * another, or presented a grant twice, is refused there (design item 8: double enforcement).
 *
 * A declined, expired or abandoned approval, or an abort at any point before the call, mints
 * nothing and moves nothing.
 */
import { createApprovalHandler, type ApprovalSteps, type ToolExecutionContext, type ToolHandler } from "@jini-ai/core";
import { toMajorString, type Money } from "../../money/money.js";
import type { IntentResult, PaymentView, RefundView } from "../contract/payments-port.js";
import type { PaymentError } from "../contract/provider.js";
import type { PaymentScope } from "../contract/scope.js";
import type { MoneyGrantBinding } from "../ops/grants.js";
import { MAX_REASON_LENGTH, PAYMENTS_TOOL_IDS } from "./catalog.js";
import {
  NO_SCOPE, paymentNotFound, requirePaymentsPermission, type PaymentApprovalDescription, type PaymentsToolRefusal, type ToolsDeps,
} from "./deps.js";
import { optionalText, readAmount, requiredText, strictInput } from "./input.js";

type MoneyOp = MoneyGrantBinding["op"];

export type MoneyToolResult =
  | { readonly ok: true; readonly operation: MoneyOp; readonly replayed: boolean; readonly idempotencyKey: string; readonly payment: PaymentView; readonly refund?: RefundView }
  | { readonly ok: false; readonly reason: "payment-error"; readonly error: PaymentError; readonly idempotencyKey: string; readonly message: string; readonly payment?: PaymentView }
  | { readonly ok: false; readonly reason: "declined" | "expired" | "abandoned"; readonly message: string }
  | PaymentsToolRefusal;

/** Everything the effect uses, fixed in `prepare` and shown to the human in `describe`. */
interface Ready {
  readonly kind: "ready";
  readonly scope: PaymentScope;
  readonly payment: PaymentView;
  /** Non-null exactly for the ops whose spec has an amount (refund, capture). */
  readonly amount: Money | null;
  readonly idempotencyKey: string;
  readonly reason: string | undefined;
}
type Prepared = Ready | { readonly kind: "refused"; readonly result: PaymentsToolRefusal };

interface Effect extends Ready {
  readonly grant: string;
}

interface OpSpec {
  readonly op: MoneyOp;
  readonly toolId: string;
  readonly fields: readonly string[];
  readonly hasAmount: boolean;
  readonly headline: (shown: { amount: string | null; paymentAmount: string; paymentId: string }) => string;
  readonly call: (required: { deps: ToolsDeps; effect: Effect }) => Promise<MoneyToolResult>;
}

const display = (money: Money): string => `${money.currency} ${toMajorString({ money })}`;

function failure(
  { op, error, idempotencyKey }: { op: MoneyOp; error: PaymentError; idempotencyKey: string },
  { payment }: { payment?: PaymentView | undefined } = {}
): MoneyToolResult {
  // `retryable` = a retry under the SAME key may succeed; otherwise it can only return this answer again (C-1).
  const retry = error.retryable ? "Retrying with the same idempotencyKey is safe." : "Retrying with the same idempotencyKey returns this same result.";
  const message = `the ${op} did not complete (${error.code}): ${error.message}. ${retry}`;
  return { ok: false, reason: "payment-error", error, idempotencyKey, message, ...(payment ? { payment } : {}) };
}

function fromIntent({ op, result, idempotencyKey }: { op: MoneyOp; result: IntentResult; idempotencyKey: string }): MoneyToolResult {
  if (!result.ok) return failure({ op, error: result.error, idempotencyKey }, { payment: result.payment });
  return { ok: true, operation: op, replayed: result.replayed, idempotencyKey, payment: result.payment };
}

// `effect.amount as Money` below: refund and capture specs have `hasAmount`, so `prepare` read a
// non-null amount for them (`readRequest`).
const SPECS: readonly OpSpec[] = [
  {
    op: "refund", toolId: PAYMENTS_TOOL_IDS.refund, fields: ["paymentId", "amount", "reason", "idempotencyKey"], hasAmount: true,
    headline: ({ amount, paymentId }) => `refund ${amount} of payment ${paymentId}`,
    call: async ({ deps, effect: { scope, payment, amount, idempotencyKey, grant, reason } }) => {
      const result = await deps.payments.refund(
        { scope, paymentId: payment.id, amount: amount as Money, idempotencyKey, grant }, reason === undefined ? {} : { reason }
      );
      if (!result.ok) return failure({ op: "refund", error: result.error, idempotencyKey });
      return { ok: true, operation: "refund", replayed: result.replayed, idempotencyKey, payment: result.payment, refund: result.refund };
    },
  },
  {
    op: "capture", toolId: PAYMENTS_TOOL_IDS.capture, fields: ["paymentId", "amount", "idempotencyKey"], hasAmount: true,
    headline: ({ amount, paymentId }) => `capture ${amount} of payment ${paymentId}`,
    call: async ({ deps, effect: { scope, payment, amount, idempotencyKey, grant } }) => fromIntent({
      op: "capture", idempotencyKey, result: await deps.payments.capture({ scope, paymentId: payment.id, amount: amount as Money, idempotencyKey, grant }),
    }),
  },
  {
    op: "void", toolId: PAYMENTS_TOOL_IDS.void, fields: ["paymentId", "idempotencyKey"], hasAmount: false,
    headline: ({ paymentAmount, paymentId }) => `void the uncaptured authorization (${paymentAmount}) of payment ${paymentId}`,
    call: async ({ deps, effect: { scope, payment, idempotencyKey, grant } }) => fromIntent({
      op: "void", idempotencyKey, result: await deps.payments.void({ scope, paymentId: payment.id, idempotencyKey, grant }),
    }),
  },
];

function notConfirmed(reason: "declined" | "expired" | "abandoned"): MoneyToolResult {
  return { ok: false, reason, message: `the human did not confirm (${reason}); no money moved and no grant was issued` };
}

function readRequest({ spec, input }: { spec: OpSpec; input: unknown }) {
  const record = strictInput({ input, allowed: spec.fields });
  return {
    paymentId: requiredText({ input: record, key: "paymentId" }),
    amount: spec.hasAmount ? readAmount({ input: record }) : null,
    idempotencyKey: optionalText({ input: record, key: "idempotencyKey" }),
    // Absent for capture/void: `strictInput` refused the field there.
    reason: optionalText({ input: record, key: "reason" }, { max: MAX_REASON_LENGTH }),
  };
}

async function prepareOp({ deps, spec, ctx }: { deps: ToolsDeps; spec: OpSpec; ctx: ToolExecutionContext }): Promise<Prepared> {
  const request = readRequest({ spec, input: ctx.input });
  const scope = await deps.scopeFor({ ctx });
  if (!scope) return { kind: "refused", result: NO_SCOPE };
  await requirePaymentsPermission({ deps, ctx, scope, permission: deps.permissions.manage }, { paymentId: request.paymentId });
  const payment = await deps.payments.getPayment({ scope, paymentId: request.paymentId });
  if (!payment) return { kind: "refused", result: paymentNotFound(request.paymentId) };
  if (request.amount && request.amount.currency !== payment.amount.currency) {
    const message = `the ${spec.op} is in ${request.amount.currency} but payment '${payment.id}' is in ${payment.amount.currency}; nothing was changed`;
    return { kind: "refused", result: { ok: false, reason: "currency-mismatch", message } };
  }
  const idempotencyKey = request.idempotencyKey ?? deps.newIdempotencyKey();
  return { kind: "ready", scope, payment, amount: request.amount, idempotencyKey, reason: request.reason };
}

function describeOp({ spec, ready }: { spec: OpSpec; ready: Ready }): PaymentApprovalDescription {
  const { scope, payment, amount, idempotencyKey } = ready;
  const live = scope.mode === "live";
  const amountDisplay = amount ? display(amount) : null;
  const paymentAmountDisplay = display(payment.amount);
  const reason = ready.reason ?? null;
  const headline = spec.headline({ amount: amountDisplay, paymentAmount: paymentAmountDisplay, paymentId: payment.id });
  const summary = `${live ? "LIVE MODE (real money)" : "Test mode"}: ${headline} (reference ${payment.reference}, provider ${scope.providerId}). `
    + `Idempotency key ${idempotencyKey}.${reason === null ? "" : ` Reason: ${reason}.`} This cannot be undone.`;
  return {
    toolId: spec.toolId, operation: spec.op, mode: scope.mode, live, paymentId: payment.id, reference: payment.reference,
    providerId: scope.providerId, amount, amountDisplay, paymentAmount: payment.amount, paymentAmountDisplay, idempotencyKey,
    reason, irreversible: true, summary,
  };
}

async function runOp({ deps, spec, ctx, prepared }: { deps: ToolsDeps; spec: OpSpec; ctx: ToolExecutionContext; prepared: Prepared }): Promise<MoneyToolResult> {
  if (prepared.kind === "refused") return prepared.result;
  const { scope, payment, amount, idempotencyKey } = prepared;
  // Fresh, after the human wait: a permission revoked while the card was open stops the effect.
  await requirePaymentsPermission({ deps, ctx, scope, permission: deps.permissions.manage }, { paymentId: payment.id });
  if (ctx.signal.aborted) return notConfirmed("abandoned");
  const binding: MoneyGrantBinding = { op: spec.op, workspaceId: scope.workspaceId, mode: scope.mode, paymentId: payment.id, amount, idempotencyKey };
  const grant = await deps.grants.mint({ binding, expiresAt: deps.now() + deps.grantTtlMs });
  // Aborted while minting: the grant is never presented and lapses at its expiry.
  if (ctx.signal.aborted) return notConfirmed("abandoned");
  return spec.call({ deps, effect: { ...prepared, grant } });
}

function stepsFor({ deps, spec }: { deps: ToolsDeps; spec: OpSpec }): ApprovalSteps<Prepared, PaymentApprovalDescription | null> {
  return {
    prepare: ({ ctx }) => prepareOp({ deps, spec, ctx }),
    // A refusal asks nobody; `run` returns it. No `rememberKey` on purpose (see the file comment).
    describe: ({ prepared }) => (prepared.kind === "ready" ? { ask: true, description: describeOp({ spec, ready: prepared }) } : { ask: false, description: null }),
    // Core calls askHuman only for a plan with `ask: true`, which `describe` builds only with a description.
    askHuman: ({ ctx, description }, options) => deps.askHuman({ ctx, description: description as PaymentApprovalDescription }, options),
    run: ({ ctx, prepared }) => runOp({ deps, spec, ctx, prepared }),
    notConfirmed: ({ reason }) => notConfirmed(reason),
  };
}

/** The three approval-gated handlers, keyed by tool id. Each is built once, with no remembered-grant store. */
export function moneyToolHandlers({ deps }: { deps: ToolsDeps }, _optional: Record<string, never> = {}): Record<string, ToolHandler> {
  return Object.fromEntries(SPECS.map((spec) => [spec.toolId, createApprovalHandler(stepsFor({ deps, spec }))]));
}

/** @file DOM helpers for the browser client: cookies, storage purge, inert tags and the Jini banner binding.
 * The Jini banner is a client of the public API, exactly like an owner's own ("My own") banner. */
import { OPEN_EVENT, OPTIONAL, type Choices, type ConsentAction, type ConsentState, type Flags, type JiniConsentApi, type Optional, type StoragePrefixes } from '../contract.js';

const INERT = 'script[type="text/plain"][data-consent-category],iframe[data-consent-category][data-src]';
const SKIP: ReadonlySet<string> = new Set(['type', 'data-src', 'data-type', 'data-consent-category']);
// Not <html>: the client sets html[data-consent-open] while the banner shows, and every click's closest() would hit it.
const OPENERS = ':not(html)[data-consent-open],a[href="#privacy-choices"]';

/** @complexity O(cookie header). Malformed escapes read as "no value", never throw. */
export function readCookie(doc: Document, name: string): string | null {
  const part = doc.cookie.split(/;\s*/).find(p => p.startsWith(name + '='));
  try { return part ? decodeURIComponent(part.slice(name.length + 1)) : null; } catch { return null; }
}

export function writeCookie(doc: Document, { name, value, maxAgeS }: { name: string; value: string; maxAgeS: number }, { domain }: { domain?: string | undefined } = {}): void {
  const secure = doc.defaultView?.location.protocol === 'https:' ? '; Secure' : '';
  doc.cookie = `${name}=${encodeURIComponent(value)}; Path=/; Max-Age=${Math.floor(maxAgeS)}; SameSite=Lax${secure}${domain ? `; Domain=${domain}` : ''}`;
}

/** Vendors set cookies on the registrable domain, so expire on the host and each parent domain. */
function expireEverywhere(doc: Document, name: string): void {
  const parts = (doc.defaultView?.location.hostname ?? '').split('.');
  doc.cookie = `${name}=; Path=/; Max-Age=0`;
  for (let i = 0; i < parts.length - 1; i++) doc.cookie = `${name}=; Path=/; Max-Age=0; Domain=.${parts.slice(i).join('.')}`;
}

/** Expire prefixed cookies and local-storage keys; storage access can throw in sandboxes. @complexity O(cookies + keys). */
export function purge(doc: Document, storage?: StoragePrefixes): void {
  if (!storage) return;
  for (const part of doc.cookie.split(/;\s*/)) {
    const name = part.split('=')[0]!;
    if (storage.cookies?.some(p => name.startsWith(p))) expireEverywhere(doc, name);
  }
  try {
    const local = doc.defaultView!.localStorage;
    for (const key of Object.keys(local)) if (storage.local?.some(p => key.startsWith(p))) local.removeItem(key);
  } catch { /* no storage: nothing to purge */ }
}

// MOVED-FROM: @jini-ai/cms consent/html/client.ts template release (ordered, each template consumed once).
// TODO(P4): delete the cms runtime once the consumer inserts this client.
/** Allowed inert tags become live, in authored order (async=false). Unknown labels stay inert.
 * @complexity O(inert tags). */
export function activateInert(doc: Document, { allowed, ran }: { allowed: Choices; ran: Set<Optional> }): void {
  doc.querySelectorAll<HTMLElement>(INERT).forEach(node => {
    const category = node.dataset.consentCategory as Optional;
    if (!OPTIONAL.includes(category) || !allowed[category]) return;
    ran.add(category);
    if (node.tagName === 'IFRAME') { node.setAttribute('src', node.dataset.src!); node.removeAttribute('data-src'); return; }
    node.replaceWith(liveScript(doc, node as HTMLScriptElement));
  });
}

function liveScript(doc: Document, inert: HTMLScriptElement): HTMLScriptElement {
  const s = doc.createElement('script');
  for (const { name, value } of Array.from(inert.attributes)) if (!SKIP.has(name)) s.setAttribute(name, value);
  if (inert.nonce) s.nonce = inert.nonce;              // owner-set CSPs keep working
  if (inert.dataset.type) s.type = inert.dataset.type;
  if (inert.dataset.src) s.src = inert.dataset.src; else s.text = inert.text;
  s.async = false;
  return s;
}

/** Footer links and the reopen button work for every banner mode, including "My own". */
export function installOpeners({ api, doc }: { api: JiniConsentApi; doc: Document }): void {
  doc.addEventListener('click', event => {
    if (!(event.target as Element).closest?.(OPENERS)) return;
    event.preventDefault();
    api.open();
  });
}

function readPicked(root: HTMLElement): Partial<Flags> {
  const picked: Partial<Flags> = {};
  for (const c of OPTIONAL) {
    const box = root.querySelector<HTMLInputElement>(`input[name="${c}"]`);
    if (box) picked[c] = box.checked;
  }
  return picked;
}

function syncInputs(root: HTMLElement, s: ConsentState): void {
  for (const c of OPTIONAL) {
    const box = root.querySelector<HTMLInputElement>(`input[name="${c}"]`);
    if (!box) continue;
    box.checked = s.choices[c];
    box.disabled = s.gpc && c !== 'functional';        // GPC-clamped categories cannot be ticked
  }
}

/** A durable grant that is still waiting for its receipt keeps the banner open with its alert. */
export const waiting = (s: ConsentState) => OPTIONAL.some(c => s.choices[c] && !s.allowed[c]);

/** Wire #jini-consent (renderBanner's markup) to the public API. @complexity O(1) per click. */
export function bindBanner({ api, doc }: { api: JiniConsentApi; doc: Document }): void {
  const root = doc.getElementById('jini-consent');
  if (!root) return;
  const alert = root.querySelector<HTMLElement>('[data-consent-error]');
  const show = (open: boolean) => { root.hidden = !open; api.setOpen({ open }); };
  const settle = (s: ConsentState) => {
    if (alert) alert.hidden = !waiting(s);
    if (!waiting(s)) show(false);
  };
  root.addEventListener('click', event => {
    const action = (event.target as Element).closest?.('[data-consent-action]')?.getAttribute('data-consent-action');
    if (!action) return;
    event.preventDefault();
    void api.set({ action: action as ConsentAction }, { choices: readPicked(root) }).then(settle);
  });
  root.addEventListener('keydown', event => { if (event.key === 'Escape' && api.get().status === 'set') show(false); });
  doc.addEventListener(OPEN_EVENT, () => { syncInputs(root, api.get()); show(true); root.querySelector('button')?.focus(); });
  api.subscribe({ listener: s => { syncInputs(root, s); if (alert && !alert.hidden && !waiting(s)) settle(s); } });
  syncInputs(root, api.get());
  show(api.get().status === 'pending');
}

/** @file Browser runtime (dist/client.min.js). It owns the cookie, the adapter lifecycle, inert tags and
 * receipts. Denial is applied before any network; a durable grant runs only once its receipt exists; a
 * response never sets a cookie, so a slow Accept can't overwrite a newer Reject. No polling, and no reload
 * unless something already ran that cannot be stopped (a raw inert script, or an adapter that can't revoke). */
import { ADAPTER_KIND, CONFIG_ID, CONSENT_COOKIE, OPEN_EVENT, OPTIONAL, READY_EVENT, REGION_COOKIE, STATE_EVENT,
  type AdapterContribution, type ClientConfig, type ConsentAction, type ConsentAdapter, type ConsentState, type Contribution,
  type Evidence, type Flags, type JiniConsentApi, type LazyAdapter, type Optional, type PageConfig, type PluginRegistry,
  type RawContribution, type Revoker, type StoragePrefixes, type StoredChoice } from '../contract.js';
import { choicesFor, DAY_MS, effective, parseStored, RECEIPT_ID, regionFrom } from '../contracts/policy.js';
import { ADAPTER_SLOT, createPluginRegistry } from '../contracts/plugins.js';
import { activateInert, installOpeners, purge, readCookie, waiting, writeCookie } from './dom.js';

export interface ClientPorts {
  doc: Document; fetch: typeof fetch; now: () => number; gpc: () => boolean; reload: () => void;
  importModule: (src: string) => Promise<{ default: ConsentAdapter }>;
}
export interface ClientOptions { plugins?: PluginRegistry; evidence?: Evidence | undefined }
type Run = { ctl: AbortController; result: Promise<Revoker | null> };
type Slot = { entry: AdapterContribution; generation: number; adapter?: ConsentAdapter | undefined; run?: Run | undefined };
const within = (p: Promise<unknown>, ms: number) => Promise.race([p, new Promise(r => setTimeout(r, ms))]);
const quiet = (fn: () => void) => { try { fn(); } catch { /* a broken plugin or listener never blocks consent */ } };

/** @example createCookieConsent({ config, ports: browserPorts(window) }, { evidence: { mode: 'local' } }) */
export function createCookieConsent({ config, ports }: { config: ClientConfig; ports: ClientPorts }, options: ClientOptions = {}): JiniConsentApi {
  const { doc } = ports;
  const plugins = options.plugins ?? createPluginRegistry({}, { slots: [ADAPTER_SLOT] });
  const durable = durableEvidence(options);
  const slots = new Map<string, Slot>();
  const listeners = new Set<(s: ConsentState) => void>();
  const ran = new Set<Optional>();                                    // categories whose raw inert tags executed
  const anonymous = config.banner === 'off';
  const maxAgeMs = (config.maxAgeDays ?? 180) * DAY_MS;
  const region = regionFrom({ configured: config.regionMode, hint: anonymous ? null : readCookie(doc, REGION_COOKIE) });
  const fromCookie = () => anonymous ? null : parseStored({ raw: readCookie(doc, CONSENT_COOKIE) });
  let stored = fromCookie();
  let cookiePersisted = true;
  let state = compute();

  function compute(): ConsentState {
    return effective({ stored, policy: config.policy, region, gpc: ports.gpc(), nowMs: ports.now() }, { maxAgeMs, durable: !!durable, anonymous });
  }
  function persist(): void {
    const value = JSON.stringify(stored);
    writeCookie(doc, { name: CONSENT_COOKIE, value, maxAgeS: maxAgeMs / 1000 }, { domain: config.cookieDomain });
    cookiePersisted = readCookie(doc, CONSENT_COOKIE) === value;
  }

  /** Off-mode adapters load for identity cleanup even at none; only permitted levels grant.
   * Abort is checked after the import and handed to grant(), so a withdrawal during either wait wins. */
  function start(slot: Slot): void {
    slot.generation++;
    const ctl = new AbortController();
    const load = Promise.resolve(slot.adapter ?? ports.importModule((slot.entry as LazyAdapter).src).then(m => (slot.adapter = m.default)));
    const result = load.then(adapter => {
      quiet(() => adapter.onState?.({ state }));
      if (ctl.signal.aborted || anonymous && state.analyticsLevel === 'none') return null;                              // withdrawn first: nothing ran
      return Promise.resolve().then(() => adapter.grant({ config: slot.entry.config ?? adapter.config, state, signal: ctl.signal }))
        .then((r = {}) => r, () => ({}));                            // a grant that threw may have run code
    }, () => null);                                                     // import failed: nothing ran
    slot.run = { ctl, result };
  }
  /** Detached from set(): a hung import can never delay a withdrawal. Resolves true when a reload is needed.
   * A newer grant owns its storage even if this revoke finishes after another withdrawal. */
  async function stop(slot: Slot): Promise<boolean> {
    const run = slot.run!;
    const generation = slot.generation;
    slot.run = undefined;
    run.ctl.abort();
    const revoker = await run.result;
    if (!revoker) return false;
    const clean = await Promise.resolve().then(() => revoker.revoke?.()).catch(() => false);
    if (!anonymous && slot.generation === generation) purge(doc, slot.adapter?.storage ?? slot.entry.storage);
    return !clean;
  }
  function reconcile(next: ConsentState): void {
    const stops: Promise<boolean>[] = [];
    for (const slot of slots.values()) {
      const allowed = anonymous ? next.analyticsLevel === 'anonymous' : next.allowed[slot.entry.category];
      if (allowed) {
        if (!slot.run) start(slot);
      }
      else if (slot.run) stops.push(stop(slot));
      quiet(() => slot.adapter?.onState?.({ state: next }));
    }
    // Raw tags cannot promise anonymous behavior; only declared adapters can.
    if (!anonymous) activateInert(doc, { allowed: next.allowed, ran });
    const rawRevoked = OPTIONAL.some(c => ran.has(c) && !next.allowed[c]);
    void Promise.all(stops).then(dirty => { if (rawRevoked || dirty.includes(true)) ports.reload(); });
  }
  function apply(): ConsentState {
    const next = (state = compute());
    const html = doc.documentElement;
    html.dataset.consent = next.status;
    html.dataset.consentRegion = next.region;
    html.toggleAttribute('data-consent-gpc', next.gpc);
    reconcile(next);                                                    // stops start before any listener runs
    listeners.forEach(fn => quiet(() => fn(next)));
    doc.dispatchEvent(new CustomEvent(STATE_EVENT, { detail: next }));
    return next;
  }

  async function confirm(choice: StoredChoice, previousId?: string): Promise<void> {
    if (!durable) return;
    const body = JSON.stringify({ policy: choice.p, choices: choice.c, action: choice.a, gpc: ports.gpc(), previousId });
    const res = await ports.fetch(durable.endpoint, { method: 'POST', credentials: 'same-origin', keepalive: true,
      headers: { 'content-type': 'application/json' }, body }).catch(() => null);
    const out = res?.ok ? ((await res.json().catch(() => null)) as { id?: unknown } | null) : null;
    // Superseded in this tab, or another tab wrote a newer choice (adopt it): the late receipt is ignored.
    if (stored !== choice || adopt()) return;
    if (typeof out?.id !== 'string' || !RECEIPT_ID.test(out.id)) return; // failed: q stays, retried at the next boot
    stored = { v: 1, p: choice.p, c: choice.c, t: choice.t, a: choice.a, r: out.id };
    persist();
    apply();                                                            // the receipt is what lets durable grants run
  }

  async function set({ action }: { action: ConsentAction }, { choices: picked = {} }: { choices?: Partial<Flags> } = {}): Promise<ConsentState> {
    if (anonymous) return apply();
    const previousId = stored?.r;
    stored = { v: 1, p: config.policy, c: choicesFor({ action, picked }), t: ports.now(), a: action, ...(durable ? { q: 1 as const } : {}) };
    persist();
    const now = apply();                                                // denial is live here, before any network
    const sent = confirm(stored, previousId);
    if (durable && waiting(now)) await within(sent, durable.waitMs ?? 1500);
    return state;
  }

  function addSlot(entry: AdapterContribution): void {
    if (anonymous && (!entry.supportsAnonymous || entry.category !== 'analytics')) return;
    const slot: Slot = { entry, generation: 0, adapter: typeof (entry as ConsentAdapter).grant === 'function' ? entry as ConsentAdapter : undefined };
    slots.set(entry.id, slot);
    if (anonymous || state.allowed[entry.category]) start(slot);
    else purge(doc, entry.storage);                     // leftovers of an expired or withdrawn choice
    quiet(() => slot.adapter?.onState?.({ state }));                    // lazy adapters get state once loaded
  }
  function syncSlots(items: readonly Contribution[]): void {
    const ids = new Set(items.map(i => i.id));
    for (const [id, slot] of slots) {
      if (ids.has(id)) continue;
      slots.delete(id);
      if (slot.run) void stop(slot).then(dirty => { if (dirty) ports.reload(); });
    }
    for (const item of items as readonly AdapterContribution[]) if (!slots.has(item.id)) addSlot(item);
  }
  /** Another tab chose: adopt its cookie exactly as a page load would. Page-visible events only, no polling.
   * Returns true when the cookie held a different choice. */
  function adopt(): boolean {
    const latest = fromCookie();
    // A refused cookie write leaves only this tab's choice; absence cannot supersede it.
    if (!latest && !cookiePersisted) return false;
    if (sameStoredChoice({ latest, stored })) return false;
    stored = latest;
    apply();
    return true;
  }

  const api: JiniConsentApi = {
    contract: 1, plugins, set,
    get: () => state,
    subscribe: ({ listener }) => { listeners.add(listener); return () => { listeners.delete(listener); }; },
    open: () => { doc.dispatchEvent(new CustomEvent(OPEN_EVENT)); },
    setOpen: ({ open }) => { doc.documentElement.toggleAttribute('data-consent-open', open); },
  };
  plugins.subscribe({ kind: ADAPTER_KIND, listener: syncSlots });
  syncSlots(plugins.list({ kind: ADAPTER_KIND }));                     // registered before this client existed
  config.plugins?.forEach(item => plugins.registerPlugin(item, { source: 'page' }));
  apply();
  doc.addEventListener('visibilitychange', () => { if (doc.visibilityState === 'visible') adopt(); });
  doc.defaultView?.addEventListener('pageshow', () => adopt());
  if (stored?.q && stored.p === config.policy) void confirm(stored);   // durable retry of an earlier failed receipt
  return api;
}

function sameStoredChoice({ latest, stored }: { latest: StoredChoice | null; stored: StoredChoice | null }): boolean {
  return latest?.t === stored?.t && latest?.a === stored?.a && latest?.r === stored?.r;
}

function durableEvidence({ evidence }: ClientOptions, _optional = {}): Extract<Evidence, { mode: 'durable' }> | null {
  return evidence?.mode === 'durable' ? evidence : null;
}

export function browserPorts(win: Window & typeof globalThis): ClientPorts {
  return {
    doc: win.document, fetch: win.fetch.bind(win), now: Date.now, reload: () => win.location.reload(),
    gpc: () => (win.navigator as Navigator & { globalPrivacyControl?: boolean }).globalPrivacyControl === true || win.navigator.doNotTrack === '1',
    importModule: src => import(/* @vite-ignore */ src) as Promise<{ default: ConsentAdapter }>,
  };
}

export interface BootOptions {
  ports?: ClientPorts;
  /** The Jini banner binding; only the client-jini.min.js build passes it, so headless pages never download it. */
  bindBanner?: (required: { api: JiniConsentApi; doc: Document }) => void;
}

function readPage(doc: Document): PageConfig | null {
  try { return JSON.parse(doc.getElementById(CONFIG_ID)?.textContent ?? '') as PageConfig; } catch { return null; }
}

/** Reads #jini-consent-config, installs window.jiniConsent, drains and replaces the pre-boot queue.
 * A missing or broken config installs nothing, so nothing optional can run (fail closed). */
export function boot(win: Window & typeof globalThis = window, { ports = browserPorts(win), bindBanner }: BootOptions = {}): JiniConsentApi | undefined {
  if (win.jiniConsent) return win.jiniConsent;
  const page = readPage(win.document);
  if (!page) return undefined;
  const { evidence, ...config } = page;
  const api = createCookieConsent({ config, ports }, { evidence });
  // Before boot the queue is a plain array; an already-replaced queue object has nothing left to drain.
  const queued = Array.isArray(win.jiniConsentQueue) ? (win.jiniConsentQueue as RawContribution[]) : [];
  win.jiniConsent = api;
  win.jiniConsentQueue = { push: (...items) => items.forEach(item => api.plugins.registerPlugin(item, { source: 'queue' })) };
  win.jiniConsentQueue.push(...queued);
  installOpeners({ api, doc: win.document });
  if (config.banner === 'jini') bindBanner?.({ api, doc: win.document });
  win.document.dispatchEvent(new CustomEvent(READY_EVENT, { detail: api }));
  return api;
}
/** Delete only the caller's storage prefixes; blocked localStorage is tolerated.
 * @example purgeStorage({ doc: document, storage: { cookies: ['vendor_'], local: ['vendor_'] } })
 * @complexity O(cookies + local keys), O(keys) temporary space; no new identity or network. */
export function purgeStorage({ doc, storage }: { doc: Document; storage: StoragePrefixes }, _optional = {}): void {
  purge(doc, storage);
}
export { bindBanner, installOpeners } from './dom.js';

/** @file The one consent rule, shared by the browser client and the server so they can never disagree.
 * Pure functions: no DOM, no Node. */
// MOVED-FROM: @jini-ai/cms consent/policy.ts (resolveConsentRegion, resolveConsentChoices, readConsentRecord,
// createConsentRecord). TODO(P4): delete the cms copies once the consumer reads this package.
import { ACTIONS, type Choices, type ConsentAction, type ConsentState, type Flags, type RegionMode, type ReceiptStatus, type StoredChoice } from '../contract.js';

export const DAY_MS = 86_400_000;
export const DEFAULT_MAX_AGE_MS = 180 * DAY_MS;
/** A receipt time comes from the server clock and is compared with the client clock; allow a minute. */
const SKEW_MS = 60_000;
/** Receipt ids keep the cms receipt-file rule, so ids can never navigate out of a receipt directory. */
export const RECEIPT_ID = /^[\w-]{16,128}$/;
export const DENIED: Choices = Object.freeze({ necessary: true, functional: false, analytics: false, marketing: false });

/** Only the literal hint 'us' loosens; anything else, including absence, is strict. @complexity O(1). */
export function regionFrom({ configured, hint }: { configured: 'auto' | RegionMode; hint: string | null | undefined }, _optional = {}): RegionMode {
  if (configured !== 'auto') return configured;
  return hint === 'us' ? 'opt-out' : 'opt-in';
}

const flags = (functional: boolean, analytics = functional, marketing = analytics): Flags => ({ functional, analytics, marketing });

/** What a button press means. Unknown picks are false. @complexity O(1). */
export function choicesFor({ action, picked = {} }: { action: ConsentAction; picked?: Partial<Flags> }, _optional = {}): Flags {
  if (action === 'accept') return flags(true);
  if (action === 'save') return flags(picked.functional === true, picked.analytics === true, picked.marketing === true);
  // Do-not-sell keeps functional unless explicitly unticked: it is a sale/share refusal, not a reject.
  if (action === 'do-not-sell') return flags(picked.functional !== false, false);
  return flags(false);                                                          // reject, withdraw
}

/** GPC wins over stored or new grants for every category that can share data; nothing can lift it. @complexity O(1). */
export function clamp({ flags, gpc }: { flags: Flags; gpc: boolean }, _optional = {}): Choices {
  return { necessary: true, functional: flags.functional, analytics: flags.analytics && !gpc, marketing: flags.marketing && !gpc };
}

/** Region default, policy-version + age expiry, GPC clamp, and (durable mode) no grant without a receipt.
 * A region default with no stored choice (the opt-out model) is never "waiting", so it runs as configured.
 * Anonymous delivery ignores stored grants; its level permits only anonymous-capable adapters, subject to the privacy signal.
 * @example effective({ stored, policy: '2026-10-26', region: 'opt-in', gpc: false, nowMs: Date.now() }, { durable: true })
 * @complexity O(1). */
export function effective(
  { stored, policy, region, gpc, nowMs }: { stored: StoredChoice | null; policy: string; region: RegionMode; gpc: boolean; nowMs: number },
  { maxAgeMs = DEFAULT_MAX_AGE_MS, durable = false, anonymous = false }: { maxAgeMs?: number; durable?: boolean; anonymous?: boolean } = {},
): ConsentState {
  // Banner-off never revives an old identity or consent grant, even in an opt-out region.
  const live = current({ stored, policy, nowMs, maxAgeMs, anonymous });
  const choices = clamp({ flags: anonymous ? DENIED : live?.c ?? flags(region === 'opt-out'), gpc });
  const base = { contract: 1, policy, region, gpc, choices, ...permissionFor({ choices, live, durable, anonymous, gpc }) } as const;
  if (!live) return { ...base, status: 'pending', action: null, at: null, receipt: 'none' };
  return { ...base, status: 'set', action: live.a, at: live.t, receipt: receiptOf(live) };
}

/** Unparseable, future (beyond skew) and expired choices are all stale. @complexity O(1). */
function current({ stored, policy, nowMs, maxAgeMs, anonymous }: { stored: StoredChoice | null; policy: string; nowMs: number; maxAgeMs: number; anonymous: boolean }): StoredChoice | null {
  return !anonymous && stored && stored.p === policy && stored.t <= nowMs + SKEW_MS && nowMs - stored.t <= maxAgeMs ? stored : null;
}

/** Runtime permissions differ from choices for anonymous delivery and unconfirmed durable grants.
 * @complexity O(1). */
function permissionFor({ choices, live, durable, anonymous, gpc }: { choices: Choices; live: StoredChoice | null; durable: boolean; anonymous: boolean; gpc: boolean }, _optional = {}): Pick<ConsentState, 'allowed' | 'analyticsLevel'> {
  const allowed = anonymous || live && durable && !live.r ? DENIED : choices;
  return { allowed, analyticsLevel: anonymous && !gpc ? 'anonymous' : allowed.analytics ? 'full' : 'none' };
}

function receiptOf(stored: StoredChoice): ReceiptStatus {
  if (stored.r) return 'stored';
  return stored.q ? 'pending' : 'local';
}

/** Trust boundary for the cookie: anything malformed is "no choice". Only known fields are copied out.
 * @complexity O(raw length ≤ 1 KiB). */
export function parseStored({ raw }: { raw: string | null | undefined }, _optional = {}): StoredChoice | null {
  if (!raw || raw.length > 1024) return null;
  let s: Partial<StoredChoice> | null;
  try { s = JSON.parse(raw) as Partial<StoredChoice> | null; } catch { return null; }
  if (!isStored(s)) return null;
  const out: StoredChoice = { v: 1, p: s.p, c: flags(s.c.functional, s.c.analytics, s.c.marketing), t: s.t, a: s.a };
  if (typeof s.r === 'string' && RECEIPT_ID.test(s.r)) out.r = s.r;
  if (s.q === 1) out.q = 1;
  return out;
}

function isStored(s: Partial<StoredChoice> | null): s is StoredChoice {
  if (!s || s.v !== 1 || typeof s.p !== 'string' || !Number.isFinite(s.t)) return false;
  return ACTIONS.includes(s.a!) && isFlags(s.c);
}

/** Own booleans only: truthy strings never count as a grant. @complexity O(1). */
export function isFlags(c: unknown): c is Flags {
  const f = c as Partial<Flags> | null;
  return !!f && typeof f === 'object' && typeof f.functional === 'boolean' && typeof f.analytics === 'boolean' && typeof f.marketing === 'boolean';
}

// MOVED-FROM: @jini-ai/cms consent/node/index.ts, unchanged except the record types now come from ../server.
// TODO(P4): delete the cms copy once the consumer reads this package.
import path from 'node:path';
import * as fs from 'node:fs/promises';
import { isIP } from 'node:net';
import { randomUUID } from 'node:crypto';
import { DEFAULT_MAX_AGE_MS as CONSENT_MAX_AGE_MS } from '../contracts/policy.js';
import type { ConsentRecord, ConsentRecordPort } from '../server/receipt.js';

const RECEIPT_FILENAME = /^[a-zA-Z0-9_-]{16,128}\.json$/;

/** Count is unknown when the host cannot inspect receipt storage. */
export type ConsentReceiptStorageHealth = { writable: boolean; count: number | null };

/** Prepare the same private directory used by receipt writes, check write/search access and count
 * receipt files without reading visitor proof. Filesystem errors propagate to the host's readiness check.
 * This is a current permissions check, not a guarantee against later capacity or I/O failures.
 * @example await readConsentReceiptStorage({ directory: '/site/consent-receipts' })
 * @complexity O(directory entries) time and space; no per-receipt reads or writes. */
export async function readConsentReceiptStorage({ directory }: { directory: string }, { filesystem = fs }: { filesystem?: Pick<typeof fs, 'mkdir' | 'access' | 'readdir'> } = {}): Promise<ConsentReceiptStorageHealth> {
  await filesystem.mkdir(directory, { recursive: true, mode: 0o700 });
  await filesystem.access(directory, fs.constants.W_OK | fs.constants.X_OK);
  const entries = await filesystem.readdir(directory, { withFileTypes: true });
  return { writable: true, count: entries.filter(entry => entry.isFile() && RECEIPT_FILENAME.test(entry.name)).length };
}

/** Atomic writer owns flush/rename/permissions; the host binds its installed platform writer. */
export interface ConsentFilePorts {
  readText(required: { filePath: string }, optional?: Record<string, never>): Promise<string | null>;
  writeJson(required: { filePath: string; record: ConsentRecord }, optional?: Record<string, never>): Promise<void>;
  /** Preserve evidence outside active receipt lookup. Missing files are already inactive. */
  retire?(required: { filePath: string }, optional?: Record<string, never>): Promise<void>;
}

/** Host injects the existing platform/fs writer rather than copying its durability lifecycle. */
export type ConsentAtomicWriter = (required: { filePath: string; data: unknown }, optional: { createParent: boolean; mode: number; refuseSymlink: boolean }) => Promise<void>;

/** @complexity O(1). */
function assertLimits({ maximumRecords, retentionMs }: { maximumRecords: number; retentionMs: number }): void {
  if (!Number.isSafeInteger(maximumRecords) || maximumRecords < 1) throw new Error('Consent receipt capacity must be a positive integer.');
  if (!Number.isFinite(retentionMs) || retentionMs < 0) throw new Error('Consent receipt retention must be nonnegative.');
}

/** Publish a flushed staging file with an exclusive hard link, then flush the directory on non-Windows hosts.
 * Filesystem/link failures propagate. No reader ever sees a partially-written proof file.
 * @complexity Startup O(r log r) time/O(r) space; subsequent writes amortized O(1) plus bounded receipt I/O. */
export function createNodeConsentFiles({ atomicWrite }: { atomicWrite: ConsentAtomicWriter }, { filesystem = fs, uniqueId = randomUUID, maximumRecords = 10000, retentionMs = CONSENT_MAX_AGE_MS, nowMs = Date.now, platform = process.platform }: { filesystem?: Pick<typeof fs, 'link' | 'unlink' | 'open' | 'readdir' | 'stat'>; uniqueId?: () => string; maximumRecords?: number; retentionMs?: number; nowMs?: () => number; platform?: NodeJS.Platform } = {}): ConsentFilePorts {
  assertLimits({ maximumRecords, retentionMs });
  const writes = new Map<string, Promise<void>>();
  const inventories = new Map<string, Map<string, number>>();
  /** Keep active-file removal and publication in the same directory queue so scans cannot race unlink.
   * Operation failures propagate and invalidate only that directory's inventory. @complexity O(1) queue overhead. */
  async function serialize({ directory, operation }: { directory: string; operation: () => Promise<void> }, _options = {}): Promise<void> {
    const pending = (writes.get(directory) ?? Promise.resolve()).catch(() => undefined).then(operation);
    writes.set(directory, pending);
    try { await pending; } catch (error) { inventories.delete(directory); throw error; } finally { if (writes.get(directory) === pending) writes.delete(directory); }
  }
  /** Serialize capacity checks/publication in this adapter. The host selects proof retention;
   * cookie expiry is not a legal proof-erasure policy. This bounded default is configurable,
   * and capacity eviction may shorten it; hosts needing longer proof retention must size accordingly.
   * Scan once at startup, then maintain an oldest-first inventory rather than stat every save.
   * @complexity Initial O(r log r); cached lookup O(1), pruning amortized O(1) per receipt. */
  async function inventory({ directory }: { directory: string }, _options = {}): Promise<Map<string, number>> {
    const cached = inventories.get(directory);
    if (cached) return cached;
    let names: string[];
    try { names = await filesystem.readdir(directory); }
    catch (error) {
      if (error && typeof error === 'object' && 'code' in error && error.code === 'ENOENT') names = [];
      else throw error;
    }
    const entries: Array<[string, number]> = [];
    for (const name of names) {
      if (RECEIPT_FILENAME.test(name)) entries.push([name, (await filesystem.stat(path.join(directory, name))).mtimeMs]);
    }
    entries.sort((left, right) => left[1] - right[1]);
    const retained = new Map(entries);
    inventories.set(directory, retained);
    return retained;
  }
  /** Expiry and capacity remove only owned receipts; unrelated files stay intact. */
  async function capacity({ directory, retained }: { directory: string; retained: Map<string, number> }, _options = {}): Promise<void> {
    const cutoff = nowMs() - retentionMs;
    for (const [name, timestamp] of retained) {
      if (retained.size < maximumRecords && timestamp >= cutoff) break;
      try { await filesystem.unlink(path.join(directory, name)); }
      catch (error) { if (!(error && typeof error === 'object' && 'code' in error && error.code === 'ENOENT')) throw error; }
      retained.delete(name);
    }
  }
  return {
    async retire({ filePath }, _options = {}) {
      const directoryPath = path.dirname(filePath);
      await serialize({ directory: directoryPath, operation: async () => {
        const text = await this.readText({ filePath });
        if (text === null) return;
        // Publish the archive durably before unlinking the active receipt. A crash can only leave
        // the old choice active before the replacement save has been acknowledged to the visitor.
        const archived = path.join(directoryPath, 'retired', path.basename(filePath));
        if (await this.readText({ filePath: archived }) === null) await this.writeJson({ filePath: archived, record: JSON.parse(text) as ConsentRecord });
        try { await filesystem.unlink(filePath); }
        catch (error) { if (!(error && typeof error === 'object' && 'code' in error && error.code === 'ENOENT')) throw error; }
        inventories.get(directoryPath)?.delete(path.basename(filePath));
        if (platform !== 'win32') {
          const directory = await filesystem.open(directoryPath, 'r');
          try { await directory.sync(); } finally { await directory.close(); }
        }
      } });
    },
    async readText({ filePath }) {
      try {
        const handle = await filesystem.open(filePath, 'r');
        try {
          if ((await handle.stat()).size > 4096) throw new Error('Consent receipt exceeds 4096 bytes.');
          return await handle.readFile('utf8');
        } finally { await handle.close(); }
      }
      catch (error) {
        if (typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT') return null;
        throw error;
      }
    },
    async writeJson({ filePath, record }, _options = {}) {
      const directoryPath = path.dirname(filePath);
      await serialize({ directory: directoryPath, operation: async () => {
        if (JSON.stringify(record).length > 4096) throw new Error('Consent receipt exceeds 4096 bytes.');
        const retained = await inventory({ directory: directoryPath });
        if (retained.has(path.basename(filePath))) throw new Error('Consent receipt ID already exists.');
        const staging = path.join(path.dirname(filePath), `.${path.basename(filePath)}.${uniqueId()}.pending`);
        await atomicWrite({ filePath: staging, data: record }, { createParent: true, mode: 0o600, refuseSymlink: true });
        try {
          await capacity({ directory: directoryPath, retained });
          await filesystem.link(staging, filePath);
          retained.set(path.basename(filePath), nowMs());
          if (platform !== 'win32') {
            const directory = await filesystem.open(path.dirname(filePath), 'r');
            try { await directory.sync(); } finally { await directory.close(); }
          }
        } finally { await filesystem.unlink(staging); }
      } });
    },
  };
}

/** Per-site opaque filenames; IDs cannot navigate out of the configured proof directory.
 * One immutable file per choice keeps historic policy versions without schema changes.
 * @complexity O(1) record lookup; publication uses the injected writer's cached capacity/retention inventory.
 * @throws Invalid ID, filesystem and malformed JSON errors; only absence returns null. */
export function createConsentFileRecords({ directory, files }: { directory: string; files: ConsentFilePorts }, _options = {}): ConsentRecordPort {
  const filePath = (id: string) => {
    if (!/^[a-zA-Z0-9_-]{16,128}$/.test(id)) throw new Error('Invalid consent receipt ID.');
    return path.join(directory, `${id}.json`);
  };
  return {
    ...(files.retire ? { retire: async ({ id }: { id: string }) => files.retire!({ filePath: filePath(id) }) } : {}),
    async read({ id }) {
      const text = await files.readText({ filePath: filePath(id) });
      if (text === null) return null;
      if (text.length > 4096) throw new Error('Consent receipt exceeds 4096 bytes.');
      return JSON.parse(text) as unknown;
    },
    async save({ record }) {
      const destination = filePath(record.id);
      // The injected writer must also enforce exclusive publication against concurrent collisions.
      if (await files.readText({ filePath: destination }) !== null) throw new Error('Consent receipt ID already exists.');
      await files.writeJson({ filePath: destination, record });
    },
  };
}

/** A dotted IPv4 tail becomes two hex groups so every spelling parses the same way. @complexity O(1). */
function hexIpv4Tail(address: string): string {
  if (!address.includes('.')) return address;
  const at = address.lastIndexOf(':');
  const octets = address.slice(at + 1).split('.').map(Number);
  return address.slice(0, at + 1) + ((octets[0]! << 8) + octets[1]!).toString(16) + ':' + ((octets[2]! << 8) + octets[3]!).toString(16);
}

/** Expand :: into explicit zero groups. @complexity O(1). */
function ipv6Groups(address: string): number[] {
  const [left = '', right = ''] = address.toLowerCase().split('::');
  const before = left ? left.split(':') : [];
  const after = right ? right.split(':') : [];
  const groups = address.includes('::') ? [...before, ...Array(8 - before.length - after.length).fill('0'), ...after] : before;
  return groups.map(group => parseInt(group, 16));
}

/** Group temporary IPv6 addresses by /64 using native address validation; mapped IPv4 keeps
 * its IPv4 budget. The host still owns trusted-proxy address selection. @complexity O(1). */
export function consentRateLimitKey({ address }: { address: string }, _options = {}): string {
  if (isIP(address) !== 6) return address;
  const values = ipv6Groups(hexIpv4Tail(address.split('%')[0]!));
  if (values.slice(0, 5).every(value => value === 0) && values[5] === 65535) return `${values[6]! >> 8}.${values[6]! & 255}.${values[7]! >> 8}.${values[7]! & 255}`;
  return values.slice(0, 4).map(value => value.toString(16)).join(':') + '::/64';
}

/** @file Pure strings: no DOM, no Node. The same output feeds live pages, the static export and the admin
 * preview iframe, so preview and live cannot drift. The markup is identical for every visitor: region and GPC
 * variants are toggled by CSS from <html> attributes the client sets, so pages stay cacheable. */
import { BANNER_MODES, CONFIG_ID, type BannerMode, type Category, type ClientConfig, type Evidence, type RegionMode } from '../contract.js';
import { BASE_CSS } from './base-css.js';
import { compileConsentCss, type ConsentAppearanceTokens, type ConsentCssProblem } from './css.js';

export const CONSENT_PLACEMENTS = ['bottom-bar', 'bottom-left', 'bottom-right', 'top-bar'] as const;
export type ConsentPlacement = typeof CONSENT_PLACEMENTS[number];

/** Every visible string is owner copy; DEFAULT_COPY fills only what the host leaves out. */
export interface BannerCopy {
  title: string; message: string; acceptLabel: string; rejectLabel: string; preferencesLabel: string;
  saveLabel: string; doNotSellLabel: string; categoriesLegend: string; gpcNote: string; errorMessage: string;
  reopenLabel: string; privacyLabel: string; privacyPolicyUrl: string;
  secondaryLinkLabel?: string; secondaryLinkUrl?: string;
  categoryLabels: Record<Category, string>;
}
export const DEFAULT_COPY: Readonly<BannerCopy> = Object.freeze({
  title: 'Cookies', message: 'We use optional cookies for analytics and marketing only if you agree.',
  acceptLabel: 'Accept', rejectLabel: 'Reject', preferencesLabel: 'Preferences', saveLabel: 'Save preferences',
  doNotSellLabel: 'Do not sell or share my personal information', categoriesLegend: 'Cookie categories',
  gpcNote: 'Your browser privacy signal is on, so analytics and marketing stay off.',
  errorMessage: 'Your choice could not be saved yet. Optional cookies stay off until it is.',
  reopenLabel: 'Privacy choices', privacyLabel: 'Privacy policy', privacyPolicyUrl: '',
  categoryLabels: { necessary: 'Necessary (always on)', functional: 'Functional', analytics: 'Analytics', marketing: 'Marketing' },
});

export type BannerCopyInput = Partial<Omit<BannerCopy, 'categoryLabels'>> & { categoryLabels?: Partial<Record<Category, string>> };
export interface RenderBannerConfig { mode: BannerMode; client: Omit<ClientConfig, 'banner'>; copy: BannerCopyInput }
export interface RenderBannerOptions {
  evidence?: Evidence; placement?: ConsentPlacement; reopen?: 'corner' | 'link';
  appearance?: ConsentAppearanceTokens; customCss?: string;
  /** URL of dist/client.min.js as the host serves it. Omitted in a preview. */
  clientSrc?: string; nonce?: string;
  /** Scriptless admin preview: the banner renders open for the given region; htmlAttrs go on the iframe's <html>. */
  preview?: { region: RegionMode; panel?: boolean };
}
export interface RenderedBanner { head: string; body: string; htmlAttrs: string; problems: ConsentCssProblem[] }

const ESC: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (s: string) => String(s).replace(/[&<>"']/g, ch => ESC[ch]!);
const json = (v: unknown) => JSON.stringify(v).replace(/</g, '\\u003c');
const EMPTY: RenderedBanner = Object.freeze({ head: '', body: '', htmlAttrs: '', problems: [] }) as RenderedBanner;

// MOVED-FROM: @jini-ai/cms consent/html/render.ts consentPolicyHref. TODO(P4): delete the cms copy.
/** Refuse executable/data/protocol-relative links; local pages are the common case. @complexity O(url length). */
export function safeHref(url: string | undefined): string | null {
  if (!url) return null;
  if (/^\/(?!\/)/.test(url) && !/[\\\x00-\x20]/.test(url)) return url;
  try { const parsed = new URL(url); return parsed.protocol === 'https:' && !parsed.username && !parsed.password ? parsed.href : null; }
  catch { return null; }
}

/** Owner copy over the defaults; a non-string field falls back instead of rendering "undefined". */
export function resolveCopy(input: BannerCopyInput = {}): BannerCopy {
  const pick = <T extends object>(base: T, over: object | undefined): T =>
    Object.fromEntries(Object.entries(base).map(([k, v]) => [k, typeof (over as Record<string, unknown> | undefined)?.[k] === 'string' ? (over as Record<string, string>)[k] : v])) as T;
  const { categoryLabels, ...rest } = DEFAULT_COPY;
  const merged = pick(rest, input) as BannerCopy;
  for (const key of ['secondaryLinkLabel', 'secondaryLinkUrl'] as const) if (typeof input[key] === 'string') merged[key] = input[key];
  merged.categoryLabels = pick(categoryLabels, input.categoryLabels);
  return merged;
}

/** @example renderBanner({ mode: 'jini', client: { contract: 1, policy: '2026-10-26', regionMode: 'auto' }, copy: {} }, { clientSrc: '/consent/client.min.js', evidence: { mode: 'local' } })
 * @complexity O(copy + CSS length). */
export function renderBanner({ mode, client, copy }: RenderBannerConfig, options: RenderBannerOptions = {}): RenderedBanner {
  if (!BANNER_MODES.includes(mode)) return EMPTY;
  const evidence = options.evidence ?? { mode: 'local' };
  const n = options.nonce ? ` nonce="${esc(options.nonce)}"` : '';
  const head = `<script type="application/json" id="${CONFIG_ID}">${json({ ...client, banner: mode, evidence })}</script>${clientScript(options, n)}`;
  const htmlAttrs = previewAttrs(options.preview);
  if (mode !== 'jini') return { head, body: '', htmlAttrs, problems: [] };
  const compiled = compileConsentCss({ css: options.customCss ?? '', tokens: options.appearance ?? {} });
  const style = `<style data-jini-consent-style${n}>${BASE_CSS}${compiled.css}</style>`;
  return { head: style + head, body: markup({ copy: resolveCopy(copy), options, evidence }), htmlAttrs, problems: compiled.problems };
}

/** A preview is scriptless: the admin iframe shows the markup, never runs the client. */
function clientScript({ preview, clientSrc }: RenderBannerOptions, nonceAttr: string): string {
  return preview || !clientSrc ? '' : `<script src="${esc(clientSrc)}" defer${nonceAttr}></script>`;
}

/** Attributes for the preview iframe's <html>, standing in for what the client sets on a live page. */
function previewAttrs(preview: RenderBannerOptions['preview']): string {
  if (!preview) return '';
  return `data-consent="pending" data-consent-region="${preview.region === 'opt-out' ? 'opt-out' : 'opt-in'}" data-consent-open`;
}

function links(copy: BannerCopy): string {
  const privacy = safeHref(copy.privacyPolicyUrl);
  const second = safeHref(copy.secondaryLinkUrl);
  const items = [privacy ? `<a href="${esc(privacy)}">${esc(copy.privacyLabel)}</a>` : '',
    second && copy.secondaryLinkLabel ? `<a href="${esc(second)}">${esc(copy.secondaryLinkLabel)}</a>` : ''].filter(Boolean);
  return items.length ? `<p class="jini-consent-links">${items.join(' · ')}</p>` : '';
}

function categories(copy: BannerCopy): string {
  const box = (name: Category, attrs: string) => `<label><input type="checkbox" name="${name}"${attrs}>${esc(copy.categoryLabels[name])}</label>`;
  return box('necessary', ' checked disabled') + box('functional', '') + box('analytics', '') + box('marketing', '');
}

function markup({ copy, options, evidence }: { copy: BannerCopy; options: RenderBannerOptions; evidence: Evidence }): string {
  const b = (action: string, label: string, extra = '') => `<button type="button" data-consent-action="${action}"${extra}>${esc(label)}</button>`;
  const placement = CONSENT_PLACEMENTS.includes(options.placement!) ? options.placement! : 'bottom-bar';
  const reopen = options.reopen === 'link' ? '' : `<button type="button" class="jini-consent-reopen" data-consent-open>${esc(copy.reopenLabel)}</button>`;
  return `<section id="jini-consent" class="jini-consent" role="dialog" aria-modal="false" aria-labelledby="jini-consent-title" data-placement="${placement}" data-evidence="${evidence.mode}"${options.preview ? ' data-preview' : ' hidden'}>
<h2 id="jini-consent-title">${esc(copy.title)}</h2><p>${esc(copy.message)}</p>${links(copy)}
<p data-consent-gpc>${esc(copy.gpcNote)}</p><p role="alert" data-consent-error hidden>${esc(copy.errorMessage)}</p>
<div class="jini-consent-actions">${b('reject', copy.rejectLabel, ' data-consent-only="opt-in"')}${b('accept', copy.acceptLabel)}</div>
${b('do-not-sell', copy.doNotSellLabel, ' class="jini-consent-link" data-consent-only="opt-out"')}
<details${options.preview?.panel ? ' open' : ''}><summary>${esc(copy.preferencesLabel)}</summary><fieldset><legend>${esc(copy.categoriesLegend)}</legend>${categories(copy)}</fieldset>
<div class="jini-consent-actions">${b('save', copy.saveLabel)}${b('reject', copy.rejectLabel)}</div></details>
</section>${options.preview ? '' : reopen}`;
}

