// MOVED-FROM: @jini-ai/cms consent/css-parser.ts, unchanged. TODO(P4): delete the cms copy once the consumer reads this package.
/** A deliberately small CSS grammar: qualified rules, optionally inside width media queries.
 * Comments, strings and balanced functions are tokenized before structural punctuation is read.
 * The HTML resource scanner classifies remote URLs, not declarations/selectors; customization
 * needs this stricter grammar. Unknown CSS is rejected rather than repaired. */
export interface ConsentCssToken { kind: 'text' | 'string' | 'symbol' | 'space'; value: string; offset: number }
export interface ConsentCssDeclaration { property: string; value: string; offset: number }
export interface ConsentCssRule { selector: string; declarations: ConsentCssDeclaration[]; offset: number; media?: string }

export class ConsentCssSyntaxError extends Error {
  constructor(message: string, readonly offset: number) { super(message); }
}

/** Read a quoted CSS string; escape syntax is excluded by the compiler before parsing.
 * @throws ConsentCssSyntaxError for an unterminated string. @complexity O(string length). */
function quotedToken({ css, start }: { css: string; start: number }): ConsentCssToken {
  const end = css.indexOf(css[start]!, start + 1);
  if (end === -1 || /[\n\r\f]/.test(css.slice(start, end))) throw new ConsentCssSyntaxError('Unterminated CSS string.', start);
  return { kind: 'string', value: css.slice(start, end + 1), offset: start };
}

/** Read one lexical token; comment boundaries remain whitespace so identifiers never fuse.
 * @throws ConsentCssSyntaxError for unterminated comments/strings. @complexity O(token length). */
function nextToken({ css, state }: { css: string; state: { cursor: number } }): ConsentCssToken {
  const start = state.cursor;
  const char = css[start]!;
  if (css.startsWith('/*', start)) {
    const end = css.indexOf('*/', start + 2);
    if (end === -1) throw new ConsentCssSyntaxError('Unterminated CSS comment.', start);
    state.cursor = end + 2;
    return { kind: 'space', value: ' ', offset: start };
  }
  if ('"\''.includes(char)) {
    const token = quotedToken({ css, start }); state.cursor += token.value.length; return token;
  }
  state.cursor++;
  if ('{}:;(),!@[]'.includes(char)) return { kind: 'symbol', value: char, offset: start };
  if (/\s/.test(char)) return { kind: 'space', value: ' ', offset: start };
  while (state.cursor < css.length && !/[\s{}:;(),!@\[\]"']/.test(css[state.cursor]!) && !css.startsWith('/*', state.cursor)) state.cursor++;
  return { kind: 'text', value: css.slice(start, state.cursor), offset: start };
}

/** @throws ConsentCssSyntaxError for invalid tokens. @complexity O(n) time/space. */
function tokenize({ css }: { css: string }): ConsentCssToken[] {
  const tokens: ConsentCssToken[] = [];
  const state = { cursor: 0 };
  while (state.cursor < css.length) tokens.push(nextToken({ css, state }));
  return tokens;
}

/** @throws ConsentCssSyntaxError on mismatched brackets/functions. @complexity O(1). */
function trackGroup(token: ConsentCssToken, closing: string[]): void {
  if (token.kind !== 'symbol') return;
  if (token.value === '(') closing.push(')');
  if (token.value === '[') closing.push(']');
  if ([')', ']'].includes(token.value) && closing.pop() !== token.value) throw new ConsentCssSyntaxError('Unbalanced CSS group.', token.offset);
}

/** Consume structural delimiters only outside strings and balanced parentheses/brackets.
 * @throws ConsentCssSyntaxError for unbalanced groups. @complexity O(consumed tokens). */
function takeUntil({ tokens, state, delimiters }: { tokens: ConsentCssToken[]; state: { cursor: number }; delimiters: string }): string {
  const parts: string[] = [];
  const closing: string[] = [];
  while (state.cursor < tokens.length) {
    const token = tokens[state.cursor]!;
    if (token.kind === 'symbol' && !closing.length && delimiters.includes(token.value)) break;
    trackGroup(token, closing);
    parts.push(token.value); state.cursor++;
  }
  // A non-empty `closing` means this loop consumed the opener, so `cursor - 1` is a real token.
  if (closing.length) throw new ConsentCssSyntaxError('Unclosed CSS group.', tokens[state.cursor - 1]!.offset);
  return parts.join('').trim();
}

/** Parse a flat declaration list without splitting quoted/function semicolons.
 * @throws ConsentCssSyntaxError for malformed declarations. @complexity O(consumed tokens). */
function declarations({ tokens, state }: { tokens: ConsentCssToken[]; state: { cursor: number } }): ConsentCssDeclaration[] {
  const result: ConsentCssDeclaration[] = [];
  while (state.cursor < tokens.length) {
    if (tokens[state.cursor]!.kind === 'space') { state.cursor++; continue; }
    if (tokens[state.cursor]!.value === '}') { state.cursor++; return result; }
    if (tokens[state.cursor]!.value === ';') { state.cursor++; continue; }
    result.push(declaration({ tokens, state }));
  }
  // Only entered after the rule's `{` was consumed, so `cursor - 1` is always a real token.
  throw new ConsentCssSyntaxError('Unclosed CSS rule.', tokens[state.cursor - 1]!.offset);
}

/** @throws ConsentCssSyntaxError for malformed properties/values. @complexity O(consumed tokens). */
function declaration({ tokens, state }: { tokens: ConsentCssToken[]; state: { cursor: number } }): ConsentCssDeclaration {
  const offset = tokens[state.cursor]!.offset;
  const property = takeUntil({ tokens, state, delimiters: ':;{}' });
  if (tokens[state.cursor]?.value !== ':') throw new ConsentCssSyntaxError('Expected a CSS property followed by a colon.', offset);
  state.cursor++;
  const value = takeUntil({ tokens, state, delimiters: ';{}' });
  if (![';', '}'].includes(tokens[state.cursor]?.value ?? '')) throw new ConsentCssSyntaxError('Expected a semicolon or closing brace.', offset);
  if (tokens[state.cursor]?.value === ';') state.cursor++;
  return { property: property.toLowerCase(), value, offset };
}

type RuleInput = { tokens: ConsentCssToken[]; state: { cursor: number }; media?: string };

/** Read one non-nested rule; the compiler validates every selector and declaration.
 * @throws ConsentCssSyntaxError for unsupported syntax. @complexity O(consumed tokens). */
function qualifiedRule({ tokens, state, media }: RuleInput, _options = {}): ConsentCssRule {
  const offset = tokens[state.cursor]!.offset;
  const selector = takeUntil({ tokens, state, delimiters: '{};@' });
  if (!selector || tokens[state.cursor]?.value !== '{') throw new ConsentCssSyntaxError('Expected a scoped CSS rule.', offset);
  state.cursor++;
  return { selector, declarations: declarations({ tokens, state }), offset, ...(media === undefined ? {} : { media }) };
}

/** Width queries are the only supported at-rule; no imports, nested queries or feature rules.
 * @throws ConsentCssSyntaxError for unsupported queries. @complexity O(consumed tokens). */
function mediaRules({ tokens, state, media }: RuleInput, _options = {}): ConsentCssRule[] {
  const offset = tokens[state.cursor]!.offset;
  if (media !== undefined) throw new ConsentCssSyntaxError('Nested media queries are not supported.', offset);
  state.cursor++;
  const header = takeUntil({ tokens, state, delimiters: '{};@' });
  const match = /^media\s*((?:screen\s+and\s+)?\((?:min|max)-width:\s*\d{1,4}(?:\.\d+)?px\)(?:\s+and\s+\((?:min|max)-width:\s*\d{1,4}(?:\.\d+)?px\))?)$/.exec(header);
  if (!match || tokens[state.cursor]?.value !== '{') throw new ConsentCssSyntaxError('Only width @media queries are supported.', offset);
  state.cursor++;
  return ruleList({ tokens, state, media: match[1]! });
}

/** Flatten one level of media rules, preserving their conditions for safe emission.
 * @throws ConsentCssSyntaxError for unclosed/nested blocks. @complexity O(consumed tokens). */
function ruleList(input: RuleInput, _options = {}): ConsentCssRule[] {
  const { tokens, state, media } = input;
  const rules: ConsentCssRule[] = [];
  while (state.cursor < tokens.length) {
    const token = tokens[state.cursor]!;
    if (token.kind === 'space') { state.cursor++; continue; }
    if (token.value === '}' && media !== undefined) { state.cursor++; return rules; }
    if (token.value === '@') { rules.push(...mediaRules(input)); continue; }
    rules.push(qualifiedRule(input));
  }
  if (media !== undefined) throw new ConsentCssSyntaxError('Unclosed media query.', tokens[state.cursor - 1]!.offset);
  return rules;
}

/** Internal AST parser; the compiler adds size/character, selector and declaration allowlists.
 * @example parseConsentCss({ css: '@media(max-width:640px){#jini-consent{padding:12px}}' })
 * @throws ConsentCssSyntaxError for unsupported/malformed syntax. @complexity O(n) time/space. */
export function parseConsentCss({ css }: { css: string }, _options = {}): ConsentCssRule[] {
  return ruleList({ tokens: tokenize({ css }), state: { cursor: 0 } });
}

/** @file Owner CSS for the Jini banner: appearance tokens + custom CSS, compiled for the preview, live pages
 * and the static export alike. Any selector under the banner scope is allowed; a bad rule is dropped and
 * reported on its own (the rest of the customization stays); the 4.5:1 contrast check and the engine
 * Reject-parity block always apply. No DOM, no I/O. */
// MOVED-FROM: @jini-ai/cms consent/css.ts (value rules, contrast check, parity block). Changed: the selector
// gate is "anything under the scope" instead of a fixed surface list, and problems drop one rule instead
// of the whole customization. TODO(P4): delete the cms copy once the consumer reads this package.
import { ConsentCssSyntaxError, parseConsentCss, type ConsentCssDeclaration, type ConsentCssRule } from './css-parser.js';

export const CONSENT_CSS_SCOPE = '#jini-consent';
export const CONSENT_MAX_CSS_LENGTH = 16_384;

/** Bounded appearance tokens; colors are opaque hex and must meet 4.5:1 contrast. */
export interface ConsentAppearanceTokens {
  backgroundColor?: string; textColor?: string; borderColor?: string; borderRadius?: string;
  padding?: string; fontSize?: string; maxWidth?: string; fontFamily?: string;
}
export interface ConsentCssProblem {
  code: 'size' | 'syntax' | 'selector' | 'property' | 'value' | 'contrast';
  message: string;
  /** Zero-based customCss offset; token diagnostics use 0, aggregate diagnostics omit it. */
  offset?: number;
  selector?: string;
  property?: string;
}
export interface ConsentCssResult {
  /** The accepted rules followed by the engine parity block. */
  css: string;
  problems: ConsentCssProblem[];
}

const TOKEN_PROPERTIES: Record<keyof ConsentAppearanceTokens, string> = {
  backgroundColor: 'background-color', textColor: 'color', borderColor: 'border-color', borderRadius: 'border-radius',
  padding: 'padding', fontSize: 'font-size', maxWidth: 'max-width', fontFamily: 'font-family',
};
const DEFAULT_COLORS = { background: '#ffffff', text: '#222222' };
type Colors = typeof DEFAULT_COLORS;
const COLOR_PROPS: ReadonlySet<string> = new Set(['background-color', 'color']);

/** Opaque hex only: functions, variables, alpha and currentColor cannot hide notice text. @complexity O(1). */
function isColor(value: string): boolean { return /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(value); }

/** Absolute lengths keep bounds independent of the host's root font/viewport dimensions. @complexity O(value length). */
function pixels(value: string): number {
  if (value === '0') return 0;
  const match = /^(\d+(?:\.\d+)?)px$/.exec(value);
  return match ? Number(match[1]) : NaN;
}

function boundedLength(value: string, min: number, max: number): boolean {
  const size = pixels(value);
  return Number.isFinite(size) && size >= min && size <= max;
}

/** Bounded non-negative spacing cannot move required controls off screen. @complexity O(value length). */
function lengthList({ value, min = 0, max = 32, count = 4 }: { value: string; min?: number; max?: number; count?: number }): boolean {
  const parts = value.split(/\s+/);
  return parts.length <= count && parts.every(part => boundedLength(part, min, max));
}

/** Alpha is permitted only for shadows, never for text or control fills. @complexity O(value length). */
function shadowColor(value: string): boolean {
  if (isColor(value)) return true;
  const match = /^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(0(?:\.\d+)?|1(?:\.0+)?|\.\d+)\s*\)$/.exec(value);
  return match !== null && match.slice(1, 4).every(channel => Number(channel) <= 255);
}

/** A bounded shadow cannot cover the page or disguise the banner with a huge spread. @complexity O(value length). */
function isShadow(value: string): boolean {
  if (value === 'none') return true;
  const colorStart = value.search(/#|rgba\(/i);
  const prefix = value.slice(0, colorStart);
  if (colorStart < 0 || !/\s$/.test(prefix)) return false;
  const lengths = prefix.trim().split(/\s+/);
  if (lengths.length < 3 || lengths.length > 4) return false;
  return lengths.every((part, index) => boundedLength(part, 0, [24, 24, 64, 8][index]!)) && shadowColor(value.slice(colorStart));
}

/** Font names and generic families only: no url(), no functions, bounded length. */
const isFontFamily = (value: string) => value.length <= 200 && /^[\w\s,"'-]+$/.test(value);

const VALUE_RULES: Record<string, (value: string) => boolean> = {
  'background-color': isColor, color: isColor, 'border-color': isColor,
  'border-radius': value => lengthList({ value }),
  'border-width': value => lengthList({ value, max: 4 }),
  'border-style': value => /^(?:solid|dashed|dotted|none)$/.test(value),
  padding: value => lengthList({ value }),
  margin: value => lengthList({ value }),
  'margin-top': value => boundedLength(value, 0, 32),
  'margin-left': value => boundedLength(value, 0, 32),
  gap: value => lengthList({ value, count: 2 }),
  'line-height': value => /^(?:1(?:\.\d+)?|2(?:\.0+)?)$/.test(value),
  'min-height': value => boundedLength(value, 24, 64),
  'font-size': value => boundedLength(value, 12, 24),
  'font-family': isFontFamily,
  'font-weight': value => /^(?:normal|bold|[1-9]00)$/.test(value),
  'letter-spacing': value => value === 'normal' || boundedLength(value, 0, 4),
  'text-align': value => /^(?:start|end|left|right|center)$/.test(value),
  'text-transform': value => /^(?:none|uppercase|lowercase|capitalize)$/.test(value),
  'max-width': value => value === '100%' || boundedLength(value, 256, 960),
  'box-shadow': isShadow,
};
const ROOT_ONLY: ReadonlySet<string> = new Set(['background-color', 'color', 'max-width', 'box-shadow']);

/** Decode an already validated opaque hex color to sRGB channels. @complexity O(1). */
function colorChannels(color: string): number[] {
  const hex = color.length === 4 ? color.slice(1).split('').map(char => char + char).join('') : color.slice(1);
  return [0, 2, 4].map(offset => parseInt(hex.slice(offset, offset + 2), 16) / 255);
}

/** WCAG relative luminance of normalized sRGB channels. @complexity O(1). */
function luminance(channels: number[]): number {
  const linear = channels.map(value => value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
  return linear[0]! * 0.2126 + linear[1]! * 0.7152 + linear[2]! * 0.0722;
}

/** Fail closed on low-contrast banner and button fills, including declarations overriding tokens. @complexity O(1). */
function hasContrast({ background, text }: Colors): boolean {
  const bg = colorChannels(background); const fg = colorChannels(text);
  const b = luminance(fg);
  // Match the base CSS's sRGB mixes (button fill 7%, hover 13%) before linearizing for WCAG contrast.
  return [0, 0.07, 0.13].every(weight => {
    const a = luminance(bg.map((channel, index) => channel * (1 - weight) + fg[index]! * weight));
    return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05) >= 4.5;
  });
}

/** One compound: optional type, classes/ids, at most one interaction pseudo-class. No attribute selectors,
 * no structural pseudo-classes (:first-child, :not, :has...), no pseudo-elements, no sibling combinators:
 * those are the ways to style Accept differently from Reject, which the parity rule forbids. */
const COMPOUND = /^(?:[a-z][a-z0-9-]*|\*)?(?:[.#][a-z][\w-]*)*(?::(?:hover|focus|focus-visible|focus-within|active))?$/i;
const ROOTS = /^(?:#jini-consent|\.jini-consent|\.jini-consent-reopen)(?=$|[\s>:])/;

/** Normalized selector, or null when it leaves the banner scope or could break Reject parity. @complexity O(selector length). */
export function scopedSelector(selector: string): string | null {
  const normalized = selector.trim().replace(/\s*>\s*/g, ' > ').replace(/\s+/g, ' ');
  if (!ROOTS.test(normalized)) return null;
  const compounds = normalized.split(' ').filter(part => part !== '>');
  return compounds.every(part => part && COMPOUND.test(part)) ? normalized.replace(/^\.jini-consent(?=$|[\s>:])/, CONSENT_CSS_SCOPE) : null;
}

/** One declaration policy shared by tokens and parsed CSS. @complexity O(value length). */
function declarationProblem({ declaration, selector, media }: { declaration: ConsentCssDeclaration; selector: string; media: string | undefined }): ConsentCssProblem | null {
  const { property, value, offset } = declaration;
  const at = { offset, selector, property };
  if (!Object.hasOwn(VALUE_RULES, property)) return { code: 'property', message: `The property "${property}" is not allowed.`, ...at };
  if (ROOT_ONLY.has(property) && selector !== CONSENT_CSS_SCOPE) return { code: 'property', message: `Set "${property}" on #jini-consent itself so every control inherits the same readable appearance.`, ...at };
  // Conditional palettes would need per-query contrast analysis; width queries customize geometry only.
  if (media && COLOR_PROPS.has(property)) return { code: 'property', message: 'Set text and background colors outside media queries so contrast is verified for every viewport.', ...at };
  if (property === 'padding' && selector === CONSENT_CSS_SCOPE && !lengthList({ value, min: 8 })) return { code: 'value', message: 'Banner padding must be between 8px and 32px on every side.', ...at };
  if (!VALUE_RULES[property]!(value)) return { code: 'value', message: `The value of "${property}" is outside the supported safe subset. Resources and !important are not allowed.`, ...at };
  return null;
}

/** All problems of one rule; any problem drops that rule only. @complexity O(rule size). */
function ruleProblems(rule: ConsentCssRule): ConsentCssProblem[] {
  const problems: ConsentCssProblem[] = [];
  for (const raw of rule.selector.split(',')) {
    const selector = scopedSelector(raw);
    if (!selector) { problems.push({ code: 'selector', message: `"${raw.trim()}" must start with #jini-consent and may not use attribute, structural or sibling selectors (Accept and Reject must look alike).`, offset: rule.offset, selector: raw.trim() }); continue; }
    for (const declaration of rule.declarations) {
      const problem = declarationProblem({ declaration, selector, media: rule.media });
      if (problem) problems.push(problem);
    }
  }
  return problems;
}

/** Convert host tokens to the same declaration AST instead of introducing another validator. @complexity O(tokens). */
function tokenRule(tokens: ConsentAppearanceTokens): ConsentCssRule {
  const declarations = Object.entries(tokens).filter(([, value]) => value !== undefined && value !== '').map(([key, value]) => ({
    property: Object.hasOwn(TOKEN_PROPERTIES, key) ? TOKEN_PROPERTIES[key as keyof ConsentAppearanceTokens] : key,
    value: typeof value === 'string' ? value : '', offset: 0,
  }));
  return { selector: CONSENT_CSS_SCOPE, declarations, offset: 0 };
}

const isRoot = (rule: ConsentCssRule) => rule.media === undefined && rule.selector.split(',').some(s => scopedSelector(s) === CONSENT_CSS_SCOPE);

/** Last root color declaration wins, matching the emitted cascade. Null = no customized color, so the theme
 * colors of the base styles stay in charge; one customized side is checked against the default other side.
 * @complexity O(declarations). */
function finalColors(rules: readonly ConsentCssRule[]): Colors | null {
  let colors: Colors | null = null;
  for (const { property, value } of rules.filter(isRoot).flatMap(rule => rule.declarations)) {
    if (property === 'background-color') colors = { ...(colors ?? DEFAULT_COLORS), background: value };
    if (property === 'color') colors = { ...(colors ?? DEFAULT_COLORS), text: value };
  }
  return colors;
}

/** Engine-owned lock after all customization: the banner stays visible and on top, Reject and Accept share
 * one fill and border, controls inherit the root's validated colors, and the region/GPC variants are
 * CSS-toggled from <html> attributes so the markup is the same for every visitor. Unknown region = strict:
 * the opt-in variant (with Reject) shows unless the client has positively set opt-out. @complexity O(1). */
export function parityCss({ colors }: { colors: Colors | null }): string {
  const root = CONSENT_CSS_SCOPE;
  // Derived text and button fills must use the same validated palette as the root.
  const rootColors = colors ? `--consent-bg:${colors.background}!important;--consent-fg:${colors.text}!important;background:${colors.background}!important;color:${colors.text}!important;` : '';
  return `\n/* ENGINE PARITY BLOCK */
${root}{position:fixed!important;z-index:2147483647!important;visibility:visible!important;opacity:1!important;transform:none!important;clip:auto!important;clip-path:none!important;filter:none!important;pointer-events:auto!important;isolation:isolate!important}
${root}:not([hidden]){display:block!important;${rootColors}background-image:none!important;min-width:0!important;max-height:85dvh!important;overflow:auto!important;box-sizing:border-box!important}
${root}[hidden]{display:none!important}
${root} :is(h2,p,label,legend,fieldset,details,.jini-consent-actions){background:transparent!important}
${root} :is(h2,p,label,legend,details,.jini-consent-actions){color:inherit!important}
${root} .jini-consent-actions{display:grid!important}
${root} :is(button,a,summary){visibility:visible!important;opacity:1!important;transform:none!important;clip-path:none!important;filter:none!important;pointer-events:auto!important;color:inherit!important}
${root} :is(a,summary){background:transparent!important;border:0!important}
${root} .jini-consent-actions button{background:var(--consent-button-bg)!important;border:1px solid var(--consent-button-border)!important}
${root} .jini-consent-actions button:hover{background:var(--consent-button-hover-bg)!important}
${root} .jini-consent-link{background:transparent!important;border:0!important}
${root} button{display:inline-flex!important;align-items:center!important;justify-content:center!important;min-width:0!important;max-width:100%!important;white-space:normal!important;overflow-wrap:anywhere!important}
${root} a{display:inline!important;text-decoration:underline!important}
${root} :focus-visible{outline:3px solid currentColor!important;outline-offset:2px!important}
html[data-consent-region="opt-out"] ${root} [data-consent-only="opt-in"],html:not([data-consent-region="opt-out"]) ${root} [data-consent-only="opt-out"],html:not([data-consent-gpc]) ${root} [data-consent-gpc]{display:none!important}
@media(max-width:640px){${root}{inset:auto 0 0!important;width:100%!important;max-width:100%!important;margin:0!important}}
`;
}

/** Reject syntax that could change token boundaries or break out of the HTML style sink. @complexity O(n). */
function inputProblem(css: unknown): ConsentCssProblem | null {
  // Stored settings are JSON from the host; a wrong shape must not throw at render time.
  if (typeof css !== 'string') return { code: 'syntax', message: 'Custom CSS and appearance tokens must be text and an object of text values.' };
  if (css.length > CONSENT_MAX_CSS_LENGTH) return { code: 'size', message: `Custom CSS must be at most ${CONSENT_MAX_CSS_LENGTH} characters.` };
  // `>` stays parseable for child combinators; `<` alone can open `</style`.
  if (/[\\<\x00-\x08\x0b\x0e-\x1f\x7f]/.test(css)) return { code: 'syntax', message: 'CSS escapes, HTML delimiters and control characters are not allowed.' };
  return null;
}

/** Parsed owner rules, or the one whole-input problem that makes them unreadable. Tokens survive either way. */
function ownerRules(css: unknown): { rules: ConsentCssRule[]; problem?: ConsentCssProblem } {
  const problem = inputProblem(css);
  if (problem) return { rules: [], problem };
  try { return { rules: parseConsentCss({ css: css as string }) }; }
  catch (error) {
    if (!(error instanceof ConsentCssSyntaxError)) throw error;
    return { rules: [], problem: { code: 'syntax', message: error.message, offset: error.offset } };
  }
}

function tokenObject(tokens: unknown): { tokens: ConsentAppearanceTokens; problem?: ConsentCssProblem } {
  const ok = tokens !== null && typeof tokens === 'object' && !Array.isArray(tokens) && JSON.stringify(tokens).length <= CONSENT_MAX_CSS_LENGTH;
  return ok ? { tokens: tokens as ConsentAppearanceTokens } : { tokens: {}, problem: { code: 'syntax', message: 'Appearance tokens must be an object of text values.' } };
}

/** Low contrast drops the root colors only, so the theme palette (and everything else) still applies. */
function withoutRootColors(rules: readonly ConsentCssRule[]): ConsentCssRule[] {
  return rules.map(rule => isRoot(rule) ? { ...rule, declarations: rule.declarations.filter(d => !COLOR_PROPS.has(d.property)) } : rule);
}

/** Emit only validated selectors/declarations, retaining their optional width condition. @complexity O(rule bytes). */
function emitRule(rule: ConsentCssRule): string {
  const css = `${rule.selector.split(',').map(s => scopedSelector(s)).join(',')}{${rule.declarations.map(({ property, value }) => `${property}:${value}`).join(';')}}`;
  return rule.media === undefined ? css : `@media ${rule.media}{${css}}`;
}

/** Validate/compile the banner appearance for both the admin preview and delivery. Tokens render first, then
 * owner CSS, then the engine parity block. Each bad rule is dropped and reported; the rest applies.
 * @example compileConsentCss({ css: '#jini-consent button{font-weight:700}', tokens: { backgroundColor: '#101820', textColor: '#ffffff' } })
 * @complexity O(n) time/space, with custom CSS and tokens each capped at 16 KiB. */
export function compileConsentCss({ css = '', tokens = {} }: { css?: string; tokens?: ConsentAppearanceTokens }, _optional = {}): ConsentCssResult {
  const owner = ownerRules(css);
  const token = tokenObject(tokens);
  const problems = [owner.problem, token.problem].filter((p): p is ConsentCssProblem => !!p);
  let kept: ConsentCssRule[] = [];
  for (const rule of [tokenRule(token.tokens), ...owner.rules]) {
    const found = ruleProblems(rule);
    problems.push(...found);
    if (!found.length && rule.declarations.length) kept.push(rule);
  }
  let colors = finalColors(kept);
  if (colors && !hasContrast(colors)) {
    problems.push({ code: 'contrast', message: 'Banner text must have at least 4.5:1 contrast against the background and button fills. Your colors were not applied.' });
    kept = withoutRootColors(kept).filter(rule => rule.declarations.length);
    colors = null;
  }
  const compiled = kept.map(emitRule).join('\n');
  return { css: `${compiled ? '\n' + compiled : ''}${parityCss({ colors })}`, problems };
}

/** @file Web-standard receipts (Request -> Response): Express, edge workers, serverless functions and Deno mount the
 * same function. The response never sets a cookie: the browser client owns the cookie, so a slow Accept
 * response can't overwrite a newer Reject. */
// MOVED-FROM: @jini-ai/cms consent/policy.ts createConsentRecord/readConsentRecord and consent/express receipt
// handling (origin check, policy race, no IP/user-agent in evidence). TODO(P4): delete the cms copies.
import { ACTIONS, CONSENT_COOKIE, REGION_COOKIE, type Choices, type ConsentAction, type ConsentState, type RegionMode } from '../contract.js';
import { choicesFor, clamp, DEFAULT_MAX_AGE_MS, effective, isFlags, parseStored, RECEIPT_ID, regionFrom } from '../contracts/policy.js';

/** Immutable evidence; no IP, user-agent, or principal identity is collected. */
export interface ConsentRecord { id: string; timestamp: string; policyVersion: string; choices: Choices; regionMode: RegionMode; gpc: boolean; action: ConsentAction }
/** save must be durable before resolving and must not overwrite an existing id. */
export interface ConsentRecordPort {
  save(required: { record: ConsentRecord }, optional?: object): Promise<void>;
  /** Remove a superseded choice from active lookup while retaining its immutable evidence. */
  retire?(required: { id: string }, optional?: object): Promise<void>;
  read?(required: { id: string }, optional?: object): Promise<unknown>;
}
export interface ReceiptPorts {
  store: ConsentRecordPort;
  policy: () => string | Promise<string>;
  /** Unguessable ids matching /^[\w-]{16,128}$/ (crypto.randomUUID() qualifies). */
  ids: () => string;
  now: () => number;
}
export interface ReceiptOptions {
  maxBytes?: number;
  /** The site's configured mode; 'auto' reads the region cookie the host's region middleware set. */
  regionMode?: 'auto' | RegionMode;
  /** Host-owned region answer for this request; overrides regionMode/cookie. */
  region?: (required: { request: Request }) => RegionMode | Promise<RegionMode>;
  /** Host-owned rate limit (the host binds consentRateLimitKey + its limiter). */
  allow?: (required: { request: Request }) => boolean | Promise<boolean>;
}
type Body = { policy?: unknown; choices?: unknown; action?: unknown; gpc?: unknown; previousId?: unknown };

const problem = (status: number, message: string) =>
  new Response(JSON.stringify({ error: message }), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });

/** POST <endpoint>. The host builds `request.url` from its PUBLIC origin so the origin check is meaningful.
 * @example app.post('/_consent', async (req, res) => send(res, await handleReceipt({ request: toRequest(req), ports })))
 * @complexity O(body ≤ maxBytes). */
export async function handleReceipt({ request, ports }: { request: Request; ports: ReceiptPorts }, options: ReceiptOptions = {}): Promise<Response> {
  const refused = await refuse({ request, options });
  if (refused) return refused;
  const body = await readJson({ request, maxBytes: options.maxBytes ?? 2048 });
  if (body instanceof Response) return body;
  const policy = await ports.policy();
  if (body.policy !== policy) return problem(409, 'The privacy policy changed. Reload this page and choose again.');
  const action = body.action as ConsentAction;
  if (!ACTIONS.includes(action)) return problem(400, 'Choose accept, reject, save, do-not-sell or withdraw.');
  const record = await toRecord({ request, body, action, policy, ports, options });
  await ports.store.save({ record });
  await retire({ store: ports.store, previousId: body.previousId });
  return new Response(JSON.stringify({ id: record.id }), { status: 201, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });
}

async function toRecord({ request, body, action, policy, ports, options }: { request: Request; body: Body; action: ConsentAction; policy: string; ports: ReceiptPorts; options: ReceiptOptions }): Promise<ConsentRecord> {
  // eslint-disable-next-line no-restricted-syntax -- the Global Privacy Control request header, not a spec id
  const gpc = request.headers.get('sec-gpc') === '1' || request.headers.get('dnt') === '1' || body.gpc === true;
  const flags = choicesFor({ action, picked: isFlags(body.choices) ? body.choices : {} });
  const regionMode = await (options.region ? options.region({ request }) : regionFrom({ configured: options.regionMode ?? 'auto', hint: cookie(request.headers.get('cookie'), REGION_COOKIE) }));
  return { id: ports.ids(), timestamp: new Date(ports.now()).toISOString(), policyVersion: policy, regionMode, gpc, action, choices: clamp({ flags, gpc }) };
}

async function refuse({ request, options }: { request: Request; options: ReceiptOptions }): Promise<Response | null> {
  if (request.method !== 'POST') return problem(405, 'POST a consent choice.');
  if (request.headers.get('origin') !== new URL(request.url).origin) return problem(403, 'Cross-site consent writes are refused.');
  if (options.allow && !(await options.allow({ request }))) return problem(429, 'Too many choices. Try again in a few minutes.');
  return null;
}

/** The superseded receipt leaves active lookup; its evidence stays. A failed retire never fails the new choice. */
async function retire({ store, previousId }: { store: ConsentRecordPort; previousId: unknown }): Promise<void> {
  if (!store.retire || typeof previousId !== 'string' || !RECEIPT_ID.test(previousId)) return;
  await store.retire({ id: previousId }).catch(() => undefined);
}

async function readJson({ request, maxBytes }: { request: Request; maxBytes: number }): Promise<Body | Response> {
  if (!(request.headers.get('content-type') ?? '').startsWith('application/json')) return problem(415, 'Send the choice as JSON.');
  if (Number(request.headers.get('content-length') ?? 0) > maxBytes) return problem(413, 'The consent choice is too large.');
  const text = await request.text();
  if (text.length > maxBytes) return problem(413, 'The consent choice is too large.');
  try {
    const value = JSON.parse(text) as unknown;
    if (value && typeof value === 'object' && !Array.isArray(value)) return value as Body;
  } catch { /* reported below */ }
  return problem(400, 'Send one JSON consent choice.');
}

/** @complexity O(cookie header). */
function cookie(header: string | null | undefined, name: string): string | null {
  for (const part of (header ?? '').split(/;\s*/)) {
    const at = part.indexOf('=');
    if (at < 1) continue;
    if (part.slice(0, at) !== name) continue;
    try { return decodeURIComponent(part.slice(at + 1)); } catch { return null; }
  }
  return null;
}

/** Server-side read for a host's server-event gate, with the same rule as the browser (durable: an
 * unconfirmed grant is not allowed). The cookie is the visitor's own assertion: good enough to GATE their
 * own events, never proof. Proof is the receipt. No file read per event. @complexity O(cookie header). */
export function readConsent(
  { cookieHeader, policy, regionMode }: { cookieHeader: string | null | undefined; policy: string; regionMode: 'auto' | RegionMode },
  { secGpc, dnt, anonymous = false, nowMs = Date.now(), maxAgeMs = DEFAULT_MAX_AGE_MS, regionHint }: { secGpc?: string | null; dnt?: string | null; anonymous?: boolean; nowMs?: number; maxAgeMs?: number; regionHint?: 'us' | null } = {},
): ConsentState {
  const header = anonymous ? null : cookieHeader;
  const hint = regionHint === undefined ? cookie(header, REGION_COOKIE) : regionHint;
  return effective({ stored: parseStored({ raw: cookie(header, CONSENT_COOKIE) }), policy, gpc: secGpc === '1' || dnt === '1',
    region: regionFrom({ configured: regionMode, hint }), nowMs }, { maxAgeMs, durable: true, anonymous });
}

/**
 * @module origin-validation
 *
 * Same-origin / allow-listed-origin validation for a locally-bound HTTP
 * daemon: is this browser request actually coming from a page the daemon
 * itself served (or an operator-configured allow-listed origin), as
 * opposed to an arbitrary third-party site making a cross-site request to
 * the daemon's loopback/private-LAN port.
 *
 * Generalized from an upstream flat daemon module: the origin hardcoded its
 * host product's env-var names, now fields on
 * {@link OriginValidationEnvConfig} — see `archived provenance ledger` for the exact
 * mapping. One function, a bypass for a specific product's own
 * browser-extension-driven ingest route, was deliberately **not** ported —
 * it names a specific product route and product feature with no generic
 * equivalent; see `archived provenance ledger`.
 */

import type { Logger } from "./primitives/index.js";

export interface ParsedHostHeader {
  hostname: string;
  host: string;
  port: string;
}

export interface RequestWithOriginHeaders {
  headers?: {
    host?: unknown;
    origin?: unknown;
    'sec-fetch-site'?: unknown;
  };
}

/** Names the env vars this port reads. */
export interface OriginValidationEnvConfig {
  /** Env var carrying a comma-separated list of extra allow-listed origins. */
  allowedOriginsEnvVar: string;
  /** Env var carrying an additional browser-facing port to treat as local (e.g. a separate web dev server). */
  webPortEnvVar: string;
  /** Env var carrying the host the daemon itself is bound to (default `'127.0.0.1'`). */
  bindHostEnvVar: string;
}

/** Host-supplied environment snapshot, shared by origin validation helpers. */
export interface OriginValidationArgs {
  config: OriginValidationEnvConfig;
  env: Readonly<Record<string, string | undefined>>;
}

/** Optional diagnostic sink; validation never reads an ambient logger. */
export type OriginValidationLoggerPort = Pick<Logger, "warn">;

/** Splits and trims the configured allow-list into entries. Both lenient request parsing and
 * strict boot validation share this splitter so their definition of one entry cannot drift. */
function splitAllowedOriginsEnv(config: OriginValidationEnvConfig, env: Readonly<Record<string, string | undefined>>): string[] {
  const raw = env[config.allowedOriginsEnvVar] || '';
  if (!raw.trim()) return [];
  return raw
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);
}

/** Parses `value` as a URL, or `undefined` when it is unparseable or not HTTP(S). Shared by
 * allow-list parsing and the Origin check so both agree on what counts as a web origin. */
function parseHttpUrl(value: string): URL | undefined {
  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    return undefined;
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return undefined;
  return parsed;
}

/** Normalizes one entry to a protocol://host origin; invalid or non-HTTP(S) entries are rejected. */
function parseAllowedOrigin(entry: string): string | undefined {
  return parseHttpUrl(entry)?.origin;
}

/**
 * Parses {@link OriginValidationEnvConfig.allowedOriginsEnvVar} into normalized origins.
 *
 * Deliberately never throws — this is on the hot path of {@link isLocalSameOrigin}, called fresh
 * on every same-origin decision a host makes. A malformed entry is dropped and logged instead of
 * aborting the whole parse. A request-time throw used to turn one config typo into
 * either a 500 on every request, or — on a route with no enclosing catch — an unhandled
 * rejection: hand-mounted attachment routes and provider catch-all routes had no common
 * enclosing catch. Dropping the malformed entry degrades to one fewer trusted origin,
 * never every request breaking. Call {@link assertValidAllowedOrigins} once at host startup instead, to fail loudly
 * before any request-serving traffic exists.
 */
export function configuredAllowedOrigins({ config, env }: OriginValidationArgs,
  { logger }: { logger?: OriginValidationLoggerPort | undefined } = {},
): string[] {
  const origins: string[] = [];
  for (const entry of splitAllowedOriginsEnv(config, env)) {
    const origin = parseAllowedOrigin(entry);
    if (origin === undefined) {
      logger?.warn({
        message: `[@jini-ai/core] ignoring malformed ${config.allowedOriginsEnvVar} entry (must be an http:// or https:// origin): ${entry}`,
      });
      continue;
    }
    origins.push(origin);
  }
  return origins;
}

/**
 * Boot-time companion to {@link configuredAllowedOrigins}: throws, naming every malformed entry,
 * instead of silently dropping them. Call once, early in host startup, before the HTTP server
 * accepts connections. A misconfiguration must fail boot loudly rather than quietly serving with
 * a smaller-than-intended allow-list, or throwing on whichever request first reaches the guard.
 */
export function assertValidAllowedOrigins({ config, env }: OriginValidationArgs): void {
  const invalid = splitAllowedOriginsEnv(config, env).filter((entry) => parseAllowedOrigin(entry) === undefined);
  if (invalid.length === 0) return;
  throw new Error(
    `${config.allowedOriginsEnvVar} has ${invalid.length} invalid entr${invalid.length === 1 ? 'y' : 'ies'} ` +
      `(must be http:// or https:// origins): ${invalid.join(', ')}`,
  );
}

/** The `host` (hostname:port) component of each configured allowed origin. */
export function configuredAllowedHosts({ origins }: { origins: string[] }): string[] {
  return origins.map((origin) => new URL(origin).host);
}

/** The set of browser-facing ports considered "local": the daemon's own port plus an optional configured web port. */
export function allowedBrowserPorts(
  { config, port, env }: OriginValidationArgs & { port: number | string | null | undefined },
): number[] {
  const ports = [];
  const primary = Number(port);
  if (primary) ports.push(primary);
  const webPort = Number(env[config.webPortEnvVar]);
  if (webPort && webPort !== primary) ports.push(webPort);
  return ports;
}

/** The loopback spellings a locally-served page's Host or Origin can carry. */
const LOOPBACK_HOSTS = ['127.0.0.1', 'localhost', '[::1]'];

function headerValue(value: unknown): string | undefined {
  if (Array.isArray(value)) {
    const first = value[0];
    return first == null ? undefined : String(first);
  }
  return value == null ? undefined : String(value);
}

/** Parses a raw `Host` header value into hostname/host/port, or `null` when unparseable. */
export function parseHostHeader({ value }: { value: unknown }): ParsedHostHeader | null {
  const raw = String(headerValue(value) || '').trim();
  if (!raw) return null;
  try {
    const parsed = new URL(`http://${raw}`);
    return { hostname: parsed.hostname, host: parsed.host, port: parsed.port || '80' };
  } catch {
    return null;
  }
}

type Octets = [number, number, number, number];

/** Parses an exact dotted-quad (four all-digit parts, each 0-255) into octets, else `undefined`.
 * Shared by the private-range and IP-literal checks so both agree on what an IPv4 literal is.
 * `/^\d+$/` admits only non-negative integers, so the octet range check needs only an upper bound. */
function parseDottedQuad(host: string): Octets | undefined {
  const parts = host.split('.');
  if (parts.length !== 4) return undefined;
  if (!parts.every((part) => /^\d+$/.test(part))) return undefined;
  const octets = parts.map(Number);
  return octets.every((n) => n <= 255) ? (octets as Octets) : undefined;
}

/** RFC 1918 (10/8, 172.16/12, 192.168/16) or link-local (169.254/16), from the first two octets. */
function isPrivateIpv4Prefix([a, b]: Octets): boolean {
  if (a === 10) return true;
  if (a === 172) return b >= 16 && b <= 31;
  if (a === 192) return b === 168;
  return a === 169 && b === 254;
}

/** Whether `hostname` is an RFC 1918 private IPv4 address (10/8, 172.16/12, 192.168/16) or link-local (169.254/16).
 * Implements the dev-browser LAN allow-list, not SSRF blocking. Use @jini-ai/platform/net
 * for SSRF address classification; private addresses are allowed here for local development. */
export function isPrivateIpv4({ hostname }: { hostname: unknown }): boolean {
  const octets = parseDottedQuad(String(hostname || ''));
  return octets !== undefined && isPrivateIpv4Prefix(octets);
}

/** Whether `hostname` is a literal IPv4 address or bracketed IPv6 literal (as opposed to a DNS name). */
export function isIpLiteralHostname({ hostname }: { hostname: unknown }): boolean {
  const host = String(hostname || '').trim();
  if (!host) return false;
  if (host.startsWith('[') && host.endsWith(']')) return true;
  return parseDottedQuad(host) !== undefined;
}

const LOOPBACK_OR_UNSPECIFIED_HOSTS: ReadonlySet<string> = new Set(['localhost', '127.0.0.1', '::1', '[::1]', '0.0.0.0', '::']);

/** Whether `hostname` is loopback, unspecified, or a private-LAN address.
 * Implements the dev-browser LAN allow-list, not SSRF blocking (@jini-ai/platform/net). */
export function isLoopbackOrPrivateLanHost({ hostname }: { hostname: unknown }): boolean {
  const host = String(hostname || '').toLowerCase();
  return LOOPBACK_OR_UNSPECIFIED_HOSTS.has(host) || isPrivateIpv4({ hostname: host });
}

/** Whether a request's `Host` header names a locally-served or explicitly allow-listed host. */
export function isAllowedBrowserHost(
  { hostHeader, ports, bindHost, extraAllowedOrigins }: {
    config: OriginValidationEnvConfig; hostHeader: unknown; ports: number[]; bindHost: string; extraAllowedOrigins: string[];
  },
): boolean {
  const requestHost = parseHostHeader({ value: hostHeader });
  if (!requestHost) return false;

  const explicitHosts = new Set([
    ...ports.flatMap((p) => [...LOOPBACK_HOSTS.map((h) => `${h}:${p}`), `${bindHost}:${p}`]),
    ...configuredAllowedHosts({ origins: extraAllowedOrigins }),
  ]);
  if (explicitHosts.has(requestHost.host)) return true;

  if (!ports.map(String).includes(requestHost.port)) return false;
  return isLoopbackOrPrivateLanHost({ hostname: requestHost.hostname });
}

/** Every `scheme://host:port` origin a locally-served page can have: loopback spellings and the bind host, over both schemes. */
function explicitLocalOrigins(ports: number[], bindHost: string): Set<string> {
  const hosts = [...LOOPBACK_HOSTS, bindHost];
  return new Set(ports.flatMap((p) => ['http', 'https'].flatMap((s) => hosts.map((h) => `${s}://${h}:${p}`))));
}

/** The URL's port, or its scheme's default when the URL omits it (only http/https reach here). */
function effectivePort(url: URL): string {
  return url.port || (url.protocol === 'https:' ? '443' : '80');
}

/** Whether an `Origin` header value names a locally-served or explicitly allow-listed origin. */
export function isAllowedBrowserOrigin(
  { origin, hostHeader, ports, bindHost, extraAllowedOrigins }: {
    config: OriginValidationEnvConfig; origin: unknown; hostHeader: unknown; ports: number[]; bindHost: string; extraAllowedOrigins: string[];
  },
): boolean {
  const originText = String(origin);
  if (extraAllowedOrigins.includes(originText)) return true;

  const parsedOrigin = parseHttpUrl(originText);
  if (!parsedOrigin) return false;

  const requestHost = parseHostHeader({ value: hostHeader });
  if (!requestHost) return false;

  if (explicitLocalOrigins(ports, bindHost).has(originText)) return true;

  if (!ports.map(String).includes(effectivePort(parsedOrigin))) return false;
  if (parsedOrigin.hostname !== requestHost.hostname) return false;
  return isLoopbackOrPrivateLanHost({ hostname: parsedOrigin.hostname });
}

type BrowserHostArgs = Omit<Parameters<typeof isAllowedBrowserHost>[0], 'extraAllowedOrigins'>;

/** The decision for a request carrying no `Origin` header (as a same-origin GET subresource does). */
function isAllowedWithoutOrigin(
  { req, hostArgs, extraAllowedOrigins }: { req: RequestWithOriginHeaders; hostArgs: BrowserHostArgs; extraAllowedOrigins: string[] },
): boolean {
  const ipOnlyExtraOrigins = extraAllowedOrigins.filter((o) => isIpLiteralHostname({ hostname: new URL(o).hostname }));
  if (isAllowedBrowserHost({ ...hostArgs, extraAllowedOrigins: ipOnlyExtraOrigins })) return true;
  // Browsers (Firefox, Chrome) omit Origin on same-origin GET subresource
  // requests per the Fetch spec, which makes hostname entries in the
  // allow-list unreachable for legitimate same-origin GETs through a
  // reverse proxy. Sec-Fetch-Site is set by the user agent and cannot be
  // modified by JavaScript, so a value of "same-origin" attests that the
  // request originated from the same origin as the target — a cross-site
  // `<img>`/`<script>` exploit would carry "cross-site" instead. Only
  // consult the broader allow-list once that signal is present.
  if (headerValue(req.headers?.['sec-fetch-site']) !== 'same-origin') return false;
  return isAllowedBrowserHost({ ...hostArgs, extraAllowedOrigins });
}

/**
 * The top-level same-origin gate: is `req` a request the daemon should treat
 * as coming from one of its own locally-served (or explicitly allow-listed)
 * pages.
 */
export function isLocalSameOrigin(
  { config, req, port, env }: OriginValidationArgs & {
    req: RequestWithOriginHeaders; port: number | string | null | undefined;
  },
  { logger }: { logger?: OriginValidationLoggerPort | undefined } = {},
): boolean {
  const host = String(headerValue(req.headers?.host) || '');
  const origin = headerValue(req.headers?.origin);
  const ports = allowedBrowserPorts({ config, port, env });
  const bindHost = env[config.bindHostEnvVar] || '127.0.0.1';
  const extraAllowedOrigins = configuredAllowedOrigins({ config, env }, { logger });

  if (origin == null || origin === '') {
    return isAllowedWithoutOrigin({ req, hostArgs: { config, hostHeader: host, ports, bindHost }, extraAllowedOrigins });
  }
  // Reverse-proxy deployments terminate the browser connection at the proxy
  // and open a fresh upstream connection to the daemon. The Host header the
  // daemon sees is the proxy upstream's address, not the browser-visible
  // origin, so the host check below fails even when the user explicitly
  // listed their proxy origin in the allow-list. Trust the Origin header in
  // that case: a client-supplied origin that exactly matches an explicitly
  // allow-listed entry is the documented escape hatch for these deployments.
  if (extraAllowedOrigins.includes(origin)) return true;
  if (!isAllowedBrowserHost({ config, hostHeader: host, ports, bindHost, extraAllowedOrigins })) return false;
  return isAllowedBrowserOrigin({ config, origin, hostHeader: host, ports, bindHost, extraAllowedOrigins });
}

/** Unbranded identifier; UUID-producing adapters and opaque host IDs share this port. */
export type UUID = string;

export interface IdGenerator { newId(): string }

/** Uses the host's cryptographic UUID generator; no insecure random fallback. */
export function createRandomUuidGenerator(): IdGenerator {
  return { newId: () => globalThis.crypto.randomUUID() };
}

/** Unbranded wire timestamp: hosts can share clocks without conversion adapters. */
export type ISODateTime = string;

/** Milliseconds since the Unix epoch. Zero-argument getters need no empty argument object. */
export interface Clock { nowMs(): number }

/** Default wall clock; inject a Clock to control time in application code. */
export function createSystemClock(): Clock {
  return { nowMs: () => Date.now() };
}

/** Converts epoch milliseconds using the standard UTC ISO representation. Invalid time throws. */
export function toIsoDateTime({ epochMs }: { epochMs: number }): ISODateTime {
  return new Date(epochMs).toISOString();
}

/** Samples the supplied clock once and formats its time in UTC. */
export function nowIso({ clock }: { clock: Clock }): ISODateTime {
  return toIsoDateTime({ epochMs: clock.nowMs() });
}

/**
 * Shared surface-exchange ABI. The daemon owns the store and ask/report implementation;
 * consumers inject those ports without depending on the daemon runtime.
 */
import type { SurfaceEmission, SurfaceEmitter } from './tool-registry.js';

/**
 * The callback param carrying an exchange id from a rendered surface back to the server.
 *
 * Double-underscored to keep it clear of a surface's real fields, and named in one place because
 * three parties must agree on it: whatever builds the surface, the route that routes on it, and the
 * handler that opened the exchange.
 *
 * This is MCP-UI's carrier specifically, because an mcp-ui surface can only answer by issuing a tool
 * call, so its correlation has to ride inside that call's params. A channel that can name the
 * exchange directly should do so — `mcp-ui-tool-calls-route.ts` also accepts a top-level
 * `exchangeId`, and A2UI/`surface_request` correlate by their own `surfaceId`.
 */
export const SURFACE_EXCHANGE_ID_PARAM = '__exchangeId';
/**
 * The callback param a surface's Cancel action sets, so a dismissal resolves the exchange
 * immediately instead of stranding the agent until the idle deadline.
 *
 * Carried as data rather than as a distinct {@link SurfaceMessage} status: "the human answered, and
 * the answer was no" is genuinely an answer, and only the tool that built the surface knows what a
 * dismissal means for its own result.
 */
export const SURFACE_DISMISSED_PARAM = '__dismissed';
/**
 * The callback param carrying free text a human TYPED — into the chat composer — as their answer to
 * an outstanding surface, rather than clicking the rendered form.
 *
 * ## The deadlock this exists to break
 *
 * A held-open exchange can only be resolved by a message that names it, and until now every param
 * shape a surface posts back was one the FORM produced. A human who reads the question, ignores the
 * dialog and types the answer into the composer therefore resolved nothing: their message was queued
 * behind the very run it was meant to unblock, and the agent sat parked until the idle deadline
 * fired minutes later.
 *
 * ## Why it is a separate param rather than the tool's own answer fields
 *
 * Prose is not a selection. A tool whose answer fields are option VALUES the model itself supplied
 * (`assistant_ask_choice`'s `choice`/`selections`) would, if prose were poured into them, report to
 * the model that the administrator picked an option that was never offered. Carrying typed text
 * under its own name is what forces each tool to decide, explicitly, what a typed answer means for
 * its own result — and lets a tool that has no safe reading of one simply ignore it.
 *
 * ## What it deliberately cannot do
 *
 * It cannot confirm anything. `classifyConfirmationAnswer` reads only a literal `decision:
 * "confirm"`, so a typed answer arriving at a confirmation-shaped exchange fails closed to
 * `"declined"` with no code change and no exception — which is the correct reading of "the human
 * wrote a sentence instead of clicking Confirm". Nothing here should ever grow a prose-to-consent
 * mapping.
 *
 * Double-underscored, and named here rather than at a tool, for the same reason as
 * {@link SURFACE_EXCHANGE_ID_PARAM}: several parties must agree on the spelling.
 */
export const SURFACE_TYPED_ANSWER_PARAM = '__typedAnswer';
/**
 * Which inbound route may answer an exchange. `"mcp-ui"` (the host's default) is a tool-call-shaped answer
 * posted to the MCP-UI route; `"a2ui"` is a renderer message posted to the A2UI route. A2UI posts
 * carry no `toolId`, so without this an A2UI message could land in, and cancel, a pending MCP-UI
 * confirmation of the same principal.
 */
export type SurfaceAnswerChannel = string;
/** Who an exchange belongs to. Checked on every delivery; a mismatch is a rejection, not a warning. */
export interface SurfaceExchangeBinding {
  /** The tool that opened it. A message for one tool cannot resolve another's exchange. */
  readonly toolId: string;
  /** The principal whose run opened it: one human's answer must not land in another's call. */
  readonly principalId: string;
  /** The route allowed to answer it; omission uses the store's injected default channel. */
  readonly channel?: SurfaceAnswerChannel;
}
/**
 * One inbound message, or the reason there will not be one.
 *
 * The non-`received` cases are part of the contract rather than error handling (ADR-055 Decision 6):
 * blocking moves the timeout story, it does not remove it, and a handler must be able to tell the
 * model something true about which happened.
 */
export type SurfaceMessage = { status: 'received'; params: Record<string, unknown> } | { status: 'expired' } | { status: 'abandoned' };
/** Why a delivery did not reach an exchange. Reported to the browser, never to the model. */
export type SurfaceDeliveryRejectionReason = 'unknown-or-closed' | 'binding-mismatch';
export type DeliverResult = { ok: true } | { ok: false; reason: SurfaceDeliveryRejectionReason };
/** A live, two-way conversation bound to one in-flight tool call. */
export interface SurfaceExchange {
  /** Correlation handle embedded in the human's answer carrier; not a secret. */
  readonly id: string;
  /**
   * Sends one message out to the human.
   *
   * @throws {Error} If the exchange has already ended — the same posture the daemon's emitter takes,
   * because a message sent onto a settled call has no way to be answered.
   */
  send(args: { emission: SurfaceEmission }, optional?: Record<string, never>): Promise<void>;
  /**
   * Waits for the next inbound message.
   *
   * Returns a buffered one immediately if the human answered while the handler was busy. Once the
   * exchange has ended, returns that terminal status rather than hanging — so a handler looping on
   * `receive()` terminates instead of waiting out the transport.
   */
  receive(_args: Record<string, never>, optional?: Record<string, never>): Promise<SurfaceMessage>;
  /** Ends the exchange idempotently. Pending receives resolve "abandoned"; an ended exchange is unchanged. */
  close(_args: Record<string, never>, optional?: Record<string, never>): void;
  /**
   * When the exchange expires if nothing more happens, in epoch ms: the earlier of the idle and
   * lifetime deadlines. Activity moves the idle one, so read it right before rendering a deadline
   * for the human; a card drawn just before its `send()` shows a deadline a few ms early, never late.
   */
  expiresAtMs(): number;
}
/** Messaging helpers do not require deadline tracking. Hosts may supply a conversation port
 * without a deadline; the daemon store always returns the full, dated SurfaceExchange. */
export type SurfaceExchangeConversation = Omit<SurfaceExchange, 'expiresAtMs'> & Partial<Pick<SurfaceExchange, 'expiresAtMs'>>;
/**
 * What a delivery must prove about itself. `principalId` is load-bearing for every channel — one
 * human's answer must never land in another's call. `toolId` is load-bearing only for a channel
 * whose correlation carrier is itself a tool call: MCP-UI's surface can only answer by issuing one,
 * so it always has a real tool name to offer, and the store checks it.
 *
 * A channel that correlates directly by its own id — A2UI's `surfaceId`, the run protocol's own
 * `surface_request`/`surface_response` — has no natural `toolId` to supply; the browser never
 * learns which tool opened the exchange, only its id. Requiring one anyway would force such a
 * channel to either lie (send a placeholder that means nothing) or grow a lookup this store does
 * not expose. So `toolId` is optional here: when a caller supplies it, it must still match exactly
 * (MCP-UI's behavior is unchanged, byte for byte); when omitted, only `principalId` and the
 * exchange's own unguessable `randomUUID()` id gate the delivery. That pair is still sufficient —
 * the id is not enumerable, and `principalId` is a server-verified session identity, never a value
 * the browser chooses (see `run-ownership.ts`) — so relaxing the caller's OBLIGATION does not
 * relax the exchange's own binding, which `open()` still records honestly as whatever tool actually
 * opened it.
 */
export interface SurfaceDeliverySpec {
  exchangeId: string; params: Record<string, unknown>; principalId: string; toolId?: string; channel?: SurfaceAnswerChannel;
}
export interface SurfaceExchangeStore {
  /**
   * Opens an exchange bound to one in-flight tool call.
   *
   * @param args.emit - The call's live {@link SurfaceEmitter}. Required, not optional: an exchange whose
   * messages cannot reach anybody is a guaranteed deadlock, and taking the emitter here is what makes
   * that state unrepresentable rather than merely discouraged.
   */
  open(args: { binding: SurfaceExchangeBinding; emit: SurfaceEmitter }, optional?: Record<string, never>): SurfaceExchange;
  /**
   * Routes one inbound message to the exchange it names, queueing it if nothing is waiting yet.
   * See {@link SurfaceDeliverySpec} for why `toolId` is optional rather than part of
   * {@link SurfaceExchangeBinding} here.
   */
  deliver(requiredArgs: Pick<SurfaceDeliverySpec, 'exchangeId' | 'params' | 'principalId'>, optionalArgs?: Pick<SurfaceDeliverySpec, 'toolId' | 'channel'>): DeliverResult;
  /**
   * Resolves which open exchange a TYPED answer is for, when the human named none.
   *
   * A person typing into the chat composer does not know exchanges exist, so they cannot carry a
   * {@link SURFACE_EXCHANGE_ID_PARAM} the way a rendered form does. This store is the only thing
   * that knows what is open, so the correlation is recovered here rather than guessed by a client
   * scraping an id out of the surface's own (model-influenced) HTML.
   *
   * Scoped by `toolId` as well as `principalId` on purpose: it is an OPT-IN, not a broadcast. Only
   * a tool that has a safe reading of prose should ever be named here, which is what keeps typed
   * text away from confirmation-shaped exchanges (see {@link SURFACE_TYPED_ANSWER_PARAM}).
   *
   * @returns The single matching open exchange's id, or `undefined` when there is none — or more
   * than one. Ambiguity fails closed: delivering to the wrong one would silently answer a question
   * the human was not looking at, and report their words as an answer to it.
   * @complexity O(n) in the number of open exchanges, which is bounded by concurrent agent runs.
   */
  findTypedAnswerTarget(args: { principalId: string; toolId: string }, optional?: Record<string, never>): string | undefined;
  /** Open, unsettled count — for tests and diagnostics only. */
  size(): number;
}

/** Send a form, handle its answer, report the outcome, and finally close the exchange.
 * Supply `askThenReport` from `@jini-ai/daemon/surface-exchanges` at the host boundary. */
export type SurfaceAskThenReport = <Result>(args: {
  exchange: SurfaceExchangeConversation;
  confirmationEmission: SurfaceEmission;
  handle: (answer: SurfaceMessage) => Promise<{ result: Result; outcome?: SurfaceEmission }>;
}, optional?: Record<string, never>) => Promise<Result>;

