/**
 * @module kernel-base
 *
 * The infrastructure every composition owns regardless of which features it activates: the durable
 * (or in-memory) event log, the run lifecycle, the byte journal, the agent executor, the one shared
 * `ToolRegistry`/`ToolExecutor` pair, and — for sqlite storage — the raw database connection.
 *
 * **The database connection belongs here, not to a feature.** It is borrowed by the readiness probe
 * (`health`), by the raw db-operations tools (`daemonDb`), and by the durable tool catalog
 * (`toolCatalog`) — three independently-selectable features. Had any one of them owned it, disabling
 * that feature would have silently broken the others: turning off `daemonDb` would leave `health`'s
 * readiness probe with nothing to check, which is a much worse failure than the one it was meant to
 * simplify, because a readiness probe that stops probing still answers `200`. Ownership by the base,
 * borrowing by features, is what makes the feature set genuinely independent.
 */
import { openSqliteConnection, type SqliteDb, type SqliteSyncOpener } from '@jini-ai/db/sqlite';
import { join } from 'node:path';
import { createNativeAgentRuntime, type AiTraceSink, type NativeAgentRuntime } from '@jini-ai/agent-runtime';

import { createToolRegistry, type ToolRegistry } from '@jini-ai/core';
import {
  createAgentExecutor,
  createInMemoryEventLog,
  createRunByteJournal,
  createRunLifecycle,
  createToolExecutor,
  resumableFromProcessExit,
  withAiTracing,
  type AiTracingOptions,
  type AgentExecutor,
  type EventLog,
  type RunLifecycle,
  type RunRetrySideEffectState,
  type ToolExecutor,
} from '@jini-ai/daemon';
import { openSqliteEventLog } from '@jini-ai/daemon/store/event-log/sqlite';

/** Where a composition's durable state lives. */
export type JiniKernelStorage =
  /** No files touched. Runs and their events vanish with the process — right for tests and for an
   * embedded host that treats runs as ephemeral. Features needing a real database file
   * (`daemonDb`, `toolCatalog`, `xai`) cannot be activated against it. */
  | { readonly kind: 'memory' }
  /** `<dataDir>/events.db` + `<dataDir>/journal.db`. The directory must already exist. */
  | { readonly kind: 'sqlite'; readonly dataDir: string; readonly open: SqliteSyncOpener };

/** The raw sqlite handle and its path, borrowed by `health`/`daemonDb`/`toolCatalog`. */
export interface KernelSqliteAccess {
  readonly connection: SqliteDb;
  readonly eventsDbPath: string;
  readonly dataDir: string;
}

/**
 * An `EventLog` that may or may not hold an OS resource. `@jini-ai/daemon/store/event-log/sqlite`'s `SqliteEventLog` adds
 * `close({})`; `@jini-ai/daemon`'s in-memory reference adapter has nothing to release and so declares
 * none. Modelling `close` as optional lets the base treat both storage kinds uniformly instead of
 * branching on which one it happens to hold.
 */
export type ClosableEventLog = EventLog & { close?: (requiredArgs: Record<string, never>) => Promise<void> };

export interface JiniKernelBase {
  readonly eventLog: ClosableEventLog;
  readonly journalEventLog: ClosableEventLog;
  readonly lifecycle: RunLifecycle;
  readonly agentExecutor: AgentExecutor;
  /** One runtime shared by this kernel's discovery and executor paths. */
  readonly agentRuntime: NativeAgentRuntime;
  /** The single registry every active feature's tools land in, and the only one `toolExecutor` reads. */
  readonly registry: ToolRegistry;
  readonly toolExecutor: ToolExecutor;
  /** `null` under memory storage. Owned here; features borrow and must never close it. */
  readonly sqlite: KernelSqliteAccess | null;
  /** Closes every handle this base opened, in the same order the standalone daemon always has. */
  close(): Promise<void>;
}

export interface CreateJiniKernelBaseOptions {
  readonly storage: JiniKernelStorage;
  /** Extra `createAgentExecutor` options (e.g. `mcpJsonInjection`). `lifecycle`/`journal`/`classifyFailure` are kernel-owned. */
  readonly agentExecutor?: Omit<NonNullable<Parameters<typeof createAgentExecutor>[1]>, 'journal' | 'classifyFailure'>;
  /** Optional AI-run tracing: every run's normalized agent events are also recorded to `sink`. Absent = no tracing, no cost. */
  readonly aiTrace?: AiTracingOptions & { readonly sink: AiTraceSink };
}

/**
 * The zero-config retry classifier every composition gets. Delegates entirely to `@jini-ai/daemon`'s
 * `resumableFromProcessExit` — see that function's own doc for the classification policy.
 */
export function classifyRunFailureForRetry(context: {
  code: number | null;
  signal: string | null;
  sideEffects?: Pick<RunRetrySideEffectState, 'userVisibleOutputSeen' | 'toolCallSeen'>;
}): boolean {
  return resumableFromProcessExit({ code: context.code, signal: context.signal },
    context.sideEffects === undefined ? {} : { sideEffects: context.sideEffects });
}

function tracedIfConfigured(lifecycle: RunLifecycle, aiTrace: CreateJiniKernelBaseOptions['aiTrace']): { lifecycle: RunLifecycle; disposeTracing: () => void } {
  if (!aiTrace) return { lifecycle, disposeTracing: () => {} };
  const { sink, ...options } = aiTrace;
  const traced = withAiTracing({ lifecycle, sink }, options);
  return { lifecycle: traced, disposeTracing: traced.dispose };
}

async function closeFailedAcquisition(
  { featureConnection, opened }: { featureConnection: SqliteDb | undefined; opened: readonly ClosableEventLog[] },
  _optional: Record<string, never> = {},
): Promise<void> {
  // Every acquired handle is attempted even if another closer fails. Preserve the boot error.
  try { featureConnection?.close(); } catch { /* Keep the boot failure. */ }
  await Promise.allSettled(opened.map((log) => log.close?.({})));
}

function createKernelAgentRuntime(
  { options }: { options: CreateJiniKernelBaseOptions },
  _optional: Record<string, never> = {},
): NativeAgentRuntime {
  const agentRuntime = createNativeAgentRuntime({ env: options.agentExecutor?.hostEnv ?? process.env }, {
    ...(options.agentExecutor?.runtimeState ? { state: options.agentExecutor.runtimeState } : {}),
    ...(options.agentExecutor?.codexDisablePlugins !== undefined ? { codexDisablePlugins: options.agentExecutor.codexDisablePlugins } : {}),
    ...(options.agentExecutor?.piGracefulShutdownMs !== undefined ? { piGracefulShutdownMs: options.agentExecutor.piGracefulShutdownMs } : {}),
  });
  return agentRuntime;
}

/**
 * Opens every kernel-owned resource and rehydrates durable run history.
 *
 * @throws If rehydration fails against a corrupt or unreadable durable history. Every handle this
 * call had already opened is closed before it rethrows, so a failed boot never leaks a sqlite file
 * handle — the invariant the standalone daemon has always maintained.
 */
export async function createJiniKernelBase(options: CreateJiniKernelBaseOptions): Promise<JiniKernelBase> {
  const sqliteStorage = options.storage.kind === 'sqlite' ? options.storage : null;
  const dataDir = sqliteStorage?.dataDir ?? null;
  const eventsDbPath = dataDir === null ? null : join(dataDir, 'events.db');

  // One acquisition block, one cleanup path — and **every** acquisition is inside it. Opening even
  // the first event log outside the block would reintroduce exactly the leak this shape exists to
  // prevent: `events.db` opens, `journal.db` fails (corrupt file, or a directory sitting where a
  // database was expected), and the first handle stays open for the lifetime of a process that has
  // no kernel. The second sqlite connection and the rehydration are grouped here for the same
  // reason: all four can fail after handles are already open, and two try/catch blocks with
  // near-identical cleanup is how one of them eventually drifts and starts leaking.
  const opened: ClosableEventLog[] = [];
  const openEventLog = (path: string | null): ClosableEventLog => {
    let log: ClosableEventLog;
    if (path === null) log = createInMemoryEventLog({});
    else {
      // A non-null path is derived only from sqliteStorage above.
      log = openSqliteEventLog({ file: path, open: sqliteStorage!.open });
    }
    opened.push(log);
    return log;
  };

  let sqlite: KernelSqliteAccess | null = null;
  let featureConnection: SqliteDb | undefined;
  let eventLog!: ClosableEventLog;
  let journalEventLog!: ClosableEventLog;
  let lifecycle!: RunLifecycle;
  let disposeTracing = (): void => {};
  let journal!: ReturnType<typeof createRunByteJournal>;
  try {
    eventLog = openEventLog(eventsDbPath);
    // Gap 1's byte journal gets its own store, deliberately separate from `eventLog`: that log
    // replays every entry it holds to SSE subscribers as a `RunProtocolEvent`, and a journal entry
    // has no corresponding protocol-event kind.
    journalEventLog = openEventLog(dataDir === null ? null : join(dataDir, 'journal.db'));

    if (sqliteStorage && eventsDbPath !== null && dataDir !== null) {
      // A *second* connection to the same `events.db` the log above owns — safe: both run in WAL
      // mode, which permits multiple concurrently open handles on one file within a single process.
      featureConnection = openSqliteConnection({ filePath: eventsDbPath, open({ filePath }, settings) {
        featureConnection = sqliteStorage.open(filePath, settings);
        return featureConnection;
      } });
      sqlite = { connection: featureConnection, eventsDbPath, dataDir };
    }

    journal = createRunByteJournal({ eventLog: journalEventLog });
    ({ lifecycle, disposeTracing } = tracedIfConfigured(createRunLifecycle({ eventLog }), options.aiTrace));
    await lifecycle.rehydrate({});
  } catch (error) {
    await closeFailedAcquisition({ featureConnection, opened });
    throw error;
  }

  const agentRuntime = createKernelAgentRuntime({ options });
  const agentExecutor = createAgentExecutor({ lifecycle }, {
    ...options.agentExecutor,
    runtimeState: agentRuntime.state,
    hostEnv: agentRuntime.hostEnv,
    codexDisablePlugins: agentRuntime.codexDisablePlugins,
    piGracefulShutdownMs: agentRuntime.piGracefulShutdownMs,
    journal,
    classifyFailure: classifyRunFailureForRetry,
  });

  const registry = createToolRegistry({});
  // Created eagerly against the still-empty registry, and that is correct: `ToolExecutor` resolves
  // a registration at execute time, not at construction, so features composed later can contribute
  // tools this executor will find. It is what lets a feature's routes take the executor as a
  // dependency while its own tools register in the same pass.
  const toolExecutor = createToolExecutor({ registry });

  let closed: Promise<void> | null = null;
  return {
    eventLog,
    journalEventLog,
    lifecycle,
    agentExecutor,
    agentRuntime,
    registry,
    toolExecutor,
    sqlite,
    close(): Promise<void> {
      closed ??= (async () => {
        try { await agentRuntime.dispose({}); } finally {
          // After the runtime stops its runs (their traces finish with real outcomes); releases the
          // traces and terminal waits still open so a retained kernel keeps none of them. Never throws.
          disposeTracing();
          try { sqlite?.connection.close(); } finally {
            await Promise.all([eventLog.close?.({}), journalEventLog.close?.({})]);
          }
        }
      })();
      return closed;
    },
  };
}

import type { BootResult, ReadinessStore } from './boot-lifecycle.js';

function copy(snapshot: BootResult): BootResult {
  return { ok: snapshot.ok, modules: snapshot.modules.map(module => ({
    ...module, lifecycle: { ...module.lifecycle },
  })) };
}

/** Instance-owned snapshots. Host-specific health records are supplied by the caller. */
export function createReadinessStore(
  required: Record<string, never>,
  optional: { initial?: BootResult } = {},
): ReadinessStore {
  void required;
  let snapshot = copy(optional.initial ?? { ok: true, modules: [] });
  return {
    set({ snapshot: next }) { snapshot = copy(next); },
    get() { return copy(snapshot); },
  };
}

/**
 * @module backend-config
 *
 * Resolves which SQL backend a host daemon should use from environment
 * variables. v1 ships local SQLite via an injected `better-sqlite3` opener (the event-log adapter
 * now belongs to the daemon's storage subpath);
 * a `postgres` selection is recorded so a future adapter can read it, but
 * `resolveSqliteBackendConfig` never opens a connection itself — it only
 * pins the parameter surface (host/port/database/user/sslMode) so a
 * follow-up package can land the adapter without re-litigating the env-var
 * contract.
 */

export type SqliteBackendKind = 'sqlite' | 'postgres';

export interface SqliteBackendConfig {
  kind: SqliteBackendKind;
  /** Resolution metadata a future Postgres adapter will read. */
  postgres?: {
    host: string;
    port: number;
    database: string;
    user: string;
    /**
     * Password / connection string are looked up at runtime from the
     * caller's own secret manager; this layer never reads them through env.
     */
    sslMode?: 'disable' | 'require' | 'verify-full';
  };
}

export class SqliteBackendConfigError extends Error {
  constructor({ message }: { message: string }) {
    super(message);
    this.name = 'SqliteBackendConfigError';
  }
}

/** Normalizes an explicit SSL mode; unknown values fail rather than weakening verification. */
function resolvePostgresSslMode(
  required: { env: Record<string, string | undefined> },
  _optional: Record<string, never> = {},
): 'disable' | 'require' | 'verify-full' {
  const mode = (required.env.JINI_PG_SSL_MODE ?? 'require').trim().toLowerCase();
  if (mode === 'disable' || mode === 'require' || mode === 'verify-full') return mode;
  throw new SqliteBackendConfigError({ message:
    'JINI_PG_SSL_MODE must be "disable", "require", or "verify-full".',
  });
}

/** Defaults only an omitted port; explicit values must be decimal integers in 1..65535. */
function resolvePostgresPort(
  required: { env: Record<string, string | undefined> },
  _optional: Record<string, never> = {},
): number {
  const value = (required.env.JINI_PG_PORT ?? '5432').trim();
  const port = Number(value);
  if (!/^\d+$/.test(value) || !Number.isInteger(port) || port < 1 || port > 65535) {
    throw new SqliteBackendConfigError({ message: 'JINI_PG_PORT must be an integer between 1 and 65535.' });
  }
  return port;
}

function resolvePostgresConfig(
  required: { env: Record<string, string | undefined> },
  _optional: Record<string, never> = {},
): SqliteBackendConfig {
  const e = required.env;
  const host = e.JINI_PG_HOST ?? '';
  const port = resolvePostgresPort({ env: e });
  const database = e.JINI_PG_DATABASE ?? '';
  const user = e.JINI_PG_USER ?? '';
  const sslMode = resolvePostgresSslMode({ env: e });
  if (!host || !database || !user) {
    throw new SqliteBackendConfigError({ message:
      'JINI_SQLITE_BACKEND=postgres requires JINI_PG_HOST, JINI_PG_DATABASE, JINI_PG_USER. ' +
        'JINI_PG_PORT defaults to 5432; JINI_PG_SSL_MODE defaults to "require".',
    });
  }
  return {
    kind: 'postgres',
    postgres: { host, port, database, user, sslMode },
  };
}

/**
 * Reads `JINI_SQLITE_BACKEND` (`'sqlite'` default, or `'postgres'`) and, for
 * `postgres`, `JINI_PG_HOST`/`JINI_PG_PORT`/`JINI_PG_DATABASE`/`JINI_PG_USER`/
 * `JINI_PG_SSL_MODE` from the given env map (defaults to `process.env`).
 *
 * @param required - No required configuration values; pass an empty argument object.
 * @param optional.env - Environment map to read from. Defaults to `process.env`.
 * @returns The resolved backend config.
 * @throws {SqliteBackendConfigError} When `kind` is unrecognized, or `postgres`
 *   is selected without the required host/database/user, with an unknown SSL mode,
 *   or with an invalid port. Omitted port/SSL mode default to 5432/"require";
 *   explicit SSL modes are trimmed and lowercased before validation.
 */
export function resolveSqliteBackendConfig(
  required: Record<string, never>,
  optional: { env?: Record<string, string | undefined> } = {},
): SqliteBackendConfig {
  void required;
  const e = optional.env ?? process.env;
  const kind = (e.JINI_SQLITE_BACKEND ?? 'sqlite').trim().toLowerCase();
  if (kind === 'postgres') {
    return resolvePostgresConfig({ env: e });
  }
  if (kind !== 'sqlite' && kind !== '') {
    throw new SqliteBackendConfigError({ message: `unknown JINI_SQLITE_BACKEND value '${kind}'. Accepted: 'sqlite' (default), 'postgres'.` });
  }
  return { kind: 'sqlite' };
}

/** @module db/projects
 * CRUD, run-status queries, and awaiting-input detection for the `projects` SQLite table — a
 * generic workspace/container row-store, not an OD-specific concept. Also queries `messages` and
 * `conversations` for run-status and input-gate state. Imports only the core/ kernel (SqliteDb,
 * DbRow); reaches no sibling concern.
 *
 * NOTE (neutral port): drops three OD-product columns with no generic engine equivalent —
 * `skill_id` (OD's agent-skill marketplace selection), `design_system_id` (OD's Design System
 * feature), and `applied_plugin_snapshot_id` (OD's plugin host). The already-ported
 * `schema/migrate.ts` projects table was pre-trimmed to match; see that file and `source-map.md`'s
 * Design Decisions for the same drop list. The kernel-noun exclusion in `extraction-plan.md` §2.1
 * ("projects... conversations" are not kernel nouns) does not block this module for the same reason
 * it didn't block `conversations`: `concern-owned storage` is a generic *optional* storage adapter any
 * consumer may use, not the kernel itself (`@jini-ai/core`/`@jini-ai/daemon` know nothing about this
 * table) — so "project" here is a de-branded generic workspace/container concept, not OD's model.
 */
import type { SqliteDb } from '@jini-ai/db/sqlite';
import type { DbRow } from '@jini-ai/db/core';

/** @internal Column alias list used in every SELECT against the projects table. */
const PROJECT_COLS = `id, name,
  pending_prompt AS pendingPrompt,
  metadata_json AS metadataJson,
  custom_instructions AS customInstructions,
  created_at AS createdAt,
  updated_at AS updatedAt`;

/**
 * Returns all projects ordered by most-recently updated first.
 * @param db - Open SQLite connection.
 */
export function listProjects({ db }: { db: SqliteDb }) {
  const rows = db
    .prepare(
      `SELECT ${PROJECT_COLS}
         FROM projects
        ORDER BY updated_at DESC`,
    )
    .all() as DbRow[];
  return rows.map(normalizeProject);
}

/**
 * Returns the most recent run status for each project, keyed by projectId.
 * Scans messages with a run_status column and collapses to one entry per project,
 * so callers can render project-level status badges without iterating conversations.
 * @param db - Open SQLite connection.
 */
export function listLatestProjectRunStatuses({ db }: { db: SqliteDb }) {
  const rows = db
    .prepare(
      `SELECT c.project_id AS projectId,
              m.run_id AS runId,
              m.run_status AS status,
              COALESCE(m.ended_at, m.started_at, m.created_at) AS updatedAt
         FROM messages m
         JOIN conversations c ON c.id = m.conversation_id
        WHERE m.run_status IS NOT NULL
        ORDER BY updatedAt DESC`,
    )
    .all() as DbRow[];
  const latestByProject = new Map<string, DbRow>();
  for (const row of rows) {
    if (!latestByProject.has(row.projectId)) {
      latestByProject.set(row.projectId, {
        value: normalizeProjectRunStatus(row.status),
        updatedAt: Number(row.updatedAt),
        runId: row.runId ?? undefined,
      });
    }
  }
  return latestByProject;
}

/**
 * Returns the most recent run status for each conversation, keyed by conversationId.
 * Used to display per-conversation activity state in a project sidebar.
 * @param db - Open SQLite connection.
 */
export function listLatestConversationRunStatuses({ db }: { db: SqliteDb }) {
  const rows = db
    .prepare(
      `SELECT m.conversation_id AS conversationId,
              m.run_id AS runId,
              m.run_status AS status,
              COALESCE(m.ended_at, m.started_at, m.created_at) AS updatedAt,
              m.position AS position
         FROM messages m
        WHERE m.run_status IS NOT NULL
        ORDER BY updatedAt DESC, m.position DESC`,
    )
    .all() as DbRow[];
  const latestByConversation = new Map<string, DbRow>();
  for (const row of rows) {
    if (!latestByConversation.has(row.conversationId)) {
      latestByConversation.set(row.conversationId, {
        value: normalizeProjectRunStatus(row.status),
        updatedAt: Number(row.updatedAt),
        runId: row.runId ?? undefined,
      });
    }
  }
  return latestByConversation;
}

/**
 * Returns the earliest run status for each conversation, keyed by conversationId.
 * Useful for determining when a conversation's first agent turn began.
 * @param db - Open SQLite connection.
 */
export function listFirstConversationRunStatuses({ db }: { db: SqliteDb }) {
  const rows = db
    .prepare(
      `SELECT m.conversation_id AS conversationId,
              m.run_id AS runId,
              m.run_status AS status,
              COALESCE(m.ended_at, m.started_at, m.created_at) AS updatedAt,
              m.position AS position
         FROM messages m
        WHERE m.run_status IS NOT NULL
          AND m.run_id IS NOT NULL
        ORDER BY m.position ASC`,
    )
    .all() as DbRow[];
  const firstByConversation = new Map<string, DbRow>();
  for (const row of rows) {
    if (!firstByConversation.has(row.conversationId)) {
      firstByConversation.set(row.conversationId, {
        value: normalizeProjectRunStatus(row.status),
        updatedAt: Number(row.updatedAt),
        runId: row.runId ?? undefined,
      });
    }
  }
  return firstByConversation;
}

/**
 * Returns the most recent run status for each individual run, keyed by runId.
 * Powers per-run status indicators in a conversation thread.
 * @param db - Open SQLite connection.
 */
export function listLatestRunStatuses({ db }: { db: SqliteDb }) {
  const rows = db
    .prepare(
      `SELECT m.run_id AS runId,
              m.run_status AS status,
              COALESCE(m.ended_at, m.started_at, m.created_at) AS updatedAt,
              m.position AS position
         FROM messages m
        WHERE m.run_status IS NOT NULL
          AND m.run_id IS NOT NULL
        ORDER BY updatedAt DESC, m.position DESC`,
    )
    .all() as DbRow[];
  const latestByRun = new Map<string, DbRow>();
  for (const row of rows) {
    if (!latestByRun.has(row.runId)) {
      latestByRun.set(row.runId, {
        value: normalizeProjectRunStatus(row.status),
        updatedAt: Number(row.updatedAt),
        runId: row.runId ?? undefined,
      });
    }
  }
  return latestByRun;
}

/**
 * Returns the set of project IDs with any conversation whose latest form-bearing assistant
 * message contains a `<question-form>` or `<ask-question>` artifact without a user reply.
 * Form filtering deliberately precedes ranking: a newer plain assistant turn does not consume
 * an outstanding question. Keep timestamp/position ordering for replies sharing a timestamp.
 * This is the data source for an "awaiting input" badge on a project list.
 * @param db - Open SQLite connection.
 */
export function listProjectsAwaitingInput(
  { db }: { db: SqliteDb },
  _optional: Record<string, never> = {},
) {
  const rows = db
    .prepare(
      `SELECT DISTINCT latest.projectId
         FROM (
           SELECT c.project_id AS projectId,
                  m.conversation_id AS conversationId,
                  m.created_at AS createdAt,
                  m.position AS position,
                  ROW_NUMBER() OVER (
                    PARTITION BY m.conversation_id
                    ORDER BY m.created_at DESC, m.position DESC
                  ) AS rowNum
             FROM messages m
             JOIN conversations c ON c.id = m.conversation_id
            WHERE m.role = 'assistant'
              -- ask-question is an accepted alias for question-form (host UI parser
              -- + agent open-tag matcher), so an alias-form turn must also count as
              -- awaiting input.
              AND (
                LOWER(m.content) LIKE '%<question-form%'
                OR LOWER(m.content) LIKE '%<ask-question%'
              )
         ) latest
        WHERE latest.rowNum = 1
          AND NOT EXISTS (
            SELECT 1
              FROM messages reply
             WHERE reply.conversation_id = latest.conversationId
               AND reply.role = 'user'
               AND (
                 reply.created_at > latest.createdAt
                 OR (reply.created_at = latest.createdAt AND reply.position > latest.position)
               )
          )`,
    )
    .all() as DbRow[];
  return new Set((rows as DbRow[]).map((row: DbRow) => row.projectId));
}

/**
 * Returns the set of conversation IDs whose latest form-bearing assistant message contains a
 * `<question-form>` or `<ask-question>` artifact and has not yet received a user reply.
 * As in the project query, a newer plain assistant turn leaves an unanswered form outstanding.
 * @param db - Open SQLite connection.
 */
export function listConversationsAwaitingInput({ db }: { db: SqliteDb }) {
  const rows = db
    .prepare(
      `SELECT latest.conversationId
         FROM (
           SELECT m.conversation_id AS conversationId,
                  m.created_at AS createdAt,
                  m.position AS position,
                  ROW_NUMBER() OVER (
                    PARTITION BY m.conversation_id
                    ORDER BY m.created_at DESC, m.position DESC
                  ) AS rowNum
             FROM messages m
            WHERE m.role = 'assistant'
              AND (
                LOWER(m.content) LIKE '%<question-form%'
                OR LOWER(m.content) LIKE '%<ask-question%'
              )
         ) latest
        WHERE latest.rowNum = 1
          AND NOT EXISTS (
            SELECT 1
              FROM messages reply
             WHERE reply.conversation_id = latest.conversationId
               AND reply.role = 'user'
               AND (
                 reply.created_at > latest.createdAt
                 OR (reply.created_at = latest.createdAt AND reply.position > latest.position)
               )
          )`,
    )
    .all() as DbRow[];
  return new Set((rows as DbRow[]).map((row: DbRow) => row.conversationId));
}

/**
 * Fetches a single project by id, or returns null if it does not exist.
 * @param db - Open SQLite connection.
 * @param id - Project id.
 */
export function getProject({ db, id }: { db: SqliteDb; id: string }) {
  const row = db
    .prepare(`SELECT ${PROJECT_COLS} FROM projects WHERE id = ?`)
    .get(id) as DbRow | undefined;
  return row ? normalizeProject(row) : null;
}

/**
 * Inserts a new project row and returns the freshly read, normalized record.
 * Metadata is serialized to JSON; all nullable fields default to null on omission.
 * @param db - Open SQLite connection.
 * @param project - Project fields to insert.
 */
export function insertProject({ db, project: p }: { db: SqliteDb; project: DbRow }) {
  db.prepare(
    `INSERT INTO projects
       (id, name, pending_prompt, metadata_json, custom_instructions, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    p.id,
    p.name,
    p.pendingPrompt ?? null,
    p.metadata ? JSON.stringify(p.metadata) : null,
    p.customInstructions ?? null,
    p.createdAt,
    p.updatedAt,
  );
  return getProject({ db, id: p.id });
}

/**
 * Applies a partial patch to an existing project, preserving omitted or undefined fields.
 * Explicit nulls still clear nullable fields.
 * Returns null when the project does not exist; otherwise returns the updated record.
 * updatedAt defaults to Date.now() when the patch omits it.
 * @param db - Open SQLite connection.
 * @param id - Project id to update.
 * @param patch - Fields to overwrite.
 * @param optional.clock - Host clock port; defaults to Date.now() as before. An explicit updatedAt
 * wins without reading the clock, so replayed/imported timestamps remain stable.
 */
export function updateProject(
  { db, id, patch }: { db: SqliteDb; id: string; patch: DbRow },
  optional: { clock?: { now(): number } } = {},
) {
  const existing = getProject({ db, id });
  if (!existing) return null;
  const merged = {
    ...existing,
    ...Object.fromEntries(Object.entries(patch).filter(([, value]) => value !== undefined)),
    updatedAt: typeof patch.updatedAt === 'number' ? patch.updatedAt : (optional.clock ?? Date).now(),
  };
  db.prepare(
    `UPDATE projects
        SET name = ?,
            pending_prompt = ?,
            metadata_json = ?,
            custom_instructions = ?,
            updated_at = ?
      WHERE id = ?`,
  ).run(
    merged.name,
    merged.pendingPrompt ?? null,
    merged.metadata ? JSON.stringify(merged.metadata) : null,
    merged.customInstructions ?? null,
    merged.updatedAt,
    id,
  );
  return getProject({ db, id });
}

/**
 * Permanently removes a project row. Cascading deletes for related rows are
 * handled at the SQLite schema level, not here.
 * @param db - Open SQLite connection.
 * @param id - Project id to delete.
 */
export function deleteProject({ db, id }: { db: SqliteDb; id: string }) {
  db.prepare(`DELETE FROM projects WHERE id = ?`).run(id);
}

/** @internal Converts a raw SQLite row into the typed project shape, parsing
 *  metadataJson and casting numeric timestamps. */
function normalizeProject(row: DbRow) {
  let metadata;
  if (row.metadataJson) {
    try {
      metadata = JSON.parse(row.metadataJson);
    } catch {
      metadata = undefined;
    }
  }
  return {
    id: row.id,
    name: row.name,
    pendingPrompt: row.pendingPrompt ?? undefined,
    metadata,
    customInstructions: row.customInstructions ?? undefined,
    createdAt: Number(row.createdAt),
    updatedAt: Number(row.updatedAt),
  };
}

/** @internal Maps raw DB run_status strings to the canonical client-facing enum,
 *  collapsing 'starting' → 'running' and 'cancelled' → 'canceled', and defaulting
 *  unknown values to 'not_started'. */
function normalizeProjectRunStatus(status: unknown) {
  if (status === 'starting') return 'running';
  if (status === 'cancelled') return 'canceled';
  if (
    status === 'queued' ||
    status === 'running' ||
    status === 'succeeded' ||
    status === 'failed' ||
    status === 'canceled'
  ) {
    return status;
  }
  return 'not_started';
}

/** Unchanged local host-project schema; no automatic migration at import. */
export const LEGACY_PROJECTS_DDL = `    CREATE TABLE IF NOT EXISTS projects (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      pending_prompt TEXT,
      metadata_json TEXT,
      custom_instructions TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

`;

/**
 * @module daemon-registry
 *
 * A local daemon "where am I listening" registry: a small, atomically-written JSON pointer
 * file recording a running daemon's URL/host/port/pid, plus a liveness-checked reader so a
 * separate process (e.g. a CLI invocation) can discover it without trusting a stale record
 * left behind by a daemon that crashed rather than shutting down cleanly. Built on this
 * package's own `json-file.ts` (atomic write, forgiving read, guarded pointer removal) — the
 * exact primitives OD's sidecar already uses for its own `current.json` namespace pointer
 * (see `paths.ts`'s `resolvePointerPath`) — plus a new `isProcessAlive` liveness probe no
 * existing module in this package needed before. Depends on `node:path` and this package's
 * own `json-file.ts`.
 */

import { randomUUID } from "node:crypto";
import { link, rename } from "node:fs/promises";
import { join, resolve } from "node:path";

import { readJsonFile, removeFile, writeJsonFile } from "./json-file.js";

/** Default file name for a daemon's registry record, resolved relative to its `dataDir`. */
const DEFAULT_DAEMON_REGISTRY_FILE_NAME = "daemon.json";

/** A running local daemon's discoverable identity: where it listens and which process owns it. */
export interface LocalDaemonRegistryRecord {
  /** The daemon's real, resolved base URL (e.g. `http://127.0.0.1:54213`). */
  readonly url: string;
  /** The host the daemon is reachable on (already loopback-substituted — see `resolveReportHost`). */
  readonly host: string;
  /** The daemon's bound TCP port. */
  readonly port: number;
  /** The OS process id of the daemon process that wrote this record. */
  readonly pid: number;
  /** ISO-8601 timestamp of when the daemon started listening. */
  readonly startedAt: string;
}

/**
 * Resolve the on-disk path of a daemon's registry record, scoped to its `dataDir` by default —
 * the same per-instance isolation `dataDir` already provides for `<dataDir>/events.db`, so two
 * daemons on one machine (each with their own `dataDir`, already a hard requirement for two
 * independent sqlite files) never collide on a single global registry path.
 * @param dataDir - The daemon's own data directory (same value passed to `createLocalNodeDaemon`).
 * @param fileName - Override the record's file name. Defaults to `daemon.json`.
 * @returns The resolved absolute registry file path.
 * @throws When `dataDir` is not a non-empty string.
 */
export function resolveDaemonRegistryPath({ dataDir }: { dataDir: string }, { fileName = DEFAULT_DAEMON_REGISTRY_FILE_NAME }: { fileName?: string } = {}): string {
  if (typeof dataDir !== "string" || dataDir.trim().length === 0) {
    throw new Error("dataDir must be a non-empty string");
  }
  return join(resolve(dataDir), fileName);
}

/**
 * Durably (atomically, via `json-file.ts`'s temp-file-rename writer) record a daemon's identity
 * at `registryPath`. Safe under concurrent writers — the last writer to complete its rename wins,
 * and every reader only ever observes a fully-written file, never a partial one.
 */
export async function writeDaemonRegistryRecord({ registryPath, record }: { registryPath: string; record: LocalDaemonRegistryRecord }): Promise<void> {
  await writeJsonFile({ filePath: registryPath, payload: record });
}

/** The two path moves `removeDaemonRegistryRecordIfCurrent` makes; injectable so a race lost to
 *  another remover, or a refused restore, can be reproduced without a real filesystem race. */
export interface DaemonRegistryFilePorts {
  rename(oldPath: string, newPath: string): Promise<void>;
  link(existingPath: string, newPath: string): Promise<void>;
}

/** Options for {@link removeDaemonRegistryRecordIfCurrent}. */
export interface RemoveDaemonRegistryRecordOptions {
  /** Defaults to `node:fs/promises`' `rename` and `link`. */
  readonly files?: DaemonRegistryFilePorts;
}

const DEFAULT_REGISTRY_FILE_PORTS: DaemonRegistryFilePorts = { rename, link };

/** Moves the public record aside; `false` when another remover already detached it (ENOENT). */
async function detachRecord(files: DaemonRegistryFilePorts, registryPath: string, tombstonePath: string): Promise<boolean> {
  try {
    await files.rename(registryPath, tombstonePath);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

/** Puts a captured record that turned out to be foreign back, unless a newer one already exists. */
async function restoreCapturedRecord(files: DaemonRegistryFilePorts, tombstonePath: string, registryPath: string): Promise<void> {
  try {
    // A hard link restores the captured file atomically ONLY if no newer record exists.
    // Rename would overwrite that newer writer. Keep the tombstone if restoration fails.
    await files.link(tombstonePath, registryPath);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
  }
}

/**
 * Remove a daemon's registry record at `registryPath`, but only if it still names `pid` as the
 * owning process — the same guarded-removal shape `json-file.ts`'s `removePointerIfCurrent` uses
 * for its own pointer file. Guards a fast crash-restart race on a reused `dataDir`: an old
 * daemon's delayed shutdown cleanup must never delete a newer daemon's already-written record.
 */
export async function removeDaemonRegistryRecordIfCurrent(
  { registryPath, pid }: { registryPath: string; pid: number },
  options: RemoveDaemonRegistryRecordOptions = {},
): Promise<void> {
  const record = await readJsonFile<{ pid?: unknown }>({ filePath: registryPath });
  if (record?.pid !== pid) return;
  const files = options.files ?? DEFAULT_REGISTRY_FILE_PORTS;

  // Detach first, then check the captured record: a writer may replace the public path
  // between the initial read and this rename. Only the captured file is ever removed.
  const tombstonePath = `${registryPath}.${process.pid}.${randomUUID()}.removed`;
  if (!(await detachRecord(files, registryPath, tombstonePath))) return;
  const captured = await readJsonFile<{ pid?: unknown }>({ filePath: tombstonePath });
  if (captured?.pid !== pid) await restoreCapturedRecord(files, tombstonePath, registryPath);
  await removeFile({ filePath: tombstonePath });
}

/**
 * Probe whether OS process `pid` is currently alive, via `process.kill(pid, 0)` (sends no
 * actual signal — `0` only tests deliverability). This is the liveness half of "verify, don't
 * just trust the file": a registry record left behind by a daemon that crashed instead of
 * shutting down cleanly must not be handed to a caller as if it were still reachable.
 * @param pid - The process id to probe.
 * @returns `true` when the process exists (either the signal-check succeeded, or it failed with
 * `EPERM` — the process exists but this process lacks permission to signal it, still "alive" for
 * discovery purposes). `false` for a non-positive/non-integer `pid`, a `pid` that does not exist
 * (`ESRCH`), or any other unexpected failure (treated conservatively as not confirmed alive).
 */
export function isProcessAlive({ pid }: { pid: number }): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    const code = (error as NodeJS.ErrnoException | undefined)?.code;
    return code === "EPERM";
  }
}

function isPositiveInteger({ value }: { value: unknown }, _options: Record<string, never> = {}): boolean {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

/**
 * @internal Structural + type validation for a value read back from a registry file — a
 * cross-process JSON file is untrusted input (wrong version, hand-edited, truncated write from
 * a process that was killed mid-write despite the atomic-rename writer, etc.).
 */
function isValidRegistryRecord(value: unknown): value is LocalDaemonRegistryRecord {
  if (value === null || typeof value !== "object") return false;
  const record = value as Partial<LocalDaemonRegistryRecord>;
  return (
    typeof record.url === "string" &&
    record.url.length > 0 &&
    typeof record.host === "string" &&
    record.host.length > 0 &&
    isPositiveInteger({ value: record.port }) &&
    isPositiveInteger({ value: record.pid }) &&
    typeof record.startedAt === "string" &&
    record.startedAt.length > 0
  );
}

/**
 * Read a daemon's registry record at `registryPath` and return it only if it is well-formed AND
 * its recorded `pid` is still alive — the combined "read, don't just trust" discovery primitive a
 * CLI-side `resolveDaemonUrl({}, { discover })` probe needs. A stale record from a daemon that crashed
 * (pid no longer alive), a missing file, or a malformed/foreign JSON file all resolve to `null`
 * rather than throwing — discovery failing is an expected, non-exceptional outcome (the caller
 * falls through to its own `defaultUrl`/error, per `resolveDaemonUrl`'s own contract).
 * @returns The live record, or `null` when nothing live was found.
 */
export async function readLiveDaemonRegistryRecord({ registryPath }: { registryPath: string }): Promise<LocalDaemonRegistryRecord | null> {
  const record = await readJsonFile<unknown>({ filePath: registryPath });
  if (!isValidRegistryRecord(record)) return null;
  if (!isProcessAlive({ pid: record.pid })) return null;
  return record;
}

/**
 * @module paths
 *
 * Namespace and runtime-path resolution for a sidecar. Derives the effective
 * namespace, the project/source runtime roots, the sidecar base, the
 * namespace/runtime roots and their pointer/manifest/log paths, per-app runtime
 * dirs/files, and the app IPC socket/pipe path — all from a host contract so no
 * product-specific strings are hardcoded here. Depends on `node:path` and the
 * public types.
 */

import { dirname, isAbsolute, join, resolve } from "node:path";

import type {
  AppIpcPathRequest,
  AppRuntimePathRequest,
  BaseResolutionOptions,
  BaseResolutionOptionsOptionalArgs,
  AppIpcPathRequestOptionalArgs,
  NamespaceResolutionOptions,
  NamespaceOptionalArgs,
  ProjectRuntimePathRequest,
  RuntimePathRequest,
  RuntimeRootRequest,
  SidecarContractDescriptor,
  SidecarRuntimeContext,
  SidecarStampShape,
} from "./types.js";

/**
 * Resolve the effective namespace from an explicit value, the env var named by
 * the contract, or the contract default — then normalize it.
 * @returns The normalized namespace.
 */
export function resolveNamespace<TStamp extends SidecarStampShape>({ contract }: Pick<NamespaceResolutionOptions<TStamp>, "contract">, options: NamespaceOptionalArgs = {}): string {
  return contract.normalizeNamespace({ namespace: options.namespace ??
      options.env?.[contract.env.namespace] ??
      contract.defaults.namespace });
}

/**
 * Validate and resolve a project root to an absolute path.
 * @returns The resolved absolute project root.
 */
export function resolveProjectRoot({ projectRoot }: { projectRoot: string }): string {
  if (typeof projectRoot !== "string" || projectRoot.trim().length === 0) {
    throw new Error("projectRoot must be a non-empty string");
  }
  return resolve(projectRoot);
}

/**
 * Resolve the project's tmp root (`<projectRoot>/<projectTmpDirName>`).
 * @returns The resolved tmp root path.
 */
export function resolveProjectTmpRoot<TStamp extends SidecarStampShape>({
  contract,
  projectRoot,
}: {
  contract: SidecarContractDescriptor<TStamp>;
  projectRoot: string;
}): string {
  return join(resolveProjectRoot({ projectRoot }), contract.defaults.projectTmpDirName);
}

/**
 * Resolve the source-scoped runtime root (`<projectTmpRoot>/<source>`).
 * @returns The resolved source runtime root path.
 */
export function resolveSourceRuntimeRoot<TStamp extends SidecarStampShape>({
  contract,
  projectRoot,
  source,
}: ProjectRuntimePathRequest<TStamp>): string {
  return join(resolveProjectTmpRoot({ contract, projectRoot }), contract.normalizeSource({ source }));
}

/**
 * Resolve the sidecar base from an explicit value, the env var named by the
 * contract, or the source runtime root.
 * @returns The resolved absolute base path.
 */
export function resolveSidecarBase<TStamp extends SidecarStampShape>({
  contract,
  source,
}: BaseResolutionOptions<TStamp>, { base, env = process.env, projectRoot = process.cwd() }: BaseResolutionOptionsOptionalArgs = {}): string {
  return resolve(base ?? env[contract.env.base] ?? resolveSourceRuntimeRoot({ contract, projectRoot, source }));
}

/**
 * Resolve the namespace root (`<base>/<namespace>`).
 * @returns The resolved namespace root path.
 */
export function resolveNamespaceRoot<TStamp extends SidecarStampShape>({
  base,
  contract,
  namespace,
}: RuntimePathRequest<TStamp>): string {
  return join(resolve(base), contract.normalizeNamespace({ namespace }));
}

/**
 * Resolve the namespace root (the directory that holds `logs/`, `runs/`,
 * `current.json`, …) from a *live* {@link SidecarRuntimeContext}.
 *
 * `resolveNamespaceRoot` alone is not enough here because the sidecar `base`
 * carries a different meaning depending on how the process was launched:
 *
 * - **dev (`tools-dev`):** every child is launched with `base` set to the
 *   pre-namespace source runtime root (see `tools/dev/src/config.ts`), so the
 *   namespace root is `base/<namespace>` — exactly what `resolveNamespaceRoot`
 *   computes.
 * - **packaged (runtime mode):** the orchestrator launches every child with
 *   `base = <namespaceRoot>/runtime` (see `apps/packaged/src/paths.ts` →
 *   `runtimeRoot`, wired in `apps/packaged/src/sidecars.ts`), while the actual
 *   logs live as a sibling at `<namespaceRoot>/logs`. Re-appending the
 *   namespace via `resolveNamespaceRoot` would yield
 *   `<namespaceRoot>/runtime/<namespace>`, so every daemon/web log file
 *   resolved that way is an ENOENT — which is why packaged diagnostics bundles
 *   used to capture none of them.
 *
 * Callers pass their contract's runtime-mode constant (e.g.
 * `SIDECAR_MODES.RUNTIME`) so this generic helper does not have to hardcode
 * the host product's mode strings.
 */
export function resolveRuntimeNamespaceRoot<TStamp extends SidecarStampShape>({
  contract,
  runtime,
  runtimeMode,
}: {
  contract: SidecarContractDescriptor<TStamp>;
  runtime: Pick<SidecarRuntimeContext<TStamp>, "base" | "mode" | "namespace">;
  runtimeMode: TStamp["mode"] | string;
}): string {
  if (runtime.mode === runtimeMode) {
    // packaged: `base` already points INTO the namespace tree
    // (`<namespaceRoot>/runtime`), so the namespace root is its parent.
    return dirname(resolve(runtime.base));
  }
  // dev / tools-dev: `base` is the pre-namespace source runtime root.
  return resolveNamespaceRoot({ base: runtime.base, contract, namespace: runtime.namespace });
}

/**
 * Resolve a per-run runtime root (`<namespaceRoot>/runs/<runId>`).
 * @returns The resolved run runtime root path.
 */
export function resolveRuntimeRoot<TStamp extends SidecarStampShape>({
  base,
  contract,
  namespace,
  runId,
}: RuntimeRootRequest<TStamp>): string {
  return join(resolveNamespaceRoot({ base, contract, namespace }), "runs", runId);
}

/**
 * Resolve the namespace pointer file (`<namespaceRoot>/current.json`).
 * @returns The resolved pointer path.
 */
export function resolvePointerPath<TStamp extends SidecarStampShape>({ base, contract, namespace }: RuntimePathRequest<TStamp>): string {
  return join(resolveNamespaceRoot({ base, contract, namespace }), "current.json");
}

/**
 * Resolve a run's manifest file (`<runtimeRoot>/manifest.json`).
 * @returns The resolved manifest path.
 */
export function resolveManifestPath({ runtimeRoot }: { runtimeRoot: string }): string {
  return join(runtimeRoot, "manifest.json");
}

/**
 * Resolve an app's logs directory (`<runtimeRoot>/logs/<app>`).
 * @returns The resolved logs directory path.
 */
export function resolveLogsDir<TStamp extends SidecarStampShape>({
  app,
  contract,
  runtimeRoot,
}: {
  app: TStamp["app"] | string;
  contract: SidecarContractDescriptor<TStamp>;
  runtimeRoot: string;
}): string {
  return join(runtimeRoot, "logs", contract.normalizeApp({ app }));
}

/**
 * Resolve an app's log file (`<logsDir>/<fileName>`, default `latest.log`).
 * @returns The resolved log file path.
 */
export function resolveLogFilePath<TStamp extends SidecarStampShape>({
  app,
  contract,
  runtimeRoot,
}: {
  app: TStamp["app"] | string;
  contract: SidecarContractDescriptor<TStamp>;
  runtimeRoot: string;
}, { fileName = "latest.log" }: { fileName?: string } = {}): string {
  return join(resolveLogsDir({ app, contract, runtimeRoot }), fileName);
}

/**
 * Resolve an app's runtime dir under a namespace root (`<namespaceRoot>/<app>`).
 * @returns The resolved app runtime directory path.
 */
export function resolveAppRuntimeDir<TStamp extends SidecarStampShape>({
  app,
  contract,
  namespaceRoot,
}: AppRuntimePathRequest<TStamp>): string {
  return join(namespaceRoot, contract.normalizeApp({ app }));
}

/**
 * Resolve a file inside an app's runtime dir, rejecting non-simple file names.
 * @returns The resolved app runtime file path.
 */
export function resolveAppRuntimePath<TStamp extends SidecarStampShape>({
  app,
  contract,
  fileName,
  namespaceRoot,
}: AppRuntimePathRequest<TStamp> & { fileName: string }): string {
  if (fileName.length === 0 || fileName.includes("\0") || /[\\/]/.test(fileName)) {
    throw new Error(`app runtime fileName must be a simple path segment: ${fileName}`);
  }
  return join(resolveAppRuntimeDir({ app, contract, namespaceRoot }), fileName);
}

/**
 * Resolve an app's IPC endpoint: a Windows named pipe, or a unix socket under
 * `<ipcBase>/<namespace>/<app>.sock`.
 * @returns The resolved IPC socket/pipe path.
 */
export function resolveAppIpcPath<TStamp extends SidecarStampShape>({
  app,
  contract,
  namespace,
}: AppIpcPathRequest<TStamp>, { env = process.env }: AppIpcPathRequestOptionalArgs = {}): string {
  const normalizedApp = contract.normalizeApp({ app });
  const normalizedNamespace = contract.normalizeNamespace({ namespace });

  if (process.platform === "win32") {
    return `\\\\.\\pipe\\${contract.defaults.windowsPipePrefix}-${normalizedNamespace}-${normalizedApp}`;
  }

  const ipcBase = resolve(env[contract.env.ipcBase] ?? contract.defaults.ipcBase);
  return join(ipcBase, normalizedNamespace, `${normalizedApp}.sock`);
}

import type { AgentSpec } from './attrs.js';
export type ConfirmTone = 'default' | 'warning' | 'danger';
export type DismissReason = 'cancel-button' | 'escape' | 'backdrop' | 'close';
export interface ConfirmInput {
  readonly open: boolean; readonly title: string; readonly confirmLabel: string;
  readonly cancelLabel?: string; readonly tone?: ConfirmTone; readonly pending?: boolean;
  readonly consequence?: string; readonly agentHandle?: string; readonly agentMayConfirm?: boolean;
}
const defaultConsequences: ReadonlyMap<ConfirmTone, string> = new Map<ConfirmTone, string>([
  ['warning', 'changes access, but is reversible'], ['danger', 'cannot be undone'],
]);
export function planConfirm(required: ConfirmInput, _optional: Record<string, never> = {}) {
  const pending = required.pending === true, tone = required.tone ?? 'default';
  const consequence = required.consequence?.trim() || defaultConsequences.get(tone);
  const confirmLabel = `${required.confirmLabel} — ${required.title}${consequence ? `; ${consequence}` : ''}`;
  const cancelLabel = required.cancelLabel ?? 'Cancel';
  const agent = (action: string, label: string): AgentSpec | undefined => required.agentHandle === undefined ? undefined :
    { handle: `${required.agentHandle}-${action}`, role: 'button', label };
  return Object.freeze({ initialFocus: 'cancel' as const, pending, dismissible: required.open && !pending,
    cancelDisabled: pending, confirmDisabled: pending, cancelLabel, confirmLabel, consequence,
    confirmVariant: tone === 'default' ? 'primary' as const : tone,
    cancel: agent('cancel', `${cancelLabel} — leaves "${required.title}" unconfirmed; no action taken`),
    confirm: required.agentMayConfirm === false ? undefined : agent('confirm', confirmLabel) });
}
/** Reads current policy on every invocation, so stale view callbacks cannot bypass a pending update. */
export function createConfirmController(required: {
  read: (required: Record<string, never>, optional?: Record<string, never>) => ConfirmInput;
  onConfirm: (required: Record<string, never>, optional?: Record<string, never>) => void | Promise<void>;
  onCancel: (required: Record<string, never>, optional?: Record<string, never>) => void;
}, _optional: Record<string, never> = {}) {
  let executing = false;
  return Object.freeze({
    requestDismiss(_required: { reason: DismissReason }, _optional: Record<string, never> = {}): boolean {
      if (executing || !planConfirm(required.read({})).dismissible) return false;
      required.onCancel({}); return true;
    },
    async confirm(input: { actor?: 'human' | 'agent' } = {}, _optional: Record<string, never> = {}): Promise<boolean> {
      const policy = required.read({});
      if (executing || !policy.open || policy.pending || (input.actor === 'agent' && policy.agentMayConfirm === false)) return false;
      // Set synchronously before calling the port: two clicks in one React frame must not execute twice.
      executing = true;
      try { await required.onConfirm({}); return true; } finally { executing = false; }
    },
    isExecuting(_required: Record<string, never>, _optional: Record<string, never> = {}): boolean { return executing; },
  });
}

