import type { ImplementedComponentName } from '../kit-contract.js';
export type ConformanceAction = { readonly type: 'click' | 'cancel' | 'focus' | 'key'; readonly selector: string; readonly key?: string };
export type ConformanceExpectation =
  | { readonly type: 'attribute'; readonly selector: string; readonly name: string; readonly value: string }
  | { readonly type: 'focused' | 'disabled' | 'absent' | 'native-select' | 'focusable'; readonly selector: string }
  | { readonly type: 'calls'; readonly name: string; readonly count: number };
export interface KitScenario {
  readonly id: string; readonly component: ImplementedComponentName; readonly safety?: boolean;
  readonly browserOnly?: boolean; readonly props: Readonly<Record<string, unknown>>;
  readonly actions: readonly ConformanceAction[]; readonly expectations: readonly ConformanceExpectation[];
}
/** Serializable cases can drive another framework or a real-browser fixture without importing React. */
export const kitConformanceScenarios: readonly KitScenario[] = Object.freeze([
  ...(['Button', 'IconButton', 'TextField', 'TextArea', 'Select', 'Checkbox', 'Switch', 'Dialog', 'Tabs', 'Menu', 'Toast', 'Tooltip', 'Notice', 'Spinner', 'Badge'] as const).map(component => ({
    id: `${component}:opaque-attrs`, component, props: { attrs: { 'data-agent-element': 'probe', 'data-jini-part': 'x.host.part', 'aria-description': 'opaque' } }, actions: [],
    expectations: [{ type: 'focusable' as const, selector: '[data-agent-element="probe"]' },
      { type: 'attribute' as const, selector: '[data-agent-element="probe"]', name: 'data-jini-part', value: 'x.host.part' },
      { type: 'attribute' as const, selector: '[data-agent-element="probe"]', name: 'aria-description', value: 'opaque' }],
  })),
  { id: 'Select:native-semantics', component: 'Select', props: {}, actions: [], expectations: [{ type: 'native-select', selector: '[data-jini-part="kit.select"]' }] },
  { id: 'Button:disabled-blocks-press', component: 'Button', props: { disabled: true }, actions: [{ type: 'click', selector: 'button' }], expectations: [{ type: 'calls', name: 'press', count: 0 }] },
  { id: 'ConfirmDialog:cancel-first-focus', component: 'ConfirmDialog', safety: true, props: {}, actions: [], expectations: [{ type: 'focused', selector: '[data-jini-part="confirm.cancel"]' }] },
  { id: 'ConfirmDialog:pending-blocks-every-dismissal', component: 'ConfirmDialog', safety: true, props: { pending: true },
    actions: [{ type: 'cancel', selector: '[data-jini-part="confirm.dialog"]' }, { type: 'click', selector: '[data-jini-part="confirm.dialog"]' },
      { type: 'click', selector: '[data-jini-part="confirm.cancel"]' }, { type: 'click', selector: '[data-jini-part="confirm.confirm"]' }],
    expectations: [{ type: 'calls', name: 'cancel', count: 0 }, { type: 'calls', name: 'confirm', count: 0 },
      { type: 'disabled', selector: '[data-jini-part="confirm.cancel"]' }, { type: 'disabled', selector: '[data-jini-part="confirm.confirm"]' }] },
  { id: 'ConfirmDialog:agent-confirm-withheld', component: 'ConfirmDialog', safety: true, props: { agentHandle: 'erase', agentMayConfirm: false }, actions: [],
    expectations: [{ type: 'absent', selector: '[data-agent-element="erase-confirm"]' },
      { type: 'attribute', selector: '[data-jini-part="confirm.cancel"]', name: 'data-agent-element', value: 'erase-cancel' }] },
  { id: 'ConfirmDialog:consequence-label', component: 'ConfirmDialog', safety: true, props: { agentHandle: 'erase', tone: 'danger' }, actions: [],
    expectations: [{ type: 'attribute', selector: '[data-jini-part="confirm.confirm"]', name: 'data-agent-label', value: 'Delete — Delete record?; cannot be undone' },
      { type: 'attribute', selector: '[data-jini-part="confirm.confirm"]', name: 'aria-label', value: 'Delete — Delete record?; cannot be undone' }] },
  { id: 'ConfirmDialog:browser-escape', component: 'ConfirmDialog', safety: true, browserOnly: true, props: {},
    actions: [{ type: 'key', selector: '[data-jini-part="confirm.cancel"]', key: 'Escape' }], expectations: [{ type: 'calls', name: 'cancel', count: 1 }] },
  { id: 'ConfirmDialog:browser-modal-focus', component: 'ConfirmDialog', safety: true, browserOnly: true, props: {}, actions: [],
    expectations: [{ type: 'focused', selector: '[data-jini-part="confirm.cancel"]' }] },
]);

export interface ToastMessage { readonly id: string; readonly message: string; readonly tone?: 'info' | 'success' | 'warning' | 'danger'; readonly durationMs?: number }
export interface ToastScheduler {
  schedule(required: { delayMs: number; run: (required: Record<string, never>, optional?: Record<string, never>) => void }, optional?: Record<string, never>): unknown;
  cancel(required: { ticket: unknown }, optional?: Record<string, never>): void;
}
export interface ToastService {
  push(required: Omit<ToastMessage, 'id'>, optional?: { id?: string }): string;
  dismiss(required: { id: string }, optional?: Record<string, never>): void;
  snapshot(required: Record<string, never>, optional?: Record<string, never>): readonly ToastMessage[];
  subscribe(required: { listener: (required: Record<string, never>, optional?: Record<string, never>) => void }, optional?: Record<string, never>): () => void;
  dispose(required: Record<string, never>, optional?: Record<string, never>): void;
}
const defaultScheduler: ToastScheduler = {
  schedule: ({ delayMs, run }) => setTimeout(() => run({}), delayMs),
  cancel: ({ ticket }) => clearTimeout(ticket as ReturnType<typeof setTimeout>),
};
/** Instance-local queues avoid mixing messages between hosts and SSR requests. */
export function createToastService(_required: Record<string, never>, optional: { scheduler?: ToastScheduler; durationMs?: number } = {}): ToastService {
  const scheduler = optional.scheduler ?? defaultScheduler;
  let messages: readonly ToastMessage[] = Object.freeze([]), sequence = 0, disposed = false;
  const listeners = new Set<(required: Record<string, never>) => void>(), timers = new Map<string, unknown>();
  function emit() { for (const listener of listeners) listener({}); }
  function dismiss({ id }: { id: string }, _optional: Record<string, never> = {}) {
    if (timers.has(id)) { scheduler.cancel({ ticket: timers.get(id) }); timers.delete(id); }
    if (!messages.some(message => message.id === id)) return;
    messages = Object.freeze(messages.filter(message => message.id !== id)); emit();
  }
  return Object.freeze({
    push(input: Omit<ToastMessage, 'id'>, opts: { id?: string } = {}) {
      if (disposed) throw new Error('Toast service is disposed');
      const id = opts.id ?? `toast-${++sequence}`;
      dismiss({ id }); messages = Object.freeze([...messages, Object.freeze({ ...input, id })]); emit();
      const delayMs = input.durationMs ?? optional.durationMs ?? 5000;
      if (delayMs > 0) timers.set(id, scheduler.schedule({ delayMs, run: () => dismiss({ id }) }));
      return id;
    },
    dismiss,
    snapshot(_required: Record<string, never>, _optional: Record<string, never> = {}) { return messages; },
    subscribe({ listener }: { listener: (required: Record<string, never>, optional?: Record<string, never>) => void }, _optional: Record<string, never> = {}) {
      listeners.add(listener); return () => { listeners.delete(listener); };
    },
    dispose(_required: Record<string, never>, _optional: Record<string, never> = {}) {
      disposed = true;
      for (const ticket of timers.values()) scheduler.cancel({ ticket });
      timers.clear(); messages = Object.freeze([]); emit(); listeners.clear();
    },
  });
}

import type { AdminTheme, AdminThemeColors } from './types.js';

export const adminThemeColorKeys = ['primary', 'primaryInk', 'bg', 'surface', 'text', 'muted', 'border', 'danger', 'success', 'warning'] as const satisfies readonly (keyof AdminThemeColors)[];
type Validation = { readonly valid: true; readonly theme: AdminTheme } | { readonly valid: false; readonly errors: readonly string[] };
type Fields = Record<string, unknown>;
const record = (value: unknown): value is Fields => typeof value === 'object' && value !== null && !Array.isArray(value);
const safeValue = (value: unknown): value is string => typeof value === 'string' && value.trim().length > 0
  && value.length <= 512 && !/[;{}\x00-\x1f<>\\]/.test(value) && !/url\s*\(|\/\*|\*\//i.test(value);
// Concrete palette values, deliberately excluding dependent var()/url() expressions.
const component = '(?:[+-]?(?:\\d+(?:\\.\\d+)?|\\.\\d+)(?:%|deg|rad|grad|turn)?|none)';
const components = new RegExp(`^(?:rgb|rgba|hsl|hsla|oklch|oklab|lab|lch)\\(\\s*${component}(?:\\s*,\\s*|\\s+)${component}(?:\\s*,\\s*|\\s+)${component}(?:(?:\\s*[,/]\\s*)${component})?\\s*\\)$`, 'i');
const colorValue = (value: unknown): value is string => safeValue(value)
  && (/^#[\da-f]{3}(?:[\da-f]|[\da-f]{3}|[\da-f]{5})?$/i.test(value)
    || components.test(value)
    || /^(?:transparent|black|white|red|green|blue|gray|grey)$/i.test(value));

const fontStacksValid = ({ fonts }: { readonly fonts: unknown }): boolean =>
  record(fonts) && safeValue(fonts.body) && safeValue(fonts.heading) && (fonts.mono === undefined || safeValue(fonts.mono));

const stylesheetUrlValid = ({ url }: { readonly url: unknown }): boolean => {
  if (typeof url !== 'string' || url.length > 4096 || /[\x00-\x20<>]/.test(url)) return false;
  try { return new URL(url, 'https://font-base.invalid').protocol === 'https:'; } catch { return false; }
};

const fontLoadValid = ({ load }: { readonly load: unknown }): boolean =>
  load === undefined || (Array.isArray(load) && load.length <= 16 && load.every((url: unknown) => stylesheetUrlValid({ url })));

function fontErrors({ fonts }: { readonly fonts: unknown }): string[] {
  const errors: string[] = [];
  if (!fontStacksValid({ fonts })) errors.push('fonts must provide body and heading font stacks');
  if (record(fonts) && !fontLoadValid({ load: fonts.load })) errors.push('fonts.load must contain relative or HTTPS stylesheet URLs');
  return errors;
}

function paletteErrors({ scheme, colors }: { readonly scheme: 'light' | 'dark'; readonly colors: unknown }): string[] {
  if (!record(colors)) return [`${scheme} must be a complete palette`];
  const known: readonly string[] = adminThemeColorKeys;
  const invalid = adminThemeColorKeys.filter((key) => !Object.hasOwn(colors, key) || !colorValue(colors[key]))
    .map((key) => `${scheme}.${key} must be a concrete CSS color`);
  const unknown = Object.keys(colors).filter((key) => !known.includes(key)).map((key) => `${scheme}.${key} is not a theme color`);
  return [...invalid, ...unknown];
}

const radiusValid = ({ radius }: { readonly radius: unknown }): boolean =>
  radius === undefined || (typeof radius === 'string' && /^(?:0|\d+(?:\.\d+)?(?:px|rem|em))$/.test(radius));

const densityValid = ({ density }: { readonly density: unknown }): boolean =>
  density === undefined || (typeof density === 'number' && Number.isFinite(density) && density >= 0.5 && density <= 2);

/** Validate serializable theme data before any DOM or font-loading effect. */
export function validateAdminTheme({ theme }: { readonly theme: unknown }): Validation {
  if (!record(theme)) return { valid: false, errors: ['Theme must be an object'] };
  const errors = [
    ...(safeValue(theme.name) ? [] : ['name must be a nonempty safe string']),
    ...fontErrors({ fonts: theme.fonts }),
    ...paletteErrors({ scheme: 'light', colors: theme.light }),
    ...paletteErrors({ scheme: 'dark', colors: theme.dark }),
    ...(radiusValid({ radius: theme.radius }) ? [] : ['radius must be a nonnegative CSS length']),
    ...(densityValid({ density: theme.density }) ? [] : ['density must be between 0.5 and 2']),
  ];
  return errors.length ? { valid: false, errors } : { valid: true, theme: theme as unknown as AdminTheme };
}

import { useEffect, useState } from 'react';

export type HtmlPreviewPort = (input: { source: string }, options: { signal: AbortSignal }) => Promise<string>;
export interface HtmlPreviewState { document: string; loading: boolean; error: string | null }

/** Debounces an unsaved source through the host's renderer; cleanup cancels timers and ignores
 * responses even when the transport cannot abort. No rendering policy belongs to this hook.
 * @returns The last successful document and one-line request state.
 * @complexity O(1) per source change, excluding the injected renderer's cost.
 */
export function useDebouncedHtmlPreview(
  { source, render }: { source: string; render: HtmlPreviewPort },
  { revision = '', delayMs = 400 }: { revision?: string; delayMs?: number } = {},
): HtmlPreviewState {
  // `settled` names the source+revision the stored result belongs to, so `loading` and a stale
  // error are derived during render. Setting state from the effect on every keystroke left a
  // pending update after each commit, and ~50 fast keystrokes then tripped React's nested-update
  // limit, which dropped that keystroke from the host's controlled input.
  const key = JSON.stringify([source, revision]);
  const [state, setState] = useState<{ document: string; error: string | null; settled: string | null }>({ document: '', error: null, settled: null });
  useEffect(() => {
    let current = true;
    const controller = new AbortController();
    const timer = setTimeout(() => {
      // Promise.resolve also maps a synchronously throwing host adapter to the error state.
      void Promise.resolve().then(() => render({ source }, { signal: controller.signal })).then(
        document => { if (current) setState({ document, error: null, settled: key }); },
        () => { if (current) setState(previous => ({ ...previous, error: 'Preview unavailable.', settled: key })); },
      );
    }, delayMs);
    return () => { current = false; clearTimeout(timer); controller.abort(); };
  }, [key, source, render, delayMs]);
  const settled = state.settled === key;
  return { document: state.document, loading: !settled, error: settled ? state.error : null };
}

import { useCallback, useMemo, useRef, useState, type ReactNode } from 'react';
import { useT } from '../../../i18n/index.js';
import { dayKeyFromTimestamp, resolveFacetLabel } from '../../rules.js';
import type { AssetGridDependencies } from '../../ports.js';
import type { AssetGridFacetOption, AssetGridItem, AssetGridSelectors, AssetGridViewMode } from '../../types.js';
import { useWiredAssetGridData } from '../hooks/useAssetGridData.js';
import { useWiredAssetGridLiveUpdates } from '../hooks/useAssetGridLiveUpdates.js';
import { useAssetGridSelection } from '../hooks/useAssetGridSelection.js';
import { useRubberBandDrag } from '../hooks/useRubberBandDrag.js';
import { useAssetGridKeyboardShortcuts } from '../hooks/useAssetGridKeyboardShortcuts.js';
import { useAssetGridFilters } from './useAssetGridFilters.js';
import { AssetCard } from './AssetCard.js';
import { AssetGridBody, type AssetGridBodyProps } from './AssetGridBody.js';
import { AssetGridToolbar } from './AssetGridToolbar.js';
import { SelectionActionBar } from './SelectionActionBar.js';
import { SelectionBand } from './SelectionBand.js';
import { DeleteConfirmDialog } from './DeleteConfirmDialog.js';

export interface AssetGridProps<TAsset extends AssetGridItem> {
  /** Whether this grid is the visible/active surface — gates fetch-on-mount, live updates, and keyboard shortcuts (a tab-visibility gate). Defaults to `true`. */
  active?: boolean;
  selectors: AssetGridSelectors<TAsset>;
  /** Defaults to an empty in-memory fake — a host supplies its own `data` (and optionally `liveUpdates`) port. */
  dependencies?: AssetGridDependencies<TAsset>;
  kindFacets?: AssetGridFacetOption[];
  sourceFacets?: AssetGridFacetOption[];
  /** Host-supplied, kind-aware thumbnail renderer — required, since only the host knows its asset kinds. */
  renderThumbnail: (asset: TAsset) => ReactNode;
  renderThumbnailPlaceholder?: (asset: TAsset) => ReactNode;
  /** Host-owned per-card extra actions (e.g. an "open origin" link), rendered alongside the generic Remove action. */
  renderCardExtra?: (asset: TAsset) => ReactNode;
  /** Host-owned extra bulk actions, rendered in the selection bar before the generic Delete action. */
  renderBulkActions?: (selectedIds: string[]) => ReactNode;
  /** The actual per-asset delete call. Omit to hide the built-in per-card Remove action. */
  onDeleteAsset?: (id: string) => void | Promise<void>;
  /** The actual bulk-delete call, invoked after the user confirms the dialog. Omit to hide the bulk-delete action and Delete-key shortcut entirely. */
  onDeleteSelected?: (ids: string[]) => void | Promise<void>;
  onPreview?: (asset: TAsset) => void;
  /** True while a host-owned preview surface is open — Escape/Delete then defer to it instead of the grid. */
  isPreviewOpen?: boolean;
  /** Host-specific extra toolbar controls (e.g. Upload/Sync buttons). */
  toolbarActions?: ReactNode;
  emptyState?: ReactNode;
  searchPlaceholder?: string;
  searchDebounceMs?: number;
  liveUpdateCoalesceMs?: number;
  initialViewMode?: AssetGridViewMode;
  /** Custom hook overrides for dependency injection / testing. */
  useWiredAssetGridData?: typeof useWiredAssetGridData;
  useAssetGridSelection?: typeof useAssetGridSelection;
}

function renderGridContent<TAsset extends AssetGridItem>(
  { loading, emptyState, t, ...bodyProps }: AssetGridBodyProps<TAsset> & {
    loading: boolean;
    emptyState: ReactNode;
    t: ReturnType<typeof useT>;
  },
  _options: Record<string, never> = {},
) {
  if (loading && bodyProps.assets.length === 0) return <p className="asset-grid-empty">{t('Loading…')}</p>;
  if (bodyProps.assets.length === 0) return emptyState ?? <div className="asset-grid-empty">{t('No assets yet.')}</div>;
  return <AssetGridBody {...bodyProps} />;
}

/**
 * A live-updating, filterable, multi-selectable asset grid — the generic
 * pattern behind a photo library / DAM. See `packages/ui/source-map.md` for
 * the full retained-behavior manifest against the original `LibrarySection.tsx`.
 */
export function AssetGrid<TAsset extends AssetGridItem>({
  active = true,
  selectors,
  dependencies,
  kindFacets: configuredKindFacets,
  sourceFacets: configuredSourceFacets,
  renderThumbnail,
  renderThumbnailPlaceholder,
  renderCardExtra,
  renderBulkActions,
  onDeleteAsset,
  onDeleteSelected,
  onPreview,
  isPreviewOpen = false,
  toolbarActions,
  emptyState,
  searchPlaceholder,
  searchDebounceMs,
  liveUpdateCoalesceMs,
  initialViewMode = 'grid',
  useWiredAssetGridData: useWiredAssetGridDataHook = useWiredAssetGridData,
  useAssetGridSelection: useAssetGridSelectionHook = useAssetGridSelection,
}: AssetGridProps<TAsset>) {
  const t = useT();

  const {
    kind, setKind, source, setSource, search, setSearch,
    debouncedSearch, filtersActive, kindFacets, sourceFacets, kindFacetLabels, sourceFacetLabels,
  } = useAssetGridFilters({
    kindFacets: configuredKindFacets,
    sourceFacets: configuredSourceFacets,
    searchDebounceMs,
  });
  const [viewMode, setViewMode] = useState<AssetGridViewMode>(initialViewMode);
  const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);
  /** Message from a delete the host rejected. Rendered inline — see `runDelete`. */
  const [deleteError, setDeleteError] = useState<string | null>(null);

  // `dependencies` (host-supplied, or omitted to fall back to the package's
  // in-memory fake) is resolved by each wirer independently — neither this
  // component nor the real `useAssetGridData`/`useAssetGridLiveUpdates`
  // hooks import `dependencies.ts` themselves.
  const { assets, setAssets, loading, reload } = useWiredAssetGridDataHook({
    dependencies,
    active,
    kind,
    source,
    debouncedSearch,
    getKind: selectors.getKind,
    matchesKindFilter: selectors.matchesKindFilter,
    mapKindToQuery: selectors.mapKindToQuery,
  });

  useWiredAssetGridLiveUpdates({
    dependencies,
    active,
    filtersActive,
    setAssets,
    reload,
    coalesceMs: liveUpdateCoalesceMs,
  });

  const { selectedIds, setSelectedIds, toggleOne, rangeTo, selectAll, clearSelection } = useAssetGridSelectionHook(assets);
  const containerRef = useRef<HTMLDivElement>(null);
  const { band, dragging, onMouseDown } = useRubberBandDrag({ containerRef, selectedIds, setSelectedIds });

  const requestDeleteSelected = useCallback(() => {
    if (selectedIds.size) setConfirmDeleteOpen(true);
  }, [selectedIds]);

  /**
   * Drops rows from the grid only once the host has actually deleted them.
   *
   * Two distinct defects here, each reported independently and each reproduced:
   *
   * - **No handler.** `onDelete*` is optional and the API says a host may omit
   *   it — but `await undefined` resolves happily, so the rows were filtered out
   *   of local state anyway. The assets appeared to delete and reappeared on the
   *   next load: the UI lying about state, with nothing persisted.
   * - **Rejected handler.** No `catch`, and the caller discards the promise with
   *   `void`, so a failed delete became an unhandled rejection with no toast, no
   *   inline error, and no visual change of any kind.
   *
   * The error is surfaced rather than swallowed. `resource-dashboard` in this
   * same package already threads an `actionError` through for exactly this
   * situation, so this follows the established pattern rather than inventing one.
   */
  const runDelete = useCallback(
    async (deleteFn: ((ids: readonly string[]) => unknown) | null, ids: readonly string[], drop: () => void) => {
      // No handler means the host cannot persist this — do not pretend it did.
      if (!deleteFn) return;
      setDeleteError(null);
      try {
        await deleteFn(ids);
      } catch (error: unknown) {
        setDeleteError(error instanceof Error ? error.message : String(error));
        return;
      }
      drop();
    },
    [],
  );

  const confirmDelete = useCallback(async () => {
    setConfirmDeleteOpen(false);
    const ids = [...selectedIds];
    if (!ids.length) return;
    await runDelete(onDeleteSelected ? (batch) => onDeleteSelected([...batch]) : null, ids, () => {
      const idSet = new Set(ids);
      setAssets((prev) => prev.filter((a) => !idSet.has(a.id)));
      setSelectedIds(new Set());
    });
  }, [selectedIds, onDeleteSelected, setAssets, setSelectedIds, runDelete]);

  // Built only when the host supplied `onDeleteAsset`: the card shows its per-asset delete control
  // only when it receives a handler, so there is no "no handler" path to route through `runDelete`
  // here (the old inline `onDeleteAsset ? … : null` could never see `null` from a rendered card).
  const handleDeleteAsset = useMemo(
    () => onDeleteAsset
      ? async (id: string) => {
        await runDelete((batch) => onDeleteAsset(batch[0]!), [id], () => {
          setAssets((prev) => prev.filter((a) => a.id !== id));
        });
      }
      : undefined,
    [onDeleteAsset, setAssets, runDelete],
  );

  const handlePreview = useCallback(
    (id: string) => {
      const asset = assets.find((a) => a.id === id);
      if (asset) onPreview?.(asset);
    },
    [assets, onPreview],
  );

  useAssetGridKeyboardShortcuts({
    active,
    enabled: !confirmDeleteOpen,
    hasAssets: assets.length > 0,
    hasSelection: selectedIds.size > 0,
    isPreviewOpen,
    onSelectAll: selectAll,
    onClearSelection: clearSelection,
    onRequestDeleteSelected: requestDeleteSelected,
  });

  const getDayKey = useMemo(
    () => selectors.getDayKey ?? ((asset: TAsset) => dayKeyFromTimestamp(selectors.getTimestamp(asset))),
    [selectors],
  );

  const renderCard = useCallback(
    (asset: TAsset, index: number) => {
      const kindValue = selectors.getKind(asset);
      const sourceValue = selectors.getSource?.(asset);
      return (
        <AssetCard
          key={asset.id}
          asset={asset}
          index={index}
          selected={selectedIds.has(asset.id)}
          title={selectors.getTitle(asset)}
          subtitle={selectors.getSubtitle?.(asset)}
          kindLabel={resolveFacetLabel(kindValue, kindFacetLabels)}
          sourceLabel={sourceValue ? resolveFacetLabel(sourceValue, sourceFacetLabels) : undefined}
          renderThumbnail={renderThumbnail}
          renderThumbnailPlaceholder={renderThumbnailPlaceholder}
          onToggle={toggleOne}
          onRange={rangeTo}
          onPreview={handlePreview}
          onDeleteAsset={handleDeleteAsset}
          renderCardExtra={renderCardExtra}
        />
      );
    },
    [
      selectedIds,
      selectors,
      kindFacetLabels,
      sourceFacetLabels,
      renderThumbnail,
      renderThumbnailPlaceholder,
      toggleOne,
      rangeTo,
      handlePreview,
      onDeleteAsset,
      handleDeleteAsset,
      renderCardExtra,
    ],
  );

  return (
    <div className="asset-grid-root">
      <AssetGridToolbar
        search={search}
        onSearchChange={setSearch}
        searchPlaceholder={searchPlaceholder}
        kind={kind}
        onKindChange={setKind}
        kindFacets={kindFacets}
        source={source}
        onSourceChange={setSource}
        sourceFacets={sourceFacets}
        viewMode={viewMode}
        onViewModeChange={setViewMode}
        onRefresh={() => void reload()}
        loading={loading}
        toolbarActions={toolbarActions}
      />

      {selectedIds.size > 0 && !dragging ? (
        <SelectionActionBar
          selectedIds={[...selectedIds]}
          onSelectAll={selectAll}
          onClear={clearSelection}
          onRequestDelete={requestDeleteSelected}
          renderBulkActions={renderBulkActions}
        />
      ) : null}

      {renderGridContent({
        loading,
        emptyState,
        t,
        viewMode,
        assets,
        getDayKey,
        containerRef,
        onMouseDown,
        selecting: selectedIds.size > 0,
        renderCard,
      })}

      <SelectionBand band={band} />

      {deleteError ? (
        <p className="jini-hint jini-hint-error" role="alert">
          {deleteError}
        </p>
      ) : null}

      {confirmDeleteOpen ? (
        <DeleteConfirmDialog
          count={selectedIds.size}
          onCancel={() => setConfirmDeleteOpen(false)}
          onConfirm={() => void confirmDelete()}
        />
      ) : null}
    </div>
  );
}

import { useEffect, useMemo, useRef } from 'react';
import { DEFAULT_LIVE_UPDATE_COALESCE_MS } from '../../constants.js';
import { mergeIngestedAssets } from '../../rules.js';
import { createFakeAssetGridDependencies } from '../../dependencies.js';
import type { AssetGridDependencies, AssetGridLiveUpdatesPort } from '../../ports.js';
import type { AssetGridItem } from '../../types.js';

export interface UseAssetGridLiveUpdatesParams<TAsset extends AssetGridItem> {
  active: boolean;
  liveUpdates: AssetGridLiveUpdatesPort | undefined;
  /** When true, incremental membership can't be predicted client-side (an active kind/source/search filter) — every event falls back to a full reload. */
  filtersActive: boolean;
  fetchAssetById?: ((id: string) => Promise<TAsset | null>) | undefined;
  setAssets: React.Dispatch<React.SetStateAction<TAsset[]>>;
  reload: () => Promise<void>;
  coalesceMs?: number | undefined;
}

/** Drains pending deletes and cancels matching ingests before the pass can fetch.
 * Mutates the pending sets and schedules the asset update. @complexity O(d + a) deletes and assets. */
function applyPendingDeletes<TAsset extends AssetGridItem>({ pendingDelete, pendingIngest, setAssets }: {
  pendingDelete: Set<string>;
  pendingIngest: Set<string>;
  setAssets: UseAssetGridLiveUpdatesParams<TAsset>['setAssets'];
}, _options: Record<string, never> = {}): void {
  // Deletes are free (no fetch); apply them first.
  if (pendingDelete.size) {
    const del = new Set(pendingDelete);
    pendingDelete.clear();
    for (const id of del) pendingIngest.delete(id);
    setAssets((prev) => prev.filter((a) => !del.has(a.id)));
  }
}

/**
 * Subscribes to a live-update transport and reconciles incremental
 * ingest/delete events into the current asset list. Events are coalesced
 * over a short window and applied as one targeted merge (fetch the new/
 * changed ids, drop the deleted ids) instead of one full reload per event.
 * A burst of many events, a filtered view, or an event with no resolvable
 * id all fall back to a single full reload for that window — see
 * `packages/ui/archived provenance ledger` for why (the original OD comment: "a filtered
 * view can't predict membership client-side").
 * Disposed subscriptions discard in-flight incremental reads. Failed passes report a
 * fixed diagnostic and request a full reconciliation on the next live event.
 */
export function useAssetGridLiveUpdates<TAsset extends AssetGridItem>(
  params: UseAssetGridLiveUpdatesParams<TAsset>,
): void {
  const { active, liveUpdates, filtersActive, fetchAssetById, setAssets, reload, coalesceMs = DEFAULT_LIVE_UPDATE_COALESCE_MS } =
    params;

  // Refs so the long-lived subscription (set up once per active/liveUpdates
  // change) always reads the LATEST filtersActive/reload/fetchAssetById
  // without resubscribing — resubscribing would drop and recreate the
  // transport on every keystroke/filter change.
  const filtersActiveRef = useRef(filtersActive);
  useEffect(() => {
    filtersActiveRef.current = filtersActive;
  }, [filtersActive]);
  const reloadRef = useRef(reload);
  useEffect(() => {
    reloadRef.current = reload;
  }, [reload]);
  const fetchAssetByIdRef = useRef(fetchAssetById);
  useEffect(() => {
    fetchAssetByIdRef.current = fetchAssetById;
  }, [fetchAssetById]);

  useEffect(() => {
    if (!active || !liveUpdates) return undefined;
    let disposed = false;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const pendingIngest = new Set<string>();
    const pendingDelete = new Set<string>();
    let pendingFull = false;

    // No `disposed` check on entry: a pass only ever starts from `flush`, whose first pass runs
    // synchronously from a timer that cleanup cancels, and whose later passes are gated by the loop's
    // own `!disposed` condition — so a pass can never begin after disposal. The post-fetch check
    // below still matters, because disposal can land while a pass is awaiting.
    const runFlushPass = async () => {
      applyPendingDeletes({ pendingDelete, pendingIngest, setAssets });
      if (pendingFull || filtersActiveRef.current) {
        pendingFull = false;
        pendingIngest.clear();
        await reloadRef.current();
        return;
      }
      if (pendingIngest.size) {
        const ids = [...pendingIngest];
        pendingIngest.clear();
        const fetchById = fetchAssetByIdRef.current;
        if (!fetchById) {
          await reloadRef.current();
          return;
        }
        const fetched = await Promise.all(ids.map((id) => fetchById(id)));
        // The same state setter can outlive this subscription (for example after deactivation).
        if (disposed) return;
        // A missing fetch is ambiguous (filtered out? race?) — reload instead.
        if (fetched.some((a) => a === null)) {
          await reloadRef.current();
          return;
        }
        // `Promise.all` types its result through `Awaited<TAsset>`, which TS
        // cannot prove is identical to the generic `TAsset` itself — safe
        // here since the `some(a => a === null)` check above already
        // guarantees every element is non-null.
        const resolved = fetched as unknown as TAsset[];
        setAssets((prev) => mergeIngestedAssets(prev, resolved));
      }
    };

    /**
     * At most ONE pass runs at a time, and a pass requested during one is coalesced into a single
     * follow-up rather than started alongside it.
     *
     * `timer` alone did not provide that. `flush` nulled it on entry and then awaited, so a second
     * pass could start while the first was still inside `fetchById` — and by then the first had
     * already drained `pendingIngest`, so the second pass's delete found nothing there to cancel.
     * The first pass would then merge the asset the second had just removed, putting a deleted
     * asset back on screen. The `fetched.some(a => a === null)` guard does not cover it: the fetch
     * can legitimately have resolved WITH the asset, moments before it was deleted.
     *
     * Guarding the merge instead was tried and is not sufficient — `pendingDelete` is cleared by
     * whichever pass applies it, so by the time the fetching pass resumes there is nothing left to
     * re-check against. Serializing removes the precondition rather than the symptom, the same
     * reasoning `useMediaProvidersTab`'s `persist` uses for overlapping writes.
     *
     * Events arriving mid-pass are not lost: they accumulate in the same pending sets and the
     * `rerun` loop picks them up, one window later than they would have been applied before.
     */
    let flushing = false;
    let rerun = false;

    const flush = async () => {
      timer = null;
      if (flushing) {
        rerun = true;
        return;
      }
      flushing = true;
      try {
        do {
          rerun = false;
          try {
            await runFlushPass();
          } catch {
            if (!disposed) {
              pendingFull = true;
              console.error('[asset-grid] Live update failed.');
            }
          }
        } while (rerun && !disposed);
      } finally {
        flushing = false;
      }
    };

    const schedule = () => {
      if (disposed || timer) return;
      timer = setTimeout(() => void flush(), coalesceMs);
    };

    const unsubscribe = liveUpdates.subscribe({
      onIngest(id) {
        pendingIngest.add(id);
        schedule();
      },
      onDelete(id) {
        pendingDelete.add(id);
        schedule();
      },
      onFullReload() {
        pendingFull = true;
        schedule();
      },
    });

    return () => {
      disposed = true;
      if (timer) clearTimeout(timer);
      unsubscribe();
    };
  }, [active, liveUpdates, coalesceMs, setAssets]);
}

export type UseWiredAssetGridLiveUpdatesParams<TAsset extends AssetGridItem> = Omit<
  UseAssetGridLiveUpdatesParams<TAsset>,
  'liveUpdates' | 'fetchAssetById'
> & {
  /**
   * Optional host-supplied dependencies (`liveUpdates` and `data.fetchAssetById`
   * are read here). Omit to fall back to the package's in-memory fake, which
   * carries no `liveUpdates` port — matching `AssetGrid`'s own default of
   * disabling live-merge reconciliation when no dependencies are supplied.
   */
  dependencies?: AssetGridDependencies<TAsset> | undefined;
};

/**
 * Wirer: binds `liveUpdates` and `fetchAssetById` from `dependencies.ts` so
 * production callers don't need to import `dependencies.ts` themselves.
 * `useAssetGridLiveUpdates` itself stays fake-able in tests — this is the
 * only export in the file that touches a concrete adapter.
 */
export function useWiredAssetGridLiveUpdates<TAsset extends AssetGridItem>(
  params: UseWiredAssetGridLiveUpdatesParams<TAsset>,
): void {
  const { dependencies, ...rest } = params;
  const deps = useMemo(() => dependencies ?? createFakeAssetGridDependencies<TAsset>(), [dependencies]);
  useAssetGridLiveUpdates({
    ...rest,
    liveUpdates: deps.liveUpdates,
    fetchAssetById: deps.data.fetchAssetById?.bind(deps.data),
  });
}

