// --- directory + section derivation ----------------------------------------

export interface TreeChildren<TFile> {
  dirsAtCurrentDir: string[];
  filesAtCurrentDir: TFile[];
}

/**
 * Derives the immediate subdirectories and files visible at `currentDir`
 * from the flat `files` list plus any persisted (possibly-empty) `folders`.
 *
 * Preserves the origin's root-level behavior exactly: at the tree root
 * (`currentDir === ''`), every file is pushed into `filesAtCurrentDir` —
 * both root-level files AND files nested under a subdirectory (which also
 * contribute their top segment to `dirsAtCurrentDir`) — so the root view is
 * a flattened "everything" listing with folders offered as a secondary
 * drill-down. Inside a non-root directory, only files strictly at that one
 * level are included. Verified against the real `DesignFilesPanel.tsx`
 * (`dirsAtCurrentDir`/`filesAtCurrentDir` `useMemo`) rather than assumed —
 * this asymmetry looks surprising but is exactly what the source does.
 */
export function deriveTreeChildren<TFile extends AssetTreeFileItem>(
  files: readonly TFile[],
  folders: readonly AssetTreeFolderItem[],
  currentDir: string,
): TreeChildren<TFile> {
  const isRoot = currentDir === '';
  const prefix = isRoot ? '' : `${currentDir}/`;
  const dirs = new Set<string>();
  const localFiles = collectFileChildren({ files, prefix, isRoot, dirs });
  collectFolderChildren({ folders, prefix, dirs });
  return {
    dirsAtCurrentDir: [...dirs].sort((a, b) => a.localeCompare(b)),
    filesAtCurrentDir: localFiles,
  };
}

interface ChildSegment {
  /** The first path component below the prefix. */
  head: string;
  /** Whether the path continues past `head` (i.e. `head` is a directory). */
  nested: boolean;
}

/** The first path component of `path` below `prefix`, or `null` when `path` is outside `prefix`. */
function childSegment(path: string, prefix: string): ChildSegment | null {
  if (!path.startsWith(prefix)) return null;
  const remainder = path.slice(prefix.length);
  const slashIdx = remainder.indexOf('/');
  if (slashIdx === -1) return { head: remainder, nested: false };
  return { head: remainder.slice(0, slashIdx), nested: true };
}

/**
 * File half of {@link deriveTreeChildren}: adds each nested file's top
 * segment to `dirs` and returns the files listed at this level (every
 * in-prefix file at the root, only one-level-deep files elsewhere).
 */
function collectFileChildren<TFile extends AssetTreeFileItem>(input: {
  files: readonly TFile[];
  prefix: string;
  isRoot: boolean;
  dirs: Set<string>;
}): TFile[] {
  const localFiles: TFile[] = [];
  for (const f of input.files) {
    const segment = childSegment(f.path, input.prefix);
    if (!segment) continue;
    if (segment.nested) input.dirs.add(segment.head);
    if (!segment.nested || input.isRoot) localFiles.push(f);
  }
  return localFiles;
}

/** Folder half of {@link deriveTreeChildren}: adds each persisted folder's top segment below `prefix` to `dirs`. */
function collectFolderChildren(input: {
  folders: readonly AssetTreeFolderItem[];
  prefix: string;
  dirs: Set<string>;
}): void {
  for (const folder of input.folders) {
    const segment = childSegment(folder.path, input.prefix);
    if (!segment) continue;
    if (!segment.nested && !segment.head) continue; // the current directory itself
    input.dirs.add(segment.head);
  }
}

/** Total files (at every depth, not just the immediate level) under `dirPath` — what a folder row's "N files" subtitle counts. */
export function countFilesUnderDir<TFile extends AssetTreeFileItem>(
  files: readonly TFile[],
  dirPath: string,
): number {
  const prefix = `${dirPath}/`;
  let count = 0;
  for (const f of files) {
    if (f.path.startsWith(prefix)) count += 1;
  }
  return count;
}

/**
 * Groups files at the current level into kind sections, ordered by the
 * host's `sectionOrder` with any kind absent from it appended afterward in
 * first-seen order (the origin's `SECTION_ORDER` never needed this fallback
 * since it enumerated every `ProjectFileKind` — this package's `kind` is an
 * arbitrary host string, so an unconfigured kind must still render
 * somewhere rather than silently vanishing). Files within a section sort
 * most-recently-modified first.
 */
export function groupFilesByKind<TFile>(
  files: readonly TFile[],
  sectionOrder: readonly string[],
  getKind: (file: TFile) => string,
  getModifiedAt: (file: TFile) => number,
): AssetTreeSection<TFile>[] {
  const grouped = new Map<string, TFile[]>();
  const firstSeenOrder: string[] = [];
  for (const f of files) {
    const kind = getKind(f);
    let bucket = grouped.get(kind);
    if (!bucket) {
      bucket = [];
      grouped.set(kind, bucket);
      firstSeenOrder.push(kind);
    }
    bucket.push(f);
  }
  for (const bucket of grouped.values()) {
    bucket.sort((a, b) => getModifiedAt(b) - getModifiedAt(a));
  }
  const ordered = sectionOrder.filter((kind) => grouped.has(kind));
  const seen = new Set(ordered);
  for (const kind of firstSeenOrder) {
    if (!seen.has(kind)) {
      ordered.push(kind);
      seen.add(kind);
    }
  }
  return ordered.map((kind) => ({ kind, files: grouped.get(kind)! }));
}

/**
 * The nearest ancestor of `currentDir` that still exists (has files under it
 * or is itself a persisted folder), or `''` if none do. Returns `null` when
 * no correction is needed (already at the root, or `currentDir` itself still
 * exists) — callers should treat `null` as "don't navigate".
 */
export function nextExistingAncestorDir<TFile extends AssetTreeFileItem>(
  files: readonly TFile[],
  folders: readonly AssetTreeFolderItem[],
  currentDir: string,
): string | null {
  if (currentDir === '') return null;
  const dirExists = (dir: string) =>
    files.some((f) => f.path.startsWith(`${dir}/`)) ||
    folders.some((fo) => fo.path === dir || fo.path.startsWith(`${dir}/`));
  if (dirExists(currentDir)) return null;
  const parts = currentDir.split('/');
  for (let i = parts.length - 1; i > 0; i--) {
    const ancestor = parts.slice(0, i).join('/');
    if (dirExists(ancestor)) return ancestor;
  }
  return '';
}

// --- selection ---------------------------------------------------------

export function toggleInSet(prev: ReadonlySet<string>, path: string): Set<string> {
  const next = new Set(prev);
  if (next.has(path)) next.delete(path);
  else next.add(path);
  return next;
}

/**
 * Drops selected paths absent from `livePaths`. Returns `prev` unchanged
 * (the exact same `Set` reference) when nothing was dropped, so a caller's
 * `setSelected` bails out of the state update instead of forcing an extra
 * render — same reasoning as `features/asset-grid/rules.ts`'s
 * `pruneMissingSelection`.
 */
export function pruneMissingPaths(prev: Set<string>, livePaths: Iterable<string>): Set<string> {
  if (prev.size === 0) return prev;
  const live = new Set(livePaths);
  const next = new Set(prev);
  let changed = false;
  for (const p of next) {
    if (!live.has(p)) {
      next.delete(p);
      changed = true;
    }
  }
  return changed ? next : prev;
}

// --- rename ---------------------------------------------------------

/** The editable basename for `path` when renaming inside `currentDir` (strips the directory prefix). */
export function basenameForRename(path: string, currentDir: string): string {
  return currentDir === '' ? path : path.slice(currentDir.length + 1);
}

export interface RenameCommitDecision {
  nextPath: string;
}

/**
 * Whether a commit of `draft` (the edited basename) should proceed, and the
 * resulting full path if so. Returns `null` for the two no-op cases the
 * origin's `commitRename` short-circuits on: an empty (whitespace-only)
 * draft, or a draft that resolves back to the exact same path.
 */
export function resolveRenameCommit(path: string, currentDir: string, draft: string): RenameCommitDecision | null {
  const nextBasename = draft.trim();
  if (!nextBasename) return null;
  const nextPath = currentDir === '' ? nextBasename : `${currentDir}/${nextBasename}`;
  if (nextPath === path) return null;
  return { nextPath };
}

// --- row context menu ---------------------------------------------------

export interface MenuAnchorRect {
  top: number;
  bottom: number;
  right: number;
}

export interface MenuPositionOptions {
  estimatedHeight?: number;
  safePadding?: number;
}

/**
 * Viewport-flip position for the row context menu: opens below its anchor
 * when there's room, above when there isn't but there IS room above, and
 * otherwise clamps to the viewport with `safePadding` clearance.
 */
export function computeMenuPosition(
  anchor: MenuAnchorRect,
  viewportHeight: number,
  options: MenuPositionOptions = {},
): { top: number; left: number } {
  const estimatedHeight = options.estimatedHeight ?? ROW_MENU_ESTIMATED_HEIGHT_PX;
  const safePadding = options.safePadding ?? ROW_MENU_SAFE_PADDING_PX;
  const spaceBelow = viewportHeight - anchor.bottom;
  const spaceAbove = anchor.top;
  let top: number;
  if (spaceBelow >= estimatedHeight + safePadding) {
    top = anchor.bottom + 4;
  } else if (spaceAbove >= estimatedHeight + safePadding) {
    top = anchor.top - estimatedHeight - 4;
  } else {
    top = Math.max(safePadding, viewportHeight - estimatedHeight - safePadding);
  }
  const left = Math.max(safePadding, anchor.right - 160);
  return { top, left };
}

/** Whether the row menu's "copy local path" action should be enabled for `file`. */
export function canCopyLocalPath<TFile>(file: TFile, selectors: AssetTreeSelectors<TFile>): boolean {
  return !!selectors.getLocalPath?.(file);
}

// --- keyboard row activation ---------------------------------------------------

/** Whether `nowMs` lands within `windowMs` of a prior activation timestamp — the double-Enter-to-open gesture on a keyboard-focused row name. */
export function isDoubleActivation(
  lastTimestampMs: number | undefined,
  nowMs: number,
  windowMs: number = DOUBLE_ACTIVATION_WINDOW_MS,
): boolean {
  return lastTimestampMs !== undefined && nowMs - lastTimestampMs < windowMs;
}

// --- display formatting ---------------------------------------------------

/** Display config for `kind`, falling back to the raw kind key as the label and a generic glyph when the host's `AssetTreeKindConfigMap` has no entry for it. */
export function resolveKindConfig(kind: string, kindConfig: AssetTreeKindConfigMap): AssetTreeKindConfig {
  return kindConfig[kind] ?? { label: kind, glyph: DEFAULT_KIND_GLYPH };
}

export function humanBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(1)} MB`;
}

/** See {@link AssetTreeRelativeTime} for why this returns a template + params instead of a finished string. */
export function relativeTimeResult(ts: number, nowMs: number = Date.now()): AssetTreeRelativeTime {
  const diff = nowMs - ts;
  const min = 60_000;
  const hr = 60 * min;
  const day = 24 * hr;
  if (diff < min) return { label: 'Just now', translatable: true };
  if (diff < hr) return { label: '{n}m ago', translatable: true, params: { n: Math.floor(diff / min) } };
  if (diff < day) return { label: '{n}h ago', translatable: true, params: { n: Math.floor(diff / hr) } };
  if (diff < 7 * day) return { label: '{n}d ago', translatable: true, params: { n: Math.floor(diff / day) } };
  if (diff < 30 * day) {
    return { label: '{n}w ago', translatable: true, params: { n: Math.floor(diff / (7 * day)) } };
  }
  return { label: new Date(ts).toLocaleDateString(), translatable: false };
}

/** Uppercase extension for a path's display, e.g. `"a/b.TXT"` -> `"TXT"`; `""` for an extensionless or dotfile-only path. */
export function fileExtensionLabel(path: string): string {
  const dot = path.lastIndexOf('.');
  if (dot < 0 || dot === path.length - 1) return '';
  return path.slice(dot + 1).toUpperCase();
}

/** Breadcrumb segments for every path component below the tree root (the root itself is rendered separately by `Breadcrumbs` since its label is host-configurable). */
export function buildBreadcrumbSegments(currentDir: string): AssetTreeBreadcrumbSegment[] {
  const parts = currentDir.split('/').filter(Boolean);
  return parts.map((segment, idx) => ({
    path: parts.slice(0, idx + 1).join('/'),
    label: segment,
    isLast: idx === parts.length - 1,
  }));
}

import type {
  AddressDisplayParts,
  BrowserHistoryEntry,
  BrowserNavigationEntry,
  BrowserNavigationState,
} from './types.js';
import { DEFAULT_HOME_NAVIGATION_ENTRY, EMPTY_URL, HISTORY_LIMIT } from './constants.js';
import { trimTrailingChars } from '../../utils/trim-chars.js';

// ---------------------------------------------------------------------------
// Address normalization
// ---------------------------------------------------------------------------

export interface NormalizeBrowserAddressOptions {
  /**
   * Absolute-path prefixes (e.g. `['api', 'artifacts']`) that should resolve
   * against `appOrigin` instead of being treated as a local file path. A host
   * whose app serves its own routes under the same origin the browser tab is
   * embedded in supplies this; omit both to always fall back to `file://`.
   */
  appRoutePrefixes?: string[];
  /** Origin `appRoutePrefixes` matches resolve against — typically the host's `window.location.origin`. */
  appOrigin?: string;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Resolves a `/`-rooted address: against `appOrigin` when it matches a configured app-route prefix, else as a local `file://` path. */
function resolveAbsolutePath(value: string, options: NormalizeBrowserAddressOptions): string {
  const { appRoutePrefixes = [], appOrigin } = options;
  if (appOrigin && appRoutePrefixes.length > 0) {
    const prefixPattern = new RegExp(`^/(${appRoutePrefixes.map(escapeRegExp).join('|')})(/|$)`);
    if (prefixPattern.test(value)) return new URL(value, appOrigin).toString();
  }
  return `file://${encodeURI(value)}`;
}

export function normalizeBrowserAddress(rawAddress: string, options: NormalizeBrowserAddressOptions = {}): string {
  const value = rawAddress.trim();
  if (!value || value === EMPTY_URL) return EMPTY_URL;
  if (/^(https?|file):\/\//i.test(value)) return value;
  if (/^(localhost|127\.0\.0\.1|0\.0\.0\.0)(:\d+)?(\/.*)?$/i.test(value)) return `http://${value}`;
  if (value.startsWith('/')) return resolveAbsolutePath(value, options);
  if (/^[\w.-]+\.[a-z]{2,}(:\d+)?(\/.*)?$/i.test(value)) return `https://${value}`;
  return `https://www.google.com/search?q=${encodeURIComponent(value)}`;
}

export function labelFromUrl(url: string, homeLabel: string = DEFAULT_HOME_NAVIGATION_ENTRY.title): string {
  if (url === EMPTY_URL) return homeLabel;
  try {
    const parsed = new URL(url);
    return parsed.hostname.replace(/^www\./, '') || url;
  } catch {
    return url;
  }
}

export function formatAddressDisplayParts(
  url: string,
  title?: string,
  homeLabel: string = DEFAULT_HOME_NAVIGATION_ENTRY.title,
): AddressDisplayParts {
  if (url === EMPTY_URL) return { url: '' };
  const cleanTitle = title?.trim();
  if (!cleanTitle) return { url };
  const fallback = labelFromUrl(url, homeLabel);
  if (cleanTitle === fallback || cleanTitle === url) return { url };
  return { url: trimTrailingChars(url, '/'), title: cleanTitle };
}

export function formatAddressDisplay(
  url: string,
  title?: string,
  homeLabel: string = DEFAULT_HOME_NAVIGATION_ENTRY.title,
): string {
  const parts = formatAddressDisplayParts(url, title, homeLabel);
  if (!parts.url) return '';
  if (!parts.title) return parts.url;
  return `${parts.url} / ${parts.title}`;
}

export function hostnameFromUrl(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url;
  }
}

function isHttpLikeUrl(url: string): boolean {
  return /^https?:\/\//i.test(url);
}

export function faviconUrl(url: string): string | undefined {
  if (!isHttpLikeUrl(url)) return undefined;
  try {
    return new URL('/favicon.ico', new URL(url).origin).toString();
  } catch {
    return undefined;
  }
}

export function isHistoryUrl(url: string): boolean {
  return url !== EMPTY_URL && (isHttpLikeUrl(url) || /^file:\/\//i.test(url));
}

export function sameUrl(left: string, right: string): boolean {
  return trimTrailingChars(left, '/') === trimTrailingChars(right, '/');
}

function cleanIconUrl(url?: string): string | undefined {
  const value = url?.trim();
  if (!value) return undefined;
  if (/^https?:\/\//i.test(value) || /^data:image\//i.test(value)) return value;
  return undefined;
}

// ---------------------------------------------------------------------------
// History entries
// ---------------------------------------------------------------------------

export function isHistoryEntry(value: unknown): value is BrowserHistoryEntry {
  if (typeof value !== 'object' || value == null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.url === 'string'
    && typeof record.title === 'string'
    && typeof record.lastVisitedAt === 'number'
    && typeof record.visitCount === 'number'
    && (record.iconUrl === undefined || typeof record.iconUrl === 'string')
  );
}

/** Namespace + scope key -> storage key. Namespace defaults to a generic Jini prefix (see `constants.ts`); scope key is host-supplied (e.g. a project or tab id). */
export function historyStorageKey(namespace: string, scopeKey: string): string {
  return `${namespace}:${scopeKey}`;
}

/** Parses a raw JSON storage payload into a sorted, deduped, limit-capped history list. Never throws — returns `[]` on any malformed input. */
export function parseHistoryPayload(raw: string, limit: number = HISTORY_LIMIT): BrowserHistoryEntry[] {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter(isHistoryEntry)
      .sort((left, right) => right.lastVisitedAt - left.lastVisitedAt)
      .slice(0, limit);
  } catch {
    return [];
  }
}

export function serializeHistoryPayload(history: BrowserHistoryEntry[], limit: number = HISTORY_LIMIT): string {
  return JSON.stringify(history.slice(0, limit));
}

export interface MergeHistoryEntryMeta {
  title?: string;
  iconUrl?: string;
}

export interface MergeHistoryEntryOptions {
  /** Pass `false` to update an entry's metadata without counting a visit (e.g. a back/forward replay). Defaults to counting. */
  countVisit?: boolean;
}

/**
 * Merges a visited URL into a history list: updates the existing entry in
 * place (bumping it to the front) or inserts a new one, returning the SAME
 * array reference when nothing actually changed (so callers can skip a
 * re-render/re-save). `now` is injectable for deterministic tests.
 */
export function mergeHistoryEntry(
  history: BrowserHistoryEntry[],
  url: string,
  meta: MergeHistoryEntryMeta = {},
  options: MergeHistoryEntryOptions = {},
  now: number = Date.now(),
): BrowserHistoryEntry[] {
  if (!isHistoryUrl(url)) return history;
  const existing = history.find((entry) => sameUrl(entry.url, url));
  const entry = buildHistoryEntry({ url, meta, now, countVisit: options.countVisit !== false }, { existing });
  if (existing && sameHistoryEntryState(existing, entry)) return history;
  return [entry, ...history.filter((item) => !sameUrl(item.url, url))].slice(0, HISTORY_LIMIT);
}

interface BuildHistoryEntryInput {
  url: string;
  meta: MergeHistoryEntryMeta;
  now: number;
  countVisit: boolean;
}

/** Builds the merged entry for `url`: an update of `existing` when present, otherwise a fresh first-visit entry. */
function buildHistoryEntry(
  { url, meta, now, countVisit }: BuildHistoryEntryInput,
  { existing }: { existing?: BrowserHistoryEntry | undefined },
): BrowserHistoryEntry {
  const resolved = resolveHistoryMeta({ url, meta }, { existing });
  if (!existing) return { ...resolved, url, lastVisitedAt: now, visitCount: 1 };
  return {
    ...existing,
    ...resolved,
    lastVisitedAt: countVisit ? now : existing.lastVisitedAt,
    visitCount: existing.visitCount + (countVisit ? 1 : 0),
  };
}

/** Title and icon for a merged entry: the caller's meta wins, then the existing entry's, then values derived from `url`. */
function resolveHistoryMeta(
  { url, meta }: { url: string; meta: MergeHistoryEntryMeta },
  { existing }: { existing?: BrowserHistoryEntry | undefined },
): { iconUrl?: string; title: string } {
  // `isHistoryUrl` above already excludes `EMPTY_URL`, so `labelFromUrl`'s
  // home-label branch can never trigger here — no `homeLabel` option to pass.
  const title = meta.title?.trim() || existing?.title || labelFromUrl(url);
  const iconUrl = cleanIconUrl(meta.iconUrl) || existing?.iconUrl || faviconUrl(url);
  return iconUrl !== undefined ? { iconUrl, title } : { title };
}

function sameHistoryEntryState(left: BrowserHistoryEntry, right: BrowserHistoryEntry): boolean {
  return (
    left.title === right.title
    && left.iconUrl === right.iconUrl
    && left.lastVisitedAt === right.lastVisitedAt
    && left.visitCount === right.visitCount
  );
}

// ---------------------------------------------------------------------------
// Navigation stack
// ---------------------------------------------------------------------------

export function initialNavigationState(
  initialUrl?: string,
  initialTitle?: string,
  homeEntry: BrowserNavigationEntry = DEFAULT_HOME_NAVIGATION_ENTRY,
): BrowserNavigationState & { url: string; addressValue: string } {
  const trimmedUrl = initialUrl?.trim();
  const url = trimmedUrl && isHistoryUrl(trimmedUrl) ? trimmedUrl : EMPTY_URL;
  if (url === EMPTY_URL) {
    return {
      addressValue: '',
      navigationIndex: 0,
      navigationStack: [homeEntry],
      url,
    };
  }
  const title = initialTitle?.trim() || labelFromUrl(url, homeEntry.title);
  return {
    addressValue: url,
    navigationIndex: 0,
    navigationStack: [{ title, url }],
    url,
  };
}

export interface RecordNavigationOptions {
  replacePendingTarget?: boolean;
  pendingTarget?: string | null;
  homeLabel?: string;
}

/**
 * Records a navigation into the stack: updates the current entry in place if
 * the URL matches it (or an adjacent back/forward entry, or a pending-load
 * target), otherwise truncates any forward history and appends a new entry —
 * the same "linear stack with in-place back/forward matching" model a real
 * browser's history uses.
 */
export function recordNavigation(
  state: BrowserNavigationState,
  url: string,
  title?: string,
  options: RecordNavigationOptions = {},
): BrowserNavigationState {
  if (url !== EMPTY_URL && !isHistoryUrl(url)) return state;

  const { navigationStack: stack, navigationIndex: index } = state;
  const nextTitle = navigationTitle({ url }, { title, homeLabel: options.homeLabel });
  const rejoin = findRejoinTarget({ state, url }, options);
  if (rejoin) {
    const next = stack.slice();
    // `nextTitle` is only ever '' for EMPTY_URL with an explicit '' homeLabel;
    // keep the rejoined entry's own title rather than blanking it.
    next[rejoin.index] = { title: nextTitle || rejoin.entry.title, url };
    return { navigationStack: next, navigationIndex: rejoin.index };
  }

  const base = index >= 0 ? stack.slice(0, index + 1) : [];
  const nextStack = [...base, { title: nextTitle, url }].slice(-HISTORY_LIMIT);
  return { navigationStack: nextStack, navigationIndex: nextStack.length - 1 };
}

function navigationTitle({ url }: { url: string }, { title, homeLabel }: { title?: string | undefined; homeLabel?: string | undefined }): string {
  // Bug fix: this used to hardcode DEFAULT_HOME_NAVIGATION_ENTRY.title here,
  // ignoring a caller-supplied `options.homeLabel` — so a host configuring a
  // custom `homeEntry` (via useBrowserNavigationStack) would see the entry's
  // title silently revert to "New Tab" on any navigation back to EMPTY_URL,
  // even though `initialNavigationState`/`labelFromUrl` both honor the
  // custom label correctly. Falls back to the generic default only when no
  // homeLabel is supplied.
  if (url === EMPTY_URL) return homeLabel ?? DEFAULT_HOME_NAVIGATION_ENTRY.title;
  return title?.trim() || labelFromUrl(url, homeLabel);
}

interface RejoinTarget {
  index: number;
  entry: BrowserNavigationEntry;
}

/**
 * The stack entry `url` should update in place instead of appending: the
 * current entry (same url, or the pending-load target being replaced), else
 * the adjacent back entry, else the adjacent forward entry. An out-of-range
 * index reads as `undefined`, which never matches.
 */
function findRejoinTarget(
  { state, url }: { state: BrowserNavigationState; url: string },
  { replacePendingTarget, pendingTarget }: RecordNavigationOptions,
): RejoinTarget | undefined {
  const { navigationStack: stack, navigationIndex: index } = state;
  const current = stack[index];
  if (current && (sameUrl(current.url, url) || (replacePendingTarget && pendingTarget && sameUrl(current.url, pendingTarget)))) {
    return { index, entry: current };
  }
  return [index - 1, index + 1]
    .map((candidate) => ({ index: candidate, entry: stack[candidate] }))
    .find((target): target is RejoinTarget => target.entry !== undefined && sameUrl(target.entry.url, url));
}

export function updateCurrentNavigationTitle(state: BrowserNavigationState, title?: string): BrowserNavigationState {
  const trimmedTitle = title?.trim();
  const { navigationStack: stack, navigationIndex: index } = state;
  if (!trimmedTitle || index < 0) return state;
  const currentEntry = stack[index];
  if (!currentEntry || currentEntry.title === trimmedTitle) return state;
  const nextStack = stack.slice();
  nextStack[index] = { ...currentEntry, title: trimmedTitle };
  return { navigationStack: nextStack, navigationIndex: index };
}

export interface NavigationHistoryDeltaResult {
  state: BrowserNavigationState;
  entry: BrowserNavigationEntry;
}

/** Resolves a back (`delta: -1`) or forward (`delta: 1`) step. Returns `null` at either end of the stack. */
export function resolveNavigationHistoryDelta(
  state: BrowserNavigationState,
  delta: -1 | 1,
): NavigationHistoryDeltaResult | null {
  const targetIndex = state.navigationIndex + delta;
  const entry = state.navigationStack[targetIndex];
  if (!entry) return null;
  return {
    state: { navigationStack: state.navigationStack.slice(), navigationIndex: targetIndex },
    entry,
  };
}

export function canGoBack(state: BrowserNavigationState): boolean {
  return state.navigationIndex > 0;
}

export function canGoForward(state: BrowserNavigationState): boolean {
  return state.navigationIndex >= 0 && state.navigationIndex < state.navigationStack.length - 1;
}

import { useState } from 'react';
import { isBaseUrlInvalid, missingRequiredFields } from '../../rules.js';
import type { ByokConfig, ProviderPreset } from '../../types.js';

type Field = 'apiKey' | 'baseUrl' | 'model';

/** Keeps required-field gates immediate while optionally waiting for blur to paint errors.
 * Stored keys satisfy only the key requirement; touching one provider never marks another.
 * @complexity Time/space: O(1), bounded by the three required fields.
 */
export function useByokFieldValidation(
  required: { config: ByokConfig; preset: ProviderPreset | null; apiKeyStoredExternally: boolean },
  optional: { deferMissingFeedback?: boolean } = {},
) {
  const { config, preset, apiKeyStoredExternally } = required;
  const [touched, setTouched] = useState<{ providerId: ByokConfig['providerId']; fields: Set<Field> }>(
    { providerId: config.providerId, fields: new Set() },
  );
  const missing = new Set(missingRequiredFields(config, preset));
  if (apiKeyStoredExternally) missing.delete('apiKey');
  const baseUrlInvalid = isBaseUrlInvalid(config);

  return {
    missing,
    baseUrlInvalid,
    isMissing: ({ field }: { field: Field }, _options: Record<string, never> = {}) =>
      (missing.has(field) || (field === 'baseUrl' && baseUrlInvalid)) &&
      (!optional.deferMissingFeedback || (touched.providerId === config.providerId && touched.fields.has(field))),
    markTouched: ({ field }: { field: Field }, _options: Record<string, never> = {}) => {
      setTouched(current => ({
        providerId: config.providerId,
        fields: new Set([...(current.providerId === config.providerId ? current.fields : []), field]),
      }));
    },
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { ExecutionPort } from '../../ports.js';
import { sortDetectedAgents } from '../../rules.js';
import type {
  AgentScanState,
  AgentTestState,
  ByokConfig,
  ConnectionTestState,
  DetectedAgent,
  ModelDiscoveryState,
} from '../../types.js';

export interface UseExecutionTabOptions {
  port: ExecutionPort;
  /** Skips the mount-time detection call — useful when the host already has
   *  agents in hand, or when the tab is rendered but not visible. */
  autoDetect?: boolean;
  /**
   * Turns a rejected BYOK probe (`testConnection` or `listModels`) into the message the tab shows.
   * Defaults to the error's own message.
   *
   * For a host whose backend refuses some probes in words written for API callers. The host knows its
   * own error codes and the operator's locale; this package knows neither.
   *
   * Read through a ref when the probe settles, so it never becomes part of `testConnection`'s or
   * `loadModels`'s identity. Hosts pass inline arrows, and `ExecutionTab`'s discovery effect depends on
   * `loadModels`: an identity that followed this function would re-probe on every render.
   */
  describeProbeError?: (error: unknown) => string;
}

export interface UseExecutionTabResult {
  agents: readonly DetectedAgent[];
  scan: AgentScanState;
  connectionTest: ConnectionTestState;
  /** Result of the most recent `loadModels` call. `{status:'idle'}` until one
   *  runs. A `'error'` state is a real, renderable failure — distinct from
   *  `'ok'` with an empty list — see `ModelDiscoveryState`'s doc. */
  modelDiscovery: ModelDiscoveryState;
  /** Result of the most recent per-agent Test. Carries the `agentId` it
   *  belongs to so a card only renders its OWN result — without that, testing
   *  one agent and then selecting another would show the first agent's verdict
   *  under the second one's card. */
  agentTest: AgentTestState;
  rescan: () => void;
  testConnection: (config: ByokConfig) => void;
  testAgent: (agentId: string, model?: string | undefined) => void;
  loadModels: (config: ByokConfig) => void;
  /** Returns `modelDiscovery` to `idle` and discards any `loadModels` response still in flight. Sends
   *  nothing. For a host that says discovery cannot run — see `ExecutionTab`'s `canDiscoverModels`. */
  resetModelDiscovery: () => void;
  canRescan: boolean;
  canTestAgent: boolean;
}

/** A rejected async edge's default message: the error's own text. */
function describeErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Owns the tab's async edges: local-agent detection, rescan, connection test,
 * and optional model discovery. Config state itself stays with the host — the
 * tab is controlled, so a host can persist to its own store on every change.
 *
 * Every async result is dropped if the hook unmounted first, so a slow probe
 * can't set state on a torn-down tree.
 */
export function useExecutionTab({
  port,
  autoDetect = true,
  describeProbeError = describeErrorMessage,
}: UseExecutionTabOptions): UseExecutionTabResult {
  const [agents, setAgents] = useState<readonly DetectedAgent[]>([]);
  const [scan, setScan] = useState<AgentScanState>({ status: 'idle' });
  const [connectionTest, setConnectionTest] = useState<ConnectionTestState>({ status: 'idle' });
  const [modelDiscovery, setModelDiscovery] = useState<ModelDiscoveryState>({ status: 'idle' });
  const [agentTest, setAgentTest] = useState<AgentTestState>({ status: 'idle' });

  /*
   * One monotonic ticket per async edge.
   *
   * `alive` alone is NOT enough: it only stops a result landing after UNMOUNT,
   * and says nothing about ORDER. Every edge here can be launched again before
   * the previous call settles — the operator switches provider mid-discovery,
   * clicks Test twice, rescans while a scan is running — and responses are not
   * guaranteed to return in the order they were sent. Without a ticket the
   * slower FIRST response lands last and overwrites the newer one, so the form
   * shows provider A's models under provider B, or A's failure hides B's
   * success. Only the newest ticket for an edge may write its state.
   */
  const detectionTicket = useRef(0);
  const connectionTestTicket = useRef(0);
  const agentTestTicket = useRef(0);
  const modelDiscoveryTicket = useRef(0);

  /** The host's describer as of the latest render — see `UseExecutionTabOptions.describeProbeError`. */
  const describeProbeErrorRef = useRef(describeProbeError);
  describeProbeErrorRef.current = describeProbeError;

  const detectionTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const alive = useRef(true);
  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
      clearTimeout(detectionTimer.current);
    };
  }, []);

  const runDetection: (detect: () => Promise<readonly DetectedAgent[]>) => void = useCallback(
    (detect: () => Promise<readonly DetectedAgent[]>) => {
      clearTimeout(detectionTimer.current);
      detectionTicket.current += 1;
      const ticket = detectionTicket.current;
      const isCurrent = () => alive.current && detectionTicket.current === ticket;
      setScan({ status: 'scanning' });
      detect().then(
        (found) => {
          if (!isCurrent()) return;
          const sorted = sortDetectedAgents(found);
          setAgents(sorted);
          setScan({ status: 'ok', count: sorted.filter((agent) => agent.installed).length });
          if (found.some(agent => agent.discoveryPending)) {
            detectionTimer.current = setTimeout(() => {
              if (isCurrent()) runDetection(() => port.detectLocalAgents());
            }, 1000);
          }
        },
        (error: unknown) => {
          if (!isCurrent()) return;
          setScan({ status: 'error', message: describeErrorMessage(error) });
        },
      );
    },
    [port],
  );

  useEffect(() => {
    if (!autoDetect) return;
    runDetection(() => port.detectLocalAgents());
  }, [autoDetect, port, runDetection]);

  const rescan = useCallback(() => {
    const rescanFn = port.rescanLocalAgents;
    if (!rescanFn) return;
    runDetection(() => rescanFn.call(port));
  }, [port, runDetection]);

  const testConnection = useCallback(
    (config: ByokConfig) => {
      connectionTestTicket.current += 1;
      const ticket = connectionTestTicket.current;
      const isCurrent = () => alive.current && connectionTestTicket.current === ticket;
      setConnectionTest({ status: 'testing' });
      port.testConnection(config).then(
        (result) => {
          if (!isCurrent()) return;
          setConnectionTest(
            result.ok
              ? { status: 'ok', message: result.message }
              : { status: 'error', message: result.message ?? 'Connection failed' },
          );
        },
        (error: unknown) => {
          if (!isCurrent()) return;
          setConnectionTest({ status: 'error', message: describeProbeErrorRef.current(error) });
        },
      );
    },
    [port],
  );

  const testAgent = useCallback(
    (agentId: string, model?: string | undefined) => {
      const run = port.testAgent;
      if (!run) return;
      agentTestTicket.current += 1;
      const ticket = agentTestTicket.current;
      const isCurrent = () => alive.current && agentTestTicket.current === ticket;
      setAgentTest({ status: 'testing', agentId });
      run.call(port, agentId, model).then(
        (result) => {
          if (!isCurrent()) return;
          setAgentTest(
            result.ok
              ? {
                  status: 'ok',
                  agentId,
                  message: result.message,
                  // Passed through (not derived) so `agentExecutableRepairState`
                  // can only ever act on what the host's own probe actually
                  // reported — see `ExecutionPort.testAgent`'s doc.
                  usedExecutableSource: result.usedExecutableSource,
                  detectedExecutablePath: result.detectedExecutablePath,
                }
              : { status: 'error', agentId, message: result.message ?? 'Agent check failed' },
          );
        },
        (error: unknown) => {
          if (!isCurrent()) return;
          setAgentTest({ status: 'error', agentId, message: describeErrorMessage(error) });
        },
      );
    },
    [port],
  );

  const loadModels = useCallback(
    (config: ByokConfig) => {
      const listModels = port.listModels;
      if (!listModels) return;
      modelDiscoveryTicket.current += 1;
      const ticket = modelDiscoveryTicket.current;
      const isCurrent = () => alive.current && modelDiscoveryTicket.current === ticket;
      setModelDiscovery({ status: 'loading' });
      listModels.call(port, config).then(
        (found) => {
          if (!isCurrent()) return;
          setModelDiscovery({ status: 'ok', models: found });
        },
        (error: unknown) => {
          // Error-reporting contract §3.2: non-blocking ≠ silent. The Model
          // field stays usable (the component still falls back to the
          // preset's `preferredModels` when `modelDiscovery.status !== 'ok'`)
          // but the failure itself is a real, renderable state — auth
          // failures, timeouts, and unreachable endpoints are all operator-
          // actionable and must not read as "this provider has no models."
          if (!isCurrent()) return;
          setModelDiscovery({ status: 'error', message: describeProbeErrorRef.current(error) });
        },
      );
    },
    [port],
  );

  const resetModelDiscovery = useCallback(() => {
    // Taking a new ticket is what discards a response still in flight: its `isCurrent()` goes false.
    ++modelDiscoveryTicket.current;
    setModelDiscovery({ status: 'idle' });
  }, []);

  return {
    agents,
    scan,
    connectionTest,
    modelDiscovery,
    agentTest,
    rescan,
    testConnection,
    testAgent,
    loadModels,
    resetModelDiscovery,
    canRescan: typeof port.rescanLocalAgents === 'function',
    canTestAgent: typeof port.testAgent === 'function',
  };
}

import { useState } from 'react';
import { CUSTOM_MODEL_SENTINEL } from '../../constants.js';
import { agentExecutableRepairState, binPathEnvField, cliEnvFieldsForAgent } from '../../rules.js';
import type { AgentCliEnvFieldSpec, AgentTestState, DetectedAgent, LocalCliConfig } from '../../types.js';
import { useReasoningControl, type UseReasoningControlResult } from './useReasoningControl.js';

type Translate = (key: string) => string;

export interface UseLocalCliAgentCardInput {
  agent: DetectedAgent;
  config: LocalCliConfig;
  agentTest: AgentTestState;
  cliEnvFields: readonly AgentCliEnvFieldSpec[];
  onModelChange: (agentId: string, model: string) => void;
  onReasoningChange: (agentId: string, reasoning: string) => void;
  onRescan?: (() => void) | undefined;
  /** Only its presence matters here: a Test button alone is enough to show the settings strip. */
  onTest?: ((agent: DetectedAgent) => void) | undefined;
  t: Translate;
}

export interface UseLocalCliAgentCardResult {
  reasoning: UseReasoningControlResult;
  /** Whether the selected card's settings strip has anything to show; without this it rendered
   *  as an empty bordered box for a CLI with no models, effort, Test or env fields. */
  hasSettings: boolean;
  /** `agent.modelsSource`, passed through for the badge's modifier class. */
  source: DetectedAgent['modelsSource'];
  sourceLabel: string;
  sourceHint: string;
  testing: boolean;
  result: Extract<AgentTestState, { status: 'ok' | 'error' }> | null;
  repair: ReturnType<typeof agentExecutableRepairState>;
  repairField: AgentCliEnvFieldSpec | null;
  diagnosticHandlers: {
    onRescan: (() => void) | undefined;
    onOpenInstall: (() => void) | undefined;
    onOpenDocs: (() => void) | undefined;
  };
  /** The model picker's change handler, including its "Custom…" sentinel. */
  selectModel: (nextValue: string) => void;
  /** The reasoning picker's change handler, including the model-suffix shape. */
  selectReasoning: (nextValue: string) => void;
}

/**
 * Everything `LocalCliAgentCard` and its settings strip derive from one agent, kept out of the
 * `.tsx` so both render from the same values.
 */
export function useLocalCliAgentCard({
  agent,
  config,
  agentTest,
  cliEnvFields,
  onModelChange,
  onReasoningChange,
  onRescan,
  onTest,
  t,
}: UseLocalCliAgentCardInput): UseLocalCliAgentCardResult {
  // Whether the operator explicitly opened the free-text "Custom" entry via
  // the model picker's own "Custom…" option — distinct from "the saved model
  // simply isn't in the known list" (`shouldShowCustomModelInput` covers
  // both, but only THIS one needs to be remembered as a UI-local toggle,
  // since it is not itself persisted config: see `LocalCliConfig`, which has
  // nowhere for "the operator is mid-typing a custom id" to live). Scoped to
  // this card instance, so switching to a different agent and back does not
  // leak one agent's custom-mode toggle onto another.
  const [explicitCustomMode, setExplicitCustomMode] = useState(false);

  const reasoning = useReasoningControl({
    agent,
    config,
    explicitCustomMode,
    onReasoningChange: (next) => onReasoningChange(agent.id, next),
  });

  const { source, sourceLabel, sourceHint } = modelSourcePresentation({ source: agent.modelsSource, t });
  const { testing, result, repair, repairField } = agentTestPresentation({ agent, agentTest, cliEnvFields });

  const openUrl = (url: string | undefined) => {
    if (!url) return;
    window.open(url, '_blank', 'noopener,noreferrer');
  };
  const diagnosticHandlers = {
    onRescan,
    onOpenInstall: agent.installUrl ? () => openUrl(agent.installUrl) : undefined,
    onOpenDocs: agent.docsUrl ? () => openUrl(agent.docsUrl) : undefined,
  };

  const selectModel = (nextValue: string) => {
    if (nextValue === CUSTOM_MODEL_SENTINEL) {
      setExplicitCustomMode(true);
      onModelChange(agent.id, '');
      return;
    }
    setExplicitCustomMode(false);
    onModelChange(agent.id, reasoning.resolveNextModelId(nextValue));
  };

  const selectReasoning = (nextValue: string) => {
    // A model-suffix agent has no reasoning value of its own to record: the choice
    // is which model id runs, so it goes back out through `onModelChange`.
    const suffixModelId = reasoning.resolveReasoningModelId(nextValue);
    if (suffixModelId !== null) {
      onModelChange(agent.id, suffixModelId);
      return;
    }
    onReasoningChange(agent.id, nextValue);
  };

  const hasSettings =
    reasoning.hasModels ||
    reasoning.hasReasoning ||
    Boolean(onTest) ||
    result !== null ||
    cliEnvFieldsForAgent(cliEnvFields, agent.id).length > 0;

  return {
    reasoning,
    hasSettings,
    source,
    sourceLabel,
    sourceHint,
    testing,
    result,
    repair,
    repairField,
    diagnosticHandlers,
    selectModel,
    selectReasoning,
  };
}

/** Model-list provenance claims, translated only when the host supplied a source. */
function modelSourcePresentation(
  { source, t }: { source: DetectedAgent['modelsSource']; t: Translate },
  _options = {},
): Pick<UseLocalCliAgentCardResult, 'source' | 'sourceLabel' | 'sourceHint'> {
  // `modelsSource` is optional in the contract, so an absent value means the
  // host did not say where the list came from — NOT that it came from a
  // built-in fallback. Defaulting to 'fallback' rendered "Built-in list" over
  // a list that may well be live, and told the operator to Rescan to fix a
  // problem they do not have. Unknown provenance shows no badge and no claim.
  switch (source) {
    case 'live':
      return {
        source,
        sourceLabel: t('Live from CLI'),
        sourceHint: t("Model list comes from this CLI. Default uses the CLI's own config."),
      };
    case 'fallback':
      return {
        source,
        sourceLabel: t('Built-in list'),
        sourceHint: t('Showing built-in defaults. Click Rescan to pull live models from the CLI.'),
      };
    default:
      return { source, sourceLabel: '', sourceHint: '' };
  }
}

/** Scope probe evidence and its executable repair affordance to the card being rendered. */
function agentTestPresentation(
  { agent, agentTest, cliEnvFields }: Pick<UseLocalCliAgentCardInput, 'agent' | 'agentTest' | 'cliEnvFields'>,
  _options = {},
): Pick<UseLocalCliAgentCardResult, 'testing' | 'result' | 'repair' | 'repairField'> {
  // The test result belongs to whichever agent was probed, so a stale verdict
  // from a previously-tested CLI never renders under this one.
  const testing = agentTest.status === 'testing' && agentTest.agentId === agent.id;
  const result =
    (agentTest.status === 'ok' || agentTest.status === 'error') && agentTest.agentId === agent.id
      ? agentTest
      : null;

  // The "use the binary that actually ran" / "clear the override" repair
  // affordance — only meaningful when a successful test silently fell back
  // off a configured override, AND this agent's catalog names which field
  // that override lives in. See `agentExecutableRepairState`'s doc.
  //
  // `AgentTestState`'s 'ok' variant spells success as `status: 'ok'`, not an
  // `ok: true` field — `agentExecutableRepairState` takes the latter (it
  // mirrors `ExecutionPort.testAgent`'s raw resolved shape, one layer below
  // this state union), so the two must be translated explicitly here rather
  // than passing `result` straight through.
  const repair =
    result?.status === 'ok'
      ? agentExecutableRepairState({
          ok: true,
          usedExecutableSource: result.usedExecutableSource,
          detectedExecutablePath: result.detectedExecutablePath,
        })
      : null;
  const repairField = repair ? binPathEnvField(cliEnvFields, agent.id) : null;

  return { testing, result, repair, repairField };
}

import { useCallback, useEffect } from 'react';
import { CUSTOM_MODEL_SENTINEL } from '../../constants.js';
import {
  modelIdForReasoningLevel,
  pickerModelOptions,
  reasoningModelGroupFor,
  reasoningModelGroups,
  selectedAgentModel,
  selectedAgentReasoning,
  shouldShowCustomModelInput,
  splitReasoningModelId,
} from '../../rules.js';
import type {
  AgentModelOption,
  DetectedAgent,
  LocalCliConfig,
  ReasoningModelGroup,
} from '../../types.js';

export interface UseReasoningControlOptions {
  agent: DetectedAgent;
  config: LocalCliConfig;
  explicitCustomMode?: boolean | undefined;
  /**
   * Notified with `''` when the resolved model's reasoning-effort options no longer include the
   * operator's previously persisted per-agent pick (`config.reasoningByAgentId[agent.id]`) — e.g.
   * switching from a model that supports `xhigh` to one that tops out at `high`. Wire this to
   * `onReasoningChange(agent.id, next)` so the stale value is actually cleared from persisted config,
   * not just patched over at render time: `selectedAgentReasoning` (`rules.ts`) is a public rule a
   * host's dispatch code may call directly, so a value corrected only inside this hook's derived
   * `reasoningValue` could still leak an unsupported id into the CLI invocation.
   *
   * Never invoked on the `reasoningInModelId` path — that shape has no reasoning value of its own to
   * clear; the level lives inside the model id itself, and picking a new base model already replaces
   * it (`resolveNextModelId`). Omitted means nothing is auto-cleared, matching this hook's behavior
   * before per-model narrowing existed.
   */
  onReasoningChange?: ((next: string) => void) | undefined;
}

export interface UseReasoningControlResult {
  /** The agent's model list, or empty array if not defined. */
  models: readonly AgentModelOption[];
  /** Whether the agent has any models defined. */
  hasModels: boolean;
  /** The model that will run, with fallback to first model or empty string. */
  resolvedModel: string;
  /** The raw model string configured for this agent in `config.modelByAgentId`. */
  rawModel: string;
  /** Vocabulary of suffix levels declared in `agent.reasoningInModelId.levels`. */
  suffixLevels: readonly AgentModelOption[];
  /** IDs of the suffix levels. */
  suffixLevelIds: readonly string[];
  /** Model groups when `reasoningInModelId` is declared, or `null` otherwise. */
  modelGroups: readonly ReasoningModelGroup[] | null;
  /** Active group corresponding to the resolved model, or `null`. */
  activeGroup: ReasoningModelGroup | null;
  /** Active effort level split from the resolved model, or `null`. */
  activeLevel: string | null;
  /** Flat reasoning options declared in `agent.reasoningOptions`. */
  flatReasoningOptions: readonly AgentModelOption[];
  /** Effort options to render in the reasoning dropdown: either flat options or the active group's levels. */
  reasoningOptions: readonly AgentModelOption[];
  /** Whether reasoning effort controls should be displayed. */
  hasReasoning: boolean;
  /** Current value for the reasoning select input. */
  reasoningValue: string;
  /** Whether the reasoning select should be disabled (e.g. single-variant base model). */
  reasoningDisabled: boolean;
  /** Whether custom model free-text input is supported. */
  allowCustomModel: boolean;
  /** Known model IDs in the agent's catalog. */
  knownModelIds: readonly string[];
  /** Whether the custom model input is currently active. */
  customActive: boolean;
  /** Options for the model select: base models for suffix agents, or deduped catalog rows. */
  modelChoices: readonly AgentModelOption[];
  /** Selected value for the model select element. */
  selectValue: string;
  /** Display value for the custom model text input. */
  customModelInputValue: string;
  /**
   * Resolves the next full model ID when the base model selection changes.
   * For model-suffix agents, carries over the active level if supported by the new base,
   * or falls back to a valid level for the target group.
   */
  resolveNextModelId: (nextValue: string) => string;
  /**
   * Resolves the full model ID when a reasoning level is selected for a model-suffix agent.
   * Returns `null` if the agent does not use suffix-in-model-id reasoning.
   */
  resolveReasoningModelId: (level: string) => string | null;
}

/**
 * Orchestrates reasoning-effort and model selection derivation for a local CLI agent.
 *
 * Supports two distinct reasoning shapes:
 * 1. `reasoningOptions` — Flat vocabulary sent via dedicated CLI flags (`--effort high`).
 *    Persisted independently via `onReasoningChange`.
 * 2. `reasoningInModelId` — Effort level is encoded as a model slug suffix (`gemini-3.1-pro-high`).
 *    The selection is recombined into the model ID itself via `onModelChange`, with base model
 *    and effort levels derived from the agent's model catalog via `reasoningModelGroups`.
 */
export function useReasoningControl(options: UseReasoningControlOptions): UseReasoningControlResult;
export function useReasoningControl(
  agent: DetectedAgent,
  config: LocalCliConfig,
  explicitCustomMode?: boolean,
): UseReasoningControlResult;
export function useReasoningControl(
  optionsOrAgent: UseReasoningControlOptions | DetectedAgent,
  maybeConfig?: LocalCliConfig,
  maybeExplicitCustomMode?: boolean,
): UseReasoningControlResult {
  const { agent, config, explicitCustomMode = false, onReasoningChange } =
    reasoningControlOptions(optionsOrAgent, maybeConfig, maybeExplicitCustomMode);

  const models = agent.models ?? [];
  const hasModels = models.length > 0;
  const resolvedModel = selectedAgentModel(config, agent);
  const rawModel = config.modelByAgentId?.[agent.id] ?? '';

  const { suffixLevels, suffixLevelIds, modelGroups, activeGroup, activeLevel } =
    suffixReasoning({ agent, models, resolvedModel });

  const flatReasoningOptions = agent.reasoningOptions ?? [];
  const reasoningOptions = effortOptions({ flatReasoningOptions, activeGroup, models, resolvedModel });
  const hasReasoning = reasoningOptions.length > 0;
  const reasoningValue = effortValue({ agent, config, flatReasoningOptions, activeLevel, reasoningOptions });
  // A base model with exactly one variant has a real, fixed level worth showing — but nothing to
  // choose between, so the control is shown disabled rather than offering an illusion of choice.
  const reasoningDisabled = flatReasoningOptions.length === 0 && reasoningOptions.length < 2;

  const reasoningOptionIdsKey = reasoningOptions.map((option) => option.id).join('|');
  useEffect(() => {
    if (!onReasoningChange) return;
    if (isStaleReasoningPick({ agent, config, flatReasoningOptions, reasoningOptions })) onReasoningChange('');
    // `reasoningOptionIdsKey` stands in for `reasoningOptions` (a fresh array every render) so this
    // only re-runs when the narrowed vocabulary actually changes, not on every unrelated re-render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flatReasoningOptions.length, onReasoningChange, config.reasoningByAgentId, agent.id, reasoningOptionIdsKey]);

  const { allowCustomModel, knownModelIds, customActive } =
    customModelState({ agent, modelGroups, models, resolvedModel, explicitCustomMode });
  // A model-suffix agent picks a BASE model here; the effort control below supplies the rest of the
  // id. Everything else about the field — search, labels, provenance badge — is unchanged.
  const modelChoices: readonly AgentModelOption[] = modelGroups
    ? modelGroups.map((group) => ({ id: group.baseId, label: group.label }))
    : pickerModelOptions({ models });
  const selectValue = modelSelectValue({ customActive, modelGroups, activeGroup, models, resolvedModel });
  // While the custom box is open, the text field must show the operator's raw
  // typed text (which may not resolve to anything yet) rather than the
  // resolved-with-fallback value — otherwise every keystroke would show a
  // stale fallback model instead of what was actually typed.
  const customModelInputValue = explicitCustomMode ? rawModel : resolvedModel;

  const resolveNextModelId = useCallback(
    (nextValue: string): string => {
      if (!modelGroups) {
        return nextValue;
      }
      // Switching base carries the current effort level over when the new base
      // really has it, and lands on one it does have otherwise — never composes a
      // slug (see `modelIdForReasoningLevel`), so `gemini-3.1-pro-medium` cannot be
      // produced from a `medium` carried off `gemini-3.8-flash`.
      const nextGroup = modelGroups.find((group) => group.baseId === nextValue);
      return nextGroup ? modelIdForReasoningLevel(nextGroup, activeLevel) : nextValue;
    },
    [modelGroups, activeLevel],
  );

  const resolveReasoningModelId = useCallback(
    (level: string): string | null => {
      // A model-suffix agent has no reasoning value of its own to record: the choice
      // is which model id runs, so it goes back out through `onModelChange`.
      if (activeGroup) {
        return modelIdForReasoningLevel(activeGroup, level);
      }
      return null;
    },
    [activeGroup],
  );

  return {
    models,
    hasModels,
    resolvedModel,
    rawModel,
    suffixLevels,
    suffixLevelIds,
    modelGroups,
    activeGroup,
    activeLevel,
    flatReasoningOptions,
    reasoningOptions,
    hasReasoning,
    reasoningValue,
    reasoningDisabled,
    allowCustomModel,
    knownModelIds,
    customActive,
    modelChoices,
    selectValue,
    customModelInputValue,
    resolveNextModelId,
    resolveReasoningModelId,
  };
}

/** The two call shapes (options object, or the older positional `agent, config, explicitCustomMode`)
 *  as one options object. */
function reasoningControlOptions(
  optionsOrAgent: UseReasoningControlOptions | DetectedAgent,
  maybeConfig: LocalCliConfig | undefined,
  maybeExplicitCustomMode: boolean | undefined,
): UseReasoningControlOptions {
  if ('agent' in optionsOrAgent && 'config' in optionsOrAgent) return optionsOrAgent;
  return {
    agent: optionsOrAgent as DetectedAgent,
    config: maybeConfig!,
    explicitCustomMode: maybeExplicitCustomMode ?? false,
  };
}

/**
 * The model-suffix reasoning shape: the agent's declared suffix levels, its catalog grouped by base
 * model, and where the resolved model sits in those groups. All `null` (and empty) for an agent
 * without `reasoningInModelId`.
 *
 * Two ways an agent can expose a reasoning-effort axis, and the card branches on the DECLARATION
 * rather than on the agent's id — adding a third runtime with either shape is a def change, not
 * an edit here.
 *
 *   `reasoningOptions`     — one flat vocabulary that travels to the CLI as its own flag
 *                            (`claude --effort high`, codex's `-c model_reasoning_effort=...`).
 *                            The choice is its own persisted value; `onReasoningChange` owns it.
 *   `reasoningInModelId`   — no effort flag exists; the level is a suffix on the model id itself
 *                            (antigravity's `gemini-3.1-pro-high`). The choice IS the model, so
 *                            it goes through `onModelChange`, and the available levels are
 *                            derived PER BASE MODEL from the agent's own catalog — they are not
 *                            uniform (`gemini-3.1-pro` has no `-medium`, and `agy --model`
 *                            rejects one), so a fixed dropdown would offer ids the CLI refuses.
 */
function suffixReasoning({ agent, models, resolvedModel }: {
  agent: DetectedAgent;
  models: readonly AgentModelOption[];
  resolvedModel: string;
}) {
  const suffixLevels = agent.reasoningInModelId?.levels ?? [];
  const suffixLevelIds = suffixLevels.map((level) => level.id);
  if (suffixLevels.length === 0) {
    return { suffixLevels, suffixLevelIds, modelGroups: null, activeGroup: null, activeLevel: null };
  }
  const modelGroups = reasoningModelGroups(models, suffixLevels);
  const activeGroup = reasoningModelGroupFor(modelGroups, resolvedModel, suffixLevelIds);
  const activeLevel = splitReasoningModelId(resolvedModel, suffixLevelIds).level;
  return { suffixLevels, suffixLevelIds, modelGroups, activeGroup, activeLevel };
}

/** The effort options the reasoning dropdown offers for the resolved model. */
function effortOptions({ flatReasoningOptions, activeGroup, models, resolvedModel }: {
  flatReasoningOptions: readonly AgentModelOption[];
  activeGroup: ReasoningModelGroup | null;
  models: readonly AgentModelOption[];
  resolvedModel: string;
}): readonly AgentModelOption[] {
  // Exactly one effort control, whichever shape declared it. `reasoningOptions` wins if a def ever
  // declares both, rather than rendering two controls that disagree about where the choice lands.
  if (flatReasoningOptions.length === 0) return activeGroup?.levels ?? [];
  // Per-model narrowing: a runtime whose catalog reports reasoning levels PER MODEL rather than
  // uniformly across the agent (Codex — see `AgentModelOption.reasoning`'s doc) declares them on the
  // resolved model's own catalog row. `undefined` there means "this model's entry has nothing
  // model-specific to say", so it falls back to the agent-wide union below — the same list every
  // model rendered before this field existed. An explicit `[]` is honored AS-IS, even though a model
  // with genuinely zero levels then hides the control: falling back to the union for `[]` too would
  // just move today's "every model sees every level" bug one layer down instead of fixing it.
  const selectedModelReasoning = models.find((model) => model.id === resolvedModel)?.reasoning;
  return selectedModelReasoning === undefined ? flatReasoningOptions : selectedModelReasoning;
}

/** The value the reasoning select renders: the persisted / derived pick, or the first offered level
 *  when that pick is not among the options. */
function effortValue({ agent, config, flatReasoningOptions, activeLevel, reasoningOptions }: {
  agent: DetectedAgent;
  config: LocalCliConfig;
  flatReasoningOptions: readonly AgentModelOption[];
  activeLevel: string | null;
  reasoningOptions: readonly AgentModelOption[];
}): string {
  const rawReasoningValue =
    flatReasoningOptions.length > 0
      ? selectedAgentReasoning(config, agent)
      : (activeLevel ?? reasoningOptions[0]?.id ?? '');
  // The persisted (or agent-wide-default) pick can name a level the narrowed list above does not
  // actually offer for the CURRENT model — that is the whole point of narrowing. Rendering it anyway
  // would just relocate today's bug: the `<select>` below has no matching `<option>`, so it would
  // silently show whatever the browser highlights first while the underlying value stays wrong. This
  // guards what actually renders; the effect further down clears the persisted copy so every other
  // reader of `config.reasoningByAgentId` (not just this hook) sees the correction too.
  const reasoningSupported = reasoningOptions.some((option) => option.id === rawReasoningValue);
  return reasoningSupported ? rawReasoningValue : (reasoningOptions[0]?.id ?? '');
}

/** Whether the agent's persisted flat-reasoning pick names a level the current options no longer
 *  offer, so the hook should ask the host to clear it. */
function isStaleReasoningPick({ agent, config, flatReasoningOptions, reasoningOptions }: {
  agent: DetectedAgent;
  config: LocalCliConfig;
  flatReasoningOptions: readonly AgentModelOption[];
  reasoningOptions: readonly AgentModelOption[];
}): boolean {
  // The reasoningInModelId path has no reasoning value of its own to clear — the level lives
  // inside the model id itself, and picking a new base model already replaces it.
  if (flatReasoningOptions.length === 0) return false;
  const persisted = config.reasoningByAgentId?.[agent.id]?.trim();
  if (!persisted) return false;
  return !reasoningOptions.some((option) => option.id === persisted);
}

/** The model select's value: the Custom sentinel, a suffix agent's base id, or the resolved model. */
function modelSelectValue({ customActive, modelGroups, activeGroup, models, resolvedModel }: {
  customActive: boolean;
  modelGroups: readonly ReasoningModelGroup[] | null;
  activeGroup: ReasoningModelGroup | null;
  models: readonly AgentModelOption[];
  resolvedModel: string;
}): string {
  if (customActive) return CUSTOM_MODEL_SENTINEL;
  if (modelGroups) return activeGroup?.baseId ?? '';
  // Persisted aliases stay known in the full catalog above, but the picker selects their concrete
  // row. This is display-only: the saved model and dispatch resolution keep the operator's pick.
  const selectedModel = models.find((model) => model.id === resolvedModel);
  return selectedModel?.identityKind === 'alias' ? (selectedModel.resolvedId || resolvedModel) : resolvedModel;
}

/** Whether this agent takes a free-text model id at all, and whether the free-text box is open now. */
function customModelState({ agent, modelGroups, models, resolvedModel, explicitCustomMode }: {
  agent: DetectedAgent;
  modelGroups: readonly ReasoningModelGroup[] | null;
  models: readonly AgentModelOption[];
  resolvedModel: string;
  explicitCustomMode: boolean;
}) {
  // Adapters opt out via `supportsCustomModel: false` when their CLI has no
  // free-text model flag, or validates the id against a live catalog and
  // rejects unknown ones. `undefined` allows it, matching every adapter's
  // default before this field existed.
  const allowCustomModel = agent.supportsCustomModel !== false && modelGroups === null;
  const knownModelIds = models.map((model) => model.id);
  const customActive =
    allowCustomModel && models.length > 0 && shouldShowCustomModelInput(resolvedModel, knownModelIds, explicitCustomMode);
  return { allowCustomModel, knownModelIds, customActive };
}

import { isAllowedEndpointUrl } from '../../utils/endpoint-policy.js';
import {
  API_KEY_CROSS_VENDOR_WARNING,
  API_KEY_TOO_SHORT_WARNING,
  CUSTOM_PRESET_ID,
  MIN_PLAUSIBLE_API_KEY_LENGTH,
} from './constants.js';
import type {
  AgentCliEnvFieldSpec,
  AgentDiagnostic,
  AgentExecutableRepair,
  AgentExecutableSource,
  AgentModelOption,
  ApiKeyWarning,
  ByokConfig,
  ByokProviderCredentials,
  ByokRequiredField,
  DetectedAgent,
  ExecutionConfig,
  ExecutionMode,
  LocalCliConfig,
  ProviderPreset,
  ReasoningModelGroup,
} from './types.js';

/**
 * Pure decision logic for the execution tab. Everything here is total and
 * side-effect free so the React layer stays a thin renderer — same split the
 * `privacy` and `integrations` tabs use.
 */

/**
 * Accepts only absolute http(s) URLs pointing somewhere a credentialed request
 * may go. Origin: `isValidApiBaseUrl`. A blank string is *not* valid here;
 * callers decide whether blank is allowed (it is, for fixed-origin gateways,
 * which resolve their own endpoint).
 *
 * This used to check the scheme and nothing else, which accepted
 * `http://169.254.169.254/` and every RFC1918 address — an operator-supplied
 * endpoint that this tab then pairs with a real API key and persists. The
 * host policy now lives in one shared module; see `utils/endpoint-policy.ts`
 * for why it is a browser-safe copy of `@jini-ai/agent-runtime`'s guard rather
 * than an import of it, and for the DNS-aware layer that complements it at
 * connection time.
 */
export function isValidApiBaseUrl(raw: string): boolean {
  return isAllowedEndpointUrl({ raw });
}

/** The synthetic "Custom" preset, so the picker always has a manual escape
 *  hatch even when a host supplies zero presets. */
export function customPreset(protocol: ByokConfig['protocol'], title = 'Custom'): ProviderPreset {
  return {
    id: CUSTOM_PRESET_ID,
    title,
    protocol,
    baseUrl: '',
    preferredModels: [],
    custom: true,
  };
}

/** Presets that speak the given protocol, excluding the custom entry. */
export function presetsForProtocol(
  presets: readonly ProviderPreset[],
  protocol: ByokConfig['protocol'],
): readonly ProviderPreset[] {
  return presets.filter((preset) => !preset.custom && preset.protocol === protocol);
}

/** Splits a catalog into the two chip rows the origin rendered. Presets with
 *  no `kind` fall into `protocols` so a host that ignores the distinction
 *  still gets one populated row rather than two empty ones. */
export function groupPresets(presets: readonly ProviderPreset[]): {
  protocols: readonly ProviderPreset[];
  gateways: readonly ProviderPreset[];
} {
  const protocols: ProviderPreset[] = [];
  const gateways: ProviderPreset[] = [];
  for (const preset of presets) {
    if (preset.custom) continue;
    if (preset.kind === 'gateway') gateways.push(preset);
    else protocols.push(preset);
  }
  return { protocols, gateways };
}

/** The preset the current config points at, or `null` for custom/manual.
 *  Matches on id first (stable across base-URL edits), falling back to the
 *  origin's protocol+baseUrl match so a config written by an older catalog
 *  still resolves. */
export function resolveSelectedPreset(
  presets: readonly ProviderPreset[],
  config: ByokConfig,
): ProviderPreset | null {
  if (config.providerId === null) return null;
  const byId = presets.find((preset) => !preset.custom && preset.id === config.providerId);
  if (byId) return byId;
  return (
    presets.find(
      (preset) =>
        !preset.custom && preset.protocol === config.protocol && preset.baseUrl === config.baseUrl,
    ) ?? null
  );
}

/** Whether a preset needs an API key. Defaults to `true`; only an explicit
 *  `requiresApiKey: false` opts out. */
export function presetRequiresApiKey(preset: ProviderPreset | null): boolean {
  return preset?.requiresApiKey !== false;
}

/** Fixed-origin gateways resolve their own endpoint, so the Base URL field is
 *  hidden rather than shown-and-ignored. Origin: `showBaseUrlField`. */
export function showsBaseUrlField(preset: ProviderPreset | null): boolean {
  return preset?.fixedOrigin !== true;
}

/**
 * Which required fields are still blank or invalid. Returned in render order
 * so a caller can surface the first offender without re-sorting.
 */
export function missingRequiredFields(
  config: ByokConfig,
  preset: ProviderPreset | null,
): readonly ByokRequiredField[] {
  const missing: ByokRequiredField[] = [];
  if (presetRequiresApiKey(preset) && !config.apiKey.trim()) missing.push('apiKey');
  if (showsBaseUrlField(preset) && !isValidApiBaseUrl(config.baseUrl)) missing.push('baseUrl');
  if (!config.model.trim()) missing.push('model');
  return missing;
}

/**
 * The catalog entry that claims this key MORE specifically than the selected preset does — i.e. the
 * vendor the operator most likely meant to paste it into. `null` when no other row recognises the
 * string, or when the selection's own claim is at least as specific as any rival's.
 *
 * "More specific" is prefix LENGTH, not catalog order. `sk-or-v1-…` starts with both OpenRouter's
 * `sk-or-` and OpenAI's `sk-`; the longer prefix is the truer claim, and deciding it by row position
 * would make the message move when someone reorders the catalog. The same comparison gives the
 * selected preset a tie: a host row that legitimately takes `sk-ant-` keys (an Anthropic-compatible
 * proxy) claims them exactly as strongly as Anthropic does and so keeps them, silently.
 *
 * @param key - The trimmed key text as typed.
 * @param preset - The selected preset. Required: with no selection there is no "wrong field" to be
 *   in, and on custom/manual any vendor's key may be exactly right.
 * @param presets - The catalog to recognise foreign keys against.
 * @returns The foreign owner, or `null` for silence.
 * @complexity O(n·m) — n presets, m the length of the longest prefix. Catalogs are single-digit
 *   rows of authored data, and `startsWith` short-circuits on the first differing character.
 */
function foreignKeyOwner(
  key: string,
  preset: ProviderPreset,
  presets: readonly ProviderPreset[],
): ProviderPreset | null {
  // -1, not 0, so a preset with no prefix of its own still loses every comparison rather than tying
  // with one. Azure ships no prefix and must still be told when it is holding an Anthropic key.
  let bestClaim =
    preset.apiKeyPrefix && key.startsWith(preset.apiKeyPrefix) ? preset.apiKeyPrefix.length : -1;
  let owner: ProviderPreset | null = null;
  for (const candidate of presets) {
    const prefix = candidate.apiKeyPrefix;
    if (!prefix || candidate.custom || candidate.id === preset.id) continue;
    if (prefix.length <= bestClaim || !key.startsWith(prefix)) continue;
    owner = candidate;
    bestClaim = prefix.length;
  }
  return owner;
}

/**
 * The advisory "that key looks wrong" remark for the current draft, or `null` for silence.
 *
 * Warns ONLY on what it can positively recognise as wrong, and there are exactly two such things:
 * a key wearing another catalogued vendor's prefix (pasted into the wrong provider's field), and a
 * key shorter than {@link MIN_PLAUSIBLE_API_KEY_LENGTH} (the reported Chrome-autofilled PASSWORD).
 * Everything else — including every shape this package has never seen — is silence.
 *
 * That direction is the whole design, and it is the fix for a real reported defect. This function
 * used to ask "does the key match the selected preset's pattern?" and warn when it did not: a
 * positive allowlist, which false-positives the instant a vendor issues a shape the catalog has not
 * been taught. That happened within hours of shipping — an operator pasted a working Google Gemini
 * key and was told it did not look like a Google API key. A catalog can prove a string belongs to
 * vendor X; it can never prove a string belongs to nobody. Do not re-derive an allowlist here, and
 * do not add a per-provider branch: the conditions above are the only two that hold without one.
 *
 * ADVISORY ONLY, also by construction: this returns a message, not a validity verdict. No caller may
 * use it to disable a control or gate a submit — a client-side guess must never be able to block a
 * working credential. It is deliberately absent from {@link missingRequiredFields}, which IS a gate.
 *
 * @param config - The active BYOK draft; only `apiKey` is read.
 * @param preset - The resolved preset, or `null` on custom/manual, which is exempt from the
 *   cross-vendor arm (see {@link foreignKeyOwner}) but not from the length floor.
 * @param presets - The catalog to recognise foreign keys against. Defaults to empty, which is why
 *   omitting it costs the cross-vendor arm and gains nothing else: an under-informed rule must
 *   degrade toward silence, never toward guessing.
 * @returns A translatable {@link ApiKeyWarning}, or `null` when there is nothing to say.
 * @complexity O(n·m) via {@link foreignKeyOwner}; the length check is O(1).
 */
export function apiKeyFormatWarning(
  config: ByokConfig,
  preset: ProviderPreset | null,
  presets: readonly ProviderPreset[] = [],
): ApiKeyWarning | null {
  const key = config.apiKey.trim();
  if (!key) return null;
  if (preset) {
    const owner = foreignKeyOwner(key, preset, presets);
    if (owner) {
      return {
        message: API_KEY_CROSS_VENDOR_WARNING,
        vars: { vendor: owner.title, provider: preset.title },
      };
    }
  }
  if (key.length < MIN_PLAUSIBLE_API_KEY_LENGTH) {
    return { message: API_KEY_TOO_SHORT_WARNING, vars: {} };
  }
  return null;
}

/**
 * The credentials a given preset would use — the active selection's live
 * top-level fields when `preset` IS the current selection, otherwise that
 * preset's own saved draft (`config.savedByProviderId`), or blank/preset
 * defaults when it has never been configured. This is the read side of the
 * per-provider keying `ByokConfig.savedByProviderId` documents: every preset
 * chip must be judged against ITS OWN credentials, never whichever provider
 * happens to be active right now.
 */
export function credentialsForPreset(
  config: ByokConfig,
  preset: ProviderPreset | null,
): ByokProviderCredentials {
  if (!preset || preset.custom || config.providerId === preset.id) {
    return { apiKey: config.apiKey, baseUrl: config.baseUrl, model: config.model, maxTokens: config.maxTokens };
  }
  return (
    config.savedByProviderId?.[preset.id] ?? { apiKey: '', baseUrl: preset.baseUrl, model: '', maxTokens: undefined }
  );
}

/** A provider chip renders a filled status dot when ITS OWN saved credentials
 *  (not necessarily the active selection's) satisfy its required fields —
 *  see `credentialsForPreset`. */
export function isProviderConfigured(config: ByokConfig, preset: ProviderPreset | null): boolean {
  if (!preset) return false;
  const credentials = credentialsForPreset(config, preset);
  const requiresApiKey = presetRequiresApiKey(preset);
  const hasApiKey = !requiresApiKey || Boolean(credentials.apiKey.trim());
  const hasBaseUrl = !showsBaseUrlField(preset) || isValidApiBaseUrl(credentials.baseUrl);
  const hasModel = Boolean(credentials.model.trim());
  return hasApiKey && hasBaseUrl && hasModel;
}

/** True when the operator typed something into Base URL that isn't a URL —
 *  distinct from "hasn't typed anything yet", which is not an error state. */
export function isBaseUrlInvalid(config: ByokConfig): boolean {
  return Boolean(config.baseUrl.trim()) && !isValidApiBaseUrl(config.baseUrl);
}

/**
 * Selecting a preset first snapshots the OUTGOING provider's live credentials
 * into `savedByProviderId` (so they aren't lost), then loads the INCOMING
 * preset's own saved draft — or, if it has never been configured, blank
 * credentials seeded with its base URL and top preferred model.
 *
 * This deliberately does NOT carry the outgoing provider's API key/base URL
 * forward as a shared default the way the single-`ByokConfig` design used to:
 * that sharing is exactly what let an unrelated preset's chip read as
 * "configured" off of whichever provider was last active (see
 * `isProviderConfigured`'s doc and `ByokConfig.savedByProviderId`'s header).
 * Each preset now keeps only what was actually saved for IT.
 */
export function nextConfigForPresetSelect(config: ByokConfig, preset: ProviderPreset): ByokConfig {
  const savedByProviderId = { ...config.savedByProviderId };
  if (config.providerId !== null) {
    savedByProviderId[config.providerId] = {
      apiKey: config.apiKey,
      baseUrl: config.baseUrl,
      model: config.model,
      maxTokens: config.maxTokens,
    };
  }
  if (preset.custom) {
    return { ...config, providerId: null, savedByProviderId };
  }
  return {
    ...config,
    providerId: preset.id,
    protocol: preset.protocol,
    ...presetCredentials(savedByProviderId[preset.id], preset),
    savedByProviderId,
  };
}

/** A preset's saved draft, or blank credentials seeded with its base URL and top preferred model. */
function presetCredentials(saved: ByokProviderCredentials | undefined, preset: ProviderPreset): ByokProviderCredentials {
  return {
    apiKey: saved?.apiKey ?? '',
    baseUrl: saved?.baseUrl ?? preset.baseUrl,
    model: saved?.model ?? preset.preferredModels[0] ?? '',
    maxTokens: saved?.maxTokens,
  };
}

/** Switching protocol by hand drops the preset selection (the old preset no
 *  longer speaks this protocol) and keeps operator-entered endpoints. Hosts
 *  seed endpoints through presets; protocol selection never chooses a vendor. */
export function nextConfigForProtocolSelect(
  config: ByokConfig,
  protocol: ByokConfig['protocol'],
): ByokConfig {
  if (config.protocol === protocol) return config;
  return {
    ...config,
    protocol,
    providerId: null,
    baseUrl: config.baseUrl.trim() ? config.baseUrl : '',
  };
}

/** Mode changes never discard BYOK credentials — flipping to Local CLI and
 *  back must not make the operator retype their key. */
export function nextConfigForModeChange(
  config: ExecutionConfig,
  mode: ExecutionMode,
): ExecutionConfig {
  return config.mode === mode ? config : { ...config, mode };
}

/** Parses the optional max-tokens field. Blank means "use the model default"
 *  (`undefined`); anything non-positive or non-numeric is rejected as
 *  `undefined` rather than silently stored as 0. */
export function parseMaxTokens(raw: string): number | undefined {
  const trimmed = raw.trim();
  if (!trimmed) return undefined;
  const parsed = Number(trimmed);
  if (!Number.isFinite(parsed) || !Number.isInteger(parsed) || parsed <= 0) return undefined;
  return parsed;
}

/** Local-CLI agents, installed first, then alphabetical — the origin grouped
 *  by installed/not-installed and this preserves that read order. */
export function sortDetectedAgents<T extends { installed: boolean; label: string }>(
  agents: readonly T[],
): readonly T[] {
  return [...agents].sort((a, b) => {
    if (a.installed !== b.installed) return a.installed ? -1 : 1;
    return a.label.localeCompare(b.label);
  });
}

/**
 * Splits the CLI grid into what to show up front and what sits behind the "Show N not installed"
 * toggle. Installed CLIs are the ones an operator can pick, so a long tail of uninstalled cards
 * buried every setting below the grid. The selected agent always stays visible even when it is
 * not installed (a stale pick after an uninstall), so the current choice is never hidden.
 */
export function partitionAgentsByInstalled<T extends { id: string; installed: boolean }>(
  agents: readonly T[],
  selectedAgentId: string | null | undefined,
): { visible: T[]; collapsed: T[] } {
  const visible: T[] = [];
  const collapsed: T[] = [];
  for (const agent of agents) {
    (agent.installed || agent.id === selectedAgentId ? visible : collapsed).push(agent);
  }
  return { visible, collapsed };
}

/**
 * Strips a redundant trailing agent name from a CLI's `--version` output, so
 * "1.2.3 (Claude Code)" renders as "1.2.3" beside a card already titled
 * "Claude Code". Origin: `cleanAgentVersionLabel`.
 *
 * Only a trailing occurrence is removed, and only when it matches the agent's
 * own label — a version string that legitimately *contains* the name earlier
 * on is left intact rather than mangled.
 */
export function cleanAgentVersionLabel(label: string, version: string | null | undefined): string {
  if (!version) return '';
  const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return version
    .replace(new RegExp(`\\s*\\(${escaped}\\)\\s*$`, 'i'), '')
    .replace(new RegExp(`\\s+${escaped}\\s*$`, 'i'), '')
    .trim();
}

/** English label keys for `agentMetaLabel`, passed in so this stays a pure
 *  function rather than reaching for a translator. */
export interface AgentMetaLabels {
  authRequired: string;
  authUnknown: string;
  installed: string;
  notInstalled: string;
}

/**
 * The one-line status under an agent's name, and the tooltip behind it.
 *
 * Auth trouble outranks the version string: an operator whose CLI is installed
 * but signed out needs to see that, and "1.2.3" would read as everything being
 * fine. The tooltip then carries the detail (`authMessage`) or the resolved
 * binary path, so the card stays one line without discarding either.
 */
export function agentMetaLabel(
  agent: DetectedAgent,
  labels: AgentMetaLabels,
): { text: string; title: string } {
  const title = (agent.authStatus === 'missing' || agent.authStatus === 'unknown'
    ? (agent.authMessage ?? agent.path ?? '')
    : (agent.path ?? '')) as string;
  if (!agent.installed) return { text: labels.notInstalled, title };
  if (agent.authStatus === 'missing') return { text: labels.authRequired, title };
  if (agent.authStatus === 'unknown') return { text: labels.authUnknown, title };
  const version = cleanAgentVersionLabel(agent.label, agent.version);
  return { text: version || labels.installed, title };
}

/** The model an agent will actually run: the operator's explicit per-agent
 *  pick when they made one, else the first entry of whatever list the host
 *  reported, else nothing. */
export function selectedAgentModel(config: LocalCliConfig, agent: DetectedAgent): string {
  const chosen = config.modelByAgentId?.[agent.id]?.trim();
  if (chosen) return chosen;
  return agent.models?.[0]?.id ?? '';
}

/** Human label for the model an agent will run, for the collapsed summary line
 *  on unselected cards. Falls back to the raw id when the host reported a
 *  model list that doesn't contain the operator's saved pick — a stale saved
 *  choice is still the choice, and hiding it would misreport what will run. */
export function agentModelSummary(config: LocalCliConfig, agent: DetectedAgent): string {
  const id = selectedAgentModel(config, agent);
  if (!id) return '';
  return agent.models?.find((model) => model.id === id)?.label ?? id;
}

/** Picking an agent card. Re-picking the selected agent is a no-op rather than
 *  a deselect — the origin had no "no agent" affordance once one was chosen,
 *  and silently clearing it on a stray second click would strand the tab in a
 *  state the operator did not ask for. */
export function nextConfigForAgentSelect(config: ExecutionConfig, agentId: string): ExecutionConfig {
  if (config.localCli.agentId === agentId) return config;
  return { ...config, localCli: { ...config.localCli, agentId } };
}

/** Recording a per-agent model pick. Keyed by agent id so switching agents and
 *  back preserves each one's own choice — see `LocalCliConfig`. */
export function nextConfigForAgentModel(
  config: ExecutionConfig,
  agentId: string,
  model: string,
): ExecutionConfig {
  return {
    ...config,
    localCli: {
      ...config.localCli,
      modelByAgentId: { ...config.localCli.modelByAgentId, [agentId]: model },
    },
  };
}

/** The reasoning-effort id an agent will actually run: the operator's
 *  explicit per-agent pick when they made one, else the first entry of
 *  whatever `reasoningOptions` the host reported, else nothing. Mirrors
 *  `selectedAgentModel` exactly — a reasoning choice is a model-catalog
 *  pick from a second, independent list. */
export function selectedAgentReasoning(config: LocalCliConfig, agent: DetectedAgent): string {
  const chosen = config.reasoningByAgentId?.[agent.id]?.trim();
  if (chosen) return chosen;
  return agent.reasoningOptions?.[0]?.id ?? '';
}

/** Recording a per-agent reasoning-effort pick. Keyed by agent id for the
 *  same cross-contamination reason as `nextConfigForAgentModel`. */
export function nextConfigForAgentReasoning(
  config: ExecutionConfig,
  agentId: string,
  reasoning: string,
): ExecutionConfig {
  return {
    ...config,
    localCli: {
      ...config.localCli,
      reasoningByAgentId: { ...config.localCli.reasoningByAgentId, [agentId]: reasoning },
    },
  };
}

/**
 * Whether the model picker should show its free-text "Custom" input instead
 * of (or alongside) the searchable list. True when the operator explicitly
 * switched to custom mode (a UI-local toggle the host tracks, since it is not
 * itself persisted config — see `LocalCliAgentCard`), when there is nothing
 * to show a resolved value for yet, or when the current value simply isn't
 * one of the agent's known models (a value from an older/different catalog).
 * Origin: `shouldShowCustomModelInput`.
 */
export function shouldShowCustomModelInput(
  modelValue: string,
  knownModelIds: readonly string[],
  explicitCustomMode: boolean,
): boolean {
  return explicitCustomMode || !modelValue || !knownModelIds.includes(modelValue);
}

/** The catalog entries relevant to one agent, in catalog order. Mirrors
 *  `presetsForProtocol`'s "filter the shared catalog down to what THIS
 *  context needs" shape. */
export function cliEnvFieldsForAgent(
  fields: readonly AgentCliEnvFieldSpec[],
  agentId: string,
): readonly AgentCliEnvFieldSpec[] {
  return fields.filter((field) => field.agentId === agentId);
}

/** The operator's current value for one agent's CLI env field, or `''` when
 *  unset — the value an `<input>` should render. */
export function agentCliEnvValue(config: LocalCliConfig, agentId: string, envKey: string): string {
  return config.envByAgentId?.[agentId]?.[envKey] ?? '';
}

/**
 * Setting (or, for a blank value, clearing) one agent's CLI env override.
 * Trims the incoming value the same way `parseMaxTokens`/`isValidApiBaseUrl`
 * treat operator input; a blank result deletes the key rather than storing
 * an empty string, and an agent whose every field is now empty is dropped
 * from the map entirely rather than left as `{}` — origin:
 * `updateAgentCliEnvValue`'s identical empty-object cleanup, minus its
 * AMR-wallet-specific `agentCliEnvIntent`/`apiKeyOverride` side channel,
 * which is product-bound (this package tracks no such intent).
 */
export function nextConfigForAgentCliEnvChange(
  config: ExecutionConfig,
  agentId: string,
  envKey: string,
  rawValue: string,
): ExecutionConfig {
  const value = rawValue.trim();
  const nextAgentEnv = { ...config.localCli.envByAgentId?.[agentId] };
  if (value) {
    nextAgentEnv[envKey] = value;
  } else {
    delete nextAgentEnv[envKey];
  }

  const envByAgentId = { ...config.localCli.envByAgentId };
  if (Object.keys(nextAgentEnv).length > 0) {
    envByAgentId[agentId] = nextAgentEnv;
  } else {
    delete envByAgentId[agentId];
  }

  return { ...config, localCli: { ...config.localCli, envByAgentId } };
}

/** The catalog field (if any) tagged as one agent's executable-path override
 *  — see `AgentCliEnvFieldSpec.kind`. At most one is expected per agent; the
 *  first match wins if a host's catalog carries more than one. */
export function binPathEnvField(
  fields: readonly AgentCliEnvFieldSpec[],
  agentId: string,
): AgentCliEnvFieldSpec | null {
  return fields.find((field) => field.agentId === agentId && field.kind === 'binPath') ?? null;
}

/**
 * Whether a successful agent test unlocks the "use the binary that actually
 * ran" / "clear the override" repair affordance: only when the test
 * REACHED a working binary (`ok: true`) by silently falling back away from a
 * configured override that didn't work (`usedExecutableSource` is one of the
 * two `fallback-*` values) AND the host reported which path that was.
 * Returns `null` for a normal (`'primary'`) run, a failed test (nothing
 * "worked" to offer), or a fallback the host didn't name a path for — a
 * repair affordance with no destination path would be a dead-end button.
 * Origin: `codexPathRepairState`, generalized off one hardcoded agent id —
 * see this file's module doc and `binPathEnvField`.
 */
export function agentExecutableRepairState(result: {
  ok: boolean;
  usedExecutableSource?: AgentExecutableSource | undefined;
  detectedExecutablePath?: string | undefined;
}): AgentExecutableRepair | null {
  if (!result.ok) return null;
  if (result.usedExecutableSource !== 'fallback-invalid' && result.usedExecutableSource !== 'fallback-failed') {
    return null;
  }
  const detectedPath = result.detectedExecutablePath?.trim() || '';
  if (!detectedPath) return null;
  return { detectedPath, canUseDetected: true };
}

/** Resolves alias evidence to a concrete picker row; other rows retain their identity. */
function resolvedPickerModelOption(
  { model }: { model: AgentModelOption },
  _optional: Record<string, never> = {},
): AgentModelOption {
  const resolvedId = model.identityKind === 'alias' ? model.resolvedId : undefined;
  if (!resolvedId) return model;
  const label = model.label === model.id ? resolvedId : model.label;
  return { ...model, id: resolvedId, label, identityKind: 'concrete' };
}

/**
 * Builds picker rows from catalog evidence without changing the source catalog. Resolved aliases
 * share a concrete row; unresolved aliases and routing modes remain selectable as reported.
 * Keeps the first position and prefers a human label over a raw ID, including the CLI default's
 * raw-label row. No names or context variants are inferred from model IDs.
 * @returns Distinct picker rows in catalog order. No side effects or errors.
 * @complexity O(n) time and space in catalog rows, using insertion-ordered Map keys.
 */
export function pickerModelOptions(
  { models }: { models: readonly AgentModelOption[] },
  _optional: Record<string, never> = {},
): AgentModelOption[] {
  const choices = new Map<string, AgentModelOption>();
  for (const model of models) {
    const option = resolvedPickerModelOption({ model });
    const { id, label } = option;
    const existing = choices.get(id);
    if (!existing) {
      choices.set(id, option);
      continue;
    }
    // A later duplicate only upgrades an entry whose label was just its id.
    if (existing.label === id && label !== id) choices.set(id, { ...existing, label });
  }
  return [...choices.values()];
}

/** Case-insensitive substring match against a model's id or label, mirroring
 *  the origin's search box. Matches on both fields (not just the visible
 *  label) so an operator can search by the raw model id too. */
function matchesModelQuery(option: AgentModelOption, query: string): boolean {
  const haystack = `${option.id}\n${option.label}`.toLowerCase();
  return haystack.includes(query);
}

/**
 * Filters a searchable model list down to what matches the operator's typed
 * query. The currently-selected value's own option is always kept even when
 * it no longer matches — hiding the active selection out from under the
 * operator while they type would look like their pick vanished. A blank
 * query returns every option unfiltered. Origin: the `filteredOptions`
 * `useMemo` inside `SearchableModelSelect`.
 */
export function filterAgentModelOptions(
  options: readonly AgentModelOption[],
  query: string,
  selectedValue: string,
): readonly AgentModelOption[] {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return options;
  return options.filter((option) => option.id === selectedValue || matchesModelQuery(option, normalized));
}

/** The tooltip text for one `AgentDiagnostic` row: its longer `detail`
 *  followed by every directory PATH detection searched (for the
 *  `'not-on-path'` case), blank lines dropped. Returns `''` when there is
 *  nothing beyond the always-visible one-line `message`. Origin: the
 *  `tooltip` computation inside `AgentDiagnosticRow`. */
export function agentDiagnosticTooltip(diagnostic: AgentDiagnostic): string {
  return [diagnostic.detail, ...(diagnostic.searchedDirs ?? [])]
    .filter((line): line is string => typeof line === 'string' && line.length > 0)
    .join('\n');
}

/**
 * Splits a model id into its base and its reasoning-effort suffix, for a runtime that encodes
 * effort inside the id (`DetectedAgent.reasoningInModelId`).
 *
 * Only a trailing `-<token>` whose token appears in `levelIds` is a level. Everything else stays
 * part of the base id — which is the whole point: `claude-opus-4-6-thinking` ends in `-thinking`,
 * which LOOKS like a modifier and is not an effort level, and reading it as one would invent a
 * `claude-opus-4-6` base that has no variants and a `thinking` level no control can render.
 *
 * @param modelId - A full model id from the agent's own catalog.
 * @param levelIds - The declared effort vocabulary (`reasoningInModelId.levels`, ids only).
 * @returns The base id and the level, or `level: null` when the id carries no recognized suffix.
 * @complexity O(k) in `levelIds.length`.
 */
export function splitReasoningModelId(
  modelId: string,
  levelIds: readonly string[],
): { baseId: string; level: string | null } {
  for (const level of levelIds) {
    const suffix = `-${level}`;
    // `length > suffix.length` rather than `endsWith` alone: an id that is nothing BUT the suffix
    // has no base to split off, and splitting it would merge every such entry into one empty-id
    // group.
    if (modelId.length > suffix.length && modelId.endsWith(suffix)) {
      return { baseId: modelId.slice(0, -suffix.length), level };
    }
  }
  return { baseId: modelId, level: null };
}

/**
 * Strips a trailing effort qualifier from a model label — `Gemini 3.1 Pro (High)` -> `Gemini 3.1
 * Pro` — and only when the label really ends in the qualifier for the level its id carried.
 *
 * Deliberately narrow: it removes a parenthetical only when that parenthetical's contents match
 * THIS entry's own level (by id or by label, case-insensitively). `Claude Sonnet 4.6 (Thinking)`
 * has no level, so nothing is stripped, and a vendor label that happens to end in an unrelated
 * parenthetical keeps it.
 */
/** `Head (Inner)` with optional surrounding whitespace; group 1 is the head, group 2 the qualifier. */
const TRAILING_PARENTHETICAL = /^(.*?)\s*\(([^()]*)\)\s*$/;

function baseLabelForLevel(label: string, level: AgentModelOption | undefined): string {
  if (!level) return label;
  if (!TRAILING_PARENTHETICAL.test(label)) return label;
  // Both capture groups always participate once the pattern matches, so reading them through
  // `replace` (which yields a plain string) replaces the old `match[n] ?? ''` fallbacks, which no
  // matching label could ever reach.
  const inner = label.replace(TRAILING_PARENTHETICAL, '$2').trim().toLowerCase();
  if (inner !== level.id.toLowerCase() && inner !== level.label.toLowerCase()) return label;
  const stripped = label.replace(TRAILING_PARENTHETICAL, '$1').trim();
  return stripped || label;
}

/**
 * Groups an agent's model list by base model, recording for each base the effort levels it
 * ACTUALLY has.
 *
 * Derived, never declared — that is the correctness property this function exists for. Verified
 * against `agy models`' real output: `gemini-3.8-flash` has high/medium/low, `gemini-3.1-pro` has
 * ONLY high and low, `gpt-oss-120b` only medium, and `claude-sonnet-4-6` none. A fixed
 * high/medium/low control would offer `gemini-3.1-pro-medium`, which does not exist and which
 * `agy --model` rejects outright. Running the same derivation over whichever list the host
 * supplied — live from the CLI or the def's `fallbackModels` — is also what makes an offline
 * degrade behave consistently rather than differently.
 *
 * @param models - The agent's model catalog, in the order it should be offered.
 * @param levels - The declared effort vocabulary, in display order.
 * @returns One group per base id, in first-appearance order. With an empty vocabulary every id is
 *   its own bare group, so a caller needs no special case for "this agent declares nothing".
 * @complexity O(n * k) in the catalog size and the vocabulary size.
 */
export function reasoningModelGroups(
  models: readonly AgentModelOption[],
  levels: readonly AgentModelOption[],
): ReasoningModelGroup[] {
  const levelIds = levels.map((level) => level.id);
  const byBase = new Map<string, { label: string; ids: Map<string, string>; bare?: string }>();
  for (const model of models) {
    const { baseId, level } = splitReasoningModelId(model.id, levelIds);
    const existing = byBase.get(baseId);
    const entry = existing ?? { label: baseLabelForLevel(model.label, levels.find((l) => l.id === level)), ids: new Map<string, string>() };
    if (level === null) {
      // A base listed on its own AND with variants keeps both: the bare id is the "no effort
      // stated" choice, the variants are the stated ones.
      entry.bare = model.id;
    } else {
      entry.ids.set(level, model.id);
    }
    if (!existing) byBase.set(baseId, entry);
  }
  return [...byBase.entries()].map(([baseId, entry]) => ({
    baseId,
    label: entry.label,
    // Ordered by the DECLARED vocabulary, not by catalog order, so the control's option order is
    // stable across bases even if a CLI ever lists one base's variants in a different order.
    levels: levels.filter((level) => entry.ids.has(level.id)),
    modelIdByLevel: Object.fromEntries(entry.ids),
    ...(entry.bare !== undefined ? { bareModelId: entry.bare } : {}),
  }));
}

/** The group a full model id belongs to, or `null` when the id is not in this catalog at all — a
 *  saved pick from an older/different catalog must not be silently attached to some other base. */
export function reasoningModelGroupFor(
  groups: readonly ReasoningModelGroup[],
  modelId: string,
  levelIds: readonly string[],
): ReasoningModelGroup | null {
  if (!modelId) return null;
  const { baseId } = splitReasoningModelId(modelId, levelIds);
  return groups.find((group) => group.baseId === baseId) ?? null;
}

/**
 * Recombines a base model and an effort level back into one model id — the value `--model`
 * actually receives.
 *
 * Never composes a string: every id it can return came out of the agent's own catalog. That is
 * what makes "switch base while a level is selected" safe — carrying `medium` from
 * `gemini-3.8-flash` over to `gemini-3.1-pro` cannot produce `gemini-3.1-pro-medium`, because
 * that base's table has no `medium` entry and the fallback below lands on a level it does have.
 *
 * @param group - The target base's derived group.
 * @param level - The level to prefer, or `null` for "no preference".
 * @returns An id from the catalog: the requested level's, else the base's bare id, else its first
 *   available level's, else the bare base id (only reachable for a group built from nothing).
 * @complexity O(1).
 */
export function modelIdForReasoningLevel(group: ReasoningModelGroup, level: string | null): string {
  if (level) {
    const exact = group.modelIdByLevel[level];
    if (exact) return exact;
  }
  if (group.bareModelId !== undefined) return group.bareModelId;
  const first = group.levels[0];
  return first ? (group.modelIdByLevel[first.id] ?? group.baseId) : group.baseId;
}

import type { ProviderPreset as SharedProviderPreset } from '@jini-ai/core';
/**
 * Origin: the inline `execution` tab body in `SettingsDialog.tsx`
 * (lines 4080-5336), classified MIXED by
 * `ADS-memory/reports/jini-port/recon/r6-god-component-internals.md` §1.3 — a generic
 * "Local CLI vs. bring-your-own-key" execution switch wrapped in
 * origin-specific managed-runtime/wallet chrome.
 *
 * What is ported: the mode switch, the provider/gateway chip groups, and the
 * BYOK credential form (the origin had already factored these fields into
 * `components/byok/*`, which is why this slice is assembly rather than
 * surgery).
 *
 * What is deliberately left behind: the origin's managed-runtime wallet
 * (balance polling, top-up, sign-in coachmarks, the `SettingsHighlight`
 * one-shot focus hint) and its analytics tracking calls — all product-bound,
 * none of it generic.
 */

/** `'local-cli'` runs a detected code-agent CLI on this machine; `'byok'`
 *  talks to a model endpoint with the operator's own credentials. The origin
 *  spelled these `'daemon'` and `'api'` — renamed here to say what they mean
 *  rather than how the origin's transport happened to be wired. */
export type ExecutionMode = 'local-cli' | 'byok';

/** Wire protocol a BYOK endpoint speaks. Vendor-shaped, not product-shaped:
 *  these name public API dialects, the same way `features/i18n` names locales. */
export type ApiProtocol = 'anthropic' | 'openai' | 'azure' | 'google';

/** Where a preset renders in the chip strip. The origin drew one row of
 *  protocol presets and one of gateway presets; hosts that don't care can
 *  leave this unset and get a single row. */
export type { ProviderPresetKind } from '@jini-ai/core';

/** One selectable endpoint preset supplied by the host. */
export interface ProviderPreset extends SharedProviderPreset<ApiProtocol> {}

/**
 * One advisory remark about the API key currently typed into the form, ready to translate.
 *
 * `message` is plain English AND its own i18n key (this package's convention — see
 * `DEFAULT_AGENT_DESCRIPTIONS`), and `vars` fills its `{name}` placeholders. Kept split rather than
 * pre-composed because the vendor names are runtime values from the catalog: a pre-composed
 * sentence would be a key no dictionary can contain, and would also freeze English word order for
 * every locale.
 *
 * Advisory by construction — a message, not a validity verdict. See {@link ProviderPreset.apiKeyPrefix}.
 */
export interface ApiKeyWarning {
  message: string;
  vars: Readonly<Record<string, string>>;
}

/** One provider's saved credential draft — everything `ByokConfig` carries at
 *  the top level, minus the selection fields (`protocol`/`providerId`), which
 *  only make sense for the *active* selection. */
export interface ByokProviderCredentials {
  apiKey: string;
  baseUrl: string;
  model: string;
  maxTokens?: number | undefined;
}

/**
 * The operator's BYOK credentials and endpoint selection.
 *
 * `apiKey`/`baseUrl`/`model`/`maxTokens` at the top level are the *active*
 * selection's live values — what the form renders and what a connection test
 * or real dispatch uses right now. They are NOT shared across providers:
 * every other preset's last-saved credentials live in `savedByProviderId`,
 * keyed by preset id, and `nextConfigForPresetSelect` (`rules.ts`) snapshots
 * the outgoing provider into that map before loading the incoming one.
 *
 * Origin: `state/config.ts`'s `apiProtocolConfigs` (keyed per protocol) plus
 * `byokProviderConfigDrafts` (keyed per protocol+baseUrl, for presets that
 * share a protocol but not an endpoint). This package collapses both into one
 * map keyed by preset id, which is already unique per endpoint in this tab's
 * catalog. Without this split, every preset chip's "configured" status
 * (`isProviderConfigured`) reads the SAME shared fields — so selecting
 * Anthropic and typing a key made the unrelated Ollama chip (which requires
 * no key) render "configured" too, because it was being checked against
 * Anthropic's live base URL rather than its own.
 */
export interface ByokConfig {
  protocol: ApiProtocol;
  /** `null` selects the custom/manual endpoint rather than a preset. */
  providerId: string | null;
  apiKey: string;
  baseUrl: string;
  model: string;
  /** Omitted/undefined means "use the model's own default", which is why this
   *  is not `number | 0` — 0 would be a real cap of zero tokens. */
  maxTokens?: number | undefined;
  /** Saved credentials for every preset OTHER than the active selection,
   *  keyed by `ProviderPreset.id`. See this interface's header. */
  savedByProviderId?: Readonly<Record<string, ByokProviderCredentials>>;
}

export interface ExecutionConfig {
  mode: ExecutionMode;
  byok: ByokConfig;
  localCli: LocalCliConfig;
}

/** One model a detected agent can be asked to run. Mirrors
 *  `@jini-ai/agent-runtime`'s `RuntimeModelOption` field-for-field so a host
 *  backed by that package passes its detection payload through unmapped. */
export interface AgentModelOption {
  id: string;
  label: string;
  identityKind?: 'concrete' | 'alias' | 'routing-mode';
  resolvedId?: string;
  /**
   * The reasoning-effort levels THIS model supports, when the runtime's own catalog reports them
   * per model rather than uniformly across the agent. Mirrors `@jini-ai/agent-runtime`'s
   * `RuntimeModelOption.reasoning` field-for-field, for the same reason every other field on this
   * interface does (see this file's header doc) — Codex's `debug models` catalog reports it, and the
   * levels genuinely differ between models on the same CLI.
   *
   * `undefined` means "nothing model-specific to say" and is read as agent-wide by
   * `useReasoningControl`'s narrowing rule — it falls back to `DetectedAgent.reasoningOptions`'s
   * union, the same list every model showed before this field existed. It is NOT a synonym for "zero
   * levels". An explicit `[]` means the catalog said so outright, and is honored as-is even though it
   * hides the effort control for that model.
   */
  reasoning?: readonly AgentModelOption[] | undefined;
}

/** Where an agent's model list came from. `'live'` was pulled from the CLI
 *  itself (its config or a catalog call); `'fallback'` is the adapter's
 *  built-in list. The distinction is rendered, not cosmetic: an operator
 *  looking at a stale built-in list needs to know a rescan can improve it. */
export type AgentModelSource = 'live' | 'fallback';

/** Whether the CLI appears to be signed in. `'unknown'` is a real third state,
 *  not a synonym for `'missing'` — an adapter with no auth probe, or a probe
 *  that could not be classified, genuinely does not know, and saying
 *  "authentication required" there would be a false claim. */
export type AgentAuthStatus = 'ok' | 'missing' | 'unknown';

/** Whether an agent's CLI accepts an operator-typed model id outside its
 *  known `models` list. `undefined` means "allow" (most CLIs do) — a host
 *  opts OUT with an explicit `false` for a CLI that routes model selection
 *  through a closed catalog (no free-text `--model` flag, or a protocol that
 *  validates the id against a live catalog and rejects unknown ones).
 *  Origin: `RuntimeAgentDef.supportsCustomModel`. */
export type AgentSupportsCustomModel = boolean;

/**
 * A code-agent CLI found on the machine that ran detection, as reported by
 * `ExecutionPort`.
 *
 * Everything below `path` is optional because a host may know less than
 * `@jini-ai/agent-runtime` does — but a host backed by that package should
 * pass all of it through. Its `DetectedAgent` (`types.ts`, the `models` /
 * `modelsSource` / `authStatus` / `authMessage` / `path` / `version`
 * intersection) already carries every field here, so narrowing the payload at
 * the route boundary throws away data the card is built to render.
 */
export interface DetectedAgent {
  /** Cached inventory is usable now; retry a normal read until background discovery settles. */
  discoveryPending?: boolean;
  id: string;
  label: string;
  installed: boolean;
  version?: string | undefined;
  /** Absolute path to the resolved binary, when the host can determine it. */
  path?: string | undefined;
  /** One-line vendor description ("Anthropic official CLI"). Describes the
   *  CLI, not the product embedding it — see `DEFAULT_AGENT_DESCRIPTIONS`,
   *  which a host may extend or replace. */
  description?: string | undefined;
  models?: readonly AgentModelOption[] | undefined;
  modelsSource?: AgentModelSource | undefined;
  /** Reasoning-effort/mode presets this agent's model exposes (e.g.
   *  "low"/"medium"/"high"), reusing `AgentModelOption`'s `{id, label}` shape
   *  — the same shape `@jini-ai/agent-runtime`'s `RuntimeReasoningOption`
   *  aliases from its model-option type, for the same reason: a reasoning
   *  choice IS a model-catalog entry, just from a different picker. Absent or
   *  empty means the agent has no reasoning axis to configure. */
  reasoningOptions?: readonly AgentModelOption[] | undefined;
  /**
   * Declares that this agent's CLI carries its reasoning-effort choice INSIDE
   * the model id — as a trailing `-<level>` on the slug — instead of in a flag
   * of its own, and names which trailing tokens count as levels.
   *
   * Mirrors `@jini-ai/agent-runtime`'s `RuntimeReasoningInModelId` field-for-
   * field, the same way `reasoningOptions` above mirrors its
   * `RuntimeReasoningOption[]`, and for the same reason (see this interface's
   * own doc). Present INSTEAD of `reasoningOptions`, never alongside it: a card
   * carrying both would render two effort controls that disagree about where
   * the choice goes.
   *
   * Only the vocabulary is declared. Which of these levels a given base model
   * actually has is DERIVED from `models` by `reasoningModelGroups`
   * (`rules.ts`) — availability is genuinely not uniform (antigravity's
   * `gemini-3.1-pro` has only high and low, `gpt-oss-120b` only medium,
   * `claude-sonnet-4-6` none), so a fixed high/medium/low control would offer
   * slugs the CLI rejects outright.
   */
  reasoningInModelId?: { levels: readonly AgentModelOption[] } | undefined;
  /** See `AgentSupportsCustomModel`. `undefined` allows custom input,
   *  matching every adapter's default before this field existed. */
  supportsCustomModel?: AgentSupportsCustomModel | undefined;
  authStatus?: AgentAuthStatus | undefined;
  /** Operator-actionable detail behind a `'missing'`/`'unknown'` status —
   *  rendered as the meta line's tooltip so the card stays compact without
   *  discarding the reason. */
  authMessage?: string | undefined;
  /** Short marketing-ish tags ("Official", "Lower cost"). The mechanism is
   *  generic; the vocabulary is the host's — this package ships none. */
  badges?: readonly string[] | undefined;
  /** Why this agent is unavailable or only partially usable, as one or more
   *  renderable "reason + fix button(s)" rows — see `AgentDiagnostic`. Absent
   *  or empty means detection has nothing actionable to report (the common
   *  case for a healthy, authenticated CLI). */
  diagnostics?: readonly AgentDiagnostic[] | undefined;
  /** Destination for an `{kind: 'openInstall'}` fix action — the CLI's
   *  install/download page. Absent hides that action even if a diagnostic
   *  requests it, per `AgentDiagnosticRow`'s "only render what the host can
   *  actually do" contract. */
  installUrl?: string | undefined;
  /** Destination for an `{kind: 'openDocs'}` fix action — the CLI's
   *  configuration/auth docs. Same absent-hides-the-action rule as
   *  `installUrl`. */
  docsUrl?: string | undefined;
}

/**
 * Why a CLI agent is unavailable or only partially usable, in a shape a UI
 * can render as "one-line reason + fix button(s)" instead of a silent grey
 * card.
 *
 * Origin: OD's `packages/contracts/src/api/registry.ts#AgentDiagnostic` /
 * `AgentFixIntent`, vendored into `@jini-ai/protocol`'s `agent-catalog.ts`
 * (2026-07-29) unmodified. Mirrored here field-for-field rather than
 * imported — this file has zero imports of its own (framework-free, part of
 * this package's `./core` subpath), the same reasoning `DetectedAgent`'s own
 * doc comment gives for mirroring `@jini-ai/agent-runtime`'s shape instead of
 * depending on that Node-only package. A host on `@jini-ai/agent-runtime` /
 * `@jini-ai/protocol` passes its `AgentDiagnostic[]` straight through
 * unmapped, since the fields are identical.
 */
export interface AgentDiagnostic {
  reason: AgentDiagnosticReason;
  severity: AgentDiagnosticSeverity;
  /** Short, human-readable, single-sentence explanation. */
  message: string;
  /** Optional longer context (e.g. the probe's stderr tail). */
  detail?: string | undefined;
  /** Directories PATH detection searched, surfaced verbatim for the
   *  `'not-on-path'` case so the operator can see where detection looked
   *  before being asked to set an explicit binary path. */
  searchedDirs?: readonly string[] | undefined;
  /** Ordered fix affordances the UI should offer for this diagnostic. */
  fixActions?: readonly AgentFixIntent[] | undefined;
}

export type AgentDiagnosticReason =
  /** The binary (and any fallback names) was not found on PATH. */
  | 'not-on-path'
  /** A file matched but is not executable (missing +x / wrong PATHEXT). */
  | 'not-executable'
  /** A wrapper/shim was found but its target is gone (exit 126/127). */
  | 'shim-broken'
  /** A user-set binary-path override points at a missing/invalid file. */
  | 'configured-bin-invalid'
  /** Installed and invocable, but the CLI is not authenticated. */
  | 'auth-missing'
  /** Installed, but auth status could not be verified. */
  | 'auth-unknown';

export type AgentDiagnosticSeverity = 'error' | 'warning' | 'info';

/**
 * A typed "what should the UI do to fix this" intent attached to an
 * `AgentDiagnostic`. The UI renders one button per intent and owns the
 * concrete handler (open a URL, re-run detection, write an env override);
 * keeping the intent typed — rather than a pre-baked button label + URL —
 * lets more than one surface render the same fix affordances from one
 * source of truth.
 */
export type AgentFixIntent =
  /** Open the agent's configuration/auth docs. */
  | { kind: 'openDocs' }
  /** Open the agent's install/download page. */
  | { kind: 'openInstall' }
  /** Re-run agent detection (this tab's rescan affordance). */
  | { kind: 'rescan' }
  /** Prompt the operator to point the host at an explicit binary by writing
   *  `envKey` into `LocalCliConfig.envByAgentId` — used when the CLI is
   *  installed somewhere PATH detection can't reach. */
  | { kind: 'setEnv'; envKey: string }
  /** Clear a previously-set binary override so detection falls back to PATH. */
  | { kind: 'clearEnv'; envKey: string }
  /** Launch the agent's interactive sign-in in a system terminal (used by
   *  adapters whose OAuth flow cannot complete headlessly). */
  | { kind: 'launchOAuth'; agentId: string };

/**
 * Catalog entry describing one operator-configurable CLI environment
 * variable for one agent (a proxy base URL, a custom config directory, a
 * binary-path override, …). Origin: `AGENT_CLI_ENV_FIELDS`. A host supplies
 * its own catalog the same way it supplies `ProviderPreset`s — this package
 * ships `DEFAULT_AGENT_CLI_ENV_FIELDS` as a starting point for the CLIs it
 * already knows about (see `DEFAULT_AGENT_DESCRIPTIONS`), not as a fixed list.
 */
export interface AgentCliEnvFieldSpec {
  agentId: string;
  envKey: string;
  /** Field label. This package's convention: the English string IS the i18n
   *  key (see `PROTOCOL_OPTIONS`) — a host translates it, it does not supply
   *  a separate key. */
  label: string;
  placeholder?: string | undefined;
  /** Renders the input as `type="password"` and omits the value from any
   *  plain-text display. */
  secret?: boolean | undefined;
  /** Marks this field as the agent's executable-path override — the field a
   *  "use detected path" / "clear custom path" repair affordance (see
   *  `agentExecutableRepairState`) should set or clear. At most one field per
   *  `agentId` should carry this; the mechanism is generic, but this
   *  package's own `DEFAULT_AGENT_CLI_ENV_FIELDS` only tags Codex's
   *  `CODEX_BIN`, mirroring the origin's actual (Codex-only) behavior. */
  kind?: 'binPath' | undefined;
}

/**
 * Which detected CLI runs the operator's prompts, and with which model.
 *
 * `modelByAgentId` is keyed rather than flat because the picker is per-agent:
 * switching from Claude to Codex and back must not silently hand Codex's model
 * id to Claude. The origin kept the same shape (`cfg.agentModels`, keyed by
 * agent id) for the same reason.
 */
export interface LocalCliConfig {
  /** `null` until the operator picks one — deliberately not defaulted to the
   *  first detected agent, so "nothing selected" stays distinguishable from
   *  "the first one was chosen for you". */
  agentId: string | null;
  modelByAgentId?: Readonly<Record<string, string>>;
  /** Per-agent reasoning-effort pick, keyed the same way as `modelByAgentId`
   *  and for the same reason: switching agents and back must not hand one
   *  agent's reasoning choice to another. */
  reasoningByAgentId?: Readonly<Record<string, string>>;
  /** Per-agent CLI environment overrides — proxy URLs, custom config dirs, a
   *  binary-path override — keyed by agent id then env var name. Origin:
   *  `AppConfig.agentCliEnv`. Mirrors that two-level shape directly rather
   *  than flattening it, since a field's env-var name is only unique WITHIN
   *  an agent (`CODEX_BIN` means nothing for `claude`). */
  envByAgentId?: Readonly<Record<string, Readonly<Record<string, string>>>>;
}

/** Which required BYOK field is still blank/invalid. Drives the inline
 *  "required" markers without the tab hard-coding field labels. */
export type ByokRequiredField = 'apiKey' | 'baseUrl' | 'model';

export type ConnectionTestState =
  | { status: 'idle' }
  | { status: 'testing' }
  | { status: 'ok'; message?: string | undefined }
  | { status: 'error'; message: string };

/**
 * Which executable a Local-CLI test actually invoked. `'primary'` is the
 * normal case (the resolved/on-PATH binary ran). The two `fallback-*`
 * variants report that a configured binary-path override
 * (`AgentCliEnvFieldSpec` with `kind: 'binPath'`) could not be used and
 * detection fell back to a different binary anyway — `'fallback-invalid'`
 * when the override path never resolved to an executable, `'fallback-failed'`
 * when it resolved but failed to run. Both are the trigger for
 * `agentExecutableRepairState`'s repair affordance. Origin: OD's
 * `ConnectionTestResponse.usedExecutableSource` (`'fallback_invalid'` /
 * `'fallback_failed'`, renamed to this package's kebab-case convention).
 */
export type AgentExecutableSource = 'primary' | 'fallback-invalid' | 'fallback-failed';

/** Result of the per-agent Test button, surfaced under the selected card.
 *  Same idiom as `ConnectionTestState` — the two report the same kind of
 *  outcome for the two execution modes, so they deliberately share a shape.
 *  `usedExecutableSource`/`detectedExecutablePath` are optional passthrough
 *  from `ExecutionPort.testAgent`'s result, present only when the host's
 *  probe can report which binary it actually ran — see
 *  `agentExecutableRepairState`. */
export type AgentTestState =
  | { status: 'idle' }
  | { status: 'testing'; agentId: string }
  | {
      status: 'ok';
      agentId: string;
      message?: string | undefined;
      usedExecutableSource?: AgentExecutableSource | undefined;
      detectedExecutablePath?: string | undefined;
    }
  | { status: 'error'; agentId: string; message: string };

/** The repair affordance a successful-but-fallback agent test unlocks: an
 *  operator-set binary-path override didn't work, detection silently fell
 *  back to a different binary, and the test still passed — so the operator
 *  should be offered "use the binary that actually worked" or "clear the
 *  override and stop overriding". `canUseDetected` is carried explicitly
 *  (rather than always being implied `true`) so a future detection outcome
 *  that finds a fallback path but cannot vouch for it has somewhere to say
 *  so without a breaking shape change. */
export interface AgentExecutableRepair {
  detectedPath: string;
  canUseDetected: boolean;
}

/**
 * One base model of a `DetectedAgent.reasoningInModelId` agent, together with the effort levels
 * that model ACTUALLY has — derived from the agent's own model list by `reasoningModelGroups`
 * (`rules.ts`), never declared.
 *
 * This is the shape the card renders its two controls from: the base picker lists one entry per
 * group, and the effort picker lists exactly `levels` for whichever group is active. That is what
 * keeps it from offering a slug the CLI would reject — `gemini-3.1-pro` genuinely has no `-medium`
 * variant, so `levels` genuinely has no `medium` entry.
 */
export interface ReasoningModelGroup {
  /** The model id with any recognized effort suffix removed (`gemini-3.1-pro`). */
  baseId: string;
  /** Display name for the base. The effort qualifier is stripped from the source label only when
   *  the id it came from carried a real suffix — so `Gemini 3.1 Pro (High)` becomes `Gemini 3.1
   *  Pro`, while `Claude Sonnet 4.6 (Thinking)` (a suffix-less id) keeps its parenthetical. */
  label: string;
  /** The effort levels this base really offers, in the declared vocabulary's order. Empty for a
   *  base the catalog lists without any suffixed variant. */
  levels: readonly AgentModelOption[];
  /** Full model id per level in `levels` — the recombination table, so composing a slug is a
   *  lookup of something the catalog actually contained rather than string concatenation. */
  modelIdByLevel: Readonly<Record<string, string>>;
  /** The suffix-less id, when the catalog lists the base on its own (`claude-sonnet-4-6`,
   *  `default`). Absent for a base that only ever appears with a suffix. */
  bareModelId?: string | undefined;
}

/** Result of a local-CLI rescan, surfaced as an inline status line. */
export type AgentScanState =
  | { status: 'idle' }
  | { status: 'scanning' }
  | { status: 'ok'; count: number }
  | { status: 'error'; message: string };

/** Result of `ExecutionPort.listModels`, surfaced as an inline hint near the
 *  Model field. Mirrors `ConnectionTestState`/`AgentScanState`'s shape
 *  deliberately — one idiom for "async edge result" across this tab, per
 *  this package's error-reporting contract (§3.2: reuse an existing union
 *  over introducing a parallel shape). A failure here must NOT collapse
 *  into the same "no models" the field already tolerates when a host
 *  supplies no `listModels` at all — `'error'` is a distinct, renderable
 *  state, not an empty `'ok'`. */
export type ModelDiscoveryState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ok'; models: readonly string[] }
  | { status: 'error'; message: string };

/**
 * Pure logic for the file-dropzone feature. No React, no DOM globals — every
 * DOM-shaped value (`File`, event targets) arrives as a parameter.
 */
import { FILE_DROPZONE_KIND_BY_EXTENSION } from './constants.js';
import type { FileDropzoneKind } from './types.js';
import { trimChars } from '../../utils/trim-chars.js';

/** Lowercased extension (no dot), or `''` for an extensionless name. */
export function fileDropzoneExtension(file: File): string {
  return (/\.([a-z0-9]+)$/i.exec(file.name)?.[1] ?? '').toLowerCase();
}

/** MIME-first (authoritative when present), falling back to extension for files the browser typed as `application/octet-stream`. */
export function fileDropzoneKind(file: File): FileDropzoneKind {
  const type = file.type.toLowerCase();
  const ext = fileDropzoneExtension(file);
  if (type.startsWith('image/')) return 'image';
  if (type.startsWith('video/')) return 'video';
  if (type.startsWith('audio/')) return 'audio';
  if (type === 'application/pdf') return 'pdf';
  if (type === 'text/html') return 'html';
  if (type.startsWith('font/')) return 'font';
  if (type.startsWith('text/')) return 'text';
  return FILE_DROPZONE_KIND_BY_EXTENSION[ext] ?? 'other';
}

/** Kinds renderable straight from an object URL (`blob:`). Fonts also need one (`FontFace` loads from a URL); text is read via `FileReader`/`Blob.text()` instead. */
export function fileDropzoneNeedsObjectUrl(kind: FileDropzoneKind): boolean {
  return kind === 'image' || kind === 'video' || kind === 'audio' || kind === 'pdf' || kind === 'html' || kind === 'font';
}

/** Uppercased, 4-char-capped extension for the glyph badge (e.g. `"a/b.jpeg"` -> `"JPEG"`, extensionless -> `"FILE"`). */
export function fileDropzoneExtensionLabel(file: File): string {
  return (fileDropzoneExtension(file) || 'file').toUpperCase().slice(0, 4);
}

export function fileDropzoneSizeLabel(bytes: number): string {
  if (!bytes || bytes <= 0) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

/** A stable key for a staged `File` (name + size + mtime is collision-safe for the staging lists this feature renders). */
export function fileDropzoneStagingKey(file: File): string {
  return `${file.name}:${file.size}:${file.lastModified}`;
}

/** CSS-safe, collision-resistant `@font-face` family name for a staged font at `index`. */
export function fileDropzoneFontFamilyName(file: File, index: number): string {
  const slug = trimChars(file.name.replace(/[^a-z0-9]+/gi, '-'), '-').slice(0, 24);
  return `jini-file-dropzone-font-${index}-${slug || 'font'}`;
}

/** Whether a selection is large enough (by count or total bytes) to warrant a loading affordance while it's staged. */
export function fileDropzoneShouldShowProcessing(
  files: readonly File[],
  fileCountThreshold: number,
  totalBytesThreshold: number,
): boolean {
  if (files.length >= fileCountThreshold) return true;
  const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
  return totalBytes >= totalBytesThreshold;
}

/**
 * @file Decorates every canvas element a host recognizes as an unresolved embed marker with an
 * explicit "this is a placeholder, not real content" card, so an operator editing a document in the
 * canvas sees something intentional where an embed will render instead of an empty, unlabeled element
 * that looks safe to delete by accident.
 *
 * Same seam as `canvas-content-wrapper.ts`, for the identical reason: this module has zero knowledge
 * of what an "embed marker" IS (that convention — `data-embed-config`, a `{"type":...}` JSON payload —
 * belongs to a host; see `@jini-ai/admin/react`'s `InteractiveHtmlEditor` for the one that supplies
 * it), and it runs on GrapesJS's `load` event against the live canvas DOM
 * (`editor.Canvas.getBody()`), never through the `components` string GrapesJS's exported
 * `getHtml()`/`getCss()` are built from. See that sibling file's header for the fuller argument; the
 * short version: GrapesJS's export walks its own component MODEL, which is fixed at
 * `grapesjs.init({ components: html })` and never re-reads the canvas iframe's live DOM afterward, so
 * anything this module adds to that DOM later is invisible to export by construction, not because of a
 * strip-on-save step that could be forgotten or miss a case.
 *
 * **The marker element is never given new children of its own — a NEW wrapper is built around it
 * instead, and the marker is MOVED inside that wrapper (never cloned), exactly the "move, never clone"
 * technique `canvas-content-wrapper.ts` uses to keep GrapesJS's component-view `.el` references
 * intact.** This is the one place this module's technique goes beyond a plain copy of that sibling's,
 * and the reason is a real, currently-open hazard specific to embed markers: a marker element is not
 * guaranteed to be excluded from GrapesJS's own RTE (rich-text-editing) machinery by a host's
 * `isProtectedElement` predicate — see `InteractiveHtmlEditor.tsx` (`@jini-ai/admin/react`)'s own doc
 * for that gap. If GrapesJS ever treats a marker element as an editable `text` component, an edit
 * gesture on it triggers `ComponentTextView.syncContent`, which re-parses that element's LIVE
 * `innerHTML` back into the component model. Putting the card's markup INSIDE the marker would hand
 * that re-parse something real to capture into a saved document; putting it in a wrapper AROUND the
 * (untouched, still literally empty) marker means there is nothing inside the marker for that re-parse
 * to ever pick up, regardless of whether that `isProtectedElement` gap is ever closed.
 *
 * **Safe to call again after every structural edit** (the hook does, on the tick after any component
 * add or remove): each pass first drops cards whose marker has gone (see `removeStaleCards`), then
 * wraps any marker not already inside a card.
 *
 * Re-entrancy (defensive, mirroring `canvas-content-wrapper.ts`'s own `WRAPPER_ROOT_MARKER` guard): a
 * marker already sitting inside a placeholder card (`el.closest('[' + CARD_ROOT_MARKER + ']')`) is
 * skipped, so a second call — or a caller's own `load` handler firing twice — cannot nest a second card
 * around an already-decorated marker. Only a runtime card's direct marker is described again, to
 * refresh its footprint after theme styles settle; card chrome is always skipped.
 */

/** What to show on one embed's placeholder card — supplied per-element by the host's own `describe`
 *  callback, since only the host knows the marker convention (attribute name, JSON shape, and how to
 *  turn a parsed config into words a human recognizes). */
export interface CanvasEmbedPlaceholderDescriptor {
  /** Short name for the embed's kind, shown as the card's heading — e.g. `"Media"`, `"Widget"`. */
  kindLabel: string;
  /** Human-identifiable target, shown under the heading — e.g. a name, or a truncated id, or a note
   *  that none was set. Never fetched by this module; the host decides what's cheap enough to show. */
  identityLabel: string;
  /** Runtime blocks use the same card with a bounded view-only footprint and locked guidance. */
  presentation?: 'embed' | 'runtime';
  guidanceLabel?: string;
  inline?: boolean | undefined;
  declaredHeight?: number | undefined;
}

/** Finite positive declared/native geometry wins, otherwise use the bounded runtime fallback. */
export function editorBlockHeight(
  { declaredHeight, nativeHeight, inline }: { declaredHeight?: number | undefined; nativeHeight?: number | undefined; inline?: boolean | undefined },
  _options: object = {},
): number {
  const height = [declaredHeight, nativeHeight].find(value => typeof value === 'number' && Number.isFinite(value) && value > 0);
  return Math.max(inline ? 48 : 96, Math.min(inline ? 160 : 960, height ?? (inline ? 64 : 280)));
}

/** Marks a placeholder card's own root, so a later pass (this function called again, or a re-entrant
 *  `load`) can recognize an already-decorated marker via `el.closest` and skip it — see this file's
 *  header. */
const CARD_ROOT_MARKER = 'data-jini-embed-placeholder-root';

/** Canvas-only flag permitting footprint refreshes without describing embed cards or chrome again. */
const CARD_RUNTIME_MARKER = 'data-jini-embed-placeholder-runtime';

/** Flags every child the card itself builds (icon, text), so the one unflagged child is always the
 *  marker. {@link OVERLAY_RULE} and the stale-card check in `removeStaleCards` both rely on it. */
const CARD_CHROME_MARKER = 'data-jini-embed-placeholder-chrome';

/** Identifies the one `<style>` this module adds to the canvas document's `<head>`. */
const OVERLAY_STYLE_MARKER = 'data-jini-embed-placeholder-style';

/**
 * Stretches the (empty) marker over its card as a transparent overlay, so a click anywhere on the card
 * lands on the marker element itself. GrapesJS resolves a click by walking up from the event target to
 * the nearest element it rendered; the card is not one of those, so without this a click on the card
 * selected whatever block wraps the embed, and Delete then removed that block together with the embed.
 * With it, the editor selects (and outlines) the embed. A stylesheet rule rather than an inline style,
 * so the marker's own attributes stay untouched. `!important` because the host's theme may style the
 * marker element.
 */
const OVERLAY_RULE =
  `[${CARD_ROOT_MARKER}] > :not([${CARD_CHROME_MARKER}])` +
  ' { position: absolute !important; inset: 0 !important; margin: 0 !important; width: auto !important;' +
  ' height: auto !important; min-width: 0 !important; max-width: none !important; min-height: 0 !important;' +
  ' display: block !important; background: transparent !important; }';

/** One CSS declaration list, as `property:value` pairs, for the card's own opaque chrome. Deliberately
 *  NOT derived from the host's theme in any way — themes are arbitrary and downloadable, and this card
 *  must stay legible whether the canvas underneath is a light theme, a dark theme, or (mid-edit) no
 *  theme at all. An opaque background plus a fixed, high-contrast foreground guarantees that
 *  regardless of what renders behind it, unlike a translucent or theme-token-based treatment would. */
const CARD_STYLE = [
  'position:relative',
  'display:flex',
  'align-items:flex-start',
  'gap:8px',
  'box-sizing:border-box',
  'border:2px dashed var(--jini-warning)',
  'border-radius:8px',
  'background:var(--jini-surface)',
  'color:var(--jini-text)',
  'padding:10px 12px',
  "font:13px/1.4 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif",
].join(';');

/** Builds the small dashed-square-with-a-plus glyph that opens every card — assembled via
 *  `createElementNS`/`setAttribute` rather than an `innerHTML` template string, so its element nodes
 *  are unambiguously in the SVG namespace regardless of parser quirks around fragment-parsing SVG
 *  content on an element that itself was just created and not yet attached to a document. */
function buildPlaceholderIcon(doc: Document): SVGSVGElement {
  const SVG_NS = 'http://www.w3.org/2000/svg';
  const icon = doc.createElementNS(SVG_NS, 'svg') as SVGSVGElement;
  icon.setAttribute('width', '18');
  icon.setAttribute('height', '18');
  icon.setAttribute('viewBox', '0 0 24 24');
  icon.setAttribute('fill', 'none');
  icon.setAttribute('stroke', 'var(--jini-warning)');
  icon.setAttribute('stroke-width', '2');
  icon.setAttribute('style', 'flex-shrink:0;margin-top:1px;');

  const rect = doc.createElementNS(SVG_NS, 'rect');
  rect.setAttribute('x', '3');
  rect.setAttribute('y', '3');
  rect.setAttribute('width', '18');
  rect.setAttribute('height', '18');
  rect.setAttribute('rx', '3');
  rect.setAttribute('stroke-dasharray', '4 3');

  const plus = doc.createElementNS(SVG_NS, 'path');
  plus.setAttribute('d', 'M8 12h8M12 8v8');

  icon.append(rect, plus);
  return icon;
}

/** Builds one card's full DOM: icon, kind heading, identity line, and a short explanatory note so an
 *  operator unfamiliar with the convention still understands what they're looking at (REQ from the
 *  owner's own ask: "make it very explicit as a placeholder"). Every piece of text goes through
 *  `textContent`, never string-concatenated markup, so a marker's own config values (which flow into
 *  `descriptor.identityLabel`) can never be interpreted as HTML. */
function buildPlaceholderCard(doc: Document, descriptor: CanvasEmbedPlaceholderDescriptor): HTMLElement {
  const card = doc.createElement(descriptor.inline ? 'span' : 'div');
  card.setAttribute(CARD_ROOT_MARKER, '');
  if (descriptor.presentation === 'runtime') card.setAttribute(CARD_RUNTIME_MARKER, '');
  card.setAttribute('style', CARD_STYLE);

  const text = doc.createElement('div');
  text.setAttribute(CARD_CHROME_MARKER, '');
  const heading = doc.createElement('div');
  heading.setAttribute('style', 'font-weight:600;');
  heading.textContent = descriptor.presentation === 'runtime' ? descriptor.kindLabel : `Placeholder — ${descriptor.kindLabel}`;
  const identity = doc.createElement('div');
  identity.setAttribute('style', 'opacity:.8;margin-top:2px;');
  identity.textContent = descriptor.identityLabel;
  const note = doc.createElement('div');
  note.setAttribute('style', 'opacity:.6;margin-top:4px;font-size:11px;');
  note.textContent = descriptor.guidanceLabel ?? 'Shown here for editing only — the real content renders on the published page.';
  text.append(heading, identity, note);

  const icon = buildPlaceholderIcon(doc);
  icon.setAttribute(CARD_CHROME_MARKER, '');
  card.append(icon, text);
  return card;
}

/**
 * Carries the marker's own RESOLVED `max-width`, if it has one, onto the card — a second,
 * complementary mechanism to the literal `style` attribute copy in `applyCanvasEmbedPlaceholders`,
 * and the one that actually matters against a real GrapesJS canvas.
 *
 * **Why a second mechanism is needed at all.** Confirmed live against a real canvas (not discoverable
 * in a plain-DOM unit test — GrapesJS itself hangs under jsdom, see this file's own testing note):
 * GrapesJS's parser does NOT leave an authored `style="max-width:600px"` as a literal attribute on the
 * live element it renders. It converts it into a scoped CSS rule instead (`CssComposer`, keyed by the
 * component's own generated id — `#iow1b { max-width: 600px }` in a canvas `<style>` tag), so
 * `el.getAttribute('style')` finds nothing to copy for every REAL marker despite working correctly
 * against a bare, non-GrapesJS element. `getComputedStyle` reads the RESOLVED value regardless of
 * which of those two forms produced it, so it is what actually reaches a real canvas.
 *
 * Scoped to `max-width` alone (not a wholesale computed-style copy) on purpose: copying every resolved
 * property would fight this card's own deliberately theme-independent, opaque chrome (font, colors,
 * spacing) with whatever the surrounding page happens to compute — the one thing worth inheriting is
 * the box-width constraint the "respect the author's own wrapper" requirement is actually about, not
 * the marker's full computed style.
 *
 * A no-op wherever `getComputedStyle` cannot resolve anything meaningful — no global (a non-browser
 * test environment), or a marker with no width constraint at all (`'none'`, the property's initial
 * value, or an empty string for a detached node with no attached window) — which is also exactly the
 * behavior every existing caller of this module had before this function existed.
 */
function applyResolvedMaxWidth(marker: Element, card: HTMLElement): void {
  const win = marker.ownerDocument.defaultView;
  if (!win) return;
  const maxWidth = win.getComputedStyle(marker).maxWidth;
  if (maxWidth && maxWidth !== 'none') card.style.setProperty('max-width', maxWidth);
}

/** Adds {@link OVERLAY_RULE} to `doc`'s `<head>` once. Idempotent. */
function ensureOverlayRule(doc: Document): void {
  if (doc.head.querySelector(`style[${OVERLAY_STYLE_MARKER}]`)) return;
  const style = doc.createElement('style');
  style.setAttribute(OVERLAY_STYLE_MARKER, '');
  style.textContent = OVERLAY_RULE;
  doc.head.appendChild(style);
}

/**
 * Removes every card whose marker is no longer inside it. The card lives only in the canvas DOM, so the
 * editor knows nothing about it: deleting the embed removes just the marker element (leaving a ghost
 * card that still reads "Placeholder"), and moving it takes the marker out (leaving an empty card
 * behind). The next pass of `applyCanvasEmbedPlaceholders` then wraps the moved marker again.
 */
function removeStaleCards(body: HTMLElement): void {
  for (const card of Array.from(body.querySelectorAll(`[${CARD_ROOT_MARKER}]`))) {
    const hasMarker = Array.from(card.children).some((child) => !child.hasAttribute(CARD_CHROME_MARKER));
    if (!hasMarker) card.remove();
  }
}

/**
 * Scans every element under `body` once and, for each one `describe` recognizes (returns a descriptor
 * for), replaces its visible slot with an explicit placeholder card — see this file's header for the
 * export-safety argument and for why the marker is wrapped rather than written into.
 *
 * @param body - The canvas iframe's `<body>` element (`editor.Canvas.getBody()`), already populated by
 *   GrapesJS's initial component render — same input `applyCanvasContentWrapper` takes, and safe to
 *   call after that function has already restructured `body`'s top level, since this walks the full
 *   subtree regardless of how deep any one marker now sits.
 * @param describe - Host-supplied recognizer/labeler. Returning `undefined` means "not a marker this
 *   host owns" — the element is left completely untouched, no wrapping, no traversal into its own
 *   children skipped either (a marker's own children, if any, are themselves ordinary elements this
 *   function still visits, since `Array.from(body.querySelectorAll('*'))` is a flat snapshot of every
 *   descendant, not a tree walk this function short-circuits).
 * @complexity O(n) over the number of elements under `body` for the scan, plus O(1) per matched marker
 *   for its card's fixed-size DOM (icon plus three text nodes) — independent of document size.
 */
export function applyCanvasEmbedPlaceholders(
  body: HTMLElement,
  describe: (el: Element) => CanvasEmbedPlaceholderDescriptor | undefined
): void {
  const doc = body.ownerDocument;
  removeStaleCards(body);
  // Snapshotted into an array before any mutation starts: this function inserts new ancestors as it
  // goes, and a live `querySelectorAll` result must never be iterated while the tree it was taken over
  // is being restructured underneath it — same discipline `applyCanvasContentWrapper` applies to
  // `body.childNodes` for the same reason.
  const candidates = Array.from(body.querySelectorAll('*'));

  for (const el of candidates) {
    // Skip existing embed cards and all chrome before calling the host. Runtime cards still
    // re-describe their direct marker so theme changes can refresh its bounded footprint.
    const existingCard = el.closest(`[${CARD_ROOT_MARKER}]`) as HTMLElement | null;
    if (existingCard && !canRefreshRuntimeCard({ el, card: existingCard }, {})) continue;
    const descriptor = describe(el);
    if (!descriptor) continue;
    updatePlaceholder({ el, doc, descriptor, existingCard }, {});
  }
}

function canRefreshRuntimeCard({ el, card }: { el: Element; card: HTMLElement }, _options: object = {}): boolean {
  return card.hasAttribute(CARD_RUNTIME_MARKER) && el.parentElement === card && !el.hasAttribute(CARD_CHROME_MARKER);
}

function updatePlaceholder(
  { el, doc, descriptor, existingCard }: { el: Element; doc: Document; descriptor: CanvasEmbedPlaceholderDescriptor; existingCard: HTMLElement | null },
  _options: object = {},
): void {
  if (existingCard) {
    if (descriptor.presentation === 'runtime') applyRuntimeFootprint(el, existingCard, descriptor);
    return;
  }
  const parent = el.parentNode;
  if (!parent) return; // Unreachable for a live `body` descendant; defensive only.

  const card = buildPlaceholderCard(doc, descriptor);
  // Respect the author's own box (e.g. `style="max-width:600px"` on the marker) by carrying its
  // inline style onto the card BEFORE the card's own chrome declarations, so same-named properties
  // in `CARD_STYLE` win on the cascade's normal "last declaration wins" rule while anything the
  // author set that `CARD_STYLE` doesn't touch (like `max-width`) still applies unopposed. Guarded
  // on presence so a marker with no `style` attribute at all is a no-op, not a leading `;`.
  const authoredStyle = el.getAttribute('style');
  if (authoredStyle && descriptor.presentation !== 'runtime') card.setAttribute('style', `${authoredStyle};${card.getAttribute('style')}`);
  applyResolvedMaxWidth(el, card);
  if (descriptor.presentation === 'runtime') applyRuntimeFootprint(el, card, descriptor);

  parent.insertBefore(card, el);
  card.appendChild(el); // Moves the SAME node (auto-detaches from `parent`) — never cloned.
  ensureOverlayRule(doc);
}

/** Geometry belongs to canvas DOM only; arbitrary transforms/min-height cannot defeat the clamp. */
function applyRuntimeFootprint(el: Element, card: HTMLElement, descriptor: CanvasEmbedPlaceholderDescriptor): void {
  const resolved = measureAuthoredHeight({ el }, {});
  const native = el.getAttribute('height');
  const declared = descriptor.declaredHeight ?? (resolved?.endsWith('px') ? Number.parseFloat(resolved) : undefined);
  card.style.height = `${editorBlockHeight({ declaredHeight: declared, nativeHeight: native ? Number(native) : undefined, inline: descriptor.inline }, {})}px`;
  card.style.minHeight = '0';
  card.style.maxHeight = descriptor.inline ? '160px' : '960px';
  card.style.overflow = 'hidden';
  if (descriptor.inline) { card.style.display = 'inline-flex'; card.style.verticalAlign = 'middle'; }
  // The marker is the selectable hit surface, never an authored layout/transform or media view.
  (el as HTMLElement).style.setProperty('transform', 'none', 'important');
  (el as HTMLElement).style.setProperty('overflow', 'hidden', 'important');
}

function measureAuthoredHeight({ el }: { el: Element }, _options: object = {}): string | undefined {
  // Re-measure the authored shell after theme links settle, without our selection overlay's
  // !important auto-height masking its declarations. No component/model styles are changed.
  const overlay = el.ownerDocument.head.querySelector<HTMLStyleElement>(`style[${OVERLAY_STYLE_MARKER}]`);
  const sheet = overlay?.sheet;
  const wasDisabled = sheet?.disabled;
  let resolved: string | undefined;
  try {
    if (sheet) sheet.disabled = true;
    resolved = el.ownerDocument.defaultView?.getComputedStyle(el).height;
  } finally {
    if (sheet) sheet.disabled = wasDisabled ?? false;
  }
  return resolved;
}

import { trimTrailingChars } from '../../utils/trim-chars.js';
/**
 * `editor.getCss()` always returns single-line, semicolon-packed CSS — confirmed directly in
 * GrapesJS's own bundled source (`CssRule.prototype.toCSS`/`getDeclaration`): there is no
 * formatting/indent option anywhere in that path, minification is unconditional. Left as-is, a host
 * reopening an HTML-source view after an Interactive-tab edit would find hand-authored, readable CSS
 * replaced by one dense blob. A real CSS parser (e.g. `postcss` + a printer, or a browser-bundle
 * build of `prettier`) is unwarranted weight for a formatting-only pass over CSS this function's own
 * caller already generated — the input is always GrapesJS's own regular, predictable serialization,
 * never arbitrary untrusted CSS, so a small tokenizer is sufficient and safe here specifically (it
 * would not be a safe substitute for a real parser on attacker-controlled input).
 *
 * Tracks brace depth (indentation), quote state (so `;`/`{`/`}` inside a string literal, e.g.
 * `content: "a;b"`, are never mistaken for structure), and paren depth (so the same characters
 * inside a function value are left alone too — the concrete case that broke without this: a
 * `url(data:image/svg+xml;base64,...)` value's own semicolon, which naive brace/semicolon splitting
 * mistakes for a declaration terminator and corrupts the value).
 *
 * @complexity O(n) single pass over the CSS string, O(1) additional space beyond the output buffer.
 * @overallScore 100
 */
export function prettifyCss(css: string): string {
  const INDENT = '  ';
  let out = '';
  let depth = 0;
  let parenDepth = 0;
  let quote: '"' | "'" | null = null;
  let atDeclStart = false;
  let i = 0;
  const n = css.length;

  const skipWhitespace = (_input: object, _options: object = {}): void => {
    while (i < n && /\s/.test(css[i]!)) i++;
  };

  const consumeValue = ({ ch }: { ch: string }, _options: object = {}): boolean => {
    if (quote) {
      out += ch;
      if (ch === '\\' && i + 1 < n) {
        out += css[i + 1];
        i += 2;
        return true;
      }
      if (ch === quote) quote = null;
      i++;
      return true;
    }

    if (ch === '"' || ch === "'") {
      quote = ch;
      out += ch;
      i++;
      return true;
    }

    if (ch === '(') {
      parenDepth++;
      out += ch;
      i++;
      return true;
    }
    if (ch === ')') {
      parenDepth = Math.max(0, parenDepth - 1);
      out += ch;
      i++;
      return true;
    }

    return false;
  };

  const openRule = (_input: object, _options: object = {}): boolean => {
    out = trimTrailingChars(out, ' \t');
    out += ' {';
    depth++;
    atDeclStart = true;
    i++;
    skipWhitespace({}, {});
    if (css[i] !== '}') out += '\n' + INDENT.repeat(depth);
    return true;
  };

  const closeRule = (_input: object, _options: object = {}): boolean => {
    depth = Math.max(0, depth - 1);
    out = trimTrailingChars(out, ' \t');
    // A `}` immediately after `{` (an empty rule) needs no newline before it; otherwise close on
    // its own indented line.
    if (!out.endsWith('{')) out += '\n' + INDENT.repeat(depth);
    out += '}';
    atDeclStart = false;
    i++;
    skipWhitespace({}, {});
    const nextCh = css[i];
    // A following `}` (closing a parent at-rule) manages its own leading newline via the same
    // trailing-space trim above — adding one here too would double up into a stray blank line.
    if (nextCh !== undefined && nextCh !== '}') {
      out += depth === 0 ? '\n\n' : '\n' + INDENT.repeat(depth);
    }
    return true;
  };

  const endDeclaration = (_input: object, _options: object = {}): boolean => {
    out += ';';
    i++;
    skipWhitespace({}, {});
    const nextCh = css[i];
    if (nextCh !== '}' && nextCh !== undefined) {
      out += '\n' + INDENT.repeat(depth);
      atDeclStart = true;
    }
    return true;
  };

  // Only the FIRST colon of a declaration (the property/value separator) gets a space after it —
  // a selector's own colon (`.gm-btn:hover`, matched at `depth === 0`, before any `{`) is left
  // untouched, and only `atDeclStart` (cleared the moment this fires) keeps a later colon inside
  // the same value (there are none in practice here, but the guard costs nothing) from being
  // treated as another property separator.
  const separateValue = (_input: object, _options: object = {}): boolean => {
    out += ': ';
    atDeclStart = false;
    i++;
    while (i < n && css[i] === ' ') i++;
    return true;
  };

  const consumeStructure = ({ ch }: { ch: string }, _options: object = {}): boolean => {
    if (parenDepth !== 0) return false;
    switch (ch) {
      case '{': return openRule({}, {});
      case '}': return closeRule({}, {});
      case ';': return endDeclaration({}, {});
      case ':': return depth > 0 && atDeclStart ? separateValue({}, {}) : false;
      default: return false;
    }
  };

  while (i < n) {
    const ch = css[i]!;
    if (consumeValue({ ch }, {}) || consumeStructure({ ch }, {})) continue;
    if (/\s/.test(ch)) {
      out += ' ';
      i++;
      skipWhitespace({}, {});
      continue;
    }

    out += ch;
    i++;
  }

  return out.trim();
}

import type { CanvasEmbedPlaceholderDescriptor } from './canvas-embed-placeholders.js';
import { sourceElementAttributeView } from './dom.js';
import { indexSourceElements, type ElementOuterRange, type SourceElement } from './source-splice.js';

export type EditorBlockReason = 'kuinetic' | 'canvas' | 'autoplay-video' | 'scripted' | 'embed';
export interface EditorBlock extends ElementOuterRange {
  readonly tagName: string;
  readonly id?: string | undefined;
  readonly reason: EditorBlockReason;
  readonly descriptor: CanvasEmbedPlaceholderDescriptor;
  readonly element: SourceElement;
}
export interface EditorBlockOptions {
  /** Attribute-only compatibility view, matching the existing DOM/parsed-node host seam. */
  describeHostElement?: ((el: Element) => CanvasEmbedPlaceholderDescriptor | undefined) | undefined;
  isProtectedElement?: ((el: Element) => boolean) | undefined;
  translate?: ((key: string) => string) | undefined;
}
export interface EditorHtmlTarget {
  /** Zero-based occurrence among source elements sharing tagName and (when supplied) id. */
  occurrenceIndex: number;
  tagName: string;
  id?: string;
}
export type RequestEditHtml = (target: EditorHtmlTarget, options: object) => void | Promise<void>;

const LABELS: Record<EditorBlockReason, string> = {
  kuinetic: 'Animation · Kuinetic', canvas: 'Canvas', 'autoplay-video': 'Autoplay video',
  scripted: 'Scripted section', embed: 'Content',
};
const INLINE_TAGS: ReadonlySet<string> = new Set(['span', 'a', 'b', 'i', 'em', 'strong', 'small', 'mark', 's', 'u', 'sub', 'sup']);
const UNSUPPORTED_CONTEXTS: ReadonlySet<string> = new Set(['table', 'thead', 'tbody', 'tfoot', 'tr', 'td', 'th', 'select', 'option', 'svg', 'math', 'template']);
// A Kuinetic entrance/decoration effect (fade-up, text-reveal, split-chars, count-up…)
// only animates authored text the canvas never runs, so locking it hid Landing's headline, ledes and
// buttons behind grey cards. Such elements stay editable; their data-kui attribute round-trips like
// any other, including stagger lists and decorated containers. Layout/runtime effects (ring, pin…)
// stay locked; unknown names retain the structural rule, and data-editor="block" still forces a lock.
// Names follow Kuinetic's core entrance, text, numbers, media and interaction catalogs; the bare
// fade/reveal/text-reveal/glow spellings are also part of the editor's authored-effect contract.
const EDITABLE_EFFECTS: ReadonlySet<string> = new Set([
  'fade', 'fade-in', 'fade-up', 'fade-down', 'fade-left', 'fade-right', 'fade-blur-in', 'fade-blur-up',
  'slide-up', 'slide-down', 'slide-left', 'slide-right', 'slide-inline-start', 'slide-inline-end', 'slide-block-start', 'slide-block-end',
  'zoom-in', 'zoom-in-up', 'zoom-in-down', 'pop-in', 'flip-in-x', 'flip-in-y', 'rotate-in', 'rotate-in-left', 'rotate-in-right',
  'roll-in', 'swing-in', 'blur-in', 'bounce-in', 'bounce-in-up', 'bounce-in-down', 'back-in-up', 'back-in-down', 'reveal', 'reveal-once',
  'text-reveal', 'text-reveal-up', 'text-reveal-down', 'text-reveal-mask', 'split-chars', 'split-words', 'split-lines',
  'count-up', 'count-down', 'count-currency', 'count-percent', 'count-compact', 'odometer-roll',
  'wipe-up', 'wipe-down', 'wipe-left', 'wipe-right', 'wipe-circle', 'wipe-diagonal', 'mask-reveal', 'curtain-reveal', 'blur-up',
  'magnetic', 'glow', 'glow-pulse', 'border-glow', 'border-draw', 'beam-border', 'beam-border-auto', 'proximity-glow',
  'shine-sweep', 'lift', 'lift-shadow', 'pop', 'underline-slide', 'underline-center', 'icon-wiggle', 'icon-spin', 'icon-bounce',
]);
const RUNTIME_EFFECTS: ReadonlySet<string> = new Set([
  'ring', 'carousel', 'deck', 'slides', 'pin', 'pin-section', 'pin-until', 'pin-spacer', 'marquee', 'marquee-scroll-linked', 'accordion', 'tabs',
  'carousel-3d', 'carousel-3d-high', 'carousel-3d-low', 'carousel-3d-inside', 'carousel-orbit', 'carousel-stack',
  'carousel-fade', 'carousel-slide', 'slideshow', 'video-hero-slideshow', 'step-progress', 'stacking-cards', 'horizontal-scroll',
  'flip-reorder', 'flip-filter', 'flip-sort', 'flip-shuffle', 'grid-to-list', 'masonry-reflow', 'expand-to-modal', 'accordion-height',
  'card-flip-x', 'card-flip-y', 'flip-card', 'scroll-snap-x', 'scroll-snap-y',
]);
const TEXT_EFFECT_TAGS: ReadonlySet<string> = new Set(['h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'li', 'dt', 'dd', 'blockquote', 'figcaption', 'label']);
const PHRASING_TAGS: ReadonlySet<string> = new Set([...INLINE_TAGS, 'abbr', 'br', 'cite', 'code', 'data', 'dfn', 'img', 'kbd', 'q', 'samp', 'time', 'var', 'wbr']);
const isPhrasingOnly = (el: SourceElement): boolean => el.children.every(child => PHRASING_TAGS.has(child.tagName) && isPhrasingOnly(child));
const isEditableEffect = (el: SourceElement): boolean => {
  if (el.attributes['data-editor'] === 'block') return false;
  // Quoted selectors and timing/color functions may contain commas, which are not effect separators.
  const effects = (el.attributes['data-kui'] ?? '').replace(/"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\([^)]*\)/g, '')
    .split(',').map(segment => segment.trim().split(/\s+/)[0]!).filter(Boolean);
  if (effects.some(effect => RUNTIME_EFFECTS.has(effect))) return false;
  if (effects.length > 0 && effects.every(effect => EDITABLE_EFFECTS.has(effect))) return true;
  if (el.attributes['data-kui'] === undefined && 'data-kui-stagger' in el.attributes) return true;
  return (TEXT_EFFECT_TAGS.has(el.tagName) || PHRASING_TAGS.has(el.tagName)) && isPhrasingOnly(el);
};

function runtimeBlockReason({ el, isLive }: { el: SourceElement; isLive: boolean }, _options: object = {}): EditorBlockReason | undefined {
  if (isLive) return undefined;
  if (Object.keys(el.attributes).some(name => name.startsWith('data-kui')) && !isEditableEffect(el)) return 'kuinetic';
  if (el.tagName === 'canvas') return 'canvas';
  if (el.tagName === 'video' && 'autoplay' in el.attributes) return 'autoplay-video';
  if (el.attributes['data-editor'] === 'block') return 'scripted';
  return undefined;
}

function describeBlock(
  { el, isLive, hasLiveDescendants }: { el: SourceElement; isLive: boolean; hasLiveDescendants: boolean },
  options: EditorBlockOptions = {},
): { reason: EditorBlockReason | undefined; host: CanvasEmbedPlaceholderDescriptor | undefined } {
  const view = sourceElementAttributeView(el, {});
  const host = options.describeHostElement?.(view);
  const embed = !!host || !!options.isProtectedElement?.(view);
  let reason = runtimeBlockReason({ el, isLive }, {});
  if (reason && hasLiveDescendants) reason = undefined;
  if (!reason && embed) reason = 'embed';
  return { reason, host };
}

/** `.first.second` from an element's class attribute (first two classes), or undefined when it has none. */
function classIdentity(className: string | undefined): string | undefined {
  if (!className) return undefined;
  return `.${className.trim().split(/\s+/).slice(0, 2).join('.')}`;
}

function createEditorBlock(
  { el, reason, host }: { el: SourceElement; reason: EditorBlockReason; host: CanvasEmbedPlaceholderDescriptor | undefined },
  options: EditorBlockOptions = {},
): EditorBlock {
  const t = options.translate ?? ((key: string) => key);
  const id = el.attributes.id;
  const identity = id ? `#${id}` : classIdentity(el.attributes.class) ?? el.tagName;
  return {
    ...el.outerRange!, tagName: el.tagName, ...(id ? { id } : {}), reason, element: el,
    descriptor: reason === 'embed' && host ? host : {
      kindLabel: t(LABELS[reason]), identityLabel: identity.slice(0, 64), presentation: reason === 'embed' ? 'embed' : 'runtime',
      guidanceLabel: t('Locked · Edit in HTML · Preview plays it'), inline: INLINE_TAGS.has(el.tagName),
    },
  };
}

/** Outermost disjoint roots; explicit live islands veto aggregation but never host embed safety. */
export function detectEditorBlocks({ html }: { html: string }, options: EditorBlockOptions = {}):
  { ok: true; blocks: EditorBlock[]; elements: SourceElement[] } | { ok: false; problem: string } {
  const elements = indexSourceElements({ html }, {});
  const blocks: EditorBlock[] = [];
  const liveIslands = new Map<SourceElement, boolean>();
  const annotate = (el: SourceElement): boolean => {
    const descendants = el.children.map(annotate).some(Boolean);
    liveIslands.set(el, descendants);
    return el.attributes['data-editor'] === 'live' || descendants;
  };
  elements.forEach(annotate);
  let unsupported = false;
  const walk = ({ el, live, invalidAncestor }: { el: SourceElement; live: boolean; invalidAncestor: boolean }, _options: object = {}) => {
    const mode = el.attributes['data-editor'];
    const isLive = mode === 'live' || (mode !== 'block' && live);
    const { reason, host } = describeBlock({ el, isLive, hasLiveDescendants: !!liveIslands.get(el) }, options);
    const invalid = invalidAncestor || !el.outerRange || UNSUPPORTED_CONTEXTS.has(el.tagName);
    if (reason) {
      if (invalid || !el.sourceSupported) { unsupported = true; return; }
      blocks.push(createEditorBlock({ el, reason, host }, options));
      return;
    }
    el.children.forEach(child => walk({ el: child, live: isLive, invalidAncestor: invalid }, {}));
  };
  elements.forEach(el => walk({ el, live: false, invalidAncestor: false }, {}));
  return unsupported || (blocks.length > 0 && elements.some(el => !el.sourceSupported))
    ? { ok: false, problem: "Can't edit this source visually. Use HTML." } : { ok: true, blocks, elements };
}

export interface RawSourceInstance extends ElementOuterRange {
  readonly originalHtml: string;
  readonly openingTag: string;
  readonly tagName: string;
  readonly id?: string | undefined;
  readonly nonvisual: boolean;
  readonly descriptor?: CanvasEmbedPlaceholderDescriptor;
}
export interface PreparedEditorSource {
  readonly ok: true;
  readonly html: string;
  readonly markerAttribute: string;
  readonly instances: readonly RawSourceInstance[];
  readonly canvasCss: string;
}
export type EditorSourcePlan = PreparedEditorSource | { readonly ok: false; readonly html: string; readonly problem: string };

const escapeAttribute = (value: string) => value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');

/**
 * Capture before GrapesJS parses. Only a mount-private lookup token reaches the parser; authored
 * source stays in model metadata. Style/script atoms use inert spans, never executable source tags.
 */
export function prepareEditorSource({ html }: { html: string }, options: EditorBlockOptions = {}): EditorSourcePlan {
  const detected = detectEditorBlocks({ html }, options);
  if (!detected.ok) return { ...detected, html };
  const instances: RawSourceInstance[] = detected.blocks.map(block => ({
    ...block, originalHtml: html.slice(block.outerStart, block.outerEnd),
    openingTag: html.slice(block.outerStart, block.openingEnd), nonvisual: false,
  }));
  const blocked = new Set(detected.blocks.map(block => block.element));
  const css: string[] = [];
  let unsupported = false;
  const walk = (el: SourceElement, enclosed: boolean, invalidAncestor: boolean) => {
    const inside = enclosed || blocked.has(el);
    const invalid = invalidAncestor || !el.outerRange;
    if (el.tagName === 'style' && el.outerRange) {
      const original = html.slice(el.outerRange.outerStart, el.outerRange.outerEnd);
      const closingLength = original.length - (original.toLowerCase().lastIndexOf('</style'));
      css.push(html.slice(el.outerRange.openingEnd, el.outerRange.outerEnd - closingLength));
    }
    if (!inside && (el.tagName === 'style' || el.tagName === 'script')) {
      if (invalid) unsupported = true;
      else instances.push({ ...el.outerRange!, originalHtml: html.slice(el.outerRange!.outerStart, el.outerRange!.outerEnd),
        openingTag: html.slice(el.outerRange!.outerStart, el.outerRange!.openingEnd), tagName: el.tagName, nonvisual: true });
    }
    el.children.forEach(child => walk(child, inside, invalid));
  };
  detected.elements.forEach(el => walk(el, false, false));
  if (unsupported || (instances.length > 0 && detected.elements.some(el => !el.sourceSupported))) {
    return { ok: false, html, problem: "Can't edit this source visually. Use HTML." };
  }
  instances.sort((a, b) => a.outerStart - b.outerStart);
  let markerAttribute = 'data-jini-raw-source-0';
  let namespace = 0;
  while (html.toLowerCase().includes(markerAttribute)) {
    namespace += 1;
    markerAttribute = `data-jini-raw-source-${namespace}`;
  }
  const prepared = renderSourceShells({ html, instances, blocks: detected.blocks, markerAttribute }, {});
  return { ok: true, html: prepared, markerAttribute, instances, canvasCss: css.join('\n') };
}

function renderSourceShells(
  { html, instances, blocks, markerAttribute }: { html: string; instances: readonly RawSourceInstance[]; blocks: readonly EditorBlock[]; markerAttribute: string },
  _options: object = {},
): string {
  let prepared = html;
  const roots = new Map(blocks.map(block => [block.outerStart, block]));
  for (let i = instances.length - 1; i >= 0; i--) {
    const instance = instances[i]!;
    const block = roots.get(instance.outerStart);
    const attrs = block?.element.attributes ?? {};
    // Data selectors may declare the root's geometry. They are inert without page scripts; keep
    // them alongside box attributes, while resource URLs, event handlers, autoplay and GrapesJS
    // parser directives stay absent. Authored data-gjs flags must not override the protected type.
    const layout = Object.keys(attrs).filter(name => ['id', 'class', 'style', 'height', 'width'].includes(name)
      || (name.startsWith('data-') && !name.startsWith('data-gjs-')))
      .map(name => ` ${name}="${escapeAttribute(attrs[name]!)}"`).join('');
    const tag = instance.nonvisual ? 'span' : instance.tagName;
    const voidTag = instance.openingEnd === instance.outerEnd;
    const closingTag = voidTag && !instance.nonvisual ? '' : `</${tag}>`;
    const shell = `<${tag} ${markerAttribute}="${i}"${layout}>${closingTag}`;
    prepared = prepared.slice(0, instance.outerStart) + shell + prepared.slice(instance.outerEnd);
  }
  return prepared;
}

/** Exact authored opening tag and its source offsets; no regex-based HTML parsing or id guessing. */
export function findEditorBlockOpening(
  { html, target }: { html: string; target: EditorHtmlTarget }, _options: object = {},
): { start: number; end: number; openingTag: string } | undefined {
  let occurrence = 0;
  let result: { start: number; end: number; openingTag: string } | undefined;
  const walk = (el: SourceElement) => {
    if (el.tagName === target.tagName.toLowerCase() && (target.id === undefined || el.attributes.id === target.id)) {
      const index = occurrence;
      occurrence += 1;
      if (index === target.occurrenceIndex && el.outerRange) {
        const { outerStart: start, openingEnd: end } = el.outerRange;
        result = { start, end, openingTag: html.slice(start, end) };
      }
    }
    el.children.forEach(walk);
  };
  indexSourceElements({ html }, {}).forEach(walk);
  return result;
}

import { parseFragment } from 'parse5';
import type { DefaultTreeAdapterMap } from 'parse5';

/**
 * @file Bug C's root cause (see this repo's `pages-redo` plan, "Bug C: one text edit rewrites the
 * whole page's HTML") is that `serializeEditorContent` rebuilds the **whole document** from
 * GrapesJS's own component model on every edit, so anything the model doesn't preserve
 * byte-for-byte — HTML entities, attribute quote style, a leading `<style>` block's formatting —
 * is silently lost outside the edited element too, not just inside it.
 *
 * This module is the lossless-splice primitive that fixes that: parse the **original** source
 * once with parse5 to find exactly where each element's inner content starts and ends
 * (`indexElementSourceRanges`), then replace only those bytes for the one element that actually
 * changed (`spliceElementInner`) — every other byte of the original string, including its
 * whitespace, quoting, and entities, passes through untouched because it is never re-serialized.
 *
 * Deliberately product-neutral and DOM-free: it knows nothing about GrapesJS, "protected"
 * elements, or embed markers. The caller (the `useInteractiveHtmlEditor` hook, wired in a later
 * slice) is responsible for deciding which element changed and supplying its path and tag name.
 *
 * `style` and `script` elements are skipped entirely, both from indexing and from path
 * numbering — GrapesJS removes both from its own component tree (moving `<style>` into its
 * `CssComposer` and dropping `<script>` unless `allowScripts` is set), so a path computed from
 * GrapesJS's tree would never account for them either. Skipping them here, rather than indexing
 * and then filtering, keeps this module's one path numbering scheme the single source of truth
 * that both sides (this indexer and whatever numbers GrapesJS's tree) must agree on.
 */

type Parse5Node = DefaultTreeAdapterMap['node'];
type Parse5ParentNode = DefaultTreeAdapterMap['parentNode'];
type Parse5Element = DefaultTreeAdapterMap['element'];

/** Tags GrapesJS never represents as ordinary tree components — never indexed, never a path slot. */
const UNINDEXED_TAGS = new Set(['style', 'script']);

/**
 * An element's position among its ancestors' **element-only** children, ignoring text nodes,
 * comments, and `style`/`script` elements at every level. `[0, 1]` means "the second element
 * child of the first element child of the fragment root".
 */
export type ElementPath = readonly number[];

/** One element's source byte range, as located in the original HTML string that was indexed. */
export interface ElementSourceRange {
  /** Byte offset of the first character of the element's inner content (just after `startTag`). */
  readonly start: number;
  /** Byte offset just past the element's inner content (just before `endTag`, if any). */
  readonly end: number;
  /** The element's tag name, so a caller can detect drift between what it expects and what parsed. */
  readonly tagName: string;
}

/** Canonical string key for a path, for use as a `Map` key (`Map<pathKey(path), ...>`). */
export function pathKey(path: ElementPath): string {
  return path.join('.');
}

function isElement(node: Parse5Node): node is Parse5Element {
  return 'tagName' in node;
}

function hasChildNodes(node: Parse5Node): node is Parse5ParentNode {
  return 'childNodes' in node;
}

function recordInnerRange(
  { node, currentPath, out }: { node: Parse5Element; currentPath: ElementPath; out: Map<string, ElementSourceRange> },
  _options: object = {},
): void {
  const location = node.sourceCodeLocation;
  // parse5 attaches a location only to elements created from a start-tag token, so a located
  // element always has `startTag` (implied elements — a `tbody`, a `</p>`- or `</br>`-created
  // element — carry no location at all and are skipped). Requiring `startTag` here replaces the old
  // `: location.endOffset` fallback, which no parsed element could reach.
  if (location?.startTag) {
    // Void elements (`<br>`, `<img>`) have no `endTag` and no inner content: their range is
    // empty (`start === end`), anchored at the end of the start tag.
    const start = location.startTag.endOffset;
    const end = location.endTag ? location.endTag.startOffset : start;
    out.set(pathKey(currentPath), { start, end, tagName: node.tagName });
  }
}

/**
 * Walks one level of element-only children (recursing into each), assigning each a path and
 * recording its source range. `style`/`script` children are skipped without consuming a path slot.
 *
 * @complexity O(n) over the fragment's total node count — each node is visited exactly once.
 */
function indexChildren(children: readonly Parse5Node[], parentPath: ElementPath, out: Map<string, ElementSourceRange>): void {
  let elementIndex = 0;
  for (const node of children) {
    if (!isElement(node)) continue;
    if (UNINDEXED_TAGS.has(node.tagName)) continue;

    const currentPath = [...parentPath, elementIndex];
    recordInnerRange({ node, currentPath, out }, {});

    if (hasChildNodes(node)) indexChildren(node.childNodes, currentPath, out);
    elementIndex++;
  }
}

/**
 * Parses `html` once and indexes every reachable element's inner-content source range by its
 * element-only child path (see `ElementPath`). The same `html` string must be re-indexed after
 * any splice — a returned index is only valid against the exact string it was built from, since
 * every offset is a byte position into that specific string.
 *
 * @param html Source HTML to index. Parsed as a fragment (`parse5.parseFragment`), so a leading
 *   `<html>`/`<body>` wrapper is not assumed and is not specially handled here.
 * @returns A map from `pathKey(path)` to that element's source range. `style`/`script` elements,
 *   comments, and text nodes are never present as entries or path slots.
 * @complexity O(n) in the size of `html` (parse5's own parse cost dominates; indexing itself is
 *   a single linear tree walk).
 * @overallScore 100
 */
export function indexElementSourceRanges(html: string): Map<string, ElementSourceRange> {
  const fragment = parseFragment(html, { sourceCodeLocationInfo: true });
  const index = new Map<string, ElementSourceRange>();
  indexChildren(fragment.childNodes, [], index);
  return index;
}

/**
 * Replaces only the inner-content bytes of the element at `path` with `newInner`, leaving every
 * other byte of `html` — including whitespace, attribute quoting, and entities — untouched.
 *
 * Returns `null`, never a wrong splice, when the address cannot be trusted: `path` does not
 * resolve to any indexed element (the document's shape changed since the path was computed), or
 * it resolves to an element whose tag does not match `expectedTagName` (the caller's own model
 * and the source string have drifted apart). Callers must treat `null` as a signal to fall back
 * to a full re-serialization — never retry with a guessed range.
 *
 * @param html Original source string (not a previously-spliced one — see this module's file
 *   header on re-splicing from the original on every edit rather than compounding offsets).
 * @param path Element-only child path of the element to edit, as produced by
 *   `indexElementSourceRanges`.
 * @param expectedTagName Tag name the caller believes lives at `path` (e.g. the GrapesJS
 *   component's own tag). A mismatch is treated the same as an unresolved path.
 * @param newInner Replacement inner HTML for the addressed element.
 * @returns The spliced string, or `null` if `path` could not be located or its tag disagreed.
 * @complexity O(n) — dominated by re-indexing `html` (see `indexElementSourceRanges`); the splice
 *   itself is two string slices and a concatenation.
 * @overallScore 100
 */
export function spliceElementInner(html: string, path: ElementPath, expectedTagName: string, newInner: string): string | null {
  const range = indexElementSourceRanges(html).get(pathKey(path));
  if (!range || range.tagName !== expectedTagName) return null;
  return html.slice(0, range.start) + newInner + html.slice(range.end);
}

const VOID_TAGS: ReadonlySet<string> = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr']);

/** Verified offsets are JS string indexes (UTF-16), suitable for slice and textarea selection. */
export interface ElementOuterRange {
  readonly outerStart: number;
  readonly outerEnd: number;
  readonly openingEnd: number;
}

/** Source tree shared by block detection and preparation; raw atoms never consume a splice slot. */
export interface SourceElement {
  readonly tagName: string;
  readonly attributes: Readonly<Record<string, string>>;
  readonly path: ElementPath | null;
  readonly outerRange: ElementOuterRange | null;
  readonly sourceSupported: boolean;
  readonly children: readonly SourceElement[];
}

function sourceOuterEnd({ node, html }: { node: Parse5Element; html: string }, _options: object = {}): number | undefined {
  const loc = node.sourceCodeLocation;
  const start = loc?.startTag;
  const foreignSelfClosing = node.namespaceURI !== 'http://www.w3.org/1999/xhtml' && !!start
    && html.slice(start.startOffset, start.endOffset).endsWith('/>');
  if (VOID_TAGS.has(node.tagName) || foreignSelfClosing) return start?.endOffset;
  return loc?.endTag?.endOffset;
}

function sourceOuterRange(
  { node, html, parentStart, parentEnd }: { node: Parse5Element; html: string; parentStart: number; parentEnd: number },
  _options: object = {},
): ElementOuterRange | null {
  const start = node.sourceCodeLocation?.startTag;
  const outerEnd = sourceOuterEnd({ node, html }, {});
  const boundsValid = !!start && outerEnd !== undefined && start.startOffset >= parentStart && outerEnd <= parentEnd;
  // Template content is a separate fragment; it has no ordinary component path/shell here.
  if (!boundsValid || node.tagName === 'template') return null;
  return { outerStart: start!.startOffset, outerEnd: outerEnd!, openingEnd: start!.endOffset };
}

function invalidateOverlappingSiblings(
  { elements }: { elements: (Omit<SourceElement, 'sourceSupported'> & { sourceSupported: boolean })[] },
  _options: object = {},
): void {
  // Foster parenting can move a valid-looking node ahead of a source-earlier table. Neither
  // sibling can be trusted as a model-addressable source owner in that recovered ordering.
  for (let i = 1; i < elements.length; i++) {
    const previous = elements[i - 1]!;
    const current = elements[i]!;
    if (previous.outerRange && current.outerRange && previous.outerRange.outerEnd > current.outerRange.outerStart) {
      previous.sourceSupported = current.sourceSupported = false;
    }
  }
}

/**
 * Extends the inner-splice index without changing its published range shape. Missing end tags,
 * implicit nodes and reordered/foster-parented children cannot establish an opaque source owner.
 * Validation is linear in source nodes; ranges are checked against their immediate source parent.
 */
export function indexSourceElements({ html }: { html: string }, _options: object = {}): SourceElement[] {
  const fragment = parseFragment(html, { sourceCodeLocationInfo: true });
  const walk = ({ nodes, parentPath, parentStart, parentEnd }: { nodes: readonly Parse5Node[]; parentPath: ElementPath; parentStart: number; parentEnd: number }, _options: object = {}): SourceElement[] => {
    let slot = 0;
    const elements = nodes.filter(isElement).map(node => {
      const atom = UNINDEXED_TAGS.has(node.tagName);
      let path: ElementPath | null = null;
      if (!atom) {
        path = [...parentPath, slot];
        slot += 1;
      }
      const loc = node.sourceCodeLocation;
      const children = walk({ nodes: node.childNodes, parentPath: path ?? parentPath, parentStart: loc?.startTag?.endOffset ?? parentStart, parentEnd: loc?.endTag?.startOffset ?? parentEnd }, {});
      const outerRange = sourceOuterRange({ node, html, parentStart, parentEnd }, {});
      return {
        tagName: node.tagName,
        attributes: Object.fromEntries(node.attrs.map(attr => [attr.name, attr.value])),
        path,
        outerRange,
        sourceSupported: !!outerRange && children.every(child => child.sourceSupported),
        children,
      };
    });
    invalidateOverlappingSiblings({ elements }, {});
    return elements;
  };
  return walk({ nodes: fragment.childNodes, parentPath: [], parentStart: 0, parentEnd: html.length }, {});
}

/**
 * Generic i18n type vocabulary.
 *
 * Origin (`i18n/types.ts` in the vendored OD web tree) hard-codes a single
 * `Locale` union of 19 language tags and a `Dict` interface with ~1,400
 * named keys — OD's actual translated product copy, not reusable content.
 * This module keeps only the *shape* of that pattern (a locale is a plain
 * string, a dictionary is a flat, string-keyed lookup) so a host supplies
 * its own locale union and its own dictionary type as a generic parameter.
 */

/** A BCP-47-ish locale tag (e.g. `'en'`, `'zh-CN'`). Any string a host defines. */
export type Locale = string;

/** Interpolation values substituted into a `{name}`-style placeholder. */
export type TranslationVars = Record<string, string | number>;

/**
 * Flat, string-keyed translation dictionary. Kept flat (not deeply nested)
 * for the same reason the origin's `Dict` was: a missing key surfaces as a
 * plain string-index miss instead of a structural type mismatch.
 *
 * A host narrows this via its own dictionary interface (mirroring OD's own
 * `Dict`) and passes `Record<Locale, ItsDict>` to {@link I18nProvider}.
 */
export interface TranslationDict {
  [key: string]: string;
}

/**
 * Parses `@token` mentions out of a committed plain-text string. This is the
 * "reconcile a document model back into a string" side of the picture —
 * used by `deserialize.ts` to decide which `@token` runs become atomic
 * mention nodes, and available to hosts that need the same rule to fold
 * plain-text-typed `@token`s into a "currently referenced" entity list.
 *
 * Trie lookup prefers the longest token subject to left/right boundaries. MentionEntity.kind
 * is host-defined rather than a fixed product vocabulary.
 */
import type { MentionEntity, MentionPart } from './types.js';

export function buildMentionToken(label: string): string {
  return label.startsWith('@') ? label : `@${label}`;
}

export function parseMentionParts(
  text: string,
  entities: MentionEntity[],
  options: { highlightUnknown?: boolean } = {},
): MentionPart[] | null {
  // An empty string never contains '@', so this one check also covers `!text`.
  if (!text.includes('@')) return null;
  const scan = {
    known: getMentionTokenIndex(entities),
    highlightUnknown: options.highlightUnknown ?? true,
  };
  const parts: MentionPart[] = [];
  let copiedUntil = 0;
  let start = text.indexOf('@');

  while (start !== -1) {
    const match = findMentionAt({ ...scan, text, start });
    if (match) copiedUntil = appendMatch({ parts, text, copiedUntil, match });
    start = text.indexOf('@', match ? copiedUntil : start + 1);
  }

  // Every mention token is at least two characters ('@' plus one more), so
  // `copiedUntil` only moves off 0 once a mention part has been pushed.
  if (copiedUntil === 0) return null;
  if (copiedUntil < text.length) {
    parts.push({ kind: 'text', text: text.slice(copiedUntil) });
  }

  // Every 'text' part pushed above is guarded to be non-empty (`match.start
  // > copiedUntil` / `copiedUntil < text.length`), and each is immediately
  // followed by that iteration's mention part — so `parts` never contains
  // an empty or adjacent-duplicate 'text' entry that would need coalescing.
  // An earlier version of this function ran the result through a
  // coalesce-adjacent-and-drop-empty pass copied from the origin; removed
  // per this package's coverage-driven-refactor policy once the loop proved
  // every branch of that pass was unreachable from this one real call site
  // (Phase 9.5: a dead branch gets refactored out, not padded with a test).
  return parts;
}

/**
 * Pushes the plain text between `copiedUntil` and the match (when non-empty)
 * followed by the mention part; returns the new `copiedUntil`.
 */
function appendMatch(at: {
  parts: MentionPart[];
  text: string;
  copiedUntil: number;
  match: MentionMatch;
}): number {
  const { parts, text, copiedUntil, match } = at;
  if (match.start > copiedUntil) {
    parts.push({ kind: 'text', text: text.slice(copiedUntil, match.start) });
  }
  parts.push({ kind: 'mention', entity: match.entity, text: match.token });
  return match.start + match.token.length;
}

/**
 * The mention starting at `scan.start`, or null. A known (trie) match wins
 * unless the unknown-mention run at the same position is strictly longer.
 */
function findMentionAt(scan: {
  text: string;
  known: MentionTrieNode;
  highlightUnknown: boolean;
  start: number;
}): MentionMatch | null {
  const { text } = scan;
  if (!isMentionBoundary(text, scan.start)) return null;
  const knownMatch = findKnownMentionAt(text, scan.known, scan.start);
  const unknownMatch = scan.highlightUnknown ? findUnknownMentionAt(text, scan.start) : null;
  return knownMatch && (!unknownMatch || knownMatch.token.length >= unknownMatch.token.length)
    ? knownMatch
    : unknownMatch;
}

interface MentionTrieNode {
  children: Map<string, MentionTrieNode>;
  entity?: MentionEntity & { token: string };
}

const mentionTokenIndexCache = new WeakMap<MentionEntity[], MentionTrieNode>();

/** Root of the (cached, per entities-array) trie of every entity's `@token`. */
function getMentionTokenIndex(entities: MentionEntity[]): MentionTrieNode {
  const cached = mentionTokenIndexCache.get(entities);
  if (cached) return cached;

  const root: MentionTrieNode = { children: new Map() };
  const seen = new Set<string>();
  const normalized = entities
    .map((entity) => {
      const token = entity.token ?? buildMentionToken(entity.label);
      return {
        id: entity.id,
        kind: entity.kind,
        label: entity.label,
        token,
        ...(entity.title ? { title: entity.title } : {}),
      };
    })
    .filter((entity) => {
      if (!entity.token || entity.token === '@') return false;
      const key = `${entity.kind}:${entity.token}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    // The preceding .filter() step already excludes every entity whose
    // `token` is falsy, so by the time .sort() runs every element's `token`
    // is a real string — the `!` documents that (noUncheckedIndexedAccess
    // makes `.length` on an optional string require narrowing) rather than
    // adding an unreachable `?? 0` fallback branch no real input can hit.
    .sort((a, b) => b.token!.length - a.token!.length);

  for (const entity of normalized) {
    // `normalized` was already filtered above to exclude any falsy/`'@'`
    // token, so `token` here is always a real, non-`'@'` string.
    const token = entity.token;
    let node = root;
    for (const char of token) {
      let child = node.children.get(char);
      if (!child) {
        child = { children: new Map() };
        node.children.set(char, child);
      }
      node = child;
    }
    // First writer wins: two entities of different kinds can share a token.
    node.entity ??= entity;
  }

  mentionTokenIndexCache.set(entities, root);
  return root;
}

function findKnownMentionAt(
  text: string,
  root: MentionTrieNode,
  start: number,
): MentionMatch | null {
  let best: MentionMatch | null = null;
  let node: MentionTrieNode | undefined = root;
  for (let i = start; i < text.length; i += 1) {
    // `i < text.length` is the loop condition itself, so `text[i]` is always
    // defined here — the `!` documents that instead of adding an
    // unreachable `?? ''` fallback (noUncheckedIndexedAccess requires
    // narrowing a string index read either way).
    node = node.children.get(text[i]!);
    if (!node) break;
    if (node.entity && isMentionRightBoundary(text, i + 1)) {
      best = { start, token: node.entity.token, entity: node.entity };
    }
  }
  return best;
}

function findUnknownMentionAt(text: string, start: number): MentionMatch | null {
  let end = start + 1;
  // Both `text[end]` reads below are only ever evaluated once a preceding
  // `end < text.length` check (the `||`'s left side / the `&&`'s left side)
  // has already passed, so `text[end]` is always defined — `!` documents
  // that instead of an unreachable `?? ''` fallback.
  if (end >= text.length || /[\s@]/.test(text[end]!)) return null;
  while (end < text.length && !/[\s@]/.test(text[end]!)) {
    end += 1;
  }
  const token = text.slice(start, end);
  return {
    start,
    token,
    entity: {
      id: `unknown:${token}`,
      kind: 'unknown',
      label: token.slice(1),
      token,
      title: token,
    },
  };
}

/**
 * Left boundary rule: `@<token>` is a candidate mention only when the
 * character before `@` is the start of the string or whitespace / opening
 * bracket / quote.
 */
export function isMentionBoundary(text: string, start: number): boolean {
  if (start === 0) return true;
  // `start > 0` here (the `start === 0` case already returned), so
  // `start - 1` is always a valid index — `!` documents that instead of an
  // unreachable `?? ''` fallback.
  return /[\s([{"']/.test(text[start - 1]!);
}

/**
 * Right boundary rule: the unknown-mention regex is `/@[^\s@]+/`, so a
 * `@<token>` candidate is the full mention only when the character after the
 * token is the end of the string, whitespace, or another `@`.
 */
export function isMentionRightBoundary(text: string, end: number): boolean {
  if (end >= text.length) return true;
  // `end < text.length` here — `!` documents the always-defined read
  // instead of an unreachable `?? ''` fallback.
  return /[\s@]/.test(text[end]!);
}

interface MentionMatch {
  start: number;
  token: string;
  entity: MentionEntity;
}

/**
 * Submit-time right boundary for reconciling a *still-visible atomic pill*
 * against serialized text. Looser than `isMentionRightBoundary`: a pill stays
 * "referenced" even when the user types trailing punctuation right after it
 * (e.g. `@Slack,` or `@Notion.`), so the character after the token may also
 * be sentence/clause punctuation that cannot be part of a mention token.
 */
function isMentionSubmitRightBoundary(text: string, end: number): boolean {
  if (end >= text.length) return true;
  // `end < text.length` here — `!` documents the always-defined read
  // instead of an unreachable `?? ''` fallback.
  return /[\s@,.;:!?)\]}"'»”’]/.test(text[end]!);
}

/**
 * Whether `@label` appears in `text` as a standalone inline mention (proper
 * left boundary, not a substring of a longer word). Useful for a host that
 * reconciles a "currently referenced" entity list against typed text at
 * submit time — a chip whose `@token` the user deleted should not be kept.
 */
export function mentionTokenPresent(text: string, label: string): boolean {
  const token = buildMentionToken(label);
  let from = 0;
  let start = text.indexOf(token, from);
  while (start !== -1) {
    if (
      isMentionBoundary(text, start) &&
      isMentionSubmitRightBoundary(text, start + token.length)
    ) {
      return true;
    }
    from = start + 1;
    start = text.indexOf(token, from);
  }
  return false;
}

/**
 * Folds plain-text `@token` runs that still match a known entity into
 * `present` (entities already backed by an atomic mention node in the
 * tree). A host that inserts mentions as plain text rather than atomic
 * nodes (e.g. via `insertText` instead of `insertMention`) needs this to
 * keep a "currently referenced" list in sync with what's actually typed.
 *
 * Origin: `LexicalComposerInput.tsx`'s `foldPresentEntities`.
 */
export function foldPresentMentions(
  text: string,
  present: MentionEntity[],
  known: MentionEntity[],
): MentionEntity[] {
  const result: MentionEntity[] = [...present];
  const seen = new Set(present.map((e) => `${e.kind}:${e.id}`));
  const parts = parseMentionParts(text, known, { highlightUnknown: false }) ?? [];
  for (const part of parts) {
    if (part.kind !== 'mention' || part.entity.kind === 'unknown') continue;
    const key = `${part.entity.kind}:${part.entity.id}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(part.entity);
  }
  return result;
}

'use client';

import { forwardRef, useImperativeHandle, useRef, type ForwardedRef } from 'react';
import { LexicalComposer } from '@lexical/react/LexicalComposer';
import type { InitialConfigType } from '@lexical/react/LexicalComposer';
import { PlainTextPlugin } from '@lexical/react/LexicalPlainTextPlugin';
import { ContentEditable } from '@lexical/react/LexicalContentEditable';
import { LexicalErrorBoundary } from '@lexical/react/LexicalErrorBoundary';
import { HistoryPlugin } from '@lexical/react/LexicalHistoryPlugin';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { $getRoot, $getSelection, $isRangeSelection, type RangeSelection } from 'lexical';
import { DEFAULT_TEST_ID, DEFAULT_TRIGGERS, EDITOR_THEME } from '../../constants.js';
import { setRichTextFromPlainText } from '../../deserialize.js';
import { $createMentionNode, MentionNode } from '../../mention-node.js';
import {
  buildAnyTriggerDeletionRegex,
  buildTriggerDeletionRegex,
  deleteActiveTrigger,
} from '../../rules.js';
import { serializeRichText } from '../../serialize.js';
import type {
  MentionEntity,
