const DEFAULT_MENTION_TRIGGER_ID = 'mention';

export interface RichTextInputProps {
  placeholder: string;
  /** Host-controlled value. Reseeded into the editor only when it changes
   *  for a reason other than the user's own typing — see `useSeededValue`. */
  value: string;
  /** Rendered as pills (via `setText`/seeding) and used to fold plain-text
   *  `@token`s into the reported mention list. */
  knownMentions: MentionEntity[];
  /** Fires on every real text change with the serialized plain text + the
   *  mentions currently referenced by it (atomic nodes + matched plain
   *  `@token`s). */
  onChange(text: string, mentions: MentionEntity[]): void;
  /** The trigger (if any) active at the caret, e.g. to drive a popover. */
  onTriggerChange(match: RichTextTriggerMatch | null): void;
  /** Plain Enter with no popover open and no IME composition in progress. */
  onSubmit(): void;
  /** Pasted files/images — omit to fall back to plain-text paste only. */
  onPasteFiles?: ((files: File[]) => void) | undefined;
  /** Whether a popover is open; gates the arrow/tab/enter/escape routing. */
  popoverOpen: boolean;
  /** Routes a popover key to the host; returns true when the host consumed it. */
  onPopoverKey(key: PopoverNavigationKey): boolean;
  /** Optional combobox a11y: announces the active row of a portaled listbox
   *  without moving DOM focus. */
  comboboxAria?: { activeId: string | null; expanded: boolean } | undefined;
  title?: string | undefined;
  testId?: string | undefined;
  /** `aria-controls` target — must match the host's portaled listbox id. */
  mentionListboxId?: string | undefined;
  namespace?: string | undefined;
  /** Which trigger characters are recognized at the caret. Defaults to an
   *  inline `@mention` + a line-start-anchored `/command`, matching the
   *  origin. Pass `[]` to disable trigger detection entirely. */
  triggers?: readonly RichTextTriggerConfig[] | undefined;
  /** Which `triggers` entry's character `insertMention` deletes before
   *  splicing in the picked mention node. Defaults to `'mention'`. */
  mentionTriggerId?: string | undefined;
  /** Resolves a per-mention color, applied as a CSS custom property on that
   *  mention's DOM element — see `useMentionColorStamping`. Omit for
   *  CSS-only (className-driven) mention styling. */
  resolveMentionColor?: ((mention: MentionEntity) => string | undefined) | undefined;
}

function EditorSurface(props: RichTextInputProps, ref: ForwardedRef<RichTextInputHandle>) {
  const {
    placeholder,
    value,
    knownMentions,
    onChange,
    onTriggerChange,
    onSubmit,
    onPasteFiles,
    popoverOpen,
    onPopoverKey,
    comboboxAria,
    title,
    testId = DEFAULT_TEST_ID,
    mentionListboxId = 'rich-text-mention-listbox',
    triggers = DEFAULT_TRIGGERS,
    mentionTriggerId = DEFAULT_MENTION_TRIGGER_ID,
    resolveMentionColor,
  } = props;

  const [editor] = useLexicalComposerContext();

  // `knownMentions`/`triggers`/`mentionTriggerId` can change between renders;
  // the imperative handle below is created once (stable identity, deps
  // `[editor]`) and always reads the latest values through these refs,
  // mirroring the origin's `knownEntitiesRef` pattern.
  const knownMentionsRef = useRef(knownMentions);
  knownMentionsRef.current = knownMentions;
  const triggersRef = useRef(triggers);
  triggersRef.current = triggers;
  const mentionTriggerIdRef = useRef(mentionTriggerId);
  mentionTriggerIdRef.current = mentionTriggerId;

  useSyncedOnChange(knownMentions, onChange);
  useTriggerDetection(triggers, onTriggerChange);
  useMentionAtomicNavigation();
  useKeyboardCommands(popoverOpen, onSubmit, onPopoverKey);
  usePasteFiles(onPasteFiles);
  useSeededValue(value, knownMentions);
  useMentionColorStamping(resolveMentionColor);

  useImperativeHandle(
    ref,
    (): RichTextInputHandle => ({
      getText() {
        // Belt-and-suspenders: collapse any stray \n\n the single-paragraph
        // model should never produce, so the wire format stays byte-stable.
        return serializeRichText(editor.getEditorState()).text.replace(/\n{2,}/g, '\n');
      },
      setText(text: string) {
        setRichTextFromPlainText(editor, text, knownMentionsRef.current);
      },
      clear() {
        setRichTextFromPlainText(editor, '', knownMentionsRef.current);
      },
      focus() {
        editor.focus();
      },
      insertText(text: string) {
        editor.update(
          () => {
            let sel = $getSelection();
            if (!$isRangeSelection(sel)) {
              $getRoot().selectEnd();
              sel = $getSelection();
            }
            if ($isRangeSelection(sel)) sel.insertText(text);
          },
          { discrete: true },
        );
      },
      insertMention(insert: MentionInsert) {
        editor.update(
          () => {
            let sel = $getSelection();
            if (!$isRangeSelection(sel)) {
              $getRoot().selectEnd();
              sel = $getSelection();
            }
            // `$getRoot().selectEnd()` always establishes a collapsed
            // RangeSelection — even an empty root selects at its own
            // boundary — so `sel` is guaranteed to be one by this point.
            // The cast documents that instead of an unreachable
            // early-return branch no real document state can trigger.
            const rangeSel = sel as RangeSelection;
            const mentionTrigger =
              triggersRef.current.find((t) => t.id === mentionTriggerIdRef.current) ??
              triggersRef.current[0];
            if (mentionTrigger) {
              deleteActiveTrigger(rangeSel, buildTriggerDeletionRegex(mentionTrigger));
            }
            const node = $createMentionNode({
              mentionId: insert.entity.id,
              mentionKind: insert.entity.kind,
              token: insert.token,
              label: insert.entity.label,
              title: insert.entity.title,
            });
            const active = $getSelection();
            if ($isRangeSelection(active)) {
              active.insertNodes([node]);
              const after = $getSelection();
              if ($isRangeSelection(after)) after.insertText(' ');
            }
          },
          { discrete: true },
        );
      },
      replaceActiveTrigger(text: string) {
        editor.update(
          () => {
            let sel = $getSelection();
            if (!$isRangeSelection(sel)) {
              $getRoot().selectEnd();
              sel = $getSelection();
            }
            // See the identical `selectEnd()` guarantee noted in
            // `insertMention` above.
            const rangeSel = sel as RangeSelection;
            // Drop whichever trigger's query is active, then insert the
            // plain text (e.g. a Tab-completed slash command's own text).
            deleteActiveTrigger(rangeSel, buildAnyTriggerDeletionRegex(triggersRef.current));
            const active = $getSelection();
            if ($isRangeSelection(active)) active.insertText(text);
          },
          { discrete: true },
        );
      },
    }),
    [editor],
  );

  return (
    <>
      <PlainTextPlugin
        contentEditable={
          <ContentEditable
            data-testid={testId}
            className="rich-text-input-editable"
            aria-placeholder={placeholder}
            title={title ?? placeholder}
            role="combobox"
            aria-expanded={comboboxAria?.expanded ? 'true' : 'false'}
            aria-controls={mentionListboxId}
            {...(comboboxAria?.activeId ? { 'aria-activedescendant': comboboxAria.activeId } : {})}
            placeholder={<div className="rich-text-input-placeholder">{placeholder}</div>}
          />
        }
        placeholder={<div className="rich-text-input-placeholder">{placeholder}</div>}
        ErrorBoundary={LexicalErrorBoundary}
      />
      <HistoryPlugin />
    </>
  );
}

const EditorSurfaceWithRef = forwardRef<RichTextInputHandle, RichTextInputProps>(EditorSurface);

/**
 * Origin: `apps/web/src/components/composer/LexicalComposerInput.tsx` (OD's
 * chat composer input). A plain-text Lexical editor (not a full block/marks
 * rich text editor) with atomic `@mention`/`/command` trigger tokens, a
 * single-paragraph model (Enter submits, Shift+Enter soft-breaks), and an
 * imperative handle mirroring a controlled `<textarea>`'s usual operations.
 *
 * The origin's `EditorRefPlugin` (a ref-bridging plugin needed because its
 * `forwardRef` component lived OUTSIDE the `LexicalComposer` context) is
 * dropped: `EditorSurface` above is itself inside that context, so its
 * `useImperativeHandle` reads `editor` directly from
 * `useLexicalComposerContext()`.
 */
export const RichTextInput = forwardRef<RichTextInputHandle, RichTextInputProps>(
  function RichTextInput(props, ref) {
    const initialConfig: InitialConfigType = {
      namespace: props.namespace ?? 'rich-text-input',
      editable: true,
      nodes: [MentionNode],
      theme: EDITOR_THEME,
      onError(err) {
        if (process.env.NODE_ENV !== 'production') {
          console.error('[rich-text-input]', err);
        }
      },
      // editorState intentionally omitted → empty on first paint (SSR-safe).
    };

    return (
      <div className="rich-text-input">
        <LexicalComposer initialConfig={initialConfig}>
          <EditorSurfaceWithRef {...props} ref={ref} />
        </LexicalComposer>
      </div>
    );
  },
);

import { trimTrailingChars } from '../../utils/trim-chars.js';
/**
 * @module features/mcp-ui/confirmation-store
 *
 * A short-lived, single-use, binding-checked token store — the server half of the MCP-UI two-step
 * confirmation pattern. Generalized from the reference implementation's `pending-confirmations.ts`,
 * which was already domain-agnostic in intent but hardcoded one binding shape (tool/workspace/principal/
 * entity/entityVersion); here the binding is whatever record the caller mints with.
 *
 * ## Why a token rather than a boolean "requires confirmation" flag
 *
 * A flag makes the *agent* the thing that confirms. This makes the *human* the thing that confirms,
 * because of where the secret lives: a destructive tool's first call mints a token, embeds it only
 * inside the UI resource's HTML, and returns without acting. Per MCP Apps' security model a host
 * renders that HTML for the user and does not feed it to the model — so the model sees "a dialog is
 * open", the rendered dialog holds the only copy of the token, and the second call is unreachable
 * without a human clicking. If the token ever appears in the tool result's text block, in `_meta`,
 * or in an error message, the whole arrangement collapses into theater; keeping it out of those
 * places is the caller's obligation, and one this module cannot enforce for it.
 *
 * ## Deliberate divergence from the reference implementation's version: no hashing at rest, by default
 *
 * The reference implementation stores `sha256(token)` so a heap dump yields nothing redeemable. That is defense in depth on
 * top of the real properties (random, single-use, TTL-bounded, binding-checked), and it costs a
 * `node:crypto` import — which this package, a browser-runtime package, cannot take. The two
 * isomorphic alternatives are both worse than the trade made here: `crypto.subtle.digest` is async
 * (it would make `mint`/`redeem` return promises for a defense-in-depth property) *and* absent
 * outside secure contexts, and a non-cryptographic hash would add collisions while implying a
 * strength it does not have. So the default keys entries by the raw token, and {@link
 * ConfirmationStoreDeps.digestToken} is the one-line seam a Node consumer uses to restore hashing:
 * `digestToken: (token) => createHash('sha256').update(token, 'utf8').digest('hex')`.
 */

/** Default lifetime: long enough for a human to read a dialog, short enough that an abandoned one cannot be redeemed later out of scrollback. */
export const DEFAULT_CONFIRMATION_TTL_MS = 5 * 60 * 1000;

/** 256 bits — the same sizing as a session token, since a guessable confirmation token is a bypass. */
const TOKEN_BYTES = 32;

/**
 * What a token is bound to. Every entry is compared on redemption, and any difference — a changed
 * value, a missing key, an extra key — is a rejection rather than a warning.
 *
 * Values are `string | number` rather than `unknown` on purpose: a binding is an identity claim, and
 * comparing arbitrary values would need a deep-equality contract this module has no business
 * defining. A caller with structured binding data should serialize it into a string itself, so it
 * owns the serialization rather than inheriting a surprising one.
 */
export type ConfirmationBinding = Readonly<Record<string, string | number>>;

/** A minted, not-yet-redeemed confirmation. */
export interface PendingConfirmation {
  readonly binding: ConfirmationBinding;
  /** Human-readable description of what was agreed to, echoed back on redemption for the audit trail. */
  readonly summary: string;
  readonly expiresAtMs: number;
}

/**
 * Why a redemption failed.
 *
 * Deliberately coarse. "No such token" and "expired token" share one reason because distinguishing
 * them tells a caller holding a guessed token that it was once real. There is no `already-used`
 * reason for the same kind of reason: a redeemed token is deleted, so a replay is indistinguishable
 * from a guess, which is the intended behavior rather than a missing case.
 */
export type ConfirmationRejectionReason = 'unknown-or-expired' | 'binding-mismatch';

export type RedeemResult =
  | { readonly ok: true; readonly confirmation: PendingConfirmation }
  | { readonly ok: false; readonly reason: ConfirmationRejectionReason };

export interface ConfirmationStore {
  /**
   * Mints a token for one pending action.
   *
   * @returns The RAW token and its expiry. The token's only safe destination is inside the UI
   * resource's HTML — see this module's header.
   */
  mint(spec: { binding: ConfirmationBinding; summary: string }): {
    readonly token: string;
    readonly expiresAtMs: number;
  };
  /** Redeems a token exactly once, against the binding the caller expects it to carry. */
  redeem(spec: { token: string; binding: ConfirmationBinding }): RedeemResult;
  /** Pending, unexpired count — for tests and diagnostics only. */
  size(): number;
}

export interface ConfirmationStoreDeps {
  /** Millisecond clock, injected so TTL expiry is testable without waiting. */
  now?: () => number;
  /** Token source, injected so a test can assert a known value. Defaults to 256 bits of `crypto.getRandomValues`, never `Math.random`. */
  randomToken?: () => string;
  /** Lifetime of a minted token. Defaults to {@link DEFAULT_CONFIRMATION_TTL_MS}. */
  ttlMs?: number;
  /** Maps a raw token to the key it is stored under. Defaults to identity — see this module's header for why, and what to pass to get hashing at rest. */
  digestToken?: (token: string) => string;
}

/**
 * Compares two strings without leaking their contents through timing.
 *
 * Length is compared first and therefore does leak, exactly as `node:crypto`'s own
 * `timingSafeEqual` leaks it (by throwing on a length mismatch). That is acceptable here: binding
 * values are ids the caller already knows the shape of, and the secret — the token — is not
 * compared with this at all, it is a map key.
 */
function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let difference = 0;
  for (let index = 0; index < a.length; index += 1) {
    difference |= a.charCodeAt(index) ^ b.charCodeAt(index);
  }
  return difference === 0;
}

function bindingsMatch(minted: ConfirmationBinding, presented: ConfirmationBinding): boolean {
  const mintedKeys = Object.keys(minted);
  if (mintedKeys.length !== Object.keys(presented).length) return false;
  let matched = true;
  for (const key of mintedKeys) {
    if (!Object.prototype.hasOwnProperty.call(presented, key)) {
      matched = false;
      continue;
    }
    const left = minted[key];
    const right = presented[key];
    // Compared as strings so a `1` presented where `1` was minted still matches, while `'1'` vs `1`
    // does not — the type check below is what keeps those apart, and it is exact on purpose: a
    // binding that silently coerces is a binding that can be satisfied by a value the minter never
    // agreed to.
    if (typeof left !== typeof right) {
      matched = false;
      continue;
    }
    if (!constantTimeEquals(String(left), String(right))) matched = false;
  }
  return matched;
}

function defaultRandomToken(): string {
  const source = globalThis.crypto;
  if (typeof source?.getRandomValues !== 'function') {
    // No `Math.random` fallback. A predictable confirmation token is a confirmation bypass, and a
    // store that silently degrades to one is worse than a store that refuses to mint — every
    // browser and every supported Node exposes `getRandomValues` (it needs no secure context,
    // unlike `crypto.subtle`), so reaching this means something is deeply wrong with the host.
    // Creation is lazy: the default token source is checked on mint, not when the store is created.
    throw new Error('createConfirmationStore requires crypto.getRandomValues; pass deps.randomToken to override.');
  }
  const bytes = source.getRandomValues(new Uint8Array(TOKEN_BYTES));
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return trimTrailingChars(btoa(binary).replace(/\+/g, '-').replace(/\//g, '_'), '=');
}

/**
 * Creates an in-process confirmation store.
 *
 * In-process is correct rather than a shortcut: a confirmation that does not survive a process
 * restart is a confirmation the human is simply asked for again — the fail-closed direction —
 * whereas persisting them would build a durable store of pre-authorized destructive actions.
 *
 * @param deps - See {@link ConfirmationStoreDeps}.
 * @complexity O(1) amortized per operation; expired entries are swept lazily on `mint`/`size`.
 */
export function createConfirmationStore(deps: ConfirmationStoreDeps = {}): ConfirmationStore {
  const now = deps.now ?? (() => Date.now());
  const randomToken = deps.randomToken ?? defaultRandomToken;
  const ttlMs = deps.ttlMs ?? DEFAULT_CONFIRMATION_TTL_MS;
  const digestToken = deps.digestToken ?? ((token: string) => token);

  const pending = new Map<string, PendingConfirmation>();

  function sweep(nowMs: number): void {
    for (const [key, entry] of pending) {
      if (entry.expiresAtMs <= nowMs) pending.delete(key);
    }
  }

  return {
    mint(spec) {
      const nowMs = now();
      sweep(nowMs);
      const token = randomToken();
      const expiresAtMs = nowMs + ttlMs;
      pending.set(digestToken(token), {
        binding: { ...spec.binding },
        summary: spec.summary,
        expiresAtMs,
      });
      return { token, expiresAtMs };
    },

    redeem(spec) {
      const nowMs = now();
      const key = digestToken(spec.token);
      const entry = pending.get(key);
      if (!entry) return { ok: false, reason: 'unknown-or-expired' };

      // Deleted before any binding check, so a held token cannot be probed repeatedly against
      // different bindings to learn what it was minted for.
      pending.delete(key);

      if (entry.expiresAtMs <= nowMs) return { ok: false, reason: 'unknown-or-expired' };
      if (!bindingsMatch(entry.binding, spec.binding)) return { ok: false, reason: 'binding-mismatch' };
      return { ok: true, confirmation: entry };
    },

    size() {
      sweep(now());
      return pending.size;
    },
  };
}

/** Shared value presentation for confirmation, form and outcome details. Never interprets HTML. */
import { escapeHtml } from '../escape.js';

/** One fact. Values and previous snapshots must be JSON-serializable; strings remain supported. */
export interface SurfaceDetail {
  readonly label: string;
  readonly value: unknown;
  /** Presence enables a diff, including an explicitly absent previous override. */
  readonly previous?: unknown;
  /** Explicit, optionally translated labels keyed by dotted object path. */
  readonly labels?: Readonly<Record<string, string>>;
  /** Optional secondary context beneath the label, using the shared muted hint style. */
  readonly description?: string;
  /**
   * `code` discloses a monospace `<pre>` that keeps line breaks and scrolls inside its own box
   * past a fixed height, so long SQL or JSON remains readable without stretching the dialog past
   * its frame. `status` reserves one line for a short outcome value. Omitted (or `text`) permits
   * value-sensitive presentation, preserving plain inline strings for short prose.
   */
  readonly format?: 'text' | 'code' | 'status';
}

type ValueContext = { value: unknown; path: string; labels: Readonly<Record<string, string>>; format?: SurfaceDetail['format'] };
type DiffContext = ValueContext & { previous: unknown };

/** Native details owns keyboard interaction; mirror its state for explicit ARIA consumers. */
export const DETAIL_DISCLOSURE_SCRIPT = `document.addEventListener("toggle", function (event) {
  var disclosure = event.target;
  if (!disclosure.matches || !disclosure.matches("details.mcpui-detail-disclosure")) return;
  disclosure.querySelector("summary").setAttribute("aria-expanded", disclosure.open ? "true" : "false");
}, true);`;

/** Humanized English fallback; caller labels remain verbatim. @complexity O(k) key length. */
export function surfaceDetailLabel({ key, path, labels }: { key: string; path: string; labels: ValueContext['labels'] }, _options = {}): string {
  if (Object.hasOwn(labels, path)) return labels[path]!;
  const words = key.replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/([A-Z])([A-Z][a-z])/g, '$1 $2').replace(/[_-]+/g, ' ').toLowerCase();
  const acronyms = words.replace(/\b(url|css|html|json|api|id)\b/g, word => word.toUpperCase());
  return acronyms.charAt(0).toUpperCase() + acronyms.slice(1);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function disclosure({ summary, body, kind = '' }: { summary: string; body: string; kind?: string }, _options = {}): string {
  return `<details class="mcpui-detail-disclosure ${kind}"><summary aria-expanded="false">${escapeHtml(summary)}</summary>${body}</details>`;
}

/** JSON scalar display; missing override values use the same empty marker as null. */
function scalarText({ value }: { value: unknown }, _options = {}): string {
  if (value === undefined || value === null || value === '') return '—';
  if (typeof value === 'boolean') return value ? 'On' : 'Off';
  return String(value);
}

/** Classifies content for a disclosure, preserving the original text bytes in the body. */
function codeKind({ value, path, format }: { value: string; path: string; format?: SurfaceDetail['format'] }, _options = {}): string | undefined {
  if (/css$/i.test(path) || (/\{[^}:]*:[^}]*\}/.test(value) && !/^\s*[\[{]/.test(value))) return 'CSS';
  if (/^\s*</.test(value)) return 'HTML';
  if (/^\s*[\[{]/.test(value)) return 'JSON';
  if (format === 'code') return 'Code';
  return /[\r\n]/.test(value) ? 'Text' : undefined;
}

/** Escapes all text once at the HTML sink. Long prose uses a three-line summary. */
function renderText({ value, path, format }: { value: string; path: string; format?: SurfaceDetail['format'] }, _options = {}): string {
  const text = escapeHtml(value);
  const kind = codeKind({ value, path, format });
  if (kind) {
    const lines = value.split(/\r\n|\r|\n/).length;
    return disclosure({ summary: `${kind} · ${lines} ${lines === 1 ? 'line' : 'lines'}`, body: `<pre class="mcpui-code">${text}</pre>`, kind: 'mcpui-detail-code' });
  }
  if (value.length <= 80) return text;
  return `<details class="mcpui-detail-disclosure mcpui-detail-long"><summary aria-expanded="false"><span class="mcpui-detail-preview">${text}</span><span class="mcpui-detail-more">Show more</span><span class="mcpui-detail-less">Show less</span></summary><div class="mcpui-detail-full">${text}</div></details>`;
}

/** Arrays keep scalar items compact; nested or long items use readable bullet rows. */
function renderArray({ value, ...context }: ValueContext & { value: readonly unknown[] }, _options = {}): string {
  if (value.length === 0) return '<span class="mcpui-detail-value">—</span>';
  const compact = value.every(item => item === null || ['boolean', 'number', 'string'].includes(typeof item))
    && value.every(item => String(item).length <= 80 && !/[\r\n<{[]/.test(String(item)));
  if (compact) return renderText({ ...context, value: value.map(item => scalarText({ value: item })).join(', ') });
  const items = value.map((item, index) => {
    const path = context.path ? `${context.path}.${index}` : String(index);
    return `<li>${renderValue({ ...context, value: item, path })}</li>`;
  });
  const rest = items.length <= 5 ? '' : disclosure({ summary: `Show more (${items.length - 5} items)`, body: `<ul class="mcpui-detail-array">${items.slice(5).join('')}</ul>` });
  return `<ul class="mcpui-detail-array">${items.slice(0, 5).join('')}</ul>${rest}`;
}

function objectRow({ key, context, body }: { key: string; context: ValueContext; body: string }, _options = {}): string {
  return `<div class="mcpui-detail-row"><dt>${escapeHtml(surfaceDetailLabel({ key, path: context.path, labels: context.labels }))}</dt><dd>${body}</dd></div>`;
}

/** Nested objects stay definition lists, indented once per actual group. @complexity O(n) rendered bytes. */
function renderObject({ value, ...context }: ValueContext & { value: Record<string, unknown> }, _options = {}): string {
  const entries = Object.entries(value);
  if (entries.length === 0) return '<span class="mcpui-detail-value">—</span>';
  const rows = entries.map(([key, item]) => {
    const child = { ...context, value: item, path: context.path ? `${context.path}.${key}` : key };
    return objectRow({ key, context: child, body: renderValue(child) });
  }).join('');
  return `<dl class="mcpui-detail-group">${rows}</dl>`;
}

/** Pure recursive rendering, O(n) in output bytes and O(depth) traversal stack; no external I/O. */
function renderValue(context: ValueContext, _options = {}): string {
  const { value } = context;
  if (Array.isArray(value)) return renderArray({ ...context, value });
  if (isRecord(value)) return renderObject({ ...context, value });
  if (typeof value === 'string' && value !== '') return renderText({ ...context, value });
  return escapeHtml(scalarText({ value }));
}

/** Object order is immaterial; array order and missing keys matter to an approval diff. */
function equalValue({ before, after }: { before: unknown; after: unknown }, _options = {}): boolean {
  if (Object.is(before, after)) return true;
  if (Array.isArray(before) && Array.isArray(after)) {
    return before.length === after.length && before.every((item, index) => equalValue({ before: item, after: after[index] }));
  }
  if (!isRecord(before) || !isRecord(after)) return false;
  const keys = Object.keys(before);
  return keys.length === Object.keys(after).length && keys.every(key => Object.hasOwn(after, key) && equalValue({ before: before[key], after: after[key] }));
}

/** A missing JSON key must never read an inherited property such as __proto__ or constructor. */
function ownValue({ record, key }: { record: Record<string, unknown>; key: string }, _options = {}): unknown {
  return Object.hasOwn(record, key) ? record[key] : undefined;
}

/** Presence needs its own label: null and missing otherwise both display an empty marker. */
function renderFieldDiff({ child, previous, value, key }: {
  child: DiffContext; previous: Record<string, unknown>; value: Record<string, unknown>; key: string;
}, _options = {}): string {
  const body = renderDiff(child);
  if (Object.hasOwn(previous, key) && Object.hasOwn(value, key)) return body;
  const label = Object.hasOwn(value, key) ? 'Added' : 'Removed';
  return `<span class="mcpui-hint">${label}</span>${body}`;
}

/** Partition by equality before rendering so unchanged fields never crowd out changes.
 * @complexity O(n * depth) worst-case nested comparison work; O(n) markup space. No reads or mutation. */
function renderObjectDiff(context: DiffContext & { previous: Record<string, unknown>; value: Record<string, unknown> }, _options = {}): string {
  const { previous, value } = context;
  const keys = [...new Set([...Object.keys(value), ...Object.keys(previous)])];
  const changed: string[] = [];
  const unchanged: string[] = [];
  for (const key of keys) {
    const child = { ...context, previous: ownValue({ record: previous, key }), value: ownValue({ record: value, key }), path: context.path ? `${context.path}.${key}` : key };
    const same = Object.hasOwn(previous, key) === Object.hasOwn(value, key) && equalValue({ before: child.previous, after: child.value });
    const body = same ? renderValue(child) : renderFieldDiff({ child, previous, value, key });
    (same ? unchanged : changed).push(objectRow({ key, context: child, body }));
  }
  const rest = unchanged.length === 0 ? '' : disclosure({ summary: `Unchanged fields (${unchanged.length})`, body: `<dl class="mcpui-detail-group">${unchanged.join('')}</dl>`, kind: 'mcpui-detail-unchanged' });
  const changes = changed.length === 0 ? '' : `<dl class="mcpui-detail-group">${changed.join('')}</dl>`;
  return changes + rest || '<span class="mcpui-detail-value">—</span>';
}

/** Recurse only through object pairs; atomic and array updates show explicit before/after values. */
function renderDiff(context: DiffContext, _options = {}): string {
  if (isRecord(context.previous) && isRecord(context.value)) return renderObjectDiff({ ...context, previous: context.previous, value: context.value });
  return `<div class="mcpui-detail-change"><div><span class="mcpui-hint">Before</span>${renderValue({ ...context, value: context.previous })}</div><div><span class="mcpui-hint">After</span>${renderValue(context)}</div></div>`;
}

/** One reusable detail body. Raw JSON is escaped text, never a script or HTML fragment.
 * @returns HTML for JSON-compatible caller data; JSON.stringify errors propagate for invalid data.
 * @complexity O(n * depth) with a previous snapshot, otherwise O(n), in serialized bytes. */
export function renderStructuredDetail({ detail }: { detail: SurfaceDetail }, _options = {}): string {
  const context: ValueContext = { value: detail.value, path: '', labels: detail.labels ?? {}, format: detail.format };
  const hasPrevious = Object.hasOwn(detail, 'previous');
  const body = hasPrevious ? renderDiff({ ...context, previous: detail.previous }) : renderValue(context);
  const raw = hasPrevious ? { previous: detail.previous, value: detail.value } : detail.value;
  const showRaw = hasPrevious || (typeof detail.value === 'object' && detail.value !== null) || body.startsWith('<details ');
  if (!showRaw) return body;
  return body + disclosure({ summary: 'View raw', body: `<pre class="mcpui-code">${escapeHtml(JSON.stringify(raw, null, 2))}</pre>`, kind: 'mcpui-detail-raw' });
}

/**
 * @module features/mcp-ui/surfaces/text-input
 *
 * The free-text control fragment — `<input type="text">`, `<input type="number">`, or `<textarea>`
 * depending on the props, because all three are the same field to a caller (a labelled box you type
 * into) and differ only in how the value is read back.
 */
import { escapeHtml } from '../escape.js';
import { fieldDescribedBy, fieldElementId, renderFieldLabel } from './document.js';

/** Verbs the host can translate for a secret's reveal toggle; the field label is appended. */
export interface SecretInputText {
  readonly showSecret: string;
  readonly hideSecret: string;
}

export const DEFAULT_SECRET_INPUT_TEXT: SecretInputText = { showSecret: 'Show', hideSecret: 'Hide' };

export interface TextInputProps extends Partial<SecretInputText> {
  /** HTML `name`, DOM `id` suffix, and the params key the value is posted under. */
  readonly name: string;
  readonly label: string;
  /** Pre-filled value. Numbers are stringified; `undefined` leaves the control empty.
   *  Forbidden when `secret` is true, including an empty string. */
  readonly value?: string | number;
  readonly placeholder?: string;
  /** Help text, wired up with `aria-describedby`. */
  readonly hint?: string;
  readonly required?: boolean;
  readonly disabled?: boolean;
  /** `'number'` also constrains the on-screen keyboard on touch devices, which `'text'` would not. */
  readonly inputType?: 'text' | 'number';
  /** Renders as `<input type="password">`, or a masked textarea when multiline — either way with
   *  an eye show/hide toggle. No `<textarea type="password">` exists, so multiline uses CSS text security.
   *  Ignored for presentation when `inputType` is `'number'` (no such thing as a masked number) —
   *  same precedence `multiline`'s own doc comment already gives `inputType: 'number'`.
   *  A supplied value is always rejected: masking cannot protect a secret serialized into HTML. */
  readonly secret?: boolean;
  /** Renders a `<textarea>`. Ignored when `inputType` is `'number'` — there is no multiline number. */
  readonly multiline?: boolean;
  readonly rows?: number;
  /** Number-only constraints; ignored for text. */
  readonly min?: number;
  readonly max?: number;
  readonly step?: number;
}

function optionalAttribute(name: string, value: string | number | undefined): string {
  if (value === undefined) return '';
  return ` ${name}="${escapeHtml(String(value))}"`;
}

function booleanAttribute(name: string, value: boolean | undefined): string {
  return value === true ? ` ${name}` : '';
}

/**
 * Resolves which HTML `type` a text control renders as. `'number'` wins over `secret` — there is no
 * masked number input, and `TextInputProps.secret`'s own doc comment already fixes that precedence.
 *
 * @param props - The `inputType`/`secret` slice of {@link TextInputProps}.
 * @returns The concrete `<input type>` value.
 * @complexity O(1).
 */
function resolveInputType(props: Pick<TextInputProps, 'inputType' | 'secret'>): 'text' | 'number' | 'password' {
  if (props.inputType === 'number') return 'number';
  return props.secret === true ? 'password' : 'text';
}

/** Eye / eye-off glyphs. Both ship; CSS shows the one matching `aria-pressed`, so the inline script
 *  never builds markup. `currentColor` keeps them on the surface's theme tokens in light and dark. */
const EYE_ICON =
  '<svg class="mcpui-secret-icon-show" aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>' +
  '<svg class="mcpui-secret-icon-hide" aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9.9 4.24A9.1 9.1 0 0 1 12 4c6.5 0 10 7 10 7a17.8 17.8 0 0 1-2.16 3.19M6.6 6.6C3.9 8.4 2 12 2 12s3.5 7 10 7a9.7 9.7 0 0 0 5.4-1.6M14.12 14.12a3 3 0 1 1-4.24-4.24"/><path d="M2 2l20 20"/></svg>';

/**
 * The eye toggle every secret control carries, inside the field's right edge. Its accessible name
 * is the host's verb plus the field label ("Show Token"); the full show/hide names ride on data
 * attributes so the form script swaps them without knowing the label.
 * @complexity O(n) in the label lengths.
 */
function renderSecretToggle(props: TextInputProps, id: string): string {
  const show = `${props.showSecret ?? DEFAULT_SECRET_INPUT_TEXT.showSecret} ${props.label}`;
  const hide = `${props.hideSecret ?? DEFAULT_SECRET_INPUT_TEXT.hideSecret} ${props.label}`;
  return `<button type="button" class="mcpui-secret-toggle" data-mcpui-secret-toggle="${escapeHtml(id)}" data-mcpui-show-secret="${escapeHtml(show)}" data-mcpui-hide-secret="${escapeHtml(hide)}" aria-label="${escapeHtml(show)}" aria-controls="${escapeHtml(id)}" aria-pressed="false"${booleanAttribute('disabled', props.disabled)}>${EYE_ICON}</button>`;
}

/** Wraps a secret control so its toggle sits inside the field's right edge. @complexity O(n) in the rendered length. */
function withSecretToggle(control: string, props: TextInputProps, id: string): string {
  return `<div class="mcpui-secret">${control}${renderSecretToggle(props, id)}</div>`;
}

/** The `<textarea>` control, masked with a reveal toggle when secret. @complexity O(n) in the rendered length. */
function renderTextarea(props: TextInputProps, required: { id: string; common: string }): string {
  const secret = props.secret === true;
  const control = `<textarea class="mcpui-textarea"${required.common}${optionalAttribute('rows', props.rows)}` +
    // Password inputs strip line breaks. CSS masking keeps the textarea's actual value intact,
    // and disables browser text assistance that could retain or alter a pasted credential.
    (secret ? ' data-mcpui-secret style="-webkit-text-security: disc;" autocomplete="off" spellcheck="false"' : '') +
    `>${props.value === undefined ? '' : escapeHtml(String(props.value))}</textarea>`;
  return secret ? withSecretToggle(control, props, required.id) : control;
}

/** The single-line `<input>` control, with the eye toggle when masked. @complexity O(n) in the rendered length. */
function renderInput(props: TextInputProps, required: { id: string; type: 'text' | 'number' | 'password'; common: string }): string {
  const { type, common } = required;
  const control = `<input class="mcpui-input" type="${type}"${common}` +
    optionalAttribute('value', props.value) +
    // A stored secret (e.g. a cloud provider's access key or a database password) must never be
    // autofilled with a saved website login. `new-password`, not `off`: Chrome ignores `off` on
    // password inputs by design and fills the saved login anyway.
    // spellcheck off: once revealed as `type="text"`, enhanced spellcheck would ship the secret out.
    (type === 'password' ? optionalAttribute('autocomplete', 'new-password') + optionalAttribute('spellcheck', 'false') : '') +
    (type === 'number'
      ? optionalAttribute('min', props.min) + optionalAttribute('max', props.max) + optionalAttribute('step', props.step)
      : '') +
    '>';
  return type === 'password' ? withSecretToggle(control, props, required.id) : control;
}

/**
 * Renders one free-text field: its label, hint, and control, wrapped in `.mcpui-field`.
 *
 * @param props - See {@link TextInputProps}.
 * @returns An HTML fragment. Not a whole document — compose it with `form.ts`.
 * @complexity O(n) in the rendered length.
 */
export function renderTextInput(props: TextInputProps): string {
  // Even an empty prefill is forbidden: callers must omit value so a stored credential can never
  // enter the resource's HTML. Keep this error fixed, without the field name or rejected value.
  if (props.secret === true && props.value !== undefined) {
    throw new Error('Secret fields cannot have a pre-filled value. Omit value.');
  }
  const id = fieldElementId(props.name);
  const common =
    ` id="${escapeHtml(id)}" name="${escapeHtml(props.name)}"` +
    optionalAttribute('placeholder', props.placeholder) +
    booleanAttribute('required', props.required) +
    booleanAttribute('disabled', props.disabled) +
    fieldDescribedBy(props);

  const type = resolveInputType(props);
  const control = props.multiline === true && type !== 'number'
    ? renderTextarea(props, { id, common })
    : renderInput(props, { id, type, common });

  return `<div class="mcpui-field">\n${renderFieldLabel(props)}\n${control}\n</div>`;
}

// Dumb panel for the "Import from apps" (connected) tab: the source summary,
// the connector picker workbench (connect/select rows), the scan run bar, the
// suggestion review list, the status/error banners, the last-scan diagnostics,
// and the recent-scans history. Rendering only — every list, flag, and handler
// is supplied by a host's connectors/extractions hooks. Connector
// labels/byte counts come from the slice formatters. `ConnectorLogo` is
// `@jini-ai/ui`'s own (`features/connectors`) — it has no theme prop (that
// concern was already dropped when the connectors canary shipped; a host
// resolving theme-swapped logo URLs does so before handing `logoUrl` in).
import { useMemo } from 'react';
import type {  Connector,  ConnectorStatusMap } from '../../../connectors/types.js';
import {
  connectorAttemptDetail,
  connectorAttemptTitle,
  formatConnectorContextBytes,
  memoryTypeLabels,
} from '../../formatters.js';
import type {
  ConnectorMemoryAttempt,
  MemoryExtractionRecord,
  MemorySuggestion,
} from '../../types.js';
import { ConnectorLogo } from '../../../connectors/index.js';
import { Icon } from '../../../../react/components/Icon.js';
import { useT } from '../../../i18n/index.js';
import { MemoryExtractionCard } from './MemoryExtractionCard.js';

type Translate = ReturnType<typeof useT>;

/** The per-connector lookup tables a picker row derives its state from. */
interface ConnectorRowContext {
  connectorStatuses: ConnectorStatusMap;
  connectorsLoading: boolean;
  selectedConnectorIds: Set<string>;
  connectingConnectorIds: Set<string>;
  pendingConnectorAuthIds: Set<string>;
  connectorConnectErrors: Record<string, string>;
  connectorIdsWithDetails: Set<string>;
}

interface ConnectorRowState {
  connected: boolean;
  selected: boolean;
  connecting: boolean;
  authorizationPending: boolean;
  connectError: string | undefined;
  checkingStatus: boolean;
  reconnecting: boolean;
  /** Connecting, awaiting authorization, or still checking status. */
  busy: boolean;
}

function isStatusResolved({ connector, context }: { connector: Connector; context: ConnectorRowContext }): boolean {
  return context.connectorIdsWithDetails.has(connector.id) || context.connectorStatuses[connector.id] !== undefined;
}

function connectorRowState({ connector, context }: { connector: Connector; context: ConnectorRowContext }): ConnectorRowState {
  const connected = connector.status === 'connected';
  const connecting = context.connectingConnectorIds.has(connector.id);
  const authorizationPending = context.pendingConnectorAuthIds.has(connector.id);
  const connectError = context.connectorConnectErrors[connector.id];
  const checkingStatus =
    context.connectorsLoading && !isStatusResolved({ connector, context }) && !connected && !authorizationPending && !connectError && !connecting;
  return {
    connected,
    selected: context.selectedConnectorIds.has(connector.id) && connected,
    connecting,
    authorizationPending,
    connectError,
    checkingStatus,
    reconnecting: connector.status === 'error',
    busy: connecting || authorizationPending || checkingStatus,
  };
}

function connectorHint({ connector, state, t }: { connector: Connector; state: ConnectorRowState; t: Translate }): string {
  if (state.connected) return connector.accountLabel || `${connector.tools.length} ${t('read tools')}`;
  if (state.checkingStatus) return t('Checking connection status…');
  if (state.authorizationPending) return t('Finish authorization in your browser, then return here');
  return connector.lastError?.trim() || state.connectError || t('Connect this app before extraction');
}

function connectButtonLabel({ state, t }: { state: ConnectorRowState; t: Translate }): string {
  if (state.checkingStatus) return t('Checking');
  if (state.authorizationPending) return t('Waiting');
  if (state.connecting) return t('Connecting');
  return state.reconnecting ? t('Reconnect') : t('Connect');
}

function MemoryConnectButton({
  connector,
  state,
  onConnectMemoryConnector,
}: {
  connector: Connector;
  state: ConnectorRowState;
  onConnectMemoryConnector: (connectorId: string) => void;
}) {
  const t = useT();
  return (
    <button
      type="button"
      className={`memory-connector-connect-button${state.busy ? ' is-loading' : ''}`}
      disabled={state.busy}
      aria-busy={state.busy || undefined}
      aria-label={`${state.reconnecting ? t('Reconnect') : t('Connect')} ${connector.name}`}
      onClick={(event) => {
        event.preventDefault();
        event.stopPropagation();
        void onConnectMemoryConnector(connector.id);
      }}
    >
      <Icon name={state.busy ? 'refresh' : 'plus'} size={12} className={state.busy ? 'icon-spin' : ''} />
      <span>{connectButtonLabel({ state, t })}</span>
    </button>
  );
}

function MemoryConnectorPicker({ selected }: { selected: boolean }) {
  const t = useT();
  return (
    <span className={`memory-connector-picker${selected ? ' is-selected' : ''}`}>
      <span className="memory-connector-picker-box" aria-hidden="true">
        {selected ? <Icon name="check" size={12} /> : null}
      </span>
      <span>{selected ? t('Selected') : t('Select')}</span>
    </span>
  );
}

function MemoryConnectorRow({
  connector,
  context,
  toggleConnectorSelection,
  onConnectMemoryConnector,
}: {
  connector: Connector;
  context: ConnectorRowContext;
  toggleConnectorSelection: (connectorId: string) => void;
  onConnectMemoryConnector: (connectorId: string) => void;
}) {
  const t = useT();
  const state = connectorRowState({ connector, context });
  const { connected, selected } = state;
  return (
    <label
      className={`memory-connector-row${connected ? '' : ' is-disabled'}${selected ? ' is-selected' : ''}`}
      data-memory-connector-id={connector.id}
    >
      <input
        className="memory-connector-input"
        type="checkbox"
        checked={selected}
        disabled={!connected}
        aria-label={`${t('Use')} ${connector.name} ${t('for memory extraction')}`}
        onChange={() => toggleConnectorSelection(connector.id)}
      />
      <span className={`memory-connector-brand${selected ? ' is-selected' : ''}`}>
        <ConnectorLogo connectorId={connector.id} connectorName={connector.name} logoUrl={connector.logoUrl} size="sm" />
        <span className="memory-connector-selected-mark" aria-hidden="true">
          {selected ? <Icon name="check" size={13} /> : null}
        </span>
      </span>
      <span className="memory-connector-copy">
        <strong>{connector.name}</strong>
        <small>{connectorHint({ connector, state, t })}</small>
      </span>
      {connected ? (
        <MemoryConnectorPicker selected={selected} />
      ) : (
        <MemoryConnectButton connector={connector} state={state} onConnectMemoryConnector={onConnectMemoryConnector} />
      )}
    </label>
  );
}

