export const DEFAULT_FAILURE_SOUND_ID: SoundId = 'buzz';

import { useCallback, useEffect, useRef, useState } from "react";

export type SettingsRefreshScope = readonly string[] | null;
import { useSerialWrites } from "./use-serial-writes.hooks.js";
import { useSettlementGeneration } from "./use-settlement-generation.hooks.js";

/**
 * @file One settings-dialog tab's load/edit/debounced-save lifecycle,
 * generic over the tab's own config type.
 *
 * This was `SettingsUi.tsx`'s inline machinery when exactly one tab (Execution
 * mode) was mounted. It is extracted rather than copied because the logic is
 * subtle out of proportion to its size — successive audits have found FOUR
 * distinct data-loss bugs in it (see `saveTicket`, `hasUnsavedEdits`, `runSave`,
 * and `commits` below), and every one of those hazards is identical for every
 * tab. Duplicating it per tab would mean re-introducing all four bugs three
 * more times, and fixing them in three more places.
 *
 * The last two share one root cause worth stating plainly, because it is the
 * shape every future bug here will take: **a value read at schedule time is a
 * claim about the store that may already be false by the time the code using it
 * runs.** `runSave` fixes it for writes by reading the diff base at run time;
 * `commits` fixes it for reads by discarding a reload whose response predates a
 * write that landed while it was in flight. Anything added here that captures
 * `persisted` or `latest` across an `await` needs the same treatment.
 *
 * Each mounted tab owns one instance. They are independent by construction:
 * separate debounce timers, separate save chains, separate diff bases. The
 * only shared surface is the merged status the page chrome renders, which
 * `SettingsUi.tsx` derives.
 */

export type SaveState =
  | { status: "idle" }
  | { status: "saving" }
  | { status: "saved" }
  | { status: "error"; message: string };

/** Debounce for text fields: tabs are controlled and fire on every keystroke,
 *  and each ledger write is an append-only revision. Without this, typing into
 *  a textarea would write one revision per character. */
export const SAVE_DEBOUNCE_MS = 600;

/** Namespace-only notifications preserve the authorized re-read boundary; never carry values. */
export interface SettingsSliceRefreshPort {
  publish(required: { namespaces: readonly string[] }, optional?: Record<string, never>): void;
  subscribe(required: { listener: (scope: SettingsRefreshScope) => void }, optional?: Record<string, never>): () => void;
}

export interface SettingsSliceOptions<T> {
  /** Reads the persisted value. A rejection surfaces as `loadError` and the
   *  slice falls back to `defaultValue` — an unreadable setting shows defaults
   *  with a visible warning rather than blocking the whole dialog. */
  load: (required: Record<string, never>, optional?: Record<string, never>) => Promise<T>;
  /** Writes whatever changed between `next` and `previous`, returning the keys
   *  actually written (an empty array means "nothing to do", which the status
   *  indicator renders as idle rather than a misleading "Saved"). */
  save: (required: { next: T; previous: T }, optional?: Record<string, never>) => Promise<readonly string[]>;
  defaultValue: T;
  /**
   * Ledger namespaces this slice reads, so a refresh naming other namespaces
   * is ignored instead of costing a pointless reload.
   *
   * Omit to reload on EVERY refresh. That is the safe default in both
   * directions: a slice that forgets to declare its namespaces stays correct
   * (it just refetches more than it needs), whereas defaulting to "ignore
   * everything" would make a forgotten declaration silently stop updating —
   * the exact bug this feature exists to remove.
   */
  namespaces?: readonly string[];
  /** Use one port for publication and subscription, so successful writes refresh their own surface.
   * The host supplies a namespace-only bus; ports own their subscription cleanup. */
  refreshPort: SettingsSliceRefreshPort;
  /**
   * Reconciles a freshly loaded value against the operator's current in-memory value before
   * {@link SettingsSlice.refresh} lets it replace `value`/`persisted`/`latest`. Defaults to "the
   * loaded value wins outright" — correct for every field this slice actually round-trips through
   * `save`/`load`.
   *
   * Provide this when `T` carries a field `save`/`load` deliberately never touch (see
   * `execution-settings.ts`'s `reconcileExecutionConfigRefresh` for `byok.apiKey`, which `save`
   * never writes and `load` always returns empty). Without it, an external refresh — a same-tab
   * echo of this slice's OWN write arriving over the settings-changed SSE feed, another tab,
   * another operator — carries that field back at its "nothing here" default and silently
   * overwrites an operator's typed-but-unsaved edit to it. `runSave` cannot leak this on its own:
   * it never calls `setValue`. This path can, because replacing `value` with server truth is its
   * entire job.
   *
   * @param current - `latest.current` at the moment the reload settled — the newest value the
   *   operator has produced, saved or not.
   * @param loaded - What `load()` just returned — true server state for every field it manages.
   */
  reconcileRefresh?: (required: { current: T; loaded: T }, optional?: Record<string, never>) => T;
}

/**
 * Runs one save-chain link: calls `runSave`, then paints the ticket-owning outcome onto
 * `saveState` — unless a newer save has since taken the ticket (`currentTicket()` no longer matches
 * `ticket`), or the operator has queued another edit behind this one (`hasUnsavedEdits()`). Pulled
 * out of `onChange`'s debounce-timer closure (2026-08-06, complexity pass) — it was the deepest
 * nesting in this file, three closures in (`onChange` > the `setTimeout` callback > the
 * `saveChain.current.then(async () => …)` link) — so the ticket/staleness handling is directly
 * assertable against a fake `runSave`, without a real timer or save chain.
 *
 * The ref reads are passed as thunks rather than plain booleans specifically so this keeps the
 * original "read at run time, not schedule time" contract this whole file's header calls out:
 * `deps.currentTicket()`/`deps.hasUnsavedEdits()` are called from inside this function, at the same
 * points the inline version read `saveTicket.current`/`hasUnsavedEdits.current` directly, so a
 * ticket or edit that changes while `runSave` is in flight is still seen correctly.
 *
 * @param ticket - This link's own ticket, taken by the caller when the debounce timer fired.
 */
export async function commitQueuedSave(
  { ticket, deps }: { ticket: number; deps: {
    runSave: () => Promise<readonly string[]>;
    currentTicket: () => number;
    hasUnsavedEdits: () => boolean;
    setSaveState: (state: SaveState) => void;
  } },
  _options: Record<string, never> = {},
): Promise<void> {
  try {
    const written = await deps.runSave();
    if (deps.currentTicket() !== ticket) return;
    // A newer edit is already queued behind this one, so "Saved" would be a claim about state
    // that is not saved. Stay in "saving".
    if (deps.hasUnsavedEdits()) return;
    deps.setSaveState(written.length > 0 ? { status: "saved" } : { status: "idle" });
  } catch (error: unknown) {
    if (deps.currentTicket() !== ticket) return;
    deps.setSaveState({
      status: "error",
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

/**
 * Whether a background `refresh()` reload may still land, given what is true about the slice's
 * uncommitted-work state at the moment of the check.
 *
 * Pulled out of `refresh` (2026-08-06, complexity pass, third pass): the same four-flag shape is
 * checked TWICE inside `refresh` — once before the `load()` await (where `mounted`/`commitsUnchanged`
 * are trivially true, since nothing could have unmounted or committed a save before the function has
 * even started awaiting), once after (where all four are live) — and collapsing the check into one
 * named function removes the duplicated branch count rather than moving it. This does not change
 * WHEN any ref is read: every call site below still reads `timer.current`/`hasUnsavedEdits.current`/
 * `mounted.current`/`commits.current` at exactly the point in `refresh`'s own body the inline version
 * did, in the same tick — this function only names the boolean combination those reads produce. See
 * `refresh`'s own doc for why a re-check after the await is necessary at all.
 */
export function canAcceptRefresh(state: {
  timerPending: boolean;
  hasUnsavedEdits: boolean;
  mounted: boolean;
  commitsUnchanged: boolean;
}, _options: Record<string, never> = {}): boolean {
  return !state.timerPending && !state.hasUnsavedEdits && state.mounted && state.commitsUnchanged;
}

export interface SettingsSlice<T> {
  /** `null` until the initial load settles — the caller renders a loading state. */
  value: T | null;
  loadError: string | null;
  saveState: SaveState;
  onChange: (next: T) => void;
  /**
   * Re-reads the persisted value, discarding nothing.
   *
   * Wired to {@link subscribeToSettingsRefresh} automatically; exposed mainly so
   * a caller can force one. Declines while the operator has uncommitted work —
   * see the implementation for why that is a refusal rather than a merge.
   */
  refresh: () => Promise<void>;
}

/**
 * @complexity O(1) per edit — one debounce timer reset plus one link appended
 * to the save chain.
 *
 * @complexityExemption (2026-08-06, complexity pass, third pass; bar raised to ≤9/≤9 same day,
 * exemption reconfirmed against the new bar) **Score: this hook's own lexical scope is 1
 * cyclomatic / ~0 cognitive under ESLint — every closure inside it is independently ≤9/≤9 too
 * (`onChange`'s debounce callback is 2/1, the unmount-flush cleanup is 3/2, `refresh` is 5/4 as of
 * this pass — see below). What is exempted here is a DIFFERENT, unmeasurable-by-me number: the
 * dispatch brief's owner-tool score of 17/23, which rolls every nested closure's branches into the
 * hook's total. Bar: ≤9/≤9 on whichever view is scored — ESLint's view already clears it; the
 * owner-tool aggregate does not, and I have no local tool that reproduces that aggregate to
 * re-measure against the new bar.**
 *
 * Same shape as `use-assistant-chats.hooks.ts`'s `useAssistantChats` exemption — see that one for
 * the full reasoning. `commitQueuedSave` (first pass) and `canAcceptRefresh` (this pass, pulled out
 * of `refresh`'s two duplicated guard checks — see its own doc) are the two pieces of this hook's
 * logic that genuinely fit a top-level pure-function shape (0–4 plain params, no ref reads);
 * `refresh` itself dropped from 9/5 to 5/4 as a result, its own per-function score real progress,
 * not exempted. What remains (`runSave`/`onChange`/the unmount cleanup/the rest of `refresh`) each
 * reads or writes 3–6 of this hook's own refs (`io`, `persisted`, `latest`, `timer`,
 * `saveTicket`, `hasUnsavedEdits`, `commits`, `mounted`) plus the shared `writes` lane, and several of
 * them call each other
 * (`onChange` schedules a link that calls `runSave`; the unmount cleanup calls `runSave` directly),
 * so none of them can become a top-level function without threading that whole ref set through as a
 * parameter object. This file's own header states the reason that is dangerous here specifically:
 * "a value read at schedule time is a claim about the store that may already be false by the time
 * the code using it runs," and every ref above exists because an earlier version of exactly this
 * logic got that ordering wrong (four distinct data-loss bugs, per the header). A previous pass
 * already tried this kind of extraction on this file and the total was unchanged, 25 → 25 — the
 * honest reading of that result is that the remaining closures do not have a top-level-shaped cut
 * available at the risk level a time-boxed pass allows, not that the attempt was done wrong.
 * Declined for the remainder; flagged to the coordinator. See this session's report for the full
 * reasoning.
 */
export function useSettingsSlice<T>(options: SettingsSliceOptions<T>, _optional: Record<string, never> = {}): SettingsSlice<T> {
  const { defaultValue } = options;
  const [value, setValue] = useState<T | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [saveState, setSaveState] = useState<SaveState>({ status: "idle" });

  /** Guards `refresh`'s own `setValue`/`persisted`/`latest` write against a second background
   *  refresh started after it: `canAcceptRefresh`'s `commitsUnchanged` check cannot tell two
   *  refreshes apart when no save happens between them (both sample the same `commits.current`),
   *  so without this an older refresh call that happens to SETTLE last could still land over a
   *  newer one's result (S2, plan-components.md 2026-09-20; two rapid SSE frames from another
   *  tab's writes is the trigger). Same guard `use-admin-execution-credential.hooks.ts`'s `refresh`
   *  and `use-admin-locale.hooks.ts`'s `fetchLocale` already use for the identical shape. */
  const refreshSettlement = useSettlementGeneration();

  /** `load`/`save` are usually inline arrows at the call site, so a new
   *  identity arrives on every render. Holding them in a ref keeps the effect
   *  and callback below from re-running (and re-loading, and dropping pending
   *  timers) once per render. */
  const io = useRef(options);
  io.current = options;

  /** Last value known to be persisted — the diff base handed to `save`. */
  const persisted = useRef<T>(defaultValue);

  /** The newest value the operator has produced, saved or not. A queued save
   *  writes THIS rather than whatever was current when it was scheduled, so a
   *  save that waited behind another still persists the latest state instead
   *  of resurrecting an intermediate one. */
  const latest = useRef<T>(defaultValue);

  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  /**
   * Saves run strictly one at a time, queued through this lane.
   *
   * The debounce alone does NOT prevent overlap: it only cancels a save that
   * has not STARTED. Once one is in flight, the next edit schedules a fresh
   * timer that can fire while the first is still running, and then two saves
   * race — their per-key writes interleave (so the ledger can end on the older
   * value), and both diff against the same `persisted` base, which the slower
   * one then overwrites on completion. That leaves the diff base claiming a
   * value was persisted that never was, so the next edit skips writing the
   * fields it thinks are already saved.
   */
  const writes = useSerialWrites();

  /** Monotonic ticket, so only the newest save may write the status
   *  indicator. Without it a slow earlier save resolving last would paint
   *  "Saved" over a newer save's error, or vice versa. */
  const saveTicket = useRef(0);

  /**
   * True whenever `latest` has moved ahead of `persisted` — i.e. the operator
   * has edited something no save has committed yet.
   *
   * The ticket alone does NOT cover this. A ticket is only taken when a
   * DEBOUNCE TIMER FIRES, so an edit made while an earlier save is still in
   * flight has no ticket yet: the in-flight save still owns the newest one,
   * completes, and paints "Saved" over changes that are not saved at all. If
   * the operator then navigates away, unmount clears the pending timer and
   * those edits are gone — with the UI's last word having been "Saved".
   */
  const hasUnsavedEdits = useRef(false);

  /**
   * Bumped every time a save commits and advances `persisted`.
   *
   * `refresh` samples it before its `load()` round trip and discards the
   * response if it moved. The two flag checks cannot cover this on their own:
   * `timer` and `hasUnsavedEdits` describe work that is still OUTSTANDING, and
   * a save that both started and finished inside the reload's await window
   * clears them, so a response that predates that write passes every check.
   * Letting it through does not merely repaint a stale value — it installs it
   * as the diff base, so the next edit diffs against a value the store never
   * held and skips writing the fields that differ.
   */
  const commits = useRef(0);

  /** Guards every post-await `setState` in {@link refresh}, which — unlike the
   *  mount load — can be invoked at any time by an external publisher. */
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  // `defaultValue` is a module-level constant at every call site; re-running
  // this on a new identity would re-issue the load and clobber live edits.
  // biome-ignore lint/correctness/useExhaustiveDependencies: `defaultValue` is a module-level constant; re-running on a new identity would re-issue the load and clobber live edits.
  useEffect(() => {
    let alive = true;
    io.current
      .load({}, {})
      .then((loaded) => {
        if (!alive) return;
        // `persisted` always takes the raw load, same as `refresh()` — it is the diff base the next
        // save diffs against, and the server's real state is a strictly better base than the
        // never-actually-persisted `defaultValue` this ref started at, whether or not the operator
        // has since edited.
        persisted.current = loaded;
        // Guards the same hazard `refresh()` guards via `canAcceptRefresh`'s `hasUnsavedEdits` check,
        // on the OTHER load path: `onChange` has no documented precondition requiring `value` to be
        // non-null first, so nothing stops an edit from landing before this initial `load()` settles.
        // Without this check, that edit is silently overwritten the instant the response arrives —
        // the same class of data loss this file's four prior audited bugs all belong to.
        if (hasUnsavedEdits.current) return;
        latest.current = loaded;
        setValue(loaded);
      })
      .catch((error: unknown) => {
        if (!alive) return;
        setLoadError(error instanceof Error ? error.message : String(error));
        if (hasUnsavedEdits.current) return;
        setValue(defaultValue);
      });
    return () => {
      alive = false;
    };
  }, []);

  /**
   * The only place a save is ever issued.
   *
   * Both the target and the diff base are read at RUN time, never at schedule
   * time. By the time a chained link runs, an earlier save may already have
   * advanced `persisted` and the operator may have edited further, so anything
   * captured when the link was queued is potentially a lie about the store.
   *
   * This exists as one function rather than two call sites because the second
   * call site is exactly where that invariant was lost: the unmount flush used
   * to snapshot both values as it queued itself behind an in-flight save, so
   * edit A→B, revert B→A, unmount produced `save(A, A)` — an empty diff — and
   * the revert was dropped while the store kept B. Sharing the runner makes the
   * rule structural instead of something each caller has to remember.
   */
  const runSave = useCallback(async (): Promise<readonly string[]> => {
    const target = latest.current;
    const written = await io.current.save({ next: target, previous: persisted.current }, {});
    // `persisted` is deliberately advanced only here, after a resolved save, so
    // a rejection leaves the base alone and the next save re-attempts the
    // fields this one could not write.
    persisted.current = target;
    commits.current += 1;
    // Only clear the flag if nothing was edited WHILE this save ran.
    if (latest.current === target) hasUnsavedEdits.current = false;
    // Notify same-tab siblings this slice has no direct connection to — same rationale
    // `settings-refresh-bus.ts`'s own doc comment gives for `AssistantDock`: this slice and
    // whatever else reads this namespace (e.g. `useAdminLocale()`, read by ~30 screens outside the
    // Settings dialog for `core.language`) are unrelated subtrees under `App.tsx` with no shared
    // state. Without this, a language switch only reached OTHER tabs via SSE — the tab that made
    // the change never re-read its own write, so it looked "stuck" until a hard reload. Scoped to
    // this slice's own declared `namespaces`, so an unrelated slice's save doesn't trigger a
    // pointless refetch elsewhere; a slice that never declared `namespaces` publishes nothing,
    // matching that it never subscribed to anything either.
    if (io.current.namespaces && io.current.namespaces.length > 0) {
      io.current.refreshPort.publish({ namespaces: io.current.namespaces }, {});
    }
    return written;
  }, []);

  // On unmount, don't just drop a debounced edit — run it. Cancelling the
  // timer silently discards whatever the operator typed in the last 600ms.
  useEffect(
    () => () => {
      if (!timer.current) return;
      clearTimeout(timer.current);
      if (!hasUnsavedEdits.current) return;
      // Fire-and-forget: the component is going away, so there is no status
      // left to paint. The write itself still has to happen — through the same
      // lane as the debounce path, so it diffs against the base that is
      // current when it RUNS, not the one that was current when it was queued.
      void writes.run({ task: () =>
        runSave().then(
          () => {},
          // No view remains to show the failure; settings and native errors may contain secrets.
          () => { console.error('[settings] Final save failed after unmount.'); },
        ) },
      );
    },
    [runSave, writes],
  );

  const onChange = useCallback((next: T) => {
    setValue(next);
    latest.current = next;
    hasUnsavedEdits.current = true;
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      // Cleared as the timer FIRES, so `timer.current` means "a debounce is still pending" rather
      // than "one was ever scheduled". The unmount flush below already pairs it with
      // `hasUnsavedEdits`, so it tolerated a stale handle; `refresh` reads it alone as the
      // "operator has work in flight" signal, and a handle that never cleared would refuse every
      // external refresh for the rest of the component's life after the first keystroke.
      timer.current = null;
      saveTicket.current += 1;
      const ticket = saveTicket.current;
      setSaveState({ status: "saving" });
      void writes.run({ task: () =>
        commitQueuedSave({ ticket, deps: {
          runSave,
          currentTicket: () => saveTicket.current,
          hasUnsavedEdits: () => hasUnsavedEdits.current,
          setSaveState,
        } }, {}) },
      );
    }, SAVE_DEBOUNCE_MS);
  }, [runSave, writes]);

  /**
   * Re-reads the persisted value on an external notification.
   *
   * **Refuses whenever the operator has uncommitted work**, rather than merging. Three states count
   * as uncommitted: a pending debounce timer, `hasUnsavedEdits`, and a non-idle save. Overwriting
   * any of them replaces what the operator typed with a value from somewhere else, mid-keystroke —
   * data loss, and the same class of bug the audit already found twice in this file. Refusing costs
   * only a missed update, and the operator's own save re-establishes agreement a moment later.
   *
   * The check runs AGAIN after the await: `load()` is a network round trip, and an edit begun while
   * it was in flight would otherwise be clobbered by a response that predates it.
   *
   * Re-checking the flags is necessary but NOT sufficient, which is why {@link commits} is sampled
   * too. Both flags describe work that is still outstanding, so a save that started and finished
   * entirely within the await window leaves them clear and the stale response sails through — see
   * the counter's own doc for why that is worse than a wrong repaint.
   *
   * A failed reload is swallowed on purpose. This is a background refresh the operator never asked
   * for; surfacing `loadError` here would replace a working panel with an error state because of a
   * transient blip. The mount load still reports its failures.
   */
  const refresh = useCallback(async () => {
    if (
      !canAcceptRefresh({
        timerPending: timer.current !== null,
        hasUnsavedEdits: hasUnsavedEdits.current,
        mounted: true,
        commitsUnchanged: true,
      })
    ) {
      return;
    }
    const seenCommits = commits.current;
    const generation = refreshSettlement.next();
    let loaded: T;
    try {
      loaded = await io.current.load({}, {});
    } catch {
      return;
    }
    if (
      !refreshSettlement.isCurrent({ generation }) ||
      !canAcceptRefresh({
        timerPending: timer.current !== null,
        hasUnsavedEdits: hasUnsavedEdits.current,
        mounted: mounted.current,
        commitsUnchanged: commits.current === seenCommits,
      })
    ) {
      return;
    }
    // `persisted` tracks what `load`/`save` actually manage, so it takes the RAW reload — a
    // reconciled field like a never-persisted API key has no business in the diff base `save` will
    // next diff against. `latest`/`value` are what the operator sees and edits next, so THEY take
    // the reconciled result.
    const reconciled = io.current.reconcileRefresh ? io.current.reconcileRefresh({ current: latest.current, loaded }, {}) : loaded;
    persisted.current = loaded;
    latest.current = reconciled;
    setValue(reconciled);
  }, []);

  /**
   * Subscribes to out-of-band changes — an assistant run that wrote a setting, or an SSE frame from
   * a write in another tab. `namespaces` narrows which notifications matter; see the option's doc
   * for why omitting it means "refresh on everything" rather than "never".
   */
  const refreshPort = options.refreshPort;
  useEffect(() => {
    return refreshPort.subscribe({ listener: (scope) => {
      const mine = io.current.namespaces;
      if (scope && mine && !mine.some((ns) => scope.includes(ns))) return;
      void refresh();
    } }, {});
  }, [refresh, refreshPort]);

  return { value, loadError, saveState, onChange, refresh };
}

/**
 * Collapses several slices' save states into the single one the page chrome
 * renders.
 *
 * Precedence is error > saving > saved > idle, and it is deliberate: an error
 * is the only state the operator must act on, so it must not be hidden by
 * another tab's cheerful "Saved". "Saving" outranks "saved" for the same
 * reason in miniature — while anything is still in flight, claiming everything
 * is saved is false.
 */
export function mergeSaveStates({ states }: { states: readonly SaveState[] }, _options: Record<string, never> = {}): SaveState {
  const failed = states.find((state) => state.status === "error");
  if (failed) return failed;
  if (states.some((state) => state.status === "saving")) return { status: "saving" };
  if (states.some((state) => state.status === "saved")) return { status: "saved" };
  return { status: "idle" };
}

/**
 * Reference adapters mapping two independently-shaped "agent run" inputs onto
 * the generic `ProgressCardData` shape. The input types here are narrow,
 * locally-declared structural subsets (`*Like`) rather than real imports of
 * an external product's contracts package — this package has no dependency
 * on that package, and any host whose real types are a structural superset
 * can pass them in directly. Field-level provenance and what was
 * deliberately dropped (a Bash `rm`-command heuristic from the file-ops
 * derivation) are documented in `packages/ui/archived provenance ledger`.
 *
 * These adapters are shipped as documented reference material, not as the
 * package's primary port surface — a host with its own run/job shape maps
 * directly onto `ProgressCardData` instead of going through these.
 */
import type { ProgressCardItem, ProgressCardData, ProgressStatus } from './types.js';
import { clampProgressPercent } from './rules.js';

// ---------------------------------------------------------------------------
// Agent-event primitives
// ---------------------------------------------------------------------------

export interface AgentToolUseEventLike {
  kind: 'tool_use';
  id: string;
  name: string;
  input: unknown;
}

export interface AgentToolResultEventLike {
  kind: 'tool_result';
  toolUseId: string;
  isError?: boolean;
}

export interface AgentStatusEventLike {
  kind: 'status';
  label: string;
  detail?: string;
}

export interface AgentOtherEventLike {
  kind: string;
}

export type AgentEventLike =
  | AgentToolUseEventLike
  | AgentToolResultEventLike
  | AgentStatusEventLike
  | AgentOtherEventLike;

function isToolUseEvent(event: AgentEventLike): event is AgentToolUseEventLike {
  return event.kind === 'tool_use' && 'id' in event && 'name' in event;
}

function isToolResultEvent(event: AgentEventLike): event is AgentToolResultEventLike {
  return event.kind === 'tool_result' && 'toolUseId' in event;
}

function isStatusEvent(event: AgentEventLike): event is AgentStatusEventLike {
  return event.kind === 'status' && 'label' in event;
}

// ---------------------------------------------------------------------------
// To-do/step derivation (ported from the source `runtime/todos.ts`)
// ---------------------------------------------------------------------------

export type TodoStatusLike = 'pending' | 'in_progress' | 'completed' | 'stopped';

export interface TodoItemLike {
  content: string;
  status: TodoStatusLike;
}

const TODO_WRITE_TOOL_NAMES = new Set(['TodoWrite', 'todowrite', 'todo_write', 'update_plan']);

export function isTodoWriteToolName(name: string): boolean {
  return TODO_WRITE_TOOL_NAMES.has(name);
}

function normalizeTodoStatus(status: unknown): TodoStatusLike {
  if (status === 'completed' || status === 'in_progress' || status === 'stopped') return status;
  if (status === 'cancelled' || status === 'canceled' || status === 'failed') return 'stopped';
  return 'pending';
}

export function parseTodoWriteInput(input: unknown): TodoItemLike[] {
  if (!input || typeof input !== 'object') return [];
  const record = input as { todos?: unknown; plan?: unknown };
  const rawItems = [record.todos, record.plan].find(Array.isArray) ?? [];
  return rawItems
    .map((todo): TodoItemLike | null => {
      if (!todo || typeof todo !== 'object') return null;
      const todoRecord = todo as Record<string, unknown>;
      let content = '';
      for (const key of ['content', 'step', 'description', 'label', 'text'] as const) {
        if (typeof todoRecord[key] === 'string') {
          content = todoRecord[key] as string;
          break;
        }
      }
      if (!content) return null;
      return { content, status: normalizeTodoStatus(todoRecord.status) };
    })
    .filter((todo): todo is TodoItemLike => todo !== null);
}

export function latestTodosFromAgentEvents(events: AgentEventLike[] | undefined): TodoItemLike[] {
  if (!events) return [];
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (!event || !isToolUseEvent(event) || !isTodoWriteToolName(event.name)) continue;
    return parseTodoWriteInput(event.input);
  }
  return [];
}

export function latestStatusDetailFromAgentEvents(events: AgentEventLike[]): string | null {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (!event || !isStatusEvent(event)) continue;
    const label = event.label.replace(/[_-]/g, ' ');
    return event.detail ? `${label}: ${event.detail}` : label;
  }
  return null;
}

function todoStatusToProgressStatus(status: TodoStatusLike): ProgressStatus {
  if (status === 'completed') return 'succeeded';
  if (status === 'in_progress') return 'running';
  if (status === 'stopped') return 'failed';
  return 'pending';
}

// ---------------------------------------------------------------------------
// File-op derivation (ported from the source `runtime/file-ops.ts` and
// `runtime/tool-events.ts`, minus the Bash `rm`-command detection heuristic —
// see archived provenance ledger)
// ---------------------------------------------------------------------------

export type FileOpStatusLike = 'running' | 'done' | 'error';
export type FileOpKindLike = 'read' | 'write' | 'edit' | 'delete';

export interface FileOpEntryLike {
  path: string;
  fullPath: string;
  ops: FileOpKindLike[];
  status: FileOpStatusLike;
}

const READ_TOOL_NAMES = new Set(['Read', 'read_file']);
const WRITE_TOOL_NAMES = new Set(['Write', 'create_file']);
const EDIT_TOOL_NAMES = new Set(['Edit', 'str_replace_edit', 'MultiEdit', 'multi_edit']);
const DELETE_TOOL_NAMES = new Set(['Delete', 'delete', 'delete_file', 'remove_file', 'rm_file', 'unlink_file']);

function classifyFileOp(name: string): FileOpKindLike | null {
  if (READ_TOOL_NAMES.has(name)) return 'read';
  if (WRITE_TOOL_NAMES.has(name)) return 'write';
  if (EDIT_TOOL_NAMES.has(name)) return 'edit';
  if (DELETE_TOOL_NAMES.has(name)) return 'delete';
  return null;
}

function extractFileOpPath(input: unknown): string | null {
  if (!input || typeof input !== 'object') return null;
  const record = input as Record<string, unknown>;
  const filePath =
    record.file_path ?? record.filePath ?? record.path ?? record.filename ?? record.target_path ?? record.targetPath;
  return typeof filePath === 'string' && filePath.trim() ? filePath : null;
}

function basename(path: string): string {
  const segments = path.split(/[\\/]/).filter((segment) => segment.length > 0);
  return segments[segments.length - 1] ?? path;
}

function mergeFileOpStatus(a: FileOpStatusLike, b: FileOpStatusLike): FileOpStatusLike {
  if (a === 'error' || b === 'error') return 'error';
  if (a === 'running' || b === 'running') return 'running';
  return 'done';
}

/** Drops duplicate `tool_use` events sharing an id, keeping the run's final
 *  attempt for each — a retried tool call otherwise double-counts. */
export function dedupeToolUsesById(events: AgentEventLike[] | undefined): AgentEventLike[] {
  if (!events || events.length === 0) return [];
  const seen = new Set<string>();
  let deduped: AgentEventLike[] | null = null;
  for (let index = 0; index < events.length; index += 1) {
    const event = events[index]!;
    if (!isToolUseEvent(event)) {
      deduped?.push(event);
    } else if (seen.has(event.id)) {
      deduped ??= events.slice(0, index);
    } else {
      seen.add(event.id);
      deduped?.push(event);
    }
  }
  return deduped ?? events;
}

function fileOpFromAgentEvent(
  { event, resultByToolUseId }: {
    event: AgentEventLike;
    resultByToolUseId: ReadonlyMap<string, AgentToolResultEventLike>;
  },
  _options: Record<string, never> = {},
): { fullPath: string; kind: FileOpKindLike; status: FileOpStatusLike } | null {
  if (!isToolUseEvent(event)) return null;
  const kind = classifyFileOp(event.name);
  if (!kind) return null;
  const fullPath = extractFileOpPath(event.input);
  if (!fullPath) return null;
  const result = resultByToolUseId.get(event.id);
  let status: FileOpStatusLike = 'running';
  if (result !== undefined) status = result.isError ? 'error' : 'done';
  return { fullPath, kind, status };
}

export function deriveFileOpsFromAgentEvents(events: AgentEventLike[] | undefined): FileOpEntryLike[] {
  if (!events || events.length === 0) return [];
  const dedupedEvents = dedupeToolUsesById(events);
  const resultByToolUseId = new Map(
    dedupedEvents.filter(isToolResultEvent).map((event) => [event.toolUseId, event] as const),
  );
  const byPath = new Map<string, FileOpEntryLike>();
  for (const event of dedupedEvents) {
    const entry = fileOpFromAgentEvent({ event, resultByToolUseId });
    if (!entry) continue;
    const existing = byPath.get(entry.fullPath);
    if (existing) {
      if (!existing.ops.includes(entry.kind)) existing.ops.push(entry.kind);
      existing.status = mergeFileOpStatus(existing.status, entry.status);
      continue;
    }
    byPath.set(entry.fullPath, {
      path: basename(entry.fullPath),
      fullPath: entry.fullPath,
      ops: [entry.kind],
      status: entry.status,
    });
  }
  return Array.from(byPath.values());
}

function fileOpStatusToProgressStatus(status: FileOpStatusLike): ProgressStatus {
  if (status === 'error') return 'failed';
  if (status === 'running') return 'running';
  return 'succeeded';
}

// ---------------------------------------------------------------------------
// Adapter 1 — ported from `WorkspaceActivityCard`
// ---------------------------------------------------------------------------

export interface ChatActivityLike {
  events?: AgentEventLike[];
  runStatus?: 'queued' | 'running' | 'succeeded' | 'failed' | 'canceled';
}

export interface ChatActivityToProgressCardOptions {
  /** `ProgressCardData.id` — the source has no natural id of its own for
   *  this view (it's derived from a chat message + a live/absent run), so
   *  the host supplies one. */
  id: string;
  /** Whether a run is actively streaming right now, independent of
   *  `runStatus` (mirrors the source's separate `active` prop). */
  active: boolean;
}

function chatActivityStatus(message: ChatActivityLike | null, active: boolean): ProgressStatus {
  if (active || message?.runStatus === 'queued' || message?.runStatus === 'running') return 'running';
  if (message?.runStatus === 'failed' || message?.runStatus === 'canceled') return 'failed';
  return 'succeeded';
}

function chatActivityProgress(status: ProgressStatus, todos: TodoItemLike[], fileOps: FileOpEntryLike[]): number {
  if (status === 'succeeded' || status === 'failed') return 100;
  if (todos.length > 0) {
    const completed = todos.filter((todo) => todo.status === 'completed').length;
    const inProgress = todos.some((todo) => todo.status === 'in_progress') ? 0.5 : 0;
    return Math.max(18, Math.min(92, Math.round(((completed + inProgress) / todos.length) * 100)));
  }
  if (fileOps.some((entry) => entry.ops.includes('write') || entry.ops.includes('edit'))) return 72;
  if (fileOps.length > 0) return 38;
  return 18;
}

function fallbackChatActivitySteps(status: ProgressStatus, fileOps: FileOpEntryLike[]): ProgressCardItem[] {
  const hasRead = fileOps.some((entry) => entry.ops.includes('read'));
  const hasMutation = fileOps.some((entry) => entry.ops.includes('write') || entry.ops.includes('edit'));
  const hasError = status === 'failed' || fileOps.some((entry) => entry.status === 'error');
  return [
    {
      id: 'read-current-state',
      label: 'Read current state',
      status: fallbackReadStatus({ status, done: hasRead || hasMutation }),
    },
    {
      id: 'update-files',
      label: 'Update files',
      status: fallbackUpdateStatus({ status, fileOps, hasError, hasMutation }),
    },
    {
      id: 'finalize',
      label: 'Finalize',
      status: status === 'succeeded' || status === 'failed' ? status : 'pending',
    },
  ];
}

function fallbackReadStatus({ status, done }: { status: ProgressStatus; done: boolean }): ProgressStatus {
  if (done || status === 'succeeded') return 'succeeded';
  return status === 'running' ? 'running' : 'pending';
}

function fallbackUpdateStatus(
  { status, fileOps, hasError, hasMutation }: {
    status: ProgressStatus;
    fileOps: FileOpEntryLike[];
    hasError: boolean;
    hasMutation: boolean;
  },
  _options: Record<string, never> = {},
): ProgressStatus {
  if (hasError) return 'failed';
  if (hasMutation) return fileOps.some((entry) => entry.status === 'running') ? 'running' : 'succeeded';
  return status === 'running' ? 'pending' : 'succeeded';
}

function chatActivitySteps(
  { todos, status, fileOps }: { todos: TodoItemLike[]; status: ProgressStatus; fileOps: FileOpEntryLike[] },
  _options: Record<string, never> = {},
): ProgressCardItem[] {
  if (todos.length === 0) return fallbackChatActivitySteps(status, fileOps);
  return todos.map((todo, index) => ({
    id: `${todo.content}-${index}`,
    label: todo.content,
    status: todoStatusToProgressStatus(todo.status),
  }));
}

/** Maps a chat message's agent-event stream onto `ProgressCardData`. Returns
 *  `null` when there's nothing worth showing (mirrors the source's own
 *  `hasActivity` early-return — a message with no run, no todos, no file
 *  ops, no status detail, and not currently active renders nothing). */
export function chatActivityToProgressCard(
  message: ChatActivityLike | null,
  options: ChatActivityToProgressCardOptions,
): ProgressCardData | null {
  const events = message?.events ?? [];
  const todos = latestTodosFromAgentEvents(events);
  const fileOps = deriveFileOpsFromAgentEvents(events);
  const status = chatActivityStatus(message, options.active);
  const statusDetail = latestStatusDetailFromAgentEvents(events);
  const hasActivity =
    options.active || todos.length > 0 || fileOps.length > 0 || statusDetail !== null || status === 'failed';
  if (!hasActivity) return null;

  const steps = chatActivitySteps({ todos, status, fileOps });

  const secondaryItems: ProgressCardItem[] = fileOps.map((entry) => ({
    id: entry.fullPath,
    label: entry.path,
    status: fileOpStatusToProgressStatus(entry.status),
  }));

  return {
    id: options.id,
    status,
    ...(statusDetail !== null ? { detail: statusDetail } : {}),
    progress: chatActivityProgress(status, todos, fileOps),
    steps,
    ...(secondaryItems.length > 0 ? { secondaryItems } : {}),
  };
}

// ---------------------------------------------------------------------------
// Adapter 2 — ported from `GenerationStatusCard`
// ---------------------------------------------------------------------------

export type DesignSystemGenerationJobStatusLike = 'queued' | 'running' | 'succeeded' | 'failed' | 'canceled';

export interface DesignSystemGenerationJobStepLike {
  id: string;
  title: string;
  status: ProgressStatus;
}

export interface DesignSystemGenerationJobLike {
  id: string;
  status: DesignSystemGenerationJobStatusLike;
  /** 0-100. */
  progress: number;
  steps: DesignSystemGenerationJobStepLike[];
  message?: string;
}

function designSystemGenerationJobStatusToProgressStatus(status: DesignSystemGenerationJobStatusLike): ProgressStatus {
  if (status === 'queued') return 'pending';
  if (status === 'running') return 'running';
  if (status === 'succeeded') return 'succeeded';
  return 'failed'; // 'failed' | 'canceled' — both terminal-non-success, same as the chat-activity adapter
}

/** Maps a generation/revision job onto `ProgressCardData`. Unlike the
 *  chat-activity adapter, this one always has something to show — the
 *  source component is only ever mounted when a job exists. */
export function designSystemGenerationJobToProgressCard(job: DesignSystemGenerationJobLike): ProgressCardData {
  return {
    id: job.id,
    status: designSystemGenerationJobStatusToProgressStatus(job.status),
    ...(job.message !== undefined ? { detail: job.message } : {}),
    progress: clampProgressPercent(job.progress),
    steps: job.steps.map((step) => ({ id: step.id, label: step.title, status: step.status })),
  };
}

/**
 * The DOM-enhancement toolkit that makes embedding a third-party editor
 * (Excalidraw exposes no hooks for any of this) feel native: tooltip
 * injection, context-menu simplification, DOM text-override application,
 * toast rewriting, and modal/portal enhancement. Every function here takes
 * whatever root element(s) it needs to operate on as parameters — none of
 * it reaches for a module-level singleton — so it stays independently
 * unit-testable against hand-built DOM fixtures.
 *
 * This file intentionally touches `document`/`window`/global DOM APIs
 * directly rather than going through `dependencies.ts` (unlike a
 * transport/fetch concern): DOM manipulation of a mounted third-party
 * library's own rendered output *is* this feature's entire purpose, not an
 * external dependency to abstract away. Excalidraw itself is still bound
 * through `ports.ts`/`dependencies.ts` (see those files).
 */
import {
  SKETCH_CONTEXT_MENU_MARGIN,
  SKETCH_TEXT_OVERRIDE_ATTRS,
} from './constants.js';
import {
  isExcalidrawUnableToEmbedToast,
  normalizeTooltipLabel,
  orderContextMenuActions,
  resolveDefaultSketchToolColor,
  translateDomTextValue,
} from './rules.js';
import type { SketchDomTextOverrides, SketchTooltipLabels, SketchTooltipTarget } from './types.js';

export function readExcalidrawTheme(): 'light' | 'dark' {
  if (typeof document === 'undefined') return 'light';
  return document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
}

export function readDefaultSketchToolColor(): string {
  if (typeof document === 'undefined') return resolveDefaultSketchToolColor(null, false);
  const theme = document.documentElement.getAttribute('data-theme');
  const prefersDark = window.matchMedia?.('(prefers-color-scheme: dark)').matches === true;
  return resolveDefaultSketchToolColor(theme, prefersDark);
}

export function setTooltipAttribute(target: HTMLElement, name: string, value: string): void {
  if (target.getAttribute(name) === value) return;
  target.setAttribute(name, value);
}

function resolveTooltipTarget(trigger: HTMLElement, entry: SketchTooltipTarget): HTMLElement | null {
  return entry.target === 'closest-label' ? trigger.closest<HTMLElement>('label') : trigger;
}

function decorateTooltipTarget({
  target,
  trigger,
  label,
  placement,
}: {
  target: HTMLElement;
  trigger: HTMLElement;
  label: string;
  placement: string;
}): void {
  setTooltipAttribute(target, 'data-tooltip', label);
  setTooltipAttribute(target, 'data-tooltip-placement', placement);
  if (!target.classList.contains('jini-tooltip')) target.classList.add('jini-tooltip');
  setTooltipAttribute(trigger, 'aria-label', label);
}

/**
 * Drives ONLY the shared `TooltipLayer` contract (`.jini-tooltip[data-tooltip]`):
 * it renders a single styled, viewport-aware bubble and suppresses the
 * native browser `title` on hover. Painting a separate `::after`/`title`
 * on top of it produces duplicate tooltips.
 */
export function applySketchEditorTooltips(
  root: HTMLElement,
  labels: SketchTooltipLabels,
  targets: readonly SketchTooltipTarget[],
): void {
  const decorated = new Set<HTMLElement>();
  for (const entry of targets) {
    const triggers = Array.from(root.querySelectorAll<HTMLElement>(entry.selector));
    const label = normalizeTooltipLabel(labels[entry.label]);
    if (!label) continue;
    for (const trigger of triggers) {
      const target = resolveTooltipTarget(trigger, entry);
      if (!target || decorated.has(target)) continue;
      decorateTooltipTarget({ target, trigger, label, placement: entry.placement ?? 'bottom' });
      decorated.add(target);
    }
  }
}

function readPopoverOrigin(popover: HTMLElement, rect: DOMRect): { left: number; top: number } | null {
  const left = Number.parseFloat(popover.style.left || `${rect.left}`);
  const top = Number.parseFloat(popover.style.top || `${rect.top}`);
  return Number.isFinite(left) && Number.isFinite(top) ? { left, top } : null;
}

/** Shifts `value` so the `[start, end]` span fits inside `[min, max]`: the
 *  overflow past `max` is subtracted first, then the underflow before `min`
 *  is added, in that order. */
function clampAxis(
  { value, start, end }: { value: number; start: number; end: number },
  { min, max }: { min: number; max: number },
): number {
  let next = value;
  if (end > max) next -= end - max;
  if (start < min) next += min - start;
  return next;
}

function writePopoverCoordinate({ popover, side, next }: { popover: HTMLElement; side: 'left' | 'top'; next: number }): void {
  if (next !== Number.parseFloat(popover.style[side] || 'NaN')) popover.style[side] = `${Math.max(0, Math.round(next))}px`;
}

export function clampSketchContextPopover(popover: HTMLElement, viewportRoot: HTMLElement): void {
  const viewportRect = viewportRoot.getBoundingClientRect();
  const rect = popover.getBoundingClientRect();
  if (!rect.width || !rect.height) return;

  const origin = readPopoverOrigin(popover, rect);
  if (!origin) return;

  const nextLeft = clampAxis(
    { value: origin.left, start: rect.left, end: rect.right },
    { min: viewportRect.left + SKETCH_CONTEXT_MENU_MARGIN, max: viewportRect.right - SKETCH_CONTEXT_MENU_MARGIN },
  );
  const nextTop = clampAxis(
    { value: origin.top, start: rect.top, end: rect.bottom },
    { min: viewportRect.top + SKETCH_CONTEXT_MENU_MARGIN, max: viewportRect.bottom - SKETCH_CONTEXT_MENU_MARGIN },
  );

  writePopoverCoordinate({ popover, side: 'left', next: nextLeft });
  writePopoverCoordinate({ popover, side: 'top', next: nextTop });
}

function hasRecognizedContextMenuAction(menu: HTMLUListElement, recognized: ReadonlySet<string>): boolean {
  // `li[data-testid]` is an attribute selector: every `item` it matches is
  // guaranteed to carry the attribute, so `getAttribute` can't return null
  // here — only typed nullable because `getAttribute` is nullable in general.
  return Array.from(menu.querySelectorAll<HTMLLIElement>('li[data-testid]')).some((item) =>
    recognized.has(item.getAttribute('data-testid')!),
  );
}

/** Removes every `<hr>` and every non-allow-listed `<li>` from `menu`,
 *  returning the surviving `<li>`s keyed by action name. */
function pruneContextMenuItems(menu: HTMLUListElement, allowed: ReadonlySet<string>): Map<string, HTMLLIElement> {
  const byAction = new Map<string, HTMLLIElement>();
  for (const child of Array.from(menu.children)) {
    if (child instanceof HTMLHRElement) {
      child.remove();
      continue;
    }
    if (!(child instanceof HTMLLIElement)) continue;
    const actionName = child.getAttribute('data-testid') ?? '';
    if (!allowed.has(actionName)) {
      child.remove();
      continue;
    }
    byAction.set(actionName, child);
  }
  return byAction;
}

function isContextMenuOrdered(menu: HTMLUListElement, orderedItems: readonly HTMLLIElement[]): boolean {
  const currentItems = Array.from(menu.children).filter(
    (child): child is HTMLLIElement => child instanceof HTMLLIElement,
  );
  return currentItems.length === orderedItems.length && currentItems.every((item, index) => item === orderedItems[index]);
}

function simplifyContextMenu(
  { menu, viewportRoot, allowList }: { menu: HTMLUListElement; viewportRoot: HTMLElement; allowList: readonly string[] },
  { allowed, recognized }: { allowed: ReadonlySet<string>; recognized: ReadonlySet<string> },
): void {
  // `menu` was found via `root.querySelectorAll(...)`, so it is always a
  // strict descendant of `root` and therefore always has a parent element
  // — `.parentElement` is only typed nullable because `Element` itself
  // permits detached nodes, not because that's reachable here.
  const popover = menu.closest<HTMLElement>('.popover') ?? menu.parentElement!;
  if (!hasRecognizedContextMenuAction(menu, recognized)) return;

  menu.classList.add('jini-sketch-context-menu');
  popover.classList.add('jini-sketch-context-popover');

  const byAction = pruneContextMenuItems(menu, allowed);
  // `orderContextMenuActions` only returns names present in `byAction`'s
  // keys, so every lookup here is defined.
  const orderedItems = orderContextMenuActions(Array.from(byAction.keys()), allowList).map((action) => byAction.get(action)!);
  if (orderedItems.length === 0) {
    popover.remove();
    return;
  }
  // Only touch the DOM when the order is actually wrong. This runs on
  // every MutationObserver tick, and re-appending nodes already in place
  // detaches/re-inserts them each frame; because that re-triggers the
  // observer, an unconditional reorder becomes a self-sustaining
  // per-frame churn that cancels the in-flight pointer interaction,
  // making the menu impossible to click.
  if (!isContextMenuOrdered(menu, orderedItems)) {
    for (const item of orderedItems) menu.appendChild(item);
  }

  clampSketchContextPopover(popover, viewportRoot);
}

/**
 * Simplifies Excalidraw's built-in right-click context menu down to
 * `allowList`, dropping any `<hr>` separators. `recognizedActions` guards
 * against mistaking an unrelated `ul.context-menu` elsewhere on the page for
 * Excalidraw's own.
 */
export function applySketchContextMenuSimplification(
  root: HTMLElement,
  viewportRoot: HTMLElement,
  allowList: readonly string[],
  recognizedActions: readonly string[],
): void {
  const sets = { allowed: new Set(allowList), recognized: new Set(recognizedActions) };
  for (const menu of Array.from(root.querySelectorAll<HTMLUListElement>('ul.context-menu'))) {
    simplifyContextMenu({ menu, viewportRoot, allowList }, sets);
  }
}

/** The override for `value`, or `null` when there is none or it would not
 *  change anything (so callers skip a no-op DOM write). */
function resolveTextOverride(value: string, overrides: SketchDomTextOverrides): string | null {
  const next = translateDomTextValue(value, overrides);
  return next !== null && next !== value ? next : null;
}

function rewriteTextNodes(root: ParentNode, overrides: SketchDomTextOverrides): void {
  const textWalker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node = textWalker.nextNode();
  while (node) {
    // `NodeFilter.SHOW_TEXT` restricts this walk to `Text` nodes, whose
    // `nodeValue` is always a string per spec (only `Document`/`DocumentType`
    // nodes ever have a null `nodeValue`) — `Node.nodeValue`'s broader type
    // is nullable only because it covers those other node kinds too.
    const next = resolveTextOverride(node.nodeValue!, overrides);
    if (next !== null) node.nodeValue = next;
    node = textWalker.nextNode();
  }
}

function rewriteOverrideAttributes(root: ParentNode, overrides: SketchDomTextOverrides): void {
  const descendants = Array.from(root.querySelectorAll<HTMLElement>('*'));
  const elements = root instanceof Element ? [root, ...descendants] : descendants;
  for (const element of elements) {
    for (const attr of SKETCH_TEXT_OVERRIDE_ATTRS) {
      const value = element.getAttribute(attr);
      if (!value) continue;
      const next = resolveTextOverride(value, overrides);
      if (next !== null) element.setAttribute(attr, next);
    }
  }
}

/**
 * Walks `root`'s text nodes and a fixed set of text-bearing attributes,
 * rewriting any that match `overrides`. `overrides` is entirely
 * host-supplied — no translated copy ships as a default (see
 * `packages/ui/archived provenance ledger`).
 */
export function applySketchDomTextOverrides(root: ParentNode, overrides: SketchDomTextOverrides | undefined): void {
  if (!overrides || Object.keys(overrides).length === 0 || typeof document === 'undefined') return;
  rewriteTextNodes(root, overrides);
  rewriteOverrideAttributes(root, overrides);
}

export function rewriteExcalidrawUnableToEmbedToasts(
  root: HTMLElement,
  replacement: string,
  additionalPhrases: readonly string[] = [],
): void {
  const normalizedReplacement = normalizeTooltipLabel(replacement);
  if (!normalizedReplacement) return;
  for (const messageNode of Array.from(root.querySelectorAll<HTMLElement>('.Toast__message'))) {
    const current = normalizeTooltipLabel(messageNode.textContent);
    if (!current || current === normalizedReplacement || !isExcalidrawUnableToEmbedToast(current, additionalPhrases)) {
      continue;
    }
    messageNode.textContent = normalizedReplacement;
    messageNode.closest<HTMLElement>('.Toast')?.setAttribute('data-jini-sketch-embed-toast-rewritten', 'true');
  }
}

export function findSketchMermaidInsertButton(content: HTMLElement, insertLabelPattern: RegExp): HTMLButtonElement | null {
  const dialogText = normalizeTooltipLabel(content.textContent);
  if (!dialogText || !/Mermaid/i.test(dialogText)) return null;
  for (const button of Array.from(content.querySelectorAll<HTMLButtonElement>('button'))) {
    const label = normalizeTooltipLabel(button.textContent) ?? normalizeTooltipLabel(button.getAttribute('aria-label'));
    if (!label) continue;
    if (insertLabelPattern.test(label)) return button;
  }
  return null;
}

export function removeSketchMermaidShortcutHints(content: HTMLElement, insertLabelPattern: RegExp): void {
  const insertButton = findSketchMermaidInsertButton(content, insertLabelPattern);
  if (!insertButton) return;
  for (const hint of Array.from(insertButton.querySelectorAll('kbd'))) hint.remove();
  for (const hint of Array.from(content.querySelectorAll('.ttd-dialog-submit-shortcut'))) hint.remove();
}

/**
 * Adds a `jini-sketch-modal` marker + a close button to every Excalidraw
 * modal portal mounted on `document.body` (Excalidraw renders these via its
 * own portal, outside the component's own DOM subtree, so this must walk
 * the whole document rather than a local root).
 */
export function enhanceSketchExcalidrawPortals(
  closeLabel: string,
  onClose: () => void,
  domTextOverrides: SketchDomTextOverrides | undefined,
  insertLabelPattern: RegExp,
): void {
  for (const portal of Array.from(document.querySelectorAll<HTMLElement>('.excalidraw-modal-container'))) {
    portal.classList.add('jini-sketch-modal');
    portal.classList.toggle('jini-sketch-help-modal', Boolean(portal.querySelector('.HelpDialog__header')));
    applySketchDomTextOverrides(portal, domTextOverrides);
    for (const content of Array.from(portal.querySelectorAll<HTMLElement>('.Modal__content'))) {
      removeSketchMermaidShortcutHints(content, insertLabelPattern);
      let close = content.querySelector<HTMLButtonElement>(':scope > .jini-sketch-dialog-close');
      if (!close) {
        close = document.createElement('button');
        close.type = 'button';
        close.className = 'jini-sketch-dialog-close';
        close.addEventListener('click', (event) => {
          event.preventDefault();
          event.stopPropagation();
          onClose();
        });
        content.appendChild(close);
      }
      close.setAttribute('aria-label', closeLabel);
      close.setAttribute('title', closeLabel);
    }
  }
}

function isCommandEnter(event: KeyboardEvent): boolean {
  return event.key === 'Enter' && (event.metaKey || event.ctrlKey) && !event.altKey;
}

/** The `.Modal__content` around `target`, but only when it sits inside one
 *  of our marked `.jini-sketch-modal` portals and holds a `<textarea>`. */
function resolvePortalEditorContent(target: EventTarget | null): HTMLElement | null {
  if (!(target instanceof Element)) return null;
  const portal = target.closest<HTMLElement>('.jini-sketch-modal');
  const content = target.closest<HTMLElement>('.Modal__content');
  if (!portal || !content || !portal.contains(content)) return null;
  return content.querySelector('textarea') ? content : null;
}

function isButtonEnabled(button: HTMLButtonElement): boolean {
  return !button.disabled && button.getAttribute('aria-disabled') !== 'true';
}

export function handleSketchPortalCommandEnter(event: KeyboardEvent, insertLabelPattern: RegExp): void {
  if (!isCommandEnter(event)) return;
  const content = resolvePortalEditorContent(event.target);
  if (!content) return;

  const insertButton = findSketchMermaidInsertButton(content, insertLabelPattern);
  if (!insertButton || !isButtonEnabled(insertButton)) return;

  event.preventDefault();
  event.stopPropagation();
  insertButton.click();
}

import { useT } from '../../../i18n/index.js';
import type { ViewportPreset } from '../../../viewer-shell/index.js';
import {
  effectivePreviewScale,
  findViewportPreset,
  previewScaleShellStyle,
  previewViewportStyle,
} from '../../rules.js';
import { DEFAULT_PREVIEW_CANVAS_PADDING } from '../../constants.js';
import { usePreviewCanvasSize } from '../hooks/usePreviewCanvasSize.js';

export interface VersionPreviewFrameProps {
  previewDocument: string;
  frameReady: boolean;
  onFrameLoad: () => void;
  viewport: string;
  viewportPresets: ViewportPreset[];
  title: string;
  error: string | null;
  loading: boolean;
  loadingContent: boolean;
}

/** The scaled, sandboxed preview iframe + its loading overlay. Measures its
 *  own container so a fixed-size viewport preset (tablet/mobile) can be
 *  scaled to fit whatever space the host actually gives this pane. */
export function VersionPreviewFrame({
  previewDocument,
  frameReady,
  onFrameLoad,
  viewport,
  viewportPresets,
  title,
  error,
  loading,
  loadingContent,
}: VersionPreviewFrameProps) {
  const t = useT();
  const [frameRef, canvasSize] = usePreviewCanvasSize<HTMLDivElement>();
  const preset = findViewportPreset(viewportPresets, viewport);
  const scale = effectivePreviewScale(preset, 1, canvasSize, DEFAULT_PREVIEW_CANVAS_PADDING);

  return (
    <div className="jini-version-preview" ref={frameRef}>
      {error ? (
        <div className="jini-viewer-empty" role="alert">
          {error}
        </div>
      ) : (
        <>
          {previewDocument ? (
            <div className="jini-preview-viewport" style={previewViewportStyle(preset, scale, 1)}>
              <div className="jini-preview-frame-clip">
                <div style={previewScaleShellStyle(preset, 1)}>
                  <iframe
                    title={title}
                    sandbox="allow-scripts allow-downloads"
                    srcDoc={previewDocument}
                    onLoad={onFrameLoad}
                  />
                </div>
              </div>
            </div>
          ) : null}
          {!previewDocument && !loading && !loadingContent ? (
            <div className="jini-viewer-empty">{t('No preview available.')}</div>
          ) : null}
          {loading || loadingContent || (previewDocument && !frameReady) ? (
            <div className="jini-version-preview-overlay" role="status" aria-label={t('Loading preview…')}>
              <span className="jini-version-preview-spinner" aria-hidden="true" />
            </div>
          ) : null}
        </>
      )}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useI18n } from '../../../i18n/index.js';
import type { ViewportPreset } from '../../../viewer-shell/index.js';
import { DEFAULT_VIEWPORT_PRESETS } from '../../../viewer-shell/index.js';
import {
  PREVIEW_LOAD_FALLBACK_MS,
  SEARCH_VISIBLE_THRESHOLD,
} from '../../constants.js';
import { defaultVersionManagerDependencies } from '../../dependencies.js';
import type { VersionManagerDependencies, VersionManagerPort } from '../../ports.js';
import {
  buildVersionIndex,
  contentMatchesSelection,
  filterVersionsBySearch,
  formatVersionDateTime,
  isRestoreDisabled,
  restoredFromVersion,
  resolveSelectedVersion,
  shouldShowVersionSearch,
  sortVersionsDescending,
  versionSourceLabel,
} from '../../rules.js';
import type { VersionManagerFileRef, VersionRecord } from '../../types.js';

export interface UseVersionManagerOptions<TVersion extends VersionRecord> {
  fileRef: VersionManagerFileRef;
  /** The file's current (pre-version-history) content, used to seed the
   *  cache so the version flagged `current` renders instantly with no
   *  round-trip. `null` if there is none yet. */
  currentContent: string | null;
  onRestored: (content: string, version: TVersion) => Promise<void> | void;
  /** Called after a restore completes with no warning — matches the
   *  source, which closes the modal immediately on a clean restore but
   *  keeps it open (showing the warning) when the restore succeeded with
   *  a caveat. Omit if the host wants to keep the modal open regardless. */
  onRestoredCleanly?: () => void;
  viewportPresets?: ViewportPreset[];
}

export interface VersionManagerController<TVersion extends VersionRecord> {
  versions: TVersion[];
  visibleVersions: TVersion[];
  versionById: ReadonlyMap<string, TVersion>;
  selectedVersion: TVersion | null;
  selectedId: string | null;
  selectVersion: (id: string) => void;
  prefetchVersion: (id: string) => void;
  restoredFrom: (version: TVersion) => TVersion | null;
  loading: boolean;
  loadingContent: boolean;
  error: string | null;
  search: string;
  setSearch: (value: string) => void;
  showSearch: boolean;
  selectedContent: string | null;
  previewDocument: string;
  frameReady: boolean;
  markFrameLoaded: (document: string) => void;
  restoring: boolean;
  restoreDisabled: boolean;
  restore: () => Promise<void>;
  openInNewTab: (() => void) | null;
  viewportPresets: ViewportPreset[];
  viewport: string;
  setViewport: (id: string) => void;
  describeVersion: (version: TVersion) => string;
}

function seedCurrentVersionContent({
  currentVersion,
  currentContent,
  contentCache,
}: {
  currentVersion: VersionRecord | undefined;
  currentContent: string | null;
  contentCache: Map<string, string>;
}) {
  if (currentVersion && currentContent != null && !contentCache.has(currentVersion.id)) {
    contentCache.set(currentVersion.id, currentContent);
  }
}

/**
 * Owns the whole version-manager state machine: list fetch, selection,
 * content cache/prefetch, search, restore, and viewport choice. Kept as one
 * cohesive hook per this package's Phase 6 "one natural owning cluster"
 * discipline (matching `features/connectors/`'s `useConnectorAuthorization`
 * precedent) — the source's own version, list, and preview state are all
 * read/written by each other's effects and don't split cleanly.
 */
export function useVersionManager<TVersion extends VersionRecord>(
  dependencies: VersionManagerDependencies<TVersion>,
  options: UseVersionManagerOptions<TVersion>,
): VersionManagerController<TVersion> {
  const { fileRef, currentContent, onRestored, onRestoredCleanly, viewportPresets = DEFAULT_VIEWPORT_PRESETS } = options;
  const port: VersionManagerPort<TVersion> = dependencies.versions;
  const { locale, t } = useI18n();

  // Latest-ref indirection so the fetch callbacks below don't need `t` in
  // their dependency arrays (see this package's documented infinite-loop
  // gotcha for hooks that call useT()/useI18n() from an effect).
  const tRef = useRef(t);
  useEffect(() => {
    tRef.current = t;
  }, [t]);

  const [versions, setVersions] = useState<TVersion[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedContent, setSelectedContent] = useState<string | null>(currentContent);
  const [selectedContentVersionId, setSelectedContentVersionId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingContent, setLoadingContent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [restoring, setRestoring] = useState(false);
  const [search, setSearch] = useState('');
  const [viewport, setViewport] = useState<string>(viewportPresets[0]?.id ?? 'desktop');
  const [loadedPreviewDocument, setLoadedPreviewDocument] = useState<string | null>(null);

  const contentCacheRef = useRef<Map<string, string>>(new Map());
  const inFlightRef = useRef<Map<string, Promise<void>>>(new Map());
  // Set right before a restore-warning reload changes `selectedId` (which
  // re-triggers the content-load effect below); consumed once by that
  // effect to skip its normal `setError(null)` so the just-set warning
  // message survives the version switch instead of being immediately
  // clobbered. See the `restore` warning branch.
  const preserveErrorOnNextSelectionRef = useRef(false);

  const versionById = useMemo(() => buildVersionIndex(versions), [versions]);
  const selectedVersion = resolveSelectedVersion(versions, versionById, selectedId);
  const showSearch = shouldShowVersionSearch(versions.length, SEARCH_VISIBLE_THRESHOLD);

  const describeVersion = useCallback(
    (version: TVersion): string => {
      const from = restoredFromVersion(version, versionById);
      return [
        `v${version.version}`,
        `version ${version.version}`,
        version.prompt ?? '',
        version.label ?? '',
        tRef.current(versionSourceLabel(version.source)),
        formatVersionDateTime(version.createdAt, locale),
        from ? `v${from.version}` : '',
      ]
        .join(' ')
        .toLowerCase();
    },
    [versionById, locale],
  );

  const visibleVersions = useMemo(
    () => (showSearch ? filterVersionsBySearch(versions, search, describeVersion) : versions),
    [showSearch, versions, search, describeVersion],
  );

  const selectedContentMatchesVersion = contentMatchesSelection(
    selectedId,
    selectedContentVersionId,
    selectedContent,
  );
  const restoreDisabled = isRestoreDisabled({
    selectedVersion,
    restoring,
    loadingContent,
    selectedContentMatchesVersion,
  });

  const previewDocument = useMemo(
    () => (selectedContent ? port.resolvePreviewDocument(fileRef, selectedContent) : ''),
    [port, fileRef, selectedContent],
  );
  const frameReady = loadedPreviewDocument === previewDocument;

  // Primes the content cache for one version at most once, deduping
  // concurrent callers (hover-prefetch racing the click that selects it).
  const primeVersionContent = useCallback(
    (versionId: string): Promise<void> => {
      if (contentCacheRef.current.has(versionId)) return Promise.resolve();
      const pending = inFlightRef.current.get(versionId);
      if (pending) return pending;
      const request = port
        .fetchVersionContent(fileRef, versionId)
        .then((result) => {
          if (result != null) contentCacheRef.current.set(versionId, result);
        })
        .catch(() => {})
        .finally(() => {
          inFlightRef.current.delete(versionId);
        });
      inFlightRef.current.set(versionId, request);
      return request;
    },
    [port, fileRef],
  );

  const loadVersions = useCallback(
    async (preferredId?: string | null) => {
      setLoading(true);
      setError(null);
      const result = await port.listVersions(fileRef);
      if (!result) {
        setError(tRef.current('Couldn’t load version history.'));
        setLoading(false);
        return;
      }
      const nextVersions = sortVersionsDescending(result);
      setVersions(nextVersions);
      const currentVersion = nextVersions.find((version) => version.current);
      seedCurrentVersionContent({ currentVersion, currentContent, contentCache: contentCacheRef.current });
      const nextSelected =
        (preferredId ? nextVersions.find((version) => version.id === preferredId) : null) ??
        currentVersion ??
        nextVersions[0] ??
        null;
      setSelectedId(nextSelected?.id ?? null);
      setLoading(false);
    },
    [port, fileRef, currentContent],
  );

  // Re-fetches whenever `loadVersions`'s own dependencies change — including
  // `currentContent` — matching the source exactly (a fresh `currentContent`
  // re-lists so it can be cache-seeded as the new `current` version's body).
  useEffect(() => {
    void loadVersions();
  }, [loadVersions]);

  useEffect(() => {
    if (!selectedId) {
      setSelectedContent(null);
      setSelectedContentVersionId(null);
      return undefined;
    }
    const cached = contentCacheRef.current.get(selectedId);
    if (cached !== undefined) {
      setSelectedContent(cached);
      setSelectedContentVersionId(selectedId);
      setLoadingContent(false);
      if (preserveErrorOnNextSelectionRef.current) {
        preserveErrorOnNextSelectionRef.current = false;
      } else {
        setError(null);
      }
      return undefined;
    }
    // Cache miss: keep the previous preview mounted (don't clear
    // `selectedContent`) so switching versions never blanks to empty while
    // the loading overlay covers it.
    //
    // No `preserveErrorOnNextSelectionRef` check here (unlike the cache-hit
    // branch above): the only caller that sets that flag (`restore`'s
    // warning branch) always seeds the cache for the version it switches
    // to first, so that switch can only ever land in the cache-HIT branch
    // above — this branch genuinely cannot run with the flag set. A real
    // cache-miss always means a genuinely new fetch starting, which should
    // unconditionally clear a stale error.
    let cancelled = false;
    setLoadingContent(true);
    setError(null);
    void primeVersionContent(selectedId).then(() => {
      if (cancelled) return;
      const next = contentCacheRef.current.get(selectedId);
      if (next === undefined) {
        setSelectedContent(null);
        setSelectedContentVersionId(null);
        setError(tRef.current('Couldn’t load this version’s preview.'));
      } else {
        setSelectedContent(next);
        setSelectedContentVersionId(selectedId);
      }
      setLoadingContent(false);
    });
    return () => {
      cancelled = true;
    };
  }, [primeVersionContent, selectedId]);

  // Safety net: clear a stuck loading overlay if the iframe's `load` event
  // is ever missed.
  useEffect(() => {
    if (!previewDocument || loadedPreviewDocument === previewDocument) return undefined;
    const fallback = setTimeout(() => setLoadedPreviewDocument(previewDocument), PREVIEW_LOAD_FALLBACK_MS);
    return () => clearTimeout(fallback);
  }, [previewDocument, loadedPreviewDocument]);

  const restore = useCallback(async () => {
    if (
      isRestoreDisabled({ selectedVersion, restoring, loadingContent, selectedContentMatchesVersion }) ||
      !selectedVersion ||
      !selectedContent
    ) {
      return;
    }
    setRestoring(true);
    setError(null);
    let handledRestore = false;
    try {
      const result = await port.restoreVersion(fileRef, selectedVersion);
      if (!result) {
        setError(tRef.current('Restore failed.'));
        return;
      }
      const restoredVersion = result.version ?? selectedVersion;
      await onRestored(selectedContent, restoredVersion);
      if (result.warning) {
        // Seed the cache with the content we already have in hand — it's
        // exactly what was just restored — so the list reload below
        // selects the new version as a cache HIT. Without this, the
        // content-load effect's own fetch-start `setError(null)` (for a
        // legitimate reason: clearing a stale error when starting a new
        // load) would race with and clobber the warning message set right
        // below, once React flushes that effect after this restore
        // completes. Seeding also avoids a pointless refetch of content
        // this hook already has.
        contentCacheRef.current.set(restoredVersion.id, selectedContent);
        preserveErrorOnNextSelectionRef.current = true;
        await loadVersions(restoredVersion.id);
        setError(result.warning.message);
        return;
      }
      handledRestore = true;
      onRestoredCleanly?.();
    } finally {
      if (!handledRestore) setRestoring(false);
    }
  }, [
    selectedVersion,
    restoring,
    loadingContent,
    selectedContentMatchesVersion,
    selectedContent,
    port,
    fileRef,
    onRestored,
    onRestoredCleanly,
    loadVersions,
  ]);

  const openInNewTab = useMemo(() => {
    if (!port.openPreviewInNewTab) return null;
    return () => {
      if (loadingContent || !selectedContentMatchesVersion || !selectedContent || !selectedVersion) return;
      port.openPreviewInNewTab!(
        fileRef,
        selectedContent,
        `${fileRef.name} · v${selectedVersion.version}`,
      );
    };
  }, [port, fileRef, loadingContent, selectedContentMatchesVersion, selectedContent, selectedVersion]);

  return {
    versions,
    visibleVersions,
    versionById,
    selectedVersion,
    selectedId,
    selectVersion: setSelectedId,
    prefetchVersion: (id: string) => {
      void primeVersionContent(id);
    },
    restoredFrom: (version: TVersion) => restoredFromVersion(version, versionById),
    loading,
    loadingContent,
    error,
    search,
    setSearch,
    showSearch,
    selectedContent,
    previewDocument,
    frameReady,
    markFrameLoaded: setLoadedPreviewDocument,
    restoring,
    restoreDisabled,
    restore,
    openInNewTab,
    viewportPresets,
    viewport,
    setViewport,
    describeVersion,
  };
}

/**
 * Production wiring for `useVersionManager`: binds the module-level default
 * dependencies singleton (a stateless fake port + the real stateless
 * browser clipboard — see `dependencies.ts`'s `defaultVersionManagerDependencies`
 * for why this must stay ONE shared instance rather than a fresh call per
 * render: a fresh `dependencies.versions` identity every render would
 * re-trigger `loadVersions`'s effect in a loop, the same reasoning
 * `useWiredCopyToClipboard` in `features/viewer-shell/` documents for its
 * own singleton). A real host supplies its own `VersionManagerDependencies`
 * directly to `useVersionManager` instead of using this wirer.
 */
export function useWiredVersionManager<TVersion extends VersionRecord>(
  options: UseVersionManagerOptions<TVersion>,
  dependencies: VersionManagerDependencies<TVersion> = defaultVersionManagerDependencies as unknown as VersionManagerDependencies<TVersion>,
): VersionManagerController<TVersion> {
  return useVersionManager(dependencies, options);
}

import type { ViewportPreset } from '../viewer-shell/index.js';
import type { PreviewCanvasSize, VersionRecord, VersionSource } from './types.js';

/** Formats an epoch-millis timestamp for the version list/header, using the
 *  host's locale. Falls back to the runtime default locale formatting if
 *  the given locale tag is invalid — matches the source's own try/catch
 *  fallback rather than throwing on a bad locale string. */
export function formatVersionDateTime(value: number | undefined, locale: string): string {
  const date = new Date(typeof value === 'number' && Number.isFinite(value) ? value : Date.now());
  try {
    return date.toLocaleString(locale, {
      month: 'short',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch {
    return date.toLocaleString();
  }
}

/** Plain-English label for a version's `source` — the caller wraps this in
 *  `t()` at the call site (the English string is the translation key
 *  convention this package uses; see `packages/ui/README.md`). */
export function versionSourceLabel(source: VersionSource): string {
  if (source === 'manual') return 'Manual';
  if (source === 'restore') return 'Restored';
  return 'AI generated';
}

/** CSS class suffix for a version's source badge. */
export function versionSourceClassName(source: VersionSource): string {
  if (source === 'manual') return 'manual';
  if (source === 'restore') return 'restore';
  return 'ai';
}

/** Newest-first order, matching the source's own list ordering. */
export function sortVersionsDescending<TVersion extends VersionRecord>(
  versions: readonly TVersion[],
): TVersion[] {
  return [...versions].sort((a, b) => b.version - a.version);
}

/** Builds an id → version lookup map, used for resolving `restoreFromVersionId`
 *  references and for O(1) selection lookups. */
export function buildVersionIndex<TVersion extends VersionRecord>(
  versions: readonly TVersion[],
): Map<string, TVersion> {
  const map = new Map<string, TVersion>();
  for (const version of versions) map.set(version.id, version);
  return map;
}

/** The version a given version was restored from, if any and if still
 *  present in the current list. */
export function restoredFromVersion<TVersion extends VersionRecord>(
  version: TVersion | null | undefined,
  versionById: ReadonlyMap<string, TVersion>,
): TVersion | null {
  if (!version?.restoreFromVersionId) return null;
  return versionById.get(version.restoreFromVersionId) ?? null;
}

/** Resolves the effective "selected" version: an explicit selection if one
 *  is set and still present, else the version flagged `current`, else the
 *  first (newest) version, else `null` for an empty list. Matches the
 *  source's own selection-fallback chain exactly. */
export function resolveSelectedVersion<TVersion extends VersionRecord>(
  versions: readonly TVersion[],
  versionById: ReadonlyMap<string, TVersion>,
  selectedId: string | null,
): TVersion | null {
  if (selectedId) {
    const explicit = versionById.get(selectedId);
    if (explicit) return explicit;
  }
  return versions.find((version) => version.current) ?? versions[0] ?? null;
}

/** Should the search box be shown at all — only once the list is long
 *  enough to need filtering. */
export function shouldShowVersionSearch(versionCount: number, threshold: number): boolean {
  return versionCount > threshold;
}

/**
 * Filters `versions` by a case-insensitive substring match against a
 * caller-supplied per-version description string. Kept hook-free (no
 * `useT()`/locale here) per this package's i18n convention — the caller
 * builds `describe()` using its own `t()`/locale and the other pure
 * helpers above (`versionSourceLabel`, `formatVersionDateTime`,
 * `restoredFromVersion`), then this function only does the filtering.
 */
export function filterVersionsBySearch<TVersion extends VersionRecord>(
  versions: readonly TVersion[],
  search: string,
  describe: (version: TVersion) => string,
): TVersion[] {
  const normalized = search.trim().toLowerCase();
  if (!normalized) return [...versions];
  return versions.filter((version) => describe(version).toLowerCase().includes(normalized));
}

export interface RestoreDisabledInput<TVersion extends VersionRecord> {
  selectedVersion: TVersion | null;
  restoring: boolean;
  loadingContent: boolean;
  selectedContentMatchesVersion: boolean;
}

/** Whether the restore action should be disabled — mirrors the source's
 *  `restoreDisabled` derivation exactly (no restoring the version already
 *  current, no restoring mid-fetch, no restoring stale/mismatched content). */
export function isRestoreDisabled<TVersion extends VersionRecord>(
  input: RestoreDisabledInput<TVersion>,
): boolean {
  const { selectedVersion, restoring, loadingContent, selectedContentMatchesVersion } = input;
  return (
    !selectedVersion ||
    selectedVersion.current ||
    restoring ||
    loadingContent ||
    !selectedContentMatchesVersion
  );
}

/** Whether the currently-loaded preview content actually corresponds to the
 *  currently-selected version (guards against acting on stale content
 *  during a version switch's in-flight fetch). */
export function contentMatchesSelection(
  selectedId: string | null,
  selectedContentVersionId: string | null,
  selectedContent: string | null,
): boolean {
  return Boolean(selectedId && selectedContentVersionId === selectedId && selectedContent);
}

/** Finds a viewport preset by id, falling back to the first preset in the
 *  list (matches `ViewportSwitcher`/`ViewportToggleGroup`'s own fallback
 *  behavior in `features/viewer-shell/`). */
export function findViewportPreset(presets: readonly ViewportPreset[], id: string): ViewportPreset {
  return presets.find((preset) => preset.id === id) ?? presets[0]!;
}

/**
 * How much a fixed-size viewport preset (tablet/mobile — `width`/`height`
 * both non-null) must be scaled down to fit inside the measured canvas.
 * A preset with `width === null` ("no fixed frame", e.g. "desktop") is
 * never scaled by this function — it returns `previewScale` unchanged,
 * generalizing the source's `viewport === 'desktop'` special case to any
 * preset that opts out of fixed framing.
 */
export function effectivePreviewScale(
  preset: ViewportPreset,
  previewScale: number,
  canvasSize: PreviewCanvasSize | undefined,
  canvasPadding: number,
): number {
  if (!preset.width || !preset.height) return previewScale;
  if (!canvasSize || !canvasSize.width || !canvasSize.height) return previewScale;
  const availableWidth = Math.max(1, canvasSize.width - canvasPadding);
  const availableHeight = Math.max(1, canvasSize.height - canvasPadding);
  const fitScale = Math.min(1, availableWidth / preset.width, availableHeight / preset.height);
  return Math.min(previewScale, fitScale);
}

/** CSS custom properties driving the fixed-size preview frame's dimensions
 *  and scale. Returns an empty object for a "no fixed frame" preset (the
 *  frame just fills its container at 100%, no custom properties needed). */
export function previewViewportStyle(
  preset: ViewportPreset,
  effectiveScale: number,
  previewScale: number,
): Record<string, string | number> {
  if (!preset.width) return {};
  return {
    '--preview-viewport-width': `${preset.width}px`,
    '--preview-viewport-height': `${preset.height}px`,
    '--preview-scale': effectiveScale,
    '--preview-user-scale': previewScale,
  };
}

/** Inline style for the scaled shell wrapping the preview iframe. A
 *  "no fixed frame" preset scales the whole shell directly by
 *  `previewScale`; a fixed-size preset instead sizes to the CSS custom
 *  properties `previewViewportStyle` sets and scales by the *fitted*
 *  `--preview-scale` variable, matching the source's two-mode behavior. */
export function previewScaleShellStyle(
  preset: ViewportPreset,
  previewScale: number,
): Record<string, string> {
  if (!preset.width) {
    return {
      width: `${100 / previewScale}%`,
      height: `${100 / previewScale}%`,
      transform: `scale(${previewScale})`,
      transformOrigin: '0 0',
    };
  }
  return {
    width: 'var(--preview-viewport-width)',
    height: 'var(--preview-viewport-height)',
    transform: 'scale(var(--preview-scale, 1))',
    transformOrigin: '0 0',
  };
}

import {
  buildScrollAnchors,
  mapScrollPosition,
  measureEditorBlockOffsets,
  measurePreviewBlockOffsets,
} from '../../utils/markdown-scroll-sync.js';
import type { CommentSideDropEdge, MarkdownScrollPane, ViewerCommentBase } from './types.js';

// ---------------------------------------------------------------------------
// Byte/size formatting
// ---------------------------------------------------------------------------

/** Human-readable file size (`"512 B"` / `"3.4 KB"` / `"1.2 MB"`). Ported
 *  verbatim (no OD coupling in the original — a pure number formatter). */
export function humanFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

// ---------------------------------------------------------------------------
// Comment side-panel: drag-reorder + saved-order bookkeeping
// ---------------------------------------------------------------------------

/** Which edge of the drop target a pointer is over, based on the event's
 *  vertical position relative to the target element's own bounding rect. */
export function dropEdgeForClientY(clientY: number, targetRect: { top: number; height: number }): CommentSideDropEdge {
  return clientY < targetRect.top + targetRect.height / 2 ? 'before' : 'after';
}

/** Recompute an ordered id list after dragging `draggingId` to sit
 *  before/after `targetId`. Returns the original order unchanged if either
 *  id is missing. */
export function reorderCommentIds(
  ids: string[],
  draggingId: string,
  targetId: string,
  edge: CommentSideDropEdge,
): string[] {
  const next = [...ids];
  const from = next.indexOf(draggingId);
  if (from < 0) return next;
  const [draggedId] = next.splice(from, 1);
  const targetIndex = next.indexOf(targetId);
  if (targetIndex < 0 || !draggedId) return ids;
  next.splice(edge === 'after' ? targetIndex + 1 : targetIndex, 0, draggedId);
  return next;
}

/** Append a newly-saved comment id to a persisted order list, reconciling it
 *  against the currently-visible comment ids first (drops ids that are no
 *  longer visible, keeps visible ids not yet in the saved order). Returns the
 *  same array reference when nothing actually changed. */
export function appendSavedCommentOrder(
  currentOrderIds: string[],
  visibleIds: string[],
  savedId: string,
): string[] {
  if (!savedId) return currentOrderIds;
  if (currentOrderIds.includes(savedId) || visibleIds.includes(savedId)) {
    return currentOrderIds;
  }
  const visibleIdSet = new Set(visibleIds);
  const kept = currentOrderIds.filter((id) => visibleIdSet.has(id));
  const missingVisibleIds = visibleIds.filter((id) => !kept.includes(id));
  const base = currentOrderIds.length > 0 ? [...kept, ...missingVisibleIds] : visibleIds;
  const next = [...base, savedId];
  return next.join('\0') === currentOrderIds.join('\0') ? currentOrderIds : next;
}

/** Default "just now / 5 minutes ago / 3 days ago" relative-time formatter.
 *  Pure given a `now` timestamp — callers wrap the result in `t()` at the
 *  call site (see the i18n policy in
 *  `ADS-memory/reports/jini-port/god-components-extraction-plan.md`). Returns a
 *  `{ key, vars }` pair rather than a finished string so a host's `t()` can
 *  supply its own plural/locale-aware phrasing; `key` is always one of a
 *  small fixed set of English template strings. */
export function relativeCommentTimeTranslation(
  timestampMs: number,
  nowMs: number = Date.now(),
): { key: string; vars?: Record<string, number> } {
  const diff = nowMs - timestampMs;
  if (diff < 60_000) return { key: 'Just now' };
  const mins = Math.floor(diff / 60_000);
  if (mins < 60) return { key: '{n} minutes ago', vars: { n: mins } };
  const hours = Math.floor(mins / 60);
  if (hours < 24) return { key: '{n} hours ago', vars: { n: hours } };
  const days = Math.floor(hours / 24);
  if (days < 7) return { key: '{n} days ago', vars: { n: days } };
  const weeks = Math.floor(days / 7);
  if (weeks < 5) return { key: '{n} weeks ago', vars: { n: weeks } };
  return { key: new Date(timestampMs).toLocaleDateString() };
}

/** Selection-count bookkeeping shared by the comment side-panel. */
export function visibleSelectedCommentIds<TComment extends ViewerCommentBase>(
  comments: TComment[],
  selectedIds: ReadonlySet<string>,
): Set<string> {
  return new Set(comments.filter((comment) => selectedIds.has(comment.id)).map((comment) => comment.id));
}

// ---------------------------------------------------------------------------
// JSON-safe text formatting (used by a plain-text viewer body)
// ---------------------------------------------------------------------------

/** True when re-serializing `text` through `JSON.parse`/`JSON.stringify`
 *  would silently change a number's printed form — e.g. `-0`, or a value
 *  whose decimal digits round-trip differently once parsed into a JS
 *  `number`. When true, callers should display the original text verbatim
 *  instead of a "prettified" re-stringify. */
export function hasPrecisionSensitiveJsonNumberText(text: string): boolean {
  const numberTokenPattern = /-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/y;
  for (let i = 0; i < text.length; ) {
    if (text[i] === '"') {
      i = indexAfterJsonString(text, i + 1);
      continue;
    }

    numberTokenPattern.lastIndex = i;
    const match = numberTokenPattern.exec(text);
    if (!match) {
      i += 1;
      continue;
    }

    if (isPrecisionSensitiveNumberLiteral(match[0])) return true;
    i = numberTokenPattern.lastIndex;
  }
  return false;
}

/** Index just past the closing quote of the JSON string whose body starts at
 *  `start` (honouring `\` escapes), or `text.length` when it is unterminated. */
function indexAfterJsonString(text: string, start: number): number {
  for (let i = start; i < text.length; i += 1) {
    if (text[i] === '"') return i + 1;
    if (text[i] === '\\') i += 1;
  }
  return text.length;
}

function isPrecisionSensitiveNumberLiteral(token: string): boolean {
  if (isSignedNegativeZeroJsonNumberToken(token)) return true;
  return /[.eE]/.test(token) && isPrecisionSensitiveJsonNumberToken(token);
}

function isSignedNegativeZeroJsonNumberToken(token: string): boolean {
  return /^-0(?:\.0+)?(?:[eE][+-]?\d+)?$/.test(token);
}

function isPrecisionSensitiveJsonNumberToken(token: string): boolean {
  const parsed = Number(token);
  if (!Number.isFinite(parsed)) return true;
  // `JSON.stringify` of a finite number always returns a non-empty numeral
  // string ("0" at minimum) — there is no finite input for which it returns
  // "" or another falsy value, so the defensive `!rendered` check this line
  // replaces (present in the original source) could never actually fire.
  const rendered = JSON.stringify(parsed);
  const originalValue = parseJsonNumberTokenAsDecimal(token);
  const renderedValue = parseJsonNumberTokenAsDecimal(rendered);
  return originalValue.coefficient !== renderedValue.coefficient || originalValue.exponent !== renderedValue.exponent;
}

function parseJsonNumberTokenAsDecimal(token: string): { coefficient: bigint; exponent: number } {
  // Both call sites above only ever pass a well-formed decimal/exponential
  // JSON number literal: either a value matched by
  // `hasPrecisionSensitiveJsonNumberText`'s own number-token regex (a strict
  // subset of the pattern below — no leading zeros, always digits either
  // side of `.`) or `JSON.stringify` output of a finite number (guaranteed
  // by the JS spec to already be in this exact shape). So this match is
  // guaranteed to succeed; the non-null assertion exists only to satisfy
  // TypeScript's `RegExpExecArray | null` return type, not because there is
  // a real runtime path where it fails.
  const match = /^(-)?(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$/.exec(token)!;
  const [, sign, integerPart, fractionPart = '', exponentPart = '0'] = match;
  const coefficient = BigInt(`${sign ?? ''}${integerPart}${fractionPart}`);
  const exponent = Number(exponentPart) - fractionPart.length;
  return normalizeDecimalParts(coefficient, exponent);
}

function normalizeDecimalParts(coefficient: bigint, exponent: number): { coefficient: bigint; exponent: number } {
  if (coefficient === 0n) return { coefficient: 0n, exponent: 0 };
  let normalizedCoefficient = coefficient;
  let normalizedExponent = exponent;
  while (normalizedCoefficient % 10n === 0n) {
    normalizedCoefficient /= 10n;
    normalizedExponent += 1;
  }
  return { coefficient: normalizedCoefficient, exponent: normalizedExponent };
}

/** True when `value` (already `JSON.parse`d) contains any non-finite number
 *  or an integer outside `Number.isSafeInteger` range. */
export function hasUnsafeJsonNumber(value: unknown): boolean {
  if (typeof value === 'number') {
    return !Number.isFinite(value) || (Number.isInteger(value) && !Number.isSafeInteger(value));
  }
  if (Array.isArray(value)) return value.some(hasUnsafeJsonNumber);
  if (value && typeof value === 'object') return Object.values(value).some(hasUnsafeJsonNumber);
  return false;
}

/**
 * Pretty-print `text` as JSON when `isJsonLike` is true and doing so is
 * provably safe (no precision loss) — otherwise returns `text` unchanged.
 * `isJsonLike` is a plain boolean the caller derives from its own file-kind
 * check (e.g. `file.name.endsWith('.json')`), not baked in here, since what
 * counts as "this is a JSON file" is host-specific.
 */
export function formatJsonTextForDisplay(text: string, isJsonLike: boolean): string {
  if (!isJsonLike) return text;
  try {
    if (hasPrecisionSensitiveJsonNumberText(text)) return text;
    const parsed = JSON.parse(text) as unknown;
    if (hasUnsafeJsonNumber(parsed)) return text;
    return JSON.stringify(parsed, null, 2);
  } catch {
    return text;
  }
}

// ---------------------------------------------------------------------------
// Split source/preview pane scroll-sync
// ---------------------------------------------------------------------------

/** Full scrollable range of `element` (0 when there's nothing to scroll). */
export function scrollRange(element: { scrollHeight: number; clientHeight: number }): number {
  return Math.max(0, element.scrollHeight - element.clientHeight);
}

/** `element`'s current scroll position as a 0..1 ratio of its scrollable
 *  range (0 when there's nothing to scroll). */
export function scrollRatio(element: { scrollHeight: number; clientHeight: number; scrollTop: number }): number {
  const range = scrollRange(element);
  return range > 0 ? element.scrollTop / range : 0;
}

/** Inverse of {@link scrollRatio}: the scrollTop that puts `element` at
 *  `ratio` (0..1, clamped) of its scrollable range. */
export function scrollTopForRatio(
  element: { scrollHeight: number; clientHeight: number },
  ratio: number,
): number {
  const clamped = Math.max(0, Math.min(1, Number.isFinite(ratio) ? ratio : 0));
  return scrollRange(element) * clamped;
}

/**
 * Compute the target pane's scrollTop that keeps it aligned with the source
 * pane, given the shared per-block line numbers (from
 * `extractMarkdownBlockLines`, already ported to `../../utils/markdown-scroll-sync.js`).
 * Falls back to plain ratio-sync when block-level anchors can't be measured
 * (e.g. the rendered preview's direct-child count doesn't match the block
 * count — see `measurePreviewBlockOffsets`'s own doc comment).
 */
export function computeSplitPaneScrollTarget(params: {
  sourcePane: MarkdownScrollPane;
  source: { scrollTop: number; scrollHeight: number; clientHeight: number };
  target: { scrollHeight: number; clientHeight: number };
  blockLineCount: number;
  editorOffsets: number[] | null;
  previewOffsets: number[] | null;
}): number {
  const { sourcePane, source, target, blockLineCount, editorOffsets, previewOffsets } = params;
  if (blockLineCount > 0 && editorOffsets && previewOffsets) {
    const isEditorSource = sourcePane === 'editor';
    const sourceOffsets = isEditorSource ? editorOffsets : previewOffsets;
    const targetOffsets = isEditorSource ? previewOffsets : editorOffsets;
    const sourceAnchors = buildScrollAnchors(sourceOffsets, source.scrollHeight);
    const targetAnchors = buildScrollAnchors(targetOffsets, target.scrollHeight);
    const mapped = mapScrollPosition(source.scrollTop, sourceAnchors, targetAnchors);
    return Math.max(0, Math.min(scrollRange(target), mapped));
  }
  return scrollTopForRatio(target, scrollRatio(source));
}

export { measureEditorBlockOffsets, measurePreviewBlockOffsets };

// HeaderActionsMenu — a compact "More" overflow menu for a sticky/compact
// header: a single trigger button that opens a grouped popover of actions
// (divided into visually-separated groups, empty groups skipped). Closes on
// outside click or Escape.

import {
  Fragment,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
} from 'react';

import { Icon, type IconName } from './Icon.js';

export interface HeaderMenuAction {
  id: string;
  label: string;
  icon: IconName;
  onClick: () => void;
  disabled?: boolean;
  loading?: boolean;
  /** Toggles render with checkbox semantics + a trailing check when active. */
  active?: boolean;
}

export interface HeaderActionsMenuProps {
  /** Each inner array renders as one visually-divided group; empty groups are skipped. */
  groups: HeaderMenuAction[][];
  /** Accessible label for the trigger button and the popover menu. */
  label: string;
  /** Custom hook override for dependency injection / testing. */
  useHeaderActionsMenu?: typeof useHeaderActionsMenu;
}

// ---------------------------------------------------------------------------
// Pure helpers — no React, directly unit-testable.
// ---------------------------------------------------------------------------

/** Drops empty groups so only groups with at least one action render. */
export function filterVisibleActionGroups(groups: HeaderMenuAction[][]): HeaderMenuAction[][] {
  return groups.filter((group) => group.length > 0);
}

/** The single key that dismisses the menu. */
export function isHeaderMenuDismissKey(key: string): boolean {
  return key === 'Escape';
}

/**
 * Whether a pointer event landed outside the menu (and should therefore close
 * it). A missing container never counts as "outside".
 */
export function isOutsideHeaderMenu(
  container: HTMLElement | null,
  target: EventTarget | null,
): boolean {
  if (!container) return false;
  return !container.contains(target as Node | null);
}

/** ARIA role: plain menuitem, or checkbox semantics when the item is a toggle. */
export function headerMenuItemRole(active: boolean | undefined): 'menuitem' | 'menuitemcheckbox' {
  return active === undefined ? 'menuitem' : 'menuitemcheckbox';
}

/** `aria-checked` value: only meaningful (and only set) for toggle items. */
export function headerMenuItemAriaChecked(active: boolean | undefined): boolean | undefined {
  return active === undefined ? undefined : active;
}

/** The icon to render — the spinner while loading, otherwise the item's icon. */
export function headerMenuItemIcon(item: HeaderMenuAction): IconName {
  return item.loading ? 'spinner' : item.icon;
}

/** Disabled while explicitly disabled or loading. */
export function headerMenuItemDisabled(item: HeaderMenuAction): boolean {
  return Boolean(item.disabled || item.loading);
}

/** `aria-busy` value: `true` while loading, otherwise unset. */
export function headerMenuItemBusy(item: HeaderMenuAction): true | undefined {
  return item.loading || undefined;
}

// ---------------------------------------------------------------------------
// Hooks — every stateful/effectful seam, exported for isolated testing.
// ---------------------------------------------------------------------------

export interface HeaderActionsMenuDisclosure {
  open: boolean;
  toggle: () => void;
  close: () => void;
}

/** Open/close state for the popover with stable toggle/close callbacks. */
export function useHeaderActionsMenuDisclosure(): HeaderActionsMenuDisclosure {
  const [open, setOpen] = useState(false);
  const toggle = useCallback(() => setOpen((value) => !value), []);
  const close = useCallback(() => setOpen(false), []);
  return { open, toggle, close };
}

/** Memoized list of non-empty groups. */
export function useVisibleActionGroups(groups: HeaderMenuAction[][]): HeaderMenuAction[][] {
  return useMemo(() => filterVisibleActionGroups(groups), [groups]);
}

/**
 * While `open`, closes the menu on an outside `mousedown` or an Escape keydown.
 * Listeners are only attached while open and torn down on close/unmount.
 */
export function useHeaderActionsMenuDismiss(params: {
  open: boolean;
  onDismiss: () => void;
  containerRef: MutableRefObject<HTMLElement | null>;
}): void {
  const { open, onDismiss, containerRef } = params;
  useEffect(() => {
    if (!open) return undefined;
    function onPointerDown(event: MouseEvent) {
      if (isOutsideHeaderMenu(containerRef.current, event.target)) onDismiss();
    }
    function onKeyDown(event: KeyboardEvent) {
      if (isHeaderMenuDismissKey(event.key)) onDismiss();
    }
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onDismiss, containerRef]);
}

export interface UseHeaderActionsMenuResult {
  open: boolean;
  toggle: () => void;
  close: () => void;
  containerRef: MutableRefObject<HTMLDivElement | null>;
  visibleGroups: HeaderMenuAction[][];
}

/**
