export function createHttpUsersApi({ transport, workspaceId }: { transport: RolesHttpTransport; workspaceId: string }, { basePath = '/workspaces', authPath = '/auth' }: { basePath?: string; authPath?: string } = {}): import('../ports.js').UsersApiPort {
