/**
 * @file An amendment that completes the users/roles/policies admin CRUD surface
 * (feature.spec.md..19).
 *
 * Purpose:
 * Two of these nine transitions (`disablePrincipal`, `writePolicyPermission`) were fully specified
 * since v0.5.0/v0.5.3 but never implemented — this file is their first implementation, not a
 * re-specification. The other seven (`enablePrincipal`, `updateUser`,
 * `resetUserPassword`, `updateRole`, `updatePolicy`, `deleteRole`, `deletePolicy`) are new
 * transitions this amendment adds. Grouped in one file, separate from `grant-service.ts`'s
 * "human grant-writing transitions" (`CREATE_*`/`ASSIGN_ROLE`/`ATTACH_POLICY`) because most of
 * these are plain CRUD, not grant-writing — `writePolicyPermission` is the one exception (it IS
 * -clamped) and reuses `grant-service.ts`'s exported `assertGrantClamp` rather than
 * duplicating it.
 *
 * Architectural role:
 * Ordinary core functions — same shape as `grant-service.ts`: one exported async
 * function per transition, plain `Error` subclasses for control flow, the caller-permission gate
 * enforced here (not pushed to the route layer).
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */

/**
 * `DISABLE_PRINCIPAL` (feature.spec.md, state.spec §3). Gated by
 * `user.manage`. Refuses the seeded owner unconditionally ( CLI/core resolution target —
 * disabling it would strand the CLI-only management plane) and refuses any disable that would drop
 * the workspace's active owner-`*` count to zero — both checked, and the status update
 * performed inside one identity transaction. Asynchronous repository calls yield even in a
 * single-event-loop composition, so the transaction port must serialize competing owner/status
 * writes for the whole workspace rather than rely on "atomic by construction" reasoning.
 *
 * `input.seededOwnerPrincipalId` is the caller's job to resolve (`await deps.ownerPrincipalId` at
 * the route layer, mirroring `identityReady`'s existing await-before-use convention) — this
 * function takes the already-resolved id so it stays a plain, directly-testable function.
 *
 * @complexity O(n) in the workspace's principal count (one `list` call to count active owner-`*`
 * holders) — bounded by the same operator-managed-roster assumption `identity/INFO.md` already
 * makes for `PrincipalRepoPort.list`.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function disablePrincipal(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; principalId: UUID; seededOwnerPrincipalId: UUID };
}): Promise<{ principal: PrincipalRecord }> {
  const { deps, input } = required;

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["user.manage"],
      });

      const target = await deps.repos.principals.findById({ workspaceId: input.workspaceId, id: input.principalId });
      if (!target) throw new IdentityNotFoundError({ message: `principal '${input.principalId}' was not found` });

      if (target.id === input.seededOwnerPrincipalId) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new OwnerRequiredError({ message: "the seeded owner principal can never be disabled" });
      }

      await assertOwnerTargetMayBeModified({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        principalId: input.principalId,
      });

      if (target.status === "disabled") {
        // Idempotent — matches LOGOUT's "already revoked is a no-op" discipline (state.spec §3).
        return { principal: target };
      }

      const holdsOwnerWildcard = await principalHoldsOwnerWildcard({
        deps,
        workspaceId: input.workspaceId,
        principalId: target.id,
      });
      if (holdsOwnerWildcard) {
        const activeOwnerCount = await countActiveOwnerWildcardPrincipals({ deps, workspaceId: input.workspaceId });
        if (activeOwnerCount <= 1) {
          // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
          throw new OwnerRequiredError({ message: "the workspace must keep at least one active owner-`*` principal" });
        }
      }

      const disabled: PrincipalRecord = { ...target, status: "disabled", disabledAt: kernelNowIso({ clock: deps.clock }) };
      await deps.repos.principals.save(disabled);
      return { principal: disabled };
    },
  });
}

/**
 * `ENABLE_PRINCIPAL` (feature.spec.md ). Gated by `user.manage`. Target must be
 * `kind='user'` — a `system`/`api_key` target is rejected `VALIDATION_ERROR` (mirrors 
 * human-only scoping; re-activating the disabled legacy `user-local` stub or an api_key principal
 * outside `ISSUE_API_KEY`'s own lifecycle is never a valid call). Already-active is idempotent
 * (mirrors `disablePrincipal`'s own already-disabled no-op above).
 *
 * @complexity O(1) — one lookup, one save.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function enablePrincipal(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; principalId: UUID };
}): Promise<{ principal: PrincipalRecord }> {
  const { deps, input } = required;

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["user.manage"],
      });

      const target = await deps.repos.principals.findById({ workspaceId: input.workspaceId, id: input.principalId });
      if (!target) throw new IdentityNotFoundError({ message: `principal '${input.principalId}' was not found` });

      if (target.kind !== "user") {
        throw new IdentityValidationError({ message: `ENABLE_PRINCIPAL target must be a human (kind='user') principal, got kind='${target.kind}'` });
      }

      await assertOwnerTargetMayBeModified({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        principalId: input.principalId,
      });

      if (target.status === "active") {
        return { principal: target };
      }

      const enabled: PrincipalRecord = { ...target, status: "active", disabledAt: undefined };
      await deps.repos.principals.save(enabled);
      return { principal: enabled };
    },
  });
}

/**
 * `UPDATE_USER` (feature.spec.md ). Gated by `user.manage`; existing self-profile edits also
 * accept `member.manage`. Username changes require `user.manage`, including self edits.
 * Only owners may edit owner targets. Password is not this transition's concern.
 * An absent or empty-string `email`
 * clears the stored value to `undefined` ( — no distinct "blank but present" state).
 *
 * @complexity O(n) normalization for n username characters; fixed repo/Trash reads, one user save
 * and one audit append for an actual rename, all inside the shared identity transaction.
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function updateUser(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; principalId: UUID; };
}, optional: { email?: string | undefined; username?: string | undefined } = {}): Promise<{ user: UserRecord }> {
  const { deps } = required;
  const input = { ...required.input, ...optional };

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        // Preserve existing self-profile access without letting member.manage edit other operators.
        permissions: input.username === undefined && input.callerPrincipalId === input.principalId
          ? ["user.manage", "member.manage"]
          : ["user.manage"],
      });

      const target = await deps.repos.users.findByPrincipalId({
        workspaceId: input.workspaceId,
        principalId: input.principalId,
      });
      if (!target) throw new IdentityNotFoundError({ message: `user '${input.principalId}' was not found` });

      await assertOwnerTargetMayBeModified({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        principalId: input.principalId,
      });

      const username = input.username === undefined ? target.username : await resolveUpdatedUsername({ deps, input, target });
      // Preserve the old email setter contract, while a username-only call retains email.
      const email = input.username !== undefined && !Object.hasOwn(optional, "email")
        ? target.email : (input.email || undefined);
      const updated: UserRecord = { ...target, username, email };
      await deps.repos.users.save(updated);
      if (username !== target.username) {
        // Renaming never changes the principal id or credentials: existing sessions stay valid.
        await deps.usernameChanges!.record({ workspaceId: input.workspaceId, principalId: input.principalId,
          callerPrincipalId: input.callerPrincipalId, previousUsername: target.username, username,
          occurredAt: kernelNowIso({ clock: deps.clock }) });
      }
      return { user: updated };
    },
  });
}

/** Validate and reserve a normalized name inside the caller's identity transaction.
 * Permission/owner gates run first, so conflicts never disclose accounts to unauthorized callers.
 * Check order (pinned in `__tests__/admin-crud-service.pins.test.ts`): type, blank, port wiring,
 * the target's Trash state, host support (actual changes only), then uniqueness.
 * @complexity O(n) normalization for n username characters; one indexed lookup and up to two Trash reads.
 * Throws validation or conflict errors; performs no writes.
 */
async function resolveUpdatedUsername(required: {
  deps: AuthServiceDeps; target: UserRecord;
  input: { workspaceId: string; principalId: string; username?: string | undefined };
}): Promise<string> {
  const { deps, input, target } = required;
  const username = normalizeRequestedUsername({ raw: input.username });
  // Missing host ports are internal wiring faults, not user input errors (HTTP 500, not 400).
  if (!deps.usernameChanges) throw new Error("username changes are not configured");
  if (await deps.usernameChanges.isInTrash({ workspaceId: input.workspaceId, principalId: input.principalId })) {
    throw new IdentityConflictError({ message: "this user is in the Trash; restore them first", code: "USER_IN_TRASH" });
  }
  if (username !== target.username) {
    await deps.usernameChanges.assertSupported?.({ workspaceId: input.workspaceId, principalId: input.principalId });
  }
  await assertUsernameAvailable({ deps, usernameChanges: deps.usernameChanges, workspaceId: input.workspaceId, target, username });
  return username;
}

/** A requested username must be a string that is not blank once normalized. */
function normalizeRequestedUsername(required: { raw: unknown }): string {
  if (typeof required.raw !== "string") throw new IdentityValidationError({ message: "username must be a string" });
  const username = normalizeUsername({ raw: required.raw });
  if (!username) throw new IdentityValidationError({ message: "username must not be blank" });
  return username;
}

/** Refuses a normalized name held by ANY other user, naming Trash as the reason when the holder is there. */
async function assertUsernameAvailable(required: {
  deps: AuthServiceDeps; usernameChanges: UsernameChangePort; workspaceId: string; target: UserRecord; username: string;
}): Promise<void> {
  const { deps, usernameChanges, workspaceId, target, username } = required;
  // Trash keeps credential rows until purge, so the unfiltered lookup reserves those names too.
  const existing = await deps.repos.users.findByUsername({ workspaceId, username });
  if (!existing || existing.principalId === target.principalId) return;
  if (await usernameChanges.isInTrash({ workspaceId, principalId: existing.principalId })) {
    throw new IdentityConflictError({ message: "a user with this username is in the Trash; restore or delete them permanently first", code: "USERNAME_IN_TRASH" });
  }
  throw new IdentityConflictError({ message: `username '${username}' is already in use`, code: "RESOURCE_CONFLICT" });
}

/**
 * `RESET_USER_PASSWORD` (feature.spec.md ). Gated by **`user.manage`** only
 * (resetting a credential is at least as sensitive as disabling the account, own reasoning). Hashes the new password identically to `CREATE_USER` (argon2id,
 * ), then revokes every one of the target's active sessions (idempotent no-op if it has none,
 * ) — a reset that left old sessions alive would not actually contain a compromised account.
 *
 * Refuses a THIRD PARTY resetting the seeded owner's password ( reasoning, same
 * `OwnerRequiredError` `disablePrincipal` uses): `user.manage` is independently grantable and not
 * owner-exclusive (`permissions.ts` — "Create/disable operator users and principals"), so without
 * this check a caller holding only that one delegated permission could set a password of their own
 * choosing on the seeded owner's account and log in as owner — a full takeover from a routine
 * delegation. Checked before the password-policy validation so the refusal doesn't depend on the
 * caller supplying a well-formed password first.
 *
 * Deliberately NOT unconditional the way `disablePrincipal`'s owner check is: the owner resetting
 * ITS OWN password (`callerPrincipalId === principalId === seededOwnerPrincipalId`) is refused
 * nothing — that self-service path is real, shipped infrastructure
 * (`reset-admin-password-self-verified.ts`, driven by both the `HOST_ADMIN_RESET_PASSWORD`
 * boot-time incident-recovery hook and the `backfill-reset-admin-password.ts` CLI script), added
 * specifically to let an operator recover a locked-out owner account out-of-band. Disabling has no
 * legitimate self-case (an owner disabling itself only ever stands the workspace down), so
 * `disablePrincipal` can refuse unconditionally; a credential rotation the owner performs on itself
 * is ordinary hygiene and the documented recovery path, so only a MISMATCHED caller — the actual
 * escalation shape — is refused here.
 *
 * Deliberately NOT -clamped (unlike `disablePrincipal`'s second guard): a reset changes a
 * credential, it never changes `status`, so it can never drop the workspace's active owner-`*`
 * count — headcount guard has nothing to protect here.
 *
 * `input.seededOwnerPrincipalId` is the caller's job to resolve (`await deps.ownerPrincipalId` at
 * the route layer, mirroring `disablePrincipal`'s own contract above) — this function takes the
 * already-resolved id so it stays a plain, directly-testable function.
 *
 * @complexity O(s) in the target's session count, s = active session rows to revoke — bounded by
 * the same operator-managed-roster scale assumption every other identity list call here makes.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function resetUserPassword(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; principalId: UUID; password: string; seededOwnerPrincipalId: UUID };
}): Promise<{ user: UserRecord }> {
  const { deps, input } = required;

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["user.manage"],
      });

      const target = await deps.repos.users.findByPrincipalId({
        workspaceId: input.workspaceId,
        principalId: input.principalId,
      });
      if (!target) throw new IdentityNotFoundError({ message: `user '${input.principalId}' was not found` });

      if (target.principalId === input.seededOwnerPrincipalId && input.callerPrincipalId !== input.seededOwnerPrincipalId) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new OwnerRequiredError({ message: "the seeded owner's password can only be reset by the owner itself, never by another caller" });
      }

      await assertOwnerTargetMayBeModified({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        principalId: input.principalId,
      });

      if (!input.password) {
        throw new IdentityValidationError({ message: "password is required" });
      }
      // Same presence-and-upper-bound-only policy `createUser` applies (no minimum length). Both
      // write paths must enforce it or neither does: a reset that accepted an empty password would be
      // a strictly easier way to reach the state the create-side check exists to prevent. Never
      // reaches `seed.ts`'s owner password or the login path — see `password-policy.ts`'s header for
      // why.
      const passwordError = validatePasswordPolicy({ password: input.password });
      if (passwordError) {
        throw new IdentityValidationError({ message: passwordError });
      }

      const passwordHash = await deps.hasher.hash({ password: input.password });
      const updated: UserRecord = { ...target, passwordHash };
      await deps.repos.users.save(updated);

      const sessions = await deps.repos.sessions.listByPrincipalId({
        workspaceId: input.workspaceId,
        principalId: input.principalId,
      });
      const nowIso = kernelNowIso({ clock: deps.clock });
      await Promise.all(
        sessions
          .filter((session) => !session.revokedAt)
          .map((session) => deps.repos.sessions.revoke({ workspaceId: input.workspaceId, id: session.id, revokedAt: nowIso }))
      );

      return { user: updated };
    },
  });
}

/**
 * `UPDATE_ROLE` (feature.spec.md ). Gated by `role.manage`. A built-in target is
 * refused `VALIDATION_ERROR` — extends existing undeletable/immutable/un-attachable-to
 * rule to also cover un-renameable (same escalation shape: relabeling `viewer` to read as trusted
 * is a social-engineering variant of what already blocks structurally).
 *
 * @complexity O(1) — one lookup, one save.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function updateRole(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; roleId: UUID; name: string };
}): Promise<{ role: RoleRecord }> {
  const { deps, input } = required;

  await assertCallerHasAnyPermission({
    deps,
    workspaceId: input.workspaceId,
    callerPrincipalId: input.callerPrincipalId,
    permissions: ["role.manage"],
  });

  const target = await deps.repos.roles.findById({ workspaceId: input.workspaceId, id: input.roleId });
  if (!target) throw new IdentityNotFoundError({ message: `role '${input.roleId}' was not found` });
  if (target.isBuiltin) {
    // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
    throw new IdentityValidationError({ message: "a built-in role cannot be renamed" });
  }

  const name = (input.name ?? "").trim();
  if (!name) throw new IdentityValidationError({ message: "role name is required" });

  const updated: RoleRecord = { ...target, name };
  await deps.repos.roles.save(updated);
  return { role: updated };
}

/**
 * `UPDATE_POLICY` (feature.spec.md ). Gated by `role.manage`. A built-in or
 * `is_frozen` target is refused `VALIDATION_ERROR` — the frozen-policy half mirrors
 * `WRITE_POLICY_PERMISSION`'s existing refusal : an issuance snapshot's identity is as
 * immutable as its permission set. At least one of `name`/`description` must be present.
 *
 * @complexity O(1) — one lookup, one save.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function updatePolicy(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; policyId: UUID; };
}, optional: { name?: string | undefined; description?: string | undefined } = {}): Promise<{ policy: PolicyRecord }> {
  const { deps } = required;
  const input = { ...required.input, ...optional };

  await assertCallerHasAnyPermission({
    deps,
    workspaceId: input.workspaceId,
    callerPrincipalId: input.callerPrincipalId,
    permissions: ["role.manage"],
  });

  const target = await deps.repos.policies.findById({ workspaceId: input.workspaceId, id: input.policyId });
  if (!target) throw new IdentityNotFoundError({ message: `policy '${input.policyId}' was not found` });
  if (target.isBuiltin || target.isFrozen) {
    // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
    throw new IdentityValidationError({ message: "a built-in or frozen policy cannot be renamed/re-described" });
  }

  if (input.name === undefined && input.description === undefined) {
    throw new IdentityValidationError({ message: "at least one of name or description is required" });
  }

  const name = input.name !== undefined ? input.name.trim() : target.name;
  if (!name) throw new IdentityValidationError({ message: "policy name is required" });

  const updated: PolicyRecord = {
    ...target,
    name,
    description: input.description !== undefined ? input.description : target.description,
  };
  await deps.repos.policies.save(updated);
  return { policy: updated };
}

/**
 * `DELETE_ROLE` (feature.spec.md ). Gated by `role.manage`. A built-in
 * target is refused `VALIDATION_ERROR` (checked before the reference count, matching 
 * stated precedence). A still-referenced target (≥1 `principal_roles` row) is refused
 * `IdentityConflictError` (409 `RESOURCE_CONFLICT`) — the reference check and the delete happen in
 * one identity transaction ( atomicity, same isolation requirement as
 * `disablePrincipal`'s owner-count guard above). Concurrent grant writers use the same port so
 * no assignment can appear between the reference check and deletion.
 *
 * @complexity O(a) in the role's assignment count (`principalRoles.listByRoleId`) — bounded by the
 * same operator-managed-roster assumption every other identity list call makes.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function deleteRole(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; roleId: UUID };
}): Promise<void> {
  const { deps, input } = required;

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["role.manage"],
      });

      const target = await deps.repos.roles.findById({ workspaceId: input.workspaceId, id: input.roleId });
      if (!target) throw new IdentityNotFoundError({ message: `role '${input.roleId}' was not found` });
      if (target.isBuiltin) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new IdentityValidationError({ message: "a built-in role cannot be deleted" });
      }

      const assignments = await deps.repos.principalRoles.listByRoleId({
        workspaceId: input.workspaceId,
        roleId: input.roleId,
      });
      if (assignments.length > 0) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new IdentityConflictError({ message: `role '${input.roleId}' is still assigned to ${assignments.length} principal(s)` });
      }

      await deps.repos.roles.delete({ workspaceId: input.workspaceId, id: input.roleId });
    },
  });
}

/**
 * `DELETE_POLICY` (feature.spec.md ). Gated by `role.manage`. A
 * built-in or `is_frozen` target is refused `VALIDATION_ERROR` (checked before the reference
 * count). A still-referenced target (≥1 `role_policies` or `principal_policies` row) is refused
 * `IdentityConflictError`. On success, cascades to the policy's OWN `policy_permissions` rows only
 * (never a different policy's) before deleting the policy row itself. Both deletes and the
 * reference guard share one transaction; failure rolls back the permission cascade.
 *
 * @complexity O(r + p) — role-reference count + principal-reference count, both bounded by the same
 * operator-managed-roster assumption every other identity list call makes.
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function deletePolicy(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; policyId: UUID };
}): Promise<void> {
  const { deps, input } = required;

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["role.manage"],
      });

      const target = await deps.repos.policies.findById({ workspaceId: input.workspaceId, id: input.policyId });
      if (!target) throw new IdentityNotFoundError({ message: `policy '${input.policyId}' was not found` });
      if (target.isBuiltin || target.isFrozen) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new IdentityValidationError({ message: "a built-in or frozen policy cannot be deleted" });
      }

      const [roleRefs, principalRefs] = await Promise.all([
        deps.repos.rolePolicies.listByPolicyId({ workspaceId: input.workspaceId, policyId: input.policyId }),
        deps.repos.principalPolicies.listByPolicyId({ workspaceId: input.workspaceId, policyId: input.policyId }),
      ]);
      const referenceCount = roleRefs.length + principalRefs.length;
      if (referenceCount > 0) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new IdentityConflictError({ message: `policy '${input.policyId}' is still referenced by ${referenceCount} row(s)` });
      }

      await deps.repos.policyPermissions.deleteByPolicyId({ workspaceId: input.workspaceId, policyId: input.policyId });
      await deps.repos.policies.delete({ workspaceId: input.workspaceId, id: input.policyId });
    },
  });
}

/**
 * `WRITE_POLICY_PERMISSION` (feature.spec.md, state.spec §3). First HTTP
 * implementation of a transition specified since v0.5.3 ( — this is a route, not a
 * re-specification). Gated by `role.manage`. Refuses an unregistered permission
 * (`PermissionUnknownError`), a built-in or `is_frozen` parent policy, and
 * (via the shared `assertGrantClamp`) a permission the caller does not itself hold unconstrained
 * (`GrantExceedsIssuerError`).
 *
 * @complexity O(assertGrantClamp) — see that function's own doc (resolveEffectivePermissions +
 * O(1) local filtering, one permission).
 * @overallScore 100
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function writePolicyPermission(required: {
  deps: AuthServiceDeps;
  input: {
    workspaceId: UUID;
    callerPrincipalId: UUID;
    policyId: UUID;
    permission: string;
  };
}, optional: { resourceType?: string | null; constraintJson?: string | null } = {}): Promise<{ policyPermission: PolicyPermissionRecord }> {
  const { deps } = required;
  const input = { ...required.input, ...optional };

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["role.manage"],
      });

      if (!isKnownPermission({ id: input.permission })) {
        throw new PermissionUnknownError({ message: `permission '${input.permission}' is not in the registered catalog` });
      }

      const policy = await deps.repos.policies.findById({ workspaceId: input.workspaceId, id: input.policyId });
      if (!policy) throw new IdentityNotFoundError({ message: `policy '${input.policyId}' was not found` });
      if (policy.isBuiltin || policy.isFrozen) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new IdentityValidationError({ message: "cannot write a permission onto a built-in or frozen policy" });
      }

      await assertGrantClamp({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        conferredPermissions: [input.permission],
      });

      const policyPermission: PolicyPermissionRecord = {
        id: deps.idGen.newId(),
        workspaceId: input.workspaceId,
        policyId: input.policyId,
        permission: input.permission,
        resourceType: input.resourceType ?? null,
        constraintJson: input.constraintJson ?? null,
      };
      await deps.repos.policyPermissions.save(policyPermission);
      return { policyPermission };
    },
  });
}

/**
 * `REMOVE_POLICY_PERMISSION` — the inverse of {@link writePolicyPermission}, and the
 * transition whose absence made a policy's permission set append-only: the only way to shrink one
 * was `deletePolicy` + recreate, which blocks outright the moment anything references the
 * policy.
 *
 * Gated by `role.manage`, the same permission `writePolicyPermission` and `deletePolicy` require.
 * Deliberately NOT clamped by `assertGrantClamp` : the clamp exists to stop a caller
 * conferring authority it does not itself hold, and removal confers nothing — it is a strict
 * de-escalation. Requiring the clamp here would mean an admin who cannot grant `content.write`
 * also cannot take it back, which is the wrong direction for a safety rule. This is strictly less
 * powerful than the already-unclamped `deletePolicy`, which drops EVERY permission row the policy
 * has.
 *
 * Refuses a built-in or `is_frozen` parent policy, checked BEFORE the row lookup so
 * a frozen policy reports why it is frozen rather than leaking whether the row exists. A row that
 * is absent — or that exists but belongs to a DIFFERENT policy — is one and the same
 * `IdentityNotFoundError`: membership is proven from `listByPolicyId`'s result, so a caller can
 * never delete across a policy boundary by guessing an id.
 *
 * @complexity O(n) in the policy's own permission-row count (one `listByPolicyId`) — bounded by the
 * same operator-managed-roster assumption every other identity list call makes.
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
export async function removePolicyPermission(required: {
  deps: AuthServiceDeps;
  input: { workspaceId: UUID; callerPrincipalId: UUID; policyId: UUID; policyPermissionId: UUID };
}): Promise<void> {
  const { deps, input } = required;

  return inIdentityTransaction({
    transactions: deps.repos.transactions,
    workspaceId: input.workspaceId,
    execute: async () => {
      await assertCallerHasAnyPermission({
        deps,
        workspaceId: input.workspaceId,
        callerPrincipalId: input.callerPrincipalId,
        permissions: ["role.manage"],
      });

      const policy = await deps.repos.policies.findById({ workspaceId: input.workspaceId, id: input.policyId });
      if (!policy) throw new IdentityNotFoundError({ message: `policy '${input.policyId}' was not found` });
      if (policy.isBuiltin || policy.isFrozen) {
        // See docs/decisions/DR-002-grant-authority-and-admin-safety.md for the invariant behind this refusal; keep external identifiers out of caller-facing messages.
        throw new IdentityValidationError({ message: "cannot remove a permission from a built-in or frozen policy" });
      }

      const rows = await deps.repos.policyPermissions.listByPolicyId({
        workspaceId: input.workspaceId,
        policyId: input.policyId,
      });
      const target = rows.find((row) => row.id === input.policyPermissionId);
      if (!target) {
        throw new IdentityNotFoundError({ message: `policy permission '${input.policyPermissionId}' was not found on policy '${input.policyId}'` });
      }

      await deps.repos.policyPermissions.delete({ workspaceId: input.workspaceId, id: target.id });
    },
  });
}

/**
 * Count `active` principals in `workspaceId` that hold the owner wildcard `*` ( own
 * definition of "owner-`*` principal"). O(n) in the workspace's principal count, n bounded by the
 * same operator-managed-roster assumption `identity/INFO.md` documents.
 * See docs/decisions/DR-002-grant-authority-and-admin-safety.md.
 */
async function countActiveOwnerWildcardPrincipals(required: {
  deps: AuthServiceDeps;
  workspaceId: UUID;
}): Promise<number> {
  const { deps, workspaceId } = required;
  const principals = await deps.repos.principals.list({ workspaceId });
  // A kind barred from operator permissions (a site `member`) can never act as an owner, so it is
  // not counted even if a `*` row reaches it — and members never cost a grant read here.
  const activePrincipals = principals.filter(
    (principal) =>
      principal.status === "active" && principalKindMayExercisePermission({ kind: principal.kind, permission: "*" })
  );
  const flags = await Promise.all(
    activePrincipals.map((principal) =>
      principalHoldsOwnerWildcard({ deps, workspaceId, principalId: principal.id })
    )
  );
  return flags.filter(Boolean).length;
}

import type { Clock, IdGenerator } from "@jini-ai/core/primitives";
/**
 * @file Identity's half of the agent-tool authorization wiring: maps `agent-tools.ts`'s fifteen catalog
 * entries onto the users/roles/policies transitions `grant-service.ts`/`admin-crud-service.ts`
 * export, plus the three repo-backed reads, as `ToolRegistration`s.
 *
 * `ToolPolicy.authorize` is a pass-through for all fifteen (see `buildDomainRegistrations`) for the
 * "one evaluator" reason: the gate is the domain layer's, reached identically by every
 * tool kind — mutations through their own service function, which opens with the check, and reads
 * through {@link assertIdentityReadAllowed}, which calls the domain's own exported
 * `assertCallerHasAnyPermission` rather than re-deriving an OR gate. A second check here would be a
 * duplicate evaluator, and one any non-tool caller of the same service function would bypass. See
 * `assistant/__tests__/tool-registrations.identity-authorization.test.ts`.
 */
import {
  buildDomainRegistrations,
  indexCatalogById,
  type AgentToolSideEffect,
  type DerivedRiskByToolId,
  type ToolHandler,
  type ToolRegistration,
} from "@jini-ai/core";
import { parseIdentityToolInput } from "./agent-tool-input.js";
import { identityAgentToolCatalog, type IdentityAgentToolDefinition } from "./agent-tools.js";
import type { AuthServiceDeps } from "./auth-service.js";
import { assertCallerHasAnyPermission, assignRole, attachPolicy, createPolicy, createRole, createUser } from "./grant-service.js";
import { deletePolicy, deleteRole, disablePrincipal, enablePrincipal, updatePolicy, updateRole, updateUser } from "./admin-crud-service.js";
import type {
  IdentityRepos,
  PasswordHasherPort,
  PolicyPermissionRepoPort,
  PolicyRepoPort,
  PrincipalPolicyRepoPort,
  PrincipalRepoPort,
  PrincipalRoleRepoPort,
  RolePolicyRepoPort,
  RoleRepoPort,
  SessionRepoPort,
  UserRepoPort,
} from "../core/index.js";
import type { PolicyRecord, PrincipalRecord, PrincipalRoleRecord, RoleRecord, UserRecord } from "../core/index.js";

const CATALOG_BY_ID = indexCatalogById({ catalog: identityAgentToolCatalog });

/**
 * The exact slice of the route-deps bag Identity's tool handlers read. Declared structurally
 * (rather than importing `server/routes/types`'s `RouteDeps`) so this module carries no back-edge
 * into the composition root. `server/routes/*` satisfies this structurally by passing its existing
 * `RouteDeps` (in practice a users-route subset) object after binding the shared transaction
 * and session-token ports and using the kernel clock/ID contracts.
 */
export interface IdentityToolDeps {
  workspaceId: string;
  clock: Clock;
  idGen: IdGenerator;
  principalRepo: PrincipalRepoPort;
  userRepo: UserRepoPort;
  sessionRepo: SessionRepoPort;
  roleRepo: RoleRepoPort;
  policyRepo: PolicyRepoPort;
  policyPermissionRepo: PolicyPermissionRepoPort;
  rolePolicyRepo: RolePolicyRepoPort;
  principalRoleRepo: PrincipalRoleRepoPort;
  principalPolicyRepo: PrincipalPolicyRepoPort;
  passwordHasher: PasswordHasherPort;
  ownerPrincipalId: Promise<string>;
  /** Bind the same transaction port as every grant/status writer. */
  transactions: IdentityRepos["transactions"];
  tokens: AuthServiceDeps["tokens"];
  usernameChanges?: AuthServiceDeps["usernameChanges"];
}

/**
 * Assembles `auth-service.ts`'s `IdentityRepos` bag from {@link IdentityToolDeps}'s flat fields — a
 * local duplicate of `server/routes/admin/users/deps.ts`'s `identityReposFrom` rather than an import
 * of it, for the same reason `features/settings/tool-registrations.ts`'s header gives for
 * duplicating `toWriteServiceDeps`: importing from the HTTP admin layer would invert this codebase's
 * ports/adapters direction. It is a field mapping, not an authorization decision. Host route bags must bind the same
 * transaction and session-token ports so all paths share persistence semantics.
 */
function identityReposFrom(deps: IdentityToolDeps): IdentityRepos {
  return {
    transactions: deps.transactions,
    principals: deps.principalRepo,
    users: deps.userRepo,
    sessions: deps.sessionRepo,
    roles: deps.roleRepo,
    policies: deps.policyRepo,
    policyPermissions: deps.policyPermissionRepo,
    rolePolicies: deps.rolePolicyRepo,
    principalRoles: deps.principalRoleRepo,
    principalPolicies: deps.principalPolicyRepo,
  };
}

/** Assembles `grant-service.ts`'s/`admin-crud-service.ts`'s `AuthServiceDeps` bag from
 * {@link IdentityToolDeps} — the local twin of `identityReposFrom` just above. */
function identityServiceDepsFrom(deps: IdentityToolDeps): AuthServiceDeps {
  return {
    repos: identityReposFrom(deps),
    hasher: deps.passwordHasher,
    clock: deps.clock,
    idGen: deps.idGen,
    tokens: deps.tokens,
    usernameChanges: deps.usernameChanges,
  };
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const identityDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> authorize() + repo reads only; no save on any path.
  ["identity_user_list", "none"],
  ["identity_role_list", "none"],
  ["identity_policy_list", "none"],
  // -> createUser (grant-service.ts): saves a principal row AND a users row (credential).
  ["identity_user_create", "mutates-durable-state"],
  // -> updateUser (admin-crud-service.ts): users.save, email field only.
  ["identity_user_update_email", "mutates-durable-state"],
  // -> updateUser (admin-crud-service.ts): users.save, username field only, plus the transactional audit.
  ["identity_user_change_username", "mutates-durable-state"],
  // -> disablePrincipal (admin-crud-service.ts): status flip, guarded by the owner floor. See docs/decisions/DR-007-workspace-and-owner-floors.md.
  ["identity_user_disable", "mutates-durable-state"],
  // -> enablePrincipal (admin-crud-service.ts): status flip back to active.
  ["identity_user_enable", "mutates-durable-state"],
  // -> createRole (grant-service.ts): roles.save, always isBuiltin=false.
  ["identity_role_create", "mutates-durable-state"],
  // -> assignRole (grant-service.ts): principalRoles.save behind the grant clamp. The one. See docs/decisions/DR-007-workspace-and-owner-floors.md.
  //    identity tool that confers permissions, hence the heaviest of these.
  ["identity_role_assign", "mutates-durable-state"],
  // -> updateRole (admin-crud-service.ts): roles.save, refuses built-ins.
  ["identity_role_rename", "mutates-durable-state"],
  // -> deleteRole (admin-crud-service.ts): roles.delete, refuses built-ins and referenced roles.
  ["identity_role_delete", "mutates-durable-state"],
  // -> createPolicy (grant-service.ts): policies.save, always isBuiltin=false/isFrozen=false.
  ["identity_policy_create", "mutates-durable-state"],
  // -> updatePolicy (admin-crud-service.ts): policies.save, refuses built-in/frozen.
  ["identity_policy_update", "mutates-durable-state"],
  // -> deletePolicy (admin-crud-service.ts): policyPermissions.deleteByPolicyId + policies.delete,
  //    refuses built-in/frozen and still-referenced policies.
  ["identity_policy_delete", "mutates-durable-state"],
  // -> attachPolicy (grant-service.ts): principalPolicies.save behind the grant clamp — the. See docs/decisions/DR-007-workspace-and-owner-floors.md.
  //    direct-grant counterpart to identity_role_assign, same weight.
  ["identity_policy_attach", "mutates-durable-state"],
]);

/**
 * Upper bound on the roster `identity_user_list` will fan out over.
 *
 * `routes/admin/users/list.ts` does the same O(n) per-user fan-out uncapped, on the documented
 * "operator-managed roster, not member/content scale" assumption. That assumption is fine for a
 * human screen and NOT fine here for a different reason than scale: this result is spent as model
 * context, so an unexpectedly large roster would silently consume the run's context window. The
 * cap truncates and SAYS SO in the payload rather than failing, so a caller that hits it can still
 * work with what it got and knows not to treat the list as complete.
 */
const IDENTITY_USER_LIST_MAX = 200;

/**
 * Catalog lookup that fails loudly on drift between a handler's tool id and the published catalog.
 * Exported for this module's tests only — the package entry does not re-export it.
 */
export function requireIdentityCatalogEntry({ toolId }: { toolId: string }): IdentityAgentToolDefinition {
  const entry = CATALOG_BY_ID.get(toolId);
  if (!entry) throw new Error(`agent-tool-registrations: catalog has no entry named '${toolId}' — @jini-ai/user-management/server catalog drifted`);
  return entry;
}

/**
 * Validates `input` through the tool's OWN published `inputSchema` (interpreted by
 * `agent-tool-input.ts`), then re-throws any rejection with that schema appended.
 *
 * Identity is the one domain whose published schema is ALSO the enforcing parser, so this does not
 * use the kit's `withSchemaOnRejection`: there is no domain call to wrap, the rejection is produced
 * here. Same error-recovery contract either way — a model that gets back only "'roleId' is
 * required" must guess the rest of the shape, whereas one that gets the schema with it can correct
 * the call in a single turn.
 *
 * @complexity O(p) in the tool's declared property count.
 * @overallScore 100
 */
/**
 * A validated tool input, with required and optional reads spelled differently.
 *
 * The distinction is not decoration. `parseIdentityToolInput` returns a `Record<string, string>`
 * whose keys are whatever the caller supplied and the schema accepted, so nothing in the type says
 * which fields are guaranteed. Reading them all the same way makes a schema that forgot to mark a
 * field `required` indistinguishable from one that did — and the failure mode is silent: the
 * handler passes `undefined` into a service call, which stores it. Splitting the read means the
 * handler states which fields it is relying on, and a schema/handler disagreement throws at the
 * boundary naming the field.
 */
export interface ValidatedIdentityInput {
  /** A field the tool's published `inputSchema` marks `required`. @throws {Error} If absent. */
  req(field: string): string;
  /** A field the schema leaves optional. `undefined` means the caller omitted it. */
  opt(field: string): string | undefined;
}

/**
 * Parses `input` against `toolId`'s published schema and returns the split required/optional reader.
 * Exported for this module's tests only — the package entry does not re-export it.
 */
export function identityInput({ toolId, input }: { toolId: string; input: unknown }): ValidatedIdentityInput {
  const entry = requireIdentityCatalogEntry({ toolId });
  const parsed = parseIdentityToolInput({ schema: entry.inputSchema, input });
  if (!parsed.ok) {
    const recovery = "Fix the input and retry — this will not resolve on retry without an input change.";
    throw new Error(`${parsed.error.message}. ${recovery} Schema for '${toolId}': ${JSON.stringify(entry.inputSchema)}`);
  }
  const value = parsed.value;
  return {
    req(field) {
      const found = value[field];
      if (found === undefined) {
        throw new Error(
          `identity tool '${toolId}': the handler reads '${field}' as required, but the published inputSchema does not mark it required — add it to that schema's 'required' list, or read it with opt() and handle its absence`,
        );
      }
      return found;
    },
    opt(field) {
      return value[field];
    },
  };
}

/** The permission set a tool's catalog entry declares — both halves when the gate is an OR. */
function identityPermissionsFor(toolId: string): string[] {
  const { authorization } = requireIdentityCatalogEntry({ toolId });
  return authorization.orPermission ? [authorization.permission, authorization.orPermission] : [authorization.permission];
}

/**
 * The gate for the two READ tools.
 *
 * The mutating tools need no equivalent: their domain function opens with this same
 * `assertCallerHasAnyPermission` call itself. Reads have no service-layer function to inherit it
 * from — `identity` exports grant-writing transitions, not read wrappers, which is why
 * `routes/admin/users/list.ts` also gates in the route and then reads the repo ports directly.
 * This calls the domain's own exported helper rather than re-deriving an OR gate (and rather than
 * the kit's generic `requireToolPermission`, which cannot express an OR), so the single
 * evaluator is reached by an identical path from both tool kinds.
 */
async function assertIdentityReadAllowed(routeDeps: IdentityToolDeps, toolId: string, callerPrincipalId: string): Promise<void> {
  await assertCallerHasAnyPermission({
    deps: identityServiceDepsFrom(routeDeps),
    workspaceId: routeDeps.workspaceId,
    callerPrincipalId,
    permissions: identityPermissionsFor(toolId),
  });
}

/** What an identity user tool returns to the model — see {@link toIdentityUserView}. */
interface IdentityUserToolView {
  principalId: string;
  username: string;
  status: PrincipalRecord["status"];
  roleIds: string[];
  email?: string;
}

/**
 * Projects a principal + its credential row into the explicit model-facing shape.
 *
 * The load-bearing omission is `UserRecord.passwordHash`: keeps hashed secrets server-side,
 * and this view has no field for one, so there is nothing to forward by accident even if a future
 * `UserRecord` field is added. `workspaceId` is dropped for the same reason content-types'
 * `toContentTypeView` drops it — the agent is scoped to one workspace it cannot change, so echoing
 * the id spends model attention on a value that can never inform a decision.
 *
 * @param record.roleIds - The principal's role assignments, passed in rather than resolved here so
 * the projection stays pure and the caller decides whether the extra repo read is worth it.
 * @returns The model-facing view. `email` is present only when set, so a user without one carries
 * no always-undefined key.
 * @complexity O(r) in the role count (the array is copied so the caller cannot alias domain state).
 * @overallScore 100
 * See docs/decisions/DR-007-workspace-and-owner-floors.md.
 */
function toIdentityUserView(record: { principal: PrincipalRecord; user: UserRecord; roleIds: readonly string[] }): IdentityUserToolView {
  const view: IdentityUserToolView = {
    principalId: record.principal.id,
    username: record.user.username,
    status: record.principal.status,
    roleIds: [...record.roleIds],
  };
  if (record.user.email) view.email = record.user.email;
  return view;
}

/** What an identity role tool returns to the model. `isBuiltin` is kept because it is what predicts a rename/delete refusal. */
function toIdentityRoleView(role: RoleRecord): { id: string; name: string; isBuiltin: boolean } {
  return { id: role.id, name: role.name, isBuiltin: role.isBuiltin };
}

/**
 * What an identity policy tool returns to the model. `isBuiltin`/`isFrozen` are both kept because
 * together they are what predicts an update/delete/write-permission refusal (mirrors
 * `toIdentityRoleView`'s `isBuiltin`, extended for the second immutability flag policies carry that
 * roles do not). `description` is present only when set, matching `toIdentityUserView`'s `email`.
 */
function toIdentityPolicyView(policy: PolicyRecord): { id: string; name: string; isBuiltin: boolean; isFrozen: boolean; description?: string } {
  const view: { id: string; name: string; isBuiltin: boolean; isFrozen: boolean; description?: string } = {
    id: policy.id,
    name: policy.name,
    isBuiltin: policy.isBuiltin,
    isFrozen: policy.isFrozen,
  };
  if (policy.description) view.description = policy.description;
  return view;
}

/** Read a principal's role-assignment ids. Shared by every tool that returns a user view. */
async function roleIdsFor(routeDeps: IdentityToolDeps, principalId: string): Promise<string[]> {
  const links = await routeDeps.principalRoleRepo.listByPrincipalId({ workspaceId: routeDeps.workspaceId, principalId });
  return links.map((link) => link.roleId);
}

/**
 * Load the `UserRecord` paired with a principal the domain just returned.
 *
 * Every `kind='user'` principal has one by construction (CREATE_USER's atomicity guarantee), so
 * the miss is defensive rather than an expected path — the same reasoning `routes/admin/users/
 * disable.ts` records for its identical second lookup.
 */
async function requireUserRecord(routeDeps: IdentityToolDeps, principalId: string): Promise<UserRecord> {
  const user = await routeDeps.userRepo.findByPrincipalId({ workspaceId: routeDeps.workspaceId, principalId });
  if (!user) throw new Error(`user '${principalId}' was not found`);
  return user;
}

export function buildIdentityRegistrations(routeDeps: IdentityToolDeps): ToolRegistration[] {
  /** Assembled per call, not per handler, because every mutating handler needs the identical bag. */
  const serviceDeps = () => identityServiceDepsFrom(routeDeps);

  const handlers: Record<string, ToolHandler> = {
    identity_user_list: async (ctx) => {
      identityInput({ toolId: "identity_user_list", input: ctx.input });
      await assertIdentityReadAllowed(routeDeps, "identity_user_list", ctx.principal.id);

      const principals = await routeDeps.principalRepo.list({ workspaceId: routeDeps.workspaceId });
      // Humans only — `system`/`agent`/`api_key` principals (including the disabled `user-local`
      // seed row) are not what "users" means on this surface, matching `routes/.../list.ts`.
      const humans = principals.filter((principal) => principal.kind === "user");
      const page = humans.slice(0, IDENTITY_USER_LIST_MAX);

      const users = await Promise.all(
        page.map(async (principal) => {
          const user = await routeDeps.userRepo.findByPrincipalId({ workspaceId: routeDeps.workspaceId, principalId: principal.id });
          if (!user) return null;
          return toIdentityUserView({ principal, user, roleIds: await roleIdsFor(routeDeps, principal.id) });
        }),
      );

      const listed = users.filter((user): user is IdentityUserToolView => user !== null);
      return humans.length > page.length
        ? { users: listed, truncated: true, totalCount: humans.length }
        : { users: listed };
    },

    identity_role_list: async (ctx) => {
      identityInput({ toolId: "identity_role_list", input: ctx.input });
      await assertIdentityReadAllowed(routeDeps, "identity_role_list", ctx.principal.id);

      const roles = await routeDeps.roleRepo.list({ workspaceId: routeDeps.workspaceId });
      return { roles: roles.map(toIdentityRoleView) };
    },

    identity_policy_list: async (ctx) => {
      identityInput({ toolId: "identity_policy_list", input: ctx.input });
      await assertIdentityReadAllowed(routeDeps, "identity_policy_list", ctx.principal.id);

      const policies = await routeDeps.policyRepo.list({ workspaceId: routeDeps.workspaceId });
      return { policies: policies.map(toIdentityPolicyView) };
    },

    identity_user_create: async (ctx) => {
      const input = identityInput({ toolId: "identity_user_create", input: ctx.input });
      const { principal, user } = await createUser({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          username: input.req("username"),
          password: input.req("password"),
        },
      }, { email: input.opt("email") });
      // A brand-new principal has no assignments yet, so this is [] by construction, not a read.
      return { user: toIdentityUserView({ principal, user, roleIds: [] }) };
    },

    identity_user_update_email: async (ctx) => {
      const input = identityInput({ toolId: "identity_user_update_email", input: ctx.input });
      const { user } = await updateUser({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          principalId: input.req("principalId"),
          // Absent stays absent: `updateUser` treats a falsy email as "clear", which is exactly
          // what this tool's description tells the model omitting it does.
        },
      }, { email: input.opt("email") });
      const principal = await routeDeps.principalRepo.findById({ workspaceId: routeDeps.workspaceId, id: input.req("principalId") });
      if (!principal) throw new Error(`principal '${input.req("principalId")}' was not found`);
      return { user: toIdentityUserView({ principal, user, roleIds: await roleIdsFor(routeDeps, principal.id) }) };
    },

    identity_user_change_username: async (ctx) => {
      const input = identityInput({ toolId: "identity_user_change_username", input: ctx.input });
      const principalId = input.req("principalId");
      const { user } = await updateUser({ deps: serviceDeps(), input: {
        workspaceId: routeDeps.workspaceId, callerPrincipalId: ctx.principal.id, principalId,
      } }, { username: input.req("username") });
      const principal = await routeDeps.principalRepo.findById({ workspaceId: routeDeps.workspaceId, id: principalId });
      if (!principal) throw new Error(`principal '${principalId}' was not found`);
      return { user: toIdentityUserView({ principal, user, roleIds: await roleIdsFor(routeDeps, principalId) }) };
    },

    identity_user_disable: async (ctx) => {
      const input = identityInput({ toolId: "identity_user_disable", input: ctx.input });
      const { principal } = await disablePrincipal({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          principalId: input.req("principalId"),
          // Resolved by the caller, per `disablePrincipal`'s own contract — the same
          // `await deps.ownerPrincipalId` the human disable route performs.
          seededOwnerPrincipalId: await routeDeps.ownerPrincipalId,
        },
      });
      const user = await requireUserRecord(routeDeps, principal.id);
      return { user: toIdentityUserView({ principal, user, roleIds: await roleIdsFor(routeDeps, principal.id) }) };
    },

    identity_user_enable: async (ctx) => {
      const input = identityInput({ toolId: "identity_user_enable", input: ctx.input });
      const { principal } = await enablePrincipal({
        deps: serviceDeps(),
        input: { workspaceId: routeDeps.workspaceId, callerPrincipalId: ctx.principal.id, principalId: input.req("principalId") },
      });
      const user = await requireUserRecord(routeDeps, principal.id);
      return { user: toIdentityUserView({ principal, user, roleIds: await roleIdsFor(routeDeps, principal.id) }) };
    },

    identity_role_create: async (ctx) => {
      const input = identityInput({ toolId: "identity_role_create", input: ctx.input });
      const { role } = await createRole({
        deps: serviceDeps(),
        input: { workspaceId: routeDeps.workspaceId, callerPrincipalId: ctx.principal.id, name: input.req("name") },
      });
      return { role: toIdentityRoleView(role) };
    },

    identity_role_assign: async (ctx) => {
      const input = identityInput({ toolId: "identity_role_assign", input: ctx.input });
      const { assignment }: { assignment: PrincipalRoleRecord } = await assignRole({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          principalId: input.req("principalId"),
          roleId: input.req("roleId"),
        },
      });
      // The join row's own id is not addressable by any other tool, so it is dropped; what the
      // model needs back is confirmation of WHICH pair is now linked.
      return { assigned: { principalId: assignment.principalId, roleId: assignment.roleId } };
    },

    identity_role_rename: async (ctx) => {
      const input = identityInput({ toolId: "identity_role_rename", input: ctx.input });
      const { role } = await updateRole({
        deps: serviceDeps(),
        input: { workspaceId: routeDeps.workspaceId, callerPrincipalId: ctx.principal.id, roleId: input.req("roleId"), name: input.req("name") },
      });
      return { role: toIdentityRoleView(role) };
    },

    identity_role_delete: async (ctx) => {
      const input = identityInput({ toolId: "identity_role_delete", input: ctx.input });
      await deleteRole({
        deps: serviceDeps(),
        input: { workspaceId: routeDeps.workspaceId, callerPrincipalId: ctx.principal.id, roleId: input.req("roleId") },
      });
      // `deleteRole` resolves void; an empty tool result would read to the model as "nothing
      // happened", so the deleted id is echoed as the acknowledgement.
      return { deleted: { roleId: input.req("roleId") } };
    },

    identity_policy_create: async (ctx) => {
      const input = identityInput({ toolId: "identity_policy_create", input: ctx.input });
      const { policy } = await createPolicy({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          name: input.req("name"),
          // Absent stays absent: `input.description` is only present when the caller supplied it
          // (`parseIdentityToolInput` omits absent optional keys entirely), so this passes through
          // unchanged rather than coercing a caller-supplied empty string to "no description".
        },
      }, { description: input.opt("description") });
      return { policy: toIdentityPolicyView(policy) };
    },

    identity_policy_update: async (ctx) => {
      const input = identityInput({ toolId: "identity_policy_update", input: ctx.input });
      const { policy } = await updatePolicy({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          policyId: input.req("policyId"),
          // Same absent-stays-absent reasoning as identity_policy_create — `updatePolicy` itself
          // distinguishes undefined ("leave unchanged") from an explicit empty string.
        },
      }, { name: input.opt("name"), description: input.opt("description") });
      return { policy: toIdentityPolicyView(policy) };
    },

    identity_policy_delete: async (ctx) => {
      const input = identityInput({ toolId: "identity_policy_delete", input: ctx.input });
      await deletePolicy({
        deps: serviceDeps(),
        input: { workspaceId: routeDeps.workspaceId, callerPrincipalId: ctx.principal.id, policyId: input.req("policyId") },
      });
      // `deletePolicy` resolves void; an empty tool result would read to the model as "nothing
      // happened", so the deleted id is echoed as the acknowledgement (mirrors identity_role_delete).
      return { deleted: { policyId: input.req("policyId") } };
    },

    identity_policy_attach: async (ctx) => {
      const input = identityInput({ toolId: "identity_policy_attach", input: ctx.input });
      const { attachment } = await attachPolicy({
        deps: serviceDeps(),
        input: {
          workspaceId: routeDeps.workspaceId,
          callerPrincipalId: ctx.principal.id,
          principalId: input.req("principalId"),
          policyId: input.req("policyId"),
        },
      });
      // The join row's own id is not addressable by any other tool, so it is dropped; what the
      // model needs back is confirmation of WHICH pair is now linked (mirrors identity_role_assign).
      return { attached: { principalId: attachment.principalId, policyId: attachment.policyId } };
    },
  };

  // No `unwiredToolIds`: identity wires its ENTIRE catalog (which is why its own
  // `AgentToolDefinition` makes `inputSchema` required rather than optional).
  return buildDomainRegistrations({
    domain: "identity",
    catalogModule: "./index.js",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: identityDerivedRisk,
  });
}

/** Pure email-challenge primitives. Hosts own persistence, delivery and atomic consumption. */
import type { PasswordHasherPort } from "../core/ports.js";
import type { SessionTokenPort } from "../core/runtime-ports.js";

/** Persisted metadata only; raw link tokens and codes must never enter this record. */
export interface AuthChallengeRecord {
  readonly id: string;
  readonly workspaceId: string;
  readonly realm: string;
  readonly purpose: string;
  readonly tokenHash: string;
  /** Null for legacy link-only challenges. */
  readonly codeHash: string | null;
  readonly expiresAt: string;
  readonly consumedAt?: string | null;
  /**
   * Code attempts spent. Each is reserved before its code is verified, and a correct code
   * consumes the challenge, so on a live challenge every counted attempt failed or is in flight.
   */
  readonly failedAttempts: number;
}

export interface ChallengeScope {
  readonly workspaceId: string;
  readonly realm: string;
  readonly purpose: string;
}

/**
 * Storage contract only: implementations live in the host. Reads are scope-bound.
 * Link completion: findByTokenHash -> decideChallenge -> consume.
 * Code completion: findById -> decideChallenge -> reserveCodeAttempt -> verifyChallengeCode -> consume.
 * Any false or "invalid" step gives the caller the same uniform failure.
 */
export interface ChallengeStorePort {
  save(record: AuthChallengeRecord): Promise<void>;
  findById(input: ChallengeScope & { id: string }): Promise<AuthChallengeRecord | null>;
  findByTokenHash(input: ChallengeScope & { tokenHash: string }): Promise<AuthChallengeRecord | null>;
  /**
   * Atomically (lock/CAS) increment failedAttempts while decideChallenge is "ok" on current
   * state; false when none remain. It runs BEFORE the code is verified, so parallel guesses
   * cannot each read a stale counter and outrun the limit. Never resets the counter.
   */
  reserveCodeAttempt(input: ChallengeScope & { id: string; nowIso: string; maxAttempts?: number }): Promise<boolean>;
  /**
   * Atomically stamp consumedAt while in scope, unconsumed and unexpired; link and code share
   * this one stamp. Attempts are not rechecked: link completion checked them in decideChallenge
   * and code completion already spent one. Returns false if another completion won.
   */
  consume(input: ChallengeScope & { id: string; nowIso: string }): Promise<boolean>;
}

export interface ChallengeSecretDependencies {
  /** Inject NodeSessionTokens (32 cryptographic random bytes, SHA-256 digest), or equivalent. */
  readonly tokens: SessionTokenPort;
  /** Inject crypto.randomInt via ({ min, max }) => randomInt(min, max); max is exclusive. */
  readonly randomInt: (input: { min: number; max: number }) => number;
}

export interface ChallengeSecrets {
  readonly token: string;
  readonly tokenHash: string;
  readonly code: string;
}

/**
 * Generate one 256-bit link bearer and uniform six-digit code through injected entropy.
 * Only tokenHash and hashChallengeCode's result may be persisted. No clock or I/O is read.
 * @throws RangeError if the supplied random-integer adapter violates its bounds.
 * @complexity O(1), with one token generation/digest and one bounded integer draw.
 */
export function newChallengeSecrets(
  { tokens, randomInt }: ChallengeSecretDependencies,
  _options: Record<string, never> = {},
): ChallengeSecrets {
  const value = randomInt({ min: 0, max: 1_000_000 });
  if (!Number.isInteger(value) || value < 0 || value >= 1_000_000) {
    throw new RangeError("Challenge entropy must be an integer in [0, 1000000).");
  }
  const token = tokens.newToken({});
  return { token, tokenHash: tokens.hashToken({ rawToken: token }), code: String(value).padStart(6, "0") };
}

/** Exact ASCII shape; without the m flag, $ also refuses trailing line terminators. O(1). */
function isChallengeCode(code: string): boolean {
  return /^[0-9]{6}$/.test(code);
}

/**
 * Hash the low-entropy code using the existing password hasher, never a fast digest.
 * @throws RangeError for malformed codes; hashing adapter errors propagate.
 * @complexity O(1) adapter calls; hashing cost belongs to PasswordHasherPort.
 */
export function hashChallengeCode(
  { code, hasher }: { code: string; hasher: PasswordHasherPort },
  _options: Record<string, never> = {},
): Promise<string> {
  if (!isChallengeCode(code)) throw new RangeError("Challenge code must contain exactly six ASCII digits.");
  return hasher.hash({ password: code });
}

/**
 * Verify through PasswordHasherPort's timing-safe verifier (Argon2PasswordHasher in Node).
 * Legacy link-only hashes and malformed codes return false. Adapter errors propagate.
 * @complexity O(1) adapter calls; no repository access or attempt mutation.
 */
export async function verifyChallengeCode(
  { code, hash, hasher }: { code: string; hash: string | null; hasher: PasswordHasherPort },
  _options: Record<string, never> = {},
): Promise<boolean> {
  if (!hash || !isChallengeCode(code)) return false;
  return hasher.verify({ hash, password: code });
}

/** Invalid counters or limits deny access; O(1), without changing the stored counter. */
function hasAttemptsRemaining(failedAttempts: number, maxAttempts: number): boolean {
  return Number.isSafeInteger(failedAttempts) && failedAttempts >= 0
    && Number.isSafeInteger(maxAttempts) && maxAttempts > 0 && failedAttempts < maxAttempts;
}

/**
 * Decide metadata eligibility only; callers must also verify the token/code and use the
 * store's atomic steps above. nowIso is the caller's injected clock value. Expiry is exclusive.
 * Every denial returns the same result, including malformed timestamps/counters.
 * @complexity O(1) for fixed-size metadata; no I/O, clock reads or input mutation.
 */
export function decideChallenge(
  { record, workspaceId, realm, purpose, nowIso, maxAttempts = 5 }: ChallengeScope & {
    record: AuthChallengeRecord | null;
    nowIso: string;
    maxAttempts?: number;
  },
  _options: Record<string, never> = {},
): "ok" | "invalid" {
  if (!record) return "invalid";
  if (record.workspaceId !== workspaceId || record.realm !== realm || record.purpose !== purpose) return "invalid";
  if (record.consumedAt != null) return "invalid";
  if (!hasAttemptsRemaining(record.failedAttempts, maxAttempts)) return "invalid";
  const now = Date.parse(nowIso);
  const expires = Date.parse(record.expiresAt);
  // Invalid dates parse to NaN, so the comparison also denies malformed timestamps.
  return expires > now ? "ok" : "invalid";
}

import { AsyncLocalStorage } from 'node:async_hooks';
import type { IdentityRepos, IdentityTransactionPort } from '../core/ports.js';
import { InMemoryIdentityRows } from './repo.memory.js';

/**
 * Wrap a complete memory repository bag with one serialization queue and rollback snapshots.
 * Use only the returned repositories after binding: retained raw handles bypass isolation.
 * Every ordinary read/write also joins the queue, so an assignment outside a service cannot
 * race a guarded delete and readers cannot observe uncommitted changes. This is a dev/test
 * adapter; durable hosts supply their own transaction port over their own storage connection.
 */
export function createTransactionalInMemoryIdentityRepos(required: {
  repos: Omit<IdentityRepos, "transactions"> & { transactions?: IdentityTransactionPort };
}): IdentityRepos & { transactions: IdentityTransactionPort } {
  if (required.repos.transactions) throw new Error('identity repositories are already bound to a transaction port');
  const context = new AsyncLocalStorage<{ active: boolean }>();
  let tail = Promise.resolve();
  const stores = Object.entries(required.repos).filter(([key]) => key !== 'transactions').map(([, repo]) => {
    if (!(repo instanceof InMemoryIdentityRows)) {
      throw new Error('memory transactions require in-memory identity repositories');
    }
    return repo;
  });

  /** Preserve queue progress after rejection; descendants of a completed body cannot bypass it. */
  async function exclusive<T>(execute: () => Promise<T>): Promise<T> {
    if (context.getStore()?.active) return execute();
    const previous = tail;
    let release!: () => void;
    tail = new Promise<void>(resolve => { release = resolve; });
    await previous;
    const scope = { active: true };
    try {
      return await context.run(scope, execute);
    } finally {
      scope.active = false;
      release();
    }
  }

  const transactions: IdentityTransactionPort = {
    run: ({ execute }) => exclusive(async () => {
      // Every store was checked to be InMemoryIdentityRows when the bag was bound above.
      const snapshots = stores.map((repo) => {
        const rows = repo.snapshotRows({});
        return { restore: () => repo.restoreRows({ rows }) };
      });
      try {
        return await execute();
      } catch (error) {
        for (const snapshot of snapshots) snapshot.restore();
        throw error;
      }
    }),
  };
  function wrap<T extends object>(repo: T): T {
    return new Proxy(repo, {
      get(target, property, receiver) {
        const member = Reflect.get(target, property, receiver);
        if (typeof member !== 'function') return member;
        return (...args: unknown[]) => exclusive(async () => {
          // Detach inputs/outputs so a row reference outside the queue cannot mutate stored state.
          const result = await Reflect.apply(member, target, structuredClone(args));
          return structuredClone(result);
        });
      },
    });
  }
  const repos = {
    principals: wrap(required.repos.principals), users: wrap(required.repos.users),
    sessions: wrap(required.repos.sessions), roles: wrap(required.repos.roles),
    policies: wrap(required.repos.policies), policyPermissions: wrap(required.repos.policyPermissions),
    rolePolicies: wrap(required.repos.rolePolicies), principalRoles: wrap(required.repos.principalRoles),
    principalPolicies: wrap(required.repos.principalPolicies),
  };
  return { ...repos, transactions };
}

/**
 * @module core/types
 *
 * The vocabulary of a conversational authoring session, deliberately independent of *what* is
 * being authored.
 *
 * The whole design rests on one observation: every AI app-builder differs at exactly one place —
 * the artifact being edited. One tool edits a file tree; another edits a single markup document.
 * The conversation, the streaming, the undo, and the preview are the same in all of them. So this
 * package owns the loop and knows nothing about the target, which reaches it as a small port
 * (see `./target.ts`).
 *
 * Terminology: an artifact is made of **parts**. A part is the unit a model may be asked to
 * rewrite — a file for a file-tree host, a tagged region for a single-document host. Parts are
 * addressed by an opaque `PartId` that the host publishes; a caller never supplies a selector or a
 * path of its own devising.
 */

/**
 * An opaque handle to one editable part, minted and published by the host.
 *
 * It is an **allowlist entry, not a query**. A model or caller may only name an id the host has
 * already listed, which is what keeps a model-authored string from becoming a path traversal or an
 * arbitrary DOM selector. Hosts that expose filesystem paths or CSS selectors as ids are
 * responsible for validating them at the boundary before publishing them.
 */
export type PartId = string;

/** One editable part as advertised to the model, without its content. */
export interface PartRef {
  /** The host-published handle used to read or replace this part. */
  readonly id: PartId;
  /**
   * Optional host-meaningful category (e.g. a language, a region role). Purely descriptive —
   * the loop never branches on it, it exists so a host can shape its own prompt.
   */
  readonly kind?: string;
  /**
   * Optional human-facing label. Host-authored and therefore **untrusted** for display: treat it
   * as text, never as markup.
   */
  readonly label?: string;
}

/**
 * A point-in-time copy of every part's content.
 *
 * Deliberately a flat id → content map and nothing more. Two consequences worth stating, because
 * the reference implementation this shape was taken from conflates them:
 *
 * 1. **A snapshot restores DATA, never an execution environment.** A host with downstream state —
 *    a dev server, a build, an installed dependency tree — re-syncs itself *after* `restore`
 *    returns. If this type implied "and everything depending on these parts works again," it would
 *    be promising something it cannot deliver for any host but the simplest.
 * 2. It carries no ordering and no tree structure. A host that needs those reconstructs them from
 *    its own ids, which it minted and therefore understands.
 */
export interface Snapshot {
  /** Identifies this snapshot within a session. Assigned by the caller that took it. */
  readonly id: string;
  /** Every part's content at capture time, keyed by `PartId`. */
  readonly parts: Readonly<Record<PartId, string>>;
}

/** A host's verdict on a prospective change, returned by `EditTarget.validate`. */
export type ValidationResult =
  | { readonly ok: true }
  | {
      readonly ok: false;
      /**
       * Why the change was refused, phrased for the **model** rather than for a log. This string
       * is fed back as the next turn's input, so it should name the defect concretely
       * (e.g. "unclosed <section> — the document no longer parses") rather than say "invalid".
       */
      readonly reason: string;
    };

/** What happened to one `replace` attempt. */
export type ApplyOutcome =
  | { readonly status: "applied"; readonly id: PartId }
  | { readonly status: "rejected"; readonly id: PartId; readonly reason: string }
  | { readonly status: "failed"; readonly id: PartId; readonly error: Error };
